import type { Sentence } from '../../types/content';
export const sentencesPart7 = JSON.parse('[{"id":"zhuangzi_ch-25_p-71_s-1","passageId":"zhuangzi_ch-25_p-71","order":1,"canonicalText":"斯而析之，精至於无倫，大至於不可圍，或之使，莫之為，未免於物而終以為過。","chunks":[["斯而析之，精至於无倫，大至於不可圍，或之使，莫之為，未免於物而終以為過。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-71_s-2","passageId":"zhuangzi_ch-25_p-71","order":2,"canonicalText":"或使則實，莫為則虛。","chunks":[["或使則實，莫為則虛。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-71_s-3","passageId":"zhuangzi_ch-25_p-71","order":3,"canonicalText":"有名有實，是物之居；","chunks":[["有名有實，是物之居；","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-71_s-4","passageId":"zhuangzi_ch-25_p-71","order":4,"canonicalText":"无名无實，在物之虛。","chunks":[["无名无實，在物之虛。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-72_s-1","passageId":"zhuangzi_ch-25_p-72","order":1,"canonicalText":"可言可意，言而愈䟽。","chunks":[["可言可意，言而愈䟽。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-72_s-2","passageId":"zhuangzi_ch-25_p-72","order":2,"canonicalText":"未生不可忌，已死不可阻。","chunks":[["未生不可忌，已死不可阻。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-72_s-3","passageId":"zhuangzi_ch-25_p-72","order":3,"canonicalText":"死生非遠也，理不可覩。","chunks":[["死生非遠也，理不可覩。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-72_s-4","passageId":"zhuangzi_ch-25_p-72","order":4,"canonicalText":"或之使，莫之為，疑之所假。","chunks":[["或之使，莫之為，疑之所假。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-72_s-5","passageId":"zhuangzi_ch-25_p-72","order":5,"canonicalText":"吾觀之本，其往无窮；","chunks":[["吾觀之本，其往无窮；","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-73_s-1","passageId":"zhuangzi_ch-25_p-73","order":1,"canonicalText":"吾求之末，其來无止。","chunks":[["吾求之末，其來无止。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-73_s-2","passageId":"zhuangzi_ch-25_p-73","order":2,"canonicalText":"无窮无止，言之无也，與物同理；","chunks":[["无窮无止，言之无也，與物同理；","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-73_s-3","passageId":"zhuangzi_ch-25_p-73","order":3,"canonicalText":"或使莫為，言之本也，與物終始。","chunks":[["或使莫為，言之本也，與物終始。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-74_s-1","passageId":"zhuangzi_ch-25_p-74","order":1,"canonicalText":"道不可有，有不可无，道之為名，所假而行。","chunks":[["道不可有，有不可无，道之為名，所假而行。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-74_s-2","passageId":"zhuangzi_ch-25_p-74","order":2,"canonicalText":"或使莫為，在物一曲，夫胡為於大方？","chunks":[["或使莫為，在物一曲，夫胡為於大方？","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-74_s-3","passageId":"zhuangzi_ch-25_p-74","order":3,"canonicalText":"言而足，則終日言而盡道；","chunks":[["言而足，則終日言而盡道；","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-74_s-4","passageId":"zhuangzi_ch-25_p-74","order":4,"canonicalText":"言而不足，則終日言而盡物。","chunks":[["言而不足，則終日言而盡物。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-75_s-1","passageId":"zhuangzi_ch-25_p-75","order":1,"canonicalText":"道物之極，言默不足以載；","chunks":[["道物之極，言默不足以載；","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-75_s-2","passageId":"zhuangzi_ch-25_p-75","order":2,"canonicalText":"非言非默，議有所極。","chunks":[["非言非默，議有所極。","zh-Hant"]]},{"id":"zhuangzi_ch-25_p-75_s-3","passageId":"zhuangzi_ch-25_p-75","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-1_s-1","passageId":"zhuangzi_ch-26_p-1","order":1,"canonicalText":"外物不可必，故龍逢誅，比干戮，箕子狂，惡來死，桀紂亡。","chunks":[["外物不可必，故龍逢誅，比干戮，箕子狂，惡來死，桀紂亡。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-1_s-2","passageId":"zhuangzi_ch-26_p-1","order":2,"canonicalText":"人主莫不欲其臣之忠，而忠未必信，故伍員流于江，萇弘死于蜀，藏其血三年而化為碧。","chunks":[["人主莫不欲其臣之忠，而忠未必信，故伍員流于江，萇弘死于蜀，藏其血三年而化為碧。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-2_s-1","passageId":"zhuangzi_ch-26_p-2","order":1,"canonicalText":"人親莫不欲其子之孝，而孝未必愛，故孝己憂而曾參悲。","chunks":[["人親莫不欲其子之孝，而孝未必愛，故孝己憂而曾參悲。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-2_s-2","passageId":"zhuangzi_ch-26_p-2","order":2,"canonicalText":"木與木相摩則然，金與火相守則流。","chunks":[["木與木相摩則然，金與火相守則流。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-3_s-1","passageId":"zhuangzi_ch-26_p-3","order":1,"canonicalText":"陰陽錯行，則天地大絯，於是乎有雷有霆，水中有火，乃焚大槐。","chunks":[["陰陽錯行，則天地大絯，於是乎有雷有霆，水中有火，乃焚大槐。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-3_s-2","passageId":"zhuangzi_ch-26_p-3","order":2,"canonicalText":"有甚憂兩陷而无所逃，","chunks":[["有甚憂兩陷而无所逃，","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-4_s-1","passageId":"zhuangzi_ch-26_p-4","order":1,"canonicalText":"螴蜳不得成，心若縣於天地之閒，慰暋沈屯，利害相摩，生火甚多，眾人焚和，月固不勝火，於是乎有僓然而道盡。","chunks":[["螴蜳不得成，心若縣於天地之閒，慰暋沈屯，利害相摩，生火甚多，眾人焚和，月固不勝火，於是乎有僓然而道盡。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-5_s-1","passageId":"zhuangzi_ch-26_p-5","order":1,"canonicalText":"莊周家貧，故往貸粟於監河侯。","chunks":[["莊周家貧，故往貸粟於監河侯。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-5_s-2","passageId":"zhuangzi_ch-26_p-5","order":2,"canonicalText":"監河侯曰：「諾。","chunks":[["監河侯曰：「諾。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-5_s-3","passageId":"zhuangzi_ch-26_p-5","order":3,"canonicalText":"我將得邑金，將貸子三百金，可乎？","chunks":[["我將得邑金，將貸子三百金，可乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-5_s-4","passageId":"zhuangzi_ch-26_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-1","passageId":"zhuangzi_ch-26_p-6","order":1,"canonicalText":"莊周忿然作色曰：「周昨來，有中道而呼者。","chunks":[["莊周忿然作色曰：「周昨來，有中道而呼者。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-2","passageId":"zhuangzi_ch-26_p-6","order":2,"canonicalText":"周顧視，車轍中有鮒魚焉。","chunks":[["周顧視，車轍中有鮒魚焉。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-3","passageId":"zhuangzi_ch-26_p-6","order":3,"canonicalText":"周問之曰：『鮒魚來，子何為者邪？","chunks":[["周問之曰：『鮒魚來，子何為者邪？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-4","passageId":"zhuangzi_ch-26_p-6","order":4,"canonicalText":"』對曰：『我，東海之波臣也。","chunks":[["』對曰：『我，東海之波臣也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-5","passageId":"zhuangzi_ch-26_p-6","order":5,"canonicalText":"君豈有升斗之水而活我哉？","chunks":[["君豈有升斗之水而活我哉？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-6_s-6","passageId":"zhuangzi_ch-26_p-6","order":6,"canonicalText":"』","chunks":[["』","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-7_s-1","passageId":"zhuangzi_ch-26_p-7","order":1,"canonicalText":"周曰：『諾。","chunks":[["周曰：『諾。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-7_s-2","passageId":"zhuangzi_ch-26_p-7","order":2,"canonicalText":"我且南遊吳越之王，激西江之水而迎子，可乎？","chunks":[["我且南遊吳越之王，激西江之水而迎子，可乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-7_s-3","passageId":"zhuangzi_ch-26_p-7","order":3,"canonicalText":"』鮒魚忿然作色曰：『吾失我常與，我无所處。","chunks":[["』鮒魚忿然作色曰：『吾失我常與，我无所處。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-7_s-4","passageId":"zhuangzi_ch-26_p-7","order":4,"canonicalText":"吾得斗升之水然活耳，君乃言此，曾不如早索我於枯魚之肆！","chunks":[["吾得斗升之水然活耳，君乃言此，曾不如早索我於枯魚之肆！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-7_s-5","passageId":"zhuangzi_ch-26_p-7","order":5,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-8_s-1","passageId":"zhuangzi_ch-26_p-8","order":1,"canonicalText":"任公子為大鉤巨緇，五十犗以為餌，蹲乎會稽，投竿東海，旦旦而釣，期年不得魚。","chunks":[["任公子為大鉤巨緇，五十犗以為餌，蹲乎會稽，投竿東海，旦旦而釣，期年不得魚。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-8_s-2","passageId":"zhuangzi_ch-26_p-8","order":2,"canonicalText":"已而大魚食之，牽巨鉤錎沒而下，騖揚而奮鬐，白波若山，海水震蕩，","chunks":[["已而大魚食之，牽巨鉤錎沒而下，騖揚而奮鬐，白波若山，海水震蕩，","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-9_s-1","passageId":"zhuangzi_ch-26_p-9","order":1,"canonicalText":"聲侔鬼神，憚赫千里。","chunks":[["聲侔鬼神，憚赫千里。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-9_s-2","passageId":"zhuangzi_ch-26_p-9","order":2,"canonicalText":"任公子得若魚，離而腊之，自制河以東，蒼梧已北，莫不厭若魚者。","chunks":[["任公子得若魚，離而腊之，自制河以東，蒼梧已北，莫不厭若魚者。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-10_s-1","passageId":"zhuangzi_ch-26_p-10","order":1,"canonicalText":"已而後世輇才諷說之徒，皆驚而相告也。","chunks":[["已而後世輇才諷說之徒，皆驚而相告也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-10_s-2","passageId":"zhuangzi_ch-26_p-10","order":2,"canonicalText":"夫揭竿累，趨灌瀆，守鯢鮒，其於得大魚難矣，飾小說以干縣令，其於大達亦遠矣，","chunks":[["夫揭竿累，趨灌瀆，守鯢鮒，其於得大魚難矣，飾小說以干縣令，其於大達亦遠矣，","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-11_s-1","passageId":"zhuangzi_ch-26_p-11","order":1,"canonicalText":"是以未嘗聞任氏之風俗，其不可與經於世亦遠矣。","chunks":[["是以未嘗聞任氏之風俗，其不可與經於世亦遠矣。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-12_s-1","passageId":"zhuangzi_ch-26_p-12","order":1,"canonicalText":"儒以《詩》、《禮》發冢。","chunks":[["儒以《詩》、《禮》發冢。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-12_s-2","passageId":"zhuangzi_ch-26_p-12","order":2,"canonicalText":"大儒臚傳曰：「東方作矣，事之何若？","chunks":[["大儒臚傳曰：「東方作矣，事之何若？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-12_s-3","passageId":"zhuangzi_ch-26_p-12","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-13_s-1","passageId":"zhuangzi_ch-26_p-13","order":1,"canonicalText":"小儒曰：「未解裙襦，口中有珠。","chunks":[["小儒曰：「未解裙襦，口中有珠。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-13_s-2","passageId":"zhuangzi_ch-26_p-13","order":2,"canonicalText":"《詩》固有之曰：『青青之麥，生於陵陂。","chunks":[["《詩》固有之曰：『青青之麥，生於陵陂。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-13_s-3","passageId":"zhuangzi_ch-26_p-13","order":3,"canonicalText":"生不布施，死何含珠為！","chunks":[["生不布施，死何含珠為！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-13_s-4","passageId":"zhuangzi_ch-26_p-13","order":4,"canonicalText":"』接其鬢，擪其顪，儒以金椎控其頤，徐別其頰，无傷口中珠！","chunks":[["』接其鬢，擪其顪，儒以金椎控其頤，徐別其頰，无傷口中珠！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-13_s-5","passageId":"zhuangzi_ch-26_p-13","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-14_s-1","passageId":"zhuangzi_ch-26_p-14","order":1,"canonicalText":"老萊子之弟子出薪，遇仲尼，反以告，曰：「有人於彼，脩上而趨下，末僂而後耳，視若營四海，不知其誰氏之子。","chunks":[["老萊子之弟子出薪，遇仲尼，反以告，曰：「有人於彼，脩上而趨下，末僂而後耳，視若營四海，不知其誰氏之子。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-14_s-2","passageId":"zhuangzi_ch-26_p-14","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-15_s-1","passageId":"zhuangzi_ch-26_p-15","order":1,"canonicalText":"老萊子曰：「是丘也。","chunks":[["老萊子曰：「是丘也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-15_s-2","passageId":"zhuangzi_ch-26_p-15","order":2,"canonicalText":"召而來。","chunks":[["召而來。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-15_s-3","passageId":"zhuangzi_ch-26_p-15","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-16_s-1","passageId":"zhuangzi_ch-26_p-16","order":1,"canonicalText":"仲尼至。","chunks":[["仲尼至。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-16_s-2","passageId":"zhuangzi_ch-26_p-16","order":2,"canonicalText":"曰：「丘！","chunks":[["曰：「丘！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-16_s-3","passageId":"zhuangzi_ch-26_p-16","order":3,"canonicalText":"去汝躬矜與汝容知，斯為君子矣。","chunks":[["去汝躬矜與汝容知，斯為君子矣。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-16_s-4","passageId":"zhuangzi_ch-26_p-16","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-17_s-1","passageId":"zhuangzi_ch-26_p-17","order":1,"canonicalText":"仲尼揖而退，蹙然改容而問曰：「業可得進乎？","chunks":[["仲尼揖而退，蹙然改容而問曰：「業可得進乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-17_s-2","passageId":"zhuangzi_ch-26_p-17","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-18_s-1","passageId":"zhuangzi_ch-26_p-18","order":1,"canonicalText":"老萊子曰：「夫不忍一世之傷而驁萬世之患，抑固窶邪，亡其略弗及邪？","chunks":[["老萊子曰：「夫不忍一世之傷而驁萬世之患，抑固窶邪，亡其略弗及邪？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-18_s-2","passageId":"zhuangzi_ch-26_p-18","order":2,"canonicalText":"惠以歡為驁，終身之醜，中民之行進焉耳，相引以名，相結以隱。","chunks":[["惠以歡為驁，終身之醜，中民之行進焉耳，相引以名，相結以隱。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-18_s-3","passageId":"zhuangzi_ch-26_p-18","order":3,"canonicalText":"與其譽堯而非桀，不如兩忘而閉其所譽。","chunks":[["與其譽堯而非桀，不如兩忘而閉其所譽。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-19_s-1","passageId":"zhuangzi_ch-26_p-19","order":1,"canonicalText":"反无非傷也，動无非邪也。","chunks":[["反无非傷也，動无非邪也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-19_s-2","passageId":"zhuangzi_ch-26_p-19","order":2,"canonicalText":"聖人躊躇以興事，以每成功。","chunks":[["聖人躊躇以興事，以每成功。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-19_s-3","passageId":"zhuangzi_ch-26_p-19","order":3,"canonicalText":"奈何哉其載焉終矜爾！","chunks":[["奈何哉其載焉終矜爾！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-19_s-4","passageId":"zhuangzi_ch-26_p-19","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-20_s-1","passageId":"zhuangzi_ch-26_p-20","order":1,"canonicalText":"宋元君夜半而夢人被髮闚阿門，曰：「予自宰路之淵，予為清江使河伯之所，漁者余且得予。","chunks":[["宋元君夜半而夢人被髮闚阿門，曰：「予自宰路之淵，予為清江使河伯之所，漁者余且得予。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-20_s-2","passageId":"zhuangzi_ch-26_p-20","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-21_s-1","passageId":"zhuangzi_ch-26_p-21","order":1,"canonicalText":"元君覺，使人占之，曰：「此神龜也。","chunks":[["元君覺，使人占之，曰：「此神龜也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-21_s-2","passageId":"zhuangzi_ch-26_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-22_s-1","passageId":"zhuangzi_ch-26_p-22","order":1,"canonicalText":"君曰：「漁者有余且乎？","chunks":[["君曰：「漁者有余且乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-22_s-2","passageId":"zhuangzi_ch-26_p-22","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-23_s-1","passageId":"zhuangzi_ch-26_p-23","order":1,"canonicalText":"左右曰：「有。","chunks":[["左右曰：「有。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-23_s-2","passageId":"zhuangzi_ch-26_p-23","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-24_s-1","passageId":"zhuangzi_ch-26_p-24","order":1,"canonicalText":"君曰：「令余且會朝。","chunks":[["君曰：「令余且會朝。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-24_s-2","passageId":"zhuangzi_ch-26_p-24","order":2,"canonicalText":"」明日，余且朝。","chunks":[["」明日，余且朝。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-24_s-3","passageId":"zhuangzi_ch-26_p-24","order":3,"canonicalText":"君曰：「漁何得？","chunks":[["君曰：「漁何得？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-24_s-4","passageId":"zhuangzi_ch-26_p-24","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-25_s-1","passageId":"zhuangzi_ch-26_p-25","order":1,"canonicalText":"對曰：「且之網得白龜焉，其圓五尺。","chunks":[["對曰：「且之網得白龜焉，其圓五尺。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-25_s-2","passageId":"zhuangzi_ch-26_p-25","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-26_s-1","passageId":"zhuangzi_ch-26_p-26","order":1,"canonicalText":"君曰：「獻若之龜。","chunks":[["君曰：「獻若之龜。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-26_s-2","passageId":"zhuangzi_ch-26_p-26","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-27_s-1","passageId":"zhuangzi_ch-26_p-27","order":1,"canonicalText":"龜至，君再欲殺之，再欲活之，心疑，卜之，曰：「殺龜以卜吉。","chunks":[["龜至，君再欲殺之，再欲活之，心疑，卜之，曰：「殺龜以卜吉。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-27_s-2","passageId":"zhuangzi_ch-26_p-27","order":2,"canonicalText":"」乃刳龜，七十二鑽而无遺筴。","chunks":[["」乃刳龜，七十二鑽而无遺筴。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-28_s-1","passageId":"zhuangzi_ch-26_p-28","order":1,"canonicalText":"仲尼曰：「神（龜）能見夢於元君，而不能避余且之網；","chunks":[["仲尼曰：「神（龜）能見夢於元君，而不能避余且之網；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-28_s-2","passageId":"zhuangzi_ch-26_p-28","order":2,"canonicalText":"知能七十二鑽而无遺筴，不能避刳腸之患。","chunks":[["知能七十二鑽而无遺筴，不能避刳腸之患。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-28_s-3","passageId":"zhuangzi_ch-26_p-28","order":3,"canonicalText":"如是，則知有所困，神有所不及也。","chunks":[["如是，則知有所困，神有所不及也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-28_s-4","passageId":"zhuangzi_ch-26_p-28","order":4,"canonicalText":"雖有至知，萬人謀之。","chunks":[["雖有至知，萬人謀之。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-29_s-1","passageId":"zhuangzi_ch-26_p-29","order":1,"canonicalText":"魚不畏網而畏鵜鶦。","chunks":[["魚不畏網而畏鵜鶦。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-29_s-2","passageId":"zhuangzi_ch-26_p-29","order":2,"canonicalText":"去小知而大知明，去善而自善矣。","chunks":[["去小知而大知明，去善而自善矣。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-29_s-3","passageId":"zhuangzi_ch-26_p-29","order":3,"canonicalText":"嬰兒生无石師而能言，與能言者處也。","chunks":[["嬰兒生无石師而能言，與能言者處也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-29_s-4","passageId":"zhuangzi_ch-26_p-29","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-30_s-1","passageId":"zhuangzi_ch-26_p-30","order":1,"canonicalText":"惠子謂莊子曰：「子言无用。","chunks":[["惠子謂莊子曰：「子言无用。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-30_s-2","passageId":"zhuangzi_ch-26_p-30","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-31_s-1","passageId":"zhuangzi_ch-26_p-31","order":1,"canonicalText":"莊子曰：「知无用而始可與言用矣。","chunks":[["莊子曰：「知无用而始可與言用矣。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-31_s-2","passageId":"zhuangzi_ch-26_p-31","order":2,"canonicalText":"夫地非不廣且大也，人之所用容足耳。","chunks":[["夫地非不廣且大也，人之所用容足耳。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-31_s-3","passageId":"zhuangzi_ch-26_p-31","order":3,"canonicalText":"然則廁足而墊之致黃泉，人尚有用乎？","chunks":[["然則廁足而墊之致黃泉，人尚有用乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-31_s-4","passageId":"zhuangzi_ch-26_p-31","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-32_s-1","passageId":"zhuangzi_ch-26_p-32","order":1,"canonicalText":"惠子曰：「无用。","chunks":[["惠子曰：「无用。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-32_s-2","passageId":"zhuangzi_ch-26_p-32","order":2,"canonicalText":"」莊子曰：「然則无用之為用也亦明矣。","chunks":[["」莊子曰：「然則无用之為用也亦明矣。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-32_s-3","passageId":"zhuangzi_ch-26_p-32","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-33_s-1","passageId":"zhuangzi_ch-26_p-33","order":1,"canonicalText":"莊子曰：「人有能遊，且得不遊乎？","chunks":[["莊子曰：「人有能遊，且得不遊乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-33_s-2","passageId":"zhuangzi_ch-26_p-33","order":2,"canonicalText":"人而不能遊，且得遊乎？","chunks":[["人而不能遊，且得遊乎？","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-33_s-3","passageId":"zhuangzi_ch-26_p-33","order":3,"canonicalText":"夫流遁之志，決絕之行，噫其非至知厚德之任與！","chunks":[["夫流遁之志，決絕之行，噫其非至知厚德之任與！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-33_s-4","passageId":"zhuangzi_ch-26_p-33","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-34_s-1","passageId":"zhuangzi_ch-26_p-34","order":1,"canonicalText":"覆墜而不反，火馳而不顧，雖相與為君臣，時也，易世而无以相賤。","chunks":[["覆墜而不反，火馳而不顧，雖相與為君臣，時也，易世而无以相賤。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-34_s-2","passageId":"zhuangzi_ch-26_p-34","order":2,"canonicalText":"故曰至人不留行焉。","chunks":[["故曰至人不留行焉。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-35_s-1","passageId":"zhuangzi_ch-26_p-35","order":1,"canonicalText":"夫尊古而卑今，學者之流也。","chunks":[["夫尊古而卑今，學者之流也。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-35_s-2","passageId":"zhuangzi_ch-26_p-35","order":2,"canonicalText":"且以狶韋氏之流觀今之世，夫孰能不波！","chunks":[["且以狶韋氏之流觀今之世，夫孰能不波！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-35_s-3","passageId":"zhuangzi_ch-26_p-35","order":3,"canonicalText":"唯至人乃能遊於世而不僻，順人而不失己。","chunks":[["唯至人乃能遊於世而不僻，順人而不失己。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-35_s-4","passageId":"zhuangzi_ch-26_p-35","order":4,"canonicalText":"彼教不學，承意不彼。","chunks":[["彼教不學，承意不彼。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-36_s-1","passageId":"zhuangzi_ch-26_p-36","order":1,"canonicalText":"目徹為明，耳徹為聰，鼻徹為顫，口徹為甘，心徹為知，知徹為德。","chunks":[["目徹為明，耳徹為聰，鼻徹為顫，口徹為甘，心徹為知，知徹為德。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-36_s-2","passageId":"zhuangzi_ch-26_p-36","order":2,"canonicalText":"凡道不欲壅，壅則哽，哽而不止則跈，跈則眾害生。","chunks":[["凡道不欲壅，壅則哽，哽而不止則跈，跈則眾害生。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-37_s-1","passageId":"zhuangzi_ch-26_p-37","order":1,"canonicalText":"物之有知者恃息，其不殷，非天之罪。","chunks":[["物之有知者恃息，其不殷，非天之罪。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-37_s-2","passageId":"zhuangzi_ch-26_p-37","order":2,"canonicalText":"天之穿之，日夜无降，人則顧塞其竇。","chunks":[["天之穿之，日夜无降，人則顧塞其竇。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-37_s-3","passageId":"zhuangzi_ch-26_p-37","order":3,"canonicalText":"胞有重閬，心有天遊。","chunks":[["胞有重閬，心有天遊。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-37_s-4","passageId":"zhuangzi_ch-26_p-37","order":4,"canonicalText":"室无空虛，則婦姑勃谿；","chunks":[["室无空虛，則婦姑勃谿；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-37_s-5","passageId":"zhuangzi_ch-26_p-37","order":5,"canonicalText":"心无天遊，則六鑿相攘。","chunks":[["心无天遊，則六鑿相攘。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-38_s-1","passageId":"zhuangzi_ch-26_p-38","order":1,"canonicalText":"大林丘山之善於人也，亦神者不勝。","chunks":[["大林丘山之善於人也，亦神者不勝。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-38_s-2","passageId":"zhuangzi_ch-26_p-38","order":2,"canonicalText":"德溢乎名，名溢乎暴，謀稽乎誸，知出乎爭，柴生乎守，官事果乎眾宜。","chunks":[["德溢乎名，名溢乎暴，謀稽乎誸，知出乎爭，柴生乎守，官事果乎眾宜。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-38_s-3","passageId":"zhuangzi_ch-26_p-38","order":3,"canonicalText":"春雨日時，草木怒生，銚鎒於是乎始脩，草木之到植者過半而不知其然。","chunks":[["春雨日時，草木怒生，銚鎒於是乎始脩，草木之到植者過半而不知其然。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-39_s-1","passageId":"zhuangzi_ch-26_p-39","order":1,"canonicalText":"「靜然可以補病，眥搣可以休老，寧可以止遽。","chunks":[["「靜然可以補病，眥搣可以休老，寧可以止遽。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-39_s-2","passageId":"zhuangzi_ch-26_p-39","order":2,"canonicalText":"雖然，若是，勞者之務也，非佚者之所未嘗過而問焉。","chunks":[["雖然，若是，勞者之務也，非佚者之所未嘗過而問焉。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-39_s-3","passageId":"zhuangzi_ch-26_p-39","order":3,"canonicalText":"聖人之所以駴天下，神人未嘗過而問焉；","chunks":[["聖人之所以駴天下，神人未嘗過而問焉；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-40_s-1","passageId":"zhuangzi_ch-26_p-40","order":1,"canonicalText":"賢人所以駴世，聖人未嘗過而問焉；","chunks":[["賢人所以駴世，聖人未嘗過而問焉；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-40_s-2","passageId":"zhuangzi_ch-26_p-40","order":2,"canonicalText":"君子所以駴國，賢人未嘗過而問焉；","chunks":[["君子所以駴國，賢人未嘗過而問焉；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-40_s-3","passageId":"zhuangzi_ch-26_p-40","order":3,"canonicalText":"小人所以合時，君子未嘗過而問焉。","chunks":[["小人所以合時，君子未嘗過而問焉。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-41_s-1","passageId":"zhuangzi_ch-26_p-41","order":1,"canonicalText":"演門有親死者，以善毀爵為官師，其黨人毀而死者半。","chunks":[["演門有親死者，以善毀爵為官師，其黨人毀而死者半。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-42_s-1","passageId":"zhuangzi_ch-26_p-42","order":1,"canonicalText":"堯與許由天下，許由逃之；","chunks":[["堯與許由天下，許由逃之；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-42_s-2","passageId":"zhuangzi_ch-26_p-42","order":2,"canonicalText":"湯與務光，務光怒之，紀他聞之，帥弟子而踆於窾水，諸侯弔之，三年，申徒狄因以踣河。","chunks":[["湯與務光，務光怒之，紀他聞之，帥弟子而踆於窾水，諸侯弔之，三年，申徒狄因以踣河。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-43_s-1","passageId":"zhuangzi_ch-26_p-43","order":1,"canonicalText":"荃者所以在魚，得魚而忘荃；","chunks":[["荃者所以在魚，得魚而忘荃；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-43_s-2","passageId":"zhuangzi_ch-26_p-43","order":2,"canonicalText":"蹄者所以在兔，得兔而忘蹄；","chunks":[["蹄者所以在兔，得兔而忘蹄；","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-43_s-3","passageId":"zhuangzi_ch-26_p-43","order":3,"canonicalText":"言者所以在意，得意而忘言。","chunks":[["言者所以在意，得意而忘言。","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-43_s-4","passageId":"zhuangzi_ch-26_p-43","order":4,"canonicalText":"吾安得夫忘言之人而與之言哉！","chunks":[["吾安得夫忘言之人而與之言哉！","zh-Hant"]]},{"id":"zhuangzi_ch-26_p-43_s-5","passageId":"zhuangzi_ch-26_p-43","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-1_s-1","passageId":"zhuangzi_ch-27_p-1","order":1,"canonicalText":"寓言十九，重言十七，巵言日出，和以天倪。","chunks":[["寓言十九，重言十七，巵言日出，和以天倪。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-1","passageId":"zhuangzi_ch-27_p-2","order":1,"canonicalText":"寓言十九，藉外論之。","chunks":[["寓言十九，藉外論之。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-2","passageId":"zhuangzi_ch-27_p-2","order":2,"canonicalText":"親父不為其子媒。","chunks":[["親父不為其子媒。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-3","passageId":"zhuangzi_ch-27_p-2","order":3,"canonicalText":"親父譽之，不若非其父者也；","chunks":[["親父譽之，不若非其父者也；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-4","passageId":"zhuangzi_ch-27_p-2","order":4,"canonicalText":"非吾罪也，人之罪也。","chunks":[["非吾罪也，人之罪也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-5","passageId":"zhuangzi_ch-27_p-2","order":5,"canonicalText":"與己同則應，不與己同則反；","chunks":[["與己同則應，不與己同則反；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-2_s-6","passageId":"zhuangzi_ch-27_p-2","order":6,"canonicalText":"同於己為是之，異於己為非之。","chunks":[["同於己為是之，異於己為非之。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-3_s-1","passageId":"zhuangzi_ch-27_p-3","order":1,"canonicalText":"重言十七，所以已言也，是為耆艾。","chunks":[["重言十七，所以已言也，是為耆艾。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-3_s-2","passageId":"zhuangzi_ch-27_p-3","order":2,"canonicalText":"年先矣，而无經緯本末以期年耆者，是非先也。","chunks":[["年先矣，而无經緯本末以期年耆者，是非先也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-3_s-3","passageId":"zhuangzi_ch-27_p-3","order":3,"canonicalText":"人而无以先人，无人道也；","chunks":[["人而无以先人，无人道也；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-3_s-4","passageId":"zhuangzi_ch-27_p-3","order":4,"canonicalText":"人而无人道，是之謂陳人。","chunks":[["人而无人道，是之謂陳人。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-4_s-1","passageId":"zhuangzi_ch-27_p-4","order":1,"canonicalText":"巵言日出，和以天倪，因以曼衍，所以窮年。","chunks":[["巵言日出，和以天倪，因以曼衍，所以窮年。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-4_s-2","passageId":"zhuangzi_ch-27_p-4","order":2,"canonicalText":"不言則齊，齊與言不齊，言與齊不齊也，故曰言无言。","chunks":[["不言則齊，齊與言不齊，言與齊不齊也，故曰言无言。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-5_s-1","passageId":"zhuangzi_ch-27_p-5","order":1,"canonicalText":"言无言，終身言，未嘗不言；","chunks":[["言无言，終身言，未嘗不言；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-5_s-2","passageId":"zhuangzi_ch-27_p-5","order":2,"canonicalText":"終身不言，未嘗不言。","chunks":[["終身不言，未嘗不言。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-5_s-3","passageId":"zhuangzi_ch-27_p-5","order":3,"canonicalText":"有自也而可，有自也而不可；","chunks":[["有自也而可，有自也而不可；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-5_s-4","passageId":"zhuangzi_ch-27_p-5","order":4,"canonicalText":"有自也而然，有自也而不然。","chunks":[["有自也而然，有自也而不然。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-1","passageId":"zhuangzi_ch-27_p-6","order":1,"canonicalText":"惡乎然？","chunks":[["惡乎然？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-2","passageId":"zhuangzi_ch-27_p-6","order":2,"canonicalText":"然於然。","chunks":[["然於然。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-3","passageId":"zhuangzi_ch-27_p-6","order":3,"canonicalText":"惡乎不然？","chunks":[["惡乎不然？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-4","passageId":"zhuangzi_ch-27_p-6","order":4,"canonicalText":"不然於不然。","chunks":[["不然於不然。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-5","passageId":"zhuangzi_ch-27_p-6","order":5,"canonicalText":"惡乎可？","chunks":[["惡乎可？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-6","passageId":"zhuangzi_ch-27_p-6","order":6,"canonicalText":"可於可。","chunks":[["可於可。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-7","passageId":"zhuangzi_ch-27_p-6","order":7,"canonicalText":"惡乎不可？","chunks":[["惡乎不可？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-8","passageId":"zhuangzi_ch-27_p-6","order":8,"canonicalText":"不可於不可。","chunks":[["不可於不可。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-6_s-9","passageId":"zhuangzi_ch-27_p-6","order":9,"canonicalText":"物固有所然，物固有所可，无物不然，无物不可。","chunks":[["物固有所然，物固有所可，无物不然，无物不可。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-7_s-1","passageId":"zhuangzi_ch-27_p-7","order":1,"canonicalText":"非巵言日出，和以天倪，孰得其久！","chunks":[["非巵言日出，和以天倪，孰得其久！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-7_s-2","passageId":"zhuangzi_ch-27_p-7","order":2,"canonicalText":"萬物皆種也，以不同形相禪，始卒若環，莫得其倫，是謂天均。","chunks":[["萬物皆種也，以不同形相禪，始卒若環，莫得其倫，是謂天均。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-7_s-3","passageId":"zhuangzi_ch-27_p-7","order":3,"canonicalText":"天均者，天倪也。","chunks":[["天均者，天倪也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-8_s-1","passageId":"zhuangzi_ch-27_p-8","order":1,"canonicalText":"莊子謂惠子曰：「孔子行年六十而六十化，始時所是，卒而非之，未知今之所謂是之非五十九非也。","chunks":[["莊子謂惠子曰：「孔子行年六十而六十化，始時所是，卒而非之，未知今之所謂是之非五十九非也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-8_s-2","passageId":"zhuangzi_ch-27_p-8","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-9_s-1","passageId":"zhuangzi_ch-27_p-9","order":1,"canonicalText":"惠子曰：「孔子勤志服知也。","chunks":[["惠子曰：「孔子勤志服知也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-9_s-2","passageId":"zhuangzi_ch-27_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-10_s-1","passageId":"zhuangzi_ch-27_p-10","order":1,"canonicalText":"莊子曰：「孔子謝之矣，而其未之嘗言？","chunks":[["莊子曰：「孔子謝之矣，而其未之嘗言？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-10_s-2","passageId":"zhuangzi_ch-27_p-10","order":2,"canonicalText":"孔子云：『夫受才乎大本，復靈以生。","chunks":[["孔子云：『夫受才乎大本，復靈以生。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-10_s-3","passageId":"zhuangzi_ch-27_p-10","order":3,"canonicalText":"』鳴而當律，言而當法，利義陳乎前，而好惡是非直服人之口而已矣。","chunks":[["』鳴而當律，言而當法，利義陳乎前，而好惡是非直服人之口而已矣。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-11_s-1","passageId":"zhuangzi_ch-27_p-11","order":1,"canonicalText":"使人乃以心服，而不敢蘁立，定天下之定。","chunks":[["使人乃以心服，而不敢蘁立，定天下之定。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-11_s-2","passageId":"zhuangzi_ch-27_p-11","order":2,"canonicalText":"已乎已乎！","chunks":[["已乎已乎！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-11_s-3","passageId":"zhuangzi_ch-27_p-11","order":3,"canonicalText":"吾且不得及彼乎！","chunks":[["吾且不得及彼乎！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-11_s-4","passageId":"zhuangzi_ch-27_p-11","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-12_s-1","passageId":"zhuangzi_ch-27_p-12","order":1,"canonicalText":"曾子再仕而心再化，曰：「吾及親仕，三釜而心樂；","chunks":[["曾子再仕而心再化，曰：「吾及親仕，三釜而心樂；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-12_s-2","passageId":"zhuangzi_ch-27_p-12","order":2,"canonicalText":"後仕，三千鍾不洎，吾心悲。","chunks":[["後仕，三千鍾不洎，吾心悲。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-12_s-3","passageId":"zhuangzi_ch-27_p-12","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-13_s-1","passageId":"zhuangzi_ch-27_p-13","order":1,"canonicalText":"弟子問于仲尼曰：「若參者，可謂无所縣其罪乎？","chunks":[["弟子問于仲尼曰：「若參者，可謂无所縣其罪乎？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-13_s-2","passageId":"zhuangzi_ch-27_p-13","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-14_s-1","passageId":"zhuangzi_ch-27_p-14","order":1,"canonicalText":"曰：「既已縣矣。","chunks":[["曰：「既已縣矣。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-14_s-2","passageId":"zhuangzi_ch-27_p-14","order":2,"canonicalText":"夫无所縣者，可以有哀乎？","chunks":[["夫无所縣者，可以有哀乎？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-14_s-3","passageId":"zhuangzi_ch-27_p-14","order":3,"canonicalText":"彼視三釜三千鍾，如觀雀蚊虻相過乎前也。","chunks":[["彼視三釜三千鍾，如觀雀蚊虻相過乎前也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-14_s-4","passageId":"zhuangzi_ch-27_p-14","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-15_s-1","passageId":"zhuangzi_ch-27_p-15","order":1,"canonicalText":"顏成子游謂東郭子綦曰：「自吾聞子之言，一年而野，二年而從，三年而通，四年而物，五年而來，六年而鬼入，七年而天成，八年而不知死，不知生，九年而大妙。","chunks":[["顏成子游謂東郭子綦曰：「自吾聞子之言，一年而野，二年而從，三年而通，四年而物，五年而來，六年而鬼入，七年而天成，八年而不知死，不知生，九年而大妙。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-16_s-1","passageId":"zhuangzi_ch-27_p-16","order":1,"canonicalText":"生有為，死也。","chunks":[["生有為，死也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-16_s-2","passageId":"zhuangzi_ch-27_p-16","order":2,"canonicalText":"勸公，以其死也，有自也；","chunks":[["勸公，以其死也，有自也；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-16_s-3","passageId":"zhuangzi_ch-27_p-16","order":3,"canonicalText":"而生陽也，无自也。","chunks":[["而生陽也，无自也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-1","passageId":"zhuangzi_ch-27_p-17","order":1,"canonicalText":"而果然乎？","chunks":[["而果然乎？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-2","passageId":"zhuangzi_ch-27_p-17","order":2,"canonicalText":"惡乎其所適？","chunks":[["惡乎其所適？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-3","passageId":"zhuangzi_ch-27_p-17","order":3,"canonicalText":"惡乎其所不適？","chunks":[["惡乎其所不適？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-4","passageId":"zhuangzi_ch-27_p-17","order":4,"canonicalText":"天有歷數，地有人據，吾惡乎求之？","chunks":[["天有歷數，地有人據，吾惡乎求之？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-5","passageId":"zhuangzi_ch-27_p-17","order":5,"canonicalText":"莫知其所終，若之何其无命也？","chunks":[["莫知其所終，若之何其无命也？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-6","passageId":"zhuangzi_ch-27_p-17","order":6,"canonicalText":"莫知其所始，若之何其有命也？","chunks":[["莫知其所始，若之何其有命也？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-7","passageId":"zhuangzi_ch-27_p-17","order":7,"canonicalText":"有以相應也，若之何其无鬼邪？","chunks":[["有以相應也，若之何其无鬼邪？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-8","passageId":"zhuangzi_ch-27_p-17","order":8,"canonicalText":"无以相應也，若之何其有鬼邪？","chunks":[["无以相應也，若之何其有鬼邪？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-17_s-9","passageId":"zhuangzi_ch-27_p-17","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-18_s-1","passageId":"zhuangzi_ch-27_p-18","order":1,"canonicalText":"眾罔兩問於影曰：「若向也俯而今也仰，向也括而今也被髮，向也坐而今也起，向也行而今也止，何也？","chunks":[["眾罔兩問於影曰：「若向也俯而今也仰，向也括而今也被髮，向也坐而今也起，向也行而今也止，何也？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-18_s-2","passageId":"zhuangzi_ch-27_p-18","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-19_s-1","passageId":"zhuangzi_ch-27_p-19","order":1,"canonicalText":"影曰：「叟叟也，奚稍問也！","chunks":[["影曰：「叟叟也，奚稍問也！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-19_s-2","passageId":"zhuangzi_ch-27_p-19","order":2,"canonicalText":"予有而不知其所以。","chunks":[["予有而不知其所以。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-19_s-3","passageId":"zhuangzi_ch-27_p-19","order":3,"canonicalText":"予，蜩甲也，蛇蛻也，似之而非也。","chunks":[["予，蜩甲也，蛇蛻也，似之而非也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-19_s-4","passageId":"zhuangzi_ch-27_p-19","order":4,"canonicalText":"火與日，吾屯也；","chunks":[["火與日，吾屯也；","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-19_s-5","passageId":"zhuangzi_ch-27_p-19","order":5,"canonicalText":"陰與夜，吾代也。","chunks":[["陰與夜，吾代也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-20_s-1","passageId":"zhuangzi_ch-27_p-20","order":1,"canonicalText":"彼吾所以有待邪？","chunks":[["彼吾所以有待邪？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-20_s-2","passageId":"zhuangzi_ch-27_p-20","order":2,"canonicalText":"而況乎无待者乎！","chunks":[["而況乎无待者乎！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-20_s-3","passageId":"zhuangzi_ch-27_p-20","order":3,"canonicalText":"彼來則我與之來，彼往則我與之往，彼強陽則我與之強陽。","chunks":[["彼來則我與之來，彼往則我與之往，彼強陽則我與之強陽。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-20_s-4","passageId":"zhuangzi_ch-27_p-20","order":4,"canonicalText":"強陽者又何以有問乎！","chunks":[["強陽者又何以有問乎！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-20_s-5","passageId":"zhuangzi_ch-27_p-20","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-21_s-1","passageId":"zhuangzi_ch-27_p-21","order":1,"canonicalText":"陽子居南之沛，老聃西遊於秦，邀於郊，至於梁而遇老子。","chunks":[["陽子居南之沛，老聃西遊於秦，邀於郊，至於梁而遇老子。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-21_s-2","passageId":"zhuangzi_ch-27_p-21","order":2,"canonicalText":"老子中道仰天而歎曰：「始以汝為可教，今不可也。","chunks":[["老子中道仰天而歎曰：「始以汝為可教，今不可也。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-21_s-3","passageId":"zhuangzi_ch-27_p-21","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-22_s-1","passageId":"zhuangzi_ch-27_p-22","order":1,"canonicalText":"陽子居不荅。","chunks":[["陽子居不荅。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-22_s-2","passageId":"zhuangzi_ch-27_p-22","order":2,"canonicalText":"至舍，進盥漱巾櫛，脫屨戶外，膝行而前曰：「向者弟子欲請夫子，夫子行不閒，是以不敢。","chunks":[["至舍，進盥漱巾櫛，脫屨戶外，膝行而前曰：「向者弟子欲請夫子，夫子行不閒，是以不敢。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-22_s-3","passageId":"zhuangzi_ch-27_p-22","order":3,"canonicalText":"今閒矣，請問其過。","chunks":[["今閒矣，請問其過。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-22_s-4","passageId":"zhuangzi_ch-27_p-22","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-23_s-1","passageId":"zhuangzi_ch-27_p-23","order":1,"canonicalText":"老子曰：「而睢睢，而盱盱，而誰與居？","chunks":[["老子曰：「而睢睢，而盱盱，而誰與居？","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-23_s-2","passageId":"zhuangzi_ch-27_p-23","order":2,"canonicalText":"大白若辱，盛德若不足。","chunks":[["大白若辱，盛德若不足。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-23_s-3","passageId":"zhuangzi_ch-27_p-23","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-24_s-1","passageId":"zhuangzi_ch-27_p-24","order":1,"canonicalText":"陽子居蹴然變容曰：「敬聞命矣！","chunks":[["陽子居蹴然變容曰：「敬聞命矣！","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-24_s-2","passageId":"zhuangzi_ch-27_p-24","order":2,"canonicalText":"」其往也，舍者迎將，其家公執席，妻執巾櫛，舍者避席，煬者避竈。","chunks":[["」其往也，舍者迎將，其家公執席，妻執巾櫛，舍者避席，煬者避竈。","zh-Hant"]]},{"id":"zhuangzi_ch-27_p-24_s-3","passageId":"zhuangzi_ch-27_p-24","order":3,"canonicalText":"其反也，舍者與之爭席矣。","chunks":[["其反也，舍者與之爭席矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-1_s-1","passageId":"zhuangzi_ch-28_p-1","order":1,"canonicalText":"堯以天下讓許由，許由不受。","chunks":[["堯以天下讓許由，許由不受。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-1_s-2","passageId":"zhuangzi_ch-28_p-1","order":2,"canonicalText":"又讓於子州支父，子州支父曰：「以我為天子，猶之可也。","chunks":[["又讓於子州支父，子州支父曰：「以我為天子，猶之可也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-2_s-1","passageId":"zhuangzi_ch-28_p-2","order":1,"canonicalText":"雖然，我適有幽憂之病，方且治之，未暇治天下也。","chunks":[["雖然，我適有幽憂之病，方且治之，未暇治天下也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-2_s-2","passageId":"zhuangzi_ch-28_p-2","order":2,"canonicalText":"」夫天下至重也，而不以害其生，又況他物乎！","chunks":[["」夫天下至重也，而不以害其生，又況他物乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-2_s-3","passageId":"zhuangzi_ch-28_p-2","order":3,"canonicalText":"唯无以天下為者，可以託天下也。","chunks":[["唯无以天下為者，可以託天下也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-3_s-1","passageId":"zhuangzi_ch-28_p-3","order":1,"canonicalText":"舜讓天下於子州支伯。","chunks":[["舜讓天下於子州支伯。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-3_s-2","passageId":"zhuangzi_ch-28_p-3","order":2,"canonicalText":"子州支伯曰：「予適有幽憂之病，方且治之，未暇治天下也。","chunks":[["子州支伯曰：「予適有幽憂之病，方且治之，未暇治天下也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-3_s-3","passageId":"zhuangzi_ch-28_p-3","order":3,"canonicalText":"」故天下大器也，而不以易生，此有道者之所以異乎俗者也。","chunks":[["」故天下大器也，而不以易生，此有道者之所以異乎俗者也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-4_s-1","passageId":"zhuangzi_ch-28_p-4","order":1,"canonicalText":"舜以天下讓善卷，善卷曰：「余立於宇宙之中，冬日衣皮毛，夏日衣葛絺；","chunks":[["舜以天下讓善卷，善卷曰：「余立於宇宙之中，冬日衣皮毛，夏日衣葛絺；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-4_s-2","passageId":"zhuangzi_ch-28_p-4","order":2,"canonicalText":"春耕種，形足以勞動；","chunks":[["春耕種，形足以勞動；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-4_s-3","passageId":"zhuangzi_ch-28_p-4","order":3,"canonicalText":"秋收斂，身足以休食；","chunks":[["秋收斂，身足以休食；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-5_s-1","passageId":"zhuangzi_ch-28_p-5","order":1,"canonicalText":"日出而作，日入而息，逍遙於天地之閒而心意自得。","chunks":[["日出而作，日入而息，逍遙於天地之閒而心意自得。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-5_s-2","passageId":"zhuangzi_ch-28_p-5","order":2,"canonicalText":"吾何以天下為哉！","chunks":[["吾何以天下為哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-5_s-3","passageId":"zhuangzi_ch-28_p-5","order":3,"canonicalText":"悲夫，子之不知余也！","chunks":[["悲夫，子之不知余也！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-5_s-4","passageId":"zhuangzi_ch-28_p-5","order":4,"canonicalText":"」遂不受。","chunks":[["」遂不受。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-5_s-5","passageId":"zhuangzi_ch-28_p-5","order":5,"canonicalText":"於是去而入深山，莫知其處。","chunks":[["於是去而入深山，莫知其處。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-6_s-1","passageId":"zhuangzi_ch-28_p-6","order":1,"canonicalText":"舜以天下讓其友石戶之農，石戶之農曰：「捲捲乎后之為人，葆力之士也！","chunks":[["舜以天下讓其友石戶之農，石戶之農曰：「捲捲乎后之為人，葆力之士也！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-6_s-2","passageId":"zhuangzi_ch-28_p-6","order":2,"canonicalText":"」以舜之德為未至也，於是夫負妻戴，攜子以入於海，終身不反也。","chunks":[["」以舜之德為未至也，於是夫負妻戴，攜子以入於海，終身不反也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-7_s-1","passageId":"zhuangzi_ch-28_p-7","order":1,"canonicalText":"大王亶父居邠，狄人攻之；","chunks":[["大王亶父居邠，狄人攻之；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-7_s-2","passageId":"zhuangzi_ch-28_p-7","order":2,"canonicalText":"事之以皮帛而不受，事之以犬馬而不受，事之以珠玉而不受，","chunks":[["事之以皮帛而不受，事之以犬馬而不受，事之以珠玉而不受，","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-8_s-1","passageId":"zhuangzi_ch-28_p-8","order":1,"canonicalText":"狄人之所求者土地也。","chunks":[["狄人之所求者土地也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-8_s-2","passageId":"zhuangzi_ch-28_p-8","order":2,"canonicalText":"大王亶父曰：「與人之兄居而殺其弟，與人之父居而殺其子，吾不忍也。","chunks":[["大王亶父曰：「與人之兄居而殺其弟，與人之父居而殺其子，吾不忍也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-8_s-3","passageId":"zhuangzi_ch-28_p-8","order":3,"canonicalText":"子皆勉居矣！","chunks":[["子皆勉居矣！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-9_s-1","passageId":"zhuangzi_ch-28_p-9","order":1,"canonicalText":"為吾臣與為狄人臣奚以異！","chunks":[["為吾臣與為狄人臣奚以異！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-9_s-2","passageId":"zhuangzi_ch-28_p-9","order":2,"canonicalText":"且吾聞之，不以所用養害所養。","chunks":[["且吾聞之，不以所用養害所養。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-9_s-3","passageId":"zhuangzi_ch-28_p-9","order":3,"canonicalText":"」因杖筴而去之。","chunks":[["」因杖筴而去之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-9_s-4","passageId":"zhuangzi_ch-28_p-9","order":4,"canonicalText":"民相連而從之，遂成國於岐山之下。","chunks":[["民相連而從之，遂成國於岐山之下。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-10_s-1","passageId":"zhuangzi_ch-28_p-10","order":1,"canonicalText":"夫大王亶父，可謂能尊生矣。","chunks":[["夫大王亶父，可謂能尊生矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-10_s-2","passageId":"zhuangzi_ch-28_p-10","order":2,"canonicalText":"能尊生者，雖貴富不以養傷身，雖貧賤不以利累形。","chunks":[["能尊生者，雖貴富不以養傷身，雖貧賤不以利累形。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-10_s-3","passageId":"zhuangzi_ch-28_p-10","order":3,"canonicalText":"今世之人居高官尊爵者，皆重失之，見利輕亡其身，豈不惑哉！","chunks":[["今世之人居高官尊爵者，皆重失之，見利輕亡其身，豈不惑哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-11_s-1","passageId":"zhuangzi_ch-28_p-11","order":1,"canonicalText":"越人三世弒其君，王子搜患之，逃乎丹穴。","chunks":[["越人三世弒其君，王子搜患之，逃乎丹穴。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-11_s-2","passageId":"zhuangzi_ch-28_p-11","order":2,"canonicalText":"而越國无君，求王子搜不得，從之丹穴。","chunks":[["而越國无君，求王子搜不得，從之丹穴。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-11_s-3","passageId":"zhuangzi_ch-28_p-11","order":3,"canonicalText":"王子搜不肯出，越人薰之以艾。","chunks":[["王子搜不肯出，越人薰之以艾。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-11_s-4","passageId":"zhuangzi_ch-28_p-11","order":4,"canonicalText":"乘以玉輿。","chunks":[["乘以玉輿。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-12_s-1","passageId":"zhuangzi_ch-28_p-12","order":1,"canonicalText":"王子搜援綏登車，仰天而呼曰：「君乎君乎！","chunks":[["王子搜援綏登車，仰天而呼曰：「君乎君乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-12_s-2","passageId":"zhuangzi_ch-28_p-12","order":2,"canonicalText":"獨不可以舍我乎！","chunks":[["獨不可以舍我乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-12_s-3","passageId":"zhuangzi_ch-28_p-12","order":3,"canonicalText":"」王子搜非惡為君也，惡為君之患也。","chunks":[["」王子搜非惡為君也，惡為君之患也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-12_s-4","passageId":"zhuangzi_ch-28_p-12","order":4,"canonicalText":"若王子搜者，可謂不以國傷生矣，此固越人之所欲得為君也。","chunks":[["若王子搜者，可謂不以國傷生矣，此固越人之所欲得為君也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-13_s-1","passageId":"zhuangzi_ch-28_p-13","order":1,"canonicalText":"韓魏相與爭侵地。","chunks":[["韓魏相與爭侵地。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-13_s-2","passageId":"zhuangzi_ch-28_p-13","order":2,"canonicalText":"子華子見昭僖侯，昭僖侯有憂色。","chunks":[["子華子見昭僖侯，昭僖侯有憂色。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-13_s-3","passageId":"zhuangzi_ch-28_p-13","order":3,"canonicalText":"子華子曰：「今使天下書銘於君之前，書之言曰：『左手攫之則右手廢，右手攫之則左手廢，然而攫之者必有天下。","chunks":[["子華子曰：「今使天下書銘於君之前，書之言曰：『左手攫之則右手廢，右手攫之則左手廢，然而攫之者必有天下。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-13_s-4","passageId":"zhuangzi_ch-28_p-13","order":4,"canonicalText":"』君能攫之乎？","chunks":[["』君能攫之乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-13_s-5","passageId":"zhuangzi_ch-28_p-13","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-14_s-1","passageId":"zhuangzi_ch-28_p-14","order":1,"canonicalText":"昭僖侯曰：「寡人不攫也。","chunks":[["昭僖侯曰：「寡人不攫也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-14_s-2","passageId":"zhuangzi_ch-28_p-14","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-15_s-1","passageId":"zhuangzi_ch-28_p-15","order":1,"canonicalText":"子華子曰：「甚善！","chunks":[["子華子曰：「甚善！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-15_s-2","passageId":"zhuangzi_ch-28_p-15","order":2,"canonicalText":"自是觀之，兩臂重於天下也，身亦重於兩臂。","chunks":[["自是觀之，兩臂重於天下也，身亦重於兩臂。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-15_s-3","passageId":"zhuangzi_ch-28_p-15","order":3,"canonicalText":"韓之輕於天下亦遠矣，今之所爭者，其輕於韓又遠。","chunks":[["韓之輕於天下亦遠矣，今之所爭者，其輕於韓又遠。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-15_s-4","passageId":"zhuangzi_ch-28_p-15","order":4,"canonicalText":"君固愁身傷生以憂戚不得也！","chunks":[["君固愁身傷生以憂戚不得也！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-15_s-5","passageId":"zhuangzi_ch-28_p-15","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-16_s-1","passageId":"zhuangzi_ch-28_p-16","order":1,"canonicalText":"僖侯曰：「善哉！","chunks":[["僖侯曰：「善哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-16_s-2","passageId":"zhuangzi_ch-28_p-16","order":2,"canonicalText":"教寡人者眾矣，未嘗得聞此言也。","chunks":[["教寡人者眾矣，未嘗得聞此言也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-16_s-3","passageId":"zhuangzi_ch-28_p-16","order":3,"canonicalText":"」子華子可謂知輕重矣。","chunks":[["」子華子可謂知輕重矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-1","passageId":"zhuangzi_ch-28_p-17","order":1,"canonicalText":"魯君聞顏闔得道之人也，使人以幣先焉。","chunks":[["魯君聞顏闔得道之人也，使人以幣先焉。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-2","passageId":"zhuangzi_ch-28_p-17","order":2,"canonicalText":"顏闔守陋閭，苴布之衣而自飯牛。","chunks":[["顏闔守陋閭，苴布之衣而自飯牛。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-3","passageId":"zhuangzi_ch-28_p-17","order":3,"canonicalText":"魯君之使者至，顏闔自對之。","chunks":[["魯君之使者至，顏闔自對之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-4","passageId":"zhuangzi_ch-28_p-17","order":4,"canonicalText":"使者曰：「此顏闔之家與？","chunks":[["使者曰：「此顏闔之家與？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-5","passageId":"zhuangzi_ch-28_p-17","order":5,"canonicalText":"」顏闔對曰：「此闔之家也。","chunks":[["」顏闔對曰：「此闔之家也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-17_s-6","passageId":"zhuangzi_ch-28_p-17","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-18_s-1","passageId":"zhuangzi_ch-28_p-18","order":1,"canonicalText":"使者致幣，顏闔對曰：「恐聽者謬而遺使者罪，不若審之。","chunks":[["使者致幣，顏闔對曰：「恐聽者謬而遺使者罪，不若審之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-18_s-2","passageId":"zhuangzi_ch-28_p-18","order":2,"canonicalText":"」使者還反審之，復來求之，則不得已。","chunks":[["」使者還反審之，復來求之，則不得已。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-18_s-3","passageId":"zhuangzi_ch-28_p-18","order":3,"canonicalText":"故若顏闔者，非惡富貴也，由重生惡之也。","chunks":[["故若顏闔者，非惡富貴也，由重生惡之也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-19_s-1","passageId":"zhuangzi_ch-28_p-19","order":1,"canonicalText":"故曰：「道之真以治身，其緒餘以為國家，其土苴以治天下。","chunks":[["故曰：「道之真以治身，其緒餘以為國家，其土苴以治天下。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-19_s-2","passageId":"zhuangzi_ch-28_p-19","order":2,"canonicalText":"」由此觀之，帝王之功，聖人之餘事也，非所以完身養生也。","chunks":[["」由此觀之，帝王之功，聖人之餘事也，非所以完身養生也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-20_s-1","passageId":"zhuangzi_ch-28_p-20","order":1,"canonicalText":"今世俗之君子，多危身棄生以殉物，豈不悲哉！","chunks":[["今世俗之君子，多危身棄生以殉物，豈不悲哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-21_s-1","passageId":"zhuangzi_ch-28_p-21","order":1,"canonicalText":"凡聖人之動作也，必察其所以之與其所以為。","chunks":[["凡聖人之動作也，必察其所以之與其所以為。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-21_s-2","passageId":"zhuangzi_ch-28_p-21","order":2,"canonicalText":"今且有人於此，以隨侯之珠彈千仞之雀，世必笑之。","chunks":[["今且有人於此，以隨侯之珠彈千仞之雀，世必笑之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-21_s-3","passageId":"zhuangzi_ch-28_p-21","order":3,"canonicalText":"是何也？","chunks":[["是何也？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-21_s-4","passageId":"zhuangzi_ch-28_p-21","order":4,"canonicalText":"則其所用者重而所要者輕也。","chunks":[["則其所用者重而所要者輕也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-21_s-5","passageId":"zhuangzi_ch-28_p-21","order":5,"canonicalText":"夫生者，豈特隨侯珠之重哉！","chunks":[["夫生者，豈特隨侯珠之重哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-22_s-1","passageId":"zhuangzi_ch-28_p-22","order":1,"canonicalText":"子列子窮，容貌有飢色。","chunks":[["子列子窮，容貌有飢色。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-22_s-2","passageId":"zhuangzi_ch-28_p-22","order":2,"canonicalText":"客有言之於鄭子陽者曰：「列御寇，蓋有道之士也，居君之國而窮，君无乃為不好士乎？","chunks":[["客有言之於鄭子陽者曰：「列御寇，蓋有道之士也，居君之國而窮，君无乃為不好士乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-22_s-3","passageId":"zhuangzi_ch-28_p-22","order":3,"canonicalText":"」鄭子陽即令官遺之粟。","chunks":[["」鄭子陽即令官遺之粟。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-22_s-4","passageId":"zhuangzi_ch-28_p-22","order":4,"canonicalText":"子列子出見使者，再拜而辭。","chunks":[["子列子出見使者，再拜而辭。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-23_s-1","passageId":"zhuangzi_ch-28_p-23","order":1,"canonicalText":"使者去，子列子入，其妻望之而拊心曰：「妾聞為有道者之妻子，皆得佚樂，今有飢色。","chunks":[["使者去，子列子入，其妻望之而拊心曰：「妾聞為有道者之妻子，皆得佚樂，今有飢色。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-23_s-2","passageId":"zhuangzi_ch-28_p-23","order":2,"canonicalText":"君過而遺先生食，先生不受，豈不命邪！","chunks":[["君過而遺先生食，先生不受，豈不命邪！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-23_s-3","passageId":"zhuangzi_ch-28_p-23","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-24_s-1","passageId":"zhuangzi_ch-28_p-24","order":1,"canonicalText":"子列子笑謂之曰：「君非自知我也。","chunks":[["子列子笑謂之曰：「君非自知我也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-24_s-2","passageId":"zhuangzi_ch-28_p-24","order":2,"canonicalText":"以人之言而遺我粟，至其罪我也又且以人之言，此吾所以不受也。","chunks":[["以人之言而遺我粟，至其罪我也又且以人之言，此吾所以不受也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-24_s-3","passageId":"zhuangzi_ch-28_p-24","order":3,"canonicalText":"」其卒，民果作難而殺子陽。","chunks":[["」其卒，民果作難而殺子陽。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-1","passageId":"zhuangzi_ch-28_p-25","order":1,"canonicalText":"楚昭王失國，屠羊說走而從於昭王。","chunks":[["楚昭王失國，屠羊說走而從於昭王。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-2","passageId":"zhuangzi_ch-28_p-25","order":2,"canonicalText":"昭王反國，將賞從者，及屠羊說。","chunks":[["昭王反國，將賞從者，及屠羊說。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-3","passageId":"zhuangzi_ch-28_p-25","order":3,"canonicalText":"屠羊說曰：「大王失國，說失屠羊；","chunks":[["屠羊說曰：「大王失國，說失屠羊；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-4","passageId":"zhuangzi_ch-28_p-25","order":4,"canonicalText":"大王反國，說亦反屠羊。","chunks":[["大王反國，說亦反屠羊。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-5","passageId":"zhuangzi_ch-28_p-25","order":5,"canonicalText":"臣之爵祿已復矣，又何賞之有！","chunks":[["臣之爵祿已復矣，又何賞之有！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-25_s-6","passageId":"zhuangzi_ch-28_p-25","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-26_s-1","passageId":"zhuangzi_ch-28_p-26","order":1,"canonicalText":"王曰：「強之！","chunks":[["王曰：「強之！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-26_s-2","passageId":"zhuangzi_ch-28_p-26","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-27_s-1","passageId":"zhuangzi_ch-28_p-27","order":1,"canonicalText":"屠羊說曰：「大王失國，非臣之罪，故不敢伏其誅；","chunks":[["屠羊說曰：「大王失國，非臣之罪，故不敢伏其誅；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-27_s-2","passageId":"zhuangzi_ch-28_p-27","order":2,"canonicalText":"大王反國，非臣之功，故不敢當其賞。","chunks":[["大王反國，非臣之功，故不敢當其賞。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-27_s-3","passageId":"zhuangzi_ch-28_p-27","order":3,"canonicalText":"」王曰：「見之！","chunks":[["」王曰：「見之！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-27_s-4","passageId":"zhuangzi_ch-28_p-27","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-28_s-1","passageId":"zhuangzi_ch-28_p-28","order":1,"canonicalText":"屠羊說曰：「楚國之法，必有重賞大功而後得見，今臣之知不足以存國而勇不足以死寇。","chunks":[["屠羊說曰：「楚國之法，必有重賞大功而後得見，今臣之知不足以存國而勇不足以死寇。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-29_s-1","passageId":"zhuangzi_ch-28_p-29","order":1,"canonicalText":"吳軍入郢，說畏難而避寇，非故隨大王也。","chunks":[["吳軍入郢，說畏難而避寇，非故隨大王也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-29_s-2","passageId":"zhuangzi_ch-28_p-29","order":2,"canonicalText":"今大王欲廢法毀約而見說，此非臣之所以聞於天下也。","chunks":[["今大王欲廢法毀約而見說，此非臣之所以聞於天下也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-29_s-3","passageId":"zhuangzi_ch-28_p-29","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-30_s-1","passageId":"zhuangzi_ch-28_p-30","order":1,"canonicalText":"王謂司馬子綦曰：「屠羊說居處卑賤而陳義甚高，子其為我延之以三旌之位。","chunks":[["王謂司馬子綦曰：「屠羊說居處卑賤而陳義甚高，子其為我延之以三旌之位。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-30_s-2","passageId":"zhuangzi_ch-28_p-30","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-31_s-1","passageId":"zhuangzi_ch-28_p-31","order":1,"canonicalText":"屠羊說曰：「夫三旌之位，吾知其貴於屠羊之肆也；","chunks":[["屠羊說曰：「夫三旌之位，吾知其貴於屠羊之肆也；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-31_s-2","passageId":"zhuangzi_ch-28_p-31","order":2,"canonicalText":"萬鍾之祿，吾知其富於屠羊之利也；","chunks":[["萬鍾之祿，吾知其富於屠羊之利也；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-31_s-3","passageId":"zhuangzi_ch-28_p-31","order":3,"canonicalText":"然豈可以貪爵祿而使吾君有妄施之名乎！","chunks":[["然豈可以貪爵祿而使吾君有妄施之名乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-31_s-4","passageId":"zhuangzi_ch-28_p-31","order":4,"canonicalText":"說不敢當，願復反吾屠羊之肆。","chunks":[["說不敢當，願復反吾屠羊之肆。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-31_s-5","passageId":"zhuangzi_ch-28_p-31","order":5,"canonicalText":"」遂不受也。","chunks":[["」遂不受也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-32_s-1","passageId":"zhuangzi_ch-28_p-32","order":1,"canonicalText":"原憲居魯，環堵之室，茨以生草；","chunks":[["原憲居魯，環堵之室，茨以生草；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-32_s-2","passageId":"zhuangzi_ch-28_p-32","order":2,"canonicalText":"蓬戶不完，桑以為樞；","chunks":[["蓬戶不完，桑以為樞；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-32_s-3","passageId":"zhuangzi_ch-28_p-32","order":3,"canonicalText":"而甕牗二室，褐以為塞；","chunks":[["而甕牗二室，褐以為塞；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-32_s-4","passageId":"zhuangzi_ch-28_p-32","order":4,"canonicalText":"上漏下濕，匡坐而弦歌。","chunks":[["上漏下濕，匡坐而弦歌。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-33_s-1","passageId":"zhuangzi_ch-28_p-33","order":1,"canonicalText":"子貢乘大馬，中紺而表素，軒車不容巷，往見原憲。","chunks":[["子貢乘大馬，中紺而表素，軒車不容巷，往見原憲。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-33_s-2","passageId":"zhuangzi_ch-28_p-33","order":2,"canonicalText":"原憲華冠縱履，杖藜而應門。","chunks":[["原憲華冠縱履，杖藜而應門。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-34_s-1","passageId":"zhuangzi_ch-28_p-34","order":1,"canonicalText":"子貢曰：「嘻！","chunks":[["子貢曰：「嘻！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-34_s-2","passageId":"zhuangzi_ch-28_p-34","order":2,"canonicalText":"先生何病？","chunks":[["先生何病？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-34_s-3","passageId":"zhuangzi_ch-28_p-34","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-35_s-1","passageId":"zhuangzi_ch-28_p-35","order":1,"canonicalText":"原憲應之曰：「憲聞之，无財之謂貧，學而不能行之謂病。","chunks":[["原憲應之曰：「憲聞之，无財之謂貧，學而不能行之謂病。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-35_s-2","passageId":"zhuangzi_ch-28_p-35","order":2,"canonicalText":"今憲貧也，非病也。","chunks":[["今憲貧也，非病也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-35_s-3","passageId":"zhuangzi_ch-28_p-35","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-36_s-1","passageId":"zhuangzi_ch-28_p-36","order":1,"canonicalText":"子貢逡巡而有愧色。","chunks":[["子貢逡巡而有愧色。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-36_s-2","passageId":"zhuangzi_ch-28_p-36","order":2,"canonicalText":"原憲笑曰：「夫希世而行，比周而友，學以為人，教以為己，仁義之慝，輿馬之飾，憲不忍為也。","chunks":[["原憲笑曰：「夫希世而行，比周而友，學以為人，教以為己，仁義之慝，輿馬之飾，憲不忍為也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-36_s-3","passageId":"zhuangzi_ch-28_p-36","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-37_s-1","passageId":"zhuangzi_ch-28_p-37","order":1,"canonicalText":"曾子居衛，縕袍无表，顏色腫噲，手足胼胝。","chunks":[["曾子居衛，縕袍无表，顏色腫噲，手足胼胝。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-37_s-2","passageId":"zhuangzi_ch-28_p-37","order":2,"canonicalText":"三日不舉火，十年不製衣，正冠而纓絕，捉衿而肘見，納屨而踵決。","chunks":[["三日不舉火，十年不製衣，正冠而纓絕，捉衿而肘見，納屨而踵決。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-37_s-3","passageId":"zhuangzi_ch-28_p-37","order":3,"canonicalText":"曳縰而歌《商頌》，聲滿天地，若出金石。","chunks":[["曳縰而歌《商頌》，聲滿天地，若出金石。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-38_s-1","passageId":"zhuangzi_ch-28_p-38","order":1,"canonicalText":"天子不得臣，諸侯不得友。","chunks":[["天子不得臣，諸侯不得友。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-38_s-2","passageId":"zhuangzi_ch-28_p-38","order":2,"canonicalText":"故養志者忘形，養形者忘利，致道者忘心矣。","chunks":[["故養志者忘形，養形者忘利，致道者忘心矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-39_s-1","passageId":"zhuangzi_ch-28_p-39","order":1,"canonicalText":"孔子謂顏回曰：「回，來！","chunks":[["孔子謂顏回曰：「回，來！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-39_s-2","passageId":"zhuangzi_ch-28_p-39","order":2,"canonicalText":"家貧居卑，胡不仕乎？","chunks":[["家貧居卑，胡不仕乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-39_s-3","passageId":"zhuangzi_ch-28_p-39","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-1","passageId":"zhuangzi_ch-28_p-40","order":1,"canonicalText":"顏回對曰：「不願仕。","chunks":[["顏回對曰：「不願仕。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-2","passageId":"zhuangzi_ch-28_p-40","order":2,"canonicalText":"回有郭外之田五十畝，足以給飦粥；","chunks":[["回有郭外之田五十畝，足以給飦粥；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-3","passageId":"zhuangzi_ch-28_p-40","order":3,"canonicalText":"郭內之田十畝，足以為絲麻；","chunks":[["郭內之田十畝，足以為絲麻；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-4","passageId":"zhuangzi_ch-28_p-40","order":4,"canonicalText":"鼓琴足以自娛，所學夫子之道者足以自樂也。","chunks":[["鼓琴足以自娛，所學夫子之道者足以自樂也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-5","passageId":"zhuangzi_ch-28_p-40","order":5,"canonicalText":"回不願仕。","chunks":[["回不願仕。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-40_s-6","passageId":"zhuangzi_ch-28_p-40","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-41_s-1","passageId":"zhuangzi_ch-28_p-41","order":1,"canonicalText":"孔子愀然變容曰：「善哉，回之意！","chunks":[["孔子愀然變容曰：「善哉，回之意！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-41_s-2","passageId":"zhuangzi_ch-28_p-41","order":2,"canonicalText":"丘聞之，『知足者不以利自累也，審自得者失之而不懼，行脩於內者无位而不怍。","chunks":[["丘聞之，『知足者不以利自累也，審自得者失之而不懼，行脩於內者无位而不怍。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-41_s-3","passageId":"zhuangzi_ch-28_p-41","order":3,"canonicalText":"』丘誦之久矣，今於回而後見之，是丘之得也。","chunks":[["』丘誦之久矣，今於回而後見之，是丘之得也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-41_s-4","passageId":"zhuangzi_ch-28_p-41","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-42_s-1","passageId":"zhuangzi_ch-28_p-42","order":1,"canonicalText":"中山公子牟謂瞻子曰：「身在江海之上，心居魏闕之下，奈何？","chunks":[["中山公子牟謂瞻子曰：「身在江海之上，心居魏闕之下，奈何？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-42_s-2","passageId":"zhuangzi_ch-28_p-42","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-43_s-1","passageId":"zhuangzi_ch-28_p-43","order":1,"canonicalText":"瞻子曰：「重生。","chunks":[["瞻子曰：「重生。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-43_s-2","passageId":"zhuangzi_ch-28_p-43","order":2,"canonicalText":"重生則輕利。","chunks":[["重生則輕利。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-43_s-3","passageId":"zhuangzi_ch-28_p-43","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-44_s-1","passageId":"zhuangzi_ch-28_p-44","order":1,"canonicalText":"中山公子牟曰：「雖知之，未能自勝也。","chunks":[["中山公子牟曰：「雖知之，未能自勝也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-44_s-2","passageId":"zhuangzi_ch-28_p-44","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-45_s-1","passageId":"zhuangzi_ch-28_p-45","order":1,"canonicalText":"瞻子曰：「不能自勝則從，神无惡乎？","chunks":[["瞻子曰：「不能自勝則從，神无惡乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-45_s-2","passageId":"zhuangzi_ch-28_p-45","order":2,"canonicalText":"不能自勝而強不從者，此之謂重傷。","chunks":[["不能自勝而強不從者，此之謂重傷。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-45_s-3","passageId":"zhuangzi_ch-28_p-45","order":3,"canonicalText":"重傷之人，无壽類矣。","chunks":[["重傷之人，无壽類矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-45_s-4","passageId":"zhuangzi_ch-28_p-45","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-46_s-1","passageId":"zhuangzi_ch-28_p-46","order":1,"canonicalText":"魏牟，萬乘之公子也，其隱巖穴也，難為於布衣之士；","chunks":[["魏牟，萬乘之公子也，其隱巖穴也，難為於布衣之士；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-46_s-2","passageId":"zhuangzi_ch-28_p-46","order":2,"canonicalText":"雖未至乎道，可謂有其意矣。","chunks":[["雖未至乎道，可謂有其意矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-47_s-1","passageId":"zhuangzi_ch-28_p-47","order":1,"canonicalText":"孔子窮於陳蔡之閒，七日不火食，藜羹不糝，顏色甚憊，而弦歌於室。","chunks":[["孔子窮於陳蔡之閒，七日不火食，藜羹不糝，顏色甚憊，而弦歌於室。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-47_s-2","passageId":"zhuangzi_ch-28_p-47","order":2,"canonicalText":"顏回擇菜於外，子路、子貢相與言曰：","chunks":[["顏回擇菜於外，子路、子貢相與言曰：","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-48_s-1","passageId":"zhuangzi_ch-28_p-48","order":1,"canonicalText":"「夫子再逐於魯，削迹於衛，伐樹於宋，窮於商周，圍於陳蔡，殺夫子者无罪，藉夫子者无禁。","chunks":[["「夫子再逐於魯，削迹於衛，伐樹於宋，窮於商周，圍於陳蔡，殺夫子者无罪，藉夫子者无禁。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-48_s-2","passageId":"zhuangzi_ch-28_p-48","order":2,"canonicalText":"弦歌鼓琴，未嘗絕音，君子之无恥也若此乎？","chunks":[["弦歌鼓琴，未嘗絕音，君子之无恥也若此乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-48_s-3","passageId":"zhuangzi_ch-28_p-48","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-49_s-1","passageId":"zhuangzi_ch-28_p-49","order":1,"canonicalText":"顏回无以應，入告孔子。","chunks":[["顏回无以應，入告孔子。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-49_s-2","passageId":"zhuangzi_ch-28_p-49","order":2,"canonicalText":"孔子推琴喟然而歎曰：「由與賜，細人也。","chunks":[["孔子推琴喟然而歎曰：「由與賜，細人也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-49_s-3","passageId":"zhuangzi_ch-28_p-49","order":3,"canonicalText":"召而來，吾語之。","chunks":[["召而來，吾語之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-49_s-4","passageId":"zhuangzi_ch-28_p-49","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-50_s-1","passageId":"zhuangzi_ch-28_p-50","order":1,"canonicalText":"子路、子貢入。","chunks":[["子路、子貢入。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-50_s-2","passageId":"zhuangzi_ch-28_p-50","order":2,"canonicalText":"子路曰：「如此者，可謂窮矣！","chunks":[["子路曰：「如此者，可謂窮矣！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-50_s-3","passageId":"zhuangzi_ch-28_p-50","order":3,"canonicalText":"」孔子曰：「是何言也！","chunks":[["」孔子曰：「是何言也！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-50_s-4","passageId":"zhuangzi_ch-28_p-50","order":4,"canonicalText":"君子通於道之謂通，窮於道之謂窮。","chunks":[["君子通於道之謂通，窮於道之謂窮。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-51_s-1","passageId":"zhuangzi_ch-28_p-51","order":1,"canonicalText":"今丘抱仁義之道以遭亂世之患，其何窮之為！","chunks":[["今丘抱仁義之道以遭亂世之患，其何窮之為！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-51_s-2","passageId":"zhuangzi_ch-28_p-51","order":2,"canonicalText":"故內省而不疚於道，臨難而不失其德，大寒既至，霜雪既降，吾是以知松柏之茂也。","chunks":[["故內省而不疚於道，臨難而不失其德，大寒既至，霜雪既降，吾是以知松柏之茂也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-51_s-3","passageId":"zhuangzi_ch-28_p-51","order":3,"canonicalText":"昔桓公得之莒，文公得之曹，越王得之會稽，陳蔡之隘，於丘其幸乎！","chunks":[["昔桓公得之莒，文公得之曹，越王得之會稽，陳蔡之隘，於丘其幸乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-51_s-4","passageId":"zhuangzi_ch-28_p-51","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-52_s-1","passageId":"zhuangzi_ch-28_p-52","order":1,"canonicalText":"孔子列然反琴而弦歌，子路扢然執干而舞。","chunks":[["孔子列然反琴而弦歌，子路扢然執干而舞。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-52_s-2","passageId":"zhuangzi_ch-28_p-52","order":2,"canonicalText":"子貢曰：「吾不知天之高也，地之下也。","chunks":[["子貢曰：「吾不知天之高也，地之下也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-52_s-3","passageId":"zhuangzi_ch-28_p-52","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-53_s-1","passageId":"zhuangzi_ch-28_p-53","order":1,"canonicalText":"古之得道者，窮亦樂，通亦樂。","chunks":[["古之得道者，窮亦樂，通亦樂。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-53_s-2","passageId":"zhuangzi_ch-28_p-53","order":2,"canonicalText":"所樂非窮通也，道得於此，則窮通一也，為寒暑風雨之序矣。","chunks":[["所樂非窮通也，道得於此，則窮通一也，為寒暑風雨之序矣。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-53_s-3","passageId":"zhuangzi_ch-28_p-53","order":3,"canonicalText":"故許由娛於潁陽，而共伯得乎丘首。","chunks":[["故許由娛於潁陽，而共伯得乎丘首。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-54_s-1","passageId":"zhuangzi_ch-28_p-54","order":1,"canonicalText":"舜以天下讓其友北人无擇，北人无擇曰：「異哉后之為人也，居於畎畝之中而遊堯之門！","chunks":[["舜以天下讓其友北人无擇，北人无擇曰：「異哉后之為人也，居於畎畝之中而遊堯之門！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-54_s-2","passageId":"zhuangzi_ch-28_p-54","order":2,"canonicalText":"不若是而已，又欲以其辱行漫我。","chunks":[["不若是而已，又欲以其辱行漫我。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-54_s-3","passageId":"zhuangzi_ch-28_p-54","order":3,"canonicalText":"吾羞見之。","chunks":[["吾羞見之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-54_s-4","passageId":"zhuangzi_ch-28_p-54","order":4,"canonicalText":"」因自投清泠之淵。","chunks":[["」因自投清泠之淵。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-55_s-1","passageId":"zhuangzi_ch-28_p-55","order":1,"canonicalText":"湯將伐桀，因卞隨而謀，卞隨曰：「非吾事也。","chunks":[["湯將伐桀，因卞隨而謀，卞隨曰：「非吾事也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-55_s-2","passageId":"zhuangzi_ch-28_p-55","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-56_s-1","passageId":"zhuangzi_ch-28_p-56","order":1,"canonicalText":"湯曰：「孰可？","chunks":[["湯曰：「孰可？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-56_s-2","passageId":"zhuangzi_ch-28_p-56","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-57_s-1","passageId":"zhuangzi_ch-28_p-57","order":1,"canonicalText":"曰：「吾不知也。","chunks":[["曰：「吾不知也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-57_s-2","passageId":"zhuangzi_ch-28_p-57","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-58_s-1","passageId":"zhuangzi_ch-28_p-58","order":1,"canonicalText":"湯又因務光而謀，務光曰：「非吾事也。","chunks":[["湯又因務光而謀，務光曰：「非吾事也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-58_s-2","passageId":"zhuangzi_ch-28_p-58","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-59_s-1","passageId":"zhuangzi_ch-28_p-59","order":1,"canonicalText":"湯曰：「孰可？","chunks":[["湯曰：「孰可？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-59_s-2","passageId":"zhuangzi_ch-28_p-59","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-60_s-1","passageId":"zhuangzi_ch-28_p-60","order":1,"canonicalText":"曰：「吾不知也。","chunks":[["曰：「吾不知也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-60_s-2","passageId":"zhuangzi_ch-28_p-60","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-61_s-1","passageId":"zhuangzi_ch-28_p-61","order":1,"canonicalText":"湯曰：「伊尹何如？","chunks":[["湯曰：「伊尹何如？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-61_s-2","passageId":"zhuangzi_ch-28_p-61","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-62_s-1","passageId":"zhuangzi_ch-28_p-62","order":1,"canonicalText":"曰：「強力忍垢，吾不知其他也。","chunks":[["曰：「強力忍垢，吾不知其他也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-62_s-2","passageId":"zhuangzi_ch-28_p-62","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-63_s-1","passageId":"zhuangzi_ch-28_p-63","order":1,"canonicalText":"湯遂與伊尹謀伐桀，剋之，以讓卞隨。","chunks":[["湯遂與伊尹謀伐桀，剋之，以讓卞隨。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-63_s-2","passageId":"zhuangzi_ch-28_p-63","order":2,"canonicalText":"卞隨辭曰：「后之伐桀也謀乎我，必以我為賊也；","chunks":[["卞隨辭曰：「后之伐桀也謀乎我，必以我為賊也；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-64_s-1","passageId":"zhuangzi_ch-28_p-64","order":1,"canonicalText":"勝桀而讓我，必以我為貪也。","chunks":[["勝桀而讓我，必以我為貪也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-64_s-2","passageId":"zhuangzi_ch-28_p-64","order":2,"canonicalText":"吾生乎亂世，而无道之人再來漫我以其辱行，吾不忍數聞也。","chunks":[["吾生乎亂世，而无道之人再來漫我以其辱行，吾不忍數聞也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-64_s-3","passageId":"zhuangzi_ch-28_p-64","order":3,"canonicalText":"」乃自投椆水而死。","chunks":[["」乃自投椆水而死。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-65_s-1","passageId":"zhuangzi_ch-28_p-65","order":1,"canonicalText":"湯又讓務光曰：「知者謀之，武者遂之，仁者居之，古之道也。","chunks":[["湯又讓務光曰：「知者謀之，武者遂之，仁者居之，古之道也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-65_s-2","passageId":"zhuangzi_ch-28_p-65","order":2,"canonicalText":"吾子胡不立乎？","chunks":[["吾子胡不立乎？","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-65_s-3","passageId":"zhuangzi_ch-28_p-65","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-66_s-1","passageId":"zhuangzi_ch-28_p-66","order":1,"canonicalText":"務光辭曰：「廢上，非義也；","chunks":[["務光辭曰：「廢上，非義也；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-66_s-2","passageId":"zhuangzi_ch-28_p-66","order":2,"canonicalText":"殺民，非仁也；","chunks":[["殺民，非仁也；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-66_s-3","passageId":"zhuangzi_ch-28_p-66","order":3,"canonicalText":"人犯其難，我享其利，非廉也。","chunks":[["人犯其難，我享其利，非廉也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-67_s-1","passageId":"zhuangzi_ch-28_p-67","order":1,"canonicalText":"吾聞之曰：『非其義者，不受其祿，无道之世，不踐其土。","chunks":[["吾聞之曰：『非其義者，不受其祿，无道之世，不踐其土。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-67_s-2","passageId":"zhuangzi_ch-28_p-67","order":2,"canonicalText":"』況尊我乎！","chunks":[["』況尊我乎！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-67_s-3","passageId":"zhuangzi_ch-28_p-67","order":3,"canonicalText":"吾不忍久見也。","chunks":[["吾不忍久見也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-67_s-4","passageId":"zhuangzi_ch-28_p-67","order":4,"canonicalText":"」乃負石而自沈於廬水。","chunks":[["」乃負石而自沈於廬水。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-68_s-1","passageId":"zhuangzi_ch-28_p-68","order":1,"canonicalText":"昔周之興，有士二人處於孤竹，曰伯夷、叔齊。","chunks":[["昔周之興，有士二人處於孤竹，曰伯夷、叔齊。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-68_s-2","passageId":"zhuangzi_ch-28_p-68","order":2,"canonicalText":"二人相謂曰：「吾聞西方有人，似有道者，試往觀焉。","chunks":[["二人相謂曰：「吾聞西方有人，似有道者，試往觀焉。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-68_s-3","passageId":"zhuangzi_ch-28_p-68","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-69_s-1","passageId":"zhuangzi_ch-28_p-69","order":1,"canonicalText":"至於岐陽則文王已歿矣，武王聞之，使叔旦往見之，與盟曰：「加富二等，就官一列。","chunks":[["至於岐陽則文王已歿矣，武王聞之，使叔旦往見之，與盟曰：「加富二等，就官一列。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-69_s-2","passageId":"zhuangzi_ch-28_p-69","order":2,"canonicalText":"」血牲而埋之。","chunks":[["」血牲而埋之。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-70_s-1","passageId":"zhuangzi_ch-28_p-70","order":1,"canonicalText":"二人相視而笑曰：「嘻，異哉！","chunks":[["二人相視而笑曰：「嘻，異哉！","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-70_s-2","passageId":"zhuangzi_ch-28_p-70","order":2,"canonicalText":"此非吾所謂道也。","chunks":[["此非吾所謂道也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-70_s-3","passageId":"zhuangzi_ch-28_p-70","order":3,"canonicalText":"昔者神農之有天下也，時祀盡敬而不祈喜；","chunks":[["昔者神農之有天下也，時祀盡敬而不祈喜；","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-70_s-4","passageId":"zhuangzi_ch-28_p-70","order":4,"canonicalText":"其於人也，忠信盡治而无求焉。","chunks":[["其於人也，忠信盡治而无求焉。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-71_s-1","passageId":"zhuangzi_ch-28_p-71","order":1,"canonicalText":"樂與政為政，樂與治為治，不以人之壞自成也，不以人之卑自高也，不以遭時自利也。","chunks":[["樂與政為政，樂與治為治，不以人之壞自成也，不以人之卑自高也，不以遭時自利也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-72_s-1","passageId":"zhuangzi_ch-28_p-72","order":1,"canonicalText":"今周見殷之亂而遽為政與治，上謀而下行貨，阻兵而保威，割牲而盟以為信，揚行以悅眾，殺伐以要利，是推亂以易暴也。","chunks":[["今周見殷之亂而遽為政與治，上謀而下行貨，阻兵而保威，割牲而盟以為信，揚行以悅眾，殺伐以要利，是推亂以易暴也。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-73_s-1","passageId":"zhuangzi_ch-28_p-73","order":1,"canonicalText":"吾聞古之士，遭治世不避其任，遇亂世不為苟存。","chunks":[["吾聞古之士，遭治世不避其任，遇亂世不為苟存。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-73_s-2","passageId":"zhuangzi_ch-28_p-73","order":2,"canonicalText":"今天下闇，周德衰，其並乎周以塗吾身也，不如避之以絜吾行。","chunks":[["今天下闇，周德衰，其並乎周以塗吾身也，不如避之以絜吾行。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-73_s-3","passageId":"zhuangzi_ch-28_p-73","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-74_s-1","passageId":"zhuangzi_ch-28_p-74","order":1,"canonicalText":"二子北至於首陽之山，遂餓而死焉。","chunks":[["二子北至於首陽之山，遂餓而死焉。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-74_s-2","passageId":"zhuangzi_ch-28_p-74","order":2,"canonicalText":"若伯夷、叔齊者，其於富貴也，苟可得已，則必不賴。","chunks":[["若伯夷、叔齊者，其於富貴也，苟可得已，則必不賴。","zh-Hant"]]},{"id":"zhuangzi_ch-28_p-74_s-3","passageId":"zhuangzi_ch-28_p-74","order":3,"canonicalText":"高節戾行，獨樂其志，不事於世，此二士之節也。","chunks":[["高節戾行，獨樂其志，不事於世，此二士之節也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-1_s-1","passageId":"zhuangzi_ch-29_p-1","order":1,"canonicalText":"孔子與柳下季為友，柳下季之弟名曰盜跖。","chunks":[["孔子與柳下季為友，柳下季之弟名曰盜跖。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-1_s-2","passageId":"zhuangzi_ch-29_p-1","order":2,"canonicalText":"盜跖從卒九千人，橫行天下，侵暴諸侯，穴室樞戶，驅人牛馬，取人婦女，貪得忘親，不顧父母兄弟，不祭先祖。","chunks":[["盜跖從卒九千人，橫行天下，侵暴諸侯，穴室樞戶，驅人牛馬，取人婦女，貪得忘親，不顧父母兄弟，不祭先祖。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-2_s-1","passageId":"zhuangzi_ch-29_p-2","order":1,"canonicalText":"所過之邑，大國守城，小國入保，萬民苦之。","chunks":[["所過之邑，大國守城，小國入保，萬民苦之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-3_s-1","passageId":"zhuangzi_ch-29_p-3","order":1,"canonicalText":"孔子謂柳下季曰：「夫為人父者，必能詔其子；","chunks":[["孔子謂柳下季曰：「夫為人父者，必能詔其子；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-3_s-2","passageId":"zhuangzi_ch-29_p-3","order":2,"canonicalText":"為人兄者，必能教其弟。","chunks":[["為人兄者，必能教其弟。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-3_s-3","passageId":"zhuangzi_ch-29_p-3","order":3,"canonicalText":"若父不能詔其子，兄不能教其弟，則无貴父子兄弟之親矣。","chunks":[["若父不能詔其子，兄不能教其弟，則无貴父子兄弟之親矣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-4_s-1","passageId":"zhuangzi_ch-29_p-4","order":1,"canonicalText":"今先生，世之才士也，弟為盜跖，為天下害，而弗能教也，丘竊為先生羞之。","chunks":[["今先生，世之才士也，弟為盜跖，為天下害，而弗能教也，丘竊為先生羞之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-4_s-2","passageId":"zhuangzi_ch-29_p-4","order":2,"canonicalText":"丘請為先生往說之。","chunks":[["丘請為先生往說之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-4_s-3","passageId":"zhuangzi_ch-29_p-4","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-5_s-1","passageId":"zhuangzi_ch-29_p-5","order":1,"canonicalText":"柳下季曰：「先生言為人父者必能詔其子，為人兄者必能教其弟，若子不聽父之詔，弟不受兄之教，雖今先生之辯，將奈之何哉！","chunks":[["柳下季曰：「先生言為人父者必能詔其子，為人兄者必能教其弟，若子不聽父之詔，弟不受兄之教，雖今先生之辯，將奈之何哉！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-6_s-1","passageId":"zhuangzi_ch-29_p-6","order":1,"canonicalText":"且跖之為人也，心如涌泉，意如飄風，強足以距敵，辯足以飾非，順其心則喜，逆其心則怒，易辱人以言。","chunks":[["且跖之為人也，心如涌泉，意如飄風，強足以距敵，辯足以飾非，順其心則喜，逆其心則怒，易辱人以言。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-6_s-2","passageId":"zhuangzi_ch-29_p-6","order":2,"canonicalText":"先生必无往。","chunks":[["先生必无往。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-6_s-3","passageId":"zhuangzi_ch-29_p-6","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-7_s-1","passageId":"zhuangzi_ch-29_p-7","order":1,"canonicalText":"孔子不聽，顏回為馭，子貢為右，往見盜跖。","chunks":[["孔子不聽，顏回為馭，子貢為右，往見盜跖。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-7_s-2","passageId":"zhuangzi_ch-29_p-7","order":2,"canonicalText":"盜跖乃方休卒徒太山之陽，膾人肝而餔之。","chunks":[["盜跖乃方休卒徒太山之陽，膾人肝而餔之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-8_s-1","passageId":"zhuangzi_ch-29_p-8","order":1,"canonicalText":"孔子下車而前，見謁者曰：「魯人孔丘，聞將軍高義，敬再拜謁者。","chunks":[["孔子下車而前，見謁者曰：「魯人孔丘，聞將軍高義，敬再拜謁者。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-8_s-2","passageId":"zhuangzi_ch-29_p-8","order":2,"canonicalText":"」謁者入通，","chunks":[["」謁者入通，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-9_s-1","passageId":"zhuangzi_ch-29_p-9","order":1,"canonicalText":"盜跖聞之大怒，目如明星，髮上指冠，","chunks":[["盜跖聞之大怒，目如明星，髮上指冠，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-10_s-1","passageId":"zhuangzi_ch-29_p-10","order":1,"canonicalText":"曰：「此夫魯國之巧偽人孔丘非邪？","chunks":[["曰：「此夫魯國之巧偽人孔丘非邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-10_s-2","passageId":"zhuangzi_ch-29_p-10","order":2,"canonicalText":"為我告之：『爾作言造語，妄稱文武，冠枝木之冠，帶死牛之脅，多辭謬說，不耕而食，不織而衣，","chunks":[["為我告之：『爾作言造語，妄稱文武，冠枝木之冠，帶死牛之脅，多辭謬說，不耕而食，不織而衣，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-11_s-1","passageId":"zhuangzi_ch-29_p-11","order":1,"canonicalText":"搖脣鼓舌，擅生是非，以迷天下之主，使天下學士不反其本，妄作孝悌而儌倖於封侯富貴者也。","chunks":[["搖脣鼓舌，擅生是非，以迷天下之主，使天下學士不反其本，妄作孝悌而儌倖於封侯富貴者也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-11_s-2","passageId":"zhuangzi_ch-29_p-11","order":2,"canonicalText":"子之罪大極重，疾走歸！","chunks":[["子之罪大極重，疾走歸！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-11_s-3","passageId":"zhuangzi_ch-29_p-11","order":3,"canonicalText":"不然，我將以子肝益晝餔之膳！","chunks":[["不然，我將以子肝益晝餔之膳！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-11_s-4","passageId":"zhuangzi_ch-29_p-11","order":4,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-12_s-1","passageId":"zhuangzi_ch-29_p-12","order":1,"canonicalText":"孔子復通曰：「丘得幸於季，願望履幕下。","chunks":[["孔子復通曰：「丘得幸於季，願望履幕下。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-12_s-2","passageId":"zhuangzi_ch-29_p-12","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-13_s-1","passageId":"zhuangzi_ch-29_p-13","order":1,"canonicalText":"謁者復通，盜跖曰：「使來前！","chunks":[["謁者復通，盜跖曰：「使來前！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-13_s-2","passageId":"zhuangzi_ch-29_p-13","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-14_s-1","passageId":"zhuangzi_ch-29_p-14","order":1,"canonicalText":"孔子趨而進，避席反走，再拜盜跖。","chunks":[["孔子趨而進，避席反走，再拜盜跖。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-14_s-2","passageId":"zhuangzi_ch-29_p-14","order":2,"canonicalText":"盜跖大怒，兩展其足，案劍瞋目，聲如乳虎，曰：「丘來前！","chunks":[["盜跖大怒，兩展其足，案劍瞋目，聲如乳虎，曰：「丘來前！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-14_s-3","passageId":"zhuangzi_ch-29_p-14","order":3,"canonicalText":"若所言，順吾意則生，逆吾心則死。","chunks":[["若所言，順吾意則生，逆吾心則死。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-14_s-4","passageId":"zhuangzi_ch-29_p-14","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-15_s-1","passageId":"zhuangzi_ch-29_p-15","order":1,"canonicalText":"孔子曰：「丘聞之，凡天下有三德，生而長大，美好无雙，少長貴賤見而皆悅之，此上德也；","chunks":[["孔子曰：「丘聞之，凡天下有三德，生而長大，美好无雙，少長貴賤見而皆悅之，此上德也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-15_s-2","passageId":"zhuangzi_ch-29_p-15","order":2,"canonicalText":"知維天地，能辯諸物，此中德也；","chunks":[["知維天地，能辯諸物，此中德也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-15_s-3","passageId":"zhuangzi_ch-29_p-15","order":3,"canonicalText":"勇悍果敢，聚眾率兵，此下德也。","chunks":[["勇悍果敢，聚眾率兵，此下德也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-16_s-1","passageId":"zhuangzi_ch-29_p-16","order":1,"canonicalText":"凡人有此一德者，足以南面稱孤矣。","chunks":[["凡人有此一德者，足以南面稱孤矣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-16_s-2","passageId":"zhuangzi_ch-29_p-16","order":2,"canonicalText":"今將軍兼此三者，身長八尺二寸，面目有光，脣如激丹，齒如齊貝，音中黃鍾，而名曰盜跖，","chunks":[["今將軍兼此三者，身長八尺二寸，面目有光，脣如激丹，齒如齊貝，音中黃鍾，而名曰盜跖，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-17_s-1","passageId":"zhuangzi_ch-29_p-17","order":1,"canonicalText":"丘竊為將軍恥不取焉。","chunks":[["丘竊為將軍恥不取焉。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-17_s-2","passageId":"zhuangzi_ch-29_p-17","order":2,"canonicalText":"將軍有意聽臣，臣請南使吳越，北使齊魯，東使宋衛，西使晉楚，使為將軍造大城數百里，立數十萬戶之邑，尊將軍為諸侯，","chunks":[["將軍有意聽臣，臣請南使吳越，北使齊魯，東使宋衛，西使晉楚，使為將軍造大城數百里，立數十萬戶之邑，尊將軍為諸侯，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-18_s-1","passageId":"zhuangzi_ch-29_p-18","order":1,"canonicalText":"與天下更始，罷兵休卒，收養昆弟，共祭先祖。","chunks":[["與天下更始，罷兵休卒，收養昆弟，共祭先祖。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-18_s-2","passageId":"zhuangzi_ch-29_p-18","order":2,"canonicalText":"此聖人才士之行，而天下之願也。","chunks":[["此聖人才士之行，而天下之願也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-18_s-3","passageId":"zhuangzi_ch-29_p-18","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-19_s-1","passageId":"zhuangzi_ch-29_p-19","order":1,"canonicalText":"盜跖大怒，曰：「丘來前！","chunks":[["盜跖大怒，曰：「丘來前！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-19_s-2","passageId":"zhuangzi_ch-29_p-19","order":2,"canonicalText":"夫可規以利而可諫以言者，皆愚陋恆民之謂耳。","chunks":[["夫可規以利而可諫以言者，皆愚陋恆民之謂耳。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-19_s-3","passageId":"zhuangzi_ch-29_p-19","order":3,"canonicalText":"今長大美好，人見而悅之者，此吾父母之遺德也。","chunks":[["今長大美好，人見而悅之者，此吾父母之遺德也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-19_s-4","passageId":"zhuangzi_ch-29_p-19","order":4,"canonicalText":"丘雖不吾譽，吾獨不自知邪？","chunks":[["丘雖不吾譽，吾獨不自知邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-20_s-1","passageId":"zhuangzi_ch-29_p-20","order":1,"canonicalText":"且吾聞之，好面譽人者，亦好背而毀之。","chunks":[["且吾聞之，好面譽人者，亦好背而毀之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-20_s-2","passageId":"zhuangzi_ch-29_p-20","order":2,"canonicalText":"今丘告我以大城眾民，是欲規我以利而恆民畜我也，安可長久也！","chunks":[["今丘告我以大城眾民，是欲規我以利而恆民畜我也，安可長久也！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-20_s-3","passageId":"zhuangzi_ch-29_p-20","order":3,"canonicalText":"城之大者，莫大乎天下矣。","chunks":[["城之大者，莫大乎天下矣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-21_s-1","passageId":"zhuangzi_ch-29_p-21","order":1,"canonicalText":"堯舜有天下，子孫无置錐之地；","chunks":[["堯舜有天下，子孫无置錐之地；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-21_s-2","passageId":"zhuangzi_ch-29_p-21","order":2,"canonicalText":"湯武立為天子，而後世絕滅；","chunks":[["湯武立為天子，而後世絕滅；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-21_s-3","passageId":"zhuangzi_ch-29_p-21","order":3,"canonicalText":"非以其利大故邪？","chunks":[["非以其利大故邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-22_s-1","passageId":"zhuangzi_ch-29_p-22","order":1,"canonicalText":"「且吾聞之，古者禽獸多而人民少，於是民皆巢居以避之，晝拾橡栗，暮栖木上，故命之曰有巢氏之民。","chunks":[["「且吾聞之，古者禽獸多而人民少，於是民皆巢居以避之，晝拾橡栗，暮栖木上，故命之曰有巢氏之民。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-23_s-1","passageId":"zhuangzi_ch-29_p-23","order":1,"canonicalText":"古者民不知衣服，夏多積薪，冬則煬之，故命之曰知生之民。","chunks":[["古者民不知衣服，夏多積薪，冬則煬之，故命之曰知生之民。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-23_s-2","passageId":"zhuangzi_ch-29_p-23","order":2,"canonicalText":"神農之世，臥則居居，起則于于，民知其母，不知其父，與麋鹿共處，","chunks":[["神農之世，臥則居居，起則于于，民知其母，不知其父，與麋鹿共處，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-24_s-1","passageId":"zhuangzi_ch-29_p-24","order":1,"canonicalText":"耕而食，織而衣，无有相害之心，此至德之隆也。","chunks":[["耕而食，織而衣，无有相害之心，此至德之隆也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-24_s-2","passageId":"zhuangzi_ch-29_p-24","order":2,"canonicalText":"然而黃帝不能致德，與蚩尤戰於涿鹿之野，流血百里。","chunks":[["然而黃帝不能致德，與蚩尤戰於涿鹿之野，流血百里。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-25_s-1","passageId":"zhuangzi_ch-29_p-25","order":1,"canonicalText":"堯舜作，立群臣，湯放其主，武王殺紂。","chunks":[["堯舜作，立群臣，湯放其主，武王殺紂。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-25_s-2","passageId":"zhuangzi_ch-29_p-25","order":2,"canonicalText":"自是之後，以強陵弱，以眾暴寡。","chunks":[["自是之後，以強陵弱，以眾暴寡。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-25_s-3","passageId":"zhuangzi_ch-29_p-25","order":3,"canonicalText":"湯武以來，皆亂人之徒也。","chunks":[["湯武以來，皆亂人之徒也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-26_s-1","passageId":"zhuangzi_ch-29_p-26","order":1,"canonicalText":"「今子脩文、武之道，掌天下之辯，以教後世，縫衣淺帶，矯言偽行，以迷惑天下之主，而欲求富貴焉，盜莫大於子。","chunks":[["「今子脩文、武之道，掌天下之辯，以教後世，縫衣淺帶，矯言偽行，以迷惑天下之主，而欲求富貴焉，盜莫大於子。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-26_s-2","passageId":"zhuangzi_ch-29_p-26","order":2,"canonicalText":"天下何故不謂子為盜丘，而乃謂我為盜跖？","chunks":[["天下何故不謂子為盜丘，而乃謂我為盜跖？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-27_s-1","passageId":"zhuangzi_ch-29_p-27","order":1,"canonicalText":"子以甘辭說子路而使從之，使子路去其危冠，解其長劍，而受教於子，天下皆曰孔丘能止暴禁非。","chunks":[["子以甘辭說子路而使從之，使子路去其危冠，解其長劍，而受教於子，天下皆曰孔丘能止暴禁非。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-27_s-2","passageId":"zhuangzi_ch-29_p-27","order":2,"canonicalText":"其卒之也，子路欲殺衛君而事不成，身菹於衛東門之上，是子教之不至也。","chunks":[["其卒之也，子路欲殺衛君而事不成，身菹於衛東門之上，是子教之不至也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-28_s-1","passageId":"zhuangzi_ch-29_p-28","order":1,"canonicalText":"子自謂才士聖人邪？","chunks":[["子自謂才士聖人邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-28_s-2","passageId":"zhuangzi_ch-29_p-28","order":2,"canonicalText":"則再逐於魯，削跡於衛，窮於齊，圍於陳蔡，不容身於天下。","chunks":[["則再逐於魯，削跡於衛，窮於齊，圍於陳蔡，不容身於天下。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-28_s-3","passageId":"zhuangzi_ch-29_p-28","order":3,"canonicalText":"子教子路菹此患，上无以為身，下无以為人，子之道豈足貴邪？","chunks":[["子教子路菹此患，上无以為身，下无以為人，子之道豈足貴邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-29_s-1","passageId":"zhuangzi_ch-29_p-29","order":1,"canonicalText":"「世之所高，莫若黃帝，黃帝尚不能全德，而戰涿鹿之野，流血百里。","chunks":[["「世之所高，莫若黃帝，黃帝尚不能全德，而戰涿鹿之野，流血百里。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-29_s-2","passageId":"zhuangzi_ch-29_p-29","order":2,"canonicalText":"堯不慈，舜不孝，禹偏枯，湯放其主，武王伐紂，文王拘羑里。","chunks":[["堯不慈，舜不孝，禹偏枯，湯放其主，武王伐紂，文王拘羑里。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-30_s-1","passageId":"zhuangzi_ch-29_p-30","order":1,"canonicalText":"此六子者，世之所高也，孰論之，皆以利惑其真而強反其情性，其行乃甚可羞也。","chunks":[["此六子者，世之所高也，孰論之，皆以利惑其真而強反其情性，其行乃甚可羞也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-31_s-1","passageId":"zhuangzi_ch-29_p-31","order":1,"canonicalText":"「世之所謂賢士，莫若伯夷、叔齊。","chunks":[["「世之所謂賢士，莫若伯夷、叔齊。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-31_s-2","passageId":"zhuangzi_ch-29_p-31","order":2,"canonicalText":"伯夷、叔齊辭孤竹之君，而餓死於首陽之山，骨肉不葬。","chunks":[["伯夷、叔齊辭孤竹之君，而餓死於首陽之山，骨肉不葬。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-31_s-3","passageId":"zhuangzi_ch-29_p-31","order":3,"canonicalText":"鮑焦飾行非世，抱木而死。","chunks":[["鮑焦飾行非世，抱木而死。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-31_s-4","passageId":"zhuangzi_ch-29_p-31","order":4,"canonicalText":"申徒狄諫而不聽，負石自投於河，為魚鼈所食。","chunks":[["申徒狄諫而不聽，負石自投於河，為魚鼈所食。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-32_s-1","passageId":"zhuangzi_ch-29_p-32","order":1,"canonicalText":"介子推至忠也，自割其股以食文公，文公後背之，子推怒而去，拘木而燔死。","chunks":[["介子推至忠也，自割其股以食文公，文公後背之，子推怒而去，拘木而燔死。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-32_s-2","passageId":"zhuangzi_ch-29_p-32","order":2,"canonicalText":"尾生與女子期於梁下，女子不來，水至不去，抱梁柱而死。","chunks":[["尾生與女子期於梁下，女子不來，水至不去，抱梁柱而死。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-33_s-1","passageId":"zhuangzi_ch-29_p-33","order":1,"canonicalText":"此六子者，无異於磔犬流豕操瓢而乞者，皆離名輕死，不念本養壽命者也。","chunks":[["此六子者，无異於磔犬流豕操瓢而乞者，皆離名輕死，不念本養壽命者也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-34_s-1","passageId":"zhuangzi_ch-29_p-34","order":1,"canonicalText":"「世之所謂忠臣者，莫若王子比干、伍子胥。","chunks":[["「世之所謂忠臣者，莫若王子比干、伍子胥。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-34_s-2","passageId":"zhuangzi_ch-29_p-34","order":2,"canonicalText":"子胥沈江，比干剖心，此二子者，世謂忠臣也，然卒為天下笑。","chunks":[["子胥沈江，比干剖心，此二子者，世謂忠臣也，然卒為天下笑。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-34_s-3","passageId":"zhuangzi_ch-29_p-34","order":3,"canonicalText":"自上觀之，至于子胥、比干，皆不足貴也。","chunks":[["自上觀之，至于子胥、比干，皆不足貴也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-35_s-1","passageId":"zhuangzi_ch-29_p-35","order":1,"canonicalText":"丘之所以說我者，若告我以鬼事，則我不能知也；","chunks":[["丘之所以說我者，若告我以鬼事，則我不能知也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-35_s-2","passageId":"zhuangzi_ch-29_p-35","order":2,"canonicalText":"若告我以人事者，不過此矣，皆吾所聞知也。","chunks":[["若告我以人事者，不過此矣，皆吾所聞知也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-35_s-3","passageId":"zhuangzi_ch-29_p-35","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-36_s-1","passageId":"zhuangzi_ch-29_p-36","order":1,"canonicalText":"「今吾告子以人之情，目欲視色，耳欲聽聲，口欲察味，志氣欲盈。","chunks":[["「今吾告子以人之情，目欲視色，耳欲聽聲，口欲察味，志氣欲盈。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-36_s-2","passageId":"zhuangzi_ch-29_p-36","order":2,"canonicalText":"人上壽百歲，中壽八十，下壽六十，","chunks":[["人上壽百歲，中壽八十，下壽六十，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-37_s-1","passageId":"zhuangzi_ch-29_p-37","order":1,"canonicalText":"除病瘐死喪憂患，其中開口而笑者，一月之中不過四五日而已矣。","chunks":[["除病瘐死喪憂患，其中開口而笑者，一月之中不過四五日而已矣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-37_s-2","passageId":"zhuangzi_ch-29_p-37","order":2,"canonicalText":"天與地无窮，人死者有時，操有時之具而託於无窮之閒，勿然无異騏驥之馳過隙也。","chunks":[["天與地无窮，人死者有時，操有時之具而託於无窮之閒，勿然无異騏驥之馳過隙也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-37_s-3","passageId":"zhuangzi_ch-29_p-37","order":3,"canonicalText":"不能悅其志意，養其壽命者，皆非通道者也。","chunks":[["不能悅其志意，養其壽命者，皆非通道者也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-38_s-1","passageId":"zhuangzi_ch-29_p-38","order":1,"canonicalText":"丘之所言，皆吾之所棄也，亟去走歸，无復言之！","chunks":[["丘之所言，皆吾之所棄也，亟去走歸，无復言之！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-38_s-2","passageId":"zhuangzi_ch-29_p-38","order":2,"canonicalText":"子之道，狂狂伋伋，詐巧虛偽事也，非可以全真也，奚足論哉！","chunks":[["子之道，狂狂伋伋，詐巧虛偽事也，非可以全真也，奚足論哉！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-38_s-3","passageId":"zhuangzi_ch-29_p-38","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-39_s-1","passageId":"zhuangzi_ch-29_p-39","order":1,"canonicalText":"孔子再拜趨走，出門上車，執轡三失，目芒然无見，色若死灰，據軾低頭，不能出氣。","chunks":[["孔子再拜趨走，出門上車，執轡三失，目芒然无見，色若死灰，據軾低頭，不能出氣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-39_s-2","passageId":"zhuangzi_ch-29_p-39","order":2,"canonicalText":"歸到魯東門外，適遇柳下季。","chunks":[["歸到魯東門外，適遇柳下季。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-39_s-3","passageId":"zhuangzi_ch-29_p-39","order":3,"canonicalText":"柳下季曰：「今者闕然數日不見，車馬有行色，得微往見跖邪？","chunks":[["柳下季曰：「今者闕然數日不見，車馬有行色，得微往見跖邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-39_s-4","passageId":"zhuangzi_ch-29_p-39","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-40_s-1","passageId":"zhuangzi_ch-29_p-40","order":1,"canonicalText":"孔子仰天而歎曰：「然。","chunks":[["孔子仰天而歎曰：「然。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-40_s-2","passageId":"zhuangzi_ch-29_p-40","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-41_s-1","passageId":"zhuangzi_ch-29_p-41","order":1,"canonicalText":"柳下季曰：「跖得无逆汝意若前乎？","chunks":[["柳下季曰：「跖得无逆汝意若前乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-41_s-2","passageId":"zhuangzi_ch-29_p-41","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-42_s-1","passageId":"zhuangzi_ch-29_p-42","order":1,"canonicalText":"孔子曰：「然。","chunks":[["孔子曰：「然。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-42_s-2","passageId":"zhuangzi_ch-29_p-42","order":2,"canonicalText":"丘所謂无病而自灸也，疾走料虎頭，編虎須，幾不免虎口哉！","chunks":[["丘所謂无病而自灸也，疾走料虎頭，編虎須，幾不免虎口哉！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-42_s-3","passageId":"zhuangzi_ch-29_p-42","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-43_s-1","passageId":"zhuangzi_ch-29_p-43","order":1,"canonicalText":"子張問於滿苟得曰：「盍不為行？","chunks":[["子張問於滿苟得曰：「盍不為行？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-43_s-2","passageId":"zhuangzi_ch-29_p-43","order":2,"canonicalText":"无行則不信，不信則不任，不任則不利。","chunks":[["无行則不信，不信則不任，不任則不利。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-43_s-3","passageId":"zhuangzi_ch-29_p-43","order":3,"canonicalText":"故觀之名，計之利，而義真是也。","chunks":[["故觀之名，計之利，而義真是也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-43_s-4","passageId":"zhuangzi_ch-29_p-43","order":4,"canonicalText":"若棄名利，反之於心，則夫士之為行，不可一日不為乎！","chunks":[["若棄名利，反之於心，則夫士之為行，不可一日不為乎！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-43_s-5","passageId":"zhuangzi_ch-29_p-43","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-44_s-1","passageId":"zhuangzi_ch-29_p-44","order":1,"canonicalText":"滿苟得曰：「无恥者富，多信者顯。","chunks":[["滿苟得曰：「无恥者富，多信者顯。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-44_s-2","passageId":"zhuangzi_ch-29_p-44","order":2,"canonicalText":"夫名利之大者，幾在无恥而信。","chunks":[["夫名利之大者，幾在无恥而信。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-44_s-3","passageId":"zhuangzi_ch-29_p-44","order":3,"canonicalText":"故觀之名，計之利，而信真是也。","chunks":[["故觀之名，計之利，而信真是也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-44_s-4","passageId":"zhuangzi_ch-29_p-44","order":4,"canonicalText":"若棄名利，反之於心，則夫士之為行，抱其天乎！","chunks":[["若棄名利，反之於心，則夫士之為行，抱其天乎！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-44_s-5","passageId":"zhuangzi_ch-29_p-44","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-45_s-1","passageId":"zhuangzi_ch-29_p-45","order":1,"canonicalText":"子張曰：「昔者桀紂貴為天子，富有天下，今謂臧聚曰：『汝行如桀紂。","chunks":[["子張曰：「昔者桀紂貴為天子，富有天下，今謂臧聚曰：『汝行如桀紂。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-45_s-2","passageId":"zhuangzi_ch-29_p-45","order":2,"canonicalText":"』則有怍色有不服之心者，小人所賤也。","chunks":[["』則有怍色有不服之心者，小人所賤也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-45_s-3","passageId":"zhuangzi_ch-29_p-45","order":3,"canonicalText":"仲尼、墨翟窮為匹夫，","chunks":[["仲尼、墨翟窮為匹夫，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-1","passageId":"zhuangzi_ch-29_p-46","order":1,"canonicalText":"今謂宰相曰：『子行如仲尼、墨翟。","chunks":[["今謂宰相曰：『子行如仲尼、墨翟。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-2","passageId":"zhuangzi_ch-29_p-46","order":2,"canonicalText":"』則變容易色稱不足者，士誠貴也。","chunks":[["』則變容易色稱不足者，士誠貴也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-3","passageId":"zhuangzi_ch-29_p-46","order":3,"canonicalText":"故勢為天子，未必貴也；","chunks":[["故勢為天子，未必貴也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-4","passageId":"zhuangzi_ch-29_p-46","order":4,"canonicalText":"窮為匹夫，未必賤也；","chunks":[["窮為匹夫，未必賤也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-5","passageId":"zhuangzi_ch-29_p-46","order":5,"canonicalText":"貴賤之分，在行之美惡。","chunks":[["貴賤之分，在行之美惡。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-46_s-6","passageId":"zhuangzi_ch-29_p-46","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-47_s-1","passageId":"zhuangzi_ch-29_p-47","order":1,"canonicalText":"滿苟得曰：「小盜者拘，大盜者為諸侯，諸侯之門，仁義存焉。","chunks":[["滿苟得曰：「小盜者拘，大盜者為諸侯，諸侯之門，仁義存焉。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-47_s-2","passageId":"zhuangzi_ch-29_p-47","order":2,"canonicalText":"昔者桓公小白殺兄入嫂而管仲為臣，","chunks":[["昔者桓公小白殺兄入嫂而管仲為臣，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-48_s-1","passageId":"zhuangzi_ch-29_p-48","order":1,"canonicalText":"田成子常殺君竊國而孔子受幣。","chunks":[["田成子常殺君竊國而孔子受幣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-48_s-2","passageId":"zhuangzi_ch-29_p-48","order":2,"canonicalText":"論則賤之，行則下之，則是言行之情悖戰於胸中也，不亦拂乎！","chunks":[["論則賤之，行則下之，則是言行之情悖戰於胸中也，不亦拂乎！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-48_s-3","passageId":"zhuangzi_ch-29_p-48","order":3,"canonicalText":"故《書》曰：『孰惡孰美？","chunks":[["故《書》曰：『孰惡孰美？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-48_s-4","passageId":"zhuangzi_ch-29_p-48","order":4,"canonicalText":"成者為首，不成者為尾。","chunks":[["成者為首，不成者為尾。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-48_s-5","passageId":"zhuangzi_ch-29_p-48","order":5,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-49_s-1","passageId":"zhuangzi_ch-29_p-49","order":1,"canonicalText":"子張曰：「子不為行，即將䟽戚无倫，貴賤无義，長幼无序；","chunks":[["子張曰：「子不為行，即將䟽戚无倫，貴賤无義，長幼无序；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-49_s-2","passageId":"zhuangzi_ch-29_p-49","order":2,"canonicalText":"五紀六位，將何以為別乎？","chunks":[["五紀六位，將何以為別乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-49_s-3","passageId":"zhuangzi_ch-29_p-49","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-50_s-1","passageId":"zhuangzi_ch-29_p-50","order":1,"canonicalText":"滿苟得曰：「堯殺長子，舜流母弟，䟽戚有倫乎？","chunks":[["滿苟得曰：「堯殺長子，舜流母弟，䟽戚有倫乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-50_s-2","passageId":"zhuangzi_ch-29_p-50","order":2,"canonicalText":"湯放桀，武王殺紂，貴賤有義乎？","chunks":[["湯放桀，武王殺紂，貴賤有義乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-50_s-3","passageId":"zhuangzi_ch-29_p-50","order":3,"canonicalText":"王季為適，周公殺兄，長幼有序乎？","chunks":[["王季為適，周公殺兄，長幼有序乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-51_s-1","passageId":"zhuangzi_ch-29_p-51","order":1,"canonicalText":"儒者偽辭，墨者兼愛，五紀六位，將有別乎？","chunks":[["儒者偽辭，墨者兼愛，五紀六位，將有別乎？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-52_s-1","passageId":"zhuangzi_ch-29_p-52","order":1,"canonicalText":"且子正為名，我正為利。","chunks":[["且子正為名，我正為利。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-52_s-2","passageId":"zhuangzi_ch-29_p-52","order":2,"canonicalText":"名利之實，不順於理，不監於道。","chunks":[["名利之實，不順於理，不監於道。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-52_s-3","passageId":"zhuangzi_ch-29_p-52","order":3,"canonicalText":"吾日與子訟於无約曰：","chunks":[["吾日與子訟於无約曰：","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-53_s-1","passageId":"zhuangzi_ch-29_p-53","order":1,"canonicalText":"『小人殉財，君子殉名。","chunks":[["『小人殉財，君子殉名。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-53_s-2","passageId":"zhuangzi_ch-29_p-53","order":2,"canonicalText":"其所以變其情，易其性，則異矣；","chunks":[["其所以變其情，易其性，則異矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-53_s-3","passageId":"zhuangzi_ch-29_p-53","order":3,"canonicalText":"乃至於棄其所為而殉其所不為，則一也。","chunks":[["乃至於棄其所為而殉其所不為，則一也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-53_s-4","passageId":"zhuangzi_ch-29_p-53","order":4,"canonicalText":"』","chunks":[["』","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-54_s-1","passageId":"zhuangzi_ch-29_p-54","order":1,"canonicalText":"故曰：无為小人，反殉而天；","chunks":[["故曰：无為小人，反殉而天；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-54_s-2","passageId":"zhuangzi_ch-29_p-54","order":2,"canonicalText":"无為君子，從天之理。","chunks":[["无為君子，從天之理。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-54_s-3","passageId":"zhuangzi_ch-29_p-54","order":3,"canonicalText":"若枉若直，相而天極；","chunks":[["若枉若直，相而天極；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-54_s-4","passageId":"zhuangzi_ch-29_p-54","order":4,"canonicalText":"面觀四方，與時消息。","chunks":[["面觀四方，與時消息。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-55_s-1","passageId":"zhuangzi_ch-29_p-55","order":1,"canonicalText":"若是若非，執而圓機；","chunks":[["若是若非，執而圓機；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-55_s-2","passageId":"zhuangzi_ch-29_p-55","order":2,"canonicalText":"獨成而意，與道俳佪。","chunks":[["獨成而意，與道俳佪。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-55_s-3","passageId":"zhuangzi_ch-29_p-55","order":3,"canonicalText":"无轉而行，无成而義，將失而所為。","chunks":[["无轉而行，无成而義，將失而所為。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-55_s-4","passageId":"zhuangzi_ch-29_p-55","order":4,"canonicalText":"无赴而富，无殉而成，將棄而天。","chunks":[["无赴而富，无殉而成，將棄而天。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-56_s-1","passageId":"zhuangzi_ch-29_p-56","order":1,"canonicalText":"比干剖心，子胥抉眼，忠之禍也；","chunks":[["比干剖心，子胥抉眼，忠之禍也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-56_s-2","passageId":"zhuangzi_ch-29_p-56","order":2,"canonicalText":"直躬證父，尾生溺死，信之患也；","chunks":[["直躬證父，尾生溺死，信之患也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-56_s-3","passageId":"zhuangzi_ch-29_p-56","order":3,"canonicalText":"鮑子立乾，申子自埋，廉之害也；","chunks":[["鮑子立乾，申子自埋，廉之害也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-56_s-4","passageId":"zhuangzi_ch-29_p-56","order":4,"canonicalText":"孔子不見母，匡子不見父，義之失也。","chunks":[["孔子不見母，匡子不見父，義之失也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-57_s-1","passageId":"zhuangzi_ch-29_p-57","order":1,"canonicalText":"此上世之所傳，下世之所語，以為士者正其言，必其行，故服其殃，離其患也。","chunks":[["此上世之所傳，下世之所語，以為士者正其言，必其行，故服其殃，離其患也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-57_s-2","passageId":"zhuangzi_ch-29_p-57","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-58_s-1","passageId":"zhuangzi_ch-29_p-58","order":1,"canonicalText":"无足問於知和曰：「人卒未有不興名就利者。","chunks":[["无足問於知和曰：「人卒未有不興名就利者。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-58_s-2","passageId":"zhuangzi_ch-29_p-58","order":2,"canonicalText":"彼富則人歸之，歸則下之，下則貴之。","chunks":[["彼富則人歸之，歸則下之，下則貴之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-58_s-3","passageId":"zhuangzi_ch-29_p-58","order":3,"canonicalText":"夫見下貴者，所以長生安體樂意之道也。","chunks":[["夫見下貴者，所以長生安體樂意之道也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-59_s-1","passageId":"zhuangzi_ch-29_p-59","order":1,"canonicalText":"今子獨无意焉，知不足邪，意知而力不能行邪，故推正不忘邪？","chunks":[["今子獨无意焉，知不足邪，意知而力不能行邪，故推正不忘邪？","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-59_s-2","passageId":"zhuangzi_ch-29_p-59","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-60_s-1","passageId":"zhuangzi_ch-29_p-60","order":1,"canonicalText":"知和曰：「今夫此人以為與己同時而生，同鄉而處者，以為夫絕俗過世之士焉；","chunks":[["知和曰：「今夫此人以為與己同時而生，同鄉而處者，以為夫絕俗過世之士焉；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-60_s-2","passageId":"zhuangzi_ch-29_p-60","order":2,"canonicalText":"是專无主正，所以覽古今之時，是非之分也，與俗化。","chunks":[["是專无主正，所以覽古今之時，是非之分也，與俗化。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-60_s-3","passageId":"zhuangzi_ch-29_p-60","order":3,"canonicalText":"世去至重，棄至尊，以為其所為也；","chunks":[["世去至重，棄至尊，以為其所為也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-60_s-4","passageId":"zhuangzi_ch-29_p-60","order":4,"canonicalText":"此其所以論長生安體樂意之道，不亦遠乎！","chunks":[["此其所以論長生安體樂意之道，不亦遠乎！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-61_s-1","passageId":"zhuangzi_ch-29_p-61","order":1,"canonicalText":"慘怛之疾，恬愉之安，不監於體；","chunks":[["慘怛之疾，恬愉之安，不監於體；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-61_s-2","passageId":"zhuangzi_ch-29_p-61","order":2,"canonicalText":"怵惕之恐，欣懽之喜，不監於心；","chunks":[["怵惕之恐，欣懽之喜，不監於心；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-62_s-1","passageId":"zhuangzi_ch-29_p-62","order":1,"canonicalText":"知為為而不知所以為，是以貴為天子，富有天下，而不免於患也。","chunks":[["知為為而不知所以為，是以貴為天子，富有天下，而不免於患也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-62_s-2","passageId":"zhuangzi_ch-29_p-62","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-63_s-1","passageId":"zhuangzi_ch-29_p-63","order":1,"canonicalText":"无足曰：「夫富之於人，无所不利，窮美究勢，至人之所不得逮，賢人之所不能及，","chunks":[["无足曰：「夫富之於人，无所不利，窮美究勢，至人之所不得逮，賢人之所不能及，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-64_s-1","passageId":"zhuangzi_ch-29_p-64","order":1,"canonicalText":"俠人之勇力而以為威強，秉人之知謀以為明察，因人之德以為賢良，非享國而嚴若君父。","chunks":[["俠人之勇力而以為威強，秉人之知謀以為明察，因人之德以為賢良，非享國而嚴若君父。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-65_s-1","passageId":"zhuangzi_ch-29_p-65","order":1,"canonicalText":"且夫聲色滋味權勢之於人，心不待學而樂之，體不待象而安之。","chunks":[["且夫聲色滋味權勢之於人，心不待學而樂之，體不待象而安之。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-65_s-2","passageId":"zhuangzi_ch-29_p-65","order":2,"canonicalText":"夫欲惡避就，固不待師，此人之性也。","chunks":[["夫欲惡避就，固不待師，此人之性也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-65_s-3","passageId":"zhuangzi_ch-29_p-65","order":3,"canonicalText":"天下雖非我，孰能辭之！","chunks":[["天下雖非我，孰能辭之！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-65_s-4","passageId":"zhuangzi_ch-29_p-65","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-66_s-1","passageId":"zhuangzi_ch-29_p-66","order":1,"canonicalText":"知和曰：「知者之為，故動以百姓，不違其度，是以足而不爭，无以為故不求。","chunks":[["知和曰：「知者之為，故動以百姓，不違其度，是以足而不爭，无以為故不求。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-66_s-2","passageId":"zhuangzi_ch-29_p-66","order":2,"canonicalText":"不足故求之，爭四處而不自以為貪；","chunks":[["不足故求之，爭四處而不自以為貪；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-67_s-1","passageId":"zhuangzi_ch-29_p-67","order":1,"canonicalText":"有餘故辭之，棄天下而不自以為廉。","chunks":[["有餘故辭之，棄天下而不自以為廉。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-67_s-2","passageId":"zhuangzi_ch-29_p-67","order":2,"canonicalText":"廉貪之實，非以迫外也，反監之度。","chunks":[["廉貪之實，非以迫外也，反監之度。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-67_s-3","passageId":"zhuangzi_ch-29_p-67","order":3,"canonicalText":"勢為天子而不以貴驕人，富有天下而不以財戲人。","chunks":[["勢為天子而不以貴驕人，富有天下而不以財戲人。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-68_s-1","passageId":"zhuangzi_ch-29_p-68","order":1,"canonicalText":"計其患，慮其反，以為害於性，故辭而不受也，非以要名譽也。","chunks":[["計其患，慮其反，以為害於性，故辭而不受也，非以要名譽也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-68_s-2","passageId":"zhuangzi_ch-29_p-68","order":2,"canonicalText":"堯舜為帝而雍，非仁天下也，不以美害生也；","chunks":[["堯舜為帝而雍，非仁天下也，不以美害生也；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-68_s-3","passageId":"zhuangzi_ch-29_p-68","order":3,"canonicalText":"善卷許由得帝而不受，非虛辭讓也，不以事害己。","chunks":[["善卷許由得帝而不受，非虛辭讓也，不以事害己。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-69_s-1","passageId":"zhuangzi_ch-29_p-69","order":1,"canonicalText":"此皆就其利，辭其害，而天下稱賢焉，則可以有之，彼非以興名譽也。","chunks":[["此皆就其利，辭其害，而天下稱賢焉，則可以有之，彼非以興名譽也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-69_s-2","passageId":"zhuangzi_ch-29_p-69","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-70_s-1","passageId":"zhuangzi_ch-29_p-70","order":1,"canonicalText":"无足曰：「必持其名，苦體絕甘，約養以持生，則亦久病長阨而不死者也。","chunks":[["无足曰：「必持其名，苦體絕甘，約養以持生，則亦久病長阨而不死者也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-70_s-2","passageId":"zhuangzi_ch-29_p-70","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-71_s-1","passageId":"zhuangzi_ch-29_p-71","order":1,"canonicalText":"知和曰：「平為福，有餘為害者，物莫不然，而財其甚者也。","chunks":[["知和曰：「平為福，有餘為害者，物莫不然，而財其甚者也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-71_s-2","passageId":"zhuangzi_ch-29_p-71","order":2,"canonicalText":"今富人，耳營鍾鼓管籥之聲，口嗛於芻豢醪醴之味，以感其意，遺忘其業，可謂亂矣；","chunks":[["今富人，耳營鍾鼓管籥之聲，口嗛於芻豢醪醴之味，以感其意，遺忘其業，可謂亂矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-72_s-1","passageId":"zhuangzi_ch-29_p-72","order":1,"canonicalText":"侅溺於馮氣，若負重行而上阪也，可謂苦矣；","chunks":[["侅溺於馮氣，若負重行而上阪也，可謂苦矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-72_s-2","passageId":"zhuangzi_ch-29_p-72","order":2,"canonicalText":"貪財而取慰，貪權而取竭，靜居則溺，體澤則馮，可謂疾矣；","chunks":[["貪財而取慰，貪權而取竭，靜居則溺，體澤則馮，可謂疾矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-73_s-1","passageId":"zhuangzi_ch-29_p-73","order":1,"canonicalText":"為欲富就利，故滿若堵耳而不知避，且馮而不舍，可謂辱矣；","chunks":[["為欲富就利，故滿若堵耳而不知避，且馮而不舍，可謂辱矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-73_s-2","passageId":"zhuangzi_ch-29_p-73","order":2,"canonicalText":"財積而无用，服膺而不舍，滿心戚醮，求益而不止，可謂憂矣；","chunks":[["財積而无用，服膺而不舍，滿心戚醮，求益而不止，可謂憂矣；","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-74_s-1","passageId":"zhuangzi_ch-29_p-74","order":1,"canonicalText":"內則疑刦請之賊，外則畏寇盜之害，內周樓䟽，外不敢獨行，可謂畏矣。","chunks":[["內則疑刦請之賊，外則畏寇盜之害，內周樓䟽，外不敢獨行，可謂畏矣。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-74_s-2","passageId":"zhuangzi_ch-29_p-74","order":2,"canonicalText":"此六者，天下之至害也，皆遺忘而不知察，","chunks":[["此六者，天下之至害也，皆遺忘而不知察，","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-75_s-1","passageId":"zhuangzi_ch-29_p-75","order":1,"canonicalText":"及其患至，求盡性竭財，單以反一日之无故而不可得也。","chunks":[["及其患至，求盡性竭財，單以反一日之无故而不可得也。","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-75_s-2","passageId":"zhuangzi_ch-29_p-75","order":2,"canonicalText":"故觀之名則不見，求之利則不得，繚意絕體而爭此，不亦惑乎！","chunks":[["故觀之名則不見，求之利則不得，繚意絕體而爭此，不亦惑乎！","zh-Hant"]]},{"id":"zhuangzi_ch-29_p-75_s-3","passageId":"zhuangzi_ch-29_p-75","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-1_s-1","passageId":"zhuangzi_ch-30_p-1","order":1,"canonicalText":"昔趙文王喜劍，劍士夾門而客三千餘人，日夜相擊於前，死傷者歲百餘人，好之不厭。","chunks":[["昔趙文王喜劍，劍士夾門而客三千餘人，日夜相擊於前，死傷者歲百餘人，好之不厭。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-1_s-2","passageId":"zhuangzi_ch-30_p-1","order":2,"canonicalText":"如是三年，國衰，諸侯謀之。","chunks":[["如是三年，國衰，諸侯謀之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-2_s-1","passageId":"zhuangzi_ch-30_p-2","order":1,"canonicalText":"太子悝患之，募左右曰：「孰能說王之意止劍士者，賜之千金。","chunks":[["太子悝患之，募左右曰：「孰能說王之意止劍士者，賜之千金。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-2_s-2","passageId":"zhuangzi_ch-30_p-2","order":2,"canonicalText":"」左右曰：「莊子當能。","chunks":[["」左右曰：「莊子當能。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-2_s-3","passageId":"zhuangzi_ch-30_p-2","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-3_s-1","passageId":"zhuangzi_ch-30_p-3","order":1,"canonicalText":"太子乃使人以千金奉莊子。","chunks":[["太子乃使人以千金奉莊子。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-3_s-2","passageId":"zhuangzi_ch-30_p-3","order":2,"canonicalText":"莊子弗受，與使者俱往見太子曰：「太子何以教周，賜周千金？","chunks":[["莊子弗受，與使者俱往見太子曰：「太子何以教周，賜周千金？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-3_s-3","passageId":"zhuangzi_ch-30_p-3","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-4_s-1","passageId":"zhuangzi_ch-30_p-4","order":1,"canonicalText":"太子曰：「聞夫子明聖，謹奉千金以幣從車。","chunks":[["太子曰：「聞夫子明聖，謹奉千金以幣從車。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-4_s-2","passageId":"zhuangzi_ch-30_p-4","order":2,"canonicalText":"夫子弗受，悝尚何敢言！","chunks":[["夫子弗受，悝尚何敢言！","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-4_s-3","passageId":"zhuangzi_ch-30_p-4","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-5_s-1","passageId":"zhuangzi_ch-30_p-5","order":1,"canonicalText":"莊子曰：「聞太子所欲用周者，欲絕王之喜好也。","chunks":[["莊子曰：「聞太子所欲用周者，欲絕王之喜好也。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-5_s-2","passageId":"zhuangzi_ch-30_p-5","order":2,"canonicalText":"使臣上說大王而逆王意，下不當太子，則身刑而死，周尚安所事金乎？","chunks":[["使臣上說大王而逆王意，下不當太子，則身刑而死，周尚安所事金乎？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-5_s-3","passageId":"zhuangzi_ch-30_p-5","order":3,"canonicalText":"使臣上說大王，下當太子，趙國何求而不得也！","chunks":[["使臣上說大王，下當太子，趙國何求而不得也！","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-5_s-4","passageId":"zhuangzi_ch-30_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-6_s-1","passageId":"zhuangzi_ch-30_p-6","order":1,"canonicalText":"太子曰：「然。","chunks":[["太子曰：「然。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-6_s-2","passageId":"zhuangzi_ch-30_p-6","order":2,"canonicalText":"吾王所見，唯劍士也。","chunks":[["吾王所見，唯劍士也。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-6_s-3","passageId":"zhuangzi_ch-30_p-6","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-7_s-1","passageId":"zhuangzi_ch-30_p-7","order":1,"canonicalText":"莊子曰：「諾。","chunks":[["莊子曰：「諾。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-7_s-2","passageId":"zhuangzi_ch-30_p-7","order":2,"canonicalText":"周善為劍。","chunks":[["周善為劍。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-7_s-3","passageId":"zhuangzi_ch-30_p-7","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-8_s-1","passageId":"zhuangzi_ch-30_p-8","order":1,"canonicalText":"太子曰：「然。","chunks":[["太子曰：「然。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-8_s-2","passageId":"zhuangzi_ch-30_p-8","order":2,"canonicalText":"吾王所見劍士，皆蓬頭突鬢垂冠，曼胡之纓，短後之衣，瞋目而語難王乃悅之。","chunks":[["吾王所見劍士，皆蓬頭突鬢垂冠，曼胡之纓，短後之衣，瞋目而語難王乃悅之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-8_s-3","passageId":"zhuangzi_ch-30_p-8","order":3,"canonicalText":"今夫子必儒服而見王，事必大逆。","chunks":[["今夫子必儒服而見王，事必大逆。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-8_s-4","passageId":"zhuangzi_ch-30_p-8","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-9_s-1","passageId":"zhuangzi_ch-30_p-9","order":1,"canonicalText":"莊子曰：「請治劍服。","chunks":[["莊子曰：「請治劍服。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-9_s-2","passageId":"zhuangzi_ch-30_p-9","order":2,"canonicalText":"」治劍服三日，乃見太子。","chunks":[["」治劍服三日，乃見太子。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-9_s-3","passageId":"zhuangzi_ch-30_p-9","order":3,"canonicalText":"太子乃與見王，王脫白刃待之。","chunks":[["太子乃與見王，王脫白刃待之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-10_s-1","passageId":"zhuangzi_ch-30_p-10","order":1,"canonicalText":"莊子入殿門不趨，見王不拜。","chunks":[["莊子入殿門不趨，見王不拜。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-10_s-2","passageId":"zhuangzi_ch-30_p-10","order":2,"canonicalText":"王曰：「子欲何以教寡人，使太子先？","chunks":[["王曰：「子欲何以教寡人，使太子先？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-10_s-3","passageId":"zhuangzi_ch-30_p-10","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-11_s-1","passageId":"zhuangzi_ch-30_p-11","order":1,"canonicalText":"曰：「臣聞大王喜劍，故以劍見王。","chunks":[["曰：「臣聞大王喜劍，故以劍見王。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-11_s-2","passageId":"zhuangzi_ch-30_p-11","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-12_s-1","passageId":"zhuangzi_ch-30_p-12","order":1,"canonicalText":"王曰：「子之劍何能禁制？","chunks":[["王曰：「子之劍何能禁制？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-12_s-2","passageId":"zhuangzi_ch-30_p-12","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-13_s-1","passageId":"zhuangzi_ch-30_p-13","order":1,"canonicalText":"曰：「臣之劍，十步殺一人，千里不留行。","chunks":[["曰：「臣之劍，十步殺一人，千里不留行。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-13_s-2","passageId":"zhuangzi_ch-30_p-13","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-14_s-1","passageId":"zhuangzi_ch-30_p-14","order":1,"canonicalText":"王大悅之，曰：「天下无敵矣！","chunks":[["王大悅之，曰：「天下无敵矣！","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-14_s-2","passageId":"zhuangzi_ch-30_p-14","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-15_s-1","passageId":"zhuangzi_ch-30_p-15","order":1,"canonicalText":"莊子曰：「夫為劍者，示之以虛，開之以利，後之以發，先之以至。","chunks":[["莊子曰：「夫為劍者，示之以虛，開之以利，後之以發，先之以至。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-15_s-2","passageId":"zhuangzi_ch-30_p-15","order":2,"canonicalText":"願得試之。","chunks":[["願得試之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-15_s-3","passageId":"zhuangzi_ch-30_p-15","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-16_s-1","passageId":"zhuangzi_ch-30_p-16","order":1,"canonicalText":"王曰：「夫子休，就舍。","chunks":[["王曰：「夫子休，就舍。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-16_s-2","passageId":"zhuangzi_ch-30_p-16","order":2,"canonicalText":"待命令設戲請夫子。","chunks":[["待命令設戲請夫子。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-16_s-3","passageId":"zhuangzi_ch-30_p-16","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-17_s-1","passageId":"zhuangzi_ch-30_p-17","order":1,"canonicalText":"王乃校劍士七日，死傷者六十餘人，得五六人，使奉劍於殿下，乃召莊子。","chunks":[["王乃校劍士七日，死傷者六十餘人，得五六人，使奉劍於殿下，乃召莊子。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-17_s-2","passageId":"zhuangzi_ch-30_p-17","order":2,"canonicalText":"王曰：「今日試使士敦劍。","chunks":[["王曰：「今日試使士敦劍。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-17_s-3","passageId":"zhuangzi_ch-30_p-17","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-18_s-1","passageId":"zhuangzi_ch-30_p-18","order":1,"canonicalText":"莊子曰：「望之久矣。","chunks":[["莊子曰：「望之久矣。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-18_s-2","passageId":"zhuangzi_ch-30_p-18","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-19_s-1","passageId":"zhuangzi_ch-30_p-19","order":1,"canonicalText":"王曰：「夫子所御杖，長短何如？","chunks":[["王曰：「夫子所御杖，長短何如？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-19_s-2","passageId":"zhuangzi_ch-30_p-19","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-20_s-1","passageId":"zhuangzi_ch-30_p-20","order":1,"canonicalText":"曰：「臣之所奉皆可。","chunks":[["曰：「臣之所奉皆可。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-20_s-2","passageId":"zhuangzi_ch-30_p-20","order":2,"canonicalText":"然臣有三劍，唯王所用，請先言而後試。","chunks":[["然臣有三劍，唯王所用，請先言而後試。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-20_s-3","passageId":"zhuangzi_ch-30_p-20","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-21_s-1","passageId":"zhuangzi_ch-30_p-21","order":1,"canonicalText":"王曰：「願聞三劍。","chunks":[["王曰：「願聞三劍。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-21_s-2","passageId":"zhuangzi_ch-30_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-22_s-1","passageId":"zhuangzi_ch-30_p-22","order":1,"canonicalText":"曰：「有天子劍，有諸侯劍，有庶人劍。","chunks":[["曰：「有天子劍，有諸侯劍，有庶人劍。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-22_s-2","passageId":"zhuangzi_ch-30_p-22","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-23_s-1","passageId":"zhuangzi_ch-30_p-23","order":1,"canonicalText":"王曰：「天子之劍何如？","chunks":[["王曰：「天子之劍何如？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-23_s-2","passageId":"zhuangzi_ch-30_p-23","order":2,"canonicalText":"」曰：「天子之劍，以燕谿石城為鋒，齊岱為鍔，晉衛為脊，周宋為鐔，韓魏為鋏；","chunks":[["」曰：「天子之劍，以燕谿石城為鋒，齊岱為鍔，晉衛為脊，周宋為鐔，韓魏為鋏；","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-24_s-1","passageId":"zhuangzi_ch-30_p-24","order":1,"canonicalText":"包以四夷，裹以四時；","chunks":[["包以四夷，裹以四時；","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-24_s-2","passageId":"zhuangzi_ch-30_p-24","order":2,"canonicalText":"繞以渤海，帶以常山；","chunks":[["繞以渤海，帶以常山；","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-24_s-3","passageId":"zhuangzi_ch-30_p-24","order":3,"canonicalText":"制以五行，論以刑德；","chunks":[["制以五行，論以刑德；","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-24_s-4","passageId":"zhuangzi_ch-30_p-24","order":4,"canonicalText":"開以陰陽，持以春夏，行以秋冬。","chunks":[["開以陰陽，持以春夏，行以秋冬。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-25_s-1","passageId":"zhuangzi_ch-30_p-25","order":1,"canonicalText":"此劍，直之无前，舉之无上，案之无下，運之无旁，上決浮雲，下絕地紀。","chunks":[["此劍，直之无前，舉之无上，案之无下，運之无旁，上決浮雲，下絕地紀。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-25_s-2","passageId":"zhuangzi_ch-30_p-25","order":2,"canonicalText":"此劍一用，匡諸侯，天下服矣。","chunks":[["此劍一用，匡諸侯，天下服矣。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-25_s-3","passageId":"zhuangzi_ch-30_p-25","order":3,"canonicalText":"此天子之劍也。","chunks":[["此天子之劍也。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-25_s-4","passageId":"zhuangzi_ch-30_p-25","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-26_s-1","passageId":"zhuangzi_ch-30_p-26","order":1,"canonicalText":"文王芒然自失，曰：「諸侯之劍何如？","chunks":[["文王芒然自失，曰：「諸侯之劍何如？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-26_s-2","passageId":"zhuangzi_ch-30_p-26","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-27_s-1","passageId":"zhuangzi_ch-30_p-27","order":1,"canonicalText":"曰：「諸侯之劍，以知勇士為鋒，以清廉士為鍔，以賢良士為脊，以忠聖士為鐔，以豪桀士為鋏。","chunks":[["曰：「諸侯之劍，以知勇士為鋒，以清廉士為鍔，以賢良士為脊，以忠聖士為鐔，以豪桀士為鋏。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-28_s-1","passageId":"zhuangzi_ch-30_p-28","order":1,"canonicalText":"此劍，直之亦无前，舉之亦无上，案之亦无下，運之亦无旁；","chunks":[["此劍，直之亦无前，舉之亦无上，案之亦无下，運之亦无旁；","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-28_s-2","passageId":"zhuangzi_ch-30_p-28","order":2,"canonicalText":"上法圓天以順三光，下法方地以順四時，中和民意以安四鄉。","chunks":[["上法圓天以順三光，下法方地以順四時，中和民意以安四鄉。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-29_s-1","passageId":"zhuangzi_ch-30_p-29","order":1,"canonicalText":"此劍一用，如雷霆之震也，四封之內，无不賓服而聽從君命者矣。","chunks":[["此劍一用，如雷霆之震也，四封之內，无不賓服而聽從君命者矣。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-29_s-2","passageId":"zhuangzi_ch-30_p-29","order":2,"canonicalText":"此諸侯之劍也。","chunks":[["此諸侯之劍也。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-29_s-3","passageId":"zhuangzi_ch-30_p-29","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-30_s-1","passageId":"zhuangzi_ch-30_p-30","order":1,"canonicalText":"王曰：「庶人之劍何如？","chunks":[["王曰：「庶人之劍何如？","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-30_s-2","passageId":"zhuangzi_ch-30_p-30","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-31_s-1","passageId":"zhuangzi_ch-30_p-31","order":1,"canonicalText":"曰：「庶人之劍，蓬頭突鬢垂冠，曼胡之纓，短後之衣，瞋目而語難。","chunks":[["曰：「庶人之劍，蓬頭突鬢垂冠，曼胡之纓，短後之衣，瞋目而語難。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-31_s-2","passageId":"zhuangzi_ch-30_p-31","order":2,"canonicalText":"相擊於前，","chunks":[["相擊於前，","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-32_s-1","passageId":"zhuangzi_ch-30_p-32","order":1,"canonicalText":"上斬頸領，下決肝肺。","chunks":[["上斬頸領，下決肝肺。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-32_s-2","passageId":"zhuangzi_ch-30_p-32","order":2,"canonicalText":"此庶人之劍，无異於鬭雞，一旦命已絕矣，无所用於國事。","chunks":[["此庶人之劍，无異於鬭雞，一旦命已絕矣，无所用於國事。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-32_s-3","passageId":"zhuangzi_ch-30_p-32","order":3,"canonicalText":"今大王有天子之位而好庶人之劍，臣竊為大王薄之。","chunks":[["今大王有天子之位而好庶人之劍，臣竊為大王薄之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-32_s-4","passageId":"zhuangzi_ch-30_p-32","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-33_s-1","passageId":"zhuangzi_ch-30_p-33","order":1,"canonicalText":"王乃牽而上殿。","chunks":[["王乃牽而上殿。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-33_s-2","passageId":"zhuangzi_ch-30_p-33","order":2,"canonicalText":"宰人上食，王三環之。","chunks":[["宰人上食，王三環之。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-33_s-3","passageId":"zhuangzi_ch-30_p-33","order":3,"canonicalText":"莊子曰：「大王安坐定氣，劍事已畢奏矣。","chunks":[["莊子曰：「大王安坐定氣，劍事已畢奏矣。","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-33_s-4","passageId":"zhuangzi_ch-30_p-33","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-30_p-34_s-1","passageId":"zhuangzi_ch-30_p-34","order":1,"canonicalText":"於是文王不出宮三月，劍士皆服斃其處也。","chunks":[["於是文王不出宮三月，劍士皆服斃其處也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-1_s-1","passageId":"zhuangzi_ch-31_p-1","order":1,"canonicalText":"孔子遊乎緇帷之林，休坐乎杏壇之上。","chunks":[["孔子遊乎緇帷之林，休坐乎杏壇之上。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-1_s-2","passageId":"zhuangzi_ch-31_p-1","order":2,"canonicalText":"弟子讀書，孔子弦歌鼓琴，奏曲未半。","chunks":[["弟子讀書，孔子弦歌鼓琴，奏曲未半。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-1_s-3","passageId":"zhuangzi_ch-31_p-1","order":3,"canonicalText":"有漁父者，下船而來，","chunks":[["有漁父者，下船而來，","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-2_s-1","passageId":"zhuangzi_ch-31_p-2","order":1,"canonicalText":"鬢眉交白，被髮揄袂，行原以上，距陸而止，左手據膝，右手持頤以聽。","chunks":[["鬢眉交白，被髮揄袂，行原以上，距陸而止，左手據膝，右手持頤以聽。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-2_s-2","passageId":"zhuangzi_ch-31_p-2","order":2,"canonicalText":"曲終而招子貢、子路，二人俱對。","chunks":[["曲終而招子貢、子路，二人俱對。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-3_s-1","passageId":"zhuangzi_ch-31_p-3","order":1,"canonicalText":"客指孔子曰：「彼何為者也？","chunks":[["客指孔子曰：「彼何為者也？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-3_s-2","passageId":"zhuangzi_ch-31_p-3","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-4_s-1","passageId":"zhuangzi_ch-31_p-4","order":1,"canonicalText":"子路對曰：「魯之君子也。","chunks":[["子路對曰：「魯之君子也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-4_s-2","passageId":"zhuangzi_ch-31_p-4","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-5_s-1","passageId":"zhuangzi_ch-31_p-5","order":1,"canonicalText":"客問其族。","chunks":[["客問其族。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-5_s-2","passageId":"zhuangzi_ch-31_p-5","order":2,"canonicalText":"子路對曰：「族孔氏。","chunks":[["子路對曰：「族孔氏。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-5_s-3","passageId":"zhuangzi_ch-31_p-5","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-6_s-1","passageId":"zhuangzi_ch-31_p-6","order":1,"canonicalText":"客曰：「孔氏者何治也？","chunks":[["客曰：「孔氏者何治也？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-6_s-2","passageId":"zhuangzi_ch-31_p-6","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-7_s-1","passageId":"zhuangzi_ch-31_p-7","order":1,"canonicalText":"子路未應，子貢對曰：「孔氏者，性服忠信，身行仁義，飾禮樂，選人倫，上以忠於世主，下以化於齊民，將以利天下。","chunks":[["子路未應，子貢對曰：「孔氏者，性服忠信，身行仁義，飾禮樂，選人倫，上以忠於世主，下以化於齊民，將以利天下。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-7_s-2","passageId":"zhuangzi_ch-31_p-7","order":2,"canonicalText":"此孔氏之所治也。","chunks":[["此孔氏之所治也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-7_s-3","passageId":"zhuangzi_ch-31_p-7","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-8_s-1","passageId":"zhuangzi_ch-31_p-8","order":1,"canonicalText":"又問曰：「有土之君與？","chunks":[["又問曰：「有土之君與？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-8_s-2","passageId":"zhuangzi_ch-31_p-8","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-9_s-1","passageId":"zhuangzi_ch-31_p-9","order":1,"canonicalText":"子貢曰：「非也。","chunks":[["子貢曰：「非也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-9_s-2","passageId":"zhuangzi_ch-31_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-10_s-1","passageId":"zhuangzi_ch-31_p-10","order":1,"canonicalText":"「侯王之佐與？","chunks":[["「侯王之佐與？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-10_s-2","passageId":"zhuangzi_ch-31_p-10","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-11_s-1","passageId":"zhuangzi_ch-31_p-11","order":1,"canonicalText":"子貢曰：「非也。","chunks":[["子貢曰：「非也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-11_s-2","passageId":"zhuangzi_ch-31_p-11","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-12_s-1","passageId":"zhuangzi_ch-31_p-12","order":1,"canonicalText":"客乃笑而還，行言曰：「仁則仁矣，恐不免其身；","chunks":[["客乃笑而還，行言曰：「仁則仁矣，恐不免其身；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-12_s-2","passageId":"zhuangzi_ch-31_p-12","order":2,"canonicalText":"苦心勞形以危其真。","chunks":[["苦心勞形以危其真。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-12_s-3","passageId":"zhuangzi_ch-31_p-12","order":3,"canonicalText":"嗚呼，遠哉其分於道也！","chunks":[["嗚呼，遠哉其分於道也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-12_s-4","passageId":"zhuangzi_ch-31_p-12","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-13_s-1","passageId":"zhuangzi_ch-31_p-13","order":1,"canonicalText":"子貢還，報孔子。","chunks":[["子貢還，報孔子。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-13_s-2","passageId":"zhuangzi_ch-31_p-13","order":2,"canonicalText":"孔子推琴而起曰：「其聖人與！","chunks":[["孔子推琴而起曰：「其聖人與！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-13_s-3","passageId":"zhuangzi_ch-31_p-13","order":3,"canonicalText":"」乃下求之，至於澤畔，方將杖挐而引其船，顧見孔子，還鄉而立。","chunks":[["」乃下求之，至於澤畔，方將杖挐而引其船，顧見孔子，還鄉而立。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-13_s-4","passageId":"zhuangzi_ch-31_p-13","order":4,"canonicalText":"孔子反走，再拜而進。","chunks":[["孔子反走，再拜而進。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-14_s-1","passageId":"zhuangzi_ch-31_p-14","order":1,"canonicalText":"客曰：「子將何求？","chunks":[["客曰：「子將何求？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-14_s-2","passageId":"zhuangzi_ch-31_p-14","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-15_s-1","passageId":"zhuangzi_ch-31_p-15","order":1,"canonicalText":"孔子曰：「曩者先生有緒言而去，丘不肖，未知所謂，竊待於下風，幸聞咳唾之音以卒相丘也！","chunks":[["孔子曰：「曩者先生有緒言而去，丘不肖，未知所謂，竊待於下風，幸聞咳唾之音以卒相丘也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-15_s-2","passageId":"zhuangzi_ch-31_p-15","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-16_s-1","passageId":"zhuangzi_ch-31_p-16","order":1,"canonicalText":"客曰：「嘻！","chunks":[["客曰：「嘻！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-16_s-2","passageId":"zhuangzi_ch-31_p-16","order":2,"canonicalText":"甚矣子之好學也！","chunks":[["甚矣子之好學也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-16_s-3","passageId":"zhuangzi_ch-31_p-16","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-17_s-1","passageId":"zhuangzi_ch-31_p-17","order":1,"canonicalText":"孔子再拜而起曰：「丘少而脩學，以至於今，六十九歲矣，无所得聞至教，敢不虛心！","chunks":[["孔子再拜而起曰：「丘少而脩學，以至於今，六十九歲矣，无所得聞至教，敢不虛心！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-17_s-2","passageId":"zhuangzi_ch-31_p-17","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-18_s-1","passageId":"zhuangzi_ch-31_p-18","order":1,"canonicalText":"客曰：「同類相從，同聲相應，固天之理也。","chunks":[["客曰：「同類相從，同聲相應，固天之理也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-18_s-2","passageId":"zhuangzi_ch-31_p-18","order":2,"canonicalText":"吾請釋吾之所有而經子之所以。","chunks":[["吾請釋吾之所有而經子之所以。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-18_s-3","passageId":"zhuangzi_ch-31_p-18","order":3,"canonicalText":"子之所以者，人事也。","chunks":[["子之所以者，人事也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-18_s-4","passageId":"zhuangzi_ch-31_p-18","order":4,"canonicalText":"天子諸侯大夫庶人，此四者自正，治之美也，四者離位而亂莫大焉。","chunks":[["天子諸侯大夫庶人，此四者自正，治之美也，四者離位而亂莫大焉。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-19_s-1","passageId":"zhuangzi_ch-31_p-19","order":1,"canonicalText":"官治其職，人處其事，乃无所陵。","chunks":[["官治其職，人處其事，乃无所陵。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-19_s-2","passageId":"zhuangzi_ch-31_p-19","order":2,"canonicalText":"故田荒室露，衣食不足，徵賦不屬，妻妾不和，長少无序，庶人之憂也；","chunks":[["故田荒室露，衣食不足，徵賦不屬，妻妾不和，長少无序，庶人之憂也；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-20_s-1","passageId":"zhuangzi_ch-31_p-20","order":1,"canonicalText":"能不勝任，官事不治，行不清白，群下荒怠，功美不有，爵祿不持，大夫之憂也；","chunks":[["能不勝任，官事不治，行不清白，群下荒怠，功美不有，爵祿不持，大夫之憂也；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-21_s-1","passageId":"zhuangzi_ch-31_p-21","order":1,"canonicalText":"廷无忠臣，國家昏亂，工技不巧，貢職不美，春秋後倫，不順天子，諸侯之憂也；","chunks":[["廷无忠臣，國家昏亂，工技不巧，貢職不美，春秋後倫，不順天子，諸侯之憂也；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-22_s-1","passageId":"zhuangzi_ch-31_p-22","order":1,"canonicalText":"陰陽不和，寒暑不時，以傷庶物，諸侯暴亂，擅相攘伐，以殘民人，禮樂不節，財用窮匱，人倫不飭，百姓淫亂，天子有司之憂也。","chunks":[["陰陽不和，寒暑不時，以傷庶物，諸侯暴亂，擅相攘伐，以殘民人，禮樂不節，財用窮匱，人倫不飭，百姓淫亂，天子有司之憂也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-23_s-1","passageId":"zhuangzi_ch-31_p-23","order":1,"canonicalText":"今子既上无君侯有司之勢，而下无大臣職事之官，而擅飾禮樂，選人倫，以化齊民，不泰多事乎！","chunks":[["今子既上无君侯有司之勢，而下无大臣職事之官，而擅飾禮樂，選人倫，以化齊民，不泰多事乎！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-23_s-2","passageId":"zhuangzi_ch-31_p-23","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-1","passageId":"zhuangzi_ch-31_p-24","order":1,"canonicalText":"「且人有八疵，事有四患，不可不察也。","chunks":[["「且人有八疵，事有四患，不可不察也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-2","passageId":"zhuangzi_ch-31_p-24","order":2,"canonicalText":"非其事而事之，謂之揔；","chunks":[["非其事而事之，謂之揔；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-3","passageId":"zhuangzi_ch-31_p-24","order":3,"canonicalText":"莫之顧而進之，謂之佞；","chunks":[["莫之顧而進之，謂之佞；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-4","passageId":"zhuangzi_ch-31_p-24","order":4,"canonicalText":"希意導言，謂之諂；","chunks":[["希意導言，謂之諂；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-5","passageId":"zhuangzi_ch-31_p-24","order":5,"canonicalText":"不擇是非而言，謂之諛；","chunks":[["不擇是非而言，謂之諛；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-24_s-6","passageId":"zhuangzi_ch-31_p-24","order":6,"canonicalText":"好言人之惡，謂之讒；","chunks":[["好言人之惡，謂之讒；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-25_s-1","passageId":"zhuangzi_ch-31_p-25","order":1,"canonicalText":"析交離親，謂之賊；","chunks":[["析交離親，謂之賊；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-25_s-2","passageId":"zhuangzi_ch-31_p-25","order":2,"canonicalText":"稱譽詐偽以敗惡人，謂之慝；","chunks":[["稱譽詐偽以敗惡人，謂之慝；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-26_s-1","passageId":"zhuangzi_ch-31_p-26","order":1,"canonicalText":"不擇善否，兩容顏適，偷拔其所欲，謂之險。","chunks":[["不擇善否，兩容顏適，偷拔其所欲，謂之險。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-26_s-2","passageId":"zhuangzi_ch-31_p-26","order":2,"canonicalText":"此八疵者，外以亂人，內以傷身，君子不友，明君不臣。","chunks":[["此八疵者，外以亂人，內以傷身，君子不友，明君不臣。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-27_s-1","passageId":"zhuangzi_ch-31_p-27","order":1,"canonicalText":"所謂四患者：好經大事，變更易常，以挂功名，謂之叨；","chunks":[["所謂四患者：好經大事，變更易常，以挂功名，謂之叨；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-27_s-2","passageId":"zhuangzi_ch-31_p-27","order":2,"canonicalText":"專知擅事，侵人自用，謂之貪；","chunks":[["專知擅事，侵人自用，謂之貪；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-28_s-1","passageId":"zhuangzi_ch-31_p-28","order":1,"canonicalText":"見過不更，聞諫愈甚，謂之很；","chunks":[["見過不更，聞諫愈甚，謂之很；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-28_s-2","passageId":"zhuangzi_ch-31_p-28","order":2,"canonicalText":"人同於己則可，不同於己，則雖善不善，謂之矜。","chunks":[["人同於己則可，不同於己，則雖善不善，謂之矜。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-28_s-3","passageId":"zhuangzi_ch-31_p-28","order":3,"canonicalText":"此四患也。","chunks":[["此四患也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-28_s-4","passageId":"zhuangzi_ch-31_p-28","order":4,"canonicalText":"能去八疵，无行四患，而始可教已。","chunks":[["能去八疵，无行四患，而始可教已。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-28_s-5","passageId":"zhuangzi_ch-31_p-28","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-29_s-1","passageId":"zhuangzi_ch-31_p-29","order":1,"canonicalText":"孔子愀然而歎，再拜而起曰：「丘再逐於魯，削迹於衛，伐樹於宋，圍於陳蔡。","chunks":[["孔子愀然而歎，再拜而起曰：「丘再逐於魯，削迹於衛，伐樹於宋，圍於陳蔡。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-29_s-2","passageId":"zhuangzi_ch-31_p-29","order":2,"canonicalText":"丘不知所失，而離此四謗者何也？","chunks":[["丘不知所失，而離此四謗者何也？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-29_s-3","passageId":"zhuangzi_ch-31_p-29","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-30_s-1","passageId":"zhuangzi_ch-31_p-30","order":1,"canonicalText":"客悽然變容曰：「甚矣子之難悟也！","chunks":[["客悽然變容曰：「甚矣子之難悟也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-30_s-2","passageId":"zhuangzi_ch-31_p-30","order":2,"canonicalText":"人有畏影惡迹而去之走者，舉足愈數而迹愈多，走愈疾而影不離（身），自以為尚遲，疾走不休，絕力而死。","chunks":[["人有畏影惡迹而去之走者，舉足愈數而迹愈多，走愈疾而影不離（身），自以為尚遲，疾走不休，絕力而死。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-31_s-1","passageId":"zhuangzi_ch-31_p-31","order":1,"canonicalText":"不知處陰以休影，處靜以息迹，愚亦甚矣！","chunks":[["不知處陰以休影，處靜以息迹，愚亦甚矣！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-31_s-2","passageId":"zhuangzi_ch-31_p-31","order":2,"canonicalText":"子審仁義之閒，察同異之際，觀動靜之變，適受與之度，理好惡之情，和喜怒之節，而幾於不免矣。","chunks":[["子審仁義之閒，察同異之際，觀動靜之變，適受與之度，理好惡之情，和喜怒之節，而幾於不免矣。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-32_s-1","passageId":"zhuangzi_ch-31_p-32","order":1,"canonicalText":"謹脩而身，慎守其真，還以物與人，則无所累矣。","chunks":[["謹脩而身，慎守其真，還以物與人，則无所累矣。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-32_s-2","passageId":"zhuangzi_ch-31_p-32","order":2,"canonicalText":"今不脩之身而求之人，不亦外乎！","chunks":[["今不脩之身而求之人，不亦外乎！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-32_s-3","passageId":"zhuangzi_ch-31_p-32","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-33_s-1","passageId":"zhuangzi_ch-31_p-33","order":1,"canonicalText":"孔子愀然曰：「請問何謂真？","chunks":[["孔子愀然曰：「請問何謂真？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-33_s-2","passageId":"zhuangzi_ch-31_p-33","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-34_s-1","passageId":"zhuangzi_ch-31_p-34","order":1,"canonicalText":"客曰：「真者，精誠之至也。","chunks":[["客曰：「真者，精誠之至也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-34_s-2","passageId":"zhuangzi_ch-31_p-34","order":2,"canonicalText":"不精不誠，不能動人。","chunks":[["不精不誠，不能動人。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-34_s-3","passageId":"zhuangzi_ch-31_p-34","order":3,"canonicalText":"故強哭者雖悲不哀，強怒者雖嚴不威，強親者雖笑不和。","chunks":[["故強哭者雖悲不哀，強怒者雖嚴不威，強親者雖笑不和。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-35_s-1","passageId":"zhuangzi_ch-31_p-35","order":1,"canonicalText":"真悲无聲而哀，真怒未發而威，真親未笑而和。","chunks":[["真悲无聲而哀，真怒未發而威，真親未笑而和。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-35_s-2","passageId":"zhuangzi_ch-31_p-35","order":2,"canonicalText":"真在內者，神動於外，是所以貴真也。","chunks":[["真在內者，神動於外，是所以貴真也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-35_s-3","passageId":"zhuangzi_ch-31_p-35","order":3,"canonicalText":"其用於人理也，事親則慈孝，事君則忠貞，飲酒則歡樂，處喪則悲哀。","chunks":[["其用於人理也，事親則慈孝，事君則忠貞，飲酒則歡樂，處喪則悲哀。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-36_s-1","passageId":"zhuangzi_ch-31_p-36","order":1,"canonicalText":"忠貞以功為主，飲酒以樂為主，處喪以哀為主，事親以適為主，功成之美，无一其迹矣。","chunks":[["忠貞以功為主，飲酒以樂為主，處喪以哀為主，事親以適為主，功成之美，无一其迹矣。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-36_s-2","passageId":"zhuangzi_ch-31_p-36","order":2,"canonicalText":"事親以適，不論所以矣；","chunks":[["事親以適，不論所以矣；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-36_s-3","passageId":"zhuangzi_ch-31_p-36","order":3,"canonicalText":"飲酒以樂，不選其具矣；","chunks":[["飲酒以樂，不選其具矣；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-36_s-4","passageId":"zhuangzi_ch-31_p-36","order":4,"canonicalText":"處喪以哀，无問其禮矣。","chunks":[["處喪以哀，无問其禮矣。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-37_s-1","passageId":"zhuangzi_ch-31_p-37","order":1,"canonicalText":"禮者，世俗之所為也；","chunks":[["禮者，世俗之所為也；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-37_s-2","passageId":"zhuangzi_ch-31_p-37","order":2,"canonicalText":"真者，所以受於天也，自然不可易也。","chunks":[["真者，所以受於天也，自然不可易也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-37_s-3","passageId":"zhuangzi_ch-31_p-37","order":3,"canonicalText":"故聖人法天貴真，不拘於俗。","chunks":[["故聖人法天貴真，不拘於俗。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-37_s-4","passageId":"zhuangzi_ch-31_p-37","order":4,"canonicalText":"愚者反此。","chunks":[["愚者反此。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-38_s-1","passageId":"zhuangzi_ch-31_p-38","order":1,"canonicalText":"不能法天而恤於人，不知貴真，祿祿而受變於俗，故不足。","chunks":[["不能法天而恤於人，不知貴真，祿祿而受變於俗，故不足。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-38_s-2","passageId":"zhuangzi_ch-31_p-38","order":2,"canonicalText":"惜哉，子之早湛於人偽而晚聞大道也！","chunks":[["惜哉，子之早湛於人偽而晚聞大道也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-38_s-3","passageId":"zhuangzi_ch-31_p-38","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-39_s-1","passageId":"zhuangzi_ch-31_p-39","order":1,"canonicalText":"孔子又再拜而起曰：「今者丘得遇也，若天幸然。","chunks":[["孔子又再拜而起曰：「今者丘得遇也，若天幸然。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-39_s-2","passageId":"zhuangzi_ch-31_p-39","order":2,"canonicalText":"先生不羞而比之服役，而身教之。","chunks":[["先生不羞而比之服役，而身教之。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-39_s-3","passageId":"zhuangzi_ch-31_p-39","order":3,"canonicalText":"敢問舍所在，請因受業而卒學大道。","chunks":[["敢問舍所在，請因受業而卒學大道。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-39_s-4","passageId":"zhuangzi_ch-31_p-39","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-40_s-1","passageId":"zhuangzi_ch-31_p-40","order":1,"canonicalText":"客曰：「吾聞之，可與往者與之，至於妙道，不可與往者，不知其道，慎勿與之，身乃无咎。","chunks":[["客曰：「吾聞之，可與往者與之，至於妙道，不可與往者，不知其道，慎勿與之，身乃无咎。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-40_s-2","passageId":"zhuangzi_ch-31_p-40","order":2,"canonicalText":"子勉之！","chunks":[["子勉之！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-40_s-3","passageId":"zhuangzi_ch-31_p-40","order":3,"canonicalText":"吾去子矣，吾去子矣！","chunks":[["吾去子矣，吾去子矣！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-40_s-4","passageId":"zhuangzi_ch-31_p-40","order":4,"canonicalText":"」乃刺船而去，延緣葦閒。","chunks":[["」乃刺船而去，延緣葦閒。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-41_s-1","passageId":"zhuangzi_ch-31_p-41","order":1,"canonicalText":"顏淵還車，子路授綏，孔子不顧，待水波定，不聞挐音而後敢乘。","chunks":[["顏淵還車，子路授綏，孔子不顧，待水波定，不聞挐音而後敢乘。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-42_s-1","passageId":"zhuangzi_ch-31_p-42","order":1,"canonicalText":"子路旁車而問曰：「由得為役久矣，未嘗見夫子遇人如此其威也。","chunks":[["子路旁車而問曰：「由得為役久矣，未嘗見夫子遇人如此其威也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-42_s-2","passageId":"zhuangzi_ch-31_p-42","order":2,"canonicalText":"萬乘之主，千乘之君，見夫子未嘗不分庭伉禮，夫子猶有倨敖之容。","chunks":[["萬乘之主，千乘之君，見夫子未嘗不分庭伉禮，夫子猶有倨敖之容。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-43_s-1","passageId":"zhuangzi_ch-31_p-43","order":1,"canonicalText":"今漁父杖挐逆立，而夫子曲要磬折，言拜而應，得无太甚乎？","chunks":[["今漁父杖挐逆立，而夫子曲要磬折，言拜而應，得无太甚乎？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-43_s-2","passageId":"zhuangzi_ch-31_p-43","order":2,"canonicalText":"門人皆怪夫子矣，漁父何以得此乎？","chunks":[["門人皆怪夫子矣，漁父何以得此乎？","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-43_s-3","passageId":"zhuangzi_ch-31_p-43","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-44_s-1","passageId":"zhuangzi_ch-31_p-44","order":1,"canonicalText":"孔子伏軾而歎曰：「甚矣由之難化也！","chunks":[["孔子伏軾而歎曰：「甚矣由之難化也！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-44_s-2","passageId":"zhuangzi_ch-31_p-44","order":2,"canonicalText":"湛於禮義有閒矣，而樸鄙之心至今未去。","chunks":[["湛於禮義有閒矣，而樸鄙之心至今未去。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-44_s-3","passageId":"zhuangzi_ch-31_p-44","order":3,"canonicalText":"進，吾語汝！","chunks":[["進，吾語汝！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-44_s-4","passageId":"zhuangzi_ch-31_p-44","order":4,"canonicalText":"夫遇長不敬，失禮也；","chunks":[["夫遇長不敬，失禮也；","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-44_s-5","passageId":"zhuangzi_ch-31_p-44","order":5,"canonicalText":"見賢不尊，不仁也。","chunks":[["見賢不尊，不仁也。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-45_s-1","passageId":"zhuangzi_ch-31_p-45","order":1,"canonicalText":"彼非至人，不能下人，下人不精，不得其真，故長傷身。","chunks":[["彼非至人，不能下人，下人不精，不得其真，故長傷身。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-45_s-2","passageId":"zhuangzi_ch-31_p-45","order":2,"canonicalText":"惜哉！","chunks":[["惜哉！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-45_s-3","passageId":"zhuangzi_ch-31_p-45","order":3,"canonicalText":"不仁之於人也，禍莫大焉，而由獨擅之。","chunks":[["不仁之於人也，禍莫大焉，而由獨擅之。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-46_s-1","passageId":"zhuangzi_ch-31_p-46","order":1,"canonicalText":"且道者，萬物之所由也，庶物失之者死，得之者生，為事逆之則敗，順之則成。","chunks":[["且道者，萬物之所由也，庶物失之者死，得之者生，為事逆之則敗，順之則成。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-46_s-2","passageId":"zhuangzi_ch-31_p-46","order":2,"canonicalText":"故道之所在，聖人尊之。","chunks":[["故道之所在，聖人尊之。","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-46_s-3","passageId":"zhuangzi_ch-31_p-46","order":3,"canonicalText":"今漁父之於道，可謂有矣，吾敢不敬乎！","chunks":[["今漁父之於道，可謂有矣，吾敢不敬乎！","zh-Hant"]]},{"id":"zhuangzi_ch-31_p-46_s-4","passageId":"zhuangzi_ch-31_p-46","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-1_s-1","passageId":"zhuangzi_ch-32_p-1","order":1,"canonicalText":"列御寇之齊，中道而反，遇伯昏瞀人。","chunks":[["列御寇之齊，中道而反，遇伯昏瞀人。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-1_s-2","passageId":"zhuangzi_ch-32_p-1","order":2,"canonicalText":"伯昏瞀人曰：「奚方而反？","chunks":[["伯昏瞀人曰：「奚方而反？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-1_s-3","passageId":"zhuangzi_ch-32_p-1","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-2_s-1","passageId":"zhuangzi_ch-32_p-2","order":1,"canonicalText":"曰：「吾驚焉。","chunks":[["曰：「吾驚焉。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-2_s-2","passageId":"zhuangzi_ch-32_p-2","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-3_s-1","passageId":"zhuangzi_ch-32_p-3","order":1,"canonicalText":"曰：「惡乎驚？","chunks":[["曰：「惡乎驚？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-3_s-2","passageId":"zhuangzi_ch-32_p-3","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-4_s-1","passageId":"zhuangzi_ch-32_p-4","order":1,"canonicalText":"曰：「吾嘗食於十漿，而五漿先饋。","chunks":[["曰：「吾嘗食於十漿，而五漿先饋。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-4_s-2","passageId":"zhuangzi_ch-32_p-4","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-5_s-1","passageId":"zhuangzi_ch-32_p-5","order":1,"canonicalText":"伯昏瞀人曰：「若是，則汝何為驚已？","chunks":[["伯昏瞀人曰：「若是，則汝何為驚已？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-5_s-2","passageId":"zhuangzi_ch-32_p-5","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-6_s-1","passageId":"zhuangzi_ch-32_p-6","order":1,"canonicalText":"曰：「夫內誠不解，形諜成光，以外鎮人心，使人輕乎貴老，而𩐋其所患。","chunks":[["曰：「夫內誠不解，形諜成光，以外鎮人心，使人輕乎貴老，而𩐋其所患。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-7_s-1","passageId":"zhuangzi_ch-32_p-7","order":1,"canonicalText":"夫漿人特為食羹之貨，多餘之贏，其為利也薄，其為權也輕，而猶若是，而況於萬乘之主乎！","chunks":[["夫漿人特為食羹之貨，多餘之贏，其為利也薄，其為權也輕，而猶若是，而況於萬乘之主乎！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-7_s-2","passageId":"zhuangzi_ch-32_p-7","order":2,"canonicalText":"身勞於國而知盡於事，彼將任我以事而效我以功，吾是以驚。","chunks":[["身勞於國而知盡於事，彼將任我以事而效我以功，吾是以驚。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-7_s-3","passageId":"zhuangzi_ch-32_p-7","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-8_s-1","passageId":"zhuangzi_ch-32_p-8","order":1,"canonicalText":"伯昏瞀人曰：「善哉觀乎！","chunks":[["伯昏瞀人曰：「善哉觀乎！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-8_s-2","passageId":"zhuangzi_ch-32_p-8","order":2,"canonicalText":"汝處己，人將保汝矣！","chunks":[["汝處己，人將保汝矣！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-8_s-3","passageId":"zhuangzi_ch-32_p-8","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-9_s-1","passageId":"zhuangzi_ch-32_p-9","order":1,"canonicalText":"无幾何而往，則戶外之屨滿矣。","chunks":[["无幾何而往，則戶外之屨滿矣。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-9_s-2","passageId":"zhuangzi_ch-32_p-9","order":2,"canonicalText":"伯昏瞀人北面而立，敦杖蹙之乎頤，立有閒，不言而出。","chunks":[["伯昏瞀人北面而立，敦杖蹙之乎頤，立有閒，不言而出。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-10_s-1","passageId":"zhuangzi_ch-32_p-10","order":1,"canonicalText":"賓者以告列子，列子提屨，跣而走，暨乎門，曰：「先生既來，曾不發藥乎？","chunks":[["賓者以告列子，列子提屨，跣而走，暨乎門，曰：「先生既來，曾不發藥乎？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-10_s-2","passageId":"zhuangzi_ch-32_p-10","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-11_s-1","passageId":"zhuangzi_ch-32_p-11","order":1,"canonicalText":"曰：「已矣，吾固告汝曰人將保汝，果保汝矣。","chunks":[["曰：「已矣，吾固告汝曰人將保汝，果保汝矣。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-11_s-2","passageId":"zhuangzi_ch-32_p-11","order":2,"canonicalText":"非汝能使人保汝，而汝不能使人无保汝也，而焉用之感豫出異也！","chunks":[["非汝能使人保汝，而汝不能使人无保汝也，而焉用之感豫出異也！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-11_s-3","passageId":"zhuangzi_ch-32_p-11","order":3,"canonicalText":"必且有感，搖而本性，又无謂也。","chunks":[["必且有感，搖而本性，又无謂也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-12_s-1","passageId":"zhuangzi_ch-32_p-12","order":1,"canonicalText":"與汝遊者又莫汝告也，彼所小言，盡人毒也。","chunks":[["與汝遊者又莫汝告也，彼所小言，盡人毒也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-12_s-2","passageId":"zhuangzi_ch-32_p-12","order":2,"canonicalText":"莫覺莫悟，何相孰也！","chunks":[["莫覺莫悟，何相孰也！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-12_s-3","passageId":"zhuangzi_ch-32_p-12","order":3,"canonicalText":"巧者勞而知者憂，无能者无所求，飽食而遨遊，汎若不繫之舟，虛而遨遊者也。","chunks":[["巧者勞而知者憂，无能者无所求，飽食而遨遊，汎若不繫之舟，虛而遨遊者也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-12_s-4","passageId":"zhuangzi_ch-32_p-12","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-13_s-1","passageId":"zhuangzi_ch-32_p-13","order":1,"canonicalText":"鄭人緩也，呻吟裘氏之地。","chunks":[["鄭人緩也，呻吟裘氏之地。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-13_s-2","passageId":"zhuangzi_ch-32_p-13","order":2,"canonicalText":"衹三年而緩為儒，河潤九里，澤及三族，使其弟墨。","chunks":[["衹三年而緩為儒，河潤九里，澤及三族，使其弟墨。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-13_s-3","passageId":"zhuangzi_ch-32_p-13","order":3,"canonicalText":"儒墨相與辯，其父助翟。","chunks":[["儒墨相與辯，其父助翟。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-14_s-1","passageId":"zhuangzi_ch-32_p-14","order":1,"canonicalText":"十年而緩自殺。","chunks":[["十年而緩自殺。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-14_s-2","passageId":"zhuangzi_ch-32_p-14","order":2,"canonicalText":"其父夢之曰：「使而子為墨者予也。","chunks":[["其父夢之曰：「使而子為墨者予也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-14_s-3","passageId":"zhuangzi_ch-32_p-14","order":3,"canonicalText":"闔胡嘗視其良，既為秋柏之實矣？","chunks":[["闔胡嘗視其良，既為秋柏之實矣？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-14_s-4","passageId":"zhuangzi_ch-32_p-14","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-15_s-1","passageId":"zhuangzi_ch-32_p-15","order":1,"canonicalText":"夫造物者之報人也，不報其人而報其人之天。","chunks":[["夫造物者之報人也，不報其人而報其人之天。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-15_s-2","passageId":"zhuangzi_ch-32_p-15","order":2,"canonicalText":"彼故使彼。","chunks":[["彼故使彼。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-15_s-3","passageId":"zhuangzi_ch-32_p-15","order":3,"canonicalText":"夫人以己為有以異於人以賤其親，齊人之井飲者相捽也。","chunks":[["夫人以己為有以異於人以賤其親，齊人之井飲者相捽也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-16_s-1","passageId":"zhuangzi_ch-32_p-16","order":1,"canonicalText":"故曰：今之世皆緩也，自是有德者以不知也，而況有道者乎！","chunks":[["故曰：今之世皆緩也，自是有德者以不知也，而況有道者乎！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-16_s-2","passageId":"zhuangzi_ch-32_p-16","order":2,"canonicalText":"古者謂之遁天之刑。","chunks":[["古者謂之遁天之刑。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-17_s-1","passageId":"zhuangzi_ch-32_p-17","order":1,"canonicalText":"聖人安其所安，不安其所不安；","chunks":[["聖人安其所安，不安其所不安；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-17_s-2","passageId":"zhuangzi_ch-32_p-17","order":2,"canonicalText":"眾人安其所不安，不安其所安。","chunks":[["眾人安其所不安，不安其所安。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-18_s-1","passageId":"zhuangzi_ch-32_p-18","order":1,"canonicalText":"莊子曰：「知道易，勿言難。","chunks":[["莊子曰：「知道易，勿言難。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-18_s-2","passageId":"zhuangzi_ch-32_p-18","order":2,"canonicalText":"知而不言，所以之天也；","chunks":[["知而不言，所以之天也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-18_s-3","passageId":"zhuangzi_ch-32_p-18","order":3,"canonicalText":"知而言之，所以之人也；","chunks":[["知而言之，所以之人也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-18_s-4","passageId":"zhuangzi_ch-32_p-18","order":4,"canonicalText":"古之人，天而不人。","chunks":[["古之人，天而不人。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-18_s-5","passageId":"zhuangzi_ch-32_p-18","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-19_s-1","passageId":"zhuangzi_ch-32_p-19","order":1,"canonicalText":"朱泙漫學屠龍於支離益，單千金之家，三年技成而无所用其巧。","chunks":[["朱泙漫學屠龍於支離益，單千金之家，三年技成而无所用其巧。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-20_s-1","passageId":"zhuangzi_ch-32_p-20","order":1,"canonicalText":"聖人以必不必，故无兵；","chunks":[["聖人以必不必，故无兵；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-20_s-2","passageId":"zhuangzi_ch-32_p-20","order":2,"canonicalText":"眾人以不必必之，故多兵；","chunks":[["眾人以不必必之，故多兵；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-20_s-3","passageId":"zhuangzi_ch-32_p-20","order":3,"canonicalText":"順於兵，故行有求。","chunks":[["順於兵，故行有求。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-20_s-4","passageId":"zhuangzi_ch-32_p-20","order":4,"canonicalText":"兵，恃之則亡。","chunks":[["兵，恃之則亡。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-21_s-1","passageId":"zhuangzi_ch-32_p-21","order":1,"canonicalText":"小夫之知，不離苞苴竿牘，敝精神乎蹇淺，而欲兼濟導物，太一形虛。","chunks":[["小夫之知，不離苞苴竿牘，敝精神乎蹇淺，而欲兼濟導物，太一形虛。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-21_s-2","passageId":"zhuangzi_ch-32_p-21","order":2,"canonicalText":"若是者，迷惑于宇宙，形累不知太初。","chunks":[["若是者，迷惑于宇宙，形累不知太初。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-22_s-1","passageId":"zhuangzi_ch-32_p-22","order":1,"canonicalText":"彼至人者，歸精神乎无始而甘瞑乎无何有之鄉。","chunks":[["彼至人者，歸精神乎无始而甘瞑乎无何有之鄉。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-22_s-2","passageId":"zhuangzi_ch-32_p-22","order":2,"canonicalText":"水流乎无形，發泄乎大清。","chunks":[["水流乎无形，發泄乎大清。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-22_s-3","passageId":"zhuangzi_ch-32_p-22","order":3,"canonicalText":"悲哉乎！","chunks":[["悲哉乎！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-22_s-4","passageId":"zhuangzi_ch-32_p-22","order":4,"canonicalText":"汝為知在豪毛，而不知大寧！","chunks":[["汝為知在豪毛，而不知大寧！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-23_s-1","passageId":"zhuangzi_ch-32_p-23","order":1,"canonicalText":"宋人有曹商者，為宋王使秦。","chunks":[["宋人有曹商者，為宋王使秦。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-23_s-2","passageId":"zhuangzi_ch-32_p-23","order":2,"canonicalText":"其往也，得車數乘；","chunks":[["其往也，得車數乘；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-23_s-3","passageId":"zhuangzi_ch-32_p-23","order":3,"canonicalText":"王悅之，益車百乘。","chunks":[["王悅之，益車百乘。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-24_s-1","passageId":"zhuangzi_ch-32_p-24","order":1,"canonicalText":"反於宋，見莊子曰：「夫處窮閭阨巷，困窘織屨，槁項黃馘者，商之所短也；","chunks":[["反於宋，見莊子曰：「夫處窮閭阨巷，困窘織屨，槁項黃馘者，商之所短也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-24_s-2","passageId":"zhuangzi_ch-32_p-24","order":2,"canonicalText":"一悟萬乘之主而從車百乘者，商之所長也。","chunks":[["一悟萬乘之主而從車百乘者，商之所長也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-24_s-3","passageId":"zhuangzi_ch-32_p-24","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-25_s-1","passageId":"zhuangzi_ch-32_p-25","order":1,"canonicalText":"莊子曰：「秦王有病召醫，破癰潰痤者得車一乘，舐痔者得車五乘，所治愈下，得車愈多。","chunks":[["莊子曰：「秦王有病召醫，破癰潰痤者得車一乘，舐痔者得車五乘，所治愈下，得車愈多。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-25_s-2","passageId":"zhuangzi_ch-32_p-25","order":2,"canonicalText":"子豈治其痔邪，何得車之多也？","chunks":[["子豈治其痔邪，何得車之多也？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-25_s-3","passageId":"zhuangzi_ch-32_p-25","order":3,"canonicalText":"子行矣！","chunks":[["子行矣！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-25_s-4","passageId":"zhuangzi_ch-32_p-25","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-26_s-1","passageId":"zhuangzi_ch-32_p-26","order":1,"canonicalText":"魯哀公問乎顏闔曰：「吾以仲尼為貞幹，國其有瘳乎？","chunks":[["魯哀公問乎顏闔曰：「吾以仲尼為貞幹，國其有瘳乎？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-26_s-2","passageId":"zhuangzi_ch-32_p-26","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-27_s-1","passageId":"zhuangzi_ch-32_p-27","order":1,"canonicalText":"曰：「殆哉圾乎仲尼！","chunks":[["曰：「殆哉圾乎仲尼！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-27_s-2","passageId":"zhuangzi_ch-32_p-27","order":2,"canonicalText":"方且飾羽而畫，從事華辭，以支為旨，忍性以視民而不知不信，受乎心，宰乎神，夫何足以上民！","chunks":[["方且飾羽而畫，從事華辭，以支為旨，忍性以視民而不知不信，受乎心，宰乎神，夫何足以上民！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-28_s-1","passageId":"zhuangzi_ch-32_p-28","order":1,"canonicalText":"彼宜汝與？","chunks":[["彼宜汝與？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-28_s-2","passageId":"zhuangzi_ch-32_p-28","order":2,"canonicalText":"予頤與？","chunks":[["予頤與？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-28_s-3","passageId":"zhuangzi_ch-32_p-28","order":3,"canonicalText":"誤而可矣。","chunks":[["誤而可矣。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-28_s-4","passageId":"zhuangzi_ch-32_p-28","order":4,"canonicalText":"今使民離實學偽，非所以視民也，為後世慮，不若休之。","chunks":[["今使民離實學偽，非所以視民也，為後世慮，不若休之。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-29_s-1","passageId":"zhuangzi_ch-32_p-29","order":1,"canonicalText":"難治也。","chunks":[["難治也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-29_s-2","passageId":"zhuangzi_ch-32_p-29","order":2,"canonicalText":"」施於人而不忘，非天布也。","chunks":[["」施於人而不忘，非天布也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-29_s-3","passageId":"zhuangzi_ch-32_p-29","order":3,"canonicalText":"商賈不齒，雖以事齒之，神者弗齒。","chunks":[["商賈不齒，雖以事齒之，神者弗齒。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-30_s-1","passageId":"zhuangzi_ch-32_p-30","order":1,"canonicalText":"為外刑者，金與木也；","chunks":[["為外刑者，金與木也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-30_s-2","passageId":"zhuangzi_ch-32_p-30","order":2,"canonicalText":"為內刑者，動與過也。","chunks":[["為內刑者，動與過也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-30_s-3","passageId":"zhuangzi_ch-32_p-30","order":3,"canonicalText":"宵人之離外刑者，金木訊之；","chunks":[["宵人之離外刑者，金木訊之；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-30_s-4","passageId":"zhuangzi_ch-32_p-30","order":4,"canonicalText":"離內刑者，陰陽食之。","chunks":[["離內刑者，陰陽食之。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-30_s-5","passageId":"zhuangzi_ch-32_p-30","order":5,"canonicalText":"夫免乎外內之刑者，唯真人能之。","chunks":[["夫免乎外內之刑者，唯真人能之。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-31_s-1","passageId":"zhuangzi_ch-32_p-31","order":1,"canonicalText":"孔子曰：「凡人心險於山川，難於知天；","chunks":[["孔子曰：「凡人心險於山川，難於知天；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-31_s-2","passageId":"zhuangzi_ch-32_p-31","order":2,"canonicalText":"天猶有春秋冬夏旦暮之期，人者厚貌深情。","chunks":[["天猶有春秋冬夏旦暮之期，人者厚貌深情。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-32_s-1","passageId":"zhuangzi_ch-32_p-32","order":1,"canonicalText":"故有貌愿而益，有長若不肖，有順懁而達，有堅而縵，有緩而釬。","chunks":[["故有貌愿而益，有長若不肖，有順懁而達，有堅而縵，有緩而釬。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-32_s-2","passageId":"zhuangzi_ch-32_p-32","order":2,"canonicalText":"故其就義若渴者，其去義若熱。","chunks":[["故其就義若渴者，其去義若熱。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-33_s-1","passageId":"zhuangzi_ch-32_p-33","order":1,"canonicalText":"故君子遠使之而觀其忠，近使之而觀其敬，煩使之而觀其能，卒然問焉而觀其知，急與之期而觀其信，委之以財而觀其仁，告之以危而觀其節，","chunks":[["故君子遠使之而觀其忠，近使之而觀其敬，煩使之而觀其能，卒然問焉而觀其知，急與之期而觀其信，委之以財而觀其仁，告之以危而觀其節，","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-34_s-1","passageId":"zhuangzi_ch-32_p-34","order":1,"canonicalText":"醉之以酒而觀其則，雜之以處而觀其色。","chunks":[["醉之以酒而觀其則，雜之以處而觀其色。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-34_s-2","passageId":"zhuangzi_ch-32_p-34","order":2,"canonicalText":"九徵至，不肖人得矣。","chunks":[["九徵至，不肖人得矣。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-34_s-3","passageId":"zhuangzi_ch-32_p-34","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-35_s-1","passageId":"zhuangzi_ch-32_p-35","order":1,"canonicalText":"正考父一命而傴，再命而僂，三命而俯，循牆而走，孰敢不軌！","chunks":[["正考父一命而傴，再命而僂，三命而俯，循牆而走，孰敢不軌！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-36_s-1","passageId":"zhuangzi_ch-32_p-36","order":1,"canonicalText":"如而夫者，一命而呂鉅，再命而於車上儛，三命而名諸父，孰協唐、許！","chunks":[["如而夫者，一命而呂鉅，再命而於車上儛，三命而名諸父，孰協唐、許！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-37_s-1","passageId":"zhuangzi_ch-32_p-37","order":1,"canonicalText":"賊莫大乎德有心而心有眼，及其有眼也而內視，內視而敗矣。","chunks":[["賊莫大乎德有心而心有眼，及其有眼也而內視，內視而敗矣。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-37_s-2","passageId":"zhuangzi_ch-32_p-37","order":2,"canonicalText":"凶德有五，中德為首。","chunks":[["凶德有五，中德為首。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-37_s-3","passageId":"zhuangzi_ch-32_p-37","order":3,"canonicalText":"何謂中德？","chunks":[["何謂中德？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-37_s-4","passageId":"zhuangzi_ch-32_p-37","order":4,"canonicalText":"中德也者，有以自好也，而吡其所不為者也。","chunks":[["中德也者，有以自好也，而吡其所不為者也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-38_s-1","passageId":"zhuangzi_ch-32_p-38","order":1,"canonicalText":"窮有八極，達有三必，形有六府。","chunks":[["窮有八極，達有三必，形有六府。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-38_s-2","passageId":"zhuangzi_ch-32_p-38","order":2,"canonicalText":"美髯長大壯麗勇敢，八者俱過人也，因以是窮。","chunks":[["美髯長大壯麗勇敢，八者俱過人也，因以是窮。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-38_s-3","passageId":"zhuangzi_ch-32_p-38","order":3,"canonicalText":"緣循，偃佒，困畏不若人，三者俱通達。","chunks":[["緣循，偃佒，困畏不若人，三者俱通達。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-39_s-1","passageId":"zhuangzi_ch-32_p-39","order":1,"canonicalText":"知慧外通，勇動多怨，仁義多責。","chunks":[["知慧外通，勇動多怨，仁義多責。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-39_s-2","passageId":"zhuangzi_ch-32_p-39","order":2,"canonicalText":"達生之情者傀，達於知者肖；","chunks":[["達生之情者傀，達於知者肖；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-39_s-3","passageId":"zhuangzi_ch-32_p-39","order":3,"canonicalText":"達大命者隨，達小命者遭。","chunks":[["達大命者隨，達小命者遭。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-40_s-1","passageId":"zhuangzi_ch-32_p-40","order":1,"canonicalText":"人有見宋王者，錫車十乘，以其十乘驕稺莊子。","chunks":[["人有見宋王者，錫車十乘，以其十乘驕稺莊子。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-41_s-1","passageId":"zhuangzi_ch-32_p-41","order":1,"canonicalText":"莊子曰：「河上有家貧恃緯蕭而食者，其子沒於淵，得千金之珠。","chunks":[["莊子曰：「河上有家貧恃緯蕭而食者，其子沒於淵，得千金之珠。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-41_s-2","passageId":"zhuangzi_ch-32_p-41","order":2,"canonicalText":"其父謂其子曰：『取石來鍛之！","chunks":[["其父謂其子曰：『取石來鍛之！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-41_s-3","passageId":"zhuangzi_ch-32_p-41","order":3,"canonicalText":"夫千金之珠，必在九重之淵而驪龍頷下，","chunks":[["夫千金之珠，必在九重之淵而驪龍頷下，","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-1","passageId":"zhuangzi_ch-32_p-42","order":1,"canonicalText":"子能得珠者，必遭其睡也。","chunks":[["子能得珠者，必遭其睡也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-2","passageId":"zhuangzi_ch-32_p-42","order":2,"canonicalText":"使驪龍而寤，子尚奚微之有哉！","chunks":[["使驪龍而寤，子尚奚微之有哉！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-3","passageId":"zhuangzi_ch-32_p-42","order":3,"canonicalText":"』今宋國之深，非直九重之淵也；","chunks":[["』今宋國之深，非直九重之淵也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-4","passageId":"zhuangzi_ch-32_p-42","order":4,"canonicalText":"宋王之猛，非直驪龍也；","chunks":[["宋王之猛，非直驪龍也；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-5","passageId":"zhuangzi_ch-32_p-42","order":5,"canonicalText":"子能得車者，必遭其睡也。","chunks":[["子能得車者，必遭其睡也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-6","passageId":"zhuangzi_ch-32_p-42","order":6,"canonicalText":"使宋王而寤，子為𩐋粉夫！","chunks":[["使宋王而寤，子為𩐋粉夫！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-42_s-7","passageId":"zhuangzi_ch-32_p-42","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-43_s-1","passageId":"zhuangzi_ch-32_p-43","order":1,"canonicalText":"或聘於莊子。","chunks":[["或聘於莊子。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-43_s-2","passageId":"zhuangzi_ch-32_p-43","order":2,"canonicalText":"莊子應其使曰：「子不見夫犧牛乎？","chunks":[["莊子應其使曰：「子不見夫犧牛乎？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-43_s-3","passageId":"zhuangzi_ch-32_p-43","order":3,"canonicalText":"衣以文繡，食以芻菽，及其牽而入於太廟，雖欲為孤犢，其可得乎！","chunks":[["衣以文繡，食以芻菽，及其牽而入於太廟，雖欲為孤犢，其可得乎！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-43_s-4","passageId":"zhuangzi_ch-32_p-43","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-44_s-1","passageId":"zhuangzi_ch-32_p-44","order":1,"canonicalText":"莊子將死，弟子欲厚葬之。","chunks":[["莊子將死，弟子欲厚葬之。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-44_s-2","passageId":"zhuangzi_ch-32_p-44","order":2,"canonicalText":"莊子曰：「吾以天地為棺槨，以日月為連璧，星辰為珠璣，萬物為齎送。","chunks":[["莊子曰：「吾以天地為棺槨，以日月為連璧，星辰為珠璣，萬物為齎送。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-44_s-3","passageId":"zhuangzi_ch-32_p-44","order":3,"canonicalText":"吾葬具豈不備邪？","chunks":[["吾葬具豈不備邪？","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-44_s-4","passageId":"zhuangzi_ch-32_p-44","order":4,"canonicalText":"何以加此！","chunks":[["何以加此！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-44_s-5","passageId":"zhuangzi_ch-32_p-44","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-45_s-1","passageId":"zhuangzi_ch-32_p-45","order":1,"canonicalText":"弟子曰：「吾恐烏鳶之食夫子也。","chunks":[["弟子曰：「吾恐烏鳶之食夫子也。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-45_s-2","passageId":"zhuangzi_ch-32_p-45","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-46_s-1","passageId":"zhuangzi_ch-32_p-46","order":1,"canonicalText":"莊子曰：「在上為烏鳶食，在下為螻蟻食，奪彼與此，何其偏也！","chunks":[["莊子曰：「在上為烏鳶食，在下為螻蟻食，奪彼與此，何其偏也！","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-46_s-2","passageId":"zhuangzi_ch-32_p-46","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-47_s-1","passageId":"zhuangzi_ch-32_p-47","order":1,"canonicalText":"以不平平，其平也不平；","chunks":[["以不平平，其平也不平；","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-47_s-2","passageId":"zhuangzi_ch-32_p-47","order":2,"canonicalText":"以不徵徵，其徵也不徵。","chunks":[["以不徵徵，其徵也不徵。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-47_s-3","passageId":"zhuangzi_ch-32_p-47","order":3,"canonicalText":"明者唯為之使，神者徵之。","chunks":[["明者唯為之使，神者徵之。","zh-Hant"]]},{"id":"zhuangzi_ch-32_p-47_s-4","passageId":"zhuangzi_ch-32_p-47","order":4,"canonicalText":"夫明之不勝神也久矣，而愚者恃其所見入於人，其功外也，不亦悲乎！","chunks":[["夫明之不勝神也久矣，而愚者恃其所見入於人，其功外也，不亦悲乎！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-1_s-1","passageId":"zhuangzi_ch-33_p-1","order":1,"canonicalText":"天下之治方術者多矣，皆以其有為不可加矣。","chunks":[["天下之治方術者多矣，皆以其有為不可加矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-1_s-2","passageId":"zhuangzi_ch-33_p-1","order":2,"canonicalText":"古之所謂道術者，果惡乎在？","chunks":[["古之所謂道術者，果惡乎在？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-1_s-3","passageId":"zhuangzi_ch-33_p-1","order":3,"canonicalText":"曰：「无乎不在。","chunks":[["曰：「无乎不在。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-1_s-4","passageId":"zhuangzi_ch-33_p-1","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-2_s-1","passageId":"zhuangzi_ch-33_p-2","order":1,"canonicalText":"曰：「神何由降？","chunks":[["曰：「神何由降？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-2_s-2","passageId":"zhuangzi_ch-33_p-2","order":2,"canonicalText":"明何由出？","chunks":[["明何由出？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-2_s-3","passageId":"zhuangzi_ch-33_p-2","order":3,"canonicalText":"」「聖有所生，王有所成，皆原於一。","chunks":[["」「聖有所生，王有所成，皆原於一。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-2_s-4","passageId":"zhuangzi_ch-33_p-2","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-3_s-1","passageId":"zhuangzi_ch-33_p-3","order":1,"canonicalText":"不離於宗，謂之天人。","chunks":[["不離於宗，謂之天人。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-3_s-2","passageId":"zhuangzi_ch-33_p-3","order":2,"canonicalText":"不離於精，謂之神人。","chunks":[["不離於精，謂之神人。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-3_s-3","passageId":"zhuangzi_ch-33_p-3","order":3,"canonicalText":"不離於真，謂之至人。","chunks":[["不離於真，謂之至人。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-3_s-4","passageId":"zhuangzi_ch-33_p-3","order":4,"canonicalText":"以天為宗，以德為本，以道為門，兆於變化，謂之聖人。","chunks":[["以天為宗，以德為本，以道為門，兆於變化，謂之聖人。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-4_s-1","passageId":"zhuangzi_ch-33_p-4","order":1,"canonicalText":"以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂之君子。","chunks":[["以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂之君子。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-4_s-2","passageId":"zhuangzi_ch-33_p-4","order":2,"canonicalText":"以法為分，以名為表，以操為驗，以稽為決，其數一二三四是也，百官以此相齒，","chunks":[["以法為分，以名為表，以操為驗，以稽為決，其數一二三四是也，百官以此相齒，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-5_s-1","passageId":"zhuangzi_ch-33_p-5","order":1,"canonicalText":"以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民之理也。","chunks":[["以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民之理也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-6_s-1","passageId":"zhuangzi_ch-33_p-6","order":1,"canonicalText":"古之人其備乎！","chunks":[["古之人其備乎！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-6_s-2","passageId":"zhuangzi_ch-33_p-6","order":2,"canonicalText":"配神明，醇天地，育萬物，和天下，澤及百姓，明於本數，係於末度，六通四闢，小大精粗，其運无乎不在。","chunks":[["配神明，醇天地，育萬物，和天下，澤及百姓，明於本數，係於末度，六通四闢，小大精粗，其運无乎不在。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-7_s-1","passageId":"zhuangzi_ch-33_p-7","order":1,"canonicalText":"其明而在數度者，舊法世傳之史尚多有之。","chunks":[["其明而在數度者，舊法世傳之史尚多有之。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-7_s-2","passageId":"zhuangzi_ch-33_p-7","order":2,"canonicalText":"其在於《詩》、《書》、《禮》、《樂》者，鄒魯之士搢紳先生多能明之。","chunks":[["其在於《詩》、《書》、《禮》、《樂》者，鄒魯之士搢紳先生多能明之。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-8_s-1","passageId":"zhuangzi_ch-33_p-8","order":1,"canonicalText":"《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分。","chunks":[["《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-8_s-2","passageId":"zhuangzi_ch-33_p-8","order":2,"canonicalText":"其數散於天下而設於中國者，百家之學時或稱而道之。","chunks":[["其數散於天下而設於中國者，百家之學時或稱而道之。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-9_s-1","passageId":"zhuangzi_ch-33_p-9","order":1,"canonicalText":"天下大亂，賢聖不明，道德不一，天下多得一察焉以自好。","chunks":[["天下大亂，賢聖不明，道德不一，天下多得一察焉以自好。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-9_s-2","passageId":"zhuangzi_ch-33_p-9","order":2,"canonicalText":"譬如耳目鼻口，皆有所明，不能相通。","chunks":[["譬如耳目鼻口，皆有所明，不能相通。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-9_s-3","passageId":"zhuangzi_ch-33_p-9","order":3,"canonicalText":"猶百家眾技也，皆有所長，時有所用。","chunks":[["猶百家眾技也，皆有所長，時有所用。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-10_s-1","passageId":"zhuangzi_ch-33_p-10","order":1,"canonicalText":"雖然，不該不徧，一曲之士也。","chunks":[["雖然，不該不徧，一曲之士也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-10_s-2","passageId":"zhuangzi_ch-33_p-10","order":2,"canonicalText":"判天地之美，析萬物之理，察古人之全，寡能備於天地之美，稱神明之容。","chunks":[["判天地之美，析萬物之理，察古人之全，寡能備於天地之美，稱神明之容。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-11_s-1","passageId":"zhuangzi_ch-33_p-11","order":1,"canonicalText":"是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其所欲焉以自為方。","chunks":[["是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其所欲焉以自為方。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-11_s-2","passageId":"zhuangzi_ch-33_p-11","order":2,"canonicalText":"悲夫，百家往而不反，必不合矣！","chunks":[["悲夫，百家往而不反，必不合矣！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-12_s-1","passageId":"zhuangzi_ch-33_p-12","order":1,"canonicalText":"後世之學者，不幸不見天地之純，古人之大體，道術將為天下裂。","chunks":[["後世之學者，不幸不見天地之純，古人之大體，道術將為天下裂。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-13_s-1","passageId":"zhuangzi_ch-33_p-13","order":1,"canonicalText":"不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世之急，古之道術有在於是者。","chunks":[["不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世之急，古之道術有在於是者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-13_s-2","passageId":"zhuangzi_ch-33_p-13","order":2,"canonicalText":"墨翟禽滑釐聞其風而悅之，為之太過，已之大循。","chunks":[["墨翟禽滑釐聞其風而悅之，為之太過，已之大循。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-14_s-1","passageId":"zhuangzi_ch-33_p-14","order":1,"canonicalText":"作為《非樂》，命之曰《節用》；","chunks":[["作為《非樂》，命之曰《節用》；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-14_s-2","passageId":"zhuangzi_ch-33_p-14","order":2,"canonicalText":"生不歌，死无服。","chunks":[["生不歌，死无服。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-14_s-3","passageId":"zhuangzi_ch-33_p-14","order":3,"canonicalText":"墨子氾愛兼利而非鬭，其道不怒；","chunks":[["墨子氾愛兼利而非鬭，其道不怒；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-14_s-4","passageId":"zhuangzi_ch-33_p-14","order":4,"canonicalText":"又好學而博，不異，不與先王同，毀古之禮樂。","chunks":[["又好學而博，不異，不與先王同，毀古之禮樂。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-15_s-1","passageId":"zhuangzi_ch-33_p-15","order":1,"canonicalText":"黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍之樂，武王周公作《武》。","chunks":[["黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍之樂，武王周公作《武》。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-15_s-2","passageId":"zhuangzi_ch-33_p-15","order":2,"canonicalText":"古之喪禮，貴賤有儀，上下有等，","chunks":[["古之喪禮，貴賤有儀，上下有等，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-16_s-1","passageId":"zhuangzi_ch-33_p-16","order":1,"canonicalText":"天子棺槨七重，諸侯五重，大夫三重，士再重。","chunks":[["天子棺槨七重，諸侯五重，大夫三重，士再重。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-16_s-2","passageId":"zhuangzi_ch-33_p-16","order":2,"canonicalText":"今墨子獨生不歌，死不服，桐棺三寸而无槨，以為法式。","chunks":[["今墨子獨生不歌，死不服，桐棺三寸而无槨，以為法式。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-17_s-1","passageId":"zhuangzi_ch-33_p-17","order":1,"canonicalText":"以此教人，恐不愛人；","chunks":[["以此教人，恐不愛人；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-17_s-2","passageId":"zhuangzi_ch-33_p-17","order":2,"canonicalText":"以此自行，固不愛己。","chunks":[["以此自行，固不愛己。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-17_s-3","passageId":"zhuangzi_ch-33_p-17","order":3,"canonicalText":"末敗墨子道，雖然，歌而非歌，哭而非哭，樂而非樂，是果類乎？","chunks":[["末敗墨子道，雖然，歌而非歌，哭而非哭，樂而非樂，是果類乎？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-17_s-4","passageId":"zhuangzi_ch-33_p-17","order":4,"canonicalText":"其生也勤，其死也薄，其道大觳；","chunks":[["其生也勤，其死也薄，其道大觳；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-18_s-1","passageId":"zhuangzi_ch-33_p-18","order":1,"canonicalText":"使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反天下之心，天下不堪。","chunks":[["使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反天下之心，天下不堪。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-18_s-2","passageId":"zhuangzi_ch-33_p-18","order":2,"canonicalText":"墨子雖獨能任，奈天下何！","chunks":[["墨子雖獨能任，奈天下何！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-18_s-3","passageId":"zhuangzi_ch-33_p-18","order":3,"canonicalText":"離於天下，其去王也遠矣。","chunks":[["離於天下，其去王也遠矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-19_s-1","passageId":"zhuangzi_ch-33_p-19","order":1,"canonicalText":"墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，名川三百，支川三千，小者无數。","chunks":[["墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，名川三百，支川三千，小者无數。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-19_s-2","passageId":"zhuangzi_ch-33_p-19","order":2,"canonicalText":"禹親自操橐耜而九雜天下之川；","chunks":[["禹親自操橐耜而九雜天下之川；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-19_s-3","passageId":"zhuangzi_ch-33_p-19","order":3,"canonicalText":"腓无胈，脛无毛，","chunks":[["腓无胈，脛无毛，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-20_s-1","passageId":"zhuangzi_ch-33_p-20","order":1,"canonicalText":"沐甚雨，櫛疾風，置萬國。","chunks":[["沐甚雨，櫛疾風，置萬國。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-20_s-2","passageId":"zhuangzi_ch-33_p-20","order":2,"canonicalText":"禹大聖也而形勞天下也如此。","chunks":[["禹大聖也而形勞天下也如此。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-20_s-3","passageId":"zhuangzi_ch-33_p-20","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-21_s-1","passageId":"zhuangzi_ch-33_p-21","order":1,"canonicalText":"使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，曰：「不能如此，非禹之道也，不足謂墨。","chunks":[["使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，曰：「不能如此，非禹之道也，不足謂墨。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-21_s-2","passageId":"zhuangzi_ch-33_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-22_s-1","passageId":"zhuangzi_ch-33_p-22","order":1,"canonicalText":"相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之屬，俱誦《墨經》，而倍譎不同，相謂別墨；","chunks":[["相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之屬，俱誦《墨經》，而倍譎不同，相謂別墨；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-22_s-2","passageId":"zhuangzi_ch-33_p-22","order":2,"canonicalText":"以堅白同異之辯相訾，以觭偶不仵之辭相應；","chunks":[["以堅白同異之辯相訾，以觭偶不仵之辭相應；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-23_s-1","passageId":"zhuangzi_ch-33_p-23","order":1,"canonicalText":"以巨子為聖人，皆願為之尸，冀得為其後世，至今不決。","chunks":[["以巨子為聖人，皆願為之尸，冀得為其後世，至今不決。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-24_s-1","passageId":"zhuangzi_ch-33_p-24","order":1,"canonicalText":"墨翟禽滑釐之意則是，其行則非也。","chunks":[["墨翟禽滑釐之意則是，其行則非也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-24_s-2","passageId":"zhuangzi_ch-33_p-24","order":2,"canonicalText":"將使後世之墨者，必自苦以腓无胈脛无毛相進而已矣。","chunks":[["將使後世之墨者，必自苦以腓无胈脛无毛相進而已矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-24_s-3","passageId":"zhuangzi_ch-33_p-24","order":3,"canonicalText":"亂之上也，治之下也。","chunks":[["亂之上也，治之下也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-24_s-4","passageId":"zhuangzi_ch-33_p-24","order":4,"canonicalText":"雖然，墨子真天下之好也，將求之不得也，雖枯槁不舍也。","chunks":[["雖然，墨子真天下之好也，將求之不得也，雖枯槁不舍也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-24_s-5","passageId":"zhuangzi_ch-33_p-24","order":5,"canonicalText":"才士也夫！","chunks":[["才士也夫！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-25_s-1","passageId":"zhuangzi_ch-33_p-25","order":1,"canonicalText":"不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧以活民命，人我之養畢足而止，以此白心，古之道術有在於是者。","chunks":[["不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧以活民命，人我之養畢足而止，以此白心，古之道術有在於是者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-25_s-2","passageId":"zhuangzi_ch-33_p-25","order":2,"canonicalText":"宋鉼尹文聞其風而悅之，","chunks":[["宋鉼尹文聞其風而悅之，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-26_s-1","passageId":"zhuangzi_ch-33_p-26","order":1,"canonicalText":"作為華山之冠以自表，接萬物以別宥為始；","chunks":[["作為華山之冠以自表，接萬物以別宥為始；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-26_s-2","passageId":"zhuangzi_ch-33_p-26","order":2,"canonicalText":"語心之容，命之曰心之行，以聏合驩，以調海內，請欲置之以為主。","chunks":[["語心之容，命之曰心之行，以聏合驩，以調海內，請欲置之以為主。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-26_s-3","passageId":"zhuangzi_ch-33_p-26","order":3,"canonicalText":"見侮不辱，救民之鬭，禁攻寢兵，救世之戰。","chunks":[["見侮不辱，救民之鬭，禁攻寢兵，救世之戰。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-27_s-1","passageId":"zhuangzi_ch-33_p-27","order":1,"canonicalText":"以此周行天下，上說下教，雖天下不取，強聒而不舍者也，故曰：上下見厭而強見也。","chunks":[["以此周行天下，上說下教，雖天下不取，強聒而不舍者也，故曰：上下見厭而強見也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-28_s-1","passageId":"zhuangzi_ch-33_p-28","order":1,"canonicalText":"雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯足矣。","chunks":[["雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯足矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-28_s-2","passageId":"zhuangzi_ch-33_p-28","order":2,"canonicalText":"」先生恐不得飽，弟子雖飢，不忘天下，日夜不休，曰：","chunks":[["」先生恐不得飽，弟子雖飢，不忘天下，日夜不休，曰：","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-29_s-1","passageId":"zhuangzi_ch-33_p-29","order":1,"canonicalText":"「我必得活哉！","chunks":[["「我必得活哉！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-29_s-2","passageId":"zhuangzi_ch-33_p-29","order":2,"canonicalText":"」圖傲乎救世之士哉！","chunks":[["」圖傲乎救世之士哉！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-29_s-3","passageId":"zhuangzi_ch-33_p-29","order":3,"canonicalText":"曰：「君子不為苛察，不以身假物。","chunks":[["曰：「君子不為苛察，不以身假物。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-29_s-4","passageId":"zhuangzi_ch-33_p-29","order":4,"canonicalText":"」以為无益於天下者，明之不如已也，","chunks":[["」以為无益於天下者，明之不如已也，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-30_s-1","passageId":"zhuangzi_ch-33_p-30","order":1,"canonicalText":"以禁攻寢兵為外，以情欲寡淺為內，其小大精粗，其行適至是而止。","chunks":[["以禁攻寢兵為外，以情欲寡淺為內，其小大精粗，其行適至是而止。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-31_s-1","passageId":"zhuangzi_ch-33_p-31","order":1,"canonicalText":"公而不黨，易而无私，決然无主，趣物而不兩，不顧於慮，不謀於知，於物无擇，與之俱往，古之道術有在於是者。","chunks":[["公而不黨，易而无私，決然无主，趣物而不兩，不顧於慮，不謀於知，於物无擇，與之俱往，古之道術有在於是者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-32_s-1","passageId":"zhuangzi_ch-33_p-32","order":1,"canonicalText":"彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天能覆之，而不能載之；","chunks":[["彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天能覆之，而不能載之；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-32_s-2","passageId":"zhuangzi_ch-33_p-32","order":2,"canonicalText":"地能載之，而不能覆之；","chunks":[["地能載之，而不能覆之；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-32_s-3","passageId":"zhuangzi_ch-33_p-32","order":3,"canonicalText":"大道能包之，而不能辯之。","chunks":[["大道能包之，而不能辯之。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-32_s-4","passageId":"zhuangzi_ch-33_p-32","order":4,"canonicalText":"知萬物皆有所可，有所不可，故曰：選則不徧，教則不至，道則无遺者矣。","chunks":[["知萬物皆有所可，有所不可，故曰：選則不徧，教則不至，道則无遺者矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-32_s-5","passageId":"zhuangzi_ch-33_p-32","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-33_s-1","passageId":"zhuangzi_ch-33_p-33","order":1,"canonicalText":"是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：「知不知，將薄知而後鄰傷之者也。","chunks":[["是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：「知不知，將薄知而後鄰傷之者也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-33_s-2","passageId":"zhuangzi_ch-33_p-33","order":2,"canonicalText":"」謑髁无任，而笑天下之尚賢也；","chunks":[["」謑髁无任，而笑天下之尚賢也；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-33_s-3","passageId":"zhuangzi_ch-33_p-33","order":3,"canonicalText":"縱脫无行，而非天下之大聖。","chunks":[["縱脫无行，而非天下之大聖。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-34_s-1","passageId":"zhuangzi_ch-33_p-34","order":1,"canonicalText":"椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不知前後，魏然而已矣。","chunks":[["椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不知前後，魏然而已矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-34_s-2","passageId":"zhuangzi_ch-33_p-34","order":2,"canonicalText":"推而後行，曳而後往，若飄風之還，若羽之旋，若磨石之隧，全而无非，動靜无過，未嘗有罪。","chunks":[["推而後行，曳而後往，若飄風之還，若羽之旋，若磨石之隧，全而无非，動靜无過，未嘗有罪。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-35_s-1","passageId":"zhuangzi_ch-33_p-35","order":1,"canonicalText":"是何故？","chunks":[["是何故？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-35_s-2","passageId":"zhuangzi_ch-33_p-35","order":2,"canonicalText":"夫无知之物，无建己之患，无用知之累，動靜不離於理，是以終身无譽。","chunks":[["夫无知之物，无建己之患，无用知之累，動靜不離於理，是以終身无譽。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-36_s-1","passageId":"zhuangzi_ch-33_p-36","order":1,"canonicalText":"故曰：至於若无知之物而已，无用賢聖，夫塊不失道。","chunks":[["故曰：至於若无知之物而已，无用賢聖，夫塊不失道。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-36_s-2","passageId":"zhuangzi_ch-33_p-36","order":2,"canonicalText":"豪桀相與笑之曰：「慎到之道，非生人之行而至死人之理，適得怪焉。","chunks":[["豪桀相與笑之曰：「慎到之道，非生人之行而至死人之理，適得怪焉。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-36_s-3","passageId":"zhuangzi_ch-33_p-36","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-37_s-1","passageId":"zhuangzi_ch-33_p-37","order":1,"canonicalText":"田駢亦然，學於彭蒙，得不教焉。","chunks":[["田駢亦然，學於彭蒙，得不教焉。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-37_s-2","passageId":"zhuangzi_ch-33_p-37","order":2,"canonicalText":"彭蒙之師曰：「古之道人，至於莫之是莫之非而已矣。","chunks":[["彭蒙之師曰：「古之道人，至於莫之是莫之非而已矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-37_s-3","passageId":"zhuangzi_ch-33_p-37","order":3,"canonicalText":"其風窢然，惡可而言？","chunks":[["其風窢然，惡可而言？","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-37_s-4","passageId":"zhuangzi_ch-33_p-37","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-38_s-1","passageId":"zhuangzi_ch-33_p-38","order":1,"canonicalText":"常反人，不聚觀，而不免於魭斷。","chunks":[["常反人，不聚觀，而不免於魭斷。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-38_s-2","passageId":"zhuangzi_ch-33_p-38","order":2,"canonicalText":"其所謂道非道，而所言之韙不免於非。","chunks":[["其所謂道非道，而所言之韙不免於非。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-38_s-3","passageId":"zhuangzi_ch-33_p-38","order":3,"canonicalText":"彭蒙、田駢、慎到不知道。","chunks":[["彭蒙、田駢、慎到不知道。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-38_s-4","passageId":"zhuangzi_ch-33_p-38","order":4,"canonicalText":"雖然，概乎皆嘗有聞者也。","chunks":[["雖然，概乎皆嘗有聞者也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-39_s-1","passageId":"zhuangzi_ch-33_p-39","order":1,"canonicalText":"以本為精，以物為粗，以有積為不足，澹然獨與神明居，古之道術有在於是者。","chunks":[["以本為精，以物為粗，以有積為不足，澹然獨與神明居，古之道術有在於是者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-39_s-2","passageId":"zhuangzi_ch-33_p-39","order":2,"canonicalText":"關尹、老聃聞其風而悅之，建之以常无有，主之以太一，以濡弱謙下為表，以空虛不毀萬物為實。","chunks":[["關尹、老聃聞其風而悅之，建之以常无有，主之以太一，以濡弱謙下為表，以空虛不毀萬物為實。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-1","passageId":"zhuangzi_ch-33_p-40","order":1,"canonicalText":"關尹曰：「在己无居，形物自著。","chunks":[["關尹曰：「在己无居，形物自著。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-2","passageId":"zhuangzi_ch-33_p-40","order":2,"canonicalText":"其動若水，其靜若鏡，其應若響。","chunks":[["其動若水，其靜若鏡，其應若響。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-3","passageId":"zhuangzi_ch-33_p-40","order":3,"canonicalText":"芴乎若亡，寂乎若清。","chunks":[["芴乎若亡，寂乎若清。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-4","passageId":"zhuangzi_ch-33_p-40","order":4,"canonicalText":"同焉者和，得焉者失。","chunks":[["同焉者和，得焉者失。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-5","passageId":"zhuangzi_ch-33_p-40","order":5,"canonicalText":"未嘗先人而常隨人。","chunks":[["未嘗先人而常隨人。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-40_s-6","passageId":"zhuangzi_ch-33_p-40","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-41_s-1","passageId":"zhuangzi_ch-33_p-41","order":1,"canonicalText":"老聃曰：「知其雄，守其雌，為天下谿；","chunks":[["老聃曰：「知其雄，守其雌，為天下谿；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-41_s-2","passageId":"zhuangzi_ch-33_p-41","order":2,"canonicalText":"知其白，守其辱，為天下谷。","chunks":[["知其白，守其辱，為天下谷。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-41_s-3","passageId":"zhuangzi_ch-33_p-41","order":3,"canonicalText":"」人皆取先，己獨取後，曰受天下之垢；","chunks":[["」人皆取先，己獨取後，曰受天下之垢；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-42_s-1","passageId":"zhuangzi_ch-33_p-42","order":1,"canonicalText":"人皆取實，己獨取虛，无藏也故有餘，巋然而有餘。","chunks":[["人皆取實，己獨取虛，无藏也故有餘，巋然而有餘。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-42_s-2","passageId":"zhuangzi_ch-33_p-42","order":2,"canonicalText":"其行身也，徐而不費，无為也而笑巧；","chunks":[["其行身也，徐而不費，无為也而笑巧；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-43_s-1","passageId":"zhuangzi_ch-33_p-43","order":1,"canonicalText":"人皆求福，己獨曲全，曰苟免於咎。","chunks":[["人皆求福，己獨曲全，曰苟免於咎。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-43_s-2","passageId":"zhuangzi_ch-33_p-43","order":2,"canonicalText":"以深為根，以約為紀，曰堅則毀矣，銳則挫矣。","chunks":[["以深為根，以約為紀，曰堅則毀矣，銳則挫矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-43_s-3","passageId":"zhuangzi_ch-33_p-43","order":3,"canonicalText":"常寬容於物，不削於人，可謂至極。","chunks":[["常寬容於物，不削於人，可謂至極。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-44_s-1","passageId":"zhuangzi_ch-33_p-44","order":1,"canonicalText":"關尹、老聃乎！","chunks":[["關尹、老聃乎！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-44_s-2","passageId":"zhuangzi_ch-33_p-44","order":2,"canonicalText":"古之博大真人哉！","chunks":[["古之博大真人哉！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-45_s-1","passageId":"zhuangzi_ch-33_p-45","order":1,"canonicalText":"寂漠无形，變化无常，死與生與，天地並與，神明往與！","chunks":[["寂漠无形，變化无常，死與生與，天地並與，神明往與！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-45_s-2","passageId":"zhuangzi_ch-33_p-45","order":2,"canonicalText":"芒乎何之，忽乎何適，萬物畢羅，莫足以歸，古之道術有在於是者。","chunks":[["芒乎何之，忽乎何適，萬物畢羅，莫足以歸，古之道術有在於是者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-46_s-1","passageId":"zhuangzi_ch-33_p-46","order":1,"canonicalText":"莊周聞其風而悅之，以謬悠之說，荒唐之言，无端崖之辭，時恣縱而不儻，不以觭見之也。","chunks":[["莊周聞其風而悅之，以謬悠之說，荒唐之言，无端崖之辭，時恣縱而不儻，不以觭見之也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-46_s-2","passageId":"zhuangzi_ch-33_p-46","order":2,"canonicalText":"以天下為沈濁，不可與莊語，以巵言為曼衍，以重言為真，以寓言為廣。","chunks":[["以天下為沈濁，不可與莊語，以巵言為曼衍，以重言為真，以寓言為廣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-47_s-1","passageId":"zhuangzi_ch-33_p-47","order":1,"canonicalText":"獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗處。","chunks":[["獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗處。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-47_s-2","passageId":"zhuangzi_ch-33_p-47","order":2,"canonicalText":"其書雖瓌瑋，而連犿无傷也。","chunks":[["其書雖瓌瑋，而連犿无傷也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-47_s-3","passageId":"zhuangzi_ch-33_p-47","order":3,"canonicalText":"其辭雖參差，而諔詭可觀。","chunks":[["其辭雖參差，而諔詭可觀。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-47_s-4","passageId":"zhuangzi_ch-33_p-47","order":4,"canonicalText":"彼其充實不可以已，","chunks":[["彼其充實不可以已，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-48_s-1","passageId":"zhuangzi_ch-33_p-48","order":1,"canonicalText":"上與造物者遊，而下與外死生无終始者為友。","chunks":[["上與造物者遊，而下與外死生无終始者為友。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-48_s-2","passageId":"zhuangzi_ch-33_p-48","order":2,"canonicalText":"其於本也，弘大而闢，深閎而肆，其於宗也，可謂調適而上遂矣。","chunks":[["其於本也，弘大而闢，深閎而肆，其於宗也，可謂調適而上遂矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-49_s-1","passageId":"zhuangzi_ch-33_p-49","order":1,"canonicalText":"雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧乎，未之盡者。","chunks":[["雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧乎，未之盡者。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-50_s-1","passageId":"zhuangzi_ch-33_p-50","order":1,"canonicalText":"惠施多方，其書五車，其道舛駁，其言也不中。","chunks":[["惠施多方，其書五車，其道舛駁，其言也不中。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-50_s-2","passageId":"zhuangzi_ch-33_p-50","order":2,"canonicalText":"歷物之意，曰：「至大无外，謂之大一；","chunks":[["歷物之意，曰：「至大无外，謂之大一；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-50_s-3","passageId":"zhuangzi_ch-33_p-50","order":3,"canonicalText":"至小无內，謂之小一。","chunks":[["至小无內，謂之小一。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-51_s-1","passageId":"zhuangzi_ch-33_p-51","order":1,"canonicalText":"无厚，不可積也，其大千里。","chunks":[["无厚，不可積也，其大千里。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-51_s-2","passageId":"zhuangzi_ch-33_p-51","order":2,"canonicalText":"天與地卑，山與澤平。","chunks":[["天與地卑，山與澤平。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-51_s-3","passageId":"zhuangzi_ch-33_p-51","order":3,"canonicalText":"日方中方睨，物方生方死。","chunks":[["日方中方睨，物方生方死。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-51_s-4","passageId":"zhuangzi_ch-33_p-51","order":4,"canonicalText":"大同而與小同異，此之謂小同異；","chunks":[["大同而與小同異，此之謂小同異；","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-51_s-5","passageId":"zhuangzi_ch-33_p-51","order":5,"canonicalText":"萬物畢同畢異，此之謂大同異。","chunks":[["萬物畢同畢異，此之謂大同異。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-52_s-1","passageId":"zhuangzi_ch-33_p-52","order":1,"canonicalText":"南方无窮而有窮，今日適越而昔來。","chunks":[["南方无窮而有窮，今日適越而昔來。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-52_s-2","passageId":"zhuangzi_ch-33_p-52","order":2,"canonicalText":"連環可解也。","chunks":[["連環可解也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-52_s-3","passageId":"zhuangzi_ch-33_p-52","order":3,"canonicalText":"我知天下之中央，燕之北越之南是也。","chunks":[["我知天下之中央，燕之北越之南是也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-52_s-4","passageId":"zhuangzi_ch-33_p-52","order":4,"canonicalText":"氾愛萬物，天地一體也。","chunks":[["氾愛萬物，天地一體也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-52_s-5","passageId":"zhuangzi_ch-33_p-52","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-53_s-1","passageId":"zhuangzi_ch-33_p-53","order":1,"canonicalText":"惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之。","chunks":[["惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-53_s-2","passageId":"zhuangzi_ch-33_p-53","order":2,"canonicalText":"卵有毛，雞三足，郢有天下，犬可以為羊，馬有卵，丁子有尾，","chunks":[["卵有毛，雞三足，郢有天下，犬可以為羊，馬有卵，丁子有尾，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-54_s-1","passageId":"zhuangzi_ch-33_p-54","order":1,"canonicalText":"火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥之景未嘗動也，","chunks":[["火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥之景未嘗動也，","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-55_s-1","passageId":"zhuangzi_ch-33_p-55","order":1,"canonicalText":"鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺之捶，日取其半，萬世不竭。","chunks":[["鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺之捶，日取其半，萬世不竭。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-55_s-2","passageId":"zhuangzi_ch-33_p-55","order":2,"canonicalText":"辯者以此與惠施相應，終身无窮。","chunks":[["辯者以此與惠施相應，終身无窮。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-56_s-1","passageId":"zhuangzi_ch-33_p-56","order":1,"canonicalText":"桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口，不能服人之心，辯者之囿也。","chunks":[["桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口，不能服人之心，辯者之囿也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-56_s-2","passageId":"zhuangzi_ch-33_p-56","order":2,"canonicalText":"惠施日以其知與人之辯，特與天下之辯者為怪，此其柢也。","chunks":[["惠施日以其知與人之辯，特與天下之辯者為怪，此其柢也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-57_s-1","passageId":"zhuangzi_ch-33_p-57","order":1,"canonicalText":"然惠施之口談，自以為最賢，曰天地其壯乎！","chunks":[["然惠施之口談，自以為最賢，曰天地其壯乎！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-57_s-2","passageId":"zhuangzi_ch-33_p-57","order":2,"canonicalText":"施存雄而无術。","chunks":[["施存雄而无術。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-57_s-3","passageId":"zhuangzi_ch-33_p-57","order":3,"canonicalText":"南方有倚人焉曰黃繚，問天地所以不墜不陷，風雨雷霆之故。","chunks":[["南方有倚人焉曰黃繚，問天地所以不墜不陷，風雨雷霆之故。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-58_s-1","passageId":"zhuangzi_ch-33_p-58","order":1,"canonicalText":"惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而无已，猶以為寡，益之以怪。","chunks":[["惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而无已，猶以為寡，益之以怪。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-58_s-2","passageId":"zhuangzi_ch-33_p-58","order":2,"canonicalText":"以反人為實而欲以勝人為名，是以與眾不適也。","chunks":[["以反人為實而欲以勝人為名，是以與眾不適也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-59_s-1","passageId":"zhuangzi_ch-33_p-59","order":1,"canonicalText":"弱於德，強於物，其塗隩矣。","chunks":[["弱於德，強於物，其塗隩矣。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-59_s-2","passageId":"zhuangzi_ch-33_p-59","order":2,"canonicalText":"由天地之道觀惠施之能，其猶一蚊一䖟之勞者也。","chunks":[["由天地之道觀惠施之能，其猶一蚊一䖟之勞者也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-59_s-3","passageId":"zhuangzi_ch-33_p-59","order":3,"canonicalText":"其於物也何庸！","chunks":[["其於物也何庸！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-59_s-4","passageId":"zhuangzi_ch-33_p-59","order":4,"canonicalText":"夫充一尚可，曰愈貴道，幾矣！","chunks":[["夫充一尚可，曰愈貴道，幾矣！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-60_s-1","passageId":"zhuangzi_ch-33_p-60","order":1,"canonicalText":"惠施不能以此自寧，散於萬物而不厭，卒以善辯為名。","chunks":[["惠施不能以此自寧，散於萬物而不厭，卒以善辯為名。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-60_s-2","passageId":"zhuangzi_ch-33_p-60","order":2,"canonicalText":"惜乎！","chunks":[["惜乎！","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-60_s-3","passageId":"zhuangzi_ch-33_p-60","order":3,"canonicalText":"惠施之才，駘蕩而不得，逐萬物而不反，是窮響以聲，形與影競走也。","chunks":[["惠施之才，駘蕩而不得，逐萬物而不反，是窮響以聲，形與影競走也。","zh-Hant"]]},{"id":"zhuangzi_ch-33_p-60_s-4","passageId":"zhuangzi_ch-33_p-60","order":4,"canonicalText":"悲夫！","chunks":[["悲夫！","zh-Hant"]]},{"id":"three-strategies_ch-1_p-1_s-1","passageId":"three-strategies_ch-1_p-1","order":1,"canonicalText":"夫主將之法，務攬英雄之心，賞祿有功，通志于眾，故與眾同好，靡不成與眾同惡，靡不傾。","chunks":[["夫主將之法，務攬英雄之心，賞祿有功，通志于眾，故與眾同好，靡不成與眾同惡，靡不傾。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-1_s-2","passageId":"three-strategies_ch-1_p-1","order":2,"canonicalText":"治國安家，得人也，亡國破家，失人也，含氣之類，咸願得其志。","chunks":[["治國安家，得人也，亡國破家，失人也，含氣之類，咸願得其志。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-1","passageId":"three-strategies_ch-1_p-2","order":1,"canonicalText":"軍讖曰：柔能制剛，弱能制強。","chunks":[["軍讖曰：柔能制剛，弱能制強。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-2","passageId":"three-strategies_ch-1_p-2","order":2,"canonicalText":"柔者，德也。","chunks":[["柔者，德也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-3","passageId":"three-strategies_ch-1_p-2","order":3,"canonicalText":"剛者，賊也。","chunks":[["剛者，賊也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-4","passageId":"three-strategies_ch-1_p-2","order":4,"canonicalText":"弱者，人之所助。","chunks":[["弱者，人之所助。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-5","passageId":"three-strategies_ch-1_p-2","order":5,"canonicalText":"強者，怨之所攻。","chunks":[["強者，怨之所攻。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-2_s-6","passageId":"three-strategies_ch-1_p-2","order":6,"canonicalText":"柔有所設，剛有所施，弱有所用，強有所加，兼此四者，而制其宜。","chunks":[["柔有所設，剛有所施，弱有所用，強有所加，兼此四者，而制其宜。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-1","passageId":"three-strategies_ch-1_p-3","order":1,"canonicalText":"端末未見，人莫能知。","chunks":[["端末未見，人莫能知。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-2","passageId":"three-strategies_ch-1_p-3","order":2,"canonicalText":"天地神明；","chunks":[["天地神明；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-3","passageId":"three-strategies_ch-1_p-3","order":3,"canonicalText":"與物推移。","chunks":[["與物推移。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-4","passageId":"three-strategies_ch-1_p-3","order":4,"canonicalText":"變動無常，因敵轉化。","chunks":[["變動無常，因敵轉化。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-5","passageId":"three-strategies_ch-1_p-3","order":5,"canonicalText":"不為事先，動而輒隨。","chunks":[["不為事先，動而輒隨。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-6","passageId":"three-strategies_ch-1_p-3","order":6,"canonicalText":"故能圖制無疆，扶成天威。","chunks":[["故能圖制無疆，扶成天威。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-7","passageId":"three-strategies_ch-1_p-3","order":7,"canonicalText":"康正八極，密定九夷。","chunks":[["康正八極，密定九夷。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-3_s-8","passageId":"three-strategies_ch-1_p-3","order":8,"canonicalText":"如此謀者，為帝王師。","chunks":[["如此謀者，為帝王師。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-4_s-1","passageId":"three-strategies_ch-1_p-4","order":1,"canonicalText":"故曰：莫不貪強，鮮能守微，若能守微，乃保其生。","chunks":[["故曰：莫不貪強，鮮能守微，若能守微，乃保其生。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-4_s-2","passageId":"three-strategies_ch-1_p-4","order":2,"canonicalText":"聖人存之，以應事機。","chunks":[["聖人存之，以應事機。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-4_s-3","passageId":"three-strategies_ch-1_p-4","order":3,"canonicalText":"舒之彌四海，卷之不盈杯，居之不以室宅，守之不以城郭，藏之胸臆，而敵國服。","chunks":[["舒之彌四海，卷之不盈杯，居之不以室宅，守之不以城郭，藏之胸臆，而敵國服。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-5_s-1","passageId":"three-strategies_ch-1_p-5","order":1,"canonicalText":"軍讖曰：能柔能剛，其國彌光。","chunks":[["軍讖曰：能柔能剛，其國彌光。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-5_s-2","passageId":"three-strategies_ch-1_p-5","order":2,"canonicalText":"能弱能強，其國彌彰。","chunks":[["能弱能強，其國彌彰。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-5_s-3","passageId":"three-strategies_ch-1_p-5","order":3,"canonicalText":"純柔純弱，其國必削、純剛純強，其國必亡。","chunks":[["純柔純弱，其國必削、純剛純強，其國必亡。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-6_s-1","passageId":"three-strategies_ch-1_p-6","order":1,"canonicalText":"夫為國之道，恃賢與民，信賢如腹心，使民如四肢，則策無遣。","chunks":[["夫為國之道，恃賢與民，信賢如腹心，使民如四肢，則策無遣。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-6_s-2","passageId":"three-strategies_ch-1_p-6","order":2,"canonicalText":"所適如肢體相隨，骨節相救，天道自然，其巧無間。","chunks":[["所適如肢體相隨，骨節相救，天道自然，其巧無間。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-1","passageId":"three-strategies_ch-1_p-7","order":1,"canonicalText":"軍國之要，察眾心，施百務；","chunks":[["軍國之要，察眾心，施百務；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-2","passageId":"three-strategies_ch-1_p-7","order":2,"canonicalText":"危者，安之。","chunks":[["危者，安之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-3","passageId":"three-strategies_ch-1_p-7","order":3,"canonicalText":"懼者，歡之。","chunks":[["懼者，歡之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-4","passageId":"three-strategies_ch-1_p-7","order":4,"canonicalText":"叛者，還之。","chunks":[["叛者，還之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-5","passageId":"three-strategies_ch-1_p-7","order":5,"canonicalText":"冤者，原之：訴者，察之。","chunks":[["冤者，原之：訴者，察之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-6","passageId":"three-strategies_ch-1_p-7","order":6,"canonicalText":"卑者，貴之。","chunks":[["卑者，貴之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-7","passageId":"three-strategies_ch-1_p-7","order":7,"canonicalText":"強者，抑之。","chunks":[["強者，抑之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-8","passageId":"three-strategies_ch-1_p-7","order":8,"canonicalText":"敵者，殘之。","chunks":[["敵者，殘之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-9","passageId":"three-strategies_ch-1_p-7","order":9,"canonicalText":"貪者，豐之。","chunks":[["貪者，豐之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-10","passageId":"three-strategies_ch-1_p-7","order":10,"canonicalText":"欲者，使之。","chunks":[["欲者，使之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-11","passageId":"three-strategies_ch-1_p-7","order":11,"canonicalText":"畏者，隱之。","chunks":[["畏者，隱之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-12","passageId":"three-strategies_ch-1_p-7","order":12,"canonicalText":"謀者，近之。","chunks":[["謀者，近之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-13","passageId":"three-strategies_ch-1_p-7","order":13,"canonicalText":"讒者，覆之。","chunks":[["讒者，覆之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-14","passageId":"three-strategies_ch-1_p-7","order":14,"canonicalText":"毀者，復之。","chunks":[["毀者，復之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-15","passageId":"three-strategies_ch-1_p-7","order":15,"canonicalText":"反者，廢之。","chunks":[["反者，廢之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-16","passageId":"three-strategies_ch-1_p-7","order":16,"canonicalText":"橫者，挫之。","chunks":[["橫者，挫之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-17","passageId":"three-strategies_ch-1_p-7","order":17,"canonicalText":"滿者，損之。","chunks":[["滿者，損之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-18","passageId":"three-strategies_ch-1_p-7","order":18,"canonicalText":"歸者，招之。","chunks":[["歸者，招之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-19","passageId":"three-strategies_ch-1_p-7","order":19,"canonicalText":"服者，活之。","chunks":[["服者，活之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-20","passageId":"three-strategies_ch-1_p-7","order":20,"canonicalText":"降者，脫之。","chunks":[["降者，脫之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-21","passageId":"three-strategies_ch-1_p-7","order":21,"canonicalText":"獲固，守之。","chunks":[["獲固，守之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-22","passageId":"three-strategies_ch-1_p-7","order":22,"canonicalText":"獲阨，塞之。","chunks":[["獲阨，塞之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-23","passageId":"three-strategies_ch-1_p-7","order":23,"canonicalText":"獲難，屯之。","chunks":[["獲難，屯之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-24","passageId":"three-strategies_ch-1_p-7","order":24,"canonicalText":"獲城，割之。","chunks":[["獲城，割之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-25","passageId":"three-strategies_ch-1_p-7","order":25,"canonicalText":"獲地，裂之。","chunks":[["獲地，裂之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-26","passageId":"three-strategies_ch-1_p-7","order":26,"canonicalText":"獲財，散之。","chunks":[["獲財，散之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-27","passageId":"three-strategies_ch-1_p-7","order":27,"canonicalText":"敵動，伺之。","chunks":[["敵動，伺之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-28","passageId":"three-strategies_ch-1_p-7","order":28,"canonicalText":"敵近，備之。","chunks":[["敵近，備之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-29","passageId":"three-strategies_ch-1_p-7","order":29,"canonicalText":"敵強，下之。","chunks":[["敵強，下之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-30","passageId":"three-strategies_ch-1_p-7","order":30,"canonicalText":"敵佚，去之。","chunks":[["敵佚，去之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-31","passageId":"three-strategies_ch-1_p-7","order":31,"canonicalText":"敵陵，待之。","chunks":[["敵陵，待之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-32","passageId":"three-strategies_ch-1_p-7","order":32,"canonicalText":"敵暴，緩之。","chunks":[["敵暴，緩之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-33","passageId":"three-strategies_ch-1_p-7","order":33,"canonicalText":"敵悖，義之。","chunks":[["敵悖，義之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-34","passageId":"three-strategies_ch-1_p-7","order":34,"canonicalText":"敵睦，攜之。","chunks":[["敵睦，攜之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-35","passageId":"three-strategies_ch-1_p-7","order":35,"canonicalText":"順舉挫之。","chunks":[["順舉挫之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-36","passageId":"three-strategies_ch-1_p-7","order":36,"canonicalText":"因勢破之。","chunks":[["因勢破之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-37","passageId":"three-strategies_ch-1_p-7","order":37,"canonicalText":"放言過之。","chunks":[["放言過之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-38","passageId":"three-strategies_ch-1_p-7","order":38,"canonicalText":"四網羅之。","chunks":[["四網羅之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-39","passageId":"three-strategies_ch-1_p-7","order":39,"canonicalText":"得而勿有，居而勿守，拔而勿久，立而勿取。","chunks":[["得而勿有，居而勿守，拔而勿久，立而勿取。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-40","passageId":"three-strategies_ch-1_p-7","order":40,"canonicalText":"為者則己，有者則士，焉知利之所在。","chunks":[["為者則己，有者則士，焉知利之所在。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-7_s-41","passageId":"three-strategies_ch-1_p-7","order":41,"canonicalText":"彼為諸侯，己為天子，使城自保，令士自處。","chunks":[["彼為諸侯，己為天子，使城自保，令士自處。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-8_s-1","passageId":"three-strategies_ch-1_p-8","order":1,"canonicalText":"世能祖祖，鮮能下下，祖祖為親，下下為君。","chunks":[["世能祖祖，鮮能下下，祖祖為親，下下為君。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-8_s-2","passageId":"three-strategies_ch-1_p-8","order":2,"canonicalText":"下下者，務耕桑，不奪其時；","chunks":[["下下者，務耕桑，不奪其時；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-8_s-3","passageId":"three-strategies_ch-1_p-8","order":3,"canonicalText":"薄賦斂，不匱其財。","chunks":[["薄賦斂，不匱其財。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-8_s-4","passageId":"three-strategies_ch-1_p-8","order":4,"canonicalText":"罕徭役，不使其勞，則國富而家娛，然後選士以司牧之。","chunks":[["罕徭役，不使其勞，則國富而家娛，然後選士以司牧之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-9_s-1","passageId":"three-strategies_ch-1_p-9","order":1,"canonicalText":"夫所謂士者，英雄也。","chunks":[["夫所謂士者，英雄也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-9_s-2","passageId":"three-strategies_ch-1_p-9","order":2,"canonicalText":"故曰羅其英雄，則敵國窮。","chunks":[["故曰羅其英雄，則敵國窮。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-9_s-3","passageId":"three-strategies_ch-1_p-9","order":3,"canonicalText":"英雄者，國之幹。","chunks":[["英雄者，國之幹。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-9_s-4","passageId":"three-strategies_ch-1_p-9","order":4,"canonicalText":"庶民者，國之本。","chunks":[["庶民者，國之本。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-9_s-5","passageId":"three-strategies_ch-1_p-9","order":5,"canonicalText":"得其幹，收其本，則政行而無怨。","chunks":[["得其幹，收其本，則政行而無怨。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-10_s-1","passageId":"three-strategies_ch-1_p-10","order":1,"canonicalText":"夫用兵之要，在崇禮而重祿。","chunks":[["夫用兵之要，在崇禮而重祿。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-10_s-2","passageId":"three-strategies_ch-1_p-10","order":2,"canonicalText":"禮崇則智士至，祿重則義士輕死。","chunks":[["禮崇則智士至，祿重則義士輕死。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-10_s-3","passageId":"three-strategies_ch-1_p-10","order":3,"canonicalText":"故祿賢不愛財，賞功不瑜時，則下力并，敵國削。","chunks":[["故祿賢不愛財，賞功不瑜時，則下力并，敵國削。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-10_s-4","passageId":"three-strategies_ch-1_p-10","order":4,"canonicalText":"夫用人之道，尊以爵，睹以財，則士自來。","chunks":[["夫用人之道，尊以爵，睹以財，則士自來。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-10_s-5","passageId":"three-strategies_ch-1_p-10","order":5,"canonicalText":"接以禮，勵以義，則士死之。","chunks":[["接以禮，勵以義，則士死之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-11_s-1","passageId":"three-strategies_ch-1_p-11","order":1,"canonicalText":"夫將帥者，必與士卒同滋味，而共安危，敵乃可加：故兵有全勝，敵有全因。","chunks":[["夫將帥者，必與士卒同滋味，而共安危，敵乃可加：故兵有全勝，敵有全因。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-11_s-2","passageId":"three-strategies_ch-1_p-11","order":2,"canonicalText":"昔者，良將之用，有饋簞醪者，使投諸河，與士卒同流而飲。","chunks":[["昔者，良將之用，有饋簞醪者，使投諸河，與士卒同流而飲。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-11_s-3","passageId":"three-strategies_ch-1_p-11","order":3,"canonicalText":"夫一簞之醪，不能味一河之水，而三軍之士，思為致死者，以滋味之及己也。","chunks":[["夫一簞之醪，不能味一河之水，而三軍之士，思為致死者，以滋味之及己也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-1","passageId":"three-strategies_ch-1_p-12","order":1,"canonicalText":"軍讖曰：軍井未達，將不言渴。","chunks":[["軍讖曰：軍井未達，將不言渴。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-2","passageId":"three-strategies_ch-1_p-12","order":2,"canonicalText":"軍幕未辦，將不言倦。","chunks":[["軍幕未辦，將不言倦。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-3","passageId":"three-strategies_ch-1_p-12","order":3,"canonicalText":"軍灶未炊，將不言飢。","chunks":[["軍灶未炊，將不言飢。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-4","passageId":"three-strategies_ch-1_p-12","order":4,"canonicalText":"冬不服裘，夏不操扇，雨不張蓋，是謂將禮。","chunks":[["冬不服裘，夏不操扇，雨不張蓋，是謂將禮。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-5","passageId":"three-strategies_ch-1_p-12","order":5,"canonicalText":"與之安，與之危，故其眾，可合而不可離，可用而不可疲，以其恩素蓄，謀素合也。","chunks":[["與之安，與之危，故其眾，可合而不可離，可用而不可疲，以其恩素蓄，謀素合也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-12_s-6","passageId":"three-strategies_ch-1_p-12","order":6,"canonicalText":"故曰：蓄恩不倦，以一取萬。","chunks":[["故曰：蓄恩不倦，以一取萬。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-13_s-1","passageId":"three-strategies_ch-1_p-13","order":1,"canonicalText":"軍讖曰：將之所以為威者，號令也。","chunks":[["軍讖曰：將之所以為威者，號令也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-13_s-2","passageId":"three-strategies_ch-1_p-13","order":2,"canonicalText":"戰之所以全勝者，軍政也。","chunks":[["戰之所以全勝者，軍政也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-13_s-3","passageId":"three-strategies_ch-1_p-13","order":3,"canonicalText":"士之所以輕死者，用命也。","chunks":[["士之所以輕死者，用命也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-13_s-4","passageId":"three-strategies_ch-1_p-13","order":4,"canonicalText":"故將無還令，賞罰必信，如天如地，乃可使人，士卒用命，乃可越境。","chunks":[["故將無還令，賞罰必信，如天如地，乃可使人，士卒用命，乃可越境。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-1","passageId":"three-strategies_ch-1_p-14","order":1,"canonicalText":"夫統軍持勢者，將也。","chunks":[["夫統軍持勢者，將也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-2","passageId":"three-strategies_ch-1_p-14","order":2,"canonicalText":"制勝敗敵者，眾也。","chunks":[["制勝敗敵者，眾也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-3","passageId":"three-strategies_ch-1_p-14","order":3,"canonicalText":"故亂將不可使保軍，乘眾不可使伐人。","chunks":[["故亂將不可使保軍，乘眾不可使伐人。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-4","passageId":"three-strategies_ch-1_p-14","order":4,"canonicalText":"攻城不可拔，圍邑則不廢。","chunks":[["攻城不可拔，圍邑則不廢。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-5","passageId":"three-strategies_ch-1_p-14","order":5,"canonicalText":"二者無功，則士力疲憊，士力疲憊，則將孤眾悖，以守則不固，以戰則奔北，是謂老兵。","chunks":[["二者無功，則士力疲憊，士力疲憊，則將孤眾悖，以守則不固，以戰則奔北，是謂老兵。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-6","passageId":"three-strategies_ch-1_p-14","order":6,"canonicalText":"兵老，則將威不行。","chunks":[["兵老，則將威不行。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-7","passageId":"three-strategies_ch-1_p-14","order":7,"canonicalText":"將無威，則士卒輕刑。","chunks":[["將無威，則士卒輕刑。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-8","passageId":"three-strategies_ch-1_p-14","order":8,"canonicalText":"士卒輕刑，則軍失伍。","chunks":[["士卒輕刑，則軍失伍。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-9","passageId":"three-strategies_ch-1_p-14","order":9,"canonicalText":"軍失伍，則士卒逃亡。","chunks":[["軍失伍，則士卒逃亡。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-10","passageId":"three-strategies_ch-1_p-14","order":10,"canonicalText":"士卒逃亡，則敵乘利。","chunks":[["士卒逃亡，則敵乘利。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-14_s-11","passageId":"three-strategies_ch-1_p-14","order":11,"canonicalText":"敵乘利，則軍必喪。","chunks":[["敵乘利，則軍必喪。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-1","passageId":"three-strategies_ch-1_p-15","order":1,"canonicalText":"軍讖曰：良將之統軍也，恕己而治人，推惠施恩，士力日新。","chunks":[["軍讖曰：良將之統軍也，恕己而治人，推惠施恩，士力日新。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-2","passageId":"three-strategies_ch-1_p-15","order":2,"canonicalText":"戰如風發，攻如河決，故其眾可望而不可當，可下而不可勝。","chunks":[["戰如風發，攻如河決，故其眾可望而不可當，可下而不可勝。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-3","passageId":"three-strategies_ch-1_p-15","order":3,"canonicalText":"以身先人，故其兵為天下雄。","chunks":[["以身先人，故其兵為天下雄。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-4","passageId":"three-strategies_ch-1_p-15","order":4,"canonicalText":"軍讖曰：軍以賞為表，以罰為裹。","chunks":[["軍讖曰：軍以賞為表，以罰為裹。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-5","passageId":"three-strategies_ch-1_p-15","order":5,"canonicalText":"賞罰明，則將威行。","chunks":[["賞罰明，則將威行。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-6","passageId":"three-strategies_ch-1_p-15","order":6,"canonicalText":"官人得，則士卒服。","chunks":[["官人得，則士卒服。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-15_s-7","passageId":"three-strategies_ch-1_p-15","order":7,"canonicalText":"所任賢，則敵國畏。","chunks":[["所任賢，則敵國畏。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-1","passageId":"three-strategies_ch-1_p-16","order":1,"canonicalText":"軍讖曰：賢者所適，其前無敵。","chunks":[["軍讖曰：賢者所適，其前無敵。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-2","passageId":"three-strategies_ch-1_p-16","order":2,"canonicalText":"故士可下而不可驕，將可樂而不可憂，謀可深而不可疑。","chunks":[["故士可下而不可驕，將可樂而不可憂，謀可深而不可疑。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-3","passageId":"three-strategies_ch-1_p-16","order":3,"canonicalText":"士驕，則下不順。","chunks":[["士驕，則下不順。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-4","passageId":"three-strategies_ch-1_p-16","order":4,"canonicalText":"將憂，則內外不相信。","chunks":[["將憂，則內外不相信。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-5","passageId":"three-strategies_ch-1_p-16","order":5,"canonicalText":"謀疑，則敵國奮，以此攻伐，則致亂。","chunks":[["謀疑，則敵國奮，以此攻伐，則致亂。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-16_s-6","passageId":"three-strategies_ch-1_p-16","order":6,"canonicalText":"夫將者，國之命也，將能制勝，則國家安定。","chunks":[["夫將者，國之命也，將能制勝，則國家安定。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-1","passageId":"three-strategies_ch-1_p-17","order":1,"canonicalText":"軍讖曰：將能清，能靜，能平，能整，能受諫，能聽訟，能納人，能採言，能知國俗，能圖山川，能表險難，能制軍權。","chunks":[["軍讖曰：將能清，能靜，能平，能整，能受諫，能聽訟，能納人，能採言，能知國俗，能圖山川，能表險難，能制軍權。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-2","passageId":"three-strategies_ch-1_p-17","order":2,"canonicalText":"故曰：仁賢之智，聖明之慮，負薪之言，廊廟之語，興衰之事，將所宜聞。","chunks":[["故曰：仁賢之智，聖明之慮，負薪之言，廊廟之語，興衰之事，將所宜聞。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-3","passageId":"three-strategies_ch-1_p-17","order":3,"canonicalText":"將者，能思士如渴，則策從焉。","chunks":[["將者，能思士如渴，則策從焉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-4","passageId":"three-strategies_ch-1_p-17","order":4,"canonicalText":"夫將拒諫，則英雄散，策不從，則謀士叛。","chunks":[["夫將拒諫，則英雄散，策不從，則謀士叛。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-5","passageId":"three-strategies_ch-1_p-17","order":5,"canonicalText":"善惡同，則功臣倦。","chunks":[["善惡同，則功臣倦。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-6","passageId":"three-strategies_ch-1_p-17","order":6,"canonicalText":"專己，則下歸咎。","chunks":[["專己，則下歸咎。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-7","passageId":"three-strategies_ch-1_p-17","order":7,"canonicalText":"自伐，則下少功。","chunks":[["自伐，則下少功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-8","passageId":"three-strategies_ch-1_p-17","order":8,"canonicalText":"信讒，則眾離心。","chunks":[["信讒，則眾離心。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-9","passageId":"three-strategies_ch-1_p-17","order":9,"canonicalText":"貪財，則奸不禁。","chunks":[["貪財，則奸不禁。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-10","passageId":"three-strategies_ch-1_p-17","order":10,"canonicalText":"內顧，則士卒淫。","chunks":[["內顧，則士卒淫。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-11","passageId":"three-strategies_ch-1_p-17","order":11,"canonicalText":"將有一，則眾不服。","chunks":[["將有一，則眾不服。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-12","passageId":"three-strategies_ch-1_p-17","order":12,"canonicalText":"有二，則軍無式。","chunks":[["有二，則軍無式。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-13","passageId":"three-strategies_ch-1_p-17","order":13,"canonicalText":"有三，則下奔北。","chunks":[["有三，則下奔北。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-17_s-14","passageId":"three-strategies_ch-1_p-17","order":14,"canonicalText":"有四，則禍及國。","chunks":[["有四，則禍及國。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-1","passageId":"three-strategies_ch-1_p-18","order":1,"canonicalText":"軍讖曰；","chunks":[["軍讖曰；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-2","passageId":"three-strategies_ch-1_p-18","order":2,"canonicalText":"將謀欲密，士眾欲一，攻敵欲疾。","chunks":[["將謀欲密，士眾欲一，攻敵欲疾。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-3","passageId":"three-strategies_ch-1_p-18","order":3,"canonicalText":"將謀密，則姦心閉。","chunks":[["將謀密，則姦心閉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-4","passageId":"three-strategies_ch-1_p-18","order":4,"canonicalText":"士眾一，則軍心結。","chunks":[["士眾一，則軍心結。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-5","passageId":"three-strategies_ch-1_p-18","order":5,"canonicalText":"攻敵疾，則備不及設。","chunks":[["攻敵疾，則備不及設。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-6","passageId":"three-strategies_ch-1_p-18","order":6,"canonicalText":"軍有此三者，則計不奪。","chunks":[["軍有此三者，則計不奪。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-7","passageId":"three-strategies_ch-1_p-18","order":7,"canonicalText":"將謀泄，則軍無勢。","chunks":[["將謀泄，則軍無勢。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-8","passageId":"three-strategies_ch-1_p-18","order":8,"canonicalText":"外窺內，則禍不制。","chunks":[["外窺內，則禍不制。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-9","passageId":"three-strategies_ch-1_p-18","order":9,"canonicalText":"財入營，則眾奸會。","chunks":[["財入營，則眾奸會。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-10","passageId":"three-strategies_ch-1_p-18","order":10,"canonicalText":"將有此三者，軍必敗。","chunks":[["將有此三者，軍必敗。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-11","passageId":"three-strategies_ch-1_p-18","order":11,"canonicalText":"將無慮，則謀士去。","chunks":[["將無慮，則謀士去。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-12","passageId":"three-strategies_ch-1_p-18","order":12,"canonicalText":"將無勇，則士卒恐。","chunks":[["將無勇，則士卒恐。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-18_s-13","passageId":"three-strategies_ch-1_p-18","order":13,"canonicalText":"將妄動，則軍不重，將遷怒，則一軍懼。","chunks":[["將妄動，則軍不重，將遷怒，則一軍懼。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-19_s-1","passageId":"three-strategies_ch-1_p-19","order":1,"canonicalText":"軍讖曰：慮也，勇也，將之所重。","chunks":[["軍讖曰：慮也，勇也，將之所重。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-19_s-2","passageId":"three-strategies_ch-1_p-19","order":2,"canonicalText":"動也，怒也，將之所用。","chunks":[["動也，怒也，將之所用。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-19_s-3","passageId":"three-strategies_ch-1_p-19","order":3,"canonicalText":"此四者，將之盯誡也。","chunks":[["此四者，將之盯誡也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-20_s-1","passageId":"three-strategies_ch-1_p-20","order":1,"canonicalText":"軍讖曰：軍無財，士不來。","chunks":[["軍讖曰：軍無財，士不來。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-20_s-2","passageId":"three-strategies_ch-1_p-20","order":2,"canonicalText":"軍無賞；","chunks":[["軍無賞；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-20_s-3","passageId":"three-strategies_ch-1_p-20","order":3,"canonicalText":"士不往。","chunks":[["士不往。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-21_s-1","passageId":"three-strategies_ch-1_p-21","order":1,"canonicalText":"軍讖曰：香餌之下，必有死魚。","chunks":[["軍讖曰：香餌之下，必有死魚。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-21_s-2","passageId":"three-strategies_ch-1_p-21","order":2,"canonicalText":"重賞之下，必有勇夫。","chunks":[["重賞之下，必有勇夫。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-21_s-3","passageId":"three-strategies_ch-1_p-21","order":3,"canonicalText":"故禮者，士之所歸，賞者，士之所死，招其所歸，示其所死，則所求者至。","chunks":[["故禮者，士之所歸，賞者，士之所死，招其所歸，示其所死，則所求者至。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-21_s-4","passageId":"three-strategies_ch-1_p-21","order":4,"canonicalText":"故禮而後悔者，士不止，賞而後悔者，士不使。","chunks":[["故禮而後悔者，士不止，賞而後悔者，士不使。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-21_s-5","passageId":"three-strategies_ch-1_p-21","order":5,"canonicalText":"禮賞不倦，則士爭死。","chunks":[["禮賞不倦，則士爭死。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-22_s-1","passageId":"three-strategies_ch-1_p-22","order":1,"canonicalText":"軍讖曰：興師之國，務先隆恩。","chunks":[["軍讖曰：興師之國，務先隆恩。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-22_s-2","passageId":"three-strategies_ch-1_p-22","order":2,"canonicalText":"攻取之國，務先養民。","chunks":[["攻取之國，務先養民。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-22_s-3","passageId":"three-strategies_ch-1_p-22","order":3,"canonicalText":"以寡勝眾者，恩也。","chunks":[["以寡勝眾者，恩也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-22_s-4","passageId":"three-strategies_ch-1_p-22","order":4,"canonicalText":"以弱勝強者，民也。","chunks":[["以弱勝強者，民也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-22_s-5","passageId":"three-strategies_ch-1_p-22","order":5,"canonicalText":"故良將之養士，不易于身，故能使三軍如一心，則其勝可全。","chunks":[["故良將之養士，不易于身，故能使三軍如一心，則其勝可全。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-1","passageId":"three-strategies_ch-1_p-23","order":1,"canonicalText":"軍讖曰：用兵之要，必先察敵情，視其倉庫，度其糧食，卜其強弱，察其天地，伺其空隙。","chunks":[["軍讖曰：用兵之要，必先察敵情，視其倉庫，度其糧食，卜其強弱，察其天地，伺其空隙。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-2","passageId":"three-strategies_ch-1_p-23","order":2,"canonicalText":"故國無軍旅之難，而運糧者，虛也。","chunks":[["故國無軍旅之難，而運糧者，虛也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-3","passageId":"three-strategies_ch-1_p-23","order":3,"canonicalText":"民菜色者，窮也。","chunks":[["民菜色者，窮也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-4","passageId":"three-strategies_ch-1_p-23","order":4,"canonicalText":"千里饋糧，士有飢色。","chunks":[["千里饋糧，士有飢色。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-5","passageId":"three-strategies_ch-1_p-23","order":5,"canonicalText":"樵蘇後爨，師不宿飽。","chunks":[["樵蘇後爨，師不宿飽。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-6","passageId":"three-strategies_ch-1_p-23","order":6,"canonicalText":"夫運糧千里，無一年之食，二千里，無二年之食，三千里，無三年之食，是謂國虛。","chunks":[["夫運糧千里，無一年之食，二千里，無二年之食，三千里，無三年之食，是謂國虛。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-7","passageId":"three-strategies_ch-1_p-23","order":7,"canonicalText":"國虛，則民貧：民貧，則上下不親。","chunks":[["國虛，則民貧：民貧，則上下不親。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-23_s-8","passageId":"three-strategies_ch-1_p-23","order":8,"canonicalText":"敵攻其外，民盜其內，是謂必潰。","chunks":[["敵攻其外，民盜其內，是謂必潰。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-24_s-1","passageId":"three-strategies_ch-1_p-24","order":1,"canonicalText":"軍讖曰：上行虐，則下急刻。","chunks":[["軍讖曰：上行虐，則下急刻。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-24_s-2","passageId":"three-strategies_ch-1_p-24","order":2,"canonicalText":"賦重斂數，刑罰無極，民相殘賊，是謂亡國。","chunks":[["賦重斂數，刑罰無極，民相殘賊，是謂亡國。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-25_s-1","passageId":"three-strategies_ch-1_p-25","order":1,"canonicalText":"軍讖曰：內貪外廉，詐譽取名，竊公為恩，令上下昏，飾躬正顏，以獲高官，是謂盜端。","chunks":[["軍讖曰：內貪外廉，詐譽取名，竊公為恩，令上下昏，飾躬正顏，以獲高官，是謂盜端。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-26_s-1","passageId":"three-strategies_ch-1_p-26","order":1,"canonicalText":"軍讖曰：群吏朋黨，各進所親。","chunks":[["軍讖曰：群吏朋黨，各進所親。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-26_s-2","passageId":"three-strategies_ch-1_p-26","order":2,"canonicalText":"招舉姦枉，抑挫仁賢，背公立私，同位相訕，是謂亂源。","chunks":[["招舉姦枉，抑挫仁賢，背公立私，同位相訕，是謂亂源。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-27_s-1","passageId":"three-strategies_ch-1_p-27","order":1,"canonicalText":"軍讖曰：強宗聚姦，無位而尊，威而不震，葛藟相連，種德立恩，奪在位權，侵侮下民，國內諠譁，臣蔽不言，是謂亂根。","chunks":[["軍讖曰：強宗聚姦，無位而尊，威而不震，葛藟相連，種德立恩，奪在位權，侵侮下民，國內諠譁，臣蔽不言，是謂亂根。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-28_s-1","passageId":"three-strategies_ch-1_p-28","order":1,"canonicalText":"軍讖曰：世世作姦，侵盜縣官，進退求便，委曲弄文，以危其君，是謂國姦。","chunks":[["軍讖曰：世世作姦，侵盜縣官，進退求便，委曲弄文，以危其君，是謂國姦。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-29_s-1","passageId":"three-strategies_ch-1_p-29","order":1,"canonicalText":"軍讖曰：吏多民寡，尊卑相若，強弱相虜，莫適禁禦，延及君子，國受其咎。","chunks":[["軍讖曰：吏多民寡，尊卑相若，強弱相虜，莫適禁禦，延及君子，國受其咎。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-30_s-1","passageId":"three-strategies_ch-1_p-30","order":1,"canonicalText":"軍讖曰：善善不進，惡惡不退，賢者隱蔽，不肖在位，國受其害。","chunks":[["軍讖曰：善善不進，惡惡不退，賢者隱蔽，不肖在位，國受其害。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-31_s-1","passageId":"three-strategies_ch-1_p-31","order":1,"canonicalText":"軍讖曰：枝葉強大，比周居勢，卑賤陵貴，久而益大，上不忍廢，國受其敗。","chunks":[["軍讖曰：枝葉強大，比周居勢，卑賤陵貴，久而益大，上不忍廢，國受其敗。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-1","passageId":"three-strategies_ch-1_p-32","order":1,"canonicalText":"軍讖曰：佞臣在上，一軍皆訟。","chunks":[["軍讖曰：佞臣在上，一軍皆訟。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-2","passageId":"three-strategies_ch-1_p-32","order":2,"canonicalText":"引威自與，動違于眾。","chunks":[["引威自與，動違于眾。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-3","passageId":"three-strategies_ch-1_p-32","order":3,"canonicalText":"無進無退，苟然取容。","chunks":[["無進無退，苟然取容。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-4","passageId":"three-strategies_ch-1_p-32","order":4,"canonicalText":"專任自己，舉措伐功。","chunks":[["專任自己，舉措伐功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-5","passageId":"three-strategies_ch-1_p-32","order":5,"canonicalText":"誹謗盛德，誣述庸庸。","chunks":[["誹謗盛德，誣述庸庸。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-6","passageId":"three-strategies_ch-1_p-32","order":6,"canonicalText":"無善無惡，皆與己同。","chunks":[["無善無惡，皆與己同。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-7","passageId":"three-strategies_ch-1_p-32","order":7,"canonicalText":"稽留行事，命令不通。","chunks":[["稽留行事，命令不通。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-8","passageId":"three-strategies_ch-1_p-32","order":8,"canonicalText":"造作苛政，變古易常。","chunks":[["造作苛政，變古易常。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-32_s-9","passageId":"three-strategies_ch-1_p-32","order":9,"canonicalText":"君用佞人，必受禍殃。","chunks":[["君用佞人，必受禍殃。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-1","passageId":"three-strategies_ch-1_p-33","order":1,"canonicalText":"軍讖曰：姦雄相稱，障蔽主明。","chunks":[["軍讖曰：姦雄相稱，障蔽主明。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-2","passageId":"three-strategies_ch-1_p-33","order":2,"canonicalText":"毀譽並興，壅塞主聰，各阿所私，令主失忠。","chunks":[["毀譽並興，壅塞主聰，各阿所私，令主失忠。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-3","passageId":"three-strategies_ch-1_p-33","order":3,"canonicalText":"故主察異言，乃觀其萌。","chunks":[["故主察異言，乃觀其萌。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-4","passageId":"three-strategies_ch-1_p-33","order":4,"canonicalText":"主聘儒賢，姦雄乃遯。","chunks":[["主聘儒賢，姦雄乃遯。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-5","passageId":"three-strategies_ch-1_p-33","order":5,"canonicalText":"主任舊齒，萬事乃理。","chunks":[["主任舊齒，萬事乃理。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-6","passageId":"three-strategies_ch-1_p-33","order":6,"canonicalText":"主聘巖穴，士乃得實。","chunks":[["主聘巖穴，士乃得實。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-7","passageId":"three-strategies_ch-1_p-33","order":7,"canonicalText":"謀及負薪，功乃可述。","chunks":[["謀及負薪，功乃可述。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-33_s-8","passageId":"three-strategies_ch-1_p-33","order":8,"canonicalText":"不失人心，德乃洋益。","chunks":[["不失人心，德乃洋益。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-34_s-1","passageId":"three-strategies_ch-1_p-34","order":1,"canonicalText":"夫三皇無言，而化流四海，故天下無所歸功。","chunks":[["夫三皇無言，而化流四海，故天下無所歸功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-34_s-2","passageId":"three-strategies_ch-1_p-34","order":2,"canonicalText":"帝者，體天則地，有言有令，而天下太平：君臣讓功，四海化行，百姓不知其所以然，故使臣不待禮賞，有功美而無害。","chunks":[["帝者，體天則地，有言有令，而天下太平：君臣讓功，四海化行，百姓不知其所以然，故使臣不待禮賞，有功美而無害。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-34_s-3","passageId":"three-strategies_ch-1_p-34","order":3,"canonicalText":"王者，制人以道，降心服志，設矩備衰，四海會同，王職不廢，雖有甲兵之備，而無戰鬥之患；","chunks":[["王者，制人以道，降心服志，設矩備衰，四海會同，王職不廢，雖有甲兵之備，而無戰鬥之患；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-34_s-4","passageId":"three-strategies_ch-1_p-34","order":4,"canonicalText":"君無疑于臣，臣無疑于主，國定民安，臣以義退，亦能美而無害。","chunks":[["君無疑于臣，臣無疑于主，國定民安，臣以義退，亦能美而無害。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-34_s-5","passageId":"three-strategies_ch-1_p-34","order":5,"canonicalText":"霸者，制士以權，結士以信，使士以賞：信衰則士疏，賞虧則士不用命。","chunks":[["霸者，制士以權，結士以信，使士以賞：信衰則士疏，賞虧則士不用命。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-35_s-1","passageId":"three-strategies_ch-1_p-35","order":1,"canonicalText":"軍勢曰：出軍行師，將在自專。","chunks":[["軍勢曰：出軍行師，將在自專。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-35_s-2","passageId":"three-strategies_ch-1_p-35","order":2,"canonicalText":"進退內御，則功難成。","chunks":[["進退內御，則功難成。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-1","passageId":"three-strategies_ch-1_p-36","order":1,"canonicalText":"軍勢曰：使智，使勇，使貪，使愚。","chunks":[["軍勢曰：使智，使勇，使貪，使愚。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-2","passageId":"three-strategies_ch-1_p-36","order":2,"canonicalText":"智者，樂立其功。","chunks":[["智者，樂立其功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-3","passageId":"three-strategies_ch-1_p-36","order":3,"canonicalText":"勇者，好行其志。","chunks":[["勇者，好行其志。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-4","passageId":"three-strategies_ch-1_p-36","order":4,"canonicalText":"貪者，邀趨其利。","chunks":[["貪者，邀趨其利。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-5","passageId":"three-strategies_ch-1_p-36","order":5,"canonicalText":"愚者，不顧其死。","chunks":[["愚者，不顧其死。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-36_s-6","passageId":"three-strategies_ch-1_p-36","order":6,"canonicalText":"因其至情而用之，此軍之微權也。","chunks":[["因其至情而用之，此軍之微權也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-37_s-1","passageId":"three-strategies_ch-1_p-37","order":1,"canonicalText":"軍勢曰：無使辯士談說敵美，為其惑眾。","chunks":[["軍勢曰：無使辯士談說敵美，為其惑眾。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-37_s-2","passageId":"three-strategies_ch-1_p-37","order":2,"canonicalText":"勿使仁者主財，為其多施而附于下。","chunks":[["勿使仁者主財，為其多施而附于下。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-38_s-1","passageId":"three-strategies_ch-1_p-38","order":1,"canonicalText":"軍勢曰：禁巫祝，不得為吏士卜問軍之吉凶。","chunks":[["軍勢曰：禁巫祝，不得為吏士卜問軍之吉凶。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-39_s-1","passageId":"three-strategies_ch-1_p-39","order":1,"canonicalText":"軍勢曰：使義士，不以財。","chunks":[["軍勢曰：使義士，不以財。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-39_s-2","passageId":"three-strategies_ch-1_p-39","order":2,"canonicalText":"故義者，不為不仁者死。","chunks":[["故義者，不為不仁者死。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-39_s-3","passageId":"three-strategies_ch-1_p-39","order":3,"canonicalText":"智者，不為闇主謀。","chunks":[["智者，不為闇主謀。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-40_s-1","passageId":"three-strategies_ch-1_p-40","order":1,"canonicalText":"主不可以無德，無德則臣叛：不可以無威，無威則失權。","chunks":[["主不可以無德，無德則臣叛：不可以無威，無威則失權。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-40_s-2","passageId":"three-strategies_ch-1_p-40","order":2,"canonicalText":"臣不可以無德，無德則無以事君：不可以無威，無威則國弱，威多則身蹶。","chunks":[["臣不可以無德，無德則無以事君：不可以無威，無威則國弱，威多則身蹶。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-41_s-1","passageId":"three-strategies_ch-1_p-41","order":1,"canonicalText":"故聖王御世，觀盛衰，度得失，而為之制。","chunks":[["故聖王御世，觀盛衰，度得失，而為之制。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-41_s-2","passageId":"three-strategies_ch-1_p-41","order":2,"canonicalText":"故諸侯二師，方伯三師，天子六師。","chunks":[["故諸侯二師，方伯三師，天子六師。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-41_s-3","passageId":"three-strategies_ch-1_p-41","order":3,"canonicalText":"世亂則叛逆生，王澤竭則盟誓相誅伐。","chunks":[["世亂則叛逆生，王澤竭則盟誓相誅伐。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-42_s-1","passageId":"three-strategies_ch-1_p-42","order":1,"canonicalText":"德同勢敵，無以相傾，乃攬英雄之心，與眾同好惡，然後加之以權變。","chunks":[["德同勢敵，無以相傾，乃攬英雄之心，與眾同好惡，然後加之以權變。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-42_s-2","passageId":"three-strategies_ch-1_p-42","order":2,"canonicalText":"故非計策，無以決嫌定疑。","chunks":[["故非計策，無以決嫌定疑。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-42_s-3","passageId":"three-strategies_ch-1_p-42","order":3,"canonicalText":"非譎奇無以破姦息寇，非陰謀無以成功。","chunks":[["非譎奇無以破姦息寇，非陰謀無以成功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-1","passageId":"three-strategies_ch-1_p-43","order":1,"canonicalText":"聖人體天，賢人法地，智者師古。","chunks":[["聖人體天，賢人法地，智者師古。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-2","passageId":"three-strategies_ch-1_p-43","order":2,"canonicalText":"是故三略為衰世作：上略設禮賞，別姦雄，著成敗。","chunks":[["是故三略為衰世作：上略設禮賞，別姦雄，著成敗。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-3","passageId":"three-strategies_ch-1_p-43","order":3,"canonicalText":"中略差德行，審權變。","chunks":[["中略差德行，審權變。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-4","passageId":"three-strategies_ch-1_p-43","order":4,"canonicalText":"下略陳道德，察安危，明賊賢之咎。","chunks":[["下略陳道德，察安危，明賊賢之咎。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-5","passageId":"three-strategies_ch-1_p-43","order":5,"canonicalText":"故人主深曉上略，則能任賢擒敵。","chunks":[["故人主深曉上略，則能任賢擒敵。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-6","passageId":"three-strategies_ch-1_p-43","order":6,"canonicalText":"深曉中略，則能御將統眾。","chunks":[["深曉中略，則能御將統眾。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-43_s-7","passageId":"three-strategies_ch-1_p-43","order":7,"canonicalText":"深曉下略，則能明盛衰之源，審治國之紀。","chunks":[["深曉下略，則能明盛衰之源，審治國之紀。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-1","passageId":"three-strategies_ch-1_p-44","order":1,"canonicalText":"人臣深曉中略，則能全功保身。","chunks":[["人臣深曉中略，則能全功保身。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-2","passageId":"three-strategies_ch-1_p-44","order":2,"canonicalText":"夫高鳥死，良弓藏，敵國滅，謀臣亡。","chunks":[["夫高鳥死，良弓藏，敵國滅，謀臣亡。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-3","passageId":"three-strategies_ch-1_p-44","order":3,"canonicalText":"亡者，非喪其身也。","chunks":[["亡者，非喪其身也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-4","passageId":"three-strategies_ch-1_p-44","order":4,"canonicalText":"謂奪其威，廢其權也。","chunks":[["謂奪其威，廢其權也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-5","passageId":"three-strategies_ch-1_p-44","order":5,"canonicalText":"封之于朝，極人臣之位，以顯其功。","chunks":[["封之于朝，極人臣之位，以顯其功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-44_s-6","passageId":"three-strategies_ch-1_p-44","order":6,"canonicalText":"中州善國，以富其家，美色珍玩，以悅其心。","chunks":[["中州善國，以富其家，美色珍玩，以悅其心。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-45_s-1","passageId":"three-strategies_ch-1_p-45","order":1,"canonicalText":"夫人眾一合而不可卒離。","chunks":[["夫人眾一合而不可卒離。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-45_s-2","passageId":"three-strategies_ch-1_p-45","order":2,"canonicalText":"權威一與而不可卒移。","chunks":[["權威一與而不可卒移。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-45_s-3","passageId":"three-strategies_ch-1_p-45","order":3,"canonicalText":"還師罷軍，存亡之階。","chunks":[["還師罷軍，存亡之階。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-45_s-4","passageId":"three-strategies_ch-1_p-45","order":4,"canonicalText":"故弱之以位，奪之以國，是謂霸者之略，故霸者之作，其論駁也。","chunks":[["故弱之以位，奪之以國，是謂霸者之略，故霸者之作，其論駁也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-46_s-1","passageId":"three-strategies_ch-1_p-46","order":1,"canonicalText":"存社稷，羅英雄者，中略之勢也，故勢秘焉。","chunks":[["存社稷，羅英雄者，中略之勢也，故勢秘焉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-1","passageId":"three-strategies_ch-1_p-47","order":1,"canonicalText":"夫能扶天下之危者，則據天下之安。","chunks":[["夫能扶天下之危者，則據天下之安。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-2","passageId":"three-strategies_ch-1_p-47","order":2,"canonicalText":"能除天下之憂者，則享天下之樂。","chunks":[["能除天下之憂者，則享天下之樂。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-3","passageId":"three-strategies_ch-1_p-47","order":3,"canonicalText":"能救天下之禍者，則獲天下之福。","chunks":[["能救天下之禍者，則獲天下之福。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-4","passageId":"three-strategies_ch-1_p-47","order":4,"canonicalText":"故澤及于民，則賢人歸之。","chunks":[["故澤及于民，則賢人歸之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-5","passageId":"three-strategies_ch-1_p-47","order":5,"canonicalText":"澤及昆蟲，則聖人歸之。","chunks":[["澤及昆蟲，則聖人歸之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-6","passageId":"three-strategies_ch-1_p-47","order":6,"canonicalText":"賢人所歸，則其國強。","chunks":[["賢人所歸，則其國強。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-7","passageId":"three-strategies_ch-1_p-47","order":7,"canonicalText":"聖人所歸，則六合同。","chunks":[["聖人所歸，則六合同。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-8","passageId":"three-strategies_ch-1_p-47","order":8,"canonicalText":"求賢以德、致聖以道。","chunks":[["求賢以德、致聖以道。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-9","passageId":"three-strategies_ch-1_p-47","order":9,"canonicalText":"賢去則國微，聖去則國乖。","chunks":[["賢去則國微，聖去則國乖。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-47_s-10","passageId":"three-strategies_ch-1_p-47","order":10,"canonicalText":"微者危之階，乖者亡之徵。","chunks":[["微者危之階，乖者亡之徵。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-1","passageId":"three-strategies_ch-1_p-48","order":1,"canonicalText":"賢人之政，降人以體，聖人之政，降人以心。","chunks":[["賢人之政，降人以體，聖人之政，降人以心。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-2","passageId":"three-strategies_ch-1_p-48","order":2,"canonicalText":"體降可以圖始，心降可以保終。","chunks":[["體降可以圖始，心降可以保終。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-3","passageId":"three-strategies_ch-1_p-48","order":3,"canonicalText":"降體以禮，降心以樂。","chunks":[["降體以禮，降心以樂。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-4","passageId":"three-strategies_ch-1_p-48","order":4,"canonicalText":"所謂樂者，非金，石，絲，竹也，謂人樂其家，謂人樂其俗，謂人樂其業，謂人樂其都邑，謂人樂其政令，謂人樂其道德；","chunks":[["所謂樂者，非金，石，絲，竹也，謂人樂其家，謂人樂其俗，謂人樂其業，謂人樂其都邑，謂人樂其政令，謂人樂其道德；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-5","passageId":"three-strategies_ch-1_p-48","order":5,"canonicalText":"加此君人者，乃作樂以節之，使不失其和。","chunks":[["加此君人者，乃作樂以節之，使不失其和。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-6","passageId":"three-strategies_ch-1_p-48","order":6,"canonicalText":"故有德之君，以樂樂人，無德之君，以樂樂身。","chunks":[["故有德之君，以樂樂人，無德之君，以樂樂身。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-48_s-7","passageId":"three-strategies_ch-1_p-48","order":7,"canonicalText":"樂人者，久而長，樂身者不久而亡。","chunks":[["樂人者，久而長，樂身者不久而亡。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-1","passageId":"three-strategies_ch-1_p-49","order":1,"canonicalText":"釋近謀近者，勞而無功。","chunks":[["釋近謀近者，勞而無功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-2","passageId":"three-strategies_ch-1_p-49","order":2,"canonicalText":"釋遠謀者，佚而有終。","chunks":[["釋遠謀者，佚而有終。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-3","passageId":"three-strategies_ch-1_p-49","order":3,"canonicalText":"佚政多忠臣，勞政多怨民。","chunks":[["佚政多忠臣，勞政多怨民。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-4","passageId":"three-strategies_ch-1_p-49","order":4,"canonicalText":"故曰；","chunks":[["故曰；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-5","passageId":"three-strategies_ch-1_p-49","order":5,"canonicalText":"務廣地者荒，務廣德者強。","chunks":[["務廣地者荒，務廣德者強。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-6","passageId":"three-strategies_ch-1_p-49","order":6,"canonicalText":"能有其有者安，貪人之有者殘。","chunks":[["能有其有者安，貪人之有者殘。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-7","passageId":"three-strategies_ch-1_p-49","order":7,"canonicalText":"殘滅之政，累世受患。","chunks":[["殘滅之政，累世受患。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-49_s-8","passageId":"three-strategies_ch-1_p-49","order":8,"canonicalText":"造作過制，雖成必敗。","chunks":[["造作過制，雖成必敗。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-1","passageId":"three-strategies_ch-1_p-50","order":1,"canonicalText":"舍己而教人者逆，正己而化人者順。","chunks":[["舍己而教人者逆，正己而化人者順。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-2","passageId":"three-strategies_ch-1_p-50","order":2,"canonicalText":"逆者亂之招，順者治之要。","chunks":[["逆者亂之招，順者治之要。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-3","passageId":"three-strategies_ch-1_p-50","order":3,"canonicalText":"道、德、仁、義、禮五者，一體也。","chunks":[["道、德、仁、義、禮五者，一體也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-4","passageId":"three-strategies_ch-1_p-50","order":4,"canonicalText":"道者人之所蹈，德者人之所得，仁者人之所親，義者人之所宜，禮者人之所體，不可無一焉。","chunks":[["道者人之所蹈，德者人之所得，仁者人之所親，義者人之所宜，禮者人之所體，不可無一焉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-5","passageId":"three-strategies_ch-1_p-50","order":5,"canonicalText":"故夙興夜寐，禮之制也。","chunks":[["故夙興夜寐，禮之制也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-6","passageId":"three-strategies_ch-1_p-50","order":6,"canonicalText":"討賊報讎，義之決也。","chunks":[["討賊報讎，義之決也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-7","passageId":"three-strategies_ch-1_p-50","order":7,"canonicalText":"惻隱之心，仁之發也。","chunks":[["惻隱之心，仁之發也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-8","passageId":"three-strategies_ch-1_p-50","order":8,"canonicalText":"得己，得人，德之路也。","chunks":[["得己，得人，德之路也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-50_s-9","passageId":"three-strategies_ch-1_p-50","order":9,"canonicalText":"使人均平，不失其所，道之化也。","chunks":[["使人均平，不失其所，道之化也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-1","passageId":"three-strategies_ch-1_p-51","order":1,"canonicalText":"出君下臣，名曰命。","chunks":[["出君下臣，名曰命。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-2","passageId":"three-strategies_ch-1_p-51","order":2,"canonicalText":"施于竹帛，名曰令。","chunks":[["施于竹帛，名曰令。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-3","passageId":"three-strategies_ch-1_p-51","order":3,"canonicalText":"奉而行之，名曰政。","chunks":[["奉而行之，名曰政。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-4","passageId":"three-strategies_ch-1_p-51","order":4,"canonicalText":"夫命失，則令不行，令不行，則政不立。","chunks":[["夫命失，則令不行，令不行，則政不立。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-5","passageId":"three-strategies_ch-1_p-51","order":5,"canonicalText":"政不立，則道不通。","chunks":[["政不立，則道不通。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-51_s-6","passageId":"three-strategies_ch-1_p-51","order":6,"canonicalText":"道不通，則邪臣勝，邪臣勝，則主威傷。","chunks":[["道不通，則邪臣勝，邪臣勝，則主威傷。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-52_s-1","passageId":"three-strategies_ch-1_p-52","order":1,"canonicalText":"千里迎賢其路遠，致不肖其路近。","chunks":[["千里迎賢其路遠，致不肖其路近。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-52_s-2","passageId":"three-strategies_ch-1_p-52","order":2,"canonicalText":"是以明君舍近而收遠，故能全功尚人，而下盡力。","chunks":[["是以明君舍近而收遠，故能全功尚人，而下盡力。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-53_s-1","passageId":"three-strategies_ch-1_p-53","order":1,"canonicalText":"廢一善則眾善衰，賞一惡則眾惡掃。","chunks":[["廢一善則眾善衰，賞一惡則眾惡掃。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-53_s-2","passageId":"three-strategies_ch-1_p-53","order":2,"canonicalText":"善者得其佑，惡者受其誅，則國安而眾善至。","chunks":[["善者得其佑，惡者受其誅，則國安而眾善至。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-53_s-3","passageId":"three-strategies_ch-1_p-53","order":3,"canonicalText":"眾疑無定國，眾惑無治民，疑定惑還，國乃可安。","chunks":[["眾疑無定國，眾惑無治民，疑定惑還，國乃可安。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-53_s-4","passageId":"three-strategies_ch-1_p-53","order":4,"canonicalText":"一令逆則百令失，一惡失則百惡結。","chunks":[["一令逆則百令失，一惡失則百惡結。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-53_s-5","passageId":"three-strategies_ch-1_p-53","order":5,"canonicalText":"故善施于順民，惡加于凶，則令行而無怨。","chunks":[["故善施于順民，惡加于凶，則令行而無怨。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-54_s-1","passageId":"three-strategies_ch-1_p-54","order":1,"canonicalText":"使怨治怨，是謂逆天。","chunks":[["使怨治怨，是謂逆天。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-54_s-2","passageId":"three-strategies_ch-1_p-54","order":2,"canonicalText":"使讎治讎，其禍不救。","chunks":[["使讎治讎，其禍不救。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-54_s-3","passageId":"three-strategies_ch-1_p-54","order":3,"canonicalText":"治民使平，致平以清。","chunks":[["治民使平，致平以清。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-54_s-4","passageId":"three-strategies_ch-1_p-54","order":4,"canonicalText":"則民得其所，而天下寧。","chunks":[["則民得其所，而天下寧。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-55_s-1","passageId":"three-strategies_ch-1_p-55","order":1,"canonicalText":"犯上者尊，貪鄙者富，雖有聖主，不能致其治。","chunks":[["犯上者尊，貪鄙者富，雖有聖主，不能致其治。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-55_s-2","passageId":"three-strategies_ch-1_p-55","order":2,"canonicalText":"犯上者誅，貪鄙者拘，則化行而眾惡消。","chunks":[["犯上者誅，貪鄙者拘，則化行而眾惡消。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-1","passageId":"three-strategies_ch-1_p-56","order":1,"canonicalText":"清白之士，不可以爵祿得。","chunks":[["清白之士，不可以爵祿得。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-2","passageId":"three-strategies_ch-1_p-56","order":2,"canonicalText":"節義之士，不可以威刑脅。","chunks":[["節義之士，不可以威刑脅。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-3","passageId":"three-strategies_ch-1_p-56","order":3,"canonicalText":"故明君求賢，必觀其所以而致焉。","chunks":[["故明君求賢，必觀其所以而致焉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-4","passageId":"three-strategies_ch-1_p-56","order":4,"canonicalText":"致清白之士，修其禮；","chunks":[["致清白之士，修其禮；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-5","passageId":"three-strategies_ch-1_p-56","order":5,"canonicalText":"致節義之士，修其道。","chunks":[["致節義之士，修其道。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-56_s-6","passageId":"three-strategies_ch-1_p-56","order":6,"canonicalText":"然後士可致，而名可保。","chunks":[["然後士可致，而名可保。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-57_s-1","passageId":"three-strategies_ch-1_p-57","order":1,"canonicalText":"夫聖人君子，明盛衰之源，通成敗之端，審治亂之機，知去就之節。","chunks":[["夫聖人君子，明盛衰之源，通成敗之端，審治亂之機，知去就之節。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-58_s-1","passageId":"three-strategies_ch-1_p-58","order":1,"canonicalText":"雖窮不處亡國之位，雖貧不食亂邦之祿。","chunks":[["雖窮不處亡國之位，雖貧不食亂邦之祿。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-58_s-2","passageId":"three-strategies_ch-1_p-58","order":2,"canonicalText":"潛名抱道者，時至而動，則極人臣之位。","chunks":[["潛名抱道者，時至而動，則極人臣之位。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-58_s-3","passageId":"three-strategies_ch-1_p-58","order":3,"canonicalText":"德合于己，則建殊絕之功。","chunks":[["德合于己，則建殊絕之功。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-58_s-4","passageId":"three-strategies_ch-1_p-58","order":4,"canonicalText":"故其道高而名揚于後世。","chunks":[["故其道高而名揚于後世。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-1","passageId":"three-strategies_ch-1_p-59","order":1,"canonicalText":"聖王之用兵，非樂之也；","chunks":[["聖王之用兵，非樂之也；","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-2","passageId":"three-strategies_ch-1_p-59","order":2,"canonicalText":"將以誅暴討亂也。","chunks":[["將以誅暴討亂也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-3","passageId":"three-strategies_ch-1_p-59","order":3,"canonicalText":"夫以義誅不義，若決江河而溉爝火，臨不測而擠欲墜，其克必矣。","chunks":[["夫以義誅不義，若決江河而溉爝火，臨不測而擠欲墜，其克必矣。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-4","passageId":"three-strategies_ch-1_p-59","order":4,"canonicalText":"所以優游恬淡而不進者，重傷人物也。","chunks":[["所以優游恬淡而不進者，重傷人物也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-5","passageId":"three-strategies_ch-1_p-59","order":5,"canonicalText":"夫兵者，不祥之器，天道惡之，不得已而用之。","chunks":[["夫兵者，不祥之器，天道惡之，不得已而用之。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-59_s-6","passageId":"three-strategies_ch-1_p-59","order":6,"canonicalText":"是天道也。","chunks":[["是天道也。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-60_s-1","passageId":"three-strategies_ch-1_p-60","order":1,"canonicalText":"夫人之在道，若魚之在水，得水而生，失水而死，故君子常懼而不敢失道。","chunks":[["夫人之在道，若魚之在水，得水而生，失水而死，故君子常懼而不敢失道。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-61_s-1","passageId":"three-strategies_ch-1_p-61","order":1,"canonicalText":"豪傑秉職，國威乃弱，殺生在豪傑，國勢乃竭。","chunks":[["豪傑秉職，國威乃弱，殺生在豪傑，國勢乃竭。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-61_s-2","passageId":"three-strategies_ch-1_p-61","order":2,"canonicalText":"豪傑低首，國乃可久。","chunks":[["豪傑低首，國乃可久。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-61_s-3","passageId":"three-strategies_ch-1_p-61","order":3,"canonicalText":"殺生在君，國乃可安。","chunks":[["殺生在君，國乃可安。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-61_s-4","passageId":"three-strategies_ch-1_p-61","order":4,"canonicalText":"四民用虛，國乃無儲。","chunks":[["四民用虛，國乃無儲。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-61_s-5","passageId":"three-strategies_ch-1_p-61","order":5,"canonicalText":"四民用足，國乃安樂。","chunks":[["四民用足，國乃安樂。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-62_s-1","passageId":"three-strategies_ch-1_p-62","order":1,"canonicalText":"賢臣內，則邪臣外。","chunks":[["賢臣內，則邪臣外。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-62_s-2","passageId":"three-strategies_ch-1_p-62","order":2,"canonicalText":"邪臣內，則賢臣斃。","chunks":[["邪臣內，則賢臣斃。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-62_s-3","passageId":"three-strategies_ch-1_p-62","order":3,"canonicalText":"內外失宜，禍亂傳世。","chunks":[["內外失宜，禍亂傳世。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-63_s-1","passageId":"three-strategies_ch-1_p-63","order":1,"canonicalText":"大臣疑主，眾姦集聚。","chunks":[["大臣疑主，眾姦集聚。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-63_s-2","passageId":"three-strategies_ch-1_p-63","order":2,"canonicalText":"臣當君尊，上下乃昏。","chunks":[["臣當君尊，上下乃昏。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-63_s-3","passageId":"three-strategies_ch-1_p-63","order":3,"canonicalText":"君當臣處，上下失序。","chunks":[["君當臣處，上下失序。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-64_s-1","passageId":"three-strategies_ch-1_p-64","order":1,"canonicalText":"傷賢者，殃及三世。","chunks":[["傷賢者，殃及三世。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-64_s-2","passageId":"three-strategies_ch-1_p-64","order":2,"canonicalText":"蔽賢者，身受其害。","chunks":[["蔽賢者，身受其害。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-64_s-3","passageId":"three-strategies_ch-1_p-64","order":3,"canonicalText":"嫉賢者，其名不全。","chunks":[["嫉賢者，其名不全。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-64_s-4","passageId":"three-strategies_ch-1_p-64","order":4,"canonicalText":"進賢者，福流子孫。","chunks":[["進賢者，福流子孫。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-64_s-5","passageId":"three-strategies_ch-1_p-64","order":5,"canonicalText":"故君子急于進賢，而美名彰焉。","chunks":[["故君子急于進賢，而美名彰焉。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-65_s-1","passageId":"three-strategies_ch-1_p-65","order":1,"canonicalText":"利一害百，民去城郭。","chunks":[["利一害百，民去城郭。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-65_s-2","passageId":"three-strategies_ch-1_p-65","order":2,"canonicalText":"利一害萬，國乃思散。","chunks":[["利一害萬，國乃思散。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-65_s-3","passageId":"three-strategies_ch-1_p-65","order":3,"canonicalText":"去一利百，人乃慕澤。","chunks":[["去一利百，人乃慕澤。","zh-Hant"]]},{"id":"three-strategies_ch-1_p-65_s-4","passageId":"three-strategies_ch-1_p-65","order":4,"canonicalText":"去一利萬，政乃不亂。","chunks":[["去一利萬，政乃不亂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-1_s-1","passageId":"li-ji_ch-1_p-1","order":1,"canonicalText":"《曲禮》曰：「毋不敬，儼若思，安定辭。","chunks":[["《曲禮》曰：「毋不敬，儼若思，安定辭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-1_s-2","passageId":"li-ji_ch-1_p-1","order":2,"canonicalText":"」安民哉！","chunks":[["」安民哉！","zh-Hant"]]},{"id":"li-ji_ch-1_p-2_s-1","passageId":"li-ji_ch-1_p-2","order":1,"canonicalText":"敖不可長，欲不可從，志不可滿，樂不可極。","chunks":[["敖不可長，欲不可從，志不可滿，樂不可極。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-1","passageId":"li-ji_ch-1_p-3","order":1,"canonicalText":"賢者狎而敬之，畏而愛之。","chunks":[["賢者狎而敬之，畏而愛之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-2","passageId":"li-ji_ch-1_p-3","order":2,"canonicalText":"愛而知其惡，憎而知其善。","chunks":[["愛而知其惡，憎而知其善。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-3","passageId":"li-ji_ch-1_p-3","order":3,"canonicalText":"積而能散，安安而能遷。","chunks":[["積而能散，安安而能遷。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-4","passageId":"li-ji_ch-1_p-3","order":4,"canonicalText":"臨財毋茍得，臨難毋茍免。","chunks":[["臨財毋茍得，臨難毋茍免。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-5","passageId":"li-ji_ch-1_p-3","order":5,"canonicalText":"很毋求勝，分毋求多。","chunks":[["很毋求勝，分毋求多。","zh-Hant"]]},{"id":"li-ji_ch-1_p-3_s-6","passageId":"li-ji_ch-1_p-3","order":6,"canonicalText":"疑事毋質，直而勿有。","chunks":[["疑事毋質，直而勿有。","zh-Hant"]]},{"id":"li-ji_ch-1_p-4_s-1","passageId":"li-ji_ch-1_p-4","order":1,"canonicalText":"若夫，坐如尸，立如齊。","chunks":[["若夫，坐如尸，立如齊。","zh-Hant"]]},{"id":"li-ji_ch-1_p-5_s-1","passageId":"li-ji_ch-1_p-5","order":1,"canonicalText":"禮從宜，使從俗。","chunks":[["禮從宜，使從俗。","zh-Hant"]]},{"id":"li-ji_ch-1_p-6_s-1","passageId":"li-ji_ch-1_p-6","order":1,"canonicalText":"夫禮者所以定親疏，決嫌疑，別同異，明是非也。","chunks":[["夫禮者所以定親疏，決嫌疑，別同異，明是非也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-1","passageId":"li-ji_ch-1_p-7","order":1,"canonicalText":"禮，不妄說人，不辭費。","chunks":[["禮，不妄說人，不辭費。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-2","passageId":"li-ji_ch-1_p-7","order":2,"canonicalText":"禮，不逾節，不侵侮，不好狎。","chunks":[["禮，不逾節，不侵侮，不好狎。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-3","passageId":"li-ji_ch-1_p-7","order":3,"canonicalText":"修身踐言，謂之善行。","chunks":[["修身踐言，謂之善行。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-4","passageId":"li-ji_ch-1_p-7","order":4,"canonicalText":"行修言道，禮之質也。","chunks":[["行修言道，禮之質也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-5","passageId":"li-ji_ch-1_p-7","order":5,"canonicalText":"禮聞取於人，不聞取人。","chunks":[["禮聞取於人，不聞取人。","zh-Hant"]]},{"id":"li-ji_ch-1_p-7_s-6","passageId":"li-ji_ch-1_p-7","order":6,"canonicalText":"禮聞來學，不聞往教。","chunks":[["禮聞來學，不聞往教。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-1","passageId":"li-ji_ch-1_p-8","order":1,"canonicalText":"道德仁義，非禮不成，教訓正俗，非禮不備。","chunks":[["道德仁義，非禮不成，教訓正俗，非禮不備。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-2","passageId":"li-ji_ch-1_p-8","order":2,"canonicalText":"分爭辨訟，非禮不決。","chunks":[["分爭辨訟，非禮不決。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-3","passageId":"li-ji_ch-1_p-8","order":3,"canonicalText":"君臣上下父子兄弟，非禮不定。","chunks":[["君臣上下父子兄弟，非禮不定。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-4","passageId":"li-ji_ch-1_p-8","order":4,"canonicalText":"宦學事師，非禮不親。","chunks":[["宦學事師，非禮不親。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-5","passageId":"li-ji_ch-1_p-8","order":5,"canonicalText":"班朝治軍，蒞官行法，非禮威嚴不行。","chunks":[["班朝治軍，蒞官行法，非禮威嚴不行。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-6","passageId":"li-ji_ch-1_p-8","order":6,"canonicalText":"禱祠祭祀，供給鬼神，非禮不誠不莊。","chunks":[["禱祠祭祀，供給鬼神，非禮不誠不莊。","zh-Hant"]]},{"id":"li-ji_ch-1_p-8_s-7","passageId":"li-ji_ch-1_p-8","order":7,"canonicalText":"是以君子恭敬撙節退讓以明禮。","chunks":[["是以君子恭敬撙節退讓以明禮。","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-1","passageId":"li-ji_ch-1_p-9","order":1,"canonicalText":"鸚鵡能言，不離飛鳥；","chunks":[["鸚鵡能言，不離飛鳥；","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-2","passageId":"li-ji_ch-1_p-9","order":2,"canonicalText":"猩猩能言，不離禽獸。","chunks":[["猩猩能言，不離禽獸。","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-3","passageId":"li-ji_ch-1_p-9","order":3,"canonicalText":"今人而無禮，雖能言，不亦禽獸之心乎？","chunks":[["今人而無禮，雖能言，不亦禽獸之心乎？","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-4","passageId":"li-ji_ch-1_p-9","order":4,"canonicalText":"夫唯禽獸無禮，故父子聚麀。","chunks":[["夫唯禽獸無禮，故父子聚麀。","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-5","passageId":"li-ji_ch-1_p-9","order":5,"canonicalText":"是故聖人作，為禮以教人。","chunks":[["是故聖人作，為禮以教人。","zh-Hant"]]},{"id":"li-ji_ch-1_p-9_s-6","passageId":"li-ji_ch-1_p-9","order":6,"canonicalText":"使人以有禮，知自別於禽獸。","chunks":[["使人以有禮，知自別於禽獸。","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-1","passageId":"li-ji_ch-1_p-10","order":1,"canonicalText":"太上貴德，其次務施報。","chunks":[["太上貴德，其次務施報。","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-2","passageId":"li-ji_ch-1_p-10","order":2,"canonicalText":"禮尚往來。","chunks":[["禮尚往來。","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-3","passageId":"li-ji_ch-1_p-10","order":3,"canonicalText":"往而不來，非禮也；","chunks":[["往而不來，非禮也；","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-4","passageId":"li-ji_ch-1_p-10","order":4,"canonicalText":"來而不往，亦非禮也。","chunks":[["來而不往，亦非禮也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-5","passageId":"li-ji_ch-1_p-10","order":5,"canonicalText":"人有禮則安，無禮則危。","chunks":[["人有禮則安，無禮則危。","zh-Hant"]]},{"id":"li-ji_ch-1_p-10_s-6","passageId":"li-ji_ch-1_p-10","order":6,"canonicalText":"故曰：禮者不可不學也。","chunks":[["故曰：禮者不可不學也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-11_s-1","passageId":"li-ji_ch-1_p-11","order":1,"canonicalText":"夫禮者，自卑而尊人。","chunks":[["夫禮者，自卑而尊人。","zh-Hant"]]},{"id":"li-ji_ch-1_p-11_s-2","passageId":"li-ji_ch-1_p-11","order":2,"canonicalText":"雖負販者，必有尊也，而況富貴乎？","chunks":[["雖負販者，必有尊也，而況富貴乎？","zh-Hant"]]},{"id":"li-ji_ch-1_p-11_s-3","passageId":"li-ji_ch-1_p-11","order":3,"canonicalText":"富貴而知好禮，則不驕不淫；","chunks":[["富貴而知好禮，則不驕不淫；","zh-Hant"]]},{"id":"li-ji_ch-1_p-11_s-4","passageId":"li-ji_ch-1_p-11","order":4,"canonicalText":"貧賤而知好禮，則志不懾。","chunks":[["貧賤而知好禮，則志不懾。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-1","passageId":"li-ji_ch-1_p-12","order":1,"canonicalText":"人生十年曰幼，學。","chunks":[["人生十年曰幼，學。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-2","passageId":"li-ji_ch-1_p-12","order":2,"canonicalText":"二十曰弱，冠。","chunks":[["二十曰弱，冠。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-3","passageId":"li-ji_ch-1_p-12","order":3,"canonicalText":"三十曰壯，有室。","chunks":[["三十曰壯，有室。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-4","passageId":"li-ji_ch-1_p-12","order":4,"canonicalText":"四十曰強，而仕。","chunks":[["四十曰強，而仕。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-5","passageId":"li-ji_ch-1_p-12","order":5,"canonicalText":"五十曰艾，服官政。","chunks":[["五十曰艾，服官政。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-6","passageId":"li-ji_ch-1_p-12","order":6,"canonicalText":"六十曰耆，指使。","chunks":[["六十曰耆，指使。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-7","passageId":"li-ji_ch-1_p-12","order":7,"canonicalText":"七十曰老，而傳。","chunks":[["七十曰老，而傳。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-8","passageId":"li-ji_ch-1_p-12","order":8,"canonicalText":"八十、九十曰耄，七年曰悼，悼與耄雖有罪，不加刑焉。","chunks":[["八十、九十曰耄，七年曰悼，悼與耄雖有罪，不加刑焉。","zh-Hant"]]},{"id":"li-ji_ch-1_p-12_s-9","passageId":"li-ji_ch-1_p-12","order":9,"canonicalText":"百年曰期，頤。","chunks":[["百年曰期，頤。","zh-Hant"]]},{"id":"li-ji_ch-1_p-13_s-1","passageId":"li-ji_ch-1_p-13","order":1,"canonicalText":"大夫七十而致事。","chunks":[["大夫七十而致事。","zh-Hant"]]},{"id":"li-ji_ch-1_p-13_s-2","passageId":"li-ji_ch-1_p-13","order":2,"canonicalText":"若不得謝，則必賜之几杖，行役以婦人。","chunks":[["若不得謝，則必賜之几杖，行役以婦人。","zh-Hant"]]},{"id":"li-ji_ch-1_p-13_s-3","passageId":"li-ji_ch-1_p-13","order":3,"canonicalText":"適四方，乘安車。","chunks":[["適四方，乘安車。","zh-Hant"]]},{"id":"li-ji_ch-1_p-13_s-4","passageId":"li-ji_ch-1_p-13","order":4,"canonicalText":"自稱曰老夫，於其國則稱名；","chunks":[["自稱曰老夫，於其國則稱名；","zh-Hant"]]},{"id":"li-ji_ch-1_p-13_s-5","passageId":"li-ji_ch-1_p-13","order":5,"canonicalText":"越國而問焉，必告之以其制。","chunks":[["越國而問焉，必告之以其制。","zh-Hant"]]},{"id":"li-ji_ch-1_p-14_s-1","passageId":"li-ji_ch-1_p-14","order":1,"canonicalText":"謀於長者，必操几杖以從之。","chunks":[["謀於長者，必操几杖以從之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-14_s-2","passageId":"li-ji_ch-1_p-14","order":2,"canonicalText":"長者問，不辭讓而對，非禮也。","chunks":[["長者問，不辭讓而對，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-15_s-1","passageId":"li-ji_ch-1_p-15","order":1,"canonicalText":"凡為人子之禮：冬溫而夏凊，昏定而晨省，在醜夷不爭。","chunks":[["凡為人子之禮：冬溫而夏凊，昏定而晨省，在醜夷不爭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-16_s-1","passageId":"li-ji_ch-1_p-16","order":1,"canonicalText":"夫為人子者，三賜不及車馬。","chunks":[["夫為人子者，三賜不及車馬。","zh-Hant"]]},{"id":"li-ji_ch-1_p-16_s-2","passageId":"li-ji_ch-1_p-16","order":2,"canonicalText":"故州閭鄉黨稱其孝也，兄弟親戚稱其慈也，僚友稱其弟也，執友稱其仁也，交游稱其信也。","chunks":[["故州閭鄉黨稱其孝也，兄弟親戚稱其慈也，僚友稱其弟也，執友稱其仁也，交游稱其信也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-16_s-3","passageId":"li-ji_ch-1_p-16","order":3,"canonicalText":"見父之執，不謂之進不敢進，不謂之退不敢退，不問不敢對。","chunks":[["見父之執，不謂之進不敢進，不謂之退不敢退，不問不敢對。","zh-Hant"]]},{"id":"li-ji_ch-1_p-16_s-4","passageId":"li-ji_ch-1_p-16","order":4,"canonicalText":"此孝子之行也。","chunks":[["此孝子之行也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-17_s-1","passageId":"li-ji_ch-1_p-17","order":1,"canonicalText":"夫為人子者：出必告，反必面，所游必有常，所習必有業。","chunks":[["夫為人子者：出必告，反必面，所游必有常，所習必有業。","zh-Hant"]]},{"id":"li-ji_ch-1_p-17_s-2","passageId":"li-ji_ch-1_p-17","order":2,"canonicalText":"恒言不稱老。","chunks":[["恒言不稱老。","zh-Hant"]]},{"id":"li-ji_ch-1_p-17_s-3","passageId":"li-ji_ch-1_p-17","order":3,"canonicalText":"年長以倍則父事之，十年以長則兄事之，五年以長則肩隨之。","chunks":[["年長以倍則父事之，十年以長則兄事之，五年以長則肩隨之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-17_s-4","passageId":"li-ji_ch-1_p-17","order":4,"canonicalText":"群居五人，則長者必異席。","chunks":[["群居五人，則長者必異席。","zh-Hant"]]},{"id":"li-ji_ch-1_p-18_s-1","passageId":"li-ji_ch-1_p-18","order":1,"canonicalText":"為人子者，居不主奧，坐不中席，行不中道，立不中門。","chunks":[["為人子者，居不主奧，坐不中席，行不中道，立不中門。","zh-Hant"]]},{"id":"li-ji_ch-1_p-18_s-2","passageId":"li-ji_ch-1_p-18","order":2,"canonicalText":"食饗不為概，祭祀不為尸。","chunks":[["食饗不為概，祭祀不為尸。","zh-Hant"]]},{"id":"li-ji_ch-1_p-18_s-3","passageId":"li-ji_ch-1_p-18","order":3,"canonicalText":"聽於無聲，視於無形。","chunks":[["聽於無聲，視於無形。","zh-Hant"]]},{"id":"li-ji_ch-1_p-18_s-4","passageId":"li-ji_ch-1_p-18","order":4,"canonicalText":"不登高，不臨深。","chunks":[["不登高，不臨深。","zh-Hant"]]},{"id":"li-ji_ch-1_p-18_s-5","passageId":"li-ji_ch-1_p-18","order":5,"canonicalText":"不茍訾，不茍笑。","chunks":[["不茍訾，不茍笑。","zh-Hant"]]},{"id":"li-ji_ch-1_p-19_s-1","passageId":"li-ji_ch-1_p-19","order":1,"canonicalText":"孝子不服暗，不登危，懼辱親也。","chunks":[["孝子不服暗，不登危，懼辱親也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-19_s-2","passageId":"li-ji_ch-1_p-19","order":2,"canonicalText":"父母存，不許友以死。","chunks":[["父母存，不許友以死。","zh-Hant"]]},{"id":"li-ji_ch-1_p-19_s-3","passageId":"li-ji_ch-1_p-19","order":3,"canonicalText":"不有私財。","chunks":[["不有私財。","zh-Hant"]]},{"id":"li-ji_ch-1_p-20_s-1","passageId":"li-ji_ch-1_p-20","order":1,"canonicalText":"為人子者：父母存，冠衣不純素。","chunks":[["為人子者：父母存，冠衣不純素。","zh-Hant"]]},{"id":"li-ji_ch-1_p-20_s-2","passageId":"li-ji_ch-1_p-20","order":2,"canonicalText":"孤子當室，冠衣不純采。","chunks":[["孤子當室，冠衣不純采。","zh-Hant"]]},{"id":"li-ji_ch-1_p-21_s-1","passageId":"li-ji_ch-1_p-21","order":1,"canonicalText":"幼子常視毋誑，童子不衣裘裳。","chunks":[["幼子常視毋誑，童子不衣裘裳。","zh-Hant"]]},{"id":"li-ji_ch-1_p-21_s-2","passageId":"li-ji_ch-1_p-21","order":2,"canonicalText":"立必正方。","chunks":[["立必正方。","zh-Hant"]]},{"id":"li-ji_ch-1_p-21_s-3","passageId":"li-ji_ch-1_p-21","order":3,"canonicalText":"不傾聽。","chunks":[["不傾聽。","zh-Hant"]]},{"id":"li-ji_ch-1_p-21_s-4","passageId":"li-ji_ch-1_p-21","order":4,"canonicalText":"長者與之提攜，則兩手奉長者之手。","chunks":[["長者與之提攜，則兩手奉長者之手。","zh-Hant"]]},{"id":"li-ji_ch-1_p-21_s-5","passageId":"li-ji_ch-1_p-21","order":5,"canonicalText":"負劍辟咡詔之，則掩口而對。","chunks":[["負劍辟咡詔之，則掩口而對。","zh-Hant"]]},{"id":"li-ji_ch-1_p-22_s-1","passageId":"li-ji_ch-1_p-22","order":1,"canonicalText":"從於先生，不越路而與人言。","chunks":[["從於先生，不越路而與人言。","zh-Hant"]]},{"id":"li-ji_ch-1_p-22_s-2","passageId":"li-ji_ch-1_p-22","order":2,"canonicalText":"遭先生於道，趨而進，正立拱手。","chunks":[["遭先生於道，趨而進，正立拱手。","zh-Hant"]]},{"id":"li-ji_ch-1_p-22_s-3","passageId":"li-ji_ch-1_p-22","order":3,"canonicalText":"先生與之言則對；","chunks":[["先生與之言則對；","zh-Hant"]]},{"id":"li-ji_ch-1_p-22_s-4","passageId":"li-ji_ch-1_p-22","order":4,"canonicalText":"不與之言則趨而退。","chunks":[["不與之言則趨而退。","zh-Hant"]]},{"id":"li-ji_ch-1_p-23_s-1","passageId":"li-ji_ch-1_p-23","order":1,"canonicalText":"從長者而上丘陵，則必鄉長者所視。","chunks":[["從長者而上丘陵，則必鄉長者所視。","zh-Hant"]]},{"id":"li-ji_ch-1_p-24_s-1","passageId":"li-ji_ch-1_p-24","order":1,"canonicalText":"登城不指，城上不呼。","chunks":[["登城不指，城上不呼。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-1","passageId":"li-ji_ch-1_p-25","order":1,"canonicalText":"將適舍，求毋固。","chunks":[["將適舍，求毋固。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-2","passageId":"li-ji_ch-1_p-25","order":2,"canonicalText":"將上堂，聲必揚。","chunks":[["將上堂，聲必揚。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-3","passageId":"li-ji_ch-1_p-25","order":3,"canonicalText":"戶外有二屨，言聞則入，言不聞則不入。","chunks":[["戶外有二屨，言聞則入，言不聞則不入。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-4","passageId":"li-ji_ch-1_p-25","order":4,"canonicalText":"將入戶，視必下。","chunks":[["將入戶，視必下。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-5","passageId":"li-ji_ch-1_p-25","order":5,"canonicalText":"入戶奉扃，視瞻毋回；","chunks":[["入戶奉扃，視瞻毋回；","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-6","passageId":"li-ji_ch-1_p-25","order":6,"canonicalText":"戶開亦開，戶闔亦闔；","chunks":[["戶開亦開，戶闔亦闔；","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-7","passageId":"li-ji_ch-1_p-25","order":7,"canonicalText":"有後入者，闔而勿遂。","chunks":[["有後入者，闔而勿遂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-8","passageId":"li-ji_ch-1_p-25","order":8,"canonicalText":"毋踐屨，毋踖席，摳衣趨隅。","chunks":[["毋踐屨，毋踖席，摳衣趨隅。","zh-Hant"]]},{"id":"li-ji_ch-1_p-25_s-9","passageId":"li-ji_ch-1_p-25","order":9,"canonicalText":"必慎唯諾。","chunks":[["必慎唯諾。","zh-Hant"]]},{"id":"li-ji_ch-1_p-26_s-1","passageId":"li-ji_ch-1_p-26","order":1,"canonicalText":"大夫士出入君門，由闑右，不踐閾。","chunks":[["大夫士出入君門，由闑右，不踐閾。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-1","passageId":"li-ji_ch-1_p-27","order":1,"canonicalText":"凡與客入者，每門讓於客。","chunks":[["凡與客入者，每門讓於客。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-2","passageId":"li-ji_ch-1_p-27","order":2,"canonicalText":"客至於寢門，則主人請入為席，然後出迎客。","chunks":[["客至於寢門，則主人請入為席，然後出迎客。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-3","passageId":"li-ji_ch-1_p-27","order":3,"canonicalText":"客固辭，主人肅客而入。","chunks":[["客固辭，主人肅客而入。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-4","passageId":"li-ji_ch-1_p-27","order":4,"canonicalText":"主人入門而右，客入門而左。","chunks":[["主人入門而右，客入門而左。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-5","passageId":"li-ji_ch-1_p-27","order":5,"canonicalText":"主人就東階，客就西階，客若降等，則就主人之階。","chunks":[["主人就東階，客就西階，客若降等，則就主人之階。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-6","passageId":"li-ji_ch-1_p-27","order":6,"canonicalText":"主人固辭，然後客復就西階。","chunks":[["主人固辭，然後客復就西階。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-7","passageId":"li-ji_ch-1_p-27","order":7,"canonicalText":"主人與客讓登，主人先登，客從之，拾級聚足，連步以上。","chunks":[["主人與客讓登，主人先登，客從之，拾級聚足，連步以上。","zh-Hant"]]},{"id":"li-ji_ch-1_p-27_s-8","passageId":"li-ji_ch-1_p-27","order":8,"canonicalText":"上於東階則先右足，上於西階則先左足。","chunks":[["上於東階則先右足，上於西階則先左足。","zh-Hant"]]},{"id":"li-ji_ch-1_p-28_s-1","passageId":"li-ji_ch-1_p-28","order":1,"canonicalText":"帷薄之外不趨，堂上不趨，執玉不趨。","chunks":[["帷薄之外不趨，堂上不趨，執玉不趨。","zh-Hant"]]},{"id":"li-ji_ch-1_p-28_s-2","passageId":"li-ji_ch-1_p-28","order":2,"canonicalText":"堂上接武，堂下布武。","chunks":[["堂上接武，堂下布武。","zh-Hant"]]},{"id":"li-ji_ch-1_p-28_s-3","passageId":"li-ji_ch-1_p-28","order":3,"canonicalText":"室中不翔，并坐不橫肱。","chunks":[["室中不翔，并坐不橫肱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-28_s-4","passageId":"li-ji_ch-1_p-28","order":4,"canonicalText":"授立不跪，授坐不立。","chunks":[["授立不跪，授坐不立。","zh-Hant"]]},{"id":"li-ji_ch-1_p-29_s-1","passageId":"li-ji_ch-1_p-29","order":1,"canonicalText":"凡為長者糞之禮，必加帚於箕上，以袂拘而退；","chunks":[["凡為長者糞之禮，必加帚於箕上，以袂拘而退；","zh-Hant"]]},{"id":"li-ji_ch-1_p-29_s-2","passageId":"li-ji_ch-1_p-29","order":2,"canonicalText":"其塵不及長者，以箕自鄉而扱之。","chunks":[["其塵不及長者，以箕自鄉而扱之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-29_s-3","passageId":"li-ji_ch-1_p-29","order":3,"canonicalText":"奉席如橋衡，請席何鄉，請衽何趾。","chunks":[["奉席如橋衡，請席何鄉，請衽何趾。","zh-Hant"]]},{"id":"li-ji_ch-1_p-29_s-4","passageId":"li-ji_ch-1_p-29","order":4,"canonicalText":"席：南鄉北鄉，以西方為上；","chunks":[["席：南鄉北鄉，以西方為上；","zh-Hant"]]},{"id":"li-ji_ch-1_p-29_s-5","passageId":"li-ji_ch-1_p-29","order":5,"canonicalText":"東鄉西鄉，以南方為上。","chunks":[["東鄉西鄉，以南方為上。","zh-Hant"]]},{"id":"li-ji_ch-1_p-30_s-1","passageId":"li-ji_ch-1_p-30","order":1,"canonicalText":"若非飲食之客，則布席，席間函丈。","chunks":[["若非飲食之客，則布席，席間函丈。","zh-Hant"]]},{"id":"li-ji_ch-1_p-30_s-2","passageId":"li-ji_ch-1_p-30","order":2,"canonicalText":"主人跪正席，客跪撫席而辭。","chunks":[["主人跪正席，客跪撫席而辭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-30_s-3","passageId":"li-ji_ch-1_p-30","order":3,"canonicalText":"客徹重席，主人固辭。","chunks":[["客徹重席，主人固辭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-30_s-4","passageId":"li-ji_ch-1_p-30","order":4,"canonicalText":"客踐席，乃坐。","chunks":[["客踐席，乃坐。","zh-Hant"]]},{"id":"li-ji_ch-1_p-30_s-5","passageId":"li-ji_ch-1_p-30","order":5,"canonicalText":"主人不問，客不先舉。","chunks":[["主人不問，客不先舉。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-1","passageId":"li-ji_ch-1_p-31","order":1,"canonicalText":"將即席，容毋怍。","chunks":[["將即席，容毋怍。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-2","passageId":"li-ji_ch-1_p-31","order":2,"canonicalText":"兩手摳衣去齊尺。","chunks":[["兩手摳衣去齊尺。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-3","passageId":"li-ji_ch-1_p-31","order":3,"canonicalText":"衣毋撥，足毋蹶。","chunks":[["衣毋撥，足毋蹶。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-4","passageId":"li-ji_ch-1_p-31","order":4,"canonicalText":"先生書策琴瑟在前，坐而遷之，戒勿越。","chunks":[["先生書策琴瑟在前，坐而遷之，戒勿越。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-5","passageId":"li-ji_ch-1_p-31","order":5,"canonicalText":"虛坐盡後，食坐盡前。","chunks":[["虛坐盡後，食坐盡前。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-6","passageId":"li-ji_ch-1_p-31","order":6,"canonicalText":"坐必安，執爾顏。","chunks":[["坐必安，執爾顏。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-7","passageId":"li-ji_ch-1_p-31","order":7,"canonicalText":"長者不及，毋儳言。","chunks":[["長者不及，毋儳言。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-8","passageId":"li-ji_ch-1_p-31","order":8,"canonicalText":"正爾容，聽必恭。","chunks":[["正爾容，聽必恭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-9","passageId":"li-ji_ch-1_p-31","order":9,"canonicalText":"毋剿說，毋雷同。","chunks":[["毋剿說，毋雷同。","zh-Hant"]]},{"id":"li-ji_ch-1_p-31_s-10","passageId":"li-ji_ch-1_p-31","order":10,"canonicalText":"必則古昔，稱先王。","chunks":[["必則古昔，稱先王。","zh-Hant"]]},{"id":"li-ji_ch-1_p-32_s-1","passageId":"li-ji_ch-1_p-32","order":1,"canonicalText":"侍坐於先生：先生問焉，終則對。","chunks":[["侍坐於先生：先生問焉，終則對。","zh-Hant"]]},{"id":"li-ji_ch-1_p-32_s-2","passageId":"li-ji_ch-1_p-32","order":2,"canonicalText":"請業則起，請益則起。","chunks":[["請業則起，請益則起。","zh-Hant"]]},{"id":"li-ji_ch-1_p-32_s-3","passageId":"li-ji_ch-1_p-32","order":3,"canonicalText":"父召無諾，先生召無諾，唯而起。","chunks":[["父召無諾，先生召無諾，唯而起。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-1","passageId":"li-ji_ch-1_p-33","order":1,"canonicalText":"侍坐於所尊敬，毋餘席。","chunks":[["侍坐於所尊敬，毋餘席。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-2","passageId":"li-ji_ch-1_p-33","order":2,"canonicalText":"見同等不起。","chunks":[["見同等不起。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-3","passageId":"li-ji_ch-1_p-33","order":3,"canonicalText":"燭至起，食至起，上客起。","chunks":[["燭至起，食至起，上客起。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-4","passageId":"li-ji_ch-1_p-33","order":4,"canonicalText":"燭不見跋。","chunks":[["燭不見跋。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-5","passageId":"li-ji_ch-1_p-33","order":5,"canonicalText":"尊客之前不叱狗。","chunks":[["尊客之前不叱狗。","zh-Hant"]]},{"id":"li-ji_ch-1_p-33_s-6","passageId":"li-ji_ch-1_p-33","order":6,"canonicalText":"讓食不唾。","chunks":[["讓食不唾。","zh-Hant"]]},{"id":"li-ji_ch-1_p-34_s-1","passageId":"li-ji_ch-1_p-34","order":1,"canonicalText":"侍坐於君子，君子欠伸，撰杖屨，視日蚤莫，侍坐者請出矣。","chunks":[["侍坐於君子，君子欠伸，撰杖屨，視日蚤莫，侍坐者請出矣。","zh-Hant"]]},{"id":"li-ji_ch-1_p-34_s-2","passageId":"li-ji_ch-1_p-34","order":2,"canonicalText":"侍坐於君子，君子問更端，則起而對。","chunks":[["侍坐於君子，君子問更端，則起而對。","zh-Hant"]]},{"id":"li-ji_ch-1_p-34_s-3","passageId":"li-ji_ch-1_p-34","order":3,"canonicalText":"侍坐於君子，若有告者曰：「少間」，愿有復也；","chunks":[["侍坐於君子，若有告者曰：「少間」，愿有復也；","zh-Hant"]]},{"id":"li-ji_ch-1_p-34_s-4","passageId":"li-ji_ch-1_p-34","order":4,"canonicalText":"則左右屏而待。","chunks":[["則左右屏而待。","zh-Hant"]]},{"id":"li-ji_ch-1_p-35_s-1","passageId":"li-ji_ch-1_p-35","order":1,"canonicalText":"毋側聽，毋噭應，毋淫視，毋怠荒。","chunks":[["毋側聽，毋噭應，毋淫視，毋怠荒。","zh-Hant"]]},{"id":"li-ji_ch-1_p-35_s-2","passageId":"li-ji_ch-1_p-35","order":2,"canonicalText":"游毋倨，立毋跛，坐毋箕，寢毋伏。","chunks":[["游毋倨，立毋跛，坐毋箕，寢毋伏。","zh-Hant"]]},{"id":"li-ji_ch-1_p-35_s-3","passageId":"li-ji_ch-1_p-35","order":3,"canonicalText":"斂髮毋髢，冠毋免，勞毋袒，暑毋褰裳。","chunks":[["斂髮毋髢，冠毋免，勞毋袒，暑毋褰裳。","zh-Hant"]]},{"id":"li-ji_ch-1_p-36_s-1","passageId":"li-ji_ch-1_p-36","order":1,"canonicalText":"侍坐於長者，屨不上於堂，解屨不敢當階。","chunks":[["侍坐於長者，屨不上於堂，解屨不敢當階。","zh-Hant"]]},{"id":"li-ji_ch-1_p-36_s-2","passageId":"li-ji_ch-1_p-36","order":2,"canonicalText":"就屨，跪而舉之，屏於側。","chunks":[["就屨，跪而舉之，屏於側。","zh-Hant"]]},{"id":"li-ji_ch-1_p-36_s-3","passageId":"li-ji_ch-1_p-36","order":3,"canonicalText":"鄉長者而屨；","chunks":[["鄉長者而屨；","zh-Hant"]]},{"id":"li-ji_ch-1_p-36_s-4","passageId":"li-ji_ch-1_p-36","order":4,"canonicalText":"跪而遷屨，俯而納屨。","chunks":[["跪而遷屨，俯而納屨。","zh-Hant"]]},{"id":"li-ji_ch-1_p-37_s-1","passageId":"li-ji_ch-1_p-37","order":1,"canonicalText":"離坐離立，毋往參焉；","chunks":[["離坐離立，毋往參焉；","zh-Hant"]]},{"id":"li-ji_ch-1_p-37_s-2","passageId":"li-ji_ch-1_p-37","order":2,"canonicalText":"離立者，不出中間。","chunks":[["離立者，不出中間。","zh-Hant"]]},{"id":"li-ji_ch-1_p-38_s-1","passageId":"li-ji_ch-1_p-38","order":1,"canonicalText":"男女不雜坐，不同椸枷，不同巾櫛，不親授。","chunks":[["男女不雜坐，不同椸枷，不同巾櫛，不親授。","zh-Hant"]]},{"id":"li-ji_ch-1_p-38_s-2","passageId":"li-ji_ch-1_p-38","order":2,"canonicalText":"嫂叔不通問，諸母不漱裳。","chunks":[["嫂叔不通問，諸母不漱裳。","zh-Hant"]]},{"id":"li-ji_ch-1_p-38_s-3","passageId":"li-ji_ch-1_p-38","order":3,"canonicalText":"外言不入於梱，內言不出於捆。","chunks":[["外言不入於梱，內言不出於捆。","zh-Hant"]]},{"id":"li-ji_ch-1_p-39_s-1","passageId":"li-ji_ch-1_p-39","order":1,"canonicalText":"女子許嫁，纓；","chunks":[["女子許嫁，纓；","zh-Hant"]]},{"id":"li-ji_ch-1_p-39_s-2","passageId":"li-ji_ch-1_p-39","order":2,"canonicalText":"非有大故，不入其門。","chunks":[["非有大故，不入其門。","zh-Hant"]]},{"id":"li-ji_ch-1_p-39_s-3","passageId":"li-ji_ch-1_p-39","order":3,"canonicalText":"姑姊妹女子子，已嫁而反，兄弟弗與同席而坐，弗與同器而食。","chunks":[["姑姊妹女子子，已嫁而反，兄弟弗與同席而坐，弗與同器而食。","zh-Hant"]]},{"id":"li-ji_ch-1_p-39_s-4","passageId":"li-ji_ch-1_p-39","order":4,"canonicalText":"父子不同席。","chunks":[["父子不同席。","zh-Hant"]]},{"id":"li-ji_ch-1_p-40_s-1","passageId":"li-ji_ch-1_p-40","order":1,"canonicalText":"男女非有行媒，不相知名；","chunks":[["男女非有行媒，不相知名；","zh-Hant"]]},{"id":"li-ji_ch-1_p-40_s-2","passageId":"li-ji_ch-1_p-40","order":2,"canonicalText":"非受幣，不交不親。","chunks":[["非受幣，不交不親。","zh-Hant"]]},{"id":"li-ji_ch-1_p-40_s-3","passageId":"li-ji_ch-1_p-40","order":3,"canonicalText":"故日月以告君，齊戒以告鬼神，為酒食以召鄉黨僚友，以厚其別也。","chunks":[["故日月以告君，齊戒以告鬼神，為酒食以召鄉黨僚友，以厚其別也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-41_s-1","passageId":"li-ji_ch-1_p-41","order":1,"canonicalText":"取妻不取同姓；","chunks":[["取妻不取同姓；","zh-Hant"]]},{"id":"li-ji_ch-1_p-41_s-2","passageId":"li-ji_ch-1_p-41","order":2,"canonicalText":"故買妾不知其姓則卜之。","chunks":[["故買妾不知其姓則卜之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-41_s-3","passageId":"li-ji_ch-1_p-41","order":3,"canonicalText":"寡婦之子，非有見焉，弗與為友。","chunks":[["寡婦之子，非有見焉，弗與為友。","zh-Hant"]]},{"id":"li-ji_ch-1_p-42_s-1","passageId":"li-ji_ch-1_p-42","order":1,"canonicalText":"賀取妻者，曰：「某子使某聞子有客，使某羞。","chunks":[["賀取妻者，曰：「某子使某聞子有客，使某羞。","zh-Hant"]]},{"id":"li-ji_ch-1_p-42_s-2","passageId":"li-ji_ch-1_p-42","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-1_p-43_s-1","passageId":"li-ji_ch-1_p-43","order":1,"canonicalText":"貧者不以貨財為禮，老者不以筋力為禮。","chunks":[["貧者不以貨財為禮，老者不以筋力為禮。","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-1","passageId":"li-ji_ch-1_p-44","order":1,"canonicalText":"名子者不以國，不以日月，不以隱疾，不以山川。","chunks":[["名子者不以國，不以日月，不以隱疾，不以山川。","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-2","passageId":"li-ji_ch-1_p-44","order":2,"canonicalText":"男女異長。","chunks":[["男女異長。","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-3","passageId":"li-ji_ch-1_p-44","order":3,"canonicalText":"男子二十，冠而字。","chunks":[["男子二十，冠而字。","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-4","passageId":"li-ji_ch-1_p-44","order":4,"canonicalText":"父前，子名；","chunks":[["父前，子名；","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-5","passageId":"li-ji_ch-1_p-44","order":5,"canonicalText":"君前，臣名。","chunks":[["君前，臣名。","zh-Hant"]]},{"id":"li-ji_ch-1_p-44_s-6","passageId":"li-ji_ch-1_p-44","order":6,"canonicalText":"女子許嫁，笄而字。","chunks":[["女子許嫁，笄而字。","zh-Hant"]]},{"id":"li-ji_ch-1_p-45_s-1","passageId":"li-ji_ch-1_p-45","order":1,"canonicalText":"凡進食之禮，左殽右胾，食居人之左，羹居人之右。","chunks":[["凡進食之禮，左殽右胾，食居人之左，羹居人之右。","zh-Hant"]]},{"id":"li-ji_ch-1_p-45_s-2","passageId":"li-ji_ch-1_p-45","order":2,"canonicalText":"膾炙處外，醯醬處內，蔥渫處末，酒漿處右。","chunks":[["膾炙處外，醯醬處內，蔥渫處末，酒漿處右。","zh-Hant"]]},{"id":"li-ji_ch-1_p-45_s-3","passageId":"li-ji_ch-1_p-45","order":3,"canonicalText":"以脯修置者，左朐右末。","chunks":[["以脯修置者，左朐右末。","zh-Hant"]]},{"id":"li-ji_ch-1_p-46_s-1","passageId":"li-ji_ch-1_p-46","order":1,"canonicalText":"客若降等執食興辭，主人興辭於客，然後客坐。","chunks":[["客若降等執食興辭，主人興辭於客，然後客坐。","zh-Hant"]]},{"id":"li-ji_ch-1_p-46_s-2","passageId":"li-ji_ch-1_p-46","order":2,"canonicalText":"主人延客祭：祭食，祭所先進。","chunks":[["主人延客祭：祭食，祭所先進。","zh-Hant"]]},{"id":"li-ji_ch-1_p-46_s-3","passageId":"li-ji_ch-1_p-46","order":3,"canonicalText":"殽之序，遍祭之。","chunks":[["殽之序，遍祭之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-46_s-4","passageId":"li-ji_ch-1_p-46","order":4,"canonicalText":"三飯，主人延客食胾，然後辯殽。","chunks":[["三飯，主人延客食胾，然後辯殽。","zh-Hant"]]},{"id":"li-ji_ch-1_p-46_s-5","passageId":"li-ji_ch-1_p-46","order":5,"canonicalText":"主人未辯，客不虛口。","chunks":[["主人未辯，客不虛口。","zh-Hant"]]},{"id":"li-ji_ch-1_p-47_s-1","passageId":"li-ji_ch-1_p-47","order":1,"canonicalText":"侍食於長者，主人親饋，則拜而食；","chunks":[["侍食於長者，主人親饋，則拜而食；","zh-Hant"]]},{"id":"li-ji_ch-1_p-47_s-2","passageId":"li-ji_ch-1_p-47","order":2,"canonicalText":"主人不親饋，則不拜而食。","chunks":[["主人不親饋，則不拜而食。","zh-Hant"]]},{"id":"li-ji_ch-1_p-47_s-3","passageId":"li-ji_ch-1_p-47","order":3,"canonicalText":"共食不飽，共飯不澤手。","chunks":[["共食不飽，共飯不澤手。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-1","passageId":"li-ji_ch-1_p-48","order":1,"canonicalText":"毋摶飯，毋放飯，毋流歠，毋吒食，毋嚙骨，毋反魚肉，毋投與狗骨。","chunks":[["毋摶飯，毋放飯，毋流歠，毋吒食，毋嚙骨，毋反魚肉，毋投與狗骨。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-2","passageId":"li-ji_ch-1_p-48","order":2,"canonicalText":"毋固獲，毋揚飯。","chunks":[["毋固獲，毋揚飯。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-3","passageId":"li-ji_ch-1_p-48","order":3,"canonicalText":"飯黍毋以箸。","chunks":[["飯黍毋以箸。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-4","passageId":"li-ji_ch-1_p-48","order":4,"canonicalText":"毋嚃羹，毋絮羹，毋刺齒，毋歠醢。","chunks":[["毋嚃羹，毋絮羹，毋刺齒，毋歠醢。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-5","passageId":"li-ji_ch-1_p-48","order":5,"canonicalText":"客絮羹，主人辭不能亨。","chunks":[["客絮羹，主人辭不能亨。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-6","passageId":"li-ji_ch-1_p-48","order":6,"canonicalText":"客歠醢，主人辭以窶。","chunks":[["客歠醢，主人辭以窶。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-7","passageId":"li-ji_ch-1_p-48","order":7,"canonicalText":"濡肉齒決，乾肉不齒決。","chunks":[["濡肉齒決，乾肉不齒決。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-8","passageId":"li-ji_ch-1_p-48","order":8,"canonicalText":"毋嘬炙。","chunks":[["毋嘬炙。","zh-Hant"]]},{"id":"li-ji_ch-1_p-48_s-9","passageId":"li-ji_ch-1_p-48","order":9,"canonicalText":"卒食，客自前跪，徹飯齊以授相者，主人興辭於客，然後客坐。","chunks":[["卒食，客自前跪，徹飯齊以授相者，主人興辭於客，然後客坐。","zh-Hant"]]},{"id":"li-ji_ch-1_p-49_s-1","passageId":"li-ji_ch-1_p-49","order":1,"canonicalText":"侍飲於長者，酒進則起，拜受於尊所。","chunks":[["侍飲於長者，酒進則起，拜受於尊所。","zh-Hant"]]},{"id":"li-ji_ch-1_p-49_s-2","passageId":"li-ji_ch-1_p-49","order":2,"canonicalText":"長者辭，少者反席而飲。","chunks":[["長者辭，少者反席而飲。","zh-Hant"]]},{"id":"li-ji_ch-1_p-49_s-3","passageId":"li-ji_ch-1_p-49","order":3,"canonicalText":"長者舉未釂，少者不敢飲。","chunks":[["長者舉未釂，少者不敢飲。","zh-Hant"]]},{"id":"li-ji_ch-1_p-50_s-1","passageId":"li-ji_ch-1_p-50","order":1,"canonicalText":"長者賜，少者、賤者不敢辭。","chunks":[["長者賜，少者、賤者不敢辭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-50_s-2","passageId":"li-ji_ch-1_p-50","order":2,"canonicalText":"賜果於君前，其有核者懷其核。","chunks":[["賜果於君前，其有核者懷其核。","zh-Hant"]]},{"id":"li-ji_ch-1_p-50_s-3","passageId":"li-ji_ch-1_p-50","order":3,"canonicalText":"御食於君，君賜餘，器之溉者不寫，其餘皆寫。","chunks":[["御食於君，君賜餘，器之溉者不寫，其餘皆寫。","zh-Hant"]]},{"id":"li-ji_ch-1_p-51_s-1","passageId":"li-ji_ch-1_p-51","order":1,"canonicalText":"餕餘不祭。","chunks":[["餕餘不祭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-51_s-2","passageId":"li-ji_ch-1_p-51","order":2,"canonicalText":"父不祭子，夫不祭妻。","chunks":[["父不祭子，夫不祭妻。","zh-Hant"]]},{"id":"li-ji_ch-1_p-52_s-1","passageId":"li-ji_ch-1_p-52","order":1,"canonicalText":"御同於長者，雖貳不辭，偶坐不辭。","chunks":[["御同於長者，雖貳不辭，偶坐不辭。","zh-Hant"]]},{"id":"li-ji_ch-1_p-53_s-1","passageId":"li-ji_ch-1_p-53","order":1,"canonicalText":"羹之有菜者用梜，其無菜者不用梜。","chunks":[["羹之有菜者用梜，其無菜者不用梜。","zh-Hant"]]},{"id":"li-ji_ch-1_p-54_s-1","passageId":"li-ji_ch-1_p-54","order":1,"canonicalText":"為天子削瓜者副之，巾以絺。","chunks":[["為天子削瓜者副之，巾以絺。","zh-Hant"]]},{"id":"li-ji_ch-1_p-54_s-2","passageId":"li-ji_ch-1_p-54","order":2,"canonicalText":"為國君者華之，巾以綌。","chunks":[["為國君者華之，巾以綌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-54_s-3","passageId":"li-ji_ch-1_p-54","order":3,"canonicalText":"為大夫累之，士疐之，庶人齕之。","chunks":[["為大夫累之，士疐之，庶人齕之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-55_s-1","passageId":"li-ji_ch-1_p-55","order":1,"canonicalText":"父母有疾，冠者不櫛，行不翔，言不惰，琴瑟不御，食肉不至變味，飲酒不至變貌，笑不至矧，怒不至詈。","chunks":[["父母有疾，冠者不櫛，行不翔，言不惰，琴瑟不御，食肉不至變味，飲酒不至變貌，笑不至矧，怒不至詈。","zh-Hant"]]},{"id":"li-ji_ch-1_p-55_s-2","passageId":"li-ji_ch-1_p-55","order":2,"canonicalText":"疾止復故。","chunks":[["疾止復故。","zh-Hant"]]},{"id":"li-ji_ch-1_p-56_s-1","passageId":"li-ji_ch-1_p-56","order":1,"canonicalText":"有憂者側席而坐，有喪者專席而坐。","chunks":[["有憂者側席而坐，有喪者專席而坐。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-1","passageId":"li-ji_ch-1_p-57","order":1,"canonicalText":"水潦降，不獻魚鱉，獻鳥者拂其首，畜鳥者則勿拂也。","chunks":[["水潦降，不獻魚鱉，獻鳥者拂其首，畜鳥者則勿拂也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-2","passageId":"li-ji_ch-1_p-57","order":2,"canonicalText":"獻車馬者執策綏，獻甲者執胄，獻杖者執末。","chunks":[["獻車馬者執策綏，獻甲者執胄，獻杖者執末。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-3","passageId":"li-ji_ch-1_p-57","order":3,"canonicalText":"獻民虜者操右袂。","chunks":[["獻民虜者操右袂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-4","passageId":"li-ji_ch-1_p-57","order":4,"canonicalText":"獻粟者執右契，獻米者操量鼓。","chunks":[["獻粟者執右契，獻米者操量鼓。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-5","passageId":"li-ji_ch-1_p-57","order":5,"canonicalText":"獻孰食者操醬齊。","chunks":[["獻孰食者操醬齊。","zh-Hant"]]},{"id":"li-ji_ch-1_p-57_s-6","passageId":"li-ji_ch-1_p-57","order":6,"canonicalText":"獻田宅者操書致。","chunks":[["獻田宅者操書致。","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-1","passageId":"li-ji_ch-1_p-58","order":1,"canonicalText":"凡遺人弓者：張弓尚筋，弛弓尚角。","chunks":[["凡遺人弓者：張弓尚筋，弛弓尚角。","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-2","passageId":"li-ji_ch-1_p-58","order":2,"canonicalText":"右手執簫，左手承弣。","chunks":[["右手執簫，左手承弣。","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-3","passageId":"li-ji_ch-1_p-58","order":3,"canonicalText":"尊卑垂帨。","chunks":[["尊卑垂帨。","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-4","passageId":"li-ji_ch-1_p-58","order":4,"canonicalText":"若主人拜，則客還辟，辟拜。","chunks":[["若主人拜，則客還辟，辟拜。","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-5","passageId":"li-ji_ch-1_p-58","order":5,"canonicalText":"主人自受，由客之左接下承弣；","chunks":[["主人自受，由客之左接下承弣；","zh-Hant"]]},{"id":"li-ji_ch-1_p-58_s-6","passageId":"li-ji_ch-1_p-58","order":6,"canonicalText":"鄉與客并，然後受。","chunks":[["鄉與客并，然後受。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-1","passageId":"li-ji_ch-1_p-59","order":1,"canonicalText":"進劍者左首。","chunks":[["進劍者左首。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-2","passageId":"li-ji_ch-1_p-59","order":2,"canonicalText":"進戈者前其鐏，後其刃。","chunks":[["進戈者前其鐏，後其刃。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-3","passageId":"li-ji_ch-1_p-59","order":3,"canonicalText":"進矛戟者前其鐓。","chunks":[["進矛戟者前其鐓。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-4","passageId":"li-ji_ch-1_p-59","order":4,"canonicalText":"進几杖者拂之。","chunks":[["進几杖者拂之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-5","passageId":"li-ji_ch-1_p-59","order":5,"canonicalText":"效馬效羊者右牽之；","chunks":[["效馬效羊者右牽之；","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-6","passageId":"li-ji_ch-1_p-59","order":6,"canonicalText":"效犬者左牽之。","chunks":[["效犬者左牽之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-7","passageId":"li-ji_ch-1_p-59","order":7,"canonicalText":"執禽者左首。","chunks":[["執禽者左首。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-8","passageId":"li-ji_ch-1_p-59","order":8,"canonicalText":"飾羔雁者以繢。","chunks":[["飾羔雁者以繢。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-9","passageId":"li-ji_ch-1_p-59","order":9,"canonicalText":"受珠玉者以掬。","chunks":[["受珠玉者以掬。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-10","passageId":"li-ji_ch-1_p-59","order":10,"canonicalText":"受弓劍者以袂。","chunks":[["受弓劍者以袂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-11","passageId":"li-ji_ch-1_p-59","order":11,"canonicalText":"飲玉爵者弗揮。","chunks":[["飲玉爵者弗揮。","zh-Hant"]]},{"id":"li-ji_ch-1_p-59_s-12","passageId":"li-ji_ch-1_p-59","order":12,"canonicalText":"凡以弓劍、苞苴、簞笥問人者，操以受命，如使之容。","chunks":[["凡以弓劍、苞苴、簞笥問人者，操以受命，如使之容。","zh-Hant"]]},{"id":"li-ji_ch-1_p-60_s-1","passageId":"li-ji_ch-1_p-60","order":1,"canonicalText":"凡為君使者，已受命，君言不宿於家。","chunks":[["凡為君使者，已受命，君言不宿於家。","zh-Hant"]]},{"id":"li-ji_ch-1_p-60_s-2","passageId":"li-ji_ch-1_p-60","order":2,"canonicalText":"君言至，則主人出拜君言之辱；","chunks":[["君言至，則主人出拜君言之辱；","zh-Hant"]]},{"id":"li-ji_ch-1_p-60_s-3","passageId":"li-ji_ch-1_p-60","order":3,"canonicalText":"使者歸，則必拜送于門外。","chunks":[["使者歸，則必拜送于門外。","zh-Hant"]]},{"id":"li-ji_ch-1_p-60_s-4","passageId":"li-ji_ch-1_p-60","order":4,"canonicalText":"若使人於君所，則必朝服而命之；","chunks":[["若使人於君所，則必朝服而命之；","zh-Hant"]]},{"id":"li-ji_ch-1_p-60_s-5","passageId":"li-ji_ch-1_p-60","order":5,"canonicalText":"使者反，則必下堂而受命。","chunks":[["使者反，則必下堂而受命。","zh-Hant"]]},{"id":"li-ji_ch-1_p-61_s-1","passageId":"li-ji_ch-1_p-61","order":1,"canonicalText":"博聞強識而讓，敦善行而不怠，謂之君子。","chunks":[["博聞強識而讓，敦善行而不怠，謂之君子。","zh-Hant"]]},{"id":"li-ji_ch-1_p-61_s-2","passageId":"li-ji_ch-1_p-61","order":2,"canonicalText":"君子不盡人之歡，不竭人之忠，以全交也。","chunks":[["君子不盡人之歡，不竭人之忠，以全交也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-62_s-1","passageId":"li-ji_ch-1_p-62","order":1,"canonicalText":"《禮》曰：「君子抱孫不抱子。","chunks":[["《禮》曰：「君子抱孫不抱子。","zh-Hant"]]},{"id":"li-ji_ch-1_p-62_s-2","passageId":"li-ji_ch-1_p-62","order":2,"canonicalText":"」此言孫可以為王父尸，子不可以為父尸。","chunks":[["」此言孫可以為王父尸，子不可以為父尸。","zh-Hant"]]},{"id":"li-ji_ch-1_p-62_s-3","passageId":"li-ji_ch-1_p-62","order":3,"canonicalText":"為君尸者，大夫士見之，則下之。","chunks":[["為君尸者，大夫士見之，則下之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-62_s-4","passageId":"li-ji_ch-1_p-62","order":4,"canonicalText":"君知所以為尸者，則自下之，尸必式。","chunks":[["君知所以為尸者，則自下之，尸必式。","zh-Hant"]]},{"id":"li-ji_ch-1_p-62_s-5","passageId":"li-ji_ch-1_p-62","order":5,"canonicalText":"乘必以几。","chunks":[["乘必以几。","zh-Hant"]]},{"id":"li-ji_ch-1_p-63_s-1","passageId":"li-ji_ch-1_p-63","order":1,"canonicalText":"齊者不樂不吊。","chunks":[["齊者不樂不吊。","zh-Hant"]]},{"id":"li-ji_ch-1_p-64_s-1","passageId":"li-ji_ch-1_p-64","order":1,"canonicalText":"居喪之禮，毀瘠不形，視聽不衰。","chunks":[["居喪之禮，毀瘠不形，視聽不衰。","zh-Hant"]]},{"id":"li-ji_ch-1_p-64_s-2","passageId":"li-ji_ch-1_p-64","order":2,"canonicalText":"升降不由阼階，出入不當門隧。","chunks":[["升降不由阼階，出入不當門隧。","zh-Hant"]]},{"id":"li-ji_ch-1_p-64_s-3","passageId":"li-ji_ch-1_p-64","order":3,"canonicalText":"居喪之禮，頭有創則沐，身有瘍則浴，有疾則飲酒食肉，疾止復初。","chunks":[["居喪之禮，頭有創則沐，身有瘍則浴，有疾則飲酒食肉，疾止復初。","zh-Hant"]]},{"id":"li-ji_ch-1_p-64_s-4","passageId":"li-ji_ch-1_p-64","order":4,"canonicalText":"不勝喪，乃比於不慈不孝。","chunks":[["不勝喪，乃比於不慈不孝。","zh-Hant"]]},{"id":"li-ji_ch-1_p-64_s-5","passageId":"li-ji_ch-1_p-64","order":5,"canonicalText":"五十不致毀，六十不毀，七十唯衰麻在身，飲酒食肉，處於內。","chunks":[["五十不致毀，六十不毀，七十唯衰麻在身，飲酒食肉，處於內。","zh-Hant"]]},{"id":"li-ji_ch-1_p-65_s-1","passageId":"li-ji_ch-1_p-65","order":1,"canonicalText":"生與來日，死與往日。","chunks":[["生與來日，死與往日。","zh-Hant"]]},{"id":"li-ji_ch-1_p-65_s-2","passageId":"li-ji_ch-1_p-65","order":2,"canonicalText":"知生者吊，知死者傷。","chunks":[["知生者吊，知死者傷。","zh-Hant"]]},{"id":"li-ji_ch-1_p-65_s-3","passageId":"li-ji_ch-1_p-65","order":3,"canonicalText":"知生而不知死，吊而不傷；","chunks":[["知生而不知死，吊而不傷；","zh-Hant"]]},{"id":"li-ji_ch-1_p-65_s-4","passageId":"li-ji_ch-1_p-65","order":4,"canonicalText":"知死而不知生，傷而不吊。","chunks":[["知死而不知生，傷而不吊。","zh-Hant"]]},{"id":"li-ji_ch-1_p-66_s-1","passageId":"li-ji_ch-1_p-66","order":1,"canonicalText":"吊喪弗能賻，不問其所費。","chunks":[["吊喪弗能賻，不問其所費。","zh-Hant"]]},{"id":"li-ji_ch-1_p-66_s-2","passageId":"li-ji_ch-1_p-66","order":2,"canonicalText":"問疾弗能遺，不問其所欲。","chunks":[["問疾弗能遺，不問其所欲。","zh-Hant"]]},{"id":"li-ji_ch-1_p-66_s-3","passageId":"li-ji_ch-1_p-66","order":3,"canonicalText":"見人弗能館，不問其所舍。","chunks":[["見人弗能館，不問其所舍。","zh-Hant"]]},{"id":"li-ji_ch-1_p-66_s-4","passageId":"li-ji_ch-1_p-66","order":4,"canonicalText":"賜人者不曰來取。","chunks":[["賜人者不曰來取。","zh-Hant"]]},{"id":"li-ji_ch-1_p-66_s-5","passageId":"li-ji_ch-1_p-66","order":5,"canonicalText":"與人者不問其所欲。","chunks":[["與人者不問其所欲。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-1","passageId":"li-ji_ch-1_p-67","order":1,"canonicalText":"適墓不登壟，助葬必執紼。","chunks":[["適墓不登壟，助葬必執紼。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-2","passageId":"li-ji_ch-1_p-67","order":2,"canonicalText":"臨喪不笑。","chunks":[["臨喪不笑。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-3","passageId":"li-ji_ch-1_p-67","order":3,"canonicalText":"揖人必違其位。","chunks":[["揖人必違其位。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-4","passageId":"li-ji_ch-1_p-67","order":4,"canonicalText":"望柩不歌。","chunks":[["望柩不歌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-5","passageId":"li-ji_ch-1_p-67","order":5,"canonicalText":"入臨不翔。","chunks":[["入臨不翔。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-6","passageId":"li-ji_ch-1_p-67","order":6,"canonicalText":"當食不嘆。","chunks":[["當食不嘆。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-7","passageId":"li-ji_ch-1_p-67","order":7,"canonicalText":"鄰有喪，舂不相。","chunks":[["鄰有喪，舂不相。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-8","passageId":"li-ji_ch-1_p-67","order":8,"canonicalText":"里有殯，不巷歌。","chunks":[["里有殯，不巷歌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-9","passageId":"li-ji_ch-1_p-67","order":9,"canonicalText":"適墓不歌。","chunks":[["適墓不歌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-10","passageId":"li-ji_ch-1_p-67","order":10,"canonicalText":"哭日不歌。","chunks":[["哭日不歌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-11","passageId":"li-ji_ch-1_p-67","order":11,"canonicalText":"送喪不由徑，送葬不辟涂潦。","chunks":[["送喪不由徑，送葬不辟涂潦。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-12","passageId":"li-ji_ch-1_p-67","order":12,"canonicalText":"臨喪則必有哀色，執紼不笑，臨樂不嘆；","chunks":[["臨喪則必有哀色，執紼不笑，臨樂不嘆；","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-13","passageId":"li-ji_ch-1_p-67","order":13,"canonicalText":"介胄，則有不可犯之色。","chunks":[["介胄，則有不可犯之色。","zh-Hant"]]},{"id":"li-ji_ch-1_p-67_s-14","passageId":"li-ji_ch-1_p-67","order":14,"canonicalText":"故君子戒慎，不失色於人。","chunks":[["故君子戒慎，不失色於人。","zh-Hant"]]},{"id":"li-ji_ch-1_p-68_s-1","passageId":"li-ji_ch-1_p-68","order":1,"canonicalText":"國君撫式，大夫下之。","chunks":[["國君撫式，大夫下之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-68_s-2","passageId":"li-ji_ch-1_p-68","order":2,"canonicalText":"大夫撫式，士下之。","chunks":[["大夫撫式，士下之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-68_s-3","passageId":"li-ji_ch-1_p-68","order":3,"canonicalText":"禮不下庶人，刑不上大夫。","chunks":[["禮不下庶人，刑不上大夫。","zh-Hant"]]},{"id":"li-ji_ch-1_p-68_s-4","passageId":"li-ji_ch-1_p-68","order":4,"canonicalText":"刑人不在君側。","chunks":[["刑人不在君側。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-1","passageId":"li-ji_ch-1_p-69","order":1,"canonicalText":"兵車不式。","chunks":[["兵車不式。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-2","passageId":"li-ji_ch-1_p-69","order":2,"canonicalText":"武車綏旌，德車結旌。","chunks":[["武車綏旌，德車結旌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-3","passageId":"li-ji_ch-1_p-69","order":3,"canonicalText":"史載筆，士載言。","chunks":[["史載筆，士載言。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-4","passageId":"li-ji_ch-1_p-69","order":4,"canonicalText":"前有水，則載青旌。","chunks":[["前有水，則載青旌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-5","passageId":"li-ji_ch-1_p-69","order":5,"canonicalText":"前有塵埃，則載鳴鳶。","chunks":[["前有塵埃，則載鳴鳶。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-6","passageId":"li-ji_ch-1_p-69","order":6,"canonicalText":"前有車騎，則載飛鴻。","chunks":[["前有車騎，則載飛鴻。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-7","passageId":"li-ji_ch-1_p-69","order":7,"canonicalText":"前有士師，則載虎皮。","chunks":[["前有士師，則載虎皮。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-8","passageId":"li-ji_ch-1_p-69","order":8,"canonicalText":"前有摯獸，則載貔貅。","chunks":[["前有摯獸，則載貔貅。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-9","passageId":"li-ji_ch-1_p-69","order":9,"canonicalText":"行：前朱鳥而後玄武，左青龍而右白虎。","chunks":[["行：前朱鳥而後玄武，左青龍而右白虎。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-10","passageId":"li-ji_ch-1_p-69","order":10,"canonicalText":"招搖在上，急繕其怒。","chunks":[["招搖在上，急繕其怒。","zh-Hant"]]},{"id":"li-ji_ch-1_p-69_s-11","passageId":"li-ji_ch-1_p-69","order":11,"canonicalText":"進退有度，左右有局，各司其局。","chunks":[["進退有度，左右有局，各司其局。","zh-Hant"]]},{"id":"li-ji_ch-1_p-70_s-1","passageId":"li-ji_ch-1_p-70","order":1,"canonicalText":"父之讎，弗與共戴天。","chunks":[["父之讎，弗與共戴天。","zh-Hant"]]},{"id":"li-ji_ch-1_p-70_s-2","passageId":"li-ji_ch-1_p-70","order":2,"canonicalText":"兄弟之讎不反兵。","chunks":[["兄弟之讎不反兵。","zh-Hant"]]},{"id":"li-ji_ch-1_p-70_s-3","passageId":"li-ji_ch-1_p-70","order":3,"canonicalText":"交游之讎不同國。","chunks":[["交游之讎不同國。","zh-Hant"]]},{"id":"li-ji_ch-1_p-71_s-1","passageId":"li-ji_ch-1_p-71","order":1,"canonicalText":"四郊多壘，此卿大夫之辱也。","chunks":[["四郊多壘，此卿大夫之辱也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-71_s-2","passageId":"li-ji_ch-1_p-71","order":2,"canonicalText":"地廣大，荒而不治，此亦士之辱也。","chunks":[["地廣大，荒而不治，此亦士之辱也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-72_s-1","passageId":"li-ji_ch-1_p-72","order":1,"canonicalText":"臨祭不惰。","chunks":[["臨祭不惰。","zh-Hant"]]},{"id":"li-ji_ch-1_p-72_s-2","passageId":"li-ji_ch-1_p-72","order":2,"canonicalText":"祭服敝則焚之，祭器敝則埋之，龜策敝則埋之，牲死則埋之。","chunks":[["祭服敝則焚之，祭器敝則埋之，龜策敝則埋之，牲死則埋之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-72_s-3","passageId":"li-ji_ch-1_p-72","order":3,"canonicalText":"凡祭於公者，必自徹其俎。","chunks":[["凡祭於公者，必自徹其俎。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-1","passageId":"li-ji_ch-1_p-73","order":1,"canonicalText":"卒哭乃諱。","chunks":[["卒哭乃諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-2","passageId":"li-ji_ch-1_p-73","order":2,"canonicalText":"禮，不諱嫌名。","chunks":[["禮，不諱嫌名。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-3","passageId":"li-ji_ch-1_p-73","order":3,"canonicalText":"二名不偏諱。","chunks":[["二名不偏諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-4","passageId":"li-ji_ch-1_p-73","order":4,"canonicalText":"逮事父母，則諱王父母；","chunks":[["逮事父母，則諱王父母；","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-5","passageId":"li-ji_ch-1_p-73","order":5,"canonicalText":"不逮事父母，則不諱王父母。","chunks":[["不逮事父母，則不諱王父母。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-6","passageId":"li-ji_ch-1_p-73","order":6,"canonicalText":"君所無私諱，大夫之所有公諱。","chunks":[["君所無私諱，大夫之所有公諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-7","passageId":"li-ji_ch-1_p-73","order":7,"canonicalText":"《詩》、《書》不諱，臨文不諱。","chunks":[["《詩》、《書》不諱，臨文不諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-8","passageId":"li-ji_ch-1_p-73","order":8,"canonicalText":"廟中不諱。","chunks":[["廟中不諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-9","passageId":"li-ji_ch-1_p-73","order":9,"canonicalText":"夫人之諱，雖質君之前，臣不諱也；","chunks":[["夫人之諱，雖質君之前，臣不諱也；","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-10","passageId":"li-ji_ch-1_p-73","order":10,"canonicalText":"婦諱不出門。","chunks":[["婦諱不出門。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-11","passageId":"li-ji_ch-1_p-73","order":11,"canonicalText":"大功小功不諱。","chunks":[["大功小功不諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-73_s-12","passageId":"li-ji_ch-1_p-73","order":12,"canonicalText":"入竟而問禁，入國而問俗，入門而問諱。","chunks":[["入竟而問禁，入國而問俗，入門而問諱。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-1","passageId":"li-ji_ch-1_p-74","order":1,"canonicalText":"外事以剛日，內事以柔日。","chunks":[["外事以剛日，內事以柔日。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-2","passageId":"li-ji_ch-1_p-74","order":2,"canonicalText":"凡卜筮日：旬之外曰遠某日，旬之內曰近某日。","chunks":[["凡卜筮日：旬之外曰遠某日，旬之內曰近某日。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-3","passageId":"li-ji_ch-1_p-74","order":3,"canonicalText":"喪事先遠日，吉事先近日。","chunks":[["喪事先遠日，吉事先近日。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-4","passageId":"li-ji_ch-1_p-74","order":4,"canonicalText":"曰：「為日，假爾泰龜有常，假爾泰筮有常。","chunks":[["曰：「為日，假爾泰龜有常，假爾泰筮有常。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-5","passageId":"li-ji_ch-1_p-74","order":5,"canonicalText":"」卜筮不過三，卜筮不相襲。","chunks":[["」卜筮不過三，卜筮不相襲。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-6","passageId":"li-ji_ch-1_p-74","order":6,"canonicalText":"龜為卜，策為筮，卜筮者，先聖王之所以使民信時日、敬鬼神、畏法令也；","chunks":[["龜為卜，策為筮，卜筮者，先聖王之所以使民信時日、敬鬼神、畏法令也；","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-7","passageId":"li-ji_ch-1_p-74","order":7,"canonicalText":"所以使民決嫌疑、定猶與也。","chunks":[["所以使民決嫌疑、定猶與也。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-8","passageId":"li-ji_ch-1_p-74","order":8,"canonicalText":"故曰：「疑而筮之，則弗非也；","chunks":[["故曰：「疑而筮之，則弗非也；","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-9","passageId":"li-ji_ch-1_p-74","order":9,"canonicalText":"日而行事，則必踐之。","chunks":[["日而行事，則必踐之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-74_s-10","passageId":"li-ji_ch-1_p-74","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-1","passageId":"li-ji_ch-1_p-75","order":1,"canonicalText":"君車將駕，則仆執策立於馬前。","chunks":[["君車將駕，則仆執策立於馬前。","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-2","passageId":"li-ji_ch-1_p-75","order":2,"canonicalText":"已駕，仆展軨、效駕，奮衣由右上取貳綏，跪乘，執策分轡，驅之五步而立。","chunks":[["已駕，仆展軨、效駕，奮衣由右上取貳綏，跪乘，執策分轡，驅之五步而立。","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-3","passageId":"li-ji_ch-1_p-75","order":3,"canonicalText":"君出就車，則仆并轡授綏。","chunks":[["君出就車，則仆并轡授綏。","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-4","passageId":"li-ji_ch-1_p-75","order":4,"canonicalText":"左右攘辟，車驅而騶。","chunks":[["左右攘辟，車驅而騶。","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-5","passageId":"li-ji_ch-1_p-75","order":5,"canonicalText":"至于大門，君撫仆之手而顧，命車右就車；","chunks":[["至于大門，君撫仆之手而顧，命車右就車；","zh-Hant"]]},{"id":"li-ji_ch-1_p-75_s-6","passageId":"li-ji_ch-1_p-75","order":6,"canonicalText":"門閭溝渠，必步。","chunks":[["門閭溝渠，必步。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-1","passageId":"li-ji_ch-1_p-76","order":1,"canonicalText":"凡仆人之禮，必授人綏。","chunks":[["凡仆人之禮，必授人綏。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-2","passageId":"li-ji_ch-1_p-76","order":2,"canonicalText":"若仆者降等，則受；","chunks":[["若仆者降等，則受；","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-3","passageId":"li-ji_ch-1_p-76","order":3,"canonicalText":"不然，則否。","chunks":[["不然，則否。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-4","passageId":"li-ji_ch-1_p-76","order":4,"canonicalText":"若仆者降等，則撫仆之手；","chunks":[["若仆者降等，則撫仆之手；","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-5","passageId":"li-ji_ch-1_p-76","order":5,"canonicalText":"不然，則自下拘之。","chunks":[["不然，則自下拘之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-6","passageId":"li-ji_ch-1_p-76","order":6,"canonicalText":"客車不入大門。","chunks":[["客車不入大門。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-7","passageId":"li-ji_ch-1_p-76","order":7,"canonicalText":"婦人不立乘。","chunks":[["婦人不立乘。","zh-Hant"]]},{"id":"li-ji_ch-1_p-76_s-8","passageId":"li-ji_ch-1_p-76","order":8,"canonicalText":"犬馬不上於堂。","chunks":[["犬馬不上於堂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-1","passageId":"li-ji_ch-1_p-77","order":1,"canonicalText":"故君子式黃髮，下卿位，入國不馳，入里必式。","chunks":[["故君子式黃髮，下卿位，入國不馳，入里必式。","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-2","passageId":"li-ji_ch-1_p-77","order":2,"canonicalText":"君命召，雖賤人，大夫士必自御之。","chunks":[["君命召，雖賤人，大夫士必自御之。","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-3","passageId":"li-ji_ch-1_p-77","order":3,"canonicalText":"介者不拜，為其拜而蓌拜。","chunks":[["介者不拜，為其拜而蓌拜。","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-4","passageId":"li-ji_ch-1_p-77","order":4,"canonicalText":"祥車曠左，乘君之乘車不敢曠左；","chunks":[["祥車曠左，乘君之乘車不敢曠左；","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-5","passageId":"li-ji_ch-1_p-77","order":5,"canonicalText":"左必式。","chunks":[["左必式。","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-6","passageId":"li-ji_ch-1_p-77","order":6,"canonicalText":"仆御、婦人則進左手，後右手；","chunks":[["仆御、婦人則進左手，後右手；","zh-Hant"]]},{"id":"li-ji_ch-1_p-77_s-7","passageId":"li-ji_ch-1_p-77","order":7,"canonicalText":"御國君，則進右手、後左手而俯。","chunks":[["御國君，則進右手、後左手而俯。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-1","passageId":"li-ji_ch-1_p-78","order":1,"canonicalText":"國君不乘奇車。","chunks":[["國君不乘奇車。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-2","passageId":"li-ji_ch-1_p-78","order":2,"canonicalText":"車上不廣咳，不妄指。","chunks":[["車上不廣咳，不妄指。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-3","passageId":"li-ji_ch-1_p-78","order":3,"canonicalText":"立視五巂，式視馬尾，顧不過轂。","chunks":[["立視五巂，式視馬尾，顧不過轂。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-4","passageId":"li-ji_ch-1_p-78","order":4,"canonicalText":"國中以策彗恤勿驅。","chunks":[["國中以策彗恤勿驅。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-5","passageId":"li-ji_ch-1_p-78","order":5,"canonicalText":"塵不出軌。","chunks":[["塵不出軌。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-6","passageId":"li-ji_ch-1_p-78","order":6,"canonicalText":"國君下齊牛，式宗廟。","chunks":[["國君下齊牛，式宗廟。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-7","passageId":"li-ji_ch-1_p-78","order":7,"canonicalText":"大夫士下公門，式路馬。","chunks":[["大夫士下公門，式路馬。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-8","passageId":"li-ji_ch-1_p-78","order":8,"canonicalText":"乘路馬，必朝服載鞭策，不敢授綏，左必式。","chunks":[["乘路馬，必朝服載鞭策，不敢授綏，左必式。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-9","passageId":"li-ji_ch-1_p-78","order":9,"canonicalText":"步路馬，必中道。","chunks":[["步路馬，必中道。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-10","passageId":"li-ji_ch-1_p-78","order":10,"canonicalText":"以足蹙路馬芻，有誅。","chunks":[["以足蹙路馬芻，有誅。","zh-Hant"]]},{"id":"li-ji_ch-1_p-78_s-11","passageId":"li-ji_ch-1_p-78","order":11,"canonicalText":"齒路馬，有誅。","chunks":[["齒路馬，有誅。","zh-Hant"]]},{"id":"li-ji_ch-2_p-1_s-1","passageId":"li-ji_ch-2_p-1","order":1,"canonicalText":"凡奉者當心，提者當帶。","chunks":[["凡奉者當心，提者當帶。","zh-Hant"]]},{"id":"li-ji_ch-2_p-1_s-2","passageId":"li-ji_ch-2_p-1","order":2,"canonicalText":"執天子之器則上衡，國君則平衡，大夫則綏之，士則提之。","chunks":[["執天子之器則上衡，國君則平衡，大夫則綏之，士則提之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-2_s-1","passageId":"li-ji_ch-2_p-2","order":1,"canonicalText":"凡執主器，執輕如不克。","chunks":[["凡執主器，執輕如不克。","zh-Hant"]]},{"id":"li-ji_ch-2_p-2_s-2","passageId":"li-ji_ch-2_p-2","order":2,"canonicalText":"執主器，操幣圭璧，則尚左手，行不舉足，車輪曳踵。","chunks":[["執主器，操幣圭璧，則尚左手，行不舉足，車輪曳踵。","zh-Hant"]]},{"id":"li-ji_ch-2_p-3_s-1","passageId":"li-ji_ch-2_p-3","order":1,"canonicalText":"立則磬折垂佩。","chunks":[["立則磬折垂佩。","zh-Hant"]]},{"id":"li-ji_ch-2_p-3_s-2","passageId":"li-ji_ch-2_p-3","order":2,"canonicalText":"主佩倚，則臣佩垂。","chunks":[["主佩倚，則臣佩垂。","zh-Hant"]]},{"id":"li-ji_ch-2_p-3_s-3","passageId":"li-ji_ch-2_p-3","order":3,"canonicalText":"主佩垂，則臣佩委。","chunks":[["主佩垂，則臣佩委。","zh-Hant"]]},{"id":"li-ji_ch-2_p-3_s-4","passageId":"li-ji_ch-2_p-3","order":4,"canonicalText":"執玉，其有藉者則裼；","chunks":[["執玉，其有藉者則裼；","zh-Hant"]]},{"id":"li-ji_ch-2_p-3_s-5","passageId":"li-ji_ch-2_p-3","order":5,"canonicalText":"無藉者則襲。","chunks":[["無藉者則襲。","zh-Hant"]]},{"id":"li-ji_ch-2_p-4_s-1","passageId":"li-ji_ch-2_p-4","order":1,"canonicalText":"國君不名卿老世婦，大夫不名世臣侄娣，士不名家相長妾。","chunks":[["國君不名卿老世婦，大夫不名世臣侄娣，士不名家相長妾。","zh-Hant"]]},{"id":"li-ji_ch-2_p-4_s-2","passageId":"li-ji_ch-2_p-4","order":2,"canonicalText":"君大夫之子，不敢自稱曰「余小子」；","chunks":[["君大夫之子，不敢自稱曰「余小子」；","zh-Hant"]]},{"id":"li-ji_ch-2_p-4_s-3","passageId":"li-ji_ch-2_p-4","order":3,"canonicalText":"大夫士之子，不敢自稱曰「嗣子某」，不敢與世子同名。","chunks":[["大夫士之子，不敢自稱曰「嗣子某」，不敢與世子同名。","zh-Hant"]]},{"id":"li-ji_ch-2_p-5_s-1","passageId":"li-ji_ch-2_p-5","order":1,"canonicalText":"君使士射，不能，則辭以疾；","chunks":[["君使士射，不能，則辭以疾；","zh-Hant"]]},{"id":"li-ji_ch-2_p-5_s-2","passageId":"li-ji_ch-2_p-5","order":2,"canonicalText":"言曰：「某有負薪之憂。","chunks":[["言曰：「某有負薪之憂。","zh-Hant"]]},{"id":"li-ji_ch-2_p-5_s-3","passageId":"li-ji_ch-2_p-5","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-2_p-6_s-1","passageId":"li-ji_ch-2_p-6","order":1,"canonicalText":"侍於君子，不顧望而對，非禮也。","chunks":[["侍於君子，不顧望而對，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-7_s-1","passageId":"li-ji_ch-2_p-7","order":1,"canonicalText":"君子行禮，不求變俗。","chunks":[["君子行禮，不求變俗。","zh-Hant"]]},{"id":"li-ji_ch-2_p-7_s-2","passageId":"li-ji_ch-2_p-7","order":2,"canonicalText":"祭祀之禮，居喪之服，哭泣之位，皆如其國之故，謹修其法而審行之。","chunks":[["祭祀之禮，居喪之服，哭泣之位，皆如其國之故，謹修其法而審行之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-7_s-3","passageId":"li-ji_ch-2_p-7","order":3,"canonicalText":"去國三世，爵祿有列於朝，出入有詔於國，若兄弟宗族猶存，則反告於宗後；","chunks":[["去國三世，爵祿有列於朝，出入有詔於國，若兄弟宗族猶存，則反告於宗後；","zh-Hant"]]},{"id":"li-ji_ch-2_p-7_s-4","passageId":"li-ji_ch-2_p-7","order":4,"canonicalText":"去國三世，爵祿無列於朝，出入無詔於國，唯興之日，從新國之法。","chunks":[["去國三世，爵祿無列於朝，出入無詔於國，唯興之日，從新國之法。","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-1","passageId":"li-ji_ch-2_p-8","order":1,"canonicalText":"君子已孤不更名。","chunks":[["君子已孤不更名。","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-2","passageId":"li-ji_ch-2_p-8","order":2,"canonicalText":"已孤暴貴，不為父作謚。","chunks":[["已孤暴貴，不為父作謚。","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-3","passageId":"li-ji_ch-2_p-8","order":3,"canonicalText":"居喪，未葬，讀喪禮；","chunks":[["居喪，未葬，讀喪禮；","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-4","passageId":"li-ji_ch-2_p-8","order":4,"canonicalText":"既葬，讀祭禮；","chunks":[["既葬，讀祭禮；","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-5","passageId":"li-ji_ch-2_p-8","order":5,"canonicalText":"喪復常，讀樂章。","chunks":[["喪復常，讀樂章。","zh-Hant"]]},{"id":"li-ji_ch-2_p-8_s-6","passageId":"li-ji_ch-2_p-8","order":6,"canonicalText":"居喪不言樂，祭事不言凶，公庭不言婦女。","chunks":[["居喪不言樂，祭事不言凶，公庭不言婦女。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-1","passageId":"li-ji_ch-2_p-9","order":1,"canonicalText":"振書、端書於君前，有誅。","chunks":[["振書、端書於君前，有誅。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-2","passageId":"li-ji_ch-2_p-9","order":2,"canonicalText":"倒策側龜於君前，有誅。","chunks":[["倒策側龜於君前，有誅。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-3","passageId":"li-ji_ch-2_p-9","order":3,"canonicalText":"龜策、几杖、席蓋、重素、袗絺綌，不入公門。","chunks":[["龜策、几杖、席蓋、重素、袗絺綌，不入公門。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-4","passageId":"li-ji_ch-2_p-9","order":4,"canonicalText":"苞屨、扱衽、厭冠，不入公門。","chunks":[["苞屨、扱衽、厭冠，不入公門。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-5","passageId":"li-ji_ch-2_p-9","order":5,"canonicalText":"書方、衰、凶器，不以告，不入公門。","chunks":[["書方、衰、凶器，不以告，不入公門。","zh-Hant"]]},{"id":"li-ji_ch-2_p-9_s-6","passageId":"li-ji_ch-2_p-9","order":6,"canonicalText":"公事不私議。","chunks":[["公事不私議。","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-1","passageId":"li-ji_ch-2_p-10","order":1,"canonicalText":"君子將營宮室：宗廟為先，廄庫為次，居室為後。","chunks":[["君子將營宮室：宗廟為先，廄庫為次，居室為後。","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-2","passageId":"li-ji_ch-2_p-10","order":2,"canonicalText":"凡家造：祭器為先，犧賦為次，養器為後。","chunks":[["凡家造：祭器為先，犧賦為次，養器為後。","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-3","passageId":"li-ji_ch-2_p-10","order":3,"canonicalText":"無田祿者不設祭器；","chunks":[["無田祿者不設祭器；","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-4","passageId":"li-ji_ch-2_p-10","order":4,"canonicalText":"有田祿者，先為祭服。","chunks":[["有田祿者，先為祭服。","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-5","passageId":"li-ji_ch-2_p-10","order":5,"canonicalText":"君子雖貧，不粥祭器；","chunks":[["君子雖貧，不粥祭器；","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-6","passageId":"li-ji_ch-2_p-10","order":6,"canonicalText":"雖寒，不衣祭服；","chunks":[["雖寒，不衣祭服；","zh-Hant"]]},{"id":"li-ji_ch-2_p-10_s-7","passageId":"li-ji_ch-2_p-10","order":7,"canonicalText":"為宮室，不斬於丘木。","chunks":[["為宮室，不斬於丘木。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-1","passageId":"li-ji_ch-2_p-11","order":1,"canonicalText":"大夫、士去國，祭器不逾竟。","chunks":[["大夫、士去國，祭器不逾竟。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-2","passageId":"li-ji_ch-2_p-11","order":2,"canonicalText":"大夫寓祭器於大夫，士寓祭器於士。","chunks":[["大夫寓祭器於大夫，士寓祭器於士。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-3","passageId":"li-ji_ch-2_p-11","order":3,"canonicalText":"大夫、士去國：逾竟，為壇位鄉國而哭。","chunks":[["大夫、士去國：逾竟，為壇位鄉國而哭。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-4","passageId":"li-ji_ch-2_p-11","order":4,"canonicalText":"素衣，素裳，素冠，徹緣，鞮屨，素冪，乘髦馬。","chunks":[["素衣，素裳，素冠，徹緣，鞮屨，素冪，乘髦馬。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-5","passageId":"li-ji_ch-2_p-11","order":5,"canonicalText":"不蚤鬋。","chunks":[["不蚤鬋。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-6","passageId":"li-ji_ch-2_p-11","order":6,"canonicalText":"不祭食，不說人以無罪；","chunks":[["不祭食，不說人以無罪；","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-7","passageId":"li-ji_ch-2_p-11","order":7,"canonicalText":"婦人不當御。","chunks":[["婦人不當御。","zh-Hant"]]},{"id":"li-ji_ch-2_p-11_s-8","passageId":"li-ji_ch-2_p-11","order":8,"canonicalText":"三月而復服。","chunks":[["三月而復服。","zh-Hant"]]},{"id":"li-ji_ch-2_p-12_s-1","passageId":"li-ji_ch-2_p-12","order":1,"canonicalText":"大夫、士見於國君，君若勞之，則還辟，再拜稽首；","chunks":[["大夫、士見於國君，君若勞之，則還辟，再拜稽首；","zh-Hant"]]},{"id":"li-ji_ch-2_p-12_s-2","passageId":"li-ji_ch-2_p-12","order":2,"canonicalText":"君若迎拜，則還辟，不敢答拜。","chunks":[["君若迎拜，則還辟，不敢答拜。","zh-Hant"]]},{"id":"li-ji_ch-2_p-12_s-3","passageId":"li-ji_ch-2_p-12","order":3,"canonicalText":"大夫、士相見，雖貴賤不敵，主人敬客，則先拜客；","chunks":[["大夫、士相見，雖貴賤不敵，主人敬客，則先拜客；","zh-Hant"]]},{"id":"li-ji_ch-2_p-12_s-4","passageId":"li-ji_ch-2_p-12","order":4,"canonicalText":"客敬主人，則先拜主人。","chunks":[["客敬主人，則先拜主人。","zh-Hant"]]},{"id":"li-ji_ch-2_p-12_s-5","passageId":"li-ji_ch-2_p-12","order":5,"canonicalText":"凡非吊喪、非見國君，無不答拜者。","chunks":[["凡非吊喪、非見國君，無不答拜者。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-1","passageId":"li-ji_ch-2_p-13","order":1,"canonicalText":"大夫見於國君，國君拜其辱。","chunks":[["大夫見於國君，國君拜其辱。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-2","passageId":"li-ji_ch-2_p-13","order":2,"canonicalText":"士見於大夫，大夫拜其辱。","chunks":[["士見於大夫，大夫拜其辱。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-3","passageId":"li-ji_ch-2_p-13","order":3,"canonicalText":"同國始相見，主人拜其辱。","chunks":[["同國始相見，主人拜其辱。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-4","passageId":"li-ji_ch-2_p-13","order":4,"canonicalText":"君於士，不答拜也；","chunks":[["君於士，不答拜也；","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-5","passageId":"li-ji_ch-2_p-13","order":5,"canonicalText":"非其臣，則答拜之。","chunks":[["非其臣，則答拜之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-6","passageId":"li-ji_ch-2_p-13","order":6,"canonicalText":"大夫於其臣，雖賤，必答拜之。","chunks":[["大夫於其臣，雖賤，必答拜之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-13_s-7","passageId":"li-ji_ch-2_p-13","order":7,"canonicalText":"男女相答拜也。","chunks":[["男女相答拜也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-14_s-1","passageId":"li-ji_ch-2_p-14","order":1,"canonicalText":"國君春田不圍澤；","chunks":[["國君春田不圍澤；","zh-Hant"]]},{"id":"li-ji_ch-2_p-14_s-2","passageId":"li-ji_ch-2_p-14","order":2,"canonicalText":"大夫不掩群，士不取麑卵。","chunks":[["大夫不掩群，士不取麑卵。","zh-Hant"]]},{"id":"li-ji_ch-2_p-15_s-1","passageId":"li-ji_ch-2_p-15","order":1,"canonicalText":"歲凶，年穀不登，君膳不祭肺，馬不食穀，馳道不除，祭事不縣。","chunks":[["歲凶，年穀不登，君膳不祭肺，馬不食穀，馳道不除，祭事不縣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-15_s-2","passageId":"li-ji_ch-2_p-15","order":2,"canonicalText":"大夫不食粱，士飲酒不樂。","chunks":[["大夫不食粱，士飲酒不樂。","zh-Hant"]]},{"id":"li-ji_ch-2_p-16_s-1","passageId":"li-ji_ch-2_p-16","order":1,"canonicalText":"君無故，玉不去身；","chunks":[["君無故，玉不去身；","zh-Hant"]]},{"id":"li-ji_ch-2_p-16_s-2","passageId":"li-ji_ch-2_p-16","order":2,"canonicalText":"大夫無故不徹縣，士無故不徹琴瑟。","chunks":[["大夫無故不徹縣，士無故不徹琴瑟。","zh-Hant"]]},{"id":"li-ji_ch-2_p-17_s-1","passageId":"li-ji_ch-2_p-17","order":1,"canonicalText":"士有獻於國君，他日，君問之曰：「安取彼？","chunks":[["士有獻於國君，他日，君問之曰：「安取彼？","zh-Hant"]]},{"id":"li-ji_ch-2_p-17_s-2","passageId":"li-ji_ch-2_p-17","order":2,"canonicalText":"」再拜稽首而後對。","chunks":[["」再拜稽首而後對。","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-1","passageId":"li-ji_ch-2_p-18","order":1,"canonicalText":"大夫私行出疆，必請。","chunks":[["大夫私行出疆，必請。","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-2","passageId":"li-ji_ch-2_p-18","order":2,"canonicalText":"反，必有獻。","chunks":[["反，必有獻。","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-3","passageId":"li-ji_ch-2_p-18","order":3,"canonicalText":"士私行出疆，必請；","chunks":[["士私行出疆，必請；","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-4","passageId":"li-ji_ch-2_p-18","order":4,"canonicalText":"反，必告。","chunks":[["反，必告。","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-5","passageId":"li-ji_ch-2_p-18","order":5,"canonicalText":"君勞之，則拜；","chunks":[["君勞之，則拜；","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-6","passageId":"li-ji_ch-2_p-18","order":6,"canonicalText":"問其行，拜而後對。","chunks":[["問其行，拜而後對。","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-7","passageId":"li-ji_ch-2_p-18","order":7,"canonicalText":"國君去其國，止之曰：「奈何去社稷也！","chunks":[["國君去其國，止之曰：「奈何去社稷也！","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-8","passageId":"li-ji_ch-2_p-18","order":8,"canonicalText":"」大夫，曰：「奈何去宗廟也！","chunks":[["」大夫，曰：「奈何去宗廟也！","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-9","passageId":"li-ji_ch-2_p-18","order":9,"canonicalText":"」士，曰：「奈何去墳墓也！","chunks":[["」士，曰：「奈何去墳墓也！","zh-Hant"]]},{"id":"li-ji_ch-2_p-18_s-10","passageId":"li-ji_ch-2_p-18","order":10,"canonicalText":"」國君死社稷，大夫死眾，士死制。","chunks":[["」國君死社稷，大夫死眾，士死制。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-1","passageId":"li-ji_ch-2_p-19","order":1,"canonicalText":"君天下，曰天子。","chunks":[["君天下，曰天子。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-2","passageId":"li-ji_ch-2_p-19","order":2,"canonicalText":"朝諸侯，分職授政任功，曰予一人。","chunks":[["朝諸侯，分職授政任功，曰予一人。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-3","passageId":"li-ji_ch-2_p-19","order":3,"canonicalText":"踐阼臨祭祀：內事曰孝王某，外事曰嗣王某。","chunks":[["踐阼臨祭祀：內事曰孝王某，外事曰嗣王某。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-4","passageId":"li-ji_ch-2_p-19","order":4,"canonicalText":"臨諸侯，畛於鬼神，曰有天王某甫。","chunks":[["臨諸侯，畛於鬼神，曰有天王某甫。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-5","passageId":"li-ji_ch-2_p-19","order":5,"canonicalText":"崩，曰天王崩。","chunks":[["崩，曰天王崩。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-6","passageId":"li-ji_ch-2_p-19","order":6,"canonicalText":"復，曰天子復矣。","chunks":[["復，曰天子復矣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-7","passageId":"li-ji_ch-2_p-19","order":7,"canonicalText":"告喪，曰天王登假。","chunks":[["告喪，曰天王登假。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-8","passageId":"li-ji_ch-2_p-19","order":8,"canonicalText":"措之廟，立之主，曰帝。","chunks":[["措之廟，立之主，曰帝。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-9","passageId":"li-ji_ch-2_p-19","order":9,"canonicalText":"天子未除喪，曰予小子。","chunks":[["天子未除喪，曰予小子。","zh-Hant"]]},{"id":"li-ji_ch-2_p-19_s-10","passageId":"li-ji_ch-2_p-19","order":10,"canonicalText":"生名之，死亦名之。","chunks":[["生名之，死亦名之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-20_s-1","passageId":"li-ji_ch-2_p-20","order":1,"canonicalText":"天子有后，有夫人，有世婦，有嬪，有妻，有妾。","chunks":[["天子有后，有夫人，有世婦，有嬪，有妻，有妾。","zh-Hant"]]},{"id":"li-ji_ch-2_p-21_s-1","passageId":"li-ji_ch-2_p-21","order":1,"canonicalText":"天子建天官，先六大：曰大宰、大宗、大史、大祝、大士、大卜，典司六典。","chunks":[["天子建天官，先六大：曰大宰、大宗、大史、大祝、大士、大卜，典司六典。","zh-Hant"]]},{"id":"li-ji_ch-2_p-22_s-1","passageId":"li-ji_ch-2_p-22","order":1,"canonicalText":"天子之五官：曰司徒、司馬、司空、司士、司寇，典司五眾。","chunks":[["天子之五官：曰司徒、司馬、司空、司士、司寇，典司五眾。","zh-Hant"]]},{"id":"li-ji_ch-2_p-23_s-1","passageId":"li-ji_ch-2_p-23","order":1,"canonicalText":"天子之六府：曰司土、司木、司水、司草、司器、司貨，典司六職。","chunks":[["天子之六府：曰司土、司木、司水、司草、司器、司貨，典司六職。","zh-Hant"]]},{"id":"li-ji_ch-2_p-24_s-1","passageId":"li-ji_ch-2_p-24","order":1,"canonicalText":"天子之六工：曰土工、金工、石工、木工、獸工、草工，典制六材。","chunks":[["天子之六工：曰土工、金工、石工、木工、獸工、草工，典制六材。","zh-Hant"]]},{"id":"li-ji_ch-2_p-24_s-2","passageId":"li-ji_ch-2_p-24","order":2,"canonicalText":"五官致貢，曰享。","chunks":[["五官致貢，曰享。","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-1","passageId":"li-ji_ch-2_p-25","order":1,"canonicalText":"五官之長，曰伯：是職方。","chunks":[["五官之長，曰伯：是職方。","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-2","passageId":"li-ji_ch-2_p-25","order":2,"canonicalText":"其擯於天子也，曰天子之吏。","chunks":[["其擯於天子也，曰天子之吏。","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-3","passageId":"li-ji_ch-2_p-25","order":3,"canonicalText":"天子同姓，謂之伯父；","chunks":[["天子同姓，謂之伯父；","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-4","passageId":"li-ji_ch-2_p-25","order":4,"canonicalText":"異姓，謂之伯舅。","chunks":[["異姓，謂之伯舅。","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-5","passageId":"li-ji_ch-2_p-25","order":5,"canonicalText":"自稱於諸侯，曰天子之老，於外曰公；","chunks":[["自稱於諸侯，曰天子之老，於外曰公；","zh-Hant"]]},{"id":"li-ji_ch-2_p-25_s-6","passageId":"li-ji_ch-2_p-25","order":6,"canonicalText":"於其國曰君。","chunks":[["於其國曰君。","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-1","passageId":"li-ji_ch-2_p-26","order":1,"canonicalText":"九州之長入天子之國，曰牧。","chunks":[["九州之長入天子之國，曰牧。","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-2","passageId":"li-ji_ch-2_p-26","order":2,"canonicalText":"天子同姓，謂之叔父；","chunks":[["天子同姓，謂之叔父；","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-3","passageId":"li-ji_ch-2_p-26","order":3,"canonicalText":"異姓，謂之叔舅；","chunks":[["異姓，謂之叔舅；","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-4","passageId":"li-ji_ch-2_p-26","order":4,"canonicalText":"於外曰侯，於其國曰君。","chunks":[["於外曰侯，於其國曰君。","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-5","passageId":"li-ji_ch-2_p-26","order":5,"canonicalText":"其在東夷、北狄、西戎、南蠻，雖大，曰子。","chunks":[["其在東夷、北狄、西戎、南蠻，雖大，曰子。","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-6","passageId":"li-ji_ch-2_p-26","order":6,"canonicalText":"於內自稱曰不穀，於外自稱曰王老。","chunks":[["於內自稱曰不穀，於外自稱曰王老。","zh-Hant"]]},{"id":"li-ji_ch-2_p-26_s-7","passageId":"li-ji_ch-2_p-26","order":7,"canonicalText":"庶方小侯，入天子之國，曰某人，於外曰子，自稱曰孤。","chunks":[["庶方小侯，入天子之國，曰某人，於外曰子，自稱曰孤。","zh-Hant"]]},{"id":"li-ji_ch-2_p-27_s-1","passageId":"li-ji_ch-2_p-27","order":1,"canonicalText":"天子當依而立，諸侯北面而見天子，曰覲。","chunks":[["天子當依而立，諸侯北面而見天子，曰覲。","zh-Hant"]]},{"id":"li-ji_ch-2_p-27_s-2","passageId":"li-ji_ch-2_p-27","order":2,"canonicalText":"天子當寧而立，諸公東面、諸侯西面，曰朝。","chunks":[["天子當寧而立，諸公東面、諸侯西面，曰朝。","zh-Hant"]]},{"id":"li-ji_ch-2_p-28_s-1","passageId":"li-ji_ch-2_p-28","order":1,"canonicalText":"諸侯未及期相見曰遇，相見於卻地曰會。","chunks":[["諸侯未及期相見曰遇，相見於卻地曰會。","zh-Hant"]]},{"id":"li-ji_ch-2_p-28_s-2","passageId":"li-ji_ch-2_p-28","order":2,"canonicalText":"諸侯使大夫問於諸侯曰聘，約信曰誓，蒞牲曰盟。","chunks":[["諸侯使大夫問於諸侯曰聘，約信曰誓，蒞牲曰盟。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-1","passageId":"li-ji_ch-2_p-29","order":1,"canonicalText":"諸侯見天子曰臣某、侯某；","chunks":[["諸侯見天子曰臣某、侯某；","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-2","passageId":"li-ji_ch-2_p-29","order":2,"canonicalText":"其與民言，自稱曰寡人；","chunks":[["其與民言，自稱曰寡人；","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-3","passageId":"li-ji_ch-2_p-29","order":3,"canonicalText":"其在凶服，曰適子孤。","chunks":[["其在凶服，曰適子孤。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-4","passageId":"li-ji_ch-2_p-29","order":4,"canonicalText":"臨祭祀，內事曰孝子某侯某，外事曰曾孫某侯某。","chunks":[["臨祭祀，內事曰孝子某侯某，外事曰曾孫某侯某。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-5","passageId":"li-ji_ch-2_p-29","order":5,"canonicalText":"死曰薨，復曰某甫復矣。","chunks":[["死曰薨，復曰某甫復矣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-6","passageId":"li-ji_ch-2_p-29","order":6,"canonicalText":"既葬見天子曰類見。","chunks":[["既葬見天子曰類見。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-7","passageId":"li-ji_ch-2_p-29","order":7,"canonicalText":"言謚曰類。","chunks":[["言謚曰類。","zh-Hant"]]},{"id":"li-ji_ch-2_p-29_s-8","passageId":"li-ji_ch-2_p-29","order":8,"canonicalText":"諸侯使人使於諸侯，使者自稱曰寡君之老。","chunks":[["諸侯使人使於諸侯，使者自稱曰寡君之老。","zh-Hant"]]},{"id":"li-ji_ch-2_p-30_s-1","passageId":"li-ji_ch-2_p-30","order":1,"canonicalText":"天子穆穆，諸侯皇皇，大夫濟濟，士蹌蹌，庶人僬僬。","chunks":[["天子穆穆，諸侯皇皇，大夫濟濟，士蹌蹌，庶人僬僬。","zh-Hant"]]},{"id":"li-ji_ch-2_p-31_s-1","passageId":"li-ji_ch-2_p-31","order":1,"canonicalText":"天子之妃曰后，諸侯曰夫人，大夫曰孺人，士曰婦人，庶人曰妻。","chunks":[["天子之妃曰后，諸侯曰夫人，大夫曰孺人，士曰婦人，庶人曰妻。","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-1","passageId":"li-ji_ch-2_p-32","order":1,"canonicalText":"公侯有夫人，有世婦，有妻，有妾。","chunks":[["公侯有夫人，有世婦，有妻，有妾。","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-2","passageId":"li-ji_ch-2_p-32","order":2,"canonicalText":"夫人自稱於天子，曰老婦；","chunks":[["夫人自稱於天子，曰老婦；","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-3","passageId":"li-ji_ch-2_p-32","order":3,"canonicalText":"自稱於諸侯，曰寡小君；","chunks":[["自稱於諸侯，曰寡小君；","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-4","passageId":"li-ji_ch-2_p-32","order":4,"canonicalText":"自稱於其君，曰小童。","chunks":[["自稱於其君，曰小童。","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-5","passageId":"li-ji_ch-2_p-32","order":5,"canonicalText":"自世婦以下，自稱曰婢子。","chunks":[["自世婦以下，自稱曰婢子。","zh-Hant"]]},{"id":"li-ji_ch-2_p-32_s-6","passageId":"li-ji_ch-2_p-32","order":6,"canonicalText":"子於父母則自名也。","chunks":[["子於父母則自名也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-33_s-1","passageId":"li-ji_ch-2_p-33","order":1,"canonicalText":"列國之大夫，入天子之國曰某士；","chunks":[["列國之大夫，入天子之國曰某士；","zh-Hant"]]},{"id":"li-ji_ch-2_p-33_s-2","passageId":"li-ji_ch-2_p-33","order":2,"canonicalText":"自稱曰陪臣某。","chunks":[["自稱曰陪臣某。","zh-Hant"]]},{"id":"li-ji_ch-2_p-33_s-3","passageId":"li-ji_ch-2_p-33","order":3,"canonicalText":"於外曰子，於其國曰寡君之老。","chunks":[["於外曰子，於其國曰寡君之老。","zh-Hant"]]},{"id":"li-ji_ch-2_p-33_s-4","passageId":"li-ji_ch-2_p-33","order":4,"canonicalText":"使者自稱曰某。","chunks":[["使者自稱曰某。","zh-Hant"]]},{"id":"li-ji_ch-2_p-34_s-1","passageId":"li-ji_ch-2_p-34","order":1,"canonicalText":"天子不言出，諸侯不生名。","chunks":[["天子不言出，諸侯不生名。","zh-Hant"]]},{"id":"li-ji_ch-2_p-34_s-2","passageId":"li-ji_ch-2_p-34","order":2,"canonicalText":"君子不親惡。","chunks":[["君子不親惡。","zh-Hant"]]},{"id":"li-ji_ch-2_p-34_s-3","passageId":"li-ji_ch-2_p-34","order":3,"canonicalText":"諸侯失地，名；","chunks":[["諸侯失地，名；","zh-Hant"]]},{"id":"li-ji_ch-2_p-34_s-4","passageId":"li-ji_ch-2_p-34","order":4,"canonicalText":"滅同姓，名。","chunks":[["滅同姓，名。","zh-Hant"]]},{"id":"li-ji_ch-2_p-35_s-1","passageId":"li-ji_ch-2_p-35","order":1,"canonicalText":"為人臣之禮：不顯諫。","chunks":[["為人臣之禮：不顯諫。","zh-Hant"]]},{"id":"li-ji_ch-2_p-35_s-2","passageId":"li-ji_ch-2_p-35","order":2,"canonicalText":"三諫而不聽，則逃之。","chunks":[["三諫而不聽，則逃之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-35_s-3","passageId":"li-ji_ch-2_p-35","order":3,"canonicalText":"子之事親也：三諫而不聽，則號泣而隨之。","chunks":[["子之事親也：三諫而不聽，則號泣而隨之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-36_s-1","passageId":"li-ji_ch-2_p-36","order":1,"canonicalText":"君有疾，飲藥，臣先嘗之。","chunks":[["君有疾，飲藥，臣先嘗之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-36_s-2","passageId":"li-ji_ch-2_p-36","order":2,"canonicalText":"親有疾，飲藥，子先嘗之。","chunks":[["親有疾，飲藥，子先嘗之。","zh-Hant"]]},{"id":"li-ji_ch-2_p-36_s-3","passageId":"li-ji_ch-2_p-36","order":3,"canonicalText":"醫不三世，不服其藥。","chunks":[["醫不三世，不服其藥。","zh-Hant"]]},{"id":"li-ji_ch-2_p-37_s-1","passageId":"li-ji_ch-2_p-37","order":1,"canonicalText":"儗人必於其倫。","chunks":[["儗人必於其倫。","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-1","passageId":"li-ji_ch-2_p-38","order":1,"canonicalText":"問天子之年，對曰：「聞之：始服衣若干尺矣。","chunks":[["問天子之年，對曰：「聞之：始服衣若干尺矣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-2","passageId":"li-ji_ch-2_p-38","order":2,"canonicalText":"」問國君之年：長，曰能從宗廟社稷之事矣；","chunks":[["」問國君之年：長，曰能從宗廟社稷之事矣；","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-3","passageId":"li-ji_ch-2_p-38","order":3,"canonicalText":"幼，曰未能從宗廟社稷之事也。","chunks":[["幼，曰未能從宗廟社稷之事也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-4","passageId":"li-ji_ch-2_p-38","order":4,"canonicalText":"問大夫之子：長，曰能御矣；","chunks":[["問大夫之子：長，曰能御矣；","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-5","passageId":"li-ji_ch-2_p-38","order":5,"canonicalText":"幼，曰未能御也。","chunks":[["幼，曰未能御也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-6","passageId":"li-ji_ch-2_p-38","order":6,"canonicalText":"問士之子：長，曰能典謁矣；","chunks":[["問士之子：長，曰能典謁矣；","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-7","passageId":"li-ji_ch-2_p-38","order":7,"canonicalText":"幼，曰未能典謁也。","chunks":[["幼，曰未能典謁也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-8","passageId":"li-ji_ch-2_p-38","order":8,"canonicalText":"問庶人之子：長，曰能負薪矣；","chunks":[["問庶人之子：長，曰能負薪矣；","zh-Hant"]]},{"id":"li-ji_ch-2_p-38_s-9","passageId":"li-ji_ch-2_p-38","order":9,"canonicalText":"幼，曰未能負薪也。","chunks":[["幼，曰未能負薪也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-39_s-1","passageId":"li-ji_ch-2_p-39","order":1,"canonicalText":"問國君之富，數地以對，山澤之所出。","chunks":[["問國君之富，數地以對，山澤之所出。","zh-Hant"]]},{"id":"li-ji_ch-2_p-39_s-2","passageId":"li-ji_ch-2_p-39","order":2,"canonicalText":"問大夫之富，曰有宰食力，祭器衣服不假。","chunks":[["問大夫之富，曰有宰食力，祭器衣服不假。","zh-Hant"]]},{"id":"li-ji_ch-2_p-39_s-3","passageId":"li-ji_ch-2_p-39","order":3,"canonicalText":"問士之富，以車數對。","chunks":[["問士之富，以車數對。","zh-Hant"]]},{"id":"li-ji_ch-2_p-39_s-4","passageId":"li-ji_ch-2_p-39","order":4,"canonicalText":"問庶人之富，數畜以對。","chunks":[["問庶人之富，數畜以對。","zh-Hant"]]},{"id":"li-ji_ch-2_p-40_s-1","passageId":"li-ji_ch-2_p-40","order":1,"canonicalText":"天子祭天地，祭四方，祭山川，祭五祀，歲遍。","chunks":[["天子祭天地，祭四方，祭山川，祭五祀，歲遍。","zh-Hant"]]},{"id":"li-ji_ch-2_p-40_s-2","passageId":"li-ji_ch-2_p-40","order":2,"canonicalText":"諸侯方祀，祭山川，祭五祀，歲遍。","chunks":[["諸侯方祀，祭山川，祭五祀，歲遍。","zh-Hant"]]},{"id":"li-ji_ch-2_p-40_s-3","passageId":"li-ji_ch-2_p-40","order":3,"canonicalText":"大夫祭五祀，歲遍。","chunks":[["大夫祭五祀，歲遍。","zh-Hant"]]},{"id":"li-ji_ch-2_p-40_s-4","passageId":"li-ji_ch-2_p-40","order":4,"canonicalText":"士祭其先。","chunks":[["士祭其先。","zh-Hant"]]},{"id":"li-ji_ch-2_p-41_s-1","passageId":"li-ji_ch-2_p-41","order":1,"canonicalText":"凡祭，有其廢之莫敢舉也，有其舉之莫敢廢也。","chunks":[["凡祭，有其廢之莫敢舉也，有其舉之莫敢廢也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-41_s-2","passageId":"li-ji_ch-2_p-41","order":2,"canonicalText":"非其所祭而祭之，名曰淫祀。","chunks":[["非其所祭而祭之，名曰淫祀。","zh-Hant"]]},{"id":"li-ji_ch-2_p-41_s-3","passageId":"li-ji_ch-2_p-41","order":3,"canonicalText":"淫祀無福。","chunks":[["淫祀無福。","zh-Hant"]]},{"id":"li-ji_ch-2_p-41_s-4","passageId":"li-ji_ch-2_p-41","order":4,"canonicalText":"天子以犧牛，諸侯以肥牛，大夫以索牛，士以羊豕。","chunks":[["天子以犧牛，諸侯以肥牛，大夫以索牛，士以羊豕。","zh-Hant"]]},{"id":"li-ji_ch-2_p-41_s-5","passageId":"li-ji_ch-2_p-41","order":5,"canonicalText":"支子不祭，祭必告于宗子。","chunks":[["支子不祭，祭必告于宗子。","zh-Hant"]]},{"id":"li-ji_ch-2_p-42_s-1","passageId":"li-ji_ch-2_p-42","order":1,"canonicalText":"凡祭宗廟之禮：牛曰一元大武，豕曰剛鬣，豚曰腯肥，羊曰柔毛，雞曰翰音，犬曰羹獻，雉曰疏趾，兔曰明視，脯曰尹祭，槁魚曰商祭，鮮魚曰脡祭，水曰清滌，酒曰清酌，黍曰薌合，粱曰薌萁，稷曰明粢，稻曰嘉蔬，韭曰豐本，鹽曰鹹鹺，玉曰嘉玉，幣曰量幣。","chunks":[["凡祭宗廟之禮：牛曰一元大武，豕曰剛鬣，豚曰腯肥，羊曰柔毛，雞曰翰音，犬曰羹獻，雉曰疏趾，兔曰明視，脯曰尹祭，槁魚曰商祭，鮮魚曰脡祭，水曰清滌，酒曰清酌，黍曰薌合，粱曰薌萁，稷曰明粢，稻曰嘉蔬，韭曰豐本，鹽曰鹹鹺，玉曰嘉玉，幣曰量幣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-43_s-1","passageId":"li-ji_ch-2_p-43","order":1,"canonicalText":"天子死曰崩，諸侯曰薨，大夫曰卒，士曰不祿，庶人曰死。","chunks":[["天子死曰崩，諸侯曰薨，大夫曰卒，士曰不祿，庶人曰死。","zh-Hant"]]},{"id":"li-ji_ch-2_p-43_s-2","passageId":"li-ji_ch-2_p-43","order":2,"canonicalText":"在床曰尸，在棺曰柩。","chunks":[["在床曰尸，在棺曰柩。","zh-Hant"]]},{"id":"li-ji_ch-2_p-43_s-3","passageId":"li-ji_ch-2_p-43","order":3,"canonicalText":"羽鳥曰降，四足曰漬。","chunks":[["羽鳥曰降，四足曰漬。","zh-Hant"]]},{"id":"li-ji_ch-2_p-43_s-4","passageId":"li-ji_ch-2_p-43","order":4,"canonicalText":"死寇曰兵。","chunks":[["死寇曰兵。","zh-Hant"]]},{"id":"li-ji_ch-2_p-44_s-1","passageId":"li-ji_ch-2_p-44","order":1,"canonicalText":"祭王父曰皇祖考，王母曰皇祖妣。","chunks":[["祭王父曰皇祖考，王母曰皇祖妣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-44_s-2","passageId":"li-ji_ch-2_p-44","order":2,"canonicalText":"父曰皇考，母曰皇妣。","chunks":[["父曰皇考，母曰皇妣。","zh-Hant"]]},{"id":"li-ji_ch-2_p-44_s-3","passageId":"li-ji_ch-2_p-44","order":3,"canonicalText":"夫曰皇辟。","chunks":[["夫曰皇辟。","zh-Hant"]]},{"id":"li-ji_ch-2_p-44_s-4","passageId":"li-ji_ch-2_p-44","order":4,"canonicalText":"生曰父、曰母、曰妻，死曰考、曰妣、曰嬪。","chunks":[["生曰父、曰母、曰妻，死曰考、曰妣、曰嬪。","zh-Hant"]]},{"id":"li-ji_ch-2_p-44_s-5","passageId":"li-ji_ch-2_p-44","order":5,"canonicalText":"壽考曰卒，短折曰不祿。","chunks":[["壽考曰卒，短折曰不祿。","zh-Hant"]]},{"id":"li-ji_ch-2_p-45_s-1","passageId":"li-ji_ch-2_p-45","order":1,"canonicalText":"天子視不上於袷，不下於帶；","chunks":[["天子視不上於袷，不下於帶；","zh-Hant"]]},{"id":"li-ji_ch-2_p-45_s-2","passageId":"li-ji_ch-2_p-45","order":2,"canonicalText":"國君，綏視；","chunks":[["國君，綏視；","zh-Hant"]]},{"id":"li-ji_ch-2_p-45_s-3","passageId":"li-ji_ch-2_p-45","order":3,"canonicalText":"大夫，衡視；","chunks":[["大夫，衡視；","zh-Hant"]]},{"id":"li-ji_ch-2_p-45_s-4","passageId":"li-ji_ch-2_p-45","order":4,"canonicalText":"士視五步。","chunks":[["士視五步。","zh-Hant"]]},{"id":"li-ji_ch-2_p-45_s-5","passageId":"li-ji_ch-2_p-45","order":5,"canonicalText":"凡視：上於面則敖，下於帶則憂，傾則奸。","chunks":[["凡視：上於面則敖，下於帶則憂，傾則奸。","zh-Hant"]]},{"id":"li-ji_ch-2_p-46_s-1","passageId":"li-ji_ch-2_p-46","order":1,"canonicalText":"君命，大夫與士肄。","chunks":[["君命，大夫與士肄。","zh-Hant"]]},{"id":"li-ji_ch-2_p-46_s-2","passageId":"li-ji_ch-2_p-46","order":2,"canonicalText":"在官言官，在府言府，在庫言庫，在朝言朝。","chunks":[["在官言官，在府言府，在庫言庫，在朝言朝。","zh-Hant"]]},{"id":"li-ji_ch-2_p-47_s-1","passageId":"li-ji_ch-2_p-47","order":1,"canonicalText":"朝言不及犬馬。","chunks":[["朝言不及犬馬。","zh-Hant"]]},{"id":"li-ji_ch-2_p-47_s-2","passageId":"li-ji_ch-2_p-47","order":2,"canonicalText":"輟朝而顧，不有異事，必有異慮。","chunks":[["輟朝而顧，不有異事，必有異慮。","zh-Hant"]]},{"id":"li-ji_ch-2_p-47_s-3","passageId":"li-ji_ch-2_p-47","order":3,"canonicalText":"故輟朝而顧，君子謂之固。","chunks":[["故輟朝而顧，君子謂之固。","zh-Hant"]]},{"id":"li-ji_ch-2_p-47_s-4","passageId":"li-ji_ch-2_p-47","order":4,"canonicalText":"在朝言禮，問禮對以禮。","chunks":[["在朝言禮，問禮對以禮。","zh-Hant"]]},{"id":"li-ji_ch-2_p-48_s-1","passageId":"li-ji_ch-2_p-48","order":1,"canonicalText":"大饗不問卜，不饒富。","chunks":[["大饗不問卜，不饒富。","zh-Hant"]]},{"id":"li-ji_ch-2_p-49_s-1","passageId":"li-ji_ch-2_p-49","order":1,"canonicalText":"凡摯，天子鬯，諸侯圭，卿羔，大夫雁，士雉，庶人之摯匹；","chunks":[["凡摯，天子鬯，諸侯圭，卿羔，大夫雁，士雉，庶人之摯匹；","zh-Hant"]]},{"id":"li-ji_ch-2_p-49_s-2","passageId":"li-ji_ch-2_p-49","order":2,"canonicalText":"童子委摯而退。","chunks":[["童子委摯而退。","zh-Hant"]]},{"id":"li-ji_ch-2_p-49_s-3","passageId":"li-ji_ch-2_p-49","order":3,"canonicalText":"野外軍中無摯，以纓，拾，矢，可也。","chunks":[["野外軍中無摯，以纓，拾，矢，可也。","zh-Hant"]]},{"id":"li-ji_ch-2_p-49_s-4","passageId":"li-ji_ch-2_p-49","order":4,"canonicalText":"婦人之摯，椇榛、脯修、棗栗。","chunks":[["婦人之摯，椇榛、脯修、棗栗。","zh-Hant"]]},{"id":"li-ji_ch-2_p-50_s-1","passageId":"li-ji_ch-2_p-50","order":1,"canonicalText":"納女於天子，曰備百姓；","chunks":[["納女於天子，曰備百姓；","zh-Hant"]]},{"id":"li-ji_ch-2_p-50_s-2","passageId":"li-ji_ch-2_p-50","order":2,"canonicalText":"於國君，曰備酒漿；","chunks":[["於國君，曰備酒漿；","zh-Hant"]]},{"id":"li-ji_ch-2_p-50_s-3","passageId":"li-ji_ch-2_p-50","order":3,"canonicalText":"於大夫，曰備掃灑。","chunks":[["於大夫，曰備掃灑。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-1","passageId":"li-ji_ch-3_p-1","order":1,"canonicalText":"公儀仲子之喪，檀弓免焉。","chunks":[["公儀仲子之喪，檀弓免焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-2","passageId":"li-ji_ch-3_p-1","order":2,"canonicalText":"仲子舍其孫而立其子，檀弓曰：「何居？","chunks":[["仲子舍其孫而立其子，檀弓曰：「何居？","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-3","passageId":"li-ji_ch-3_p-1","order":3,"canonicalText":"我未之前聞也。","chunks":[["我未之前聞也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-4","passageId":"li-ji_ch-3_p-1","order":4,"canonicalText":"」趨而就子服伯子於門右，曰：「仲子舍其孫而立其子，何也？","chunks":[["」趨而就子服伯子於門右，曰：「仲子舍其孫而立其子，何也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-5","passageId":"li-ji_ch-3_p-1","order":5,"canonicalText":"」伯子曰：「仲子亦猶行古之道也。","chunks":[["」伯子曰：「仲子亦猶行古之道也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-6","passageId":"li-ji_ch-3_p-1","order":6,"canonicalText":"昔者文王舍伯邑考而立武王，微子舍其孫腯而立衍也；","chunks":[["昔者文王舍伯邑考而立武王，微子舍其孫腯而立衍也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-7","passageId":"li-ji_ch-3_p-1","order":7,"canonicalText":"夫仲子亦猶行古之道也。","chunks":[["夫仲子亦猶行古之道也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-8","passageId":"li-ji_ch-3_p-1","order":8,"canonicalText":"」子游問諸孔子，孔子曰：「否！","chunks":[["」子游問諸孔子，孔子曰：「否！","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-9","passageId":"li-ji_ch-3_p-1","order":9,"canonicalText":"立孫。","chunks":[["立孫。","zh-Hant"]]},{"id":"li-ji_ch-3_p-1_s-10","passageId":"li-ji_ch-3_p-1","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-2_s-1","passageId":"li-ji_ch-3_p-2","order":1,"canonicalText":"事親有隱而無犯，左右就養無方，服勤至死，致喪三年。","chunks":[["事親有隱而無犯，左右就養無方，服勤至死，致喪三年。","zh-Hant"]]},{"id":"li-ji_ch-3_p-2_s-2","passageId":"li-ji_ch-3_p-2","order":2,"canonicalText":"事君有犯而無隱，左右就養有方，服勤至死，方喪三年。","chunks":[["事君有犯而無隱，左右就養有方，服勤至死，方喪三年。","zh-Hant"]]},{"id":"li-ji_ch-3_p-2_s-3","passageId":"li-ji_ch-3_p-2","order":3,"canonicalText":"事師無犯無隱，左右就養無方，服勤至死，心喪三年。","chunks":[["事師無犯無隱，左右就養無方，服勤至死，心喪三年。","zh-Hant"]]},{"id":"li-ji_ch-3_p-3_s-1","passageId":"li-ji_ch-3_p-3","order":1,"canonicalText":"季武子成寢，杜氏之葬在西階之下，請合葬焉，許之。","chunks":[["季武子成寢，杜氏之葬在西階之下，請合葬焉，許之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-3_s-2","passageId":"li-ji_ch-3_p-3","order":2,"canonicalText":"入宮而不敢哭。","chunks":[["入宮而不敢哭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-3_s-3","passageId":"li-ji_ch-3_p-3","order":3,"canonicalText":"武子曰：「合葬非古也，自周公以來，未之有改也。","chunks":[["武子曰：「合葬非古也，自周公以來，未之有改也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-3_s-4","passageId":"li-ji_ch-3_p-3","order":4,"canonicalText":"吾許其大而不許其細，何居？","chunks":[["吾許其大而不許其細，何居？","zh-Hant"]]},{"id":"li-ji_ch-3_p-3_s-5","passageId":"li-ji_ch-3_p-3","order":5,"canonicalText":"」命之哭。","chunks":[["」命之哭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-1","passageId":"li-ji_ch-3_p-4","order":1,"canonicalText":"子上之母死而不喪。","chunks":[["子上之母死而不喪。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-2","passageId":"li-ji_ch-3_p-4","order":2,"canonicalText":"門人問諸子思曰：「昔者子之先君子喪出母乎？","chunks":[["門人問諸子思曰：「昔者子之先君子喪出母乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-3","passageId":"li-ji_ch-3_p-4","order":3,"canonicalText":"」曰：「然」。","chunks":[["」曰：「然」。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-4","passageId":"li-ji_ch-3_p-4","order":4,"canonicalText":"「子之不使白也喪之。","chunks":[["「子之不使白也喪之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-5","passageId":"li-ji_ch-3_p-4","order":5,"canonicalText":"何也？","chunks":[["何也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-6","passageId":"li-ji_ch-3_p-4","order":6,"canonicalText":"」子思曰：「昔者吾先君子無所失道；","chunks":[["」子思曰：「昔者吾先君子無所失道；","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-7","passageId":"li-ji_ch-3_p-4","order":7,"canonicalText":"道隆則從而隆，道污則從而污。","chunks":[["道隆則從而隆，道污則從而污。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-8","passageId":"li-ji_ch-3_p-4","order":8,"canonicalText":"汲則安能？","chunks":[["汲則安能？","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-9","passageId":"li-ji_ch-3_p-4","order":9,"canonicalText":"為汲也妻者，是為白也母；","chunks":[["為汲也妻者，是為白也母；","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-10","passageId":"li-ji_ch-3_p-4","order":10,"canonicalText":"不為汲也妻者，是不為白也母。","chunks":[["不為汲也妻者，是不為白也母。","zh-Hant"]]},{"id":"li-ji_ch-3_p-4_s-11","passageId":"li-ji_ch-3_p-4","order":11,"canonicalText":"」故孔氏之不喪出母，自子思始也。","chunks":[["」故孔氏之不喪出母，自子思始也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-5_s-1","passageId":"li-ji_ch-3_p-5","order":1,"canonicalText":"孔子曰：「拜而後稽顙，頹乎其順也；","chunks":[["孔子曰：「拜而後稽顙，頹乎其順也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-5_s-2","passageId":"li-ji_ch-3_p-5","order":2,"canonicalText":"稽顙而後拜，頎乎其至也。","chunks":[["稽顙而後拜，頎乎其至也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-5_s-3","passageId":"li-ji_ch-3_p-5","order":3,"canonicalText":"三年之喪，吾從其至者。","chunks":[["三年之喪，吾從其至者。","zh-Hant"]]},{"id":"li-ji_ch-3_p-5_s-4","passageId":"li-ji_ch-3_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-6_s-1","passageId":"li-ji_ch-3_p-6","order":1,"canonicalText":"孔子既得合葬於防，曰：「吾聞之：古也墓而不墳；","chunks":[["孔子既得合葬於防，曰：「吾聞之：古也墓而不墳；","zh-Hant"]]},{"id":"li-ji_ch-3_p-6_s-2","passageId":"li-ji_ch-3_p-6","order":2,"canonicalText":"今丘也，東西南北人也，不可以弗識也。","chunks":[["今丘也，東西南北人也，不可以弗識也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-6_s-3","passageId":"li-ji_ch-3_p-6","order":3,"canonicalText":"」於是封之，崇四尺。","chunks":[["」於是封之，崇四尺。","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-1","passageId":"li-ji_ch-3_p-7","order":1,"canonicalText":"孔子先反，門人後，雨甚；","chunks":[["孔子先反，門人後，雨甚；","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-2","passageId":"li-ji_ch-3_p-7","order":2,"canonicalText":"至，孔子問焉曰：「爾來何遲也？","chunks":[["至，孔子問焉曰：「爾來何遲也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-3","passageId":"li-ji_ch-3_p-7","order":3,"canonicalText":"」曰：「防墓崩。","chunks":[["」曰：「防墓崩。","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-4","passageId":"li-ji_ch-3_p-7","order":4,"canonicalText":"」孔子不應。","chunks":[["」孔子不應。","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-5","passageId":"li-ji_ch-3_p-7","order":5,"canonicalText":"三，孔子泫然流涕曰：「吾聞之：古不修墓。","chunks":[["三，孔子泫然流涕曰：「吾聞之：古不修墓。","zh-Hant"]]},{"id":"li-ji_ch-3_p-7_s-6","passageId":"li-ji_ch-3_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-8_s-1","passageId":"li-ji_ch-3_p-8","order":1,"canonicalText":"孔子哭子路於中庭。","chunks":[["孔子哭子路於中庭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-8_s-2","passageId":"li-ji_ch-3_p-8","order":2,"canonicalText":"有人吊者，而夫子拜之。","chunks":[["有人吊者，而夫子拜之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-8_s-3","passageId":"li-ji_ch-3_p-8","order":3,"canonicalText":"既哭，進使者而問故。","chunks":[["既哭，進使者而問故。","zh-Hant"]]},{"id":"li-ji_ch-3_p-8_s-4","passageId":"li-ji_ch-3_p-8","order":4,"canonicalText":"使者曰：「醢之矣。","chunks":[["使者曰：「醢之矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-8_s-5","passageId":"li-ji_ch-3_p-8","order":5,"canonicalText":"」遂命覆醢。","chunks":[["」遂命覆醢。","zh-Hant"]]},{"id":"li-ji_ch-3_p-9_s-1","passageId":"li-ji_ch-3_p-9","order":1,"canonicalText":"曾子曰：「朋友之墓，有宿草而不哭焉。","chunks":[["曾子曰：「朋友之墓，有宿草而不哭焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-9_s-2","passageId":"li-ji_ch-3_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-1","passageId":"li-ji_ch-3_p-10","order":1,"canonicalText":"子思曰：「喪三日而殯，凡附於身者，必誠必信，勿之有悔焉耳矣。","chunks":[["子思曰：「喪三日而殯，凡附於身者，必誠必信，勿之有悔焉耳矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-2","passageId":"li-ji_ch-3_p-10","order":2,"canonicalText":"三月而葬，凡附於棺者，必誠必信，勿之有悔焉耳矣。","chunks":[["三月而葬，凡附於棺者，必誠必信，勿之有悔焉耳矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-3","passageId":"li-ji_ch-3_p-10","order":3,"canonicalText":"喪三年以為極，亡則弗之忘矣。","chunks":[["喪三年以為極，亡則弗之忘矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-4","passageId":"li-ji_ch-3_p-10","order":4,"canonicalText":"故君子有終身之憂，而無一朝之患。","chunks":[["故君子有終身之憂，而無一朝之患。","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-5","passageId":"li-ji_ch-3_p-10","order":5,"canonicalText":"故忌日不樂。","chunks":[["故忌日不樂。","zh-Hant"]]},{"id":"li-ji_ch-3_p-10_s-6","passageId":"li-ji_ch-3_p-10","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-11_s-1","passageId":"li-ji_ch-3_p-11","order":1,"canonicalText":"孔子少孤，不知其墓。","chunks":[["孔子少孤，不知其墓。","zh-Hant"]]},{"id":"li-ji_ch-3_p-11_s-2","passageId":"li-ji_ch-3_p-11","order":2,"canonicalText":"殯於五父之衢。","chunks":[["殯於五父之衢。","zh-Hant"]]},{"id":"li-ji_ch-3_p-11_s-3","passageId":"li-ji_ch-3_p-11","order":3,"canonicalText":"人之見之者，皆以為葬也。","chunks":[["人之見之者，皆以為葬也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-11_s-4","passageId":"li-ji_ch-3_p-11","order":4,"canonicalText":"其慎也，蓋殯也。","chunks":[["其慎也，蓋殯也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-11_s-5","passageId":"li-ji_ch-3_p-11","order":5,"canonicalText":"問於郰曼父之母，然後得合葬於防。","chunks":[["問於郰曼父之母，然後得合葬於防。","zh-Hant"]]},{"id":"li-ji_ch-3_p-12_s-1","passageId":"li-ji_ch-3_p-12","order":1,"canonicalText":"鄰有喪，舂不相；","chunks":[["鄰有喪，舂不相；","zh-Hant"]]},{"id":"li-ji_ch-3_p-12_s-2","passageId":"li-ji_ch-3_p-12","order":2,"canonicalText":"里有殯，不巷歌。","chunks":[["里有殯，不巷歌。","zh-Hant"]]},{"id":"li-ji_ch-3_p-12_s-3","passageId":"li-ji_ch-3_p-12","order":3,"canonicalText":"喪冠不緌。","chunks":[["喪冠不緌。","zh-Hant"]]},{"id":"li-ji_ch-3_p-13_s-1","passageId":"li-ji_ch-3_p-13","order":1,"canonicalText":"有虞氏瓦棺，夏后氏堲周，殷人棺槨，周人墻置翣。","chunks":[["有虞氏瓦棺，夏后氏堲周，殷人棺槨，周人墻置翣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-13_s-2","passageId":"li-ji_ch-3_p-13","order":2,"canonicalText":"周人以殷人之棺槨葬長殤，以夏后氏之堲周葬中殤、下殤，以有虞氏之瓦棺葬無服之殤。","chunks":[["周人以殷人之棺槨葬長殤，以夏后氏之堲周葬中殤、下殤，以有虞氏之瓦棺葬無服之殤。","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-1","passageId":"li-ji_ch-3_p-14","order":1,"canonicalText":"夏后氏尚黑；","chunks":[["夏后氏尚黑；","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-2","passageId":"li-ji_ch-3_p-14","order":2,"canonicalText":"大事斂用昏，戎事乘驪，牲用玄。","chunks":[["大事斂用昏，戎事乘驪，牲用玄。","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-3","passageId":"li-ji_ch-3_p-14","order":3,"canonicalText":"殷人尚白；","chunks":[["殷人尚白；","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-4","passageId":"li-ji_ch-3_p-14","order":4,"canonicalText":"大事斂用日中，戎事乘翰，牲用白。","chunks":[["大事斂用日中，戎事乘翰，牲用白。","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-5","passageId":"li-ji_ch-3_p-14","order":5,"canonicalText":"周人尚赤；","chunks":[["周人尚赤；","zh-Hant"]]},{"id":"li-ji_ch-3_p-14_s-6","passageId":"li-ji_ch-3_p-14","order":6,"canonicalText":"大事斂用日出，戎事乘騵，牲用騂。","chunks":[["大事斂用日出，戎事乘騵，牲用騂。","zh-Hant"]]},{"id":"li-ji_ch-3_p-15_s-1","passageId":"li-ji_ch-3_p-15","order":1,"canonicalText":"穆公之母卒，使人問於曾子曰：「如之何？","chunks":[["穆公之母卒，使人問於曾子曰：「如之何？","zh-Hant"]]},{"id":"li-ji_ch-3_p-15_s-2","passageId":"li-ji_ch-3_p-15","order":2,"canonicalText":"」對曰：「申也聞諸申之父曰：哭泣之哀、齊斬之情、饘粥之食，自天子達。","chunks":[["」對曰：「申也聞諸申之父曰：哭泣之哀、齊斬之情、饘粥之食，自天子達。","zh-Hant"]]},{"id":"li-ji_ch-3_p-15_s-3","passageId":"li-ji_ch-3_p-15","order":3,"canonicalText":"布幕，衛也；","chunks":[["布幕，衛也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-15_s-4","passageId":"li-ji_ch-3_p-15","order":4,"canonicalText":"縿幕，魯也。","chunks":[["縿幕，魯也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-15_s-5","passageId":"li-ji_ch-3_p-15","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-1","passageId":"li-ji_ch-3_p-16","order":1,"canonicalText":"晉獻公將殺其世子申生，公子重耳謂之曰：「子蓋言子之志於公乎？","chunks":[["晉獻公將殺其世子申生，公子重耳謂之曰：「子蓋言子之志於公乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-2","passageId":"li-ji_ch-3_p-16","order":2,"canonicalText":"」世子曰：「不可，君安驪姬，是我傷公之心也。","chunks":[["」世子曰：「不可，君安驪姬，是我傷公之心也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-3","passageId":"li-ji_ch-3_p-16","order":3,"canonicalText":"」曰：「然則蓋行乎？","chunks":[["」曰：「然則蓋行乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-4","passageId":"li-ji_ch-3_p-16","order":4,"canonicalText":"」世子曰：「不可，君謂我欲弒君也，天下豈有無父之國哉！","chunks":[["」世子曰：「不可，君謂我欲弒君也，天下豈有無父之國哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-5","passageId":"li-ji_ch-3_p-16","order":5,"canonicalText":"吾何行如之？","chunks":[["吾何行如之？","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-6","passageId":"li-ji_ch-3_p-16","order":6,"canonicalText":"」使人辭於狐突曰：「申生有罪，不念伯氏之言也，以至于死，申生不敢愛其死；","chunks":[["」使人辭於狐突曰：「申生有罪，不念伯氏之言也，以至于死，申生不敢愛其死；","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-7","passageId":"li-ji_ch-3_p-16","order":7,"canonicalText":"雖然，吾君老矣，子少，國家多難，伯氏不出而圖吾君，伯氏茍出而圖吾君，申生受賜而死。","chunks":[["雖然，吾君老矣，子少，國家多難，伯氏不出而圖吾君，伯氏茍出而圖吾君，申生受賜而死。","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-8","passageId":"li-ji_ch-3_p-16","order":8,"canonicalText":"」再拜稽首，乃卒。","chunks":[["」再拜稽首，乃卒。","zh-Hant"]]},{"id":"li-ji_ch-3_p-16_s-9","passageId":"li-ji_ch-3_p-16","order":9,"canonicalText":"是以為「恭世子」也。","chunks":[["是以為「恭世子」也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-1","passageId":"li-ji_ch-3_p-17","order":1,"canonicalText":"魯人有朝祥而莫歌者，子路笑之。","chunks":[["魯人有朝祥而莫歌者，子路笑之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-2","passageId":"li-ji_ch-3_p-17","order":2,"canonicalText":"夫子曰：「由，爾責於人，終無已夫？","chunks":[["夫子曰：「由，爾責於人，終無已夫？","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-3","passageId":"li-ji_ch-3_p-17","order":3,"canonicalText":"三年之喪，亦已久矣夫。","chunks":[["三年之喪，亦已久矣夫。","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-4","passageId":"li-ji_ch-3_p-17","order":4,"canonicalText":"」子路出，夫子曰：「又多乎哉！","chunks":[["」子路出，夫子曰：「又多乎哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-5","passageId":"li-ji_ch-3_p-17","order":5,"canonicalText":"逾月則其善也。","chunks":[["逾月則其善也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-17_s-6","passageId":"li-ji_ch-3_p-17","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-1","passageId":"li-ji_ch-3_p-18","order":1,"canonicalText":"魯莊公及宋人戰于乘丘。","chunks":[["魯莊公及宋人戰于乘丘。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-2","passageId":"li-ji_ch-3_p-18","order":2,"canonicalText":"縣賁父御，卜國為右。","chunks":[["縣賁父御，卜國為右。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-3","passageId":"li-ji_ch-3_p-18","order":3,"canonicalText":"馬驚，敗績，公隊。","chunks":[["馬驚，敗績，公隊。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-4","passageId":"li-ji_ch-3_p-18","order":4,"canonicalText":"佐車授綏。","chunks":[["佐車授綏。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-5","passageId":"li-ji_ch-3_p-18","order":5,"canonicalText":"公曰：「末之卜也。","chunks":[["公曰：「末之卜也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-6","passageId":"li-ji_ch-3_p-18","order":6,"canonicalText":"」縣賁父曰：「他日不敗績，而今敗績，是無勇也。","chunks":[["」縣賁父曰：「他日不敗績，而今敗績，是無勇也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-7","passageId":"li-ji_ch-3_p-18","order":7,"canonicalText":"」遂死之。","chunks":[["」遂死之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-8","passageId":"li-ji_ch-3_p-18","order":8,"canonicalText":"圉人浴馬，有流矢在白肉。","chunks":[["圉人浴馬，有流矢在白肉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-9","passageId":"li-ji_ch-3_p-18","order":9,"canonicalText":"公曰：「非其罪也。","chunks":[["公曰：「非其罪也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-10","passageId":"li-ji_ch-3_p-18","order":10,"canonicalText":"」遂誄之。","chunks":[["」遂誄之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-18_s-11","passageId":"li-ji_ch-3_p-18","order":11,"canonicalText":"士之有誄，自此始也。","chunks":[["士之有誄，自此始也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-1","passageId":"li-ji_ch-3_p-19","order":1,"canonicalText":"曾子寢疾，病。","chunks":[["曾子寢疾，病。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-2","passageId":"li-ji_ch-3_p-19","order":2,"canonicalText":"樂正子春坐於床下，曾元、曾申坐於足，童子隅坐而執燭。","chunks":[["樂正子春坐於床下，曾元、曾申坐於足，童子隅坐而執燭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-3","passageId":"li-ji_ch-3_p-19","order":3,"canonicalText":"童子曰：「華而睆，大夫之簀與？","chunks":[["童子曰：「華而睆，大夫之簀與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-4","passageId":"li-ji_ch-3_p-19","order":4,"canonicalText":"」子春曰：「止！","chunks":[["」子春曰：「止！","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-5","passageId":"li-ji_ch-3_p-19","order":5,"canonicalText":"」曾子聞之，瞿然曰：「呼！","chunks":[["」曾子聞之，瞿然曰：「呼！","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-6","passageId":"li-ji_ch-3_p-19","order":6,"canonicalText":"」曰：「華而睆，大夫之簀與？","chunks":[["」曰：「華而睆，大夫之簀與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-7","passageId":"li-ji_ch-3_p-19","order":7,"canonicalText":"」曾子曰：「然，斯季孫之賜也，我未之能易也。","chunks":[["」曾子曰：「然，斯季孫之賜也，我未之能易也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-8","passageId":"li-ji_ch-3_p-19","order":8,"canonicalText":"元，起易簀。","chunks":[["元，起易簀。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-9","passageId":"li-ji_ch-3_p-19","order":9,"canonicalText":"」曾元曰：「夫子之病帮矣，不可以變，幸而至於旦，請敬易之。","chunks":[["」曾元曰：「夫子之病帮矣，不可以變，幸而至於旦，請敬易之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-10","passageId":"li-ji_ch-3_p-19","order":10,"canonicalText":"」曾子曰：「爾之愛我也不如彼。","chunks":[["」曾子曰：「爾之愛我也不如彼。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-11","passageId":"li-ji_ch-3_p-19","order":11,"canonicalText":"君子之愛人也以德，細人之愛人也以姑息。","chunks":[["君子之愛人也以德，細人之愛人也以姑息。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-12","passageId":"li-ji_ch-3_p-19","order":12,"canonicalText":"吾何求哉？","chunks":[["吾何求哉？","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-13","passageId":"li-ji_ch-3_p-19","order":13,"canonicalText":"吾得正而斃焉斯已矣。","chunks":[["吾得正而斃焉斯已矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-14","passageId":"li-ji_ch-3_p-19","order":14,"canonicalText":"」舉扶而易之。","chunks":[["」舉扶而易之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-19_s-15","passageId":"li-ji_ch-3_p-19","order":15,"canonicalText":"反席未安而沒。","chunks":[["反席未安而沒。","zh-Hant"]]},{"id":"li-ji_ch-3_p-20_s-1","passageId":"li-ji_ch-3_p-20","order":1,"canonicalText":"始死，充充如有窮；","chunks":[["始死，充充如有窮；","zh-Hant"]]},{"id":"li-ji_ch-3_p-20_s-2","passageId":"li-ji_ch-3_p-20","order":2,"canonicalText":"既殯，瞿瞿如有求而弗得；","chunks":[["既殯，瞿瞿如有求而弗得；","zh-Hant"]]},{"id":"li-ji_ch-3_p-20_s-3","passageId":"li-ji_ch-3_p-20","order":3,"canonicalText":"既葬，皇皇如有望而弗至。","chunks":[["既葬，皇皇如有望而弗至。","zh-Hant"]]},{"id":"li-ji_ch-3_p-20_s-4","passageId":"li-ji_ch-3_p-20","order":4,"canonicalText":"練而慨然，祥而廓然。","chunks":[["練而慨然，祥而廓然。","zh-Hant"]]},{"id":"li-ji_ch-3_p-21_s-1","passageId":"li-ji_ch-3_p-21","order":1,"canonicalText":"邾婁復之以矢，蓋自戰於升陘始也。","chunks":[["邾婁復之以矢，蓋自戰於升陘始也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-21_s-2","passageId":"li-ji_ch-3_p-21","order":2,"canonicalText":"魯婦人之髽而吊也，自敗於臺鮐始也。","chunks":[["魯婦人之髽而吊也，自敗於臺鮐始也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-22_s-1","passageId":"li-ji_ch-3_p-22","order":1,"canonicalText":"南宮絳之妻之姑之喪，夫子誨之髽曰：「爾毋從從爾，爾毋扈扈爾。","chunks":[["南宮絳之妻之姑之喪，夫子誨之髽曰：「爾毋從從爾，爾毋扈扈爾。","zh-Hant"]]},{"id":"li-ji_ch-3_p-22_s-2","passageId":"li-ji_ch-3_p-22","order":2,"canonicalText":"蓋榛以為笄，長尺，而總八寸。","chunks":[["蓋榛以為笄，長尺，而總八寸。","zh-Hant"]]},{"id":"li-ji_ch-3_p-22_s-3","passageId":"li-ji_ch-3_p-22","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-23_s-1","passageId":"li-ji_ch-3_p-23","order":1,"canonicalText":"孟獻子禫，縣而不樂，比御而不入。","chunks":[["孟獻子禫，縣而不樂，比御而不入。","zh-Hant"]]},{"id":"li-ji_ch-3_p-23_s-2","passageId":"li-ji_ch-3_p-23","order":2,"canonicalText":"夫子曰：「獻子加於人一等矣！","chunks":[["夫子曰：「獻子加於人一等矣！","zh-Hant"]]},{"id":"li-ji_ch-3_p-23_s-3","passageId":"li-ji_ch-3_p-23","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-24_s-1","passageId":"li-ji_ch-3_p-24","order":1,"canonicalText":"孔子既祥，五日彈琴而不成聲，十日而成笙歌。","chunks":[["孔子既祥，五日彈琴而不成聲，十日而成笙歌。","zh-Hant"]]},{"id":"li-ji_ch-3_p-25_s-1","passageId":"li-ji_ch-3_p-25","order":1,"canonicalText":"有子蓋既祥而絲屨組纓。","chunks":[["有子蓋既祥而絲屨組纓。","zh-Hant"]]},{"id":"li-ji_ch-3_p-26_s-1","passageId":"li-ji_ch-3_p-26","order":1,"canonicalText":"死而不吊者三：畏、厭、溺。","chunks":[["死而不吊者三：畏、厭、溺。","zh-Hant"]]},{"id":"li-ji_ch-3_p-27_s-1","passageId":"li-ji_ch-3_p-27","order":1,"canonicalText":"子路有姊之喪，可以除之矣，而弗除也，孔子曰：「何弗除也？","chunks":[["子路有姊之喪，可以除之矣，而弗除也，孔子曰：「何弗除也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-27_s-2","passageId":"li-ji_ch-3_p-27","order":2,"canonicalText":"」子路曰：「吾寡兄弟而弗忍也。","chunks":[["」子路曰：「吾寡兄弟而弗忍也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-27_s-3","passageId":"li-ji_ch-3_p-27","order":3,"canonicalText":"」孔子曰：「先王制禮，行道之人皆弗忍也。","chunks":[["」孔子曰：「先王制禮，行道之人皆弗忍也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-27_s-4","passageId":"li-ji_ch-3_p-27","order":4,"canonicalText":"」子路聞之，遂除之。","chunks":[["」子路聞之，遂除之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-28_s-1","passageId":"li-ji_ch-3_p-28","order":1,"canonicalText":"大公封於營丘，比及五世，皆反葬於周。","chunks":[["大公封於營丘，比及五世，皆反葬於周。","zh-Hant"]]},{"id":"li-ji_ch-3_p-28_s-2","passageId":"li-ji_ch-3_p-28","order":2,"canonicalText":"君子曰：「樂樂其所自生，禮不忘其本。","chunks":[["君子曰：「樂樂其所自生，禮不忘其本。","zh-Hant"]]},{"id":"li-ji_ch-3_p-28_s-3","passageId":"li-ji_ch-3_p-28","order":3,"canonicalText":"古之人有言曰：狐死正丘首。","chunks":[["古之人有言曰：狐死正丘首。","zh-Hant"]]},{"id":"li-ji_ch-3_p-28_s-4","passageId":"li-ji_ch-3_p-28","order":4,"canonicalText":"仁也。","chunks":[["仁也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-28_s-5","passageId":"li-ji_ch-3_p-28","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-1","passageId":"li-ji_ch-3_p-29","order":1,"canonicalText":"伯魚之母死，期而猶哭。","chunks":[["伯魚之母死，期而猶哭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-2","passageId":"li-ji_ch-3_p-29","order":2,"canonicalText":"夫子聞之曰：「誰與哭者？","chunks":[["夫子聞之曰：「誰與哭者？","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-3","passageId":"li-ji_ch-3_p-29","order":3,"canonicalText":"」門人曰：「鯉也。","chunks":[["」門人曰：「鯉也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-4","passageId":"li-ji_ch-3_p-29","order":4,"canonicalText":"」夫子曰：「嘻！","chunks":[["」夫子曰：「嘻！","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-5","passageId":"li-ji_ch-3_p-29","order":5,"canonicalText":"其甚也。","chunks":[["其甚也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-29_s-6","passageId":"li-ji_ch-3_p-29","order":6,"canonicalText":"」伯魚聞之，遂除之。","chunks":[["」伯魚聞之，遂除之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-30_s-1","passageId":"li-ji_ch-3_p-30","order":1,"canonicalText":"舜葬於蒼梧之野，蓋三妃未之從也。","chunks":[["舜葬於蒼梧之野，蓋三妃未之從也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-30_s-2","passageId":"li-ji_ch-3_p-30","order":2,"canonicalText":"季武子曰：「周公蓋祔。","chunks":[["季武子曰：「周公蓋祔。","zh-Hant"]]},{"id":"li-ji_ch-3_p-30_s-3","passageId":"li-ji_ch-3_p-30","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-31_s-1","passageId":"li-ji_ch-3_p-31","order":1,"canonicalText":"曾子之喪，浴於爨室。","chunks":[["曾子之喪，浴於爨室。","zh-Hant"]]},{"id":"li-ji_ch-3_p-32_s-1","passageId":"li-ji_ch-3_p-32","order":1,"canonicalText":"大功廢業。","chunks":[["大功廢業。","zh-Hant"]]},{"id":"li-ji_ch-3_p-32_s-2","passageId":"li-ji_ch-3_p-32","order":2,"canonicalText":"或曰：「大功，誦可也。","chunks":[["或曰：「大功，誦可也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-32_s-3","passageId":"li-ji_ch-3_p-32","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-33_s-1","passageId":"li-ji_ch-3_p-33","order":1,"canonicalText":"子張病，召申祥而語之曰：「君子曰終，小人曰死；","chunks":[["子張病，召申祥而語之曰：「君子曰終，小人曰死；","zh-Hant"]]},{"id":"li-ji_ch-3_p-33_s-2","passageId":"li-ji_ch-3_p-33","order":2,"canonicalText":"吾今日其庶几乎！","chunks":[["吾今日其庶几乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-33_s-3","passageId":"li-ji_ch-3_p-33","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-34_s-1","passageId":"li-ji_ch-3_p-34","order":1,"canonicalText":"曾子曰：「始死之奠，其餘閣也與？","chunks":[["曾子曰：「始死之奠，其餘閣也與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-34_s-2","passageId":"li-ji_ch-3_p-34","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-35_s-1","passageId":"li-ji_ch-3_p-35","order":1,"canonicalText":"曾子曰：「小功不為位也者，是委巷之禮也。","chunks":[["曾子曰：「小功不為位也者，是委巷之禮也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-35_s-2","passageId":"li-ji_ch-3_p-35","order":2,"canonicalText":"子思之哭嫂也為位，婦人倡踴；","chunks":[["子思之哭嫂也為位，婦人倡踴；","zh-Hant"]]},{"id":"li-ji_ch-3_p-35_s-3","passageId":"li-ji_ch-3_p-35","order":3,"canonicalText":"申祥之哭言思也亦然。","chunks":[["申祥之哭言思也亦然。","zh-Hant"]]},{"id":"li-ji_ch-3_p-35_s-4","passageId":"li-ji_ch-3_p-35","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-36_s-1","passageId":"li-ji_ch-3_p-36","order":1,"canonicalText":"古者，冠縮縫，今也，衡縫；","chunks":[["古者，冠縮縫，今也，衡縫；","zh-Hant"]]},{"id":"li-ji_ch-3_p-36_s-2","passageId":"li-ji_ch-3_p-36","order":2,"canonicalText":"故喪冠之反吉，非古也。","chunks":[["故喪冠之反吉，非古也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-37_s-1","passageId":"li-ji_ch-3_p-37","order":1,"canonicalText":"曾子謂子思曰：「汲！","chunks":[["曾子謂子思曰：「汲！","zh-Hant"]]},{"id":"li-ji_ch-3_p-37_s-2","passageId":"li-ji_ch-3_p-37","order":2,"canonicalText":"吾執親之喪也，水漿不入於口者七日。","chunks":[["吾執親之喪也，水漿不入於口者七日。","zh-Hant"]]},{"id":"li-ji_ch-3_p-37_s-3","passageId":"li-ji_ch-3_p-37","order":3,"canonicalText":"」子思曰：「先王之制禮也，過之者俯而就之，不至焉者，跂而及之。","chunks":[["」子思曰：「先王之制禮也，過之者俯而就之，不至焉者，跂而及之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-37_s-4","passageId":"li-ji_ch-3_p-37","order":4,"canonicalText":"故君子之執親之喪也，水漿不入於口者三日，杖而後能起。","chunks":[["故君子之執親之喪也，水漿不入於口者三日，杖而後能起。","zh-Hant"]]},{"id":"li-ji_ch-3_p-37_s-5","passageId":"li-ji_ch-3_p-37","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-38_s-1","passageId":"li-ji_ch-3_p-38","order":1,"canonicalText":"曾子曰：「小功不稅，則是遠兄弟終無服也，而可乎？","chunks":[["曾子曰：「小功不稅，則是遠兄弟終無服也，而可乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-38_s-2","passageId":"li-ji_ch-3_p-38","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-39_s-1","passageId":"li-ji_ch-3_p-39","order":1,"canonicalText":"伯高之喪，孔氏之使者未至，冉子攝束帛、乘馬而將之。","chunks":[["伯高之喪，孔氏之使者未至，冉子攝束帛、乘馬而將之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-39_s-2","passageId":"li-ji_ch-3_p-39","order":2,"canonicalText":"孔子曰：「異哉！","chunks":[["孔子曰：「異哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-39_s-3","passageId":"li-ji_ch-3_p-39","order":3,"canonicalText":"徒使我不誠於伯高。","chunks":[["徒使我不誠於伯高。","zh-Hant"]]},{"id":"li-ji_ch-3_p-39_s-4","passageId":"li-ji_ch-3_p-39","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-1","passageId":"li-ji_ch-3_p-40","order":1,"canonicalText":"伯高死於衛，赴於孔子，孔子曰：「吾惡乎哭諸？","chunks":[["伯高死於衛，赴於孔子，孔子曰：「吾惡乎哭諸？","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-2","passageId":"li-ji_ch-3_p-40","order":2,"canonicalText":"兄弟，吾哭諸廟；","chunks":[["兄弟，吾哭諸廟；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-3","passageId":"li-ji_ch-3_p-40","order":3,"canonicalText":"父之友，吾哭諸廟門之外；","chunks":[["父之友，吾哭諸廟門之外；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-4","passageId":"li-ji_ch-3_p-40","order":4,"canonicalText":"師，吾哭諸寢；","chunks":[["師，吾哭諸寢；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-5","passageId":"li-ji_ch-3_p-40","order":5,"canonicalText":"朋友，吾哭諸寢門之外；","chunks":[["朋友，吾哭諸寢門之外；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-6","passageId":"li-ji_ch-3_p-40","order":6,"canonicalText":"所知，吾哭諸野。","chunks":[["所知，吾哭諸野。","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-7","passageId":"li-ji_ch-3_p-40","order":7,"canonicalText":"於野，則已疏；","chunks":[["於野，則已疏；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-8","passageId":"li-ji_ch-3_p-40","order":8,"canonicalText":"於寢，則已重。","chunks":[["於寢，則已重。","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-9","passageId":"li-ji_ch-3_p-40","order":9,"canonicalText":"夫由賜也見我，吾哭諸賜氏。","chunks":[["夫由賜也見我，吾哭諸賜氏。","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-10","passageId":"li-ji_ch-3_p-40","order":10,"canonicalText":"」遂命子貢為之主，曰：「為爾哭也來者，拜之；","chunks":[["」遂命子貢為之主，曰：「為爾哭也來者，拜之；","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-11","passageId":"li-ji_ch-3_p-40","order":11,"canonicalText":"知伯高而來者，勿拜也。","chunks":[["知伯高而來者，勿拜也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-40_s-12","passageId":"li-ji_ch-3_p-40","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-41_s-1","passageId":"li-ji_ch-3_p-41","order":1,"canonicalText":"曾子曰：「喪有疾，食肉飲酒，必有草木之滋焉。","chunks":[["曾子曰：「喪有疾，食肉飲酒，必有草木之滋焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-41_s-2","passageId":"li-ji_ch-3_p-41","order":2,"canonicalText":"以為姜桂之謂也。","chunks":[["以為姜桂之謂也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-41_s-3","passageId":"li-ji_ch-3_p-41","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-1","passageId":"li-ji_ch-3_p-42","order":1,"canonicalText":"子夏喪其子而喪其明。","chunks":[["子夏喪其子而喪其明。","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-2","passageId":"li-ji_ch-3_p-42","order":2,"canonicalText":"曾子吊之曰：「吾聞之也：朋友喪明則哭之。","chunks":[["曾子吊之曰：「吾聞之也：朋友喪明則哭之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-3","passageId":"li-ji_ch-3_p-42","order":3,"canonicalText":"」曾子哭，子夏亦哭，曰：「天乎！","chunks":[["」曾子哭，子夏亦哭，曰：「天乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-4","passageId":"li-ji_ch-3_p-42","order":4,"canonicalText":"予之無罪也。","chunks":[["予之無罪也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-5","passageId":"li-ji_ch-3_p-42","order":5,"canonicalText":"」曾子怒曰：「商，女何無罪也？","chunks":[["」曾子怒曰：「商，女何無罪也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-6","passageId":"li-ji_ch-3_p-42","order":6,"canonicalText":"吾與女事夫子於洙泗之間，退而老於西河之上，使西河之民疑女於夫子，爾罪一也；","chunks":[["吾與女事夫子於洙泗之間，退而老於西河之上，使西河之民疑女於夫子，爾罪一也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-7","passageId":"li-ji_ch-3_p-42","order":7,"canonicalText":"喪爾親，使民未有聞焉，爾罪二也；","chunks":[["喪爾親，使民未有聞焉，爾罪二也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-8","passageId":"li-ji_ch-3_p-42","order":8,"canonicalText":"喪爾子，喪爾明，爾罪三也。","chunks":[["喪爾子，喪爾明，爾罪三也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-9","passageId":"li-ji_ch-3_p-42","order":9,"canonicalText":"而曰女何無罪與！","chunks":[["而曰女何無罪與！","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-10","passageId":"li-ji_ch-3_p-42","order":10,"canonicalText":"」子夏投其杖而拜曰：「吾過矣！","chunks":[["」子夏投其杖而拜曰：「吾過矣！","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-11","passageId":"li-ji_ch-3_p-42","order":11,"canonicalText":"吾過矣！","chunks":[["吾過矣！","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-12","passageId":"li-ji_ch-3_p-42","order":12,"canonicalText":"吾離群而索居，亦已久矣。","chunks":[["吾離群而索居，亦已久矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-42_s-13","passageId":"li-ji_ch-3_p-42","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-43_s-1","passageId":"li-ji_ch-3_p-43","order":1,"canonicalText":"夫晝居於內，問其疾可也；","chunks":[["夫晝居於內，問其疾可也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-43_s-2","passageId":"li-ji_ch-3_p-43","order":2,"canonicalText":"夜居於外，吊之可也。","chunks":[["夜居於外，吊之可也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-43_s-3","passageId":"li-ji_ch-3_p-43","order":3,"canonicalText":"是故君子非有大故，不宿於外；","chunks":[["是故君子非有大故，不宿於外；","zh-Hant"]]},{"id":"li-ji_ch-3_p-43_s-4","passageId":"li-ji_ch-3_p-43","order":4,"canonicalText":"非致齊也、非疾也，不晝夜居於內。","chunks":[["非致齊也、非疾也，不晝夜居於內。","zh-Hant"]]},{"id":"li-ji_ch-3_p-44_s-1","passageId":"li-ji_ch-3_p-44","order":1,"canonicalText":"高子皋之執親之喪也，泣血三年，未嘗見齒，君子以為難。","chunks":[["高子皋之執親之喪也，泣血三年，未嘗見齒，君子以為難。","zh-Hant"]]},{"id":"li-ji_ch-3_p-45_s-1","passageId":"li-ji_ch-3_p-45","order":1,"canonicalText":"衰，與其不當物也，寧無衰。","chunks":[["衰，與其不當物也，寧無衰。","zh-Hant"]]},{"id":"li-ji_ch-3_p-45_s-2","passageId":"li-ji_ch-3_p-45","order":2,"canonicalText":"齊衰不以邊坐，大功不以服勤。","chunks":[["齊衰不以邊坐，大功不以服勤。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-1","passageId":"li-ji_ch-3_p-46","order":1,"canonicalText":"孔子之衛，遇舊館人之喪，入而哭之哀。","chunks":[["孔子之衛，遇舊館人之喪，入而哭之哀。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-2","passageId":"li-ji_ch-3_p-46","order":2,"canonicalText":"出，使子貢說驂而賻之。","chunks":[["出，使子貢說驂而賻之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-3","passageId":"li-ji_ch-3_p-46","order":3,"canonicalText":"子貢曰：「於門人之喪，未有所說驂，說驂於舊館，無乃已重乎？","chunks":[["子貢曰：「於門人之喪，未有所說驂，說驂於舊館，無乃已重乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-4","passageId":"li-ji_ch-3_p-46","order":4,"canonicalText":"」夫子曰：「予鄉者入而哭之，遇於一哀而出涕。","chunks":[["」夫子曰：「予鄉者入而哭之，遇於一哀而出涕。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-5","passageId":"li-ji_ch-3_p-46","order":5,"canonicalText":"予惡夫涕之無從也。","chunks":[["予惡夫涕之無從也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-6","passageId":"li-ji_ch-3_p-46","order":6,"canonicalText":"小子行之。","chunks":[["小子行之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-46_s-7","passageId":"li-ji_ch-3_p-46","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-1","passageId":"li-ji_ch-3_p-47","order":1,"canonicalText":"孔子在衛，有送葬者，而夫子觀之，曰：「善哉為喪乎！","chunks":[["孔子在衛，有送葬者，而夫子觀之，曰：「善哉為喪乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-2","passageId":"li-ji_ch-3_p-47","order":2,"canonicalText":"足以為法矣，小子識之。","chunks":[["足以為法矣，小子識之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-3","passageId":"li-ji_ch-3_p-47","order":3,"canonicalText":"」子貢曰：「夫子何善爾也？","chunks":[["」子貢曰：「夫子何善爾也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-4","passageId":"li-ji_ch-3_p-47","order":4,"canonicalText":"」曰：「其往也如慕，其反也如疑。","chunks":[["」曰：「其往也如慕，其反也如疑。","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-5","passageId":"li-ji_ch-3_p-47","order":5,"canonicalText":"」子貢曰：「豈若速反而虞乎？","chunks":[["」子貢曰：「豈若速反而虞乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-6","passageId":"li-ji_ch-3_p-47","order":6,"canonicalText":"」子曰：「小子識之，我未之能行也。","chunks":[["」子曰：「小子識之，我未之能行也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-47_s-7","passageId":"li-ji_ch-3_p-47","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-48_s-1","passageId":"li-ji_ch-3_p-48","order":1,"canonicalText":"顏淵之喪，饋祥肉，孔子出受之，入，彈琴而後食之。","chunks":[["顏淵之喪，饋祥肉，孔子出受之，入，彈琴而後食之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-49_s-1","passageId":"li-ji_ch-3_p-49","order":1,"canonicalText":"孔子與門人立，拱而尚右，二三子亦皆尚右。","chunks":[["孔子與門人立，拱而尚右，二三子亦皆尚右。","zh-Hant"]]},{"id":"li-ji_ch-3_p-49_s-2","passageId":"li-ji_ch-3_p-49","order":2,"canonicalText":"孔子曰：「二三子之嗜學也，我則有姊之喪故也。","chunks":[["孔子曰：「二三子之嗜學也，我則有姊之喪故也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-49_s-3","passageId":"li-ji_ch-3_p-49","order":3,"canonicalText":"」二三子皆尚左。","chunks":[["」二三子皆尚左。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-1","passageId":"li-ji_ch-3_p-50","order":1,"canonicalText":"孔子蚤作，負手曳杖，消搖於門，歌曰：「泰山其頹乎？","chunks":[["孔子蚤作，負手曳杖，消搖於門，歌曰：「泰山其頹乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-2","passageId":"li-ji_ch-3_p-50","order":2,"canonicalText":"梁木其壞乎？","chunks":[["梁木其壞乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-3","passageId":"li-ji_ch-3_p-50","order":3,"canonicalText":"哲人其萎乎？","chunks":[["哲人其萎乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-4","passageId":"li-ji_ch-3_p-50","order":4,"canonicalText":"」既歌而入，當戶而坐。","chunks":[["」既歌而入，當戶而坐。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-5","passageId":"li-ji_ch-3_p-50","order":5,"canonicalText":"子貢聞之曰：「泰山其頹，則吾將安仰？","chunks":[["子貢聞之曰：「泰山其頹，則吾將安仰？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-6","passageId":"li-ji_ch-3_p-50","order":6,"canonicalText":"梁木其壞、哲人其萎，則吾將安放？","chunks":[["梁木其壞、哲人其萎，則吾將安放？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-7","passageId":"li-ji_ch-3_p-50","order":7,"canonicalText":"夫子殆將病也。","chunks":[["夫子殆將病也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-8","passageId":"li-ji_ch-3_p-50","order":8,"canonicalText":"」遂趨而入。","chunks":[["」遂趨而入。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-9","passageId":"li-ji_ch-3_p-50","order":9,"canonicalText":"夫子曰：「賜！","chunks":[["夫子曰：「賜！","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-10","passageId":"li-ji_ch-3_p-50","order":10,"canonicalText":"爾來何遲也？","chunks":[["爾來何遲也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-11","passageId":"li-ji_ch-3_p-50","order":11,"canonicalText":"夏后氏殯於東階之上，則猶在阼也；","chunks":[["夏后氏殯於東階之上，則猶在阼也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-12","passageId":"li-ji_ch-3_p-50","order":12,"canonicalText":"殷人殯於兩楹之間，則與賓主夾之也；","chunks":[["殷人殯於兩楹之間，則與賓主夾之也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-13","passageId":"li-ji_ch-3_p-50","order":13,"canonicalText":"周人殯於西階之上，則猶賓之也。","chunks":[["周人殯於西階之上，則猶賓之也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-14","passageId":"li-ji_ch-3_p-50","order":14,"canonicalText":"而丘也殷人也。","chunks":[["而丘也殷人也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-15","passageId":"li-ji_ch-3_p-50","order":15,"canonicalText":"予疇昔之夜，夢坐奠於兩楹之間。","chunks":[["予疇昔之夜，夢坐奠於兩楹之間。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-16","passageId":"li-ji_ch-3_p-50","order":16,"canonicalText":"夫明王不興，而天下其孰能宗予？","chunks":[["夫明王不興，而天下其孰能宗予？","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-17","passageId":"li-ji_ch-3_p-50","order":17,"canonicalText":"予殆將死也。","chunks":[["予殆將死也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-50_s-18","passageId":"li-ji_ch-3_p-50","order":18,"canonicalText":"」蓋寢疾七日而沒。","chunks":[["」蓋寢疾七日而沒。","zh-Hant"]]},{"id":"li-ji_ch-3_p-51_s-1","passageId":"li-ji_ch-3_p-51","order":1,"canonicalText":"孔子之喪，門人疑所服。","chunks":[["孔子之喪，門人疑所服。","zh-Hant"]]},{"id":"li-ji_ch-3_p-51_s-2","passageId":"li-ji_ch-3_p-51","order":2,"canonicalText":"子貢曰：「昔者夫子之喪顏淵，若喪子而無服；","chunks":[["子貢曰：「昔者夫子之喪顏淵，若喪子而無服；","zh-Hant"]]},{"id":"li-ji_ch-3_p-51_s-3","passageId":"li-ji_ch-3_p-51","order":3,"canonicalText":"喪子路亦然。","chunks":[["喪子路亦然。","zh-Hant"]]},{"id":"li-ji_ch-3_p-51_s-4","passageId":"li-ji_ch-3_p-51","order":4,"canonicalText":"請喪夫子，若喪父而無服。","chunks":[["請喪夫子，若喪父而無服。","zh-Hant"]]},{"id":"li-ji_ch-3_p-51_s-5","passageId":"li-ji_ch-3_p-51","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-52_s-1","passageId":"li-ji_ch-3_p-52","order":1,"canonicalText":"孔子之喪，公西赤為志焉：飾棺、墻，置翣設披，周也；","chunks":[["孔子之喪，公西赤為志焉：飾棺、墻，置翣設披，周也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-52_s-2","passageId":"li-ji_ch-3_p-52","order":2,"canonicalText":"設崇，殷也；","chunks":[["設崇，殷也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-52_s-3","passageId":"li-ji_ch-3_p-52","order":3,"canonicalText":"綢練設旐，夏也。","chunks":[["綢練設旐，夏也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-53_s-1","passageId":"li-ji_ch-3_p-53","order":1,"canonicalText":"子張之喪，公明儀為志焉；","chunks":[["子張之喪，公明儀為志焉；","zh-Hant"]]},{"id":"li-ji_ch-3_p-53_s-2","passageId":"li-ji_ch-3_p-53","order":2,"canonicalText":"褚幕丹質，蟻結于四隅，殷士也。","chunks":[["褚幕丹質，蟻結于四隅，殷士也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-1","passageId":"li-ji_ch-3_p-54","order":1,"canonicalText":"子夏問於孔子曰：「居父母之仇如之何？","chunks":[["子夏問於孔子曰：「居父母之仇如之何？","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-2","passageId":"li-ji_ch-3_p-54","order":2,"canonicalText":"」夫子曰：「寢苫枕干，不仕，弗與共天下也；","chunks":[["」夫子曰：「寢苫枕干，不仕，弗與共天下也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-3","passageId":"li-ji_ch-3_p-54","order":3,"canonicalText":"遇諸市朝，不反兵而鬥。","chunks":[["遇諸市朝，不反兵而鬥。","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-4","passageId":"li-ji_ch-3_p-54","order":4,"canonicalText":"」曰：「請問居昆弟之仇如之何？","chunks":[["」曰：「請問居昆弟之仇如之何？","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-5","passageId":"li-ji_ch-3_p-54","order":5,"canonicalText":"」曰：「仕弗與共國；","chunks":[["」曰：「仕弗與共國；","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-6","passageId":"li-ji_ch-3_p-54","order":6,"canonicalText":"銜君命而使，雖遇之不鬥。","chunks":[["銜君命而使，雖遇之不鬥。","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-7","passageId":"li-ji_ch-3_p-54","order":7,"canonicalText":"」曰：「請問居從父昆弟之仇如之何？","chunks":[["」曰：「請問居從父昆弟之仇如之何？","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-8","passageId":"li-ji_ch-3_p-54","order":8,"canonicalText":"」曰：「不為魁，主人能，則執兵而陪其後。","chunks":[["」曰：「不為魁，主人能，則執兵而陪其後。","zh-Hant"]]},{"id":"li-ji_ch-3_p-54_s-9","passageId":"li-ji_ch-3_p-54","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-55_s-1","passageId":"li-ji_ch-3_p-55","order":1,"canonicalText":"孔子之喪，二三子皆絰而出。","chunks":[["孔子之喪，二三子皆絰而出。","zh-Hant"]]},{"id":"li-ji_ch-3_p-55_s-2","passageId":"li-ji_ch-3_p-55","order":2,"canonicalText":"群居則絰，出則否。","chunks":[["群居則絰，出則否。","zh-Hant"]]},{"id":"li-ji_ch-3_p-56_s-1","passageId":"li-ji_ch-3_p-56","order":1,"canonicalText":"易墓，非古也。","chunks":[["易墓，非古也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-57_s-1","passageId":"li-ji_ch-3_p-57","order":1,"canonicalText":"子路曰：「吾聞諸夫子：喪禮，與其哀不足而禮有餘也，不若禮不足而哀有餘也。","chunks":[["子路曰：「吾聞諸夫子：喪禮，與其哀不足而禮有餘也，不若禮不足而哀有餘也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-57_s-2","passageId":"li-ji_ch-3_p-57","order":2,"canonicalText":"祭禮，與其敬不足而禮有餘也，不若禮不足而敬有餘也。","chunks":[["祭禮，與其敬不足而禮有餘也，不若禮不足而敬有餘也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-57_s-3","passageId":"li-ji_ch-3_p-57","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-1","passageId":"li-ji_ch-3_p-58","order":1,"canonicalText":"曾子吊於負夏，主人既祖，填池，推柩而反之，降婦人而後行禮。","chunks":[["曾子吊於負夏，主人既祖，填池，推柩而反之，降婦人而後行禮。","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-2","passageId":"li-ji_ch-3_p-58","order":2,"canonicalText":"從者曰：「禮與？","chunks":[["從者曰：「禮與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-3","passageId":"li-ji_ch-3_p-58","order":3,"canonicalText":"」曾子曰：「夫祖者且也；","chunks":[["」曾子曰：「夫祖者且也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-4","passageId":"li-ji_ch-3_p-58","order":4,"canonicalText":"且，胡為其不可以反宿也？","chunks":[["且，胡為其不可以反宿也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-5","passageId":"li-ji_ch-3_p-58","order":5,"canonicalText":"」從者又問諸子游曰：「禮與？","chunks":[["」從者又問諸子游曰：「禮與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-6","passageId":"li-ji_ch-3_p-58","order":6,"canonicalText":"」子游曰：「飯於牖下，小斂於戶內，大斂於阼，殯於客位，祖於庭，葬於墓，所以即遠也。","chunks":[["」子游曰：「飯於牖下，小斂於戶內，大斂於阼，殯於客位，祖於庭，葬於墓，所以即遠也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-7","passageId":"li-ji_ch-3_p-58","order":7,"canonicalText":"故喪事有進而無退。","chunks":[["故喪事有進而無退。","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-8","passageId":"li-ji_ch-3_p-58","order":8,"canonicalText":"」曾子聞之曰：「多矣乎，予出祖者。","chunks":[["」曾子聞之曰：「多矣乎，予出祖者。","zh-Hant"]]},{"id":"li-ji_ch-3_p-58_s-9","passageId":"li-ji_ch-3_p-58","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-1","passageId":"li-ji_ch-3_p-59","order":1,"canonicalText":"曾子襲裘而吊，子游裼裘而吊。","chunks":[["曾子襲裘而吊，子游裼裘而吊。","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-2","passageId":"li-ji_ch-3_p-59","order":2,"canonicalText":"曾子指子游而示人曰：「夫夫也，為習於禮者，如之何其裼裘而吊也？","chunks":[["曾子指子游而示人曰：「夫夫也，為習於禮者，如之何其裼裘而吊也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-3","passageId":"li-ji_ch-3_p-59","order":3,"canonicalText":"」主人既小斂、袒、括髮；","chunks":[["」主人既小斂、袒、括髮；","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-4","passageId":"li-ji_ch-3_p-59","order":4,"canonicalText":"子游趨而出，襲裘帶絰而入。","chunks":[["子游趨而出，襲裘帶絰而入。","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-5","passageId":"li-ji_ch-3_p-59","order":5,"canonicalText":"曾子曰：「我過矣，我過矣，夫夫是也。","chunks":[["曾子曰：「我過矣，我過矣，夫夫是也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-59_s-6","passageId":"li-ji_ch-3_p-59","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-60_s-1","passageId":"li-ji_ch-3_p-60","order":1,"canonicalText":"子夏既除喪而見，予之琴，和之不和，彈之而不成聲。","chunks":[["子夏既除喪而見，予之琴，和之不和，彈之而不成聲。","zh-Hant"]]},{"id":"li-ji_ch-3_p-60_s-2","passageId":"li-ji_ch-3_p-60","order":2,"canonicalText":"作而曰：「哀未忘也。","chunks":[["作而曰：「哀未忘也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-60_s-3","passageId":"li-ji_ch-3_p-60","order":3,"canonicalText":"先王制禮，而弗敢過也。","chunks":[["先王制禮，而弗敢過也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-60_s-4","passageId":"li-ji_ch-3_p-60","order":4,"canonicalText":"」子張既除喪而見，予之琴，和之而和，彈之而成聲，作而曰：「先王制禮不敢不至焉。","chunks":[["」子張既除喪而見，予之琴，和之而和，彈之而成聲，作而曰：「先王制禮不敢不至焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-60_s-5","passageId":"li-ji_ch-3_p-60","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-1","passageId":"li-ji_ch-3_p-61","order":1,"canonicalText":"司寇惠子之喪，子游為之麻衰牡麻絰，文子辭曰：「子辱與彌牟之弟游，又辱為之服，敢辭。","chunks":[["司寇惠子之喪，子游為之麻衰牡麻絰，文子辭曰：「子辱與彌牟之弟游，又辱為之服，敢辭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-2","passageId":"li-ji_ch-3_p-61","order":2,"canonicalText":"」子游曰：「禮也。","chunks":[["」子游曰：「禮也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-3","passageId":"li-ji_ch-3_p-61","order":3,"canonicalText":"」文子退反哭，子游趨而就諸臣之位，文子又辭曰：「子辱與彌牟之弟游，又辱為之服，又辱臨其喪，敢辭。","chunks":[["」文子退反哭，子游趨而就諸臣之位，文子又辭曰：「子辱與彌牟之弟游，又辱為之服，又辱臨其喪，敢辭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-4","passageId":"li-ji_ch-3_p-61","order":4,"canonicalText":"」子游曰：「固以請。","chunks":[["」子游曰：「固以請。","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-5","passageId":"li-ji_ch-3_p-61","order":5,"canonicalText":"」文子退，扶適子南面而立曰：「子辱與彌牟之弟游，又辱為之服，又辱臨其喪，虎也敢不復位。","chunks":[["」文子退，扶適子南面而立曰：「子辱與彌牟之弟游，又辱為之服，又辱臨其喪，虎也敢不復位。","zh-Hant"]]},{"id":"li-ji_ch-3_p-61_s-6","passageId":"li-ji_ch-3_p-61","order":6,"canonicalText":"」子游趨而就客位。","chunks":[["」子游趨而就客位。","zh-Hant"]]},{"id":"li-ji_ch-3_p-62_s-1","passageId":"li-ji_ch-3_p-62","order":1,"canonicalText":"將軍文子之喪，既除喪，而後越人來吊，主人深衣練冠，待于廟，垂涕洟，子游觀之曰：「將軍文氏之子其庶几乎！","chunks":[["將軍文子之喪，既除喪，而後越人來吊，主人深衣練冠，待于廟，垂涕洟，子游觀之曰：「將軍文氏之子其庶几乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-62_s-2","passageId":"li-ji_ch-3_p-62","order":2,"canonicalText":"亡於禮者之禮也，其動也中。","chunks":[["亡於禮者之禮也，其動也中。","zh-Hant"]]},{"id":"li-ji_ch-3_p-62_s-3","passageId":"li-ji_ch-3_p-62","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-63_s-1","passageId":"li-ji_ch-3_p-63","order":1,"canonicalText":"幼名，冠字，五十以伯仲，死謚，周道也。","chunks":[["幼名，冠字，五十以伯仲，死謚，周道也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-64_s-1","passageId":"li-ji_ch-3_p-64","order":1,"canonicalText":"絰也者，實也。","chunks":[["絰也者，實也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-64_s-2","passageId":"li-ji_ch-3_p-64","order":2,"canonicalText":"掘中溜而浴，毀灶以綴足；","chunks":[["掘中溜而浴，毀灶以綴足；","zh-Hant"]]},{"id":"li-ji_ch-3_p-64_s-3","passageId":"li-ji_ch-3_p-64","order":3,"canonicalText":"及葬，毀宗躐行，出于大門，殷道也。","chunks":[["及葬，毀宗躐行，出于大門，殷道也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-64_s-4","passageId":"li-ji_ch-3_p-64","order":4,"canonicalText":"學者行之。","chunks":[["學者行之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-1","passageId":"li-ji_ch-3_p-65","order":1,"canonicalText":"子柳之母死，子碩請具。","chunks":[["子柳之母死，子碩請具。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-2","passageId":"li-ji_ch-3_p-65","order":2,"canonicalText":"子柳曰：「何以哉？","chunks":[["子柳曰：「何以哉？","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-3","passageId":"li-ji_ch-3_p-65","order":3,"canonicalText":"」子碩曰：「請粥庶弟之母。","chunks":[["」子碩曰：「請粥庶弟之母。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-4","passageId":"li-ji_ch-3_p-65","order":4,"canonicalText":"」子柳曰：「如之何其粥人之母以葬其母也？","chunks":[["」子柳曰：「如之何其粥人之母以葬其母也？","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-5","passageId":"li-ji_ch-3_p-65","order":5,"canonicalText":"不可。","chunks":[["不可。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-6","passageId":"li-ji_ch-3_p-65","order":6,"canonicalText":"」既葬，子碩欲以賻布之餘具祭器。","chunks":[["」既葬，子碩欲以賻布之餘具祭器。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-7","passageId":"li-ji_ch-3_p-65","order":7,"canonicalText":"子柳曰：「不可，吾聞之也：君子不家於喪。","chunks":[["子柳曰：「不可，吾聞之也：君子不家於喪。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-8","passageId":"li-ji_ch-3_p-65","order":8,"canonicalText":"請班諸兄弟之貧者。","chunks":[["請班諸兄弟之貧者。","zh-Hant"]]},{"id":"li-ji_ch-3_p-65_s-9","passageId":"li-ji_ch-3_p-65","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-66_s-1","passageId":"li-ji_ch-3_p-66","order":1,"canonicalText":"君子曰：「謀人之軍師，敗則死之；","chunks":[["君子曰：「謀人之軍師，敗則死之；","zh-Hant"]]},{"id":"li-ji_ch-3_p-66_s-2","passageId":"li-ji_ch-3_p-66","order":2,"canonicalText":"謀人之邦邑，危則亡之。","chunks":[["謀人之邦邑，危則亡之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-66_s-3","passageId":"li-ji_ch-3_p-66","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-67_s-1","passageId":"li-ji_ch-3_p-67","order":1,"canonicalText":"公叔文子升於瑕丘，蘧伯玉從。","chunks":[["公叔文子升於瑕丘，蘧伯玉從。","zh-Hant"]]},{"id":"li-ji_ch-3_p-67_s-2","passageId":"li-ji_ch-3_p-67","order":2,"canonicalText":"文子曰：「樂哉斯丘也，死則我欲葬焉。","chunks":[["文子曰：「樂哉斯丘也，死則我欲葬焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-67_s-3","passageId":"li-ji_ch-3_p-67","order":3,"canonicalText":"」蘧伯玉曰：「吾子樂之，則瑗請前。","chunks":[["」蘧伯玉曰：「吾子樂之，則瑗請前。","zh-Hant"]]},{"id":"li-ji_ch-3_p-67_s-4","passageId":"li-ji_ch-3_p-67","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-68_s-1","passageId":"li-ji_ch-3_p-68","order":1,"canonicalText":"弁人有其母死而孺子泣者，孔子曰：「哀則哀矣，而難為繼也。","chunks":[["弁人有其母死而孺子泣者，孔子曰：「哀則哀矣，而難為繼也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-68_s-2","passageId":"li-ji_ch-3_p-68","order":2,"canonicalText":"夫禮，為可傳也，為可繼也。","chunks":[["夫禮，為可傳也，為可繼也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-68_s-3","passageId":"li-ji_ch-3_p-68","order":3,"canonicalText":"故哭踴有節。","chunks":[["故哭踴有節。","zh-Hant"]]},{"id":"li-ji_ch-3_p-68_s-4","passageId":"li-ji_ch-3_p-68","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-69_s-1","passageId":"li-ji_ch-3_p-69","order":1,"canonicalText":"叔孫武叔之母死，既小斂，舉者出戶，出戶袒，且投其冠括髮。","chunks":[["叔孫武叔之母死，既小斂，舉者出戶，出戶袒，且投其冠括髮。","zh-Hant"]]},{"id":"li-ji_ch-3_p-69_s-2","passageId":"li-ji_ch-3_p-69","order":2,"canonicalText":"子游曰：「知禮。","chunks":[["子游曰：「知禮。","zh-Hant"]]},{"id":"li-ji_ch-3_p-69_s-3","passageId":"li-ji_ch-3_p-69","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-70_s-1","passageId":"li-ji_ch-3_p-70","order":1,"canonicalText":"扶君，卜人師扶右，射人師扶左；","chunks":[["扶君，卜人師扶右，射人師扶左；","zh-Hant"]]},{"id":"li-ji_ch-3_p-70_s-2","passageId":"li-ji_ch-3_p-70","order":2,"canonicalText":"君薨以是舉。","chunks":[["君薨以是舉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-71_s-1","passageId":"li-ji_ch-3_p-71","order":1,"canonicalText":"從母之夫，舅之妻，二夫人相為服，君子未之言也。","chunks":[["從母之夫，舅之妻，二夫人相為服，君子未之言也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-71_s-2","passageId":"li-ji_ch-3_p-71","order":2,"canonicalText":"或曰同爨緦。","chunks":[["或曰同爨緦。","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-1","passageId":"li-ji_ch-3_p-72","order":1,"canonicalText":"喪事，欲其縱縱爾；","chunks":[["喪事，欲其縱縱爾；","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-2","passageId":"li-ji_ch-3_p-72","order":2,"canonicalText":"吉事，欲其折折爾。","chunks":[["吉事，欲其折折爾。","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-3","passageId":"li-ji_ch-3_p-72","order":3,"canonicalText":"故喪事雖遽，不陵節；","chunks":[["故喪事雖遽，不陵節；","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-4","passageId":"li-ji_ch-3_p-72","order":4,"canonicalText":"吉事雖止，不怠。","chunks":[["吉事雖止，不怠。","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-5","passageId":"li-ji_ch-3_p-72","order":5,"canonicalText":"故騷騷爾則野，鼎鼎爾則小人。","chunks":[["故騷騷爾則野，鼎鼎爾則小人。","zh-Hant"]]},{"id":"li-ji_ch-3_p-72_s-6","passageId":"li-ji_ch-3_p-72","order":6,"canonicalText":"君子蓋猶猶爾。","chunks":[["君子蓋猶猶爾。","zh-Hant"]]},{"id":"li-ji_ch-3_p-73_s-1","passageId":"li-ji_ch-3_p-73","order":1,"canonicalText":"喪具，君子恥具，一日二日而可為也者，君子弗為也。","chunks":[["喪具，君子恥具，一日二日而可為也者，君子弗為也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-73_s-2","passageId":"li-ji_ch-3_p-73","order":2,"canonicalText":"喪服，兄弟之子猶子也，蓋引而進之也；","chunks":[["喪服，兄弟之子猶子也，蓋引而進之也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-73_s-3","passageId":"li-ji_ch-3_p-73","order":3,"canonicalText":"嫂叔之無服也，蓋推而遠之也；","chunks":[["嫂叔之無服也，蓋推而遠之也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-73_s-4","passageId":"li-ji_ch-3_p-73","order":4,"canonicalText":"姑姊妹之薄也，蓋有受我而厚之者也。","chunks":[["姑姊妹之薄也，蓋有受我而厚之者也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-73_s-5","passageId":"li-ji_ch-3_p-73","order":5,"canonicalText":"食於有喪者之側，未嘗飽也。","chunks":[["食於有喪者之側，未嘗飽也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-74_s-1","passageId":"li-ji_ch-3_p-74","order":1,"canonicalText":"曾子與客立於門側，其徒趨而出。","chunks":[["曾子與客立於門側，其徒趨而出。","zh-Hant"]]},{"id":"li-ji_ch-3_p-74_s-2","passageId":"li-ji_ch-3_p-74","order":2,"canonicalText":"曾子曰：「爾將何之？","chunks":[["曾子曰：「爾將何之？","zh-Hant"]]},{"id":"li-ji_ch-3_p-74_s-3","passageId":"li-ji_ch-3_p-74","order":3,"canonicalText":"」曰：「吾父死，將出哭於巷。","chunks":[["」曰：「吾父死，將出哭於巷。","zh-Hant"]]},{"id":"li-ji_ch-3_p-74_s-4","passageId":"li-ji_ch-3_p-74","order":4,"canonicalText":"」曰：「反，哭於爾次。","chunks":[["」曰：「反，哭於爾次。","zh-Hant"]]},{"id":"li-ji_ch-3_p-74_s-5","passageId":"li-ji_ch-3_p-74","order":5,"canonicalText":"」曾子北面而吊焉。","chunks":[["」曾子北面而吊焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-75_s-1","passageId":"li-ji_ch-3_p-75","order":1,"canonicalText":"孔子曰：「之死而致死之，不仁而不可為也；","chunks":[["孔子曰：「之死而致死之，不仁而不可為也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-75_s-2","passageId":"li-ji_ch-3_p-75","order":2,"canonicalText":"之死而致生之，不知而不可為也。","chunks":[["之死而致生之，不知而不可為也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-75_s-3","passageId":"li-ji_ch-3_p-75","order":3,"canonicalText":"是故，竹不成用，瓦不成味，木不成斫，琴瑟張而不平，竽笙備而不和，有鐘磬而無簨虡，其曰明器，神明之也。","chunks":[["是故，竹不成用，瓦不成味，木不成斫，琴瑟張而不平，竽笙備而不和，有鐘磬而無簨虡，其曰明器，神明之也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-75_s-4","passageId":"li-ji_ch-3_p-75","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-1","passageId":"li-ji_ch-3_p-76","order":1,"canonicalText":"有子問於曾子曰：「問喪於夫子乎？","chunks":[["有子問於曾子曰：「問喪於夫子乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-2","passageId":"li-ji_ch-3_p-76","order":2,"canonicalText":"」曰：「聞之矣：喪欲速貧，死欲速朽。","chunks":[["」曰：「聞之矣：喪欲速貧，死欲速朽。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-3","passageId":"li-ji_ch-3_p-76","order":3,"canonicalText":"」有子曰：「是非君子之言也。","chunks":[["」有子曰：「是非君子之言也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-4","passageId":"li-ji_ch-3_p-76","order":4,"canonicalText":"」曾子曰：「參也聞諸夫子也。","chunks":[["」曾子曰：「參也聞諸夫子也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-5","passageId":"li-ji_ch-3_p-76","order":5,"canonicalText":"」有子又曰：「是非君子之言也。","chunks":[["」有子又曰：「是非君子之言也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-6","passageId":"li-ji_ch-3_p-76","order":6,"canonicalText":"」曾子曰：「參也與子游聞之。","chunks":[["」曾子曰：「參也與子游聞之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-7","passageId":"li-ji_ch-3_p-76","order":7,"canonicalText":"」有子曰：「然，然則夫子有為言之也。","chunks":[["」有子曰：「然，然則夫子有為言之也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-76_s-8","passageId":"li-ji_ch-3_p-76","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-1","passageId":"li-ji_ch-3_p-77","order":1,"canonicalText":"曾子以斯言告於子游。","chunks":[["曾子以斯言告於子游。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-2","passageId":"li-ji_ch-3_p-77","order":2,"canonicalText":"子游曰：「甚哉，有子之言似夫子也。","chunks":[["子游曰：「甚哉，有子之言似夫子也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-3","passageId":"li-ji_ch-3_p-77","order":3,"canonicalText":"昔者夫子居於宋，見桓司馬自為石槨，三年而不成。","chunks":[["昔者夫子居於宋，見桓司馬自為石槨，三年而不成。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-4","passageId":"li-ji_ch-3_p-77","order":4,"canonicalText":"夫子曰：『若是其靡也，死不如速朽之愈也。","chunks":[["夫子曰：『若是其靡也，死不如速朽之愈也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-5","passageId":"li-ji_ch-3_p-77","order":5,"canonicalText":"』死之欲速朽，為桓司馬言之也。","chunks":[["』死之欲速朽，為桓司馬言之也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-6","passageId":"li-ji_ch-3_p-77","order":6,"canonicalText":"南宮敬叔反，必載寶而朝。","chunks":[["南宮敬叔反，必載寶而朝。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-7","passageId":"li-ji_ch-3_p-77","order":7,"canonicalText":"夫子曰：『若是其貨也，喪不如速貧之愈也。","chunks":[["夫子曰：『若是其貨也，喪不如速貧之愈也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-8","passageId":"li-ji_ch-3_p-77","order":8,"canonicalText":"』喪之欲速貧，為敬叔言之也。","chunks":[["』喪之欲速貧，為敬叔言之也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-77_s-9","passageId":"li-ji_ch-3_p-77","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-78_s-1","passageId":"li-ji_ch-3_p-78","order":1,"canonicalText":"曾子以子游之言告於有子，有子曰：「然，吾固曰：非夫子之言也。","chunks":[["曾子以子游之言告於有子，有子曰：「然，吾固曰：非夫子之言也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-78_s-2","passageId":"li-ji_ch-3_p-78","order":2,"canonicalText":"」曾子曰：「子何以知之？","chunks":[["」曾子曰：「子何以知之？","zh-Hant"]]},{"id":"li-ji_ch-3_p-78_s-3","passageId":"li-ji_ch-3_p-78","order":3,"canonicalText":"」有子曰：「夫子制於中都，四寸之棺，五寸之槨，以斯知不欲速朽也。","chunks":[["」有子曰：「夫子制於中都，四寸之棺，五寸之槨，以斯知不欲速朽也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-78_s-4","passageId":"li-ji_ch-3_p-78","order":4,"canonicalText":"昔者夫子失魯司寇，將之荊，蓋先之以子夏，又申之以冉有，以斯知不欲速貧也。","chunks":[["昔者夫子失魯司寇，將之荊，蓋先之以子夏，又申之以冉有，以斯知不欲速貧也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-78_s-5","passageId":"li-ji_ch-3_p-78","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-1","passageId":"li-ji_ch-3_p-79","order":1,"canonicalText":"陳莊子死，赴於魯，魯人欲勿哭，繆公召縣子而問焉。","chunks":[["陳莊子死，赴於魯，魯人欲勿哭，繆公召縣子而問焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-2","passageId":"li-ji_ch-3_p-79","order":2,"canonicalText":"縣子曰：「古之大夫，束修之問不出竟，雖欲哭之，安得而哭之？","chunks":[["縣子曰：「古之大夫，束修之問不出竟，雖欲哭之，安得而哭之？","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-3","passageId":"li-ji_ch-3_p-79","order":3,"canonicalText":"今之大夫，交政於中國，雖欲勿哭，焉得而弗哭？","chunks":[["今之大夫，交政於中國，雖欲勿哭，焉得而弗哭？","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-4","passageId":"li-ji_ch-3_p-79","order":4,"canonicalText":"且且臣聞之，哭有二道：有愛而哭之，有畏而哭之。","chunks":[["且且臣聞之，哭有二道：有愛而哭之，有畏而哭之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-5","passageId":"li-ji_ch-3_p-79","order":5,"canonicalText":"」公曰：「然，然則如之何而可？","chunks":[["」公曰：「然，然則如之何而可？","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-6","passageId":"li-ji_ch-3_p-79","order":6,"canonicalText":"」縣子曰：「請哭諸異姓之廟。","chunks":[["」縣子曰：「請哭諸異姓之廟。","zh-Hant"]]},{"id":"li-ji_ch-3_p-79_s-7","passageId":"li-ji_ch-3_p-79","order":7,"canonicalText":"」於是與哭諸縣氏。","chunks":[["」於是與哭諸縣氏。","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-1","passageId":"li-ji_ch-3_p-80","order":1,"canonicalText":"仲憲言於曾子曰：「夏后氏用明器，示民無知也；","chunks":[["仲憲言於曾子曰：「夏后氏用明器，示民無知也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-2","passageId":"li-ji_ch-3_p-80","order":2,"canonicalText":"殷人用祭器，示民有知也；","chunks":[["殷人用祭器，示民有知也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-3","passageId":"li-ji_ch-3_p-80","order":3,"canonicalText":"周人兼用之，示民疑也。","chunks":[["周人兼用之，示民疑也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-4","passageId":"li-ji_ch-3_p-80","order":4,"canonicalText":"」曾子曰：「其不然乎！","chunks":[["」曾子曰：「其不然乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-5","passageId":"li-ji_ch-3_p-80","order":5,"canonicalText":"其不然乎！","chunks":[["其不然乎！","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-6","passageId":"li-ji_ch-3_p-80","order":6,"canonicalText":"夫明器，鬼器也；","chunks":[["夫明器，鬼器也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-7","passageId":"li-ji_ch-3_p-80","order":7,"canonicalText":"祭器，人器也；","chunks":[["祭器，人器也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-8","passageId":"li-ji_ch-3_p-80","order":8,"canonicalText":"夫古之人，胡為而死其親乎？","chunks":[["夫古之人，胡為而死其親乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-80_s-9","passageId":"li-ji_ch-3_p-80","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-1","passageId":"li-ji_ch-3_p-81","order":1,"canonicalText":"公叔木有同母異父之昆弟死，問於子游。","chunks":[["公叔木有同母異父之昆弟死，問於子游。","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-2","passageId":"li-ji_ch-3_p-81","order":2,"canonicalText":"子游曰：「其大功乎？","chunks":[["子游曰：「其大功乎？","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-3","passageId":"li-ji_ch-3_p-81","order":3,"canonicalText":"」狄儀有同母異父之昆弟死，問於子夏，子夏曰：「我未之前聞也；","chunks":[["」狄儀有同母異父之昆弟死，問於子夏，子夏曰：「我未之前聞也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-4","passageId":"li-ji_ch-3_p-81","order":4,"canonicalText":"魯人則為之齊衰。","chunks":[["魯人則為之齊衰。","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-5","passageId":"li-ji_ch-3_p-81","order":5,"canonicalText":"」狄儀行齊衰。","chunks":[["」狄儀行齊衰。","zh-Hant"]]},{"id":"li-ji_ch-3_p-81_s-6","passageId":"li-ji_ch-3_p-81","order":6,"canonicalText":"今之齊衰，狄儀之問也。","chunks":[["今之齊衰，狄儀之問也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-1","passageId":"li-ji_ch-3_p-82","order":1,"canonicalText":"子思之母死於衛，柳若謂子思曰：「子，聖人之後也，四方於子乎觀禮，子蓋慎諸。","chunks":[["子思之母死於衛，柳若謂子思曰：「子，聖人之後也，四方於子乎觀禮，子蓋慎諸。","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-2","passageId":"li-ji_ch-3_p-82","order":2,"canonicalText":"」子思曰：「吾何慎哉？","chunks":[["」子思曰：「吾何慎哉？","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-3","passageId":"li-ji_ch-3_p-82","order":3,"canonicalText":"吾聞之：有其禮，無其財，君子弗行也；","chunks":[["吾聞之：有其禮，無其財，君子弗行也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-4","passageId":"li-ji_ch-3_p-82","order":4,"canonicalText":"有其禮，有其財，無其時，君子弗行也。","chunks":[["有其禮，有其財，無其時，君子弗行也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-5","passageId":"li-ji_ch-3_p-82","order":5,"canonicalText":"吾何慎哉！","chunks":[["吾何慎哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-82_s-6","passageId":"li-ji_ch-3_p-82","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-83_s-1","passageId":"li-ji_ch-3_p-83","order":1,"canonicalText":"縣子瑣曰：「吾聞之：古者不降，上下各以其親。","chunks":[["縣子瑣曰：「吾聞之：古者不降，上下各以其親。","zh-Hant"]]},{"id":"li-ji_ch-3_p-83_s-2","passageId":"li-ji_ch-3_p-83","order":2,"canonicalText":"滕伯文為孟虎齊衰，其叔父也；","chunks":[["滕伯文為孟虎齊衰，其叔父也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-83_s-3","passageId":"li-ji_ch-3_p-83","order":3,"canonicalText":"為孟皮齊衰，其叔父也。","chunks":[["為孟皮齊衰，其叔父也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-83_s-4","passageId":"li-ji_ch-3_p-83","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-84_s-1","passageId":"li-ji_ch-3_p-84","order":1,"canonicalText":"後木曰：「喪，吾聞諸縣子曰：夫喪，不可不深長思也，買棺外內易，我死則亦然。","chunks":[["後木曰：「喪，吾聞諸縣子曰：夫喪，不可不深長思也，買棺外內易，我死則亦然。","zh-Hant"]]},{"id":"li-ji_ch-3_p-84_s-2","passageId":"li-ji_ch-3_p-84","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-85_s-1","passageId":"li-ji_ch-3_p-85","order":1,"canonicalText":"曾子曰：「尸未設飾，故帷堂，小斂而徹帷。","chunks":[["曾子曰：「尸未設飾，故帷堂，小斂而徹帷。","zh-Hant"]]},{"id":"li-ji_ch-3_p-85_s-2","passageId":"li-ji_ch-3_p-85","order":2,"canonicalText":"」仲梁子曰：「夫婦方亂，故帷堂，小斂而徹帷。","chunks":[["」仲梁子曰：「夫婦方亂，故帷堂，小斂而徹帷。","zh-Hant"]]},{"id":"li-ji_ch-3_p-85_s-3","passageId":"li-ji_ch-3_p-85","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-86_s-1","passageId":"li-ji_ch-3_p-86","order":1,"canonicalText":"小斂之奠，子游曰：「於東方。","chunks":[["小斂之奠，子游曰：「於東方。","zh-Hant"]]},{"id":"li-ji_ch-3_p-86_s-2","passageId":"li-ji_ch-3_p-86","order":2,"canonicalText":"」曾子曰：「於西方，斂斯席矣。","chunks":[["」曾子曰：「於西方，斂斯席矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-86_s-3","passageId":"li-ji_ch-3_p-86","order":3,"canonicalText":"」小斂之奠在西方，魯禮之末失也。","chunks":[["」小斂之奠在西方，魯禮之末失也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-87_s-1","passageId":"li-ji_ch-3_p-87","order":1,"canonicalText":"縣子曰：「綌衰繐裳，非古也。","chunks":[["縣子曰：「綌衰繐裳，非古也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-87_s-2","passageId":"li-ji_ch-3_p-87","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-88_s-1","passageId":"li-ji_ch-3_p-88","order":1,"canonicalText":"子蒲卒，哭者呼滅。","chunks":[["子蒲卒，哭者呼滅。","zh-Hant"]]},{"id":"li-ji_ch-3_p-88_s-2","passageId":"li-ji_ch-3_p-88","order":2,"canonicalText":"子皋曰：「若是野哉。","chunks":[["子皋曰：「若是野哉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-88_s-3","passageId":"li-ji_ch-3_p-88","order":3,"canonicalText":"」哭者改之。","chunks":[["」哭者改之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-89_s-1","passageId":"li-ji_ch-3_p-89","order":1,"canonicalText":"杜橋之母之喪，宮中無相，以為沽也。","chunks":[["杜橋之母之喪，宮中無相，以為沽也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-90_s-1","passageId":"li-ji_ch-3_p-90","order":1,"canonicalText":"夫子曰：「始死，羔裘玄冠者，易之而已。","chunks":[["夫子曰：「始死，羔裘玄冠者，易之而已。","zh-Hant"]]},{"id":"li-ji_ch-3_p-90_s-2","passageId":"li-ji_ch-3_p-90","order":2,"canonicalText":"」羔裘玄冠，夫子不以吊。","chunks":[["」羔裘玄冠，夫子不以吊。","zh-Hant"]]},{"id":"li-ji_ch-3_p-91_s-1","passageId":"li-ji_ch-3_p-91","order":1,"canonicalText":"子游問喪具，夫子曰：「稱家之有亡。","chunks":[["子游問喪具，夫子曰：「稱家之有亡。","zh-Hant"]]},{"id":"li-ji_ch-3_p-91_s-2","passageId":"li-ji_ch-3_p-91","order":2,"canonicalText":"」子游曰：「有亡惡乎齊？","chunks":[["」子游曰：「有亡惡乎齊？","zh-Hant"]]},{"id":"li-ji_ch-3_p-91_s-3","passageId":"li-ji_ch-3_p-91","order":3,"canonicalText":"」夫子曰：「有，毋過禮；","chunks":[["」夫子曰：「有，毋過禮；","zh-Hant"]]},{"id":"li-ji_ch-3_p-91_s-4","passageId":"li-ji_ch-3_p-91","order":4,"canonicalText":"茍亡矣，斂首足形，還葬，縣棺而封，人豈有非之者哉！","chunks":[["茍亡矣，斂首足形，還葬，縣棺而封，人豈有非之者哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-91_s-5","passageId":"li-ji_ch-3_p-91","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-92_s-1","passageId":"li-ji_ch-3_p-92","order":1,"canonicalText":"司士賁告於子游曰：「請襲於床。","chunks":[["司士賁告於子游曰：「請襲於床。","zh-Hant"]]},{"id":"li-ji_ch-3_p-92_s-2","passageId":"li-ji_ch-3_p-92","order":2,"canonicalText":"」子游曰：「諾。","chunks":[["」子游曰：「諾。","zh-Hant"]]},{"id":"li-ji_ch-3_p-92_s-3","passageId":"li-ji_ch-3_p-92","order":3,"canonicalText":"」縣子聞之曰：「汰哉叔氏！","chunks":[["」縣子聞之曰：「汰哉叔氏！","zh-Hant"]]},{"id":"li-ji_ch-3_p-92_s-4","passageId":"li-ji_ch-3_p-92","order":4,"canonicalText":"專以禮許人。","chunks":[["專以禮許人。","zh-Hant"]]},{"id":"li-ji_ch-3_p-92_s-5","passageId":"li-ji_ch-3_p-92","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-93_s-1","passageId":"li-ji_ch-3_p-93","order":1,"canonicalText":"宋襄公葬其夫人，醯醢百甕。","chunks":[["宋襄公葬其夫人，醯醢百甕。","zh-Hant"]]},{"id":"li-ji_ch-3_p-93_s-2","passageId":"li-ji_ch-3_p-93","order":2,"canonicalText":"曾子曰：「既曰明器矣，而又實之。","chunks":[["曾子曰：「既曰明器矣，而又實之。","zh-Hant"]]},{"id":"li-ji_ch-3_p-93_s-3","passageId":"li-ji_ch-3_p-93","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-94_s-1","passageId":"li-ji_ch-3_p-94","order":1,"canonicalText":"孟獻子之喪，司徒旅歸四布。","chunks":[["孟獻子之喪，司徒旅歸四布。","zh-Hant"]]},{"id":"li-ji_ch-3_p-94_s-2","passageId":"li-ji_ch-3_p-94","order":2,"canonicalText":"夫子曰：「可也。","chunks":[["夫子曰：「可也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-94_s-3","passageId":"li-ji_ch-3_p-94","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-95_s-1","passageId":"li-ji_ch-3_p-95","order":1,"canonicalText":"讀賵，曾子曰：「非古也，是再告也。","chunks":[["讀賵，曾子曰：「非古也，是再告也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-95_s-2","passageId":"li-ji_ch-3_p-95","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-96_s-1","passageId":"li-ji_ch-3_p-96","order":1,"canonicalText":"成子高寢疾，慶遺入，請曰：「子之病帮矣，如至乎大病，則如之何？","chunks":[["成子高寢疾，慶遺入，請曰：「子之病帮矣，如至乎大病，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-3_p-96_s-2","passageId":"li-ji_ch-3_p-96","order":2,"canonicalText":"」子高曰：「吾聞之也：生有益於人，死不害於人。","chunks":[["」子高曰：「吾聞之也：生有益於人，死不害於人。","zh-Hant"]]},{"id":"li-ji_ch-3_p-96_s-3","passageId":"li-ji_ch-3_p-96","order":3,"canonicalText":"吾縱生無益於人，吾可以死害於人乎哉？","chunks":[["吾縱生無益於人，吾可以死害於人乎哉？","zh-Hant"]]},{"id":"li-ji_ch-3_p-96_s-4","passageId":"li-ji_ch-3_p-96","order":4,"canonicalText":"我死，則擇不食之地而葬我焉。","chunks":[["我死，則擇不食之地而葬我焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-96_s-5","passageId":"li-ji_ch-3_p-96","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-97_s-1","passageId":"li-ji_ch-3_p-97","order":1,"canonicalText":"子夏問諸夫子曰：「居君之母與妻之喪。","chunks":[["子夏問諸夫子曰：「居君之母與妻之喪。","zh-Hant"]]},{"id":"li-ji_ch-3_p-97_s-2","passageId":"li-ji_ch-3_p-97","order":2,"canonicalText":"」「居處、言語、飲食衎爾。","chunks":[["」「居處、言語、飲食衎爾。","zh-Hant"]]},{"id":"li-ji_ch-3_p-97_s-3","passageId":"li-ji_ch-3_p-97","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-98_s-1","passageId":"li-ji_ch-3_p-98","order":1,"canonicalText":"賓客至，無所館。","chunks":[["賓客至，無所館。","zh-Hant"]]},{"id":"li-ji_ch-3_p-98_s-2","passageId":"li-ji_ch-3_p-98","order":2,"canonicalText":"夫子曰：「生於我乎館，死於我乎殯。","chunks":[["夫子曰：「生於我乎館，死於我乎殯。","zh-Hant"]]},{"id":"li-ji_ch-3_p-98_s-3","passageId":"li-ji_ch-3_p-98","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-99_s-1","passageId":"li-ji_ch-3_p-99","order":1,"canonicalText":"國子高曰：「葬也者，藏也；","chunks":[["國子高曰：「葬也者，藏也；","zh-Hant"]]},{"id":"li-ji_ch-3_p-99_s-2","passageId":"li-ji_ch-3_p-99","order":2,"canonicalText":"藏也者，欲人之弗得見也。","chunks":[["藏也者，欲人之弗得見也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-99_s-3","passageId":"li-ji_ch-3_p-99","order":3,"canonicalText":"是故，衣足以飾身，棺周於衣，槨周於棺，土周於槨；","chunks":[["是故，衣足以飾身，棺周於衣，槨周於棺，土周於槨；","zh-Hant"]]},{"id":"li-ji_ch-3_p-99_s-4","passageId":"li-ji_ch-3_p-99","order":4,"canonicalText":"反壤樹之哉。","chunks":[["反壤樹之哉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-99_s-5","passageId":"li-ji_ch-3_p-99","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-1","passageId":"li-ji_ch-3_p-100","order":1,"canonicalText":"孔子之喪，有自燕來觀者，舍於子夏氏。","chunks":[["孔子之喪，有自燕來觀者，舍於子夏氏。","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-2","passageId":"li-ji_ch-3_p-100","order":2,"canonicalText":"子夏曰：「聖人之葬人與？","chunks":[["子夏曰：「聖人之葬人與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-3","passageId":"li-ji_ch-3_p-100","order":3,"canonicalText":"人之葬聖人也，子何觀焉？","chunks":[["人之葬聖人也，子何觀焉？","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-4","passageId":"li-ji_ch-3_p-100","order":4,"canonicalText":"昔者夫子言之曰：『吾見封之若堂者矣，見若坊者矣，見若覆夏屋者矣，見若斧者矣。","chunks":[["昔者夫子言之曰：『吾見封之若堂者矣，見若坊者矣，見若覆夏屋者矣，見若斧者矣。","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-5","passageId":"li-ji_ch-3_p-100","order":5,"canonicalText":"』從若斧者焉。","chunks":[["』從若斧者焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-6","passageId":"li-ji_ch-3_p-100","order":6,"canonicalText":"馬鬣封之謂也。","chunks":[["馬鬣封之謂也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-7","passageId":"li-ji_ch-3_p-100","order":7,"canonicalText":"今一日而三斬板，而已封，尚行夫子之志乎哉！","chunks":[["今一日而三斬板，而已封，尚行夫子之志乎哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-100_s-8","passageId":"li-ji_ch-3_p-100","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-101_s-1","passageId":"li-ji_ch-3_p-101","order":1,"canonicalText":"婦人不葛帶。","chunks":[["婦人不葛帶。","zh-Hant"]]},{"id":"li-ji_ch-3_p-102_s-1","passageId":"li-ji_ch-3_p-102","order":1,"canonicalText":"有薦新，如朔奠。","chunks":[["有薦新，如朔奠。","zh-Hant"]]},{"id":"li-ji_ch-3_p-103_s-1","passageId":"li-ji_ch-3_p-103","order":1,"canonicalText":"既葬，各以其服除。","chunks":[["既葬，各以其服除。","zh-Hant"]]},{"id":"li-ji_ch-3_p-104_s-1","passageId":"li-ji_ch-3_p-104","order":1,"canonicalText":"池視重溜。","chunks":[["池視重溜。","zh-Hant"]]},{"id":"li-ji_ch-3_p-105_s-1","passageId":"li-ji_ch-3_p-105","order":1,"canonicalText":"君即位而為椑，歲一漆之，藏焉。","chunks":[["君即位而為椑，歲一漆之，藏焉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-106_s-1","passageId":"li-ji_ch-3_p-106","order":1,"canonicalText":"復、楔齒、綴足、飯、設飾、帷堂并作。","chunks":[["復、楔齒、綴足、飯、設飾、帷堂并作。","zh-Hant"]]},{"id":"li-ji_ch-3_p-107_s-1","passageId":"li-ji_ch-3_p-107","order":1,"canonicalText":"父兄命赴者。","chunks":[["父兄命赴者。","zh-Hant"]]},{"id":"li-ji_ch-3_p-107_s-2","passageId":"li-ji_ch-3_p-107","order":2,"canonicalText":"君復於小寢、大寢，小祖、大祖，庫門、四郊。","chunks":[["君復於小寢、大寢，小祖、大祖，庫門、四郊。","zh-Hant"]]},{"id":"li-ji_ch-3_p-108_s-1","passageId":"li-ji_ch-3_p-108","order":1,"canonicalText":"喪不剝，奠也與？","chunks":[["喪不剝，奠也與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-108_s-2","passageId":"li-ji_ch-3_p-108","order":2,"canonicalText":"祭肉也與？","chunks":[["祭肉也與？","zh-Hant"]]},{"id":"li-ji_ch-3_p-109_s-1","passageId":"li-ji_ch-3_p-109","order":1,"canonicalText":"既殯，旬而布材與明器。","chunks":[["既殯，旬而布材與明器。","zh-Hant"]]},{"id":"li-ji_ch-3_p-110_s-1","passageId":"li-ji_ch-3_p-110","order":1,"canonicalText":"朝奠日出，夕奠逮日。","chunks":[["朝奠日出，夕奠逮日。","zh-Hant"]]},{"id":"li-ji_ch-3_p-111_s-1","passageId":"li-ji_ch-3_p-111","order":1,"canonicalText":"父母之喪，哭無時，使必知其反也。","chunks":[["父母之喪，哭無時，使必知其反也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-112_s-1","passageId":"li-ji_ch-3_p-112","order":1,"canonicalText":"練，練衣黃里、縓緣，葛要絰，繩屨無絇，角瑱，鹿裘衡長袪，袪裼之可也。","chunks":[["練，練衣黃里、縓緣，葛要絰，繩屨無絇，角瑱，鹿裘衡長袪，袪裼之可也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-113_s-1","passageId":"li-ji_ch-3_p-113","order":1,"canonicalText":"有殯，聞遠兄弟之喪，雖緦必往；","chunks":[["有殯，聞遠兄弟之喪，雖緦必往；","zh-Hant"]]},{"id":"li-ji_ch-3_p-113_s-2","passageId":"li-ji_ch-3_p-113","order":2,"canonicalText":"非兄弟，雖鄰不往。","chunks":[["非兄弟，雖鄰不往。","zh-Hant"]]},{"id":"li-ji_ch-3_p-113_s-3","passageId":"li-ji_ch-3_p-113","order":3,"canonicalText":"所識其兄弟不同居者皆吊。","chunks":[["所識其兄弟不同居者皆吊。","zh-Hant"]]},{"id":"li-ji_ch-3_p-114_s-1","passageId":"li-ji_ch-3_p-114","order":1,"canonicalText":"天子之棺四重；","chunks":[["天子之棺四重；","zh-Hant"]]},{"id":"li-ji_ch-3_p-114_s-2","passageId":"li-ji_ch-3_p-114","order":2,"canonicalText":"水兕革棺被之，其厚三寸，杝棺一，梓棺二，四者皆周。","chunks":[["水兕革棺被之，其厚三寸，杝棺一，梓棺二，四者皆周。","zh-Hant"]]},{"id":"li-ji_ch-3_p-114_s-3","passageId":"li-ji_ch-3_p-114","order":3,"canonicalText":"棺束縮二衡三，衽每束一。","chunks":[["棺束縮二衡三，衽每束一。","zh-Hant"]]},{"id":"li-ji_ch-3_p-114_s-4","passageId":"li-ji_ch-3_p-114","order":4,"canonicalText":"伯槨以端長六尺。","chunks":[["伯槨以端長六尺。","zh-Hant"]]},{"id":"li-ji_ch-3_p-115_s-1","passageId":"li-ji_ch-3_p-115","order":1,"canonicalText":"天子之哭諸侯也，爵弁絰緇衣；","chunks":[["天子之哭諸侯也，爵弁絰緇衣；","zh-Hant"]]},{"id":"li-ji_ch-3_p-115_s-2","passageId":"li-ji_ch-3_p-115","order":2,"canonicalText":"或曰：使有司哭之，為之不以樂食。","chunks":[["或曰：使有司哭之，為之不以樂食。","zh-Hant"]]},{"id":"li-ji_ch-3_p-116_s-1","passageId":"li-ji_ch-3_p-116","order":1,"canonicalText":"天子之殯也，菆涂龍輴以槨，加斧于槨上，畢涂屋，天子之禮也。","chunks":[["天子之殯也，菆涂龍輴以槨，加斧于槨上，畢涂屋，天子之禮也。","zh-Hant"]]},{"id":"li-ji_ch-3_p-117_s-1","passageId":"li-ji_ch-3_p-117","order":1,"canonicalText":"唯天子之喪，有別姓而哭。","chunks":[["唯天子之喪，有別姓而哭。","zh-Hant"]]},{"id":"li-ji_ch-3_p-118_s-1","passageId":"li-ji_ch-3_p-118","order":1,"canonicalText":"魯哀公誄孔丘曰：「天不遺耆老，莫相予位焉，嗚呼哀哉！","chunks":[["魯哀公誄孔丘曰：「天不遺耆老，莫相予位焉，嗚呼哀哉！","zh-Hant"]]},{"id":"li-ji_ch-3_p-118_s-2","passageId":"li-ji_ch-3_p-118","order":2,"canonicalText":"尼父！","chunks":[["尼父！","zh-Hant"]]},{"id":"li-ji_ch-3_p-118_s-3","passageId":"li-ji_ch-3_p-118","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-3_p-119_s-1","passageId":"li-ji_ch-3_p-119","order":1,"canonicalText":"國亡大縣邑，公、卿、大夫、士皆厭冠，哭於大廟，三日，君不舉。","chunks":[["國亡大縣邑，公、卿、大夫、士皆厭冠，哭於大廟，三日，君不舉。","zh-Hant"]]},{"id":"li-ji_ch-3_p-119_s-2","passageId":"li-ji_ch-3_p-119","order":2,"canonicalText":"或曰：君舉而哭於後土。","chunks":[["或曰：君舉而哭於後土。","zh-Hant"]]},{"id":"li-ji_ch-3_p-120_s-1","passageId":"li-ji_ch-3_p-120","order":1,"canonicalText":"孔子惡野哭者。","chunks":[["孔子惡野哭者。","zh-Hant"]]},{"id":"li-ji_ch-3_p-121_s-1","passageId":"li-ji_ch-3_p-121","order":1,"canonicalText":"未仕者，不敢稅人；","chunks":[["未仕者，不敢稅人；","zh-Hant"]]},{"id":"li-ji_ch-3_p-121_s-2","passageId":"li-ji_ch-3_p-121","order":2,"canonicalText":"如稅人，則以父兄之命。","chunks":[["如稅人，則以父兄之命。","zh-Hant"]]},{"id":"li-ji_ch-3_p-122_s-1","passageId":"li-ji_ch-3_p-122","order":1,"canonicalText":"士備入而後朝夕踴。","chunks":[["士備入而後朝夕踴。","zh-Hant"]]},{"id":"li-ji_ch-3_p-123_s-1","passageId":"li-ji_ch-3_p-123","order":1,"canonicalText":"祥而縞，是月禫，徙月樂。","chunks":[["祥而縞，是月禫，徙月樂。","zh-Hant"]]},{"id":"li-ji_ch-3_p-124_s-1","passageId":"li-ji_ch-3_p-124","order":1,"canonicalText":"君於士有賜帟。","chunks":[["君於士有賜帟。","zh-Hant"]]},{"id":"li-ji_ch-4_p-1_s-1","passageId":"li-ji_ch-4_p-1","order":1,"canonicalText":"君之適長殤，車三乘；","chunks":[["君之適長殤，車三乘；","zh-Hant"]]},{"id":"li-ji_ch-4_p-1_s-2","passageId":"li-ji_ch-4_p-1","order":2,"canonicalText":"公之庶長殤，車一乘；","chunks":[["公之庶長殤，車一乘；","zh-Hant"]]},{"id":"li-ji_ch-4_p-1_s-3","passageId":"li-ji_ch-4_p-1","order":3,"canonicalText":"大夫之適長殤，車一乘。","chunks":[["大夫之適長殤，車一乘。","zh-Hant"]]},{"id":"li-ji_ch-4_p-2_s-1","passageId":"li-ji_ch-4_p-2","order":1,"canonicalText":"公之喪，諸達官之長，杖。","chunks":[["公之喪，諸達官之長，杖。","zh-Hant"]]},{"id":"li-ji_ch-4_p-3_s-1","passageId":"li-ji_ch-4_p-3","order":1,"canonicalText":"君於大夫，將葬，吊於宮；","chunks":[["君於大夫，將葬，吊於宮；","zh-Hant"]]},{"id":"li-ji_ch-4_p-3_s-2","passageId":"li-ji_ch-4_p-3","order":2,"canonicalText":"及出，命引之，三步則止。","chunks":[["及出，命引之，三步則止。","zh-Hant"]]},{"id":"li-ji_ch-4_p-3_s-3","passageId":"li-ji_ch-4_p-3","order":3,"canonicalText":"如是者三，君退；","chunks":[["如是者三，君退；","zh-Hant"]]},{"id":"li-ji_ch-4_p-3_s-4","passageId":"li-ji_ch-4_p-3","order":4,"canonicalText":"朝亦如之，哀次亦如之。","chunks":[["朝亦如之，哀次亦如之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-4_s-1","passageId":"li-ji_ch-4_p-4","order":1,"canonicalText":"五十無車者，不越疆而吊人。","chunks":[["五十無車者，不越疆而吊人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-5_s-1","passageId":"li-ji_ch-4_p-5","order":1,"canonicalText":"季武子寢疾，蟜固不說齊衰而入見，曰：「斯道也，將亡矣；","chunks":[["季武子寢疾，蟜固不說齊衰而入見，曰：「斯道也，將亡矣；","zh-Hant"]]},{"id":"li-ji_ch-4_p-5_s-2","passageId":"li-ji_ch-4_p-5","order":2,"canonicalText":"士唯公門說齊衰。","chunks":[["士唯公門說齊衰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-5_s-3","passageId":"li-ji_ch-4_p-5","order":3,"canonicalText":"」武子曰：「不亦善乎，君子表微。","chunks":[["」武子曰：「不亦善乎，君子表微。","zh-Hant"]]},{"id":"li-ji_ch-4_p-5_s-4","passageId":"li-ji_ch-4_p-5","order":4,"canonicalText":"」及其喪也，曾點倚其門而歌。","chunks":[["」及其喪也，曾點倚其門而歌。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-1","passageId":"li-ji_ch-4_p-6","order":1,"canonicalText":"大夫吊，當事而至，則辭焉。","chunks":[["大夫吊，當事而至，則辭焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-2","passageId":"li-ji_ch-4_p-6","order":2,"canonicalText":"吊於人，是日不樂。","chunks":[["吊於人，是日不樂。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-3","passageId":"li-ji_ch-4_p-6","order":3,"canonicalText":"婦人不越疆而吊人。","chunks":[["婦人不越疆而吊人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-4","passageId":"li-ji_ch-4_p-6","order":4,"canonicalText":"行吊之日不飲酒食肉焉。","chunks":[["行吊之日不飲酒食肉焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-5","passageId":"li-ji_ch-4_p-6","order":5,"canonicalText":"吊於葬者必執引，若從柩及壙，皆執紼。","chunks":[["吊於葬者必執引，若從柩及壙，皆執紼。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-6","passageId":"li-ji_ch-4_p-6","order":6,"canonicalText":"喪，公吊之，必有拜者，雖朋友州里舍人可也。","chunks":[["喪，公吊之，必有拜者，雖朋友州里舍人可也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-7","passageId":"li-ji_ch-4_p-6","order":7,"canonicalText":"吊曰：「寡君承事。","chunks":[["吊曰：「寡君承事。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-8","passageId":"li-ji_ch-4_p-6","order":8,"canonicalText":"」主人曰：「臨。","chunks":[["」主人曰：「臨。","zh-Hant"]]},{"id":"li-ji_ch-4_p-6_s-9","passageId":"li-ji_ch-4_p-6","order":9,"canonicalText":"」君遇柩於路，必使人吊之。","chunks":[["」君遇柩於路，必使人吊之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-7_s-1","passageId":"li-ji_ch-4_p-7","order":1,"canonicalText":"大夫之喪，庶子不受吊。","chunks":[["大夫之喪，庶子不受吊。","zh-Hant"]]},{"id":"li-ji_ch-4_p-8_s-1","passageId":"li-ji_ch-4_p-8","order":1,"canonicalText":"妻之昆弟為父後者死，哭之適室，子為主，袒免哭踴，夫入門右，使人立于門外告來者，狎則入哭；","chunks":[["妻之昆弟為父後者死，哭之適室，子為主，袒免哭踴，夫入門右，使人立于門外告來者，狎則入哭；","zh-Hant"]]},{"id":"li-ji_ch-4_p-8_s-2","passageId":"li-ji_ch-4_p-8","order":2,"canonicalText":"父在，哭於妻之室；","chunks":[["父在，哭於妻之室；","zh-Hant"]]},{"id":"li-ji_ch-4_p-8_s-3","passageId":"li-ji_ch-4_p-8","order":3,"canonicalText":"非為父後者。","chunks":[["非為父後者。","zh-Hant"]]},{"id":"li-ji_ch-4_p-8_s-4","passageId":"li-ji_ch-4_p-8","order":4,"canonicalText":"哭諸異室。","chunks":[["哭諸異室。","zh-Hant"]]},{"id":"li-ji_ch-4_p-9_s-1","passageId":"li-ji_ch-4_p-9","order":1,"canonicalText":"有殯，聞遠兄弟之喪，哭于側室；","chunks":[["有殯，聞遠兄弟之喪，哭于側室；","zh-Hant"]]},{"id":"li-ji_ch-4_p-9_s-2","passageId":"li-ji_ch-4_p-9","order":2,"canonicalText":"無側室，哭于門內之右；","chunks":[["無側室，哭于門內之右；","zh-Hant"]]},{"id":"li-ji_ch-4_p-9_s-3","passageId":"li-ji_ch-4_p-9","order":3,"canonicalText":"同國，則往哭之。","chunks":[["同國，則往哭之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-10_s-1","passageId":"li-ji_ch-4_p-10","order":1,"canonicalText":"子張死，曾子有母之喪；","chunks":[["子張死，曾子有母之喪；","zh-Hant"]]},{"id":"li-ji_ch-4_p-10_s-2","passageId":"li-ji_ch-4_p-10","order":2,"canonicalText":"齊衰而往哭之。","chunks":[["齊衰而往哭之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-10_s-3","passageId":"li-ji_ch-4_p-10","order":3,"canonicalText":"或曰：「齊衰不以吊。","chunks":[["或曰：「齊衰不以吊。","zh-Hant"]]},{"id":"li-ji_ch-4_p-10_s-4","passageId":"li-ji_ch-4_p-10","order":4,"canonicalText":"」曾子曰：「我吊也與哉？","chunks":[["」曾子曰：「我吊也與哉？","zh-Hant"]]},{"id":"li-ji_ch-4_p-10_s-5","passageId":"li-ji_ch-4_p-10","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-11_s-1","passageId":"li-ji_ch-4_p-11","order":1,"canonicalText":"有若之喪，悼公吊焉，子游擯，由左。","chunks":[["有若之喪，悼公吊焉，子游擯，由左。","zh-Hant"]]},{"id":"li-ji_ch-4_p-12_s-1","passageId":"li-ji_ch-4_p-12","order":1,"canonicalText":"齊穀王姬之喪，魯莊公為之大功。","chunks":[["齊穀王姬之喪，魯莊公為之大功。","zh-Hant"]]},{"id":"li-ji_ch-4_p-12_s-2","passageId":"li-ji_ch-4_p-12","order":2,"canonicalText":"或曰：「由魯嫁，故為之服姊妹之服。","chunks":[["或曰：「由魯嫁，故為之服姊妹之服。","zh-Hant"]]},{"id":"li-ji_ch-4_p-12_s-3","passageId":"li-ji_ch-4_p-12","order":3,"canonicalText":"」或曰：「外祖母也，故為之服。","chunks":[["」或曰：「外祖母也，故為之服。","zh-Hant"]]},{"id":"li-ji_ch-4_p-12_s-4","passageId":"li-ji_ch-4_p-12","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-1","passageId":"li-ji_ch-4_p-13","order":1,"canonicalText":"晉獻公之喪，秦穆公使人吊公子重耳，且曰：「寡人聞之：亡國恒於斯，得國恒於斯。","chunks":[["晉獻公之喪，秦穆公使人吊公子重耳，且曰：「寡人聞之：亡國恒於斯，得國恒於斯。","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-2","passageId":"li-ji_ch-4_p-13","order":2,"canonicalText":"雖吾子儼然在憂服之中，喪亦不可久也，時亦不可失也。","chunks":[["雖吾子儼然在憂服之中，喪亦不可久也，時亦不可失也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-3","passageId":"li-ji_ch-4_p-13","order":3,"canonicalText":"孺子其圖之。","chunks":[["孺子其圖之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-4","passageId":"li-ji_ch-4_p-13","order":4,"canonicalText":"」以告舅犯，舅犯曰：「孺子其辭焉；","chunks":[["」以告舅犯，舅犯曰：「孺子其辭焉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-5","passageId":"li-ji_ch-4_p-13","order":5,"canonicalText":"喪人無寶，仁親以為寶。","chunks":[["喪人無寶，仁親以為寶。","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-6","passageId":"li-ji_ch-4_p-13","order":6,"canonicalText":"父死之謂何？","chunks":[["父死之謂何？","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-7","passageId":"li-ji_ch-4_p-13","order":7,"canonicalText":"又因以為利，而天下其孰能說之？","chunks":[["又因以為利，而天下其孰能說之？","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-8","passageId":"li-ji_ch-4_p-13","order":8,"canonicalText":"孺子其辭焉。","chunks":[["孺子其辭焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-13_s-9","passageId":"li-ji_ch-4_p-13","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-14_s-1","passageId":"li-ji_ch-4_p-14","order":1,"canonicalText":"公子重耳對客曰：「君惠吊亡臣重耳，身喪父死，不得與於哭泣之哀，以為君憂。","chunks":[["公子重耳對客曰：「君惠吊亡臣重耳，身喪父死，不得與於哭泣之哀，以為君憂。","zh-Hant"]]},{"id":"li-ji_ch-4_p-14_s-2","passageId":"li-ji_ch-4_p-14","order":2,"canonicalText":"父死之謂何？","chunks":[["父死之謂何？","zh-Hant"]]},{"id":"li-ji_ch-4_p-14_s-3","passageId":"li-ji_ch-4_p-14","order":3,"canonicalText":"或敢有他志，以辱君義。","chunks":[["或敢有他志，以辱君義。","zh-Hant"]]},{"id":"li-ji_ch-4_p-14_s-4","passageId":"li-ji_ch-4_p-14","order":4,"canonicalText":"」稽顙而不拜，哭而起，起而不私。","chunks":[["」稽顙而不拜，哭而起，起而不私。","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-1","passageId":"li-ji_ch-4_p-15","order":1,"canonicalText":"子顯以致命於穆公。","chunks":[["子顯以致命於穆公。","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-2","passageId":"li-ji_ch-4_p-15","order":2,"canonicalText":"穆公曰：「仁夫公子重耳！","chunks":[["穆公曰：「仁夫公子重耳！","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-3","passageId":"li-ji_ch-4_p-15","order":3,"canonicalText":"夫稽顙而不拜，則未為後也，故不成拜；","chunks":[["夫稽顙而不拜，則未為後也，故不成拜；","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-4","passageId":"li-ji_ch-4_p-15","order":4,"canonicalText":"哭而起，則愛父也；","chunks":[["哭而起，則愛父也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-5","passageId":"li-ji_ch-4_p-15","order":5,"canonicalText":"起而不私，則遠利也。","chunks":[["起而不私，則遠利也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-15_s-6","passageId":"li-ji_ch-4_p-15","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-16_s-1","passageId":"li-ji_ch-4_p-16","order":1,"canonicalText":"帷殯，非古也，自敬姜之哭穆伯始也。","chunks":[["帷殯，非古也，自敬姜之哭穆伯始也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-17_s-1","passageId":"li-ji_ch-4_p-17","order":1,"canonicalText":"喪禮，哀戚之至也。","chunks":[["喪禮，哀戚之至也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-17_s-2","passageId":"li-ji_ch-4_p-17","order":2,"canonicalText":"節哀，順變也；","chunks":[["節哀，順變也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-17_s-3","passageId":"li-ji_ch-4_p-17","order":3,"canonicalText":"君子念始之者也。","chunks":[["君子念始之者也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-18_s-1","passageId":"li-ji_ch-4_p-18","order":1,"canonicalText":"復，盡愛之道也，有禱祠之心焉；","chunks":[["復，盡愛之道也，有禱祠之心焉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-18_s-2","passageId":"li-ji_ch-4_p-18","order":2,"canonicalText":"望反諸幽，求諸鬼神之道也；","chunks":[["望反諸幽，求諸鬼神之道也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-18_s-3","passageId":"li-ji_ch-4_p-18","order":3,"canonicalText":"北面，求諸幽之義也。","chunks":[["北面，求諸幽之義也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-19_s-1","passageId":"li-ji_ch-4_p-19","order":1,"canonicalText":"拜稽顙，哀戚之至隱也；","chunks":[["拜稽顙，哀戚之至隱也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-19_s-2","passageId":"li-ji_ch-4_p-19","order":2,"canonicalText":"稽顙，隱之甚也。","chunks":[["稽顙，隱之甚也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-20_s-1","passageId":"li-ji_ch-4_p-20","order":1,"canonicalText":"飯用米貝，弗忍虛也；","chunks":[["飯用米貝，弗忍虛也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-20_s-2","passageId":"li-ji_ch-4_p-20","order":2,"canonicalText":"不以食道，用美焉爾。","chunks":[["不以食道，用美焉爾。","zh-Hant"]]},{"id":"li-ji_ch-4_p-21_s-1","passageId":"li-ji_ch-4_p-21","order":1,"canonicalText":"銘，明旌也，以死者為不可別已，故以其旗識之。","chunks":[["銘，明旌也，以死者為不可別已，故以其旗識之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-21_s-2","passageId":"li-ji_ch-4_p-21","order":2,"canonicalText":"愛之，斯錄之矣；","chunks":[["愛之，斯錄之矣；","zh-Hant"]]},{"id":"li-ji_ch-4_p-21_s-3","passageId":"li-ji_ch-4_p-21","order":3,"canonicalText":"敬之，斯盡其道焉耳。","chunks":[["敬之，斯盡其道焉耳。","zh-Hant"]]},{"id":"li-ji_ch-4_p-21_s-4","passageId":"li-ji_ch-4_p-21","order":4,"canonicalText":"重，主道也，殷主綴重焉；","chunks":[["重，主道也，殷主綴重焉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-21_s-5","passageId":"li-ji_ch-4_p-21","order":5,"canonicalText":"周主重徹焉。","chunks":[["周主重徹焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-22_s-1","passageId":"li-ji_ch-4_p-22","order":1,"canonicalText":"奠以素器，以生者有哀素之心也；","chunks":[["奠以素器，以生者有哀素之心也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-22_s-2","passageId":"li-ji_ch-4_p-22","order":2,"canonicalText":"唯祭祀之禮，主人自盡焉爾；","chunks":[["唯祭祀之禮，主人自盡焉爾；","zh-Hant"]]},{"id":"li-ji_ch-4_p-22_s-3","passageId":"li-ji_ch-4_p-22","order":3,"canonicalText":"豈知神之所饗，亦以主人有齊敬之心也。","chunks":[["豈知神之所饗，亦以主人有齊敬之心也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-23_s-1","passageId":"li-ji_ch-4_p-23","order":1,"canonicalText":"辟踴，哀之至也，有算，為之節文也。","chunks":[["辟踴，哀之至也，有算，為之節文也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-24_s-1","passageId":"li-ji_ch-4_p-24","order":1,"canonicalText":"袒、括髮，變也；","chunks":[["袒、括髮，變也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-24_s-2","passageId":"li-ji_ch-4_p-24","order":2,"canonicalText":"慍，哀之變也。","chunks":[["慍，哀之變也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-24_s-3","passageId":"li-ji_ch-4_p-24","order":3,"canonicalText":"去飾，去美也；","chunks":[["去飾，去美也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-24_s-4","passageId":"li-ji_ch-4_p-24","order":4,"canonicalText":"袒、括髮，去飾之甚也。","chunks":[["袒、括髮，去飾之甚也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-24_s-5","passageId":"li-ji_ch-4_p-24","order":5,"canonicalText":"有所袒、有所襲，哀之節也。","chunks":[["有所袒、有所襲，哀之節也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-25_s-1","passageId":"li-ji_ch-4_p-25","order":1,"canonicalText":"弁絰葛而葬，與神交之道也，有敬心焉。","chunks":[["弁絰葛而葬，與神交之道也，有敬心焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-25_s-2","passageId":"li-ji_ch-4_p-25","order":2,"canonicalText":"周人弁而葬，殷人冔而葬。","chunks":[["周人弁而葬，殷人冔而葬。","zh-Hant"]]},{"id":"li-ji_ch-4_p-26_s-1","passageId":"li-ji_ch-4_p-26","order":1,"canonicalText":"歠主人、主婦室老，為其病也，君命食之也。","chunks":[["歠主人、主婦室老，為其病也，君命食之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-27_s-1","passageId":"li-ji_ch-4_p-27","order":1,"canonicalText":"反哭升堂，反諸其所作也；","chunks":[["反哭升堂，反諸其所作也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-27_s-2","passageId":"li-ji_ch-4_p-27","order":2,"canonicalText":"主婦入于室，反諸其所養也。","chunks":[["主婦入于室，反諸其所養也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-28_s-1","passageId":"li-ji_ch-4_p-28","order":1,"canonicalText":"反哭之吊也，哀之至也。","chunks":[["反哭之吊也，哀之至也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-28_s-2","passageId":"li-ji_ch-4_p-28","order":2,"canonicalText":"反而亡焉，失之矣，於是為甚。","chunks":[["反而亡焉，失之矣，於是為甚。","zh-Hant"]]},{"id":"li-ji_ch-4_p-28_s-3","passageId":"li-ji_ch-4_p-28","order":3,"canonicalText":"殷既封而吊，周反哭而吊。","chunks":[["殷既封而吊，周反哭而吊。","zh-Hant"]]},{"id":"li-ji_ch-4_p-28_s-4","passageId":"li-ji_ch-4_p-28","order":4,"canonicalText":"孔子曰：「殷已愨，吾從周。","chunks":[["孔子曰：「殷已愨，吾從周。","zh-Hant"]]},{"id":"li-ji_ch-4_p-28_s-5","passageId":"li-ji_ch-4_p-28","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-29_s-1","passageId":"li-ji_ch-4_p-29","order":1,"canonicalText":"葬於北方北首，三代之達禮也，之幽之故也。","chunks":[["葬於北方北首，三代之達禮也，之幽之故也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-30_s-1","passageId":"li-ji_ch-4_p-30","order":1,"canonicalText":"既封，主人贈，而祝宿虞尸。","chunks":[["既封，主人贈，而祝宿虞尸。","zh-Hant"]]},{"id":"li-ji_ch-4_p-31_s-1","passageId":"li-ji_ch-4_p-31","order":1,"canonicalText":"既反哭，主人與有司視虞牲，有司以几筵舍奠於墓左，反，日中而虞。","chunks":[["既反哭，主人與有司視虞牲，有司以几筵舍奠於墓左，反，日中而虞。","zh-Hant"]]},{"id":"li-ji_ch-4_p-32_s-1","passageId":"li-ji_ch-4_p-32","order":1,"canonicalText":"葬日虞，弗忍一日離也。","chunks":[["葬日虞，弗忍一日離也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-32_s-2","passageId":"li-ji_ch-4_p-32","order":2,"canonicalText":"是日也，以虞易奠。","chunks":[["是日也，以虞易奠。","zh-Hant"]]},{"id":"li-ji_ch-4_p-32_s-3","passageId":"li-ji_ch-4_p-32","order":3,"canonicalText":"卒哭曰成事，是日也，以吉祭易喪祭，明日，祔于祖父。","chunks":[["卒哭曰成事，是日也，以吉祭易喪祭，明日，祔于祖父。","zh-Hant"]]},{"id":"li-ji_ch-4_p-32_s-4","passageId":"li-ji_ch-4_p-32","order":4,"canonicalText":"其變而之吉祭也，比至於祔，必於是日也接，不忍一日末有所歸也。","chunks":[["其變而之吉祭也，比至於祔，必於是日也接，不忍一日末有所歸也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-33_s-1","passageId":"li-ji_ch-4_p-33","order":1,"canonicalText":"殷練而祔，周卒哭而祔。","chunks":[["殷練而祔，周卒哭而祔。","zh-Hant"]]},{"id":"li-ji_ch-4_p-33_s-2","passageId":"li-ji_ch-4_p-33","order":2,"canonicalText":"孔子善殷。","chunks":[["孔子善殷。","zh-Hant"]]},{"id":"li-ji_ch-4_p-34_s-1","passageId":"li-ji_ch-4_p-34","order":1,"canonicalText":"君臨臣喪，以巫祝桃茢執戈，惡之也；","chunks":[["君臨臣喪，以巫祝桃茢執戈，惡之也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-34_s-2","passageId":"li-ji_ch-4_p-34","order":2,"canonicalText":"所以異於生也。","chunks":[["所以異於生也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-34_s-3","passageId":"li-ji_ch-4_p-34","order":3,"canonicalText":"喪有死之道焉。","chunks":[["喪有死之道焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-34_s-4","passageId":"li-ji_ch-4_p-34","order":4,"canonicalText":"先王之所難言也。","chunks":[["先王之所難言也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-35_s-1","passageId":"li-ji_ch-4_p-35","order":1,"canonicalText":"喪之朝也，順死者之孝心也，其哀離其室也，故至於祖考之廟而後行。","chunks":[["喪之朝也，順死者之孝心也，其哀離其室也，故至於祖考之廟而後行。","zh-Hant"]]},{"id":"li-ji_ch-4_p-35_s-2","passageId":"li-ji_ch-4_p-35","order":2,"canonicalText":"殷朝而殯於祖，周朝而遂葬。","chunks":[["殷朝而殯於祖，周朝而遂葬。","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-1","passageId":"li-ji_ch-4_p-36","order":1,"canonicalText":"孔子謂：「為明器者，知喪道矣，備物而不可用也。","chunks":[["孔子謂：「為明器者，知喪道矣，備物而不可用也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-2","passageId":"li-ji_ch-4_p-36","order":2,"canonicalText":"」哀哉！","chunks":[["」哀哉！","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-3","passageId":"li-ji_ch-4_p-36","order":3,"canonicalText":"死者而用生者之器也。","chunks":[["死者而用生者之器也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-4","passageId":"li-ji_ch-4_p-36","order":4,"canonicalText":"不殆於用殉乎哉？","chunks":[["不殆於用殉乎哉？","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-5","passageId":"li-ji_ch-4_p-36","order":5,"canonicalText":"「其曰明器，神明之也。","chunks":[["「其曰明器，神明之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-6","passageId":"li-ji_ch-4_p-36","order":6,"canonicalText":"」塗車、芻靈，自古有之，明器之道也。","chunks":[["」塗車、芻靈，自古有之，明器之道也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-36_s-7","passageId":"li-ji_ch-4_p-36","order":7,"canonicalText":"孔子謂「為芻靈者善」，謂「為俑者不仁」，不殆於用人乎哉？","chunks":[["孔子謂「為芻靈者善」，謂「為俑者不仁」，不殆於用人乎哉？","zh-Hant"]]},{"id":"li-ji_ch-4_p-37_s-1","passageId":"li-ji_ch-4_p-37","order":1,"canonicalText":"穆公問於子思曰：「為舊君反服，古與？","chunks":[["穆公問於子思曰：「為舊君反服，古與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-37_s-2","passageId":"li-ji_ch-4_p-37","order":2,"canonicalText":"」子思曰：「古之君子，進人以禮，退人以禮，故有舊君反服之禮也；","chunks":[["」子思曰：「古之君子，進人以禮，退人以禮，故有舊君反服之禮也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-37_s-3","passageId":"li-ji_ch-4_p-37","order":3,"canonicalText":"今之君子，進人若將加諸膝，退人若將隊諸淵，毋為戎首，不亦善乎！","chunks":[["今之君子，進人若將加諸膝，退人若將隊諸淵，毋為戎首，不亦善乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-37_s-4","passageId":"li-ji_ch-4_p-37","order":4,"canonicalText":"又何反服之禮之有？","chunks":[["又何反服之禮之有？","zh-Hant"]]},{"id":"li-ji_ch-4_p-37_s-5","passageId":"li-ji_ch-4_p-37","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-38_s-1","passageId":"li-ji_ch-4_p-38","order":1,"canonicalText":"悼公之喪，季昭子問於孟敬子曰：「為君何食？","chunks":[["悼公之喪，季昭子問於孟敬子曰：「為君何食？","zh-Hant"]]},{"id":"li-ji_ch-4_p-38_s-2","passageId":"li-ji_ch-4_p-38","order":2,"canonicalText":"」敬子曰：「食粥，天下之達禮也。","chunks":[["」敬子曰：「食粥，天下之達禮也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-38_s-3","passageId":"li-ji_ch-4_p-38","order":3,"canonicalText":"吾三臣者之不能居公室也，四方莫不聞矣，勉而為瘠則吾能，毋乃使人疑夫不以情居瘠者乎哉？","chunks":[["吾三臣者之不能居公室也，四方莫不聞矣，勉而為瘠則吾能，毋乃使人疑夫不以情居瘠者乎哉？","zh-Hant"]]},{"id":"li-ji_ch-4_p-38_s-4","passageId":"li-ji_ch-4_p-38","order":4,"canonicalText":"我則食食。","chunks":[["我則食食。","zh-Hant"]]},{"id":"li-ji_ch-4_p-38_s-5","passageId":"li-ji_ch-4_p-38","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-39_s-1","passageId":"li-ji_ch-4_p-39","order":1,"canonicalText":"衛司徒敬子死，子夏吊焉，主人未小斂，絰而往。","chunks":[["衛司徒敬子死，子夏吊焉，主人未小斂，絰而往。","zh-Hant"]]},{"id":"li-ji_ch-4_p-39_s-2","passageId":"li-ji_ch-4_p-39","order":2,"canonicalText":"子游吊焉，主人既小斂，子游出，絰反哭，子夏曰：「聞之也與？","chunks":[["子游吊焉，主人既小斂，子游出，絰反哭，子夏曰：「聞之也與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-39_s-3","passageId":"li-ji_ch-4_p-39","order":3,"canonicalText":"」曰：「聞諸夫子，主人未改服，則不絰。","chunks":[["」曰：「聞諸夫子，主人未改服，則不絰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-39_s-4","passageId":"li-ji_ch-4_p-39","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-1","passageId":"li-ji_ch-4_p-40","order":1,"canonicalText":"曾子曰：「晏子可謂知禮也已，恭敬之有焉。","chunks":[["曾子曰：「晏子可謂知禮也已，恭敬之有焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-2","passageId":"li-ji_ch-4_p-40","order":2,"canonicalText":"」有若曰：「晏子一狐裘三十年，遣車一乘，及墓而反；","chunks":[["」有若曰：「晏子一狐裘三十年，遣車一乘，及墓而反；","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-3","passageId":"li-ji_ch-4_p-40","order":3,"canonicalText":"國君七個，遣車七乘；","chunks":[["國君七個，遣車七乘；","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-4","passageId":"li-ji_ch-4_p-40","order":4,"canonicalText":"大夫五個，遣車五乘，晏子焉知禮？","chunks":[["大夫五個，遣車五乘，晏子焉知禮？","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-5","passageId":"li-ji_ch-4_p-40","order":5,"canonicalText":"」曾子曰：「國無道，君子恥盈禮焉。","chunks":[["」曾子曰：「國無道，君子恥盈禮焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-6","passageId":"li-ji_ch-4_p-40","order":6,"canonicalText":"國奢，則示之以儉；","chunks":[["國奢，則示之以儉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-7","passageId":"li-ji_ch-4_p-40","order":7,"canonicalText":"國儉，則示之以禮。","chunks":[["國儉，則示之以禮。","zh-Hant"]]},{"id":"li-ji_ch-4_p-40_s-8","passageId":"li-ji_ch-4_p-40","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-1","passageId":"li-ji_ch-4_p-41","order":1,"canonicalText":"國昭子之母死，問於子張曰：「葬及墓，男子、婦人安位？","chunks":[["國昭子之母死，問於子張曰：「葬及墓，男子、婦人安位？","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-2","passageId":"li-ji_ch-4_p-41","order":2,"canonicalText":"」子張曰：「司徒敬子之喪，夫子相，男子西鄉，婦人東鄉。","chunks":[["」子張曰：「司徒敬子之喪，夫子相，男子西鄉，婦人東鄉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-3","passageId":"li-ji_ch-4_p-41","order":3,"canonicalText":"」曰：「噫！","chunks":[["」曰：「噫！","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-4","passageId":"li-ji_ch-4_p-41","order":4,"canonicalText":"毋。","chunks":[["毋。","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-5","passageId":"li-ji_ch-4_p-41","order":5,"canonicalText":"」曰：「我喪也斯沾。","chunks":[["」曰：「我喪也斯沾。","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-6","passageId":"li-ji_ch-4_p-41","order":6,"canonicalText":"爾專之，賓為賓焉，主為主焉，婦人從男子皆西鄉。","chunks":[["爾專之，賓為賓焉，主為主焉，婦人從男子皆西鄉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-41_s-7","passageId":"li-ji_ch-4_p-41","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-42_s-1","passageId":"li-ji_ch-4_p-42","order":1,"canonicalText":"穆伯之喪，敬姜晝哭；","chunks":[["穆伯之喪，敬姜晝哭；","zh-Hant"]]},{"id":"li-ji_ch-4_p-42_s-2","passageId":"li-ji_ch-4_p-42","order":2,"canonicalText":"文伯之喪，晝夜哭。","chunks":[["文伯之喪，晝夜哭。","zh-Hant"]]},{"id":"li-ji_ch-4_p-42_s-3","passageId":"li-ji_ch-4_p-42","order":3,"canonicalText":"孔子曰：「知禮矣。","chunks":[["孔子曰：「知禮矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-42_s-4","passageId":"li-ji_ch-4_p-42","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-43_s-1","passageId":"li-ji_ch-4_p-43","order":1,"canonicalText":"文伯之喪，敬姜據其床而不哭，曰：「昔者吾有斯子也，吾以將為賢人也，吾未嘗以就公室；","chunks":[["文伯之喪，敬姜據其床而不哭，曰：「昔者吾有斯子也，吾以將為賢人也，吾未嘗以就公室；","zh-Hant"]]},{"id":"li-ji_ch-4_p-43_s-2","passageId":"li-ji_ch-4_p-43","order":2,"canonicalText":"今及其死也，朋友諸臣未有出涕者，而內人皆行哭失聲。","chunks":[["今及其死也，朋友諸臣未有出涕者，而內人皆行哭失聲。","zh-Hant"]]},{"id":"li-ji_ch-4_p-43_s-3","passageId":"li-ji_ch-4_p-43","order":3,"canonicalText":"斯子也，必多曠於禮矣夫！","chunks":[["斯子也，必多曠於禮矣夫！","zh-Hant"]]},{"id":"li-ji_ch-4_p-43_s-4","passageId":"li-ji_ch-4_p-43","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-44_s-1","passageId":"li-ji_ch-4_p-44","order":1,"canonicalText":"季康子之母死，陳褻衣。","chunks":[["季康子之母死，陳褻衣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-44_s-2","passageId":"li-ji_ch-4_p-44","order":2,"canonicalText":"敬姜曰：「婦人不飾，不敢見舅姑，將有四方之賓來，褻衣何為陳於斯？","chunks":[["敬姜曰：「婦人不飾，不敢見舅姑，將有四方之賓來，褻衣何為陳於斯？","zh-Hant"]]},{"id":"li-ji_ch-4_p-44_s-3","passageId":"li-ji_ch-4_p-44","order":3,"canonicalText":"」命徹之。","chunks":[["」命徹之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-1","passageId":"li-ji_ch-4_p-45","order":1,"canonicalText":"有子與子游立，見孺子慕者，有子謂子游曰：「予壹不知夫喪之踴也，予欲去之久矣。","chunks":[["有子與子游立，見孺子慕者，有子謂子游曰：「予壹不知夫喪之踴也，予欲去之久矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-2","passageId":"li-ji_ch-4_p-45","order":2,"canonicalText":"情在於斯，其是也夫？","chunks":[["情在於斯，其是也夫？","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-3","passageId":"li-ji_ch-4_p-45","order":3,"canonicalText":"」子游曰：「禮：有微情者，有以故興物者；","chunks":[["」子游曰：「禮：有微情者，有以故興物者；","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-4","passageId":"li-ji_ch-4_p-45","order":4,"canonicalText":"有直情而徑行者，戎狄之道也。","chunks":[["有直情而徑行者，戎狄之道也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-5","passageId":"li-ji_ch-4_p-45","order":5,"canonicalText":"禮道則不然，人喜則斯陶，陶斯詠，詠斯猶，猶斯舞，舞斯慍，慍斯戚，戚斯嘆，嘆斯辟，辟斯踴矣。","chunks":[["禮道則不然，人喜則斯陶，陶斯詠，詠斯猶，猶斯舞，舞斯慍，慍斯戚，戚斯嘆，嘆斯辟，辟斯踴矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-6","passageId":"li-ji_ch-4_p-45","order":6,"canonicalText":"品節斯，斯之謂禮。","chunks":[["品節斯，斯之謂禮。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-7","passageId":"li-ji_ch-4_p-45","order":7,"canonicalText":"人死，斯惡之矣，無能也，斯倍之矣。","chunks":[["人死，斯惡之矣，無能也，斯倍之矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-8","passageId":"li-ji_ch-4_p-45","order":8,"canonicalText":"是故制絞衾、設蔞翣，為使人勿惡也。","chunks":[["是故制絞衾、設蔞翣，為使人勿惡也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-9","passageId":"li-ji_ch-4_p-45","order":9,"canonicalText":"始死，脯醢之奠；","chunks":[["始死，脯醢之奠；","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-10","passageId":"li-ji_ch-4_p-45","order":10,"canonicalText":"將行，遣而行之；","chunks":[["將行，遣而行之；","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-11","passageId":"li-ji_ch-4_p-45","order":11,"canonicalText":"既葬而食之，未有見其饗之者也。","chunks":[["既葬而食之，未有見其饗之者也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-12","passageId":"li-ji_ch-4_p-45","order":12,"canonicalText":"自上世以來，未之有舍也，為使人勿倍也。","chunks":[["自上世以來，未之有舍也，為使人勿倍也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-13","passageId":"li-ji_ch-4_p-45","order":13,"canonicalText":"故子之所刺於禮者，亦非禮之訾也。","chunks":[["故子之所刺於禮者，亦非禮之訾也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-45_s-14","passageId":"li-ji_ch-4_p-45","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-1","passageId":"li-ji_ch-4_p-46","order":1,"canonicalText":"吳侵陳，斬祀殺厲，師還出竟，陳大宰嚭使於師。","chunks":[["吳侵陳，斬祀殺厲，師還出竟，陳大宰嚭使於師。","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-2","passageId":"li-ji_ch-4_p-46","order":2,"canonicalText":"夫差謂行人儀曰：「是夫也多言，盍嘗問焉；","chunks":[["夫差謂行人儀曰：「是夫也多言，盍嘗問焉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-3","passageId":"li-ji_ch-4_p-46","order":3,"canonicalText":"師必有名，人之稱斯師也者，則謂之何？","chunks":[["師必有名，人之稱斯師也者，則謂之何？","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-4","passageId":"li-ji_ch-4_p-46","order":4,"canonicalText":"」大宰嚭曰：「古之侵伐者，不斬祀、不殺厲、不獲二毛；","chunks":[["」大宰嚭曰：「古之侵伐者，不斬祀、不殺厲、不獲二毛；","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-5","passageId":"li-ji_ch-4_p-46","order":5,"canonicalText":"今斯師也，殺厲與？","chunks":[["今斯師也，殺厲與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-6","passageId":"li-ji_ch-4_p-46","order":6,"canonicalText":"其不謂之殺厲之師與？","chunks":[["其不謂之殺厲之師與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-7","passageId":"li-ji_ch-4_p-46","order":7,"canonicalText":"」曰：「反爾地，歸爾子，則謂之何？","chunks":[["」曰：「反爾地，歸爾子，則謂之何？","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-8","passageId":"li-ji_ch-4_p-46","order":8,"canonicalText":"」曰：「君王討敝邑之罪，又矜而赦之，師與，有無名乎？","chunks":[["」曰：「君王討敝邑之罪，又矜而赦之，師與，有無名乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-46_s-9","passageId":"li-ji_ch-4_p-46","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-47_s-1","passageId":"li-ji_ch-4_p-47","order":1,"canonicalText":"顏丁善居喪：始死，皇皇焉如有求而弗得；","chunks":[["顏丁善居喪：始死，皇皇焉如有求而弗得；","zh-Hant"]]},{"id":"li-ji_ch-4_p-47_s-2","passageId":"li-ji_ch-4_p-47","order":2,"canonicalText":"及殯，望望焉如有從而弗及；","chunks":[["及殯，望望焉如有從而弗及；","zh-Hant"]]},{"id":"li-ji_ch-4_p-47_s-3","passageId":"li-ji_ch-4_p-47","order":3,"canonicalText":"既葬，慨焉如不及其反而息。","chunks":[["既葬，慨焉如不及其反而息。","zh-Hant"]]},{"id":"li-ji_ch-4_p-48_s-1","passageId":"li-ji_ch-4_p-48","order":1,"canonicalText":"子張問曰：「《書》云：『高宗三年不言，言乃歡。","chunks":[["子張問曰：「《書》云：『高宗三年不言，言乃歡。","zh-Hant"]]},{"id":"li-ji_ch-4_p-48_s-2","passageId":"li-ji_ch-4_p-48","order":2,"canonicalText":"』有諸？","chunks":[["』有諸？","zh-Hant"]]},{"id":"li-ji_ch-4_p-48_s-3","passageId":"li-ji_ch-4_p-48","order":3,"canonicalText":"」仲尼曰：「胡為其不然也？","chunks":[["」仲尼曰：「胡為其不然也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-48_s-4","passageId":"li-ji_ch-4_p-48","order":4,"canonicalText":"古者天子崩，王世子聽於冢宰三年。","chunks":[["古者天子崩，王世子聽於冢宰三年。","zh-Hant"]]},{"id":"li-ji_ch-4_p-48_s-5","passageId":"li-ji_ch-4_p-48","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-1","passageId":"li-ji_ch-4_p-49","order":1,"canonicalText":"知悼子卒，未葬；","chunks":[["知悼子卒，未葬；","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-2","passageId":"li-ji_ch-4_p-49","order":2,"canonicalText":"平公飲酒，師曠、李調侍，鼓鐘。","chunks":[["平公飲酒，師曠、李調侍，鼓鐘。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-3","passageId":"li-ji_ch-4_p-49","order":3,"canonicalText":"杜蕢自外來，聞鐘聲，曰：「安在？","chunks":[["杜蕢自外來，聞鐘聲，曰：「安在？","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-4","passageId":"li-ji_ch-4_p-49","order":4,"canonicalText":"」曰：「在寢。","chunks":[["」曰：「在寢。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-5","passageId":"li-ji_ch-4_p-49","order":5,"canonicalText":"」杜蕢入寢，歷階而升，酌，曰：「曠飲斯。","chunks":[["」杜蕢入寢，歷階而升，酌，曰：「曠飲斯。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-6","passageId":"li-ji_ch-4_p-49","order":6,"canonicalText":"」又酌，曰：「調飲斯。","chunks":[["」又酌，曰：「調飲斯。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-7","passageId":"li-ji_ch-4_p-49","order":7,"canonicalText":"」又酌，堂上北面坐飲之。","chunks":[["」又酌，堂上北面坐飲之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-8","passageId":"li-ji_ch-4_p-49","order":8,"canonicalText":"降，趨而出。","chunks":[["降，趨而出。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-9","passageId":"li-ji_ch-4_p-49","order":9,"canonicalText":"平公呼而進之曰：「蕢，曩者爾心或開予，是以不與爾言；","chunks":[["平公呼而進之曰：「蕢，曩者爾心或開予，是以不與爾言；","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-10","passageId":"li-ji_ch-4_p-49","order":10,"canonicalText":"爾飲曠何也？","chunks":[["爾飲曠何也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-11","passageId":"li-ji_ch-4_p-49","order":11,"canonicalText":"」曰：「子卯不樂；","chunks":[["」曰：「子卯不樂；","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-12","passageId":"li-ji_ch-4_p-49","order":12,"canonicalText":"知悼子在堂，斯其為子卯也大矣。","chunks":[["知悼子在堂，斯其為子卯也大矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-13","passageId":"li-ji_ch-4_p-49","order":13,"canonicalText":"曠也大師也，不以詔，是以飲之也。","chunks":[["曠也大師也，不以詔，是以飲之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-49_s-14","passageId":"li-ji_ch-4_p-49","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-50_s-1","passageId":"li-ji_ch-4_p-50","order":1,"canonicalText":"「爾飲調何也？","chunks":[["「爾飲調何也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-50_s-2","passageId":"li-ji_ch-4_p-50","order":2,"canonicalText":"」曰：「調也君之褻臣也，為一飲一食，忘君之疾，是以飲之也。","chunks":[["」曰：「調也君之褻臣也，為一飲一食，忘君之疾，是以飲之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-50_s-3","passageId":"li-ji_ch-4_p-50","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-51_s-1","passageId":"li-ji_ch-4_p-51","order":1,"canonicalText":"「爾飲何也？","chunks":[["「爾飲何也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-51_s-2","passageId":"li-ji_ch-4_p-51","order":2,"canonicalText":"」曰：「蕢也宰夫也，非刀匕是共，又敢與知防，是以飲之也。","chunks":[["」曰：「蕢也宰夫也，非刀匕是共，又敢與知防，是以飲之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-51_s-3","passageId":"li-ji_ch-4_p-51","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-52_s-1","passageId":"li-ji_ch-4_p-52","order":1,"canonicalText":"平公曰：「寡人亦有過焉，酌而飲寡人。","chunks":[["平公曰：「寡人亦有過焉，酌而飲寡人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-52_s-2","passageId":"li-ji_ch-4_p-52","order":2,"canonicalText":"」杜蕢洗而揚觶。","chunks":[["」杜蕢洗而揚觶。","zh-Hant"]]},{"id":"li-ji_ch-4_p-52_s-3","passageId":"li-ji_ch-4_p-52","order":3,"canonicalText":"公謂侍者曰：「如我死，則必無廢斯爵也。","chunks":[["公謂侍者曰：「如我死，則必無廢斯爵也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-52_s-4","passageId":"li-ji_ch-4_p-52","order":4,"canonicalText":"」至于今，既畢獻，斯揚觶，謂之杜舉。","chunks":[["」至于今，既畢獻，斯揚觶，謂之杜舉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-1","passageId":"li-ji_ch-4_p-53","order":1,"canonicalText":"公叔文子卒，其子戍請謚於君曰：「日月有時，將葬矣。","chunks":[["公叔文子卒，其子戍請謚於君曰：「日月有時，將葬矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-2","passageId":"li-ji_ch-4_p-53","order":2,"canonicalText":"請所以易其名者。","chunks":[["請所以易其名者。","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-3","passageId":"li-ji_ch-4_p-53","order":3,"canonicalText":"」君曰：「昔者衛國凶饑，夫子為粥與國之餓者，是不亦惠乎？","chunks":[["」君曰：「昔者衛國凶饑，夫子為粥與國之餓者，是不亦惠乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-4","passageId":"li-ji_ch-4_p-53","order":4,"canonicalText":"昔者衛國有難，夫子以其死衛寡人，不亦貞乎？","chunks":[["昔者衛國有難，夫子以其死衛寡人，不亦貞乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-5","passageId":"li-ji_ch-4_p-53","order":5,"canonicalText":"夫子聽衛國之政，修其班制，以與四鄰交，衛國之社稷不辱，不亦文乎？","chunks":[["夫子聽衛國之政，修其班制，以與四鄰交，衛國之社稷不辱，不亦文乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-6","passageId":"li-ji_ch-4_p-53","order":6,"canonicalText":"故謂夫子『貞惠文子』。","chunks":[["故謂夫子『貞惠文子』。","zh-Hant"]]},{"id":"li-ji_ch-4_p-53_s-7","passageId":"li-ji_ch-4_p-53","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-1","passageId":"li-ji_ch-4_p-54","order":1,"canonicalText":"石駘仲卒，無適子，有庶子六人，卜所以為後者。","chunks":[["石駘仲卒，無適子，有庶子六人，卜所以為後者。","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-2","passageId":"li-ji_ch-4_p-54","order":2,"canonicalText":"曰：「沐浴、佩玉則兆。","chunks":[["曰：「沐浴、佩玉則兆。","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-3","passageId":"li-ji_ch-4_p-54","order":3,"canonicalText":"」五人者皆沐浴、佩玉；","chunks":[["」五人者皆沐浴、佩玉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-4","passageId":"li-ji_ch-4_p-54","order":4,"canonicalText":"石祁子曰：「孰有執親之喪而沐浴、佩玉者乎？","chunks":[["石祁子曰：「孰有執親之喪而沐浴、佩玉者乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-5","passageId":"li-ji_ch-4_p-54","order":5,"canonicalText":"」不沐浴、佩玉。","chunks":[["」不沐浴、佩玉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-6","passageId":"li-ji_ch-4_p-54","order":6,"canonicalText":"石祁子兆。","chunks":[["石祁子兆。","zh-Hant"]]},{"id":"li-ji_ch-4_p-54_s-7","passageId":"li-ji_ch-4_p-54","order":7,"canonicalText":"衛人以龜為有知也。","chunks":[["衛人以龜為有知也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-1","passageId":"li-ji_ch-4_p-55","order":1,"canonicalText":"陳子車死於衛，其妻與其家大夫謀以殉葬，定，而後陳子亢至，以告曰：「夫子疾，莫養於下，請以殉葬。","chunks":[["陳子車死於衛，其妻與其家大夫謀以殉葬，定，而後陳子亢至，以告曰：「夫子疾，莫養於下，請以殉葬。","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-2","passageId":"li-ji_ch-4_p-55","order":2,"canonicalText":"」子亢曰：「以殉葬，非禮也；","chunks":[["」子亢曰：「以殉葬，非禮也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-3","passageId":"li-ji_ch-4_p-55","order":3,"canonicalText":"雖然，則彼疾當養者，孰若妻與宰？","chunks":[["雖然，則彼疾當養者，孰若妻與宰？","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-4","passageId":"li-ji_ch-4_p-55","order":4,"canonicalText":"得已，則吾欲已；","chunks":[["得已，則吾欲已；","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-5","passageId":"li-ji_ch-4_p-55","order":5,"canonicalText":"不得已，則吾欲以二子者之為之也。","chunks":[["不得已，則吾欲以二子者之為之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-55_s-6","passageId":"li-ji_ch-4_p-55","order":6,"canonicalText":"」於是弗果用。","chunks":[["」於是弗果用。","zh-Hant"]]},{"id":"li-ji_ch-4_p-56_s-1","passageId":"li-ji_ch-4_p-56","order":1,"canonicalText":"子路曰：「傷哉貧也！","chunks":[["子路曰：「傷哉貧也！","zh-Hant"]]},{"id":"li-ji_ch-4_p-56_s-2","passageId":"li-ji_ch-4_p-56","order":2,"canonicalText":"生無以為養，死無以為禮也。","chunks":[["生無以為養，死無以為禮也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-56_s-3","passageId":"li-ji_ch-4_p-56","order":3,"canonicalText":"」孔子曰：「啜菽飲水盡其歡，斯之謂孝；","chunks":[["」孔子曰：「啜菽飲水盡其歡，斯之謂孝；","zh-Hant"]]},{"id":"li-ji_ch-4_p-56_s-4","passageId":"li-ji_ch-4_p-56","order":4,"canonicalText":"斂首足形，還葬而無槨，稱其財，斯之謂禮。","chunks":[["斂首足形，還葬而無槨，稱其財，斯之謂禮。","zh-Hant"]]},{"id":"li-ji_ch-4_p-56_s-5","passageId":"li-ji_ch-4_p-56","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-57_s-1","passageId":"li-ji_ch-4_p-57","order":1,"canonicalText":"衛獻公出奔，反於衛，及郊，將班邑於從者而後入。","chunks":[["衛獻公出奔，反於衛，及郊，將班邑於從者而後入。","zh-Hant"]]},{"id":"li-ji_ch-4_p-57_s-2","passageId":"li-ji_ch-4_p-57","order":2,"canonicalText":"柳莊曰：「如皆守社稷，則孰執羈靮而從；","chunks":[["柳莊曰：「如皆守社稷，則孰執羈靮而從；","zh-Hant"]]},{"id":"li-ji_ch-4_p-57_s-3","passageId":"li-ji_ch-4_p-57","order":3,"canonicalText":"如皆從，則孰守社稷？","chunks":[["如皆從，則孰守社稷？","zh-Hant"]]},{"id":"li-ji_ch-4_p-57_s-4","passageId":"li-ji_ch-4_p-57","order":4,"canonicalText":"君反其國而有私也，毋乃不可乎？","chunks":[["君反其國而有私也，毋乃不可乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-57_s-5","passageId":"li-ji_ch-4_p-57","order":5,"canonicalText":"」弗果班。","chunks":[["」弗果班。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-1","passageId":"li-ji_ch-4_p-58","order":1,"canonicalText":"衛有大史曰柳莊，寢疾。","chunks":[["衛有大史曰柳莊，寢疾。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-2","passageId":"li-ji_ch-4_p-58","order":2,"canonicalText":"公曰：「若疾革，雖當祭必告。","chunks":[["公曰：「若疾革，雖當祭必告。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-3","passageId":"li-ji_ch-4_p-58","order":3,"canonicalText":"」公再拜稽首，請於尸曰：「有臣柳莊也者，非寡人之臣，社稷之臣也，聞之死，請往。","chunks":[["」公再拜稽首，請於尸曰：「有臣柳莊也者，非寡人之臣，社稷之臣也，聞之死，請往。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-4","passageId":"li-ji_ch-4_p-58","order":4,"canonicalText":"」不釋服而往，遂以襚之。","chunks":[["」不釋服而往，遂以襚之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-5","passageId":"li-ji_ch-4_p-58","order":5,"canonicalText":"與之邑裘氏與縣潘氏，書而納諸棺，曰：「世世萬子孫，無變也。","chunks":[["與之邑裘氏與縣潘氏，書而納諸棺，曰：「世世萬子孫，無變也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-58_s-6","passageId":"li-ji_ch-4_p-58","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-59_s-1","passageId":"li-ji_ch-4_p-59","order":1,"canonicalText":"陳乾昔寢疾，屬其兄弟，而命其子尊已曰：「如我死，則必大為我棺，使吾二婢子夾我。","chunks":[["陳乾昔寢疾，屬其兄弟，而命其子尊已曰：「如我死，則必大為我棺，使吾二婢子夾我。","zh-Hant"]]},{"id":"li-ji_ch-4_p-59_s-2","passageId":"li-ji_ch-4_p-59","order":2,"canonicalText":"」陳乾昔死，其子曰：「以殉葬，非禮也，況又同棺乎？","chunks":[["」陳乾昔死，其子曰：「以殉葬，非禮也，況又同棺乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-59_s-3","passageId":"li-ji_ch-4_p-59","order":3,"canonicalText":"」弗果殺。","chunks":[["」弗果殺。","zh-Hant"]]},{"id":"li-ji_ch-4_p-60_s-1","passageId":"li-ji_ch-4_p-60","order":1,"canonicalText":"仲遂卒于垂；","chunks":[["仲遂卒于垂；","zh-Hant"]]},{"id":"li-ji_ch-4_p-60_s-2","passageId":"li-ji_ch-4_p-60","order":2,"canonicalText":"壬午猶繹，萬入去龠。","chunks":[["壬午猶繹，萬入去龠。","zh-Hant"]]},{"id":"li-ji_ch-4_p-60_s-3","passageId":"li-ji_ch-4_p-60","order":3,"canonicalText":"仲尼曰：「非禮也，卿卒不繹。","chunks":[["仲尼曰：「非禮也，卿卒不繹。","zh-Hant"]]},{"id":"li-ji_ch-4_p-60_s-4","passageId":"li-ji_ch-4_p-60","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-1","passageId":"li-ji_ch-4_p-61","order":1,"canonicalText":"季康子之母死，公輸若方小，斂，般請以機封，將從之，公肩假曰：「不可！","chunks":[["季康子之母死，公輸若方小，斂，般請以機封，將從之，公肩假曰：「不可！","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-2","passageId":"li-ji_ch-4_p-61","order":2,"canonicalText":"夫魯有初，公室視豐碑，三家視桓楹。","chunks":[["夫魯有初，公室視豐碑，三家視桓楹。","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-3","passageId":"li-ji_ch-4_p-61","order":3,"canonicalText":"般，爾以人之母嘗巧，則豈不得以？","chunks":[["般，爾以人之母嘗巧，則豈不得以？","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-4","passageId":"li-ji_ch-4_p-61","order":4,"canonicalText":"其母以嘗巧者乎？","chunks":[["其母以嘗巧者乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-5","passageId":"li-ji_ch-4_p-61","order":5,"canonicalText":"則病者乎？","chunks":[["則病者乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-6","passageId":"li-ji_ch-4_p-61","order":6,"canonicalText":"噫！","chunks":[["噫！","zh-Hant"]]},{"id":"li-ji_ch-4_p-61_s-7","passageId":"li-ji_ch-4_p-61","order":7,"canonicalText":"」弗果從。","chunks":[["」弗果從。","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-1","passageId":"li-ji_ch-4_p-62","order":1,"canonicalText":"戰于郎，公叔禺人遇負杖入保者息，曰：「使之雖病也，任之雖重也，君子不能為謀也，士弗能死也，不可！","chunks":[["戰于郎，公叔禺人遇負杖入保者息，曰：「使之雖病也，任之雖重也，君子不能為謀也，士弗能死也，不可！","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-2","passageId":"li-ji_ch-4_p-62","order":2,"canonicalText":"我則既言矣。","chunks":[["我則既言矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-3","passageId":"li-ji_ch-4_p-62","order":3,"canonicalText":"」與其鄰童汪踦往，皆死焉。","chunks":[["」與其鄰童汪踦往，皆死焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-4","passageId":"li-ji_ch-4_p-62","order":4,"canonicalText":"魯人欲勿殤童汪踦，問於仲尼。","chunks":[["魯人欲勿殤童汪踦，問於仲尼。","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-5","passageId":"li-ji_ch-4_p-62","order":5,"canonicalText":"仲尼曰：「能執干戈以衛社稷，雖欲勿殤也，不亦可乎！","chunks":[["仲尼曰：「能執干戈以衛社稷，雖欲勿殤也，不亦可乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-62_s-6","passageId":"li-ji_ch-4_p-62","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-1","passageId":"li-ji_ch-4_p-63","order":1,"canonicalText":"子路去魯，謂顏淵曰：「何以贈我？","chunks":[["子路去魯，謂顏淵曰：「何以贈我？","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-2","passageId":"li-ji_ch-4_p-63","order":2,"canonicalText":"」曰：「吾聞之也：去國，則哭于墓而後行；","chunks":[["」曰：「吾聞之也：去國，則哭于墓而後行；","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-3","passageId":"li-ji_ch-4_p-63","order":3,"canonicalText":"反其國，不哭，展墓而入。","chunks":[["反其國，不哭，展墓而入。","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-4","passageId":"li-ji_ch-4_p-63","order":4,"canonicalText":"」謂子路曰：「何以處我？","chunks":[["」謂子路曰：「何以處我？","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-5","passageId":"li-ji_ch-4_p-63","order":5,"canonicalText":"」子路曰：「吾聞之也：過墓則式，過祀則下。","chunks":[["」子路曰：「吾聞之也：過墓則式，過祀則下。","zh-Hant"]]},{"id":"li-ji_ch-4_p-63_s-6","passageId":"li-ji_ch-4_p-63","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-1","passageId":"li-ji_ch-4_p-64","order":1,"canonicalText":"工尹商陽與陳棄疾追吳師，及之。","chunks":[["工尹商陽與陳棄疾追吳師，及之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-2","passageId":"li-ji_ch-4_p-64","order":2,"canonicalText":"陳棄疾謂工尹商陽曰：「王事也，子手弓而可。","chunks":[["陳棄疾謂工尹商陽曰：「王事也，子手弓而可。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-3","passageId":"li-ji_ch-4_p-64","order":3,"canonicalText":"」手弓。","chunks":[["」手弓。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-4","passageId":"li-ji_ch-4_p-64","order":4,"canonicalText":"「子射諸。","chunks":[["「子射諸。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-5","passageId":"li-ji_ch-4_p-64","order":5,"canonicalText":"」射之，斃一人，韔弓。","chunks":[["」射之，斃一人，韔弓。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-6","passageId":"li-ji_ch-4_p-64","order":6,"canonicalText":"又及，謂之，又斃二人。","chunks":[["又及，謂之，又斃二人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-7","passageId":"li-ji_ch-4_p-64","order":7,"canonicalText":"每斃一人，掩其目。","chunks":[["每斃一人，掩其目。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-8","passageId":"li-ji_ch-4_p-64","order":8,"canonicalText":"止其御曰：「朝不坐，燕不與，殺三人，亦足以反命矣。","chunks":[["止其御曰：「朝不坐，燕不與，殺三人，亦足以反命矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-9","passageId":"li-ji_ch-4_p-64","order":9,"canonicalText":"」孔子曰：「殺人之中，又有禮焉。","chunks":[["」孔子曰：「殺人之中，又有禮焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-64_s-10","passageId":"li-ji_ch-4_p-64","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-65_s-1","passageId":"li-ji_ch-4_p-65","order":1,"canonicalText":"諸侯伐秦，曹桓公卒于會。","chunks":[["諸侯伐秦，曹桓公卒于會。","zh-Hant"]]},{"id":"li-ji_ch-4_p-65_s-2","passageId":"li-ji_ch-4_p-65","order":2,"canonicalText":"諸侯請含，使之襲。","chunks":[["諸侯請含，使之襲。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-1","passageId":"li-ji_ch-4_p-66","order":1,"canonicalText":"襄公朝于荊，康王卒。","chunks":[["襄公朝于荊，康王卒。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-2","passageId":"li-ji_ch-4_p-66","order":2,"canonicalText":"荊人曰：「必請襲。","chunks":[["荊人曰：「必請襲。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-3","passageId":"li-ji_ch-4_p-66","order":3,"canonicalText":"」魯人曰：「非禮也。","chunks":[["」魯人曰：「非禮也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-4","passageId":"li-ji_ch-4_p-66","order":4,"canonicalText":"」荊人強之。","chunks":[["」荊人強之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-5","passageId":"li-ji_ch-4_p-66","order":5,"canonicalText":"巫先拂柩。","chunks":[["巫先拂柩。","zh-Hant"]]},{"id":"li-ji_ch-4_p-66_s-6","passageId":"li-ji_ch-4_p-66","order":6,"canonicalText":"荊人悔之。","chunks":[["荊人悔之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-67_s-1","passageId":"li-ji_ch-4_p-67","order":1,"canonicalText":"滕成公之喪，使子叔敬叔吊，進書，子服惠伯為介。","chunks":[["滕成公之喪，使子叔敬叔吊，進書，子服惠伯為介。","zh-Hant"]]},{"id":"li-ji_ch-4_p-67_s-2","passageId":"li-ji_ch-4_p-67","order":2,"canonicalText":"及郊，為懿伯之忌，不入。","chunks":[["及郊，為懿伯之忌，不入。","zh-Hant"]]},{"id":"li-ji_ch-4_p-67_s-3","passageId":"li-ji_ch-4_p-67","order":3,"canonicalText":"惠伯曰：「政也，不可以叔父之私，不將公事。","chunks":[["惠伯曰：「政也，不可以叔父之私，不將公事。","zh-Hant"]]},{"id":"li-ji_ch-4_p-67_s-4","passageId":"li-ji_ch-4_p-67","order":4,"canonicalText":"」遂入。","chunks":[["」遂入。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-1","passageId":"li-ji_ch-4_p-68","order":1,"canonicalText":"哀公使人吊蕢尚，遇諸道。","chunks":[["哀公使人吊蕢尚，遇諸道。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-2","passageId":"li-ji_ch-4_p-68","order":2,"canonicalText":"辟於路，畫宮而受吊焉。","chunks":[["辟於路，畫宮而受吊焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-3","passageId":"li-ji_ch-4_p-68","order":3,"canonicalText":"曾子曰：「蕢尚不如杞梁之妻之知禮也。","chunks":[["曾子曰：「蕢尚不如杞梁之妻之知禮也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-4","passageId":"li-ji_ch-4_p-68","order":4,"canonicalText":"齊莊公襲莒于奪，杞梁死焉，其妻迎其柩於路而哭之哀，莊公使人吊之，對曰：『君之臣不免於罪，則將肆諸市朝，而妻妾執；","chunks":[["齊莊公襲莒于奪，杞梁死焉，其妻迎其柩於路而哭之哀，莊公使人吊之，對曰：『君之臣不免於罪，則將肆諸市朝，而妻妾執；","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-5","passageId":"li-ji_ch-4_p-68","order":5,"canonicalText":"君之臣免於罪，則有先人之敝廬在。","chunks":[["君之臣免於罪，則有先人之敝廬在。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-6","passageId":"li-ji_ch-4_p-68","order":6,"canonicalText":"君無所辱命。","chunks":[["君無所辱命。","zh-Hant"]]},{"id":"li-ji_ch-4_p-68_s-7","passageId":"li-ji_ch-4_p-68","order":7,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"li-ji_ch-4_p-69_s-1","passageId":"li-ji_ch-4_p-69","order":1,"canonicalText":"孺子𪏆之喪，哀公欲設撥，問於有若，有若曰：「其可也，君之三臣猶設之。","chunks":[["孺子𪏆之喪，哀公欲設撥，問於有若，有若曰：「其可也，君之三臣猶設之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-69_s-2","passageId":"li-ji_ch-4_p-69","order":2,"canonicalText":"」顏柳曰：「天子龍輴而槨幬，諸侯輴而設幬，為榆沈故設撥；","chunks":[["」顏柳曰：「天子龍輴而槨幬，諸侯輴而設幬，為榆沈故設撥；","zh-Hant"]]},{"id":"li-ji_ch-4_p-69_s-3","passageId":"li-ji_ch-4_p-69","order":3,"canonicalText":"三臣者廢輴而設撥，竊禮之不中者也，而君何學焉！","chunks":[["三臣者廢輴而設撥，竊禮之不中者也，而君何學焉！","zh-Hant"]]},{"id":"li-ji_ch-4_p-69_s-4","passageId":"li-ji_ch-4_p-69","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-70_s-1","passageId":"li-ji_ch-4_p-70","order":1,"canonicalText":"悼公之母死，哀公為之齊衰。","chunks":[["悼公之母死，哀公為之齊衰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-70_s-2","passageId":"li-ji_ch-4_p-70","order":2,"canonicalText":"有若曰：「為妾齊衰，禮與？","chunks":[["有若曰：「為妾齊衰，禮與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-70_s-3","passageId":"li-ji_ch-4_p-70","order":3,"canonicalText":"」公曰：「吾得已乎哉？","chunks":[["」公曰：「吾得已乎哉？","zh-Hant"]]},{"id":"li-ji_ch-4_p-70_s-4","passageId":"li-ji_ch-4_p-70","order":4,"canonicalText":"魯人以妻我。","chunks":[["魯人以妻我。","zh-Hant"]]},{"id":"li-ji_ch-4_p-70_s-5","passageId":"li-ji_ch-4_p-70","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-71_s-1","passageId":"li-ji_ch-4_p-71","order":1,"canonicalText":"季子皋葬其妻，犯人之禾，申祥以告曰：「請庚之。","chunks":[["季子皋葬其妻，犯人之禾，申祥以告曰：「請庚之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-71_s-2","passageId":"li-ji_ch-4_p-71","order":2,"canonicalText":"」子皋曰：「孟氏不以是罪予，朋友不以是棄予，以吾為邑長於斯也。","chunks":[["」子皋曰：「孟氏不以是罪予，朋友不以是棄予，以吾為邑長於斯也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-71_s-3","passageId":"li-ji_ch-4_p-71","order":3,"canonicalText":"買道而葬，後難繼也。","chunks":[["買道而葬，後難繼也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-71_s-4","passageId":"li-ji_ch-4_p-71","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-72_s-1","passageId":"li-ji_ch-4_p-72","order":1,"canonicalText":"仕而未有祿者：君有饋焉曰獻，使焉曰寡君；","chunks":[["仕而未有祿者：君有饋焉曰獻，使焉曰寡君；","zh-Hant"]]},{"id":"li-ji_ch-4_p-72_s-2","passageId":"li-ji_ch-4_p-72","order":2,"canonicalText":"違而君薨，弗為服也。","chunks":[["違而君薨，弗為服也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-73_s-1","passageId":"li-ji_ch-4_p-73","order":1,"canonicalText":"虞而立尸，有几筵。","chunks":[["虞而立尸，有几筵。","zh-Hant"]]},{"id":"li-ji_ch-4_p-73_s-2","passageId":"li-ji_ch-4_p-73","order":2,"canonicalText":"卒哭而諱，生事畢而鬼事始已。","chunks":[["卒哭而諱，生事畢而鬼事始已。","zh-Hant"]]},{"id":"li-ji_ch-4_p-73_s-3","passageId":"li-ji_ch-4_p-73","order":3,"canonicalText":"既卒哭，宰夫執木鐸以命于宮曰：「舍故而諱新。","chunks":[["既卒哭，宰夫執木鐸以命于宮曰：「舍故而諱新。","zh-Hant"]]},{"id":"li-ji_ch-4_p-73_s-4","passageId":"li-ji_ch-4_p-73","order":4,"canonicalText":"」自寢門至于庫門。","chunks":[["」自寢門至于庫門。","zh-Hant"]]},{"id":"li-ji_ch-4_p-74_s-1","passageId":"li-ji_ch-4_p-74","order":1,"canonicalText":"二名不偏諱，夫子之母名徵在；","chunks":[["二名不偏諱，夫子之母名徵在；","zh-Hant"]]},{"id":"li-ji_ch-4_p-74_s-2","passageId":"li-ji_ch-4_p-74","order":2,"canonicalText":"言在不稱徵，言徵不稱在。","chunks":[["言在不稱徵，言徵不稱在。","zh-Hant"]]},{"id":"li-ji_ch-4_p-75_s-1","passageId":"li-ji_ch-4_p-75","order":1,"canonicalText":"軍有憂，則素服哭於庫門之外，赴車不載橐韔。","chunks":[["軍有憂，則素服哭於庫門之外，赴車不載橐韔。","zh-Hant"]]},{"id":"li-ji_ch-4_p-76_s-1","passageId":"li-ji_ch-4_p-76","order":1,"canonicalText":"有焚其先人之室，則三日哭。","chunks":[["有焚其先人之室，則三日哭。","zh-Hant"]]},{"id":"li-ji_ch-4_p-76_s-2","passageId":"li-ji_ch-4_p-76","order":2,"canonicalText":"故曰：「新宮火，亦三日哭。","chunks":[["故曰：「新宮火，亦三日哭。","zh-Hant"]]},{"id":"li-ji_ch-4_p-76_s-3","passageId":"li-ji_ch-4_p-76","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-1","passageId":"li-ji_ch-4_p-77","order":1,"canonicalText":"孔子過泰山側，有婦人哭於墓者而哀，夫子式而聽之。","chunks":[["孔子過泰山側，有婦人哭於墓者而哀，夫子式而聽之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-2","passageId":"li-ji_ch-4_p-77","order":2,"canonicalText":"使子貢問之曰：「子之哭也，壹似重有憂者。","chunks":[["使子貢問之曰：「子之哭也，壹似重有憂者。","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-3","passageId":"li-ji_ch-4_p-77","order":3,"canonicalText":"」而曰：「然，昔者吾舅死於虎，吾夫又死焉，今吾子又死焉。","chunks":[["」而曰：「然，昔者吾舅死於虎，吾夫又死焉，今吾子又死焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-4","passageId":"li-ji_ch-4_p-77","order":4,"canonicalText":"」夫子曰：「何為不去也？","chunks":[["」夫子曰：「何為不去也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-5","passageId":"li-ji_ch-4_p-77","order":5,"canonicalText":"」曰：「無苛政。","chunks":[["」曰：「無苛政。","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-6","passageId":"li-ji_ch-4_p-77","order":6,"canonicalText":"」夫子曰：「小子識之，苛政猛於虎也。","chunks":[["」夫子曰：「小子識之，苛政猛於虎也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-77_s-7","passageId":"li-ji_ch-4_p-77","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-1","passageId":"li-ji_ch-4_p-78","order":1,"canonicalText":"魯人有周豐也者，哀公執摯請見之，而曰不可。","chunks":[["魯人有周豐也者，哀公執摯請見之，而曰不可。","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-2","passageId":"li-ji_ch-4_p-78","order":2,"canonicalText":"公曰：「我其已夫！","chunks":[["公曰：「我其已夫！","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-3","passageId":"li-ji_ch-4_p-78","order":3,"canonicalText":"」使人問焉，曰：「有虞氏未施信於民而民信之，夏后氏未施敬於民而民敬之，何施而得斯於民也？","chunks":[["」使人問焉，曰：「有虞氏未施信於民而民信之，夏后氏未施敬於民而民敬之，何施而得斯於民也？","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-4","passageId":"li-ji_ch-4_p-78","order":4,"canonicalText":"」對曰：「墟墓之間，未施哀於民而民哀；","chunks":[["」對曰：「墟墓之間，未施哀於民而民哀；","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-5","passageId":"li-ji_ch-4_p-78","order":5,"canonicalText":"社稷宗廟之中，未施敬於民而民敬。","chunks":[["社稷宗廟之中，未施敬於民而民敬。","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-6","passageId":"li-ji_ch-4_p-78","order":6,"canonicalText":"殷人作誓而民始畔，周人作會而民始疑。","chunks":[["殷人作誓而民始畔，周人作會而民始疑。","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-7","passageId":"li-ji_ch-4_p-78","order":7,"canonicalText":"茍無禮義忠信誠愨之心以蒞之，雖固結之，民其不解乎？","chunks":[["茍無禮義忠信誠愨之心以蒞之，雖固結之，民其不解乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-78_s-8","passageId":"li-ji_ch-4_p-78","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-79_s-1","passageId":"li-ji_ch-4_p-79","order":1,"canonicalText":"喪不慮居，毀不危身。","chunks":[["喪不慮居，毀不危身。","zh-Hant"]]},{"id":"li-ji_ch-4_p-79_s-2","passageId":"li-ji_ch-4_p-79","order":2,"canonicalText":"喪不慮居，為無廟也；","chunks":[["喪不慮居，為無廟也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-79_s-3","passageId":"li-ji_ch-4_p-79","order":3,"canonicalText":"毀不危身，為無後也。","chunks":[["毀不危身，為無後也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-1","passageId":"li-ji_ch-4_p-80","order":1,"canonicalText":"延陵季子適齊，於其反也，其長子死，葬於嬴博之間。","chunks":[["延陵季子適齊，於其反也，其長子死，葬於嬴博之間。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-2","passageId":"li-ji_ch-4_p-80","order":2,"canonicalText":"孔子曰：「延陵季子，吳之習於禮者也。","chunks":[["孔子曰：「延陵季子，吳之習於禮者也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-3","passageId":"li-ji_ch-4_p-80","order":3,"canonicalText":"」往而觀其葬焉。","chunks":[["」往而觀其葬焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-4","passageId":"li-ji_ch-4_p-80","order":4,"canonicalText":"其坎深不至於泉，其斂以時服。","chunks":[["其坎深不至於泉，其斂以時服。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-5","passageId":"li-ji_ch-4_p-80","order":5,"canonicalText":"既葬而封，廣輪掩坎，其高可隱也。","chunks":[["既葬而封，廣輪掩坎，其高可隱也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-6","passageId":"li-ji_ch-4_p-80","order":6,"canonicalText":"既封，左袒，右還其封且號者三，曰：「骨肉歸復于土，命也。","chunks":[["既封，左袒，右還其封且號者三，曰：「骨肉歸復于土，命也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-7","passageId":"li-ji_ch-4_p-80","order":7,"canonicalText":"若魂氣則無不之也，無不之也。","chunks":[["若魂氣則無不之也，無不之也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-8","passageId":"li-ji_ch-4_p-80","order":8,"canonicalText":"」而遂行。","chunks":[["」而遂行。","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-9","passageId":"li-ji_ch-4_p-80","order":9,"canonicalText":"孔子曰：「延陵季子之於禮也，其合矣乎！","chunks":[["孔子曰：「延陵季子之於禮也，其合矣乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-80_s-10","passageId":"li-ji_ch-4_p-80","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-1","passageId":"li-ji_ch-4_p-81","order":1,"canonicalText":"邾婁考公之喪，徐君使容居來吊含，曰：「寡君使容居坐含進侯玉，其使容居以含。","chunks":[["邾婁考公之喪，徐君使容居來吊含，曰：「寡君使容居坐含進侯玉，其使容居以含。","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-2","passageId":"li-ji_ch-4_p-81","order":2,"canonicalText":"」有司曰：「諸侯之來辱敝邑者，易則易，于則于，易于雜者未之有也。","chunks":[["」有司曰：「諸侯之來辱敝邑者，易則易，于則于，易于雜者未之有也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-3","passageId":"li-ji_ch-4_p-81","order":3,"canonicalText":"」容居對曰：「容居聞之：事君不敢忘其君，亦不敢遺其祖。","chunks":[["」容居對曰：「容居聞之：事君不敢忘其君，亦不敢遺其祖。","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-4","passageId":"li-ji_ch-4_p-81","order":4,"canonicalText":"昔我先君駒王西討濟於河，無所不用斯言也。","chunks":[["昔我先君駒王西討濟於河，無所不用斯言也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-5","passageId":"li-ji_ch-4_p-81","order":5,"canonicalText":"容居，魯人也，不敢忘其祖。","chunks":[["容居，魯人也，不敢忘其祖。","zh-Hant"]]},{"id":"li-ji_ch-4_p-81_s-6","passageId":"li-ji_ch-4_p-81","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-82_s-1","passageId":"li-ji_ch-4_p-82","order":1,"canonicalText":"子思之母死於衛，赴於子思，子思哭於廟。","chunks":[["子思之母死於衛，赴於子思，子思哭於廟。","zh-Hant"]]},{"id":"li-ji_ch-4_p-82_s-2","passageId":"li-ji_ch-4_p-82","order":2,"canonicalText":"門人至曰：「庶氏之母死，何為哭於孔氏之廟乎？","chunks":[["門人至曰：「庶氏之母死，何為哭於孔氏之廟乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-82_s-3","passageId":"li-ji_ch-4_p-82","order":3,"canonicalText":"」子思曰：「吾過矣，吾過矣。","chunks":[["」子思曰：「吾過矣，吾過矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-82_s-4","passageId":"li-ji_ch-4_p-82","order":4,"canonicalText":"」遂哭於他室。","chunks":[["」遂哭於他室。","zh-Hant"]]},{"id":"li-ji_ch-4_p-83_s-1","passageId":"li-ji_ch-4_p-83","order":1,"canonicalText":"天子崩，三日祝先服，五日官長服，七日國中男女服，三月天下服。","chunks":[["天子崩，三日祝先服，五日官長服，七日國中男女服，三月天下服。","zh-Hant"]]},{"id":"li-ji_ch-4_p-83_s-2","passageId":"li-ji_ch-4_p-83","order":2,"canonicalText":"虞人致百祀之木，可以為棺槨者斬之；","chunks":[["虞人致百祀之木，可以為棺槨者斬之；","zh-Hant"]]},{"id":"li-ji_ch-4_p-83_s-3","passageId":"li-ji_ch-4_p-83","order":3,"canonicalText":"不至者，廢其祀，刎其人。","chunks":[["不至者，廢其祀，刎其人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-1","passageId":"li-ji_ch-4_p-84","order":1,"canonicalText":"齊大饑，黔敖為食於路，以待餓者而食之。","chunks":[["齊大饑，黔敖為食於路，以待餓者而食之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-2","passageId":"li-ji_ch-4_p-84","order":2,"canonicalText":"有餓者蒙袂輯屨，貿貿然來。","chunks":[["有餓者蒙袂輯屨，貿貿然來。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-3","passageId":"li-ji_ch-4_p-84","order":3,"canonicalText":"黔敖左奉食，右執飲，曰：「嗟！","chunks":[["黔敖左奉食，右執飲，曰：「嗟！","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-4","passageId":"li-ji_ch-4_p-84","order":4,"canonicalText":"來食。","chunks":[["來食。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-5","passageId":"li-ji_ch-4_p-84","order":5,"canonicalText":"」揚其目而視之，曰：「予唯不食嗟來之食，以至於斯也。","chunks":[["」揚其目而視之，曰：「予唯不食嗟來之食，以至於斯也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-6","passageId":"li-ji_ch-4_p-84","order":6,"canonicalText":"」從而謝焉；","chunks":[["」從而謝焉；","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-7","passageId":"li-ji_ch-4_p-84","order":7,"canonicalText":"終不食而死。","chunks":[["終不食而死。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-8","passageId":"li-ji_ch-4_p-84","order":8,"canonicalText":"曾子聞之曰：「微與？","chunks":[["曾子聞之曰：「微與？","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-9","passageId":"li-ji_ch-4_p-84","order":9,"canonicalText":"其嗟也可去，其謝也可食。","chunks":[["其嗟也可去，其謝也可食。","zh-Hant"]]},{"id":"li-ji_ch-4_p-84_s-10","passageId":"li-ji_ch-4_p-84","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-1","passageId":"li-ji_ch-4_p-85","order":1,"canonicalText":"邾婁定公之時，有弒其父者。","chunks":[["邾婁定公之時，有弒其父者。","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-2","passageId":"li-ji_ch-4_p-85","order":2,"canonicalText":"有司以告，公瞿然失席曰：「是寡人之罪也。","chunks":[["有司以告，公瞿然失席曰：「是寡人之罪也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-3","passageId":"li-ji_ch-4_p-85","order":3,"canonicalText":"」曰：「寡人嘗學斷斯獄矣：臣弒君，凡在官者殺無赦；","chunks":[["」曰：「寡人嘗學斷斯獄矣：臣弒君，凡在官者殺無赦；","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-4","passageId":"li-ji_ch-4_p-85","order":4,"canonicalText":"子弒父，凡在宮者殺無赦。","chunks":[["子弒父，凡在宮者殺無赦。","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-5","passageId":"li-ji_ch-4_p-85","order":5,"canonicalText":"殺其人，壞其室，洿其宮而豬焉。","chunks":[["殺其人，壞其室，洿其宮而豬焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-6","passageId":"li-ji_ch-4_p-85","order":6,"canonicalText":"蓋君逾月而後舉爵。","chunks":[["蓋君逾月而後舉爵。","zh-Hant"]]},{"id":"li-ji_ch-4_p-85_s-7","passageId":"li-ji_ch-4_p-85","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-1","passageId":"li-ji_ch-4_p-86","order":1,"canonicalText":"晉獻文子成室，晉大夫發焉。","chunks":[["晉獻文子成室，晉大夫發焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-2","passageId":"li-ji_ch-4_p-86","order":2,"canonicalText":"張老曰：「美哉輪焉！","chunks":[["張老曰：「美哉輪焉！","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-3","passageId":"li-ji_ch-4_p-86","order":3,"canonicalText":"美哉奐焉！","chunks":[["美哉奐焉！","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-4","passageId":"li-ji_ch-4_p-86","order":4,"canonicalText":"拌於斯，哭於斯，聚國族於斯。","chunks":[["拌於斯，哭於斯，聚國族於斯。","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-5","passageId":"li-ji_ch-4_p-86","order":5,"canonicalText":"」文子曰：「武也得歌於斯，哭於斯，聚國族於斯，是全要領以從先大夫於九京也。","chunks":[["」文子曰：「武也得歌於斯，哭於斯，聚國族於斯，是全要領以從先大夫於九京也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-6","passageId":"li-ji_ch-4_p-86","order":6,"canonicalText":"」北面再拜稽首。","chunks":[["」北面再拜稽首。","zh-Hant"]]},{"id":"li-ji_ch-4_p-86_s-7","passageId":"li-ji_ch-4_p-86","order":7,"canonicalText":"君子謂之善頌善禱。","chunks":[["君子謂之善頌善禱。","zh-Hant"]]},{"id":"li-ji_ch-4_p-87_s-1","passageId":"li-ji_ch-4_p-87","order":1,"canonicalText":"仲尼之畜狗死，使子貢埋之，曰：「吾聞之也：敝帷不棄，為埋馬也；","chunks":[["仲尼之畜狗死，使子貢埋之，曰：「吾聞之也：敝帷不棄，為埋馬也；","zh-Hant"]]},{"id":"li-ji_ch-4_p-87_s-2","passageId":"li-ji_ch-4_p-87","order":2,"canonicalText":"敝蓋不棄，為埋狗也。","chunks":[["敝蓋不棄，為埋狗也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-87_s-3","passageId":"li-ji_ch-4_p-87","order":3,"canonicalText":"丘也貧，無蓋；","chunks":[["丘也貧，無蓋；","zh-Hant"]]},{"id":"li-ji_ch-4_p-87_s-4","passageId":"li-ji_ch-4_p-87","order":4,"canonicalText":"於其封也，亦予之席，毋使其首陷焉。","chunks":[["於其封也，亦予之席，毋使其首陷焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-87_s-5","passageId":"li-ji_ch-4_p-87","order":5,"canonicalText":"」路馬死，埋之以帷。","chunks":[["」路馬死，埋之以帷。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-1","passageId":"li-ji_ch-4_p-88","order":1,"canonicalText":"季孫之母死，哀公吊焉，曾子與子貢吊焉，閽人為君在，弗內也。","chunks":[["季孫之母死，哀公吊焉，曾子與子貢吊焉，閽人為君在，弗內也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-2","passageId":"li-ji_ch-4_p-88","order":2,"canonicalText":"曾子與子貢入於其廄而修容焉。","chunks":[["曾子與子貢入於其廄而修容焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-3","passageId":"li-ji_ch-4_p-88","order":3,"canonicalText":"子貢先入，閽人曰：「鄉者已告矣。","chunks":[["子貢先入，閽人曰：「鄉者已告矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-4","passageId":"li-ji_ch-4_p-88","order":4,"canonicalText":"」曾子後入，閽人辟之。","chunks":[["」曾子後入，閽人辟之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-5","passageId":"li-ji_ch-4_p-88","order":5,"canonicalText":"涉內溜，卿大夫皆辟位，公降一等而揖之。","chunks":[["涉內溜，卿大夫皆辟位，公降一等而揖之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-6","passageId":"li-ji_ch-4_p-88","order":6,"canonicalText":"君子言之曰：「盡飾之道，斯其行者遠矣。","chunks":[["君子言之曰：「盡飾之道，斯其行者遠矣。","zh-Hant"]]},{"id":"li-ji_ch-4_p-88_s-7","passageId":"li-ji_ch-4_p-88","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-1","passageId":"li-ji_ch-4_p-89","order":1,"canonicalText":"陽門之介夫死，司城子罕入而哭之哀。","chunks":[["陽門之介夫死，司城子罕入而哭之哀。","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-2","passageId":"li-ji_ch-4_p-89","order":2,"canonicalText":"晉人之覘宋者，反報於晉侯曰：「陽門之介夫死，而子罕哭之哀，而民說，殆不可伐也。","chunks":[["晉人之覘宋者，反報於晉侯曰：「陽門之介夫死，而子罕哭之哀，而民說，殆不可伐也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-3","passageId":"li-ji_ch-4_p-89","order":3,"canonicalText":"」孔子聞之曰：「善哉覘國乎！","chunks":[["」孔子聞之曰：「善哉覘國乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-4","passageId":"li-ji_ch-4_p-89","order":4,"canonicalText":"《詩》云：『凡民有喪，扶服救之。","chunks":[["《詩》云：『凡民有喪，扶服救之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-5","passageId":"li-ji_ch-4_p-89","order":5,"canonicalText":"』雖微晉而已，天下其孰能當之。","chunks":[["』雖微晉而已，天下其孰能當之。","zh-Hant"]]},{"id":"li-ji_ch-4_p-89_s-6","passageId":"li-ji_ch-4_p-89","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-90_s-1","passageId":"li-ji_ch-4_p-90","order":1,"canonicalText":"魯莊公之喪，既葬，而絰不入庫門。","chunks":[["魯莊公之喪，既葬，而絰不入庫門。","zh-Hant"]]},{"id":"li-ji_ch-4_p-90_s-2","passageId":"li-ji_ch-4_p-90","order":2,"canonicalText":"士、大夫既卒哭，麻不入。","chunks":[["士、大夫既卒哭，麻不入。","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-1","passageId":"li-ji_ch-4_p-91","order":1,"canonicalText":"孔子之故人曰原壤，其母死，夫子助之沐槨。","chunks":[["孔子之故人曰原壤，其母死，夫子助之沐槨。","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-2","passageId":"li-ji_ch-4_p-91","order":2,"canonicalText":"原壤登木曰：「久矣予之不托於音也。","chunks":[["原壤登木曰：「久矣予之不托於音也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-3","passageId":"li-ji_ch-4_p-91","order":3,"canonicalText":"」歌曰：「貍首之斑然，執女手之卷然。","chunks":[["」歌曰：「貍首之斑然，執女手之卷然。","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-4","passageId":"li-ji_ch-4_p-91","order":4,"canonicalText":"」夫子為弗聞也者而過之，從者曰：「子未可以已乎？","chunks":[["」夫子為弗聞也者而過之，從者曰：「子未可以已乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-5","passageId":"li-ji_ch-4_p-91","order":5,"canonicalText":"」夫子曰：「丘聞之：親者毋失其為親也，故者毋失其為故也。","chunks":[["」夫子曰：「丘聞之：親者毋失其為親也，故者毋失其為故也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-91_s-6","passageId":"li-ji_ch-4_p-91","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-1","passageId":"li-ji_ch-4_p-92","order":1,"canonicalText":"趙文子與叔譽觀乎九原。","chunks":[["趙文子與叔譽觀乎九原。","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-2","passageId":"li-ji_ch-4_p-92","order":2,"canonicalText":"文子曰：「死者如可作也，吾誰與歸？","chunks":[["文子曰：「死者如可作也，吾誰與歸？","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-3","passageId":"li-ji_ch-4_p-92","order":3,"canonicalText":"」叔譽曰：「其陽處父乎？","chunks":[["」叔譽曰：「其陽處父乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-4","passageId":"li-ji_ch-4_p-92","order":4,"canonicalText":"」文子曰：「行并植於晉國，不沒其身，其知不足稱也。","chunks":[["」文子曰：「行并植於晉國，不沒其身，其知不足稱也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-5","passageId":"li-ji_ch-4_p-92","order":5,"canonicalText":"」「其舅犯乎？","chunks":[["」「其舅犯乎？","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-6","passageId":"li-ji_ch-4_p-92","order":6,"canonicalText":"」文子曰：「見利不顧其君，其仁不足稱也。","chunks":[["」文子曰：「見利不顧其君，其仁不足稱也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-7","passageId":"li-ji_ch-4_p-92","order":7,"canonicalText":"我則隨武子乎，利其君不忘其身，謀其身不遺其友。","chunks":[["我則隨武子乎，利其君不忘其身，謀其身不遺其友。","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-8","passageId":"li-ji_ch-4_p-92","order":8,"canonicalText":"」晉人謂文子知人。","chunks":[["」晉人謂文子知人。","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-9","passageId":"li-ji_ch-4_p-92","order":9,"canonicalText":"文子其中退然如不勝衣，其言吶吶然如不出諸其口；","chunks":[["文子其中退然如不勝衣，其言吶吶然如不出諸其口；","zh-Hant"]]},{"id":"li-ji_ch-4_p-92_s-10","passageId":"li-ji_ch-4_p-92","order":10,"canonicalText":"所舉於晉國管庫之士七十有餘家，生不交利，死不屬其子焉。","chunks":[["所舉於晉國管庫之士七十有餘家，生不交利，死不屬其子焉。","zh-Hant"]]},{"id":"li-ji_ch-4_p-93_s-1","passageId":"li-ji_ch-4_p-93","order":1,"canonicalText":"叔仲皮學子柳。","chunks":[["叔仲皮學子柳。","zh-Hant"]]},{"id":"li-ji_ch-4_p-93_s-2","passageId":"li-ji_ch-4_p-93","order":2,"canonicalText":"叔仲皮死，其妻魯人也，衣衰而繆絰。","chunks":[["叔仲皮死，其妻魯人也，衣衰而繆絰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-93_s-3","passageId":"li-ji_ch-4_p-93","order":3,"canonicalText":"叔仲衍以告，請繐衰而環絰，曰：「昔者吾喪姑姊妹亦如斯，末吾禁也。","chunks":[["叔仲衍以告，請繐衰而環絰，曰：「昔者吾喪姑姊妹亦如斯，末吾禁也。","zh-Hant"]]},{"id":"li-ji_ch-4_p-93_s-4","passageId":"li-ji_ch-4_p-93","order":4,"canonicalText":"」退，使其妻繐衰而環絰。","chunks":[["」退，使其妻繐衰而環絰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-94_s-1","passageId":"li-ji_ch-4_p-94","order":1,"canonicalText":"成人有其兄死而不為衰者，聞子皋將為成宰，遂為衰。","chunks":[["成人有其兄死而不為衰者，聞子皋將為成宰，遂為衰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-94_s-2","passageId":"li-ji_ch-4_p-94","order":2,"canonicalText":"成人曰：「蠶則績而蟹有匡，范則冠而蟬有緌，兄則死而子皋為之衰。","chunks":[["成人曰：「蠶則績而蟹有匡，范則冠而蟬有緌，兄則死而子皋為之衰。","zh-Hant"]]},{"id":"li-ji_ch-4_p-94_s-3","passageId":"li-ji_ch-4_p-94","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-95_s-1","passageId":"li-ji_ch-4_p-95","order":1,"canonicalText":"樂正子春之母死，五日而不食。","chunks":[["樂正子春之母死，五日而不食。","zh-Hant"]]},{"id":"li-ji_ch-4_p-95_s-2","passageId":"li-ji_ch-4_p-95","order":2,"canonicalText":"曰：「吾悔之，自吾母而不得吾情，吾惡乎用吾情！","chunks":[["曰：「吾悔之，自吾母而不得吾情，吾惡乎用吾情！","zh-Hant"]]},{"id":"li-ji_ch-4_p-95_s-3","passageId":"li-ji_ch-4_p-95","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-1","passageId":"li-ji_ch-4_p-96","order":1,"canonicalText":"歲旱，穆公召縣子而問然，曰：「天久不雨，吾欲暴尪而奚若？","chunks":[["歲旱，穆公召縣子而問然，曰：「天久不雨，吾欲暴尪而奚若？","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-2","passageId":"li-ji_ch-4_p-96","order":2,"canonicalText":"」曰：「天久不雨，而暴人之疾子，虐，毋乃不可與！","chunks":[["」曰：「天久不雨，而暴人之疾子，虐，毋乃不可與！","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-3","passageId":"li-ji_ch-4_p-96","order":3,"canonicalText":"」「然則吾欲暴巫而奚若？","chunks":[["」「然則吾欲暴巫而奚若？","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-4","passageId":"li-ji_ch-4_p-96","order":4,"canonicalText":"」曰：「天則不雨，而望之愚婦人，於以求之，毋乃已疏乎！","chunks":[["」曰：「天則不雨，而望之愚婦人，於以求之，毋乃已疏乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-5","passageId":"li-ji_ch-4_p-96","order":5,"canonicalText":"」「徙市則奚若？","chunks":[["」「徙市則奚若？","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-6","passageId":"li-ji_ch-4_p-96","order":6,"canonicalText":"」曰：「天子崩，巷市七日；","chunks":[["」曰：「天子崩，巷市七日；","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-7","passageId":"li-ji_ch-4_p-96","order":7,"canonicalText":"諸侯薨，巷市三日。","chunks":[["諸侯薨，巷市三日。","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-8","passageId":"li-ji_ch-4_p-96","order":8,"canonicalText":"為之徙市，不亦可乎！","chunks":[["為之徙市，不亦可乎！","zh-Hant"]]},{"id":"li-ji_ch-4_p-96_s-9","passageId":"li-ji_ch-4_p-96","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-4_p-97_s-1","passageId":"li-ji_ch-4_p-97","order":1,"canonicalText":"孔子曰：「衛人之祔也，離之；","chunks":[["孔子曰：「衛人之祔也，離之；","zh-Hant"]]},{"id":"li-ji_ch-4_p-97_s-2","passageId":"li-ji_ch-4_p-97","order":2,"canonicalText":"魯人之祔也，合之，善夫！","chunks":[["魯人之祔也，合之，善夫！","zh-Hant"]]},{"id":"li-ji_ch-4_p-97_s-3","passageId":"li-ji_ch-4_p-97","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-5_p-1_s-1","passageId":"li-ji_ch-5_p-1","order":1,"canonicalText":"王者之制：祿爵，公、侯、伯、子、男，凡五等。","chunks":[["王者之制：祿爵，公、侯、伯、子、男，凡五等。","zh-Hant"]]},{"id":"li-ji_ch-5_p-1_s-2","passageId":"li-ji_ch-5_p-1","order":2,"canonicalText":"諸侯之上大夫卿、下大夫、上士、中士、下士，凡五等。","chunks":[["諸侯之上大夫卿、下大夫、上士、中士、下士，凡五等。","zh-Hant"]]},{"id":"li-ji_ch-5_p-2_s-1","passageId":"li-ji_ch-5_p-2","order":1,"canonicalText":"天子之田方千里，公侯田方百里，伯七十里，子男五十里。","chunks":[["天子之田方千里，公侯田方百里，伯七十里，子男五十里。","zh-Hant"]]},{"id":"li-ji_ch-5_p-2_s-2","passageId":"li-ji_ch-5_p-2","order":2,"canonicalText":"不能五十里者，不合於天子，附於諸侯曰附庸。","chunks":[["不能五十里者，不合於天子，附於諸侯曰附庸。","zh-Hant"]]},{"id":"li-ji_ch-5_p-2_s-3","passageId":"li-ji_ch-5_p-2","order":3,"canonicalText":"天子之三公之田視公侯，天子之卿視伯，天子之大夫視子男，天子之元士視附庸。","chunks":[["天子之三公之田視公侯，天子之卿視伯，天子之大夫視子男，天子之元士視附庸。","zh-Hant"]]},{"id":"li-ji_ch-5_p-3_s-1","passageId":"li-ji_ch-5_p-3","order":1,"canonicalText":"制：農田百畝。","chunks":[["制：農田百畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-3_s-2","passageId":"li-ji_ch-5_p-3","order":2,"canonicalText":"百畝之分：上農夫食九人，其次食八人，其次食七人，其次食六人；","chunks":[["百畝之分：上農夫食九人，其次食八人，其次食七人，其次食六人；","zh-Hant"]]},{"id":"li-ji_ch-5_p-3_s-3","passageId":"li-ji_ch-5_p-3","order":3,"canonicalText":"下農夫食五人。","chunks":[["下農夫食五人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-3_s-4","passageId":"li-ji_ch-5_p-3","order":4,"canonicalText":"庶人在官者，其祿以是為差也。","chunks":[["庶人在官者，其祿以是為差也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-1","passageId":"li-ji_ch-5_p-4","order":1,"canonicalText":"諸侯之下士視上農夫，祿足以代其耕也。","chunks":[["諸侯之下士視上農夫，祿足以代其耕也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-2","passageId":"li-ji_ch-5_p-4","order":2,"canonicalText":"中上倍下士，上士倍中士，下大夫倍上士；","chunks":[["中上倍下士，上士倍中士，下大夫倍上士；","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-3","passageId":"li-ji_ch-5_p-4","order":3,"canonicalText":"卿，四大夫祿；","chunks":[["卿，四大夫祿；","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-4","passageId":"li-ji_ch-5_p-4","order":4,"canonicalText":"君，十卿祿。","chunks":[["君，十卿祿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-5","passageId":"li-ji_ch-5_p-4","order":5,"canonicalText":"次國之卿，三大夫祿；","chunks":[["次國之卿，三大夫祿；","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-6","passageId":"li-ji_ch-5_p-4","order":6,"canonicalText":"君，十卿祿。","chunks":[["君，十卿祿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-4_s-7","passageId":"li-ji_ch-5_p-4","order":7,"canonicalText":"小國之卿，倍大夫祿，君十卿祿。","chunks":[["小國之卿，倍大夫祿，君十卿祿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-5_s-1","passageId":"li-ji_ch-5_p-5","order":1,"canonicalText":"次國之上卿，位當大國之中，中當其下，下當其上大夫。","chunks":[["次國之上卿，位當大國之中，中當其下，下當其上大夫。","zh-Hant"]]},{"id":"li-ji_ch-5_p-5_s-2","passageId":"li-ji_ch-5_p-5","order":2,"canonicalText":"小國之上卿，位當大國之下卿，中當其上大夫，下當其下大夫，其有中士、下士者，數各居其上之三分。","chunks":[["小國之上卿，位當大國之下卿，中當其上大夫，下當其下大夫，其有中士、下士者，數各居其上之三分。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-1","passageId":"li-ji_ch-5_p-6","order":1,"canonicalText":"凡四海之內九州，州方千里。","chunks":[["凡四海之內九州，州方千里。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-2","passageId":"li-ji_ch-5_p-6","order":2,"canonicalText":"州，建百里之國三十，七十里之國六十，五十里之國百有二十，凡二百一十國；","chunks":[["州，建百里之國三十，七十里之國六十，五十里之國百有二十，凡二百一十國；","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-3","passageId":"li-ji_ch-5_p-6","order":3,"canonicalText":"名山大澤不以封，其餘以為附庸間田。","chunks":[["名山大澤不以封，其餘以為附庸間田。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-4","passageId":"li-ji_ch-5_p-6","order":4,"canonicalText":"八州，州二百一十國。","chunks":[["八州，州二百一十國。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-5","passageId":"li-ji_ch-5_p-6","order":5,"canonicalText":"天子之縣內，方百里之國九，七十里之國二十有一，五十里之國六十有三，凡九十三國；","chunks":[["天子之縣內，方百里之國九，七十里之國二十有一，五十里之國六十有三，凡九十三國；","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-6","passageId":"li-ji_ch-5_p-6","order":6,"canonicalText":"名山大澤不以封，其餘以祿士，以為間田。","chunks":[["名山大澤不以封，其餘以祿士，以為間田。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-7","passageId":"li-ji_ch-5_p-6","order":7,"canonicalText":"凡九州，千七百七十三國。","chunks":[["凡九州，千七百七十三國。","zh-Hant"]]},{"id":"li-ji_ch-5_p-6_s-8","passageId":"li-ji_ch-5_p-6","order":8,"canonicalText":"天子之元士、諸侯之附庸不與。","chunks":[["天子之元士、諸侯之附庸不與。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-1","passageId":"li-ji_ch-5_p-7","order":1,"canonicalText":"天子百里之內以共官，千里之內以為御。","chunks":[["天子百里之內以共官，千里之內以為御。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-2","passageId":"li-ji_ch-5_p-7","order":2,"canonicalText":"千里之外，設方伯。","chunks":[["千里之外，設方伯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-3","passageId":"li-ji_ch-5_p-7","order":3,"canonicalText":"五國以為屬，屬有長。","chunks":[["五國以為屬，屬有長。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-4","passageId":"li-ji_ch-5_p-7","order":4,"canonicalText":"十國以為連，連有帥。","chunks":[["十國以為連，連有帥。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-5","passageId":"li-ji_ch-5_p-7","order":5,"canonicalText":"三十國以為卒，卒有正。","chunks":[["三十國以為卒，卒有正。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-6","passageId":"li-ji_ch-5_p-7","order":6,"canonicalText":"二百一十國以為州，州有伯。","chunks":[["二百一十國以為州，州有伯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-7","passageId":"li-ji_ch-5_p-7","order":7,"canonicalText":"八州八伯，五十六正，百六十八帥，三百三十六長。","chunks":[["八州八伯，五十六正，百六十八帥，三百三十六長。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-8","passageId":"li-ji_ch-5_p-7","order":8,"canonicalText":"八伯各以其屬，屬於天子之老二人，分天下以為左右，曰二伯。","chunks":[["八伯各以其屬，屬於天子之老二人，分天下以為左右，曰二伯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-7_s-9","passageId":"li-ji_ch-5_p-7","order":9,"canonicalText":"千里之內曰甸，千里之外，曰采、曰流。","chunks":[["千里之內曰甸，千里之外，曰采、曰流。","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-1","passageId":"li-ji_ch-5_p-8","order":1,"canonicalText":"天子：三公，九卿，二十七大夫，八十一元士。","chunks":[["天子：三公，九卿，二十七大夫，八十一元士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-2","passageId":"li-ji_ch-5_p-8","order":2,"canonicalText":"大國：三卿；","chunks":[["大國：三卿；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-3","passageId":"li-ji_ch-5_p-8","order":3,"canonicalText":"皆命於天子；","chunks":[["皆命於天子；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-4","passageId":"li-ji_ch-5_p-8","order":4,"canonicalText":"下大夫五人，上士二十七人。","chunks":[["下大夫五人，上士二十七人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-5","passageId":"li-ji_ch-5_p-8","order":5,"canonicalText":"次國：三卿；","chunks":[["次國：三卿；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-6","passageId":"li-ji_ch-5_p-8","order":6,"canonicalText":"二卿命於天子，一卿命於其君；","chunks":[["二卿命於天子，一卿命於其君；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-7","passageId":"li-ji_ch-5_p-8","order":7,"canonicalText":"下大夫五人，上士二十七人。","chunks":[["下大夫五人，上士二十七人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-8","passageId":"li-ji_ch-5_p-8","order":8,"canonicalText":"小國：二卿；","chunks":[["小國：二卿；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-9","passageId":"li-ji_ch-5_p-8","order":9,"canonicalText":"皆命於其君；","chunks":[["皆命於其君；","zh-Hant"]]},{"id":"li-ji_ch-5_p-8_s-10","passageId":"li-ji_ch-5_p-8","order":10,"canonicalText":"下大夫五人，上士二十七人。","chunks":[["下大夫五人，上士二十七人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-9_s-1","passageId":"li-ji_ch-5_p-9","order":1,"canonicalText":"天子使其大夫為三監，監於方伯之國，國三人。","chunks":[["天子使其大夫為三監，監於方伯之國，國三人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-10_s-1","passageId":"li-ji_ch-5_p-10","order":1,"canonicalText":"天子之縣內諸侯，祿也；","chunks":[["天子之縣內諸侯，祿也；","zh-Hant"]]},{"id":"li-ji_ch-5_p-10_s-2","passageId":"li-ji_ch-5_p-10","order":2,"canonicalText":"外諸侯，嗣也。","chunks":[["外諸侯，嗣也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-1","passageId":"li-ji_ch-5_p-11","order":1,"canonicalText":"制：三公，一命卷；","chunks":[["制：三公，一命卷；","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-2","passageId":"li-ji_ch-5_p-11","order":2,"canonicalText":"若有加，則賜也。","chunks":[["若有加，則賜也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-3","passageId":"li-ji_ch-5_p-11","order":3,"canonicalText":"不過九命。","chunks":[["不過九命。","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-4","passageId":"li-ji_ch-5_p-11","order":4,"canonicalText":"次國之君，不過七命；","chunks":[["次國之君，不過七命；","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-5","passageId":"li-ji_ch-5_p-11","order":5,"canonicalText":"小國之君，不過五命。","chunks":[["小國之君，不過五命。","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-6","passageId":"li-ji_ch-5_p-11","order":6,"canonicalText":"大國之卿，不過三命；","chunks":[["大國之卿，不過三命；","zh-Hant"]]},{"id":"li-ji_ch-5_p-11_s-7","passageId":"li-ji_ch-5_p-11","order":7,"canonicalText":"下卿再命，小國之卿與下大夫一命。","chunks":[["下卿再命，小國之卿與下大夫一命。","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-1","passageId":"li-ji_ch-5_p-12","order":1,"canonicalText":"凡官民材，必先論之。","chunks":[["凡官民材，必先論之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-2","passageId":"li-ji_ch-5_p-12","order":2,"canonicalText":"論辨然後使之，任事然後爵之，位定然後祿之。","chunks":[["論辨然後使之，任事然後爵之，位定然後祿之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-3","passageId":"li-ji_ch-5_p-12","order":3,"canonicalText":"爵人於朝，與士共之。","chunks":[["爵人於朝，與士共之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-4","passageId":"li-ji_ch-5_p-12","order":4,"canonicalText":"刑人於市，與眾棄之。","chunks":[["刑人於市，與眾棄之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-5","passageId":"li-ji_ch-5_p-12","order":5,"canonicalText":"是故公家不畜刑人，大夫弗養，士遇之涂弗與言也；","chunks":[["是故公家不畜刑人，大夫弗養，士遇之涂弗與言也；","zh-Hant"]]},{"id":"li-ji_ch-5_p-12_s-6","passageId":"li-ji_ch-5_p-12","order":6,"canonicalText":"屏之四方，唯其所之，不及以政，亦弗故生也。","chunks":[["屏之四方，唯其所之，不及以政，亦弗故生也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-13_s-1","passageId":"li-ji_ch-5_p-13","order":1,"canonicalText":"諸侯之於天子也，比年一小聘，三年一大聘，五年一朝。","chunks":[["諸侯之於天子也，比年一小聘，三年一大聘，五年一朝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-14_s-1","passageId":"li-ji_ch-5_p-14","order":1,"canonicalText":"天子五年一巡守：歲二月，東巡守至于岱宗，柴而望祀山川；","chunks":[["天子五年一巡守：歲二月，東巡守至于岱宗，柴而望祀山川；","zh-Hant"]]},{"id":"li-ji_ch-5_p-14_s-2","passageId":"li-ji_ch-5_p-14","order":2,"canonicalText":"覲諸侯；","chunks":[["覲諸侯；","zh-Hant"]]},{"id":"li-ji_ch-5_p-14_s-3","passageId":"li-ji_ch-5_p-14","order":3,"canonicalText":"問百年者就見之。","chunks":[["問百年者就見之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-14_s-4","passageId":"li-ji_ch-5_p-14","order":4,"canonicalText":"命大師陳詩以觀民風，命市納賈以觀民之所好惡，志淫好辟。","chunks":[["命大師陳詩以觀民風，命市納賈以觀民之所好惡，志淫好辟。","zh-Hant"]]},{"id":"li-ji_ch-5_p-14_s-5","passageId":"li-ji_ch-5_p-14","order":5,"canonicalText":"命典禮考時月，定日，同律，禮樂制度衣服正之。","chunks":[["命典禮考時月，定日，同律，禮樂制度衣服正之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-1","passageId":"li-ji_ch-5_p-15","order":1,"canonicalText":"山川神祇，有不舉者，為不敬；","chunks":[["山川神祇，有不舉者，為不敬；","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-2","passageId":"li-ji_ch-5_p-15","order":2,"canonicalText":"不敬者，君削以地。","chunks":[["不敬者，君削以地。","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-3","passageId":"li-ji_ch-5_p-15","order":3,"canonicalText":"宗廟，有不順者為不孝；","chunks":[["宗廟，有不順者為不孝；","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-4","passageId":"li-ji_ch-5_p-15","order":4,"canonicalText":"不孝者，君絀以爵。","chunks":[["不孝者，君絀以爵。","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-5","passageId":"li-ji_ch-5_p-15","order":5,"canonicalText":"變禮易樂者，為不從；","chunks":[["變禮易樂者，為不從；","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-6","passageId":"li-ji_ch-5_p-15","order":6,"canonicalText":"不從者，君流。","chunks":[["不從者，君流。","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-7","passageId":"li-ji_ch-5_p-15","order":7,"canonicalText":"革制度衣服者，為畔；","chunks":[["革制度衣服者，為畔；","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-8","passageId":"li-ji_ch-5_p-15","order":8,"canonicalText":"畔者，君討。","chunks":[["畔者，君討。","zh-Hant"]]},{"id":"li-ji_ch-5_p-15_s-9","passageId":"li-ji_ch-5_p-15","order":9,"canonicalText":"有功德於民者，加地進律。","chunks":[["有功德於民者，加地進律。","zh-Hant"]]},{"id":"li-ji_ch-5_p-16_s-1","passageId":"li-ji_ch-5_p-16","order":1,"canonicalText":"五月，南巡守至于南岳，如東巡守之禮。","chunks":[["五月，南巡守至于南岳，如東巡守之禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-16_s-2","passageId":"li-ji_ch-5_p-16","order":2,"canonicalText":"八月，西巡守至于西岳，如南巡守之禮。","chunks":[["八月，西巡守至于西岳，如南巡守之禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-16_s-3","passageId":"li-ji_ch-5_p-16","order":3,"canonicalText":"十有一月，北巡守至于北岳，如西巡守之禮。","chunks":[["十有一月，北巡守至于北岳，如西巡守之禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-16_s-4","passageId":"li-ji_ch-5_p-16","order":4,"canonicalText":"歸，假于祖禰，用特。","chunks":[["歸，假于祖禰，用特。","zh-Hant"]]},{"id":"li-ji_ch-5_p-17_s-1","passageId":"li-ji_ch-5_p-17","order":1,"canonicalText":"天子將出，類乎上帝，宜乎社，造乎禰。","chunks":[["天子將出，類乎上帝，宜乎社，造乎禰。","zh-Hant"]]},{"id":"li-ji_ch-5_p-17_s-2","passageId":"li-ji_ch-5_p-17","order":2,"canonicalText":"諸侯將出，宜乎社，造乎禰。","chunks":[["諸侯將出，宜乎社，造乎禰。","zh-Hant"]]},{"id":"li-ji_ch-5_p-18_s-1","passageId":"li-ji_ch-5_p-18","order":1,"canonicalText":"天子無事與諸侯相見曰朝，考禮正刑一德，以尊于天子。","chunks":[["天子無事與諸侯相見曰朝，考禮正刑一德，以尊于天子。","zh-Hant"]]},{"id":"li-ji_ch-5_p-19_s-1","passageId":"li-ji_ch-5_p-19","order":1,"canonicalText":"天子賜諸侯樂，則以柷將之，賜伯、子、男樂，則以鼗將之。","chunks":[["天子賜諸侯樂，則以柷將之，賜伯、子、男樂，則以鼗將之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-20_s-1","passageId":"li-ji_ch-5_p-20","order":1,"canonicalText":"諸侯，賜弓矢然後征，賜鈇鉞然後殺，賜圭瓚然後為鬯。","chunks":[["諸侯，賜弓矢然後征，賜鈇鉞然後殺，賜圭瓚然後為鬯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-20_s-2","passageId":"li-ji_ch-5_p-20","order":2,"canonicalText":"未賜圭瓚，則資鬯於天子。","chunks":[["未賜圭瓚，則資鬯於天子。","zh-Hant"]]},{"id":"li-ji_ch-5_p-21_s-1","passageId":"li-ji_ch-5_p-21","order":1,"canonicalText":"天子命之教然後為學。","chunks":[["天子命之教然後為學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-21_s-2","passageId":"li-ji_ch-5_p-21","order":2,"canonicalText":"小學在公宮南之左，大學在郊。","chunks":[["小學在公宮南之左，大學在郊。","zh-Hant"]]},{"id":"li-ji_ch-5_p-21_s-3","passageId":"li-ji_ch-5_p-21","order":3,"canonicalText":"天子曰辟癰，諸侯曰頖宮。","chunks":[["天子曰辟癰，諸侯曰頖宮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-22_s-1","passageId":"li-ji_ch-5_p-22","order":1,"canonicalText":"天子將出征，類乎上帝，宜乎社，造乎禰，禡於所征之地。","chunks":[["天子將出征，類乎上帝，宜乎社，造乎禰，禡於所征之地。","zh-Hant"]]},{"id":"li-ji_ch-5_p-22_s-2","passageId":"li-ji_ch-5_p-22","order":2,"canonicalText":"受命於祖，受成於學。","chunks":[["受命於祖，受成於學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-22_s-3","passageId":"li-ji_ch-5_p-22","order":3,"canonicalText":"出征，執有罪；","chunks":[["出征，執有罪；","zh-Hant"]]},{"id":"li-ji_ch-5_p-22_s-4","passageId":"li-ji_ch-5_p-22","order":4,"canonicalText":"反，釋奠于學，以訊馘告。","chunks":[["反，釋奠于學，以訊馘告。","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-1","passageId":"li-ji_ch-5_p-23","order":1,"canonicalText":"天子、諸侯無事則歲三田：一為乾豆，二為賓客，三為充君之庖。","chunks":[["天子、諸侯無事則歲三田：一為乾豆，二為賓客，三為充君之庖。","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-2","passageId":"li-ji_ch-5_p-23","order":2,"canonicalText":"無事而不田，曰不敬；","chunks":[["無事而不田，曰不敬；","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-3","passageId":"li-ji_ch-5_p-23","order":3,"canonicalText":"田不以禮，曰暴天物。","chunks":[["田不以禮，曰暴天物。","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-4","passageId":"li-ji_ch-5_p-23","order":4,"canonicalText":"天子不合圍，諸侯不掩群。","chunks":[["天子不合圍，諸侯不掩群。","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-5","passageId":"li-ji_ch-5_p-23","order":5,"canonicalText":"天子殺則下大綏，諸侯殺則下小綏，大夫殺則止佐車。","chunks":[["天子殺則下大綏，諸侯殺則下小綏，大夫殺則止佐車。","zh-Hant"]]},{"id":"li-ji_ch-5_p-23_s-6","passageId":"li-ji_ch-5_p-23","order":6,"canonicalText":"佐車止，則百姓田獵。","chunks":[["佐車止，則百姓田獵。","zh-Hant"]]},{"id":"li-ji_ch-5_p-24_s-1","passageId":"li-ji_ch-5_p-24","order":1,"canonicalText":"獺祭魚，然後虞人入澤梁。","chunks":[["獺祭魚，然後虞人入澤梁。","zh-Hant"]]},{"id":"li-ji_ch-5_p-24_s-2","passageId":"li-ji_ch-5_p-24","order":2,"canonicalText":"豺祭獸，然後田獵。","chunks":[["豺祭獸，然後田獵。","zh-Hant"]]},{"id":"li-ji_ch-5_p-24_s-3","passageId":"li-ji_ch-5_p-24","order":3,"canonicalText":"鳩化為鷹，然後設罻羅。","chunks":[["鳩化為鷹，然後設罻羅。","zh-Hant"]]},{"id":"li-ji_ch-5_p-24_s-4","passageId":"li-ji_ch-5_p-24","order":4,"canonicalText":"草木零落，然後入山林。","chunks":[["草木零落，然後入山林。","zh-Hant"]]},{"id":"li-ji_ch-5_p-24_s-5","passageId":"li-ji_ch-5_p-24","order":5,"canonicalText":"昆蟲未蟄，不以火田，不麑，不卵，不殺胎，不殀夭，不覆巢。","chunks":[["昆蟲未蟄，不以火田，不麑，不卵，不殺胎，不殀夭，不覆巢。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-1","passageId":"li-ji_ch-5_p-25","order":1,"canonicalText":"冢宰制國用，必於歲之杪，五穀皆入然後制國用。","chunks":[["冢宰制國用，必於歲之杪，五穀皆入然後制國用。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-2","passageId":"li-ji_ch-5_p-25","order":2,"canonicalText":"用地小大，視年之豐耗。","chunks":[["用地小大，視年之豐耗。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-3","passageId":"li-ji_ch-5_p-25","order":3,"canonicalText":"以三十年之通制國用，量入以為出，祭用數之仂。","chunks":[["以三十年之通制國用，量入以為出，祭用數之仂。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-4","passageId":"li-ji_ch-5_p-25","order":4,"canonicalText":"喪，三年不祭，唯祭天地社稷為越紼而行事。","chunks":[["喪，三年不祭，唯祭天地社稷為越紼而行事。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-5","passageId":"li-ji_ch-5_p-25","order":5,"canonicalText":"喪用三年之仂。","chunks":[["喪用三年之仂。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-6","passageId":"li-ji_ch-5_p-25","order":6,"canonicalText":"喪祭，用不足曰暴，有余曰浩。","chunks":[["喪祭，用不足曰暴，有余曰浩。","zh-Hant"]]},{"id":"li-ji_ch-5_p-25_s-7","passageId":"li-ji_ch-5_p-25","order":7,"canonicalText":"祭，豐年不奢，凶年不儉。","chunks":[["祭，豐年不奢，凶年不儉。","zh-Hant"]]},{"id":"li-ji_ch-5_p-26_s-1","passageId":"li-ji_ch-5_p-26","order":1,"canonicalText":"國無九年之蓄曰不足，無六年之蓄曰急，無三年之蓄曰國非其國也。","chunks":[["國無九年之蓄曰不足，無六年之蓄曰急，無三年之蓄曰國非其國也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-26_s-2","passageId":"li-ji_ch-5_p-26","order":2,"canonicalText":"三年耕，必有一年之食；","chunks":[["三年耕，必有一年之食；","zh-Hant"]]},{"id":"li-ji_ch-5_p-26_s-3","passageId":"li-ji_ch-5_p-26","order":3,"canonicalText":"九年耕，必有三年之食。","chunks":[["九年耕，必有三年之食。","zh-Hant"]]},{"id":"li-ji_ch-5_p-26_s-4","passageId":"li-ji_ch-5_p-26","order":4,"canonicalText":"以三十年之通，雖有凶旱水溢，民無菜色，然後天子食，日舉以樂。","chunks":[["以三十年之通，雖有凶旱水溢，民無菜色，然後天子食，日舉以樂。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-1","passageId":"li-ji_ch-5_p-27","order":1,"canonicalText":"天子七日而殯，七月而葬。","chunks":[["天子七日而殯，七月而葬。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-2","passageId":"li-ji_ch-5_p-27","order":2,"canonicalText":"諸侯五日而殯，五月而葬。","chunks":[["諸侯五日而殯，五月而葬。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-3","passageId":"li-ji_ch-5_p-27","order":3,"canonicalText":"大夫、士、庶人，三日而殯，三月而葬。","chunks":[["大夫、士、庶人，三日而殯，三月而葬。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-4","passageId":"li-ji_ch-5_p-27","order":4,"canonicalText":"三年之喪，自天子達，庶人縣封，葬不為雨止，不封不樹，喪不貳事，自天子達於庶人。","chunks":[["三年之喪，自天子達，庶人縣封，葬不為雨止，不封不樹，喪不貳事，自天子達於庶人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-5","passageId":"li-ji_ch-5_p-27","order":5,"canonicalText":"喪從死者，祭從生者。","chunks":[["喪從死者，祭從生者。","zh-Hant"]]},{"id":"li-ji_ch-5_p-27_s-6","passageId":"li-ji_ch-5_p-27","order":6,"canonicalText":"支子不祭。","chunks":[["支子不祭。","zh-Hant"]]},{"id":"li-ji_ch-5_p-28_s-1","passageId":"li-ji_ch-5_p-28","order":1,"canonicalText":"天子七廟，三昭三穆，與太祖之廟而七。","chunks":[["天子七廟，三昭三穆，與太祖之廟而七。","zh-Hant"]]},{"id":"li-ji_ch-5_p-28_s-2","passageId":"li-ji_ch-5_p-28","order":2,"canonicalText":"諸侯五廟，二昭二穆，與太祖之廟而五。","chunks":[["諸侯五廟，二昭二穆，與太祖之廟而五。","zh-Hant"]]},{"id":"li-ji_ch-5_p-28_s-3","passageId":"li-ji_ch-5_p-28","order":3,"canonicalText":"大夫三廟，一昭一穆，與太祖之廟而三。","chunks":[["大夫三廟，一昭一穆，與太祖之廟而三。","zh-Hant"]]},{"id":"li-ji_ch-5_p-28_s-4","passageId":"li-ji_ch-5_p-28","order":4,"canonicalText":"士一廟。","chunks":[["士一廟。","zh-Hant"]]},{"id":"li-ji_ch-5_p-28_s-5","passageId":"li-ji_ch-5_p-28","order":5,"canonicalText":"庶人祭於寢。","chunks":[["庶人祭於寢。","zh-Hant"]]},{"id":"li-ji_ch-5_p-29_s-1","passageId":"li-ji_ch-5_p-29","order":1,"canonicalText":"天子、諸侯宗廟之祭：春曰礿，夏曰禘，秋曰嘗，冬曰烝。","chunks":[["天子、諸侯宗廟之祭：春曰礿，夏曰禘，秋曰嘗，冬曰烝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-30_s-1","passageId":"li-ji_ch-5_p-30","order":1,"canonicalText":"天子祭天地，諸侯祭社稷，大夫祭五祀。","chunks":[["天子祭天地，諸侯祭社稷，大夫祭五祀。","zh-Hant"]]},{"id":"li-ji_ch-5_p-30_s-2","passageId":"li-ji_ch-5_p-30","order":2,"canonicalText":"天子祭天下名山大川：五岳視三公，四瀆視諸侯。","chunks":[["天子祭天下名山大川：五岳視三公，四瀆視諸侯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-30_s-3","passageId":"li-ji_ch-5_p-30","order":3,"canonicalText":"諸侯祭名山大川之在其地者。","chunks":[["諸侯祭名山大川之在其地者。","zh-Hant"]]},{"id":"li-ji_ch-5_p-31_s-1","passageId":"li-ji_ch-5_p-31","order":1,"canonicalText":"天子諸侯祭因國之在其地而無主後者。","chunks":[["天子諸侯祭因國之在其地而無主後者。","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-1","passageId":"li-ji_ch-5_p-32","order":1,"canonicalText":"天子犆礿，祫禘，祫嘗，祫烝。","chunks":[["天子犆礿，祫禘，祫嘗，祫烝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-2","passageId":"li-ji_ch-5_p-32","order":2,"canonicalText":"諸侯礿則不禘，禘則不嘗，嘗則不烝，烝則不礿。","chunks":[["諸侯礿則不禘，禘則不嘗，嘗則不烝，烝則不礿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-3","passageId":"li-ji_ch-5_p-32","order":3,"canonicalText":"諸侯礿，犆；","chunks":[["諸侯礿，犆；","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-4","passageId":"li-ji_ch-5_p-32","order":4,"canonicalText":"禘，一犆一祫；","chunks":[["禘，一犆一祫；","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-5","passageId":"li-ji_ch-5_p-32","order":5,"canonicalText":"嘗，祫；","chunks":[["嘗，祫；","zh-Hant"]]},{"id":"li-ji_ch-5_p-32_s-6","passageId":"li-ji_ch-5_p-32","order":6,"canonicalText":"烝，祫。","chunks":[["烝，祫。","zh-Hant"]]},{"id":"li-ji_ch-5_p-33_s-1","passageId":"li-ji_ch-5_p-33","order":1,"canonicalText":"天子社稷皆大牢，諸侯社稷皆少牢。","chunks":[["天子社稷皆大牢，諸侯社稷皆少牢。","zh-Hant"]]},{"id":"li-ji_ch-5_p-33_s-2","passageId":"li-ji_ch-5_p-33","order":2,"canonicalText":"大夫、士宗廟之祭，有田則祭，無田則薦。","chunks":[["大夫、士宗廟之祭，有田則祭，無田則薦。","zh-Hant"]]},{"id":"li-ji_ch-5_p-33_s-3","passageId":"li-ji_ch-5_p-33","order":3,"canonicalText":"庶人春薦韭，夏薦麥，秋薦黍，冬薦稻。","chunks":[["庶人春薦韭，夏薦麥，秋薦黍，冬薦稻。","zh-Hant"]]},{"id":"li-ji_ch-5_p-33_s-4","passageId":"li-ji_ch-5_p-33","order":4,"canonicalText":"韭以卵，麥以魚，黍以豚，稻以雁。","chunks":[["韭以卵，麥以魚，黍以豚，稻以雁。","zh-Hant"]]},{"id":"li-ji_ch-5_p-34_s-1","passageId":"li-ji_ch-5_p-34","order":1,"canonicalText":"祭天地之牛，角繭栗；","chunks":[["祭天地之牛，角繭栗；","zh-Hant"]]},{"id":"li-ji_ch-5_p-34_s-2","passageId":"li-ji_ch-5_p-34","order":2,"canonicalText":"宗廟之牛，角握；","chunks":[["宗廟之牛，角握；","zh-Hant"]]},{"id":"li-ji_ch-5_p-34_s-3","passageId":"li-ji_ch-5_p-34","order":3,"canonicalText":"賓客之牛，角尺。","chunks":[["賓客之牛，角尺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-34_s-4","passageId":"li-ji_ch-5_p-34","order":4,"canonicalText":"諸侯無故不殺牛，大夫無故不殺羊，士無故不殺犬豕，庶人無故不食珍。","chunks":[["諸侯無故不殺牛，大夫無故不殺羊，士無故不殺犬豕，庶人無故不食珍。","zh-Hant"]]},{"id":"li-ji_ch-5_p-34_s-5","passageId":"li-ji_ch-5_p-34","order":5,"canonicalText":"庶羞不逾牲，燕衣不逾祭服，寢不逾廟。","chunks":[["庶羞不逾牲，燕衣不逾祭服，寢不逾廟。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-1","passageId":"li-ji_ch-5_p-35","order":1,"canonicalText":"古者：公田，藉而不稅。","chunks":[["古者：公田，藉而不稅。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-2","passageId":"li-ji_ch-5_p-35","order":2,"canonicalText":"市，廛而不稅。","chunks":[["市，廛而不稅。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-3","passageId":"li-ji_ch-5_p-35","order":3,"canonicalText":"關，譏而不征。","chunks":[["關，譏而不征。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-4","passageId":"li-ji_ch-5_p-35","order":4,"canonicalText":"林麓川澤，以時入而不禁。","chunks":[["林麓川澤，以時入而不禁。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-5","passageId":"li-ji_ch-5_p-35","order":5,"canonicalText":"夫圭田無征。","chunks":[["夫圭田無征。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-6","passageId":"li-ji_ch-5_p-35","order":6,"canonicalText":"用民之力，歲不過三日。","chunks":[["用民之力，歲不過三日。","zh-Hant"]]},{"id":"li-ji_ch-5_p-35_s-7","passageId":"li-ji_ch-5_p-35","order":7,"canonicalText":"田里不粥，墓地不請。","chunks":[["田里不粥，墓地不請。","zh-Hant"]]},{"id":"li-ji_ch-5_p-36_s-1","passageId":"li-ji_ch-5_p-36","order":1,"canonicalText":"司空執度度地，居民山川沮澤，時四時。","chunks":[["司空執度度地，居民山川沮澤，時四時。","zh-Hant"]]},{"id":"li-ji_ch-5_p-36_s-2","passageId":"li-ji_ch-5_p-36","order":2,"canonicalText":"量地遠近，興事任力。","chunks":[["量地遠近，興事任力。","zh-Hant"]]},{"id":"li-ji_ch-5_p-36_s-3","passageId":"li-ji_ch-5_p-36","order":3,"canonicalText":"凡使民：任老者之事，食壯者之食。","chunks":[["凡使民：任老者之事，食壯者之食。","zh-Hant"]]},{"id":"li-ji_ch-5_p-37_s-1","passageId":"li-ji_ch-5_p-37","order":1,"canonicalText":"凡居民材，必因天地寒暖燥濕，廣谷大川異制。","chunks":[["凡居民材，必因天地寒暖燥濕，廣谷大川異制。","zh-Hant"]]},{"id":"li-ji_ch-5_p-37_s-2","passageId":"li-ji_ch-5_p-37","order":2,"canonicalText":"民生其間者異俗：剛柔輕重遲速異齊，五味異和，器械異制，衣服異宜。","chunks":[["民生其間者異俗：剛柔輕重遲速異齊，五味異和，器械異制，衣服異宜。","zh-Hant"]]},{"id":"li-ji_ch-5_p-37_s-3","passageId":"li-ji_ch-5_p-37","order":3,"canonicalText":"修其教，不易其俗；","chunks":[["修其教，不易其俗；","zh-Hant"]]},{"id":"li-ji_ch-5_p-37_s-4","passageId":"li-ji_ch-5_p-37","order":4,"canonicalText":"齊其政，不易其宜。","chunks":[["齊其政，不易其宜。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-1","passageId":"li-ji_ch-5_p-38","order":1,"canonicalText":"中國戎夷，五方之民，皆有其性也，不可推移。","chunks":[["中國戎夷，五方之民，皆有其性也，不可推移。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-2","passageId":"li-ji_ch-5_p-38","order":2,"canonicalText":"東方曰夷，被髮文身，有不火食者矣。","chunks":[["東方曰夷，被髮文身，有不火食者矣。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-3","passageId":"li-ji_ch-5_p-38","order":3,"canonicalText":"南方曰蠻，雕題交趾，有不火食者矣。","chunks":[["南方曰蠻，雕題交趾，有不火食者矣。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-4","passageId":"li-ji_ch-5_p-38","order":4,"canonicalText":"西方曰戎，被髮衣皮，有不粒食者矣。","chunks":[["西方曰戎，被髮衣皮，有不粒食者矣。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-5","passageId":"li-ji_ch-5_p-38","order":5,"canonicalText":"北方曰狄，衣羽毛穴居，有不粒食者矣。","chunks":[["北方曰狄，衣羽毛穴居，有不粒食者矣。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-6","passageId":"li-ji_ch-5_p-38","order":6,"canonicalText":"中國、夷、蠻、戎、狄，皆有安居、和味、宜服、利用、備器，五方之民，言語不通，嗜欲不同。","chunks":[["中國、夷、蠻、戎、狄，皆有安居、和味、宜服、利用、備器，五方之民，言語不通，嗜欲不同。","zh-Hant"]]},{"id":"li-ji_ch-5_p-38_s-7","passageId":"li-ji_ch-5_p-38","order":7,"canonicalText":"達其志，通其欲：東方曰寄，南方曰象，西方曰狄鞮，北方曰譯。","chunks":[["達其志，通其欲：東方曰寄，南方曰象，西方曰狄鞮，北方曰譯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-39_s-1","passageId":"li-ji_ch-5_p-39","order":1,"canonicalText":"凡居民，量地以制邑，度地以居民。","chunks":[["凡居民，量地以制邑，度地以居民。","zh-Hant"]]},{"id":"li-ji_ch-5_p-39_s-2","passageId":"li-ji_ch-5_p-39","order":2,"canonicalText":"地、邑、民、居，必參相得也。","chunks":[["地、邑、民、居，必參相得也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-39_s-3","passageId":"li-ji_ch-5_p-39","order":3,"canonicalText":"無曠土，無游民，食節事時，民咸安其居，樂事勸功，尊君親上，然後興學。","chunks":[["無曠土，無游民，食節事時，民咸安其居，樂事勸功，尊君親上，然後興學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-40_s-1","passageId":"li-ji_ch-5_p-40","order":1,"canonicalText":"司徒修六禮以節民性，明七教以興民德，齊八政以防淫，一道德以同俗，養耆老以致孝，恤孤獨以逮不足，上賢以崇德，簡不肖以絀惡。","chunks":[["司徒修六禮以節民性，明七教以興民德，齊八政以防淫，一道德以同俗，養耆老以致孝，恤孤獨以逮不足，上賢以崇德，簡不肖以絀惡。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-1","passageId":"li-ji_ch-5_p-41","order":1,"canonicalText":"命鄉，簡不帥教者以告。","chunks":[["命鄉，簡不帥教者以告。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-2","passageId":"li-ji_ch-5_p-41","order":2,"canonicalText":"耆老皆朝于庠，元日，習射上功，習鄉上齒，大司徒帥國之俊士與執事焉。","chunks":[["耆老皆朝于庠，元日，習射上功，習鄉上齒，大司徒帥國之俊士與執事焉。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-3","passageId":"li-ji_ch-5_p-41","order":3,"canonicalText":"不變，命國之右鄉，簡不帥教者移之左；","chunks":[["不變，命國之右鄉，簡不帥教者移之左；","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-4","passageId":"li-ji_ch-5_p-41","order":4,"canonicalText":"命國之左鄉，簡不帥教者移之右，如初禮。","chunks":[["命國之左鄉，簡不帥教者移之右，如初禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-5","passageId":"li-ji_ch-5_p-41","order":5,"canonicalText":"不變，移之郊，如初禮。","chunks":[["不變，移之郊，如初禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-6","passageId":"li-ji_ch-5_p-41","order":6,"canonicalText":"不變，移之遂，如初禮。","chunks":[["不變，移之遂，如初禮。","zh-Hant"]]},{"id":"li-ji_ch-5_p-41_s-7","passageId":"li-ji_ch-5_p-41","order":7,"canonicalText":"不變，屏之遠方，終身不齒。","chunks":[["不變，屏之遠方，終身不齒。","zh-Hant"]]},{"id":"li-ji_ch-5_p-42_s-1","passageId":"li-ji_ch-5_p-42","order":1,"canonicalText":"命鄉，論秀士，升之司徒，曰選士。","chunks":[["命鄉，論秀士，升之司徒，曰選士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-42_s-2","passageId":"li-ji_ch-5_p-42","order":2,"canonicalText":"司徒論選士之秀者而升之學，曰俊士。","chunks":[["司徒論選士之秀者而升之學，曰俊士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-42_s-3","passageId":"li-ji_ch-5_p-42","order":3,"canonicalText":"升於司徒者，不征於鄉；","chunks":[["升於司徒者，不征於鄉；","zh-Hant"]]},{"id":"li-ji_ch-5_p-42_s-4","passageId":"li-ji_ch-5_p-42","order":4,"canonicalText":"升於學者，不征於司徒，曰造士。","chunks":[["升於學者，不征於司徒，曰造士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-43_s-1","passageId":"li-ji_ch-5_p-43","order":1,"canonicalText":"樂正崇四術，立四教，順先王詩書禮樂以造士。","chunks":[["樂正崇四術，立四教，順先王詩書禮樂以造士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-43_s-2","passageId":"li-ji_ch-5_p-43","order":2,"canonicalText":"春、秋教以禮樂，冬、夏教以詩書。","chunks":[["春、秋教以禮樂，冬、夏教以詩書。","zh-Hant"]]},{"id":"li-ji_ch-5_p-43_s-3","passageId":"li-ji_ch-5_p-43","order":3,"canonicalText":"王大子、王子、群後之大子、卿大夫元士之適子、國之俊選，皆造焉。","chunks":[["王大子、王子、群後之大子、卿大夫元士之適子、國之俊選，皆造焉。","zh-Hant"]]},{"id":"li-ji_ch-5_p-43_s-4","passageId":"li-ji_ch-5_p-43","order":4,"canonicalText":"凡入學以齒。","chunks":[["凡入學以齒。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-1","passageId":"li-ji_ch-5_p-44","order":1,"canonicalText":"將出學，小胥、大胥、小樂正簡不帥教者以告于大樂正。","chunks":[["將出學，小胥、大胥、小樂正簡不帥教者以告于大樂正。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-2","passageId":"li-ji_ch-5_p-44","order":2,"canonicalText":"大樂正以告于王。","chunks":[["大樂正以告于王。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-3","passageId":"li-ji_ch-5_p-44","order":3,"canonicalText":"王命三公、九卿、大夫、元士皆入學。","chunks":[["王命三公、九卿、大夫、元士皆入學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-4","passageId":"li-ji_ch-5_p-44","order":4,"canonicalText":"不變，王親視學。","chunks":[["不變，王親視學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-5","passageId":"li-ji_ch-5_p-44","order":5,"canonicalText":"不變，王三日不舉，屏之遠方。","chunks":[["不變，王三日不舉，屏之遠方。","zh-Hant"]]},{"id":"li-ji_ch-5_p-44_s-6","passageId":"li-ji_ch-5_p-44","order":6,"canonicalText":"西方曰棘，東方曰寄，終身不齒。","chunks":[["西方曰棘，東方曰寄，終身不齒。","zh-Hant"]]},{"id":"li-ji_ch-5_p-45_s-1","passageId":"li-ji_ch-5_p-45","order":1,"canonicalText":"大樂正論造士之秀者以告于王，而升諸司馬，曰進士。","chunks":[["大樂正論造士之秀者以告于王，而升諸司馬，曰進士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-46_s-1","passageId":"li-ji_ch-5_p-46","order":1,"canonicalText":"司馬辨論官材，論進士之賢者以告於王，而定其論。","chunks":[["司馬辨論官材，論進士之賢者以告於王，而定其論。","zh-Hant"]]},{"id":"li-ji_ch-5_p-46_s-2","passageId":"li-ji_ch-5_p-46","order":2,"canonicalText":"論定然後官之，任官然後爵之，位定然後祿之。","chunks":[["論定然後官之，任官然後爵之，位定然後祿之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-47_s-1","passageId":"li-ji_ch-5_p-47","order":1,"canonicalText":"大夫廢其事，終身不仕，死以士禮葬之。","chunks":[["大夫廢其事，終身不仕，死以士禮葬之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-48_s-1","passageId":"li-ji_ch-5_p-48","order":1,"canonicalText":"有發，則命大司徒教士以車甲。","chunks":[["有發，則命大司徒教士以車甲。","zh-Hant"]]},{"id":"li-ji_ch-5_p-49_s-1","passageId":"li-ji_ch-5_p-49","order":1,"canonicalText":"凡執技論力，適四方，裸股肱，決射御。","chunks":[["凡執技論力，適四方，裸股肱，決射御。","zh-Hant"]]},{"id":"li-ji_ch-5_p-49_s-2","passageId":"li-ji_ch-5_p-49","order":2,"canonicalText":"凡執技以事上者：祝史、射御、醫卜及百工。","chunks":[["凡執技以事上者：祝史、射御、醫卜及百工。","zh-Hant"]]},{"id":"li-ji_ch-5_p-49_s-3","passageId":"li-ji_ch-5_p-49","order":3,"canonicalText":"凡執技以事上者：不貳事，不移官，出鄉不與士齒。","chunks":[["凡執技以事上者：不貳事，不移官，出鄉不與士齒。","zh-Hant"]]},{"id":"li-ji_ch-5_p-49_s-4","passageId":"li-ji_ch-5_p-49","order":4,"canonicalText":"仕於家者，出鄉不與士齒。","chunks":[["仕於家者，出鄉不與士齒。","zh-Hant"]]},{"id":"li-ji_ch-5_p-50_s-1","passageId":"li-ji_ch-5_p-50","order":1,"canonicalText":"司寇正刑明辟以聽獄訟。","chunks":[["司寇正刑明辟以聽獄訟。","zh-Hant"]]},{"id":"li-ji_ch-5_p-50_s-2","passageId":"li-ji_ch-5_p-50","order":2,"canonicalText":"必三刺。","chunks":[["必三刺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-50_s-3","passageId":"li-ji_ch-5_p-50","order":3,"canonicalText":"有旨無簡不聽。","chunks":[["有旨無簡不聽。","zh-Hant"]]},{"id":"li-ji_ch-5_p-50_s-4","passageId":"li-ji_ch-5_p-50","order":4,"canonicalText":"附從輕，赦從重。","chunks":[["附從輕，赦從重。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-1","passageId":"li-ji_ch-5_p-51","order":1,"canonicalText":"凡制五刑，必即天論。","chunks":[["凡制五刑，必即天論。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-2","passageId":"li-ji_ch-5_p-51","order":2,"canonicalText":"郵罰麗於事。","chunks":[["郵罰麗於事。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-3","passageId":"li-ji_ch-5_p-51","order":3,"canonicalText":"凡聽五刑之訟，必原父子之親、立君臣之義以權之。","chunks":[["凡聽五刑之訟，必原父子之親、立君臣之義以權之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-4","passageId":"li-ji_ch-5_p-51","order":4,"canonicalText":"意論輕重之序、慎測淺深之量以別之。","chunks":[["意論輕重之序、慎測淺深之量以別之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-5","passageId":"li-ji_ch-5_p-51","order":5,"canonicalText":"悉其聰明、致其忠愛以盡之。","chunks":[["悉其聰明、致其忠愛以盡之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-6","passageId":"li-ji_ch-5_p-51","order":6,"canonicalText":"疑獄，泛與眾共之；","chunks":[["疑獄，泛與眾共之；","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-7","passageId":"li-ji_ch-5_p-51","order":7,"canonicalText":"眾疑，赦之。","chunks":[["眾疑，赦之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-51_s-8","passageId":"li-ji_ch-5_p-51","order":8,"canonicalText":"必察小大之比以成之。","chunks":[["必察小大之比以成之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-52_s-1","passageId":"li-ji_ch-5_p-52","order":1,"canonicalText":"成獄辭，史以獄成告於正，正聽之。","chunks":[["成獄辭，史以獄成告於正，正聽之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-52_s-2","passageId":"li-ji_ch-5_p-52","order":2,"canonicalText":"正以獄成告于大司寇，大司寇聽之棘木之下。","chunks":[["正以獄成告于大司寇，大司寇聽之棘木之下。","zh-Hant"]]},{"id":"li-ji_ch-5_p-52_s-3","passageId":"li-ji_ch-5_p-52","order":3,"canonicalText":"大司寇以獄之成告於王，王命三公參聽之。","chunks":[["大司寇以獄之成告於王，王命三公參聽之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-52_s-4","passageId":"li-ji_ch-5_p-52","order":4,"canonicalText":"三公以獄之成告於王，王三又，然後制刑。","chunks":[["三公以獄之成告於王，王三又，然後制刑。","zh-Hant"]]},{"id":"li-ji_ch-5_p-53_s-1","passageId":"li-ji_ch-5_p-53","order":1,"canonicalText":"凡作刑罰，輕無赦。","chunks":[["凡作刑罰，輕無赦。","zh-Hant"]]},{"id":"li-ji_ch-5_p-53_s-2","passageId":"li-ji_ch-5_p-53","order":2,"canonicalText":"刑者侀也，侀者成也，一成而不可變，故君子盡心焉。","chunks":[["刑者侀也，侀者成也，一成而不可變，故君子盡心焉。","zh-Hant"]]},{"id":"li-ji_ch-5_p-54_s-1","passageId":"li-ji_ch-5_p-54","order":1,"canonicalText":"析言破律，亂名改作，執左道以亂政，殺。","chunks":[["析言破律，亂名改作，執左道以亂政，殺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-54_s-2","passageId":"li-ji_ch-5_p-54","order":2,"canonicalText":"作淫聲、異服、奇技、奇器以疑眾，殺。","chunks":[["作淫聲、異服、奇技、奇器以疑眾，殺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-54_s-3","passageId":"li-ji_ch-5_p-54","order":3,"canonicalText":"行偽而堅，言偽而辯，學非而博，順非而澤，以疑眾，殺。","chunks":[["行偽而堅，言偽而辯，學非而博，順非而澤，以疑眾，殺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-54_s-4","passageId":"li-ji_ch-5_p-54","order":4,"canonicalText":"假於鬼神、時日、卜筮以疑眾，殺。","chunks":[["假於鬼神、時日、卜筮以疑眾，殺。","zh-Hant"]]},{"id":"li-ji_ch-5_p-54_s-5","passageId":"li-ji_ch-5_p-54","order":5,"canonicalText":"此四誅者，不以聽。","chunks":[["此四誅者，不以聽。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-1","passageId":"li-ji_ch-5_p-55","order":1,"canonicalText":"凡執禁以齊眾，不赦過。","chunks":[["凡執禁以齊眾，不赦過。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-2","passageId":"li-ji_ch-5_p-55","order":2,"canonicalText":"有圭璧金璋，不粥於市；","chunks":[["有圭璧金璋，不粥於市；","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-3","passageId":"li-ji_ch-5_p-55","order":3,"canonicalText":"命服命車，不粥於市；","chunks":[["命服命車，不粥於市；","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-4","passageId":"li-ji_ch-5_p-55","order":4,"canonicalText":"宗廟之器，不粥於市；","chunks":[["宗廟之器，不粥於市；","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-5","passageId":"li-ji_ch-5_p-55","order":5,"canonicalText":"犧牲不粥於市；","chunks":[["犧牲不粥於市；","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-6","passageId":"li-ji_ch-5_p-55","order":6,"canonicalText":"戎器不粥於市。","chunks":[["戎器不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-7","passageId":"li-ji_ch-5_p-55","order":7,"canonicalText":"用器不中度，不粥於市。","chunks":[["用器不中度，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-8","passageId":"li-ji_ch-5_p-55","order":8,"canonicalText":"兵車不中度，不粥於市。","chunks":[["兵車不中度，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-9","passageId":"li-ji_ch-5_p-55","order":9,"canonicalText":"布帛精粗不中數、幅廣狹不中量，不粥於市。","chunks":[["布帛精粗不中數、幅廣狹不中量，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-10","passageId":"li-ji_ch-5_p-55","order":10,"canonicalText":"奸色亂正色，不粥於市。","chunks":[["奸色亂正色，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-11","passageId":"li-ji_ch-5_p-55","order":11,"canonicalText":"錦文珠玉成器，不粥於市。","chunks":[["錦文珠玉成器，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-12","passageId":"li-ji_ch-5_p-55","order":12,"canonicalText":"衣服飲食，不粥於市。","chunks":[["衣服飲食，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-13","passageId":"li-ji_ch-5_p-55","order":13,"canonicalText":"五穀不時，果實未熟，不粥於市。","chunks":[["五穀不時，果實未熟，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-14","passageId":"li-ji_ch-5_p-55","order":14,"canonicalText":"木不中伐，不粥於市。","chunks":[["木不中伐，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-15","passageId":"li-ji_ch-5_p-55","order":15,"canonicalText":"禽獸魚鱉不中殺，不粥於市。","chunks":[["禽獸魚鱉不中殺，不粥於市。","zh-Hant"]]},{"id":"li-ji_ch-5_p-55_s-16","passageId":"li-ji_ch-5_p-55","order":16,"canonicalText":"關執禁以譏，禁異服，識異言。","chunks":[["關執禁以譏，禁異服，識異言。","zh-Hant"]]},{"id":"li-ji_ch-5_p-56_s-1","passageId":"li-ji_ch-5_p-56","order":1,"canonicalText":"大史典禮，執簡記，奉諱惡。","chunks":[["大史典禮，執簡記，奉諱惡。","zh-Hant"]]},{"id":"li-ji_ch-5_p-56_s-2","passageId":"li-ji_ch-5_p-56","order":2,"canonicalText":"天子齊戒受諫。","chunks":[["天子齊戒受諫。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-1","passageId":"li-ji_ch-5_p-57","order":1,"canonicalText":"司會以歲之成，質於天子，冢宰齊戒受質。","chunks":[["司會以歲之成，質於天子，冢宰齊戒受質。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-2","passageId":"li-ji_ch-5_p-57","order":2,"canonicalText":"大樂正、大司寇、市，三官以其成，從質於天子。","chunks":[["大樂正、大司寇、市，三官以其成，從質於天子。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-3","passageId":"li-ji_ch-5_p-57","order":3,"canonicalText":"大司徒、大司馬、大司空齊戒受質；","chunks":[["大司徒、大司馬、大司空齊戒受質；","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-4","passageId":"li-ji_ch-5_p-57","order":4,"canonicalText":"百官各以其成，質於三官。","chunks":[["百官各以其成，質於三官。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-5","passageId":"li-ji_ch-5_p-57","order":5,"canonicalText":"大司徒、大司馬、大司空以百官之成，質於天子。","chunks":[["大司徒、大司馬、大司空以百官之成，質於天子。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-6","passageId":"li-ji_ch-5_p-57","order":6,"canonicalText":"百官齊戒受質。","chunks":[["百官齊戒受質。","zh-Hant"]]},{"id":"li-ji_ch-5_p-57_s-7","passageId":"li-ji_ch-5_p-57","order":7,"canonicalText":"然後，休老勞農，成歲事，制國用。","chunks":[["然後，休老勞農，成歲事，制國用。","zh-Hant"]]},{"id":"li-ji_ch-5_p-58_s-1","passageId":"li-ji_ch-5_p-58","order":1,"canonicalText":"凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。","chunks":[["凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-59_s-1","passageId":"li-ji_ch-5_p-59","order":1,"canonicalText":"五十養於鄉，六十養於國，七十養於學，達於諸侯。","chunks":[["五十養於鄉，六十養於國，七十養於學，達於諸侯。","zh-Hant"]]},{"id":"li-ji_ch-5_p-59_s-2","passageId":"li-ji_ch-5_p-59","order":2,"canonicalText":"八十拜君命，一坐再至，瞽亦如之。","chunks":[["八十拜君命，一坐再至，瞽亦如之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-59_s-3","passageId":"li-ji_ch-5_p-59","order":3,"canonicalText":"九十使人受。","chunks":[["九十使人受。","zh-Hant"]]},{"id":"li-ji_ch-5_p-60_s-1","passageId":"li-ji_ch-5_p-60","order":1,"canonicalText":"五十異粻，六十宿肉，七十貳膳，八十常珍；","chunks":[["五十異粻，六十宿肉，七十貳膳，八十常珍；","zh-Hant"]]},{"id":"li-ji_ch-5_p-60_s-2","passageId":"li-ji_ch-5_p-60","order":2,"canonicalText":"九十，飲食不離寢、膳飲從於游可也。","chunks":[["九十，飲食不離寢、膳飲從於游可也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-61_s-1","passageId":"li-ji_ch-5_p-61","order":1,"canonicalText":"六十歲制，七十時制，八十月制；","chunks":[["六十歲制，七十時制，八十月制；","zh-Hant"]]},{"id":"li-ji_ch-5_p-61_s-2","passageId":"li-ji_ch-5_p-61","order":2,"canonicalText":"九十日修，唯絞、衾、冒，死而後制。","chunks":[["九十日修，唯絞、衾、冒，死而後制。","zh-Hant"]]},{"id":"li-ji_ch-5_p-62_s-1","passageId":"li-ji_ch-5_p-62","order":1,"canonicalText":"五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖；","chunks":[["五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖；","zh-Hant"]]},{"id":"li-ji_ch-5_p-62_s-2","passageId":"li-ji_ch-5_p-62","order":2,"canonicalText":"九十，雖得人不暖矣。","chunks":[["九十，雖得人不暖矣。","zh-Hant"]]},{"id":"li-ji_ch-5_p-63_s-1","passageId":"li-ji_ch-5_p-63","order":1,"canonicalText":"五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝；","chunks":[["五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝；","zh-Hant"]]},{"id":"li-ji_ch-5_p-63_s-2","passageId":"li-ji_ch-5_p-63","order":2,"canonicalText":"九十者，天子欲有問焉，則就其室，以珍從。","chunks":[["九十者，天子欲有問焉，則就其室，以珍從。","zh-Hant"]]},{"id":"li-ji_ch-5_p-64_s-1","passageId":"li-ji_ch-5_p-64","order":1,"canonicalText":"七十不俟朝，八十月告存，九十日有秩。","chunks":[["七十不俟朝，八十月告存，九十日有秩。","zh-Hant"]]},{"id":"li-ji_ch-5_p-65_s-1","passageId":"li-ji_ch-5_p-65","order":1,"canonicalText":"五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。","chunks":[["五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。","zh-Hant"]]},{"id":"li-ji_ch-5_p-66_s-1","passageId":"li-ji_ch-5_p-66","order":1,"canonicalText":"五十而爵，六十不親學，七十致政。","chunks":[["五十而爵，六十不親學，七十致政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-66_s-2","passageId":"li-ji_ch-5_p-66","order":2,"canonicalText":"唯衰麻為喪。","chunks":[["唯衰麻為喪。","zh-Hant"]]},{"id":"li-ji_ch-5_p-67_s-1","passageId":"li-ji_ch-5_p-67","order":1,"canonicalText":"有虞氏養國老於上庠，養庶老於下庠。","chunks":[["有虞氏養國老於上庠，養庶老於下庠。","zh-Hant"]]},{"id":"li-ji_ch-5_p-67_s-2","passageId":"li-ji_ch-5_p-67","order":2,"canonicalText":"夏后氏養國老於東序，養庶老於西序。","chunks":[["夏后氏養國老於東序，養庶老於西序。","zh-Hant"]]},{"id":"li-ji_ch-5_p-67_s-3","passageId":"li-ji_ch-5_p-67","order":3,"canonicalText":"殷人養國老於右學，養庶老於左學。","chunks":[["殷人養國老於右學，養庶老於左學。","zh-Hant"]]},{"id":"li-ji_ch-5_p-67_s-4","passageId":"li-ji_ch-5_p-67","order":4,"canonicalText":"周人養國老於東膠，養庶老於虞庠：虞庠在國之西郊。","chunks":[["周人養國老於東膠，養庶老於虞庠：虞庠在國之西郊。","zh-Hant"]]},{"id":"li-ji_ch-5_p-68_s-1","passageId":"li-ji_ch-5_p-68","order":1,"canonicalText":"有虞氏皇而祭，深衣而養老。","chunks":[["有虞氏皇而祭，深衣而養老。","zh-Hant"]]},{"id":"li-ji_ch-5_p-68_s-2","passageId":"li-ji_ch-5_p-68","order":2,"canonicalText":"夏后氏收而祭，燕衣而養老。","chunks":[["夏后氏收而祭，燕衣而養老。","zh-Hant"]]},{"id":"li-ji_ch-5_p-68_s-3","passageId":"li-ji_ch-5_p-68","order":3,"canonicalText":"殷人冔而祭，縞衣而養老。","chunks":[["殷人冔而祭，縞衣而養老。","zh-Hant"]]},{"id":"li-ji_ch-5_p-68_s-4","passageId":"li-ji_ch-5_p-68","order":4,"canonicalText":"周人冕而祭，玄衣而養老。","chunks":[["周人冕而祭，玄衣而養老。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-1","passageId":"li-ji_ch-5_p-69","order":1,"canonicalText":"凡三王養老皆引年。","chunks":[["凡三王養老皆引年。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-2","passageId":"li-ji_ch-5_p-69","order":2,"canonicalText":"八十者一子不從政，九十者其家不從政，廢疾非人不養者一人不從政。","chunks":[["八十者一子不從政，九十者其家不從政，廢疾非人不養者一人不從政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-3","passageId":"li-ji_ch-5_p-69","order":3,"canonicalText":"父母之喪，三年不從政。","chunks":[["父母之喪，三年不從政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-4","passageId":"li-ji_ch-5_p-69","order":4,"canonicalText":"齊衰、大功之喪，三月不從政。","chunks":[["齊衰、大功之喪，三月不從政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-5","passageId":"li-ji_ch-5_p-69","order":5,"canonicalText":"將徙於諸侯，三月不從政。","chunks":[["將徙於諸侯，三月不從政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-69_s-6","passageId":"li-ji_ch-5_p-69","order":6,"canonicalText":"自諸侯來徙家，期不從政。","chunks":[["自諸侯來徙家，期不從政。","zh-Hant"]]},{"id":"li-ji_ch-5_p-70_s-1","passageId":"li-ji_ch-5_p-70","order":1,"canonicalText":"少而無父者謂之孤，老而無子者謂之獨，老而無妻者謂之矜，老而無夫者謂之寡。","chunks":[["少而無父者謂之孤，老而無子者謂之獨，老而無妻者謂之矜，老而無夫者謂之寡。","zh-Hant"]]},{"id":"li-ji_ch-5_p-70_s-2","passageId":"li-ji_ch-5_p-70","order":2,"canonicalText":"此四者，天民之窮而無告者也，皆有常餼。","chunks":[["此四者，天民之窮而無告者也，皆有常餼。","zh-Hant"]]},{"id":"li-ji_ch-5_p-71_s-1","passageId":"li-ji_ch-5_p-71","order":1,"canonicalText":"瘖、聾、跛、躃、斷者、侏儒、百工，各以其器食之。","chunks":[["瘖、聾、跛、躃、斷者、侏儒、百工，各以其器食之。","zh-Hant"]]},{"id":"li-ji_ch-5_p-72_s-1","passageId":"li-ji_ch-5_p-72","order":1,"canonicalText":"道路：男子由右，婦人由左，車從中央。","chunks":[["道路：男子由右，婦人由左，車從中央。","zh-Hant"]]},{"id":"li-ji_ch-5_p-72_s-2","passageId":"li-ji_ch-5_p-72","order":2,"canonicalText":"父之齒隨行，兄之齒雁行，朋友不相逾。","chunks":[["父之齒隨行，兄之齒雁行，朋友不相逾。","zh-Hant"]]},{"id":"li-ji_ch-5_p-72_s-3","passageId":"li-ji_ch-5_p-72","order":3,"canonicalText":"輕任并，重任分，斑白者不提挈。","chunks":[["輕任并，重任分，斑白者不提挈。","zh-Hant"]]},{"id":"li-ji_ch-5_p-72_s-4","passageId":"li-ji_ch-5_p-72","order":4,"canonicalText":"君子耆老不徒行，庶人耆老不徒食。","chunks":[["君子耆老不徒行，庶人耆老不徒食。","zh-Hant"]]},{"id":"li-ji_ch-5_p-73_s-1","passageId":"li-ji_ch-5_p-73","order":1,"canonicalText":"大夫祭器不假。","chunks":[["大夫祭器不假。","zh-Hant"]]},{"id":"li-ji_ch-5_p-73_s-2","passageId":"li-ji_ch-5_p-73","order":2,"canonicalText":"祭器未成，不造燕器。","chunks":[["祭器未成，不造燕器。","zh-Hant"]]},{"id":"li-ji_ch-5_p-74_s-1","passageId":"li-ji_ch-5_p-74","order":1,"canonicalText":"方一里者為田九百畝。","chunks":[["方一里者為田九百畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-74_s-2","passageId":"li-ji_ch-5_p-74","order":2,"canonicalText":"方十里者，為方一里者百，為田九萬畝。","chunks":[["方十里者，為方一里者百，為田九萬畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-74_s-3","passageId":"li-ji_ch-5_p-74","order":3,"canonicalText":"方百里者，為方十里者百，為田九十億畝。","chunks":[["方百里者，為方十里者百，為田九十億畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-74_s-4","passageId":"li-ji_ch-5_p-74","order":4,"canonicalText":"方千里者，為方百里者百，為田九萬億畝。","chunks":[["方千里者，為方百里者百，為田九萬億畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-1","passageId":"li-ji_ch-5_p-75","order":1,"canonicalText":"自恒山至於南河，千里而近；","chunks":[["自恒山至於南河，千里而近；","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-2","passageId":"li-ji_ch-5_p-75","order":2,"canonicalText":"自南河至於江，千里而近。","chunks":[["自南河至於江，千里而近。","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-3","passageId":"li-ji_ch-5_p-75","order":3,"canonicalText":"自江至於衡山，千里而遙；","chunks":[["自江至於衡山，千里而遙；","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-4","passageId":"li-ji_ch-5_p-75","order":4,"canonicalText":"自東河至於東海，千里而遙。","chunks":[["自東河至於東海，千里而遙。","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-5","passageId":"li-ji_ch-5_p-75","order":5,"canonicalText":"自東河至於西河，千里而近；","chunks":[["自東河至於西河，千里而近；","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-6","passageId":"li-ji_ch-5_p-75","order":6,"canonicalText":"自西河至於流沙，千里而遙。","chunks":[["自西河至於流沙，千里而遙。","zh-Hant"]]},{"id":"li-ji_ch-5_p-75_s-7","passageId":"li-ji_ch-5_p-75","order":7,"canonicalText":"西不盡流沙，南不盡衡山，東不近東海，北不盡恒山，凡四海之內，斷長補短，方三千里，為田八十萬億一萬億畝。","chunks":[["西不盡流沙，南不盡衡山，東不近東海，北不盡恒山，凡四海之內，斷長補短，方三千里，為田八十萬億一萬億畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-76_s-1","passageId":"li-ji_ch-5_p-76","order":1,"canonicalText":"方百里者為田九十億畝：山陵、林麓、川澤、溝瀆、城郭、宮室、涂巷，三分去一，其餘六十億畝。","chunks":[["方百里者為田九十億畝：山陵、林麓、川澤、溝瀆、城郭、宮室、涂巷，三分去一，其餘六十億畝。","zh-Hant"]]},{"id":"li-ji_ch-5_p-77_s-1","passageId":"li-ji_ch-5_p-77","order":1,"canonicalText":"古者以周尺八尺為步，今以周尺六尺四寸為步。","chunks":[["古者以周尺八尺為步，今以周尺六尺四寸為步。","zh-Hant"]]},{"id":"li-ji_ch-5_p-77_s-2","passageId":"li-ji_ch-5_p-77","order":2,"canonicalText":"古者百畝，當今東田百四十六畝三十步。","chunks":[["古者百畝，當今東田百四十六畝三十步。","zh-Hant"]]},{"id":"li-ji_ch-5_p-77_s-3","passageId":"li-ji_ch-5_p-77","order":3,"canonicalText":"古者百里，當今百二十一里六十步四尺二寸二分。","chunks":[["古者百里，當今百二十一里六十步四尺二寸二分。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-1","passageId":"li-ji_ch-5_p-78","order":1,"canonicalText":"方千里者，為方百里者百。","chunks":[["方千里者，為方百里者百。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-2","passageId":"li-ji_ch-5_p-78","order":2,"canonicalText":"封方百里者三十國，其餘，方百里者七十。","chunks":[["封方百里者三十國，其餘，方百里者七十。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-3","passageId":"li-ji_ch-5_p-78","order":3,"canonicalText":"又封方七十里者六十，為方百里者二十九，方十里者四十。","chunks":[["又封方七十里者六十，為方百里者二十九，方十里者四十。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-4","passageId":"li-ji_ch-5_p-78","order":4,"canonicalText":"其餘，方百里者四十，方十里者六十；","chunks":[["其餘，方百里者四十，方十里者六十；","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-5","passageId":"li-ji_ch-5_p-78","order":5,"canonicalText":"又封方五十里者二十，為方百里者三十；","chunks":[["又封方五十里者二十，為方百里者三十；","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-6","passageId":"li-ji_ch-5_p-78","order":6,"canonicalText":"其餘，方百里者十，方十里者六十。","chunks":[["其餘，方百里者十，方十里者六十。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-7","passageId":"li-ji_ch-5_p-78","order":7,"canonicalText":"名山大澤不以封，其餘以為附庸間田。","chunks":[["名山大澤不以封，其餘以為附庸間田。","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-8","passageId":"li-ji_ch-5_p-78","order":8,"canonicalText":"諸侯之有功者，取於間田以祿之；","chunks":[["諸侯之有功者，取於間田以祿之；","zh-Hant"]]},{"id":"li-ji_ch-5_p-78_s-9","passageId":"li-ji_ch-5_p-78","order":9,"canonicalText":"其有削地者，歸之間田。","chunks":[["其有削地者，歸之間田。","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-1","passageId":"li-ji_ch-5_p-79","order":1,"canonicalText":"天子之縣內：方千里者為方百里者百。","chunks":[["天子之縣內：方千里者為方百里者百。","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-2","passageId":"li-ji_ch-5_p-79","order":2,"canonicalText":"封方百里者九，其餘方百里者九十一。","chunks":[["封方百里者九，其餘方百里者九十一。","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-3","passageId":"li-ji_ch-5_p-79","order":3,"canonicalText":"又封方七十里者二十一，為方百里者十，方十里者二十九；","chunks":[["又封方七十里者二十一，為方百里者十，方十里者二十九；","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-4","passageId":"li-ji_ch-5_p-79","order":4,"canonicalText":"其餘，方百里者八十，方十里者七十一。","chunks":[["其餘，方百里者八十，方十里者七十一。","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-5","passageId":"li-ji_ch-5_p-79","order":5,"canonicalText":"又封方五十里者六十三，為方百里者十五，方十里者七十五；","chunks":[["又封方五十里者六十三，為方百里者十五，方十里者七十五；","zh-Hant"]]},{"id":"li-ji_ch-5_p-79_s-6","passageId":"li-ji_ch-5_p-79","order":6,"canonicalText":"其餘方百里者六十四，方十里者九十六。","chunks":[["其餘方百里者六十四，方十里者九十六。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-1","passageId":"li-ji_ch-5_p-80","order":1,"canonicalText":"諸侯之下士祿食九人，中士食十八人，上士食三十六人。","chunks":[["諸侯之下士祿食九人，中士食十八人，上士食三十六人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-2","passageId":"li-ji_ch-5_p-80","order":2,"canonicalText":"下大夫食七十二人，卿食二百八十八人。","chunks":[["下大夫食七十二人，卿食二百八十八人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-3","passageId":"li-ji_ch-5_p-80","order":3,"canonicalText":"君食二千八百八十人。","chunks":[["君食二千八百八十人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-4","passageId":"li-ji_ch-5_p-80","order":4,"canonicalText":"次國之卿食二百一十六人，君食二千一百六十人。","chunks":[["次國之卿食二百一十六人，君食二千一百六十人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-5","passageId":"li-ji_ch-5_p-80","order":5,"canonicalText":"小國之卿食百四十四人，君食千四百四十人。","chunks":[["小國之卿食百四十四人，君食千四百四十人。","zh-Hant"]]},{"id":"li-ji_ch-5_p-80_s-6","passageId":"li-ji_ch-5_p-80","order":6,"canonicalText":"次國之卿，命於其君者，如小國之卿。","chunks":[["次國之卿，命於其君者，如小國之卿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-81_s-1","passageId":"li-ji_ch-5_p-81","order":1,"canonicalText":"天子之大夫為三監，監於諸侯之國者，其祿視諸侯之卿，其爵視次國之君，其祿取之於方伯之地。","chunks":[["天子之大夫為三監，監於諸侯之國者，其祿視諸侯之卿，其爵視次國之君，其祿取之於方伯之地。","zh-Hant"]]},{"id":"li-ji_ch-5_p-81_s-2","passageId":"li-ji_ch-5_p-81","order":2,"canonicalText":"方伯為朝天子，皆有湯沐之邑於天子之縣內，視元士。","chunks":[["方伯為朝天子，皆有湯沐之邑於天子之縣內，視元士。","zh-Hant"]]},{"id":"li-ji_ch-5_p-82_s-1","passageId":"li-ji_ch-5_p-82","order":1,"canonicalText":"諸侯世子世國，大夫不世爵。","chunks":[["諸侯世子世國，大夫不世爵。","zh-Hant"]]},{"id":"li-ji_ch-5_p-82_s-2","passageId":"li-ji_ch-5_p-82","order":2,"canonicalText":"使以德，爵以功，未賜爵，視天子之元士，以君其國。","chunks":[["使以德，爵以功，未賜爵，視天子之元士，以君其國。","zh-Hant"]]},{"id":"li-ji_ch-5_p-82_s-3","passageId":"li-ji_ch-5_p-82","order":3,"canonicalText":"諸侯之大夫，不世爵祿。","chunks":[["諸侯之大夫，不世爵祿。","zh-Hant"]]},{"id":"li-ji_ch-5_p-83_s-1","passageId":"li-ji_ch-5_p-83","order":1,"canonicalText":"六禮：冠、昏、喪、祭、鄉、相見。","chunks":[["六禮：冠、昏、喪、祭、鄉、相見。","zh-Hant"]]},{"id":"li-ji_ch-5_p-83_s-2","passageId":"li-ji_ch-5_p-83","order":2,"canonicalText":"七教：父子、兄弟、夫婦、君臣、長幼、朋友、賓客。","chunks":[["七教：父子、兄弟、夫婦、君臣、長幼、朋友、賓客。","zh-Hant"]]},{"id":"li-ji_ch-5_p-83_s-3","passageId":"li-ji_ch-5_p-83","order":3,"canonicalText":"八政：飲食、衣服、事為、異別、度、量、數、制。","chunks":[["八政：飲食、衣服、事為、異別、度、量、數、制。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-1","passageId":"li-ji_ch-6_p-1","order":1,"canonicalText":"孟春之月，日在營室，昏參中，旦尾中。","chunks":[["孟春之月，日在營室，昏參中，旦尾中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-2","passageId":"li-ji_ch-6_p-1","order":2,"canonicalText":"其日甲乙。","chunks":[["其日甲乙。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-3","passageId":"li-ji_ch-6_p-1","order":3,"canonicalText":"其帝大皞，其神句芒。","chunks":[["其帝大皞，其神句芒。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-4","passageId":"li-ji_ch-6_p-1","order":4,"canonicalText":"其蟲鱗。","chunks":[["其蟲鱗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-5","passageId":"li-ji_ch-6_p-1","order":5,"canonicalText":"其音角，律中大蔟。","chunks":[["其音角，律中大蔟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-6","passageId":"li-ji_ch-6_p-1","order":6,"canonicalText":"其數八。","chunks":[["其數八。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-7","passageId":"li-ji_ch-6_p-1","order":7,"canonicalText":"其味酸，其臭膻。","chunks":[["其味酸，其臭膻。","zh-Hant"]]},{"id":"li-ji_ch-6_p-1_s-8","passageId":"li-ji_ch-6_p-1","order":8,"canonicalText":"其祀戶，祭先脾。","chunks":[["其祀戶，祭先脾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-2_s-1","passageId":"li-ji_ch-6_p-2","order":1,"canonicalText":"東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來。","chunks":[["東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來。","zh-Hant"]]},{"id":"li-ji_ch-6_p-3_s-1","passageId":"li-ji_ch-6_p-3","order":1,"canonicalText":"天子居青陽左个。","chunks":[["天子居青陽左个。","zh-Hant"]]},{"id":"li-ji_ch-6_p-3_s-2","passageId":"li-ji_ch-6_p-3","order":2,"canonicalText":"乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","chunks":[["乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-1","passageId":"li-ji_ch-6_p-4","order":1,"canonicalText":"是月也，以立春。","chunks":[["是月也，以立春。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-2","passageId":"li-ji_ch-6_p-4","order":2,"canonicalText":"先立春三日，大史謁之天子曰：某日立春，盛德在木。","chunks":[["先立春三日，大史謁之天子曰：某日立春，盛德在木。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-3","passageId":"li-ji_ch-6_p-4","order":3,"canonicalText":"天子乃齊。","chunks":[["天子乃齊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-4","passageId":"li-ji_ch-6_p-4","order":4,"canonicalText":"立春之日，天子親帥三公、九卿、諸侯、大夫以迎春於東郊。","chunks":[["立春之日，天子親帥三公、九卿、諸侯、大夫以迎春於東郊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-5","passageId":"li-ji_ch-6_p-4","order":5,"canonicalText":"還反，賞公卿、諸侯、大夫於朝。","chunks":[["還反，賞公卿、諸侯、大夫於朝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-6","passageId":"li-ji_ch-6_p-4","order":6,"canonicalText":"命相布德和令，行慶施惠，下及兆民。","chunks":[["命相布德和令，行慶施惠，下及兆民。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-7","passageId":"li-ji_ch-6_p-4","order":7,"canonicalText":"慶賜遂行，毋有不當。","chunks":[["慶賜遂行，毋有不當。","zh-Hant"]]},{"id":"li-ji_ch-6_p-4_s-8","passageId":"li-ji_ch-6_p-4","order":8,"canonicalText":"乃命大史守典奉法，司天日月星辰之行，宿離不貸，毋失經紀，以初為常。","chunks":[["乃命大史守典奉法，司天日月星辰之行，宿離不貸，毋失經紀，以初為常。","zh-Hant"]]},{"id":"li-ji_ch-6_p-5_s-1","passageId":"li-ji_ch-6_p-5","order":1,"canonicalText":"是月也，天子乃以元日祈穀于上帝。","chunks":[["是月也，天子乃以元日祈穀于上帝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-5_s-2","passageId":"li-ji_ch-6_p-5","order":2,"canonicalText":"乃擇元辰，天子親載耒耜，措之參保介之御間，帥三公、九卿、諸侯、大夫，躬耕帝藉。","chunks":[["乃擇元辰，天子親載耒耜，措之參保介之御間，帥三公、九卿、諸侯、大夫，躬耕帝藉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-5_s-3","passageId":"li-ji_ch-6_p-5","order":3,"canonicalText":"天子三推，三公五推，卿諸侯九推。","chunks":[["天子三推，三公五推，卿諸侯九推。","zh-Hant"]]},{"id":"li-ji_ch-6_p-5_s-4","passageId":"li-ji_ch-6_p-5","order":4,"canonicalText":"反，執爵于大寢，三公、九卿、諸侯、大夫皆御，命曰：勞酒。","chunks":[["反，執爵于大寢，三公、九卿、諸侯、大夫皆御，命曰：勞酒。","zh-Hant"]]},{"id":"li-ji_ch-6_p-6_s-1","passageId":"li-ji_ch-6_p-6","order":1,"canonicalText":"是月也，天氣下降，地氣上騰，天地和同，草木萌動。","chunks":[["是月也，天氣下降，地氣上騰，天地和同，草木萌動。","zh-Hant"]]},{"id":"li-ji_ch-6_p-6_s-2","passageId":"li-ji_ch-6_p-6","order":2,"canonicalText":"王命布農事，命田舍東郊，皆修封疆，審端經術。","chunks":[["王命布農事，命田舍東郊，皆修封疆，審端經術。","zh-Hant"]]},{"id":"li-ji_ch-6_p-6_s-3","passageId":"li-ji_ch-6_p-6","order":3,"canonicalText":"善相丘陵阪險原隰土地所宜，五穀所殖，以教道民，必躬親之。","chunks":[["善相丘陵阪險原隰土地所宜，五穀所殖，以教道民，必躬親之。","zh-Hant"]]},{"id":"li-ji_ch-6_p-6_s-4","passageId":"li-ji_ch-6_p-6","order":4,"canonicalText":"田事既飭，先定準直，農乃不惑。","chunks":[["田事既飭，先定準直，農乃不惑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-1","passageId":"li-ji_ch-6_p-7","order":1,"canonicalText":"是月也，命樂正入學習舞。","chunks":[["是月也，命樂正入學習舞。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-2","passageId":"li-ji_ch-6_p-7","order":2,"canonicalText":"乃修祭典。","chunks":[["乃修祭典。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-3","passageId":"li-ji_ch-6_p-7","order":3,"canonicalText":"命祀山林川澤，犧牲毋用牝。","chunks":[["命祀山林川澤，犧牲毋用牝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-4","passageId":"li-ji_ch-6_p-7","order":4,"canonicalText":"禁止伐木。","chunks":[["禁止伐木。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-5","passageId":"li-ji_ch-6_p-7","order":5,"canonicalText":"毋覆巢，毋殺孩蟲、胎、夭、飛鳥。","chunks":[["毋覆巢，毋殺孩蟲、胎、夭、飛鳥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-6","passageId":"li-ji_ch-6_p-7","order":6,"canonicalText":"毋麑，毋卵。","chunks":[["毋麑，毋卵。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-7","passageId":"li-ji_ch-6_p-7","order":7,"canonicalText":"毋聚大眾，毋置城郭。","chunks":[["毋聚大眾，毋置城郭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-7_s-8","passageId":"li-ji_ch-6_p-7","order":8,"canonicalText":"掩骼埋胔。","chunks":[["掩骼埋胔。","zh-Hant"]]},{"id":"li-ji_ch-6_p-8_s-1","passageId":"li-ji_ch-6_p-8","order":1,"canonicalText":"是月也，不可以稱兵，稱兵必天殃。","chunks":[["是月也，不可以稱兵，稱兵必天殃。","zh-Hant"]]},{"id":"li-ji_ch-6_p-8_s-2","passageId":"li-ji_ch-6_p-8","order":2,"canonicalText":"兵戎不起，不可從我始。","chunks":[["兵戎不起，不可從我始。","zh-Hant"]]},{"id":"li-ji_ch-6_p-8_s-3","passageId":"li-ji_ch-6_p-8","order":3,"canonicalText":"毋變天之道，毋絕地之理，毋亂人之紀。","chunks":[["毋變天之道，毋絕地之理，毋亂人之紀。","zh-Hant"]]},{"id":"li-ji_ch-6_p-9_s-1","passageId":"li-ji_ch-6_p-9","order":1,"canonicalText":"孟春行夏令，則雨水不時，草木蚤落，國時有恐。","chunks":[["孟春行夏令，則雨水不時，草木蚤落，國時有恐。","zh-Hant"]]},{"id":"li-ji_ch-6_p-9_s-2","passageId":"li-ji_ch-6_p-9","order":2,"canonicalText":"行秋令則其民大疫，猋風暴雨總至，藜莠蓬蒿并興。","chunks":[["行秋令則其民大疫，猋風暴雨總至，藜莠蓬蒿并興。","zh-Hant"]]},{"id":"li-ji_ch-6_p-9_s-3","passageId":"li-ji_ch-6_p-9","order":3,"canonicalText":"行冬令則水潦為敗，雪霜大摯，首種不入。","chunks":[["行冬令則水潦為敗，雪霜大摯，首種不入。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-1","passageId":"li-ji_ch-6_p-10","order":1,"canonicalText":"仲春之月，日在奎，昏弧中，旦建星中。","chunks":[["仲春之月，日在奎，昏弧中，旦建星中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-2","passageId":"li-ji_ch-6_p-10","order":2,"canonicalText":"其日甲乙，其帝大皞，其神句芒。","chunks":[["其日甲乙，其帝大皞，其神句芒。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-3","passageId":"li-ji_ch-6_p-10","order":3,"canonicalText":"其蟲鱗。","chunks":[["其蟲鱗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-4","passageId":"li-ji_ch-6_p-10","order":4,"canonicalText":"其音角，律中夾鐘。","chunks":[["其音角，律中夾鐘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-5","passageId":"li-ji_ch-6_p-10","order":5,"canonicalText":"其數八。","chunks":[["其數八。","zh-Hant"]]},{"id":"li-ji_ch-6_p-10_s-6","passageId":"li-ji_ch-6_p-10","order":6,"canonicalText":"其味酸，其臭膻，其祀戶，祭先脾。","chunks":[["其味酸，其臭膻，其祀戶，祭先脾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-11_s-1","passageId":"li-ji_ch-6_p-11","order":1,"canonicalText":"始雨水，桃始華，倉庚鳴，鷹化為鳩。","chunks":[["始雨水，桃始華，倉庚鳴，鷹化為鳩。","zh-Hant"]]},{"id":"li-ji_ch-6_p-12_s-1","passageId":"li-ji_ch-6_p-12","order":1,"canonicalText":"天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","chunks":[["天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","zh-Hant"]]},{"id":"li-ji_ch-6_p-13_s-1","passageId":"li-ji_ch-6_p-13","order":1,"canonicalText":"是月也，安萌芽，養幼少，存諸孤。","chunks":[["是月也，安萌芽，養幼少，存諸孤。","zh-Hant"]]},{"id":"li-ji_ch-6_p-13_s-2","passageId":"li-ji_ch-6_p-13","order":2,"canonicalText":"擇元日，命民社。","chunks":[["擇元日，命民社。","zh-Hant"]]},{"id":"li-ji_ch-6_p-13_s-3","passageId":"li-ji_ch-6_p-13","order":3,"canonicalText":"命有司省囹圄，去桎梏，毋肆掠，止獄訟。","chunks":[["命有司省囹圄，去桎梏，毋肆掠，止獄訟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-14_s-1","passageId":"li-ji_ch-6_p-14","order":1,"canonicalText":"是月也，玄鳥至。","chunks":[["是月也，玄鳥至。","zh-Hant"]]},{"id":"li-ji_ch-6_p-14_s-2","passageId":"li-ji_ch-6_p-14","order":2,"canonicalText":"至之日，以大牢祠于高禖。","chunks":[["至之日，以大牢祠于高禖。","zh-Hant"]]},{"id":"li-ji_ch-6_p-14_s-3","passageId":"li-ji_ch-6_p-14","order":3,"canonicalText":"天子親往，后妃帥九嬪御。","chunks":[["天子親往，后妃帥九嬪御。","zh-Hant"]]},{"id":"li-ji_ch-6_p-14_s-4","passageId":"li-ji_ch-6_p-14","order":4,"canonicalText":"乃禮天子所御，帶以弓韣，授以弓矢，于高禖之前。","chunks":[["乃禮天子所御，帶以弓韣，授以弓矢，于高禖之前。","zh-Hant"]]},{"id":"li-ji_ch-6_p-15_s-1","passageId":"li-ji_ch-6_p-15","order":1,"canonicalText":"是月也，日夜分。","chunks":[["是月也，日夜分。","zh-Hant"]]},{"id":"li-ji_ch-6_p-15_s-2","passageId":"li-ji_ch-6_p-15","order":2,"canonicalText":"雷乃發聲，始電，蟄蟲咸動，啟戶始出。","chunks":[["雷乃發聲，始電，蟄蟲咸動，啟戶始出。","zh-Hant"]]},{"id":"li-ji_ch-6_p-15_s-3","passageId":"li-ji_ch-6_p-15","order":3,"canonicalText":"先雷三日，奮木鐸以令兆民曰：雷將發聲，有不戒其容止者，生子不備，必有凶災。","chunks":[["先雷三日，奮木鐸以令兆民曰：雷將發聲，有不戒其容止者，生子不備，必有凶災。","zh-Hant"]]},{"id":"li-ji_ch-6_p-15_s-4","passageId":"li-ji_ch-6_p-15","order":4,"canonicalText":"日夜分，則同度量，鈞衡石，角斗甬，正權概。","chunks":[["日夜分，則同度量，鈞衡石，角斗甬，正權概。","zh-Hant"]]},{"id":"li-ji_ch-6_p-16_s-1","passageId":"li-ji_ch-6_p-16","order":1,"canonicalText":"是月也，耕者少舍。","chunks":[["是月也，耕者少舍。","zh-Hant"]]},{"id":"li-ji_ch-6_p-16_s-2","passageId":"li-ji_ch-6_p-16","order":2,"canonicalText":"乃修闔扇，寢廟畢備。","chunks":[["乃修闔扇，寢廟畢備。","zh-Hant"]]},{"id":"li-ji_ch-6_p-16_s-3","passageId":"li-ji_ch-6_p-16","order":3,"canonicalText":"毋作大事，以妨農之事。","chunks":[["毋作大事，以妨農之事。","zh-Hant"]]},{"id":"li-ji_ch-6_p-17_s-1","passageId":"li-ji_ch-6_p-17","order":1,"canonicalText":"是月也，毋竭川澤，毋漉陂池，毋焚山林。","chunks":[["是月也，毋竭川澤，毋漉陂池，毋焚山林。","zh-Hant"]]},{"id":"li-ji_ch-6_p-17_s-2","passageId":"li-ji_ch-6_p-17","order":2,"canonicalText":"天子乃鮮羔開冰，先薦寢廟。","chunks":[["天子乃鮮羔開冰，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-17_s-3","passageId":"li-ji_ch-6_p-17","order":3,"canonicalText":"上丁，命樂正習舞，釋菜。","chunks":[["上丁，命樂正習舞，釋菜。","zh-Hant"]]},{"id":"li-ji_ch-6_p-17_s-4","passageId":"li-ji_ch-6_p-17","order":4,"canonicalText":"天子乃帥三公、九卿、諸侯、大夫親往視之。","chunks":[["天子乃帥三公、九卿、諸侯、大夫親往視之。","zh-Hant"]]},{"id":"li-ji_ch-6_p-17_s-5","passageId":"li-ji_ch-6_p-17","order":5,"canonicalText":"仲丁，又命樂正入學習舞。","chunks":[["仲丁，又命樂正入學習舞。","zh-Hant"]]},{"id":"li-ji_ch-6_p-18_s-1","passageId":"li-ji_ch-6_p-18","order":1,"canonicalText":"是月也，祀不用犧牲，用圭璧，更皮幣。","chunks":[["是月也，祀不用犧牲，用圭璧，更皮幣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-19_s-1","passageId":"li-ji_ch-6_p-19","order":1,"canonicalText":"仲春行秋令，則其國大水，寒氣總至，寇戎來征。","chunks":[["仲春行秋令，則其國大水，寒氣總至，寇戎來征。","zh-Hant"]]},{"id":"li-ji_ch-6_p-19_s-2","passageId":"li-ji_ch-6_p-19","order":2,"canonicalText":"行冬令，則陽氣不勝，麥乃不熟，民多相掠。","chunks":[["行冬令，則陽氣不勝，麥乃不熟，民多相掠。","zh-Hant"]]},{"id":"li-ji_ch-6_p-19_s-3","passageId":"li-ji_ch-6_p-19","order":3,"canonicalText":"行夏令，則國乃大旱，暖氣早來，蟲螟為害。","chunks":[["行夏令，則國乃大旱，暖氣早來，蟲螟為害。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-1","passageId":"li-ji_ch-6_p-20","order":1,"canonicalText":"季春之月，日在胃，昏七星中，旦牽牛中。","chunks":[["季春之月，日在胃，昏七星中，旦牽牛中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-2","passageId":"li-ji_ch-6_p-20","order":2,"canonicalText":"其日甲乙。","chunks":[["其日甲乙。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-3","passageId":"li-ji_ch-6_p-20","order":3,"canonicalText":"其帝大皞，其神句芒。","chunks":[["其帝大皞，其神句芒。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-4","passageId":"li-ji_ch-6_p-20","order":4,"canonicalText":"其蟲鱗。","chunks":[["其蟲鱗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-5","passageId":"li-ji_ch-6_p-20","order":5,"canonicalText":"其音角，律中姑洗。","chunks":[["其音角，律中姑洗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-6","passageId":"li-ji_ch-6_p-20","order":6,"canonicalText":"其數八。","chunks":[["其數八。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-7","passageId":"li-ji_ch-6_p-20","order":7,"canonicalText":"其味酸，其臭膻。","chunks":[["其味酸，其臭膻。","zh-Hant"]]},{"id":"li-ji_ch-6_p-20_s-8","passageId":"li-ji_ch-6_p-20","order":8,"canonicalText":"其祀戶，祭先脾。","chunks":[["其祀戶，祭先脾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-21_s-1","passageId":"li-ji_ch-6_p-21","order":1,"canonicalText":"桐始華，田鼠化為鴽，虹始見，萍始生。","chunks":[["桐始華，田鼠化為鴽，虹始見，萍始生。","zh-Hant"]]},{"id":"li-ji_ch-6_p-22_s-1","passageId":"li-ji_ch-6_p-22","order":1,"canonicalText":"天子居青陽右个，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉。","chunks":[["天子居青陽右个，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-22_s-2","passageId":"li-ji_ch-6_p-22","order":2,"canonicalText":"食麥與羊，其器疏以達。","chunks":[["食麥與羊，其器疏以達。","zh-Hant"]]},{"id":"li-ji_ch-6_p-23_s-1","passageId":"li-ji_ch-6_p-23","order":1,"canonicalText":"是月也，天子乃薦鞠衣于先帝。","chunks":[["是月也，天子乃薦鞠衣于先帝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-23_s-2","passageId":"li-ji_ch-6_p-23","order":2,"canonicalText":"命舟牧覆舟，五覆五反。","chunks":[["命舟牧覆舟，五覆五反。","zh-Hant"]]},{"id":"li-ji_ch-6_p-23_s-3","passageId":"li-ji_ch-6_p-23","order":3,"canonicalText":"乃告舟備具於天子焉，天子始乘舟。","chunks":[["乃告舟備具於天子焉，天子始乘舟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-23_s-4","passageId":"li-ji_ch-6_p-23","order":4,"canonicalText":"薦鮪于寢廟，乃為麥祈實。","chunks":[["薦鮪于寢廟，乃為麥祈實。","zh-Hant"]]},{"id":"li-ji_ch-6_p-24_s-1","passageId":"li-ji_ch-6_p-24","order":1,"canonicalText":"是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達。","chunks":[["是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達。","zh-Hant"]]},{"id":"li-ji_ch-6_p-24_s-2","passageId":"li-ji_ch-6_p-24","order":2,"canonicalText":"不可以內。","chunks":[["不可以內。","zh-Hant"]]},{"id":"li-ji_ch-6_p-24_s-3","passageId":"li-ji_ch-6_p-24","order":3,"canonicalText":"天子布德行惠，命有司發倉廩，賜貧窮，振乏絕，開府庫，出幣帛，周天下。","chunks":[["天子布德行惠，命有司發倉廩，賜貧窮，振乏絕，開府庫，出幣帛，周天下。","zh-Hant"]]},{"id":"li-ji_ch-6_p-24_s-4","passageId":"li-ji_ch-6_p-24","order":4,"canonicalText":"勉諸侯，聘名士，禮賢者。","chunks":[["勉諸侯，聘名士，禮賢者。","zh-Hant"]]},{"id":"li-ji_ch-6_p-25_s-1","passageId":"li-ji_ch-6_p-25","order":1,"canonicalText":"是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視原野，修利堤防，道達溝瀆，開通道路，毋有障塞。","chunks":[["是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視原野，修利堤防，道達溝瀆，開通道路，毋有障塞。","zh-Hant"]]},{"id":"li-ji_ch-6_p-25_s-2","passageId":"li-ji_ch-6_p-25","order":2,"canonicalText":"田獵罝罘、羅網、畢翳、餧獸之藥，毋出九門。","chunks":[["田獵罝罘、羅網、畢翳、餧獸之藥，毋出九門。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-1","passageId":"li-ji_ch-6_p-26","order":1,"canonicalText":"是月也，命野虞毋伐桑柘。","chunks":[["是月也，命野虞毋伐桑柘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-2","passageId":"li-ji_ch-6_p-26","order":2,"canonicalText":"鳴鳩拂其羽，戴勝降於桑。","chunks":[["鳴鳩拂其羽，戴勝降於桑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-3","passageId":"li-ji_ch-6_p-26","order":3,"canonicalText":"具曲植籧筐。","chunks":[["具曲植籧筐。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-4","passageId":"li-ji_ch-6_p-26","order":4,"canonicalText":"后妃齊戒，親東鄉躬桑。","chunks":[["后妃齊戒，親東鄉躬桑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-5","passageId":"li-ji_ch-6_p-26","order":5,"canonicalText":"禁婦女毋觀，省婦使以勸蠶事。","chunks":[["禁婦女毋觀，省婦使以勸蠶事。","zh-Hant"]]},{"id":"li-ji_ch-6_p-26_s-6","passageId":"li-ji_ch-6_p-26","order":6,"canonicalText":"蠶事既登，分繭稱絲效功，以共郊廟之服，無有敢惰。","chunks":[["蠶事既登，分繭稱絲效功，以共郊廟之服，無有敢惰。","zh-Hant"]]},{"id":"li-ji_ch-6_p-27_s-1","passageId":"li-ji_ch-6_p-27","order":1,"canonicalText":"是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，羽箭干，脂膠丹漆，毋或不良。","chunks":[["是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，羽箭干，脂膠丹漆，毋或不良。","zh-Hant"]]},{"id":"li-ji_ch-6_p-27_s-2","passageId":"li-ji_ch-6_p-27","order":2,"canonicalText":"百工咸理，監工日號；","chunks":[["百工咸理，監工日號；","zh-Hant"]]},{"id":"li-ji_ch-6_p-27_s-3","passageId":"li-ji_ch-6_p-27","order":3,"canonicalText":"毋悖于時，毋或作為淫巧以蕩上心。","chunks":[["毋悖于時，毋或作為淫巧以蕩上心。","zh-Hant"]]},{"id":"li-ji_ch-6_p-28_s-1","passageId":"li-ji_ch-6_p-28","order":1,"canonicalText":"是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、大夫親往視之。","chunks":[["是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、大夫親往視之。","zh-Hant"]]},{"id":"li-ji_ch-6_p-29_s-1","passageId":"li-ji_ch-6_p-29","order":1,"canonicalText":"是月也，乃合累牛騰馬，游牝於牧。","chunks":[["是月也，乃合累牛騰馬，游牝於牧。","zh-Hant"]]},{"id":"li-ji_ch-6_p-29_s-2","passageId":"li-ji_ch-6_p-29","order":2,"canonicalText":"犧牲駒犢，舉，書其數。","chunks":[["犧牲駒犢，舉，書其數。","zh-Hant"]]},{"id":"li-ji_ch-6_p-29_s-3","passageId":"li-ji_ch-6_p-29","order":3,"canonicalText":"命國難，九門磔攘，以畢春氣。","chunks":[["命國難，九門磔攘，以畢春氣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-30_s-1","passageId":"li-ji_ch-6_p-30","order":1,"canonicalText":"季春行冬令，則寒氣時發，草木皆肅，國有大恐。","chunks":[["季春行冬令，則寒氣時發，草木皆肅，國有大恐。","zh-Hant"]]},{"id":"li-ji_ch-6_p-30_s-2","passageId":"li-ji_ch-6_p-30","order":2,"canonicalText":"行夏令，則民多疾疫，時雨不降，山林不收。","chunks":[["行夏令，則民多疾疫，時雨不降，山林不收。","zh-Hant"]]},{"id":"li-ji_ch-6_p-30_s-3","passageId":"li-ji_ch-6_p-30","order":3,"canonicalText":"行秋令，則天多沉陰，淫雨蚤降，兵革并起。","chunks":[["行秋令，則天多沉陰，淫雨蚤降，兵革并起。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-1","passageId":"li-ji_ch-6_p-31","order":1,"canonicalText":"孟夏之月，日在畢，昏翼中，旦婺女中。","chunks":[["孟夏之月，日在畢，昏翼中，旦婺女中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-2","passageId":"li-ji_ch-6_p-31","order":2,"canonicalText":"其日丙丁。","chunks":[["其日丙丁。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-3","passageId":"li-ji_ch-6_p-31","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[["其帝炎帝，其神祝融。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-4","passageId":"li-ji_ch-6_p-31","order":4,"canonicalText":"其蟲羽。","chunks":[["其蟲羽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-5","passageId":"li-ji_ch-6_p-31","order":5,"canonicalText":"其音徵，律中中呂。","chunks":[["其音徵，律中中呂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-6","passageId":"li-ji_ch-6_p-31","order":6,"canonicalText":"其數七。","chunks":[["其數七。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-7","passageId":"li-ji_ch-6_p-31","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[["其味苦，其臭焦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-31_s-8","passageId":"li-ji_ch-6_p-31","order":8,"canonicalText":"其祀灶，祭先肺。","chunks":[["其祀灶，祭先肺。","zh-Hant"]]},{"id":"li-ji_ch-6_p-32_s-1","passageId":"li-ji_ch-6_p-32","order":1,"canonicalText":"螻蟈鳴，蚯螾出，王瓜生，苦菜秀。","chunks":[["螻蟈鳴，蚯螾出，王瓜生，苦菜秀。","zh-Hant"]]},{"id":"li-ji_ch-6_p-33_s-1","passageId":"li-ji_ch-6_p-33","order":1,"canonicalText":"天子居明堂左个，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","chunks":[["天子居明堂左个，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-33_s-2","passageId":"li-ji_ch-6_p-33","order":2,"canonicalText":"食菽與雞，其器高以粗。","chunks":[["食菽與雞，其器高以粗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-1","passageId":"li-ji_ch-6_p-34","order":1,"canonicalText":"是月也，以立夏。","chunks":[["是月也，以立夏。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-2","passageId":"li-ji_ch-6_p-34","order":2,"canonicalText":"先立夏三日，大史謁之天子曰：某日立夏，盛德在火。","chunks":[["先立夏三日，大史謁之天子曰：某日立夏，盛德在火。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-3","passageId":"li-ji_ch-6_p-34","order":3,"canonicalText":"天子乃齊。","chunks":[["天子乃齊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-4","passageId":"li-ji_ch-6_p-34","order":4,"canonicalText":"立夏之日，天子親帥三公、九卿、大夫以迎夏於南郊。","chunks":[["立夏之日，天子親帥三公、九卿、大夫以迎夏於南郊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-5","passageId":"li-ji_ch-6_p-34","order":5,"canonicalText":"還反，行賞，封諸侯。","chunks":[["還反，行賞，封諸侯。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-6","passageId":"li-ji_ch-6_p-34","order":6,"canonicalText":"慶賜遂行，無不欣說。","chunks":[["慶賜遂行，無不欣說。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-7","passageId":"li-ji_ch-6_p-34","order":7,"canonicalText":"乃命樂師，習合禮樂。","chunks":[["乃命樂師，習合禮樂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-34_s-8","passageId":"li-ji_ch-6_p-34","order":8,"canonicalText":"命太尉，贊桀俊，遂賢良，舉長大，行爵出祿，必當其位。","chunks":[["命太尉，贊桀俊，遂賢良，舉長大，行爵出祿，必當其位。","zh-Hant"]]},{"id":"li-ji_ch-6_p-35_s-1","passageId":"li-ji_ch-6_p-35","order":1,"canonicalText":"是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐大樹。","chunks":[["是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐大樹。","zh-Hant"]]},{"id":"li-ji_ch-6_p-36_s-1","passageId":"li-ji_ch-6_p-36","order":1,"canonicalText":"是月也，天子始絺。","chunks":[["是月也，天子始絺。","zh-Hant"]]},{"id":"li-ji_ch-6_p-36_s-2","passageId":"li-ji_ch-6_p-36","order":2,"canonicalText":"命野虞出行田原，為天子勞農勸民，毋或失時。","chunks":[["命野虞出行田原，為天子勞農勸民，毋或失時。","zh-Hant"]]},{"id":"li-ji_ch-6_p-36_s-3","passageId":"li-ji_ch-6_p-36","order":3,"canonicalText":"命司徒巡行縣鄙，命農勉作，毋休于都。","chunks":[["命司徒巡行縣鄙，命農勉作，毋休于都。","zh-Hant"]]},{"id":"li-ji_ch-6_p-37_s-1","passageId":"li-ji_ch-6_p-37","order":1,"canonicalText":"是月也，驅獸毋害五穀，毋大田獵。","chunks":[["是月也，驅獸毋害五穀，毋大田獵。","zh-Hant"]]},{"id":"li-ji_ch-6_p-37_s-2","passageId":"li-ji_ch-6_p-37","order":2,"canonicalText":"農乃登麥，天子乃以彘嘗麥，先薦寢廟。","chunks":[["農乃登麥，天子乃以彘嘗麥，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-38_s-1","passageId":"li-ji_ch-6_p-38","order":1,"canonicalText":"是月也，聚畜百藥。","chunks":[["是月也，聚畜百藥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-38_s-2","passageId":"li-ji_ch-6_p-38","order":2,"canonicalText":"靡草死，麥秋至。","chunks":[["靡草死，麥秋至。","zh-Hant"]]},{"id":"li-ji_ch-6_p-38_s-3","passageId":"li-ji_ch-6_p-38","order":3,"canonicalText":"斷薄刑，決小罪，出輕系。","chunks":[["斷薄刑，決小罪，出輕系。","zh-Hant"]]},{"id":"li-ji_ch-6_p-38_s-4","passageId":"li-ji_ch-6_p-38","order":4,"canonicalText":"蠶事畢，后妃獻繭。","chunks":[["蠶事畢，后妃獻繭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-38_s-5","passageId":"li-ji_ch-6_p-38","order":5,"canonicalText":"乃收繭稅，以桑為均，貴賤長幼如一，以給郊廟之服。","chunks":[["乃收繭稅，以桑為均，貴賤長幼如一，以給郊廟之服。","zh-Hant"]]},{"id":"li-ji_ch-6_p-39_s-1","passageId":"li-ji_ch-6_p-39","order":1,"canonicalText":"是月也，天子飲酎，用禮樂。","chunks":[["是月也，天子飲酎，用禮樂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-40_s-1","passageId":"li-ji_ch-6_p-40","order":1,"canonicalText":"孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保。","chunks":[["孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保。","zh-Hant"]]},{"id":"li-ji_ch-6_p-40_s-2","passageId":"li-ji_ch-6_p-40","order":2,"canonicalText":"行冬令，則草木蚤枯，後乃大水，敗其城郭。","chunks":[["行冬令，則草木蚤枯，後乃大水，敗其城郭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-40_s-3","passageId":"li-ji_ch-6_p-40","order":3,"canonicalText":"行春令，則蝗蟲為災，暴風來格，秀草不實。","chunks":[["行春令，則蝗蟲為災，暴風來格，秀草不實。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-1","passageId":"li-ji_ch-6_p-41","order":1,"canonicalText":"仲夏之月，日在東井，昏亢中，旦危中。","chunks":[["仲夏之月，日在東井，昏亢中，旦危中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-2","passageId":"li-ji_ch-6_p-41","order":2,"canonicalText":"其日丙丁。","chunks":[["其日丙丁。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-3","passageId":"li-ji_ch-6_p-41","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[["其帝炎帝，其神祝融。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-4","passageId":"li-ji_ch-6_p-41","order":4,"canonicalText":"其蟲羽。","chunks":[["其蟲羽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-5","passageId":"li-ji_ch-6_p-41","order":5,"canonicalText":"其音徵，律中蕤賓。","chunks":[["其音徵，律中蕤賓。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-6","passageId":"li-ji_ch-6_p-41","order":6,"canonicalText":"其數七。","chunks":[["其數七。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-7","passageId":"li-ji_ch-6_p-41","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[["其味苦，其臭焦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-41_s-8","passageId":"li-ji_ch-6_p-41","order":8,"canonicalText":"其祀灶，祭先肺。","chunks":[["其祀灶，祭先肺。","zh-Hant"]]},{"id":"li-ji_ch-6_p-42_s-1","passageId":"li-ji_ch-6_p-42","order":1,"canonicalText":"小暑至，螳蜋生。","chunks":[["小暑至，螳蜋生。","zh-Hant"]]},{"id":"li-ji_ch-6_p-42_s-2","passageId":"li-ji_ch-6_p-42","order":2,"canonicalText":"鵙始鳴，反舌無聲。","chunks":[["鵙始鳴，反舌無聲。","zh-Hant"]]},{"id":"li-ji_ch-6_p-43_s-1","passageId":"li-ji_ch-6_p-43","order":1,"canonicalText":"天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉，食菽與雞，其器高以粗。","chunks":[["天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉，食菽與雞，其器高以粗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-43_s-2","passageId":"li-ji_ch-6_p-43","order":2,"canonicalText":"養壯佼。","chunks":[["養壯佼。","zh-Hant"]]},{"id":"li-ji_ch-6_p-44_s-1","passageId":"li-ji_ch-6_p-44","order":1,"canonicalText":"是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔。","chunks":[["是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔。","zh-Hant"]]},{"id":"li-ji_ch-6_p-44_s-2","passageId":"li-ji_ch-6_p-44","order":2,"canonicalText":"命有司為民祈祀山川百源，大雩帝，用盛樂。","chunks":[["命有司為民祈祀山川百源，大雩帝，用盛樂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-44_s-3","passageId":"li-ji_ch-6_p-44","order":3,"canonicalText":"乃命百縣，雩祀百辟卿士有益於民者，以祈穀實。","chunks":[["乃命百縣，雩祀百辟卿士有益於民者，以祈穀實。","zh-Hant"]]},{"id":"li-ji_ch-6_p-44_s-4","passageId":"li-ji_ch-6_p-44","order":4,"canonicalText":"農乃登黍。","chunks":[["農乃登黍。","zh-Hant"]]},{"id":"li-ji_ch-6_p-45_s-1","passageId":"li-ji_ch-6_p-45","order":1,"canonicalText":"是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟。","chunks":[["是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-45_s-2","passageId":"li-ji_ch-6_p-45","order":2,"canonicalText":"令民毋艾藍以染，毋燒灰，毋暴布。","chunks":[["令民毋艾藍以染，毋燒灰，毋暴布。","zh-Hant"]]},{"id":"li-ji_ch-6_p-45_s-3","passageId":"li-ji_ch-6_p-45","order":3,"canonicalText":"門閭毋閉，關市毋索。","chunks":[["門閭毋閉，關市毋索。","zh-Hant"]]},{"id":"li-ji_ch-6_p-45_s-4","passageId":"li-ji_ch-6_p-45","order":4,"canonicalText":"挺重囚，益其食。","chunks":[["挺重囚，益其食。","zh-Hant"]]},{"id":"li-ji_ch-6_p-45_s-5","passageId":"li-ji_ch-6_p-45","order":5,"canonicalText":"游牝別群，則縶騰駒，班馬政。","chunks":[["游牝別群，則縶騰駒，班馬政。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-1","passageId":"li-ji_ch-6_p-46","order":1,"canonicalText":"是月也，日長至，陰陽爭，死生分。","chunks":[["是月也，日長至，陰陽爭，死生分。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-2","passageId":"li-ji_ch-6_p-46","order":2,"canonicalText":"君子齊戒，處必掩身，毋躁。","chunks":[["君子齊戒，處必掩身，毋躁。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-3","passageId":"li-ji_ch-6_p-46","order":3,"canonicalText":"止聲色，毋或進。","chunks":[["止聲色，毋或進。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-4","passageId":"li-ji_ch-6_p-46","order":4,"canonicalText":"薄滋味，毋致和。","chunks":[["薄滋味，毋致和。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-5","passageId":"li-ji_ch-6_p-46","order":5,"canonicalText":"節嗜欲，定心氣，百官靜事毋刑，以定晏陰之所成。","chunks":[["節嗜欲，定心氣，百官靜事毋刑，以定晏陰之所成。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-6","passageId":"li-ji_ch-6_p-46","order":6,"canonicalText":"鹿角解，蟬始鳴。","chunks":[["鹿角解，蟬始鳴。","zh-Hant"]]},{"id":"li-ji_ch-6_p-46_s-7","passageId":"li-ji_ch-6_p-46","order":7,"canonicalText":"半夏生，木堇榮。","chunks":[["半夏生，木堇榮。","zh-Hant"]]},{"id":"li-ji_ch-6_p-47_s-1","passageId":"li-ji_ch-6_p-47","order":1,"canonicalText":"是月也，毋用火南方。","chunks":[["是月也，毋用火南方。","zh-Hant"]]},{"id":"li-ji_ch-6_p-47_s-2","passageId":"li-ji_ch-6_p-47","order":2,"canonicalText":"可以居高明，可以遠眺望，可以升山陵，可以處臺榭。","chunks":[["可以居高明，可以遠眺望，可以升山陵，可以處臺榭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-48_s-1","passageId":"li-ji_ch-6_p-48","order":1,"canonicalText":"仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至。","chunks":[["仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至。","zh-Hant"]]},{"id":"li-ji_ch-6_p-48_s-2","passageId":"li-ji_ch-6_p-48","order":2,"canonicalText":"行春令，則五穀晚熟，百螣時起，其國乃饑。","chunks":[["行春令，則五穀晚熟，百螣時起，其國乃饑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-48_s-3","passageId":"li-ji_ch-6_p-48","order":3,"canonicalText":"行秋令，則草木零落，果實早成，民殃於疫。","chunks":[["行秋令，則草木零落，果實早成，民殃於疫。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-1","passageId":"li-ji_ch-6_p-49","order":1,"canonicalText":"季夏之月，日在柳，昏火中，旦奎中。","chunks":[["季夏之月，日在柳，昏火中，旦奎中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-2","passageId":"li-ji_ch-6_p-49","order":2,"canonicalText":"其日丙丁。","chunks":[["其日丙丁。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-3","passageId":"li-ji_ch-6_p-49","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[["其帝炎帝，其神祝融。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-4","passageId":"li-ji_ch-6_p-49","order":4,"canonicalText":"其蟲羽。","chunks":[["其蟲羽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-5","passageId":"li-ji_ch-6_p-49","order":5,"canonicalText":"其音徵，律中林鐘。","chunks":[["其音徵，律中林鐘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-6","passageId":"li-ji_ch-6_p-49","order":6,"canonicalText":"其數七。","chunks":[["其數七。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-7","passageId":"li-ji_ch-6_p-49","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[["其味苦，其臭焦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-49_s-8","passageId":"li-ji_ch-6_p-49","order":8,"canonicalText":"其祀灶，祭先肺。","chunks":[["其祀灶，祭先肺。","zh-Hant"]]},{"id":"li-ji_ch-6_p-50_s-1","passageId":"li-ji_ch-6_p-50","order":1,"canonicalText":"溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢。","chunks":[["溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢。","zh-Hant"]]},{"id":"li-ji_ch-6_p-51_s-1","passageId":"li-ji_ch-6_p-51","order":1,"canonicalText":"天子居明堂右个，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","chunks":[["天子居明堂右个，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-51_s-2","passageId":"li-ji_ch-6_p-51","order":2,"canonicalText":"食菽與雞，其器高以粗。","chunks":[["食菽與雞，其器高以粗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-51_s-3","passageId":"li-ji_ch-6_p-51","order":3,"canonicalText":"命漁師伐蛟取鼉，登龜取黿。","chunks":[["命漁師伐蛟取鼉，登龜取黿。","zh-Hant"]]},{"id":"li-ji_ch-6_p-51_s-4","passageId":"li-ji_ch-6_p-51","order":4,"canonicalText":"命澤人納材葦。","chunks":[["命澤人納材葦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-52_s-1","passageId":"li-ji_ch-6_p-52","order":1,"canonicalText":"是月也，命四監大合百縣之秩芻，以養犧牲。","chunks":[["是月也，命四監大合百縣之秩芻，以養犧牲。","zh-Hant"]]},{"id":"li-ji_ch-6_p-52_s-2","passageId":"li-ji_ch-6_p-52","order":2,"canonicalText":"令民無不咸出其力，以共皇天上帝名山大川四方之神，以祠宗廟社稷之靈，以為民祈福。","chunks":[["令民無不咸出其力，以共皇天上帝名山大川四方之神，以祠宗廟社稷之靈，以為民祈福。","zh-Hant"]]},{"id":"li-ji_ch-6_p-53_s-1","passageId":"li-ji_ch-6_p-53","order":1,"canonicalText":"是月也，命婦官染采，黼黻文章，必以法故，無或差貸。","chunks":[["是月也，命婦官染采，黼黻文章，必以法故，無或差貸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-53_s-2","passageId":"li-ji_ch-6_p-53","order":2,"canonicalText":"黑黃倉赤，莫不質良，毋敢詐偽，以給郊廟祭祀之服，以為旗章，以別貴賤等給之度。","chunks":[["黑黃倉赤，莫不質良，毋敢詐偽，以給郊廟祭祀之服，以為旗章，以別貴賤等給之度。","zh-Hant"]]},{"id":"li-ji_ch-6_p-54_s-1","passageId":"li-ji_ch-6_p-54","order":1,"canonicalText":"是月也，樹木方盛，乃命虞人入山行木，毋有斬伐。","chunks":[["是月也，樹木方盛，乃命虞人入山行木，毋有斬伐。","zh-Hant"]]},{"id":"li-ji_ch-6_p-54_s-2","passageId":"li-ji_ch-6_p-54","order":2,"canonicalText":"不可以興土功，不可以合諸侯，不可以起兵動眾，毋舉大事，以搖養氣。","chunks":[["不可以興土功，不可以合諸侯，不可以起兵動眾，毋舉大事，以搖養氣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-54_s-3","passageId":"li-ji_ch-6_p-54","order":3,"canonicalText":"毋發令而待，以妨神農之事也。","chunks":[["毋發令而待，以妨神農之事也。","zh-Hant"]]},{"id":"li-ji_ch-6_p-54_s-4","passageId":"li-ji_ch-6_p-54","order":4,"canonicalText":"水潦盛昌，神農將持功，舉大事則有天殃。","chunks":[["水潦盛昌，神農將持功，舉大事則有天殃。","zh-Hant"]]},{"id":"li-ji_ch-6_p-55_s-1","passageId":"li-ji_ch-6_p-55","order":1,"canonicalText":"是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以熱湯。","chunks":[["是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以熱湯。","zh-Hant"]]},{"id":"li-ji_ch-6_p-55_s-2","passageId":"li-ji_ch-6_p-55","order":2,"canonicalText":"可以糞田疇，可以美土強。","chunks":[["可以糞田疇，可以美土強。","zh-Hant"]]},{"id":"li-ji_ch-6_p-56_s-1","passageId":"li-ji_ch-6_p-56","order":1,"canonicalText":"季夏行春令，則穀實鮮落，國多風咳，民乃遷徙。","chunks":[["季夏行春令，則穀實鮮落，國多風咳，民乃遷徙。","zh-Hant"]]},{"id":"li-ji_ch-6_p-56_s-2","passageId":"li-ji_ch-6_p-56","order":2,"canonicalText":"行秋令，則丘隰水潦，禾稼不熟，乃多女災。","chunks":[["行秋令，則丘隰水潦，禾稼不熟，乃多女災。","zh-Hant"]]},{"id":"li-ji_ch-6_p-56_s-3","passageId":"li-ji_ch-6_p-56","order":3,"canonicalText":"行冬令，則風寒不時，鷹隼蚤鷙，四鄙入保。","chunks":[["行冬令，則風寒不時，鷹隼蚤鷙，四鄙入保。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-1","passageId":"li-ji_ch-6_p-57","order":1,"canonicalText":"中央土。","chunks":[["中央土。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-2","passageId":"li-ji_ch-6_p-57","order":2,"canonicalText":"其日戊己。","chunks":[["其日戊己。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-3","passageId":"li-ji_ch-6_p-57","order":3,"canonicalText":"其帝黃帝，其神後土。","chunks":[["其帝黃帝，其神後土。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-4","passageId":"li-ji_ch-6_p-57","order":4,"canonicalText":"其蟲裸，其音宮，律中黃鐘之宮。","chunks":[["其蟲裸，其音宮，律中黃鐘之宮。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-5","passageId":"li-ji_ch-6_p-57","order":5,"canonicalText":"其數五。","chunks":[["其數五。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-6","passageId":"li-ji_ch-6_p-57","order":6,"canonicalText":"其味甘，其臭香。","chunks":[["其味甘，其臭香。","zh-Hant"]]},{"id":"li-ji_ch-6_p-57_s-7","passageId":"li-ji_ch-6_p-57","order":7,"canonicalText":"其祠中溜，祭先心。","chunks":[["其祠中溜，祭先心。","zh-Hant"]]},{"id":"li-ji_ch-6_p-58_s-1","passageId":"li-ji_ch-6_p-58","order":1,"canonicalText":"天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃玉，食稷與牛，其器圜以閎。","chunks":[["天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃玉，食稷與牛，其器圜以閎。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-1","passageId":"li-ji_ch-6_p-59","order":1,"canonicalText":"孟秋之月，日在翼，昏建星中，旦畢中。","chunks":[["孟秋之月，日在翼，昏建星中，旦畢中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-2","passageId":"li-ji_ch-6_p-59","order":2,"canonicalText":"其日庚辛。","chunks":[["其日庚辛。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-3","passageId":"li-ji_ch-6_p-59","order":3,"canonicalText":"其帝少皞，其神蓐收。","chunks":[["其帝少皞，其神蓐收。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-4","passageId":"li-ji_ch-6_p-59","order":4,"canonicalText":"其蟲毛。","chunks":[["其蟲毛。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-5","passageId":"li-ji_ch-6_p-59","order":5,"canonicalText":"其音商，律中夷則。","chunks":[["其音商，律中夷則。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-6","passageId":"li-ji_ch-6_p-59","order":6,"canonicalText":"其數九。","chunks":[["其數九。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-7","passageId":"li-ji_ch-6_p-59","order":7,"canonicalText":"其味辛，其臭腥。","chunks":[["其味辛，其臭腥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-59_s-8","passageId":"li-ji_ch-6_p-59","order":8,"canonicalText":"其祀門，祭先肝。","chunks":[["其祀門，祭先肝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-60_s-1","passageId":"li-ji_ch-6_p-60","order":1,"canonicalText":"涼風至，白露降，寒蟬鳴。","chunks":[["涼風至，白露降，寒蟬鳴。","zh-Hant"]]},{"id":"li-ji_ch-6_p-60_s-2","passageId":"li-ji_ch-6_p-60","order":2,"canonicalText":"鷹乃祭鳥，用始行戮。","chunks":[["鷹乃祭鳥，用始行戮。","zh-Hant"]]},{"id":"li-ji_ch-6_p-61_s-1","passageId":"li-ji_ch-6_p-61","order":1,"canonicalText":"天子居總章左个，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","chunks":[["天子居總章左个，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-1","passageId":"li-ji_ch-6_p-62","order":1,"canonicalText":"是月也，以立秋。","chunks":[["是月也，以立秋。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-2","passageId":"li-ji_ch-6_p-62","order":2,"canonicalText":"先立秋三日，大史謁之天子曰：某日立秋，盛德在金。","chunks":[["先立秋三日，大史謁之天子曰：某日立秋，盛德在金。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-3","passageId":"li-ji_ch-6_p-62","order":3,"canonicalText":"天子乃齊。","chunks":[["天子乃齊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-4","passageId":"li-ji_ch-6_p-62","order":4,"canonicalText":"立秋之日，天子親帥三公、九卿、諸侯、大夫，以迎秋於西郊。","chunks":[["立秋之日，天子親帥三公、九卿、諸侯、大夫，以迎秋於西郊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-5","passageId":"li-ji_ch-6_p-62","order":5,"canonicalText":"還反，賞軍帥武人於朝。","chunks":[["還反，賞軍帥武人於朝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-6","passageId":"li-ji_ch-6_p-62","order":6,"canonicalText":"天子乃命將帥，選士厲兵，簡練桀俊，專任有功，以征不義。","chunks":[["天子乃命將帥，選士厲兵，簡練桀俊，專任有功，以征不義。","zh-Hant"]]},{"id":"li-ji_ch-6_p-62_s-7","passageId":"li-ji_ch-6_p-62","order":7,"canonicalText":"詰誅暴慢，以明好惡，順彼遠方。","chunks":[["詰誅暴慢，以明好惡，順彼遠方。","zh-Hant"]]},{"id":"li-ji_ch-6_p-63_s-1","passageId":"li-ji_ch-6_p-63","order":1,"canonicalText":"是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪，務搏執。","chunks":[["是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪，務搏執。","zh-Hant"]]},{"id":"li-ji_ch-6_p-63_s-2","passageId":"li-ji_ch-6_p-63","order":2,"canonicalText":"命理瞻傷，察創，視折，審斷。","chunks":[["命理瞻傷，察創，視折，審斷。","zh-Hant"]]},{"id":"li-ji_ch-6_p-63_s-3","passageId":"li-ji_ch-6_p-63","order":3,"canonicalText":"決獄訟，必端平。","chunks":[["決獄訟，必端平。","zh-Hant"]]},{"id":"li-ji_ch-6_p-63_s-4","passageId":"li-ji_ch-6_p-63","order":4,"canonicalText":"戮有罪，嚴斷刑。","chunks":[["戮有罪，嚴斷刑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-63_s-5","passageId":"li-ji_ch-6_p-63","order":5,"canonicalText":"天地始肅，不可以贏。","chunks":[["天地始肅，不可以贏。","zh-Hant"]]},{"id":"li-ji_ch-6_p-64_s-1","passageId":"li-ji_ch-6_p-64","order":1,"canonicalText":"是月也，農乃登穀。","chunks":[["是月也，農乃登穀。","zh-Hant"]]},{"id":"li-ji_ch-6_p-64_s-2","passageId":"li-ji_ch-6_p-64","order":2,"canonicalText":"天子嘗新，先薦寢廟。","chunks":[["天子嘗新，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-64_s-3","passageId":"li-ji_ch-6_p-64","order":3,"canonicalText":"命百官，始收斂。","chunks":[["命百官，始收斂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-64_s-4","passageId":"li-ji_ch-6_p-64","order":4,"canonicalText":"完堤防，謹壅塞，以備水潦。","chunks":[["完堤防，謹壅塞，以備水潦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-64_s-5","passageId":"li-ji_ch-6_p-64","order":5,"canonicalText":"修宮室，壞墻垣，補城郭。","chunks":[["修宮室，壞墻垣，補城郭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-65_s-1","passageId":"li-ji_ch-6_p-65","order":1,"canonicalText":"是月也，毋以封諸侯、立大官。","chunks":[["是月也，毋以封諸侯、立大官。","zh-Hant"]]},{"id":"li-ji_ch-6_p-65_s-2","passageId":"li-ji_ch-6_p-65","order":2,"canonicalText":"毋以割地、行大使、出大幣。","chunks":[["毋以割地、行大使、出大幣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-66_s-1","passageId":"li-ji_ch-6_p-66","order":1,"canonicalText":"孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來。","chunks":[["孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來。","zh-Hant"]]},{"id":"li-ji_ch-6_p-66_s-2","passageId":"li-ji_ch-6_p-66","order":2,"canonicalText":"行春令，則其國乃旱，陽氣復還，五穀無實。","chunks":[["行春令，則其國乃旱，陽氣復還，五穀無實。","zh-Hant"]]},{"id":"li-ji_ch-6_p-66_s-3","passageId":"li-ji_ch-6_p-66","order":3,"canonicalText":"行夏令，則國多火災，寒熱不節，民多瘧疾。","chunks":[["行夏令，則國多火災，寒熱不節，民多瘧疾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-1","passageId":"li-ji_ch-6_p-67","order":1,"canonicalText":"仲秋之月，日在角，昏牽牛中，旦觜觿中。","chunks":[["仲秋之月，日在角，昏牽牛中，旦觜觿中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-2","passageId":"li-ji_ch-6_p-67","order":2,"canonicalText":"其日庚辛，其帝少皞，其神蓐收。","chunks":[["其日庚辛，其帝少皞，其神蓐收。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-3","passageId":"li-ji_ch-6_p-67","order":3,"canonicalText":"其蟲毛。","chunks":[["其蟲毛。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-4","passageId":"li-ji_ch-6_p-67","order":4,"canonicalText":"其音商，律中南呂。","chunks":[["其音商，律中南呂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-5","passageId":"li-ji_ch-6_p-67","order":5,"canonicalText":"其數九。","chunks":[["其數九。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-6","passageId":"li-ji_ch-6_p-67","order":6,"canonicalText":"其味辛，其臭腥。","chunks":[["其味辛，其臭腥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-67_s-7","passageId":"li-ji_ch-6_p-67","order":7,"canonicalText":"其祀門，祭先肝。","chunks":[["其祀門，祭先肝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-68_s-1","passageId":"li-ji_ch-6_p-68","order":1,"canonicalText":"盲風至，鴻雁來，玄鳥歸，群鳥養羞。","chunks":[["盲風至，鴻雁來，玄鳥歸，群鳥養羞。","zh-Hant"]]},{"id":"li-ji_ch-6_p-69_s-1","passageId":"li-ji_ch-6_p-69","order":1,"canonicalText":"天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","chunks":[["天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","zh-Hant"]]},{"id":"li-ji_ch-6_p-70_s-1","passageId":"li-ji_ch-6_p-70","order":1,"canonicalText":"是月也，養衰老，授几杖，行糜粥飲食。","chunks":[["是月也，養衰老，授几杖，行糜粥飲食。","zh-Hant"]]},{"id":"li-ji_ch-6_p-70_s-2","passageId":"li-ji_ch-6_p-70","order":2,"canonicalText":"乃命司服，具飭衣裳，文繡有恒，制有小大，度有長短。","chunks":[["乃命司服，具飭衣裳，文繡有恒，制有小大，度有長短。","zh-Hant"]]},{"id":"li-ji_ch-6_p-70_s-3","passageId":"li-ji_ch-6_p-70","order":3,"canonicalText":"衣服有量，必循其故，冠帶有常。","chunks":[["衣服有量，必循其故，冠帶有常。","zh-Hant"]]},{"id":"li-ji_ch-6_p-70_s-4","passageId":"li-ji_ch-6_p-70","order":4,"canonicalText":"乃命有司，申嚴百刑，斬殺必當，毋或枉橈。","chunks":[["乃命有司，申嚴百刑，斬殺必當，毋或枉橈。","zh-Hant"]]},{"id":"li-ji_ch-6_p-70_s-5","passageId":"li-ji_ch-6_p-70","order":5,"canonicalText":"枉橈不當，反受其殃。","chunks":[["枉橈不當，反受其殃。","zh-Hant"]]},{"id":"li-ji_ch-6_p-71_s-1","passageId":"li-ji_ch-6_p-71","order":1,"canonicalText":"是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色。","chunks":[["是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色。","zh-Hant"]]},{"id":"li-ji_ch-6_p-71_s-2","passageId":"li-ji_ch-6_p-71","order":2,"canonicalText":"必比類，量小大，視長短，皆中度。","chunks":[["必比類，量小大，視長短，皆中度。","zh-Hant"]]},{"id":"li-ji_ch-6_p-71_s-3","passageId":"li-ji_ch-6_p-71","order":3,"canonicalText":"五者備當，上帝其饗。","chunks":[["五者備當，上帝其饗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-71_s-4","passageId":"li-ji_ch-6_p-71","order":4,"canonicalText":"天子乃難，以達秋氣。","chunks":[["天子乃難，以達秋氣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-71_s-5","passageId":"li-ji_ch-6_p-71","order":5,"canonicalText":"以犬嘗麻，先薦寢廟。","chunks":[["以犬嘗麻，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-72_s-1","passageId":"li-ji_ch-6_p-72","order":1,"canonicalText":"是月也，可以筑城郭，建都邑，穿竇窖，修囷倉。","chunks":[["是月也，可以筑城郭，建都邑，穿竇窖，修囷倉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-72_s-2","passageId":"li-ji_ch-6_p-72","order":2,"canonicalText":"乃命有司，趣民收斂，務畜菜，多積聚。","chunks":[["乃命有司，趣民收斂，務畜菜，多積聚。","zh-Hant"]]},{"id":"li-ji_ch-6_p-72_s-3","passageId":"li-ji_ch-6_p-72","order":3,"canonicalText":"乃勸種麥，毋或失時。","chunks":[["乃勸種麥，毋或失時。","zh-Hant"]]},{"id":"li-ji_ch-6_p-72_s-4","passageId":"li-ji_ch-6_p-72","order":4,"canonicalText":"其有失時，行罪無疑。","chunks":[["其有失時，行罪無疑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-73_s-1","passageId":"li-ji_ch-6_p-73","order":1,"canonicalText":"是月也，日夜分，雷始收聲。","chunks":[["是月也，日夜分，雷始收聲。","zh-Hant"]]},{"id":"li-ji_ch-6_p-73_s-2","passageId":"li-ji_ch-6_p-73","order":2,"canonicalText":"蟄蟲壞戶，殺氣浸盛，陽氣日衰，水始涸。","chunks":[["蟄蟲壞戶，殺氣浸盛，陽氣日衰，水始涸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-73_s-3","passageId":"li-ji_ch-6_p-73","order":3,"canonicalText":"日夜分，則同度量，平權衡，正鈞石，角斗甬。","chunks":[["日夜分，則同度量，平權衡，正鈞石，角斗甬。","zh-Hant"]]},{"id":"li-ji_ch-6_p-74_s-1","passageId":"li-ji_ch-6_p-74","order":1,"canonicalText":"是月也，易關市，來商旅，納貨賄，以便民事。","chunks":[["是月也，易關市，來商旅，納貨賄，以便民事。","zh-Hant"]]},{"id":"li-ji_ch-6_p-74_s-2","passageId":"li-ji_ch-6_p-74","order":2,"canonicalText":"四方來集，遠鄉皆至，則財不匱，上無乏用，百事乃遂。","chunks":[["四方來集，遠鄉皆至，則財不匱，上無乏用，百事乃遂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-74_s-3","passageId":"li-ji_ch-6_p-74","order":3,"canonicalText":"凡舉大事，毋逆大數，必順其時，慎因其類。","chunks":[["凡舉大事，毋逆大數，必順其時，慎因其類。","zh-Hant"]]},{"id":"li-ji_ch-6_p-75_s-1","passageId":"li-ji_ch-6_p-75","order":1,"canonicalText":"仲秋行春令，則秋雨不降，草木生榮，國乃有恐。","chunks":[["仲秋行春令，則秋雨不降，草木生榮，國乃有恐。","zh-Hant"]]},{"id":"li-ji_ch-6_p-75_s-2","passageId":"li-ji_ch-6_p-75","order":2,"canonicalText":"行夏令，則其國乃旱，蟄蟲不藏，五穀復生。","chunks":[["行夏令，則其國乃旱，蟄蟲不藏，五穀復生。","zh-Hant"]]},{"id":"li-ji_ch-6_p-75_s-3","passageId":"li-ji_ch-6_p-75","order":3,"canonicalText":"行冬令，則風災數起，收雷先行，草木蚤死。","chunks":[["行冬令，則風災數起，收雷先行，草木蚤死。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-1","passageId":"li-ji_ch-6_p-76","order":1,"canonicalText":"季秋之月，日在房，昏虛中，旦柳中。","chunks":[["季秋之月，日在房，昏虛中，旦柳中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-2","passageId":"li-ji_ch-6_p-76","order":2,"canonicalText":"其日庚辛。","chunks":[["其日庚辛。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-3","passageId":"li-ji_ch-6_p-76","order":3,"canonicalText":"其帝少皞，其神蓐收。","chunks":[["其帝少皞，其神蓐收。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-4","passageId":"li-ji_ch-6_p-76","order":4,"canonicalText":"其蟲毛。","chunks":[["其蟲毛。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-5","passageId":"li-ji_ch-6_p-76","order":5,"canonicalText":"其音商，律中無射。","chunks":[["其音商，律中無射。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-6","passageId":"li-ji_ch-6_p-76","order":6,"canonicalText":"其數九。","chunks":[["其數九。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-7","passageId":"li-ji_ch-6_p-76","order":7,"canonicalText":"其味辛，其臭腥。","chunks":[["其味辛，其臭腥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-76_s-8","passageId":"li-ji_ch-6_p-76","order":8,"canonicalText":"其祀門，祭先肝。","chunks":[["其祀門，祭先肝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-77_s-1","passageId":"li-ji_ch-6_p-77","order":1,"canonicalText":"鴻雁來賓，爵入大水為蛤。","chunks":[["鴻雁來賓，爵入大水為蛤。","zh-Hant"]]},{"id":"li-ji_ch-6_p-77_s-2","passageId":"li-ji_ch-6_p-77","order":2,"canonicalText":"鞠有黃華，豺乃祭獸戮禽。","chunks":[["鞠有黃華，豺乃祭獸戮禽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-78_s-1","passageId":"li-ji_ch-6_p-78","order":1,"canonicalText":"天子居總章右个，乘戎路，駕白駱，載白旗，衣白衣，服白玉。","chunks":[["天子居總章右个，乘戎路，駕白駱，載白旗，衣白衣，服白玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-78_s-2","passageId":"li-ji_ch-6_p-78","order":2,"canonicalText":"食麻與犬，其器廉以深。","chunks":[["食麻與犬，其器廉以深。","zh-Hant"]]},{"id":"li-ji_ch-6_p-79_s-1","passageId":"li-ji_ch-6_p-79","order":1,"canonicalText":"是月也，申嚴號令。","chunks":[["是月也，申嚴號令。","zh-Hant"]]},{"id":"li-ji_ch-6_p-79_s-2","passageId":"li-ji_ch-6_p-79","order":2,"canonicalText":"命百官貴賤無不務內，以會天地之藏，無有宣出。","chunks":[["命百官貴賤無不務內，以會天地之藏，無有宣出。","zh-Hant"]]},{"id":"li-ji_ch-6_p-79_s-3","passageId":"li-ji_ch-6_p-79","order":3,"canonicalText":"乃命冢宰，農事備收，舉五穀之要，藏帝藉之收於神倉，祗敬必飭。","chunks":[["乃命冢宰，農事備收，舉五穀之要，藏帝藉之收於神倉，祗敬必飭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-80_s-1","passageId":"li-ji_ch-6_p-80","order":1,"canonicalText":"是月也，霜始降，則百工休。","chunks":[["是月也，霜始降，則百工休。","zh-Hant"]]},{"id":"li-ji_ch-6_p-80_s-2","passageId":"li-ji_ch-6_p-80","order":2,"canonicalText":"乃命有司曰：寒氣總至，民力不堪，其皆入室。","chunks":[["乃命有司曰：寒氣總至，民力不堪，其皆入室。","zh-Hant"]]},{"id":"li-ji_ch-6_p-80_s-3","passageId":"li-ji_ch-6_p-80","order":3,"canonicalText":"上丁，命樂正入學習吹。","chunks":[["上丁，命樂正入學習吹。","zh-Hant"]]},{"id":"li-ji_ch-6_p-81_s-1","passageId":"li-ji_ch-6_p-81","order":1,"canonicalText":"是月也，大饗帝、嘗，犧牲告備于天子。","chunks":[["是月也，大饗帝、嘗，犧牲告備于天子。","zh-Hant"]]},{"id":"li-ji_ch-6_p-81_s-2","passageId":"li-ji_ch-6_p-81","order":2,"canonicalText":"合諸侯，制百縣，為來歲受朔日，與諸侯所稅於民輕重之法，貢職之數，以遠近土地所宜為度，以給郊廟之事，無有所私。","chunks":[["合諸侯，制百縣，為來歲受朔日，與諸侯所稅於民輕重之法，貢職之數，以遠近土地所宜為度，以給郊廟之事，無有所私。","zh-Hant"]]},{"id":"li-ji_ch-6_p-82_s-1","passageId":"li-ji_ch-6_p-82","order":1,"canonicalText":"是月也，天子乃教於田獵，以習五戎，班馬政。","chunks":[["是月也，天子乃教於田獵，以習五戎，班馬政。","zh-Hant"]]},{"id":"li-ji_ch-6_p-82_s-2","passageId":"li-ji_ch-6_p-82","order":2,"canonicalText":"命仆及七騶咸駕，載旌旐，授車以級，整設於屏外。","chunks":[["命仆及七騶咸駕，載旌旐，授車以級，整設於屏外。","zh-Hant"]]},{"id":"li-ji_ch-6_p-82_s-3","passageId":"li-ji_ch-6_p-82","order":3,"canonicalText":"司徒搢撲，北面誓之。","chunks":[["司徒搢撲，北面誓之。","zh-Hant"]]},{"id":"li-ji_ch-6_p-82_s-4","passageId":"li-ji_ch-6_p-82","order":4,"canonicalText":"天子乃厲飾，執弓挾矢以獵，命主祠祭禽于四方。","chunks":[["天子乃厲飾，執弓挾矢以獵，命主祠祭禽于四方。","zh-Hant"]]},{"id":"li-ji_ch-6_p-83_s-1","passageId":"li-ji_ch-6_p-83","order":1,"canonicalText":"是月也，草木黃落，乃伐薪為炭。","chunks":[["是月也，草木黃落，乃伐薪為炭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-83_s-2","passageId":"li-ji_ch-6_p-83","order":2,"canonicalText":"蟄蟲咸俯在內，皆墐其戶。","chunks":[["蟄蟲咸俯在內，皆墐其戶。","zh-Hant"]]},{"id":"li-ji_ch-6_p-83_s-3","passageId":"li-ji_ch-6_p-83","order":3,"canonicalText":"乃趣獄刑，毋留有罪。","chunks":[["乃趣獄刑，毋留有罪。","zh-Hant"]]},{"id":"li-ji_ch-6_p-83_s-4","passageId":"li-ji_ch-6_p-83","order":4,"canonicalText":"收祿秩之不當、供養之不宜者。","chunks":[["收祿秩之不當、供養之不宜者。","zh-Hant"]]},{"id":"li-ji_ch-6_p-84_s-1","passageId":"li-ji_ch-6_p-84","order":1,"canonicalText":"是月也，天子乃以犬嘗稻，先薦寢廟。","chunks":[["是月也，天子乃以犬嘗稻，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-85_s-1","passageId":"li-ji_ch-6_p-85","order":1,"canonicalText":"季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏。","chunks":[["季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏。","zh-Hant"]]},{"id":"li-ji_ch-6_p-85_s-2","passageId":"li-ji_ch-6_p-85","order":2,"canonicalText":"行冬令，則國多盜賊，邊境不寧，土地分裂。","chunks":[["行冬令，則國多盜賊，邊境不寧，土地分裂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-85_s-3","passageId":"li-ji_ch-6_p-85","order":3,"canonicalText":"行春令，則暖風來至，民氣解惰，師興不居。","chunks":[["行春令，則暖風來至，民氣解惰，師興不居。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-1","passageId":"li-ji_ch-6_p-86","order":1,"canonicalText":"孟冬之月，日在尾，昏危中，旦七星中。","chunks":[["孟冬之月，日在尾，昏危中，旦七星中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-2","passageId":"li-ji_ch-6_p-86","order":2,"canonicalText":"其日壬癸。","chunks":[["其日壬癸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-3","passageId":"li-ji_ch-6_p-86","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[["其帝顓頊，其神玄冥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-4","passageId":"li-ji_ch-6_p-86","order":4,"canonicalText":"其蟲介。","chunks":[["其蟲介。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-5","passageId":"li-ji_ch-6_p-86","order":5,"canonicalText":"其音羽，律中應鐘。","chunks":[["其音羽，律中應鐘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-6","passageId":"li-ji_ch-6_p-86","order":6,"canonicalText":"其數六。","chunks":[["其數六。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-7","passageId":"li-ji_ch-6_p-86","order":7,"canonicalText":"其味咸，其臭朽。","chunks":[["其味咸，其臭朽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-86_s-8","passageId":"li-ji_ch-6_p-86","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[["其祀行，祭先腎。","zh-Hant"]]},{"id":"li-ji_ch-6_p-87_s-1","passageId":"li-ji_ch-6_p-87","order":1,"canonicalText":"水始冰，地始凍。","chunks":[["水始冰，地始凍。","zh-Hant"]]},{"id":"li-ji_ch-6_p-87_s-2","passageId":"li-ji_ch-6_p-87","order":2,"canonicalText":"雉入大水為蜃。","chunks":[["雉入大水為蜃。","zh-Hant"]]},{"id":"li-ji_ch-6_p-87_s-3","passageId":"li-ji_ch-6_p-87","order":3,"canonicalText":"虹藏不見。","chunks":[["虹藏不見。","zh-Hant"]]},{"id":"li-ji_ch-6_p-88_s-1","passageId":"li-ji_ch-6_p-88","order":1,"canonicalText":"天子居玄堂左个，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉，食黍與彘，其器閎以奄。","chunks":[["天子居玄堂左个，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉，食黍與彘，其器閎以奄。","zh-Hant"]]},{"id":"li-ji_ch-6_p-89_s-1","passageId":"li-ji_ch-6_p-89","order":1,"canonicalText":"是月也，以立冬。","chunks":[["是月也，以立冬。","zh-Hant"]]},{"id":"li-ji_ch-6_p-89_s-2","passageId":"li-ji_ch-6_p-89","order":2,"canonicalText":"先立冬三日，太史謁之天子曰：某日立冬，盛德在水。","chunks":[["先立冬三日，太史謁之天子曰：某日立冬，盛德在水。","zh-Hant"]]},{"id":"li-ji_ch-6_p-89_s-3","passageId":"li-ji_ch-6_p-89","order":3,"canonicalText":"天子乃齊。","chunks":[["天子乃齊。","zh-Hant"]]},{"id":"li-ji_ch-6_p-89_s-4","passageId":"li-ji_ch-6_p-89","order":4,"canonicalText":"立冬之日，天子親帥三公、九卿、大夫以迎冬於北郊，還反，賞死事，恤孤寡。","chunks":[["立冬之日，天子親帥三公、九卿、大夫以迎冬於北郊，還反，賞死事，恤孤寡。","zh-Hant"]]},{"id":"li-ji_ch-6_p-90_s-1","passageId":"li-ji_ch-6_p-90","order":1,"canonicalText":"是月也，命大史釁龜策，占兆審卦吉凶，是察阿黨，則罪無有掩蔽。","chunks":[["是月也，命大史釁龜策，占兆審卦吉凶，是察阿黨，則罪無有掩蔽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-1","passageId":"li-ji_ch-6_p-91","order":1,"canonicalText":"是月也，天子始裘。","chunks":[["是月也，天子始裘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-2","passageId":"li-ji_ch-6_p-91","order":2,"canonicalText":"命有司曰：天氣上騰，地氣下降，天地不通，閉塞而成冬。","chunks":[["命有司曰：天氣上騰，地氣下降，天地不通，閉塞而成冬。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-3","passageId":"li-ji_ch-6_p-91","order":3,"canonicalText":"命百官謹蓋藏。","chunks":[["命百官謹蓋藏。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-4","passageId":"li-ji_ch-6_p-91","order":4,"canonicalText":"命司徒循行積聚，無有不斂。","chunks":[["命司徒循行積聚，無有不斂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-5","passageId":"li-ji_ch-6_p-91","order":5,"canonicalText":"壞城郭，戒門閭，修鍵閉，慎管龠，固封疆，備邊竟，完要塞，謹關梁，塞徯徑。","chunks":[["壞城郭，戒門閭，修鍵閉，慎管龠，固封疆，備邊竟，完要塞，謹關梁，塞徯徑。","zh-Hant"]]},{"id":"li-ji_ch-6_p-91_s-6","passageId":"li-ji_ch-6_p-91","order":6,"canonicalText":"飭喪紀，辨衣裳，審棺槨之厚薄，塋丘壟之大小、高卑、厚薄之度，貴賤之等級。","chunks":[["飭喪紀，辨衣裳，審棺槨之厚薄，塋丘壟之大小、高卑、厚薄之度，貴賤之等級。","zh-Hant"]]},{"id":"li-ji_ch-6_p-92_s-1","passageId":"li-ji_ch-6_p-92","order":1,"canonicalText":"是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心。","chunks":[["是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心。","zh-Hant"]]},{"id":"li-ji_ch-6_p-92_s-2","passageId":"li-ji_ch-6_p-92","order":2,"canonicalText":"必功致為上。","chunks":[["必功致為上。","zh-Hant"]]},{"id":"li-ji_ch-6_p-92_s-3","passageId":"li-ji_ch-6_p-92","order":3,"canonicalText":"物勒工名，以考其誠。","chunks":[["物勒工名，以考其誠。","zh-Hant"]]},{"id":"li-ji_ch-6_p-92_s-4","passageId":"li-ji_ch-6_p-92","order":4,"canonicalText":"功有不當，必行其罪，以窮其情。","chunks":[["功有不當，必行其罪，以窮其情。","zh-Hant"]]},{"id":"li-ji_ch-6_p-93_s-1","passageId":"li-ji_ch-6_p-93","order":1,"canonicalText":"是月也，大飲烝。","chunks":[["是月也，大飲烝。","zh-Hant"]]},{"id":"li-ji_ch-6_p-93_s-2","passageId":"li-ji_ch-6_p-93","order":2,"canonicalText":"天子乃祈來年於天宗，大割祠于公社及門閭。","chunks":[["天子乃祈來年於天宗，大割祠于公社及門閭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-93_s-3","passageId":"li-ji_ch-6_p-93","order":3,"canonicalText":"臘先祖五祀，勞農以休息之。","chunks":[["臘先祖五祀，勞農以休息之。","zh-Hant"]]},{"id":"li-ji_ch-6_p-93_s-4","passageId":"li-ji_ch-6_p-93","order":4,"canonicalText":"天子乃命將帥講武，習射御角力。","chunks":[["天子乃命將帥講武，習射御角力。","zh-Hant"]]},{"id":"li-ji_ch-6_p-94_s-1","passageId":"li-ji_ch-6_p-94","order":1,"canonicalText":"是月也，乃命水虞漁師，收水泉池澤之賦。","chunks":[["是月也，乃命水虞漁師，收水泉池澤之賦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-94_s-2","passageId":"li-ji_ch-6_p-94","order":2,"canonicalText":"毋或敢侵削眾庶兆民，以為天子取怨于下。","chunks":[["毋或敢侵削眾庶兆民，以為天子取怨于下。","zh-Hant"]]},{"id":"li-ji_ch-6_p-94_s-3","passageId":"li-ji_ch-6_p-94","order":3,"canonicalText":"其有若此者，行罪無赦。","chunks":[["其有若此者，行罪無赦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-95_s-1","passageId":"li-ji_ch-6_p-95","order":1,"canonicalText":"孟冬行春令，則凍閉不密，地氣上泄，民多流亡。","chunks":[["孟冬行春令，則凍閉不密，地氣上泄，民多流亡。","zh-Hant"]]},{"id":"li-ji_ch-6_p-95_s-2","passageId":"li-ji_ch-6_p-95","order":2,"canonicalText":"行夏令，則國多暴風，方冬不寒，蟄蟲復出。","chunks":[["行夏令，則國多暴風，方冬不寒，蟄蟲復出。","zh-Hant"]]},{"id":"li-ji_ch-6_p-95_s-3","passageId":"li-ji_ch-6_p-95","order":3,"canonicalText":"行秋令，則雪霜不時，小兵時起，土地侵削。","chunks":[["行秋令，則雪霜不時，小兵時起，土地侵削。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-1","passageId":"li-ji_ch-6_p-96","order":1,"canonicalText":"仲冬之月，日在斗，昏東壁中，旦軫中。","chunks":[["仲冬之月，日在斗，昏東壁中，旦軫中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-2","passageId":"li-ji_ch-6_p-96","order":2,"canonicalText":"其日壬癸。","chunks":[["其日壬癸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-3","passageId":"li-ji_ch-6_p-96","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[["其帝顓頊，其神玄冥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-4","passageId":"li-ji_ch-6_p-96","order":4,"canonicalText":"其蟲介。","chunks":[["其蟲介。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-5","passageId":"li-ji_ch-6_p-96","order":5,"canonicalText":"其音羽，律中黃鍾。","chunks":[["其音羽，律中黃鍾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-6","passageId":"li-ji_ch-6_p-96","order":6,"canonicalText":"其數六。","chunks":[["其數六。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-7","passageId":"li-ji_ch-6_p-96","order":7,"canonicalText":"其味鹹，其臭朽。","chunks":[["其味鹹，其臭朽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-96_s-8","passageId":"li-ji_ch-6_p-96","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[["其祀行，祭先腎。","zh-Hant"]]},{"id":"li-ji_ch-6_p-97_s-1","passageId":"li-ji_ch-6_p-97","order":1,"canonicalText":"冰益壯，地始坼。","chunks":[["冰益壯，地始坼。","zh-Hant"]]},{"id":"li-ji_ch-6_p-97_s-2","passageId":"li-ji_ch-6_p-97","order":2,"canonicalText":"鶡旦不鳴，虎始交。","chunks":[["鶡旦不鳴，虎始交。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-1","passageId":"li-ji_ch-6_p-98","order":1,"canonicalText":"天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","chunks":[["天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-2","passageId":"li-ji_ch-6_p-98","order":2,"canonicalText":"食黍與彘，其器閎以奄。","chunks":[["食黍與彘，其器閎以奄。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-3","passageId":"li-ji_ch-6_p-98","order":3,"canonicalText":"飭死事。","chunks":[["飭死事。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-4","passageId":"li-ji_ch-6_p-98","order":4,"canonicalText":"命有司曰：土事毋作，慎毋發蓋，毋發室屋，及起大眾，以固而閉。","chunks":[["命有司曰：土事毋作，慎毋發蓋，毋發室屋，及起大眾，以固而閉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-5","passageId":"li-ji_ch-6_p-98","order":5,"canonicalText":"地氣且泄，是謂發天地之房，諸蟄則死，民必疾疫，又隨以喪。","chunks":[["地氣且泄，是謂發天地之房，諸蟄則死，民必疾疫，又隨以喪。","zh-Hant"]]},{"id":"li-ji_ch-6_p-98_s-6","passageId":"li-ji_ch-6_p-98","order":6,"canonicalText":"命之曰暢月。","chunks":[["命之曰暢月。","zh-Hant"]]},{"id":"li-ji_ch-6_p-99_s-1","passageId":"li-ji_ch-6_p-99","order":1,"canonicalText":"是月也，命奄尹，申宮令，審門閭，謹房室，必重閉。","chunks":[["是月也，命奄尹，申宮令，審門閭，謹房室，必重閉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-99_s-2","passageId":"li-ji_ch-6_p-99","order":2,"canonicalText":"省婦事毋得淫，雖有貴戚近習，毋有不禁。","chunks":[["省婦事毋得淫，雖有貴戚近習，毋有不禁。","zh-Hant"]]},{"id":"li-ji_ch-6_p-99_s-3","passageId":"li-ji_ch-6_p-99","order":3,"canonicalText":"乃命大酋，秫稻必齊，麴蘗必時，湛熾必潔，水泉必香，陶器必良，火齊必得，兼用六物。","chunks":[["乃命大酋，秫稻必齊，麴蘗必時，湛熾必潔，水泉必香，陶器必良，火齊必得，兼用六物。","zh-Hant"]]},{"id":"li-ji_ch-6_p-99_s-4","passageId":"li-ji_ch-6_p-99","order":4,"canonicalText":"大酋監之，毋有差貸。","chunks":[["大酋監之，毋有差貸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-99_s-5","passageId":"li-ji_ch-6_p-99","order":5,"canonicalText":"天子命有司祈祀四海大川名源淵澤井泉。","chunks":[["天子命有司祈祀四海大川名源淵澤井泉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-100_s-1","passageId":"li-ji_ch-6_p-100","order":1,"canonicalText":"是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰。","chunks":[["是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰。","zh-Hant"]]},{"id":"li-ji_ch-6_p-100_s-2","passageId":"li-ji_ch-6_p-100","order":2,"canonicalText":"山林藪澤，有能取蔬食、田獵禽獸者，野虞教道之；","chunks":[["山林藪澤，有能取蔬食、田獵禽獸者，野虞教道之；","zh-Hant"]]},{"id":"li-ji_ch-6_p-100_s-3","passageId":"li-ji_ch-6_p-100","order":3,"canonicalText":"其有相侵奪者，罪之不赦。","chunks":[["其有相侵奪者，罪之不赦。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-1","passageId":"li-ji_ch-6_p-101","order":1,"canonicalText":"是月也，日短至。","chunks":[["是月也，日短至。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-2","passageId":"li-ji_ch-6_p-101","order":2,"canonicalText":"陰陽爭，諸生蕩。","chunks":[["陰陽爭，諸生蕩。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-3","passageId":"li-ji_ch-6_p-101","order":3,"canonicalText":"君子齊戒，處必掩身。","chunks":[["君子齊戒，處必掩身。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-4","passageId":"li-ji_ch-6_p-101","order":4,"canonicalText":"身欲寧，去聲色，禁耆欲。","chunks":[["身欲寧，去聲色，禁耆欲。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-5","passageId":"li-ji_ch-6_p-101","order":5,"canonicalText":"安形性，事欲靜，以待陰陽之所定。","chunks":[["安形性，事欲靜，以待陰陽之所定。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-6","passageId":"li-ji_ch-6_p-101","order":6,"canonicalText":"蕓始生，荔挺出，蚯螾結，麋角解，水泉動。","chunks":[["蕓始生，荔挺出，蚯螾結，麋角解，水泉動。","zh-Hant"]]},{"id":"li-ji_ch-6_p-101_s-7","passageId":"li-ji_ch-6_p-101","order":7,"canonicalText":"日短至，則伐木，取竹箭。","chunks":[["日短至，則伐木，取竹箭。","zh-Hant"]]},{"id":"li-ji_ch-6_p-102_s-1","passageId":"li-ji_ch-6_p-102","order":1,"canonicalText":"是月也，可以罷官之無事、去器之無用者。","chunks":[["是月也，可以罷官之無事、去器之無用者。","zh-Hant"]]},{"id":"li-ji_ch-6_p-102_s-2","passageId":"li-ji_ch-6_p-102","order":2,"canonicalText":"涂闕廷門閭，筑囹圄，此所以助天地之閉藏也。","chunks":[["涂闕廷門閭，筑囹圄，此所以助天地之閉藏也。","zh-Hant"]]},{"id":"li-ji_ch-6_p-103_s-1","passageId":"li-ji_ch-6_p-103","order":1,"canonicalText":"仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲。","chunks":[["仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲。","zh-Hant"]]},{"id":"li-ji_ch-6_p-103_s-2","passageId":"li-ji_ch-6_p-103","order":2,"canonicalText":"行秋令，則天時雨汁，瓜瓠不成，國有大兵。","chunks":[["行秋令，則天時雨汁，瓜瓠不成，國有大兵。","zh-Hant"]]},{"id":"li-ji_ch-6_p-103_s-3","passageId":"li-ji_ch-6_p-103","order":3,"canonicalText":"行春令，則蝗蟲為敗，水泉咸竭，民多疥癘。","chunks":[["行春令，則蝗蟲為敗，水泉咸竭，民多疥癘。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-1","passageId":"li-ji_ch-6_p-104","order":1,"canonicalText":"季冬之月，日在婺女，昏婁中，旦氐中。","chunks":[["季冬之月，日在婺女，昏婁中，旦氐中。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-2","passageId":"li-ji_ch-6_p-104","order":2,"canonicalText":"其日壬癸。","chunks":[["其日壬癸。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-3","passageId":"li-ji_ch-6_p-104","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[["其帝顓頊，其神玄冥。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-4","passageId":"li-ji_ch-6_p-104","order":4,"canonicalText":"其蟲介。","chunks":[["其蟲介。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-5","passageId":"li-ji_ch-6_p-104","order":5,"canonicalText":"其音羽，律中大呂。","chunks":[["其音羽，律中大呂。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-6","passageId":"li-ji_ch-6_p-104","order":6,"canonicalText":"其數六。","chunks":[["其數六。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-7","passageId":"li-ji_ch-6_p-104","order":7,"canonicalText":"其味鹹，其臭朽。","chunks":[["其味鹹，其臭朽。","zh-Hant"]]},{"id":"li-ji_ch-6_p-104_s-8","passageId":"li-ji_ch-6_p-104","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[["其祀行，祭先腎。","zh-Hant"]]},{"id":"li-ji_ch-6_p-105_s-1","passageId":"li-ji_ch-6_p-105","order":1,"canonicalText":"雁北鄉，鵲始巢。","chunks":[["雁北鄉，鵲始巢。","zh-Hant"]]},{"id":"li-ji_ch-6_p-105_s-2","passageId":"li-ji_ch-6_p-105","order":2,"canonicalText":"雉雊，雞乳。","chunks":[["雉雊，雞乳。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-1","passageId":"li-ji_ch-6_p-106","order":1,"canonicalText":"天子居玄堂右个。","chunks":[["天子居玄堂右个。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-2","passageId":"li-ji_ch-6_p-106","order":2,"canonicalText":"乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","chunks":[["乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-3","passageId":"li-ji_ch-6_p-106","order":3,"canonicalText":"食黍與彘，其器閎以奄。","chunks":[["食黍與彘，其器閎以奄。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-4","passageId":"li-ji_ch-6_p-106","order":4,"canonicalText":"命有司大難，旁磔，出土牛，以送寒氣。","chunks":[["命有司大難，旁磔，出土牛，以送寒氣。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-5","passageId":"li-ji_ch-6_p-106","order":5,"canonicalText":"征鳥厲疾。","chunks":[["征鳥厲疾。","zh-Hant"]]},{"id":"li-ji_ch-6_p-106_s-6","passageId":"li-ji_ch-6_p-106","order":6,"canonicalText":"乃畢山川之祀，及帝之大臣，天子神祇。","chunks":[["乃畢山川之祀，及帝之大臣，天子神祇。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-1","passageId":"li-ji_ch-6_p-107","order":1,"canonicalText":"是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟。","chunks":[["是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-2","passageId":"li-ji_ch-6_p-107","order":2,"canonicalText":"冰方盛，水澤腹堅。","chunks":[["冰方盛，水澤腹堅。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-3","passageId":"li-ji_ch-6_p-107","order":3,"canonicalText":"命取冰，冰以入。","chunks":[["命取冰，冰以入。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-4","passageId":"li-ji_ch-6_p-107","order":4,"canonicalText":"令告民，出五種。","chunks":[["令告民，出五種。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-5","passageId":"li-ji_ch-6_p-107","order":5,"canonicalText":"命農計耦耕事，修耒耜，具田器。","chunks":[["命農計耦耕事，修耒耜，具田器。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-6","passageId":"li-ji_ch-6_p-107","order":6,"canonicalText":"命樂師大合吹而罷。","chunks":[["命樂師大合吹而罷。","zh-Hant"]]},{"id":"li-ji_ch-6_p-107_s-7","passageId":"li-ji_ch-6_p-107","order":7,"canonicalText":"乃命四監收秩薪柴，以共郊廟及百祀之薪燎。","chunks":[["乃命四監收秩薪柴，以共郊廟及百祀之薪燎。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-1","passageId":"li-ji_ch-6_p-108","order":1,"canonicalText":"是月也，日窮於次，月窮於紀，星回於天。","chunks":[["是月也，日窮於次，月窮於紀，星回於天。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-2","passageId":"li-ji_ch-6_p-108","order":2,"canonicalText":"數將幾終，歲且更始。","chunks":[["數將幾終，歲且更始。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-3","passageId":"li-ji_ch-6_p-108","order":3,"canonicalText":"專而農民，毋有所使。","chunks":[["專而農民，毋有所使。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-4","passageId":"li-ji_ch-6_p-108","order":4,"canonicalText":"天子乃與公、卿、大夫，共飭國典，論時令，以待來歲之宜。","chunks":[["天子乃與公、卿、大夫，共飭國典，論時令，以待來歲之宜。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-5","passageId":"li-ji_ch-6_p-108","order":5,"canonicalText":"乃命太史次諸侯之列，賦之犧牲，以共皇天、上帝、社稷之饗。","chunks":[["乃命太史次諸侯之列，賦之犧牲，以共皇天、上帝、社稷之饗。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-6","passageId":"li-ji_ch-6_p-108","order":6,"canonicalText":"乃命同姓之邦，共寢廟之芻豢。","chunks":[["乃命同姓之邦，共寢廟之芻豢。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-7","passageId":"li-ji_ch-6_p-108","order":7,"canonicalText":"命宰歷卿大夫至于庶民土田之數，而賦犧牲，以共山林名川之祀。","chunks":[["命宰歷卿大夫至于庶民土田之數，而賦犧牲，以共山林名川之祀。","zh-Hant"]]},{"id":"li-ji_ch-6_p-108_s-8","passageId":"li-ji_ch-6_p-108","order":8,"canonicalText":"凡在天下九州之民者，無不咸獻其力，以共皇天、上帝、社稷、寢廟、山林、名川之祀。","chunks":[["凡在天下九州之民者，無不咸獻其力，以共皇天、上帝、社稷、寢廟、山林、名川之祀。","zh-Hant"]]},{"id":"li-ji_ch-6_p-109_s-1","passageId":"li-ji_ch-6_p-109","order":1,"canonicalText":"季冬行秋令，則白露早降，介蟲為妖，四鄙入保。","chunks":[["季冬行秋令，則白露早降，介蟲為妖，四鄙入保。","zh-Hant"]]},{"id":"li-ji_ch-6_p-109_s-2","passageId":"li-ji_ch-6_p-109","order":2,"canonicalText":"行春令，則胎夭多傷，國多固疾，命之曰逆。","chunks":[["行春令，則胎夭多傷，國多固疾，命之曰逆。","zh-Hant"]]},{"id":"li-ji_ch-6_p-109_s-3","passageId":"li-ji_ch-6_p-109","order":3,"canonicalText":"行夏令，則水潦敗國，時雪不降，冰凍消釋。","chunks":[["行夏令，則水潦敗國，時雪不降，冰凍消釋。","zh-Hant"]]},{"id":"li-ji_ch-7_p-1_s-1","passageId":"li-ji_ch-7_p-1","order":1,"canonicalText":"曾子問曰：「君薨而世子生，如之何？","chunks":[["曾子問曰：「君薨而世子生，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-1_s-2","passageId":"li-ji_ch-7_p-1","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-1","passageId":"li-ji_ch-7_p-2","order":1,"canonicalText":"孔子曰：「卿、大夫、士從攝主，北面，於西階南。","chunks":[["孔子曰：「卿、大夫、士從攝主，北面，於西階南。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-2","passageId":"li-ji_ch-7_p-2","order":2,"canonicalText":"大祝裨冕，執束帛，升自西階盡等，不升堂，命毋哭。","chunks":[["大祝裨冕，執束帛，升自西階盡等，不升堂，命毋哭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-3","passageId":"li-ji_ch-7_p-2","order":3,"canonicalText":"祝聲三，告曰：『某之子生，敢告。","chunks":[["祝聲三，告曰：『某之子生，敢告。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-4","passageId":"li-ji_ch-7_p-2","order":4,"canonicalText":"』升，奠幣于殯東几上，哭，降。","chunks":[["』升，奠幣于殯東几上，哭，降。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-5","passageId":"li-ji_ch-7_p-2","order":5,"canonicalText":"眾主人、卿、大夫、士，房中，皆哭不踴。","chunks":[["眾主人、卿、大夫、士，房中，皆哭不踴。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-6","passageId":"li-ji_ch-7_p-2","order":6,"canonicalText":"盡一哀，反位。","chunks":[["盡一哀，反位。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-7","passageId":"li-ji_ch-7_p-2","order":7,"canonicalText":"遂朝奠。","chunks":[["遂朝奠。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-8","passageId":"li-ji_ch-7_p-2","order":8,"canonicalText":"小宰升舉幣。","chunks":[["小宰升舉幣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-9","passageId":"li-ji_ch-7_p-2","order":9,"canonicalText":"三日，眾主人、卿、大夫、士，如初位，北面。","chunks":[["三日，眾主人、卿、大夫、士，如初位，北面。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-10","passageId":"li-ji_ch-7_p-2","order":10,"canonicalText":"大宰、大宗、大祝皆裨冕。","chunks":[["大宰、大宗、大祝皆裨冕。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-11","passageId":"li-ji_ch-7_p-2","order":11,"canonicalText":"少師奉子以衰；","chunks":[["少師奉子以衰；","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-12","passageId":"li-ji_ch-7_p-2","order":12,"canonicalText":"祝先，子從，宰宗人從。","chunks":[["祝先，子從，宰宗人從。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-13","passageId":"li-ji_ch-7_p-2","order":13,"canonicalText":"入門，哭者止，子升自西階。","chunks":[["入門，哭者止，子升自西階。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-14","passageId":"li-ji_ch-7_p-2","order":14,"canonicalText":"殯前北面。","chunks":[["殯前北面。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-15","passageId":"li-ji_ch-7_p-2","order":15,"canonicalText":"祝立于殯東南隅。","chunks":[["祝立于殯東南隅。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-16","passageId":"li-ji_ch-7_p-2","order":16,"canonicalText":"祝聲三曰：『某之子某，從執事，敢見。","chunks":[["祝聲三曰：『某之子某，從執事，敢見。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-17","passageId":"li-ji_ch-7_p-2","order":17,"canonicalText":"』子拜稽顙哭。","chunks":[["』子拜稽顙哭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-18","passageId":"li-ji_ch-7_p-2","order":18,"canonicalText":"祝、宰、宗人、眾主人、卿、大夫、士，哭踴三者三，降東反位，皆袒，子踴，房中亦踴三者三。","chunks":[["祝、宰、宗人、眾主人、卿、大夫、士，哭踴三者三，降東反位，皆袒，子踴，房中亦踴三者三。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-19","passageId":"li-ji_ch-7_p-2","order":19,"canonicalText":"襲衰，杖，奠出。","chunks":[["襲衰，杖，奠出。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-20","passageId":"li-ji_ch-7_p-2","order":20,"canonicalText":"大宰命祝史，以名遍告于五祀山川。","chunks":[["大宰命祝史，以名遍告于五祀山川。","zh-Hant"]]},{"id":"li-ji_ch-7_p-2_s-21","passageId":"li-ji_ch-7_p-2","order":21,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-3_s-1","passageId":"li-ji_ch-7_p-3","order":1,"canonicalText":"曾子問曰：「如已葬而世子生，則如之何？","chunks":[["曾子問曰：「如已葬而世子生，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-3_s-2","passageId":"li-ji_ch-7_p-3","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-4_s-1","passageId":"li-ji_ch-7_p-4","order":1,"canonicalText":"孔子曰：「大宰、大宗從大祝而告于禰。","chunks":[["孔子曰：「大宰、大宗從大祝而告于禰。","zh-Hant"]]},{"id":"li-ji_ch-7_p-4_s-2","passageId":"li-ji_ch-7_p-4","order":2,"canonicalText":"三月，乃名于禰，以名遍告及社稷宗廟山川。","chunks":[["三月，乃名于禰，以名遍告及社稷宗廟山川。","zh-Hant"]]},{"id":"li-ji_ch-7_p-4_s-3","passageId":"li-ji_ch-7_p-4","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-1","passageId":"li-ji_ch-7_p-5","order":1,"canonicalText":"孔子曰：「諸侯適天子，必告于祖，奠于禰。","chunks":[["孔子曰：「諸侯適天子，必告于祖，奠于禰。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-2","passageId":"li-ji_ch-7_p-5","order":2,"canonicalText":"冕而出視朝，命祝史告於社稷、宗廟、山川。","chunks":[["冕而出視朝，命祝史告於社稷、宗廟、山川。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-3","passageId":"li-ji_ch-7_p-5","order":3,"canonicalText":"乃命國家五官而後行，道而出。","chunks":[["乃命國家五官而後行，道而出。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-4","passageId":"li-ji_ch-7_p-5","order":4,"canonicalText":"告者，五日而遍，過是，非禮也。","chunks":[["告者，五日而遍，過是，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-5","passageId":"li-ji_ch-7_p-5","order":5,"canonicalText":"凡告，用牲幣。","chunks":[["凡告，用牲幣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-6","passageId":"li-ji_ch-7_p-5","order":6,"canonicalText":"反，亦如之。","chunks":[["反，亦如之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-7","passageId":"li-ji_ch-7_p-5","order":7,"canonicalText":"諸侯相見，必告于禰，朝服而出視朝。","chunks":[["諸侯相見，必告于禰，朝服而出視朝。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-8","passageId":"li-ji_ch-7_p-5","order":8,"canonicalText":"命祝史告于五廟所過山川。","chunks":[["命祝史告于五廟所過山川。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-9","passageId":"li-ji_ch-7_p-5","order":9,"canonicalText":"亦命國家五官，道而出。","chunks":[["亦命國家五官，道而出。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-10","passageId":"li-ji_ch-7_p-5","order":10,"canonicalText":"反，必親告于祖禰。","chunks":[["反，必親告于祖禰。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-11","passageId":"li-ji_ch-7_p-5","order":11,"canonicalText":"乃命祝史告至于前所告者，而後聽朝而入。","chunks":[["乃命祝史告至于前所告者，而後聽朝而入。","zh-Hant"]]},{"id":"li-ji_ch-7_p-5_s-12","passageId":"li-ji_ch-7_p-5","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-6_s-1","passageId":"li-ji_ch-7_p-6","order":1,"canonicalText":"曾子問曰：「并有喪，如之何？","chunks":[["曾子問曰：「并有喪，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-6_s-2","passageId":"li-ji_ch-7_p-6","order":2,"canonicalText":"何先何後？","chunks":[["何先何後？","zh-Hant"]]},{"id":"li-ji_ch-7_p-6_s-3","passageId":"li-ji_ch-7_p-6","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-1","passageId":"li-ji_ch-7_p-7","order":1,"canonicalText":"孔子曰：「葬，先輕而後重；","chunks":[["孔子曰：「葬，先輕而後重；","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-2","passageId":"li-ji_ch-7_p-7","order":2,"canonicalText":"其奠也，先重而後輕；","chunks":[["其奠也，先重而後輕；","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-3","passageId":"li-ji_ch-7_p-7","order":3,"canonicalText":"禮也。","chunks":[["禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-4","passageId":"li-ji_ch-7_p-7","order":4,"canonicalText":"自啟及葬，不奠，行葬不哀次；","chunks":[["自啟及葬，不奠，行葬不哀次；","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-5","passageId":"li-ji_ch-7_p-7","order":5,"canonicalText":"反葬奠，而後辭於殯，逐修葬事。","chunks":[["反葬奠，而後辭於殯，逐修葬事。","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-6","passageId":"li-ji_ch-7_p-7","order":6,"canonicalText":"其虞也，先重而後輕，禮也。","chunks":[["其虞也，先重而後輕，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-7_s-7","passageId":"li-ji_ch-7_p-7","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-8_s-1","passageId":"li-ji_ch-7_p-8","order":1,"canonicalText":"孔子曰：「宗子雖七十，無無主婦；","chunks":[["孔子曰：「宗子雖七十，無無主婦；","zh-Hant"]]},{"id":"li-ji_ch-7_p-8_s-2","passageId":"li-ji_ch-7_p-8","order":2,"canonicalText":"非宗子，雖無主婦可也。","chunks":[["非宗子，雖無主婦可也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-8_s-3","passageId":"li-ji_ch-7_p-8","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-9_s-1","passageId":"li-ji_ch-7_p-9","order":1,"canonicalText":"曾子問曰：「將冠子，冠者至，揖讓而入，聞齊衰大功之喪，如之何？","chunks":[["曾子問曰：「將冠子，冠者至，揖讓而入，聞齊衰大功之喪，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-9_s-2","passageId":"li-ji_ch-7_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-10_s-1","passageId":"li-ji_ch-7_p-10","order":1,"canonicalText":"孔子曰：「內喪則廢，外喪則冠而不醴，徹饌而掃，即位而哭。","chunks":[["孔子曰：「內喪則廢，外喪則冠而不醴，徹饌而掃，即位而哭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-10_s-2","passageId":"li-ji_ch-7_p-10","order":2,"canonicalText":"如冠者未至，則廢。","chunks":[["如冠者未至，則廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-10_s-3","passageId":"li-ji_ch-7_p-10","order":3,"canonicalText":"如將冠子而未及期日，而有齊衰、大功、小功之喪，則因喪服而冠。","chunks":[["如將冠子而未及期日，而有齊衰、大功、小功之喪，則因喪服而冠。","zh-Hant"]]},{"id":"li-ji_ch-7_p-10_s-4","passageId":"li-ji_ch-7_p-10","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-11_s-1","passageId":"li-ji_ch-7_p-11","order":1,"canonicalText":"「除喪不改冠乎？","chunks":[["「除喪不改冠乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-11_s-2","passageId":"li-ji_ch-7_p-11","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-12_s-1","passageId":"li-ji_ch-7_p-12","order":1,"canonicalText":"孔子曰：「天子賜諸侯大夫冕弁服於大廟，歸設奠，服賜服，於斯乎有冠醮，無冠醴。","chunks":[["孔子曰：「天子賜諸侯大夫冕弁服於大廟，歸設奠，服賜服，於斯乎有冠醮，無冠醴。","zh-Hant"]]},{"id":"li-ji_ch-7_p-12_s-2","passageId":"li-ji_ch-7_p-12","order":2,"canonicalText":"父沒而冠，則已冠掃地而祭於禰；","chunks":[["父沒而冠，則已冠掃地而祭於禰；","zh-Hant"]]},{"id":"li-ji_ch-7_p-12_s-3","passageId":"li-ji_ch-7_p-12","order":3,"canonicalText":"已祭，而見伯父、叔父，而後饗冠者。","chunks":[["已祭，而見伯父、叔父，而後饗冠者。","zh-Hant"]]},{"id":"li-ji_ch-7_p-12_s-4","passageId":"li-ji_ch-7_p-12","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-13_s-1","passageId":"li-ji_ch-7_p-13","order":1,"canonicalText":"曾子問曰：「祭如之何則不行旅酬之事矣？","chunks":[["曾子問曰：「祭如之何則不行旅酬之事矣？","zh-Hant"]]},{"id":"li-ji_ch-7_p-13_s-2","passageId":"li-ji_ch-7_p-13","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-14_s-1","passageId":"li-ji_ch-7_p-14","order":1,"canonicalText":"孔子曰：「聞之：小祥者，主人練祭而不旅，奠酬於賓，賓弗舉，禮也。","chunks":[["孔子曰：「聞之：小祥者，主人練祭而不旅，奠酬於賓，賓弗舉，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-14_s-2","passageId":"li-ji_ch-7_p-14","order":2,"canonicalText":"昔者，魯昭公練而舉酬行旅，非禮也；","chunks":[["昔者，魯昭公練而舉酬行旅，非禮也；","zh-Hant"]]},{"id":"li-ji_ch-7_p-14_s-3","passageId":"li-ji_ch-7_p-14","order":3,"canonicalText":"孝公大祥，奠酬弗舉，亦非禮也。","chunks":[["孝公大祥，奠酬弗舉，亦非禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-14_s-4","passageId":"li-ji_ch-7_p-14","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-15_s-1","passageId":"li-ji_ch-7_p-15","order":1,"canonicalText":"曾子問曰：「大功之喪，可以與於饋奠之事乎？","chunks":[["曾子問曰：「大功之喪，可以與於饋奠之事乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-15_s-2","passageId":"li-ji_ch-7_p-15","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-16_s-1","passageId":"li-ji_ch-7_p-16","order":1,"canonicalText":"孔子曰：「豈大功耳！","chunks":[["孔子曰：「豈大功耳！","zh-Hant"]]},{"id":"li-ji_ch-7_p-16_s-2","passageId":"li-ji_ch-7_p-16","order":2,"canonicalText":"自斬衰以下皆可，禮也。","chunks":[["自斬衰以下皆可，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-16_s-3","passageId":"li-ji_ch-7_p-16","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-17_s-1","passageId":"li-ji_ch-7_p-17","order":1,"canonicalText":"曾子曰：「不以輕服而重相為乎？","chunks":[["曾子曰：「不以輕服而重相為乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-17_s-2","passageId":"li-ji_ch-7_p-17","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-1","passageId":"li-ji_ch-7_p-18","order":1,"canonicalText":"孔子曰：「非此之謂也。","chunks":[["孔子曰：「非此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-2","passageId":"li-ji_ch-7_p-18","order":2,"canonicalText":"天子、諸侯之喪，斬衰者奠；","chunks":[["天子、諸侯之喪，斬衰者奠；","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-3","passageId":"li-ji_ch-7_p-18","order":3,"canonicalText":"大夫，齊衰者奠；","chunks":[["大夫，齊衰者奠；","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-4","passageId":"li-ji_ch-7_p-18","order":4,"canonicalText":"士則朋友奠；","chunks":[["士則朋友奠；","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-5","passageId":"li-ji_ch-7_p-18","order":5,"canonicalText":"不足，則取於大功以下者；","chunks":[["不足，則取於大功以下者；","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-6","passageId":"li-ji_ch-7_p-18","order":6,"canonicalText":"不足，則反之。","chunks":[["不足，則反之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-18_s-7","passageId":"li-ji_ch-7_p-18","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-19_s-1","passageId":"li-ji_ch-7_p-19","order":1,"canonicalText":"曾子問曰：「小功可以與於祭乎？","chunks":[["曾子問曰：「小功可以與於祭乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-19_s-2","passageId":"li-ji_ch-7_p-19","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-20_s-1","passageId":"li-ji_ch-7_p-20","order":1,"canonicalText":"孔子曰：「何必小功耳！","chunks":[["孔子曰：「何必小功耳！","zh-Hant"]]},{"id":"li-ji_ch-7_p-20_s-2","passageId":"li-ji_ch-7_p-20","order":2,"canonicalText":"自斬衰以下與祭，禮也。","chunks":[["自斬衰以下與祭，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-20_s-3","passageId":"li-ji_ch-7_p-20","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-21_s-1","passageId":"li-ji_ch-7_p-21","order":1,"canonicalText":"曾子曰：「不以輕喪而重祭乎？","chunks":[["曾子曰：「不以輕喪而重祭乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-21_s-2","passageId":"li-ji_ch-7_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-22_s-1","passageId":"li-ji_ch-7_p-22","order":1,"canonicalText":"孔子曰：「天子、諸侯之喪祭也，不斬衰者不與祭；","chunks":[["孔子曰：「天子、諸侯之喪祭也，不斬衰者不與祭；","zh-Hant"]]},{"id":"li-ji_ch-7_p-22_s-2","passageId":"li-ji_ch-7_p-22","order":2,"canonicalText":"大夫，齊衰者與祭；","chunks":[["大夫，齊衰者與祭；","zh-Hant"]]},{"id":"li-ji_ch-7_p-22_s-3","passageId":"li-ji_ch-7_p-22","order":3,"canonicalText":"士，祭不足，則取於兄弟大功以下者。","chunks":[["士，祭不足，則取於兄弟大功以下者。","zh-Hant"]]},{"id":"li-ji_ch-7_p-22_s-4","passageId":"li-ji_ch-7_p-22","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-23_s-1","passageId":"li-ji_ch-7_p-23","order":1,"canonicalText":"曾子問曰：「相識，有喪服可以與於祭乎？","chunks":[["曾子問曰：「相識，有喪服可以與於祭乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-23_s-2","passageId":"li-ji_ch-7_p-23","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-24_s-1","passageId":"li-ji_ch-7_p-24","order":1,"canonicalText":"孔子曰：「緦不祭，又何助於人。","chunks":[["孔子曰：「緦不祭，又何助於人。","zh-Hant"]]},{"id":"li-ji_ch-7_p-24_s-2","passageId":"li-ji_ch-7_p-24","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-25_s-1","passageId":"li-ji_ch-7_p-25","order":1,"canonicalText":"曾子問曰：「廢喪服，可以與於饋奠之事乎？","chunks":[["曾子問曰：「廢喪服，可以與於饋奠之事乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-25_s-2","passageId":"li-ji_ch-7_p-25","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-26_s-1","passageId":"li-ji_ch-7_p-26","order":1,"canonicalText":"孔子曰：「說衰與奠，非禮也；","chunks":[["孔子曰：「說衰與奠，非禮也；","zh-Hant"]]},{"id":"li-ji_ch-7_p-26_s-2","passageId":"li-ji_ch-7_p-26","order":2,"canonicalText":"以擯相可也。","chunks":[["以擯相可也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-26_s-3","passageId":"li-ji_ch-7_p-26","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-27_s-1","passageId":"li-ji_ch-7_p-27","order":1,"canonicalText":"曾子問曰：「昏禮既納幣，有吉日，女之父母死，則如之何？","chunks":[["曾子問曰：「昏禮既納幣，有吉日，女之父母死，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-27_s-2","passageId":"li-ji_ch-7_p-27","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-1","passageId":"li-ji_ch-7_p-28","order":1,"canonicalText":"孔子曰：「婿使人吊。","chunks":[["孔子曰：「婿使人吊。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-2","passageId":"li-ji_ch-7_p-28","order":2,"canonicalText":"如婿之父母死，則女之家亦使人吊。","chunks":[["如婿之父母死，則女之家亦使人吊。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-3","passageId":"li-ji_ch-7_p-28","order":3,"canonicalText":"父喪稱父，母喪稱母。","chunks":[["父喪稱父，母喪稱母。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-4","passageId":"li-ji_ch-7_p-28","order":4,"canonicalText":"父母不在，則稱伯父世母。","chunks":[["父母不在，則稱伯父世母。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-5","passageId":"li-ji_ch-7_p-28","order":5,"canonicalText":"婿，已葬，婿之伯父致命女氏曰：『某之子有父母之喪，不得嗣為兄弟，使某致命。","chunks":[["婿，已葬，婿之伯父致命女氏曰：『某之子有父母之喪，不得嗣為兄弟，使某致命。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-6","passageId":"li-ji_ch-7_p-28","order":6,"canonicalText":"』女氏許諾，而弗敢嫁，禮也。","chunks":[["』女氏許諾，而弗敢嫁，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-7","passageId":"li-ji_ch-7_p-28","order":7,"canonicalText":"婿，免喪，女之父母使人請，婿弗取，而後嫁之，禮也。","chunks":[["婿，免喪，女之父母使人請，婿弗取，而後嫁之，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-8","passageId":"li-ji_ch-7_p-28","order":8,"canonicalText":"女之父母死，婿亦如之。","chunks":[["女之父母死，婿亦如之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-28_s-9","passageId":"li-ji_ch-7_p-28","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-29_s-1","passageId":"li-ji_ch-7_p-29","order":1,"canonicalText":"曾子問曰：「親迎，女在涂，而婿之父母死，如之何？","chunks":[["曾子問曰：「親迎，女在涂，而婿之父母死，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-29_s-2","passageId":"li-ji_ch-7_p-29","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-30_s-1","passageId":"li-ji_ch-7_p-30","order":1,"canonicalText":"孔子曰：「女改服布深衣，縞總以趨喪。","chunks":[["孔子曰：「女改服布深衣，縞總以趨喪。","zh-Hant"]]},{"id":"li-ji_ch-7_p-30_s-2","passageId":"li-ji_ch-7_p-30","order":2,"canonicalText":"女在途，而女之父母死，則女反。","chunks":[["女在途，而女之父母死，則女反。","zh-Hant"]]},{"id":"li-ji_ch-7_p-30_s-3","passageId":"li-ji_ch-7_p-30","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-31_s-1","passageId":"li-ji_ch-7_p-31","order":1,"canonicalText":"「如婿親迎，女未至，而有齊衰大功之喪，則如之何？","chunks":[["「如婿親迎，女未至，而有齊衰大功之喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-31_s-2","passageId":"li-ji_ch-7_p-31","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-32_s-1","passageId":"li-ji_ch-7_p-32","order":1,"canonicalText":"孔子曰：「男不入，改服於外次；","chunks":[["孔子曰：「男不入，改服於外次；","zh-Hant"]]},{"id":"li-ji_ch-7_p-32_s-2","passageId":"li-ji_ch-7_p-32","order":2,"canonicalText":"女入，改服於內次；","chunks":[["女入，改服於內次；","zh-Hant"]]},{"id":"li-ji_ch-7_p-32_s-3","passageId":"li-ji_ch-7_p-32","order":3,"canonicalText":"然後即位而哭。","chunks":[["然後即位而哭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-32_s-4","passageId":"li-ji_ch-7_p-32","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-33_s-1","passageId":"li-ji_ch-7_p-33","order":1,"canonicalText":"曾子問曰：「除喪則不復昏禮乎？","chunks":[["曾子問曰：「除喪則不復昏禮乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-33_s-2","passageId":"li-ji_ch-7_p-33","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-34_s-1","passageId":"li-ji_ch-7_p-34","order":1,"canonicalText":"孔子曰：「祭，過時不祭，禮也；","chunks":[["孔子曰：「祭，過時不祭，禮也；","zh-Hant"]]},{"id":"li-ji_ch-7_p-34_s-2","passageId":"li-ji_ch-7_p-34","order":2,"canonicalText":"又何反於初？","chunks":[["又何反於初？","zh-Hant"]]},{"id":"li-ji_ch-7_p-34_s-3","passageId":"li-ji_ch-7_p-34","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-35_s-1","passageId":"li-ji_ch-7_p-35","order":1,"canonicalText":"孔子曰：「嫁女之家，三夜不息燭，思相離也。","chunks":[["孔子曰：「嫁女之家，三夜不息燭，思相離也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-35_s-2","passageId":"li-ji_ch-7_p-35","order":2,"canonicalText":"取婦之家，三日不舉樂，思嗣親也。","chunks":[["取婦之家，三日不舉樂，思嗣親也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-35_s-3","passageId":"li-ji_ch-7_p-35","order":3,"canonicalText":"三月而廟見，稱來婦也。","chunks":[["三月而廟見，稱來婦也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-35_s-4","passageId":"li-ji_ch-7_p-35","order":4,"canonicalText":"擇日而祭於禰，成婦之義也。","chunks":[["擇日而祭於禰，成婦之義也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-35_s-5","passageId":"li-ji_ch-7_p-35","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-36_s-1","passageId":"li-ji_ch-7_p-36","order":1,"canonicalText":"曾子問曰：「女未廟見而死，則如之何？","chunks":[["曾子問曰：「女未廟見而死，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-36_s-2","passageId":"li-ji_ch-7_p-36","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-37_s-1","passageId":"li-ji_ch-7_p-37","order":1,"canonicalText":"孔子曰：「不遷於祖，不祔於皇姑，婿不杖、不菲、不次，歸葬于女氏之黨，示未成婦也。","chunks":[["孔子曰：「不遷於祖，不祔於皇姑，婿不杖、不菲、不次，歸葬于女氏之黨，示未成婦也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-37_s-2","passageId":"li-ji_ch-7_p-37","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-38_s-1","passageId":"li-ji_ch-7_p-38","order":1,"canonicalText":"曾子問曰：「取女，有吉日而女死，如之何？","chunks":[["曾子問曰：「取女，有吉日而女死，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-38_s-2","passageId":"li-ji_ch-7_p-38","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-39_s-1","passageId":"li-ji_ch-7_p-39","order":1,"canonicalText":"孔子曰：「婿齊衰而吊，既葬而除之。","chunks":[["孔子曰：「婿齊衰而吊，既葬而除之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-39_s-2","passageId":"li-ji_ch-7_p-39","order":2,"canonicalText":"夫死亦如之。","chunks":[["夫死亦如之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-39_s-3","passageId":"li-ji_ch-7_p-39","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-40_s-1","passageId":"li-ji_ch-7_p-40","order":1,"canonicalText":"曾子問曰：「喪有二孤，廟有二主，禮與？","chunks":[["曾子問曰：「喪有二孤，廟有二主，禮與？","zh-Hant"]]},{"id":"li-ji_ch-7_p-40_s-2","passageId":"li-ji_ch-7_p-40","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-1","passageId":"li-ji_ch-7_p-41","order":1,"canonicalText":"孔子曰：「天無二日，土無二王，嘗禘郊社，尊無二上。","chunks":[["孔子曰：「天無二日，土無二王，嘗禘郊社，尊無二上。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-2","passageId":"li-ji_ch-7_p-41","order":2,"canonicalText":"未知其為禮也。","chunks":[["未知其為禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-3","passageId":"li-ji_ch-7_p-41","order":3,"canonicalText":"昔者齊桓公亟舉兵，作偽主以行。","chunks":[["昔者齊桓公亟舉兵，作偽主以行。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-4","passageId":"li-ji_ch-7_p-41","order":4,"canonicalText":"及反，藏諸祖廟。","chunks":[["及反，藏諸祖廟。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-5","passageId":"li-ji_ch-7_p-41","order":5,"canonicalText":"廟有二主，自桓公始也。","chunks":[["廟有二主，自桓公始也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-6","passageId":"li-ji_ch-7_p-41","order":6,"canonicalText":"喪之二孤，則昔者衛靈公適魯，遭季桓子之喪，衛君請吊，哀公辭不得命，公為主，客人吊。","chunks":[["喪之二孤，則昔者衛靈公適魯，遭季桓子之喪，衛君請吊，哀公辭不得命，公為主，客人吊。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-7","passageId":"li-ji_ch-7_p-41","order":7,"canonicalText":"康子立於門右，北面；","chunks":[["康子立於門右，北面；","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-8","passageId":"li-ji_ch-7_p-41","order":8,"canonicalText":"公揖讓升自東階，西鄉；","chunks":[["公揖讓升自東階，西鄉；","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-9","passageId":"li-ji_ch-7_p-41","order":9,"canonicalText":"客升自西階吊。","chunks":[["客升自西階吊。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-10","passageId":"li-ji_ch-7_p-41","order":10,"canonicalText":"公拜，興，哭；","chunks":[["公拜，興，哭；","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-11","passageId":"li-ji_ch-7_p-41","order":11,"canonicalText":"康子拜稽顙於位，有司弗辯也。","chunks":[["康子拜稽顙於位，有司弗辯也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-12","passageId":"li-ji_ch-7_p-41","order":12,"canonicalText":"今之二孤，自季康子之過也。","chunks":[["今之二孤，自季康子之過也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-41_s-13","passageId":"li-ji_ch-7_p-41","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-42_s-1","passageId":"li-ji_ch-7_p-42","order":1,"canonicalText":"曾子問曰：「古者師行，必以遷廟主行乎？","chunks":[["曾子問曰：「古者師行，必以遷廟主行乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-42_s-2","passageId":"li-ji_ch-7_p-42","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-1","passageId":"li-ji_ch-7_p-43","order":1,"canonicalText":"孔子曰：「天子巡守，以遷廟主行，載于齊車，言必有尊也。","chunks":[["孔子曰：「天子巡守，以遷廟主行，載于齊車，言必有尊也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-2","passageId":"li-ji_ch-7_p-43","order":2,"canonicalText":"今也取七廟之主以行，則失之矣。","chunks":[["今也取七廟之主以行，則失之矣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-3","passageId":"li-ji_ch-7_p-43","order":3,"canonicalText":"當七廟、五廟無虛主；","chunks":[["當七廟、五廟無虛主；","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-4","passageId":"li-ji_ch-7_p-43","order":4,"canonicalText":"虛主者，唯天子崩，諸侯薨與去其國，與祫祭於祖，為無主耳。","chunks":[["虛主者，唯天子崩，諸侯薨與去其國，與祫祭於祖，為無主耳。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-5","passageId":"li-ji_ch-7_p-43","order":5,"canonicalText":"吾聞諸老聃曰：天子崩，國君薨，則祝取群廟之主而藏諸祖廟，禮也。","chunks":[["吾聞諸老聃曰：天子崩，國君薨，則祝取群廟之主而藏諸祖廟，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-6","passageId":"li-ji_ch-7_p-43","order":6,"canonicalText":"卒哭成事而後，主各反其廟。","chunks":[["卒哭成事而後，主各反其廟。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-7","passageId":"li-ji_ch-7_p-43","order":7,"canonicalText":"君去其國，大宰取群廟之主以從，禮也。","chunks":[["君去其國，大宰取群廟之主以從，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-8","passageId":"li-ji_ch-7_p-43","order":8,"canonicalText":"祫祭於祖，則祝迎四廟之主。","chunks":[["祫祭於祖，則祝迎四廟之主。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-9","passageId":"li-ji_ch-7_p-43","order":9,"canonicalText":"主，出廟入廟必蹕；","chunks":[["主，出廟入廟必蹕；","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-10","passageId":"li-ji_ch-7_p-43","order":10,"canonicalText":"老聃云。","chunks":[["老聃云。","zh-Hant"]]},{"id":"li-ji_ch-7_p-43_s-11","passageId":"li-ji_ch-7_p-43","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-44_s-1","passageId":"li-ji_ch-7_p-44","order":1,"canonicalText":"曾子問曰：「古者師行，無遷主，則何主？","chunks":[["曾子問曰：「古者師行，無遷主，則何主？","zh-Hant"]]},{"id":"li-ji_ch-7_p-44_s-2","passageId":"li-ji_ch-7_p-44","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-45_s-1","passageId":"li-ji_ch-7_p-45","order":1,"canonicalText":"孔子曰：「主命。","chunks":[["孔子曰：「主命。","zh-Hant"]]},{"id":"li-ji_ch-7_p-45_s-2","passageId":"li-ji_ch-7_p-45","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-46_s-1","passageId":"li-ji_ch-7_p-46","order":1,"canonicalText":"問曰：「何謂也？","chunks":[["問曰：「何謂也？","zh-Hant"]]},{"id":"li-ji_ch-7_p-46_s-2","passageId":"li-ji_ch-7_p-46","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-47_s-1","passageId":"li-ji_ch-7_p-47","order":1,"canonicalText":"孔子曰：「天子、諸侯將出，必以幣帛皮圭告于祖禰，遂奉以出，載于齊車以行。","chunks":[["孔子曰：「天子、諸侯將出，必以幣帛皮圭告于祖禰，遂奉以出，載于齊車以行。","zh-Hant"]]},{"id":"li-ji_ch-7_p-47_s-2","passageId":"li-ji_ch-7_p-47","order":2,"canonicalText":"每舍，奠焉而後就舍。","chunks":[["每舍，奠焉而後就舍。","zh-Hant"]]},{"id":"li-ji_ch-7_p-47_s-3","passageId":"li-ji_ch-7_p-47","order":3,"canonicalText":"反必告，設奠卒，斂幣玉，藏諸兩階之間，乃出。","chunks":[["反必告，設奠卒，斂幣玉，藏諸兩階之間，乃出。","zh-Hant"]]},{"id":"li-ji_ch-7_p-47_s-4","passageId":"li-ji_ch-7_p-47","order":4,"canonicalText":"蓋貴命也。","chunks":[["蓋貴命也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-47_s-5","passageId":"li-ji_ch-7_p-47","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-48_s-1","passageId":"li-ji_ch-7_p-48","order":1,"canonicalText":"子游問曰：「喪慈母如母，禮與？","chunks":[["子游問曰：「喪慈母如母，禮與？","zh-Hant"]]},{"id":"li-ji_ch-7_p-48_s-2","passageId":"li-ji_ch-7_p-48","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-1","passageId":"li-ji_ch-7_p-49","order":1,"canonicalText":"孔子曰：「非禮也。","chunks":[["孔子曰：「非禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-2","passageId":"li-ji_ch-7_p-49","order":2,"canonicalText":"古者，男子外有傅，內有慈母，君命所使教子也，何服之有？","chunks":[["古者，男子外有傅，內有慈母，君命所使教子也，何服之有？","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-3","passageId":"li-ji_ch-7_p-49","order":3,"canonicalText":"昔者，魯昭公少喪其母，有慈母良，及其死也，公弗忍也，欲喪之，有司以聞，曰：『古之禮，慈母無服，今也君為之服，是逆古之禮而亂國法也；","chunks":[["昔者，魯昭公少喪其母，有慈母良，及其死也，公弗忍也，欲喪之，有司以聞，曰：『古之禮，慈母無服，今也君為之服，是逆古之禮而亂國法也；","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-4","passageId":"li-ji_ch-7_p-49","order":4,"canonicalText":"若終行之，則有司將書之以遺後世。","chunks":[["若終行之，則有司將書之以遺後世。","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-5","passageId":"li-ji_ch-7_p-49","order":5,"canonicalText":"無乃不可乎！","chunks":[["無乃不可乎！","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-6","passageId":"li-ji_ch-7_p-49","order":6,"canonicalText":"』公曰：『古者天子練冠以燕居。","chunks":[["』公曰：『古者天子練冠以燕居。","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-7","passageId":"li-ji_ch-7_p-49","order":7,"canonicalText":"』公弗忍也，遂練冠以喪慈母。","chunks":[["』公弗忍也，遂練冠以喪慈母。","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-8","passageId":"li-ji_ch-7_p-49","order":8,"canonicalText":"喪慈母，自魯昭公始也。","chunks":[["喪慈母，自魯昭公始也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-49_s-9","passageId":"li-ji_ch-7_p-49","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-50_s-1","passageId":"li-ji_ch-7_p-50","order":1,"canonicalText":"曾子問曰：「諸侯旅見天子，入門，不得終禮，廢者幾？","chunks":[["曾子問曰：「諸侯旅見天子，入門，不得終禮，廢者幾？","zh-Hant"]]},{"id":"li-ji_ch-7_p-50_s-2","passageId":"li-ji_ch-7_p-50","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-1","passageId":"li-ji_ch-7_p-51","order":1,"canonicalText":"孔子曰：「四。","chunks":[["孔子曰：「四。","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-2","passageId":"li-ji_ch-7_p-51","order":2,"canonicalText":"」請問之。","chunks":[["」請問之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-3","passageId":"li-ji_ch-7_p-51","order":3,"canonicalText":"曰：「大廟火，日食，後之喪，雨沾服失容，則廢。","chunks":[["曰：「大廟火，日食，後之喪，雨沾服失容，則廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-4","passageId":"li-ji_ch-7_p-51","order":4,"canonicalText":"如諸侯皆在而日食，則從天子救日，各以其方色與其兵。","chunks":[["如諸侯皆在而日食，則從天子救日，各以其方色與其兵。","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-5","passageId":"li-ji_ch-7_p-51","order":5,"canonicalText":"大廟火，則從天子救火，不以方色與兵。","chunks":[["大廟火，則從天子救火，不以方色與兵。","zh-Hant"]]},{"id":"li-ji_ch-7_p-51_s-6","passageId":"li-ji_ch-7_p-51","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-52_s-1","passageId":"li-ji_ch-7_p-52","order":1,"canonicalText":"曾子問曰：「諸侯相見，揖讓入門，不得終禮，廢者幾？","chunks":[["曾子問曰：「諸侯相見，揖讓入門，不得終禮，廢者幾？","zh-Hant"]]},{"id":"li-ji_ch-7_p-52_s-2","passageId":"li-ji_ch-7_p-52","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-53_s-1","passageId":"li-ji_ch-7_p-53","order":1,"canonicalText":"孔子曰：「六。","chunks":[["孔子曰：「六。","zh-Hant"]]},{"id":"li-ji_ch-7_p-53_s-2","passageId":"li-ji_ch-7_p-53","order":2,"canonicalText":"」請問之。","chunks":[["」請問之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-53_s-3","passageId":"li-ji_ch-7_p-53","order":3,"canonicalText":"曰：「天子崩，大廟火，日食，後夫人之喪，雨沾服失容，則廢。","chunks":[["曰：「天子崩，大廟火，日食，後夫人之喪，雨沾服失容，則廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-53_s-4","passageId":"li-ji_ch-7_p-53","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-54_s-1","passageId":"li-ji_ch-7_p-54","order":1,"canonicalText":"曾子問曰：「天子嘗禘郊社五祀之祭，簠簋既陳，天子崩，後之喪，如之何？","chunks":[["曾子問曰：「天子嘗禘郊社五祀之祭，簠簋既陳，天子崩，後之喪，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-54_s-2","passageId":"li-ji_ch-7_p-54","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-1","passageId":"li-ji_ch-7_p-55","order":1,"canonicalText":"孔子曰：「廢。","chunks":[["孔子曰：「廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-2","passageId":"li-ji_ch-7_p-55","order":2,"canonicalText":"」曾子問曰：「當祭而日食，太廟火，其祭也如之何？","chunks":[["」曾子問曰：「當祭而日食，太廟火，其祭也如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-3","passageId":"li-ji_ch-7_p-55","order":3,"canonicalText":"」孔子曰：「接祭而已矣。","chunks":[["」孔子曰：「接祭而已矣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-4","passageId":"li-ji_ch-7_p-55","order":4,"canonicalText":"如牲至，未殺，則廢。","chunks":[["如牲至，未殺，則廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-5","passageId":"li-ji_ch-7_p-55","order":5,"canonicalText":"天子崩，未殯，五祀之祭不行；","chunks":[["天子崩，未殯，五祀之祭不行；","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-6","passageId":"li-ji_ch-7_p-55","order":6,"canonicalText":"既殯而祭，其祭也，尸入，三飯不侑，酳不酢而已矣。","chunks":[["既殯而祭，其祭也，尸入，三飯不侑，酳不酢而已矣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-7","passageId":"li-ji_ch-7_p-55","order":7,"canonicalText":"自啟至于反哭，五祀之祭不行；","chunks":[["自啟至于反哭，五祀之祭不行；","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-8","passageId":"li-ji_ch-7_p-55","order":8,"canonicalText":"已葬而祭，祝畢獻而已。","chunks":[["已葬而祭，祝畢獻而已。","zh-Hant"]]},{"id":"li-ji_ch-7_p-55_s-9","passageId":"li-ji_ch-7_p-55","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-56_s-1","passageId":"li-ji_ch-7_p-56","order":1,"canonicalText":"曾子問曰：「諸侯之祭社稷，俎豆既陳，聞天子崩、後之喪、君薨、夫人之喪，如之何？","chunks":[["曾子問曰：「諸侯之祭社稷，俎豆既陳，聞天子崩、後之喪、君薨、夫人之喪，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-56_s-2","passageId":"li-ji_ch-7_p-56","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-57_s-1","passageId":"li-ji_ch-7_p-57","order":1,"canonicalText":"孔子曰：「廢。","chunks":[["孔子曰：「廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-57_s-2","passageId":"li-ji_ch-7_p-57","order":2,"canonicalText":"自薨比至於殯，自啟至于反哭，奉帥天子。","chunks":[["自薨比至於殯，自啟至于反哭，奉帥天子。","zh-Hant"]]},{"id":"li-ji_ch-7_p-57_s-3","passageId":"li-ji_ch-7_p-57","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-58_s-1","passageId":"li-ji_ch-7_p-58","order":1,"canonicalText":"曾子問曰：「大夫之祭，鼎俎既陳，籩豆既設，不得成禮，廢者幾？","chunks":[["曾子問曰：「大夫之祭，鼎俎既陳，籩豆既設，不得成禮，廢者幾？","zh-Hant"]]},{"id":"li-ji_ch-7_p-58_s-2","passageId":"li-ji_ch-7_p-58","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-1","passageId":"li-ji_ch-7_p-59","order":1,"canonicalText":"孔子曰：「九。","chunks":[["孔子曰：「九。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-2","passageId":"li-ji_ch-7_p-59","order":2,"canonicalText":"」請問之。","chunks":[["」請問之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-3","passageId":"li-ji_ch-7_p-59","order":3,"canonicalText":"曰：「天子崩、後之喪、君薨、夫人之喪、君之大廟火、日食、三年之喪、齊衰、大功，皆廢。","chunks":[["曰：「天子崩、後之喪、君薨、夫人之喪、君之大廟火、日食、三年之喪、齊衰、大功，皆廢。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-4","passageId":"li-ji_ch-7_p-59","order":4,"canonicalText":"外喪自齊衰以下，行也。","chunks":[["外喪自齊衰以下，行也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-5","passageId":"li-ji_ch-7_p-59","order":5,"canonicalText":"其齊衰之祭也，尸入，三飯不侑，酳不酢而已矣；","chunks":[["其齊衰之祭也，尸入，三飯不侑，酳不酢而已矣；","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-6","passageId":"li-ji_ch-7_p-59","order":6,"canonicalText":"大功酢而已矣；","chunks":[["大功酢而已矣；","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-7","passageId":"li-ji_ch-7_p-59","order":7,"canonicalText":"小功、緦，室中之事而已矣。","chunks":[["小功、緦，室中之事而已矣。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-8","passageId":"li-ji_ch-7_p-59","order":8,"canonicalText":"士之所以異者，緦不祭，所祭於死者無服則祭。","chunks":[["士之所以異者，緦不祭，所祭於死者無服則祭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-59_s-9","passageId":"li-ji_ch-7_p-59","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-60_s-1","passageId":"li-ji_ch-7_p-60","order":1,"canonicalText":"曾子問曰：「三年之喪，吊乎？","chunks":[["曾子問曰：「三年之喪，吊乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-60_s-2","passageId":"li-ji_ch-7_p-60","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-61_s-1","passageId":"li-ji_ch-7_p-61","order":1,"canonicalText":"孔子曰：「三年之喪，練，不群立，不旅行。","chunks":[["孔子曰：「三年之喪，練，不群立，不旅行。","zh-Hant"]]},{"id":"li-ji_ch-7_p-61_s-2","passageId":"li-ji_ch-7_p-61","order":2,"canonicalText":"君子禮以飾情，三年之喪而吊哭，不亦虛乎？","chunks":[["君子禮以飾情，三年之喪而吊哭，不亦虛乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-61_s-3","passageId":"li-ji_ch-7_p-61","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-62_s-1","passageId":"li-ji_ch-7_p-62","order":1,"canonicalText":"曾子問曰：「大夫、士有私喪，可以除之矣，而有君服焉，其除之也如之何？","chunks":[["曾子問曰：「大夫、士有私喪，可以除之矣，而有君服焉，其除之也如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-62_s-2","passageId":"li-ji_ch-7_p-62","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-63_s-1","passageId":"li-ji_ch-7_p-63","order":1,"canonicalText":"孔子曰：「有君喪服於身，不敢私服，又何除焉？","chunks":[["孔子曰：「有君喪服於身，不敢私服，又何除焉？","zh-Hant"]]},{"id":"li-ji_ch-7_p-63_s-2","passageId":"li-ji_ch-7_p-63","order":2,"canonicalText":"於是乎有過時而弗除也。","chunks":[["於是乎有過時而弗除也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-63_s-3","passageId":"li-ji_ch-7_p-63","order":3,"canonicalText":"君之喪，服除而後殷祭，禮也。","chunks":[["君之喪，服除而後殷祭，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-63_s-4","passageId":"li-ji_ch-7_p-63","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-64_s-1","passageId":"li-ji_ch-7_p-64","order":1,"canonicalText":"曾子問曰：「父母之喪，弗除可乎？","chunks":[["曾子問曰：「父母之喪，弗除可乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-64_s-2","passageId":"li-ji_ch-7_p-64","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-65_s-1","passageId":"li-ji_ch-7_p-65","order":1,"canonicalText":"孔子曰：「先王制禮，過時弗舉，禮也；","chunks":[["孔子曰：「先王制禮，過時弗舉，禮也；","zh-Hant"]]},{"id":"li-ji_ch-7_p-65_s-2","passageId":"li-ji_ch-7_p-65","order":2,"canonicalText":"非弗能勿除也，患其過於制也，故君子過時不祭，禮也。","chunks":[["非弗能勿除也，患其過於制也，故君子過時不祭，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-65_s-3","passageId":"li-ji_ch-7_p-65","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-66_s-1","passageId":"li-ji_ch-7_p-66","order":1,"canonicalText":"曾子問曰：「君薨，既殯，而臣有父母之喪，則如之何？","chunks":[["曾子問曰：「君薨，既殯，而臣有父母之喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-66_s-2","passageId":"li-ji_ch-7_p-66","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-67_s-1","passageId":"li-ji_ch-7_p-67","order":1,"canonicalText":"孔子曰：「歸居于家，有殷事，則之君所，朝夕否。","chunks":[["孔子曰：「歸居于家，有殷事，則之君所，朝夕否。","zh-Hant"]]},{"id":"li-ji_ch-7_p-67_s-2","passageId":"li-ji_ch-7_p-67","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-68_s-1","passageId":"li-ji_ch-7_p-68","order":1,"canonicalText":"曰：「君既啟，而臣有父母之喪，則如之何？","chunks":[["曰：「君既啟，而臣有父母之喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-68_s-2","passageId":"li-ji_ch-7_p-68","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-69_s-1","passageId":"li-ji_ch-7_p-69","order":1,"canonicalText":"孔子曰：「歸哭而反送君。","chunks":[["孔子曰：「歸哭而反送君。","zh-Hant"]]},{"id":"li-ji_ch-7_p-69_s-2","passageId":"li-ji_ch-7_p-69","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-70_s-1","passageId":"li-ji_ch-7_p-70","order":1,"canonicalText":"曰：「君未殯，而臣有父母之喪，則如之何？","chunks":[["曰：「君未殯，而臣有父母之喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-70_s-2","passageId":"li-ji_ch-7_p-70","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-71_s-1","passageId":"li-ji_ch-7_p-71","order":1,"canonicalText":"孔子曰：「歸殯，反于君所，有殷事則歸，朝夕否。","chunks":[["孔子曰：「歸殯，反于君所，有殷事則歸，朝夕否。","zh-Hant"]]},{"id":"li-ji_ch-7_p-71_s-2","passageId":"li-ji_ch-7_p-71","order":2,"canonicalText":"大夫，室老行事；","chunks":[["大夫，室老行事；","zh-Hant"]]},{"id":"li-ji_ch-7_p-71_s-3","passageId":"li-ji_ch-7_p-71","order":3,"canonicalText":"士，則子孫行事。","chunks":[["士，則子孫行事。","zh-Hant"]]},{"id":"li-ji_ch-7_p-71_s-4","passageId":"li-ji_ch-7_p-71","order":4,"canonicalText":"大夫內子，有殷事，亦之君所，朝夕否。","chunks":[["大夫內子，有殷事，亦之君所，朝夕否。","zh-Hant"]]},{"id":"li-ji_ch-7_p-71_s-5","passageId":"li-ji_ch-7_p-71","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-72_s-1","passageId":"li-ji_ch-7_p-72","order":1,"canonicalText":"賤不誄貴，幼不誄長，禮也。","chunks":[["賤不誄貴，幼不誄長，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-72_s-2","passageId":"li-ji_ch-7_p-72","order":2,"canonicalText":"唯天子，稱天以誄之。","chunks":[["唯天子，稱天以誄之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-72_s-3","passageId":"li-ji_ch-7_p-72","order":3,"canonicalText":"諸侯相誄，非禮也。","chunks":[["諸侯相誄，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-73_s-1","passageId":"li-ji_ch-7_p-73","order":1,"canonicalText":"曾子問曰：「君出疆以三年之戒，以椑從。","chunks":[["曾子問曰：「君出疆以三年之戒，以椑從。","zh-Hant"]]},{"id":"li-ji_ch-7_p-73_s-2","passageId":"li-ji_ch-7_p-73","order":2,"canonicalText":"君薨，其入如之何？","chunks":[["君薨，其入如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-73_s-3","passageId":"li-ji_ch-7_p-73","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-74_s-1","passageId":"li-ji_ch-7_p-74","order":1,"canonicalText":"孔子曰：「共殯服，則子麻，弁絰，疏衰，菲，杖。","chunks":[["孔子曰：「共殯服，則子麻，弁絰，疏衰，菲，杖。","zh-Hant"]]},{"id":"li-ji_ch-7_p-74_s-2","passageId":"li-ji_ch-7_p-74","order":2,"canonicalText":"入自闕，升自西階。","chunks":[["入自闕，升自西階。","zh-Hant"]]},{"id":"li-ji_ch-7_p-74_s-3","passageId":"li-ji_ch-7_p-74","order":3,"canonicalText":"如小斂，則子免而從柩，入自門，升自阼階。","chunks":[["如小斂，則子免而從柩，入自門，升自阼階。","zh-Hant"]]},{"id":"li-ji_ch-7_p-74_s-4","passageId":"li-ji_ch-7_p-74","order":4,"canonicalText":"君大夫士一節也。","chunks":[["君大夫士一節也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-74_s-5","passageId":"li-ji_ch-7_p-74","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-75_s-1","passageId":"li-ji_ch-7_p-75","order":1,"canonicalText":"曾子問曰：「君之喪既引，聞父母之喪，如之何？","chunks":[["曾子問曰：「君之喪既引，聞父母之喪，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-75_s-2","passageId":"li-ji_ch-7_p-75","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-76_s-1","passageId":"li-ji_ch-7_p-76","order":1,"canonicalText":"孔子曰：「遂。","chunks":[["孔子曰：「遂。","zh-Hant"]]},{"id":"li-ji_ch-7_p-76_s-2","passageId":"li-ji_ch-7_p-76","order":2,"canonicalText":"既封而歸，不俟子。","chunks":[["既封而歸，不俟子。","zh-Hant"]]},{"id":"li-ji_ch-7_p-76_s-3","passageId":"li-ji_ch-7_p-76","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-77_s-1","passageId":"li-ji_ch-7_p-77","order":1,"canonicalText":"曾子問曰：「父母之喪既引，及涂，聞君薨，如之何？","chunks":[["曾子問曰：「父母之喪既引，及涂，聞君薨，如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-77_s-2","passageId":"li-ji_ch-7_p-77","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-78_s-1","passageId":"li-ji_ch-7_p-78","order":1,"canonicalText":"孔子曰：「遂。","chunks":[["孔子曰：「遂。","zh-Hant"]]},{"id":"li-ji_ch-7_p-78_s-2","passageId":"li-ji_ch-7_p-78","order":2,"canonicalText":"既封，改服而往。","chunks":[["既封，改服而往。","zh-Hant"]]},{"id":"li-ji_ch-7_p-78_s-3","passageId":"li-ji_ch-7_p-78","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-79_s-1","passageId":"li-ji_ch-7_p-79","order":1,"canonicalText":"曾子問曰：「宗子為士，庶子為大夫，其祭也如之何？","chunks":[["曾子問曰：「宗子為士，庶子為大夫，其祭也如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-79_s-2","passageId":"li-ji_ch-7_p-79","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-1","passageId":"li-ji_ch-7_p-80","order":1,"canonicalText":"孔子曰：「以上牲祭於宗子之家。","chunks":[["孔子曰：「以上牲祭於宗子之家。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-2","passageId":"li-ji_ch-7_p-80","order":2,"canonicalText":"祝曰：『孝子某為介子某薦其常事。","chunks":[["祝曰：『孝子某為介子某薦其常事。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-3","passageId":"li-ji_ch-7_p-80","order":3,"canonicalText":"』若宗子有罪，居于他國，庶子為大夫，其祭也，祝曰：『孝子某使介子某執其常事。","chunks":[["』若宗子有罪，居于他國，庶子為大夫，其祭也，祝曰：『孝子某使介子某執其常事。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-4","passageId":"li-ji_ch-7_p-80","order":4,"canonicalText":"』攝主不厭祭，不旅，不假，不綏祭，不配。","chunks":[["』攝主不厭祭，不旅，不假，不綏祭，不配。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-5","passageId":"li-ji_ch-7_p-80","order":5,"canonicalText":"布奠於賓，賓奠而不舉，不歸肉。","chunks":[["布奠於賓，賓奠而不舉，不歸肉。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-6","passageId":"li-ji_ch-7_p-80","order":6,"canonicalText":"其辭於賓曰：『宗兄、宗弟、宗子在他國，使某辭。","chunks":[["其辭於賓曰：『宗兄、宗弟、宗子在他國，使某辭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-80_s-7","passageId":"li-ji_ch-7_p-80","order":7,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"li-ji_ch-7_p-81_s-1","passageId":"li-ji_ch-7_p-81","order":1,"canonicalText":"曾子問曰：「宗子去在他國，庶子無爵而居者，可以祭乎？","chunks":[["曾子問曰：「宗子去在他國，庶子無爵而居者，可以祭乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-81_s-2","passageId":"li-ji_ch-7_p-81","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-1","passageId":"li-ji_ch-7_p-82","order":1,"canonicalText":"孔子曰：「祭哉！","chunks":[["孔子曰：「祭哉！","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-2","passageId":"li-ji_ch-7_p-82","order":2,"canonicalText":"」請問：「其祭如之何？","chunks":[["」請問：「其祭如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-3","passageId":"li-ji_ch-7_p-82","order":3,"canonicalText":"」孔子曰：「望墓而為壇，以時祭。","chunks":[["」孔子曰：「望墓而為壇，以時祭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-4","passageId":"li-ji_ch-7_p-82","order":4,"canonicalText":"若宗子死，告於墓而後祭於家。","chunks":[["若宗子死，告於墓而後祭於家。","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-5","passageId":"li-ji_ch-7_p-82","order":5,"canonicalText":"宗子死，稱名不言孝，身沒而已。","chunks":[["宗子死，稱名不言孝，身沒而已。","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-6","passageId":"li-ji_ch-7_p-82","order":6,"canonicalText":"子游之徒，有庶子祭者以此，若義也。","chunks":[["子游之徒，有庶子祭者以此，若義也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-7","passageId":"li-ji_ch-7_p-82","order":7,"canonicalText":"今之祭者，不首其義，故誣於祭也。","chunks":[["今之祭者，不首其義，故誣於祭也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-82_s-8","passageId":"li-ji_ch-7_p-82","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-83_s-1","passageId":"li-ji_ch-7_p-83","order":1,"canonicalText":"曾子問曰：「祭必有尸乎？","chunks":[["曾子問曰：「祭必有尸乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-83_s-2","passageId":"li-ji_ch-7_p-83","order":2,"canonicalText":"若厭祭亦可乎？","chunks":[["若厭祭亦可乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-83_s-3","passageId":"li-ji_ch-7_p-83","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-1","passageId":"li-ji_ch-7_p-84","order":1,"canonicalText":"孔子曰：「祭成喪者必有尸，尸必以孫。","chunks":[["孔子曰：「祭成喪者必有尸，尸必以孫。","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-2","passageId":"li-ji_ch-7_p-84","order":2,"canonicalText":"孫幼，則使人抱之。","chunks":[["孫幼，則使人抱之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-3","passageId":"li-ji_ch-7_p-84","order":3,"canonicalText":"無孫，則取於同姓可也。","chunks":[["無孫，則取於同姓可也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-4","passageId":"li-ji_ch-7_p-84","order":4,"canonicalText":"祭殤必厭，蓋弗成也。","chunks":[["祭殤必厭，蓋弗成也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-5","passageId":"li-ji_ch-7_p-84","order":5,"canonicalText":"祭成喪而無尸，是殤之也。","chunks":[["祭成喪而無尸，是殤之也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-84_s-6","passageId":"li-ji_ch-7_p-84","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-85_s-1","passageId":"li-ji_ch-7_p-85","order":1,"canonicalText":"孔子曰：「有陰厭，有陽厭。","chunks":[["孔子曰：「有陰厭，有陽厭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-85_s-2","passageId":"li-ji_ch-7_p-85","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-86_s-1","passageId":"li-ji_ch-7_p-86","order":1,"canonicalText":"曾子問曰：「殤不祔祭，何謂陰厭、陽厭？","chunks":[["曾子問曰：「殤不祔祭，何謂陰厭、陽厭？","zh-Hant"]]},{"id":"li-ji_ch-7_p-86_s-2","passageId":"li-ji_ch-7_p-86","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-87_s-1","passageId":"li-ji_ch-7_p-87","order":1,"canonicalText":"孔子曰：「宗子為殤而死，庶子弗為後也。","chunks":[["孔子曰：「宗子為殤而死，庶子弗為後也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-87_s-2","passageId":"li-ji_ch-7_p-87","order":2,"canonicalText":"其吉祭，特牲。","chunks":[["其吉祭，特牲。","zh-Hant"]]},{"id":"li-ji_ch-7_p-87_s-3","passageId":"li-ji_ch-7_p-87","order":3,"canonicalText":"祭殤不舉，無肵俎，無玄酒，不告利成，是謂陰厭。","chunks":[["祭殤不舉，無肵俎，無玄酒，不告利成，是謂陰厭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-87_s-4","passageId":"li-ji_ch-7_p-87","order":4,"canonicalText":"凡殤，與無後者，祭於宗子之家，當室之白，尊于東房，是謂陽厭。","chunks":[["凡殤，與無後者，祭於宗子之家，當室之白，尊于東房，是謂陽厭。","zh-Hant"]]},{"id":"li-ji_ch-7_p-87_s-5","passageId":"li-ji_ch-7_p-87","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-88_s-1","passageId":"li-ji_ch-7_p-88","order":1,"canonicalText":"曾子問曰：「葬引至於堩，日有食之，則有變乎？","chunks":[["曾子問曰：「葬引至於堩，日有食之，則有變乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-88_s-2","passageId":"li-ji_ch-7_p-88","order":2,"canonicalText":"且不乎？","chunks":[["且不乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-88_s-3","passageId":"li-ji_ch-7_p-88","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-1","passageId":"li-ji_ch-7_p-89","order":1,"canonicalText":"孔子曰：「昔者吾從老聃助葬於巷黨，及堩，日有食之，老聃曰：『丘！","chunks":[["孔子曰：「昔者吾從老聃助葬於巷黨，及堩，日有食之，老聃曰：『丘！","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-2","passageId":"li-ji_ch-7_p-89","order":2,"canonicalText":"止柩，就道右，止哭以聽變。","chunks":[["止柩，就道右，止哭以聽變。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-3","passageId":"li-ji_ch-7_p-89","order":3,"canonicalText":"』既明反而後行。","chunks":[["』既明反而後行。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-4","passageId":"li-ji_ch-7_p-89","order":4,"canonicalText":"曰：『禮也。","chunks":[["曰：『禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-5","passageId":"li-ji_ch-7_p-89","order":5,"canonicalText":"』反葬，而丘問之曰：『夫柩不可以反者也，日有食之，不知其已之遲數，則豈如行哉？","chunks":[["』反葬，而丘問之曰：『夫柩不可以反者也，日有食之，不知其已之遲數，則豈如行哉？","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-6","passageId":"li-ji_ch-7_p-89","order":6,"canonicalText":"』老聃曰：『諸侯朝天子，見日而行，逮日而舍奠；","chunks":[["』老聃曰：『諸侯朝天子，見日而行，逮日而舍奠；","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-7","passageId":"li-ji_ch-7_p-89","order":7,"canonicalText":"大夫使，見日而行，逮日而舍。","chunks":[["大夫使，見日而行，逮日而舍。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-8","passageId":"li-ji_ch-7_p-89","order":8,"canonicalText":"夫柩不早出，不暮宿。","chunks":[["夫柩不早出，不暮宿。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-9","passageId":"li-ji_ch-7_p-89","order":9,"canonicalText":"見星而行者，唯罪人與奔父母之喪者乎！","chunks":[["見星而行者，唯罪人與奔父母之喪者乎！","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-10","passageId":"li-ji_ch-7_p-89","order":10,"canonicalText":"日有食之，安知其不見星也？","chunks":[["日有食之，安知其不見星也？","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-11","passageId":"li-ji_ch-7_p-89","order":11,"canonicalText":"且君子行禮，不以人之親痁患。","chunks":[["且君子行禮，不以人之親痁患。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-12","passageId":"li-ji_ch-7_p-89","order":12,"canonicalText":"』吾聞諸老聃云。","chunks":[["』吾聞諸老聃云。","zh-Hant"]]},{"id":"li-ji_ch-7_p-89_s-13","passageId":"li-ji_ch-7_p-89","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-90_s-1","passageId":"li-ji_ch-7_p-90","order":1,"canonicalText":"曾子問曰：「為君使而卒於舍，禮曰：公館復，私館不復。","chunks":[["曾子問曰：「為君使而卒於舍，禮曰：公館復，私館不復。","zh-Hant"]]},{"id":"li-ji_ch-7_p-90_s-2","passageId":"li-ji_ch-7_p-90","order":2,"canonicalText":"凡所使之國，有司所授舍，則公館已，何謂私館不復也？","chunks":[["凡所使之國，有司所授舍，則公館已，何謂私館不復也？","zh-Hant"]]},{"id":"li-ji_ch-7_p-90_s-3","passageId":"li-ji_ch-7_p-90","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-91_s-1","passageId":"li-ji_ch-7_p-91","order":1,"canonicalText":"孔子曰：「善乎問之也！","chunks":[["孔子曰：「善乎問之也！","zh-Hant"]]},{"id":"li-ji_ch-7_p-91_s-2","passageId":"li-ji_ch-7_p-91","order":2,"canonicalText":"自卿、大夫、士之家，曰私館；","chunks":[["自卿、大夫、士之家，曰私館；","zh-Hant"]]},{"id":"li-ji_ch-7_p-91_s-3","passageId":"li-ji_ch-7_p-91","order":3,"canonicalText":"公館與公所為，曰公館。","chunks":[["公館與公所為，曰公館。","zh-Hant"]]},{"id":"li-ji_ch-7_p-91_s-4","passageId":"li-ji_ch-7_p-91","order":4,"canonicalText":"公館復，此之謂也。","chunks":[["公館復，此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-91_s-5","passageId":"li-ji_ch-7_p-91","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-92_s-1","passageId":"li-ji_ch-7_p-92","order":1,"canonicalText":"曾子問曰：「下殤：土周葬于園，遂輿機而往，途邇故也。","chunks":[["曾子問曰：「下殤：土周葬于園，遂輿機而往，途邇故也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-92_s-2","passageId":"li-ji_ch-7_p-92","order":2,"canonicalText":"今墓遠，則其葬也如之何？","chunks":[["今墓遠，則其葬也如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-92_s-3","passageId":"li-ji_ch-7_p-92","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-1","passageId":"li-ji_ch-7_p-93","order":1,"canonicalText":"孔子曰：「吾聞諸老聃曰：昔者史佚有子而死，下殤也。","chunks":[["孔子曰：「吾聞諸老聃曰：昔者史佚有子而死，下殤也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-2","passageId":"li-ji_ch-7_p-93","order":2,"canonicalText":"墓遠，召公謂之曰：『何以不棺斂於宮中？","chunks":[["墓遠，召公謂之曰：『何以不棺斂於宮中？","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-3","passageId":"li-ji_ch-7_p-93","order":3,"canonicalText":"』史佚曰：『吾敢乎哉？","chunks":[["』史佚曰：『吾敢乎哉？","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-4","passageId":"li-ji_ch-7_p-93","order":4,"canonicalText":"』召公言於周公，周公曰：『豈不可？","chunks":[["』召公言於周公，周公曰：『豈不可？","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-5","passageId":"li-ji_ch-7_p-93","order":5,"canonicalText":"』史佚行之。","chunks":[["』史佚行之。","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-6","passageId":"li-ji_ch-7_p-93","order":6,"canonicalText":"下殤用棺衣棺，自史佚始也。","chunks":[["下殤用棺衣棺，自史佚始也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-93_s-7","passageId":"li-ji_ch-7_p-93","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-94_s-1","passageId":"li-ji_ch-7_p-94","order":1,"canonicalText":"曾子問曰：「卿、大夫將為尸於公，受宿矣，而有齊衰內喪，則如之何？","chunks":[["曾子問曰：「卿、大夫將為尸於公，受宿矣，而有齊衰內喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-7_p-94_s-2","passageId":"li-ji_ch-7_p-94","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-95_s-1","passageId":"li-ji_ch-7_p-95","order":1,"canonicalText":"孔子曰：「出，舍於公館以待事，禮也。","chunks":[["孔子曰：「出，舍於公館以待事，禮也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-95_s-2","passageId":"li-ji_ch-7_p-95","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-96_s-1","passageId":"li-ji_ch-7_p-96","order":1,"canonicalText":"孔子曰：「尸弁冕而出，卿、大夫、士皆下之，尸必式，必有前驅。","chunks":[["孔子曰：「尸弁冕而出，卿、大夫、士皆下之，尸必式，必有前驅。","zh-Hant"]]},{"id":"li-ji_ch-7_p-96_s-2","passageId":"li-ji_ch-7_p-96","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-97_s-1","passageId":"li-ji_ch-7_p-97","order":1,"canonicalText":"子夏問曰：「三年之喪卒哭，金革之事無辟也者，禮與？","chunks":[["子夏問曰：「三年之喪卒哭，金革之事無辟也者，禮與？","zh-Hant"]]},{"id":"li-ji_ch-7_p-97_s-2","passageId":"li-ji_ch-7_p-97","order":2,"canonicalText":"初有司與？","chunks":[["初有司與？","zh-Hant"]]},{"id":"li-ji_ch-7_p-97_s-3","passageId":"li-ji_ch-7_p-97","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-98_s-1","passageId":"li-ji_ch-7_p-98","order":1,"canonicalText":"孔子曰：「夏后氏三年之喪，既殯而致事，殷人既葬而致事。","chunks":[["孔子曰：「夏后氏三年之喪，既殯而致事，殷人既葬而致事。","zh-Hant"]]},{"id":"li-ji_ch-7_p-98_s-2","passageId":"li-ji_ch-7_p-98","order":2,"canonicalText":"《記》曰：『君子不奪人之親，亦不可奪親也。","chunks":[["《記》曰：『君子不奪人之親，亦不可奪親也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-98_s-3","passageId":"li-ji_ch-7_p-98","order":3,"canonicalText":"』此之謂乎？","chunks":[["』此之謂乎？","zh-Hant"]]},{"id":"li-ji_ch-7_p-98_s-4","passageId":"li-ji_ch-7_p-98","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-99_s-1","passageId":"li-ji_ch-7_p-99","order":1,"canonicalText":"子夏曰：「金革之事無辟也者，非與？","chunks":[["子夏曰：「金革之事無辟也者，非與？","zh-Hant"]]},{"id":"li-ji_ch-7_p-99_s-2","passageId":"li-ji_ch-7_p-99","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-7_p-100_s-1","passageId":"li-ji_ch-7_p-100","order":1,"canonicalText":"孔子曰：「吾聞諸老聃曰：昔者魯公伯禽有為為之也。","chunks":[["孔子曰：「吾聞諸老聃曰：昔者魯公伯禽有為為之也。","zh-Hant"]]},{"id":"li-ji_ch-7_p-100_s-2","passageId":"li-ji_ch-7_p-100","order":2,"canonicalText":"今以三年之喪，從其利者，吾弗知也！","chunks":[["今以三年之喪，從其利者，吾弗知也！","zh-Hant"]]},{"id":"li-ji_ch-7_p-100_s-3","passageId":"li-ji_ch-7_p-100","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-1","passageId":"li-ji_ch-8_p-1","order":1,"canonicalText":"文王之為世子，朝於王季，日三。","chunks":[["文王之為世子，朝於王季，日三。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-2","passageId":"li-ji_ch-8_p-1","order":2,"canonicalText":"雞初鳴而衣服，至於寢門外，問內豎之御者曰：「今日安否何如？","chunks":[["雞初鳴而衣服，至於寢門外，問內豎之御者曰：「今日安否何如？","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-3","passageId":"li-ji_ch-8_p-1","order":3,"canonicalText":"」內豎曰：「安。","chunks":[["」內豎曰：「安。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-4","passageId":"li-ji_ch-8_p-1","order":4,"canonicalText":"」文王乃喜。","chunks":[["」文王乃喜。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-5","passageId":"li-ji_ch-8_p-1","order":5,"canonicalText":"及日中，又至，亦如之。","chunks":[["及日中，又至，亦如之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-6","passageId":"li-ji_ch-8_p-1","order":6,"canonicalText":"及莫，又至，亦如之。","chunks":[["及莫，又至，亦如之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-7","passageId":"li-ji_ch-8_p-1","order":7,"canonicalText":"其有不安節，則內豎以告文王，文王色憂，行不能正履。","chunks":[["其有不安節，則內豎以告文王，文王色憂，行不能正履。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-8","passageId":"li-ji_ch-8_p-1","order":8,"canonicalText":"王季腹膳，然後亦復初。","chunks":[["王季腹膳，然後亦復初。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-9","passageId":"li-ji_ch-8_p-1","order":9,"canonicalText":"食上，必在，視寒暖之節，食下，問所膳；","chunks":[["食上，必在，視寒暖之節，食下，問所膳；","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-10","passageId":"li-ji_ch-8_p-1","order":10,"canonicalText":"命膳宰曰：「末有原！","chunks":[["命膳宰曰：「末有原！","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-11","passageId":"li-ji_ch-8_p-1","order":11,"canonicalText":"」應曰：「諾。","chunks":[["」應曰：「諾。","zh-Hant"]]},{"id":"li-ji_ch-8_p-1_s-12","passageId":"li-ji_ch-8_p-1","order":12,"canonicalText":"」然後退。","chunks":[["」然後退。","zh-Hant"]]},{"id":"li-ji_ch-8_p-2_s-1","passageId":"li-ji_ch-8_p-2","order":1,"canonicalText":"武王帥而行之，不敢有加焉。","chunks":[["武王帥而行之，不敢有加焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-2_s-2","passageId":"li-ji_ch-8_p-2","order":2,"canonicalText":"文王有疾，武王不脫1冠帶而養。","chunks":[["文王有疾，武王不脫1冠帶而養。","zh-Hant"]]},{"id":"li-ji_ch-8_p-2_s-3","passageId":"li-ji_ch-8_p-2","order":3,"canonicalText":"文王一飯，亦一飯；","chunks":[["文王一飯，亦一飯；","zh-Hant"]]},{"id":"li-ji_ch-8_p-2_s-4","passageId":"li-ji_ch-8_p-2","order":4,"canonicalText":"文王再飯，亦再飯。","chunks":[["文王再飯，亦再飯。","zh-Hant"]]},{"id":"li-ji_ch-8_p-2_s-5","passageId":"li-ji_ch-8_p-2","order":5,"canonicalText":"旬有二日乃間。","chunks":[["旬有二日乃間。","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-1","passageId":"li-ji_ch-8_p-3","order":1,"canonicalText":"文王謂武王曰：「女何夢矣？","chunks":[["文王謂武王曰：「女何夢矣？","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-2","passageId":"li-ji_ch-8_p-3","order":2,"canonicalText":"」武王對曰：「夢帝與我九齡。","chunks":[["」武王對曰：「夢帝與我九齡。","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-3","passageId":"li-ji_ch-8_p-3","order":3,"canonicalText":"」文王曰：「女以為何也？","chunks":[["」文王曰：「女以為何也？","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-4","passageId":"li-ji_ch-8_p-3","order":4,"canonicalText":"」武王曰：「西方有九國焉，君王其終撫諸？","chunks":[["」武王曰：「西方有九國焉，君王其終撫諸？","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-5","passageId":"li-ji_ch-8_p-3","order":5,"canonicalText":"」文王曰：「非也。","chunks":[["」文王曰：「非也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-6","passageId":"li-ji_ch-8_p-3","order":6,"canonicalText":"古者謂年齡，齒亦齡也。","chunks":[["古者謂年齡，齒亦齡也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-7","passageId":"li-ji_ch-8_p-3","order":7,"canonicalText":"我百爾九十，吾與爾三焉。","chunks":[["我百爾九十，吾與爾三焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-3_s-8","passageId":"li-ji_ch-8_p-3","order":8,"canonicalText":"」文王九十七乃終，武王九十三而終。","chunks":[["」文王九十七乃終，武王九十三而終。","zh-Hant"]]},{"id":"li-ji_ch-8_p-4_s-1","passageId":"li-ji_ch-8_p-4","order":1,"canonicalText":"成王幼，不能蒞阼，周公相，踐阼而治。","chunks":[["成王幼，不能蒞阼，周公相，踐阼而治。","zh-Hant"]]},{"id":"li-ji_ch-8_p-4_s-2","passageId":"li-ji_ch-8_p-4","order":2,"canonicalText":"抗世子法於伯禽，欲令成王之知父子、君臣、長幼之道也；","chunks":[["抗世子法於伯禽，欲令成王之知父子、君臣、長幼之道也；","zh-Hant"]]},{"id":"li-ji_ch-8_p-4_s-3","passageId":"li-ji_ch-8_p-4","order":3,"canonicalText":"成王有過，則撻伯禽，所以示成王世子之道也。","chunks":[["成王有過，則撻伯禽，所以示成王世子之道也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-4_s-4","passageId":"li-ji_ch-8_p-4","order":4,"canonicalText":"文王之為世子也。","chunks":[["文王之為世子也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-1","passageId":"li-ji_ch-8_p-5","order":1,"canonicalText":"凡學世子及學士，必時。","chunks":[["凡學世子及學士，必時。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-2","passageId":"li-ji_ch-8_p-5","order":2,"canonicalText":"春夏學干戈，秋冬學羽龠，皆於東序。","chunks":[["春夏學干戈，秋冬學羽龠，皆於東序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-3","passageId":"li-ji_ch-8_p-5","order":3,"canonicalText":"小樂正學干，大胥贊之。","chunks":[["小樂正學干，大胥贊之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-4","passageId":"li-ji_ch-8_p-5","order":4,"canonicalText":"龠師學戈，龠師丞贊之。","chunks":[["龠師學戈，龠師丞贊之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-5","passageId":"li-ji_ch-8_p-5","order":5,"canonicalText":"胥鼓南。","chunks":[["胥鼓南。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-6","passageId":"li-ji_ch-8_p-5","order":6,"canonicalText":"春誦夏弦，大師詔之。","chunks":[["春誦夏弦，大師詔之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-7","passageId":"li-ji_ch-8_p-5","order":7,"canonicalText":"瞽宗秋學禮，執禮者詔之；","chunks":[["瞽宗秋學禮，執禮者詔之；","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-8","passageId":"li-ji_ch-8_p-5","order":8,"canonicalText":"冬讀書，典書者詔之。","chunks":[["冬讀書，典書者詔之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-5_s-9","passageId":"li-ji_ch-8_p-5","order":9,"canonicalText":"禮在瞽宗，書在上庠。","chunks":[["禮在瞽宗，書在上庠。","zh-Hant"]]},{"id":"li-ji_ch-8_p-6_s-1","passageId":"li-ji_ch-8_p-6","order":1,"canonicalText":"凡祭與養老，乞言，合語之禮，皆小樂正詔之於東序。","chunks":[["凡祭與養老，乞言，合語之禮，皆小樂正詔之於東序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-6_s-2","passageId":"li-ji_ch-8_p-6","order":2,"canonicalText":"大樂正學舞干戚，語說，命乞言，皆大樂正授數，大司成論說在東序。","chunks":[["大樂正學舞干戚，語說，命乞言，皆大樂正授數，大司成論說在東序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-6_s-3","passageId":"li-ji_ch-8_p-6","order":3,"canonicalText":"凡侍坐於大司成者，遠近間三席，可以問。","chunks":[["凡侍坐於大司成者，遠近間三席，可以問。","zh-Hant"]]},{"id":"li-ji_ch-8_p-6_s-4","passageId":"li-ji_ch-8_p-6","order":4,"canonicalText":"終則負墻，列事未盡，不問。","chunks":[["終則負墻，列事未盡，不問。","zh-Hant"]]},{"id":"li-ji_ch-8_p-7_s-1","passageId":"li-ji_ch-8_p-7","order":1,"canonicalText":"凡學，春官釋奠於其先師，秋冬亦如之。","chunks":[["凡學，春官釋奠於其先師，秋冬亦如之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-7_s-2","passageId":"li-ji_ch-8_p-7","order":2,"canonicalText":"凡始立學者，必釋奠於先聖先師；","chunks":[["凡始立學者，必釋奠於先聖先師；","zh-Hant"]]},{"id":"li-ji_ch-8_p-7_s-3","passageId":"li-ji_ch-8_p-7","order":3,"canonicalText":"及行事，必以幣。","chunks":[["及行事，必以幣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-7_s-4","passageId":"li-ji_ch-8_p-7","order":4,"canonicalText":"凡釋奠者，必有合也，有國故則否。","chunks":[["凡釋奠者，必有合也，有國故則否。","zh-Hant"]]},{"id":"li-ji_ch-8_p-7_s-5","passageId":"li-ji_ch-8_p-7","order":5,"canonicalText":"凡大合樂，必遂養老。","chunks":[["凡大合樂，必遂養老。","zh-Hant"]]},{"id":"li-ji_ch-8_p-8_s-1","passageId":"li-ji_ch-8_p-8","order":1,"canonicalText":"凡語於郊者，必取賢斂才焉。","chunks":[["凡語於郊者，必取賢斂才焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-8_s-2","passageId":"li-ji_ch-8_p-8","order":2,"canonicalText":"或以德進，或以事舉，或以言揚。","chunks":[["或以德進，或以事舉，或以言揚。","zh-Hant"]]},{"id":"li-ji_ch-8_p-8_s-3","passageId":"li-ji_ch-8_p-8","order":3,"canonicalText":"曲藝皆誓之，以待又語。","chunks":[["曲藝皆誓之，以待又語。","zh-Hant"]]},{"id":"li-ji_ch-8_p-8_s-4","passageId":"li-ji_ch-8_p-8","order":4,"canonicalText":"三而一有焉，乃進其等，以其序，謂之郊人，遠之。","chunks":[["三而一有焉，乃進其等，以其序，謂之郊人，遠之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-8_s-5","passageId":"li-ji_ch-8_p-8","order":5,"canonicalText":"於成均以及取爵於上尊也。","chunks":[["於成均以及取爵於上尊也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-9_s-1","passageId":"li-ji_ch-8_p-9","order":1,"canonicalText":"始立學者，既興器用幣，然後釋菜不舞不授器，乃退。","chunks":[["始立學者，既興器用幣，然後釋菜不舞不授器，乃退。","zh-Hant"]]},{"id":"li-ji_ch-8_p-9_s-2","passageId":"li-ji_ch-8_p-9","order":2,"canonicalText":"儐於東序，一獻，無介語可也。","chunks":[["儐於東序，一獻，無介語可也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-9_s-3","passageId":"li-ji_ch-8_p-9","order":3,"canonicalText":"教世子。","chunks":[["教世子。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-1","passageId":"li-ji_ch-8_p-10","order":1,"canonicalText":"凡三王教世子必以禮樂。","chunks":[["凡三王教世子必以禮樂。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-2","passageId":"li-ji_ch-8_p-10","order":2,"canonicalText":"樂，所以修內也；","chunks":[["樂，所以修內也；","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-3","passageId":"li-ji_ch-8_p-10","order":3,"canonicalText":"禮，所以修外也。","chunks":[["禮，所以修外也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-4","passageId":"li-ji_ch-8_p-10","order":4,"canonicalText":"禮樂交錯於中，發形於外，是故其成也懌，恭敬而溫文。","chunks":[["禮樂交錯於中，發形於外，是故其成也懌，恭敬而溫文。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-5","passageId":"li-ji_ch-8_p-10","order":5,"canonicalText":"立大傅、少傅以養之，欲其知父子、君臣之道也。","chunks":[["立大傅、少傅以養之，欲其知父子、君臣之道也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-6","passageId":"li-ji_ch-8_p-10","order":6,"canonicalText":"大傅審父子、君臣之道以示之；","chunks":[["大傅審父子、君臣之道以示之；","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-7","passageId":"li-ji_ch-8_p-10","order":7,"canonicalText":"少傅奉世子，以觀大傅之德行而審喻之。","chunks":[["少傅奉世子，以觀大傅之德行而審喻之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-8","passageId":"li-ji_ch-8_p-10","order":8,"canonicalText":"大傅在前，少傅在後；","chunks":[["大傅在前，少傅在後；","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-9","passageId":"li-ji_ch-8_p-10","order":9,"canonicalText":"入則有保，出則有師，是以教喻而德成也。","chunks":[["入則有保，出則有師，是以教喻而德成也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-10","passageId":"li-ji_ch-8_p-10","order":10,"canonicalText":"師也者，教之以事而喻諸德者也；","chunks":[["師也者，教之以事而喻諸德者也；","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-11","passageId":"li-ji_ch-8_p-10","order":11,"canonicalText":"保也者，慎其身以輔翼之而歸諸道者也。","chunks":[["保也者，慎其身以輔翼之而歸諸道者也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-12","passageId":"li-ji_ch-8_p-10","order":12,"canonicalText":"《記》曰：「虞、夏、商、周，有師保，有疑丞。","chunks":[["《記》曰：「虞、夏、商、周，有師保，有疑丞。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-13","passageId":"li-ji_ch-8_p-10","order":13,"canonicalText":"」設四輔及三公。","chunks":[["」設四輔及三公。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-14","passageId":"li-ji_ch-8_p-10","order":14,"canonicalText":"不必備，唯其人。","chunks":[["不必備，唯其人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-10_s-15","passageId":"li-ji_ch-8_p-10","order":15,"canonicalText":"語使能也。","chunks":[["語使能也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-11_s-1","passageId":"li-ji_ch-8_p-11","order":1,"canonicalText":"君子曰德，德成而教尊，教尊而官正，官正而國治，君之謂也。","chunks":[["君子曰德，德成而教尊，教尊而官正，官正而國治，君之謂也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-1","passageId":"li-ji_ch-8_p-12","order":1,"canonicalText":"仲尼曰：「昔者周公攝政，踐阼而治，抗世子法於伯禽，所以善成王也。","chunks":[["仲尼曰：「昔者周公攝政，踐阼而治，抗世子法於伯禽，所以善成王也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-2","passageId":"li-ji_ch-8_p-12","order":2,"canonicalText":"聞之曰：為人臣者，殺其身有益於君則為之，況於其身以善其君乎？","chunks":[["聞之曰：為人臣者，殺其身有益於君則為之，況於其身以善其君乎？","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-3","passageId":"li-ji_ch-8_p-12","order":3,"canonicalText":"周公優為之！","chunks":[["周公優為之！","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-4","passageId":"li-ji_ch-8_p-12","order":4,"canonicalText":"」是故知為人子，然後可以為人父；","chunks":[["」是故知為人子，然後可以為人父；","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-5","passageId":"li-ji_ch-8_p-12","order":5,"canonicalText":"知為人臣，然後可以為人君；","chunks":[["知為人臣，然後可以為人君；","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-6","passageId":"li-ji_ch-8_p-12","order":6,"canonicalText":"知事人，然後能使人。","chunks":[["知事人，然後能使人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-12_s-7","passageId":"li-ji_ch-8_p-12","order":7,"canonicalText":"成王幼，不能蒞阼，以為世子，則無為也，是故抗世子法於伯禽，使之與成王居，欲令成王之知父子、君臣、長幼之義也。","chunks":[["成王幼，不能蒞阼，以為世子，則無為也，是故抗世子法於伯禽，使之與成王居，欲令成王之知父子、君臣、長幼之義也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-1","passageId":"li-ji_ch-8_p-13","order":1,"canonicalText":"君之於世子也，親則父也，尊則君也。","chunks":[["君之於世子也，親則父也，尊則君也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-2","passageId":"li-ji_ch-8_p-13","order":2,"canonicalText":"有父之親，有君之尊，然後兼天下而有之。","chunks":[["有父之親，有君之尊，然後兼天下而有之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-3","passageId":"li-ji_ch-8_p-13","order":3,"canonicalText":"是故，養世子不可不慎也。","chunks":[["是故，養世子不可不慎也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-4","passageId":"li-ji_ch-8_p-13","order":4,"canonicalText":"行一物而三善皆得者，唯世子而已。","chunks":[["行一物而三善皆得者，唯世子而已。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-5","passageId":"li-ji_ch-8_p-13","order":5,"canonicalText":"其齒於學之謂也。","chunks":[["其齒於學之謂也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-6","passageId":"li-ji_ch-8_p-13","order":6,"canonicalText":"故世子齒於學，國人觀之曰：「將君我而與我齒讓何也？","chunks":[["故世子齒於學，國人觀之曰：「將君我而與我齒讓何也？","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-7","passageId":"li-ji_ch-8_p-13","order":7,"canonicalText":"」曰：「有父在則禮然，然而眾知父子之道矣。","chunks":[["」曰：「有父在則禮然，然而眾知父子之道矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-8","passageId":"li-ji_ch-8_p-13","order":8,"canonicalText":"」其二曰：「將君我而與我齒讓何也？","chunks":[["」其二曰：「將君我而與我齒讓何也？","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-9","passageId":"li-ji_ch-8_p-13","order":9,"canonicalText":"」曰：「有君在則禮然，然而眾著於君臣之義也。","chunks":[["」曰：「有君在則禮然，然而眾著於君臣之義也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-10","passageId":"li-ji_ch-8_p-13","order":10,"canonicalText":"」其三曰：「將君我而與我齒讓何也？","chunks":[["」其三曰：「將君我而與我齒讓何也？","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-11","passageId":"li-ji_ch-8_p-13","order":11,"canonicalText":"」曰：「長長也，然而眾知長幼之節矣。","chunks":[["」曰：「長長也，然而眾知長幼之節矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-12","passageId":"li-ji_ch-8_p-13","order":12,"canonicalText":"」故父在斯為子，君在斯謂之臣，居子與臣之節，所以尊君親親也。","chunks":[["」故父在斯為子，君在斯謂之臣，居子與臣之節，所以尊君親親也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-13","passageId":"li-ji_ch-8_p-13","order":13,"canonicalText":"故學之為父子焉，學之為君臣焉，學之為長幼焉，父子、君臣、長幼之道得，而國治。","chunks":[["故學之為父子焉，學之為君臣焉，學之為長幼焉，父子、君臣、長幼之道得，而國治。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-14","passageId":"li-ji_ch-8_p-13","order":14,"canonicalText":"語曰：「樂正司業，父師司成，一有元良，萬國以貞。","chunks":[["語曰：「樂正司業，父師司成，一有元良，萬國以貞。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-15","passageId":"li-ji_ch-8_p-13","order":15,"canonicalText":"」世子之謂也。","chunks":[["」世子之謂也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-13_s-16","passageId":"li-ji_ch-8_p-13","order":16,"canonicalText":"周公踐阼。","chunks":[["周公踐阼。","zh-Hant"]]},{"id":"li-ji_ch-8_p-14_s-1","passageId":"li-ji_ch-8_p-14","order":1,"canonicalText":"庶子之正於公族者，教之以孝弟、睦友、子愛，明父子之義、長幼之序。","chunks":[["庶子之正於公族者，教之以孝弟、睦友、子愛，明父子之義、長幼之序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-15_s-1","passageId":"li-ji_ch-8_p-15","order":1,"canonicalText":"其朝於公：內朝，則東面北上；","chunks":[["其朝於公：內朝，則東面北上；","zh-Hant"]]},{"id":"li-ji_ch-8_p-15_s-2","passageId":"li-ji_ch-8_p-15","order":2,"canonicalText":"臣有貴者，以齒。","chunks":[["臣有貴者，以齒。","zh-Hant"]]},{"id":"li-ji_ch-8_p-15_s-3","passageId":"li-ji_ch-8_p-15","order":3,"canonicalText":"其在外朝，則以官，司士為之。","chunks":[["其在外朝，則以官，司士為之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-16_s-1","passageId":"li-ji_ch-8_p-16","order":1,"canonicalText":"其在宗廟之中，則如外朝之位。","chunks":[["其在宗廟之中，則如外朝之位。","zh-Hant"]]},{"id":"li-ji_ch-8_p-16_s-2","passageId":"li-ji_ch-8_p-16","order":2,"canonicalText":"宗人授事，以爵以官。","chunks":[["宗人授事，以爵以官。","zh-Hant"]]},{"id":"li-ji_ch-8_p-16_s-3","passageId":"li-ji_ch-8_p-16","order":3,"canonicalText":"其登餕獻受爵，則以上嗣。","chunks":[["其登餕獻受爵，則以上嗣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-16_s-4","passageId":"li-ji_ch-8_p-16","order":4,"canonicalText":"庶子治之，雖有三命，不逾父兄。","chunks":[["庶子治之，雖有三命，不逾父兄。","zh-Hant"]]},{"id":"li-ji_ch-8_p-17_s-1","passageId":"li-ji_ch-8_p-17","order":1,"canonicalText":"其公大事，則以其喪服之精粗為序。","chunks":[["其公大事，則以其喪服之精粗為序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-17_s-2","passageId":"li-ji_ch-8_p-17","order":2,"canonicalText":"雖於公族之喪亦如之，以次主人。","chunks":[["雖於公族之喪亦如之，以次主人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-18_s-1","passageId":"li-ji_ch-8_p-18","order":1,"canonicalText":"若公與族燕，則異姓為賓，膳宰為主人，公與父兄齒。","chunks":[["若公與族燕，則異姓為賓，膳宰為主人，公與父兄齒。","zh-Hant"]]},{"id":"li-ji_ch-8_p-18_s-2","passageId":"li-ji_ch-8_p-18","order":2,"canonicalText":"族食，世降一等。","chunks":[["族食，世降一等。","zh-Hant"]]},{"id":"li-ji_ch-8_p-19_s-1","passageId":"li-ji_ch-8_p-19","order":1,"canonicalText":"其在軍，則守於公禰。","chunks":[["其在軍，則守於公禰。","zh-Hant"]]},{"id":"li-ji_ch-8_p-19_s-2","passageId":"li-ji_ch-8_p-19","order":2,"canonicalText":"公若有出疆之政，庶子以公族之無事者守於公宮，正室守大廟，諸父守貴宮貴室，諸子諸孫守下宮下室。","chunks":[["公若有出疆之政，庶子以公族之無事者守於公宮，正室守大廟，諸父守貴宮貴室，諸子諸孫守下宮下室。","zh-Hant"]]},{"id":"li-ji_ch-8_p-20_s-1","passageId":"li-ji_ch-8_p-20","order":1,"canonicalText":"五廟之孫，祖廟未毀，雖為庶人，冠，取妻，必告；","chunks":[["五廟之孫，祖廟未毀，雖為庶人，冠，取妻，必告；","zh-Hant"]]},{"id":"li-ji_ch-8_p-20_s-2","passageId":"li-ji_ch-8_p-20","order":2,"canonicalText":"死，必赴；","chunks":[["死，必赴；","zh-Hant"]]},{"id":"li-ji_ch-8_p-20_s-3","passageId":"li-ji_ch-8_p-20","order":3,"canonicalText":"練祥則告。","chunks":[["練祥則告。","zh-Hant"]]},{"id":"li-ji_ch-8_p-20_s-4","passageId":"li-ji_ch-8_p-20","order":4,"canonicalText":"族之相為也，宜吊不吊，宜免不免，有司罰之。","chunks":[["族之相為也，宜吊不吊，宜免不免，有司罰之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-20_s-5","passageId":"li-ji_ch-8_p-20","order":5,"canonicalText":"至於賵賻承含，皆有正焉。","chunks":[["至於賵賻承含，皆有正焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-1","passageId":"li-ji_ch-8_p-21","order":1,"canonicalText":"公族其有死罪，則磬于甸人。","chunks":[["公族其有死罪，則磬于甸人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-2","passageId":"li-ji_ch-8_p-21","order":2,"canonicalText":"其刑罪，則纖剸，亦告于甸人。","chunks":[["其刑罪，則纖剸，亦告于甸人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-3","passageId":"li-ji_ch-8_p-21","order":3,"canonicalText":"公族無宮刑。","chunks":[["公族無宮刑。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-4","passageId":"li-ji_ch-8_p-21","order":4,"canonicalText":"獄成，有司讞於公。","chunks":[["獄成，有司讞於公。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-5","passageId":"li-ji_ch-8_p-21","order":5,"canonicalText":"其死罪，則曰「某之罪在大辟」；","chunks":[["其死罪，則曰「某之罪在大辟」；","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-6","passageId":"li-ji_ch-8_p-21","order":6,"canonicalText":"其刑罪，則曰「某之罪在小辟」。","chunks":[["其刑罪，則曰「某之罪在小辟」。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-7","passageId":"li-ji_ch-8_p-21","order":7,"canonicalText":"公曰：「宥之。","chunks":[["公曰：「宥之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-8","passageId":"li-ji_ch-8_p-21","order":8,"canonicalText":"」有司又曰：「在辟。","chunks":[["」有司又曰：「在辟。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-9","passageId":"li-ji_ch-8_p-21","order":9,"canonicalText":"」公又曰：「宥之。","chunks":[["」公又曰：「宥之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-10","passageId":"li-ji_ch-8_p-21","order":10,"canonicalText":"」有司又曰：「在辟。","chunks":[["」有司又曰：「在辟。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-11","passageId":"li-ji_ch-8_p-21","order":11,"canonicalText":"」及三宥，不對，走出，致刑於于甸人。","chunks":[["」及三宥，不對，走出，致刑於于甸人。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-12","passageId":"li-ji_ch-8_p-21","order":12,"canonicalText":"公又使人追之曰：「雖然，必赦之。","chunks":[["公又使人追之曰：「雖然，必赦之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-13","passageId":"li-ji_ch-8_p-21","order":13,"canonicalText":"」有司對曰：「無及也！","chunks":[["」有司對曰：「無及也！","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-14","passageId":"li-ji_ch-8_p-21","order":14,"canonicalText":"」反命於公，公素服不舉，為之變，如其倫之喪。","chunks":[["」反命於公，公素服不舉，為之變，如其倫之喪。","zh-Hant"]]},{"id":"li-ji_ch-8_p-21_s-15","passageId":"li-ji_ch-8_p-21","order":15,"canonicalText":"無服，親哭之。","chunks":[["無服，親哭之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-22_s-1","passageId":"li-ji_ch-8_p-22","order":1,"canonicalText":"公族朝於內朝，內親也。","chunks":[["公族朝於內朝，內親也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-22_s-2","passageId":"li-ji_ch-8_p-22","order":2,"canonicalText":"雖有貴者以齒，明父子也。","chunks":[["雖有貴者以齒，明父子也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-22_s-3","passageId":"li-ji_ch-8_p-22","order":3,"canonicalText":"外朝以官，體異姓也。","chunks":[["外朝以官，體異姓也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-23_s-1","passageId":"li-ji_ch-8_p-23","order":1,"canonicalText":"宗廟之中，以爵為位，崇德也。","chunks":[["宗廟之中，以爵為位，崇德也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-23_s-2","passageId":"li-ji_ch-8_p-23","order":2,"canonicalText":"宗人授事以官，尊賢也。","chunks":[["宗人授事以官，尊賢也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-23_s-3","passageId":"li-ji_ch-8_p-23","order":3,"canonicalText":"登餕受爵以上嗣，尊祖之道也。","chunks":[["登餕受爵以上嗣，尊祖之道也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-24_s-1","passageId":"li-ji_ch-8_p-24","order":1,"canonicalText":"喪紀以服之輕重為序，不奪人親也。","chunks":[["喪紀以服之輕重為序，不奪人親也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-25_s-1","passageId":"li-ji_ch-8_p-25","order":1,"canonicalText":"公與族燕則以齒，而孝弟之道達矣。","chunks":[["公與族燕則以齒，而孝弟之道達矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-25_s-2","passageId":"li-ji_ch-8_p-25","order":2,"canonicalText":"其族食世降一等，親親之殺也。","chunks":[["其族食世降一等，親親之殺也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-26_s-1","passageId":"li-ji_ch-8_p-26","order":1,"canonicalText":"戰則守於公禰，孝愛之深也。","chunks":[["戰則守於公禰，孝愛之深也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-26_s-2","passageId":"li-ji_ch-8_p-26","order":2,"canonicalText":"正室守大廟，尊宗室，而君臣之道著矣。","chunks":[["正室守大廟，尊宗室，而君臣之道著矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-26_s-3","passageId":"li-ji_ch-8_p-26","order":3,"canonicalText":"諸父諸兄守貴室，子弟守下室，而讓道達矣。","chunks":[["諸父諸兄守貴室，子弟守下室，而讓道達矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-27_s-1","passageId":"li-ji_ch-8_p-27","order":1,"canonicalText":"五廟之孫，祖廟未毀，雖及庶人，冠，取妻必告，死必赴，不忘親也。","chunks":[["五廟之孫，祖廟未毀，雖及庶人，冠，取妻必告，死必赴，不忘親也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-27_s-2","passageId":"li-ji_ch-8_p-27","order":2,"canonicalText":"親未絕而列於庶人，賤無能也。","chunks":[["親未絕而列於庶人，賤無能也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-27_s-3","passageId":"li-ji_ch-8_p-27","order":3,"canonicalText":"敬吊臨賻賵，睦友之道也。","chunks":[["敬吊臨賻賵，睦友之道也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-28_s-1","passageId":"li-ji_ch-8_p-28","order":1,"canonicalText":"古者，庶子之官治，而邦國有倫；","chunks":[["古者，庶子之官治，而邦國有倫；","zh-Hant"]]},{"id":"li-ji_ch-8_p-28_s-2","passageId":"li-ji_ch-8_p-28","order":2,"canonicalText":"邦國有倫，而眾鄉方矣。","chunks":[["邦國有倫，而眾鄉方矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-29_s-1","passageId":"li-ji_ch-8_p-29","order":1,"canonicalText":"公族之罪，雖親不以犯有司，正術也，所以體百姓也。","chunks":[["公族之罪，雖親不以犯有司，正術也，所以體百姓也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-29_s-2","passageId":"li-ji_ch-8_p-29","order":2,"canonicalText":"刑於隱者，不與國人慮兄弟也。","chunks":[["刑於隱者，不與國人慮兄弟也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-29_s-3","passageId":"li-ji_ch-8_p-29","order":3,"canonicalText":"弗吊，弗為服，哭於異姓之廟，為忝祖遠之也。","chunks":[["弗吊，弗為服，哭於異姓之廟，為忝祖遠之也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-29_s-4","passageId":"li-ji_ch-8_p-29","order":4,"canonicalText":"素服居外，不聽樂，私喪之也，骨肉之親無絕也。","chunks":[["素服居外，不聽樂，私喪之也，骨肉之親無絕也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-29_s-5","passageId":"li-ji_ch-8_p-29","order":5,"canonicalText":"公族無宮刑，不翦其類也。","chunks":[["公族無宮刑，不翦其類也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-1","passageId":"li-ji_ch-8_p-30","order":1,"canonicalText":"天子視學，大昕鼓徵，所以警眾也。","chunks":[["天子視學，大昕鼓徵，所以警眾也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-2","passageId":"li-ji_ch-8_p-30","order":2,"canonicalText":"眾至，然後天子至。","chunks":[["眾至，然後天子至。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-3","passageId":"li-ji_ch-8_p-30","order":3,"canonicalText":"乃命有司行事。","chunks":[["乃命有司行事。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-4","passageId":"li-ji_ch-8_p-30","order":4,"canonicalText":"興秩節，祭先師先聖焉。","chunks":[["興秩節，祭先師先聖焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-5","passageId":"li-ji_ch-8_p-30","order":5,"canonicalText":"有司卒事，反命。","chunks":[["有司卒事，反命。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-6","passageId":"li-ji_ch-8_p-30","order":6,"canonicalText":"始之養也：適東序，釋奠於先老，遂設三老五更群老之席位焉。","chunks":[["始之養也：適東序，釋奠於先老，遂設三老五更群老之席位焉。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-7","passageId":"li-ji_ch-8_p-30","order":7,"canonicalText":"適饌省醴，養老之珍，具；","chunks":[["適饌省醴，養老之珍，具；","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-8","passageId":"li-ji_ch-8_p-30","order":8,"canonicalText":"遂發詠焉，退修之以孝養也。","chunks":[["遂發詠焉，退修之以孝養也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-9","passageId":"li-ji_ch-8_p-30","order":9,"canonicalText":"反，登歌清廟，既歌而語，以成之也。","chunks":[["反，登歌清廟，既歌而語，以成之也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-10","passageId":"li-ji_ch-8_p-30","order":10,"canonicalText":"言父子、君臣、長幼之道，合德音之致，禮之大者也。","chunks":[["言父子、君臣、長幼之道，合德音之致，禮之大者也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-11","passageId":"li-ji_ch-8_p-30","order":11,"canonicalText":"下管《象》，舞《大武》。","chunks":[["下管《象》，舞《大武》。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-12","passageId":"li-ji_ch-8_p-30","order":12,"canonicalText":"大合眾以事，達有神，興有德也。","chunks":[["大合眾以事，達有神，興有德也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-13","passageId":"li-ji_ch-8_p-30","order":13,"canonicalText":"正君臣之位、貴賤之等焉，而上下之義行矣。","chunks":[["正君臣之位、貴賤之等焉，而上下之義行矣。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-14","passageId":"li-ji_ch-8_p-30","order":14,"canonicalText":"有司告以樂闋，王乃命公侯伯子男及群吏曰：「反！","chunks":[["有司告以樂闋，王乃命公侯伯子男及群吏曰：「反！","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-15","passageId":"li-ji_ch-8_p-30","order":15,"canonicalText":"養老幼於東序。","chunks":[["養老幼於東序。","zh-Hant"]]},{"id":"li-ji_ch-8_p-30_s-16","passageId":"li-ji_ch-8_p-30","order":16,"canonicalText":"」終之以仁也。","chunks":[["」終之以仁也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-31_s-1","passageId":"li-ji_ch-8_p-31","order":1,"canonicalText":"是故聖人之記事也，慮之以大，愛之以敬，行之以禮，修之以孝養，紀之以義，終之以仁。","chunks":[["是故聖人之記事也，慮之以大，愛之以敬，行之以禮，修之以孝養，紀之以義，終之以仁。","zh-Hant"]]},{"id":"li-ji_ch-8_p-31_s-2","passageId":"li-ji_ch-8_p-31","order":2,"canonicalText":"是故古之人一舉事而眾皆知其德之備也。","chunks":[["是故古之人一舉事而眾皆知其德之備也。","zh-Hant"]]},{"id":"li-ji_ch-8_p-31_s-3","passageId":"li-ji_ch-8_p-31","order":3,"canonicalText":"古之君子，舉大事，必慎其終始，而眾安得不喻焉？","chunks":[["古之君子，舉大事，必慎其終始，而眾安得不喻焉？","zh-Hant"]]},{"id":"li-ji_ch-8_p-31_s-4","passageId":"li-ji_ch-8_p-31","order":4,"canonicalText":"《兌命》曰：「念終始典於學。","chunks":[["《兌命》曰：「念終始典於學。","zh-Hant"]]},{"id":"li-ji_ch-8_p-31_s-5","passageId":"li-ji_ch-8_p-31","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-1","passageId":"li-ji_ch-8_p-32","order":1,"canonicalText":"世子之記曰：朝夕至於大寢之門外，問於內豎曰：「今日安否何如？","chunks":[["世子之記曰：朝夕至於大寢之門外，問於內豎曰：「今日安否何如？","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-2","passageId":"li-ji_ch-8_p-32","order":2,"canonicalText":"」內豎曰：「今日安。","chunks":[["」內豎曰：「今日安。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-3","passageId":"li-ji_ch-8_p-32","order":3,"canonicalText":"」世子乃有喜色。","chunks":[["」世子乃有喜色。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-4","passageId":"li-ji_ch-8_p-32","order":4,"canonicalText":"其有不安節，則內豎以告世子，世子色憂不滿容。","chunks":[["其有不安節，則內豎以告世子，世子色憂不滿容。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-5","passageId":"li-ji_ch-8_p-32","order":5,"canonicalText":"內豎言「復初」，然後亦復初。","chunks":[["內豎言「復初」，然後亦復初。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-6","passageId":"li-ji_ch-8_p-32","order":6,"canonicalText":"朝夕之食上，世子必在，視寒暖之節。","chunks":[["朝夕之食上，世子必在，視寒暖之節。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-7","passageId":"li-ji_ch-8_p-32","order":7,"canonicalText":"食下，問所膳羞。","chunks":[["食下，問所膳羞。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-8","passageId":"li-ji_ch-8_p-32","order":8,"canonicalText":"必知所進，以命膳宰，然後退。","chunks":[["必知所進，以命膳宰，然後退。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-9","passageId":"li-ji_ch-8_p-32","order":9,"canonicalText":"若內豎言「疾」，則世子親齊玄而養。","chunks":[["若內豎言「疾」，則世子親齊玄而養。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-10","passageId":"li-ji_ch-8_p-32","order":10,"canonicalText":"膳宰之饌，必敬視之；","chunks":[["膳宰之饌，必敬視之；","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-11","passageId":"li-ji_ch-8_p-32","order":11,"canonicalText":"疾之藥，必親嘗之。","chunks":[["疾之藥，必親嘗之。","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-12","passageId":"li-ji_ch-8_p-32","order":12,"canonicalText":"嘗饌善，則世子亦能食；","chunks":[["嘗饌善，則世子亦能食；","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-13","passageId":"li-ji_ch-8_p-32","order":13,"canonicalText":"嘗饌寡，世子亦不能飽；","chunks":[["嘗饌寡，世子亦不能飽；","zh-Hant"]]},{"id":"li-ji_ch-8_p-32_s-14","passageId":"li-ji_ch-8_p-32","order":14,"canonicalText":"以至於復初，然後亦復初。","chunks":[["以至於復初，然後亦復初。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-1","passageId":"li-ji_ch-9_p-1","order":1,"canonicalText":"昔者仲尼與於蜡賓，事畢，出游於觀之上，喟然而嘆。","chunks":[["昔者仲尼與於蜡賓，事畢，出游於觀之上，喟然而嘆。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-2","passageId":"li-ji_ch-9_p-1","order":2,"canonicalText":"仲尼之嘆，蓋嘆魯也。","chunks":[["仲尼之嘆，蓋嘆魯也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-3","passageId":"li-ji_ch-9_p-1","order":3,"canonicalText":"言偃在側曰：「君子何嘆？","chunks":[["言偃在側曰：「君子何嘆？","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-4","passageId":"li-ji_ch-9_p-1","order":4,"canonicalText":"」孔子曰：「大道之行也，與三代之英，丘未之逮也，而有志焉。","chunks":[["」孔子曰：「大道之行也，與三代之英，丘未之逮也，而有志焉。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-5","passageId":"li-ji_ch-9_p-1","order":5,"canonicalText":"」大道之行也，天下為公。","chunks":[["」大道之行也，天下為公。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-6","passageId":"li-ji_ch-9_p-1","order":6,"canonicalText":"選賢與能，講信修睦，故人不獨親其親，不獨子其子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者，皆有所養。","chunks":[["選賢與能，講信修睦，故人不獨親其親，不獨子其子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者，皆有所養。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-7","passageId":"li-ji_ch-9_p-1","order":7,"canonicalText":"男有分，女有歸。","chunks":[["男有分，女有歸。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-8","passageId":"li-ji_ch-9_p-1","order":8,"canonicalText":"貨惡其棄於地也，不必藏於己；","chunks":[["貨惡其棄於地也，不必藏於己；","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-9","passageId":"li-ji_ch-9_p-1","order":9,"canonicalText":"力惡其不出於身也，不必為己。","chunks":[["力惡其不出於身也，不必為己。","zh-Hant"]]},{"id":"li-ji_ch-9_p-1_s-10","passageId":"li-ji_ch-9_p-1","order":10,"canonicalText":"是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉，是謂大同。","chunks":[["是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉，是謂大同。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-1","passageId":"li-ji_ch-9_p-2","order":1,"canonicalText":"今大道既隱，天下為家，各親其親，各子其子，貨力為己，大人世及以為禮。","chunks":[["今大道既隱，天下為家，各親其親，各子其子，貨力為己，大人世及以為禮。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-2","passageId":"li-ji_ch-9_p-2","order":2,"canonicalText":"城郭溝池以為固，禮義以為紀；","chunks":[["城郭溝池以為固，禮義以為紀；","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-3","passageId":"li-ji_ch-9_p-2","order":3,"canonicalText":"以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。","chunks":[["以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-4","passageId":"li-ji_ch-9_p-2","order":4,"canonicalText":"故謀用是作，而兵由此起。","chunks":[["故謀用是作，而兵由此起。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-5","passageId":"li-ji_ch-9_p-2","order":5,"canonicalText":"禹、湯、文、武、成王、周公，由此其選也。","chunks":[["禹、湯、文、武、成王、周公，由此其選也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-6","passageId":"li-ji_ch-9_p-2","order":6,"canonicalText":"此六君子者，未有不謹於禮者也。","chunks":[["此六君子者，未有不謹於禮者也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-7","passageId":"li-ji_ch-9_p-2","order":7,"canonicalText":"以著其義，以考其信，著有過，刑仁講讓，示民有常。","chunks":[["以著其義，以考其信，著有過，刑仁講讓，示民有常。","zh-Hant"]]},{"id":"li-ji_ch-9_p-2_s-8","passageId":"li-ji_ch-9_p-2","order":8,"canonicalText":"如有不由此者，在勢者去，眾以為殃，是謂小康。","chunks":[["如有不由此者，在勢者去，眾以為殃，是謂小康。","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-1","passageId":"li-ji_ch-9_p-3","order":1,"canonicalText":"言偃復問曰：「如此乎禮之急也？","chunks":[["言偃復問曰：「如此乎禮之急也？","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-2","passageId":"li-ji_ch-9_p-3","order":2,"canonicalText":"」孔子曰：「夫禮，先王以承天之道，以治人之情。","chunks":[["」孔子曰：「夫禮，先王以承天之道，以治人之情。","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-3","passageId":"li-ji_ch-9_p-3","order":3,"canonicalText":"故失之者死，得之者生。","chunks":[["故失之者死，得之者生。","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-4","passageId":"li-ji_ch-9_p-3","order":4,"canonicalText":"《詩》曰：『相鼠有體，人而無禮；","chunks":[["《詩》曰：『相鼠有體，人而無禮；","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-5","passageId":"li-ji_ch-9_p-3","order":5,"canonicalText":"人而無禮，胡不遄死？","chunks":[["人而無禮，胡不遄死？","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-6","passageId":"li-ji_ch-9_p-3","order":6,"canonicalText":"』是故夫禮，必本於天，殽於地，列於鬼神，達於喪祭、射御、冠昏、朝聘。","chunks":[["』是故夫禮，必本於天，殽於地，列於鬼神，達於喪祭、射御、冠昏、朝聘。","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-7","passageId":"li-ji_ch-9_p-3","order":7,"canonicalText":"故聖人以禮示之，故天下國家可得而正也。","chunks":[["故聖人以禮示之，故天下國家可得而正也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-3_s-8","passageId":"li-ji_ch-9_p-3","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-1","passageId":"li-ji_ch-9_p-4","order":1,"canonicalText":"言偃復問曰：「夫子之極言禮也，可得而聞與？","chunks":[["言偃復問曰：「夫子之極言禮也，可得而聞與？","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-2","passageId":"li-ji_ch-9_p-4","order":2,"canonicalText":"」孔子曰：「我欲觀夏道，是故之杞，而不足徵也；","chunks":[["」孔子曰：「我欲觀夏道，是故之杞，而不足徵也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-3","passageId":"li-ji_ch-9_p-4","order":3,"canonicalText":"吾得夏時焉。","chunks":[["吾得夏時焉。","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-4","passageId":"li-ji_ch-9_p-4","order":4,"canonicalText":"我欲觀殷道，是故之宋，而不足徵也；","chunks":[["我欲觀殷道，是故之宋，而不足徵也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-5","passageId":"li-ji_ch-9_p-4","order":5,"canonicalText":"吾得坤乾焉。","chunks":[["吾得坤乾焉。","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-6","passageId":"li-ji_ch-9_p-4","order":6,"canonicalText":"坤乾之義，夏時之等，吾以是觀之。","chunks":[["坤乾之義，夏時之等，吾以是觀之。","zh-Hant"]]},{"id":"li-ji_ch-9_p-4_s-7","passageId":"li-ji_ch-9_p-4","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-9_p-5_s-1","passageId":"li-ji_ch-9_p-5","order":1,"canonicalText":"夫禮之初，始諸飲食，其燔黍捭豚，污尊而抔飲，蕢桴而土鼓，猶若可以致其敬於鬼神。","chunks":[["夫禮之初，始諸飲食，其燔黍捭豚，污尊而抔飲，蕢桴而土鼓，猶若可以致其敬於鬼神。","zh-Hant"]]},{"id":"li-ji_ch-9_p-5_s-2","passageId":"li-ji_ch-9_p-5","order":2,"canonicalText":"及其死也，升屋而號，告曰：「皋！","chunks":[["及其死也，升屋而號，告曰：「皋！","zh-Hant"]]},{"id":"li-ji_ch-9_p-5_s-3","passageId":"li-ji_ch-9_p-5","order":3,"canonicalText":"某復。","chunks":[["某復。","zh-Hant"]]},{"id":"li-ji_ch-9_p-5_s-4","passageId":"li-ji_ch-9_p-5","order":4,"canonicalText":"」然後飯腥而苴孰。","chunks":[["」然後飯腥而苴孰。","zh-Hant"]]},{"id":"li-ji_ch-9_p-5_s-5","passageId":"li-ji_ch-9_p-5","order":5,"canonicalText":"故天望而地藏也，體魄則降，知氣在上，故死者北首，生者南鄉，皆從其初。","chunks":[["故天望而地藏也，體魄則降，知氣在上，故死者北首，生者南鄉，皆從其初。","zh-Hant"]]},{"id":"li-ji_ch-9_p-6_s-1","passageId":"li-ji_ch-9_p-6","order":1,"canonicalText":"昔者先王，未有宮室，冬則居營窟，夏則居橧巢。","chunks":[["昔者先王，未有宮室，冬則居營窟，夏則居橧巢。","zh-Hant"]]},{"id":"li-ji_ch-9_p-6_s-2","passageId":"li-ji_ch-9_p-6","order":2,"canonicalText":"未有火化，食草木之實、鳥獸之肉，飲其血，茹其毛。","chunks":[["未有火化，食草木之實、鳥獸之肉，飲其血，茹其毛。","zh-Hant"]]},{"id":"li-ji_ch-9_p-6_s-3","passageId":"li-ji_ch-9_p-6","order":3,"canonicalText":"未有麻絲，衣其羽皮。","chunks":[["未有麻絲，衣其羽皮。","zh-Hant"]]},{"id":"li-ji_ch-9_p-6_s-4","passageId":"li-ji_ch-9_p-6","order":4,"canonicalText":"後聖有作，然後修火之利，范金合土，以為臺榭、宮室、牖戶，以炮以燔，以亨以炙，以為醴酪；","chunks":[["後聖有作，然後修火之利，范金合土，以為臺榭、宮室、牖戶，以炮以燔，以亨以炙，以為醴酪；","zh-Hant"]]},{"id":"li-ji_ch-9_p-6_s-5","passageId":"li-ji_ch-9_p-6","order":5,"canonicalText":"治其麻絲，以為布帛，以養生送死，以事鬼神上帝，皆從其朔。","chunks":[["治其麻絲，以為布帛，以養生送死，以事鬼神上帝，皆從其朔。","zh-Hant"]]},{"id":"li-ji_ch-9_p-7_s-1","passageId":"li-ji_ch-9_p-7","order":1,"canonicalText":"故玄酒在室，醴醆在戶，粢醍在堂，澄酒在下。","chunks":[["故玄酒在室，醴醆在戶，粢醍在堂，澄酒在下。","zh-Hant"]]},{"id":"li-ji_ch-9_p-7_s-2","passageId":"li-ji_ch-9_p-7","order":2,"canonicalText":"陳其犧牲，備其鼎俎，列其琴瑟管磬鐘鼓，修其祝嘏，以降上神與其先祖。","chunks":[["陳其犧牲，備其鼎俎，列其琴瑟管磬鐘鼓，修其祝嘏，以降上神與其先祖。","zh-Hant"]]},{"id":"li-ji_ch-9_p-7_s-3","passageId":"li-ji_ch-9_p-7","order":3,"canonicalText":"以正君臣，以篤父子，以睦兄弟，以齊上下，夫婦有所。","chunks":[["以正君臣，以篤父子，以睦兄弟，以齊上下，夫婦有所。","zh-Hant"]]},{"id":"li-ji_ch-9_p-7_s-4","passageId":"li-ji_ch-9_p-7","order":4,"canonicalText":"是謂承天之祜。","chunks":[["是謂承天之祜。","zh-Hant"]]},{"id":"li-ji_ch-9_p-8_s-1","passageId":"li-ji_ch-9_p-8","order":1,"canonicalText":"作其祝號，玄酒以祭，薦其血毛，腥其俎，孰其殽，與其越席，疏布以冪，衣其浣帛，醴醆以獻，薦其燔炙，君與夫人交獻，以嘉魂魄，是謂合莫。","chunks":[["作其祝號，玄酒以祭，薦其血毛，腥其俎，孰其殽，與其越席，疏布以冪，衣其浣帛，醴醆以獻，薦其燔炙，君與夫人交獻，以嘉魂魄，是謂合莫。","zh-Hant"]]},{"id":"li-ji_ch-9_p-8_s-2","passageId":"li-ji_ch-9_p-8","order":2,"canonicalText":"然後退而合亨，體其犬豕牛羊，實其簠簋、籩豆、鉶羹。","chunks":[["然後退而合亨，體其犬豕牛羊，實其簠簋、籩豆、鉶羹。","zh-Hant"]]},{"id":"li-ji_ch-9_p-8_s-3","passageId":"li-ji_ch-9_p-8","order":3,"canonicalText":"祝以孝告，嘏以慈告，是謂大祥。","chunks":[["祝以孝告，嘏以慈告，是謂大祥。","zh-Hant"]]},{"id":"li-ji_ch-9_p-8_s-4","passageId":"li-ji_ch-9_p-8","order":4,"canonicalText":"此禮之大成也。","chunks":[["此禮之大成也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-1","passageId":"li-ji_ch-9_p-9","order":1,"canonicalText":"孔子曰：「於呼哀哉！","chunks":[["孔子曰：「於呼哀哉！","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-2","passageId":"li-ji_ch-9_p-9","order":2,"canonicalText":"我觀周道，幽、厲傷之，吾舍魯何適矣！","chunks":[["我觀周道，幽、厲傷之，吾舍魯何適矣！","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-3","passageId":"li-ji_ch-9_p-9","order":3,"canonicalText":"魯之郊禘，非禮也，周公其衰矣！","chunks":[["魯之郊禘，非禮也，周公其衰矣！","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-4","passageId":"li-ji_ch-9_p-9","order":4,"canonicalText":"杞之郊也禹也，宋之郊也契也，是天子之事守也。","chunks":[["杞之郊也禹也，宋之郊也契也，是天子之事守也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-5","passageId":"li-ji_ch-9_p-9","order":5,"canonicalText":"故天子祭天地，諸侯祭社稷。","chunks":[["故天子祭天地，諸侯祭社稷。","zh-Hant"]]},{"id":"li-ji_ch-9_p-9_s-6","passageId":"li-ji_ch-9_p-9","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-9_p-10_s-1","passageId":"li-ji_ch-9_p-10","order":1,"canonicalText":"祝嘏莫敢易其常古，是謂大假。","chunks":[["祝嘏莫敢易其常古，是謂大假。","zh-Hant"]]},{"id":"li-ji_ch-9_p-10_s-2","passageId":"li-ji_ch-9_p-10","order":2,"canonicalText":"祝嘏辭說，藏於宗祝巫史，非禮也，是謂幽國。","chunks":[["祝嘏辭說，藏於宗祝巫史，非禮也，是謂幽國。","zh-Hant"]]},{"id":"li-ji_ch-9_p-10_s-3","passageId":"li-ji_ch-9_p-10","order":3,"canonicalText":"醆斝及尸君，非禮也，是謂僭君。","chunks":[["醆斝及尸君，非禮也，是謂僭君。","zh-Hant"]]},{"id":"li-ji_ch-9_p-10_s-4","passageId":"li-ji_ch-9_p-10","order":4,"canonicalText":"冕弁兵革藏於私家，非禮也，是謂脅君。","chunks":[["冕弁兵革藏於私家，非禮也，是謂脅君。","zh-Hant"]]},{"id":"li-ji_ch-9_p-10_s-5","passageId":"li-ji_ch-9_p-10","order":5,"canonicalText":"大夫具官，祭器不假，聲樂皆具，非禮也，是謂亂國。","chunks":[["大夫具官，祭器不假，聲樂皆具，非禮也，是謂亂國。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-1","passageId":"li-ji_ch-9_p-11","order":1,"canonicalText":"故仕於公曰臣，仕於家曰仆。","chunks":[["故仕於公曰臣，仕於家曰仆。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-2","passageId":"li-ji_ch-9_p-11","order":2,"canonicalText":"三年之喪，與新有昏者，期不使。","chunks":[["三年之喪，與新有昏者，期不使。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-3","passageId":"li-ji_ch-9_p-11","order":3,"canonicalText":"以衰裳入朝，與家仆雜居齊齒，非禮也，是謂君與臣同國。","chunks":[["以衰裳入朝，與家仆雜居齊齒，非禮也，是謂君與臣同國。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-4","passageId":"li-ji_ch-9_p-11","order":4,"canonicalText":"故天子有田以處其子孫，諸侯有國以處其子孫，大夫有采以處其子孫，是謂制度。","chunks":[["故天子有田以處其子孫，諸侯有國以處其子孫，大夫有采以處其子孫，是謂制度。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-5","passageId":"li-ji_ch-9_p-11","order":5,"canonicalText":"故天子適諸侯，必舍其祖朝，而不以禮籍入，是謂天子壞法亂紀。","chunks":[["故天子適諸侯，必舍其祖朝，而不以禮籍入，是謂天子壞法亂紀。","zh-Hant"]]},{"id":"li-ji_ch-9_p-11_s-6","passageId":"li-ji_ch-9_p-11","order":6,"canonicalText":"諸侯非問疾吊喪而入諸臣之家，是謂君臣為謔。","chunks":[["諸侯非問疾吊喪而入諸臣之家，是謂君臣為謔。","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-1","passageId":"li-ji_ch-9_p-12","order":1,"canonicalText":"是故，禮者君之大柄也，所以別嫌明微，儐鬼神，考制度，別仁義，所以治政安君也。","chunks":[["是故，禮者君之大柄也，所以別嫌明微，儐鬼神，考制度，別仁義，所以治政安君也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-2","passageId":"li-ji_ch-9_p-12","order":2,"canonicalText":"故政不正，則君位危；","chunks":[["故政不正，則君位危；","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-3","passageId":"li-ji_ch-9_p-12","order":3,"canonicalText":"君位危，則大臣倍，小臣竊。","chunks":[["君位危，則大臣倍，小臣竊。","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-4","passageId":"li-ji_ch-9_p-12","order":4,"canonicalText":"刑肅而俗敝，則法無常；","chunks":[["刑肅而俗敝，則法無常；","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-5","passageId":"li-ji_ch-9_p-12","order":5,"canonicalText":"法無常，而禮無列；","chunks":[["法無常，而禮無列；","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-6","passageId":"li-ji_ch-9_p-12","order":6,"canonicalText":"禮無列，則士不事也。","chunks":[["禮無列，則士不事也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-12_s-7","passageId":"li-ji_ch-9_p-12","order":7,"canonicalText":"刑肅而俗敝，則民弗歸也，是謂疵國。","chunks":[["刑肅而俗敝，則民弗歸也，是謂疵國。","zh-Hant"]]},{"id":"li-ji_ch-9_p-13_s-1","passageId":"li-ji_ch-9_p-13","order":1,"canonicalText":"故政者君之所以藏身也。","chunks":[["故政者君之所以藏身也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-13_s-2","passageId":"li-ji_ch-9_p-13","order":2,"canonicalText":"是故夫政必本於天，殽以降命。","chunks":[["是故夫政必本於天，殽以降命。","zh-Hant"]]},{"id":"li-ji_ch-9_p-13_s-3","passageId":"li-ji_ch-9_p-13","order":3,"canonicalText":"命降于社之謂殽地，降于祖廟之謂仁義，降於山川之謂興作，降於五祀之謂制度。","chunks":[["命降于社之謂殽地，降于祖廟之謂仁義，降於山川之謂興作，降於五祀之謂制度。","zh-Hant"]]},{"id":"li-ji_ch-9_p-13_s-4","passageId":"li-ji_ch-9_p-13","order":4,"canonicalText":"此聖人所以藏身之固也。","chunks":[["此聖人所以藏身之固也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-14_s-1","passageId":"li-ji_ch-9_p-14","order":1,"canonicalText":"故聖人參於天地，并於鬼神，以治政也。","chunks":[["故聖人參於天地，并於鬼神，以治政也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-14_s-2","passageId":"li-ji_ch-9_p-14","order":2,"canonicalText":"處其所存，禮之序也；","chunks":[["處其所存，禮之序也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-14_s-3","passageId":"li-ji_ch-9_p-14","order":3,"canonicalText":"玩其所樂，民之治也。","chunks":[["玩其所樂，民之治也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-14_s-4","passageId":"li-ji_ch-9_p-14","order":4,"canonicalText":"故天生時而地生財，人其父生而師教之：四者，君以正用之，故君者立於無過之地也。","chunks":[["故天生時而地生財，人其父生而師教之：四者，君以正用之，故君者立於無過之地也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-1","passageId":"li-ji_ch-9_p-15","order":1,"canonicalText":"故君者所明也，非明人者也。","chunks":[["故君者所明也，非明人者也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-2","passageId":"li-ji_ch-9_p-15","order":2,"canonicalText":"君者所養也，非養人者也。","chunks":[["君者所養也，非養人者也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-3","passageId":"li-ji_ch-9_p-15","order":3,"canonicalText":"君者所事也，非事人者也。","chunks":[["君者所事也，非事人者也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-4","passageId":"li-ji_ch-9_p-15","order":4,"canonicalText":"故君明人則有過，養人則不足，事人則失位。","chunks":[["故君明人則有過，養人則不足，事人則失位。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-5","passageId":"li-ji_ch-9_p-15","order":5,"canonicalText":"故百姓則君以自治也，養君以自安也，事君以自顯也。","chunks":[["故百姓則君以自治也，養君以自安也，事君以自顯也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-15_s-6","passageId":"li-ji_ch-9_p-15","order":6,"canonicalText":"故禮達而分定，人皆愛其死而患其生。","chunks":[["故禮達而分定，人皆愛其死而患其生。","zh-Hant"]]},{"id":"li-ji_ch-9_p-16_s-1","passageId":"li-ji_ch-9_p-16","order":1,"canonicalText":"故用人之知去其詐，用人之勇去其怒，用人之仁去其貪。","chunks":[["故用人之知去其詐，用人之勇去其怒，用人之仁去其貪。","zh-Hant"]]},{"id":"li-ji_ch-9_p-17_s-1","passageId":"li-ji_ch-9_p-17","order":1,"canonicalText":"故國有患，君死社稷謂之義，大夫死宗廟謂之變。","chunks":[["故國有患，君死社稷謂之義，大夫死宗廟謂之變。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-1","passageId":"li-ji_ch-9_p-18","order":1,"canonicalText":"故聖人耐以天下為一家，以中國為一人者，非意之也，必知其情，辟於其義，明於其利，達於其患，然後能為之。","chunks":[["故聖人耐以天下為一家，以中國為一人者，非意之也，必知其情，辟於其義，明於其利，達於其患，然後能為之。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-2","passageId":"li-ji_ch-9_p-18","order":2,"canonicalText":"何謂人情？","chunks":[["何謂人情？","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-3","passageId":"li-ji_ch-9_p-18","order":3,"canonicalText":"喜怒哀懼愛惡欲七者，弗學而能。","chunks":[["喜怒哀懼愛惡欲七者，弗學而能。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-4","passageId":"li-ji_ch-9_p-18","order":4,"canonicalText":"何謂人義？","chunks":[["何謂人義？","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-5","passageId":"li-ji_ch-9_p-18","order":5,"canonicalText":"父慈、子孝、兄良、弟弟、夫義、婦聽、長惠、幼順、君仁、臣忠十者，謂之人義。","chunks":[["父慈、子孝、兄良、弟弟、夫義、婦聽、長惠、幼順、君仁、臣忠十者，謂之人義。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-6","passageId":"li-ji_ch-9_p-18","order":6,"canonicalText":"講信修睦，謂之人利。","chunks":[["講信修睦，謂之人利。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-7","passageId":"li-ji_ch-9_p-18","order":7,"canonicalText":"爭奪相殺，謂之人患。","chunks":[["爭奪相殺，謂之人患。","zh-Hant"]]},{"id":"li-ji_ch-9_p-18_s-8","passageId":"li-ji_ch-9_p-18","order":8,"canonicalText":"故聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之？","chunks":[["故聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之？","zh-Hant"]]},{"id":"li-ji_ch-9_p-19_s-1","passageId":"li-ji_ch-9_p-19","order":1,"canonicalText":"飲食男女，人之大欲存焉；","chunks":[["飲食男女，人之大欲存焉；","zh-Hant"]]},{"id":"li-ji_ch-9_p-19_s-2","passageId":"li-ji_ch-9_p-19","order":2,"canonicalText":"死亡貧苦，人之大惡存焉。","chunks":[["死亡貧苦，人之大惡存焉。","zh-Hant"]]},{"id":"li-ji_ch-9_p-19_s-3","passageId":"li-ji_ch-9_p-19","order":3,"canonicalText":"故欲惡者，心之大端也。","chunks":[["故欲惡者，心之大端也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-19_s-4","passageId":"li-ji_ch-9_p-19","order":4,"canonicalText":"人藏其心，不可測度也；","chunks":[["人藏其心，不可測度也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-19_s-5","passageId":"li-ji_ch-9_p-19","order":5,"canonicalText":"美惡皆在其心，不見其色也，欲一以窮之，舍禮何以哉？","chunks":[["美惡皆在其心，不見其色也，欲一以窮之，舍禮何以哉？","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-1","passageId":"li-ji_ch-9_p-20","order":1,"canonicalText":"故人者，其天地之德，陰陽之交，鬼神之會，五行之秀氣也。","chunks":[["故人者，其天地之德，陰陽之交，鬼神之會，五行之秀氣也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-2","passageId":"li-ji_ch-9_p-20","order":2,"canonicalText":"故天秉陽，垂日星；","chunks":[["故天秉陽，垂日星；","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-3","passageId":"li-ji_ch-9_p-20","order":3,"canonicalText":"地秉陰，竅於山川。","chunks":[["地秉陰，竅於山川。","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-4","passageId":"li-ji_ch-9_p-20","order":4,"canonicalText":"播五行於四時，和而後月生也。","chunks":[["播五行於四時，和而後月生也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-5","passageId":"li-ji_ch-9_p-20","order":5,"canonicalText":"是以三五而盈，三五而闕。","chunks":[["是以三五而盈，三五而闕。","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-6","passageId":"li-ji_ch-9_p-20","order":6,"canonicalText":"五行之動，迭相竭也，五行、四時、十二月，還相為本也；","chunks":[["五行之動，迭相竭也，五行、四時、十二月，還相為本也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-7","passageId":"li-ji_ch-9_p-20","order":7,"canonicalText":"五聲、六律、十二管，還相為宮也；","chunks":[["五聲、六律、十二管，還相為宮也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-8","passageId":"li-ji_ch-9_p-20","order":8,"canonicalText":"五味、六和、十二食，還相為質也；","chunks":[["五味、六和、十二食，還相為質也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-9","passageId":"li-ji_ch-9_p-20","order":9,"canonicalText":"五色、六章、十二衣，還相為質也。","chunks":[["五色、六章、十二衣，還相為質也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-20_s-10","passageId":"li-ji_ch-9_p-20","order":10,"canonicalText":"故人者，天地之心也，五行之端也，食味別聲被色而生者也。","chunks":[["故人者，天地之心也，五行之端也，食味別聲被色而生者也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-21_s-1","passageId":"li-ji_ch-9_p-21","order":1,"canonicalText":"故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜。","chunks":[["故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜。","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-1","passageId":"li-ji_ch-9_p-22","order":1,"canonicalText":"以天地為本，故物可舉也；","chunks":[["以天地為本，故物可舉也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-2","passageId":"li-ji_ch-9_p-22","order":2,"canonicalText":"以陰陽為端，故情可睹也；","chunks":[["以陰陽為端，故情可睹也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-3","passageId":"li-ji_ch-9_p-22","order":3,"canonicalText":"以四時為柄，故事可勸也；","chunks":[["以四時為柄，故事可勸也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-4","passageId":"li-ji_ch-9_p-22","order":4,"canonicalText":"以日星為紀，故事可列也；","chunks":[["以日星為紀，故事可列也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-5","passageId":"li-ji_ch-9_p-22","order":5,"canonicalText":"月以為量，故功有藝也；","chunks":[["月以為量，故功有藝也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-6","passageId":"li-ji_ch-9_p-22","order":6,"canonicalText":"鬼神以為徒，故事有守也；","chunks":[["鬼神以為徒，故事有守也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-7","passageId":"li-ji_ch-9_p-22","order":7,"canonicalText":"五行以為質，故事可復也；","chunks":[["五行以為質，故事可復也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-8","passageId":"li-ji_ch-9_p-22","order":8,"canonicalText":"禮義以為器，故事行有考也；","chunks":[["禮義以為器，故事行有考也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-9","passageId":"li-ji_ch-9_p-22","order":9,"canonicalText":"人情以為田，故人以為奧也；","chunks":[["人情以為田，故人以為奧也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-22_s-10","passageId":"li-ji_ch-9_p-22","order":10,"canonicalText":"四靈以為畜，故飲食有由也。","chunks":[["四靈以為畜，故飲食有由也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-1","passageId":"li-ji_ch-9_p-23","order":1,"canonicalText":"何謂四靈？","chunks":[["何謂四靈？","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-2","passageId":"li-ji_ch-9_p-23","order":2,"canonicalText":"麟鳳龜龍，謂之四靈。","chunks":[["麟鳳龜龍，謂之四靈。","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-3","passageId":"li-ji_ch-9_p-23","order":3,"canonicalText":"故龍以為畜，故魚鮪不淰；","chunks":[["故龍以為畜，故魚鮪不淰；","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-4","passageId":"li-ji_ch-9_p-23","order":4,"canonicalText":"鳳以為畜，故鳥不獝；","chunks":[["鳳以為畜，故鳥不獝；","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-5","passageId":"li-ji_ch-9_p-23","order":5,"canonicalText":"麟以為畜，故獸不狘；","chunks":[["麟以為畜，故獸不狘；","zh-Hant"]]},{"id":"li-ji_ch-9_p-23_s-6","passageId":"li-ji_ch-9_p-23","order":6,"canonicalText":"龜以為畜，故人情不失。","chunks":[["龜以為畜，故人情不失。","zh-Hant"]]},{"id":"li-ji_ch-9_p-24_s-1","passageId":"li-ji_ch-9_p-24","order":1,"canonicalText":"故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序。","chunks":[["故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序。","zh-Hant"]]},{"id":"li-ji_ch-9_p-25_s-1","passageId":"li-ji_ch-9_p-25","order":1,"canonicalText":"故先王患禮之不達於下也，故祭帝於郊，所以定天位也；","chunks":[["故先王患禮之不達於下也，故祭帝於郊，所以定天位也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-25_s-2","passageId":"li-ji_ch-9_p-25","order":2,"canonicalText":"祀社於國，所以列地利也；","chunks":[["祀社於國，所以列地利也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-25_s-3","passageId":"li-ji_ch-9_p-25","order":3,"canonicalText":"祖廟所以本仁也，山川所以儐鬼神也，五祀所以本事也。","chunks":[["祖廟所以本仁也，山川所以儐鬼神也，五祀所以本事也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-25_s-4","passageId":"li-ji_ch-9_p-25","order":4,"canonicalText":"故宗祝在廟，三公在朝，三老在學。","chunks":[["故宗祝在廟，三公在朝，三老在學。","zh-Hant"]]},{"id":"li-ji_ch-9_p-25_s-5","passageId":"li-ji_ch-9_p-25","order":5,"canonicalText":"王，前巫而後史，卜筮瞽侑皆在左右，王中心無為也，以守至正。","chunks":[["王，前巫而後史，卜筮瞽侑皆在左右，王中心無為也，以守至正。","zh-Hant"]]},{"id":"li-ji_ch-9_p-26_s-1","passageId":"li-ji_ch-9_p-26","order":1,"canonicalText":"故禮行於郊，而百神受職焉，禮行於社，而百貨可極焉，禮行於祖廟而孝慈服焉，禮行於五祀而正法則焉。","chunks":[["故禮行於郊，而百神受職焉，禮行於社，而百貨可極焉，禮行於祖廟而孝慈服焉，禮行於五祀而正法則焉。","zh-Hant"]]},{"id":"li-ji_ch-9_p-26_s-2","passageId":"li-ji_ch-9_p-26","order":2,"canonicalText":"故自郊社、祖廟、山川、五祀，義之修而禮之藏也。","chunks":[["故自郊社、祖廟、山川、五祀，義之修而禮之藏也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-27_s-1","passageId":"li-ji_ch-9_p-27","order":1,"canonicalText":"是故夫禮，必本於大一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神。","chunks":[["是故夫禮，必本於大一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神。","zh-Hant"]]},{"id":"li-ji_ch-9_p-27_s-2","passageId":"li-ji_ch-9_p-27","order":2,"canonicalText":"其降曰命，其官於天也。","chunks":[["其降曰命，其官於天也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-27_s-3","passageId":"li-ji_ch-9_p-27","order":3,"canonicalText":"夫禮必本於天，動而之地，列而之事，變而從時，協於分藝，其居人也曰養，其行之以貨力、辭讓：飲食、冠昏、喪祭、射御、朝聘。","chunks":[["夫禮必本於天，動而之地，列而之事，變而從時，協於分藝，其居人也曰養，其行之以貨力、辭讓：飲食、冠昏、喪祭、射御、朝聘。","zh-Hant"]]},{"id":"li-ji_ch-9_p-28_s-1","passageId":"li-ji_ch-9_p-28","order":1,"canonicalText":"故禮義也者，人之大端也，所以講信修睦而固人之肌膚之會、筋骸之束也。","chunks":[["故禮義也者，人之大端也，所以講信修睦而固人之肌膚之會、筋骸之束也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-28_s-2","passageId":"li-ji_ch-9_p-28","order":2,"canonicalText":"所以養生送死事鬼神之大端也。","chunks":[["所以養生送死事鬼神之大端也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-28_s-3","passageId":"li-ji_ch-9_p-28","order":3,"canonicalText":"所以達天道順人情之大竇也。","chunks":[["所以達天道順人情之大竇也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-28_s-4","passageId":"li-ji_ch-9_p-28","order":4,"canonicalText":"故唯聖人為知禮之不可以已也，故壞國、喪家、亡人，必先去其禮。","chunks":[["故唯聖人為知禮之不可以已也，故壞國、喪家、亡人，必先去其禮。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-1","passageId":"li-ji_ch-9_p-29","order":1,"canonicalText":"故禮之於人也，猶酒之有蘗也，君子以厚，小人以薄。","chunks":[["故禮之於人也，猶酒之有蘗也，君子以厚，小人以薄。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-2","passageId":"li-ji_ch-9_p-29","order":2,"canonicalText":"故聖王修義之柄、禮之序，以治人情。","chunks":[["故聖王修義之柄、禮之序，以治人情。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-3","passageId":"li-ji_ch-9_p-29","order":3,"canonicalText":"故人情者，聖王之田也。","chunks":[["故人情者，聖王之田也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-4","passageId":"li-ji_ch-9_p-29","order":4,"canonicalText":"修禮以耕之，陳義以種之，講學以耨之，本仁以聚之，播樂以安之。","chunks":[["修禮以耕之，陳義以種之，講學以耨之，本仁以聚之，播樂以安之。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-5","passageId":"li-ji_ch-9_p-29","order":5,"canonicalText":"故禮也者，義之實也。","chunks":[["故禮也者，義之實也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-6","passageId":"li-ji_ch-9_p-29","order":6,"canonicalText":"協諸義而協，則禮雖先王未之有，可以義起也。","chunks":[["協諸義而協，則禮雖先王未之有，可以義起也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-7","passageId":"li-ji_ch-9_p-29","order":7,"canonicalText":"義者藝之分、仁之節也，協於藝，講於仁，得之者強。","chunks":[["義者藝之分、仁之節也，協於藝，講於仁，得之者強。","zh-Hant"]]},{"id":"li-ji_ch-9_p-29_s-8","passageId":"li-ji_ch-9_p-29","order":8,"canonicalText":"仁者，義之本也，順之體也，得之者尊。","chunks":[["仁者，義之本也，順之體也，得之者尊。","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-1","passageId":"li-ji_ch-9_p-30","order":1,"canonicalText":"故治國不以禮，猶無耜而耕也；","chunks":[["故治國不以禮，猶無耜而耕也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-2","passageId":"li-ji_ch-9_p-30","order":2,"canonicalText":"為禮不本於義，猶耕而弗種也；","chunks":[["為禮不本於義，猶耕而弗種也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-3","passageId":"li-ji_ch-9_p-30","order":3,"canonicalText":"為義而不講之以學，猶種而弗耨也；","chunks":[["為義而不講之以學，猶種而弗耨也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-4","passageId":"li-ji_ch-9_p-30","order":4,"canonicalText":"講之於學而不合之以仁，猶耨而弗獲也；","chunks":[["講之於學而不合之以仁，猶耨而弗獲也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-5","passageId":"li-ji_ch-9_p-30","order":5,"canonicalText":"合之以仁而不安之以樂，猶獲而弗食也；","chunks":[["合之以仁而不安之以樂，猶獲而弗食也；","zh-Hant"]]},{"id":"li-ji_ch-9_p-30_s-6","passageId":"li-ji_ch-9_p-30","order":6,"canonicalText":"安之以樂而不達於順，猶食而弗肥也。","chunks":[["安之以樂而不達於順，猶食而弗肥也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-31_s-1","passageId":"li-ji_ch-9_p-31","order":1,"canonicalText":"四體既正，膚革充盈，人之肥也。","chunks":[["四體既正，膚革充盈，人之肥也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-31_s-2","passageId":"li-ji_ch-9_p-31","order":2,"canonicalText":"父子篤，兄弟睦，夫婦和，家之肥也。","chunks":[["父子篤，兄弟睦，夫婦和，家之肥也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-31_s-3","passageId":"li-ji_ch-9_p-31","order":3,"canonicalText":"大臣法，小臣廉，官職相序，君臣相正，國之肥也。","chunks":[["大臣法，小臣廉，官職相序，君臣相正，國之肥也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-31_s-4","passageId":"li-ji_ch-9_p-31","order":4,"canonicalText":"天子以德為車、以樂為御，諸侯以禮相與，大夫以法相序，士以信相考，百姓以睦相守，天下之肥也。","chunks":[["天子以德為車、以樂為御，諸侯以禮相與，大夫以法相序，士以信相考，百姓以睦相守，天下之肥也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-31_s-5","passageId":"li-ji_ch-9_p-31","order":5,"canonicalText":"是謂大順。","chunks":[["是謂大順。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-1","passageId":"li-ji_ch-9_p-32","order":1,"canonicalText":"大順者，所以養生送死、事鬼神之常也。","chunks":[["大順者，所以養生送死、事鬼神之常也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-2","passageId":"li-ji_ch-9_p-32","order":2,"canonicalText":"故事大積焉而不苑，并行而不繆，細行而不失。","chunks":[["故事大積焉而不苑，并行而不繆，細行而不失。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-3","passageId":"li-ji_ch-9_p-32","order":3,"canonicalText":"深而通，茂而有間。","chunks":[["深而通，茂而有間。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-4","passageId":"li-ji_ch-9_p-32","order":4,"canonicalText":"連而不相及也，動而不相害也，此順之至也。","chunks":[["連而不相及也，動而不相害也，此順之至也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-5","passageId":"li-ji_ch-9_p-32","order":5,"canonicalText":"故明於順，然後能守危也。","chunks":[["故明於順，然後能守危也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-32_s-6","passageId":"li-ji_ch-9_p-32","order":6,"canonicalText":"故禮之不同也，不豐也，不殺也，所以持情而合危也。","chunks":[["故禮之不同也，不豐也，不殺也，所以持情而合危也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-1","passageId":"li-ji_ch-9_p-33","order":1,"canonicalText":"故聖王所以順，山者不使居川，不使渚者居中原，而弗敝也。","chunks":[["故聖王所以順，山者不使居川，不使渚者居中原，而弗敝也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-2","passageId":"li-ji_ch-9_p-33","order":2,"canonicalText":"用水火金木，飲食必時。","chunks":[["用水火金木，飲食必時。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-3","passageId":"li-ji_ch-9_p-33","order":3,"canonicalText":"合男女，頒爵位，必當年德。","chunks":[["合男女，頒爵位，必當年德。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-4","passageId":"li-ji_ch-9_p-33","order":4,"canonicalText":"用民必順。","chunks":[["用民必順。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-5","passageId":"li-ji_ch-9_p-33","order":5,"canonicalText":"故無水旱昆蟲之災，民無凶饑妖孽之疾。","chunks":[["故無水旱昆蟲之災，民無凶饑妖孽之疾。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-6","passageId":"li-ji_ch-9_p-33","order":6,"canonicalText":"故天不愛其道，地不愛其寶，人不愛其情。","chunks":[["故天不愛其道，地不愛其寶，人不愛其情。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-7","passageId":"li-ji_ch-9_p-33","order":7,"canonicalText":"故天降膏露，地出醴泉，山出器車，河出馬圖，鳳凰麒麟皆在郊棷，龜龍在宮沼，其餘鳥獸之卵胎，皆可俯而窺也。","chunks":[["故天降膏露，地出醴泉，山出器車，河出馬圖，鳳凰麒麟皆在郊棷，龜龍在宮沼，其餘鳥獸之卵胎，皆可俯而窺也。","zh-Hant"]]},{"id":"li-ji_ch-9_p-33_s-8","passageId":"li-ji_ch-9_p-33","order":8,"canonicalText":"則是無故，先王能修禮以達義，體信以達順，故此順之實也。","chunks":[["則是無故，先王能修禮以達義，體信以達順，故此順之實也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-1","passageId":"li-ji_ch-10_p-1","order":1,"canonicalText":"禮器是故大備。","chunks":[["禮器是故大備。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-2","passageId":"li-ji_ch-10_p-1","order":2,"canonicalText":"大備，盛德也。","chunks":[["大備，盛德也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-3","passageId":"li-ji_ch-10_p-1","order":3,"canonicalText":"禮釋回，增美質；","chunks":[["禮釋回，增美質；","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-4","passageId":"li-ji_ch-10_p-1","order":4,"canonicalText":"措則正，施則行。","chunks":[["措則正，施則行。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-5","passageId":"li-ji_ch-10_p-1","order":5,"canonicalText":"其在人也，如竹箭之有筠也；","chunks":[["其在人也，如竹箭之有筠也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-6","passageId":"li-ji_ch-10_p-1","order":6,"canonicalText":"如松柏之有心也。","chunks":[["如松柏之有心也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-7","passageId":"li-ji_ch-10_p-1","order":7,"canonicalText":"二者居天下之大端矣。","chunks":[["二者居天下之大端矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-8","passageId":"li-ji_ch-10_p-1","order":8,"canonicalText":"故貫四時而不改柯易葉。","chunks":[["故貫四時而不改柯易葉。","zh-Hant"]]},{"id":"li-ji_ch-10_p-1_s-9","passageId":"li-ji_ch-10_p-1","order":9,"canonicalText":"故君子有禮，則外諧而內無怨，故物無不懷仁，鬼神饗德。","chunks":[["故君子有禮，則外諧而內無怨，故物無不懷仁，鬼神饗德。","zh-Hant"]]},{"id":"li-ji_ch-10_p-2_s-1","passageId":"li-ji_ch-10_p-2","order":1,"canonicalText":"先王之立禮也，有本有文。","chunks":[["先王之立禮也，有本有文。","zh-Hant"]]},{"id":"li-ji_ch-10_p-2_s-2","passageId":"li-ji_ch-10_p-2","order":2,"canonicalText":"忠信，禮之本也；","chunks":[["忠信，禮之本也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-2_s-3","passageId":"li-ji_ch-10_p-2","order":3,"canonicalText":"義理，禮之文也。","chunks":[["義理，禮之文也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-2_s-4","passageId":"li-ji_ch-10_p-2","order":4,"canonicalText":"無本不立，無文不行。","chunks":[["無本不立，無文不行。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-1","passageId":"li-ji_ch-10_p-3","order":1,"canonicalText":"禮也者，合於天時，設於地財，順於鬼神，合於人心，理萬物者也。","chunks":[["禮也者，合於天時，設於地財，順於鬼神，合於人心，理萬物者也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-2","passageId":"li-ji_ch-10_p-3","order":2,"canonicalText":"是故天時有生也，地理有宜也，人官有能也，物曲有利也。","chunks":[["是故天時有生也，地理有宜也，人官有能也，物曲有利也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-3","passageId":"li-ji_ch-10_p-3","order":3,"canonicalText":"故天不生，地不養，君子不以為禮，鬼神弗饗也。","chunks":[["故天不生，地不養，君子不以為禮，鬼神弗饗也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-4","passageId":"li-ji_ch-10_p-3","order":4,"canonicalText":"居山以魚鱉為禮，居澤以鹿豕為禮，君子謂之不知禮。","chunks":[["居山以魚鱉為禮，居澤以鹿豕為禮，君子謂之不知禮。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-5","passageId":"li-ji_ch-10_p-3","order":5,"canonicalText":"故必舉其定國之數，以為禮之大經，禮之大倫。","chunks":[["故必舉其定國之數，以為禮之大經，禮之大倫。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-6","passageId":"li-ji_ch-10_p-3","order":6,"canonicalText":"以地廣狹，禮之薄厚，與年之上下。","chunks":[["以地廣狹，禮之薄厚，與年之上下。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-7","passageId":"li-ji_ch-10_p-3","order":7,"canonicalText":"是故年雖大殺，眾不匡懼。","chunks":[["是故年雖大殺，眾不匡懼。","zh-Hant"]]},{"id":"li-ji_ch-10_p-3_s-8","passageId":"li-ji_ch-10_p-3","order":8,"canonicalText":"則上之制禮也節矣。","chunks":[["則上之制禮也節矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-1","passageId":"li-ji_ch-10_p-4","order":1,"canonicalText":"禮，時為大，順次之，體次之，宜次之，稱次之。","chunks":[["禮，時為大，順次之，體次之，宜次之，稱次之。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-2","passageId":"li-ji_ch-10_p-4","order":2,"canonicalText":"堯授舜，舜授禹；","chunks":[["堯授舜，舜授禹；","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-3","passageId":"li-ji_ch-10_p-4","order":3,"canonicalText":"湯放桀，武王伐紂，時也。","chunks":[["湯放桀，武王伐紂，時也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-4","passageId":"li-ji_ch-10_p-4","order":4,"canonicalText":"《詩》云：「匪革其猶，聿追來孝。","chunks":[["《詩》云：「匪革其猶，聿追來孝。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-5","passageId":"li-ji_ch-10_p-4","order":5,"canonicalText":"」天地之祭，宗廟之事，父子之道，君臣之義，倫也。","chunks":[["」天地之祭，宗廟之事，父子之道，君臣之義，倫也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-6","passageId":"li-ji_ch-10_p-4","order":6,"canonicalText":"社稷山川之事，鬼神之祭，體也。","chunks":[["社稷山川之事，鬼神之祭，體也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-7","passageId":"li-ji_ch-10_p-4","order":7,"canonicalText":"喪祭之用，賓客之交，義也。","chunks":[["喪祭之用，賓客之交，義也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-8","passageId":"li-ji_ch-10_p-4","order":8,"canonicalText":"羔豚而祭，百官皆足；","chunks":[["羔豚而祭，百官皆足；","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-9","passageId":"li-ji_ch-10_p-4","order":9,"canonicalText":"大牢而祭，不必有餘，此之謂稱也。","chunks":[["大牢而祭，不必有餘，此之謂稱也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-10","passageId":"li-ji_ch-10_p-4","order":10,"canonicalText":"諸侯以龜為寶，以圭為瑞。","chunks":[["諸侯以龜為寶，以圭為瑞。","zh-Hant"]]},{"id":"li-ji_ch-10_p-4_s-11","passageId":"li-ji_ch-10_p-4","order":11,"canonicalText":"家不寶龜，不藏圭，不臺門，言有稱也。","chunks":[["家不寶龜，不藏圭，不臺門，言有稱也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-1","passageId":"li-ji_ch-10_p-5","order":1,"canonicalText":"禮，有以多為貴者：天子七廟，諸侯五，大夫三，士一。","chunks":[["禮，有以多為貴者：天子七廟，諸侯五，大夫三，士一。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-2","passageId":"li-ji_ch-10_p-5","order":2,"canonicalText":"天子之豆二十有六，諸公十有六，諸侯十有二，上大夫八，下大夫六。","chunks":[["天子之豆二十有六，諸公十有六，諸侯十有二，上大夫八，下大夫六。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-3","passageId":"li-ji_ch-10_p-5","order":3,"canonicalText":"諸侯七介七牢，大夫五介五牢。","chunks":[["諸侯七介七牢，大夫五介五牢。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-4","passageId":"li-ji_ch-10_p-5","order":4,"canonicalText":"天子之席五重，諸侯之席三重，大夫再重。","chunks":[["天子之席五重，諸侯之席三重，大夫再重。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-5","passageId":"li-ji_ch-10_p-5","order":5,"canonicalText":"天子崩，七月而葬，五重八翣；","chunks":[["天子崩，七月而葬，五重八翣；","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-6","passageId":"li-ji_ch-10_p-5","order":6,"canonicalText":"諸侯五月而葬，三重六翣；","chunks":[["諸侯五月而葬，三重六翣；","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-7","passageId":"li-ji_ch-10_p-5","order":7,"canonicalText":"大夫三月而葬，再重四翣。","chunks":[["大夫三月而葬，再重四翣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-5_s-8","passageId":"li-ji_ch-10_p-5","order":8,"canonicalText":"此以多為貴也。","chunks":[["此以多為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-1","passageId":"li-ji_ch-10_p-6","order":1,"canonicalText":"有以少為貴者：天子無介；","chunks":[["有以少為貴者：天子無介；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-2","passageId":"li-ji_ch-10_p-6","order":2,"canonicalText":"祭天特牲；","chunks":[["祭天特牲；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-3","passageId":"li-ji_ch-10_p-6","order":3,"canonicalText":"天子適諸侯，諸侯膳以犢；","chunks":[["天子適諸侯，諸侯膳以犢；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-4","passageId":"li-ji_ch-10_p-6","order":4,"canonicalText":"諸侯相朝，灌用郁鬯，無籩豆之薦；","chunks":[["諸侯相朝，灌用郁鬯，無籩豆之薦；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-5","passageId":"li-ji_ch-10_p-6","order":5,"canonicalText":"大夫聘禮以脯醢；","chunks":[["大夫聘禮以脯醢；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-6","passageId":"li-ji_ch-10_p-6","order":6,"canonicalText":"天子一食，諸侯再，大夫、士三，食力無數；","chunks":[["天子一食，諸侯再，大夫、士三，食力無數；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-7","passageId":"li-ji_ch-10_p-6","order":7,"canonicalText":"大路繁纓一就，次路繁纓七就；","chunks":[["大路繁纓一就，次路繁纓七就；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-8","passageId":"li-ji_ch-10_p-6","order":8,"canonicalText":"圭璋特，琥璜爵；","chunks":[["圭璋特，琥璜爵；","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-9","passageId":"li-ji_ch-10_p-6","order":9,"canonicalText":"鬼神之祭單席。","chunks":[["鬼神之祭單席。","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-10","passageId":"li-ji_ch-10_p-6","order":10,"canonicalText":"諸侯視朝，大夫特，士旅之。","chunks":[["諸侯視朝，大夫特，士旅之。","zh-Hant"]]},{"id":"li-ji_ch-10_p-6_s-11","passageId":"li-ji_ch-10_p-6","order":11,"canonicalText":"此以少為貴也。","chunks":[["此以少為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-7_s-1","passageId":"li-ji_ch-10_p-7","order":1,"canonicalText":"有以大為貴者：宮室之量，器皿之度，棺槨之厚，丘封之大。","chunks":[["有以大為貴者：宮室之量，器皿之度，棺槨之厚，丘封之大。","zh-Hant"]]},{"id":"li-ji_ch-10_p-7_s-2","passageId":"li-ji_ch-10_p-7","order":2,"canonicalText":"此以大為貴也。","chunks":[["此以大為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-8_s-1","passageId":"li-ji_ch-10_p-8","order":1,"canonicalText":"有以小為貴者：宗廟之祭，貴者獻以爵，賤者獻以散，尊者舉觶，卑者舉角；","chunks":[["有以小為貴者：宗廟之祭，貴者獻以爵，賤者獻以散，尊者舉觶，卑者舉角；","zh-Hant"]]},{"id":"li-ji_ch-10_p-8_s-2","passageId":"li-ji_ch-10_p-8","order":2,"canonicalText":"五獻之尊，門外缶，門內壺，君尊瓦甒。","chunks":[["五獻之尊，門外缶，門內壺，君尊瓦甒。","zh-Hant"]]},{"id":"li-ji_ch-10_p-8_s-3","passageId":"li-ji_ch-10_p-8","order":3,"canonicalText":"此以小為貴也。","chunks":[["此以小為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-9_s-1","passageId":"li-ji_ch-10_p-9","order":1,"canonicalText":"有以高為貴者：天子之堂九尺，諸侯七尺，大夫五尺，士三尺；","chunks":[["有以高為貴者：天子之堂九尺，諸侯七尺，大夫五尺，士三尺；","zh-Hant"]]},{"id":"li-ji_ch-10_p-9_s-2","passageId":"li-ji_ch-10_p-9","order":2,"canonicalText":"天子、諸侯臺門。","chunks":[["天子、諸侯臺門。","zh-Hant"]]},{"id":"li-ji_ch-10_p-9_s-3","passageId":"li-ji_ch-10_p-9","order":3,"canonicalText":"此以高為貴也。","chunks":[["此以高為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-10_s-1","passageId":"li-ji_ch-10_p-10","order":1,"canonicalText":"有以下為貴者：至敬不壇，掃地而祭。","chunks":[["有以下為貴者：至敬不壇，掃地而祭。","zh-Hant"]]},{"id":"li-ji_ch-10_p-10_s-2","passageId":"li-ji_ch-10_p-10","order":2,"canonicalText":"天子諸侯之尊廢禁，大夫、士棜禁。","chunks":[["天子諸侯之尊廢禁，大夫、士棜禁。","zh-Hant"]]},{"id":"li-ji_ch-10_p-10_s-3","passageId":"li-ji_ch-10_p-10","order":3,"canonicalText":"此以下為貴也。","chunks":[["此以下為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-11_s-1","passageId":"li-ji_ch-10_p-11","order":1,"canonicalText":"禮有以文為貴者：天子龍袞，諸侯黼，大夫黻，士玄衣纁裳；","chunks":[["禮有以文為貴者：天子龍袞，諸侯黼，大夫黻，士玄衣纁裳；","zh-Hant"]]},{"id":"li-ji_ch-10_p-11_s-2","passageId":"li-ji_ch-10_p-11","order":2,"canonicalText":"天子之冕，朱綠藻十有二旒，諸侯九，上大夫七，下大夫五，士三。","chunks":[["天子之冕，朱綠藻十有二旒，諸侯九，上大夫七，下大夫五，士三。","zh-Hant"]]},{"id":"li-ji_ch-10_p-11_s-3","passageId":"li-ji_ch-10_p-11","order":3,"canonicalText":"此以文為貴也。","chunks":[["此以文為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-12_s-1","passageId":"li-ji_ch-10_p-12","order":1,"canonicalText":"有以素為貴者：至敬無文，父黨無容，大圭不琢，大羹不和，大路素而越席，犧尊疏布冪，樿杓。","chunks":[["有以素為貴者：至敬無文，父黨無容，大圭不琢，大羹不和，大路素而越席，犧尊疏布冪，樿杓。","zh-Hant"]]},{"id":"li-ji_ch-10_p-12_s-2","passageId":"li-ji_ch-10_p-12","order":2,"canonicalText":"此以素為貴也。","chunks":[["此以素為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-13_s-1","passageId":"li-ji_ch-10_p-13","order":1,"canonicalText":"孔子曰：「禮，不可不省也。","chunks":[["孔子曰：「禮，不可不省也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-13_s-2","passageId":"li-ji_ch-10_p-13","order":2,"canonicalText":"」禮不同，不豐、不殺，此之謂也。","chunks":[["」禮不同，不豐、不殺，此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-13_s-3","passageId":"li-ji_ch-10_p-13","order":3,"canonicalText":"蓋言稱也。","chunks":[["蓋言稱也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-14_s-1","passageId":"li-ji_ch-10_p-14","order":1,"canonicalText":"禮之以多為貴者，以其外心者也；","chunks":[["禮之以多為貴者，以其外心者也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-14_s-2","passageId":"li-ji_ch-10_p-14","order":2,"canonicalText":"德發揚，詡萬物，大理物博，如此，則得不以多為貴乎？","chunks":[["德發揚，詡萬物，大理物博，如此，則得不以多為貴乎？","zh-Hant"]]},{"id":"li-ji_ch-10_p-14_s-3","passageId":"li-ji_ch-10_p-14","order":3,"canonicalText":"故君子樂其發也。","chunks":[["故君子樂其發也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-15_s-1","passageId":"li-ji_ch-10_p-15","order":1,"canonicalText":"禮之以少為貴者，以其內心者也。","chunks":[["禮之以少為貴者，以其內心者也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-15_s-2","passageId":"li-ji_ch-10_p-15","order":2,"canonicalText":"德產之致也精微，觀天子之物無可以稱其德者，如此則得不以少為貴乎？","chunks":[["德產之致也精微，觀天子之物無可以稱其德者，如此則得不以少為貴乎？","zh-Hant"]]},{"id":"li-ji_ch-10_p-15_s-3","passageId":"li-ji_ch-10_p-15","order":3,"canonicalText":"是故君子慎其獨也。","chunks":[["是故君子慎其獨也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-1","passageId":"li-ji_ch-10_p-16","order":1,"canonicalText":"古之聖人，內之為尊，外之為樂，少之為貴，多之為美。","chunks":[["古之聖人，內之為尊，外之為樂，少之為貴，多之為美。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-2","passageId":"li-ji_ch-10_p-16","order":2,"canonicalText":"是故先生之制禮也，不可多也，不可寡也，唯其稱也。","chunks":[["是故先生之制禮也，不可多也，不可寡也，唯其稱也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-3","passageId":"li-ji_ch-10_p-16","order":3,"canonicalText":"是故，君子大牢而祭，謂之禮；","chunks":[["是故，君子大牢而祭，謂之禮；","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-4","passageId":"li-ji_ch-10_p-16","order":4,"canonicalText":"匹士大牢而祭，謂之攘。","chunks":[["匹士大牢而祭，謂之攘。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-5","passageId":"li-ji_ch-10_p-16","order":5,"canonicalText":"管仲鏤簋朱紘，山節藻梲，君子以為濫矣。","chunks":[["管仲鏤簋朱紘，山節藻梲，君子以為濫矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-6","passageId":"li-ji_ch-10_p-16","order":6,"canonicalText":"晏平仲祀其先人，豚肩不揜豆；","chunks":[["晏平仲祀其先人，豚肩不揜豆；","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-7","passageId":"li-ji_ch-10_p-16","order":7,"canonicalText":"浣衣濯冠以朝，君子以為隘矣。","chunks":[["浣衣濯冠以朝，君子以為隘矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-8","passageId":"li-ji_ch-10_p-16","order":8,"canonicalText":"是故君子之行禮也，不可不慎也；","chunks":[["是故君子之行禮也，不可不慎也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-9","passageId":"li-ji_ch-10_p-16","order":9,"canonicalText":"眾之紀也，紀散而眾亂。","chunks":[["眾之紀也，紀散而眾亂。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-10","passageId":"li-ji_ch-10_p-16","order":10,"canonicalText":"孔子曰：「我戰則克，祭則受福。","chunks":[["孔子曰：「我戰則克，祭則受福。","zh-Hant"]]},{"id":"li-ji_ch-10_p-16_s-11","passageId":"li-ji_ch-10_p-16","order":11,"canonicalText":"」蓋得其道矣。","chunks":[["」蓋得其道矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-17_s-1","passageId":"li-ji_ch-10_p-17","order":1,"canonicalText":"君子曰：祭祀不祈，不麾蚤，不樂葆大，不善嘉事，牲不及肥大，薦不美多品。","chunks":[["君子曰：祭祀不祈，不麾蚤，不樂葆大，不善嘉事，牲不及肥大，薦不美多品。","zh-Hant"]]},{"id":"li-ji_ch-10_p-17_s-2","passageId":"li-ji_ch-10_p-17","order":2,"canonicalText":"孔子曰：「臧文仲安知禮！","chunks":[["孔子曰：「臧文仲安知禮！","zh-Hant"]]},{"id":"li-ji_ch-10_p-17_s-3","passageId":"li-ji_ch-10_p-17","order":3,"canonicalText":"夏父弗綦逆祀，而弗止也。","chunks":[["夏父弗綦逆祀，而弗止也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-17_s-4","passageId":"li-ji_ch-10_p-17","order":4,"canonicalText":"燔柴於奧，夫奧者，老婦之祭也，盛於盆，尊於瓶。","chunks":[["燔柴於奧，夫奧者，老婦之祭也，盛於盆，尊於瓶。","zh-Hant"]]},{"id":"li-ji_ch-10_p-17_s-5","passageId":"li-ji_ch-10_p-17","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-1","passageId":"li-ji_ch-10_p-18","order":1,"canonicalText":"禮也者，猶體也。","chunks":[["禮也者，猶體也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-2","passageId":"li-ji_ch-10_p-18","order":2,"canonicalText":"體不備，君子謂之不成人。","chunks":[["體不備，君子謂之不成人。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-3","passageId":"li-ji_ch-10_p-18","order":3,"canonicalText":"設之不當，猶不備也。","chunks":[["設之不當，猶不備也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-4","passageId":"li-ji_ch-10_p-18","order":4,"canonicalText":"禮有大有小，有顯有微。","chunks":[["禮有大有小，有顯有微。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-5","passageId":"li-ji_ch-10_p-18","order":5,"canonicalText":"大者不可損，小者不可益，顯者不可掩，微者不可大也。","chunks":[["大者不可損，小者不可益，顯者不可掩，微者不可大也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-6","passageId":"li-ji_ch-10_p-18","order":6,"canonicalText":"故《經禮》三百，《曲禮》三千，其致一也。","chunks":[["故《經禮》三百，《曲禮》三千，其致一也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-18_s-7","passageId":"li-ji_ch-10_p-18","order":7,"canonicalText":"未有入室而不由戶者。","chunks":[["未有入室而不由戶者。","zh-Hant"]]},{"id":"li-ji_ch-10_p-19_s-1","passageId":"li-ji_ch-10_p-19","order":1,"canonicalText":"君子之於禮也，有所竭情盡慎，致其敬而誠若，有美而文而誠若。","chunks":[["君子之於禮也，有所竭情盡慎，致其敬而誠若，有美而文而誠若。","zh-Hant"]]},{"id":"li-ji_ch-10_p-19_s-2","passageId":"li-ji_ch-10_p-19","order":2,"canonicalText":"君子之於禮也，有直而行也，有曲而殺也，有經而等也，有順而討也，有摭而播也，有推而進也，有放而文也，有放而不致也，有順而摭也。","chunks":[["君子之於禮也，有直而行也，有曲而殺也，有經而等也，有順而討也，有摭而播也，有推而進也，有放而文也，有放而不致也，有順而摭也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-20_s-1","passageId":"li-ji_ch-10_p-20","order":1,"canonicalText":"三代之禮一也，民共由之。","chunks":[["三代之禮一也，民共由之。","zh-Hant"]]},{"id":"li-ji_ch-10_p-20_s-2","passageId":"li-ji_ch-10_p-20","order":2,"canonicalText":"或素或青，夏造殷因。","chunks":[["或素或青，夏造殷因。","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-1","passageId":"li-ji_ch-10_p-21","order":1,"canonicalText":"周坐尸，詔侑武方；","chunks":[["周坐尸，詔侑武方；","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-2","passageId":"li-ji_ch-10_p-21","order":2,"canonicalText":"其禮亦然，其道一也；","chunks":[["其禮亦然，其道一也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-3","passageId":"li-ji_ch-10_p-21","order":3,"canonicalText":"夏立尸而卒祭；","chunks":[["夏立尸而卒祭；","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-4","passageId":"li-ji_ch-10_p-21","order":4,"canonicalText":"殷坐尸。","chunks":[["殷坐尸。","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-5","passageId":"li-ji_ch-10_p-21","order":5,"canonicalText":"周旅酬六尸，曾子曰：「周禮其猶醵與！","chunks":[["周旅酬六尸，曾子曰：「周禮其猶醵與！","zh-Hant"]]},{"id":"li-ji_ch-10_p-21_s-6","passageId":"li-ji_ch-10_p-21","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-10_p-22_s-1","passageId":"li-ji_ch-10_p-22","order":1,"canonicalText":"君子曰：禮之近人情者，非其至者也。","chunks":[["君子曰：禮之近人情者，非其至者也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-22_s-2","passageId":"li-ji_ch-10_p-22","order":2,"canonicalText":"郊血，大饗腥，三獻爓，一獻孰。","chunks":[["郊血，大饗腥，三獻爓，一獻孰。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-1","passageId":"li-ji_ch-10_p-23","order":1,"canonicalText":"是故君子之於禮也，非作而致其情也，此有由始也。","chunks":[["是故君子之於禮也，非作而致其情也，此有由始也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-2","passageId":"li-ji_ch-10_p-23","order":2,"canonicalText":"是故七介以相見也，不然則已愨。","chunks":[["是故七介以相見也，不然則已愨。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-3","passageId":"li-ji_ch-10_p-23","order":3,"canonicalText":"三辭三讓而至，不然則已蹙。","chunks":[["三辭三讓而至，不然則已蹙。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-4","passageId":"li-ji_ch-10_p-23","order":4,"canonicalText":"故魯人將有事於上帝，必先有事於頖宮；","chunks":[["故魯人將有事於上帝，必先有事於頖宮；","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-5","passageId":"li-ji_ch-10_p-23","order":5,"canonicalText":"晉人將有事於河，必先有事於惡池；","chunks":[["晉人將有事於河，必先有事於惡池；","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-6","passageId":"li-ji_ch-10_p-23","order":6,"canonicalText":"齊人將有事於泰山，必先有事於配林。","chunks":[["齊人將有事於泰山，必先有事於配林。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-7","passageId":"li-ji_ch-10_p-23","order":7,"canonicalText":"三月系，七日戒，三日宿，慎之至也。","chunks":[["三月系，七日戒，三日宿，慎之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-23_s-8","passageId":"li-ji_ch-10_p-23","order":8,"canonicalText":"故禮有擯詔，樂有相步，溫之至也。","chunks":[["故禮有擯詔，樂有相步，溫之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-1","passageId":"li-ji_ch-10_p-24","order":1,"canonicalText":"禮也者，反本修古，不忘其初者也。","chunks":[["禮也者，反本修古，不忘其初者也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-2","passageId":"li-ji_ch-10_p-24","order":2,"canonicalText":"故凶事不詔，朝事以樂。","chunks":[["故凶事不詔，朝事以樂。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-3","passageId":"li-ji_ch-10_p-24","order":3,"canonicalText":"醴酒之用，玄酒之尚。","chunks":[["醴酒之用，玄酒之尚。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-4","passageId":"li-ji_ch-10_p-24","order":4,"canonicalText":"割刀之用，鸞刀之貴。","chunks":[["割刀之用，鸞刀之貴。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-5","passageId":"li-ji_ch-10_p-24","order":5,"canonicalText":"莞簟之安，而稿鞂之設。","chunks":[["莞簟之安，而稿鞂之設。","zh-Hant"]]},{"id":"li-ji_ch-10_p-24_s-6","passageId":"li-ji_ch-10_p-24","order":6,"canonicalText":"是故，先王之制禮也，必有主也，故可述而多學也。","chunks":[["是故，先王之制禮也，必有主也，故可述而多學也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-1","passageId":"li-ji_ch-10_p-25","order":1,"canonicalText":"君子曰：無節於內者，觀物弗之察矣。","chunks":[["君子曰：無節於內者，觀物弗之察矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-2","passageId":"li-ji_ch-10_p-25","order":2,"canonicalText":"欲察物而不由禮，弗之得矣。","chunks":[["欲察物而不由禮，弗之得矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-3","passageId":"li-ji_ch-10_p-25","order":3,"canonicalText":"故作事不以禮，弗之敬矣。","chunks":[["故作事不以禮，弗之敬矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-4","passageId":"li-ji_ch-10_p-25","order":4,"canonicalText":"出言不以禮，弗之信矣。","chunks":[["出言不以禮，弗之信矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-5","passageId":"li-ji_ch-10_p-25","order":5,"canonicalText":"故曰：「禮也者，物之致也。","chunks":[["故曰：「禮也者，物之致也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-25_s-6","passageId":"li-ji_ch-10_p-25","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-10_p-26_s-1","passageId":"li-ji_ch-10_p-26","order":1,"canonicalText":"是故昔先王之制禮也，因其財物而致其義焉爾。","chunks":[["是故昔先王之制禮也，因其財物而致其義焉爾。","zh-Hant"]]},{"id":"li-ji_ch-10_p-26_s-2","passageId":"li-ji_ch-10_p-26","order":2,"canonicalText":"故作大事，必順天時，為朝夕必放於日月，為高必因丘陵，為下必因川澤。","chunks":[["故作大事，必順天時，為朝夕必放於日月，為高必因丘陵，為下必因川澤。","zh-Hant"]]},{"id":"li-ji_ch-10_p-26_s-3","passageId":"li-ji_ch-10_p-26","order":3,"canonicalText":"是故天時雨澤，君子達亹亹焉。","chunks":[["是故天時雨澤，君子達亹亹焉。","zh-Hant"]]},{"id":"li-ji_ch-10_p-26_s-4","passageId":"li-ji_ch-10_p-26","order":4,"canonicalText":"是故昔先王尚有德、尊有道、任有能；","chunks":[["是故昔先王尚有德、尊有道、任有能；","zh-Hant"]]},{"id":"li-ji_ch-10_p-26_s-5","passageId":"li-ji_ch-10_p-26","order":5,"canonicalText":"舉賢而置之，聚眾而誓之。","chunks":[["舉賢而置之，聚眾而誓之。","zh-Hant"]]},{"id":"li-ji_ch-10_p-27_s-1","passageId":"li-ji_ch-10_p-27","order":1,"canonicalText":"是故因天事天，因地事地，因名山升中于天，因吉土以饗帝于郊。","chunks":[["是故因天事天，因地事地，因名山升中于天，因吉土以饗帝于郊。","zh-Hant"]]},{"id":"li-ji_ch-10_p-27_s-2","passageId":"li-ji_ch-10_p-27","order":2,"canonicalText":"升中于天，而鳳凰降、龜龍假；","chunks":[["升中于天，而鳳凰降、龜龍假；","zh-Hant"]]},{"id":"li-ji_ch-10_p-27_s-3","passageId":"li-ji_ch-10_p-27","order":3,"canonicalText":"饗帝於郊，而風雨節、寒暑時。","chunks":[["饗帝於郊，而風雨節、寒暑時。","zh-Hant"]]},{"id":"li-ji_ch-10_p-27_s-4","passageId":"li-ji_ch-10_p-27","order":4,"canonicalText":"是故聖人南面而立，而天下大治。","chunks":[["是故聖人南面而立，而天下大治。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-1","passageId":"li-ji_ch-10_p-28","order":1,"canonicalText":"天道至教，聖人至德。","chunks":[["天道至教，聖人至德。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-2","passageId":"li-ji_ch-10_p-28","order":2,"canonicalText":"廟堂之上，罍尊在阼，犧尊在西。","chunks":[["廟堂之上，罍尊在阼，犧尊在西。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-3","passageId":"li-ji_ch-10_p-28","order":3,"canonicalText":"廟堂之下，縣鼓在西，應鼓在東。","chunks":[["廟堂之下，縣鼓在西，應鼓在東。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-4","passageId":"li-ji_ch-10_p-28","order":4,"canonicalText":"君在阼，夫人在房。","chunks":[["君在阼，夫人在房。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-5","passageId":"li-ji_ch-10_p-28","order":5,"canonicalText":"大明生於東，月生於西，此陰陽之分、夫婦之位也。","chunks":[["大明生於東，月生於西，此陰陽之分、夫婦之位也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-6","passageId":"li-ji_ch-10_p-28","order":6,"canonicalText":"君西酌犧象，夫人東酌罍尊。","chunks":[["君西酌犧象，夫人東酌罍尊。","zh-Hant"]]},{"id":"li-ji_ch-10_p-28_s-7","passageId":"li-ji_ch-10_p-28","order":7,"canonicalText":"禮交動乎上，樂交應乎下，和之至也。","chunks":[["禮交動乎上，樂交應乎下，和之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-1","passageId":"li-ji_ch-10_p-29","order":1,"canonicalText":"禮也者，反其所自生；","chunks":[["禮也者，反其所自生；","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-2","passageId":"li-ji_ch-10_p-29","order":2,"canonicalText":"樂也者，樂其所自成。","chunks":[["樂也者，樂其所自成。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-3","passageId":"li-ji_ch-10_p-29","order":3,"canonicalText":"是故先王之制禮也以節事，修樂以道志。","chunks":[["是故先王之制禮也以節事，修樂以道志。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-4","passageId":"li-ji_ch-10_p-29","order":4,"canonicalText":"故觀其禮樂，而治亂可知也。","chunks":[["故觀其禮樂，而治亂可知也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-5","passageId":"li-ji_ch-10_p-29","order":5,"canonicalText":"蘧伯玉曰：「君子之人達，故觀其器，而知其工之巧；","chunks":[["蘧伯玉曰：「君子之人達，故觀其器，而知其工之巧；","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-6","passageId":"li-ji_ch-10_p-29","order":6,"canonicalText":"觀其發，而知其人之知。","chunks":[["觀其發，而知其人之知。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-7","passageId":"li-ji_ch-10_p-29","order":7,"canonicalText":"」故曰：「君子慎其所以與人者。","chunks":[["」故曰：「君子慎其所以與人者。","zh-Hant"]]},{"id":"li-ji_ch-10_p-29_s-8","passageId":"li-ji_ch-10_p-29","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-1","passageId":"li-ji_ch-10_p-30","order":1,"canonicalText":"太廟之內敬矣！","chunks":[["太廟之內敬矣！","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-2","passageId":"li-ji_ch-10_p-30","order":2,"canonicalText":"君親牽牲，大夫贊幣而從。","chunks":[["君親牽牲，大夫贊幣而從。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-3","passageId":"li-ji_ch-10_p-30","order":3,"canonicalText":"君親制祭，夫人薦盎。","chunks":[["君親制祭，夫人薦盎。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-4","passageId":"li-ji_ch-10_p-30","order":4,"canonicalText":"君親割牲，夫人薦酒。","chunks":[["君親割牲，夫人薦酒。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-5","passageId":"li-ji_ch-10_p-30","order":5,"canonicalText":"卿、大夫從君，命婦從夫人。","chunks":[["卿、大夫從君，命婦從夫人。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-6","passageId":"li-ji_ch-10_p-30","order":6,"canonicalText":"洞洞乎其敬也，屬屬乎其忠也，勿勿乎其欲其饗之也。","chunks":[["洞洞乎其敬也，屬屬乎其忠也，勿勿乎其欲其饗之也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-7","passageId":"li-ji_ch-10_p-30","order":7,"canonicalText":"納牲詔於庭，血毛詔於室，羹定詔於堂，三詔皆不同位，蓋道求而未之得也。","chunks":[["納牲詔於庭，血毛詔於室，羹定詔於堂，三詔皆不同位，蓋道求而未之得也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-8","passageId":"li-ji_ch-10_p-30","order":8,"canonicalText":"設祭于堂，為祊乎外，故曰：「於彼乎？","chunks":[["設祭于堂，為祊乎外，故曰：「於彼乎？","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-9","passageId":"li-ji_ch-10_p-30","order":9,"canonicalText":"於此乎？","chunks":[["於此乎？","zh-Hant"]]},{"id":"li-ji_ch-10_p-30_s-10","passageId":"li-ji_ch-10_p-30","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-10_p-31_s-1","passageId":"li-ji_ch-10_p-31","order":1,"canonicalText":"一獻質，三獻文，五獻察，七獻神。","chunks":[["一獻質，三獻文，五獻察，七獻神。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-1","passageId":"li-ji_ch-10_p-32","order":1,"canonicalText":"大饗其王事與！","chunks":[["大饗其王事與！","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-2","passageId":"li-ji_ch-10_p-32","order":2,"canonicalText":"三牲魚臘，四海九州之美味也；","chunks":[["三牲魚臘，四海九州之美味也；","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-3","passageId":"li-ji_ch-10_p-32","order":3,"canonicalText":"籩豆之薦，四時之和氣也。","chunks":[["籩豆之薦，四時之和氣也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-4","passageId":"li-ji_ch-10_p-32","order":4,"canonicalText":"內金，示和也。","chunks":[["內金，示和也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-5","passageId":"li-ji_ch-10_p-32","order":5,"canonicalText":"束帛加璧，尊德也。","chunks":[["束帛加璧，尊德也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-6","passageId":"li-ji_ch-10_p-32","order":6,"canonicalText":"龜為前列，先知也。","chunks":[["龜為前列，先知也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-7","passageId":"li-ji_ch-10_p-32","order":7,"canonicalText":"金次之，見情也。","chunks":[["金次之，見情也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-8","passageId":"li-ji_ch-10_p-32","order":8,"canonicalText":"丹漆絲纊竹箭，與眾共財也。","chunks":[["丹漆絲纊竹箭，與眾共財也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-9","passageId":"li-ji_ch-10_p-32","order":9,"canonicalText":"其餘無常貨，各以其國之所有，則致遠物也。","chunks":[["其餘無常貨，各以其國之所有，則致遠物也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-32_s-10","passageId":"li-ji_ch-10_p-32","order":10,"canonicalText":"其出也，肆夏而送之，蓋重禮也。","chunks":[["其出也，肆夏而送之，蓋重禮也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-1","passageId":"li-ji_ch-10_p-33","order":1,"canonicalText":"祀帝於郊，敬之至也。","chunks":[["祀帝於郊，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-2","passageId":"li-ji_ch-10_p-33","order":2,"canonicalText":"宗廟之祭，仁之至也。","chunks":[["宗廟之祭，仁之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-3","passageId":"li-ji_ch-10_p-33","order":3,"canonicalText":"喪禮，忠之至也。","chunks":[["喪禮，忠之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-4","passageId":"li-ji_ch-10_p-33","order":4,"canonicalText":"備服器，仁之至也。","chunks":[["備服器，仁之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-5","passageId":"li-ji_ch-10_p-33","order":5,"canonicalText":"賓客之用幣，義之至也。","chunks":[["賓客之用幣，義之至也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-33_s-6","passageId":"li-ji_ch-10_p-33","order":6,"canonicalText":"故君子欲觀仁義之道，禮其本也。","chunks":[["故君子欲觀仁義之道，禮其本也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-34_s-1","passageId":"li-ji_ch-10_p-34","order":1,"canonicalText":"君子曰：甘受和，白受采；","chunks":[["君子曰：甘受和，白受采；","zh-Hant"]]},{"id":"li-ji_ch-10_p-34_s-2","passageId":"li-ji_ch-10_p-34","order":2,"canonicalText":"忠信之人，可以學禮。","chunks":[["忠信之人，可以學禮。","zh-Hant"]]},{"id":"li-ji_ch-10_p-34_s-3","passageId":"li-ji_ch-10_p-34","order":3,"canonicalText":"茍無忠信之人，則禮不虛道。","chunks":[["茍無忠信之人，則禮不虛道。","zh-Hant"]]},{"id":"li-ji_ch-10_p-34_s-4","passageId":"li-ji_ch-10_p-34","order":4,"canonicalText":"是以得其人之為貴也。","chunks":[["是以得其人之為貴也。","zh-Hant"]]},{"id":"li-ji_ch-10_p-35_s-1","passageId":"li-ji_ch-10_p-35","order":1,"canonicalText":"孔子曰：「誦《詩》三百，不足以一獻。","chunks":[["孔子曰：「誦《詩》三百，不足以一獻。","zh-Hant"]]},{"id":"li-ji_ch-10_p-35_s-2","passageId":"li-ji_ch-10_p-35","order":2,"canonicalText":"一獻之禮，不足以大饗。","chunks":[["一獻之禮，不足以大饗。","zh-Hant"]]},{"id":"li-ji_ch-10_p-35_s-3","passageId":"li-ji_ch-10_p-35","order":3,"canonicalText":"大饗之禮，不足以大旅。","chunks":[["大饗之禮，不足以大旅。","zh-Hant"]]},{"id":"li-ji_ch-10_p-35_s-4","passageId":"li-ji_ch-10_p-35","order":4,"canonicalText":"大旅具矣，不足以饗帝。","chunks":[["大旅具矣，不足以饗帝。","zh-Hant"]]},{"id":"li-ji_ch-10_p-35_s-5","passageId":"li-ji_ch-10_p-35","order":5,"canonicalText":"」毋輕議禮！","chunks":[["」毋輕議禮！","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-1","passageId":"li-ji_ch-10_p-36","order":1,"canonicalText":"子路為季氏宰。","chunks":[["子路為季氏宰。","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-2","passageId":"li-ji_ch-10_p-36","order":2,"canonicalText":"季氏祭，逮暗而祭，日不足，繼之以燭。","chunks":[["季氏祭，逮暗而祭，日不足，繼之以燭。","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-3","passageId":"li-ji_ch-10_p-36","order":3,"canonicalText":"雖有強力之容、肅敬之心，皆倦怠矣。","chunks":[["雖有強力之容、肅敬之心，皆倦怠矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-4","passageId":"li-ji_ch-10_p-36","order":4,"canonicalText":"有司跛倚以臨祭，其為不敬大矣。","chunks":[["有司跛倚以臨祭，其為不敬大矣。","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-5","passageId":"li-ji_ch-10_p-36","order":5,"canonicalText":"他日祭，子路與，室事交乎戶，堂事交乎階，質明而始行事，晏朝而退。","chunks":[["他日祭，子路與，室事交乎戶，堂事交乎階，質明而始行事，晏朝而退。","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-6","passageId":"li-ji_ch-10_p-36","order":6,"canonicalText":"孔子聞之曰：「誰謂由也而不知禮乎？","chunks":[["孔子聞之曰：「誰謂由也而不知禮乎？","zh-Hant"]]},{"id":"li-ji_ch-10_p-36_s-7","passageId":"li-ji_ch-10_p-36","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-1_s-1","passageId":"li-ji_ch-11_p-1","order":1,"canonicalText":"郊特牲，而社稷大牢。","chunks":[["郊特牲，而社稷大牢。","zh-Hant"]]},{"id":"li-ji_ch-11_p-1_s-2","passageId":"li-ji_ch-11_p-1","order":2,"canonicalText":"天子適諸侯，諸侯膳用犢；","chunks":[["天子適諸侯，諸侯膳用犢；","zh-Hant"]]},{"id":"li-ji_ch-11_p-1_s-3","passageId":"li-ji_ch-11_p-1","order":3,"canonicalText":"諸侯適天子，天子賜之禮大牢；","chunks":[["諸侯適天子，天子賜之禮大牢；","zh-Hant"]]},{"id":"li-ji_ch-11_p-1_s-4","passageId":"li-ji_ch-11_p-1","order":4,"canonicalText":"貴誠之義也。","chunks":[["貴誠之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-1_s-5","passageId":"li-ji_ch-11_p-1","order":5,"canonicalText":"故天子牲孕弗食也，祭帝弗用也。","chunks":[["故天子牲孕弗食也，祭帝弗用也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-2_s-1","passageId":"li-ji_ch-11_p-2","order":1,"canonicalText":"大路繁纓一就，先路三就，次路五就。","chunks":[["大路繁纓一就，先路三就，次路五就。","zh-Hant"]]},{"id":"li-ji_ch-11_p-2_s-2","passageId":"li-ji_ch-11_p-2","order":2,"canonicalText":"郊血，大饗腥，三獻爓，一獻熟；","chunks":[["郊血，大饗腥，三獻爓，一獻熟；","zh-Hant"]]},{"id":"li-ji_ch-11_p-2_s-3","passageId":"li-ji_ch-11_p-2","order":3,"canonicalText":"至敬不饗味而貴氣臭也。","chunks":[["至敬不饗味而貴氣臭也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-2_s-4","passageId":"li-ji_ch-11_p-2","order":4,"canonicalText":"諸侯為賓，灌用郁鬯。","chunks":[["諸侯為賓，灌用郁鬯。","zh-Hant"]]},{"id":"li-ji_ch-11_p-2_s-5","passageId":"li-ji_ch-11_p-2","order":5,"canonicalText":"灌用臭也，大饗，尚腶修而已矣。","chunks":[["灌用臭也，大饗，尚腶修而已矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-3_s-1","passageId":"li-ji_ch-11_p-3","order":1,"canonicalText":"大饗，君三重席而酢焉。","chunks":[["大饗，君三重席而酢焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-3_s-2","passageId":"li-ji_ch-11_p-3","order":2,"canonicalText":"三獻之介，君專席而酢焉。","chunks":[["三獻之介，君專席而酢焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-3_s-3","passageId":"li-ji_ch-11_p-3","order":3,"canonicalText":"此降尊以就卑也。","chunks":[["此降尊以就卑也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-1","passageId":"li-ji_ch-11_p-4","order":1,"canonicalText":"饗禘有樂，而食嘗無樂，陰陽之義也。","chunks":[["饗禘有樂，而食嘗無樂，陰陽之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-2","passageId":"li-ji_ch-11_p-4","order":2,"canonicalText":"凡飲，養陽氣也；","chunks":[["凡飲，養陽氣也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-3","passageId":"li-ji_ch-11_p-4","order":3,"canonicalText":"凡食，養陰氣也。","chunks":[["凡食，養陰氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-4","passageId":"li-ji_ch-11_p-4","order":4,"canonicalText":"故春禘而秋嘗；","chunks":[["故春禘而秋嘗；","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-5","passageId":"li-ji_ch-11_p-4","order":5,"canonicalText":"春饗孤子，秋食耆老，其義一也。","chunks":[["春饗孤子，秋食耆老，其義一也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-6","passageId":"li-ji_ch-11_p-4","order":6,"canonicalText":"而食嘗無樂。","chunks":[["而食嘗無樂。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-7","passageId":"li-ji_ch-11_p-4","order":7,"canonicalText":"飲，養陽氣也，故有樂；","chunks":[["飲，養陽氣也，故有樂；","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-8","passageId":"li-ji_ch-11_p-4","order":8,"canonicalText":"食，養陰氣也，故無聲。","chunks":[["食，養陰氣也，故無聲。","zh-Hant"]]},{"id":"li-ji_ch-11_p-4_s-9","passageId":"li-ji_ch-11_p-4","order":9,"canonicalText":"凡聲，陽也。","chunks":[["凡聲，陽也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-5_s-1","passageId":"li-ji_ch-11_p-5","order":1,"canonicalText":"鼎俎奇而籩豆偶，陰陽之義也。","chunks":[["鼎俎奇而籩豆偶，陰陽之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-5_s-2","passageId":"li-ji_ch-11_p-5","order":2,"canonicalText":"籩豆之實，水土之品也。","chunks":[["籩豆之實，水土之品也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-5_s-3","passageId":"li-ji_ch-11_p-5","order":3,"canonicalText":"不敢用褻味而貴多品，所以交於旦明之義也。","chunks":[["不敢用褻味而貴多品，所以交於旦明之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-6_s-1","passageId":"li-ji_ch-11_p-6","order":1,"canonicalText":"賓入大門而奏《肆夏》，示易以敬也。","chunks":[["賓入大門而奏《肆夏》，示易以敬也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-6_s-2","passageId":"li-ji_ch-11_p-6","order":2,"canonicalText":"卒爵而樂闋，孔子屢嘆之。","chunks":[["卒爵而樂闋，孔子屢嘆之。","zh-Hant"]]},{"id":"li-ji_ch-11_p-6_s-3","passageId":"li-ji_ch-11_p-6","order":3,"canonicalText":"奠酬而工升歌，發德也。","chunks":[["奠酬而工升歌，發德也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-6_s-4","passageId":"li-ji_ch-11_p-6","order":4,"canonicalText":"歌者在上，匏竹在下，貴人聲也。","chunks":[["歌者在上，匏竹在下，貴人聲也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-6_s-5","passageId":"li-ji_ch-11_p-6","order":5,"canonicalText":"樂由陽來者也，禮由陰作者也，陰陽和而萬物得。","chunks":[["樂由陽來者也，禮由陰作者也，陰陽和而萬物得。","zh-Hant"]]},{"id":"li-ji_ch-11_p-7_s-1","passageId":"li-ji_ch-11_p-7","order":1,"canonicalText":"旅幣無方，所以別土地之宜而節遠邇之期也。","chunks":[["旅幣無方，所以別土地之宜而節遠邇之期也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-7_s-2","passageId":"li-ji_ch-11_p-7","order":2,"canonicalText":"龜為前列，先知也，以鐘次之，以和居參之也。","chunks":[["龜為前列，先知也，以鐘次之，以和居參之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-7_s-3","passageId":"li-ji_ch-11_p-7","order":3,"canonicalText":"虎豹之皮，示服猛也。","chunks":[["虎豹之皮，示服猛也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-7_s-4","passageId":"li-ji_ch-11_p-7","order":4,"canonicalText":"束帛加璧，往德也。","chunks":[["束帛加璧，往德也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-8_s-1","passageId":"li-ji_ch-11_p-8","order":1,"canonicalText":"庭燎之百，由齊桓公始也。","chunks":[["庭燎之百，由齊桓公始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-8_s-2","passageId":"li-ji_ch-11_p-8","order":2,"canonicalText":"大夫之奏《肆夏》也，由趙文子始也。","chunks":[["大夫之奏《肆夏》也，由趙文子始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-9_s-1","passageId":"li-ji_ch-11_p-9","order":1,"canonicalText":"朝覲，大夫之私覿，非禮也。","chunks":[["朝覲，大夫之私覿，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-9_s-2","passageId":"li-ji_ch-11_p-9","order":2,"canonicalText":"大夫執圭而使，所以申信也；","chunks":[["大夫執圭而使，所以申信也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-9_s-3","passageId":"li-ji_ch-11_p-9","order":3,"canonicalText":"不敢私覿，所以致敬也；","chunks":[["不敢私覿，所以致敬也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-9_s-4","passageId":"li-ji_ch-11_p-9","order":4,"canonicalText":"而庭實私覿，何為乎諸侯之庭？","chunks":[["而庭實私覿，何為乎諸侯之庭？","zh-Hant"]]},{"id":"li-ji_ch-11_p-9_s-5","passageId":"li-ji_ch-11_p-9","order":5,"canonicalText":"為人臣者，無外交，不敢貳君也。","chunks":[["為人臣者，無外交，不敢貳君也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-1","passageId":"li-ji_ch-11_p-10","order":1,"canonicalText":"大夫而饗君，非禮也。","chunks":[["大夫而饗君，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-2","passageId":"li-ji_ch-11_p-10","order":2,"canonicalText":"大夫強而君殺之，義也；","chunks":[["大夫強而君殺之，義也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-3","passageId":"li-ji_ch-11_p-10","order":3,"canonicalText":"由三桓始也。","chunks":[["由三桓始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-4","passageId":"li-ji_ch-11_p-10","order":4,"canonicalText":"天子無客禮，莫敢為主焉。","chunks":[["天子無客禮，莫敢為主焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-5","passageId":"li-ji_ch-11_p-10","order":5,"canonicalText":"君適其臣，升自阼階，不敢有其室也。","chunks":[["君適其臣，升自阼階，不敢有其室也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-6","passageId":"li-ji_ch-11_p-10","order":6,"canonicalText":"覲禮，天子不下堂而見諸侯。","chunks":[["覲禮，天子不下堂而見諸侯。","zh-Hant"]]},{"id":"li-ji_ch-11_p-10_s-7","passageId":"li-ji_ch-11_p-10","order":7,"canonicalText":"下堂而見諸侯，天子之失禮也，由夷王以下。","chunks":[["下堂而見諸侯，天子之失禮也，由夷王以下。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-1","passageId":"li-ji_ch-11_p-11","order":1,"canonicalText":"諸侯之宮縣，而祭以白牡，擊玉磬，朱干設錫，冕而舞《大武》，乘大路，諸侯之僭禮也。","chunks":[["諸侯之宮縣，而祭以白牡，擊玉磬，朱干設錫，冕而舞《大武》，乘大路，諸侯之僭禮也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-2","passageId":"li-ji_ch-11_p-11","order":2,"canonicalText":"臺門而旅樹，反坫，繡黼，丹朱中衣，大夫之僭禮也。","chunks":[["臺門而旅樹，反坫，繡黼，丹朱中衣，大夫之僭禮也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-3","passageId":"li-ji_ch-11_p-11","order":3,"canonicalText":"故天子微，諸侯僭；","chunks":[["故天子微，諸侯僭；","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-4","passageId":"li-ji_ch-11_p-11","order":4,"canonicalText":"大夫強，諸侯脅。","chunks":[["大夫強，諸侯脅。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-5","passageId":"li-ji_ch-11_p-11","order":5,"canonicalText":"於此相貴以等，相覿以貨，相賂以利，而天下之禮亂矣。","chunks":[["於此相貴以等，相覿以貨，相賂以利，而天下之禮亂矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-6","passageId":"li-ji_ch-11_p-11","order":6,"canonicalText":"諸侯不敢祖天子，大夫不敢祖諸侯。","chunks":[["諸侯不敢祖天子，大夫不敢祖諸侯。","zh-Hant"]]},{"id":"li-ji_ch-11_p-11_s-7","passageId":"li-ji_ch-11_p-11","order":7,"canonicalText":"而公廟之設於私家，非禮也，由三桓始也。","chunks":[["而公廟之設於私家，非禮也，由三桓始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-12_s-1","passageId":"li-ji_ch-11_p-12","order":1,"canonicalText":"天子存二代之後，猶尊賢也，尊賢不過二代。","chunks":[["天子存二代之後，猶尊賢也，尊賢不過二代。","zh-Hant"]]},{"id":"li-ji_ch-11_p-13_s-1","passageId":"li-ji_ch-11_p-13","order":1,"canonicalText":"諸侯不臣寓公。","chunks":[["諸侯不臣寓公。","zh-Hant"]]},{"id":"li-ji_ch-11_p-13_s-2","passageId":"li-ji_ch-11_p-13","order":2,"canonicalText":"故古者寓公不繼世。","chunks":[["故古者寓公不繼世。","zh-Hant"]]},{"id":"li-ji_ch-11_p-14_s-1","passageId":"li-ji_ch-11_p-14","order":1,"canonicalText":"君之南鄉，答陽之義也。","chunks":[["君之南鄉，答陽之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-14_s-2","passageId":"li-ji_ch-11_p-14","order":2,"canonicalText":"臣之北面，答君也。","chunks":[["臣之北面，答君也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-15_s-1","passageId":"li-ji_ch-11_p-15","order":1,"canonicalText":"大夫之臣不稽首，非尊家臣，以辟君也。","chunks":[["大夫之臣不稽首，非尊家臣，以辟君也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-16_s-1","passageId":"li-ji_ch-11_p-16","order":1,"canonicalText":"大夫有獻弗親，君有賜不面拜，為君之答己也。","chunks":[["大夫有獻弗親，君有賜不面拜，為君之答己也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-17_s-1","passageId":"li-ji_ch-11_p-17","order":1,"canonicalText":"鄉人禓，孔子朝服立于阼，存室神也。","chunks":[["鄉人禓，孔子朝服立于阼，存室神也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-18_s-1","passageId":"li-ji_ch-11_p-18","order":1,"canonicalText":"孔子曰：「射之以樂也，何以聽，何以射？","chunks":[["孔子曰：「射之以樂也，何以聽，何以射？","zh-Hant"]]},{"id":"li-ji_ch-11_p-18_s-2","passageId":"li-ji_ch-11_p-18","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-19_s-1","passageId":"li-ji_ch-11_p-19","order":1,"canonicalText":"孔子曰：「士，使之射，不能，則辭以疾。","chunks":[["孔子曰：「士，使之射，不能，則辭以疾。","zh-Hant"]]},{"id":"li-ji_ch-11_p-19_s-2","passageId":"li-ji_ch-11_p-19","order":2,"canonicalText":"縣弧之義也。","chunks":[["縣弧之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-19_s-3","passageId":"li-ji_ch-11_p-19","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-20_s-1","passageId":"li-ji_ch-11_p-20","order":1,"canonicalText":"孔子曰：「三日齊，一日用之，猶恐不敬；","chunks":[["孔子曰：「三日齊，一日用之，猶恐不敬；","zh-Hant"]]},{"id":"li-ji_ch-11_p-20_s-2","passageId":"li-ji_ch-11_p-20","order":2,"canonicalText":"二日伐鼓，何居？","chunks":[["二日伐鼓，何居？","zh-Hant"]]},{"id":"li-ji_ch-11_p-20_s-3","passageId":"li-ji_ch-11_p-20","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-21_s-1","passageId":"li-ji_ch-11_p-21","order":1,"canonicalText":"孔子曰：「繹之於庫門內，祊之於東方，朝市之於西方，失之矣。","chunks":[["孔子曰：「繹之於庫門內，祊之於東方，朝市之於西方，失之矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-21_s-2","passageId":"li-ji_ch-11_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-1","passageId":"li-ji_ch-11_p-22","order":1,"canonicalText":"社祭土而主陰氣也。","chunks":[["社祭土而主陰氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-2","passageId":"li-ji_ch-11_p-22","order":2,"canonicalText":"君南鄉於北墉下，答陰之義也。","chunks":[["君南鄉於北墉下，答陰之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-3","passageId":"li-ji_ch-11_p-22","order":3,"canonicalText":"日用甲，用日之始也。","chunks":[["日用甲，用日之始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-4","passageId":"li-ji_ch-11_p-22","order":4,"canonicalText":"天子大社必受霜露風雨，以達天地之氣也。","chunks":[["天子大社必受霜露風雨，以達天地之氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-5","passageId":"li-ji_ch-11_p-22","order":5,"canonicalText":"是故喪國之社屋之，不受天陽也。","chunks":[["是故喪國之社屋之，不受天陽也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-6","passageId":"li-ji_ch-11_p-22","order":6,"canonicalText":"薄社北牖，使陰明也。","chunks":[["薄社北牖，使陰明也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-7","passageId":"li-ji_ch-11_p-22","order":7,"canonicalText":"社所以神地之道也。","chunks":[["社所以神地之道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-8","passageId":"li-ji_ch-11_p-22","order":8,"canonicalText":"地載萬物，天垂象。","chunks":[["地載萬物，天垂象。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-9","passageId":"li-ji_ch-11_p-22","order":9,"canonicalText":"取財於地，取法於天，是以尊天而親地也，故教民美報焉。","chunks":[["取財於地，取法於天，是以尊天而親地也，故教民美報焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-10","passageId":"li-ji_ch-11_p-22","order":10,"canonicalText":"家主中溜而國主社，示本也。","chunks":[["家主中溜而國主社，示本也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-11","passageId":"li-ji_ch-11_p-22","order":11,"canonicalText":"唯為社事，單出里。","chunks":[["唯為社事，單出里。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-12","passageId":"li-ji_ch-11_p-22","order":12,"canonicalText":"唯為社田，國人畢作。","chunks":[["唯為社田，國人畢作。","zh-Hant"]]},{"id":"li-ji_ch-11_p-22_s-13","passageId":"li-ji_ch-11_p-22","order":13,"canonicalText":"唯社，丘乘共粢盛，所以報本反始也。","chunks":[["唯社，丘乘共粢盛，所以報本反始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-23_s-1","passageId":"li-ji_ch-11_p-23","order":1,"canonicalText":"季春出火，為焚也。","chunks":[["季春出火，為焚也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-23_s-2","passageId":"li-ji_ch-11_p-23","order":2,"canonicalText":"然後簡其車賦，而歷其卒伍，而君親誓社，以習軍旅。","chunks":[["然後簡其車賦，而歷其卒伍，而君親誓社，以習軍旅。","zh-Hant"]]},{"id":"li-ji_ch-11_p-23_s-3","passageId":"li-ji_ch-11_p-23","order":3,"canonicalText":"左之右之，坐之起之，以觀其習變也；","chunks":[["左之右之，坐之起之，以觀其習變也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-23_s-4","passageId":"li-ji_ch-11_p-23","order":4,"canonicalText":"而流示之禽，而鹽諸利，以觀其不犯命也。","chunks":[["而流示之禽，而鹽諸利，以觀其不犯命也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-23_s-5","passageId":"li-ji_ch-11_p-23","order":5,"canonicalText":"求服其志，不貪其得，故以戰則克，以祭則受福。","chunks":[["求服其志，不貪其得，故以戰則克，以祭則受福。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-1","passageId":"li-ji_ch-11_p-24","order":1,"canonicalText":"天子適四方，先柴。","chunks":[["天子適四方，先柴。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-2","passageId":"li-ji_ch-11_p-24","order":2,"canonicalText":"郊之祭也，迎長日之至也，大報天而主日也。","chunks":[["郊之祭也，迎長日之至也，大報天而主日也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-3","passageId":"li-ji_ch-11_p-24","order":3,"canonicalText":"兆於南郊，就陽位也。","chunks":[["兆於南郊，就陽位也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-4","passageId":"li-ji_ch-11_p-24","order":4,"canonicalText":"掃地而祭，於其質也。","chunks":[["掃地而祭，於其質也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-5","passageId":"li-ji_ch-11_p-24","order":5,"canonicalText":"器用陶匏，以象天地之性也。","chunks":[["器用陶匏，以象天地之性也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-6","passageId":"li-ji_ch-11_p-24","order":6,"canonicalText":"於郊，故謂之郊。","chunks":[["於郊，故謂之郊。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-7","passageId":"li-ji_ch-11_p-24","order":7,"canonicalText":"牲用騂，尚赤也；","chunks":[["牲用騂，尚赤也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-8","passageId":"li-ji_ch-11_p-24","order":8,"canonicalText":"用犢，貴誠也。","chunks":[["用犢，貴誠也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-9","passageId":"li-ji_ch-11_p-24","order":9,"canonicalText":"郊之用辛也，周之始郊日以至。","chunks":[["郊之用辛也，周之始郊日以至。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-10","passageId":"li-ji_ch-11_p-24","order":10,"canonicalText":"卜郊，受命于祖廟，作龜于禰宮，尊祖親考之義也。","chunks":[["卜郊，受命于祖廟，作龜于禰宮，尊祖親考之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-11","passageId":"li-ji_ch-11_p-24","order":11,"canonicalText":"卜之日，王立于澤，親聽誓命，受教諫之義也。","chunks":[["卜之日，王立于澤，親聽誓命，受教諫之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-12","passageId":"li-ji_ch-11_p-24","order":12,"canonicalText":"獻命庫門之內，戒百官也。","chunks":[["獻命庫門之內，戒百官也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-24_s-13","passageId":"li-ji_ch-11_p-24","order":13,"canonicalText":"大廟之命，戒百姓也。","chunks":[["大廟之命，戒百姓也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-1","passageId":"li-ji_ch-11_p-25","order":1,"canonicalText":"祭之日，王皮弁以聽祭報，示民嚴上也。","chunks":[["祭之日，王皮弁以聽祭報，示民嚴上也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-2","passageId":"li-ji_ch-11_p-25","order":2,"canonicalText":"喪者不哭，不敢凶服，汜掃反道，鄉為田燭。","chunks":[["喪者不哭，不敢凶服，汜掃反道，鄉為田燭。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-3","passageId":"li-ji_ch-11_p-25","order":3,"canonicalText":"弗命而民聽上。","chunks":[["弗命而民聽上。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-4","passageId":"li-ji_ch-11_p-25","order":4,"canonicalText":"祭之日，王被袞以象天，戴冕，璪十有二旒，則天數也。","chunks":[["祭之日，王被袞以象天，戴冕，璪十有二旒，則天數也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-5","passageId":"li-ji_ch-11_p-25","order":5,"canonicalText":"乘素車，貴其質也。","chunks":[["乘素車，貴其質也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-6","passageId":"li-ji_ch-11_p-25","order":6,"canonicalText":"旗十有二旒，龍章而設日月，以象天也。","chunks":[["旗十有二旒，龍章而設日月，以象天也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-7","passageId":"li-ji_ch-11_p-25","order":7,"canonicalText":"天垂象，聖人則之。","chunks":[["天垂象，聖人則之。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-8","passageId":"li-ji_ch-11_p-25","order":8,"canonicalText":"郊所以明天道也。","chunks":[["郊所以明天道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-9","passageId":"li-ji_ch-11_p-25","order":9,"canonicalText":"帝牛不吉，以為稷牛。","chunks":[["帝牛不吉，以為稷牛。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-10","passageId":"li-ji_ch-11_p-25","order":10,"canonicalText":"帝牛必在滌三月，稷牛唯具。","chunks":[["帝牛必在滌三月，稷牛唯具。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-11","passageId":"li-ji_ch-11_p-25","order":11,"canonicalText":"所以別事天神與人鬼也。","chunks":[["所以別事天神與人鬼也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-12","passageId":"li-ji_ch-11_p-25","order":12,"canonicalText":"萬物本乎天，人本乎祖，此所以配上帝也。","chunks":[["萬物本乎天，人本乎祖，此所以配上帝也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-25_s-13","passageId":"li-ji_ch-11_p-25","order":13,"canonicalText":"郊之祭也，大報本反始也。","chunks":[["郊之祭也，大報本反始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-1","passageId":"li-ji_ch-11_p-26","order":1,"canonicalText":"天子大蜡八。","chunks":[["天子大蜡八。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-2","passageId":"li-ji_ch-11_p-26","order":2,"canonicalText":"伊耆氏始為蜡，蜡也者，索也。","chunks":[["伊耆氏始為蜡，蜡也者，索也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-3","passageId":"li-ji_ch-11_p-26","order":3,"canonicalText":"歲十二月，合聚萬物而索饗之也。","chunks":[["歲十二月，合聚萬物而索饗之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-4","passageId":"li-ji_ch-11_p-26","order":4,"canonicalText":"蜡之祭也：主先嗇，而祭司嗇也。","chunks":[["蜡之祭也：主先嗇，而祭司嗇也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-5","passageId":"li-ji_ch-11_p-26","order":5,"canonicalText":"祭百種以報嗇也。","chunks":[["祭百種以報嗇也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-6","passageId":"li-ji_ch-11_p-26","order":6,"canonicalText":"饗農及郵表畷，禽獸，仁之至、義之盡也。","chunks":[["饗農及郵表畷，禽獸，仁之至、義之盡也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-7","passageId":"li-ji_ch-11_p-26","order":7,"canonicalText":"古之君子，使之必報之。","chunks":[["古之君子，使之必報之。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-8","passageId":"li-ji_ch-11_p-26","order":8,"canonicalText":"迎貓，為其食田鼠也；","chunks":[["迎貓，為其食田鼠也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-9","passageId":"li-ji_ch-11_p-26","order":9,"canonicalText":"迎虎，為其食田豕也，迎而祭之也。","chunks":[["迎虎，為其食田豕也，迎而祭之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-10","passageId":"li-ji_ch-11_p-26","order":10,"canonicalText":"祭坊與水庸，事也。","chunks":[["祭坊與水庸，事也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-11","passageId":"li-ji_ch-11_p-26","order":11,"canonicalText":"曰「土反其宅」，水歸其壑，昆蟲毋作，草木歸其澤。","chunks":[["曰「土反其宅」，水歸其壑，昆蟲毋作，草木歸其澤。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-12","passageId":"li-ji_ch-11_p-26","order":12,"canonicalText":"皮弁素服而祭。","chunks":[["皮弁素服而祭。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-13","passageId":"li-ji_ch-11_p-26","order":13,"canonicalText":"素服，以送終也。","chunks":[["素服，以送終也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-14","passageId":"li-ji_ch-11_p-26","order":14,"canonicalText":"葛帶榛杖，喪殺也。","chunks":[["葛帶榛杖，喪殺也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-15","passageId":"li-ji_ch-11_p-26","order":15,"canonicalText":"蜡之祭，仁之至、義之盡也。","chunks":[["蜡之祭，仁之至、義之盡也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-16","passageId":"li-ji_ch-11_p-26","order":16,"canonicalText":"黃衣黃冠而祭，息田夫也。","chunks":[["黃衣黃冠而祭，息田夫也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-17","passageId":"li-ji_ch-11_p-26","order":17,"canonicalText":"野夫黃冠；","chunks":[["野夫黃冠；","zh-Hant"]]},{"id":"li-ji_ch-11_p-26_s-18","passageId":"li-ji_ch-11_p-26","order":18,"canonicalText":"黃冠，草服也。","chunks":[["黃冠，草服也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-27_s-1","passageId":"li-ji_ch-11_p-27","order":1,"canonicalText":"大羅氏，天子之掌鳥獸者也，諸侯貢屬焉。","chunks":[["大羅氏，天子之掌鳥獸者也，諸侯貢屬焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-27_s-2","passageId":"li-ji_ch-11_p-27","order":2,"canonicalText":"草笠而至，尊野服也。","chunks":[["草笠而至，尊野服也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-27_s-3","passageId":"li-ji_ch-11_p-27","order":3,"canonicalText":"羅氏致鹿與女，而詔客告也。","chunks":[["羅氏致鹿與女，而詔客告也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-27_s-4","passageId":"li-ji_ch-11_p-27","order":4,"canonicalText":"以戒諸侯曰：「好田好女者亡其國。","chunks":[["以戒諸侯曰：「好田好女者亡其國。","zh-Hant"]]},{"id":"li-ji_ch-11_p-27_s-5","passageId":"li-ji_ch-11_p-27","order":5,"canonicalText":"」天子樹瓜華，不斂藏之種也。","chunks":[["」天子樹瓜華，不斂藏之種也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-28_s-1","passageId":"li-ji_ch-11_p-28","order":1,"canonicalText":"八蜡以記四方。","chunks":[["八蜡以記四方。","zh-Hant"]]},{"id":"li-ji_ch-11_p-28_s-2","passageId":"li-ji_ch-11_p-28","order":2,"canonicalText":"四方年不順成，八蜡不通，以謹民財也。","chunks":[["四方年不順成，八蜡不通，以謹民財也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-28_s-3","passageId":"li-ji_ch-11_p-28","order":3,"canonicalText":"順成之方，其蜡乃通，以移民也。","chunks":[["順成之方，其蜡乃通，以移民也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-28_s-4","passageId":"li-ji_ch-11_p-28","order":4,"canonicalText":"既蜡而收，民息已。","chunks":[["既蜡而收，民息已。","zh-Hant"]]},{"id":"li-ji_ch-11_p-28_s-5","passageId":"li-ji_ch-11_p-28","order":5,"canonicalText":"故既蜡，君子不興功。","chunks":[["故既蜡，君子不興功。","zh-Hant"]]},{"id":"li-ji_ch-11_p-29_s-1","passageId":"li-ji_ch-11_p-29","order":1,"canonicalText":"恒豆之菹，水草之和氣也；","chunks":[["恒豆之菹，水草之和氣也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-29_s-2","passageId":"li-ji_ch-11_p-29","order":2,"canonicalText":"其醢，陸產之物也。","chunks":[["其醢，陸產之物也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-29_s-3","passageId":"li-ji_ch-11_p-29","order":3,"canonicalText":"加豆，陸產也；","chunks":[["加豆，陸產也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-29_s-4","passageId":"li-ji_ch-11_p-29","order":4,"canonicalText":"其醢，水物也。","chunks":[["其醢，水物也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-29_s-5","passageId":"li-ji_ch-11_p-29","order":5,"canonicalText":"籩豆之薦，水土之品也，不敢用常褻味而貴多品，所以交於神明之義也，非食味之道也。","chunks":[["籩豆之薦，水土之品也，不敢用常褻味而貴多品，所以交於神明之義也，非食味之道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-30_s-1","passageId":"li-ji_ch-11_p-30","order":1,"canonicalText":"先王之薦，可食也而不可耆也。","chunks":[["先王之薦，可食也而不可耆也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-30_s-2","passageId":"li-ji_ch-11_p-30","order":2,"canonicalText":"卷冕路車，可陳也而不可好也。","chunks":[["卷冕路車，可陳也而不可好也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-30_s-3","passageId":"li-ji_ch-11_p-30","order":3,"canonicalText":"武壯，而不可樂也。","chunks":[["武壯，而不可樂也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-30_s-4","passageId":"li-ji_ch-11_p-30","order":4,"canonicalText":"宗廟之威，而不可安也。","chunks":[["宗廟之威，而不可安也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-30_s-5","passageId":"li-ji_ch-11_p-30","order":5,"canonicalText":"宗廟之器，可用也而不可便其利也，所以交於神明者，不可以同於所安樂之義也。","chunks":[["宗廟之器，可用也而不可便其利也，所以交於神明者，不可以同於所安樂之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-1","passageId":"li-ji_ch-11_p-31","order":1,"canonicalText":"酒醴之美，玄酒明水之尚，貴五味之本也。","chunks":[["酒醴之美，玄酒明水之尚，貴五味之本也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-2","passageId":"li-ji_ch-11_p-31","order":2,"canonicalText":"黼黻文繡之美，疏布之尚，反女功之始也。","chunks":[["黼黻文繡之美，疏布之尚，反女功之始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-3","passageId":"li-ji_ch-11_p-31","order":3,"canonicalText":"莞簟之安，而蒲越稿鞂之尚，明之也。","chunks":[["莞簟之安，而蒲越稿鞂之尚，明之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-4","passageId":"li-ji_ch-11_p-31","order":4,"canonicalText":"大羹不和，貴其質也。","chunks":[["大羹不和，貴其質也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-5","passageId":"li-ji_ch-11_p-31","order":5,"canonicalText":"大圭不琢，美其質也。","chunks":[["大圭不琢，美其質也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-6","passageId":"li-ji_ch-11_p-31","order":6,"canonicalText":"丹漆雕几之美，素車之乘，尊其樸也，貴其質而已矣。","chunks":[["丹漆雕几之美，素車之乘，尊其樸也，貴其質而已矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-7","passageId":"li-ji_ch-11_p-31","order":7,"canonicalText":"所以交於神明者，不可同於所安褻之甚也。","chunks":[["所以交於神明者，不可同於所安褻之甚也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-31_s-8","passageId":"li-ji_ch-11_p-31","order":8,"canonicalText":"如是而後宜。","chunks":[["如是而後宜。","zh-Hant"]]},{"id":"li-ji_ch-11_p-32_s-1","passageId":"li-ji_ch-11_p-32","order":1,"canonicalText":"鼎俎奇而籩豆偶，陰陽之義也。","chunks":[["鼎俎奇而籩豆偶，陰陽之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-32_s-2","passageId":"li-ji_ch-11_p-32","order":2,"canonicalText":"黃目，郁氣之上尊也。","chunks":[["黃目，郁氣之上尊也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-32_s-3","passageId":"li-ji_ch-11_p-32","order":3,"canonicalText":"黃者中也；","chunks":[["黃者中也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-32_s-4","passageId":"li-ji_ch-11_p-32","order":4,"canonicalText":"目者氣之清明者也。","chunks":[["目者氣之清明者也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-32_s-5","passageId":"li-ji_ch-11_p-32","order":5,"canonicalText":"言酌於中而清明於外也。","chunks":[["言酌於中而清明於外也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-33_s-1","passageId":"li-ji_ch-11_p-33","order":1,"canonicalText":"祭天，掃地而祭焉，於其質而已矣。","chunks":[["祭天，掃地而祭焉，於其質而已矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-33_s-2","passageId":"li-ji_ch-11_p-33","order":2,"canonicalText":"醯醢之美，而煎鹽之尚，貴天產也。","chunks":[["醯醢之美，而煎鹽之尚，貴天產也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-33_s-3","passageId":"li-ji_ch-11_p-33","order":3,"canonicalText":"割刀之用，而鸞刀之貴，貴其義也。","chunks":[["割刀之用，而鸞刀之貴，貴其義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-33_s-4","passageId":"li-ji_ch-11_p-33","order":4,"canonicalText":"聲和而後斷也。","chunks":[["聲和而後斷也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-34_s-1","passageId":"li-ji_ch-11_p-34","order":1,"canonicalText":"冠義：始冠之，緇布之冠也。","chunks":[["冠義：始冠之，緇布之冠也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-34_s-2","passageId":"li-ji_ch-11_p-34","order":2,"canonicalText":"大古冠布，齊則緇之。","chunks":[["大古冠布，齊則緇之。","zh-Hant"]]},{"id":"li-ji_ch-11_p-34_s-3","passageId":"li-ji_ch-11_p-34","order":3,"canonicalText":"其緌也，孔子曰：「吾未之聞也。","chunks":[["其緌也，孔子曰：「吾未之聞也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-34_s-4","passageId":"li-ji_ch-11_p-34","order":4,"canonicalText":"冠而敝之可也。","chunks":[["冠而敝之可也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-34_s-5","passageId":"li-ji_ch-11_p-34","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-11_p-35_s-1","passageId":"li-ji_ch-11_p-35","order":1,"canonicalText":"適子冠於阼，以著代也。","chunks":[["適子冠於阼，以著代也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-35_s-2","passageId":"li-ji_ch-11_p-35","order":2,"canonicalText":"醮於客位，加有成也。","chunks":[["醮於客位，加有成也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-35_s-3","passageId":"li-ji_ch-11_p-35","order":3,"canonicalText":"三加彌尊，喻其志也。","chunks":[["三加彌尊，喻其志也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-35_s-4","passageId":"li-ji_ch-11_p-35","order":4,"canonicalText":"冠而字之，敬其名也。","chunks":[["冠而字之，敬其名也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-36_s-1","passageId":"li-ji_ch-11_p-36","order":1,"canonicalText":"委貌，周道也。","chunks":[["委貌，周道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-36_s-2","passageId":"li-ji_ch-11_p-36","order":2,"canonicalText":"章甫，殷道也。","chunks":[["章甫，殷道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-36_s-3","passageId":"li-ji_ch-11_p-36","order":3,"canonicalText":"毋追，夏后氏之道也。","chunks":[["毋追，夏后氏之道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-36_s-4","passageId":"li-ji_ch-11_p-36","order":4,"canonicalText":"周弁，殷冔，夏收。","chunks":[["周弁，殷冔，夏收。","zh-Hant"]]},{"id":"li-ji_ch-11_p-36_s-5","passageId":"li-ji_ch-11_p-36","order":5,"canonicalText":"三王共皮弁素積。","chunks":[["三王共皮弁素積。","zh-Hant"]]},{"id":"li-ji_ch-11_p-37_s-1","passageId":"li-ji_ch-11_p-37","order":1,"canonicalText":"無大夫冠禮，而有其昏禮。","chunks":[["無大夫冠禮，而有其昏禮。","zh-Hant"]]},{"id":"li-ji_ch-11_p-37_s-2","passageId":"li-ji_ch-11_p-37","order":2,"canonicalText":"古者，五十而後爵，何大夫冠禮之有？","chunks":[["古者，五十而後爵，何大夫冠禮之有？","zh-Hant"]]},{"id":"li-ji_ch-11_p-37_s-3","passageId":"li-ji_ch-11_p-37","order":3,"canonicalText":"諸侯之有冠禮，夏之末造也。","chunks":[["諸侯之有冠禮，夏之末造也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-1","passageId":"li-ji_ch-11_p-38","order":1,"canonicalText":"天子之元子，士也。","chunks":[["天子之元子，士也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-2","passageId":"li-ji_ch-11_p-38","order":2,"canonicalText":"天下無生而貴者也。","chunks":[["天下無生而貴者也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-3","passageId":"li-ji_ch-11_p-38","order":3,"canonicalText":"繼世以立諸侯，象賢也。","chunks":[["繼世以立諸侯，象賢也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-4","passageId":"li-ji_ch-11_p-38","order":4,"canonicalText":"以官爵人，德之殺也。","chunks":[["以官爵人，德之殺也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-5","passageId":"li-ji_ch-11_p-38","order":5,"canonicalText":"死而謚，今也；","chunks":[["死而謚，今也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-38_s-6","passageId":"li-ji_ch-11_p-38","order":6,"canonicalText":"古者生無爵，死無謚。","chunks":[["古者生無爵，死無謚。","zh-Hant"]]},{"id":"li-ji_ch-11_p-39_s-1","passageId":"li-ji_ch-11_p-39","order":1,"canonicalText":"禮之所尊，尊其義也。","chunks":[["禮之所尊，尊其義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-39_s-2","passageId":"li-ji_ch-11_p-39","order":2,"canonicalText":"失其義，陳其數，祝史之事也。","chunks":[["失其義，陳其數，祝史之事也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-39_s-3","passageId":"li-ji_ch-11_p-39","order":3,"canonicalText":"故其數可陳也，其義難知也。","chunks":[["故其數可陳也，其義難知也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-39_s-4","passageId":"li-ji_ch-11_p-39","order":4,"canonicalText":"知其義而敬守之，天子之所以治天下也。","chunks":[["知其義而敬守之，天子之所以治天下也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-1","passageId":"li-ji_ch-11_p-40","order":1,"canonicalText":"天地合而後萬物興焉。","chunks":[["天地合而後萬物興焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-2","passageId":"li-ji_ch-11_p-40","order":2,"canonicalText":"夫昏禮，萬世之始也。","chunks":[["夫昏禮，萬世之始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-3","passageId":"li-ji_ch-11_p-40","order":3,"canonicalText":"取於異姓，所以附遠厚別也。","chunks":[["取於異姓，所以附遠厚別也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-4","passageId":"li-ji_ch-11_p-40","order":4,"canonicalText":"幣必誠，辭無不腆。","chunks":[["幣必誠，辭無不腆。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-5","passageId":"li-ji_ch-11_p-40","order":5,"canonicalText":"告之以直信；","chunks":[["告之以直信；","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-6","passageId":"li-ji_ch-11_p-40","order":6,"canonicalText":"信，事人也；","chunks":[["信，事人也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-7","passageId":"li-ji_ch-11_p-40","order":7,"canonicalText":"信，婦德也。","chunks":[["信，婦德也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-8","passageId":"li-ji_ch-11_p-40","order":8,"canonicalText":"壹與之齊，終身不改。","chunks":[["壹與之齊，終身不改。","zh-Hant"]]},{"id":"li-ji_ch-11_p-40_s-9","passageId":"li-ji_ch-11_p-40","order":9,"canonicalText":"故夫死不嫁。","chunks":[["故夫死不嫁。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-1","passageId":"li-ji_ch-11_p-41","order":1,"canonicalText":"男子親迎，男先於女，剛柔之義也。","chunks":[["男子親迎，男先於女，剛柔之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-2","passageId":"li-ji_ch-11_p-41","order":2,"canonicalText":"天先乎地，君先乎臣，其義一也。","chunks":[["天先乎地，君先乎臣，其義一也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-3","passageId":"li-ji_ch-11_p-41","order":3,"canonicalText":"執摯以相見，敬章別也。","chunks":[["執摯以相見，敬章別也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-4","passageId":"li-ji_ch-11_p-41","order":4,"canonicalText":"男女有別，然後父子親，父子親然後義生，義生然後禮作，禮作然後萬物安。","chunks":[["男女有別，然後父子親，父子親然後義生，義生然後禮作，禮作然後萬物安。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-5","passageId":"li-ji_ch-11_p-41","order":5,"canonicalText":"無別無義，禽獸之道也。","chunks":[["無別無義，禽獸之道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-6","passageId":"li-ji_ch-11_p-41","order":6,"canonicalText":"婿親御授綏，親之也。","chunks":[["婿親御授綏，親之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-7","passageId":"li-ji_ch-11_p-41","order":7,"canonicalText":"親之也者，親之也。","chunks":[["親之也者，親之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-8","passageId":"li-ji_ch-11_p-41","order":8,"canonicalText":"敬而親之，先王之所以得天下也。","chunks":[["敬而親之，先王之所以得天下也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-9","passageId":"li-ji_ch-11_p-41","order":9,"canonicalText":"出乎大門而先，男帥女，女從男，夫婦之義由此始也。","chunks":[["出乎大門而先，男帥女，女從男，夫婦之義由此始也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-10","passageId":"li-ji_ch-11_p-41","order":10,"canonicalText":"婦人，從人者也；","chunks":[["婦人，從人者也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-11","passageId":"li-ji_ch-11_p-41","order":11,"canonicalText":"幼從父兄，嫁從夫，夫死從子。","chunks":[["幼從父兄，嫁從夫，夫死從子。","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-12","passageId":"li-ji_ch-11_p-41","order":12,"canonicalText":"夫也者，夫也；","chunks":[["夫也者，夫也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-41_s-13","passageId":"li-ji_ch-11_p-41","order":13,"canonicalText":"夫也者，以知帥人者也。","chunks":[["夫也者，以知帥人者也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-42_s-1","passageId":"li-ji_ch-11_p-42","order":1,"canonicalText":"玄冕齋戒，鬼神陰陽也。","chunks":[["玄冕齋戒，鬼神陰陽也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-42_s-2","passageId":"li-ji_ch-11_p-42","order":2,"canonicalText":"將以為社稷主，為先祖後，而可以不致敬乎？","chunks":[["將以為社稷主，為先祖後，而可以不致敬乎？","zh-Hant"]]},{"id":"li-ji_ch-11_p-42_s-3","passageId":"li-ji_ch-11_p-42","order":3,"canonicalText":"共牢而食，同尊卑也。","chunks":[["共牢而食，同尊卑也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-42_s-4","passageId":"li-ji_ch-11_p-42","order":4,"canonicalText":"故婦人無爵，從夫之爵，坐以夫之齒。","chunks":[["故婦人無爵，從夫之爵，坐以夫之齒。","zh-Hant"]]},{"id":"li-ji_ch-11_p-43_s-1","passageId":"li-ji_ch-11_p-43","order":1,"canonicalText":"器用陶匏，尚禮然也。","chunks":[["器用陶匏，尚禮然也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-43_s-2","passageId":"li-ji_ch-11_p-43","order":2,"canonicalText":"三王作牢用陶匏。","chunks":[["三王作牢用陶匏。","zh-Hant"]]},{"id":"li-ji_ch-11_p-43_s-3","passageId":"li-ji_ch-11_p-43","order":3,"canonicalText":"厥明，婦盥饋。","chunks":[["厥明，婦盥饋。","zh-Hant"]]},{"id":"li-ji_ch-11_p-43_s-4","passageId":"li-ji_ch-11_p-43","order":4,"canonicalText":"舅姑卒食，婦餕餘，私之也。","chunks":[["舅姑卒食，婦餕餘，私之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-43_s-5","passageId":"li-ji_ch-11_p-43","order":5,"canonicalText":"舅姑降自西階，婦降自阼階，授之室也。","chunks":[["舅姑降自西階，婦降自阼階，授之室也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-44_s-1","passageId":"li-ji_ch-11_p-44","order":1,"canonicalText":"昏禮不用樂，幽陰之義也。","chunks":[["昏禮不用樂，幽陰之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-44_s-2","passageId":"li-ji_ch-11_p-44","order":2,"canonicalText":"樂，陽氣也。","chunks":[["樂，陽氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-44_s-3","passageId":"li-ji_ch-11_p-44","order":3,"canonicalText":"昏禮不賀，人之序也。","chunks":[["昏禮不賀，人之序也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-1","passageId":"li-ji_ch-11_p-45","order":1,"canonicalText":"有虞氏之祭也，尚用氣；","chunks":[["有虞氏之祭也，尚用氣；","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-2","passageId":"li-ji_ch-11_p-45","order":2,"canonicalText":"血腥爓祭，用氣也。","chunks":[["血腥爓祭，用氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-3","passageId":"li-ji_ch-11_p-45","order":3,"canonicalText":"殷人尚聲，臭味未成，滌蕩其聲；","chunks":[["殷人尚聲，臭味未成，滌蕩其聲；","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-4","passageId":"li-ji_ch-11_p-45","order":4,"canonicalText":"樂三闋，然後出迎牲。","chunks":[["樂三闋，然後出迎牲。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-5","passageId":"li-ji_ch-11_p-45","order":5,"canonicalText":"聲音之號，所以詔告於天地之間也。","chunks":[["聲音之號，所以詔告於天地之間也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-6","passageId":"li-ji_ch-11_p-45","order":6,"canonicalText":"周人尚臭，灌用鬯臭，郁合鬯；","chunks":[["周人尚臭，灌用鬯臭，郁合鬯；","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-7","passageId":"li-ji_ch-11_p-45","order":7,"canonicalText":"臭，陰達於淵泉。","chunks":[["臭，陰達於淵泉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-8","passageId":"li-ji_ch-11_p-45","order":8,"canonicalText":"灌以圭璋，用玉氣也。","chunks":[["灌以圭璋，用玉氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-9","passageId":"li-ji_ch-11_p-45","order":9,"canonicalText":"既灌，然後迎牲，致陰氣也。","chunks":[["既灌，然後迎牲，致陰氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-10","passageId":"li-ji_ch-11_p-45","order":10,"canonicalText":"蕭合黍稷；","chunks":[["蕭合黍稷；","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-11","passageId":"li-ji_ch-11_p-45","order":11,"canonicalText":"臭，陽達於墻屋。","chunks":[["臭，陽達於墻屋。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-12","passageId":"li-ji_ch-11_p-45","order":12,"canonicalText":"故既奠，然後焫蕭合膻薌。","chunks":[["故既奠，然後焫蕭合膻薌。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-13","passageId":"li-ji_ch-11_p-45","order":13,"canonicalText":"凡祭，慎諸此。","chunks":[["凡祭，慎諸此。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-14","passageId":"li-ji_ch-11_p-45","order":14,"canonicalText":"魂氣歸于天，形魄歸于地。","chunks":[["魂氣歸于天，形魄歸于地。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-15","passageId":"li-ji_ch-11_p-45","order":15,"canonicalText":"故祭，求諸陰陽之義也。","chunks":[["故祭，求諸陰陽之義也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-45_s-16","passageId":"li-ji_ch-11_p-45","order":16,"canonicalText":"殷人先求諸陽，周人先求諸陰。","chunks":[["殷人先求諸陽，周人先求諸陰。","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-1","passageId":"li-ji_ch-11_p-46","order":1,"canonicalText":"詔祝於室，坐尸於堂，用牲於庭，升首於室。","chunks":[["詔祝於室，坐尸於堂，用牲於庭，升首於室。","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-2","passageId":"li-ji_ch-11_p-46","order":2,"canonicalText":"直祭，祝于主；","chunks":[["直祭，祝于主；","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-3","passageId":"li-ji_ch-11_p-46","order":3,"canonicalText":"索祭，祝于祊。","chunks":[["索祭，祝于祊。","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-4","passageId":"li-ji_ch-11_p-46","order":4,"canonicalText":"不知神之所在，於彼乎？","chunks":[["不知神之所在，於彼乎？","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-5","passageId":"li-ji_ch-11_p-46","order":5,"canonicalText":"於此乎？","chunks":[["於此乎？","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-6","passageId":"li-ji_ch-11_p-46","order":6,"canonicalText":"或諸遠人乎？","chunks":[["或諸遠人乎？","zh-Hant"]]},{"id":"li-ji_ch-11_p-46_s-7","passageId":"li-ji_ch-11_p-46","order":7,"canonicalText":"祭于祊，尚曰求諸遠者與？","chunks":[["祭于祊，尚曰求諸遠者與？","zh-Hant"]]},{"id":"li-ji_ch-11_p-47_s-1","passageId":"li-ji_ch-11_p-47","order":1,"canonicalText":"祊之為言倞也，肵之為言敬也。","chunks":[["祊之為言倞也，肵之為言敬也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-47_s-2","passageId":"li-ji_ch-11_p-47","order":2,"canonicalText":"富也者福也，首也者，直也。","chunks":[["富也者福也，首也者，直也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-47_s-3","passageId":"li-ji_ch-11_p-47","order":3,"canonicalText":"相，饗之也。","chunks":[["相，饗之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-47_s-4","passageId":"li-ji_ch-11_p-47","order":4,"canonicalText":"嘏，長也，大也。","chunks":[["嘏，長也，大也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-47_s-5","passageId":"li-ji_ch-11_p-47","order":5,"canonicalText":"尸，陳也。","chunks":[["尸，陳也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-48_s-1","passageId":"li-ji_ch-11_p-48","order":1,"canonicalText":"毛血，告幽全之物也。","chunks":[["毛血，告幽全之物也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-48_s-2","passageId":"li-ji_ch-11_p-48","order":2,"canonicalText":"告幽全之物者，貴純之道也。","chunks":[["告幽全之物者，貴純之道也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-48_s-3","passageId":"li-ji_ch-11_p-48","order":3,"canonicalText":"血祭，盛氣也。","chunks":[["血祭，盛氣也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-48_s-4","passageId":"li-ji_ch-11_p-48","order":4,"canonicalText":"祭肺肝心，貴氣主也。","chunks":[["祭肺肝心，貴氣主也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-49_s-1","passageId":"li-ji_ch-11_p-49","order":1,"canonicalText":"祭黍稷加肺，祭齊加明水，報陰也。","chunks":[["祭黍稷加肺，祭齊加明水，報陰也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-49_s-2","passageId":"li-ji_ch-11_p-49","order":2,"canonicalText":"取膟菺燔燎，升首，報陽也。","chunks":[["取膟菺燔燎，升首，報陽也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-50_s-1","passageId":"li-ji_ch-11_p-50","order":1,"canonicalText":"明水涗齊，貴新也。","chunks":[["明水涗齊，貴新也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-50_s-2","passageId":"li-ji_ch-11_p-50","order":2,"canonicalText":"凡涗，新之也。","chunks":[["凡涗，新之也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-50_s-3","passageId":"li-ji_ch-11_p-50","order":3,"canonicalText":"其謂之明水也，由主人之絜著此水也。","chunks":[["其謂之明水也，由主人之絜著此水也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-51_s-1","passageId":"li-ji_ch-11_p-51","order":1,"canonicalText":"君再拜稽首，肉袒親割，敬之至也。","chunks":[["君再拜稽首，肉袒親割，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-51_s-2","passageId":"li-ji_ch-11_p-51","order":2,"canonicalText":"敬之至也，服也。","chunks":[["敬之至也，服也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-51_s-3","passageId":"li-ji_ch-11_p-51","order":3,"canonicalText":"拜，服也；","chunks":[["拜，服也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-51_s-4","passageId":"li-ji_ch-11_p-51","order":4,"canonicalText":"稽首，服之甚也；","chunks":[["稽首，服之甚也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-51_s-5","passageId":"li-ji_ch-11_p-51","order":5,"canonicalText":"肉袒，服之盡也。","chunks":[["肉袒，服之盡也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-52_s-1","passageId":"li-ji_ch-11_p-52","order":1,"canonicalText":"祭稱孝孫孝子，以其義稱也；","chunks":[["祭稱孝孫孝子，以其義稱也；","zh-Hant"]]},{"id":"li-ji_ch-11_p-52_s-2","passageId":"li-ji_ch-11_p-52","order":2,"canonicalText":"稱曾孫某，謂國家也。","chunks":[["稱曾孫某，謂國家也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-52_s-3","passageId":"li-ji_ch-11_p-52","order":3,"canonicalText":"祭祀之相，主人自致其敬，盡其嘉，而無與讓也。","chunks":[["祭祀之相，主人自致其敬，盡其嘉，而無與讓也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-53_s-1","passageId":"li-ji_ch-11_p-53","order":1,"canonicalText":"腥肆爓腍祭，豈知神之所饗也？","chunks":[["腥肆爓腍祭，豈知神之所饗也？","zh-Hant"]]},{"id":"li-ji_ch-11_p-53_s-2","passageId":"li-ji_ch-11_p-53","order":2,"canonicalText":"主人自盡其敬而已矣。","chunks":[["主人自盡其敬而已矣。","zh-Hant"]]},{"id":"li-ji_ch-11_p-54_s-1","passageId":"li-ji_ch-11_p-54","order":1,"canonicalText":"舉斝角，詔妥尸。","chunks":[["舉斝角，詔妥尸。","zh-Hant"]]},{"id":"li-ji_ch-11_p-54_s-2","passageId":"li-ji_ch-11_p-54","order":2,"canonicalText":"古者，尸無事則立，有事而後坐也。","chunks":[["古者，尸無事則立，有事而後坐也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-54_s-3","passageId":"li-ji_ch-11_p-54","order":3,"canonicalText":"尸，神象也。","chunks":[["尸，神象也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-54_s-4","passageId":"li-ji_ch-11_p-54","order":4,"canonicalText":"祝，將命也。","chunks":[["祝，將命也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-55_s-1","passageId":"li-ji_ch-11_p-55","order":1,"canonicalText":"縮酌用茅，明酌也。","chunks":[["縮酌用茅，明酌也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-55_s-2","passageId":"li-ji_ch-11_p-55","order":2,"canonicalText":"醆酒涗于清，汁獻涗于醆酒；","chunks":[["醆酒涗于清，汁獻涗于醆酒；","zh-Hant"]]},{"id":"li-ji_ch-11_p-55_s-3","passageId":"li-ji_ch-11_p-55","order":3,"canonicalText":"猶明清與醆酒于舊澤之酒也。","chunks":[["猶明清與醆酒于舊澤之酒也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-56_s-1","passageId":"li-ji_ch-11_p-56","order":1,"canonicalText":"祭有祈焉，有報焉，有由辟焉。","chunks":[["祭有祈焉，有報焉，有由辟焉。","zh-Hant"]]},{"id":"li-ji_ch-11_p-57_s-1","passageId":"li-ji_ch-11_p-57","order":1,"canonicalText":"齊之玄也，以陰幽思也。","chunks":[["齊之玄也，以陰幽思也。","zh-Hant"]]},{"id":"li-ji_ch-11_p-57_s-2","passageId":"li-ji_ch-11_p-57","order":2,"canonicalText":"故君子三日齊，必見其所祭者。","chunks":[["故君子三日齊，必見其所祭者。","zh-Hant"]]},{"id":"li-ji_ch-12_p-1_s-1","passageId":"li-ji_ch-12_p-1","order":1,"canonicalText":"后王命冢宰，降德于眾兆民。","chunks":[["后王命冢宰，降德于眾兆民。","zh-Hant"]]},{"id":"li-ji_ch-12_p-2_s-1","passageId":"li-ji_ch-12_p-2","order":1,"canonicalText":"子事父母，雞初鳴，咸盥漱，櫛縰笄總，拂髦冠緌纓，端韠紳，搢笏。","chunks":[["子事父母，雞初鳴，咸盥漱，櫛縰笄總，拂髦冠緌纓，端韠紳，搢笏。","zh-Hant"]]},{"id":"li-ji_ch-12_p-2_s-2","passageId":"li-ji_ch-12_p-2","order":2,"canonicalText":"左右佩用，左佩紛帨、刀、礪、小觿、金燧，右佩玦、捍、管、遰、大觿、木燧，偪，屨著綦。","chunks":[["左右佩用，左佩紛帨、刀、礪、小觿、金燧，右佩玦、捍、管、遰、大觿、木燧，偪，屨著綦。","zh-Hant"]]},{"id":"li-ji_ch-12_p-3_s-1","passageId":"li-ji_ch-12_p-3","order":1,"canonicalText":"婦事舅姑，如事父母。","chunks":[["婦事舅姑，如事父母。","zh-Hant"]]},{"id":"li-ji_ch-12_p-3_s-2","passageId":"li-ji_ch-12_p-3","order":2,"canonicalText":"雞初鳴，咸盥漱，櫛縰，笄總，衣紳。","chunks":[["雞初鳴，咸盥漱，櫛縰，笄總，衣紳。","zh-Hant"]]},{"id":"li-ji_ch-12_p-3_s-3","passageId":"li-ji_ch-12_p-3","order":3,"canonicalText":"左佩紛帨、刀、礪、小觿、金燧，右佩箴、管、線、纊，施縏帙，大觿、木燧、衿纓，綦屨。","chunks":[["左佩紛帨、刀、礪、小觿、金燧，右佩箴、管、線、纊，施縏帙，大觿、木燧、衿纓，綦屨。","zh-Hant"]]},{"id":"li-ji_ch-12_p-4_s-1","passageId":"li-ji_ch-12_p-4","order":1,"canonicalText":"以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而敬抑搔之。","chunks":[["以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而敬抑搔之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-4_s-2","passageId":"li-ji_ch-12_p-4","order":2,"canonicalText":"出入，則或先或後，而敬扶持之。","chunks":[["出入，則或先或後，而敬扶持之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-4_s-3","passageId":"li-ji_ch-12_p-4","order":3,"canonicalText":"進盥，少者奉盤，長者奉水，請沃盥，盥卒授巾。","chunks":[["進盥，少者奉盤，長者奉水，請沃盥，盥卒授巾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-4_s-4","passageId":"li-ji_ch-12_p-4","order":4,"canonicalText":"問所欲而敬進之，柔色以溫之，饘酏、酒醴、芼羹、菽麥、蕡稻、黍粱、秫唯所欲，棗、栗、飴、蜜以甘之，堇、荁、枌、榆免槁薧滫以滑之，脂膏以膏之，父母舅姑必嘗之而後退。","chunks":[["問所欲而敬進之，柔色以溫之，饘酏、酒醴、芼羹、菽麥、蕡稻、黍粱、秫唯所欲，棗、栗、飴、蜜以甘之，堇、荁、枌、榆免槁薧滫以滑之，脂膏以膏之，父母舅姑必嘗之而後退。","zh-Hant"]]},{"id":"li-ji_ch-12_p-5_s-1","passageId":"li-ji_ch-12_p-5","order":1,"canonicalText":"男女未冠笄者，雞初鳴，咸盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而朝，問何食飲矣。","chunks":[["男女未冠笄者，雞初鳴，咸盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而朝，問何食飲矣。","zh-Hant"]]},{"id":"li-ji_ch-12_p-5_s-2","passageId":"li-ji_ch-12_p-5","order":2,"canonicalText":"若已食則退，若未食則佐長者視具。","chunks":[["若已食則退，若未食則佐長者視具。","zh-Hant"]]},{"id":"li-ji_ch-12_p-6_s-1","passageId":"li-ji_ch-12_p-6","order":1,"canonicalText":"凡內外，雞初鳴，咸盥漱，衣服，斂枕簟，灑掃室堂及庭，布席，各從其事。","chunks":[["凡內外，雞初鳴，咸盥漱，衣服，斂枕簟，灑掃室堂及庭，布席，各從其事。","zh-Hant"]]},{"id":"li-ji_ch-12_p-7_s-1","passageId":"li-ji_ch-12_p-7","order":1,"canonicalText":"孺子蚤寢晏起，唯所欲，食無時。","chunks":[["孺子蚤寢晏起，唯所欲，食無時。","zh-Hant"]]},{"id":"li-ji_ch-12_p-8_s-1","passageId":"li-ji_ch-12_p-8","order":1,"canonicalText":"由命士以上，父子皆異宮。","chunks":[["由命士以上，父子皆異宮。","zh-Hant"]]},{"id":"li-ji_ch-12_p-8_s-2","passageId":"li-ji_ch-12_p-8","order":2,"canonicalText":"昧爽而朝，慈以旨甘，日出而退，各從其事，日入而夕，慈以旨甘。","chunks":[["昧爽而朝，慈以旨甘，日出而退，各從其事，日入而夕，慈以旨甘。","zh-Hant"]]},{"id":"li-ji_ch-12_p-9_s-1","passageId":"li-ji_ch-12_p-9","order":1,"canonicalText":"父母舅姑將坐，奉席請何鄉；","chunks":[["父母舅姑將坐，奉席請何鄉；","zh-Hant"]]},{"id":"li-ji_ch-12_p-9_s-2","passageId":"li-ji_ch-12_p-9","order":2,"canonicalText":"將衽，長者奉席請何趾。","chunks":[["將衽，長者奉席請何趾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-9_s-3","passageId":"li-ji_ch-12_p-9","order":3,"canonicalText":"少者執床與坐，御者舉几，斂席與簟，縣衾篋枕，斂簟而襡之。","chunks":[["少者執床與坐，御者舉几，斂席與簟，縣衾篋枕，斂簟而襡之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-10_s-1","passageId":"li-ji_ch-12_p-10","order":1,"canonicalText":"父母舅姑之衣衾簟席枕几不傳，杖屨只敬之，勿敢近。","chunks":[["父母舅姑之衣衾簟席枕几不傳，杖屨只敬之，勿敢近。","zh-Hant"]]},{"id":"li-ji_ch-12_p-10_s-2","passageId":"li-ji_ch-12_p-10","order":2,"canonicalText":"敦牟卮匜，非餕莫敢用；","chunks":[["敦牟卮匜，非餕莫敢用；","zh-Hant"]]},{"id":"li-ji_ch-12_p-10_s-3","passageId":"li-ji_ch-12_p-10","order":3,"canonicalText":"與恒食飲，非餕，莫之敢飲食。","chunks":[["與恒食飲，非餕，莫之敢飲食。","zh-Hant"]]},{"id":"li-ji_ch-12_p-11_s-1","passageId":"li-ji_ch-12_p-11","order":1,"canonicalText":"父母在，朝夕恒食，子婦佐餕，既食恒餕，父沒母存，冢子御食，群子婦佐餕如初，旨甘柔滑，孺子餕。","chunks":[["父母在，朝夕恒食，子婦佐餕，既食恒餕，父沒母存，冢子御食，群子婦佐餕如初，旨甘柔滑，孺子餕。","zh-Hant"]]},{"id":"li-ji_ch-12_p-12_s-1","passageId":"li-ji_ch-12_p-12","order":1,"canonicalText":"在父母舅姑之所，有命之，應唯敬對。","chunks":[["在父母舅姑之所，有命之，應唯敬對。","zh-Hant"]]},{"id":"li-ji_ch-12_p-12_s-2","passageId":"li-ji_ch-12_p-12","order":2,"canonicalText":"進退周旋慎齊，升降出入揖游，不敢噦噫、嚏咳、欠伸、跛倚、睇視，不敢唾洟；","chunks":[["進退周旋慎齊，升降出入揖游，不敢噦噫、嚏咳、欠伸、跛倚、睇視，不敢唾洟；","zh-Hant"]]},{"id":"li-ji_ch-12_p-12_s-3","passageId":"li-ji_ch-12_p-12","order":3,"canonicalText":"寒不敢襲，癢不敢搔；","chunks":[["寒不敢襲，癢不敢搔；","zh-Hant"]]},{"id":"li-ji_ch-12_p-12_s-4","passageId":"li-ji_ch-12_p-12","order":4,"canonicalText":"不有敬事，不敢袒裼，不涉不撅，褻衣衾不見里。","chunks":[["不有敬事，不敢袒裼，不涉不撅，褻衣衾不見里。","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-1","passageId":"li-ji_ch-12_p-13","order":1,"canonicalText":"父母唾洟不見，冠帶垢，和灰請漱；","chunks":[["父母唾洟不見，冠帶垢，和灰請漱；","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-2","passageId":"li-ji_ch-12_p-13","order":2,"canonicalText":"衣裳垢，和灰請浣；","chunks":[["衣裳垢，和灰請浣；","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-3","passageId":"li-ji_ch-12_p-13","order":3,"canonicalText":"衣裳綻裂，紉箴請補綴。","chunks":[["衣裳綻裂，紉箴請補綴。","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-4","passageId":"li-ji_ch-12_p-13","order":4,"canonicalText":"五日，則燂湯請浴，三日具沐，其間面垢，燂潘請靧；","chunks":[["五日，則燂湯請浴，三日具沐，其間面垢，燂潘請靧；","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-5","passageId":"li-ji_ch-12_p-13","order":5,"canonicalText":"足垢，燂湯請洗。","chunks":[["足垢，燂湯請洗。","zh-Hant"]]},{"id":"li-ji_ch-12_p-13_s-6","passageId":"li-ji_ch-12_p-13","order":6,"canonicalText":"少事長，賤事貴，共帥時。","chunks":[["少事長，賤事貴，共帥時。","zh-Hant"]]},{"id":"li-ji_ch-12_p-14_s-1","passageId":"li-ji_ch-12_p-14","order":1,"canonicalText":"男不言內，女不言外。","chunks":[["男不言內，女不言外。","zh-Hant"]]},{"id":"li-ji_ch-12_p-14_s-2","passageId":"li-ji_ch-12_p-14","order":2,"canonicalText":"非祭非喪，不相授器。","chunks":[["非祭非喪，不相授器。","zh-Hant"]]},{"id":"li-ji_ch-12_p-14_s-3","passageId":"li-ji_ch-12_p-14","order":3,"canonicalText":"其相授，則女受以篚，其無篚則皆坐奠之而後取之。","chunks":[["其相授，則女受以篚，其無篚則皆坐奠之而後取之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-14_s-4","passageId":"li-ji_ch-12_p-14","order":4,"canonicalText":"外內不共井，不共湢浴，不通寢席，不通乞假，男女不通衣裳，內言不出，外言不入。","chunks":[["外內不共井，不共湢浴，不通寢席，不通乞假，男女不通衣裳，內言不出，外言不入。","zh-Hant"]]},{"id":"li-ji_ch-12_p-15_s-1","passageId":"li-ji_ch-12_p-15","order":1,"canonicalText":"男子入內，不嘯不指，夜行以燭，無燭則止。","chunks":[["男子入內，不嘯不指，夜行以燭，無燭則止。","zh-Hant"]]},{"id":"li-ji_ch-12_p-15_s-2","passageId":"li-ji_ch-12_p-15","order":2,"canonicalText":"女子出門，必擁蔽其面，夜行以燭，無燭則止。","chunks":[["女子出門，必擁蔽其面，夜行以燭，無燭則止。","zh-Hant"]]},{"id":"li-ji_ch-12_p-15_s-3","passageId":"li-ji_ch-12_p-15","order":3,"canonicalText":"道路：男子由右，女子由左。","chunks":[["道路：男子由右，女子由左。","zh-Hant"]]},{"id":"li-ji_ch-12_p-16_s-1","passageId":"li-ji_ch-12_p-16","order":1,"canonicalText":"子婦孝者、敬者，父母舅姑之命，勿逆勿怠。","chunks":[["子婦孝者、敬者，父母舅姑之命，勿逆勿怠。","zh-Hant"]]},{"id":"li-ji_ch-12_p-16_s-2","passageId":"li-ji_ch-12_p-16","order":2,"canonicalText":"若飲食之，雖不耆，必嘗而待；","chunks":[["若飲食之，雖不耆，必嘗而待；","zh-Hant"]]},{"id":"li-ji_ch-12_p-16_s-3","passageId":"li-ji_ch-12_p-16","order":3,"canonicalText":"加之衣服，雖不欲，必服而待；","chunks":[["加之衣服，雖不欲，必服而待；","zh-Hant"]]},{"id":"li-ji_ch-12_p-16_s-4","passageId":"li-ji_ch-12_p-16","order":4,"canonicalText":"加之事，人待之，己雖弗欲，姑與之，而姑使之，而後復之。","chunks":[["加之事，人待之，己雖弗欲，姑與之，而姑使之，而後復之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-17_s-1","passageId":"li-ji_ch-12_p-17","order":1,"canonicalText":"子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之。","chunks":[["子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-17_s-2","passageId":"li-ji_ch-12_p-17","order":2,"canonicalText":"子婦未孝未敬，勿庸疾怨，姑教之；","chunks":[["子婦未孝未敬，勿庸疾怨，姑教之；","zh-Hant"]]},{"id":"li-ji_ch-12_p-17_s-3","passageId":"li-ji_ch-12_p-17","order":3,"canonicalText":"若不可教，而後怒之；","chunks":[["若不可教，而後怒之；","zh-Hant"]]},{"id":"li-ji_ch-12_p-17_s-4","passageId":"li-ji_ch-12_p-17","order":4,"canonicalText":"不可怒，子放婦出，而不表禮焉。","chunks":[["不可怒，子放婦出，而不表禮焉。","zh-Hant"]]},{"id":"li-ji_ch-12_p-18_s-1","passageId":"li-ji_ch-12_p-18","order":1,"canonicalText":"父母有過，下氣怡色，柔聲以諫。","chunks":[["父母有過，下氣怡色，柔聲以諫。","zh-Hant"]]},{"id":"li-ji_ch-12_p-18_s-2","passageId":"li-ji_ch-12_p-18","order":2,"canonicalText":"諫若不入，起敬起孝，說則復諫；","chunks":[["諫若不入，起敬起孝，說則復諫；","zh-Hant"]]},{"id":"li-ji_ch-12_p-18_s-3","passageId":"li-ji_ch-12_p-18","order":3,"canonicalText":"不說，與其得罪於鄉黨州閭，寧孰諫。","chunks":[["不說，與其得罪於鄉黨州閭，寧孰諫。","zh-Hant"]]},{"id":"li-ji_ch-12_p-18_s-4","passageId":"li-ji_ch-12_p-18","order":4,"canonicalText":"父母怒、不說，而撻之流血，不敢疾怨，起敬起孝。","chunks":[["父母怒、不說，而撻之流血，不敢疾怨，起敬起孝。","zh-Hant"]]},{"id":"li-ji_ch-12_p-19_s-1","passageId":"li-ji_ch-12_p-19","order":1,"canonicalText":"父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰。","chunks":[["父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰。","zh-Hant"]]},{"id":"li-ji_ch-12_p-20_s-1","passageId":"li-ji_ch-12_p-20","order":1,"canonicalText":"子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰。","chunks":[["子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰。","zh-Hant"]]},{"id":"li-ji_ch-12_p-20_s-2","passageId":"li-ji_ch-12_p-20","order":2,"canonicalText":"子甚宜其妻，父母不說，出；","chunks":[["子甚宜其妻，父母不說，出；","zh-Hant"]]},{"id":"li-ji_ch-12_p-20_s-3","passageId":"li-ji_ch-12_p-20","order":3,"canonicalText":"子不宜其妻，父母曰：「是善事我。","chunks":[["子不宜其妻，父母曰：「是善事我。","zh-Hant"]]},{"id":"li-ji_ch-12_p-20_s-4","passageId":"li-ji_ch-12_p-20","order":4,"canonicalText":"」子行夫婦之禮焉，沒身不衰。","chunks":[["」子行夫婦之禮焉，沒身不衰。","zh-Hant"]]},{"id":"li-ji_ch-12_p-21_s-1","passageId":"li-ji_ch-12_p-21","order":1,"canonicalText":"父母雖沒，將為善，思貽父母令名，必果；","chunks":[["父母雖沒，將為善，思貽父母令名，必果；","zh-Hant"]]},{"id":"li-ji_ch-12_p-21_s-2","passageId":"li-ji_ch-12_p-21","order":2,"canonicalText":"將為不善，思貽父母羞辱，必不果。","chunks":[["將為不善，思貽父母羞辱，必不果。","zh-Hant"]]},{"id":"li-ji_ch-12_p-22_s-1","passageId":"li-ji_ch-12_p-22","order":1,"canonicalText":"舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於冢婦。","chunks":[["舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於冢婦。","zh-Hant"]]},{"id":"li-ji_ch-12_p-22_s-2","passageId":"li-ji_ch-12_p-22","order":2,"canonicalText":"舅姑使冢婦，毋怠，不友無禮於介婦。","chunks":[["舅姑使冢婦，毋怠，不友無禮於介婦。","zh-Hant"]]},{"id":"li-ji_ch-12_p-22_s-3","passageId":"li-ji_ch-12_p-22","order":3,"canonicalText":"舅姑若使介婦，毋敢敵耦於冢婦，不敢并行，不敢并命，不敢并坐。","chunks":[["舅姑若使介婦，毋敢敵耦於冢婦，不敢并行，不敢并命，不敢并坐。","zh-Hant"]]},{"id":"li-ji_ch-12_p-23_s-1","passageId":"li-ji_ch-12_p-23","order":1,"canonicalText":"凡婦，不命適私室，不敢退。","chunks":[["凡婦，不命適私室，不敢退。","zh-Hant"]]},{"id":"li-ji_ch-12_p-23_s-2","passageId":"li-ji_ch-12_p-23","order":2,"canonicalText":"婦將有事，大小必請於舅姑。","chunks":[["婦將有事，大小必請於舅姑。","zh-Hant"]]},{"id":"li-ji_ch-12_p-23_s-3","passageId":"li-ji_ch-12_p-23","order":3,"canonicalText":"子婦無私貨，無私畜，無私器，不敢私假，不敢私與。","chunks":[["子婦無私貨，無私畜，無私器，不敢私假，不敢私與。","zh-Hant"]]},{"id":"li-ji_ch-12_p-23_s-4","passageId":"li-ji_ch-12_p-23","order":4,"canonicalText":"婦或賜之飲食、衣服、布帛、佩帨、茝蘭，則受而獻諸舅姑，舅姑受之則喜，如新受賜，若反賜之則辭，不得命，如更受賜，藏以待乏。","chunks":[["婦或賜之飲食、衣服、布帛、佩帨、茝蘭，則受而獻諸舅姑，舅姑受之則喜，如新受賜，若反賜之則辭，不得命，如更受賜，藏以待乏。","zh-Hant"]]},{"id":"li-ji_ch-12_p-23_s-5","passageId":"li-ji_ch-12_p-23","order":5,"canonicalText":"婦若有私親兄弟將與之，則必復請其故，賜而後與之。","chunks":[["婦若有私親兄弟將與之，則必復請其故，賜而後與之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-24_s-1","passageId":"li-ji_ch-12_p-24","order":1,"canonicalText":"適子庶子只事宗子宗婦。","chunks":[["適子庶子只事宗子宗婦。","zh-Hant"]]},{"id":"li-ji_ch-12_p-24_s-2","passageId":"li-ji_ch-12_p-24","order":2,"canonicalText":"雖貴富，不敢以貴富入宗子之家，雖眾車徒舍於外，以寡約入。","chunks":[["雖貴富，不敢以貴富入宗子之家，雖眾車徒舍於外，以寡約入。","zh-Hant"]]},{"id":"li-ji_ch-12_p-25_s-1","passageId":"li-ji_ch-12_p-25","order":1,"canonicalText":"子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也；","chunks":[["子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也；","zh-Hant"]]},{"id":"li-ji_ch-12_p-25_s-2","passageId":"li-ji_ch-12_p-25","order":2,"canonicalText":"若非所獻，則不敢以入於宗子之門，不敢以貴富加於父兄宗族。","chunks":[["若非所獻，則不敢以入於宗子之門，不敢以貴富加於父兄宗族。","zh-Hant"]]},{"id":"li-ji_ch-12_p-25_s-3","passageId":"li-ji_ch-12_p-25","order":3,"canonicalText":"若富，則具二牲，獻其賢者於宗子，夫婦皆齊而宗敬焉，終事而後敢私祭。","chunks":[["若富，則具二牲，獻其賢者於宗子，夫婦皆齊而宗敬焉，終事而後敢私祭。","zh-Hant"]]},{"id":"li-ji_ch-12_p-26_s-1","passageId":"li-ji_ch-12_p-26","order":1,"canonicalText":"飯：黍，稷，稻，粱，白黍，黃粱，稰，穛。","chunks":[["飯：黍，稷，稻，粱，白黍，黃粱，稰，穛。","zh-Hant"]]},{"id":"li-ji_ch-12_p-27_s-1","passageId":"li-ji_ch-12_p-27","order":1,"canonicalText":"膳：膷，臐，膮，醢，牛炙。","chunks":[["膳：膷，臐，膮，醢，牛炙。","zh-Hant"]]},{"id":"li-ji_ch-12_p-27_s-2","passageId":"li-ji_ch-12_p-27","order":2,"canonicalText":"醢，牛胾，醢，牛膾。","chunks":[["醢，牛胾，醢，牛膾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-27_s-3","passageId":"li-ji_ch-12_p-27","order":3,"canonicalText":"羊炙，羊胾，醢，豕炙。","chunks":[["羊炙，羊胾，醢，豕炙。","zh-Hant"]]},{"id":"li-ji_ch-12_p-27_s-4","passageId":"li-ji_ch-12_p-27","order":4,"canonicalText":"醢，豕胾，芥醬，魚膾。","chunks":[["醢，豕胾，芥醬，魚膾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-27_s-5","passageId":"li-ji_ch-12_p-27","order":5,"canonicalText":"雉，兔，鶉，鷃。","chunks":[["雉，兔，鶉，鷃。","zh-Hant"]]},{"id":"li-ji_ch-12_p-28_s-1","passageId":"li-ji_ch-12_p-28","order":1,"canonicalText":"飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，黍酏，漿，水，醷，濫。","chunks":[["飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，黍酏，漿，水，醷，濫。","zh-Hant"]]},{"id":"li-ji_ch-12_p-29_s-1","passageId":"li-ji_ch-12_p-29","order":1,"canonicalText":"酒：清、白。","chunks":[["酒：清、白。","zh-Hant"]]},{"id":"li-ji_ch-12_p-30_s-1","passageId":"li-ji_ch-12_p-30","order":1,"canonicalText":"羞：糗，餌，粉，酏。","chunks":[["羞：糗，餌，粉，酏。","zh-Hant"]]},{"id":"li-ji_ch-12_p-31_s-1","passageId":"li-ji_ch-12_p-31","order":1,"canonicalText":"食：蝸醢而菰食，雉羹；","chunks":[["食：蝸醢而菰食，雉羹；","zh-Hant"]]},{"id":"li-ji_ch-12_p-31_s-2","passageId":"li-ji_ch-12_p-31","order":2,"canonicalText":"麥食，脯羹，雞羹；","chunks":[["麥食，脯羹，雞羹；","zh-Hant"]]},{"id":"li-ji_ch-12_p-31_s-3","passageId":"li-ji_ch-12_p-31","order":3,"canonicalText":"析稌，犬羹，兔羹；","chunks":[["析稌，犬羹，兔羹；","zh-Hant"]]},{"id":"li-ji_ch-12_p-31_s-4","passageId":"li-ji_ch-12_p-31","order":4,"canonicalText":"和糝不蓼。","chunks":[["和糝不蓼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-32_s-1","passageId":"li-ji_ch-12_p-32","order":1,"canonicalText":"濡豚，包苦實蓼；","chunks":[["濡豚，包苦實蓼；","zh-Hant"]]},{"id":"li-ji_ch-12_p-32_s-2","passageId":"li-ji_ch-12_p-32","order":2,"canonicalText":"濡雞，醢醬實蓼；","chunks":[["濡雞，醢醬實蓼；","zh-Hant"]]},{"id":"li-ji_ch-12_p-32_s-3","passageId":"li-ji_ch-12_p-32","order":3,"canonicalText":"濡魚，卵醬實蓼；","chunks":[["濡魚，卵醬實蓼；","zh-Hant"]]},{"id":"li-ji_ch-12_p-32_s-4","passageId":"li-ji_ch-12_p-32","order":4,"canonicalText":"濡鱉，醢醬實蓼。","chunks":[["濡鱉，醢醬實蓼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-33_s-1","passageId":"li-ji_ch-12_p-33","order":1,"canonicalText":"腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥，醢，醬，桃諸，梅諸，卵鹽。","chunks":[["腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥，醢，醬，桃諸，梅諸，卵鹽。","zh-Hant"]]},{"id":"li-ji_ch-12_p-34_s-1","passageId":"li-ji_ch-12_p-34","order":1,"canonicalText":"凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時。","chunks":[["凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時。","zh-Hant"]]},{"id":"li-ji_ch-12_p-35_s-1","passageId":"li-ji_ch-12_p-35","order":1,"canonicalText":"凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘。","chunks":[["凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘。","zh-Hant"]]},{"id":"li-ji_ch-12_p-36_s-1","passageId":"li-ji_ch-12_p-36","order":1,"canonicalText":"牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰。","chunks":[["牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰。","zh-Hant"]]},{"id":"li-ji_ch-12_p-37_s-1","passageId":"li-ji_ch-12_p-37","order":1,"canonicalText":"春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜鮮羽膳膏膻。","chunks":[["春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜鮮羽膳膏膻。","zh-Hant"]]},{"id":"li-ji_ch-12_p-38_s-1","passageId":"li-ji_ch-12_p-38","order":1,"canonicalText":"牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆有軒，雉兔皆有芼。","chunks":[["牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆有軒，雉兔皆有芼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-38_s-2","passageId":"li-ji_ch-12_p-38","order":2,"canonicalText":"爵，鷃，蜩，范，芝栭，菱，椇，棗，栗，榛，柿，瓜，桃，李，梅，杏，楂，梨，姜，桂。","chunks":[["爵，鷃，蜩，范，芝栭，菱，椇，棗，栗，榛，柿，瓜，桃，李，梅，杏，楂，梨，姜，桂。","zh-Hant"]]},{"id":"li-ji_ch-12_p-39_s-1","passageId":"li-ji_ch-12_p-39","order":1,"canonicalText":"大夫燕食，有膾無脯，有脯無膾。","chunks":[["大夫燕食，有膾無脯，有脯無膾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-39_s-2","passageId":"li-ji_ch-12_p-39","order":2,"canonicalText":"士不貳羹胾，庶人耆老不徒食。","chunks":[["士不貳羹胾，庶人耆老不徒食。","zh-Hant"]]},{"id":"li-ji_ch-12_p-40_s-1","passageId":"li-ji_ch-12_p-40","order":1,"canonicalText":"膾：春用蔥，秋用芥、豚；","chunks":[["膾：春用蔥，秋用芥、豚；","zh-Hant"]]},{"id":"li-ji_ch-12_p-40_s-2","passageId":"li-ji_ch-12_p-40","order":2,"canonicalText":"春用韭，秋用蓼。","chunks":[["春用韭，秋用蓼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-40_s-3","passageId":"li-ji_ch-12_p-40","order":3,"canonicalText":"脂用蔥，膏用薤，三牲用藙，和用醯，獸用梅。","chunks":[["脂用蔥，膏用薤，三牲用藙，和用醯，獸用梅。","zh-Hant"]]},{"id":"li-ji_ch-12_p-40_s-4","passageId":"li-ji_ch-12_p-40","order":4,"canonicalText":"鶉羹、雞羹、鴽，釀之蓼。","chunks":[["鶉羹、雞羹、鴽，釀之蓼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-40_s-5","passageId":"li-ji_ch-12_p-40","order":5,"canonicalText":"魴鱮烝，雛燒，雉，薌無蓼。","chunks":[["魴鱮烝，雛燒，雉，薌無蓼。","zh-Hant"]]},{"id":"li-ji_ch-12_p-41_s-1","passageId":"li-ji_ch-12_p-41","order":1,"canonicalText":"不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，豚去腦，魚去乙，鱉去醜。","chunks":[["不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，豚去腦，魚去乙，鱉去醜。","zh-Hant"]]},{"id":"li-ji_ch-12_p-42_s-1","passageId":"li-ji_ch-12_p-42","order":1,"canonicalText":"肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤梨曰攢之。","chunks":[["肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤梨曰攢之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-43_s-1","passageId":"li-ji_ch-12_p-43","order":1,"canonicalText":"牛夜鳴則庮，羊泠毛而毳、膻，狗赤股而躁、臊，鳥麃色而沙鳴、郁，豕望視而交睫、腥，馬黑脊而般臂、漏，雛尾不盈握弗食，舒雁翠，鵠鴞胖，舒鳧翠，雞肝，雁腎，鴇奧，鹿胃。","chunks":[["牛夜鳴則庮，羊泠毛而毳、膻，狗赤股而躁、臊，鳥麃色而沙鳴、郁，豕望視而交睫、腥，馬黑脊而般臂、漏，雛尾不盈握弗食，舒雁翠，鵠鴞胖，舒鳧翠，雞肝，雁腎，鴇奧，鹿胃。","zh-Hant"]]},{"id":"li-ji_ch-12_p-44_s-1","passageId":"li-ji_ch-12_p-44","order":1,"canonicalText":"肉腥細者為膾，大者為軒；","chunks":[["肉腥細者為膾，大者為軒；","zh-Hant"]]},{"id":"li-ji_ch-12_p-44_s-2","passageId":"li-ji_ch-12_p-44","order":2,"canonicalText":"或曰麋鹿魚為菹，麇為辟雞，野豕為軒，兔為宛脾，切蔥若薤，實諸醯以柔之。","chunks":[["或曰麋鹿魚為菹，麇為辟雞，野豕為軒，兔為宛脾，切蔥若薤，實諸醯以柔之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-45_s-1","passageId":"li-ji_ch-12_p-45","order":1,"canonicalText":"羹食，自諸侯以下至於庶人無等。","chunks":[["羹食，自諸侯以下至於庶人無等。","zh-Hant"]]},{"id":"li-ji_ch-12_p-46_s-1","passageId":"li-ji_ch-12_p-46","order":1,"canonicalText":"大夫無秩膳，大夫七十而有閣，天子之閣。","chunks":[["大夫無秩膳，大夫七十而有閣，天子之閣。","zh-Hant"]]},{"id":"li-ji_ch-12_p-46_s-2","passageId":"li-ji_ch-12_p-46","order":2,"canonicalText":"左達五，右達五，公侯伯於房中五，大夫於閣三，士於坫一。","chunks":[["左達五，右達五，公侯伯於房中五，大夫於閣三，士於坫一。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-1","passageId":"li-ji_ch-12_p-47","order":1,"canonicalText":"凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。","chunks":[["凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-2","passageId":"li-ji_ch-12_p-47","order":2,"canonicalText":"凡五十養於鄉，六十養於國，七十養於學，達於諸侯。","chunks":[["凡五十養於鄉，六十養於國，七十養於學，達於諸侯。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-3","passageId":"li-ji_ch-12_p-47","order":3,"canonicalText":"八十拜君命，一坐再至，瞽亦如之，九十者使人受。","chunks":[["八十拜君命，一坐再至，瞽亦如之，九十者使人受。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-4","passageId":"li-ji_ch-12_p-47","order":4,"canonicalText":"五十異粻，六十宿肉，七十二膳，八十常珍，九十飲食不違寢，膳飲從於游可也。","chunks":[["五十異粻，六十宿肉，七十二膳，八十常珍，九十飲食不違寢，膳飲從於游可也。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-5","passageId":"li-ji_ch-12_p-47","order":5,"canonicalText":"六十歲制，七十時制，八十月制，九十日修，唯絞紟衾冒，死而後制。","chunks":[["六十歲制，七十時制，八十月制，九十日修，唯絞紟衾冒，死而後制。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-6","passageId":"li-ji_ch-12_p-47","order":6,"canonicalText":"五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖，九十雖得人不暖矣。","chunks":[["五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖，九十雖得人不暖矣。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-7","passageId":"li-ji_ch-12_p-47","order":7,"canonicalText":"五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝，九十者天子欲有問焉，則就其室以珍從。","chunks":[["五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝，九十者天子欲有問焉，則就其室以珍從。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-8","passageId":"li-ji_ch-12_p-47","order":8,"canonicalText":"七十不俟朝，八十月告存，九十日有秩。","chunks":[["七十不俟朝，八十月告存，九十日有秩。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-9","passageId":"li-ji_ch-12_p-47","order":9,"canonicalText":"五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。","chunks":[["五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-10","passageId":"li-ji_ch-12_p-47","order":10,"canonicalText":"五十而爵，六十不親學，七十致政；","chunks":[["五十而爵，六十不親學，七十致政；","zh-Hant"]]},{"id":"li-ji_ch-12_p-47_s-11","passageId":"li-ji_ch-12_p-47","order":11,"canonicalText":"凡自七十以上，唯衰麻為喪。","chunks":[["凡自七十以上，唯衰麻為喪。","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-1","passageId":"li-ji_ch-12_p-48","order":1,"canonicalText":"凡三王養老皆引年，八十者一子不從政，九十者其家不從政；","chunks":[["凡三王養老皆引年，八十者一子不從政，九十者其家不從政；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-2","passageId":"li-ji_ch-12_p-48","order":2,"canonicalText":"瞽亦如之。","chunks":[["瞽亦如之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-3","passageId":"li-ji_ch-12_p-48","order":3,"canonicalText":"凡父母在，子雖老不坐。","chunks":[["凡父母在，子雖老不坐。","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-4","passageId":"li-ji_ch-12_p-48","order":4,"canonicalText":"有虞氏養國老於上庠，養庶老於下庠；","chunks":[["有虞氏養國老於上庠，養庶老於下庠；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-5","passageId":"li-ji_ch-12_p-48","order":5,"canonicalText":"夏后氏養國老於東序，養庶老於西序；","chunks":[["夏后氏養國老於東序，養庶老於西序；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-6","passageId":"li-ji_ch-12_p-48","order":6,"canonicalText":"殷人養國老於右學，養庶老於左學；","chunks":[["殷人養國老於右學，養庶老於左學；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-7","passageId":"li-ji_ch-12_p-48","order":7,"canonicalText":"周人養國老於東膠，養庶老於虞庠，虞庠在國之西郊。","chunks":[["周人養國老於東膠，養庶老於虞庠，虞庠在國之西郊。","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-8","passageId":"li-ji_ch-12_p-48","order":8,"canonicalText":"有虞氏皇而祭，深衣而養老；","chunks":[["有虞氏皇而祭，深衣而養老；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-9","passageId":"li-ji_ch-12_p-48","order":9,"canonicalText":"夏后氏收而祭，燕衣而養老；","chunks":[["夏后氏收而祭，燕衣而養老；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-10","passageId":"li-ji_ch-12_p-48","order":10,"canonicalText":"殷人冔而祭，縞衣而養老；","chunks":[["殷人冔而祭，縞衣而養老；","zh-Hant"]]},{"id":"li-ji_ch-12_p-48_s-11","passageId":"li-ji_ch-12_p-48","order":11,"canonicalText":"周人冕而祭，玄衣而養老。","chunks":[["周人冕而祭，玄衣而養老。","zh-Hant"]]},{"id":"li-ji_ch-12_p-49_s-1","passageId":"li-ji_ch-12_p-49","order":1,"canonicalText":"曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安其寢處，以其飲食忠養之孝子之身終，終身也者，非終父母之身，終其身也；","chunks":[["曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安其寢處，以其飲食忠養之孝子之身終，終身也者，非終父母之身，終其身也；","zh-Hant"]]},{"id":"li-ji_ch-12_p-49_s-2","passageId":"li-ji_ch-12_p-49","order":2,"canonicalText":"是故父母之所愛亦愛之，父母之所敬亦敬之，至於犬馬盡然，而況於人乎！","chunks":[["是故父母之所愛亦愛之，父母之所敬亦敬之，至於犬馬盡然，而況於人乎！","zh-Hant"]]},{"id":"li-ji_ch-12_p-49_s-3","passageId":"li-ji_ch-12_p-49","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-12_p-50_s-1","passageId":"li-ji_ch-12_p-50","order":1,"canonicalText":"凡養老，五帝憲，三王有乞言。","chunks":[["凡養老，五帝憲，三王有乞言。","zh-Hant"]]},{"id":"li-ji_ch-12_p-50_s-2","passageId":"li-ji_ch-12_p-50","order":2,"canonicalText":"五帝憲，養氣體而不乞言，有善則記之為惇史。","chunks":[["五帝憲，養氣體而不乞言，有善則記之為惇史。","zh-Hant"]]},{"id":"li-ji_ch-12_p-50_s-3","passageId":"li-ji_ch-12_p-50","order":3,"canonicalText":"三王亦憲，既養老而後乞言，亦微其禮，皆有惇史。","chunks":[["三王亦憲，既養老而後乞言，亦微其禮，皆有惇史。","zh-Hant"]]},{"id":"li-ji_ch-12_p-51_s-1","passageId":"li-ji_ch-12_p-51","order":1,"canonicalText":"淳熬：煎醢，加于陸稻上，沃之以膏曰淳熬。","chunks":[["淳熬：煎醢，加于陸稻上，沃之以膏曰淳熬。","zh-Hant"]]},{"id":"li-ji_ch-12_p-51_s-2","passageId":"li-ji_ch-12_p-51","order":2,"canonicalText":"淳毋煎醢，加于黍食上，沃之以膏曰淳毋。","chunks":[["淳毋煎醢，加于黍食上，沃之以膏曰淳毋。","zh-Hant"]]},{"id":"li-ji_ch-12_p-52_s-1","passageId":"li-ji_ch-12_p-52","order":1,"canonicalText":"炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，涂之以謹涂，炮之，涂皆乾，擘之，濯手以摩之，去其皽，為稻粉糔溲之以為酏，以付豚煎諸膏，膏必滅之，鉅鑊湯以小鼎薌脯於其中，使其湯毋滅鼎，三日三夜毋絕火，而後調之以醯醢。","chunks":[["炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，涂之以謹涂，炮之，涂皆乾，擘之，濯手以摩之，去其皽，為稻粉糔溲之以為酏，以付豚煎諸膏，膏必滅之，鉅鑊湯以小鼎薌脯於其中，使其湯毋滅鼎，三日三夜毋絕火，而後調之以醯醢。","zh-Hant"]]},{"id":"li-ji_ch-12_p-53_s-1","passageId":"li-ji_ch-12_p-53","order":1,"canonicalText":"搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，去其餌，熟出之，去其餌，柔其肉。","chunks":[["搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，去其餌，熟出之，去其餌，柔其肉。","zh-Hant"]]},{"id":"li-ji_ch-12_p-54_s-1","passageId":"li-ji_ch-12_p-54","order":1,"canonicalText":"漬：取牛肉必新殺者，薄切之，必絕其理；","chunks":[["漬：取牛肉必新殺者，薄切之，必絕其理；","zh-Hant"]]},{"id":"li-ji_ch-12_p-54_s-2","passageId":"li-ji_ch-12_p-54","order":2,"canonicalText":"湛諸美酒，期朝而食之以醢若醯醷。","chunks":[["湛諸美酒，期朝而食之以醢若醯醷。","zh-Hant"]]},{"id":"li-ji_ch-12_p-55_s-1","passageId":"li-ji_ch-12_p-55","order":1,"canonicalText":"為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而鹽之，乾而食之。","chunks":[["為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而鹽之，乾而食之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-55_s-2","passageId":"li-ji_ch-12_p-55","order":2,"canonicalText":"施羊亦如之，施麋、施鹿、施麇皆如牛羊。","chunks":[["施羊亦如之，施麋、施鹿、施麇皆如牛羊。","zh-Hant"]]},{"id":"li-ji_ch-12_p-55_s-3","passageId":"li-ji_ch-12_p-55","order":3,"canonicalText":"欲濡肉則釋而煎之以醢，欲乾肉則捶而食之。","chunks":[["欲濡肉則釋而煎之以醢，欲乾肉則捶而食之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-56_s-1","passageId":"li-ji_ch-12_p-56","order":1,"canonicalText":"糝：取牛羊豕之肉，三如一小切之，與稻米；","chunks":[["糝：取牛羊豕之肉，三如一小切之，與稻米；","zh-Hant"]]},{"id":"li-ji_ch-12_p-56_s-2","passageId":"li-ji_ch-12_p-56","order":2,"canonicalText":"稻米二肉一，合以為餌煎之。","chunks":[["稻米二肉一，合以為餌煎之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-57_s-1","passageId":"li-ji_ch-12_p-57","order":1,"canonicalText":"肝菺：取狈肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼；","chunks":[["肝菺：取狈肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼；","zh-Hant"]]},{"id":"li-ji_ch-12_p-57_s-2","passageId":"li-ji_ch-12_p-57","order":2,"canonicalText":"取稻米舉糔溲之，小切狼臅膏，以與稻米為酏。","chunks":[["取稻米舉糔溲之，小切狼臅膏，以與稻米為酏。","zh-Hant"]]},{"id":"li-ji_ch-12_p-58_s-1","passageId":"li-ji_ch-12_p-58","order":1,"canonicalText":"禮，始於謹夫婦，為宮室，辨外內。","chunks":[["禮，始於謹夫婦，為宮室，辨外內。","zh-Hant"]]},{"id":"li-ji_ch-12_p-58_s-2","passageId":"li-ji_ch-12_p-58","order":2,"canonicalText":"男子居外，女子居內，深宮固門，閽寺守之。","chunks":[["男子居外，女子居內，深宮固門，閽寺守之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-58_s-3","passageId":"li-ji_ch-12_p-58","order":3,"canonicalText":"男不入，女不出。","chunks":[["男不入，女不出。","zh-Hant"]]},{"id":"li-ji_ch-12_p-59_s-1","passageId":"li-ji_ch-12_p-59","order":1,"canonicalText":"男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不敢共湢浴。","chunks":[["男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不敢共湢浴。","zh-Hant"]]},{"id":"li-ji_ch-12_p-59_s-2","passageId":"li-ji_ch-12_p-59","order":2,"canonicalText":"夫不在，斂枕篋簟席、襡器而藏之。","chunks":[["夫不在，斂枕篋簟席、襡器而藏之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-59_s-3","passageId":"li-ji_ch-12_p-59","order":3,"canonicalText":"少事長，賤事貴，咸如之。","chunks":[["少事長，賤事貴，咸如之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-60_s-1","passageId":"li-ji_ch-12_p-60","order":1,"canonicalText":"夫婦之禮，唯及七十，同藏無間。","chunks":[["夫婦之禮，唯及七十，同藏無間。","zh-Hant"]]},{"id":"li-ji_ch-12_p-60_s-2","passageId":"li-ji_ch-12_p-60","order":2,"canonicalText":"故妾雖老，年未滿五十，必與五日之御。","chunks":[["故妾雖老，年未滿五十，必與五日之御。","zh-Hant"]]},{"id":"li-ji_ch-12_p-60_s-3","passageId":"li-ji_ch-12_p-60","order":3,"canonicalText":"將御者，齊，漱浣，慎衣服，櫛縰笄，總角，拂髦，衿纓綦屨。","chunks":[["將御者，齊，漱浣，慎衣服，櫛縰笄，總角，拂髦，衿纓綦屨。","zh-Hant"]]},{"id":"li-ji_ch-12_p-60_s-4","passageId":"li-ji_ch-12_p-60","order":4,"canonicalText":"雖婢妾，衣服飲食必後長者。","chunks":[["雖婢妾，衣服飲食必後長者。","zh-Hant"]]},{"id":"li-ji_ch-12_p-60_s-5","passageId":"li-ji_ch-12_p-60","order":5,"canonicalText":"妻不在，妾御莫敢當夕。","chunks":[["妻不在，妾御莫敢當夕。","zh-Hant"]]},{"id":"li-ji_ch-12_p-61_s-1","passageId":"li-ji_ch-12_p-61","order":1,"canonicalText":"妻將生子，及月辰，居側室，夫使人日再問之，作而自問之，妻不敢見，使姆衣服而對，至於子生，夫復使人日再問之，夫齊則不入側室之門。","chunks":[["妻將生子，及月辰，居側室，夫使人日再問之，作而自問之，妻不敢見，使姆衣服而對，至於子生，夫復使人日再問之，夫齊則不入側室之門。","zh-Hant"]]},{"id":"li-ji_ch-12_p-61_s-2","passageId":"li-ji_ch-12_p-61","order":2,"canonicalText":"子生，男子設弧於門左，女子設帨於門右。","chunks":[["子生，男子設弧於門左，女子設帨於門右。","zh-Hant"]]},{"id":"li-ji_ch-12_p-61_s-3","passageId":"li-ji_ch-12_p-61","order":3,"canonicalText":"三日，始負子，男射女否。","chunks":[["三日，始負子，男射女否。","zh-Hant"]]},{"id":"li-ji_ch-12_p-62_s-1","passageId":"li-ji_ch-12_p-62","order":1,"canonicalText":"國君世子生，告於君，接以大牢，宰掌具。","chunks":[["國君世子生，告於君，接以大牢，宰掌具。","zh-Hant"]]},{"id":"li-ji_ch-12_p-62_s-2","passageId":"li-ji_ch-12_p-62","order":2,"canonicalText":"三日，卜士負之，吉者宿齊朝服寢門外，詩負之，射人以桑弧蓬矢六。","chunks":[["三日，卜士負之，吉者宿齊朝服寢門外，詩負之，射人以桑弧蓬矢六。","zh-Hant"]]},{"id":"li-ji_ch-12_p-62_s-3","passageId":"li-ji_ch-12_p-62","order":3,"canonicalText":"射天地四方，保受乃負之，宰醴負子，賜之束帛，卜士之妻、大夫之妾，使食子。","chunks":[["射天地四方，保受乃負之，宰醴負子，賜之束帛，卜士之妻、大夫之妾，使食子。","zh-Hant"]]},{"id":"li-ji_ch-12_p-63_s-1","passageId":"li-ji_ch-12_p-63","order":1,"canonicalText":"凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢，國君世子大牢，其非冢子，則皆降一等。","chunks":[["凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢，國君世子大牢，其非冢子，則皆降一等。","zh-Hant"]]},{"id":"li-ji_ch-12_p-64_s-1","passageId":"li-ji_ch-12_p-64","order":1,"canonicalText":"異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫良恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母，皆居子室，他人無事不往。","chunks":[["異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫良恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母，皆居子室，他人無事不往。","zh-Hant"]]},{"id":"li-ji_ch-12_p-65_s-1","passageId":"li-ji_ch-12_p-65","order":1,"canonicalText":"三月之末，擇日剪發為鬌，男角女羈，否則男左女右。","chunks":[["三月之末，擇日剪發為鬌，男角女羈，否則男左女右。","zh-Hant"]]},{"id":"li-ji_ch-12_p-65_s-2","passageId":"li-ji_ch-12_p-65","order":2,"canonicalText":"是日也，妻以子見於父，貴人則為衣服，由命士以下，皆漱浣，男女夙興，沐浴衣服，具視朔食，夫入門，升自阼階。","chunks":[["是日也，妻以子見於父，貴人則為衣服，由命士以下，皆漱浣，男女夙興，沐浴衣服，具視朔食，夫入門，升自阼階。","zh-Hant"]]},{"id":"li-ji_ch-12_p-65_s-3","passageId":"li-ji_ch-12_p-65","order":3,"canonicalText":"立於阼西鄉，妻抱子出自房，當楣立東面。","chunks":[["立於阼西鄉，妻抱子出自房，當楣立東面。","zh-Hant"]]},{"id":"li-ji_ch-12_p-66_s-1","passageId":"li-ji_ch-12_p-66","order":1,"canonicalText":"姆先，相曰：「母某敢用時日只見孺子。","chunks":[["姆先，相曰：「母某敢用時日只見孺子。","zh-Hant"]]},{"id":"li-ji_ch-12_p-66_s-2","passageId":"li-ji_ch-12_p-66","order":2,"canonicalText":"」夫對曰：「欽有帥。","chunks":[["」夫對曰：「欽有帥。","zh-Hant"]]},{"id":"li-ji_ch-12_p-66_s-3","passageId":"li-ji_ch-12_p-66","order":3,"canonicalText":"」父執子之右手，咳而名之。","chunks":[["」父執子之右手，咳而名之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-66_s-4","passageId":"li-ji_ch-12_p-66","order":4,"canonicalText":"妻對曰：「記有成。","chunks":[["妻對曰：「記有成。","zh-Hant"]]},{"id":"li-ji_ch-12_p-66_s-5","passageId":"li-ji_ch-12_p-66","order":5,"canonicalText":"」遂左還，授師，子師辯告諸婦諸母名，妻遂適寢。","chunks":[["」遂左還，授師，子師辯告諸婦諸母名，妻遂適寢。","zh-Hant"]]},{"id":"li-ji_ch-12_p-67_s-1","passageId":"li-ji_ch-12_p-67","order":1,"canonicalText":"夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生。","chunks":[["夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生。","zh-Hant"]]},{"id":"li-ji_ch-12_p-67_s-2","passageId":"li-ji_ch-12_p-67","order":2,"canonicalText":"」而藏之，宰告閭史，閭史書為二，其一藏諸閭府，其一獻諸州史；","chunks":[["」而藏之，宰告閭史，閭史書為二，其一藏諸閭府，其一獻諸州史；","zh-Hant"]]},{"id":"li-ji_ch-12_p-67_s-3","passageId":"li-ji_ch-12_p-67","order":3,"canonicalText":"州史獻諸州伯，州伯命藏諸州府。","chunks":[["州史獻諸州伯，州伯命藏諸州府。","zh-Hant"]]},{"id":"li-ji_ch-12_p-67_s-4","passageId":"li-ji_ch-12_p-67","order":4,"canonicalText":"夫入食如養禮。","chunks":[["夫入食如養禮。","zh-Hant"]]},{"id":"li-ji_ch-12_p-68_s-1","passageId":"li-ji_ch-12_p-68","order":1,"canonicalText":"世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世婦抱子升自西階，君名之，乃降。","chunks":[["世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世婦抱子升自西階，君名之，乃降。","zh-Hant"]]},{"id":"li-ji_ch-12_p-69_s-1","passageId":"li-ji_ch-12_p-69","order":1,"canonicalText":"適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭。","chunks":[["適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭。","zh-Hant"]]},{"id":"li-ji_ch-12_p-70_s-1","passageId":"li-ji_ch-12_p-70","order":1,"canonicalText":"凡名子，不以日月，不以國，不以隱疾；","chunks":[["凡名子，不以日月，不以國，不以隱疾；","zh-Hant"]]},{"id":"li-ji_ch-12_p-70_s-2","passageId":"li-ji_ch-12_p-70","order":2,"canonicalText":"大夫、士之子，不敢與世子同名。","chunks":[["大夫、士之子，不敢與世子同名。","zh-Hant"]]},{"id":"li-ji_ch-12_p-71_s-1","passageId":"li-ji_ch-12_p-71","order":1,"canonicalText":"妾將生子，及月辰，夫使人日一問之。","chunks":[["妾將生子，及月辰，夫使人日一問之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-71_s-2","passageId":"li-ji_ch-12_p-71","order":2,"canonicalText":"子生三月之末，漱浣夙齊，見於內寢，禮之如始入室；","chunks":[["子生三月之末，漱浣夙齊，見於內寢，禮之如始入室；","zh-Hant"]]},{"id":"li-ji_ch-12_p-71_s-3","passageId":"li-ji_ch-12_p-71","order":3,"canonicalText":"君已食，徹焉，使之特餕，遂入御。","chunks":[["君已食，徹焉，使之特餕，遂入御。","zh-Hant"]]},{"id":"li-ji_ch-12_p-72_s-1","passageId":"li-ji_ch-12_p-72","order":1,"canonicalText":"公庶子生，就側室。","chunks":[["公庶子生，就側室。","zh-Hant"]]},{"id":"li-ji_ch-12_p-72_s-2","passageId":"li-ji_ch-12_p-72","order":2,"canonicalText":"三月之末，其母沐浴朝服見於君，擯者以其子見，君所有賜，君名之。","chunks":[["三月之末，其母沐浴朝服見於君，擯者以其子見，君所有賜，君名之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-72_s-3","passageId":"li-ji_ch-12_p-72","order":3,"canonicalText":"眾子，則使有司名之。","chunks":[["眾子，則使有司名之。","zh-Hant"]]},{"id":"li-ji_ch-12_p-73_s-1","passageId":"li-ji_ch-12_p-73","order":1,"canonicalText":"庶人無側室者，及月辰，夫出居群室，其問之也，與子見父之禮，無以異也。","chunks":[["庶人無側室者，及月辰，夫出居群室，其問之也，與子見父之禮，無以異也。","zh-Hant"]]},{"id":"li-ji_ch-12_p-74_s-1","passageId":"li-ji_ch-12_p-74","order":1,"canonicalText":"凡父在，孫見於祖，祖亦名之，禮如子見父，無辭。","chunks":[["凡父在，孫見於祖，祖亦名之，禮如子見父，無辭。","zh-Hant"]]},{"id":"li-ji_ch-12_p-75_s-1","passageId":"li-ji_ch-12_p-75","order":1,"canonicalText":"食子者，三年而出，見於公宮則劬。","chunks":[["食子者，三年而出，見於公宮則劬。","zh-Hant"]]},{"id":"li-ji_ch-12_p-75_s-2","passageId":"li-ji_ch-12_p-75","order":2,"canonicalText":"大夫之子有食母，士之妻自養其子。","chunks":[["大夫之子有食母，士之妻自養其子。","zh-Hant"]]},{"id":"li-ji_ch-12_p-76_s-1","passageId":"li-ji_ch-12_p-76","order":1,"canonicalText":"由命士以上及大夫之子，旬而見。","chunks":[["由命士以上及大夫之子，旬而見。","zh-Hant"]]},{"id":"li-ji_ch-12_p-76_s-2","passageId":"li-ji_ch-12_p-76","order":2,"canonicalText":"冢子未食而見，必執其右手，適子庶子已食而見，必循其首。","chunks":[["冢子未食而見，必執其右手，適子庶子已食而見，必循其首。","zh-Hant"]]},{"id":"li-ji_ch-12_p-77_s-1","passageId":"li-ji_ch-12_p-77","order":1,"canonicalText":"子能食食，教以右手。","chunks":[["子能食食，教以右手。","zh-Hant"]]},{"id":"li-ji_ch-12_p-77_s-2","passageId":"li-ji_ch-12_p-77","order":2,"canonicalText":"能言，男唯女俞。","chunks":[["能言，男唯女俞。","zh-Hant"]]},{"id":"li-ji_ch-12_p-77_s-3","passageId":"li-ji_ch-12_p-77","order":3,"canonicalText":"男鞶革，女鞶絲。","chunks":[["男鞶革，女鞶絲。","zh-Hant"]]},{"id":"li-ji_ch-12_p-78_s-1","passageId":"li-ji_ch-12_p-78","order":1,"canonicalText":"六年教之數與方名。","chunks":[["六年教之數與方名。","zh-Hant"]]},{"id":"li-ji_ch-12_p-78_s-2","passageId":"li-ji_ch-12_p-78","order":2,"canonicalText":"七年男女不同席，不共食。","chunks":[["七年男女不同席，不共食。","zh-Hant"]]},{"id":"li-ji_ch-12_p-78_s-3","passageId":"li-ji_ch-12_p-78","order":3,"canonicalText":"八年出入門戶及即席飲食，必後長者，始教之讓。","chunks":[["八年出入門戶及即席飲食，必後長者，始教之讓。","zh-Hant"]]},{"id":"li-ji_ch-12_p-78_s-4","passageId":"li-ji_ch-12_p-78","order":4,"canonicalText":"九年教之數日。","chunks":[["九年教之數日。","zh-Hant"]]},{"id":"li-ji_ch-12_p-79_s-1","passageId":"li-ji_ch-12_p-79","order":1,"canonicalText":"十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，朝夕學幼儀，請肄簡諒。","chunks":[["十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，朝夕學幼儀，請肄簡諒。","zh-Hant"]]},{"id":"li-ji_ch-12_p-80_s-1","passageId":"li-ji_ch-12_p-80","order":1,"canonicalText":"十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射御。","chunks":[["十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射御。","zh-Hant"]]},{"id":"li-ji_ch-12_p-80_s-2","passageId":"li-ji_ch-12_p-80","order":2,"canonicalText":"二十而冠，始學禮，可以衣裘帛，舞《大夏》，惇行孝弟，博學不教，內而不出。","chunks":[["二十而冠，始學禮，可以衣裘帛，舞《大夏》，惇行孝弟，博學不教，內而不出。","zh-Hant"]]},{"id":"li-ji_ch-12_p-81_s-1","passageId":"li-ji_ch-12_p-81","order":1,"canonicalText":"三十而有室，始理男事，博學無方，孫友視志。","chunks":[["三十而有室，始理男事，博學無方，孫友視志。","zh-Hant"]]},{"id":"li-ji_ch-12_p-81_s-2","passageId":"li-ji_ch-12_p-81","order":2,"canonicalText":"四十始仕，方物出謀發慮，道合則服從，不可則去。","chunks":[["四十始仕，方物出謀發慮，道合則服從，不可則去。","zh-Hant"]]},{"id":"li-ji_ch-12_p-81_s-3","passageId":"li-ji_ch-12_p-81","order":3,"canonicalText":"五十命為大夫，服官政。","chunks":[["五十命為大夫，服官政。","zh-Hant"]]},{"id":"li-ji_ch-12_p-81_s-4","passageId":"li-ji_ch-12_p-81","order":4,"canonicalText":"七十致事。","chunks":[["七十致事。","zh-Hant"]]},{"id":"li-ji_ch-12_p-81_s-5","passageId":"li-ji_ch-12_p-81","order":5,"canonicalText":"凡男拜，尚左手。","chunks":[["凡男拜，尚左手。","zh-Hant"]]},{"id":"li-ji_ch-12_p-82_s-1","passageId":"li-ji_ch-12_p-82","order":1,"canonicalText":"女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃，學女事以共衣服，觀於祭祀，納酒漿、籩豆、菹醢，禮相助奠。","chunks":[["女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃，學女事以共衣服，觀於祭祀，納酒漿、籩豆、菹醢，禮相助奠。","zh-Hant"]]},{"id":"li-ji_ch-12_p-83_s-1","passageId":"li-ji_ch-12_p-83","order":1,"canonicalText":"十有五年而笄，二十而嫁；","chunks":[["十有五年而笄，二十而嫁；","zh-Hant"]]},{"id":"li-ji_ch-12_p-83_s-2","passageId":"li-ji_ch-12_p-83","order":2,"canonicalText":"有故，二十三年而嫁。","chunks":[["有故，二十三年而嫁。","zh-Hant"]]},{"id":"li-ji_ch-12_p-83_s-3","passageId":"li-ji_ch-12_p-83","order":3,"canonicalText":"聘則為妻，奔則為妾。","chunks":[["聘則為妻，奔則為妾。","zh-Hant"]]},{"id":"li-ji_ch-12_p-83_s-4","passageId":"li-ji_ch-12_p-83","order":4,"canonicalText":"凡女拜尚右手。","chunks":[["凡女拜尚右手。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-1","passageId":"li-ji_ch-13_p-1","order":1,"canonicalText":"天子玉藻，十有二旒，前後邃延，龍卷以祭。","chunks":[["天子玉藻，十有二旒，前後邃延，龍卷以祭。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-2","passageId":"li-ji_ch-13_p-1","order":2,"canonicalText":"玄端而朝日於東門之外，聽朔於南門之外，閏月則闔門左扉，立於其中。","chunks":[["玄端而朝日於東門之外，聽朔於南門之外，閏月則闔門左扉，立於其中。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-3","passageId":"li-ji_ch-13_p-1","order":3,"canonicalText":"皮弁以日視朝，遂以食，日中而餕，奏而食。","chunks":[["皮弁以日視朝，遂以食，日中而餕，奏而食。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-4","passageId":"li-ji_ch-13_p-1","order":4,"canonicalText":"日少牢，朔月大牢；","chunks":[["日少牢，朔月大牢；","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-5","passageId":"li-ji_ch-13_p-1","order":5,"canonicalText":"五飲：上水、漿、酒、醴、酏。","chunks":[["五飲：上水、漿、酒、醴、酏。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-6","passageId":"li-ji_ch-13_p-1","order":6,"canonicalText":"卒食，玄端而居。","chunks":[["卒食，玄端而居。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-7","passageId":"li-ji_ch-13_p-1","order":7,"canonicalText":"動則左史書之，言則右史書之，御瞽几聲之上下。","chunks":[["動則左史書之，言則右史書之，御瞽几聲之上下。","zh-Hant"]]},{"id":"li-ji_ch-13_p-1_s-8","passageId":"li-ji_ch-13_p-1","order":8,"canonicalText":"年不順成，則天子素服，乘素車，食無樂。","chunks":[["年不順成，則天子素服，乘素車，食無樂。","zh-Hant"]]},{"id":"li-ji_ch-13_p-2_s-1","passageId":"li-ji_ch-13_p-2","order":1,"canonicalText":"諸侯玄端以祭，裨冕以朝，皮弁以聽朔於大廟，朝服以日視朝於內朝。","chunks":[["諸侯玄端以祭，裨冕以朝，皮弁以聽朔於大廟，朝服以日視朝於內朝。","zh-Hant"]]},{"id":"li-ji_ch-13_p-2_s-2","passageId":"li-ji_ch-13_p-2","order":2,"canonicalText":"朝，辨色始入。","chunks":[["朝，辨色始入。","zh-Hant"]]},{"id":"li-ji_ch-13_p-2_s-3","passageId":"li-ji_ch-13_p-2","order":3,"canonicalText":"君日出而視之，退適路寢，聽政，使人視大夫，大夫退，然後適小寢寢，釋服。","chunks":[["君日出而視之，退適路寢，聽政，使人視大夫，大夫退，然後適小寢寢，釋服。","zh-Hant"]]},{"id":"li-ji_ch-13_p-2_s-4","passageId":"li-ji_ch-13_p-2","order":4,"canonicalText":"又朝服以食，特牲三俎祭肺，夕深衣，祭牢肉，朔月少牢，五俎四簋，子卯稷食菜羹，夫人與君同庖。","chunks":[["又朝服以食，特牲三俎祭肺，夕深衣，祭牢肉，朔月少牢，五俎四簋，子卯稷食菜羹，夫人與君同庖。","zh-Hant"]]},{"id":"li-ji_ch-13_p-3_s-1","passageId":"li-ji_ch-13_p-3","order":1,"canonicalText":"君無故不殺牛，大夫無故不殺羊，士無故不殺犬、豕。","chunks":[["君無故不殺牛，大夫無故不殺羊，士無故不殺犬、豕。","zh-Hant"]]},{"id":"li-ji_ch-13_p-3_s-2","passageId":"li-ji_ch-13_p-3","order":2,"canonicalText":"君子遠庖廚，凡有血氣之類，弗身踐也。","chunks":[["君子遠庖廚，凡有血氣之類，弗身踐也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-4_s-1","passageId":"li-ji_ch-13_p-4","order":1,"canonicalText":"至於八月不雨，君不舉。","chunks":[["至於八月不雨，君不舉。","zh-Hant"]]},{"id":"li-ji_ch-13_p-4_s-2","passageId":"li-ji_ch-13_p-4","order":2,"canonicalText":"年不順成，君衣布搢本，關梁不租，山澤列而不賦，土功不興，大夫不得造車馬。","chunks":[["年不順成，君衣布搢本，關梁不租，山澤列而不賦，土功不興，大夫不得造車馬。","zh-Hant"]]},{"id":"li-ji_ch-13_p-5_s-1","passageId":"li-ji_ch-13_p-5","order":1,"canonicalText":"卜人定龜，史定墨，君定體。","chunks":[["卜人定龜，史定墨，君定體。","zh-Hant"]]},{"id":"li-ji_ch-13_p-6_s-1","passageId":"li-ji_ch-13_p-6","order":1,"canonicalText":"君羔幦虎犆；","chunks":[["君羔幦虎犆；","zh-Hant"]]},{"id":"li-ji_ch-13_p-6_s-2","passageId":"li-ji_ch-13_p-6","order":2,"canonicalText":"大夫齊車，鹿幦豹犆，朝車；","chunks":[["大夫齊車，鹿幦豹犆，朝車；","zh-Hant"]]},{"id":"li-ji_ch-13_p-6_s-3","passageId":"li-ji_ch-13_p-6","order":3,"canonicalText":"士齊車，鹿幦豹犆。","chunks":[["士齊車，鹿幦豹犆。","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-1","passageId":"li-ji_ch-13_p-7","order":1,"canonicalText":"君子之居恒當戶，寢恒東首。","chunks":[["君子之居恒當戶，寢恒東首。","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-2","passageId":"li-ji_ch-13_p-7","order":2,"canonicalText":"若有疾風迅雷甚雨，則必變，雖夜必興，衣服冠而坐。","chunks":[["若有疾風迅雷甚雨，則必變，雖夜必興，衣服冠而坐。","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-3","passageId":"li-ji_ch-13_p-7","order":3,"canonicalText":"日五盥，沐稷而靧粱，櫛用樿櫛，發曦用象櫛，進禨進羞，工乃升歌。","chunks":[["日五盥，沐稷而靧粱，櫛用樿櫛，發曦用象櫛，進禨進羞，工乃升歌。","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-4","passageId":"li-ji_ch-13_p-7","order":4,"canonicalText":"浴用二巾，上絺下綌，出杅，履蒯席，連用湯，履蒲席，衣布曦身，乃屨進飲。","chunks":[["浴用二巾，上絺下綌，出杅，履蒯席，連用湯，履蒲席，衣布曦身，乃屨進飲。","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-5","passageId":"li-ji_ch-13_p-7","order":5,"canonicalText":"將適公所，宿齊戒，居外寢，沐浴，史進象笏，書思對命；","chunks":[["將適公所，宿齊戒，居外寢，沐浴，史進象笏，書思對命；","zh-Hant"]]},{"id":"li-ji_ch-13_p-7_s-6","passageId":"li-ji_ch-13_p-7","order":6,"canonicalText":"既服，習容觀玉聲，乃出，揖私朝，輝如也，登車則有光矣。","chunks":[["既服，習容觀玉聲，乃出，揖私朝，輝如也，登車則有光矣。","zh-Hant"]]},{"id":"li-ji_ch-13_p-8_s-1","passageId":"li-ji_ch-13_p-8","order":1,"canonicalText":"天子搢挺，方正於天下也，諸侯荼，前詘後直，讓於天子也，大夫前詘後詘，無所不讓也。","chunks":[["天子搢挺，方正於天下也，諸侯荼，前詘後直，讓於天子也，大夫前詘後詘，無所不讓也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-9_s-1","passageId":"li-ji_ch-13_p-9","order":1,"canonicalText":"侍坐，則必退席；","chunks":[["侍坐，則必退席；","zh-Hant"]]},{"id":"li-ji_ch-13_p-9_s-2","passageId":"li-ji_ch-13_p-9","order":2,"canonicalText":"不退，則必引而去君之黨。","chunks":[["不退，則必引而去君之黨。","zh-Hant"]]},{"id":"li-ji_ch-13_p-9_s-3","passageId":"li-ji_ch-13_p-9","order":3,"canonicalText":"登席不由前，為躐席。","chunks":[["登席不由前，為躐席。","zh-Hant"]]},{"id":"li-ji_ch-13_p-9_s-4","passageId":"li-ji_ch-13_p-9","order":4,"canonicalText":"徒坐不盡席尺，讀書，食，則齊，豆去席尺。","chunks":[["徒坐不盡席尺，讀書，食，則齊，豆去席尺。","zh-Hant"]]},{"id":"li-ji_ch-13_p-10_s-1","passageId":"li-ji_ch-13_p-10","order":1,"canonicalText":"若賜之食而君客之，則命之祭，然後祭；","chunks":[["若賜之食而君客之，則命之祭，然後祭；","zh-Hant"]]},{"id":"li-ji_ch-13_p-10_s-2","passageId":"li-ji_ch-13_p-10","order":2,"canonicalText":"先飯辯嘗羞，飲而俟。","chunks":[["先飯辯嘗羞，飲而俟。","zh-Hant"]]},{"id":"li-ji_ch-13_p-10_s-3","passageId":"li-ji_ch-13_p-10","order":3,"canonicalText":"若有嘗羞者，則俟君之食，然後食，飯，飲而俟。","chunks":[["若有嘗羞者，則俟君之食，然後食，飯，飲而俟。","zh-Hant"]]},{"id":"li-ji_ch-13_p-11_s-1","passageId":"li-ji_ch-13_p-11","order":1,"canonicalText":"君命之羞，羞近者，命之品嘗之，然後唯所欲。","chunks":[["君命之羞，羞近者，命之品嘗之，然後唯所欲。","zh-Hant"]]},{"id":"li-ji_ch-13_p-11_s-2","passageId":"li-ji_ch-13_p-11","order":2,"canonicalText":"凡嘗遠食，必順近食。","chunks":[["凡嘗遠食，必順近食。","zh-Hant"]]},{"id":"li-ji_ch-13_p-11_s-3","passageId":"li-ji_ch-13_p-11","order":3,"canonicalText":"君未覆手，不敢飧；","chunks":[["君未覆手，不敢飧；","zh-Hant"]]},{"id":"li-ji_ch-13_p-11_s-4","passageId":"li-ji_ch-13_p-11","order":4,"canonicalText":"君既食，又飯飧，飯飧者，三飯也。","chunks":[["君既食，又飯飧，飯飧者，三飯也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-11_s-5","passageId":"li-ji_ch-13_p-11","order":5,"canonicalText":"君既徹，執飯與醬，乃出，授從者。","chunks":[["君既徹，執飯與醬，乃出，授從者。","zh-Hant"]]},{"id":"li-ji_ch-13_p-12_s-1","passageId":"li-ji_ch-13_p-12","order":1,"canonicalText":"凡侑食，不盡食；","chunks":[["凡侑食，不盡食；","zh-Hant"]]},{"id":"li-ji_ch-13_p-12_s-2","passageId":"li-ji_ch-13_p-12","order":2,"canonicalText":"食於人不飽。","chunks":[["食於人不飽。","zh-Hant"]]},{"id":"li-ji_ch-13_p-12_s-3","passageId":"li-ji_ch-13_p-12","order":3,"canonicalText":"唯水漿不祭，若祭為已儕卑。","chunks":[["唯水漿不祭，若祭為已儕卑。","zh-Hant"]]},{"id":"li-ji_ch-13_p-13_s-1","passageId":"li-ji_ch-13_p-13","order":1,"canonicalText":"君若賜之爵，則越席再拜稽首受，登席祭之，飲卒爵而俟君卒爵，然後授虛爵。","chunks":[["君若賜之爵，則越席再拜稽首受，登席祭之，飲卒爵而俟君卒爵，然後授虛爵。","zh-Hant"]]},{"id":"li-ji_ch-13_p-13_s-2","passageId":"li-ji_ch-13_p-13","order":2,"canonicalText":"君子之飲酒也，受一爵而色灑如也，二爵而言言斯，禮已三爵而油油以退，退則坐取屨，隱辟而後屨，坐左納右，坐右納左。","chunks":[["君子之飲酒也，受一爵而色灑如也，二爵而言言斯，禮已三爵而油油以退，退則坐取屨，隱辟而後屨，坐左納右，坐右納左。","zh-Hant"]]},{"id":"li-ji_ch-13_p-14_s-1","passageId":"li-ji_ch-13_p-14","order":1,"canonicalText":"凡尊必上玄酒，唯君面尊，唯饗野人皆酒，大夫側尊用棜，士側尊用禁。","chunks":[["凡尊必上玄酒，唯君面尊，唯饗野人皆酒，大夫側尊用棜，士側尊用禁。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-1","passageId":"li-ji_ch-13_p-15","order":1,"canonicalText":"始冠，緇布冠，自諸侯下達，冠而敝之可也。","chunks":[["始冠，緇布冠，自諸侯下達，冠而敝之可也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-2","passageId":"li-ji_ch-13_p-15","order":2,"canonicalText":"玄冠朱組纓，天子之冠也。","chunks":[["玄冠朱組纓，天子之冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-3","passageId":"li-ji_ch-13_p-15","order":3,"canonicalText":"緇布冠繢緌，諸侯之冠也。","chunks":[["緇布冠繢緌，諸侯之冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-4","passageId":"li-ji_ch-13_p-15","order":4,"canonicalText":"玄冠丹組纓，諸侯之齊冠也。","chunks":[["玄冠丹組纓，諸侯之齊冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-5","passageId":"li-ji_ch-13_p-15","order":5,"canonicalText":"玄冠綦組纓，士之齊冠也。","chunks":[["玄冠綦組纓，士之齊冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-6","passageId":"li-ji_ch-13_p-15","order":6,"canonicalText":"縞冠玄武，子姓之冠也。","chunks":[["縞冠玄武，子姓之冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-7","passageId":"li-ji_ch-13_p-15","order":7,"canonicalText":"縞冠素紕，既祥之冠也。","chunks":[["縞冠素紕，既祥之冠也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-8","passageId":"li-ji_ch-13_p-15","order":8,"canonicalText":"垂緌五寸，惰游之士也，玄冠縞武，不齒之服也。","chunks":[["垂緌五寸，惰游之士也，玄冠縞武，不齒之服也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-9","passageId":"li-ji_ch-13_p-15","order":9,"canonicalText":"居冠屬武，自天子下達，有事然後緌。","chunks":[["居冠屬武，自天子下達，有事然後緌。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-10","passageId":"li-ji_ch-13_p-15","order":10,"canonicalText":"五十不散送，親沒不髦，大帛不緌。","chunks":[["五十不散送，親沒不髦，大帛不緌。","zh-Hant"]]},{"id":"li-ji_ch-13_p-15_s-11","passageId":"li-ji_ch-13_p-15","order":11,"canonicalText":"衣冠紫緌，自魯桓公始也。","chunks":[["衣冠紫緌，自魯桓公始也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-16_s-1","passageId":"li-ji_ch-13_p-16","order":1,"canonicalText":"朝玄端，夕深衣。","chunks":[["朝玄端，夕深衣。","zh-Hant"]]},{"id":"li-ji_ch-13_p-16_s-2","passageId":"li-ji_ch-13_p-16","order":2,"canonicalText":"深衣三袪，縫齊倍要，衽當旁，袂可以回肘。","chunks":[["深衣三袪，縫齊倍要，衽當旁，袂可以回肘。","zh-Hant"]]},{"id":"li-ji_ch-13_p-16_s-3","passageId":"li-ji_ch-13_p-16","order":3,"canonicalText":"長中繼掩尺。","chunks":[["長中繼掩尺。","zh-Hant"]]},{"id":"li-ji_ch-13_p-16_s-4","passageId":"li-ji_ch-13_p-16","order":4,"canonicalText":"袷二寸，祛尺二寸，緣廣寸半。","chunks":[["袷二寸，祛尺二寸，緣廣寸半。","zh-Hant"]]},{"id":"li-ji_ch-13_p-16_s-5","passageId":"li-ji_ch-13_p-16","order":5,"canonicalText":"以帛裹布，非禮也。","chunks":[["以帛裹布，非禮也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-17_s-1","passageId":"li-ji_ch-13_p-17","order":1,"canonicalText":"士不衣織，無君者不貳采。","chunks":[["士不衣織，無君者不貳采。","zh-Hant"]]},{"id":"li-ji_ch-13_p-17_s-2","passageId":"li-ji_ch-13_p-17","order":2,"canonicalText":"衣正色，裳間色。","chunks":[["衣正色，裳間色。","zh-Hant"]]},{"id":"li-ji_ch-13_p-18_s-1","passageId":"li-ji_ch-13_p-18","order":1,"canonicalText":"非列采不入公門，振絺綌不入公門，表裘不入公門，襲裘不入公門。","chunks":[["非列采不入公門，振絺綌不入公門，表裘不入公門，襲裘不入公門。","zh-Hant"]]},{"id":"li-ji_ch-13_p-19_s-1","passageId":"li-ji_ch-13_p-19","order":1,"canonicalText":"纊為繭，縕為袍，禪為絅，帛為褶。","chunks":[["纊為繭，縕為袍，禪為絅，帛為褶。","zh-Hant"]]},{"id":"li-ji_ch-13_p-20_s-1","passageId":"li-ji_ch-13_p-20","order":1,"canonicalText":"朝服之以縞也，自季康子始也。","chunks":[["朝服之以縞也，自季康子始也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-20_s-2","passageId":"li-ji_ch-13_p-20","order":2,"canonicalText":"孔子曰：「朝服而朝，卒朔然後服之。","chunks":[["孔子曰：「朝服而朝，卒朔然後服之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-20_s-3","passageId":"li-ji_ch-13_p-20","order":3,"canonicalText":"」曰：「國家未道，則不充其服焉。","chunks":[["」曰：「國家未道，則不充其服焉。","zh-Hant"]]},{"id":"li-ji_ch-13_p-20_s-4","passageId":"li-ji_ch-13_p-20","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-13_p-21_s-1","passageId":"li-ji_ch-13_p-21","order":1,"canonicalText":"唯君有黼裘以誓省，大裘非古也。","chunks":[["唯君有黼裘以誓省，大裘非古也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-21_s-2","passageId":"li-ji_ch-13_p-21","order":2,"canonicalText":"君衣狐白裘，錦衣以裼之。","chunks":[["君衣狐白裘，錦衣以裼之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-21_s-3","passageId":"li-ji_ch-13_p-21","order":3,"canonicalText":"君之右虎裘，厥左狼裘。","chunks":[["君之右虎裘，厥左狼裘。","zh-Hant"]]},{"id":"li-ji_ch-13_p-21_s-4","passageId":"li-ji_ch-13_p-21","order":4,"canonicalText":"士不衣狐白。","chunks":[["士不衣狐白。","zh-Hant"]]},{"id":"li-ji_ch-13_p-22_s-1","passageId":"li-ji_ch-13_p-22","order":1,"canonicalText":"君子狐青裘豹褎，玄綃衣以裼之；","chunks":[["君子狐青裘豹褎，玄綃衣以裼之；","zh-Hant"]]},{"id":"li-ji_ch-13_p-22_s-2","passageId":"li-ji_ch-13_p-22","order":2,"canonicalText":"麑裘青豻褎，絞衣以裼之；","chunks":[["麑裘青豻褎，絞衣以裼之；","zh-Hant"]]},{"id":"li-ji_ch-13_p-22_s-3","passageId":"li-ji_ch-13_p-22","order":3,"canonicalText":"羔裘豹飾，緇衣以裼之；","chunks":[["羔裘豹飾，緇衣以裼之；","zh-Hant"]]},{"id":"li-ji_ch-13_p-22_s-4","passageId":"li-ji_ch-13_p-22","order":4,"canonicalText":"狐裘，黃衣以裼之。","chunks":[["狐裘，黃衣以裼之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-22_s-5","passageId":"li-ji_ch-13_p-22","order":5,"canonicalText":"錦衣狐裘，諸侯之服也。","chunks":[["錦衣狐裘，諸侯之服也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-23_s-1","passageId":"li-ji_ch-13_p-23","order":1,"canonicalText":"犬羊之裘不裼，不文飾也不裼。","chunks":[["犬羊之裘不裼，不文飾也不裼。","zh-Hant"]]},{"id":"li-ji_ch-13_p-23_s-2","passageId":"li-ji_ch-13_p-23","order":2,"canonicalText":"裘之裼也，見美也。","chunks":[["裘之裼也，見美也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-23_s-3","passageId":"li-ji_ch-13_p-23","order":3,"canonicalText":"吊則襲，不盡飾也；","chunks":[["吊則襲，不盡飾也；","zh-Hant"]]},{"id":"li-ji_ch-13_p-23_s-4","passageId":"li-ji_ch-13_p-23","order":4,"canonicalText":"君在則裼，盡飾也。","chunks":[["君在則裼，盡飾也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-23_s-5","passageId":"li-ji_ch-13_p-23","order":5,"canonicalText":"服之襲也，充美也，是故尸襲，執玉龜襲，無事則裼，弗敢充也。","chunks":[["服之襲也，充美也，是故尸襲，執玉龜襲，無事則裼，弗敢充也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-1","passageId":"li-ji_ch-13_p-24","order":1,"canonicalText":"笏：天子以球玉；","chunks":[["笏：天子以球玉；","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-2","passageId":"li-ji_ch-13_p-24","order":2,"canonicalText":"諸侯以象；","chunks":[["諸侯以象；","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-3","passageId":"li-ji_ch-13_p-24","order":3,"canonicalText":"大夫以魚須文竹；","chunks":[["大夫以魚須文竹；","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-4","passageId":"li-ji_ch-13_p-24","order":4,"canonicalText":"士竹本，象可也。","chunks":[["士竹本，象可也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-5","passageId":"li-ji_ch-13_p-24","order":5,"canonicalText":"見於天子與射，無說笏，入大廟說笏，非古也。","chunks":[["見於天子與射，無說笏，入大廟說笏，非古也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-6","passageId":"li-ji_ch-13_p-24","order":6,"canonicalText":"小功不說笏，當事免則說之。","chunks":[["小功不說笏，當事免則說之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-7","passageId":"li-ji_ch-13_p-24","order":7,"canonicalText":"既搢必盥，雖有執於朝，弗有盥矣。","chunks":[["既搢必盥，雖有執於朝，弗有盥矣。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-8","passageId":"li-ji_ch-13_p-24","order":8,"canonicalText":"凡有指畫於君前，用笏造，受命於君前，則書於笏，笏畢用也，因飾焉。","chunks":[["凡有指畫於君前，用笏造，受命於君前，則書於笏，笏畢用也，因飾焉。","zh-Hant"]]},{"id":"li-ji_ch-13_p-24_s-9","passageId":"li-ji_ch-13_p-24","order":9,"canonicalText":"笏度二尺有六寸，其中博三寸，其殺六分而去一。","chunks":[["笏度二尺有六寸，其中博三寸，其殺六分而去一。","zh-Hant"]]},{"id":"li-ji_ch-13_p-25_s-1","passageId":"li-ji_ch-13_p-25","order":1,"canonicalText":"鞸，君朱，大夫素，士爵韋。","chunks":[["鞸，君朱，大夫素，士爵韋。","zh-Hant"]]},{"id":"li-ji_ch-13_p-25_s-2","passageId":"li-ji_ch-13_p-25","order":2,"canonicalText":"圜殺直，天子直，公侯前後方，大夫前方後挫角，士前後正。","chunks":[["圜殺直，天子直，公侯前後方，大夫前方後挫角，士前後正。","zh-Hant"]]},{"id":"li-ji_ch-13_p-26_s-1","passageId":"li-ji_ch-13_p-26","order":1,"canonicalText":"鞸，下廣二尺，上廣一尺，長三尺，其頸五寸，肩革帶博二寸。","chunks":[["鞸，下廣二尺，上廣一尺，長三尺，其頸五寸，肩革帶博二寸。","zh-Hant"]]},{"id":"li-ji_ch-13_p-27_s-1","passageId":"li-ji_ch-13_p-27","order":1,"canonicalText":"一命縕韍幽衡，再命赤韍幽衡，三命赤韍蔥衡。","chunks":[["一命縕韍幽衡，再命赤韍幽衡，三命赤韍蔥衡。","zh-Hant"]]},{"id":"li-ji_ch-13_p-28_s-1","passageId":"li-ji_ch-13_p-28","order":1,"canonicalText":"天子素帶朱里終辟，而素帶終辟，大夫素帶辟垂，士練帶率下辟，居士錦帶，弟子縞帶。","chunks":[["天子素帶朱里終辟，而素帶終辟，大夫素帶辟垂，士練帶率下辟，居士錦帶，弟子縞帶。","zh-Hant"]]},{"id":"li-ji_ch-13_p-29_s-1","passageId":"li-ji_ch-13_p-29","order":1,"canonicalText":"并紐約，用組、三寸，長齊於帶，紳長制，士三尺，有司二尺有五寸。","chunks":[["并紐約，用組、三寸，長齊於帶，紳長制，士三尺，有司二尺有五寸。","zh-Hant"]]},{"id":"li-ji_ch-13_p-29_s-2","passageId":"li-ji_ch-13_p-29","order":2,"canonicalText":"子游曰：「參分帶下，紳居二焉，紳韍結三齊。","chunks":[["子游曰：「參分帶下，紳居二焉，紳韍結三齊。","zh-Hant"]]},{"id":"li-ji_ch-13_p-29_s-3","passageId":"li-ji_ch-13_p-29","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-13_p-30_s-1","passageId":"li-ji_ch-13_p-30","order":1,"canonicalText":"大夫大帶四寸。","chunks":[["大夫大帶四寸。","zh-Hant"]]},{"id":"li-ji_ch-13_p-30_s-2","passageId":"li-ji_ch-13_p-30","order":2,"canonicalText":"雜帶，君朱綠；","chunks":[["雜帶，君朱綠；","zh-Hant"]]},{"id":"li-ji_ch-13_p-30_s-3","passageId":"li-ji_ch-13_p-30","order":3,"canonicalText":"大夫玄華，士緇辟，二寸，再繚四寸。","chunks":[["大夫玄華，士緇辟，二寸，再繚四寸。","zh-Hant"]]},{"id":"li-ji_ch-13_p-30_s-4","passageId":"li-ji_ch-13_p-30","order":4,"canonicalText":"凡帶，有率無箴功，肆束及帶勤者，有事則收之，走則擁之。","chunks":[["凡帶，有率無箴功，肆束及帶勤者，有事則收之，走則擁之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-31_s-1","passageId":"li-ji_ch-13_p-31","order":1,"canonicalText":"王后褘衣，夫人揄狄；","chunks":[["王后褘衣，夫人揄狄；","zh-Hant"]]},{"id":"li-ji_ch-13_p-31_s-2","passageId":"li-ji_ch-13_p-31","order":2,"canonicalText":"君命屈狄，再命褘衣，一命襢衣，士褖衣。","chunks":[["君命屈狄，再命褘衣，一命襢衣，士褖衣。","zh-Hant"]]},{"id":"li-ji_ch-13_p-31_s-3","passageId":"li-ji_ch-13_p-31","order":3,"canonicalText":"唯世婦命於奠繭，其他則皆從男子。","chunks":[["唯世婦命於奠繭，其他則皆從男子。","zh-Hant"]]},{"id":"li-ji_ch-13_p-32_s-1","passageId":"li-ji_ch-13_p-32","order":1,"canonicalText":"凡侍於君，紳垂，足如履齊，頤溜垂拱，視下而聽上，視帶以及袷，聽鄉任左。","chunks":[["凡侍於君，紳垂，足如履齊，頤溜垂拱，視下而聽上，視帶以及袷，聽鄉任左。","zh-Hant"]]},{"id":"li-ji_ch-13_p-33_s-1","passageId":"li-ji_ch-13_p-33","order":1,"canonicalText":"凡君召，以三節：二節以走，一節以趨。","chunks":[["凡君召，以三節：二節以走，一節以趨。","zh-Hant"]]},{"id":"li-ji_ch-13_p-33_s-2","passageId":"li-ji_ch-13_p-33","order":2,"canonicalText":"在官不俟屨，在外不俟車。","chunks":[["在官不俟屨，在外不俟車。","zh-Hant"]]},{"id":"li-ji_ch-13_p-34_s-1","passageId":"li-ji_ch-13_p-34","order":1,"canonicalText":"士於大夫，不敢拜迎而拜送；","chunks":[["士於大夫，不敢拜迎而拜送；","zh-Hant"]]},{"id":"li-ji_ch-13_p-34_s-2","passageId":"li-ji_ch-13_p-34","order":2,"canonicalText":"士於尊者，先拜進面，答之拜則走。","chunks":[["士於尊者，先拜進面，答之拜則走。","zh-Hant"]]},{"id":"li-ji_ch-13_p-35_s-1","passageId":"li-ji_ch-13_p-35","order":1,"canonicalText":"士於君所言，大夫沒矣，則稱謚若字，名士。","chunks":[["士於君所言，大夫沒矣，則稱謚若字，名士。","zh-Hant"]]},{"id":"li-ji_ch-13_p-35_s-2","passageId":"li-ji_ch-13_p-35","order":2,"canonicalText":"與大夫言，名士字大夫。","chunks":[["與大夫言，名士字大夫。","zh-Hant"]]},{"id":"li-ji_ch-13_p-35_s-3","passageId":"li-ji_ch-13_p-35","order":3,"canonicalText":"於大夫所，有公諱無私諱。","chunks":[["於大夫所，有公諱無私諱。","zh-Hant"]]},{"id":"li-ji_ch-13_p-35_s-4","passageId":"li-ji_ch-13_p-35","order":4,"canonicalText":"凡祭不諱，廟中不諱，教學臨文不諱。","chunks":[["凡祭不諱，廟中不諱，教學臨文不諱。","zh-Hant"]]},{"id":"li-ji_ch-13_p-36_s-1","passageId":"li-ji_ch-13_p-36","order":1,"canonicalText":"古之君子必佩玉，右徵角，左宮羽。","chunks":[["古之君子必佩玉，右徵角，左宮羽。","zh-Hant"]]},{"id":"li-ji_ch-13_p-37_s-1","passageId":"li-ji_ch-13_p-37","order":1,"canonicalText":"趨以《采齊》，行以《肆夏》，周還中規，折還中矩，進則揖之，退則揚之，然後玉鏘鳴也。","chunks":[["趨以《采齊》，行以《肆夏》，周還中規，折還中矩，進則揖之，退則揚之，然後玉鏘鳴也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-37_s-2","passageId":"li-ji_ch-13_p-37","order":2,"canonicalText":"故君子在車，則聞鸞和之聲，行則鳴佩玉，是以非辟之心，無自入也。","chunks":[["故君子在車，則聞鸞和之聲，行則鳴佩玉，是以非辟之心，無自入也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-38_s-1","passageId":"li-ji_ch-13_p-38","order":1,"canonicalText":"君在不佩玉，左結佩，右設佩，居則設佩，朝則結佩，齊則綪結佩而爵韍。","chunks":[["君在不佩玉，左結佩，右設佩，居則設佩，朝則結佩，齊則綪結佩而爵韍。","zh-Hant"]]},{"id":"li-ji_ch-13_p-39_s-1","passageId":"li-ji_ch-13_p-39","order":1,"canonicalText":"凡帶必有佩玉，唯喪否。","chunks":[["凡帶必有佩玉，唯喪否。","zh-Hant"]]},{"id":"li-ji_ch-13_p-39_s-2","passageId":"li-ji_ch-13_p-39","order":2,"canonicalText":"佩玉有沖牙；","chunks":[["佩玉有沖牙；","zh-Hant"]]},{"id":"li-ji_ch-13_p-39_s-3","passageId":"li-ji_ch-13_p-39","order":3,"canonicalText":"君子無故，玉不去身，君子於玉比德焉。","chunks":[["君子無故，玉不去身，君子於玉比德焉。","zh-Hant"]]},{"id":"li-ji_ch-13_p-39_s-4","passageId":"li-ji_ch-13_p-39","order":4,"canonicalText":"天子佩白玉而玄組綬，公侯佩山玄玉而朱組綬，大夫佩水蒼玉而純組綬，世子佩瑜玉而綦組綬，士佩瓀玟而縕組綬。","chunks":[["天子佩白玉而玄組綬，公侯佩山玄玉而朱組綬，大夫佩水蒼玉而純組綬，世子佩瑜玉而綦組綬，士佩瓀玟而縕組綬。","zh-Hant"]]},{"id":"li-ji_ch-13_p-39_s-5","passageId":"li-ji_ch-13_p-39","order":5,"canonicalText":"孔子佩象環五寸，而綦組綬。","chunks":[["孔子佩象環五寸，而綦組綬。","zh-Hant"]]},{"id":"li-ji_ch-13_p-40_s-1","passageId":"li-ji_ch-13_p-40","order":1,"canonicalText":"童子之節也，緇布衣錦緣，錦紳，并紐錦，束發皆朱錦也。","chunks":[["童子之節也，緇布衣錦緣，錦紳，并紐錦，束發皆朱錦也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-40_s-2","passageId":"li-ji_ch-13_p-40","order":2,"canonicalText":"童子不裘不帛，不屨絇，無緦服。","chunks":[["童子不裘不帛，不屨絇，無緦服。","zh-Hant"]]},{"id":"li-ji_ch-13_p-40_s-3","passageId":"li-ji_ch-13_p-40","order":3,"canonicalText":"聽事不麻，無事則立主人之北面，見先生從人而入。","chunks":[["聽事不麻，無事則立主人之北面，見先生從人而入。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-1","passageId":"li-ji_ch-13_p-41","order":1,"canonicalText":"侍食於先生異爵者，後祭先飯。","chunks":[["侍食於先生異爵者，後祭先飯。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-2","passageId":"li-ji_ch-13_p-41","order":2,"canonicalText":"客祭，主人辭曰：「不足祭也。","chunks":[["客祭，主人辭曰：「不足祭也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-3","passageId":"li-ji_ch-13_p-41","order":3,"canonicalText":"」客飧，主人辭以疏。","chunks":[["」客飧，主人辭以疏。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-4","passageId":"li-ji_ch-13_p-41","order":4,"canonicalText":"主人自置其醬，則客自徹之。","chunks":[["主人自置其醬，則客自徹之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-5","passageId":"li-ji_ch-13_p-41","order":5,"canonicalText":"一室之人，非賓客，一人徹。","chunks":[["一室之人，非賓客，一人徹。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-6","passageId":"li-ji_ch-13_p-41","order":6,"canonicalText":"壹食之人，一人徹。","chunks":[["壹食之人，一人徹。","zh-Hant"]]},{"id":"li-ji_ch-13_p-41_s-7","passageId":"li-ji_ch-13_p-41","order":7,"canonicalText":"凡燕食，婦人不徹。","chunks":[["凡燕食，婦人不徹。","zh-Hant"]]},{"id":"li-ji_ch-13_p-42_s-1","passageId":"li-ji_ch-13_p-42","order":1,"canonicalText":"食棗桃李，弗致于核，瓜祭上環，食中棄所操。","chunks":[["食棗桃李，弗致于核，瓜祭上環，食中棄所操。","zh-Hant"]]},{"id":"li-ji_ch-13_p-42_s-2","passageId":"li-ji_ch-13_p-42","order":2,"canonicalText":"凡食果實者後君子，火孰者先君子。","chunks":[["凡食果實者後君子，火孰者先君子。","zh-Hant"]]},{"id":"li-ji_ch-13_p-42_s-3","passageId":"li-ji_ch-13_p-42","order":3,"canonicalText":"有慶，非君賜不賀。","chunks":[["有慶，非君賜不賀。","zh-Hant"]]},{"id":"li-ji_ch-13_p-43_s-1","passageId":"li-ji_ch-13_p-43","order":1,"canonicalText":"孔子食於季氏，不辭，不食肉而飧。","chunks":[["孔子食於季氏，不辭，不食肉而飧。","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-1","passageId":"li-ji_ch-13_p-44","order":1,"canonicalText":"君賜車馬，乘以拜賜；","chunks":[["君賜車馬，乘以拜賜；","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-2","passageId":"li-ji_ch-13_p-44","order":2,"canonicalText":"衣服，服以拜賜；","chunks":[["衣服，服以拜賜；","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-3","passageId":"li-ji_ch-13_p-44","order":3,"canonicalText":"君未有命，弗敢即乘服也。","chunks":[["君未有命，弗敢即乘服也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-4","passageId":"li-ji_ch-13_p-44","order":4,"canonicalText":"君賜，稽首，據掌致諸地；","chunks":[["君賜，稽首，據掌致諸地；","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-5","passageId":"li-ji_ch-13_p-44","order":5,"canonicalText":"酒肉之賜，弗再拜。","chunks":[["酒肉之賜，弗再拜。","zh-Hant"]]},{"id":"li-ji_ch-13_p-44_s-6","passageId":"li-ji_ch-13_p-44","order":6,"canonicalText":"凡賜，君子與小人不同日。","chunks":[["凡賜，君子與小人不同日。","zh-Hant"]]},{"id":"li-ji_ch-13_p-45_s-1","passageId":"li-ji_ch-13_p-45","order":1,"canonicalText":"凡獻於君，大夫使宰，士親，皆再拜稽首送之。","chunks":[["凡獻於君，大夫使宰，士親，皆再拜稽首送之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-45_s-2","passageId":"li-ji_ch-13_p-45","order":2,"canonicalText":"膳於君，有葷桃茢，於大夫去茢，於士去葷，皆造於膳宰。","chunks":[["膳於君，有葷桃茢，於大夫去茢，於士去葷，皆造於膳宰。","zh-Hant"]]},{"id":"li-ji_ch-13_p-45_s-3","passageId":"li-ji_ch-13_p-45","order":3,"canonicalText":"大夫不親拜，為君之答己也。","chunks":[["大夫不親拜，為君之答己也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-46_s-1","passageId":"li-ji_ch-13_p-46","order":1,"canonicalText":"大夫拜賜而退，士待諾而退，又拜，弗答拜。","chunks":[["大夫拜賜而退，士待諾而退，又拜，弗答拜。","zh-Hant"]]},{"id":"li-ji_ch-13_p-46_s-2","passageId":"li-ji_ch-13_p-46","order":2,"canonicalText":"大夫親賜士，士拜受，又拜於其室。","chunks":[["大夫親賜士，士拜受，又拜於其室。","zh-Hant"]]},{"id":"li-ji_ch-13_p-46_s-3","passageId":"li-ji_ch-13_p-46","order":3,"canonicalText":"衣服，弗服以拜。","chunks":[["衣服，弗服以拜。","zh-Hant"]]},{"id":"li-ji_ch-13_p-46_s-4","passageId":"li-ji_ch-13_p-46","order":4,"canonicalText":"敵者不在，拜於其室。","chunks":[["敵者不在，拜於其室。","zh-Hant"]]},{"id":"li-ji_ch-13_p-47_s-1","passageId":"li-ji_ch-13_p-47","order":1,"canonicalText":"凡於尊者有獻，而弗敢以聞。","chunks":[["凡於尊者有獻，而弗敢以聞。","zh-Hant"]]},{"id":"li-ji_ch-13_p-47_s-2","passageId":"li-ji_ch-13_p-47","order":2,"canonicalText":"士於大夫不承賀，下大夫於上大夫承賀。","chunks":[["士於大夫不承賀，下大夫於上大夫承賀。","zh-Hant"]]},{"id":"li-ji_ch-13_p-47_s-3","passageId":"li-ji_ch-13_p-47","order":3,"canonicalText":"親在，行禮於人稱父，人或賜之，則稱父拜之。","chunks":[["親在，行禮於人稱父，人或賜之，則稱父拜之。","zh-Hant"]]},{"id":"li-ji_ch-13_p-48_s-1","passageId":"li-ji_ch-13_p-48","order":1,"canonicalText":"禮不盛，服不充，故大裘不裼，乘路車不式。","chunks":[["禮不盛，服不充，故大裘不裼，乘路車不式。","zh-Hant"]]},{"id":"li-ji_ch-13_p-49_s-1","passageId":"li-ji_ch-13_p-49","order":1,"canonicalText":"父命呼，唯而不諾，手執業則投之，食在口則吐之，走而不趨。","chunks":[["父命呼，唯而不諾，手執業則投之，食在口則吐之，走而不趨。","zh-Hant"]]},{"id":"li-ji_ch-13_p-49_s-2","passageId":"li-ji_ch-13_p-49","order":2,"canonicalText":"親老，出不易方，復不過時。","chunks":[["親老，出不易方，復不過時。","zh-Hant"]]},{"id":"li-ji_ch-13_p-49_s-3","passageId":"li-ji_ch-13_p-49","order":3,"canonicalText":"親癠色容不盛，此孝子之疏節也。","chunks":[["親癠色容不盛，此孝子之疏節也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-50_s-1","passageId":"li-ji_ch-13_p-50","order":1,"canonicalText":"父歿而不能讀父之書，手澤存焉爾；","chunks":[["父歿而不能讀父之書，手澤存焉爾；","zh-Hant"]]},{"id":"li-ji_ch-13_p-50_s-2","passageId":"li-ji_ch-13_p-50","order":2,"canonicalText":"母歿而杯圈不能飲焉，口澤之氣存焉爾。","chunks":[["母歿而杯圈不能飲焉，口澤之氣存焉爾。","zh-Hant"]]},{"id":"li-ji_ch-13_p-51_s-1","passageId":"li-ji_ch-13_p-51","order":1,"canonicalText":"君入門，介拂闑，大夫中棖與闑之間，士介拂棖。","chunks":[["君入門，介拂闑，大夫中棖與闑之間，士介拂棖。","zh-Hant"]]},{"id":"li-ji_ch-13_p-51_s-2","passageId":"li-ji_ch-13_p-51","order":2,"canonicalText":"賓入不中門，不履閾，公事自闑西，私事自闑東。","chunks":[["賓入不中門，不履閾，公事自闑西，私事自闑東。","zh-Hant"]]},{"id":"li-ji_ch-13_p-52_s-1","passageId":"li-ji_ch-13_p-52","order":1,"canonicalText":"君與尸行接武，大夫繼武，士中武，徐趨皆用是。","chunks":[["君與尸行接武，大夫繼武，士中武，徐趨皆用是。","zh-Hant"]]},{"id":"li-ji_ch-13_p-52_s-2","passageId":"li-ji_ch-13_p-52","order":2,"canonicalText":"疾趨則欲發而手足毋移，圈豚行不舉足，齊如流，席上亦然。","chunks":[["疾趨則欲發而手足毋移，圈豚行不舉足，齊如流，席上亦然。","zh-Hant"]]},{"id":"li-ji_ch-13_p-52_s-3","passageId":"li-ji_ch-13_p-52","order":3,"canonicalText":"端行，頤溜如矢，弁行，剡剡起屨，執龜玉，舉前曳踵，蹜蹜如也。","chunks":[["端行，頤溜如矢，弁行，剡剡起屨，執龜玉，舉前曳踵，蹜蹜如也。","zh-Hant"]]},{"id":"li-ji_ch-13_p-53_s-1","passageId":"li-ji_ch-13_p-53","order":1,"canonicalText":"凡行容愓愓，廟中齊齊，朝庭濟濟翔翔。","chunks":[["凡行容愓愓，廟中齊齊，朝庭濟濟翔翔。","zh-Hant"]]},{"id":"li-ji_ch-13_p-53_s-2","passageId":"li-ji_ch-13_p-53","order":2,"canonicalText":"君子之容舒遲，見所尊者齊遫。","chunks":[["君子之容舒遲，見所尊者齊遫。","zh-Hant"]]},{"id":"li-ji_ch-13_p-53_s-3","passageId":"li-ji_ch-13_p-53","order":3,"canonicalText":"足容重，手容恭，目容端，口容止，聲容靜，頭容直，氣容肅，立容德，色容莊，坐如尸，燕居告溫溫。","chunks":[["足容重，手容恭，目容端，口容止，聲容靜，頭容直，氣容肅，立容德，色容莊，坐如尸，燕居告溫溫。","zh-Hant"]]},{"id":"li-ji_ch-13_p-54_s-1","passageId":"li-ji_ch-13_p-54","order":1,"canonicalText":"凡祭，容貌顏色，如見所祭者。","chunks":[["凡祭，容貌顏色，如見所祭者。","zh-Hant"]]},{"id":"li-ji_ch-13_p-54_s-2","passageId":"li-ji_ch-13_p-54","order":2,"canonicalText":"喪容纍纍，色容顛顛，視容瞿瞿梅梅，言容繭繭，戎容暨暨，言容詻詻，色容厲肅，視容清明。","chunks":[["喪容纍纍，色容顛顛，視容瞿瞿梅梅，言容繭繭，戎容暨暨，言容詻詻，色容厲肅，視容清明。","zh-Hant"]]},{"id":"li-ji_ch-13_p-54_s-3","passageId":"li-ji_ch-13_p-54","order":3,"canonicalText":"立容辨，卑毋諂，頭頸必中，山立時行，盛氣顛實，揚休玉色。","chunks":[["立容辨，卑毋諂，頭頸必中，山立時行，盛氣顛實，揚休玉色。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-1","passageId":"li-ji_ch-13_p-55","order":1,"canonicalText":"凡自稱：天子曰予一人，伯曰天子之力臣。","chunks":[["凡自稱：天子曰予一人，伯曰天子之力臣。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-2","passageId":"li-ji_ch-13_p-55","order":2,"canonicalText":"諸侯之於天子曰某土之守臣某，其在邊邑，曰某屏之臣某。","chunks":[["諸侯之於天子曰某土之守臣某，其在邊邑，曰某屏之臣某。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-3","passageId":"li-ji_ch-13_p-55","order":3,"canonicalText":"其於敵以下曰寡人，小國之君曰孤，擯者亦曰孤。","chunks":[["其於敵以下曰寡人，小國之君曰孤，擯者亦曰孤。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-4","passageId":"li-ji_ch-13_p-55","order":4,"canonicalText":"上大夫曰下臣，擯者曰寡君之老，下大夫自名，擯者曰寡大夫。","chunks":[["上大夫曰下臣，擯者曰寡君之老，下大夫自名，擯者曰寡大夫。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-5","passageId":"li-ji_ch-13_p-55","order":5,"canonicalText":"世子自名，擯者曰寡君之適，公子曰臣孽。","chunks":[["世子自名，擯者曰寡君之適，公子曰臣孽。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-6","passageId":"li-ji_ch-13_p-55","order":6,"canonicalText":"士曰傳遽之臣，於大夫曰外私。","chunks":[["士曰傳遽之臣，於大夫曰外私。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-7","passageId":"li-ji_ch-13_p-55","order":7,"canonicalText":"大夫私事使，私人擯則稱名，公士擯則曰寡大夫、寡君之老。","chunks":[["大夫私事使，私人擯則稱名，公士擯則曰寡大夫、寡君之老。","zh-Hant"]]},{"id":"li-ji_ch-13_p-55_s-8","passageId":"li-ji_ch-13_p-55","order":8,"canonicalText":"大夫有所往，必與公士為賓也。","chunks":[["大夫有所往，必與公士為賓也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-1","passageId":"li-ji_ch-14_p-1","order":1,"canonicalText":"昔者周公朝諸侯于明堂之位：天子負斧依南鄉而立；","chunks":[["昔者周公朝諸侯于明堂之位：天子負斧依南鄉而立；","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-2","passageId":"li-ji_ch-14_p-1","order":2,"canonicalText":"三公，中階之前，北面東上。","chunks":[["三公，中階之前，北面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-3","passageId":"li-ji_ch-14_p-1","order":3,"canonicalText":"諸侯之位，阼階之東，西面北上。","chunks":[["諸侯之位，阼階之東，西面北上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-4","passageId":"li-ji_ch-14_p-1","order":4,"canonicalText":"諸伯之國，西階之西，東面北上。","chunks":[["諸伯之國，西階之西，東面北上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-5","passageId":"li-ji_ch-14_p-1","order":5,"canonicalText":"諸子之國，門東，北面東上。","chunks":[["諸子之國，門東，北面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-6","passageId":"li-ji_ch-14_p-1","order":6,"canonicalText":"諸男之國，門西，北面東上。","chunks":[["諸男之國，門西，北面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-7","passageId":"li-ji_ch-14_p-1","order":7,"canonicalText":"九夷之國，東門之外，西面北上。","chunks":[["九夷之國，東門之外，西面北上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-8","passageId":"li-ji_ch-14_p-1","order":8,"canonicalText":"八蠻之國，南門之外，北面東上。","chunks":[["八蠻之國，南門之外，北面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-9","passageId":"li-ji_ch-14_p-1","order":9,"canonicalText":"六戎之國，西門之外，東面南上。","chunks":[["六戎之國，西門之外，東面南上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-10","passageId":"li-ji_ch-14_p-1","order":10,"canonicalText":"五狄之國，北門之外，南面東上。","chunks":[["五狄之國，北門之外，南面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-11","passageId":"li-ji_ch-14_p-1","order":11,"canonicalText":"九采之國，應門之外，北面東上。","chunks":[["九采之國，應門之外，北面東上。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-12","passageId":"li-ji_ch-14_p-1","order":12,"canonicalText":"四塞，世告至。","chunks":[["四塞，世告至。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-13","passageId":"li-ji_ch-14_p-1","order":13,"canonicalText":"此周公明堂之位也。","chunks":[["此周公明堂之位也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-1_s-14","passageId":"li-ji_ch-14_p-1","order":14,"canonicalText":"明堂也者，明諸侯之尊卑也。","chunks":[["明堂也者，明諸侯之尊卑也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-1","passageId":"li-ji_ch-14_p-2","order":1,"canonicalText":"昔殷紂亂天下，脯鬼侯以饗諸侯。","chunks":[["昔殷紂亂天下，脯鬼侯以饗諸侯。","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-2","passageId":"li-ji_ch-14_p-2","order":2,"canonicalText":"是以周公相武王以伐紂。","chunks":[["是以周公相武王以伐紂。","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-3","passageId":"li-ji_ch-14_p-2","order":3,"canonicalText":"武王崩，成王幼弱，周公踐天子之位以治天下；","chunks":[["武王崩，成王幼弱，周公踐天子之位以治天下；","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-4","passageId":"li-ji_ch-14_p-2","order":4,"canonicalText":"六年，朝諸侯於明堂，制禮作樂，頒度量，而天下大服；","chunks":[["六年，朝諸侯於明堂，制禮作樂，頒度量，而天下大服；","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-5","passageId":"li-ji_ch-14_p-2","order":5,"canonicalText":"七年，致政於成王；","chunks":[["七年，致政於成王；","zh-Hant"]]},{"id":"li-ji_ch-14_p-2_s-6","passageId":"li-ji_ch-14_p-2","order":6,"canonicalText":"成王以周公為有勛勞於天下，是以封周公於曲阜，地方七百里，革車千乘，命魯公世世祀周公天以子之禮樂。","chunks":[["成王以周公為有勛勞於天下，是以封周公於曲阜，地方七百里，革車千乘，命魯公世世祀周公天以子之禮樂。","zh-Hant"]]},{"id":"li-ji_ch-14_p-3_s-1","passageId":"li-ji_ch-14_p-3","order":1,"canonicalText":"是以魯君，孟春乘大路，載弧韣；","chunks":[["是以魯君，孟春乘大路，載弧韣；","zh-Hant"]]},{"id":"li-ji_ch-14_p-3_s-2","passageId":"li-ji_ch-14_p-3","order":2,"canonicalText":"旗十有二旒，日月之章；","chunks":[["旗十有二旒，日月之章；","zh-Hant"]]},{"id":"li-ji_ch-14_p-3_s-3","passageId":"li-ji_ch-14_p-3","order":3,"canonicalText":"祀帝于郊，配以后稷。","chunks":[["祀帝于郊，配以后稷。","zh-Hant"]]},{"id":"li-ji_ch-14_p-3_s-4","passageId":"li-ji_ch-14_p-3","order":4,"canonicalText":"天子之禮也。","chunks":[["天子之禮也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-1","passageId":"li-ji_ch-14_p-4","order":1,"canonicalText":"季夏六月，以禘禮祀周公於大廟，牲用白牡；","chunks":[["季夏六月，以禘禮祀周公於大廟，牲用白牡；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-2","passageId":"li-ji_ch-14_p-4","order":2,"canonicalText":"尊用犧象山罍；","chunks":[["尊用犧象山罍；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-3","passageId":"li-ji_ch-14_p-4","order":3,"canonicalText":"郁尊用黃目；","chunks":[["郁尊用黃目；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-4","passageId":"li-ji_ch-14_p-4","order":4,"canonicalText":"灌用玉瓚大圭；","chunks":[["灌用玉瓚大圭；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-5","passageId":"li-ji_ch-14_p-4","order":5,"canonicalText":"薦用玉豆雕篹；","chunks":[["薦用玉豆雕篹；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-6","passageId":"li-ji_ch-14_p-4","order":6,"canonicalText":"爵用玉琖，仍雕，加以璧散璧角；","chunks":[["爵用玉琖，仍雕，加以璧散璧角；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-7","passageId":"li-ji_ch-14_p-4","order":7,"canonicalText":"俎用梡嶡；","chunks":[["俎用梡嶡；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-8","passageId":"li-ji_ch-14_p-4","order":8,"canonicalText":"升歌《清廟》，下管《象》；","chunks":[["升歌《清廟》，下管《象》；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-9","passageId":"li-ji_ch-14_p-4","order":9,"canonicalText":"朱干玉戚，冕而舞《大武》；","chunks":[["朱干玉戚，冕而舞《大武》；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-10","passageId":"li-ji_ch-14_p-4","order":10,"canonicalText":"皮弁素積，裼而舞《大夏》。","chunks":[["皮弁素積，裼而舞《大夏》。","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-11","passageId":"li-ji_ch-14_p-4","order":11,"canonicalText":"昧，東夷之樂也；","chunks":[["昧，東夷之樂也；","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-12","passageId":"li-ji_ch-14_p-4","order":12,"canonicalText":"《任》，南蠻之樂也。","chunks":[["《任》，南蠻之樂也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-4_s-13","passageId":"li-ji_ch-14_p-4","order":13,"canonicalText":"納夷蠻之樂於大廟，言廣魯於天下也。","chunks":[["納夷蠻之樂於大廟，言廣魯於天下也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-5_s-1","passageId":"li-ji_ch-14_p-5","order":1,"canonicalText":"君卷冕立於阼，夫人副褘立于房中。","chunks":[["君卷冕立於阼，夫人副褘立于房中。","zh-Hant"]]},{"id":"li-ji_ch-14_p-5_s-2","passageId":"li-ji_ch-14_p-5","order":2,"canonicalText":"君肉袒迎牲于門；","chunks":[["君肉袒迎牲于門；","zh-Hant"]]},{"id":"li-ji_ch-14_p-5_s-3","passageId":"li-ji_ch-14_p-5","order":3,"canonicalText":"夫人薦豆籩。","chunks":[["夫人薦豆籩。","zh-Hant"]]},{"id":"li-ji_ch-14_p-5_s-4","passageId":"li-ji_ch-14_p-5","order":4,"canonicalText":"卿、大夫贊君，命婦贊夫人：各揚其職。","chunks":[["卿、大夫贊君，命婦贊夫人：各揚其職。","zh-Hant"]]},{"id":"li-ji_ch-14_p-5_s-5","passageId":"li-ji_ch-14_p-5","order":5,"canonicalText":"百官廢職服大刑，而天下大服。","chunks":[["百官廢職服大刑，而天下大服。","zh-Hant"]]},{"id":"li-ji_ch-14_p-6_s-1","passageId":"li-ji_ch-14_p-6","order":1,"canonicalText":"是故，夏礿、秋嘗、冬烝，春社、秋省而遂大蜡，天子之祭也。","chunks":[["是故，夏礿、秋嘗、冬烝，春社、秋省而遂大蜡，天子之祭也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-7_s-1","passageId":"li-ji_ch-14_p-7","order":1,"canonicalText":"大廟，天子明堂。","chunks":[["大廟，天子明堂。","zh-Hant"]]},{"id":"li-ji_ch-14_p-7_s-2","passageId":"li-ji_ch-14_p-7","order":2,"canonicalText":"庫門，天子皋門。","chunks":[["庫門，天子皋門。","zh-Hant"]]},{"id":"li-ji_ch-14_p-7_s-3","passageId":"li-ji_ch-14_p-7","order":3,"canonicalText":"雉門，天子應門。","chunks":[["雉門，天子應門。","zh-Hant"]]},{"id":"li-ji_ch-14_p-8_s-1","passageId":"li-ji_ch-14_p-8","order":1,"canonicalText":"振木鐸於朝，天子之政也。","chunks":[["振木鐸於朝，天子之政也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-9_s-1","passageId":"li-ji_ch-14_p-9","order":1,"canonicalText":"山節藻梲，復廟重檐，刮楹達鄉，反坫出尊，崇坫康圭，疏屏；","chunks":[["山節藻梲，復廟重檐，刮楹達鄉，反坫出尊，崇坫康圭，疏屏；","zh-Hant"]]},{"id":"li-ji_ch-14_p-9_s-2","passageId":"li-ji_ch-14_p-9","order":2,"canonicalText":"天子之廟飾也。","chunks":[["天子之廟飾也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-10_s-1","passageId":"li-ji_ch-14_p-10","order":1,"canonicalText":"鸞車，有虞氏之路也。","chunks":[["鸞車，有虞氏之路也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-10_s-2","passageId":"li-ji_ch-14_p-10","order":2,"canonicalText":"鉤車，夏后氏之路也。","chunks":[["鉤車，夏后氏之路也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-10_s-3","passageId":"li-ji_ch-14_p-10","order":3,"canonicalText":"大路，殷路也。","chunks":[["大路，殷路也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-10_s-4","passageId":"li-ji_ch-14_p-10","order":4,"canonicalText":"乘路，周路也。","chunks":[["乘路，周路也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-11_s-1","passageId":"li-ji_ch-14_p-11","order":1,"canonicalText":"有虞氏之旗，夏后氏之綏，殷之大白，周之大赤。","chunks":[["有虞氏之旗，夏后氏之綏，殷之大白，周之大赤。","zh-Hant"]]},{"id":"li-ji_ch-14_p-12_s-1","passageId":"li-ji_ch-14_p-12","order":1,"canonicalText":"夏后氏駱馬，黑鬣。","chunks":[["夏后氏駱馬，黑鬣。","zh-Hant"]]},{"id":"li-ji_ch-14_p-12_s-2","passageId":"li-ji_ch-14_p-12","order":2,"canonicalText":"殷人白馬，黑首。","chunks":[["殷人白馬，黑首。","zh-Hant"]]},{"id":"li-ji_ch-14_p-12_s-3","passageId":"li-ji_ch-14_p-12","order":3,"canonicalText":"周人黃馬，蕃鬣。","chunks":[["周人黃馬，蕃鬣。","zh-Hant"]]},{"id":"li-ji_ch-14_p-13_s-1","passageId":"li-ji_ch-14_p-13","order":1,"canonicalText":"夏后氏，牲尚黑，殷白牡，周騂剛。","chunks":[["夏后氏，牲尚黑，殷白牡，周騂剛。","zh-Hant"]]},{"id":"li-ji_ch-14_p-14_s-1","passageId":"li-ji_ch-14_p-14","order":1,"canonicalText":"泰，有虞氏之尊也。","chunks":[["泰，有虞氏之尊也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-14_s-2","passageId":"li-ji_ch-14_p-14","order":2,"canonicalText":"山罍，夏后氏之尊也。","chunks":[["山罍，夏后氏之尊也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-14_s-3","passageId":"li-ji_ch-14_p-14","order":3,"canonicalText":"著，殷尊也。","chunks":[["著，殷尊也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-14_s-4","passageId":"li-ji_ch-14_p-14","order":4,"canonicalText":"犧象，周尊也。","chunks":[["犧象，周尊也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-15_s-1","passageId":"li-ji_ch-14_p-15","order":1,"canonicalText":"爵，夏后氏以琖，殷以斝，周以爵。","chunks":[["爵，夏后氏以琖，殷以斝，周以爵。","zh-Hant"]]},{"id":"li-ji_ch-14_p-16_s-1","passageId":"li-ji_ch-14_p-16","order":1,"canonicalText":"灌尊，夏后氏以雞夷。","chunks":[["灌尊，夏后氏以雞夷。","zh-Hant"]]},{"id":"li-ji_ch-14_p-16_s-2","passageId":"li-ji_ch-14_p-16","order":2,"canonicalText":"殷以斝，周以黃目。","chunks":[["殷以斝，周以黃目。","zh-Hant"]]},{"id":"li-ji_ch-14_p-17_s-1","passageId":"li-ji_ch-14_p-17","order":1,"canonicalText":"其勺，夏后氏以龍勺，殷以疏勺，周以蒲勺。","chunks":[["其勺，夏后氏以龍勺，殷以疏勺，周以蒲勺。","zh-Hant"]]},{"id":"li-ji_ch-14_p-18_s-1","passageId":"li-ji_ch-14_p-18","order":1,"canonicalText":"土鼓蕢桴葦龠，伊耆氏之樂也。","chunks":[["土鼓蕢桴葦龠，伊耆氏之樂也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-18_s-2","passageId":"li-ji_ch-14_p-18","order":2,"canonicalText":"拊搏玉磬揩擊，大琴大瑟，中琴小瑟，四代之樂器也。","chunks":[["拊搏玉磬揩擊，大琴大瑟，中琴小瑟，四代之樂器也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-19_s-1","passageId":"li-ji_ch-14_p-19","order":1,"canonicalText":"魯公之廟，文世室也。","chunks":[["魯公之廟，文世室也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-19_s-2","passageId":"li-ji_ch-14_p-19","order":2,"canonicalText":"武公之廟，武世室也。","chunks":[["武公之廟，武世室也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-20_s-1","passageId":"li-ji_ch-14_p-20","order":1,"canonicalText":"米廩，有虞氏之庠也；","chunks":[["米廩，有虞氏之庠也；","zh-Hant"]]},{"id":"li-ji_ch-14_p-20_s-2","passageId":"li-ji_ch-14_p-20","order":2,"canonicalText":"序，夏后氏之序也；","chunks":[["序，夏后氏之序也；","zh-Hant"]]},{"id":"li-ji_ch-14_p-20_s-3","passageId":"li-ji_ch-14_p-20","order":3,"canonicalText":"瞽宗，殷學也；","chunks":[["瞽宗，殷學也；","zh-Hant"]]},{"id":"li-ji_ch-14_p-20_s-4","passageId":"li-ji_ch-14_p-20","order":4,"canonicalText":"頖宮，周學也。","chunks":[["頖宮，周學也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-21_s-1","passageId":"li-ji_ch-14_p-21","order":1,"canonicalText":"崇鼎，貫鼎，大璜，封父龜，天子之器也。","chunks":[["崇鼎，貫鼎，大璜，封父龜，天子之器也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-21_s-2","passageId":"li-ji_ch-14_p-21","order":2,"canonicalText":"越棘，大弓，天子之戎器也。","chunks":[["越棘，大弓，天子之戎器也。","zh-Hant"]]},{"id":"li-ji_ch-14_p-22_s-1","passageId":"li-ji_ch-14_p-22","order":1,"canonicalText":"夏后氏之鼓，足。","chunks":[["夏后氏之鼓，足。","zh-Hant"]]},{"id":"li-ji_ch-14_p-22_s-2","passageId":"li-ji_ch-14_p-22","order":2,"canonicalText":"殷，楹鼓；","chunks":[["殷，楹鼓；","zh-Hant"]]},{"id":"li-ji_ch-14_p-22_s-3","passageId":"li-ji_ch-14_p-22","order":3,"canonicalText":"周，縣鼓。","chunks":[["周，縣鼓。","zh-Hant"]]},{"id":"li-ji_ch-14_p-22_s-4","passageId":"li-ji_ch-14_p-22","order":4,"canonicalText":"垂之和鐘，叔之離磬，女媧之笙簧。","chunks":[["垂之和鐘，叔之離磬，女媧之笙簧。","zh-Hant"]]},{"id":"li-ji_ch-14_p-23_s-1","passageId":"li-ji_ch-14_p-23","order":1,"canonicalText":"夏后氏之龍簨虡，殷之崇牙，周之璧翣。","chunks":[["夏后氏之龍簨虡，殷之崇牙，周之璧翣。","zh-Hant"]]},{"id":"li-ji_ch-14_p-24_s-1","passageId":"li-ji_ch-14_p-24","order":1,"canonicalText":"有虞氏之兩敦，夏后氏之四連，殷之六瑚，周之八簋。","chunks":[["有虞氏之兩敦，夏后氏之四連，殷之六瑚，周之八簋。","zh-Hant"]]},{"id":"li-ji_ch-14_p-25_s-1","passageId":"li-ji_ch-14_p-25","order":1,"canonicalText":"俎，有虞氏以梡，夏后氏以嶡，殷以椇，周以房俎。","chunks":[["俎，有虞氏以梡，夏后氏以嶡，殷以椇，周以房俎。","zh-Hant"]]},{"id":"li-ji_ch-14_p-26_s-1","passageId":"li-ji_ch-14_p-26","order":1,"canonicalText":"夏后氏以楬豆，殷玉豆，周獻豆。","chunks":[["夏后氏以楬豆，殷玉豆，周獻豆。","zh-Hant"]]},{"id":"li-ji_ch-14_p-27_s-1","passageId":"li-ji_ch-14_p-27","order":1,"canonicalText":"有虞氏服韍，夏后氏山，殷火，周龍章。","chunks":[["有虞氏服韍，夏后氏山，殷火，周龍章。","zh-Hant"]]},{"id":"li-ji_ch-14_p-28_s-1","passageId":"li-ji_ch-14_p-28","order":1,"canonicalText":"有虞氏祭首，夏后氏祭心，殷祭肝，周祭肺。","chunks":[["有虞氏祭首，夏后氏祭心，殷祭肝，周祭肺。","zh-Hant"]]},{"id":"li-ji_ch-14_p-29_s-1","passageId":"li-ji_ch-14_p-29","order":1,"canonicalText":"夏后氏尚明水，殷尚醴，周尚酒。","chunks":[["夏后氏尚明水，殷尚醴，周尚酒。","zh-Hant"]]},{"id":"li-ji_ch-14_p-30_s-1","passageId":"li-ji_ch-14_p-30","order":1,"canonicalText":"有虞氏官五十，夏后氏官百，殷二百，周三百。","chunks":[["有虞氏官五十，夏后氏官百，殷二百，周三百。","zh-Hant"]]},{"id":"li-ji_ch-14_p-31_s-1","passageId":"li-ji_ch-14_p-31","order":1,"canonicalText":"有虞氏之綏，夏后氏之綢練，殷之崇牙，周之璧翣。","chunks":[["有虞氏之綏，夏后氏之綢練，殷之崇牙，周之璧翣。","zh-Hant"]]},{"id":"li-ji_ch-14_p-32_s-1","passageId":"li-ji_ch-14_p-32","order":1,"canonicalText":"凡四代之服、器、官，魯兼用之。","chunks":[["凡四代之服、器、官，魯兼用之。","zh-Hant"]]},{"id":"li-ji_ch-14_p-32_s-2","passageId":"li-ji_ch-14_p-32","order":2,"canonicalText":"是故，魯，王禮也，天下傳之久矣。","chunks":[["是故，魯，王禮也，天下傳之久矣。","zh-Hant"]]},{"id":"li-ji_ch-14_p-32_s-3","passageId":"li-ji_ch-14_p-32","order":3,"canonicalText":"君臣，未嘗相弒也；","chunks":[["君臣，未嘗相弒也；","zh-Hant"]]},{"id":"li-ji_ch-14_p-32_s-4","passageId":"li-ji_ch-14_p-32","order":4,"canonicalText":"禮樂刑法政俗，未嘗相變也，天下以為有道之國。","chunks":[["禮樂刑法政俗，未嘗相變也，天下以為有道之國。","zh-Hant"]]},{"id":"li-ji_ch-14_p-32_s-5","passageId":"li-ji_ch-14_p-32","order":5,"canonicalText":"是故，天下資禮樂焉。","chunks":[["是故，天下資禮樂焉。","zh-Hant"]]},{"id":"li-ji_ch-15_p-1_s-1","passageId":"li-ji_ch-15_p-1","order":1,"canonicalText":"斬衰，括髮以麻；","chunks":[["斬衰，括髮以麻；","zh-Hant"]]},{"id":"li-ji_ch-15_p-1_s-2","passageId":"li-ji_ch-15_p-1","order":2,"canonicalText":"為母，括髮以麻，免而以布。","chunks":[["為母，括髮以麻，免而以布。","zh-Hant"]]},{"id":"li-ji_ch-15_p-1_s-3","passageId":"li-ji_ch-15_p-1","order":3,"canonicalText":"齊衰，惡笄以終喪。","chunks":[["齊衰，惡笄以終喪。","zh-Hant"]]},{"id":"li-ji_ch-15_p-2_s-1","passageId":"li-ji_ch-15_p-2","order":1,"canonicalText":"男子冠而婦人笄，男子免而婦人髽。","chunks":[["男子冠而婦人笄，男子免而婦人髽。","zh-Hant"]]},{"id":"li-ji_ch-15_p-2_s-2","passageId":"li-ji_ch-15_p-2","order":2,"canonicalText":"其義：為男子則免，為婦人則髽。","chunks":[["其義：為男子則免，為婦人則髽。","zh-Hant"]]},{"id":"li-ji_ch-15_p-3_s-1","passageId":"li-ji_ch-15_p-3","order":1,"canonicalText":"苴杖，竹也；","chunks":[["苴杖，竹也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-3_s-2","passageId":"li-ji_ch-15_p-3","order":2,"canonicalText":"削杖，桐也。","chunks":[["削杖，桐也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-4_s-1","passageId":"li-ji_ch-15_p-4","order":1,"canonicalText":"祖父卒，而後為祖母后者三年。","chunks":[["祖父卒，而後為祖母后者三年。","zh-Hant"]]},{"id":"li-ji_ch-15_p-5_s-1","passageId":"li-ji_ch-15_p-5","order":1,"canonicalText":"為父母，長子稽顙。","chunks":[["為父母，長子稽顙。","zh-Hant"]]},{"id":"li-ji_ch-15_p-5_s-2","passageId":"li-ji_ch-15_p-5","order":2,"canonicalText":"大夫吊之，雖緦必稽顙。","chunks":[["大夫吊之，雖緦必稽顙。","zh-Hant"]]},{"id":"li-ji_ch-15_p-5_s-3","passageId":"li-ji_ch-15_p-5","order":3,"canonicalText":"婦人為夫與長子稽顙，其餘則否。","chunks":[["婦人為夫與長子稽顙，其餘則否。","zh-Hant"]]},{"id":"li-ji_ch-15_p-6_s-1","passageId":"li-ji_ch-15_p-6","order":1,"canonicalText":"男主必使同姓，婦主必使異姓。","chunks":[["男主必使同姓，婦主必使異姓。","zh-Hant"]]},{"id":"li-ji_ch-15_p-7_s-1","passageId":"li-ji_ch-15_p-7","order":1,"canonicalText":"為父後者為出母無服。","chunks":[["為父後者為出母無服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-8_s-1","passageId":"li-ji_ch-15_p-8","order":1,"canonicalText":"親親，以三為五，以五為九。","chunks":[["親親，以三為五，以五為九。","zh-Hant"]]},{"id":"li-ji_ch-15_p-8_s-2","passageId":"li-ji_ch-15_p-8","order":2,"canonicalText":"上殺，下殺，旁殺，而親畢矣。","chunks":[["上殺，下殺，旁殺，而親畢矣。","zh-Hant"]]},{"id":"li-ji_ch-15_p-9_s-1","passageId":"li-ji_ch-15_p-9","order":1,"canonicalText":"王者禘其祖之所自出，以其祖配之，而立四廟。","chunks":[["王者禘其祖之所自出，以其祖配之，而立四廟。","zh-Hant"]]},{"id":"li-ji_ch-15_p-9_s-2","passageId":"li-ji_ch-15_p-9","order":2,"canonicalText":"庶子王，亦如之。","chunks":[["庶子王，亦如之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-10_s-1","passageId":"li-ji_ch-15_p-10","order":1,"canonicalText":"別子為祖，繼別為宗，繼禰者為小宗。","chunks":[["別子為祖，繼別為宗，繼禰者為小宗。","zh-Hant"]]},{"id":"li-ji_ch-15_p-10_s-2","passageId":"li-ji_ch-15_p-10","order":2,"canonicalText":"有五世而遷之宗，其繼高祖者也。","chunks":[["有五世而遷之宗，其繼高祖者也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-10_s-3","passageId":"li-ji_ch-15_p-10","order":3,"canonicalText":"是故，祖遷於上，宗易於下。","chunks":[["是故，祖遷於上，宗易於下。","zh-Hant"]]},{"id":"li-ji_ch-15_p-10_s-4","passageId":"li-ji_ch-15_p-10","order":4,"canonicalText":"尊祖故敬宗，敬宗所以尊祖禰也。","chunks":[["尊祖故敬宗，敬宗所以尊祖禰也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-11_s-1","passageId":"li-ji_ch-15_p-11","order":1,"canonicalText":"庶子不祭祖者，明其宗也。","chunks":[["庶子不祭祖者，明其宗也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-11_s-2","passageId":"li-ji_ch-15_p-11","order":2,"canonicalText":"庶子不為長子斬，不繼祖與禰故也。","chunks":[["庶子不為長子斬，不繼祖與禰故也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-11_s-3","passageId":"li-ji_ch-15_p-11","order":3,"canonicalText":"庶子不祭殤與無後者，殤與無後者從祖祔食。","chunks":[["庶子不祭殤與無後者，殤與無後者從祖祔食。","zh-Hant"]]},{"id":"li-ji_ch-15_p-11_s-4","passageId":"li-ji_ch-15_p-11","order":4,"canonicalText":"庶子不祭禰者，明其宗也。","chunks":[["庶子不祭禰者，明其宗也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-12_s-1","passageId":"li-ji_ch-15_p-12","order":1,"canonicalText":"親親尊尊長長，男女之有別，人道之大者也。","chunks":[["親親尊尊長長，男女之有別，人道之大者也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-13_s-1","passageId":"li-ji_ch-15_p-13","order":1,"canonicalText":"從服者，所從亡則已。","chunks":[["從服者，所從亡則已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-13_s-2","passageId":"li-ji_ch-15_p-13","order":2,"canonicalText":"屬從者，所從雖沒也服。","chunks":[["屬從者，所從雖沒也服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-13_s-3","passageId":"li-ji_ch-15_p-13","order":3,"canonicalText":"妾從女君而出，則不為女君之子服。","chunks":[["妾從女君而出，則不為女君之子服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-14_s-1","passageId":"li-ji_ch-15_p-14","order":1,"canonicalText":"禮不王不禘。","chunks":[["禮不王不禘。","zh-Hant"]]},{"id":"li-ji_ch-15_p-15_s-1","passageId":"li-ji_ch-15_p-15","order":1,"canonicalText":"世子不降妻之父母；","chunks":[["世子不降妻之父母；","zh-Hant"]]},{"id":"li-ji_ch-15_p-15_s-2","passageId":"li-ji_ch-15_p-15","order":2,"canonicalText":"其為妻也，與大夫之適子同。","chunks":[["其為妻也，與大夫之適子同。","zh-Hant"]]},{"id":"li-ji_ch-15_p-16_s-1","passageId":"li-ji_ch-15_p-16","order":1,"canonicalText":"父為士，子為天子諸侯，則祭以天子諸侯，其尸服以士服。","chunks":[["父為士，子為天子諸侯，則祭以天子諸侯，其尸服以士服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-16_s-2","passageId":"li-ji_ch-15_p-16","order":2,"canonicalText":"父為天子諸侯，子為士，祭以士，其尸服以士服。","chunks":[["父為天子諸侯，子為士，祭以士，其尸服以士服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-17_s-1","passageId":"li-ji_ch-15_p-17","order":1,"canonicalText":"婦當喪而出，則除之。","chunks":[["婦當喪而出，則除之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-17_s-2","passageId":"li-ji_ch-15_p-17","order":2,"canonicalText":"為父母喪，未練而出，則三年。","chunks":[["為父母喪，未練而出，則三年。","zh-Hant"]]},{"id":"li-ji_ch-15_p-17_s-3","passageId":"li-ji_ch-15_p-17","order":3,"canonicalText":"既練而出，則已。","chunks":[["既練而出，則已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-17_s-4","passageId":"li-ji_ch-15_p-17","order":4,"canonicalText":"未練而反，則期；","chunks":[["未練而反，則期；","zh-Hant"]]},{"id":"li-ji_ch-15_p-17_s-5","passageId":"li-ji_ch-15_p-17","order":5,"canonicalText":"既練而反，則遂之。","chunks":[["既練而反，則遂之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-1","passageId":"li-ji_ch-15_p-18","order":1,"canonicalText":"再期之喪，三年也；","chunks":[["再期之喪，三年也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-2","passageId":"li-ji_ch-15_p-18","order":2,"canonicalText":"期之喪，二年也。","chunks":[["期之喪，二年也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-3","passageId":"li-ji_ch-15_p-18","order":3,"canonicalText":"九月七月之喪，三時也；","chunks":[["九月七月之喪，三時也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-4","passageId":"li-ji_ch-15_p-18","order":4,"canonicalText":"五月之喪，二時也；","chunks":[["五月之喪，二時也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-5","passageId":"li-ji_ch-15_p-18","order":5,"canonicalText":"三月之喪，一時也。","chunks":[["三月之喪，一時也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-6","passageId":"li-ji_ch-15_p-18","order":6,"canonicalText":"故期而祭，禮也；","chunks":[["故期而祭，禮也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-7","passageId":"li-ji_ch-15_p-18","order":7,"canonicalText":"期而除喪，道也。","chunks":[["期而除喪，道也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-18_s-8","passageId":"li-ji_ch-15_p-18","order":8,"canonicalText":"祭不為除喪也。","chunks":[["祭不為除喪也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-19_s-1","passageId":"li-ji_ch-15_p-19","order":1,"canonicalText":"三年而後葬者必再祭，其祭之間不同時而除喪。","chunks":[["三年而後葬者必再祭，其祭之間不同時而除喪。","zh-Hant"]]},{"id":"li-ji_ch-15_p-20_s-1","passageId":"li-ji_ch-15_p-20","order":1,"canonicalText":"大功者主人之喪，有三年者，則必為之再祭。","chunks":[["大功者主人之喪，有三年者，則必為之再祭。","zh-Hant"]]},{"id":"li-ji_ch-15_p-20_s-2","passageId":"li-ji_ch-15_p-20","order":2,"canonicalText":"朋友，虞祔而已。","chunks":[["朋友，虞祔而已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-21_s-1","passageId":"li-ji_ch-15_p-21","order":1,"canonicalText":"士妾有子，而為之緦，無子則已。","chunks":[["士妾有子，而為之緦，無子則已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-22_s-1","passageId":"li-ji_ch-15_p-22","order":1,"canonicalText":"生不及祖父母諸父昆弟，而父稅喪，己則否。","chunks":[["生不及祖父母諸父昆弟，而父稅喪，己則否。","zh-Hant"]]},{"id":"li-ji_ch-15_p-22_s-2","passageId":"li-ji_ch-15_p-22","order":2,"canonicalText":"降而在緦小功者，則稅之。","chunks":[["降而在緦小功者，則稅之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-23_s-1","passageId":"li-ji_ch-15_p-23","order":1,"canonicalText":"為君之父母、妻、長子，君已除喪而後聞喪，則不稅。","chunks":[["為君之父母、妻、長子，君已除喪而後聞喪，則不稅。","zh-Hant"]]},{"id":"li-ji_ch-15_p-23_s-2","passageId":"li-ji_ch-15_p-23","order":2,"canonicalText":"近臣，君服斯服矣；","chunks":[["近臣，君服斯服矣；","zh-Hant"]]},{"id":"li-ji_ch-15_p-23_s-3","passageId":"li-ji_ch-15_p-23","order":3,"canonicalText":"其餘，從而服，不從而稅。","chunks":[["其餘，從而服，不從而稅。","zh-Hant"]]},{"id":"li-ji_ch-15_p-23_s-4","passageId":"li-ji_ch-15_p-23","order":4,"canonicalText":"君雖未知喪，臣服已。","chunks":[["君雖未知喪，臣服已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-24_s-1","passageId":"li-ji_ch-15_p-24","order":1,"canonicalText":"虞，杖不入於室；","chunks":[["虞，杖不入於室；","zh-Hant"]]},{"id":"li-ji_ch-15_p-24_s-2","passageId":"li-ji_ch-15_p-24","order":2,"canonicalText":"祔，杖不升於堂。","chunks":[["祔，杖不升於堂。","zh-Hant"]]},{"id":"li-ji_ch-15_p-25_s-1","passageId":"li-ji_ch-15_p-25","order":1,"canonicalText":"為君母后者，君母卒，則不為君母之黨服。","chunks":[["為君母后者，君母卒，則不為君母之黨服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-26_s-1","passageId":"li-ji_ch-15_p-26","order":1,"canonicalText":"絰殺五分而去一，杖大如絰。","chunks":[["絰殺五分而去一，杖大如絰。","zh-Hant"]]},{"id":"li-ji_ch-15_p-27_s-1","passageId":"li-ji_ch-15_p-27","order":1,"canonicalText":"妾為君之長子與女君同。","chunks":[["妾為君之長子與女君同。","zh-Hant"]]},{"id":"li-ji_ch-15_p-28_s-1","passageId":"li-ji_ch-15_p-28","order":1,"canonicalText":"除喪者，先重者；","chunks":[["除喪者，先重者；","zh-Hant"]]},{"id":"li-ji_ch-15_p-28_s-2","passageId":"li-ji_ch-15_p-28","order":2,"canonicalText":"易服者，易輕者。","chunks":[["易服者，易輕者。","zh-Hant"]]},{"id":"li-ji_ch-15_p-29_s-1","passageId":"li-ji_ch-15_p-29","order":1,"canonicalText":"無事不辟廟門。","chunks":[["無事不辟廟門。","zh-Hant"]]},{"id":"li-ji_ch-15_p-29_s-2","passageId":"li-ji_ch-15_p-29","order":2,"canonicalText":"哭皆於其次。","chunks":[["哭皆於其次。","zh-Hant"]]},{"id":"li-ji_ch-15_p-30_s-1","passageId":"li-ji_ch-15_p-30","order":1,"canonicalText":"復與書銘，自天子達於士，其辭一也。","chunks":[["復與書銘，自天子達於士，其辭一也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-30_s-2","passageId":"li-ji_ch-15_p-30","order":2,"canonicalText":"男子稱名，婦人書姓與伯仲，如不知姓則書氏。","chunks":[["男子稱名，婦人書姓與伯仲，如不知姓則書氏。","zh-Hant"]]},{"id":"li-ji_ch-15_p-31_s-1","passageId":"li-ji_ch-15_p-31","order":1,"canonicalText":"斬衰之葛與齊衰之麻同。","chunks":[["斬衰之葛與齊衰之麻同。","zh-Hant"]]},{"id":"li-ji_ch-15_p-31_s-2","passageId":"li-ji_ch-15_p-31","order":2,"canonicalText":"齊衰之葛與大功之麻同。","chunks":[["齊衰之葛與大功之麻同。","zh-Hant"]]},{"id":"li-ji_ch-15_p-31_s-3","passageId":"li-ji_ch-15_p-31","order":3,"canonicalText":"麻同，皆兼服之。","chunks":[["麻同，皆兼服之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-32_s-1","passageId":"li-ji_ch-15_p-32","order":1,"canonicalText":"報葬者報虞，三月而後卒哭。","chunks":[["報葬者報虞，三月而後卒哭。","zh-Hant"]]},{"id":"li-ji_ch-15_p-33_s-1","passageId":"li-ji_ch-15_p-33","order":1,"canonicalText":"父母之喪偕，先葬者不虞祔，待後事。","chunks":[["父母之喪偕，先葬者不虞祔，待後事。","zh-Hant"]]},{"id":"li-ji_ch-15_p-33_s-2","passageId":"li-ji_ch-15_p-33","order":2,"canonicalText":"其葬，服斬衰。","chunks":[["其葬，服斬衰。","zh-Hant"]]},{"id":"li-ji_ch-15_p-34_s-1","passageId":"li-ji_ch-15_p-34","order":1,"canonicalText":"大夫降其庶子，其孫不降其父。","chunks":[["大夫降其庶子，其孫不降其父。","zh-Hant"]]},{"id":"li-ji_ch-15_p-34_s-2","passageId":"li-ji_ch-15_p-34","order":2,"canonicalText":"大夫不主士之喪。","chunks":[["大夫不主士之喪。","zh-Hant"]]},{"id":"li-ji_ch-15_p-35_s-1","passageId":"li-ji_ch-15_p-35","order":1,"canonicalText":"為慈母之父母無服。","chunks":[["為慈母之父母無服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-36_s-1","passageId":"li-ji_ch-15_p-36","order":1,"canonicalText":"夫為人後者，其妻為舅姑大功。","chunks":[["夫為人後者，其妻為舅姑大功。","zh-Hant"]]},{"id":"li-ji_ch-15_p-37_s-1","passageId":"li-ji_ch-15_p-37","order":1,"canonicalText":"士祔於大夫則易牲。","chunks":[["士祔於大夫則易牲。","zh-Hant"]]},{"id":"li-ji_ch-15_p-38_s-1","passageId":"li-ji_ch-15_p-38","order":1,"canonicalText":"繼父不同居也者；","chunks":[["繼父不同居也者；","zh-Hant"]]},{"id":"li-ji_ch-15_p-38_s-2","passageId":"li-ji_ch-15_p-38","order":2,"canonicalText":"必嘗同居。","chunks":[["必嘗同居。","zh-Hant"]]},{"id":"li-ji_ch-15_p-38_s-3","passageId":"li-ji_ch-15_p-38","order":3,"canonicalText":"皆無主後。","chunks":[["皆無主後。","zh-Hant"]]},{"id":"li-ji_ch-15_p-38_s-4","passageId":"li-ji_ch-15_p-38","order":4,"canonicalText":"同財而祭其祖禰為同居；","chunks":[["同財而祭其祖禰為同居；","zh-Hant"]]},{"id":"li-ji_ch-15_p-38_s-5","passageId":"li-ji_ch-15_p-38","order":5,"canonicalText":"有主後者為異居。","chunks":[["有主後者為異居。","zh-Hant"]]},{"id":"li-ji_ch-15_p-39_s-1","passageId":"li-ji_ch-15_p-39","order":1,"canonicalText":"哭朋友者於門外之右南面。","chunks":[["哭朋友者於門外之右南面。","zh-Hant"]]},{"id":"li-ji_ch-15_p-40_s-1","passageId":"li-ji_ch-15_p-40","order":1,"canonicalText":"祔葬者不筮宅。","chunks":[["祔葬者不筮宅。","zh-Hant"]]},{"id":"li-ji_ch-15_p-41_s-1","passageId":"li-ji_ch-15_p-41","order":1,"canonicalText":"士大夫不得祔於諸侯，祔於諸祖父之為士大夫者，其妻祔於諸祖姑，妾祔於妾祖姑；","chunks":[["士大夫不得祔於諸侯，祔於諸祖父之為士大夫者，其妻祔於諸祖姑，妾祔於妾祖姑；","zh-Hant"]]},{"id":"li-ji_ch-15_p-41_s-2","passageId":"li-ji_ch-15_p-41","order":2,"canonicalText":"亡則中一以上而祔。","chunks":[["亡則中一以上而祔。","zh-Hant"]]},{"id":"li-ji_ch-15_p-41_s-3","passageId":"li-ji_ch-15_p-41","order":3,"canonicalText":"祔必以其昭穆。","chunks":[["祔必以其昭穆。","zh-Hant"]]},{"id":"li-ji_ch-15_p-41_s-4","passageId":"li-ji_ch-15_p-41","order":4,"canonicalText":"諸侯不得祔於天子，天子、諸侯、大夫可以祔於士。","chunks":[["諸侯不得祔於天子，天子、諸侯、大夫可以祔於士。","zh-Hant"]]},{"id":"li-ji_ch-15_p-42_s-1","passageId":"li-ji_ch-15_p-42","order":1,"canonicalText":"為母之君母，母卒則不服。","chunks":[["為母之君母，母卒則不服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-43_s-1","passageId":"li-ji_ch-15_p-43","order":1,"canonicalText":"宗子，母在為妻禫。","chunks":[["宗子，母在為妻禫。","zh-Hant"]]},{"id":"li-ji_ch-15_p-44_s-1","passageId":"li-ji_ch-15_p-44","order":1,"canonicalText":"為慈母后者，為庶母可也，為祖庶母可也。","chunks":[["為慈母后者，為庶母可也，為祖庶母可也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-45_s-1","passageId":"li-ji_ch-15_p-45","order":1,"canonicalText":"為父、母、妻、長子禫。","chunks":[["為父、母、妻、長子禫。","zh-Hant"]]},{"id":"li-ji_ch-15_p-46_s-1","passageId":"li-ji_ch-15_p-46","order":1,"canonicalText":"慈母與妾母，不世祭也。","chunks":[["慈母與妾母，不世祭也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-47_s-1","passageId":"li-ji_ch-15_p-47","order":1,"canonicalText":"丈夫冠而不為殤，婦人笄而不為殤。","chunks":[["丈夫冠而不為殤，婦人笄而不為殤。","zh-Hant"]]},{"id":"li-ji_ch-15_p-47_s-2","passageId":"li-ji_ch-15_p-47","order":2,"canonicalText":"為殤後者，以其服服之。","chunks":[["為殤後者，以其服服之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-48_s-1","passageId":"li-ji_ch-15_p-48","order":1,"canonicalText":"久而不葬者，唯主喪者不除；","chunks":[["久而不葬者，唯主喪者不除；","zh-Hant"]]},{"id":"li-ji_ch-15_p-48_s-2","passageId":"li-ji_ch-15_p-48","order":2,"canonicalText":"其餘以麻終月數者，除喪則已。","chunks":[["其餘以麻終月數者，除喪則已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-49_s-1","passageId":"li-ji_ch-15_p-49","order":1,"canonicalText":"箭笄終喪三年。","chunks":[["箭笄終喪三年。","zh-Hant"]]},{"id":"li-ji_ch-15_p-50_s-1","passageId":"li-ji_ch-15_p-50","order":1,"canonicalText":"齊衰三月與大功同者，繩屨。","chunks":[["齊衰三月與大功同者，繩屨。","zh-Hant"]]},{"id":"li-ji_ch-15_p-51_s-1","passageId":"li-ji_ch-15_p-51","order":1,"canonicalText":"練，筮日筮尸，視濯，皆要絰杖繩屨。","chunks":[["練，筮日筮尸，視濯，皆要絰杖繩屨。","zh-Hant"]]},{"id":"li-ji_ch-15_p-51_s-2","passageId":"li-ji_ch-15_p-51","order":2,"canonicalText":"有司告具，而後去杖。","chunks":[["有司告具，而後去杖。","zh-Hant"]]},{"id":"li-ji_ch-15_p-51_s-3","passageId":"li-ji_ch-15_p-51","order":3,"canonicalText":"筮日筮尸，有司告事畢而後杖，拜送賓。","chunks":[["筮日筮尸，有司告事畢而後杖，拜送賓。","zh-Hant"]]},{"id":"li-ji_ch-15_p-51_s-4","passageId":"li-ji_ch-15_p-51","order":4,"canonicalText":"大祥，吉服而筮尸。","chunks":[["大祥，吉服而筮尸。","zh-Hant"]]},{"id":"li-ji_ch-15_p-52_s-1","passageId":"li-ji_ch-15_p-52","order":1,"canonicalText":"庶子在父之室，則為其母不禫。","chunks":[["庶子在父之室，則為其母不禫。","zh-Hant"]]},{"id":"li-ji_ch-15_p-52_s-2","passageId":"li-ji_ch-15_p-52","order":2,"canonicalText":"庶子不以杖即位。","chunks":[["庶子不以杖即位。","zh-Hant"]]},{"id":"li-ji_ch-15_p-52_s-3","passageId":"li-ji_ch-15_p-52","order":3,"canonicalText":"父不主庶子之喪，則孫以杖即位可也。","chunks":[["父不主庶子之喪，則孫以杖即位可也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-52_s-4","passageId":"li-ji_ch-15_p-52","order":4,"canonicalText":"父在，庶子為妻以杖即位可也。","chunks":[["父在，庶子為妻以杖即位可也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-53_s-1","passageId":"li-ji_ch-15_p-53","order":1,"canonicalText":"諸侯吊於異國之臣，則其君為主。","chunks":[["諸侯吊於異國之臣，則其君為主。","zh-Hant"]]},{"id":"li-ji_ch-15_p-54_s-1","passageId":"li-ji_ch-15_p-54","order":1,"canonicalText":"諸侯吊，必皮弁錫衰。","chunks":[["諸侯吊，必皮弁錫衰。","zh-Hant"]]},{"id":"li-ji_ch-15_p-54_s-2","passageId":"li-ji_ch-15_p-54","order":2,"canonicalText":"所吊雖已葬，主人必免。","chunks":[["所吊雖已葬，主人必免。","zh-Hant"]]},{"id":"li-ji_ch-15_p-54_s-3","passageId":"li-ji_ch-15_p-54","order":3,"canonicalText":"主人未喪服，則君於不錫衰。","chunks":[["主人未喪服，則君於不錫衰。","zh-Hant"]]},{"id":"li-ji_ch-15_p-55_s-1","passageId":"li-ji_ch-15_p-55","order":1,"canonicalText":"養有疾者不喪服，遂以主其喪。","chunks":[["養有疾者不喪服，遂以主其喪。","zh-Hant"]]},{"id":"li-ji_ch-15_p-55_s-2","passageId":"li-ji_ch-15_p-55","order":2,"canonicalText":"非養者入主人之喪，則不易己之喪服。","chunks":[["非養者入主人之喪，則不易己之喪服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-55_s-3","passageId":"li-ji_ch-15_p-55","order":3,"canonicalText":"養尊者必易服，養卑者否。","chunks":[["養尊者必易服，養卑者否。","zh-Hant"]]},{"id":"li-ji_ch-15_p-56_s-1","passageId":"li-ji_ch-15_p-56","order":1,"canonicalText":"妾無妾祖姑者，易牲而祔於女君可也。","chunks":[["妾無妾祖姑者，易牲而祔於女君可也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-57_s-1","passageId":"li-ji_ch-15_p-57","order":1,"canonicalText":"婦之喪、虞、卒哭，其夫若子主之。","chunks":[["婦之喪、虞、卒哭，其夫若子主之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-57_s-2","passageId":"li-ji_ch-15_p-57","order":2,"canonicalText":"祔，則舅主之。","chunks":[["祔，則舅主之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-58_s-1","passageId":"li-ji_ch-15_p-58","order":1,"canonicalText":"士不攝大夫。","chunks":[["士不攝大夫。","zh-Hant"]]},{"id":"li-ji_ch-15_p-58_s-2","passageId":"li-ji_ch-15_p-58","order":2,"canonicalText":"士攝大夫，唯宗子。","chunks":[["士攝大夫，唯宗子。","zh-Hant"]]},{"id":"li-ji_ch-15_p-59_s-1","passageId":"li-ji_ch-15_p-59","order":1,"canonicalText":"主人未除喪，有兄弟自他國至，則主人不免而為主。","chunks":[["主人未除喪，有兄弟自他國至，則主人不免而為主。","zh-Hant"]]},{"id":"li-ji_ch-15_p-60_s-1","passageId":"li-ji_ch-15_p-60","order":1,"canonicalText":"陳器之道，多陳之而省納之可也；","chunks":[["陳器之道，多陳之而省納之可也；","zh-Hant"]]},{"id":"li-ji_ch-15_p-60_s-2","passageId":"li-ji_ch-15_p-60","order":2,"canonicalText":"省陳之而盡納之可也。","chunks":[["省陳之而盡納之可也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-61_s-1","passageId":"li-ji_ch-15_p-61","order":1,"canonicalText":"奔兄弟之喪，先之墓而後之家，為位而哭。","chunks":[["奔兄弟之喪，先之墓而後之家，為位而哭。","zh-Hant"]]},{"id":"li-ji_ch-15_p-61_s-2","passageId":"li-ji_ch-15_p-61","order":2,"canonicalText":"所知之喪，則哭於宮而後之墓。","chunks":[["所知之喪，則哭於宮而後之墓。","zh-Hant"]]},{"id":"li-ji_ch-15_p-62_s-1","passageId":"li-ji_ch-15_p-62","order":1,"canonicalText":"父不為眾子次於外。","chunks":[["父不為眾子次於外。","zh-Hant"]]},{"id":"li-ji_ch-15_p-63_s-1","passageId":"li-ji_ch-15_p-63","order":1,"canonicalText":"與諸侯為兄弟者服斬。","chunks":[["與諸侯為兄弟者服斬。","zh-Hant"]]},{"id":"li-ji_ch-15_p-64_s-1","passageId":"li-ji_ch-15_p-64","order":1,"canonicalText":"下殤小功，帶，澡麻不絕本，詘而反以報之。","chunks":[["下殤小功，帶，澡麻不絕本，詘而反以報之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-65_s-1","passageId":"li-ji_ch-15_p-65","order":1,"canonicalText":"婦祔於祖姑，祖姑有三人，則祔於親者。","chunks":[["婦祔於祖姑，祖姑有三人，則祔於親者。","zh-Hant"]]},{"id":"li-ji_ch-15_p-66_s-1","passageId":"li-ji_ch-15_p-66","order":1,"canonicalText":"其妻為大夫而卒，而後其夫不為大夫，而祔於其妻則不易牲。","chunks":[["其妻為大夫而卒，而後其夫不為大夫，而祔於其妻則不易牲。","zh-Hant"]]},{"id":"li-ji_ch-15_p-67_s-1","passageId":"li-ji_ch-15_p-67","order":1,"canonicalText":"為父後者，為出母無服。","chunks":[["為父後者，為出母無服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-67_s-2","passageId":"li-ji_ch-15_p-67","order":2,"canonicalText":"無服也者，喪者不祭故也。","chunks":[["無服也者，喪者不祭故也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-68_s-1","passageId":"li-ji_ch-15_p-68","order":1,"canonicalText":"婦人不為主而杖者：姑在為夫杖，母為長子削杖。","chunks":[["婦人不為主而杖者：姑在為夫杖，母為長子削杖。","zh-Hant"]]},{"id":"li-ji_ch-15_p-68_s-2","passageId":"li-ji_ch-15_p-68","order":2,"canonicalText":"女子子在室為父母，其主喪者不杖，則子一人杖。","chunks":[["女子子在室為父母，其主喪者不杖，則子一人杖。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-1","passageId":"li-ji_ch-15_p-69","order":1,"canonicalText":"緦小功，虞卒哭則免。","chunks":[["緦小功，虞卒哭則免。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-2","passageId":"li-ji_ch-15_p-69","order":2,"canonicalText":"既葬而不報虞，則雖主人皆冠，及虞則皆免。","chunks":[["既葬而不報虞，則雖主人皆冠，及虞則皆免。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-3","passageId":"li-ji_ch-15_p-69","order":3,"canonicalText":"為兄弟既除喪已。","chunks":[["為兄弟既除喪已。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-4","passageId":"li-ji_ch-15_p-69","order":4,"canonicalText":"及其葬也，反服其服。","chunks":[["及其葬也，反服其服。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-5","passageId":"li-ji_ch-15_p-69","order":5,"canonicalText":"報虞卒哭則免。","chunks":[["報虞卒哭則免。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-6","passageId":"li-ji_ch-15_p-69","order":6,"canonicalText":"如不報虞則除之。","chunks":[["如不報虞則除之。","zh-Hant"]]},{"id":"li-ji_ch-15_p-69_s-7","passageId":"li-ji_ch-15_p-69","order":7,"canonicalText":"遠葬者比反哭者皆冠，及郊而後免反哭。","chunks":[["遠葬者比反哭者皆冠，及郊而後免反哭。","zh-Hant"]]},{"id":"li-ji_ch-15_p-70_s-1","passageId":"li-ji_ch-15_p-70","order":1,"canonicalText":"君吊，雖不當免時也，主人必免，不散麻。","chunks":[["君吊，雖不當免時也，主人必免，不散麻。","zh-Hant"]]},{"id":"li-ji_ch-15_p-70_s-2","passageId":"li-ji_ch-15_p-70","order":2,"canonicalText":"雖異國之君，免也。","chunks":[["雖異國之君，免也。","zh-Hant"]]},{"id":"li-ji_ch-15_p-70_s-3","passageId":"li-ji_ch-15_p-70","order":3,"canonicalText":"親者皆免。","chunks":[["親者皆免。","zh-Hant"]]},{"id":"li-ji_ch-15_p-71_s-1","passageId":"li-ji_ch-15_p-71","order":1,"canonicalText":"除殤之喪者，其祭也必玄。","chunks":[["除殤之喪者，其祭也必玄。","zh-Hant"]]},{"id":"li-ji_ch-15_p-71_s-2","passageId":"li-ji_ch-15_p-71","order":2,"canonicalText":"除成喪者，其祭也朝服縞冠。","chunks":[["除成喪者，其祭也朝服縞冠。","zh-Hant"]]},{"id":"li-ji_ch-15_p-72_s-1","passageId":"li-ji_ch-15_p-72","order":1,"canonicalText":"奔父之喪，括髮於堂上，袒降踴，襲絰于東方。","chunks":[["奔父之喪，括髮於堂上，袒降踴，襲絰于東方。","zh-Hant"]]},{"id":"li-ji_ch-15_p-72_s-2","passageId":"li-ji_ch-15_p-72","order":2,"canonicalText":"奔母之喪，不括髮，袒於堂上，降踴，襲免于東方。","chunks":[["奔母之喪，不括髮，袒於堂上，降踴，襲免于東方。","zh-Hant"]]},{"id":"li-ji_ch-15_p-72_s-3","passageId":"li-ji_ch-15_p-72","order":3,"canonicalText":"絰即位成踴，出門哭止。","chunks":[["絰即位成踴，出門哭止。","zh-Hant"]]},{"id":"li-ji_ch-15_p-72_s-4","passageId":"li-ji_ch-15_p-72","order":4,"canonicalText":"三日而五哭三袒。","chunks":[["三日而五哭三袒。","zh-Hant"]]},{"id":"li-ji_ch-15_p-73_s-1","passageId":"li-ji_ch-15_p-73","order":1,"canonicalText":"適婦不為舅後者，則姑為之小功。","chunks":[["適婦不為舅後者，則姑為之小功。","zh-Hant"]]},{"id":"li-ji_ch-16_p-1_s-1","passageId":"li-ji_ch-16_p-1","order":1,"canonicalText":"禮：不王不禘。","chunks":[["禮：不王不禘。","zh-Hant"]]},{"id":"li-ji_ch-16_p-1_s-2","passageId":"li-ji_ch-16_p-1","order":2,"canonicalText":"王者禘其祖之所自出，以其祖配之。","chunks":[["王者禘其祖之所自出，以其祖配之。","zh-Hant"]]},{"id":"li-ji_ch-16_p-1_s-3","passageId":"li-ji_ch-16_p-1","order":3,"canonicalText":"諸侯及其大祖，大夫士有大事，省於其君，干祫，及其高祖。","chunks":[["諸侯及其大祖，大夫士有大事，省於其君，干祫，及其高祖。","zh-Hant"]]},{"id":"li-ji_ch-16_p-2_s-1","passageId":"li-ji_ch-16_p-2","order":1,"canonicalText":"牧之野，武王之大事也。","chunks":[["牧之野，武王之大事也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-2_s-2","passageId":"li-ji_ch-16_p-2","order":2,"canonicalText":"既事而退，柴於上帝，祈於社，設奠於牧室。","chunks":[["既事而退，柴於上帝，祈於社，設奠於牧室。","zh-Hant"]]},{"id":"li-ji_ch-16_p-2_s-3","passageId":"li-ji_ch-16_p-2","order":3,"canonicalText":"遂率天下諸侯，執豆籩，逡奔走；","chunks":[["遂率天下諸侯，執豆籩，逡奔走；","zh-Hant"]]},{"id":"li-ji_ch-16_p-2_s-4","passageId":"li-ji_ch-16_p-2","order":4,"canonicalText":"追王大王亶父、王季歷、文王昌；","chunks":[["追王大王亶父、王季歷、文王昌；","zh-Hant"]]},{"id":"li-ji_ch-16_p-2_s-5","passageId":"li-ji_ch-16_p-2","order":5,"canonicalText":"不以卑臨尊也。","chunks":[["不以卑臨尊也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-3_s-1","passageId":"li-ji_ch-16_p-3","order":1,"canonicalText":"上治祖禰，尊尊也；","chunks":[["上治祖禰，尊尊也；","zh-Hant"]]},{"id":"li-ji_ch-16_p-3_s-2","passageId":"li-ji_ch-16_p-3","order":2,"canonicalText":"下治子孫，親親也；","chunks":[["下治子孫，親親也；","zh-Hant"]]},{"id":"li-ji_ch-16_p-3_s-3","passageId":"li-ji_ch-16_p-3","order":3,"canonicalText":"旁治昆弟，合族以食，序以昭繆，別之以禮義，人道竭矣。","chunks":[["旁治昆弟，合族以食，序以昭繆，別之以禮義，人道竭矣。","zh-Hant"]]},{"id":"li-ji_ch-16_p-4_s-1","passageId":"li-ji_ch-16_p-4","order":1,"canonicalText":"聖人南面而聽天下，所且先者五，民不與焉。","chunks":[["聖人南面而聽天下，所且先者五，民不與焉。","zh-Hant"]]},{"id":"li-ji_ch-16_p-4_s-2","passageId":"li-ji_ch-16_p-4","order":2,"canonicalText":"一曰治親，二曰報功，三曰舉賢，四曰使能，五曰存愛。","chunks":[["一曰治親，二曰報功，三曰舉賢，四曰使能，五曰存愛。","zh-Hant"]]},{"id":"li-ji_ch-16_p-4_s-3","passageId":"li-ji_ch-16_p-4","order":3,"canonicalText":"五者一得於天下，民無不足、無不贍者。","chunks":[["五者一得於天下，民無不足、無不贍者。","zh-Hant"]]},{"id":"li-ji_ch-16_p-4_s-4","passageId":"li-ji_ch-16_p-4","order":4,"canonicalText":"五者，一物紕繆，民莫得其死。","chunks":[["五者，一物紕繆，民莫得其死。","zh-Hant"]]},{"id":"li-ji_ch-16_p-4_s-5","passageId":"li-ji_ch-16_p-4","order":5,"canonicalText":"聖人南面而治天下，必自人道始矣。","chunks":[["聖人南面而治天下，必自人道始矣。","zh-Hant"]]},{"id":"li-ji_ch-16_p-5_s-1","passageId":"li-ji_ch-16_p-5","order":1,"canonicalText":"立權度量，考文章，改正朔，易服色，殊徽號，異器械，別衣服，此其所得與民變革者也。","chunks":[["立權度量，考文章，改正朔，易服色，殊徽號，異器械，別衣服，此其所得與民變革者也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-5_s-2","passageId":"li-ji_ch-16_p-5","order":2,"canonicalText":"其不可得變革者則有矣：親親也，尊尊也，長長也，男女有別，此其不可得與民變革者也。","chunks":[["其不可得變革者則有矣：親親也，尊尊也，長長也，男女有別，此其不可得與民變革者也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-1","passageId":"li-ji_ch-16_p-6","order":1,"canonicalText":"同姓從宗，合族屬；","chunks":[["同姓從宗，合族屬；","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-2","passageId":"li-ji_ch-16_p-6","order":2,"canonicalText":"異姓主名，治際會。","chunks":[["異姓主名，治際會。","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-3","passageId":"li-ji_ch-16_p-6","order":3,"canonicalText":"名著，而男女有別。","chunks":[["名著，而男女有別。","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-4","passageId":"li-ji_ch-16_p-6","order":4,"canonicalText":"其夫屬乎父道者，妻皆母道也；","chunks":[["其夫屬乎父道者，妻皆母道也；","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-5","passageId":"li-ji_ch-16_p-6","order":5,"canonicalText":"其夫屬乎子道者，妻皆婦道也。","chunks":[["其夫屬乎子道者，妻皆婦道也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-6","passageId":"li-ji_ch-16_p-6","order":6,"canonicalText":"謂弟之妻「婦」者，是嫂亦可謂之「母」乎？","chunks":[["謂弟之妻「婦」者，是嫂亦可謂之「母」乎？","zh-Hant"]]},{"id":"li-ji_ch-16_p-6_s-7","passageId":"li-ji_ch-16_p-6","order":7,"canonicalText":"名者人治之大者也，可無慎乎？","chunks":[["名者人治之大者也，可無慎乎？","zh-Hant"]]},{"id":"li-ji_ch-16_p-7_s-1","passageId":"li-ji_ch-16_p-7","order":1,"canonicalText":"四世而緦，服之窮也；","chunks":[["四世而緦，服之窮也；","zh-Hant"]]},{"id":"li-ji_ch-16_p-7_s-2","passageId":"li-ji_ch-16_p-7","order":2,"canonicalText":"五世袒免，殺同姓也。","chunks":[["五世袒免，殺同姓也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-7_s-3","passageId":"li-ji_ch-16_p-7","order":3,"canonicalText":"六世，親屬竭矣。","chunks":[["六世，親屬竭矣。","zh-Hant"]]},{"id":"li-ji_ch-16_p-7_s-4","passageId":"li-ji_ch-16_p-7","order":4,"canonicalText":"其庶姓別於上，而戚單於下，昏姻可以通乎？","chunks":[["其庶姓別於上，而戚單於下，昏姻可以通乎？","zh-Hant"]]},{"id":"li-ji_ch-16_p-7_s-5","passageId":"li-ji_ch-16_p-7","order":5,"canonicalText":"系之以姓而弗別，綴之以食而弗殊，雖百世而昏姻不通者，周道然也。","chunks":[["系之以姓而弗別，綴之以食而弗殊，雖百世而昏姻不通者，周道然也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-8_s-1","passageId":"li-ji_ch-16_p-8","order":1,"canonicalText":"服術有六：一曰親親，二曰尊尊，三曰名，四曰出入，五曰長幼，六曰從服。","chunks":[["服術有六：一曰親親，二曰尊尊，三曰名，四曰出入，五曰長幼，六曰從服。","zh-Hant"]]},{"id":"li-ji_ch-16_p-9_s-1","passageId":"li-ji_ch-16_p-9","order":1,"canonicalText":"從服有六：有屬從，有徒從，有從有服而無服，有從無服而有服，有從重而輕，有從輕而重。","chunks":[["從服有六：有屬從，有徒從，有從有服而無服，有從無服而有服，有從重而輕，有從輕而重。","zh-Hant"]]},{"id":"li-ji_ch-16_p-10_s-1","passageId":"li-ji_ch-16_p-10","order":1,"canonicalText":"自仁率親，等而上之，至于祖，名曰輕。","chunks":[["自仁率親，等而上之，至于祖，名曰輕。","zh-Hant"]]},{"id":"li-ji_ch-16_p-10_s-2","passageId":"li-ji_ch-16_p-10","order":2,"canonicalText":"自義率祖，順而下之，至于禰，名曰重。","chunks":[["自義率祖，順而下之，至于禰，名曰重。","zh-Hant"]]},{"id":"li-ji_ch-16_p-10_s-3","passageId":"li-ji_ch-16_p-10","order":3,"canonicalText":"一輕一重，其義然也。","chunks":[["一輕一重，其義然也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-11_s-1","passageId":"li-ji_ch-16_p-11","order":1,"canonicalText":"君有合族之道，族人不得以其戚戚君，位也。","chunks":[["君有合族之道，族人不得以其戚戚君，位也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-12_s-1","passageId":"li-ji_ch-16_p-12","order":1,"canonicalText":"庶子不祭，明其宗也。","chunks":[["庶子不祭，明其宗也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-12_s-2","passageId":"li-ji_ch-16_p-12","order":2,"canonicalText":"庶子不得為長子三年，不繼祖也。","chunks":[["庶子不得為長子三年，不繼祖也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-13_s-1","passageId":"li-ji_ch-16_p-13","order":1,"canonicalText":"別子為祖，繼別為宗，繼禰者為小宗。","chunks":[["別子為祖，繼別為宗，繼禰者為小宗。","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-1","passageId":"li-ji_ch-16_p-14","order":1,"canonicalText":"有百世不遷之宗，有五世則遷之宗。","chunks":[["有百世不遷之宗，有五世則遷之宗。","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-2","passageId":"li-ji_ch-16_p-14","order":2,"canonicalText":"百世不遷者，別子之後也；","chunks":[["百世不遷者，別子之後也；","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-3","passageId":"li-ji_ch-16_p-14","order":3,"canonicalText":"宗其繼別子者，百世不遷者也。","chunks":[["宗其繼別子者，百世不遷者也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-4","passageId":"li-ji_ch-16_p-14","order":4,"canonicalText":"宗其繼高祖者，五世則遷者也。","chunks":[["宗其繼高祖者，五世則遷者也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-5","passageId":"li-ji_ch-16_p-14","order":5,"canonicalText":"尊祖故敬宗。","chunks":[["尊祖故敬宗。","zh-Hant"]]},{"id":"li-ji_ch-16_p-14_s-6","passageId":"li-ji_ch-16_p-14","order":6,"canonicalText":"敬宗，尊祖之義也。","chunks":[["敬宗，尊祖之義也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-15_s-1","passageId":"li-ji_ch-16_p-15","order":1,"canonicalText":"有小宗而無大宗者，有大宗而無小宗者，有無宗亦莫之宗者，公子是也。","chunks":[["有小宗而無大宗者，有大宗而無小宗者，有無宗亦莫之宗者，公子是也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-15_s-2","passageId":"li-ji_ch-16_p-15","order":2,"canonicalText":"公子有宗道：公子之公，為其士大夫之庶者，宗其士大夫之適者，公子之宗道也。","chunks":[["公子有宗道：公子之公，為其士大夫之庶者，宗其士大夫之適者，公子之宗道也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-16_s-1","passageId":"li-ji_ch-16_p-16","order":1,"canonicalText":"絕族無移服，親者屬也。","chunks":[["絕族無移服，親者屬也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-17_s-1","passageId":"li-ji_ch-16_p-17","order":1,"canonicalText":"自仁率親，等而上之，至于祖；","chunks":[["自仁率親，等而上之，至于祖；","zh-Hant"]]},{"id":"li-ji_ch-16_p-17_s-2","passageId":"li-ji_ch-16_p-17","order":2,"canonicalText":"自義率祖，順而下之，至於禰。","chunks":[["自義率祖，順而下之，至於禰。","zh-Hant"]]},{"id":"li-ji_ch-16_p-17_s-3","passageId":"li-ji_ch-16_p-17","order":3,"canonicalText":"是故，人道親親也。","chunks":[["是故，人道親親也。","zh-Hant"]]},{"id":"li-ji_ch-16_p-18_s-1","passageId":"li-ji_ch-16_p-18","order":1,"canonicalText":"親親故尊祖，尊祖故敬宗，敬宗故收族，收族故宗廟嚴，宗廟嚴故重社稷，重社稷故愛百姓，愛百姓故刑罰中，刑罰中故庶民安，庶民安故財用足，財用足故百志成，百志成故禮俗刑，禮俗刑然後樂。","chunks":[["親親故尊祖，尊祖故敬宗，敬宗故收族，收族故宗廟嚴，宗廟嚴故重社稷，重社稷故愛百姓，愛百姓故刑罰中，刑罰中故庶民安，庶民安故財用足，財用足故百志成，百志成故禮俗刑，禮俗刑然後樂。","zh-Hant"]]},{"id":"li-ji_ch-16_p-18_s-2","passageId":"li-ji_ch-16_p-18","order":2,"canonicalText":"《詩》云：「不顯不承，無斁於人斯」，此之謂也。","chunks":[["《詩》云：「不顯不承，無斁於人斯」，此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-1","passageId":"li-ji_ch-17_p-1","order":1,"canonicalText":"聞始見君子者，辭曰：「某固愿聞名於將命者。","chunks":[["聞始見君子者，辭曰：「某固愿聞名於將命者。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-2","passageId":"li-ji_ch-17_p-1","order":2,"canonicalText":"」不得階主。","chunks":[["」不得階主。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-3","passageId":"li-ji_ch-17_p-1","order":3,"canonicalText":"敵者曰：「某固愿見。","chunks":[["敵者曰：「某固愿見。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-4","passageId":"li-ji_ch-17_p-1","order":4,"canonicalText":"」罕見曰：「聞名」。","chunks":[["」罕見曰：「聞名」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-5","passageId":"li-ji_ch-17_p-1","order":5,"canonicalText":"亟見曰：「朝夕」。","chunks":[["亟見曰：「朝夕」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-6","passageId":"li-ji_ch-17_p-1","order":6,"canonicalText":"瞽曰：「聞名」。","chunks":[["瞽曰：「聞名」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-7","passageId":"li-ji_ch-17_p-1","order":7,"canonicalText":"適有喪者曰：「比」。","chunks":[["適有喪者曰：「比」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-8","passageId":"li-ji_ch-17_p-1","order":8,"canonicalText":"童子曰：「聽事」。","chunks":[["童子曰：「聽事」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-1_s-9","passageId":"li-ji_ch-17_p-1","order":9,"canonicalText":"適公卿之喪，則曰：「聽役於司徒」。","chunks":[["適公卿之喪，則曰：「聽役於司徒」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-1","passageId":"li-ji_ch-17_p-2","order":1,"canonicalText":"君將適他，臣如致金玉貨貝於君，則曰：「致馬資於有司」；","chunks":[["君將適他，臣如致金玉貨貝於君，則曰：「致馬資於有司」；","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-2","passageId":"li-ji_ch-17_p-2","order":2,"canonicalText":"敵者曰：「贈從者」。","chunks":[["敵者曰：「贈從者」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-3","passageId":"li-ji_ch-17_p-2","order":3,"canonicalText":"臣致禭於君，則曰：「致廢衣於賈人」；","chunks":[["臣致禭於君，則曰：「致廢衣於賈人」；","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-4","passageId":"li-ji_ch-17_p-2","order":4,"canonicalText":"敵者曰：「襚」。","chunks":[["敵者曰：「襚」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-5","passageId":"li-ji_ch-17_p-2","order":5,"canonicalText":"親者兄弟不，以襚進。","chunks":[["親者兄弟不，以襚進。","zh-Hant"]]},{"id":"li-ji_ch-17_p-2_s-6","passageId":"li-ji_ch-17_p-2","order":6,"canonicalText":"臣為君喪，納貨貝於君，則曰：「納甸於有司」。","chunks":[["臣為君喪，納貨貝於君，則曰：「納甸於有司」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-3_s-1","passageId":"li-ji_ch-17_p-3","order":1,"canonicalText":"賵馬入廟門；","chunks":[["賵馬入廟門；","zh-Hant"]]},{"id":"li-ji_ch-17_p-3_s-2","passageId":"li-ji_ch-17_p-3","order":2,"canonicalText":"賻馬與其幣，大白兵車，不入廟門。","chunks":[["賻馬與其幣，大白兵車，不入廟門。","zh-Hant"]]},{"id":"li-ji_ch-17_p-3_s-3","passageId":"li-ji_ch-17_p-3","order":3,"canonicalText":"賻者既致命，坐委之，擯者舉之。","chunks":[["賻者既致命，坐委之，擯者舉之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-3_s-4","passageId":"li-ji_ch-17_p-3","order":4,"canonicalText":"主人無親受也。","chunks":[["主人無親受也。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-1","passageId":"li-ji_ch-17_p-4","order":1,"canonicalText":"受立，授立不坐。","chunks":[["受立，授立不坐。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-2","passageId":"li-ji_ch-17_p-4","order":2,"canonicalText":"性之直者則有之矣。","chunks":[["性之直者則有之矣。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-3","passageId":"li-ji_ch-17_p-4","order":3,"canonicalText":"始入而辭，曰：「辭矣」。","chunks":[["始入而辭，曰：「辭矣」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-4","passageId":"li-ji_ch-17_p-4","order":4,"canonicalText":"即席，曰：「可矣」。","chunks":[["即席，曰：「可矣」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-5","passageId":"li-ji_ch-17_p-4","order":5,"canonicalText":"排闔說屨於戶內者，一人而已矣。","chunks":[["排闔說屨於戶內者，一人而已矣。","zh-Hant"]]},{"id":"li-ji_ch-17_p-4_s-6","passageId":"li-ji_ch-17_p-4","order":6,"canonicalText":"有尊長在則否。","chunks":[["有尊長在則否。","zh-Hant"]]},{"id":"li-ji_ch-17_p-5_s-1","passageId":"li-ji_ch-17_p-5","order":1,"canonicalText":"問品味曰：「子亟食於某乎？","chunks":[["問品味曰：「子亟食於某乎？","zh-Hant"]]},{"id":"li-ji_ch-17_p-5_s-2","passageId":"li-ji_ch-17_p-5","order":2,"canonicalText":"」問道藝曰：「子習於某乎？","chunks":[["」問道藝曰：「子習於某乎？","zh-Hant"]]},{"id":"li-ji_ch-17_p-5_s-3","passageId":"li-ji_ch-17_p-5","order":3,"canonicalText":"」、「子善於某乎？","chunks":[["」、「子善於某乎？","zh-Hant"]]},{"id":"li-ji_ch-17_p-5_s-4","passageId":"li-ji_ch-17_p-5","order":4,"canonicalText":"」不疑在躬，不度民械，不愿於大家，不訾重器。","chunks":[["」不疑在躬，不度民械，不愿於大家，不訾重器。","zh-Hant"]]},{"id":"li-ji_ch-17_p-6_s-1","passageId":"li-ji_ch-17_p-6","order":1,"canonicalText":"泛掃曰掃，掃席前曰拚；","chunks":[["泛掃曰掃，掃席前曰拚；","zh-Hant"]]},{"id":"li-ji_ch-17_p-6_s-2","passageId":"li-ji_ch-17_p-6","order":2,"canonicalText":"拚席不以鬣。","chunks":[["拚席不以鬣。","zh-Hant"]]},{"id":"li-ji_ch-17_p-6_s-3","passageId":"li-ji_ch-17_p-6","order":3,"canonicalText":"執箕膺擖。","chunks":[["執箕膺擖。","zh-Hant"]]},{"id":"li-ji_ch-17_p-7_s-1","passageId":"li-ji_ch-17_p-7","order":1,"canonicalText":"不貳問。","chunks":[["不貳問。","zh-Hant"]]},{"id":"li-ji_ch-17_p-7_s-2","passageId":"li-ji_ch-17_p-7","order":2,"canonicalText":"問卜筮曰：「義與？","chunks":[["問卜筮曰：「義與？","zh-Hant"]]},{"id":"li-ji_ch-17_p-7_s-3","passageId":"li-ji_ch-17_p-7","order":3,"canonicalText":"志與？","chunks":[["志與？","zh-Hant"]]},{"id":"li-ji_ch-17_p-7_s-4","passageId":"li-ji_ch-17_p-7","order":4,"canonicalText":"」義則可問，志則否。","chunks":[["」義則可問，志則否。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-1","passageId":"li-ji_ch-17_p-8","order":1,"canonicalText":"尊長於己逾等，不敢問其年。","chunks":[["尊長於己逾等，不敢問其年。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-2","passageId":"li-ji_ch-17_p-8","order":2,"canonicalText":"燕見不將命。","chunks":[["燕見不將命。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-3","passageId":"li-ji_ch-17_p-8","order":3,"canonicalText":"遇於道，見則面，不請所之。","chunks":[["遇於道，見則面，不請所之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-4","passageId":"li-ji_ch-17_p-8","order":4,"canonicalText":"喪俟事不特吊。","chunks":[["喪俟事不特吊。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-5","passageId":"li-ji_ch-17_p-8","order":5,"canonicalText":"侍坐弗使，不執琴瑟，不畫地，手無容，不翣也。","chunks":[["侍坐弗使，不執琴瑟，不畫地，手無容，不翣也。","zh-Hant"]]},{"id":"li-ji_ch-17_p-8_s-6","passageId":"li-ji_ch-17_p-8","order":6,"canonicalText":"寢則坐而將命。","chunks":[["寢則坐而將命。","zh-Hant"]]},{"id":"li-ji_ch-17_p-9_s-1","passageId":"li-ji_ch-17_p-9","order":1,"canonicalText":"侍射則約矢，侍投則擁矢。","chunks":[["侍射則約矢，侍投則擁矢。","zh-Hant"]]},{"id":"li-ji_ch-17_p-9_s-2","passageId":"li-ji_ch-17_p-9","order":2,"canonicalText":"勝則洗而以請，客亦如之。","chunks":[["勝則洗而以請，客亦如之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-9_s-3","passageId":"li-ji_ch-17_p-9","order":3,"canonicalText":"不角，不擢馬。","chunks":[["不角，不擢馬。","zh-Hant"]]},{"id":"li-ji_ch-17_p-10_s-1","passageId":"li-ji_ch-17_p-10","order":1,"canonicalText":"執君之乘車則坐。","chunks":[["執君之乘車則坐。","zh-Hant"]]},{"id":"li-ji_ch-17_p-10_s-2","passageId":"li-ji_ch-17_p-10","order":2,"canonicalText":"仆者右帶劍，負良綏，申之面，拖諸幦，以散綏升，執轡然後步。","chunks":[["仆者右帶劍，負良綏，申之面，拖諸幦，以散綏升，執轡然後步。","zh-Hant"]]},{"id":"li-ji_ch-17_p-11_s-1","passageId":"li-ji_ch-17_p-11","order":1,"canonicalText":"請見不請退。","chunks":[["請見不請退。","zh-Hant"]]},{"id":"li-ji_ch-17_p-11_s-2","passageId":"li-ji_ch-17_p-11","order":2,"canonicalText":"朝廷曰退，燕游曰歸，師役曰罷。","chunks":[["朝廷曰退，燕游曰歸，師役曰罷。","zh-Hant"]]},{"id":"li-ji_ch-17_p-12_s-1","passageId":"li-ji_ch-17_p-12","order":1,"canonicalText":"侍坐於君子，君子欠伸，運笏，澤劍首，還屨，問日之蚤莫，雖請退可也。","chunks":[["侍坐於君子，君子欠伸，運笏，澤劍首，還屨，問日之蚤莫，雖請退可也。","zh-Hant"]]},{"id":"li-ji_ch-17_p-13_s-1","passageId":"li-ji_ch-17_p-13","order":1,"canonicalText":"事君者量而後入，不入而後量；","chunks":[["事君者量而後入，不入而後量；","zh-Hant"]]},{"id":"li-ji_ch-17_p-13_s-2","passageId":"li-ji_ch-17_p-13","order":2,"canonicalText":"凡乞假於人，為人從事者亦然。","chunks":[["凡乞假於人，為人從事者亦然。","zh-Hant"]]},{"id":"li-ji_ch-17_p-13_s-3","passageId":"li-ji_ch-17_p-13","order":3,"canonicalText":"然，故上無怨，而下遠罪也。","chunks":[["然，故上無怨，而下遠罪也。","zh-Hant"]]},{"id":"li-ji_ch-17_p-13_s-4","passageId":"li-ji_ch-17_p-13","order":4,"canonicalText":"不窺密，不旁狎，不道舊故，不戲色。","chunks":[["不窺密，不旁狎，不道舊故，不戲色。","zh-Hant"]]},{"id":"li-ji_ch-17_p-14_s-1","passageId":"li-ji_ch-17_p-14","order":1,"canonicalText":"為人臣下者，有諫而無訕，有亡而無疾；","chunks":[["為人臣下者，有諫而無訕，有亡而無疾；","zh-Hant"]]},{"id":"li-ji_ch-17_p-14_s-2","passageId":"li-ji_ch-17_p-14","order":2,"canonicalText":"頌而無諂，諫而無驕；","chunks":[["頌而無諂，諫而無驕；","zh-Hant"]]},{"id":"li-ji_ch-17_p-14_s-3","passageId":"li-ji_ch-17_p-14","order":3,"canonicalText":"怠則張而相之，廢則掃而更之；","chunks":[["怠則張而相之，廢則掃而更之；","zh-Hant"]]},{"id":"li-ji_ch-17_p-14_s-4","passageId":"li-ji_ch-17_p-14","order":4,"canonicalText":"謂之社稷之役。","chunks":[["謂之社稷之役。","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-1","passageId":"li-ji_ch-17_p-15","order":1,"canonicalText":"毋拔來，毋報往，毋瀆神，毋循枉，毋測未至。","chunks":[["毋拔來，毋報往，毋瀆神，毋循枉，毋測未至。","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-2","passageId":"li-ji_ch-17_p-15","order":2,"canonicalText":"士依於德，游於藝；","chunks":[["士依於德，游於藝；","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-3","passageId":"li-ji_ch-17_p-15","order":3,"canonicalText":"工依於法，游於說。","chunks":[["工依於法，游於說。","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-4","passageId":"li-ji_ch-17_p-15","order":4,"canonicalText":"毋訾衣服成器，毋身質言語。","chunks":[["毋訾衣服成器，毋身質言語。","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-5","passageId":"li-ji_ch-17_p-15","order":5,"canonicalText":"言語之美，穆穆皇皇；","chunks":[["言語之美，穆穆皇皇；","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-6","passageId":"li-ji_ch-17_p-15","order":6,"canonicalText":"朝廷之美，濟濟翔翔；","chunks":[["朝廷之美，濟濟翔翔；","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-7","passageId":"li-ji_ch-17_p-15","order":7,"canonicalText":"祭祀之美，齊齊皇皇；","chunks":[["祭祀之美，齊齊皇皇；","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-8","passageId":"li-ji_ch-17_p-15","order":8,"canonicalText":"車馬之美，匪匪翼翼；","chunks":[["車馬之美，匪匪翼翼；","zh-Hant"]]},{"id":"li-ji_ch-17_p-15_s-9","passageId":"li-ji_ch-17_p-15","order":9,"canonicalText":"鸞和之美，肅肅雍雍。","chunks":[["鸞和之美，肅肅雍雍。","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-1","passageId":"li-ji_ch-17_p-16","order":1,"canonicalText":"問國君之子長幼，長，則曰：「能從社稷之事矣」；","chunks":[["問國君之子長幼，長，則曰：「能從社稷之事矣」；","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-2","passageId":"li-ji_ch-17_p-16","order":2,"canonicalText":"幼，則曰：「能御」，「未能御」。","chunks":[["幼，則曰：「能御」，「未能御」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-3","passageId":"li-ji_ch-17_p-16","order":3,"canonicalText":"問大夫之子長幼，長，則曰：「能從樂人之事矣」；","chunks":[["問大夫之子長幼，長，則曰：「能從樂人之事矣」；","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-4","passageId":"li-ji_ch-17_p-16","order":4,"canonicalText":"幼，則曰：「能正於樂人」，未能正於樂人」。","chunks":[["幼，則曰：「能正於樂人」，未能正於樂人」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-5","passageId":"li-ji_ch-17_p-16","order":5,"canonicalText":"問士之子長幼，長，則曰：「能耕矣」；","chunks":[["問士之子長幼，長，則曰：「能耕矣」；","zh-Hant"]]},{"id":"li-ji_ch-17_p-16_s-6","passageId":"li-ji_ch-17_p-16","order":6,"canonicalText":"幼，則曰：「能負薪」、「未能負薪」。","chunks":[["幼，則曰：「能負薪」、「未能負薪」。","zh-Hant"]]},{"id":"li-ji_ch-17_p-17_s-1","passageId":"li-ji_ch-17_p-17","order":1,"canonicalText":"執玉執龜策不趨，堂上不趨，城上不趨。","chunks":[["執玉執龜策不趨，堂上不趨，城上不趨。","zh-Hant"]]},{"id":"li-ji_ch-17_p-17_s-2","passageId":"li-ji_ch-17_p-17","order":2,"canonicalText":"武車不式；","chunks":[["武車不式；","zh-Hant"]]},{"id":"li-ji_ch-17_p-17_s-3","passageId":"li-ji_ch-17_p-17","order":3,"canonicalText":"介者不拜。","chunks":[["介者不拜。","zh-Hant"]]},{"id":"li-ji_ch-17_p-18_s-1","passageId":"li-ji_ch-17_p-18","order":1,"canonicalText":"婦人吉事，雖有君賜，肅拜。","chunks":[["婦人吉事，雖有君賜，肅拜。","zh-Hant"]]},{"id":"li-ji_ch-17_p-18_s-2","passageId":"li-ji_ch-17_p-18","order":2,"canonicalText":"為尸坐，則不手拜，肅拜；","chunks":[["為尸坐，則不手拜，肅拜；","zh-Hant"]]},{"id":"li-ji_ch-17_p-18_s-3","passageId":"li-ji_ch-17_p-18","order":3,"canonicalText":"為喪主則不手拜。","chunks":[["為喪主則不手拜。","zh-Hant"]]},{"id":"li-ji_ch-17_p-18_s-4","passageId":"li-ji_ch-17_p-18","order":4,"canonicalText":"葛絰而麻帶。","chunks":[["葛絰而麻帶。","zh-Hant"]]},{"id":"li-ji_ch-17_p-19_s-1","passageId":"li-ji_ch-17_p-19","order":1,"canonicalText":"取俎進俎不坐。","chunks":[["取俎進俎不坐。","zh-Hant"]]},{"id":"li-ji_ch-17_p-19_s-2","passageId":"li-ji_ch-17_p-19","order":2,"canonicalText":"執虛如執盈，入虛如有人。","chunks":[["執虛如執盈，入虛如有人。","zh-Hant"]]},{"id":"li-ji_ch-17_p-19_s-3","passageId":"li-ji_ch-17_p-19","order":3,"canonicalText":"凡祭於室中堂上無跣，燕則有之。","chunks":[["凡祭於室中堂上無跣，燕則有之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-19_s-4","passageId":"li-ji_ch-17_p-19","order":4,"canonicalText":"未嘗不食新。","chunks":[["未嘗不食新。","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-1","passageId":"li-ji_ch-17_p-20","order":1,"canonicalText":"仆於君子，君子升下則授綏；","chunks":[["仆於君子，君子升下則授綏；","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-2","passageId":"li-ji_ch-17_p-20","order":2,"canonicalText":"始乘則式；","chunks":[["始乘則式；","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-3","passageId":"li-ji_ch-17_p-20","order":3,"canonicalText":"君子下行，然後還立。","chunks":[["君子下行，然後還立。","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-4","passageId":"li-ji_ch-17_p-20","order":4,"canonicalText":"乘貳車則式，佐車則否。","chunks":[["乘貳車則式，佐車則否。","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-5","passageId":"li-ji_ch-17_p-20","order":5,"canonicalText":"貳車者，諸侯七乘，上大夫五乘，下大夫三乘。","chunks":[["貳車者，諸侯七乘，上大夫五乘，下大夫三乘。","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-6","passageId":"li-ji_ch-17_p-20","order":6,"canonicalText":"有貳車者之乘馬服車不齒。","chunks":[["有貳車者之乘馬服車不齒。","zh-Hant"]]},{"id":"li-ji_ch-17_p-20_s-7","passageId":"li-ji_ch-17_p-20","order":7,"canonicalText":"觀君子之衣服，服劍，乘馬，弗賈。","chunks":[["觀君子之衣服，服劍，乘馬，弗賈。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-1","passageId":"li-ji_ch-17_p-21","order":1,"canonicalText":"其以乘壺酒，束修，一犬賜人，若獻人，則陳酒執修以將命，亦曰乘壺酒，束修，一犬。","chunks":[["其以乘壺酒，束修，一犬賜人，若獻人，則陳酒執修以將命，亦曰乘壺酒，束修，一犬。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-2","passageId":"li-ji_ch-17_p-21","order":2,"canonicalText":"其以鼎肉，則執以將命。","chunks":[["其以鼎肉，則執以將命。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-3","passageId":"li-ji_ch-17_p-21","order":3,"canonicalText":"其禽加於一雙，則執一雙以將命，委其餘。","chunks":[["其禽加於一雙，則執一雙以將命，委其餘。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-4","passageId":"li-ji_ch-17_p-21","order":4,"canonicalText":"犬則執紲；","chunks":[["犬則執紲；","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-5","passageId":"li-ji_ch-17_p-21","order":5,"canonicalText":"守犬，田犬，則授擯者，既受，乃問犬名。","chunks":[["守犬，田犬，則授擯者，既受，乃問犬名。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-6","passageId":"li-ji_ch-17_p-21","order":6,"canonicalText":"牛則執紖，馬則執靮，皆右之。","chunks":[["牛則執紖，馬則執靮，皆右之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-21_s-7","passageId":"li-ji_ch-17_p-21","order":7,"canonicalText":"臣則左之。","chunks":[["臣則左之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-1","passageId":"li-ji_ch-17_p-22","order":1,"canonicalText":"車則說綏，執以將命。","chunks":[["車則說綏，執以將命。","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-2","passageId":"li-ji_ch-17_p-22","order":2,"canonicalText":"甲若有以前之，則執以將命；","chunks":[["甲若有以前之，則執以將命；","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-3","passageId":"li-ji_ch-17_p-22","order":3,"canonicalText":"無以前之，則袒櫜奉胄。","chunks":[["無以前之，則袒櫜奉胄。","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-4","passageId":"li-ji_ch-17_p-22","order":4,"canonicalText":"哭則執蓋。","chunks":[["哭則執蓋。","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-5","passageId":"li-ji_ch-17_p-22","order":5,"canonicalText":"弓則以左手屈韣執拊。","chunks":[["弓則以左手屈韣執拊。","zh-Hant"]]},{"id":"li-ji_ch-17_p-22_s-6","passageId":"li-ji_ch-17_p-22","order":6,"canonicalText":"劍則啟櫝蓋襲之，加夫橈與劍焉。","chunks":[["劍則啟櫝蓋襲之，加夫橈與劍焉。","zh-Hant"]]},{"id":"li-ji_ch-17_p-23_s-1","passageId":"li-ji_ch-17_p-23","order":1,"canonicalText":"笏、書、修、苞苴、弓、茵、席、枕、几、穎、杖、琴、瑟、戈有刃者櫝、策、龠，其執之皆尚左手。","chunks":[["笏、書、修、苞苴、弓、茵、席、枕、几、穎、杖、琴、瑟、戈有刃者櫝、策、龠，其執之皆尚左手。","zh-Hant"]]},{"id":"li-ji_ch-17_p-23_s-2","passageId":"li-ji_ch-17_p-23","order":2,"canonicalText":"刀卻刃授穎。","chunks":[["刀卻刃授穎。","zh-Hant"]]},{"id":"li-ji_ch-17_p-23_s-3","passageId":"li-ji_ch-17_p-23","order":3,"canonicalText":"削授拊。","chunks":[["削授拊。","zh-Hant"]]},{"id":"li-ji_ch-17_p-23_s-4","passageId":"li-ji_ch-17_p-23","order":4,"canonicalText":"凡有刺刃者，以授人則辟刃。","chunks":[["凡有刺刃者，以授人則辟刃。","zh-Hant"]]},{"id":"li-ji_ch-17_p-24_s-1","passageId":"li-ji_ch-17_p-24","order":1,"canonicalText":"乘兵車，出先刃，入後刃，軍尚左，卒尚右。","chunks":[["乘兵車，出先刃，入後刃，軍尚左，卒尚右。","zh-Hant"]]},{"id":"li-ji_ch-17_p-25_s-1","passageId":"li-ji_ch-17_p-25","order":1,"canonicalText":"賓客主恭，祭祀主敬，喪事主哀，會同主詡。","chunks":[["賓客主恭，祭祀主敬，喪事主哀，會同主詡。","zh-Hant"]]},{"id":"li-ji_ch-17_p-25_s-2","passageId":"li-ji_ch-17_p-25","order":2,"canonicalText":"軍旅思險，隱情以虞。","chunks":[["軍旅思險，隱情以虞。","zh-Hant"]]},{"id":"li-ji_ch-17_p-26_s-1","passageId":"li-ji_ch-17_p-26","order":1,"canonicalText":"燕侍食於君子，則先飯而後已；","chunks":[["燕侍食於君子，則先飯而後已；","zh-Hant"]]},{"id":"li-ji_ch-17_p-26_s-2","passageId":"li-ji_ch-17_p-26","order":2,"canonicalText":"毋放飯，毋流歠；","chunks":[["毋放飯，毋流歠；","zh-Hant"]]},{"id":"li-ji_ch-17_p-26_s-3","passageId":"li-ji_ch-17_p-26","order":3,"canonicalText":"小飯而亟之；","chunks":[["小飯而亟之；","zh-Hant"]]},{"id":"li-ji_ch-17_p-26_s-4","passageId":"li-ji_ch-17_p-26","order":4,"canonicalText":"數噍毋為口容。","chunks":[["數噍毋為口容。","zh-Hant"]]},{"id":"li-ji_ch-17_p-26_s-5","passageId":"li-ji_ch-17_p-26","order":5,"canonicalText":"客自徹，辭焉則止。","chunks":[["客自徹，辭焉則止。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-1","passageId":"li-ji_ch-17_p-27","order":1,"canonicalText":"客爵居左，其飲居右；","chunks":[["客爵居左，其飲居右；","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-2","passageId":"li-ji_ch-17_p-27","order":2,"canonicalText":"介爵、酢爵、僎爵皆居右。","chunks":[["介爵、酢爵、僎爵皆居右。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-3","passageId":"li-ji_ch-17_p-27","order":3,"canonicalText":"羞濡魚者進尾；","chunks":[["羞濡魚者進尾；","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-4","passageId":"li-ji_ch-17_p-27","order":4,"canonicalText":"冬右腴，夏右鰭；","chunks":[["冬右腴，夏右鰭；","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-5","passageId":"li-ji_ch-17_p-27","order":5,"canonicalText":"祭膴。","chunks":[["祭膴。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-6","passageId":"li-ji_ch-17_p-27","order":6,"canonicalText":"凡齊，執之以右，居之於左。","chunks":[["凡齊，執之以右，居之於左。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-7","passageId":"li-ji_ch-17_p-27","order":7,"canonicalText":"贊幣自左，詔辭自右。","chunks":[["贊幣自左，詔辭自右。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-8","passageId":"li-ji_ch-17_p-27","order":8,"canonicalText":"酌尸之仆，如君之仆。","chunks":[["酌尸之仆，如君之仆。","zh-Hant"]]},{"id":"li-ji_ch-17_p-27_s-9","passageId":"li-ji_ch-17_p-27","order":9,"canonicalText":"其在車則左執轡右受爵，祭左右軌范乃飲。","chunks":[["其在車則左執轡右受爵，祭左右軌范乃飲。","zh-Hant"]]},{"id":"li-ji_ch-17_p-28_s-1","passageId":"li-ji_ch-17_p-28","order":1,"canonicalText":"凡羞有俎者，則於俎內祭。","chunks":[["凡羞有俎者，則於俎內祭。","zh-Hant"]]},{"id":"li-ji_ch-17_p-29_s-1","passageId":"li-ji_ch-17_p-29","order":1,"canonicalText":"君子不食圂腴。","chunks":[["君子不食圂腴。","zh-Hant"]]},{"id":"li-ji_ch-17_p-30_s-1","passageId":"li-ji_ch-17_p-30","order":1,"canonicalText":"小子走而不趨，舉爵則坐祭立飲。","chunks":[["小子走而不趨，舉爵則坐祭立飲。","zh-Hant"]]},{"id":"li-ji_ch-17_p-30_s-2","passageId":"li-ji_ch-17_p-30","order":2,"canonicalText":"凡洗必盥。","chunks":[["凡洗必盥。","zh-Hant"]]},{"id":"li-ji_ch-17_p-30_s-3","passageId":"li-ji_ch-17_p-30","order":3,"canonicalText":"牛羊之肺，離而不提心。","chunks":[["牛羊之肺，離而不提心。","zh-Hant"]]},{"id":"li-ji_ch-17_p-30_s-4","passageId":"li-ji_ch-17_p-30","order":4,"canonicalText":"凡羞有湇者，不以齊。","chunks":[["凡羞有湇者，不以齊。","zh-Hant"]]},{"id":"li-ji_ch-17_p-31_s-1","passageId":"li-ji_ch-17_p-31","order":1,"canonicalText":"為君子擇蔥薤，則絕其本末。","chunks":[["為君子擇蔥薤，則絕其本末。","zh-Hant"]]},{"id":"li-ji_ch-17_p-32_s-1","passageId":"li-ji_ch-17_p-32","order":1,"canonicalText":"羞首者，進喙祭耳。","chunks":[["羞首者，進喙祭耳。","zh-Hant"]]},{"id":"li-ji_ch-17_p-33_s-1","passageId":"li-ji_ch-17_p-33","order":1,"canonicalText":"尊者以酌者之左為上尊。","chunks":[["尊者以酌者之左為上尊。","zh-Hant"]]},{"id":"li-ji_ch-17_p-33_s-2","passageId":"li-ji_ch-17_p-33","order":2,"canonicalText":"尊壺者面其鼻。","chunks":[["尊壺者面其鼻。","zh-Hant"]]},{"id":"li-ji_ch-17_p-33_s-3","passageId":"li-ji_ch-17_p-33","order":3,"canonicalText":"飲酒者、禨者、醮者，有折俎不坐。","chunks":[["飲酒者、禨者、醮者，有折俎不坐。","zh-Hant"]]},{"id":"li-ji_ch-17_p-33_s-4","passageId":"li-ji_ch-17_p-33","order":4,"canonicalText":"未步爵，不嘗羞。","chunks":[["未步爵，不嘗羞。","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-1","passageId":"li-ji_ch-17_p-34","order":1,"canonicalText":"牛與羊魚之腥，聶而切之為膾；","chunks":[["牛與羊魚之腥，聶而切之為膾；","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-2","passageId":"li-ji_ch-17_p-34","order":2,"canonicalText":"麋鹿為菹，野豕為軒，皆聶而不切；","chunks":[["麋鹿為菹，野豕為軒，皆聶而不切；","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-3","passageId":"li-ji_ch-17_p-34","order":3,"canonicalText":"麇為辟雞，兔為宛脾，皆聶而切之。","chunks":[["麇為辟雞，兔為宛脾，皆聶而切之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-4","passageId":"li-ji_ch-17_p-34","order":4,"canonicalText":"切蔥若薤，實之醯以柔之。","chunks":[["切蔥若薤，實之醯以柔之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-5","passageId":"li-ji_ch-17_p-34","order":5,"canonicalText":"其有折俎者，取祭肺，反之，不坐；","chunks":[["其有折俎者，取祭肺，反之，不坐；","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-6","passageId":"li-ji_ch-17_p-34","order":6,"canonicalText":"燔亦如之。","chunks":[["燔亦如之。","zh-Hant"]]},{"id":"li-ji_ch-17_p-34_s-7","passageId":"li-ji_ch-17_p-34","order":7,"canonicalText":"尸則坐。","chunks":[["尸則坐。","zh-Hant"]]},{"id":"li-ji_ch-17_p-35_s-1","passageId":"li-ji_ch-17_p-35","order":1,"canonicalText":"衣服在躬，而不知其名為罔。","chunks":[["衣服在躬，而不知其名為罔。","zh-Hant"]]},{"id":"li-ji_ch-17_p-36_s-1","passageId":"li-ji_ch-17_p-36","order":1,"canonicalText":"其未有燭而有後至者，則以在者告。","chunks":[["其未有燭而有後至者，則以在者告。","zh-Hant"]]},{"id":"li-ji_ch-17_p-36_s-2","passageId":"li-ji_ch-17_p-36","order":2,"canonicalText":"道瞽亦然。","chunks":[["道瞽亦然。","zh-Hant"]]},{"id":"li-ji_ch-17_p-36_s-3","passageId":"li-ji_ch-17_p-36","order":3,"canonicalText":"凡飲酒為獻主者，執燭抱燋，客作而辭，然後以授人。","chunks":[["凡飲酒為獻主者，執燭抱燋，客作而辭，然後以授人。","zh-Hant"]]},{"id":"li-ji_ch-17_p-36_s-4","passageId":"li-ji_ch-17_p-36","order":4,"canonicalText":"執燭不讓，不辭，不歌。","chunks":[["執燭不讓，不辭，不歌。","zh-Hant"]]},{"id":"li-ji_ch-17_p-37_s-1","passageId":"li-ji_ch-17_p-37","order":1,"canonicalText":"洗盥執食飲者勿氣，有問焉，則辟咡而對。","chunks":[["洗盥執食飲者勿氣，有問焉，則辟咡而對。","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-1","passageId":"li-ji_ch-17_p-38","order":1,"canonicalText":"為人祭曰致福；","chunks":[["為人祭曰致福；","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-2","passageId":"li-ji_ch-17_p-38","order":2,"canonicalText":"為己祭而致膳於君子曰膳；","chunks":[["為己祭而致膳於君子曰膳；","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-3","passageId":"li-ji_ch-17_p-38","order":3,"canonicalText":"祔練曰告。","chunks":[["祔練曰告。","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-4","passageId":"li-ji_ch-17_p-38","order":4,"canonicalText":"凡膳告於君子，主人展之，以授使者于阼階之南，南面再拜稽首送；","chunks":[["凡膳告於君子，主人展之，以授使者于阼階之南，南面再拜稽首送；","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-5","passageId":"li-ji_ch-17_p-38","order":5,"canonicalText":"反命，主人又再拜稽首。","chunks":[["反命，主人又再拜稽首。","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-6","passageId":"li-ji_ch-17_p-38","order":6,"canonicalText":"其禮：大牢則以牛左肩、臂臑、折九個，少牢則以羊左肩七個，特豕則以豕左肩五個。","chunks":[["其禮：大牢則以牛左肩、臂臑、折九個，少牢則以羊左肩七個，特豕則以豕左肩五個。","zh-Hant"]]},{"id":"li-ji_ch-17_p-38_s-7","passageId":"li-ji_ch-17_p-38","order":7,"canonicalText":"國家靡敝，則車不雕几，甲不組縢，食器不刻鏤，君子不履絲屨，馬不常秣。","chunks":[["國家靡敝，則車不雕几，甲不組縢，食器不刻鏤，君子不履絲屨，馬不常秣。","zh-Hant"]]},{"id":"li-ji_ch-18_p-1_s-1","passageId":"li-ji_ch-18_p-1","order":1,"canonicalText":"發慮憲，求善良，足以謏聞，不足以動眾；","chunks":[["發慮憲，求善良，足以謏聞，不足以動眾；","zh-Hant"]]},{"id":"li-ji_ch-18_p-1_s-2","passageId":"li-ji_ch-18_p-1","order":2,"canonicalText":"就賢體遠，足以動眾，未足以化民。","chunks":[["就賢體遠，足以動眾，未足以化民。","zh-Hant"]]},{"id":"li-ji_ch-18_p-1_s-3","passageId":"li-ji_ch-18_p-1","order":3,"canonicalText":"君子如欲化民成俗，其必由學乎！","chunks":[["君子如欲化民成俗，其必由學乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-2_s-1","passageId":"li-ji_ch-18_p-2","order":1,"canonicalText":"玉不琢，不成器；","chunks":[["玉不琢，不成器；","zh-Hant"]]},{"id":"li-ji_ch-18_p-2_s-2","passageId":"li-ji_ch-18_p-2","order":2,"canonicalText":"人不學，不知道。","chunks":[["人不學，不知道。","zh-Hant"]]},{"id":"li-ji_ch-18_p-2_s-3","passageId":"li-ji_ch-18_p-2","order":3,"canonicalText":"是故古之王者建國君民，教學為先。","chunks":[["是故古之王者建國君民，教學為先。","zh-Hant"]]},{"id":"li-ji_ch-18_p-2_s-4","passageId":"li-ji_ch-18_p-2","order":4,"canonicalText":"《兌命》曰：「念終始典于學。","chunks":[["《兌命》曰：「念終始典于學。","zh-Hant"]]},{"id":"li-ji_ch-18_p-2_s-5","passageId":"li-ji_ch-18_p-2","order":5,"canonicalText":"」其此之謂乎！","chunks":[["」其此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-1","passageId":"li-ji_ch-18_p-3","order":1,"canonicalText":"雖有嘉肴，弗食，不知其旨也；","chunks":[["雖有嘉肴，弗食，不知其旨也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-2","passageId":"li-ji_ch-18_p-3","order":2,"canonicalText":"雖有至道，弗學，不知其善也。","chunks":[["雖有至道，弗學，不知其善也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-3","passageId":"li-ji_ch-18_p-3","order":3,"canonicalText":"故學然後知不足，教然後知困。","chunks":[["故學然後知不足，教然後知困。","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-4","passageId":"li-ji_ch-18_p-3","order":4,"canonicalText":"知不足，然後能自反也；","chunks":[["知不足，然後能自反也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-5","passageId":"li-ji_ch-18_p-3","order":5,"canonicalText":"知困，然後能自強也，故曰：教學相長也。","chunks":[["知困，然後能自強也，故曰：教學相長也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-6","passageId":"li-ji_ch-18_p-3","order":6,"canonicalText":"《兌命》曰：「學學半。","chunks":[["《兌命》曰：「學學半。","zh-Hant"]]},{"id":"li-ji_ch-18_p-3_s-7","passageId":"li-ji_ch-18_p-3","order":7,"canonicalText":"」其此之謂乎！","chunks":[["」其此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-1","passageId":"li-ji_ch-18_p-4","order":1,"canonicalText":"古之教者，家有塾，黨有庠，術有序，國有學。","chunks":[["古之教者，家有塾，黨有庠，術有序，國有學。","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-2","passageId":"li-ji_ch-18_p-4","order":2,"canonicalText":"比年入學，中年考校。","chunks":[["比年入學，中年考校。","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-3","passageId":"li-ji_ch-18_p-4","order":3,"canonicalText":"一年視離經辨志，三年視敬業樂群，五年視博習親師，七年視論學取友，謂之小成；","chunks":[["一年視離經辨志，三年視敬業樂群，五年視博習親師，七年視論學取友，謂之小成；","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-4","passageId":"li-ji_ch-18_p-4","order":4,"canonicalText":"九年知類通達，強立而不反，謂之大成。","chunks":[["九年知類通達，強立而不反，謂之大成。","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-5","passageId":"li-ji_ch-18_p-4","order":5,"canonicalText":"夫然後足以化民易俗，近者說服，而遠者懷之，此大學之道也。","chunks":[["夫然後足以化民易俗，近者說服，而遠者懷之，此大學之道也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-6","passageId":"li-ji_ch-18_p-4","order":6,"canonicalText":"《記》曰：「蛾子時術之。","chunks":[["《記》曰：「蛾子時術之。","zh-Hant"]]},{"id":"li-ji_ch-18_p-4_s-7","passageId":"li-ji_ch-18_p-4","order":7,"canonicalText":"」其此之謂乎！","chunks":[["」其此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-1","passageId":"li-ji_ch-18_p-5","order":1,"canonicalText":"大學始教，皮弁祭菜，示敬道也；","chunks":[["大學始教，皮弁祭菜，示敬道也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-2","passageId":"li-ji_ch-18_p-5","order":2,"canonicalText":"《宵雅》肄三，官其始也；","chunks":[["《宵雅》肄三，官其始也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-3","passageId":"li-ji_ch-18_p-5","order":3,"canonicalText":"入學鼓篋，孫其業也；","chunks":[["入學鼓篋，孫其業也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-4","passageId":"li-ji_ch-18_p-5","order":4,"canonicalText":"夏楚二物，收其威也；","chunks":[["夏楚二物，收其威也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-5","passageId":"li-ji_ch-18_p-5","order":5,"canonicalText":"未卜禘不視學，游其志也；","chunks":[["未卜禘不視學，游其志也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-6","passageId":"li-ji_ch-18_p-5","order":6,"canonicalText":"時觀而弗語，存其心也；","chunks":[["時觀而弗語，存其心也；","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-7","passageId":"li-ji_ch-18_p-5","order":7,"canonicalText":"幼者聽而弗問，學不躐等也。","chunks":[["幼者聽而弗問，學不躐等也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-8","passageId":"li-ji_ch-18_p-5","order":8,"canonicalText":"此七者，教之大倫也。","chunks":[["此七者，教之大倫也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-9","passageId":"li-ji_ch-18_p-5","order":9,"canonicalText":"《記》曰：「凡學官先事，士先志。","chunks":[["《記》曰：「凡學官先事，士先志。","zh-Hant"]]},{"id":"li-ji_ch-18_p-5_s-10","passageId":"li-ji_ch-18_p-5","order":10,"canonicalText":"」其此之謂乎！","chunks":[["」其此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-1","passageId":"li-ji_ch-18_p-6","order":1,"canonicalText":"大學之教也時，教必有正業，退息必有居。","chunks":[["大學之教也時，教必有正業，退息必有居。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-2","passageId":"li-ji_ch-18_p-6","order":2,"canonicalText":"學，不學操縵，不能安弦；","chunks":[["學，不學操縵，不能安弦；","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-3","passageId":"li-ji_ch-18_p-6","order":3,"canonicalText":"不學博依，不能安《詩》；","chunks":[["不學博依，不能安《詩》；","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-4","passageId":"li-ji_ch-18_p-6","order":4,"canonicalText":"不學雜服，不能安禮；","chunks":[["不學雜服，不能安禮；","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-5","passageId":"li-ji_ch-18_p-6","order":5,"canonicalText":"不興其藝，不能樂學。","chunks":[["不興其藝，不能樂學。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-6","passageId":"li-ji_ch-18_p-6","order":6,"canonicalText":"故君子之於學也，藏焉，修焉，息焉，游焉。","chunks":[["故君子之於學也，藏焉，修焉，息焉，游焉。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-7","passageId":"li-ji_ch-18_p-6","order":7,"canonicalText":"夫然，故安其學而親其師，樂其友而信其道。","chunks":[["夫然，故安其學而親其師，樂其友而信其道。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-8","passageId":"li-ji_ch-18_p-6","order":8,"canonicalText":"是以雖離師輔而不反也。","chunks":[["是以雖離師輔而不反也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-9","passageId":"li-ji_ch-18_p-6","order":9,"canonicalText":"《兌命》曰：「敬孫務時敏，厥修乃來。","chunks":[["《兌命》曰：「敬孫務時敏，厥修乃來。","zh-Hant"]]},{"id":"li-ji_ch-18_p-6_s-10","passageId":"li-ji_ch-18_p-6","order":10,"canonicalText":"」其此之謂乎！","chunks":[["」其此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-7_s-1","passageId":"li-ji_ch-18_p-7","order":1,"canonicalText":"今之教者，呻其占畢，多其訊，言及于數，進而不顧其安，使人不由其誠，教人不盡其材；","chunks":[["今之教者，呻其占畢，多其訊，言及于數，進而不顧其安，使人不由其誠，教人不盡其材；","zh-Hant"]]},{"id":"li-ji_ch-18_p-7_s-2","passageId":"li-ji_ch-18_p-7","order":2,"canonicalText":"其施之也悖，其求之也佛。","chunks":[["其施之也悖，其求之也佛。","zh-Hant"]]},{"id":"li-ji_ch-18_p-7_s-3","passageId":"li-ji_ch-18_p-7","order":3,"canonicalText":"夫然，故隱其學而疾其師，苦其難而不知其益也，雖終其業，其去之必速。","chunks":[["夫然，故隱其學而疾其師，苦其難而不知其益也，雖終其業，其去之必速。","zh-Hant"]]},{"id":"li-ji_ch-18_p-7_s-4","passageId":"li-ji_ch-18_p-7","order":4,"canonicalText":"教之不刑，其此之由乎！","chunks":[["教之不刑，其此之由乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-1","passageId":"li-ji_ch-18_p-8","order":1,"canonicalText":"大學之法，禁於未發之謂豫，當其可之謂時，不陵節而施之謂孫，相觀而善之謂摩。","chunks":[["大學之法，禁於未發之謂豫，當其可之謂時，不陵節而施之謂孫，相觀而善之謂摩。","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-2","passageId":"li-ji_ch-18_p-8","order":2,"canonicalText":"此四者，教之所由興也。","chunks":[["此四者，教之所由興也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-3","passageId":"li-ji_ch-18_p-8","order":3,"canonicalText":"發然後禁，則捍格而不勝；","chunks":[["發然後禁，則捍格而不勝；","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-4","passageId":"li-ji_ch-18_p-8","order":4,"canonicalText":"時過然後學，則勤苦而難成；","chunks":[["時過然後學，則勤苦而難成；","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-5","passageId":"li-ji_ch-18_p-8","order":5,"canonicalText":"雜施而不孫，則壞亂而不修；","chunks":[["雜施而不孫，則壞亂而不修；","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-6","passageId":"li-ji_ch-18_p-8","order":6,"canonicalText":"獨學而無友，則孤陋而寡聞；","chunks":[["獨學而無友，則孤陋而寡聞；","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-7","passageId":"li-ji_ch-18_p-8","order":7,"canonicalText":"燕朋逆其師；","chunks":[["燕朋逆其師；","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-8","passageId":"li-ji_ch-18_p-8","order":8,"canonicalText":"燕辟廢其學。","chunks":[["燕辟廢其學。","zh-Hant"]]},{"id":"li-ji_ch-18_p-8_s-9","passageId":"li-ji_ch-18_p-8","order":9,"canonicalText":"此六者，教之所由廢也。","chunks":[["此六者，教之所由廢也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-9_s-1","passageId":"li-ji_ch-18_p-9","order":1,"canonicalText":"君子既知教之所由興，又知教之所由廢，然後可以為人師也。","chunks":[["君子既知教之所由興，又知教之所由廢，然後可以為人師也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-9_s-2","passageId":"li-ji_ch-18_p-9","order":2,"canonicalText":"故君子之教喻也，道而弗牽，強而弗抑，開而弗達。","chunks":[["故君子之教喻也，道而弗牽，強而弗抑，開而弗達。","zh-Hant"]]},{"id":"li-ji_ch-18_p-9_s-3","passageId":"li-ji_ch-18_p-9","order":3,"canonicalText":"道而弗牽則和，強而弗抑則易，開而弗達則思；","chunks":[["道而弗牽則和，強而弗抑則易，開而弗達則思；","zh-Hant"]]},{"id":"li-ji_ch-18_p-9_s-4","passageId":"li-ji_ch-18_p-9","order":4,"canonicalText":"和易以思，可謂善喻矣。","chunks":[["和易以思，可謂善喻矣。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-1","passageId":"li-ji_ch-18_p-10","order":1,"canonicalText":"學者有四失，教者必知之。","chunks":[["學者有四失，教者必知之。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-2","passageId":"li-ji_ch-18_p-10","order":2,"canonicalText":"人之學也，或失則多，或失則寡，或失則易，或失則止。","chunks":[["人之學也，或失則多，或失則寡，或失則易，或失則止。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-3","passageId":"li-ji_ch-18_p-10","order":3,"canonicalText":"此四者，心之莫同也。","chunks":[["此四者，心之莫同也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-4","passageId":"li-ji_ch-18_p-10","order":4,"canonicalText":"知其心，然後能救其失也。","chunks":[["知其心，然後能救其失也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-5","passageId":"li-ji_ch-18_p-10","order":5,"canonicalText":"教也者，長善而救其失者也。","chunks":[["教也者，長善而救其失者也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-6","passageId":"li-ji_ch-18_p-10","order":6,"canonicalText":"善歌者，使人繼其聲；","chunks":[["善歌者，使人繼其聲；","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-7","passageId":"li-ji_ch-18_p-10","order":7,"canonicalText":"善教者，使人繼其志。","chunks":[["善教者，使人繼其志。","zh-Hant"]]},{"id":"li-ji_ch-18_p-10_s-8","passageId":"li-ji_ch-18_p-10","order":8,"canonicalText":"其言也約而達，微而臧，罕譬而喻，可謂繼志矣。","chunks":[["其言也約而達，微而臧，罕譬而喻，可謂繼志矣。","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-1","passageId":"li-ji_ch-18_p-11","order":1,"canonicalText":"君子知至學之難易，而知其美惡，然後能博喻；","chunks":[["君子知至學之難易，而知其美惡，然後能博喻；","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-2","passageId":"li-ji_ch-18_p-11","order":2,"canonicalText":"能博喻然後能為師；","chunks":[["能博喻然後能為師；","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-3","passageId":"li-ji_ch-18_p-11","order":3,"canonicalText":"能為師然後能為長；","chunks":[["能為師然後能為長；","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-4","passageId":"li-ji_ch-18_p-11","order":4,"canonicalText":"能為長然後能為君。","chunks":[["能為長然後能為君。","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-5","passageId":"li-ji_ch-18_p-11","order":5,"canonicalText":"故師也者，所以學為君也。","chunks":[["故師也者，所以學為君也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-6","passageId":"li-ji_ch-18_p-11","order":6,"canonicalText":"是故擇師不可不慎也。","chunks":[["是故擇師不可不慎也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-7","passageId":"li-ji_ch-18_p-11","order":7,"canonicalText":"《記》曰：「三王四代唯其師。","chunks":[["《記》曰：「三王四代唯其師。","zh-Hant"]]},{"id":"li-ji_ch-18_p-11_s-8","passageId":"li-ji_ch-18_p-11","order":8,"canonicalText":"」此之謂乎！","chunks":[["」此之謂乎！","zh-Hant"]]},{"id":"li-ji_ch-18_p-12_s-1","passageId":"li-ji_ch-18_p-12","order":1,"canonicalText":"凡學之道，嚴師為難。","chunks":[["凡學之道，嚴師為難。","zh-Hant"]]},{"id":"li-ji_ch-18_p-12_s-2","passageId":"li-ji_ch-18_p-12","order":2,"canonicalText":"師嚴然後道尊，道尊然後民知敬學。","chunks":[["師嚴然後道尊，道尊然後民知敬學。","zh-Hant"]]},{"id":"li-ji_ch-18_p-12_s-3","passageId":"li-ji_ch-18_p-12","order":3,"canonicalText":"是故君之所不臣於其臣者二：當其為尸則弗臣也，當其為師則弗臣也。","chunks":[["是故君之所不臣於其臣者二：當其為尸則弗臣也，當其為師則弗臣也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-12_s-4","passageId":"li-ji_ch-18_p-12","order":4,"canonicalText":"大學之禮，雖詔於天子，無北面；","chunks":[["大學之禮，雖詔於天子，無北面；","zh-Hant"]]},{"id":"li-ji_ch-18_p-12_s-5","passageId":"li-ji_ch-18_p-12","order":5,"canonicalText":"所以尊師也。","chunks":[["所以尊師也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-1","passageId":"li-ji_ch-18_p-13","order":1,"canonicalText":"善學者，師逸而功倍，又從而庸之；","chunks":[["善學者，師逸而功倍，又從而庸之；","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-2","passageId":"li-ji_ch-18_p-13","order":2,"canonicalText":"不善學者，師勤而功半，又從而怨之。","chunks":[["不善學者，師勤而功半，又從而怨之。","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-3","passageId":"li-ji_ch-18_p-13","order":3,"canonicalText":"善問者，如攻堅木，先其易者，後其節目，及其久也，相說以解；","chunks":[["善問者，如攻堅木，先其易者，後其節目，及其久也，相說以解；","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-4","passageId":"li-ji_ch-18_p-13","order":4,"canonicalText":"不善問者反此。","chunks":[["不善問者反此。","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-5","passageId":"li-ji_ch-18_p-13","order":5,"canonicalText":"善待問者，如撞鐘，叩之以小者則小鳴，叩之以大者則大鳴，待其從容，然後盡其聲；","chunks":[["善待問者，如撞鐘，叩之以小者則小鳴，叩之以大者則大鳴，待其從容，然後盡其聲；","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-6","passageId":"li-ji_ch-18_p-13","order":6,"canonicalText":"不善答問者反此。","chunks":[["不善答問者反此。","zh-Hant"]]},{"id":"li-ji_ch-18_p-13_s-7","passageId":"li-ji_ch-18_p-13","order":7,"canonicalText":"此皆進學之道也。","chunks":[["此皆進學之道也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-14_s-1","passageId":"li-ji_ch-18_p-14","order":1,"canonicalText":"記問之學，不足以為人師。","chunks":[["記問之學，不足以為人師。","zh-Hant"]]},{"id":"li-ji_ch-18_p-14_s-2","passageId":"li-ji_ch-18_p-14","order":2,"canonicalText":"必也聽語乎，力不能問，然後語之；","chunks":[["必也聽語乎，力不能問，然後語之；","zh-Hant"]]},{"id":"li-ji_ch-18_p-14_s-3","passageId":"li-ji_ch-18_p-14","order":3,"canonicalText":"語之而不知，雖舍之可也。","chunks":[["語之而不知，雖舍之可也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-15_s-1","passageId":"li-ji_ch-18_p-15","order":1,"canonicalText":"良冶之子，必學為裘；","chunks":[["良冶之子，必學為裘；","zh-Hant"]]},{"id":"li-ji_ch-18_p-15_s-2","passageId":"li-ji_ch-18_p-15","order":2,"canonicalText":"良弓之子，必學為箕；","chunks":[["良弓之子，必學為箕；","zh-Hant"]]},{"id":"li-ji_ch-18_p-15_s-3","passageId":"li-ji_ch-18_p-15","order":3,"canonicalText":"始駕者反之，車在馬前。","chunks":[["始駕者反之，車在馬前。","zh-Hant"]]},{"id":"li-ji_ch-18_p-15_s-4","passageId":"li-ji_ch-18_p-15","order":4,"canonicalText":"君子察於此三者，可以有志於學矣。","chunks":[["君子察於此三者，可以有志於學矣。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-1","passageId":"li-ji_ch-18_p-16","order":1,"canonicalText":"古之學者：比物醜類。","chunks":[["古之學者：比物醜類。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-2","passageId":"li-ji_ch-18_p-16","order":2,"canonicalText":"鼓無當於五聲，五聲弗得不和。","chunks":[["鼓無當於五聲，五聲弗得不和。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-3","passageId":"li-ji_ch-18_p-16","order":3,"canonicalText":"水無當於五色，五色弗得不章。","chunks":[["水無當於五色，五色弗得不章。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-4","passageId":"li-ji_ch-18_p-16","order":4,"canonicalText":"學無當於五官。","chunks":[["學無當於五官。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-5","passageId":"li-ji_ch-18_p-16","order":5,"canonicalText":"五官弗得不治。","chunks":[["五官弗得不治。","zh-Hant"]]},{"id":"li-ji_ch-18_p-16_s-6","passageId":"li-ji_ch-18_p-16","order":6,"canonicalText":"師無當於五服，五服弗得不親。","chunks":[["師無當於五服，五服弗得不親。","zh-Hant"]]},{"id":"li-ji_ch-18_p-17_s-1","passageId":"li-ji_ch-18_p-17","order":1,"canonicalText":"君子曰：大德不官，大道不器，大信不約，大時不齊。","chunks":[["君子曰：大德不官，大道不器，大信不約，大時不齊。","zh-Hant"]]},{"id":"li-ji_ch-18_p-17_s-2","passageId":"li-ji_ch-18_p-17","order":2,"canonicalText":"察於此四者，可以有志於學矣。","chunks":[["察於此四者，可以有志於學矣。","zh-Hant"]]},{"id":"li-ji_ch-18_p-17_s-3","passageId":"li-ji_ch-18_p-17","order":3,"canonicalText":"三王之祭川也，皆先河而後海；","chunks":[["三王之祭川也，皆先河而後海；","zh-Hant"]]},{"id":"li-ji_ch-18_p-17_s-4","passageId":"li-ji_ch-18_p-17","order":4,"canonicalText":"或源也，或委也。","chunks":[["或源也，或委也。","zh-Hant"]]},{"id":"li-ji_ch-18_p-17_s-5","passageId":"li-ji_ch-18_p-17","order":5,"canonicalText":"此之謂務本。","chunks":[["此之謂務本。","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-1","passageId":"li-ji_ch-19_p-1","order":1,"canonicalText":"凡音之起，由人心生也。","chunks":[["凡音之起，由人心生也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-2","passageId":"li-ji_ch-19_p-1","order":2,"canonicalText":"人心之動，物使之然也。","chunks":[["人心之動，物使之然也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-3","passageId":"li-ji_ch-19_p-1","order":3,"canonicalText":"感於物而動，故形於聲。","chunks":[["感於物而動，故形於聲。","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-4","passageId":"li-ji_ch-19_p-1","order":4,"canonicalText":"聲相應，故生變；","chunks":[["聲相應，故生變；","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-5","passageId":"li-ji_ch-19_p-1","order":5,"canonicalText":"變成方，謂之音；","chunks":[["變成方，謂之音；","zh-Hant"]]},{"id":"li-ji_ch-19_p-1_s-6","passageId":"li-ji_ch-19_p-1","order":6,"canonicalText":"比音而樂之，及干戚羽旄，謂之樂。","chunks":[["比音而樂之，及干戚羽旄，謂之樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-1","passageId":"li-ji_ch-19_p-2","order":1,"canonicalText":"樂者，音之所由生也；","chunks":[["樂者，音之所由生也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-2","passageId":"li-ji_ch-19_p-2","order":2,"canonicalText":"其本在人心之感於物也。","chunks":[["其本在人心之感於物也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-3","passageId":"li-ji_ch-19_p-2","order":3,"canonicalText":"是故其哀心感者，其聲噍以殺。","chunks":[["是故其哀心感者，其聲噍以殺。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-4","passageId":"li-ji_ch-19_p-2","order":4,"canonicalText":"其樂心感者，其聲嘽以緩。","chunks":[["其樂心感者，其聲嘽以緩。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-5","passageId":"li-ji_ch-19_p-2","order":5,"canonicalText":"其喜心感者，其聲發以散。","chunks":[["其喜心感者，其聲發以散。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-6","passageId":"li-ji_ch-19_p-2","order":6,"canonicalText":"其怒心感者，其聲粗以厲。","chunks":[["其怒心感者，其聲粗以厲。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-7","passageId":"li-ji_ch-19_p-2","order":7,"canonicalText":"其敬心感者，其聲直以廉。","chunks":[["其敬心感者，其聲直以廉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-8","passageId":"li-ji_ch-19_p-2","order":8,"canonicalText":"其愛心感者，其聲和以柔。","chunks":[["其愛心感者，其聲和以柔。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-9","passageId":"li-ji_ch-19_p-2","order":9,"canonicalText":"六者，非性也，感於物而後動。","chunks":[["六者，非性也，感於物而後動。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-10","passageId":"li-ji_ch-19_p-2","order":10,"canonicalText":"是故先王慎所以感之者。","chunks":[["是故先王慎所以感之者。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-11","passageId":"li-ji_ch-19_p-2","order":11,"canonicalText":"故禮以道其志，樂以和其聲，政以一其行，刑以防其奸。","chunks":[["故禮以道其志，樂以和其聲，政以一其行，刑以防其奸。","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-12","passageId":"li-ji_ch-19_p-2","order":12,"canonicalText":"禮樂刑政，其極一也；","chunks":[["禮樂刑政，其極一也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-2_s-13","passageId":"li-ji_ch-19_p-2","order":13,"canonicalText":"所以同民心而出治道也。","chunks":[["所以同民心而出治道也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-1","passageId":"li-ji_ch-19_p-3","order":1,"canonicalText":"凡音者，生人心者也。","chunks":[["凡音者，生人心者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-2","passageId":"li-ji_ch-19_p-3","order":2,"canonicalText":"情動於中，故形於聲。","chunks":[["情動於中，故形於聲。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-3","passageId":"li-ji_ch-19_p-3","order":3,"canonicalText":"聲成文，謂之音。","chunks":[["聲成文，謂之音。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-4","passageId":"li-ji_ch-19_p-3","order":4,"canonicalText":"是故治世之音安以樂，其政和。","chunks":[["是故治世之音安以樂，其政和。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-5","passageId":"li-ji_ch-19_p-3","order":5,"canonicalText":"亂世之音怨以怒，其政乖。","chunks":[["亂世之音怨以怒，其政乖。","zh-Hant"]]},{"id":"li-ji_ch-19_p-3_s-6","passageId":"li-ji_ch-19_p-3","order":6,"canonicalText":"亡國之音哀以思，其民困。","chunks":[["亡國之音哀以思，其民困。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-1","passageId":"li-ji_ch-19_p-4","order":1,"canonicalText":"聲音之道，與政通矣。","chunks":[["聲音之道，與政通矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-2","passageId":"li-ji_ch-19_p-4","order":2,"canonicalText":"宮為君，商為臣，角為民，徵為事，羽為物。","chunks":[["宮為君，商為臣，角為民，徵為事，羽為物。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-3","passageId":"li-ji_ch-19_p-4","order":3,"canonicalText":"五者不亂，則無怗懘之音矣。","chunks":[["五者不亂，則無怗懘之音矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-4","passageId":"li-ji_ch-19_p-4","order":4,"canonicalText":"宮亂則荒，其君驕。","chunks":[["宮亂則荒，其君驕。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-5","passageId":"li-ji_ch-19_p-4","order":5,"canonicalText":"商亂則陂，其官壞。","chunks":[["商亂則陂，其官壞。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-6","passageId":"li-ji_ch-19_p-4","order":6,"canonicalText":"角亂則憂，其民怨。","chunks":[["角亂則憂，其民怨。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-7","passageId":"li-ji_ch-19_p-4","order":7,"canonicalText":"徵亂則哀，其事勤。","chunks":[["徵亂則哀，其事勤。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-8","passageId":"li-ji_ch-19_p-4","order":8,"canonicalText":"羽亂則危，其財匱。","chunks":[["羽亂則危，其財匱。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-9","passageId":"li-ji_ch-19_p-4","order":9,"canonicalText":"五者皆亂，迭相陵，謂之慢。","chunks":[["五者皆亂，迭相陵，謂之慢。","zh-Hant"]]},{"id":"li-ji_ch-19_p-4_s-10","passageId":"li-ji_ch-19_p-4","order":10,"canonicalText":"如此，則國之滅亡無日矣。","chunks":[["如此，則國之滅亡無日矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-5_s-1","passageId":"li-ji_ch-19_p-5","order":1,"canonicalText":"鄭衛之音，亂世之音也，比於慢矣。","chunks":[["鄭衛之音，亂世之音也，比於慢矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-5_s-2","passageId":"li-ji_ch-19_p-5","order":2,"canonicalText":"桑間濮上之音，亡國之音也，其政散，其民流，誣上行私而不可止也。","chunks":[["桑間濮上之音，亡國之音也，其政散，其民流，誣上行私而不可止也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-1","passageId":"li-ji_ch-19_p-6","order":1,"canonicalText":"凡音者，生於人心者也。","chunks":[["凡音者，生於人心者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-2","passageId":"li-ji_ch-19_p-6","order":2,"canonicalText":"樂者，通倫理者也。","chunks":[["樂者，通倫理者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-3","passageId":"li-ji_ch-19_p-6","order":3,"canonicalText":"是故知聲而不知音者，禽獸是也；","chunks":[["是故知聲而不知音者，禽獸是也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-4","passageId":"li-ji_ch-19_p-6","order":4,"canonicalText":"知音而不知樂者，眾庶是也。","chunks":[["知音而不知樂者，眾庶是也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-5","passageId":"li-ji_ch-19_p-6","order":5,"canonicalText":"唯君子為能知樂。","chunks":[["唯君子為能知樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-6","passageId":"li-ji_ch-19_p-6","order":6,"canonicalText":"是故審聲以知音，審音以知樂，審樂以知政，而治道備矣。","chunks":[["是故審聲以知音，審音以知樂，審樂以知政，而治道備矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-7","passageId":"li-ji_ch-19_p-6","order":7,"canonicalText":"是故不知聲者不可與言音，不知音者不可與言樂。","chunks":[["是故不知聲者不可與言音，不知音者不可與言樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-8","passageId":"li-ji_ch-19_p-6","order":8,"canonicalText":"知樂則幾於禮矣。","chunks":[["知樂則幾於禮矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-9","passageId":"li-ji_ch-19_p-6","order":9,"canonicalText":"禮樂皆得，謂之有德。","chunks":[["禮樂皆得，謂之有德。","zh-Hant"]]},{"id":"li-ji_ch-19_p-6_s-10","passageId":"li-ji_ch-19_p-6","order":10,"canonicalText":"德者得也。","chunks":[["德者得也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-7_s-1","passageId":"li-ji_ch-19_p-7","order":1,"canonicalText":"是故樂之隆，非極音也。","chunks":[["是故樂之隆，非極音也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-7_s-2","passageId":"li-ji_ch-19_p-7","order":2,"canonicalText":"食饗之禮，非致味也。","chunks":[["食饗之禮，非致味也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-7_s-3","passageId":"li-ji_ch-19_p-7","order":3,"canonicalText":"清廟之瑟，朱弦而疏越，壹倡而三嘆，有遺音者矣。","chunks":[["清廟之瑟，朱弦而疏越，壹倡而三嘆，有遺音者矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-7_s-4","passageId":"li-ji_ch-19_p-7","order":4,"canonicalText":"大饗之禮，尚玄酒而俎腥魚，大羹不和，有遺味者矣。","chunks":[["大饗之禮，尚玄酒而俎腥魚，大羹不和，有遺味者矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-7_s-5","passageId":"li-ji_ch-19_p-7","order":5,"canonicalText":"是故先王之制禮樂也，非以極口腹耳目之欲也，將以教民平好惡而反人道之正也。","chunks":[["是故先王之制禮樂也，非以極口腹耳目之欲也，將以教民平好惡而反人道之正也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-8_s-1","passageId":"li-ji_ch-19_p-8","order":1,"canonicalText":"人生而靜，天之性也；","chunks":[["人生而靜，天之性也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-8_s-2","passageId":"li-ji_ch-19_p-8","order":2,"canonicalText":"感於物而動，性之欲也。","chunks":[["感於物而動，性之欲也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-8_s-3","passageId":"li-ji_ch-19_p-8","order":3,"canonicalText":"物至知知，然後好惡形焉。","chunks":[["物至知知，然後好惡形焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-8_s-4","passageId":"li-ji_ch-19_p-8","order":4,"canonicalText":"好惡無節於內，知誘於外，不能反躬，天理滅矣。","chunks":[["好惡無節於內，知誘於外，不能反躬，天理滅矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-9_s-1","passageId":"li-ji_ch-19_p-9","order":1,"canonicalText":"夫物之感人無窮，而人之好惡無節，則是物至而人化物也。","chunks":[["夫物之感人無窮，而人之好惡無節，則是物至而人化物也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-9_s-2","passageId":"li-ji_ch-19_p-9","order":2,"canonicalText":"人化物也者，滅天理而窮人欲者也。","chunks":[["人化物也者，滅天理而窮人欲者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-9_s-3","passageId":"li-ji_ch-19_p-9","order":3,"canonicalText":"於是有悖逆詐偽之心，有淫泆作亂之事。","chunks":[["於是有悖逆詐偽之心，有淫泆作亂之事。","zh-Hant"]]},{"id":"li-ji_ch-19_p-9_s-4","passageId":"li-ji_ch-19_p-9","order":4,"canonicalText":"是故強者脅弱，眾者暴寡，知者詐愚，勇者苦怯，疾病不養，老幼孤獨不得其所，此大亂之道也。","chunks":[["是故強者脅弱，眾者暴寡，知者詐愚，勇者苦怯，疾病不養，老幼孤獨不得其所，此大亂之道也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-1","passageId":"li-ji_ch-19_p-10","order":1,"canonicalText":"是故先王之制禮樂，人為之節；","chunks":[["是故先王之制禮樂，人為之節；","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-2","passageId":"li-ji_ch-19_p-10","order":2,"canonicalText":"衰麻哭泣，所以節喪紀也；","chunks":[["衰麻哭泣，所以節喪紀也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-3","passageId":"li-ji_ch-19_p-10","order":3,"canonicalText":"鐘鼓干戚，所以和安樂也；","chunks":[["鐘鼓干戚，所以和安樂也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-4","passageId":"li-ji_ch-19_p-10","order":4,"canonicalText":"昏姻冠笄，所以別男女也；","chunks":[["昏姻冠笄，所以別男女也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-5","passageId":"li-ji_ch-19_p-10","order":5,"canonicalText":"射鄉食饗，所以正交接也。","chunks":[["射鄉食饗，所以正交接也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-10_s-6","passageId":"li-ji_ch-19_p-10","order":6,"canonicalText":"禮節民心，樂和民聲，政以行之，刑以防之，禮樂刑政，四達而不悖，則王道備矣。","chunks":[["禮節民心，樂和民聲，政以行之，刑以防之，禮樂刑政，四達而不悖，則王道備矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-1","passageId":"li-ji_ch-19_p-11","order":1,"canonicalText":"樂者為同，禮者為異。","chunks":[["樂者為同，禮者為異。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-2","passageId":"li-ji_ch-19_p-11","order":2,"canonicalText":"同則相親，異則相敬，樂勝則流，禮勝則離。","chunks":[["同則相親，異則相敬，樂勝則流，禮勝則離。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-3","passageId":"li-ji_ch-19_p-11","order":3,"canonicalText":"合情飾貌者禮樂之事也。","chunks":[["合情飾貌者禮樂之事也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-4","passageId":"li-ji_ch-19_p-11","order":4,"canonicalText":"禮義立，則貴賤等矣；","chunks":[["禮義立，則貴賤等矣；","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-5","passageId":"li-ji_ch-19_p-11","order":5,"canonicalText":"樂文同，則上下和矣；","chunks":[["樂文同，則上下和矣；","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-6","passageId":"li-ji_ch-19_p-11","order":6,"canonicalText":"好惡著，則賢不肖別矣。","chunks":[["好惡著，則賢不肖別矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-7","passageId":"li-ji_ch-19_p-11","order":7,"canonicalText":"刑禁暴，爵舉賢，則政均矣。","chunks":[["刑禁暴，爵舉賢，則政均矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-11_s-8","passageId":"li-ji_ch-19_p-11","order":8,"canonicalText":"仁以愛之，義以正之，如此，則民治行矣。","chunks":[["仁以愛之，義以正之，如此，則民治行矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-1","passageId":"li-ji_ch-19_p-12","order":1,"canonicalText":"樂由中出，禮自外作。","chunks":[["樂由中出，禮自外作。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-2","passageId":"li-ji_ch-19_p-12","order":2,"canonicalText":"樂由中出故靜，禮自外作故文。","chunks":[["樂由中出故靜，禮自外作故文。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-3","passageId":"li-ji_ch-19_p-12","order":3,"canonicalText":"大樂必易，大禮必簡。","chunks":[["大樂必易，大禮必簡。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-4","passageId":"li-ji_ch-19_p-12","order":4,"canonicalText":"樂至則無怨，禮至則不爭。","chunks":[["樂至則無怨，禮至則不爭。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-5","passageId":"li-ji_ch-19_p-12","order":5,"canonicalText":"揖讓而治天下者，禮樂之謂也。","chunks":[["揖讓而治天下者，禮樂之謂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-6","passageId":"li-ji_ch-19_p-12","order":6,"canonicalText":"暴民不作，諸侯賓服，兵革不試，五刑不用，百姓無患，天子不怒，如此，則樂達矣。","chunks":[["暴民不作，諸侯賓服，兵革不試，五刑不用，百姓無患，天子不怒，如此，則樂達矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-12_s-7","passageId":"li-ji_ch-19_p-12","order":7,"canonicalText":"合父子之親，明長幼之序，以敬四海之內天子如此，則禮行矣。","chunks":[["合父子之親，明長幼之序，以敬四海之內天子如此，則禮行矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-1","passageId":"li-ji_ch-19_p-13","order":1,"canonicalText":"大樂與天地同和，大禮與天地同節。","chunks":[["大樂與天地同和，大禮與天地同節。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-2","passageId":"li-ji_ch-19_p-13","order":2,"canonicalText":"和故百物不失，節故祀天祭地，明則有禮樂，幽則有鬼神。","chunks":[["和故百物不失，節故祀天祭地，明則有禮樂，幽則有鬼神。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-3","passageId":"li-ji_ch-19_p-13","order":3,"canonicalText":"如此，則四海之內，合敬同愛矣。","chunks":[["如此，則四海之內，合敬同愛矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-4","passageId":"li-ji_ch-19_p-13","order":4,"canonicalText":"禮者殊事合敬者也；","chunks":[["禮者殊事合敬者也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-5","passageId":"li-ji_ch-19_p-13","order":5,"canonicalText":"樂者異文合愛者也。","chunks":[["樂者異文合愛者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-6","passageId":"li-ji_ch-19_p-13","order":6,"canonicalText":"禮樂之情同，故明王以相沿也。","chunks":[["禮樂之情同，故明王以相沿也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-13_s-7","passageId":"li-ji_ch-19_p-13","order":7,"canonicalText":"故事與時并，名與功偕。","chunks":[["故事與時并，名與功偕。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-1","passageId":"li-ji_ch-19_p-14","order":1,"canonicalText":"故鐘鼓管磬，羽龠干戚，樂之器也。","chunks":[["故鐘鼓管磬，羽龠干戚，樂之器也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-2","passageId":"li-ji_ch-19_p-14","order":2,"canonicalText":"屈伸俯仰，綴兆舒疾，樂之文也。","chunks":[["屈伸俯仰，綴兆舒疾，樂之文也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-3","passageId":"li-ji_ch-19_p-14","order":3,"canonicalText":"簠簋俎豆，制度文章，禮之器也。","chunks":[["簠簋俎豆，制度文章，禮之器也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-4","passageId":"li-ji_ch-19_p-14","order":4,"canonicalText":"升降上下，周還裼襲，禮之文也。","chunks":[["升降上下，周還裼襲，禮之文也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-5","passageId":"li-ji_ch-19_p-14","order":5,"canonicalText":"故知禮樂之情者能作，識禮樂之文者能述。","chunks":[["故知禮樂之情者能作，識禮樂之文者能述。","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-6","passageId":"li-ji_ch-19_p-14","order":6,"canonicalText":"作者之謂聖，述者之謂明；","chunks":[["作者之謂聖，述者之謂明；","zh-Hant"]]},{"id":"li-ji_ch-19_p-14_s-7","passageId":"li-ji_ch-19_p-14","order":7,"canonicalText":"明聖者，述作之謂也。","chunks":[["明聖者，述作之謂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-1","passageId":"li-ji_ch-19_p-15","order":1,"canonicalText":"樂者，天地之和也；","chunks":[["樂者，天地之和也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-2","passageId":"li-ji_ch-19_p-15","order":2,"canonicalText":"禮者，天地之序也。","chunks":[["禮者，天地之序也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-3","passageId":"li-ji_ch-19_p-15","order":3,"canonicalText":"和故百物皆化；","chunks":[["和故百物皆化；","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-4","passageId":"li-ji_ch-19_p-15","order":4,"canonicalText":"序故群物皆別。","chunks":[["序故群物皆別。","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-5","passageId":"li-ji_ch-19_p-15","order":5,"canonicalText":"樂由天作，禮以地制。","chunks":[["樂由天作，禮以地制。","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-6","passageId":"li-ji_ch-19_p-15","order":6,"canonicalText":"過制則亂，過作則暴。","chunks":[["過制則亂，過作則暴。","zh-Hant"]]},{"id":"li-ji_ch-19_p-15_s-7","passageId":"li-ji_ch-19_p-15","order":7,"canonicalText":"明於天地，然後能興禮樂也。","chunks":[["明於天地，然後能興禮樂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-16_s-1","passageId":"li-ji_ch-19_p-16","order":1,"canonicalText":"論倫無患，樂之情也；","chunks":[["論倫無患，樂之情也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-16_s-2","passageId":"li-ji_ch-19_p-16","order":2,"canonicalText":"欣喜歡愛，樂之官也。","chunks":[["欣喜歡愛，樂之官也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-16_s-3","passageId":"li-ji_ch-19_p-16","order":3,"canonicalText":"中正無邪，禮之質也，莊敬恭順。","chunks":[["中正無邪，禮之質也，莊敬恭順。","zh-Hant"]]},{"id":"li-ji_ch-19_p-16_s-4","passageId":"li-ji_ch-19_p-16","order":4,"canonicalText":"禮之制也。","chunks":[["禮之制也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-16_s-5","passageId":"li-ji_ch-19_p-16","order":5,"canonicalText":"若夫禮樂之施於金石，越於聲音，用於宗廟社稷，事乎山川鬼神，則此所與民同也。","chunks":[["若夫禮樂之施於金石，越於聲音，用於宗廟社稷，事乎山川鬼神，則此所與民同也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-1","passageId":"li-ji_ch-19_p-17","order":1,"canonicalText":"王者功成作樂，治定制禮。","chunks":[["王者功成作樂，治定制禮。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-2","passageId":"li-ji_ch-19_p-17","order":2,"canonicalText":"其功大者其樂備，其治辯者其禮具。","chunks":[["其功大者其樂備，其治辯者其禮具。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-3","passageId":"li-ji_ch-19_p-17","order":3,"canonicalText":"干戚之舞非備樂也，孰亨而祀非達禮也。","chunks":[["干戚之舞非備樂也，孰亨而祀非達禮也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-4","passageId":"li-ji_ch-19_p-17","order":4,"canonicalText":"五帝殊時，不相沿樂；","chunks":[["五帝殊時，不相沿樂；","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-5","passageId":"li-ji_ch-19_p-17","order":5,"canonicalText":"三王異世，不相襲禮。","chunks":[["三王異世，不相襲禮。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-6","passageId":"li-ji_ch-19_p-17","order":6,"canonicalText":"樂極則憂，禮粗則偏矣。","chunks":[["樂極則憂，禮粗則偏矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-17_s-7","passageId":"li-ji_ch-19_p-17","order":7,"canonicalText":"及夫敦樂而無憂，禮備而不偏者，其唯大聖乎？","chunks":[["及夫敦樂而無憂，禮備而不偏者，其唯大聖乎？","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-1","passageId":"li-ji_ch-19_p-18","order":1,"canonicalText":"天高地下，萬物散殊，而禮制行矣。","chunks":[["天高地下，萬物散殊，而禮制行矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-2","passageId":"li-ji_ch-19_p-18","order":2,"canonicalText":"流而不息，合同而化，而樂興焉。","chunks":[["流而不息，合同而化，而樂興焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-3","passageId":"li-ji_ch-19_p-18","order":3,"canonicalText":"春作夏長，仁也；","chunks":[["春作夏長，仁也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-4","passageId":"li-ji_ch-19_p-18","order":4,"canonicalText":"秋斂冬藏，義也。","chunks":[["秋斂冬藏，義也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-5","passageId":"li-ji_ch-19_p-18","order":5,"canonicalText":"仁近於樂，義近於禮。","chunks":[["仁近於樂，義近於禮。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-6","passageId":"li-ji_ch-19_p-18","order":6,"canonicalText":"樂者敦和，率神而從天，禮者別宜，居鬼而從地。","chunks":[["樂者敦和，率神而從天，禮者別宜，居鬼而從地。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-7","passageId":"li-ji_ch-19_p-18","order":7,"canonicalText":"故聖人作樂以應天，制禮以配地。","chunks":[["故聖人作樂以應天，制禮以配地。","zh-Hant"]]},{"id":"li-ji_ch-19_p-18_s-8","passageId":"li-ji_ch-19_p-18","order":8,"canonicalText":"禮樂明備，天地官矣。","chunks":[["禮樂明備，天地官矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-1","passageId":"li-ji_ch-19_p-19","order":1,"canonicalText":"天尊地卑，君臣定矣。","chunks":[["天尊地卑，君臣定矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-2","passageId":"li-ji_ch-19_p-19","order":2,"canonicalText":"卑高已陳，貴賤位矣。","chunks":[["卑高已陳，貴賤位矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-3","passageId":"li-ji_ch-19_p-19","order":3,"canonicalText":"動靜有常，小大殊矣。","chunks":[["動靜有常，小大殊矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-4","passageId":"li-ji_ch-19_p-19","order":4,"canonicalText":"方以類聚，物以群分，則性命不同矣。","chunks":[["方以類聚，物以群分，則性命不同矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-5","passageId":"li-ji_ch-19_p-19","order":5,"canonicalText":"在天成象，在地成形；","chunks":[["在天成象，在地成形；","zh-Hant"]]},{"id":"li-ji_ch-19_p-19_s-6","passageId":"li-ji_ch-19_p-19","order":6,"canonicalText":"如此，則禮者天地之別也。","chunks":[["如此，則禮者天地之別也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-20_s-1","passageId":"li-ji_ch-19_p-20","order":1,"canonicalText":"地氣上齊，天氣下降，陰陽相摩，天地相蕩，鼓之以雷霆，奮之以風雨，動之以四時，暖之以日月，而百化興焉。","chunks":[["地氣上齊，天氣下降，陰陽相摩，天地相蕩，鼓之以雷霆，奮之以風雨，動之以四時，暖之以日月，而百化興焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-20_s-2","passageId":"li-ji_ch-19_p-20","order":2,"canonicalText":"如此則樂者天地之和也。","chunks":[["如此則樂者天地之和也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-1","passageId":"li-ji_ch-19_p-21","order":1,"canonicalText":"化不時則不生，男女無辨則亂升；","chunks":[["化不時則不生，男女無辨則亂升；","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-2","passageId":"li-ji_ch-19_p-21","order":2,"canonicalText":"天地之情也。","chunks":[["天地之情也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-3","passageId":"li-ji_ch-19_p-21","order":3,"canonicalText":"及夫禮樂之極乎天而蟠乎地，行乎陰陽而通乎鬼神；","chunks":[["及夫禮樂之極乎天而蟠乎地，行乎陰陽而通乎鬼神；","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-4","passageId":"li-ji_ch-19_p-21","order":4,"canonicalText":"窮高極遠而測深厚。","chunks":[["窮高極遠而測深厚。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-5","passageId":"li-ji_ch-19_p-21","order":5,"canonicalText":"樂著大始，而禮居成物。","chunks":[["樂著大始，而禮居成物。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-6","passageId":"li-ji_ch-19_p-21","order":6,"canonicalText":"著不息者天也，著不動者地也。","chunks":[["著不息者天也，著不動者地也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-7","passageId":"li-ji_ch-19_p-21","order":7,"canonicalText":"一動一靜者天地之間也。","chunks":[["一動一靜者天地之間也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-21_s-8","passageId":"li-ji_ch-19_p-21","order":8,"canonicalText":"故聖人曰禮樂云。","chunks":[["故聖人曰禮樂云。","zh-Hant"]]},{"id":"li-ji_ch-19_p-22_s-1","passageId":"li-ji_ch-19_p-22","order":1,"canonicalText":"昔者，舜作五弦之琴以歌南風，夔始制樂以賞諸侯。","chunks":[["昔者，舜作五弦之琴以歌南風，夔始制樂以賞諸侯。","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-1","passageId":"li-ji_ch-19_p-23","order":1,"canonicalText":"故天子之為樂也，以賞諸侯之有德者也。","chunks":[["故天子之為樂也，以賞諸侯之有德者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-2","passageId":"li-ji_ch-19_p-23","order":2,"canonicalText":"德盛而教尊，五穀時熟，然後賞之以樂。","chunks":[["德盛而教尊，五穀時熟，然後賞之以樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-3","passageId":"li-ji_ch-19_p-23","order":3,"canonicalText":"故其治民勞者，其舞行綴遠；","chunks":[["故其治民勞者，其舞行綴遠；","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-4","passageId":"li-ji_ch-19_p-23","order":4,"canonicalText":"其治民逸者，其舞行綴短。","chunks":[["其治民逸者，其舞行綴短。","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-5","passageId":"li-ji_ch-19_p-23","order":5,"canonicalText":"故觀其舞，知其德；","chunks":[["故觀其舞，知其德；","zh-Hant"]]},{"id":"li-ji_ch-19_p-23_s-6","passageId":"li-ji_ch-19_p-23","order":6,"canonicalText":"聞其謚，知其行也。","chunks":[["聞其謚，知其行也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-24_s-1","passageId":"li-ji_ch-19_p-24","order":1,"canonicalText":"《大章》，章之也。","chunks":[["《大章》，章之也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-24_s-2","passageId":"li-ji_ch-19_p-24","order":2,"canonicalText":"《咸池》，備矣。","chunks":[["《咸池》，備矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-24_s-3","passageId":"li-ji_ch-19_p-24","order":3,"canonicalText":"《韶》，繼也。","chunks":[["《韶》，繼也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-24_s-4","passageId":"li-ji_ch-19_p-24","order":4,"canonicalText":"《夏》，大也。","chunks":[["《夏》，大也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-24_s-5","passageId":"li-ji_ch-19_p-24","order":5,"canonicalText":"殷周之樂，盡矣。","chunks":[["殷周之樂，盡矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-1","passageId":"li-ji_ch-19_p-25","order":1,"canonicalText":"天地之道，寒暑不時則疾，風雨不節則饑。","chunks":[["天地之道，寒暑不時則疾，風雨不節則饑。","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-2","passageId":"li-ji_ch-19_p-25","order":2,"canonicalText":"教者，民之寒暑也；","chunks":[["教者，民之寒暑也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-3","passageId":"li-ji_ch-19_p-25","order":3,"canonicalText":"教不時則傷世。","chunks":[["教不時則傷世。","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-4","passageId":"li-ji_ch-19_p-25","order":4,"canonicalText":"事者民之風雨也；","chunks":[["事者民之風雨也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-5","passageId":"li-ji_ch-19_p-25","order":5,"canonicalText":"事不節則無功。","chunks":[["事不節則無功。","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-6","passageId":"li-ji_ch-19_p-25","order":6,"canonicalText":"然則先王之為樂也。","chunks":[["然則先王之為樂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-25_s-7","passageId":"li-ji_ch-19_p-25","order":7,"canonicalText":"以法治也，善則行象德矣。","chunks":[["以法治也，善則行象德矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-1","passageId":"li-ji_ch-19_p-26","order":1,"canonicalText":"夫豢豕為酒，非以為禍也，而獄訟益繁，則酒之流生禍也。","chunks":[["夫豢豕為酒，非以為禍也，而獄訟益繁，則酒之流生禍也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-2","passageId":"li-ji_ch-19_p-26","order":2,"canonicalText":"是故先王因為酒禮，壹獻之禮，賓主百拜，終日飲酒而不得醉焉；","chunks":[["是故先王因為酒禮，壹獻之禮，賓主百拜，終日飲酒而不得醉焉；","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-3","passageId":"li-ji_ch-19_p-26","order":3,"canonicalText":"此先王之所以備酒禍也。","chunks":[["此先王之所以備酒禍也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-4","passageId":"li-ji_ch-19_p-26","order":4,"canonicalText":"故酒食者所以合歡也；","chunks":[["故酒食者所以合歡也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-5","passageId":"li-ji_ch-19_p-26","order":5,"canonicalText":"樂者所以象德也；","chunks":[["樂者所以象德也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-26_s-6","passageId":"li-ji_ch-19_p-26","order":6,"canonicalText":"禮者所以綴淫也。","chunks":[["禮者所以綴淫也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-27_s-1","passageId":"li-ji_ch-19_p-27","order":1,"canonicalText":"是故先王有大事，必有禮以哀之；","chunks":[["是故先王有大事，必有禮以哀之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-27_s-2","passageId":"li-ji_ch-19_p-27","order":2,"canonicalText":"有大福，必有禮以樂之。","chunks":[["有大福，必有禮以樂之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-27_s-3","passageId":"li-ji_ch-19_p-27","order":3,"canonicalText":"哀樂之分，皆以禮終。","chunks":[["哀樂之分，皆以禮終。","zh-Hant"]]},{"id":"li-ji_ch-19_p-27_s-4","passageId":"li-ji_ch-19_p-27","order":4,"canonicalText":"樂也者，聖人之所樂也，而可以善民心，其感人深，其移風易俗，故先王著其教焉。","chunks":[["樂也者，聖人之所樂也，而可以善民心，其感人深，其移風易俗，故先王著其教焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-1","passageId":"li-ji_ch-19_p-28","order":1,"canonicalText":"夫民有血氣心知之性，而無哀樂喜怒之常，應感起物而動，然後心術形焉。","chunks":[["夫民有血氣心知之性，而無哀樂喜怒之常，應感起物而動，然後心術形焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-2","passageId":"li-ji_ch-19_p-28","order":2,"canonicalText":"是故志微噍殺之音作，而民思憂。","chunks":[["是故志微噍殺之音作，而民思憂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-3","passageId":"li-ji_ch-19_p-28","order":3,"canonicalText":"嘽諧慢易、繁文簡節之音作，而民康樂。","chunks":[["嘽諧慢易、繁文簡節之音作，而民康樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-4","passageId":"li-ji_ch-19_p-28","order":4,"canonicalText":"粗厲猛起、奮末廣賁之音作，而民剛毅。","chunks":[["粗厲猛起、奮末廣賁之音作，而民剛毅。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-5","passageId":"li-ji_ch-19_p-28","order":5,"canonicalText":"廉直、勁正、莊誠之音作，而民肅敬。","chunks":[["廉直、勁正、莊誠之音作，而民肅敬。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-6","passageId":"li-ji_ch-19_p-28","order":6,"canonicalText":"寬裕肉好、順成和動之音作，而民慈愛。","chunks":[["寬裕肉好、順成和動之音作，而民慈愛。","zh-Hant"]]},{"id":"li-ji_ch-19_p-28_s-7","passageId":"li-ji_ch-19_p-28","order":7,"canonicalText":"流辟邪散、狄成滌濫之音作，而民淫亂。","chunks":[["流辟邪散、狄成滌濫之音作，而民淫亂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-1","passageId":"li-ji_ch-19_p-29","order":1,"canonicalText":"是故先王本之情性，稽之度數，制之禮義。","chunks":[["是故先王本之情性，稽之度數，制之禮義。","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-2","passageId":"li-ji_ch-19_p-29","order":2,"canonicalText":"合生氣之和，道五常之行，使之陽而不散，陰而不密，剛氣不怒，柔氣不懾，四暢交於中而發作於外，皆安其位而不相奪也；","chunks":[["合生氣之和，道五常之行，使之陽而不散，陰而不密，剛氣不怒，柔氣不懾，四暢交於中而發作於外，皆安其位而不相奪也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-3","passageId":"li-ji_ch-19_p-29","order":3,"canonicalText":"然後立之學等，廣其節奏，省其文采，以繩德厚。","chunks":[["然後立之學等，廣其節奏，省其文采，以繩德厚。","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-4","passageId":"li-ji_ch-19_p-29","order":4,"canonicalText":"律小大之稱，比終始之序，以象事行。","chunks":[["律小大之稱，比終始之序，以象事行。","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-5","passageId":"li-ji_ch-19_p-29","order":5,"canonicalText":"使親疏貴賤、長幼男女之理，皆形見於樂，故曰：「樂觀其深矣。","chunks":[["使親疏貴賤、長幼男女之理，皆形見於樂，故曰：「樂觀其深矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-29_s-6","passageId":"li-ji_ch-19_p-29","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-30_s-1","passageId":"li-ji_ch-19_p-30","order":1,"canonicalText":"土敝則草木不長，水煩則魚鱉不大，氣衰則生物不遂，世亂則禮慝而樂淫。","chunks":[["土敝則草木不長，水煩則魚鱉不大，氣衰則生物不遂，世亂則禮慝而樂淫。","zh-Hant"]]},{"id":"li-ji_ch-19_p-30_s-2","passageId":"li-ji_ch-19_p-30","order":2,"canonicalText":"是故其聲哀而不莊，樂而不安，慢易以犯節，流湎以忘本。","chunks":[["是故其聲哀而不莊，樂而不安，慢易以犯節，流湎以忘本。","zh-Hant"]]},{"id":"li-ji_ch-19_p-30_s-3","passageId":"li-ji_ch-19_p-30","order":3,"canonicalText":"廣則容奸，狹則思欲，感條暢之氣而滅平和之德。","chunks":[["廣則容奸，狹則思欲，感條暢之氣而滅平和之德。","zh-Hant"]]},{"id":"li-ji_ch-19_p-30_s-4","passageId":"li-ji_ch-19_p-30","order":4,"canonicalText":"是以君子賤之也。","chunks":[["是以君子賤之也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-1","passageId":"li-ji_ch-19_p-31","order":1,"canonicalText":"凡奸聲感人，而逆氣應之；","chunks":[["凡奸聲感人，而逆氣應之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-2","passageId":"li-ji_ch-19_p-31","order":2,"canonicalText":"逆氣成象，而淫樂興焉。","chunks":[["逆氣成象，而淫樂興焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-3","passageId":"li-ji_ch-19_p-31","order":3,"canonicalText":"正聲感人，而順氣應之；","chunks":[["正聲感人，而順氣應之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-4","passageId":"li-ji_ch-19_p-31","order":4,"canonicalText":"順氣成象，而和樂興焉。","chunks":[["順氣成象，而和樂興焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-5","passageId":"li-ji_ch-19_p-31","order":5,"canonicalText":"倡和有應，回邪曲直，各歸其分；","chunks":[["倡和有應，回邪曲直，各歸其分；","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-6","passageId":"li-ji_ch-19_p-31","order":6,"canonicalText":"而萬物之理，各以其類相動也。","chunks":[["而萬物之理，各以其類相動也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-7","passageId":"li-ji_ch-19_p-31","order":7,"canonicalText":"是故君子反情以和其志，比類以成其行。","chunks":[["是故君子反情以和其志，比類以成其行。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-8","passageId":"li-ji_ch-19_p-31","order":8,"canonicalText":"奸聲亂色，不留聰明；","chunks":[["奸聲亂色，不留聰明；","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-9","passageId":"li-ji_ch-19_p-31","order":9,"canonicalText":"淫樂慝禮，不接心術。","chunks":[["淫樂慝禮，不接心術。","zh-Hant"]]},{"id":"li-ji_ch-19_p-31_s-10","passageId":"li-ji_ch-19_p-31","order":10,"canonicalText":"惰慢邪辟之氣不設於身體，使耳目鼻口、心知百體皆由順正以行其義。","chunks":[["惰慢邪辟之氣不設於身體，使耳目鼻口、心知百體皆由順正以行其義。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-1","passageId":"li-ji_ch-19_p-32","order":1,"canonicalText":"然後發以聲音，而文以琴瑟，動以干戚，飾以羽旄，從以簫管。","chunks":[["然後發以聲音，而文以琴瑟，動以干戚，飾以羽旄，從以簫管。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-2","passageId":"li-ji_ch-19_p-32","order":2,"canonicalText":"奮至德之光，動四氣之和，以著萬物之理。","chunks":[["奮至德之光，動四氣之和，以著萬物之理。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-3","passageId":"li-ji_ch-19_p-32","order":3,"canonicalText":"是故清明象天，廣大象地，終始象四時，周還象風雨。","chunks":[["是故清明象天，廣大象地，終始象四時，周還象風雨。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-4","passageId":"li-ji_ch-19_p-32","order":4,"canonicalText":"五色成文而不亂，八風從律而不奸，百度得數而有常。","chunks":[["五色成文而不亂，八風從律而不奸，百度得數而有常。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-5","passageId":"li-ji_ch-19_p-32","order":5,"canonicalText":"小大相成，終始相生。","chunks":[["小大相成，終始相生。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-6","passageId":"li-ji_ch-19_p-32","order":6,"canonicalText":"倡和清濁，迭相為經。","chunks":[["倡和清濁，迭相為經。","zh-Hant"]]},{"id":"li-ji_ch-19_p-32_s-7","passageId":"li-ji_ch-19_p-32","order":7,"canonicalText":"故樂行而倫清，耳目聰明，血氣和平，移風易俗，天下皆寧。","chunks":[["故樂行而倫清，耳目聰明，血氣和平，移風易俗，天下皆寧。","zh-Hant"]]},{"id":"li-ji_ch-19_p-33_s-1","passageId":"li-ji_ch-19_p-33","order":1,"canonicalText":"故曰：樂者樂也。","chunks":[["故曰：樂者樂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-33_s-2","passageId":"li-ji_ch-19_p-33","order":2,"canonicalText":"君子樂得其道，小人樂得其欲。","chunks":[["君子樂得其道，小人樂得其欲。","zh-Hant"]]},{"id":"li-ji_ch-19_p-33_s-3","passageId":"li-ji_ch-19_p-33","order":3,"canonicalText":"以道制欲，則樂而不亂；","chunks":[["以道制欲，則樂而不亂；","zh-Hant"]]},{"id":"li-ji_ch-19_p-33_s-4","passageId":"li-ji_ch-19_p-33","order":4,"canonicalText":"以欲忘道，則惑而不樂。","chunks":[["以欲忘道，則惑而不樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-1","passageId":"li-ji_ch-19_p-34","order":1,"canonicalText":"是故君子反情以和其志，廣樂以成其教，樂行而民鄉方，可以觀德矣。","chunks":[["是故君子反情以和其志，廣樂以成其教，樂行而民鄉方，可以觀德矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-2","passageId":"li-ji_ch-19_p-34","order":2,"canonicalText":"德者性之端也。","chunks":[["德者性之端也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-3","passageId":"li-ji_ch-19_p-34","order":3,"canonicalText":"樂者德之華也。","chunks":[["樂者德之華也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-4","passageId":"li-ji_ch-19_p-34","order":4,"canonicalText":"金石絲竹，樂之器也。","chunks":[["金石絲竹，樂之器也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-5","passageId":"li-ji_ch-19_p-34","order":5,"canonicalText":"詩言其志也，歌詠其聲也，舞動其容也。","chunks":[["詩言其志也，歌詠其聲也，舞動其容也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-6","passageId":"li-ji_ch-19_p-34","order":6,"canonicalText":"三者本於心，然後樂氣從之。","chunks":[["三者本於心，然後樂氣從之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-7","passageId":"li-ji_ch-19_p-34","order":7,"canonicalText":"是故情深而文明，氣盛而化神。","chunks":[["是故情深而文明，氣盛而化神。","zh-Hant"]]},{"id":"li-ji_ch-19_p-34_s-8","passageId":"li-ji_ch-19_p-34","order":8,"canonicalText":"和順積中而英華發外，唯樂不可以為偽。","chunks":[["和順積中而英華發外，唯樂不可以為偽。","zh-Hant"]]},{"id":"li-ji_ch-19_p-35_s-1","passageId":"li-ji_ch-19_p-35","order":1,"canonicalText":"樂者，心之動也；","chunks":[["樂者，心之動也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-35_s-2","passageId":"li-ji_ch-19_p-35","order":2,"canonicalText":"聲者，樂之象也。","chunks":[["聲者，樂之象也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-35_s-3","passageId":"li-ji_ch-19_p-35","order":3,"canonicalText":"文采節奏，聲之飾也。","chunks":[["文采節奏，聲之飾也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-35_s-4","passageId":"li-ji_ch-19_p-35","order":4,"canonicalText":"君子動其本。","chunks":[["君子動其本。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-1","passageId":"li-ji_ch-19_p-36","order":1,"canonicalText":"樂其象，然後治其飾。","chunks":[["樂其象，然後治其飾。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-2","passageId":"li-ji_ch-19_p-36","order":2,"canonicalText":"是故先鼓以警戒，三步以見方，再始以著往，復亂以飭歸。","chunks":[["是故先鼓以警戒，三步以見方，再始以著往，復亂以飭歸。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-3","passageId":"li-ji_ch-19_p-36","order":3,"canonicalText":"奮疾而不拔，極幽而不隱。","chunks":[["奮疾而不拔，極幽而不隱。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-4","passageId":"li-ji_ch-19_p-36","order":4,"canonicalText":"獨樂其志，不厭其道；","chunks":[["獨樂其志，不厭其道；","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-5","passageId":"li-ji_ch-19_p-36","order":5,"canonicalText":"備舉其道，不私其欲。","chunks":[["備舉其道，不私其欲。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-6","passageId":"li-ji_ch-19_p-36","order":6,"canonicalText":"是故情見而義立，樂終而德尊。","chunks":[["是故情見而義立，樂終而德尊。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-7","passageId":"li-ji_ch-19_p-36","order":7,"canonicalText":"君子以好善，小人以聽過。","chunks":[["君子以好善，小人以聽過。","zh-Hant"]]},{"id":"li-ji_ch-19_p-36_s-8","passageId":"li-ji_ch-19_p-36","order":8,"canonicalText":"故曰：生民之道，樂為大焉。","chunks":[["故曰：生民之道，樂為大焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-37_s-1","passageId":"li-ji_ch-19_p-37","order":1,"canonicalText":"樂也者施也；","chunks":[["樂也者施也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-37_s-2","passageId":"li-ji_ch-19_p-37","order":2,"canonicalText":"禮也者報也。","chunks":[["禮也者報也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-37_s-3","passageId":"li-ji_ch-19_p-37","order":3,"canonicalText":"樂，樂其所自生；","chunks":[["樂，樂其所自生；","zh-Hant"]]},{"id":"li-ji_ch-19_p-37_s-4","passageId":"li-ji_ch-19_p-37","order":4,"canonicalText":"而禮，反其所自始。","chunks":[["而禮，反其所自始。","zh-Hant"]]},{"id":"li-ji_ch-19_p-37_s-5","passageId":"li-ji_ch-19_p-37","order":5,"canonicalText":"樂章德，禮報情反始也。","chunks":[["樂章德，禮報情反始也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-38_s-1","passageId":"li-ji_ch-19_p-38","order":1,"canonicalText":"所謂大輅者，天子之車也。","chunks":[["所謂大輅者，天子之車也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-38_s-2","passageId":"li-ji_ch-19_p-38","order":2,"canonicalText":"龍旗九旒，天子之旌也。","chunks":[["龍旗九旒，天子之旌也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-38_s-3","passageId":"li-ji_ch-19_p-38","order":3,"canonicalText":"青黑緣者，天子之寶龜也。","chunks":[["青黑緣者，天子之寶龜也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-38_s-4","passageId":"li-ji_ch-19_p-38","order":4,"canonicalText":"從之以牛羊之群，則所以贈諸侯也。","chunks":[["從之以牛羊之群，則所以贈諸侯也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-39_s-1","passageId":"li-ji_ch-19_p-39","order":1,"canonicalText":"樂也者，情之不可變者也。","chunks":[["樂也者，情之不可變者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-39_s-2","passageId":"li-ji_ch-19_p-39","order":2,"canonicalText":"禮也者，理之不可易者也。","chunks":[["禮也者，理之不可易者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-39_s-3","passageId":"li-ji_ch-19_p-39","order":3,"canonicalText":"樂統同，禮辨異，禮樂之說，管乎人情矣。","chunks":[["樂統同，禮辨異，禮樂之說，管乎人情矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-40_s-1","passageId":"li-ji_ch-19_p-40","order":1,"canonicalText":"窮本知變，樂之情也；","chunks":[["窮本知變，樂之情也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-40_s-2","passageId":"li-ji_ch-19_p-40","order":2,"canonicalText":"著誠去偽，禮之經也。","chunks":[["著誠去偽，禮之經也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-40_s-3","passageId":"li-ji_ch-19_p-40","order":3,"canonicalText":"禮樂偩天地之情，達神明之德，降興上下之神，而凝是精粗之體，領父子君臣之節。","chunks":[["禮樂偩天地之情，達神明之德，降興上下之神，而凝是精粗之體，領父子君臣之節。","zh-Hant"]]},{"id":"li-ji_ch-19_p-41_s-1","passageId":"li-ji_ch-19_p-41","order":1,"canonicalText":"是故大人舉禮樂，則天地將為昭焉。","chunks":[["是故大人舉禮樂，則天地將為昭焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-41_s-2","passageId":"li-ji_ch-19_p-41","order":2,"canonicalText":"天地欣合，陰陽相得，煦嫗覆育萬物，然後草木茂，區萌達，羽翼奮，角觡生，蟄蟲昭蘇，羽者嫗伏，毛者孕鬻，胎生者不殰，而卵生者不殈，則樂之道歸焉耳。","chunks":[["天地欣合，陰陽相得，煦嫗覆育萬物，然後草木茂，區萌達，羽翼奮，角觡生，蟄蟲昭蘇，羽者嫗伏，毛者孕鬻，胎生者不殰，而卵生者不殈，則樂之道歸焉耳。","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-1","passageId":"li-ji_ch-19_p-42","order":1,"canonicalText":"樂者，非謂黃鐘大呂弦歌干揚也，樂之末節也，故童者舞之。","chunks":[["樂者，非謂黃鐘大呂弦歌干揚也，樂之末節也，故童者舞之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-2","passageId":"li-ji_ch-19_p-42","order":2,"canonicalText":"鋪筵席，陳尊俎，列籩豆，以升降為禮者，禮之末節也，故有司掌之。","chunks":[["鋪筵席，陳尊俎，列籩豆，以升降為禮者，禮之末節也，故有司掌之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-3","passageId":"li-ji_ch-19_p-42","order":3,"canonicalText":"樂師辨乎聲詩，故北面而弦；","chunks":[["樂師辨乎聲詩，故北面而弦；","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-4","passageId":"li-ji_ch-19_p-42","order":4,"canonicalText":"宗祝辨乎宗廟之禮，故後尸；","chunks":[["宗祝辨乎宗廟之禮，故後尸；","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-5","passageId":"li-ji_ch-19_p-42","order":5,"canonicalText":"商祝辨乎喪禮，故後主人。","chunks":[["商祝辨乎喪禮，故後主人。","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-6","passageId":"li-ji_ch-19_p-42","order":6,"canonicalText":"是故德成而上，藝成而下；","chunks":[["是故德成而上，藝成而下；","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-7","passageId":"li-ji_ch-19_p-42","order":7,"canonicalText":"行成而先，事成而後。","chunks":[["行成而先，事成而後。","zh-Hant"]]},{"id":"li-ji_ch-19_p-42_s-8","passageId":"li-ji_ch-19_p-42","order":8,"canonicalText":"是故先王有上有下，有先有後，然後可以有制於天下也。","chunks":[["是故先王有上有下，有先有後，然後可以有制於天下也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-43_s-1","passageId":"li-ji_ch-19_p-43","order":1,"canonicalText":"魏文侯問於子夏曰：「吾端冕而聽古樂，則唯恐臥；","chunks":[["魏文侯問於子夏曰：「吾端冕而聽古樂，則唯恐臥；","zh-Hant"]]},{"id":"li-ji_ch-19_p-43_s-2","passageId":"li-ji_ch-19_p-43","order":2,"canonicalText":"聽鄭衛之音，則不知倦。","chunks":[["聽鄭衛之音，則不知倦。","zh-Hant"]]},{"id":"li-ji_ch-19_p-43_s-3","passageId":"li-ji_ch-19_p-43","order":3,"canonicalText":"敢問：古樂之如彼何也？","chunks":[["敢問：古樂之如彼何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-43_s-4","passageId":"li-ji_ch-19_p-43","order":4,"canonicalText":"新樂之如此何也？","chunks":[["新樂之如此何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-43_s-5","passageId":"li-ji_ch-19_p-43","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-44_s-1","passageId":"li-ji_ch-19_p-44","order":1,"canonicalText":"子夏對曰：「今夫古樂，進旅退旅，和正以廣。","chunks":[["子夏對曰：「今夫古樂，進旅退旅，和正以廣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-44_s-2","passageId":"li-ji_ch-19_p-44","order":2,"canonicalText":"弦匏笙簧，會守拊鼓，始奏以文，復亂以武，治亂以相，訊疾以雅。","chunks":[["弦匏笙簧，會守拊鼓，始奏以文，復亂以武，治亂以相，訊疾以雅。","zh-Hant"]]},{"id":"li-ji_ch-19_p-44_s-3","passageId":"li-ji_ch-19_p-44","order":3,"canonicalText":"君子於是語，於是道古，修身及家，平均天下。","chunks":[["君子於是語，於是道古，修身及家，平均天下。","zh-Hant"]]},{"id":"li-ji_ch-19_p-44_s-4","passageId":"li-ji_ch-19_p-44","order":4,"canonicalText":"此古樂之發也。","chunks":[["此古樂之發也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-1","passageId":"li-ji_ch-19_p-45","order":1,"canonicalText":"今夫新樂，進俯退俯，奸聲以濫，溺而不止；","chunks":[["今夫新樂，進俯退俯，奸聲以濫，溺而不止；","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-2","passageId":"li-ji_ch-19_p-45","order":2,"canonicalText":"及優侏儒，糅雜子女，不知父子。","chunks":[["及優侏儒，糅雜子女，不知父子。","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-3","passageId":"li-ji_ch-19_p-45","order":3,"canonicalText":"樂終不可以語，不可以道古。","chunks":[["樂終不可以語，不可以道古。","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-4","passageId":"li-ji_ch-19_p-45","order":4,"canonicalText":"此新樂之發也。","chunks":[["此新樂之發也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-5","passageId":"li-ji_ch-19_p-45","order":5,"canonicalText":"今君之所問者樂也，所好者音也！","chunks":[["今君之所問者樂也，所好者音也！","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-6","passageId":"li-ji_ch-19_p-45","order":6,"canonicalText":"夫樂者，與音相近而不同。","chunks":[["夫樂者，與音相近而不同。","zh-Hant"]]},{"id":"li-ji_ch-19_p-45_s-7","passageId":"li-ji_ch-19_p-45","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-1","passageId":"li-ji_ch-19_p-46","order":1,"canonicalText":"文侯曰：「敢問何如？","chunks":[["文侯曰：「敢問何如？","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-2","passageId":"li-ji_ch-19_p-46","order":2,"canonicalText":"」子夏對曰：「夫古者，天地順而四時當，民有德而五穀昌，疾疢不作而無妖祥，此之謂大當。","chunks":[["」子夏對曰：「夫古者，天地順而四時當，民有德而五穀昌，疾疢不作而無妖祥，此之謂大當。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-3","passageId":"li-ji_ch-19_p-46","order":3,"canonicalText":"然後聖人作為父子君臣，以為紀綱。","chunks":[["然後聖人作為父子君臣，以為紀綱。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-4","passageId":"li-ji_ch-19_p-46","order":4,"canonicalText":"紀綱既正，天下大定。","chunks":[["紀綱既正，天下大定。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-5","passageId":"li-ji_ch-19_p-46","order":5,"canonicalText":"天下大定，然後正六律，和五聲，弦歌詩頌，此之謂德音；","chunks":[["天下大定，然後正六律，和五聲，弦歌詩頌，此之謂德音；","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-6","passageId":"li-ji_ch-19_p-46","order":6,"canonicalText":"德音之謂樂。","chunks":[["德音之謂樂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-7","passageId":"li-ji_ch-19_p-46","order":7,"canonicalText":"《詩》云：『莫其德音，其德克明。","chunks":[["《詩》云：『莫其德音，其德克明。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-8","passageId":"li-ji_ch-19_p-46","order":8,"canonicalText":"克明克類，克長克君，王此大邦；","chunks":[["克明克類，克長克君，王此大邦；","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-9","passageId":"li-ji_ch-19_p-46","order":9,"canonicalText":"克順克俾，俾於文王，其德靡悔。","chunks":[["克順克俾，俾於文王，其德靡悔。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-10","passageId":"li-ji_ch-19_p-46","order":10,"canonicalText":"既受帝祉，施於孫子。","chunks":[["既受帝祉，施於孫子。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-11","passageId":"li-ji_ch-19_p-46","order":11,"canonicalText":"』此之謂也。","chunks":[["』此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-12","passageId":"li-ji_ch-19_p-46","order":12,"canonicalText":"今君之所好者，其溺音乎？","chunks":[["今君之所好者，其溺音乎？","zh-Hant"]]},{"id":"li-ji_ch-19_p-46_s-13","passageId":"li-ji_ch-19_p-46","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-1","passageId":"li-ji_ch-19_p-47","order":1,"canonicalText":"文侯曰：「敢問溺音何從出也？","chunks":[["文侯曰：「敢問溺音何從出也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-2","passageId":"li-ji_ch-19_p-47","order":2,"canonicalText":"」子夏對曰：「鄭音好濫淫志，宋音燕女溺志，衛音趨數煩志，齊音敖辟喬志；","chunks":[["」子夏對曰：「鄭音好濫淫志，宋音燕女溺志，衛音趨數煩志，齊音敖辟喬志；","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-3","passageId":"li-ji_ch-19_p-47","order":3,"canonicalText":"此四者皆淫於色而害於德，是以祭祀弗用也。","chunks":[["此四者皆淫於色而害於德，是以祭祀弗用也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-4","passageId":"li-ji_ch-19_p-47","order":4,"canonicalText":"《詩》云：『肅雍和鳴，先祖是聽。","chunks":[["《詩》云：『肅雍和鳴，先祖是聽。","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-5","passageId":"li-ji_ch-19_p-47","order":5,"canonicalText":"』夫肅肅，敬也；","chunks":[["』夫肅肅，敬也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-6","passageId":"li-ji_ch-19_p-47","order":6,"canonicalText":"雍雍，和也。","chunks":[["雍雍，和也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-47_s-7","passageId":"li-ji_ch-19_p-47","order":7,"canonicalText":"夫敬以和，何事不行？","chunks":[["夫敬以和，何事不行？","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-1","passageId":"li-ji_ch-19_p-48","order":1,"canonicalText":"為人君者謹其所好惡而已矣。","chunks":[["為人君者謹其所好惡而已矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-2","passageId":"li-ji_ch-19_p-48","order":2,"canonicalText":"君好之，則臣為之。","chunks":[["君好之，則臣為之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-3","passageId":"li-ji_ch-19_p-48","order":3,"canonicalText":"上行之，則民從之。","chunks":[["上行之，則民從之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-4","passageId":"li-ji_ch-19_p-48","order":4,"canonicalText":"《詩》云：『誘民孔易』，此之謂也。","chunks":[["《詩》云：『誘民孔易』，此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-5","passageId":"li-ji_ch-19_p-48","order":5,"canonicalText":"」然後，聖人作為鞉、鼓、椌、楬、塤、篪，此六者德音之音也。","chunks":[["」然後，聖人作為鞉、鼓、椌、楬、塤、篪，此六者德音之音也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-48_s-6","passageId":"li-ji_ch-19_p-48","order":6,"canonicalText":"然後鐘磬竽瑟以和之，干戚旄狄以舞之，此所以祭先王之廟也，所以獻酬酳酢也，所以官序貴賤各得其宜也，所以示後世有尊卑長幼之序也。","chunks":[["然後鐘磬竽瑟以和之，干戚旄狄以舞之，此所以祭先王之廟也，所以獻酬酳酢也，所以官序貴賤各得其宜也，所以示後世有尊卑長幼之序也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-1","passageId":"li-ji_ch-19_p-49","order":1,"canonicalText":"鐘聲鏗，鏗以立號，號以立橫，橫以立武。","chunks":[["鐘聲鏗，鏗以立號，號以立橫，橫以立武。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-2","passageId":"li-ji_ch-19_p-49","order":2,"canonicalText":"君子聽鐘聲則思武臣。","chunks":[["君子聽鐘聲則思武臣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-3","passageId":"li-ji_ch-19_p-49","order":3,"canonicalText":"石聲磬，磬以立辨，辨以致死。","chunks":[["石聲磬，磬以立辨，辨以致死。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-4","passageId":"li-ji_ch-19_p-49","order":4,"canonicalText":"君子聽磬聲則思死封疆之臣。","chunks":[["君子聽磬聲則思死封疆之臣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-5","passageId":"li-ji_ch-19_p-49","order":5,"canonicalText":"絲聲哀，哀以立廉，廉以立志。","chunks":[["絲聲哀，哀以立廉，廉以立志。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-6","passageId":"li-ji_ch-19_p-49","order":6,"canonicalText":"君子聽琴瑟之聲則思志義之臣。","chunks":[["君子聽琴瑟之聲則思志義之臣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-7","passageId":"li-ji_ch-19_p-49","order":7,"canonicalText":"竹聲濫，濫以立會，會以聚眾。","chunks":[["竹聲濫，濫以立會，會以聚眾。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-8","passageId":"li-ji_ch-19_p-49","order":8,"canonicalText":"君子聽竽笙簫管之聲，則思畜聚之臣。","chunks":[["君子聽竽笙簫管之聲，則思畜聚之臣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-9","passageId":"li-ji_ch-19_p-49","order":9,"canonicalText":"鼓鼙之聲讙，讙以立動，動以進眾。","chunks":[["鼓鼙之聲讙，讙以立動，動以進眾。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-10","passageId":"li-ji_ch-19_p-49","order":10,"canonicalText":"君子聽鼓鼙之聲，則思將帥之臣。","chunks":[["君子聽鼓鼙之聲，則思將帥之臣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-49_s-11","passageId":"li-ji_ch-19_p-49","order":11,"canonicalText":"君子之聽音，非聽其鏗槍而已也，彼亦有所合之也。","chunks":[["君子之聽音，非聽其鏗槍而已也，彼亦有所合之也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-50_s-1","passageId":"li-ji_ch-19_p-50","order":1,"canonicalText":"賓牟賈侍坐於孔子，孔子與之言及樂，曰：「夫《武》之備戒之已久，何也？","chunks":[["賓牟賈侍坐於孔子，孔子與之言及樂，曰：「夫《武》之備戒之已久，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-50_s-2","passageId":"li-ji_ch-19_p-50","order":2,"canonicalText":"」對曰：「病不得眾也。","chunks":[["」對曰：「病不得眾也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-50_s-3","passageId":"li-ji_ch-19_p-50","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-51_s-1","passageId":"li-ji_ch-19_p-51","order":1,"canonicalText":"「詠嘆之，淫液之，何也？","chunks":[["「詠嘆之，淫液之，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-51_s-2","passageId":"li-ji_ch-19_p-51","order":2,"canonicalText":"」對曰：「恐不逮事也。","chunks":[["」對曰：「恐不逮事也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-51_s-3","passageId":"li-ji_ch-19_p-51","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-52_s-1","passageId":"li-ji_ch-19_p-52","order":1,"canonicalText":"「發揚蹈厲之已蚤，何也？","chunks":[["「發揚蹈厲之已蚤，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-52_s-2","passageId":"li-ji_ch-19_p-52","order":2,"canonicalText":"」對曰：「及時事也。","chunks":[["」對曰：「及時事也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-52_s-3","passageId":"li-ji_ch-19_p-52","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-53_s-1","passageId":"li-ji_ch-19_p-53","order":1,"canonicalText":"「武坐致右憲左，何也？","chunks":[["「武坐致右憲左，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-53_s-2","passageId":"li-ji_ch-19_p-53","order":2,"canonicalText":"」對曰：「非武坐也。","chunks":[["」對曰：「非武坐也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-53_s-3","passageId":"li-ji_ch-19_p-53","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-54_s-1","passageId":"li-ji_ch-19_p-54","order":1,"canonicalText":"「聲淫及商，何也？","chunks":[["「聲淫及商，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-54_s-2","passageId":"li-ji_ch-19_p-54","order":2,"canonicalText":"」對曰：「非《武》音也。","chunks":[["」對曰：「非《武》音也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-54_s-3","passageId":"li-ji_ch-19_p-54","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-1","passageId":"li-ji_ch-19_p-55","order":1,"canonicalText":"子曰：「若非《武》音，則何音也？","chunks":[["子曰：「若非《武》音，則何音也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-2","passageId":"li-ji_ch-19_p-55","order":2,"canonicalText":"」對曰：「有司失其傳也。","chunks":[["」對曰：「有司失其傳也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-3","passageId":"li-ji_ch-19_p-55","order":3,"canonicalText":"若非有司失其傳，則武王之志荒矣。","chunks":[["若非有司失其傳，則武王之志荒矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-4","passageId":"li-ji_ch-19_p-55","order":4,"canonicalText":"」子曰：「唯！","chunks":[["」子曰：「唯！","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-5","passageId":"li-ji_ch-19_p-55","order":5,"canonicalText":"丘之聞諸萇弘，亦若吾子之言是也。","chunks":[["丘之聞諸萇弘，亦若吾子之言是也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-55_s-6","passageId":"li-ji_ch-19_p-55","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-56_s-1","passageId":"li-ji_ch-19_p-56","order":1,"canonicalText":"賓牟賈起，免席而請曰：「夫《武》之備戒之已久，則既聞命矣，敢問：遲之遲而又久，何也？","chunks":[["賓牟賈起，免席而請曰：「夫《武》之備戒之已久，則既聞命矣，敢問：遲之遲而又久，何也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-56_s-2","passageId":"li-ji_ch-19_p-56","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-1","passageId":"li-ji_ch-19_p-57","order":1,"canonicalText":"子曰：「居！","chunks":[["子曰：「居！","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-2","passageId":"li-ji_ch-19_p-57","order":2,"canonicalText":"吾語汝。","chunks":[["吾語汝。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-3","passageId":"li-ji_ch-19_p-57","order":3,"canonicalText":"夫樂者，象成者也；","chunks":[["夫樂者，象成者也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-4","passageId":"li-ji_ch-19_p-57","order":4,"canonicalText":"總干而山立，武王之事也；","chunks":[["總干而山立，武王之事也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-5","passageId":"li-ji_ch-19_p-57","order":5,"canonicalText":"發揚蹈厲，大公之志也。","chunks":[["發揚蹈厲，大公之志也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-6","passageId":"li-ji_ch-19_p-57","order":6,"canonicalText":"《武》亂皆坐，周、召之治也。","chunks":[["《武》亂皆坐，周、召之治也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-7","passageId":"li-ji_ch-19_p-57","order":7,"canonicalText":"且夫《武》，始而北出，再成而滅商。","chunks":[["且夫《武》，始而北出，再成而滅商。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-8","passageId":"li-ji_ch-19_p-57","order":8,"canonicalText":"三成而南，四成而南國是疆，五成而分周公左召公右，六成復綴以崇。","chunks":[["三成而南，四成而南國是疆，五成而分周公左召公右，六成復綴以崇。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-9","passageId":"li-ji_ch-19_p-57","order":9,"canonicalText":"天子夾振之而駟伐，盛威於中國也。","chunks":[["天子夾振之而駟伐，盛威於中國也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-57_s-10","passageId":"li-ji_ch-19_p-57","order":10,"canonicalText":"分夾而進，事早濟也，久立於綴，以待諸侯之至也。","chunks":[["分夾而進，事早濟也，久立於綴，以待諸侯之至也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-1","passageId":"li-ji_ch-19_p-58","order":1,"canonicalText":"且女獨未聞牧野之語乎？","chunks":[["且女獨未聞牧野之語乎？","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-2","passageId":"li-ji_ch-19_p-58","order":2,"canonicalText":"武王克殷反商。","chunks":[["武王克殷反商。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-3","passageId":"li-ji_ch-19_p-58","order":3,"canonicalText":"未及下車而封黃帝之後於薊，封帝堯之後於祝，封帝舜之後於陳。","chunks":[["未及下車而封黃帝之後於薊，封帝堯之後於祝，封帝舜之後於陳。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-4","passageId":"li-ji_ch-19_p-58","order":4,"canonicalText":"下車而封夏后氏之後於杞，投殷之後於宋。","chunks":[["下車而封夏后氏之後於杞，投殷之後於宋。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-5","passageId":"li-ji_ch-19_p-58","order":5,"canonicalText":"封王子比干之墓，釋箕子之囚，使之行商容而復其位。","chunks":[["封王子比干之墓，釋箕子之囚，使之行商容而復其位。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-6","passageId":"li-ji_ch-19_p-58","order":6,"canonicalText":"庶民弛政，庶士倍祿。","chunks":[["庶民弛政，庶士倍祿。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-7","passageId":"li-ji_ch-19_p-58","order":7,"canonicalText":"濟河而西，馬散之華山之陽，而弗復乘；","chunks":[["濟河而西，馬散之華山之陽，而弗復乘；","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-8","passageId":"li-ji_ch-19_p-58","order":8,"canonicalText":"牛散之桃林之野，而弗復服。","chunks":[["牛散之桃林之野，而弗復服。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-9","passageId":"li-ji_ch-19_p-58","order":9,"canonicalText":"車甲釁而藏之府庫，而弗復用。","chunks":[["車甲釁而藏之府庫，而弗復用。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-10","passageId":"li-ji_ch-19_p-58","order":10,"canonicalText":"倒載干戈，包之以虎皮；","chunks":[["倒載干戈，包之以虎皮；","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-11","passageId":"li-ji_ch-19_p-58","order":11,"canonicalText":"將帥之士，使為諸侯；","chunks":[["將帥之士，使為諸侯；","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-12","passageId":"li-ji_ch-19_p-58","order":12,"canonicalText":"名之曰建櫜。","chunks":[["名之曰建櫜。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-13","passageId":"li-ji_ch-19_p-58","order":13,"canonicalText":"然後知武王之不復用兵也。","chunks":[["然後知武王之不復用兵也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-14","passageId":"li-ji_ch-19_p-58","order":14,"canonicalText":"散軍而郊射，左射貍首，右射騶虞，而貫革之射息也。","chunks":[["散軍而郊射，左射貍首，右射騶虞，而貫革之射息也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-15","passageId":"li-ji_ch-19_p-58","order":15,"canonicalText":"裨冕搢笏，而虎賁之士說劍也。","chunks":[["裨冕搢笏，而虎賁之士說劍也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-16","passageId":"li-ji_ch-19_p-58","order":16,"canonicalText":"祀乎明堂而民知孝。","chunks":[["祀乎明堂而民知孝。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-17","passageId":"li-ji_ch-19_p-58","order":17,"canonicalText":"朝覲然後諸侯知所以臣，耕藉然後諸侯知所以敬。","chunks":[["朝覲然後諸侯知所以臣，耕藉然後諸侯知所以敬。","zh-Hant"]]},{"id":"li-ji_ch-19_p-58_s-18","passageId":"li-ji_ch-19_p-58","order":18,"canonicalText":"五者，天下之大教也。","chunks":[["五者，天下之大教也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-59_s-1","passageId":"li-ji_ch-19_p-59","order":1,"canonicalText":"食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總干，所以教諸侯之弟也。","chunks":[["食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總干，所以教諸侯之弟也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-59_s-2","passageId":"li-ji_ch-19_p-59","order":2,"canonicalText":"若此則周道四達，禮樂交通。","chunks":[["若此則周道四達，禮樂交通。","zh-Hant"]]},{"id":"li-ji_ch-19_p-59_s-3","passageId":"li-ji_ch-19_p-59","order":3,"canonicalText":"則夫《武》之遲久，不亦宜乎！","chunks":[["則夫《武》之遲久，不亦宜乎！","zh-Hant"]]},{"id":"li-ji_ch-19_p-59_s-4","passageId":"li-ji_ch-19_p-59","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-1","passageId":"li-ji_ch-19_p-60","order":1,"canonicalText":"君子曰：禮樂不可斯須去身。","chunks":[["君子曰：禮樂不可斯須去身。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-2","passageId":"li-ji_ch-19_p-60","order":2,"canonicalText":"致樂以治心，則易直子諒之心油然生矣。","chunks":[["致樂以治心，則易直子諒之心油然生矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-3","passageId":"li-ji_ch-19_p-60","order":3,"canonicalText":"易直子諒之心生則樂，樂則安，安則久，久則天，天則神。","chunks":[["易直子諒之心生則樂，樂則安，安則久，久則天，天則神。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-4","passageId":"li-ji_ch-19_p-60","order":4,"canonicalText":"天則不言而信，神則不怒而威，致樂以治心者也。","chunks":[["天則不言而信，神則不怒而威，致樂以治心者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-5","passageId":"li-ji_ch-19_p-60","order":5,"canonicalText":"致禮以治躬則莊敬，莊敬則嚴威。","chunks":[["致禮以治躬則莊敬，莊敬則嚴威。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-6","passageId":"li-ji_ch-19_p-60","order":6,"canonicalText":"心中斯須不和不樂，而鄙詐之心入之矣。","chunks":[["心中斯須不和不樂，而鄙詐之心入之矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-60_s-7","passageId":"li-ji_ch-19_p-60","order":7,"canonicalText":"外貌斯須不莊不敬，而易慢之心入之矣。","chunks":[["外貌斯須不莊不敬，而易慢之心入之矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-1","passageId":"li-ji_ch-19_p-61","order":1,"canonicalText":"故樂也者，動於內者也；","chunks":[["故樂也者，動於內者也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-2","passageId":"li-ji_ch-19_p-61","order":2,"canonicalText":"禮也者，動於外者也。","chunks":[["禮也者，動於外者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-3","passageId":"li-ji_ch-19_p-61","order":3,"canonicalText":"樂極和，禮極順，內和而外順，則民瞻其顏色而弗與爭也；","chunks":[["樂極和，禮極順，內和而外順，則民瞻其顏色而弗與爭也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-4","passageId":"li-ji_ch-19_p-61","order":4,"canonicalText":"望其容貌，而民不生易慢焉。","chunks":[["望其容貌，而民不生易慢焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-5","passageId":"li-ji_ch-19_p-61","order":5,"canonicalText":"故德輝動於內，而民莫不承聽；","chunks":[["故德輝動於內，而民莫不承聽；","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-6","passageId":"li-ji_ch-19_p-61","order":6,"canonicalText":"理發諸外，而民莫不承順。","chunks":[["理發諸外，而民莫不承順。","zh-Hant"]]},{"id":"li-ji_ch-19_p-61_s-7","passageId":"li-ji_ch-19_p-61","order":7,"canonicalText":"故曰：致禮樂之道，舉而錯之，天下無難矣。","chunks":[["故曰：致禮樂之道，舉而錯之，天下無難矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-1","passageId":"li-ji_ch-19_p-62","order":1,"canonicalText":"樂也者，動於內者也；","chunks":[["樂也者，動於內者也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-2","passageId":"li-ji_ch-19_p-62","order":2,"canonicalText":"禮也者，動於外者也。","chunks":[["禮也者，動於外者也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-3","passageId":"li-ji_ch-19_p-62","order":3,"canonicalText":"故禮主其減，樂主其盈。","chunks":[["故禮主其減，樂主其盈。","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-4","passageId":"li-ji_ch-19_p-62","order":4,"canonicalText":"禮減而進，以進為文：樂盈而反，以反為文。","chunks":[["禮減而進，以進為文：樂盈而反，以反為文。","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-5","passageId":"li-ji_ch-19_p-62","order":5,"canonicalText":"禮減而不進則銷，樂盈而不反則放；","chunks":[["禮減而不進則銷，樂盈而不反則放；","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-6","passageId":"li-ji_ch-19_p-62","order":6,"canonicalText":"故禮有報而樂有反。","chunks":[["故禮有報而樂有反。","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-7","passageId":"li-ji_ch-19_p-62","order":7,"canonicalText":"禮得其報則樂，樂得其反則安；","chunks":[["禮得其報則樂，樂得其反則安；","zh-Hant"]]},{"id":"li-ji_ch-19_p-62_s-8","passageId":"li-ji_ch-19_p-62","order":8,"canonicalText":"禮之報，樂之反，其義一也。","chunks":[["禮之報，樂之反，其義一也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-1","passageId":"li-ji_ch-19_p-63","order":1,"canonicalText":"夫樂者樂也，人情之所不能免也。","chunks":[["夫樂者樂也，人情之所不能免也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-2","passageId":"li-ji_ch-19_p-63","order":2,"canonicalText":"樂必發於聲音，形於動靜，人之道也。","chunks":[["樂必發於聲音，形於動靜，人之道也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-3","passageId":"li-ji_ch-19_p-63","order":3,"canonicalText":"聲音動靜，性術之變，盡於此矣。","chunks":[["聲音動靜，性術之變，盡於此矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-4","passageId":"li-ji_ch-19_p-63","order":4,"canonicalText":"故人不耐無樂，樂不耐無形。","chunks":[["故人不耐無樂，樂不耐無形。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-5","passageId":"li-ji_ch-19_p-63","order":5,"canonicalText":"形而不為道，不耐無亂。","chunks":[["形而不為道，不耐無亂。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-6","passageId":"li-ji_ch-19_p-63","order":6,"canonicalText":"先王恥其亂，故制雅、頌之聲以道之，使其聲足樂而不流，使其文足論而不息，使其曲直繁瘠、廉肉節奏足以感動人之善心而已矣。","chunks":[["先王恥其亂，故制雅、頌之聲以道之，使其聲足樂而不流，使其文足論而不息，使其曲直繁瘠、廉肉節奏足以感動人之善心而已矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-63_s-7","passageId":"li-ji_ch-19_p-63","order":7,"canonicalText":"不使放心邪氣得接焉，是先王立樂之方也。","chunks":[["不使放心邪氣得接焉，是先王立樂之方也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-1","passageId":"li-ji_ch-19_p-64","order":1,"canonicalText":"是故樂在宗廟之中，君臣上下同聽之則莫不和敬；","chunks":[["是故樂在宗廟之中，君臣上下同聽之則莫不和敬；","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-2","passageId":"li-ji_ch-19_p-64","order":2,"canonicalText":"在族長鄉里之中，長幼同聽之則莫不和順；","chunks":[["在族長鄉里之中，長幼同聽之則莫不和順；","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-3","passageId":"li-ji_ch-19_p-64","order":3,"canonicalText":"在閨門之內，父子兄弟同聽之則莫不和親。","chunks":[["在閨門之內，父子兄弟同聽之則莫不和親。","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-4","passageId":"li-ji_ch-19_p-64","order":4,"canonicalText":"故樂者審一以定和，比物以飾節；","chunks":[["故樂者審一以定和，比物以飾節；","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-5","passageId":"li-ji_ch-19_p-64","order":5,"canonicalText":"節奏合以成文。","chunks":[["節奏合以成文。","zh-Hant"]]},{"id":"li-ji_ch-19_p-64_s-6","passageId":"li-ji_ch-19_p-64","order":6,"canonicalText":"所以合和父子君臣，附親萬民也，是先王立樂之方也。","chunks":[["所以合和父子君臣，附親萬民也，是先王立樂之方也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-1","passageId":"li-ji_ch-19_p-65","order":1,"canonicalText":"故聽其雅、頌之聲，志意得廣焉；","chunks":[["故聽其雅、頌之聲，志意得廣焉；","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-2","passageId":"li-ji_ch-19_p-65","order":2,"canonicalText":"執其干戚，習其俯仰詘伸，容貌得莊焉；","chunks":[["執其干戚，習其俯仰詘伸，容貌得莊焉；","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-3","passageId":"li-ji_ch-19_p-65","order":3,"canonicalText":"行其綴兆，要其節奏，行列得正焉，進退得齊焉。","chunks":[["行其綴兆，要其節奏，行列得正焉，進退得齊焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-4","passageId":"li-ji_ch-19_p-65","order":4,"canonicalText":"故樂者天地之命，中和之紀，人情之所不能免也。","chunks":[["故樂者天地之命，中和之紀，人情之所不能免也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-5","passageId":"li-ji_ch-19_p-65","order":5,"canonicalText":"夫樂者，先王之所以飾喜也，軍旅鈇鉞者，先王之所以飾怒也。","chunks":[["夫樂者，先王之所以飾喜也，軍旅鈇鉞者，先王之所以飾怒也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-6","passageId":"li-ji_ch-19_p-65","order":6,"canonicalText":"故先王之喜怒，皆得其儕焉。","chunks":[["故先王之喜怒，皆得其儕焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-7","passageId":"li-ji_ch-19_p-65","order":7,"canonicalText":"喜則天下和之，怒則暴亂者畏之。","chunks":[["喜則天下和之，怒則暴亂者畏之。","zh-Hant"]]},{"id":"li-ji_ch-19_p-65_s-8","passageId":"li-ji_ch-19_p-65","order":8,"canonicalText":"先王之道，禮樂可謂盛矣。","chunks":[["先王之道，禮樂可謂盛矣。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-1","passageId":"li-ji_ch-19_p-66","order":1,"canonicalText":"子贛見師乙而問焉，曰：「賜聞聲歌各有宜也，如賜者，宜何歌也？","chunks":[["子贛見師乙而問焉，曰：「賜聞聲歌各有宜也，如賜者，宜何歌也？","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-2","passageId":"li-ji_ch-19_p-66","order":2,"canonicalText":"」師乙曰：「乙賤工也，何足以問所宜？","chunks":[["」師乙曰：「乙賤工也，何足以問所宜？","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-3","passageId":"li-ji_ch-19_p-66","order":3,"canonicalText":"請誦其所聞，而吾子自執焉：寬而靜、柔而正者宜歌頌。","chunks":[["請誦其所聞，而吾子自執焉：寬而靜、柔而正者宜歌頌。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-4","passageId":"li-ji_ch-19_p-66","order":4,"canonicalText":"廣大而靜、疏達而信者宜歌大雅。","chunks":[["廣大而靜、疏達而信者宜歌大雅。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-5","passageId":"li-ji_ch-19_p-66","order":5,"canonicalText":"恭儉而好禮者宜歌小雅。","chunks":[["恭儉而好禮者宜歌小雅。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-6","passageId":"li-ji_ch-19_p-66","order":6,"canonicalText":"正直而靜、廉而謙者宜歌風。","chunks":[["正直而靜、廉而謙者宜歌風。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-7","passageId":"li-ji_ch-19_p-66","order":7,"canonicalText":"肆直而慈愛者宜歌商；","chunks":[["肆直而慈愛者宜歌商；","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-8","passageId":"li-ji_ch-19_p-66","order":8,"canonicalText":"溫良而能斷者宜歌齊。","chunks":[["溫良而能斷者宜歌齊。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-9","passageId":"li-ji_ch-19_p-66","order":9,"canonicalText":"夫歌者，直己而陳德也。","chunks":[["夫歌者，直己而陳德也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-66_s-10","passageId":"li-ji_ch-19_p-66","order":10,"canonicalText":"動己而天地應焉，四時和焉，星辰理焉，萬物育焉。","chunks":[["動己而天地應焉，四時和焉，星辰理焉，萬物育焉。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-1","passageId":"li-ji_ch-19_p-67","order":1,"canonicalText":"故商者，五帝之遺聲也。","chunks":[["故商者，五帝之遺聲也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-2","passageId":"li-ji_ch-19_p-67","order":2,"canonicalText":"商人識之，故謂之商。","chunks":[["商人識之，故謂之商。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-3","passageId":"li-ji_ch-19_p-67","order":3,"canonicalText":"齊者三代之遺聲也，齊人識之，故謂之齊。","chunks":[["齊者三代之遺聲也，齊人識之，故謂之齊。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-4","passageId":"li-ji_ch-19_p-67","order":4,"canonicalText":"明乎商之音者，臨事而屢斷，明乎齊之音者，見利而讓。","chunks":[["明乎商之音者，臨事而屢斷，明乎齊之音者，見利而讓。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-5","passageId":"li-ji_ch-19_p-67","order":5,"canonicalText":"臨事而屢斷，勇也；","chunks":[["臨事而屢斷，勇也；","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-6","passageId":"li-ji_ch-19_p-67","order":6,"canonicalText":"見利而讓，義也。","chunks":[["見利而讓，義也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-7","passageId":"li-ji_ch-19_p-67","order":7,"canonicalText":"有勇有義，非歌孰能保此？","chunks":[["有勇有義，非歌孰能保此？","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-8","passageId":"li-ji_ch-19_p-67","order":8,"canonicalText":"故歌者，上如抗，下如隊，曲如折，止如槁木，倨中矩，句中鉤，纍纍乎端如貫珠。","chunks":[["故歌者，上如抗，下如隊，曲如折，止如槁木，倨中矩，句中鉤，纍纍乎端如貫珠。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-9","passageId":"li-ji_ch-19_p-67","order":9,"canonicalText":"故歌之為言也，長言之也。","chunks":[["故歌之為言也，長言之也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-10","passageId":"li-ji_ch-19_p-67","order":10,"canonicalText":"說之，故言之；","chunks":[["說之，故言之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-11","passageId":"li-ji_ch-19_p-67","order":11,"canonicalText":"言之不足，故長言之；","chunks":[["言之不足，故長言之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-12","passageId":"li-ji_ch-19_p-67","order":12,"canonicalText":"長言之不足，故嗟嘆之；","chunks":[["長言之不足，故嗟嘆之；","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-13","passageId":"li-ji_ch-19_p-67","order":13,"canonicalText":"嗟嘆之不足，故不知手之舞之，足之蹈之也。","chunks":[["嗟嘆之不足，故不知手之舞之，足之蹈之也。","zh-Hant"]]},{"id":"li-ji_ch-19_p-67_s-14","passageId":"li-ji_ch-19_p-67","order":14,"canonicalText":"」子貢問樂。","chunks":[["」子貢問樂。","zh-Hant"]]},{"id":"li-ji_ch-20_p-1_s-1","passageId":"li-ji_ch-20_p-1","order":1,"canonicalText":"諸侯行而死於館，則其復如於其國。","chunks":[["諸侯行而死於館，則其復如於其國。","zh-Hant"]]},{"id":"li-ji_ch-20_p-1_s-2","passageId":"li-ji_ch-20_p-1","order":2,"canonicalText":"如於道，則升其乘車之左轂，以其綏復。","chunks":[["如於道，則升其乘車之左轂，以其綏復。","zh-Hant"]]},{"id":"li-ji_ch-20_p-1_s-3","passageId":"li-ji_ch-20_p-1","order":3,"canonicalText":"其輤有裧，緇布裳帷素錦以為屋而行。","chunks":[["其輤有裧，緇布裳帷素錦以為屋而行。","zh-Hant"]]},{"id":"li-ji_ch-20_p-1_s-4","passageId":"li-ji_ch-20_p-1","order":4,"canonicalText":"至於廟門，不毀墻遂入適所殯，唯輤為說於廟門外。","chunks":[["至於廟門，不毀墻遂入適所殯，唯輤為說於廟門外。","zh-Hant"]]},{"id":"li-ji_ch-20_p-2_s-1","passageId":"li-ji_ch-20_p-2","order":1,"canonicalText":"大夫、士死於道，則升其乘車之左轂，以其綏復。","chunks":[["大夫、士死於道，則升其乘車之左轂，以其綏復。","zh-Hant"]]},{"id":"li-ji_ch-20_p-2_s-2","passageId":"li-ji_ch-20_p-2","order":2,"canonicalText":"如於館死，則其復如於家。","chunks":[["如於館死，則其復如於家。","zh-Hant"]]},{"id":"li-ji_ch-20_p-2_s-3","passageId":"li-ji_ch-20_p-2","order":3,"canonicalText":"大夫以布為輤而行，至於家而說輤，載以輲車，入自門至於阼階下而說車，舉自阼階，升適所殯。","chunks":[["大夫以布為輤而行，至於家而說輤，載以輲車，入自門至於阼階下而說車，舉自阼階，升適所殯。","zh-Hant"]]},{"id":"li-ji_ch-20_p-2_s-4","passageId":"li-ji_ch-20_p-2","order":4,"canonicalText":"士輤，葦席以為屋，蒲席以為裳帷。","chunks":[["士輤，葦席以為屋，蒲席以為裳帷。","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-1","passageId":"li-ji_ch-20_p-3","order":1,"canonicalText":"凡訃於其君，曰：「君之臣某死」；","chunks":[["凡訃於其君，曰：「君之臣某死」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-2","passageId":"li-ji_ch-20_p-3","order":2,"canonicalText":"父母、妻、長子，曰：「君之臣某之某死」。","chunks":[["父母、妻、長子，曰：「君之臣某之某死」。","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-3","passageId":"li-ji_ch-20_p-3","order":3,"canonicalText":"君訃於他國之君，曰：「寡君不祿，敢告於執事。","chunks":[["君訃於他國之君，曰：「寡君不祿，敢告於執事。","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-4","passageId":"li-ji_ch-20_p-3","order":4,"canonicalText":"」；","chunks":[["」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-5","passageId":"li-ji_ch-20_p-3","order":5,"canonicalText":"夫人，曰：「寡小君不祿。","chunks":[["夫人，曰：「寡小君不祿。","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-6","passageId":"li-ji_ch-20_p-3","order":6,"canonicalText":"」；","chunks":[["」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-7","passageId":"li-ji_ch-20_p-3","order":7,"canonicalText":"大子之喪，曰：「寡君之適子某死。","chunks":[["大子之喪，曰：「寡君之適子某死。","zh-Hant"]]},{"id":"li-ji_ch-20_p-3_s-8","passageId":"li-ji_ch-20_p-3","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-1","passageId":"li-ji_ch-20_p-4","order":1,"canonicalText":"大夫訃於同國：適者，曰：「某不祿」；","chunks":[["大夫訃於同國：適者，曰：「某不祿」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-2","passageId":"li-ji_ch-20_p-4","order":2,"canonicalText":"訃於士，亦曰：「某不祿」；","chunks":[["訃於士，亦曰：「某不祿」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-3","passageId":"li-ji_ch-20_p-4","order":3,"canonicalText":"訃於他國之君，曰：「君之外臣寡大夫某死」，訃於適者，曰：「吾子之外私寡大夫某不祿，使某實。","chunks":[["訃於他國之君，曰：「君之外臣寡大夫某死」，訃於適者，曰：「吾子之外私寡大夫某不祿，使某實。","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-4","passageId":"li-ji_ch-20_p-4","order":4,"canonicalText":"」訃於士，亦曰：「吾子之外私寡大夫某不祿，使某實。","chunks":[["」訃於士，亦曰：「吾子之外私寡大夫某不祿，使某實。","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-5","passageId":"li-ji_ch-20_p-4","order":5,"canonicalText":"」士訃於同國大夫，曰：「某死」，訃於士，亦曰：「某死」；","chunks":[["」士訃於同國大夫，曰：「某死」，訃於士，亦曰：「某死」；","zh-Hant"]]},{"id":"li-ji_ch-20_p-4_s-6","passageId":"li-ji_ch-20_p-4","order":6,"canonicalText":"訃於他國之君，曰：「君之外臣某死」，訃於大夫，曰：「吾子之外私某死」，訃於士，亦曰：「吾子之外私某死」。","chunks":[["訃於他國之君，曰：「君之外臣某死」，訃於大夫，曰：「吾子之外私某死」，訃於士，亦曰：「吾子之外私某死」。","zh-Hant"]]},{"id":"li-ji_ch-20_p-5_s-1","passageId":"li-ji_ch-20_p-5","order":1,"canonicalText":"大夫次於公館以終喪，士練而歸。","chunks":[["大夫次於公館以終喪，士練而歸。","zh-Hant"]]},{"id":"li-ji_ch-20_p-5_s-2","passageId":"li-ji_ch-20_p-5","order":2,"canonicalText":"士次於公館，大夫居廬，士居堊室。","chunks":[["士次於公館，大夫居廬，士居堊室。","zh-Hant"]]},{"id":"li-ji_ch-20_p-6_s-1","passageId":"li-ji_ch-20_p-6","order":1,"canonicalText":"大夫為其父母兄弟之未為大夫者之喪，服如士服。","chunks":[["大夫為其父母兄弟之未為大夫者之喪，服如士服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-6_s-2","passageId":"li-ji_ch-20_p-6","order":2,"canonicalText":"士為其父母兄弟之為大夫者之喪，服如士服。","chunks":[["士為其父母兄弟之為大夫者之喪，服如士服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-6_s-3","passageId":"li-ji_ch-20_p-6","order":3,"canonicalText":"大夫之適子，服大夫之服。","chunks":[["大夫之適子，服大夫之服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-6_s-4","passageId":"li-ji_ch-20_p-6","order":4,"canonicalText":"大夫之庶子為大夫，則為其父母服大夫服；","chunks":[["大夫之庶子為大夫，則為其父母服大夫服；","zh-Hant"]]},{"id":"li-ji_ch-20_p-6_s-5","passageId":"li-ji_ch-20_p-6","order":5,"canonicalText":"其位，與未為大夫者齒。","chunks":[["其位，與未為大夫者齒。","zh-Hant"]]},{"id":"li-ji_ch-20_p-7_s-1","passageId":"li-ji_ch-20_p-7","order":1,"canonicalText":"士之子為大夫，則其父母弗能主也，使其子主之。","chunks":[["士之子為大夫，則其父母弗能主也，使其子主之。","zh-Hant"]]},{"id":"li-ji_ch-20_p-7_s-2","passageId":"li-ji_ch-20_p-7","order":2,"canonicalText":"無子，則為之置後。","chunks":[["無子，則為之置後。","zh-Hant"]]},{"id":"li-ji_ch-20_p-8_s-1","passageId":"li-ji_ch-20_p-8","order":1,"canonicalText":"大夫卜宅與葬日，有司麻衣、布衰、布帶，因喪屨，緇布冠不蕤。","chunks":[["大夫卜宅與葬日，有司麻衣、布衰、布帶，因喪屨，緇布冠不蕤。","zh-Hant"]]},{"id":"li-ji_ch-20_p-8_s-2","passageId":"li-ji_ch-20_p-8","order":2,"canonicalText":"占者皮弁。","chunks":[["占者皮弁。","zh-Hant"]]},{"id":"li-ji_ch-20_p-8_s-3","passageId":"li-ji_ch-20_p-8","order":3,"canonicalText":"如筮，則史練冠長衣以筮。","chunks":[["如筮，則史練冠長衣以筮。","zh-Hant"]]},{"id":"li-ji_ch-20_p-8_s-4","passageId":"li-ji_ch-20_p-8","order":4,"canonicalText":"占者朝服。","chunks":[["占者朝服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-9_s-1","passageId":"li-ji_ch-20_p-9","order":1,"canonicalText":"大夫之喪，既薦馬。","chunks":[["大夫之喪，既薦馬。","zh-Hant"]]},{"id":"li-ji_ch-20_p-9_s-2","passageId":"li-ji_ch-20_p-9","order":2,"canonicalText":"薦馬者，哭踴，出乃包奠而讀書。","chunks":[["薦馬者，哭踴，出乃包奠而讀書。","zh-Hant"]]},{"id":"li-ji_ch-20_p-10_s-1","passageId":"li-ji_ch-20_p-10","order":1,"canonicalText":"大夫之喪，大宗人相，小宗人命龜，卜人作龜。","chunks":[["大夫之喪，大宗人相，小宗人命龜，卜人作龜。","zh-Hant"]]},{"id":"li-ji_ch-20_p-11_s-1","passageId":"li-ji_ch-20_p-11","order":1,"canonicalText":"復，諸侯以褒衣冕服，爵弁服，夫人稅衣揄狄，狄稅素沙。","chunks":[["復，諸侯以褒衣冕服，爵弁服，夫人稅衣揄狄，狄稅素沙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-11_s-2","passageId":"li-ji_ch-20_p-11","order":2,"canonicalText":"內子以鞠衣，褒衣，素沙。","chunks":[["內子以鞠衣，褒衣，素沙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-11_s-3","passageId":"li-ji_ch-20_p-11","order":3,"canonicalText":"下大夫以襢衣，其餘如士。","chunks":[["下大夫以襢衣，其餘如士。","zh-Hant"]]},{"id":"li-ji_ch-20_p-11_s-4","passageId":"li-ji_ch-20_p-11","order":4,"canonicalText":"復西上。","chunks":[["復西上。","zh-Hant"]]},{"id":"li-ji_ch-20_p-12_s-1","passageId":"li-ji_ch-20_p-12","order":1,"canonicalText":"大夫不揄絞，屬於池下。","chunks":[["大夫不揄絞，屬於池下。","zh-Hant"]]},{"id":"li-ji_ch-20_p-13_s-1","passageId":"li-ji_ch-20_p-13","order":1,"canonicalText":"大夫附於士，士不附於大夫，附於大夫之昆弟。","chunks":[["大夫附於士，士不附於大夫，附於大夫之昆弟。","zh-Hant"]]},{"id":"li-ji_ch-20_p-13_s-2","passageId":"li-ji_ch-20_p-13","order":2,"canonicalText":"無昆弟，則從其昭穆。","chunks":[["無昆弟，則從其昭穆。","zh-Hant"]]},{"id":"li-ji_ch-20_p-13_s-3","passageId":"li-ji_ch-20_p-13","order":3,"canonicalText":"雖王父母在，亦然。","chunks":[["雖王父母在，亦然。","zh-Hant"]]},{"id":"li-ji_ch-20_p-14_s-1","passageId":"li-ji_ch-20_p-14","order":1,"canonicalText":"婦附於其夫之所附之妃，無妃。","chunks":[["婦附於其夫之所附之妃，無妃。","zh-Hant"]]},{"id":"li-ji_ch-20_p-14_s-2","passageId":"li-ji_ch-20_p-14","order":2,"canonicalText":"則亦從其昭穆之妃。","chunks":[["則亦從其昭穆之妃。","zh-Hant"]]},{"id":"li-ji_ch-20_p-14_s-3","passageId":"li-ji_ch-20_p-14","order":3,"canonicalText":"妾附於妾祖姑，無妾祖姑則亦從其昭穆之妾。","chunks":[["妾附於妾祖姑，無妾祖姑則亦從其昭穆之妾。","zh-Hant"]]},{"id":"li-ji_ch-20_p-15_s-1","passageId":"li-ji_ch-20_p-15","order":1,"canonicalText":"男子附於王父則配；","chunks":[["男子附於王父則配；","zh-Hant"]]},{"id":"li-ji_ch-20_p-15_s-2","passageId":"li-ji_ch-20_p-15","order":2,"canonicalText":"女子附於王母，則不配。","chunks":[["女子附於王母，則不配。","zh-Hant"]]},{"id":"li-ji_ch-20_p-15_s-3","passageId":"li-ji_ch-20_p-15","order":3,"canonicalText":"公子附於公子。","chunks":[["公子附於公子。","zh-Hant"]]},{"id":"li-ji_ch-20_p-16_s-1","passageId":"li-ji_ch-20_p-16","order":1,"canonicalText":"君薨，大子號稱子，待猶君也。","chunks":[["君薨，大子號稱子，待猶君也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-17_s-1","passageId":"li-ji_ch-20_p-17","order":1,"canonicalText":"有三年之練冠，則以大功之麻易之；","chunks":[["有三年之練冠，則以大功之麻易之；","zh-Hant"]]},{"id":"li-ji_ch-20_p-17_s-2","passageId":"li-ji_ch-20_p-17","order":2,"canonicalText":"唯杖屨不易。","chunks":[["唯杖屨不易。","zh-Hant"]]},{"id":"li-ji_ch-20_p-18_s-1","passageId":"li-ji_ch-20_p-18","order":1,"canonicalText":"有父母之喪，尚功衰，而附兄弟之殤則練冠。","chunks":[["有父母之喪，尚功衰，而附兄弟之殤則練冠。","zh-Hant"]]},{"id":"li-ji_ch-20_p-18_s-2","passageId":"li-ji_ch-20_p-18","order":2,"canonicalText":"附於殤，稱陽童某甫，不名，神也。","chunks":[["附於殤，稱陽童某甫，不名，神也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-19_s-1","passageId":"li-ji_ch-20_p-19","order":1,"canonicalText":"凡異居，始聞兄弟之喪，唯以哭對，可也。","chunks":[["凡異居，始聞兄弟之喪，唯以哭對，可也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-19_s-2","passageId":"li-ji_ch-20_p-19","order":2,"canonicalText":"其始麻，散帶絰。","chunks":[["其始麻，散帶絰。","zh-Hant"]]},{"id":"li-ji_ch-20_p-19_s-3","passageId":"li-ji_ch-20_p-19","order":3,"canonicalText":"未服麻而奔喪，及主人之未成絰也：疏者，與主人皆成之；","chunks":[["未服麻而奔喪，及主人之未成絰也：疏者，與主人皆成之；","zh-Hant"]]},{"id":"li-ji_ch-20_p-19_s-4","passageId":"li-ji_ch-20_p-19","order":4,"canonicalText":"親者，終其麻帶絰之日數。","chunks":[["親者，終其麻帶絰之日數。","zh-Hant"]]},{"id":"li-ji_ch-20_p-20_s-1","passageId":"li-ji_ch-20_p-20","order":1,"canonicalText":"主妾之喪，則自附至於練祥，皆使其子主之。","chunks":[["主妾之喪，則自附至於練祥，皆使其子主之。","zh-Hant"]]},{"id":"li-ji_ch-20_p-20_s-2","passageId":"li-ji_ch-20_p-20","order":2,"canonicalText":"其殯祭，不於正室。","chunks":[["其殯祭，不於正室。","zh-Hant"]]},{"id":"li-ji_ch-20_p-21_s-1","passageId":"li-ji_ch-20_p-21","order":1,"canonicalText":"君不撫仆妾。","chunks":[["君不撫仆妾。","zh-Hant"]]},{"id":"li-ji_ch-20_p-22_s-1","passageId":"li-ji_ch-20_p-22","order":1,"canonicalText":"女君死，則妾為女君之黨服。","chunks":[["女君死，則妾為女君之黨服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-22_s-2","passageId":"li-ji_ch-20_p-22","order":2,"canonicalText":"攝女君，則不為先女君之黨服。","chunks":[["攝女君，則不為先女君之黨服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-23_s-1","passageId":"li-ji_ch-20_p-23","order":1,"canonicalText":"聞兄弟之喪，大功以上，見喪者之鄉而哭。","chunks":[["聞兄弟之喪，大功以上，見喪者之鄉而哭。","zh-Hant"]]},{"id":"li-ji_ch-20_p-23_s-2","passageId":"li-ji_ch-20_p-23","order":2,"canonicalText":"適兄弟之送葬者弗及，遇主人於道，則遂之於墓。","chunks":[["適兄弟之送葬者弗及，遇主人於道，則遂之於墓。","zh-Hant"]]},{"id":"li-ji_ch-20_p-23_s-3","passageId":"li-ji_ch-20_p-23","order":3,"canonicalText":"凡主兄弟之喪，雖疏亦虞之。","chunks":[["凡主兄弟之喪，雖疏亦虞之。","zh-Hant"]]},{"id":"li-ji_ch-20_p-24_s-1","passageId":"li-ji_ch-20_p-24","order":1,"canonicalText":"凡喪服未畢，有吊者，則為位而哭拜踴。","chunks":[["凡喪服未畢，有吊者，則為位而哭拜踴。","zh-Hant"]]},{"id":"li-ji_ch-20_p-25_s-1","passageId":"li-ji_ch-20_p-25","order":1,"canonicalText":"大夫之哭大夫，弁絰；","chunks":[["大夫之哭大夫，弁絰；","zh-Hant"]]},{"id":"li-ji_ch-20_p-25_s-2","passageId":"li-ji_ch-20_p-25","order":2,"canonicalText":"大夫與殯，亦弁絰。","chunks":[["大夫與殯，亦弁絰。","zh-Hant"]]},{"id":"li-ji_ch-20_p-25_s-3","passageId":"li-ji_ch-20_p-25","order":3,"canonicalText":"大夫有私喪之葛，則於其兄弟之輕喪，則弁絰。","chunks":[["大夫有私喪之葛，則於其兄弟之輕喪，則弁絰。","zh-Hant"]]},{"id":"li-ji_ch-20_p-26_s-1","passageId":"li-ji_ch-20_p-26","order":1,"canonicalText":"為長子杖，則其子不以杖即位。","chunks":[["為長子杖，則其子不以杖即位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-26_s-2","passageId":"li-ji_ch-20_p-26","order":2,"canonicalText":"為妻，父母在，不杖，不稽顙。","chunks":[["為妻，父母在，不杖，不稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-26_s-3","passageId":"li-ji_ch-20_p-26","order":3,"canonicalText":"母在，不稽顙。","chunks":[["母在，不稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-26_s-4","passageId":"li-ji_ch-20_p-26","order":4,"canonicalText":"稽顙者，其贈也拜。","chunks":[["稽顙者，其贈也拜。","zh-Hant"]]},{"id":"li-ji_ch-20_p-27_s-1","passageId":"li-ji_ch-20_p-27","order":1,"canonicalText":"違諸侯之大夫，不反服。","chunks":[["違諸侯之大夫，不反服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-27_s-2","passageId":"li-ji_ch-20_p-27","order":2,"canonicalText":"違大夫之諸侯，不反服。","chunks":[["違大夫之諸侯，不反服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-28_s-1","passageId":"li-ji_ch-20_p-28","order":1,"canonicalText":"喪冠條屬，以別吉凶。","chunks":[["喪冠條屬，以別吉凶。","zh-Hant"]]},{"id":"li-ji_ch-20_p-28_s-2","passageId":"li-ji_ch-20_p-28","order":2,"canonicalText":"三年之練冠，亦條屬，右縫。","chunks":[["三年之練冠，亦條屬，右縫。","zh-Hant"]]},{"id":"li-ji_ch-20_p-28_s-3","passageId":"li-ji_ch-20_p-28","order":3,"canonicalText":"小功以下左。","chunks":[["小功以下左。","zh-Hant"]]},{"id":"li-ji_ch-20_p-28_s-4","passageId":"li-ji_ch-20_p-28","order":4,"canonicalText":"緦冠繰纓。","chunks":[["緦冠繰纓。","zh-Hant"]]},{"id":"li-ji_ch-20_p-28_s-5","passageId":"li-ji_ch-20_p-28","order":5,"canonicalText":"大功以上散帶。","chunks":[["大功以上散帶。","zh-Hant"]]},{"id":"li-ji_ch-20_p-29_s-1","passageId":"li-ji_ch-20_p-29","order":1,"canonicalText":"朝服十五升，去其半而緦；","chunks":[["朝服十五升，去其半而緦；","zh-Hant"]]},{"id":"li-ji_ch-20_p-29_s-2","passageId":"li-ji_ch-20_p-29","order":2,"canonicalText":"加灰，錫也。","chunks":[["加灰，錫也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-30_s-1","passageId":"li-ji_ch-20_p-30","order":1,"canonicalText":"諸侯相襚，以後路與冕服。","chunks":[["諸侯相襚，以後路與冕服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-30_s-2","passageId":"li-ji_ch-20_p-30","order":2,"canonicalText":"先路與褒衣，不以襚。","chunks":[["先路與褒衣，不以襚。","zh-Hant"]]},{"id":"li-ji_ch-20_p-31_s-1","passageId":"li-ji_ch-20_p-31","order":1,"canonicalText":"遣車視牢具。","chunks":[["遣車視牢具。","zh-Hant"]]},{"id":"li-ji_ch-20_p-31_s-2","passageId":"li-ji_ch-20_p-31","order":2,"canonicalText":"疏布輤，四面有章，置於四隅。","chunks":[["疏布輤，四面有章，置於四隅。","zh-Hant"]]},{"id":"li-ji_ch-20_p-31_s-3","passageId":"li-ji_ch-20_p-31","order":3,"canonicalText":"載粻，有子曰：「非禮也。","chunks":[["載粻，有子曰：「非禮也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-31_s-4","passageId":"li-ji_ch-20_p-31","order":4,"canonicalText":"喪奠，脯醢而已。","chunks":[["喪奠，脯醢而已。","zh-Hant"]]},{"id":"li-ji_ch-20_p-31_s-5","passageId":"li-ji_ch-20_p-31","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-20_p-32_s-1","passageId":"li-ji_ch-20_p-32","order":1,"canonicalText":"祭稱孝子、孝孫，喪稱哀子、哀孫。","chunks":[["祭稱孝子、孝孫，喪稱哀子、哀孫。","zh-Hant"]]},{"id":"li-ji_ch-20_p-33_s-1","passageId":"li-ji_ch-20_p-33","order":1,"canonicalText":"端衰，喪車，皆無等。","chunks":[["端衰，喪車，皆無等。","zh-Hant"]]},{"id":"li-ji_ch-20_p-34_s-1","passageId":"li-ji_ch-20_p-34","order":1,"canonicalText":"大白冠，緇布之冠，皆不蕤。","chunks":[["大白冠，緇布之冠，皆不蕤。","zh-Hant"]]},{"id":"li-ji_ch-20_p-34_s-2","passageId":"li-ji_ch-20_p-34","order":2,"canonicalText":"委武玄縞而後蕤。","chunks":[["委武玄縞而後蕤。","zh-Hant"]]},{"id":"li-ji_ch-20_p-35_s-1","passageId":"li-ji_ch-20_p-35","order":1,"canonicalText":"大夫冕而祭於公，弁而祭於己。","chunks":[["大夫冕而祭於公，弁而祭於己。","zh-Hant"]]},{"id":"li-ji_ch-20_p-35_s-2","passageId":"li-ji_ch-20_p-35","order":2,"canonicalText":"士弁而祭於公，冠而祭於己。","chunks":[["士弁而祭於公，冠而祭於己。","zh-Hant"]]},{"id":"li-ji_ch-20_p-35_s-3","passageId":"li-ji_ch-20_p-35","order":3,"canonicalText":"士弁而親迎，然則士弁而祭於己可也。","chunks":[["士弁而親迎，然則士弁而祭於己可也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-36_s-1","passageId":"li-ji_ch-20_p-36","order":1,"canonicalText":"暢臼以椈，杵以梧。","chunks":[["暢臼以椈，杵以梧。","zh-Hant"]]},{"id":"li-ji_ch-20_p-36_s-2","passageId":"li-ji_ch-20_p-36","order":2,"canonicalText":"枇以桑，長三尺；","chunks":[["枇以桑，長三尺；","zh-Hant"]]},{"id":"li-ji_ch-20_p-36_s-3","passageId":"li-ji_ch-20_p-36","order":3,"canonicalText":"或曰五尺。","chunks":[["或曰五尺。","zh-Hant"]]},{"id":"li-ji_ch-20_p-36_s-4","passageId":"li-ji_ch-20_p-36","order":4,"canonicalText":"畢用桑，長三尺，刊其柄與末。","chunks":[["畢用桑，長三尺，刊其柄與末。","zh-Hant"]]},{"id":"li-ji_ch-20_p-37_s-1","passageId":"li-ji_ch-20_p-37","order":1,"canonicalText":"率帶，諸侯、大夫皆五采；","chunks":[["率帶，諸侯、大夫皆五采；","zh-Hant"]]},{"id":"li-ji_ch-20_p-37_s-2","passageId":"li-ji_ch-20_p-37","order":2,"canonicalText":"士二采。","chunks":[["士二采。","zh-Hant"]]},{"id":"li-ji_ch-20_p-38_s-1","passageId":"li-ji_ch-20_p-38","order":1,"canonicalText":"醴者，稻醴也。","chunks":[["醴者，稻醴也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-38_s-2","passageId":"li-ji_ch-20_p-38","order":2,"canonicalText":"甕甒筲衡，實見間而後折入。","chunks":[["甕甒筲衡，實見間而後折入。","zh-Hant"]]},{"id":"li-ji_ch-20_p-39_s-1","passageId":"li-ji_ch-20_p-39","order":1,"canonicalText":"重，既虞而埋之。","chunks":[["重，既虞而埋之。","zh-Hant"]]},{"id":"li-ji_ch-20_p-40_s-1","passageId":"li-ji_ch-20_p-40","order":1,"canonicalText":"凡婦人，從其夫之爵位。","chunks":[["凡婦人，從其夫之爵位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-41_s-1","passageId":"li-ji_ch-20_p-41","order":1,"canonicalText":"小斂、大斂、啟，皆辯拜。","chunks":[["小斂、大斂、啟，皆辯拜。","zh-Hant"]]},{"id":"li-ji_ch-20_p-42_s-1","passageId":"li-ji_ch-20_p-42","order":1,"canonicalText":"朝夕哭，不帷。","chunks":[["朝夕哭，不帷。","zh-Hant"]]},{"id":"li-ji_ch-20_p-42_s-2","passageId":"li-ji_ch-20_p-42","order":2,"canonicalText":"無柩者不帷。","chunks":[["無柩者不帷。","zh-Hant"]]},{"id":"li-ji_ch-20_p-43_s-1","passageId":"li-ji_ch-20_p-43","order":1,"canonicalText":"君若載而後吊之，則主人東面而拜，門右北面而踴。","chunks":[["君若載而後吊之，則主人東面而拜，門右北面而踴。","zh-Hant"]]},{"id":"li-ji_ch-20_p-43_s-2","passageId":"li-ji_ch-20_p-43","order":2,"canonicalText":"出待，反而後奠。","chunks":[["出待，反而後奠。","zh-Hant"]]},{"id":"li-ji_ch-20_p-44_s-1","passageId":"li-ji_ch-20_p-44","order":1,"canonicalText":"子羔之襲也：繭衣裳與稅衣纁袡為一，素端一，皮弁一，爵弁一，玄冕一。","chunks":[["子羔之襲也：繭衣裳與稅衣纁袡為一，素端一，皮弁一，爵弁一，玄冕一。","zh-Hant"]]},{"id":"li-ji_ch-20_p-44_s-2","passageId":"li-ji_ch-20_p-44","order":2,"canonicalText":"曾子曰：「不襲婦服。","chunks":[["曾子曰：「不襲婦服。","zh-Hant"]]},{"id":"li-ji_ch-20_p-44_s-3","passageId":"li-ji_ch-20_p-44","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-20_p-45_s-1","passageId":"li-ji_ch-20_p-45","order":1,"canonicalText":"為君使而死，於公館，復；","chunks":[["為君使而死，於公館，復；","zh-Hant"]]},{"id":"li-ji_ch-20_p-45_s-2","passageId":"li-ji_ch-20_p-45","order":2,"canonicalText":"私館不復。","chunks":[["私館不復。","zh-Hant"]]},{"id":"li-ji_ch-20_p-45_s-3","passageId":"li-ji_ch-20_p-45","order":3,"canonicalText":"公館者，公宮與公所為也。","chunks":[["公館者，公宮與公所為也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-45_s-4","passageId":"li-ji_ch-20_p-45","order":4,"canonicalText":"私館者，自卿大夫以下之家也。","chunks":[["私館者，自卿大夫以下之家也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-46_s-1","passageId":"li-ji_ch-20_p-46","order":1,"canonicalText":"公七踴，大夫五踴，婦人居間，士三踴，婦人皆居間。","chunks":[["公七踴，大夫五踴，婦人居間，士三踴，婦人皆居間。","zh-Hant"]]},{"id":"li-ji_ch-20_p-47_s-1","passageId":"li-ji_ch-20_p-47","order":1,"canonicalText":"公襲：卷衣一，玄端一，朝服一，素積一，纁裳一，爵弁二，玄冕一，褒衣一。","chunks":[["公襲：卷衣一，玄端一，朝服一，素積一，纁裳一，爵弁二，玄冕一，褒衣一。","zh-Hant"]]},{"id":"li-ji_ch-20_p-47_s-2","passageId":"li-ji_ch-20_p-47","order":2,"canonicalText":"朱綠帶，申加大帶於上。","chunks":[["朱綠帶，申加大帶於上。","zh-Hant"]]},{"id":"li-ji_ch-20_p-48_s-1","passageId":"li-ji_ch-20_p-48","order":1,"canonicalText":"小斂環絰，公大夫士一也。","chunks":[["小斂環絰，公大夫士一也。","zh-Hant"]]},{"id":"li-ji_ch-20_p-49_s-1","passageId":"li-ji_ch-20_p-49","order":1,"canonicalText":"公視大斂，公升，商祝鋪席，乃斂。","chunks":[["公視大斂，公升，商祝鋪席，乃斂。","zh-Hant"]]},{"id":"li-ji_ch-20_p-50_s-1","passageId":"li-ji_ch-20_p-50","order":1,"canonicalText":"魯人之贈也：三玄二纁，廣尺，長終幅。","chunks":[["魯人之贈也：三玄二纁，廣尺，長終幅。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-1","passageId":"li-ji_ch-20_p-51","order":1,"canonicalText":"吊者即位於門西，東面；","chunks":[["吊者即位於門西，東面；","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-2","passageId":"li-ji_ch-20_p-51","order":2,"canonicalText":"其介在其東南，北面西上，西於門。","chunks":[["其介在其東南，北面西上，西於門。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-3","passageId":"li-ji_ch-20_p-51","order":3,"canonicalText":"主孤西面。","chunks":[["主孤西面。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-4","passageId":"li-ji_ch-20_p-51","order":4,"canonicalText":"相者受命曰：「孤某使某請事。","chunks":[["相者受命曰：「孤某使某請事。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-5","passageId":"li-ji_ch-20_p-51","order":5,"canonicalText":"」客曰：「寡君使某，如何不淑！","chunks":[["」客曰：「寡君使某，如何不淑！","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-6","passageId":"li-ji_ch-20_p-51","order":6,"canonicalText":"」相者入告，出曰：「孤某須矣。","chunks":[["」相者入告，出曰：「孤某須矣。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-7","passageId":"li-ji_ch-20_p-51","order":7,"canonicalText":"」吊者入，主人升堂，西面。","chunks":[["」吊者入，主人升堂，西面。","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-8","passageId":"li-ji_ch-20_p-51","order":8,"canonicalText":"吊者升自西階，東面，致命曰：「寡君聞君之喪，寡君使某，如何不淑！","chunks":[["吊者升自西階，東面，致命曰：「寡君聞君之喪，寡君使某，如何不淑！","zh-Hant"]]},{"id":"li-ji_ch-20_p-51_s-9","passageId":"li-ji_ch-20_p-51","order":9,"canonicalText":"」子拜稽顙，吊者降，反位。","chunks":[["」子拜稽顙，吊者降，反位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-1","passageId":"li-ji_ch-20_p-52","order":1,"canonicalText":"含者執璧將命曰：「寡君使某含。","chunks":[["含者執璧將命曰：「寡君使某含。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-2","passageId":"li-ji_ch-20_p-52","order":2,"canonicalText":"」相者入告，出曰：「孤某須矣。","chunks":[["」相者入告，出曰：「孤某須矣。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-3","passageId":"li-ji_ch-20_p-52","order":3,"canonicalText":"」含者入，升堂，致命。","chunks":[["」含者入，升堂，致命。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-4","passageId":"li-ji_ch-20_p-52","order":4,"canonicalText":"再拜稽顙。","chunks":[["再拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-5","passageId":"li-ji_ch-20_p-52","order":5,"canonicalText":"含者坐委于殯東南，有葦席；","chunks":[["含者坐委于殯東南，有葦席；","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-6","passageId":"li-ji_ch-20_p-52","order":6,"canonicalText":"既葬，蒲席。","chunks":[["既葬，蒲席。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-7","passageId":"li-ji_ch-20_p-52","order":7,"canonicalText":"降，出，反位。","chunks":[["降，出，反位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-52_s-8","passageId":"li-ji_ch-20_p-52","order":8,"canonicalText":"宰朝服，即喪屨升自西階，西面，坐取璧，降自西階以東。","chunks":[["宰朝服，即喪屨升自西階，西面，坐取璧，降自西階以東。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-1","passageId":"li-ji_ch-20_p-53","order":1,"canonicalText":"襚者曰：「寡君使某襚。","chunks":[["襚者曰：「寡君使某襚。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-2","passageId":"li-ji_ch-20_p-53","order":2,"canonicalText":"」相者入告，出曰：「孤某須矣。","chunks":[["」相者入告，出曰：「孤某須矣。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-3","passageId":"li-ji_ch-20_p-53","order":3,"canonicalText":"」襚者執冕服；","chunks":[["」襚者執冕服；","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-4","passageId":"li-ji_ch-20_p-53","order":4,"canonicalText":"左執領，右執要，入，升堂致命曰：「寡君使某襚。","chunks":[["左執領，右執要，入，升堂致命曰：「寡君使某襚。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-5","passageId":"li-ji_ch-20_p-53","order":5,"canonicalText":"」子拜稽顙。","chunks":[["」子拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-6","passageId":"li-ji_ch-20_p-53","order":6,"canonicalText":"委衣於殯東。","chunks":[["委衣於殯東。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-7","passageId":"li-ji_ch-20_p-53","order":7,"canonicalText":"襚者降，受爵弁服於門內溜，將命，子拜稽顙，如初。","chunks":[["襚者降，受爵弁服於門內溜，將命，子拜稽顙，如初。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-8","passageId":"li-ji_ch-20_p-53","order":8,"canonicalText":"受皮弁服於中庭。","chunks":[["受皮弁服於中庭。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-9","passageId":"li-ji_ch-20_p-53","order":9,"canonicalText":"自西階受朝服，自堂受玄端，將命，子拜稽顙，皆如初。","chunks":[["自西階受朝服，自堂受玄端，將命，子拜稽顙，皆如初。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-10","passageId":"li-ji_ch-20_p-53","order":10,"canonicalText":"襚者降，出，反位。","chunks":[["襚者降，出，反位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-11","passageId":"li-ji_ch-20_p-53","order":11,"canonicalText":"宰夫五人，舉以東。","chunks":[["宰夫五人，舉以東。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-12","passageId":"li-ji_ch-20_p-53","order":12,"canonicalText":"降自西階。","chunks":[["降自西階。","zh-Hant"]]},{"id":"li-ji_ch-20_p-53_s-13","passageId":"li-ji_ch-20_p-53","order":13,"canonicalText":"其舉亦西面。","chunks":[["其舉亦西面。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-1","passageId":"li-ji_ch-20_p-54","order":1,"canonicalText":"上介賵：執圭將命，曰：「寡君使某賵。","chunks":[["上介賵：執圭將命，曰：「寡君使某賵。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-2","passageId":"li-ji_ch-20_p-54","order":2,"canonicalText":"」相者入告，反命曰：「孤某須矣。","chunks":[["」相者入告，反命曰：「孤某須矣。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-3","passageId":"li-ji_ch-20_p-54","order":3,"canonicalText":"」陳乘黃大路於中庭，北輈。","chunks":[["」陳乘黃大路於中庭，北輈。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-4","passageId":"li-ji_ch-20_p-54","order":4,"canonicalText":"執圭將命。","chunks":[["執圭將命。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-5","passageId":"li-ji_ch-20_p-54","order":5,"canonicalText":"客使自下，由路西。","chunks":[["客使自下，由路西。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-6","passageId":"li-ji_ch-20_p-54","order":6,"canonicalText":"子拜稽顙，坐委於殯東南隅。","chunks":[["子拜稽顙，坐委於殯東南隅。","zh-Hant"]]},{"id":"li-ji_ch-20_p-54_s-7","passageId":"li-ji_ch-20_p-54","order":7,"canonicalText":"宰舉以東。","chunks":[["宰舉以東。","zh-Hant"]]},{"id":"li-ji_ch-20_p-55_s-1","passageId":"li-ji_ch-20_p-55","order":1,"canonicalText":"凡將命，鄉殯將命，子拜稽顙。","chunks":[["凡將命，鄉殯將命，子拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-55_s-2","passageId":"li-ji_ch-20_p-55","order":2,"canonicalText":"西面而坐，委之。","chunks":[["西面而坐，委之。","zh-Hant"]]},{"id":"li-ji_ch-20_p-55_s-3","passageId":"li-ji_ch-20_p-55","order":3,"canonicalText":"宰舉璧與圭，宰夫舉襚，升自西階，西面，坐取之，降自西階。","chunks":[["宰舉璧與圭，宰夫舉襚，升自西階，西面，坐取之，降自西階。","zh-Hant"]]},{"id":"li-ji_ch-20_p-55_s-4","passageId":"li-ji_ch-20_p-55","order":4,"canonicalText":"賵者出，反位于門外。","chunks":[["賵者出，反位于門外。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-1","passageId":"li-ji_ch-20_p-56","order":1,"canonicalText":"上客臨曰：「寡君有宗廟之事，不得承事，使一介老某相執綍。","chunks":[["上客臨曰：「寡君有宗廟之事，不得承事，使一介老某相執綍。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-2","passageId":"li-ji_ch-20_p-56","order":2,"canonicalText":"」相者反命曰：「孤某須矣。","chunks":[["」相者反命曰：「孤某須矣。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-3","passageId":"li-ji_ch-20_p-56","order":3,"canonicalText":"」臨者入門右，介者皆從之，立於其左東上。","chunks":[["」臨者入門右，介者皆從之，立於其左東上。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-4","passageId":"li-ji_ch-20_p-56","order":4,"canonicalText":"宗人納賓，升，受命於君；","chunks":[["宗人納賓，升，受命於君；","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-5","passageId":"li-ji_ch-20_p-56","order":5,"canonicalText":"降曰：「孤敢辭吾子之辱，請吾子之復位。","chunks":[["降曰：「孤敢辭吾子之辱，請吾子之復位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-6","passageId":"li-ji_ch-20_p-56","order":6,"canonicalText":"」客對曰：「寡君命某，毋敢視賓客，敢辭。","chunks":[["」客對曰：「寡君命某，毋敢視賓客，敢辭。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-7","passageId":"li-ji_ch-20_p-56","order":7,"canonicalText":"」宗人反命曰：「孤敢固辭吾子之辱，請吾子之復位。","chunks":[["」宗人反命曰：「孤敢固辭吾子之辱，請吾子之復位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-8","passageId":"li-ji_ch-20_p-56","order":8,"canonicalText":"」客對曰：「寡君命某，毋敢視賓客，敢固辭。","chunks":[["」客對曰：「寡君命某，毋敢視賓客，敢固辭。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-9","passageId":"li-ji_ch-20_p-56","order":9,"canonicalText":"」宗人反命曰：「孤敢固辭吾子之辱，請吾子之復位。","chunks":[["」宗人反命曰：「孤敢固辭吾子之辱，請吾子之復位。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-10","passageId":"li-ji_ch-20_p-56","order":10,"canonicalText":"」客對曰：「寡君命使臣某，毋敢視賓客，是以敢固辭。","chunks":[["」客對曰：「寡君命使臣某，毋敢視賓客，是以敢固辭。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-11","passageId":"li-ji_ch-20_p-56","order":11,"canonicalText":"固辭不獲命，敢不敬從。","chunks":[["固辭不獲命，敢不敬從。","zh-Hant"]]},{"id":"li-ji_ch-20_p-56_s-12","passageId":"li-ji_ch-20_p-56","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-20_p-57_s-1","passageId":"li-ji_ch-20_p-57","order":1,"canonicalText":"客立於門西，介立於其左，東上。","chunks":[["客立於門西，介立於其左，東上。","zh-Hant"]]},{"id":"li-ji_ch-20_p-57_s-2","passageId":"li-ji_ch-20_p-57","order":2,"canonicalText":"孤降自阼階，拜之，升哭，與客拾踴三。","chunks":[["孤降自阼階，拜之，升哭，與客拾踴三。","zh-Hant"]]},{"id":"li-ji_ch-20_p-57_s-3","passageId":"li-ji_ch-20_p-57","order":3,"canonicalText":"客出，送於門外，拜稽顙。","chunks":[["客出，送於門外，拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-20_p-58_s-1","passageId":"li-ji_ch-20_p-58","order":1,"canonicalText":"其國有君喪，不敢受吊。","chunks":[["其國有君喪，不敢受吊。","zh-Hant"]]},{"id":"li-ji_ch-20_p-59_s-1","passageId":"li-ji_ch-20_p-59","order":1,"canonicalText":"外宗房中南面，小臣鋪席，商祝鋪絞紟衾，士盥於盤北。","chunks":[["外宗房中南面，小臣鋪席，商祝鋪絞紟衾，士盥於盤北。","zh-Hant"]]},{"id":"li-ji_ch-20_p-59_s-2","passageId":"li-ji_ch-20_p-59","order":2,"canonicalText":"舉遷尸於斂上，卒斂，宰告子，馮之踴。","chunks":[["舉遷尸於斂上，卒斂，宰告子，馮之踴。","zh-Hant"]]},{"id":"li-ji_ch-20_p-59_s-3","passageId":"li-ji_ch-20_p-59","order":3,"canonicalText":"夫人東面坐，馮之興踴。","chunks":[["夫人東面坐，馮之興踴。","zh-Hant"]]},{"id":"li-ji_ch-20_p-60_s-1","passageId":"li-ji_ch-20_p-60","order":1,"canonicalText":"士喪有與天子同者三：其終夜燎，及乘人，專道而行。","chunks":[["士喪有與天子同者三：其終夜燎，及乘人，專道而行。","zh-Hant"]]},{"id":"li-ji_ch-21_p-1_s-1","passageId":"li-ji_ch-21_p-1","order":1,"canonicalText":"有父之喪，如未沒喪而母死，其除父之喪也，服其除服。","chunks":[["有父之喪，如未沒喪而母死，其除父之喪也，服其除服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-1_s-2","passageId":"li-ji_ch-21_p-1","order":2,"canonicalText":"卒事，反喪服。","chunks":[["卒事，反喪服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-2_s-1","passageId":"li-ji_ch-21_p-2","order":1,"canonicalText":"雖諸父昆弟之喪，如當父母之喪，其除諸父昆弟之喪也，皆服其除喪之服。","chunks":[["雖諸父昆弟之喪，如當父母之喪，其除諸父昆弟之喪也，皆服其除喪之服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-2_s-2","passageId":"li-ji_ch-21_p-2","order":2,"canonicalText":"卒事，反喪服。","chunks":[["卒事，反喪服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-3_s-1","passageId":"li-ji_ch-21_p-3","order":1,"canonicalText":"如三年之喪，則既顈，其練祥皆同。","chunks":[["如三年之喪，則既顈，其練祥皆同。","zh-Hant"]]},{"id":"li-ji_ch-21_p-4_s-1","passageId":"li-ji_ch-21_p-4","order":1,"canonicalText":"王父死，未練祥而孫又死，猶是附於王父也。","chunks":[["王父死，未練祥而孫又死，猶是附於王父也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-5_s-1","passageId":"li-ji_ch-21_p-5","order":1,"canonicalText":"有殯，聞外喪，哭之他室。","chunks":[["有殯，聞外喪，哭之他室。","zh-Hant"]]},{"id":"li-ji_ch-21_p-5_s-2","passageId":"li-ji_ch-21_p-5","order":2,"canonicalText":"入奠，卒奠，出，改服即位，如始即位之禮。","chunks":[["入奠，卒奠，出，改服即位，如始即位之禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-1","passageId":"li-ji_ch-21_p-6","order":1,"canonicalText":"大夫、士將與祭於公，既視濯，而父母死，則猶是與祭也，次於異宮。","chunks":[["大夫、士將與祭於公，既視濯，而父母死，則猶是與祭也，次於異宮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-2","passageId":"li-ji_ch-21_p-6","order":2,"canonicalText":"既祭，釋服出公門外，哭而歸。","chunks":[["既祭，釋服出公門外，哭而歸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-3","passageId":"li-ji_ch-21_p-6","order":3,"canonicalText":"其它如奔喪之禮。","chunks":[["其它如奔喪之禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-4","passageId":"li-ji_ch-21_p-6","order":4,"canonicalText":"如未視濯，則使人告。","chunks":[["如未視濯，則使人告。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-5","passageId":"li-ji_ch-21_p-6","order":5,"canonicalText":"告者反，而後哭。","chunks":[["告者反，而後哭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-6","passageId":"li-ji_ch-21_p-6","order":6,"canonicalText":"如諸父昆弟姑姊妹之喪，則既宿，則與祭。","chunks":[["如諸父昆弟姑姊妹之喪，則既宿，則與祭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-7","passageId":"li-ji_ch-21_p-6","order":7,"canonicalText":"卒事，出公門，釋服而後歸。","chunks":[["卒事，出公門，釋服而後歸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-8","passageId":"li-ji_ch-21_p-6","order":8,"canonicalText":"其它如奔喪之禮。","chunks":[["其它如奔喪之禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-6_s-9","passageId":"li-ji_ch-21_p-6","order":9,"canonicalText":"如同宮，則次於異宮。","chunks":[["如同宮，則次於異宮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-7_s-1","passageId":"li-ji_ch-21_p-7","order":1,"canonicalText":"曾子問曰：「卿大夫將為尸於公，受宿矣，而有齊衰內喪，則如之何？","chunks":[["曾子問曰：「卿大夫將為尸於公，受宿矣，而有齊衰內喪，則如之何？","zh-Hant"]]},{"id":"li-ji_ch-21_p-7_s-2","passageId":"li-ji_ch-21_p-7","order":2,"canonicalText":"」孔子曰：「出舍乎公宮以待事，禮也。","chunks":[["」孔子曰：「出舍乎公宮以待事，禮也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-7_s-3","passageId":"li-ji_ch-21_p-7","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-8_s-1","passageId":"li-ji_ch-21_p-8","order":1,"canonicalText":"孔子曰：「尸弁冕而出，卿、大夫、士皆下之。","chunks":[["孔子曰：「尸弁冕而出，卿、大夫、士皆下之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-8_s-2","passageId":"li-ji_ch-21_p-8","order":2,"canonicalText":"尸必式，必有前驅。","chunks":[["尸必式，必有前驅。","zh-Hant"]]},{"id":"li-ji_ch-21_p-8_s-3","passageId":"li-ji_ch-21_p-8","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-9_s-1","passageId":"li-ji_ch-21_p-9","order":1,"canonicalText":"父母之喪，將祭，而昆弟死；","chunks":[["父母之喪，將祭，而昆弟死；","zh-Hant"]]},{"id":"li-ji_ch-21_p-9_s-2","passageId":"li-ji_ch-21_p-9","order":2,"canonicalText":"既殯而祭。","chunks":[["既殯而祭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-9_s-3","passageId":"li-ji_ch-21_p-9","order":3,"canonicalText":"如同宮，則雖臣妾，葬而後祭。","chunks":[["如同宮，則雖臣妾，葬而後祭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-9_s-4","passageId":"li-ji_ch-21_p-9","order":4,"canonicalText":"祭，主人之升降散等，執事者亦散等。","chunks":[["祭，主人之升降散等，執事者亦散等。","zh-Hant"]]},{"id":"li-ji_ch-21_p-9_s-5","passageId":"li-ji_ch-21_p-9","order":5,"canonicalText":"雖虞附亦然。","chunks":[["雖虞附亦然。","zh-Hant"]]},{"id":"li-ji_ch-21_p-10_s-1","passageId":"li-ji_ch-21_p-10","order":1,"canonicalText":"自諸侯達諸士，小祥之祭，主人之酢也嚌之；","chunks":[["自諸侯達諸士，小祥之祭，主人之酢也嚌之；","zh-Hant"]]},{"id":"li-ji_ch-21_p-10_s-2","passageId":"li-ji_ch-21_p-10","order":2,"canonicalText":"眾賓兄弟，則皆啐之。","chunks":[["眾賓兄弟，則皆啐之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-10_s-3","passageId":"li-ji_ch-21_p-10","order":3,"canonicalText":"大祥：主人啐之，眾賓兄弟皆飲之，可也。","chunks":[["大祥：主人啐之，眾賓兄弟皆飲之，可也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-11_s-1","passageId":"li-ji_ch-21_p-11","order":1,"canonicalText":"凡侍祭喪者，告賓祭薦而不食。","chunks":[["凡侍祭喪者，告賓祭薦而不食。","zh-Hant"]]},{"id":"li-ji_ch-21_p-12_s-1","passageId":"li-ji_ch-21_p-12","order":1,"canonicalText":"子貢問喪，子曰：「敬為上，哀次之，瘠為下。","chunks":[["子貢問喪，子曰：「敬為上，哀次之，瘠為下。","zh-Hant"]]},{"id":"li-ji_ch-21_p-12_s-2","passageId":"li-ji_ch-21_p-12","order":2,"canonicalText":"顏色稱其情；","chunks":[["顏色稱其情；","zh-Hant"]]},{"id":"li-ji_ch-21_p-12_s-3","passageId":"li-ji_ch-21_p-12","order":3,"canonicalText":"戚容稱其服。","chunks":[["戚容稱其服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-12_s-4","passageId":"li-ji_ch-21_p-12","order":4,"canonicalText":"」請問兄弟之喪，子曰：「兄弟之喪，則存乎書策矣。","chunks":[["」請問兄弟之喪，子曰：「兄弟之喪，則存乎書策矣。","zh-Hant"]]},{"id":"li-ji_ch-21_p-12_s-5","passageId":"li-ji_ch-21_p-12","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-13_s-1","passageId":"li-ji_ch-21_p-13","order":1,"canonicalText":"君子不奪人之喪，亦不可奪喪也。","chunks":[["君子不奪人之喪，亦不可奪喪也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-14_s-1","passageId":"li-ji_ch-21_p-14","order":1,"canonicalText":"孔子曰：「少連、大連善居喪，三日不怠，三月不解，期悲哀，三年憂。","chunks":[["孔子曰：「少連、大連善居喪，三日不怠，三月不解，期悲哀，三年憂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-14_s-2","passageId":"li-ji_ch-21_p-14","order":2,"canonicalText":"東夷之子也。","chunks":[["東夷之子也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-14_s-3","passageId":"li-ji_ch-21_p-14","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-15_s-1","passageId":"li-ji_ch-21_p-15","order":1,"canonicalText":"三年之喪，言而不語，對而不問：廬，堊室之中，不與人坐焉；","chunks":[["三年之喪，言而不語，對而不問：廬，堊室之中，不與人坐焉；","zh-Hant"]]},{"id":"li-ji_ch-21_p-15_s-2","passageId":"li-ji_ch-21_p-15","order":2,"canonicalText":"在堊室之中，非時見乎母也，不入門。","chunks":[["在堊室之中，非時見乎母也，不入門。","zh-Hant"]]},{"id":"li-ji_ch-21_p-15_s-3","passageId":"li-ji_ch-21_p-15","order":3,"canonicalText":"疏衰皆居堊室不廬。","chunks":[["疏衰皆居堊室不廬。","zh-Hant"]]},{"id":"li-ji_ch-21_p-15_s-4","passageId":"li-ji_ch-21_p-15","order":4,"canonicalText":"廬，嚴者也。","chunks":[["廬，嚴者也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-16_s-1","passageId":"li-ji_ch-21_p-16","order":1,"canonicalText":"妻視叔父母，姑姊妹視兄弟，長、中、下殤視成人。","chunks":[["妻視叔父母，姑姊妹視兄弟，長、中、下殤視成人。","zh-Hant"]]},{"id":"li-ji_ch-21_p-17_s-1","passageId":"li-ji_ch-21_p-17","order":1,"canonicalText":"親喪外除，兄弟之喪內除。","chunks":[["親喪外除，兄弟之喪內除。","zh-Hant"]]},{"id":"li-ji_ch-21_p-18_s-1","passageId":"li-ji_ch-21_p-18","order":1,"canonicalText":"視君之母與妻，比之兄弟。","chunks":[["視君之母與妻，比之兄弟。","zh-Hant"]]},{"id":"li-ji_ch-21_p-18_s-2","passageId":"li-ji_ch-21_p-18","order":2,"canonicalText":"發諸顏色者，亦不飲食也。","chunks":[["發諸顏色者，亦不飲食也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-19_s-1","passageId":"li-ji_ch-21_p-19","order":1,"canonicalText":"免喪之外，行於道路，見似目瞿，聞名心瞿。","chunks":[["免喪之外，行於道路，見似目瞿，聞名心瞿。","zh-Hant"]]},{"id":"li-ji_ch-21_p-19_s-2","passageId":"li-ji_ch-21_p-19","order":2,"canonicalText":"吊死而問疾，顏色戚容必有以異於人也。","chunks":[["吊死而問疾，顏色戚容必有以異於人也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-19_s-3","passageId":"li-ji_ch-21_p-19","order":3,"canonicalText":"如此而後可以服三年之喪。","chunks":[["如此而後可以服三年之喪。","zh-Hant"]]},{"id":"li-ji_ch-21_p-19_s-4","passageId":"li-ji_ch-21_p-19","order":4,"canonicalText":"其餘則直道而行之，是也。","chunks":[["其餘則直道而行之，是也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-20_s-1","passageId":"li-ji_ch-21_p-20","order":1,"canonicalText":"祥，主人之除也，於夕為期，朝服。","chunks":[["祥，主人之除也，於夕為期，朝服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-20_s-2","passageId":"li-ji_ch-21_p-20","order":2,"canonicalText":"祥因其故服。","chunks":[["祥因其故服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-21_s-1","passageId":"li-ji_ch-21_p-21","order":1,"canonicalText":"子游曰：「既祥，雖不當縞者必縞，然後反服。","chunks":[["子游曰：「既祥，雖不當縞者必縞，然後反服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-21_s-2","passageId":"li-ji_ch-21_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-22_s-1","passageId":"li-ji_ch-21_p-22","order":1,"canonicalText":"當袒，大夫至，雖當踴，絕踴而拜之，反改成踴，乃襲。","chunks":[["當袒，大夫至，雖當踴，絕踴而拜之，反改成踴，乃襲。","zh-Hant"]]},{"id":"li-ji_ch-21_p-22_s-2","passageId":"li-ji_ch-21_p-22","order":2,"canonicalText":"於士，既事成踴，襲而後拜之，不改成踴。","chunks":[["於士，既事成踴，襲而後拜之，不改成踴。","zh-Hant"]]},{"id":"li-ji_ch-21_p-23_s-1","passageId":"li-ji_ch-21_p-23","order":1,"canonicalText":"上大夫之虞也，少牢。","chunks":[["上大夫之虞也，少牢。","zh-Hant"]]},{"id":"li-ji_ch-21_p-23_s-2","passageId":"li-ji_ch-21_p-23","order":2,"canonicalText":"卒哭成事，附，皆大牢。","chunks":[["卒哭成事，附，皆大牢。","zh-Hant"]]},{"id":"li-ji_ch-21_p-23_s-3","passageId":"li-ji_ch-21_p-23","order":3,"canonicalText":"下大夫之虞也，特牲。","chunks":[["下大夫之虞也，特牲。","zh-Hant"]]},{"id":"li-ji_ch-21_p-23_s-4","passageId":"li-ji_ch-21_p-23","order":4,"canonicalText":"卒哭成事，附，皆少牢。","chunks":[["卒哭成事，附，皆少牢。","zh-Hant"]]},{"id":"li-ji_ch-21_p-24_s-1","passageId":"li-ji_ch-21_p-24","order":1,"canonicalText":"祝稱卜葬虞，子孫曰哀，夫曰乃，兄弟曰某，卜葬其兄弟曰伯子某。","chunks":[["祝稱卜葬虞，子孫曰哀，夫曰乃，兄弟曰某，卜葬其兄弟曰伯子某。","zh-Hant"]]},{"id":"li-ji_ch-21_p-25_s-1","passageId":"li-ji_ch-21_p-25","order":1,"canonicalText":"古者，貴賤皆杖。","chunks":[["古者，貴賤皆杖。","zh-Hant"]]},{"id":"li-ji_ch-21_p-25_s-2","passageId":"li-ji_ch-21_p-25","order":2,"canonicalText":"叔孫武叔朝，見輪人以其杖關轂而輠輪者，於是有爵而後杖也。","chunks":[["叔孫武叔朝，見輪人以其杖關轂而輠輪者，於是有爵而後杖也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-26_s-1","passageId":"li-ji_ch-21_p-26","order":1,"canonicalText":"鑿巾以飯，公羊賈為之也。","chunks":[["鑿巾以飯，公羊賈為之也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-27_s-1","passageId":"li-ji_ch-21_p-27","order":1,"canonicalText":"冒者何也？","chunks":[["冒者何也？","zh-Hant"]]},{"id":"li-ji_ch-21_p-27_s-2","passageId":"li-ji_ch-21_p-27","order":2,"canonicalText":"所以掩形也。","chunks":[["所以掩形也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-27_s-3","passageId":"li-ji_ch-21_p-27","order":3,"canonicalText":"自襲以至小斂，不設冒則形，是以襲而後設冒也。","chunks":[["自襲以至小斂，不設冒則形，是以襲而後設冒也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-1","passageId":"li-ji_ch-21_p-28","order":1,"canonicalText":"或問於曾子曰：「夫既遣而包其餘，猶既食而裹其餘與？","chunks":[["或問於曾子曰：「夫既遣而包其餘，猶既食而裹其餘與？","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-2","passageId":"li-ji_ch-21_p-28","order":2,"canonicalText":"君子既食，則裹其餘乎？","chunks":[["君子既食，則裹其餘乎？","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-3","passageId":"li-ji_ch-21_p-28","order":3,"canonicalText":"」曾子曰：「吾子不見大饗乎？","chunks":[["」曾子曰：「吾子不見大饗乎？","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-4","passageId":"li-ji_ch-21_p-28","order":4,"canonicalText":"夫大饗，既饗，卷三牲之俎歸於賓館。","chunks":[["夫大饗，既饗，卷三牲之俎歸於賓館。","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-5","passageId":"li-ji_ch-21_p-28","order":5,"canonicalText":"父母而賓客之，所以為哀也！","chunks":[["父母而賓客之，所以為哀也！","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-6","passageId":"li-ji_ch-21_p-28","order":6,"canonicalText":"子不見大饗乎！","chunks":[["子不見大饗乎！","zh-Hant"]]},{"id":"li-ji_ch-21_p-28_s-7","passageId":"li-ji_ch-21_p-28","order":7,"canonicalText":"」非為人喪，問與賜與？","chunks":[["」非為人喪，問與賜與？","zh-Hant"]]},{"id":"li-ji_ch-21_p-29_s-1","passageId":"li-ji_ch-21_p-29","order":1,"canonicalText":"三年之喪，以其喪拜；","chunks":[["三年之喪，以其喪拜；","zh-Hant"]]},{"id":"li-ji_ch-21_p-29_s-2","passageId":"li-ji_ch-21_p-29","order":2,"canonicalText":"非三年之喪，以吉拜。","chunks":[["非三年之喪，以吉拜。","zh-Hant"]]},{"id":"li-ji_ch-21_p-30_s-1","passageId":"li-ji_ch-21_p-30","order":1,"canonicalText":"三年之喪，如或遺之酒肉，則受之必三辭。","chunks":[["三年之喪，如或遺之酒肉，則受之必三辭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-30_s-2","passageId":"li-ji_ch-21_p-30","order":2,"canonicalText":"主人衰絰而受之。","chunks":[["主人衰絰而受之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-30_s-3","passageId":"li-ji_ch-21_p-30","order":3,"canonicalText":"如君命，則不敢辭，受而薦之。","chunks":[["如君命，則不敢辭，受而薦之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-30_s-4","passageId":"li-ji_ch-21_p-30","order":4,"canonicalText":"喪者不遺人，人遺之，雖酒肉，受也。","chunks":[["喪者不遺人，人遺之，雖酒肉，受也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-30_s-5","passageId":"li-ji_ch-21_p-30","order":5,"canonicalText":"從父昆弟以下，既卒哭，遺人可也。","chunks":[["從父昆弟以下，既卒哭，遺人可也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-31_s-1","passageId":"li-ji_ch-21_p-31","order":1,"canonicalText":"縣子曰：「三年之喪，如斬。","chunks":[["縣子曰：「三年之喪，如斬。","zh-Hant"]]},{"id":"li-ji_ch-21_p-31_s-2","passageId":"li-ji_ch-21_p-31","order":2,"canonicalText":"期之喪，如剡。","chunks":[["期之喪，如剡。","zh-Hant"]]},{"id":"li-ji_ch-21_p-31_s-3","passageId":"li-ji_ch-21_p-31","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-32_s-1","passageId":"li-ji_ch-21_p-32","order":1,"canonicalText":"三年之喪，雖功衰不吊，自諸侯達諸士。","chunks":[["三年之喪，雖功衰不吊，自諸侯達諸士。","zh-Hant"]]},{"id":"li-ji_ch-21_p-32_s-2","passageId":"li-ji_ch-21_p-32","order":2,"canonicalText":"如有服而將往哭之，則服其服而往。","chunks":[["如有服而將往哭之，則服其服而往。","zh-Hant"]]},{"id":"li-ji_ch-21_p-32_s-3","passageId":"li-ji_ch-21_p-32","order":3,"canonicalText":"期之喪，十一月而練，十三月而祥，十五月禫。","chunks":[["期之喪，十一月而練，十三月而祥，十五月禫。","zh-Hant"]]},{"id":"li-ji_ch-21_p-32_s-4","passageId":"li-ji_ch-21_p-32","order":4,"canonicalText":"練則吊。","chunks":[["練則吊。","zh-Hant"]]},{"id":"li-ji_ch-21_p-33_s-1","passageId":"li-ji_ch-21_p-33","order":1,"canonicalText":"既葬，大功吊，哭而退，不聽事焉。","chunks":[["既葬，大功吊，哭而退，不聽事焉。","zh-Hant"]]},{"id":"li-ji_ch-21_p-33_s-2","passageId":"li-ji_ch-21_p-33","order":2,"canonicalText":"期之喪，未喪，吊於鄉人。","chunks":[["期之喪，未喪，吊於鄉人。","zh-Hant"]]},{"id":"li-ji_ch-21_p-33_s-3","passageId":"li-ji_ch-21_p-33","order":3,"canonicalText":"哭而退，不聽事焉。","chunks":[["哭而退，不聽事焉。","zh-Hant"]]},{"id":"li-ji_ch-21_p-33_s-4","passageId":"li-ji_ch-21_p-33","order":4,"canonicalText":"功衰吊，待事不執事。","chunks":[["功衰吊，待事不執事。","zh-Hant"]]},{"id":"li-ji_ch-21_p-33_s-5","passageId":"li-ji_ch-21_p-33","order":5,"canonicalText":"小功緦，執事不與於禮。","chunks":[["小功緦，執事不與於禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-1","passageId":"li-ji_ch-21_p-34","order":1,"canonicalText":"相趨也，出宮而退。","chunks":[["相趨也，出宮而退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-2","passageId":"li-ji_ch-21_p-34","order":2,"canonicalText":"相揖也，哀次而退。","chunks":[["相揖也，哀次而退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-3","passageId":"li-ji_ch-21_p-34","order":3,"canonicalText":"相問也，既封而退。","chunks":[["相問也，既封而退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-4","passageId":"li-ji_ch-21_p-34","order":4,"canonicalText":"相見也。","chunks":[["相見也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-5","passageId":"li-ji_ch-21_p-34","order":5,"canonicalText":"反哭而退。","chunks":[["反哭而退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-6","passageId":"li-ji_ch-21_p-34","order":6,"canonicalText":"朋友，虞附而退。","chunks":[["朋友，虞附而退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-7","passageId":"li-ji_ch-21_p-34","order":7,"canonicalText":"吊，非從主人也。","chunks":[["吊，非從主人也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-34_s-8","passageId":"li-ji_ch-21_p-34","order":8,"canonicalText":"四十者執綍：鄉人五十者從反哭，四十者待盈坎。","chunks":[["四十者執綍：鄉人五十者從反哭，四十者待盈坎。","zh-Hant"]]},{"id":"li-ji_ch-21_p-35_s-1","passageId":"li-ji_ch-21_p-35","order":1,"canonicalText":"喪食雖惡必充饑，饑而廢事，非禮也；","chunks":[["喪食雖惡必充饑，饑而廢事，非禮也；","zh-Hant"]]},{"id":"li-ji_ch-21_p-35_s-2","passageId":"li-ji_ch-21_p-35","order":2,"canonicalText":"飽而忘哀，亦非禮也。","chunks":[["飽而忘哀，亦非禮也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-35_s-3","passageId":"li-ji_ch-21_p-35","order":3,"canonicalText":"視不明，聽不聰，行不正，不知哀，君子病之。","chunks":[["視不明，聽不聰，行不正，不知哀，君子病之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-35_s-4","passageId":"li-ji_ch-21_p-35","order":4,"canonicalText":"故有疾飲酒食肉，五十不致毀，六十不毀，七十飲酒食肉，皆為疑死。","chunks":[["故有疾飲酒食肉，五十不致毀，六十不毀，七十飲酒食肉，皆為疑死。","zh-Hant"]]},{"id":"li-ji_ch-21_p-36_s-1","passageId":"li-ji_ch-21_p-36","order":1,"canonicalText":"有服，人召之食，不往。","chunks":[["有服，人召之食，不往。","zh-Hant"]]},{"id":"li-ji_ch-21_p-36_s-2","passageId":"li-ji_ch-21_p-36","order":2,"canonicalText":"大功以下，既葬，適人，人食之，其黨也食之，非其黨弗食也。","chunks":[["大功以下，既葬，適人，人食之，其黨也食之，非其黨弗食也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-36_s-3","passageId":"li-ji_ch-21_p-36","order":3,"canonicalText":"功衰食菜果，飲水漿，無鹽酪。","chunks":[["功衰食菜果，飲水漿，無鹽酪。","zh-Hant"]]},{"id":"li-ji_ch-21_p-36_s-4","passageId":"li-ji_ch-21_p-36","order":4,"canonicalText":"不能食食，鹽酪可也。","chunks":[["不能食食，鹽酪可也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-37_s-1","passageId":"li-ji_ch-21_p-37","order":1,"canonicalText":"孔子曰：「身有瘍則浴，首有創則沐，病則飲酒食肉。","chunks":[["孔子曰：「身有瘍則浴，首有創則沐，病則飲酒食肉。","zh-Hant"]]},{"id":"li-ji_ch-21_p-37_s-2","passageId":"li-ji_ch-21_p-37","order":2,"canonicalText":"毀瘠為病，君子弗為也。","chunks":[["毀瘠為病，君子弗為也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-37_s-3","passageId":"li-ji_ch-21_p-37","order":3,"canonicalText":"毀而死，君子謂之無子。","chunks":[["毀而死，君子謂之無子。","zh-Hant"]]},{"id":"li-ji_ch-21_p-37_s-4","passageId":"li-ji_ch-21_p-37","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-38_s-1","passageId":"li-ji_ch-21_p-38","order":1,"canonicalText":"非從柩與反哭，無免於堩。","chunks":[["非從柩與反哭，無免於堩。","zh-Hant"]]},{"id":"li-ji_ch-21_p-39_s-1","passageId":"li-ji_ch-21_p-39","order":1,"canonicalText":"凡喪，小功以上，非虞附練祥，無沐浴。","chunks":[["凡喪，小功以上，非虞附練祥，無沐浴。","zh-Hant"]]},{"id":"li-ji_ch-21_p-40_s-1","passageId":"li-ji_ch-21_p-40","order":1,"canonicalText":"疏衰之喪，既葬，人請見之，則見；","chunks":[["疏衰之喪，既葬，人請見之，則見；","zh-Hant"]]},{"id":"li-ji_ch-21_p-40_s-2","passageId":"li-ji_ch-21_p-40","order":2,"canonicalText":"不請見人。","chunks":[["不請見人。","zh-Hant"]]},{"id":"li-ji_ch-21_p-40_s-3","passageId":"li-ji_ch-21_p-40","order":3,"canonicalText":"小功，請見人可也。","chunks":[["小功，請見人可也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-40_s-4","passageId":"li-ji_ch-21_p-40","order":4,"canonicalText":"大功不以執摯。","chunks":[["大功不以執摯。","zh-Hant"]]},{"id":"li-ji_ch-21_p-40_s-5","passageId":"li-ji_ch-21_p-40","order":5,"canonicalText":"唯父母之喪，不辟涕泣而見人。","chunks":[["唯父母之喪，不辟涕泣而見人。","zh-Hant"]]},{"id":"li-ji_ch-21_p-41_s-1","passageId":"li-ji_ch-21_p-41","order":1,"canonicalText":"三年之喪，祥而從政；","chunks":[["三年之喪，祥而從政；","zh-Hant"]]},{"id":"li-ji_ch-21_p-41_s-2","passageId":"li-ji_ch-21_p-41","order":2,"canonicalText":"期之喪，卒哭而從政；","chunks":[["期之喪，卒哭而從政；","zh-Hant"]]},{"id":"li-ji_ch-21_p-41_s-3","passageId":"li-ji_ch-21_p-41","order":3,"canonicalText":"九月之喪，既葬而從政；","chunks":[["九月之喪，既葬而從政；","zh-Hant"]]},{"id":"li-ji_ch-21_p-41_s-4","passageId":"li-ji_ch-21_p-41","order":4,"canonicalText":"小功緦之喪，既殯而從政。","chunks":[["小功緦之喪，既殯而從政。","zh-Hant"]]},{"id":"li-ji_ch-21_p-42_s-1","passageId":"li-ji_ch-21_p-42","order":1,"canonicalText":"曾申問於曾子曰：「哭父母有常聲乎？","chunks":[["曾申問於曾子曰：「哭父母有常聲乎？","zh-Hant"]]},{"id":"li-ji_ch-21_p-42_s-2","passageId":"li-ji_ch-21_p-42","order":2,"canonicalText":"」曰：「中路嬰兒失其母焉，何常聲之有？","chunks":[["」曰：「中路嬰兒失其母焉，何常聲之有？","zh-Hant"]]},{"id":"li-ji_ch-21_p-42_s-3","passageId":"li-ji_ch-21_p-42","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-1","passageId":"li-ji_ch-21_p-43","order":1,"canonicalText":"卒哭而諱。","chunks":[["卒哭而諱。","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-2","passageId":"li-ji_ch-21_p-43","order":2,"canonicalText":"王父母兄弟，世父叔父，姑姊妹。","chunks":[["王父母兄弟，世父叔父，姑姊妹。","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-3","passageId":"li-ji_ch-21_p-43","order":3,"canonicalText":"子與父同諱。","chunks":[["子與父同諱。","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-4","passageId":"li-ji_ch-21_p-43","order":4,"canonicalText":"母之諱，宮中諱。","chunks":[["母之諱，宮中諱。","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-5","passageId":"li-ji_ch-21_p-43","order":5,"canonicalText":"妻之諱，不舉諸其側；","chunks":[["妻之諱，不舉諸其側；","zh-Hant"]]},{"id":"li-ji_ch-21_p-43_s-6","passageId":"li-ji_ch-21_p-43","order":6,"canonicalText":"與從祖昆弟同名則諱。","chunks":[["與從祖昆弟同名則諱。","zh-Hant"]]},{"id":"li-ji_ch-21_p-44_s-1","passageId":"li-ji_ch-21_p-44","order":1,"canonicalText":"以喪冠者，雖三年之喪，可也。","chunks":[["以喪冠者，雖三年之喪，可也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-44_s-2","passageId":"li-ji_ch-21_p-44","order":2,"canonicalText":"既冠於次，入哭踴，三者三，乃出。","chunks":[["既冠於次，入哭踴，三者三，乃出。","zh-Hant"]]},{"id":"li-ji_ch-21_p-45_s-1","passageId":"li-ji_ch-21_p-45","order":1,"canonicalText":"大功之末，可以冠子，可以嫁子。","chunks":[["大功之末，可以冠子，可以嫁子。","zh-Hant"]]},{"id":"li-ji_ch-21_p-45_s-2","passageId":"li-ji_ch-21_p-45","order":2,"canonicalText":"父，小功之末，可以冠子，可以嫁子，可以取婦。","chunks":[["父，小功之末，可以冠子，可以嫁子，可以取婦。","zh-Hant"]]},{"id":"li-ji_ch-21_p-45_s-3","passageId":"li-ji_ch-21_p-45","order":3,"canonicalText":"己雖小功，既卒哭，可以冠，取妻；","chunks":[["己雖小功，既卒哭，可以冠，取妻；","zh-Hant"]]},{"id":"li-ji_ch-21_p-45_s-4","passageId":"li-ji_ch-21_p-45","order":4,"canonicalText":"下殤之小功，則不可。","chunks":[["下殤之小功，則不可。","zh-Hant"]]},{"id":"li-ji_ch-21_p-46_s-1","passageId":"li-ji_ch-21_p-46","order":1,"canonicalText":"凡弁絰，其衰侈袂。","chunks":[["凡弁絰，其衰侈袂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-47_s-1","passageId":"li-ji_ch-21_p-47","order":1,"canonicalText":"父有服，宮中子不與於樂。","chunks":[["父有服，宮中子不與於樂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-47_s-2","passageId":"li-ji_ch-21_p-47","order":2,"canonicalText":"母有服，聲聞焉不舉樂。","chunks":[["母有服，聲聞焉不舉樂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-47_s-3","passageId":"li-ji_ch-21_p-47","order":3,"canonicalText":"妻有服，不舉樂於其側。","chunks":[["妻有服，不舉樂於其側。","zh-Hant"]]},{"id":"li-ji_ch-21_p-47_s-4","passageId":"li-ji_ch-21_p-47","order":4,"canonicalText":"大功將至，辟琴瑟。","chunks":[["大功將至，辟琴瑟。","zh-Hant"]]},{"id":"li-ji_ch-21_p-47_s-5","passageId":"li-ji_ch-21_p-47","order":5,"canonicalText":"小功至，不絕樂。","chunks":[["小功至，不絕樂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-48_s-1","passageId":"li-ji_ch-21_p-48","order":1,"canonicalText":"姑姊妹，其夫死，而夫黨無兄弟，使夫之族人主喪。","chunks":[["姑姊妹，其夫死，而夫黨無兄弟，使夫之族人主喪。","zh-Hant"]]},{"id":"li-ji_ch-21_p-48_s-2","passageId":"li-ji_ch-21_p-48","order":2,"canonicalText":"妻之黨，雖親弗主。","chunks":[["妻之黨，雖親弗主。","zh-Hant"]]},{"id":"li-ji_ch-21_p-48_s-3","passageId":"li-ji_ch-21_p-48","order":3,"canonicalText":"夫若無族矣，則前後家，東西家；","chunks":[["夫若無族矣，則前後家，東西家；","zh-Hant"]]},{"id":"li-ji_ch-21_p-48_s-4","passageId":"li-ji_ch-21_p-48","order":4,"canonicalText":"無有，則里尹主之。","chunks":[["無有，則里尹主之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-48_s-5","passageId":"li-ji_ch-21_p-48","order":5,"canonicalText":"或曰：主之，而附於夫之黨。","chunks":[["或曰：主之，而附於夫之黨。","zh-Hant"]]},{"id":"li-ji_ch-21_p-49_s-1","passageId":"li-ji_ch-21_p-49","order":1,"canonicalText":"麻者不紳，執玉不麻。","chunks":[["麻者不紳，執玉不麻。","zh-Hant"]]},{"id":"li-ji_ch-21_p-49_s-2","passageId":"li-ji_ch-21_p-49","order":2,"canonicalText":"麻不加於采。","chunks":[["麻不加於采。","zh-Hant"]]},{"id":"li-ji_ch-21_p-50_s-1","passageId":"li-ji_ch-21_p-50","order":1,"canonicalText":"國禁哭，則止朝夕之奠。","chunks":[["國禁哭，則止朝夕之奠。","zh-Hant"]]},{"id":"li-ji_ch-21_p-50_s-2","passageId":"li-ji_ch-21_p-50","order":2,"canonicalText":"即位自因也。","chunks":[["即位自因也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-51_s-1","passageId":"li-ji_ch-21_p-51","order":1,"canonicalText":"童子哭不偯，不踴，不杖，不菲，不廬。","chunks":[["童子哭不偯，不踴，不杖，不菲，不廬。","zh-Hant"]]},{"id":"li-ji_ch-21_p-52_s-1","passageId":"li-ji_ch-21_p-52","order":1,"canonicalText":"孔子曰：「伯母、叔母，疏衰，踴不絕地。","chunks":[["孔子曰：「伯母、叔母，疏衰，踴不絕地。","zh-Hant"]]},{"id":"li-ji_ch-21_p-52_s-2","passageId":"li-ji_ch-21_p-52","order":2,"canonicalText":"姑姊妹之大功，踴絕於地。","chunks":[["姑姊妹之大功，踴絕於地。","zh-Hant"]]},{"id":"li-ji_ch-21_p-52_s-3","passageId":"li-ji_ch-21_p-52","order":3,"canonicalText":"如知此者，由文矣哉！","chunks":[["如知此者，由文矣哉！","zh-Hant"]]},{"id":"li-ji_ch-21_p-52_s-4","passageId":"li-ji_ch-21_p-52","order":4,"canonicalText":"由文矣哉！","chunks":[["由文矣哉！","zh-Hant"]]},{"id":"li-ji_ch-21_p-52_s-5","passageId":"li-ji_ch-21_p-52","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-53_s-1","passageId":"li-ji_ch-21_p-53","order":1,"canonicalText":"世柳之母死，相者由左。","chunks":[["世柳之母死，相者由左。","zh-Hant"]]},{"id":"li-ji_ch-21_p-53_s-2","passageId":"li-ji_ch-21_p-53","order":2,"canonicalText":"世柳死，其徒由右相。","chunks":[["世柳死，其徒由右相。","zh-Hant"]]},{"id":"li-ji_ch-21_p-53_s-3","passageId":"li-ji_ch-21_p-53","order":3,"canonicalText":"由右相，世柳之徒為之也。","chunks":[["由右相，世柳之徒為之也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-54_s-1","passageId":"li-ji_ch-21_p-54","order":1,"canonicalText":"天子飯，九貝；","chunks":[["天子飯，九貝；","zh-Hant"]]},{"id":"li-ji_ch-21_p-54_s-2","passageId":"li-ji_ch-21_p-54","order":2,"canonicalText":"諸侯七，大夫五，士三。","chunks":[["諸侯七，大夫五，士三。","zh-Hant"]]},{"id":"li-ji_ch-21_p-55_s-1","passageId":"li-ji_ch-21_p-55","order":1,"canonicalText":"士三月而葬，是月也卒哭；","chunks":[["士三月而葬，是月也卒哭；","zh-Hant"]]},{"id":"li-ji_ch-21_p-55_s-2","passageId":"li-ji_ch-21_p-55","order":2,"canonicalText":"大夫三月而葬，五月而卒哭；","chunks":[["大夫三月而葬，五月而卒哭；","zh-Hant"]]},{"id":"li-ji_ch-21_p-55_s-3","passageId":"li-ji_ch-21_p-55","order":3,"canonicalText":"諸侯五月而葬，七月而卒哭。","chunks":[["諸侯五月而葬，七月而卒哭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-55_s-4","passageId":"li-ji_ch-21_p-55","order":4,"canonicalText":"士三虞，大夫五，諸侯七。","chunks":[["士三虞，大夫五，諸侯七。","zh-Hant"]]},{"id":"li-ji_ch-21_p-56_s-1","passageId":"li-ji_ch-21_p-56","order":1,"canonicalText":"諸侯使人吊，其次：含襚賵臨，皆同日而畢事者也，其次如此也。","chunks":[["諸侯使人吊，其次：含襚賵臨，皆同日而畢事者也，其次如此也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-57_s-1","passageId":"li-ji_ch-21_p-57","order":1,"canonicalText":"卿大夫疾，君問之無算；","chunks":[["卿大夫疾，君問之無算；","zh-Hant"]]},{"id":"li-ji_ch-21_p-57_s-2","passageId":"li-ji_ch-21_p-57","order":2,"canonicalText":"士一問之。","chunks":[["士一問之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-57_s-3","passageId":"li-ji_ch-21_p-57","order":3,"canonicalText":"君於卿大夫，比葬不食肉，比卒哭不舉樂；","chunks":[["君於卿大夫，比葬不食肉，比卒哭不舉樂；","zh-Hant"]]},{"id":"li-ji_ch-21_p-57_s-4","passageId":"li-ji_ch-21_p-57","order":4,"canonicalText":"為士，比殯不舉樂。","chunks":[["為士，比殯不舉樂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-58_s-1","passageId":"li-ji_ch-21_p-58","order":1,"canonicalText":"升正柩，諸侯執綍五百人，四綍，皆銜枚，司馬執鐸，左八人，右八人，匠人執羽葆御柩。","chunks":[["升正柩，諸侯執綍五百人，四綍，皆銜枚，司馬執鐸，左八人，右八人，匠人執羽葆御柩。","zh-Hant"]]},{"id":"li-ji_ch-21_p-58_s-2","passageId":"li-ji_ch-21_p-58","order":2,"canonicalText":"大夫之喪，其升正柩也，執引者三百人，執鐸者左右各四人，御柩以茅。","chunks":[["大夫之喪，其升正柩也，執引者三百人，執鐸者左右各四人，御柩以茅。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-1","passageId":"li-ji_ch-21_p-59","order":1,"canonicalText":"孔子曰：「管仲鏤簋而朱紘，旅樹而反坫，山節而藻梲。","chunks":[["孔子曰：「管仲鏤簋而朱紘，旅樹而反坫，山節而藻梲。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-2","passageId":"li-ji_ch-21_p-59","order":2,"canonicalText":"賢大夫也，而難為上也。","chunks":[["賢大夫也，而難為上也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-3","passageId":"li-ji_ch-21_p-59","order":3,"canonicalText":"晏平仲祀其先人。","chunks":[["晏平仲祀其先人。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-4","passageId":"li-ji_ch-21_p-59","order":4,"canonicalText":"豚肩不掩豆。","chunks":[["豚肩不掩豆。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-5","passageId":"li-ji_ch-21_p-59","order":5,"canonicalText":"賢大夫也，而難為下也。","chunks":[["賢大夫也，而難為下也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-6","passageId":"li-ji_ch-21_p-59","order":6,"canonicalText":"君子上不僭上，下不偪下。","chunks":[["君子上不僭上，下不偪下。","zh-Hant"]]},{"id":"li-ji_ch-21_p-59_s-7","passageId":"li-ji_ch-21_p-59","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-60_s-1","passageId":"li-ji_ch-21_p-60","order":1,"canonicalText":"婦人非三年之喪，不逾封而吊。","chunks":[["婦人非三年之喪，不逾封而吊。","zh-Hant"]]},{"id":"li-ji_ch-21_p-60_s-2","passageId":"li-ji_ch-21_p-60","order":2,"canonicalText":"如三年之喪，則君夫人歸。","chunks":[["如三年之喪，則君夫人歸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-60_s-3","passageId":"li-ji_ch-21_p-60","order":3,"canonicalText":"夫人其歸也以諸侯之吊禮，其待之也若待諸侯然。","chunks":[["夫人其歸也以諸侯之吊禮，其待之也若待諸侯然。","zh-Hant"]]},{"id":"li-ji_ch-21_p-60_s-4","passageId":"li-ji_ch-21_p-60","order":4,"canonicalText":"夫人至，入自闈門，升自側階，君在阼。","chunks":[["夫人至，入自闈門，升自側階，君在阼。","zh-Hant"]]},{"id":"li-ji_ch-21_p-60_s-5","passageId":"li-ji_ch-21_p-60","order":5,"canonicalText":"其他如奔喪禮然。","chunks":[["其他如奔喪禮然。","zh-Hant"]]},{"id":"li-ji_ch-21_p-61_s-1","passageId":"li-ji_ch-21_p-61","order":1,"canonicalText":"嫂不撫叔，叔不撫嫂。","chunks":[["嫂不撫叔，叔不撫嫂。","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-1","passageId":"li-ji_ch-21_p-62","order":1,"canonicalText":"君子有三患：未之聞，患弗得聞也；","chunks":[["君子有三患：未之聞，患弗得聞也；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-2","passageId":"li-ji_ch-21_p-62","order":2,"canonicalText":"既聞之，患弗得學也；","chunks":[["既聞之，患弗得學也；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-3","passageId":"li-ji_ch-21_p-62","order":3,"canonicalText":"既學之，患弗能行也。","chunks":[["既學之，患弗能行也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-4","passageId":"li-ji_ch-21_p-62","order":4,"canonicalText":"君子有五恥：居其位，無其言，君子恥之；","chunks":[["君子有五恥：居其位，無其言，君子恥之；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-5","passageId":"li-ji_ch-21_p-62","order":5,"canonicalText":"有其言，無其行，君子恥之；","chunks":[["有其言，無其行，君子恥之；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-6","passageId":"li-ji_ch-21_p-62","order":6,"canonicalText":"既得之而又失之，君子恥之；","chunks":[["既得之而又失之，君子恥之；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-7","passageId":"li-ji_ch-21_p-62","order":7,"canonicalText":"地有餘而民不足，君子恥之；","chunks":[["地有餘而民不足，君子恥之；","zh-Hant"]]},{"id":"li-ji_ch-21_p-62_s-8","passageId":"li-ji_ch-21_p-62","order":8,"canonicalText":"眾寡均而倍焉，君子恥之。","chunks":[["眾寡均而倍焉，君子恥之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-63_s-1","passageId":"li-ji_ch-21_p-63","order":1,"canonicalText":"孔子曰：「凶年則乘駑馬。","chunks":[["孔子曰：「凶年則乘駑馬。","zh-Hant"]]},{"id":"li-ji_ch-21_p-63_s-2","passageId":"li-ji_ch-21_p-63","order":2,"canonicalText":"祀以下牲。","chunks":[["祀以下牲。","zh-Hant"]]},{"id":"li-ji_ch-21_p-63_s-3","passageId":"li-ji_ch-21_p-63","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-64_s-1","passageId":"li-ji_ch-21_p-64","order":1,"canonicalText":"恤由之喪，哀公使孺悲之孔子學士喪禮，士喪禮於是乎書。","chunks":[["恤由之喪，哀公使孺悲之孔子學士喪禮，士喪禮於是乎書。","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-1","passageId":"li-ji_ch-21_p-65","order":1,"canonicalText":"子貢觀於蜡。","chunks":[["子貢觀於蜡。","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-2","passageId":"li-ji_ch-21_p-65","order":2,"canonicalText":"孔子曰：「賜也樂乎？","chunks":[["孔子曰：「賜也樂乎？","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-3","passageId":"li-ji_ch-21_p-65","order":3,"canonicalText":"」對曰：「一國之人皆若狂，賜未知其樂也！","chunks":[["」對曰：「一國之人皆若狂，賜未知其樂也！","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-4","passageId":"li-ji_ch-21_p-65","order":4,"canonicalText":"」子曰：「百日之蜡，一日之澤，非爾所知也。","chunks":[["」子曰：「百日之蜡，一日之澤，非爾所知也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-5","passageId":"li-ji_ch-21_p-65","order":5,"canonicalText":"張而不弛，文武弗能也；","chunks":[["張而不弛，文武弗能也；","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-6","passageId":"li-ji_ch-21_p-65","order":6,"canonicalText":"弛而不張，文武弗為也。","chunks":[["弛而不張，文武弗為也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-7","passageId":"li-ji_ch-21_p-65","order":7,"canonicalText":"一張一弛，文武之道也。","chunks":[["一張一弛，文武之道也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-65_s-8","passageId":"li-ji_ch-21_p-65","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-66_s-1","passageId":"li-ji_ch-21_p-66","order":1,"canonicalText":"孟獻子曰：「正月日至，可以有事於上帝；","chunks":[["孟獻子曰：「正月日至，可以有事於上帝；","zh-Hant"]]},{"id":"li-ji_ch-21_p-66_s-2","passageId":"li-ji_ch-21_p-66","order":2,"canonicalText":"七月日至，可有事於祖。","chunks":[["七月日至，可有事於祖。","zh-Hant"]]},{"id":"li-ji_ch-21_p-66_s-3","passageId":"li-ji_ch-21_p-66","order":3,"canonicalText":"」七月而禘，獻子為之也。","chunks":[["」七月而禘，獻子為之也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-67_s-1","passageId":"li-ji_ch-21_p-67","order":1,"canonicalText":"夫人之不命於天子，自魯昭公始也。","chunks":[["夫人之不命於天子，自魯昭公始也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-68_s-1","passageId":"li-ji_ch-21_p-68","order":1,"canonicalText":"外宗為君夫人，猶內宗也。","chunks":[["外宗為君夫人，猶內宗也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-69_s-1","passageId":"li-ji_ch-21_p-69","order":1,"canonicalText":"廄焚，孔子拜鄉人為火來者。","chunks":[["廄焚，孔子拜鄉人為火來者。","zh-Hant"]]},{"id":"li-ji_ch-21_p-69_s-2","passageId":"li-ji_ch-21_p-69","order":2,"canonicalText":"拜之，士壹，大夫再。","chunks":[["拜之，士壹，大夫再。","zh-Hant"]]},{"id":"li-ji_ch-21_p-69_s-3","passageId":"li-ji_ch-21_p-69","order":3,"canonicalText":"亦相吊之道也。","chunks":[["亦相吊之道也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-70_s-1","passageId":"li-ji_ch-21_p-70","order":1,"canonicalText":"孔子曰：「管仲遇盜，取二人焉，上以為公臣，曰：『其所與游辟也，可人也！","chunks":[["孔子曰：「管仲遇盜，取二人焉，上以為公臣，曰：『其所與游辟也，可人也！","zh-Hant"]]},{"id":"li-ji_ch-21_p-70_s-2","passageId":"li-ji_ch-21_p-70","order":2,"canonicalText":"』管仲死，桓公使為之服。","chunks":[["』管仲死，桓公使為之服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-70_s-3","passageId":"li-ji_ch-21_p-70","order":3,"canonicalText":"宦於大夫者之為之服也，自管仲始也，有君命焉爾也。","chunks":[["宦於大夫者之為之服也，自管仲始也，有君命焉爾也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-70_s-4","passageId":"li-ji_ch-21_p-70","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-71_s-1","passageId":"li-ji_ch-21_p-71","order":1,"canonicalText":"過而舉君之諱，則起。","chunks":[["過而舉君之諱，則起。","zh-Hant"]]},{"id":"li-ji_ch-21_p-71_s-2","passageId":"li-ji_ch-21_p-71","order":2,"canonicalText":"與君之諱同，則稱字。","chunks":[["與君之諱同，則稱字。","zh-Hant"]]},{"id":"li-ji_ch-21_p-72_s-1","passageId":"li-ji_ch-21_p-72","order":1,"canonicalText":"內亂不與焉，外患弗辟也。","chunks":[["內亂不與焉，外患弗辟也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-73_s-1","passageId":"li-ji_ch-21_p-73","order":1,"canonicalText":"贊，大行曰圭。","chunks":[["贊，大行曰圭。","zh-Hant"]]},{"id":"li-ji_ch-21_p-73_s-2","passageId":"li-ji_ch-21_p-73","order":2,"canonicalText":"公九寸，侯、伯七寸，子、男五寸。","chunks":[["公九寸，侯、伯七寸，子、男五寸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-73_s-3","passageId":"li-ji_ch-21_p-73","order":3,"canonicalText":"博三寸，厚半寸。","chunks":[["博三寸，厚半寸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-73_s-4","passageId":"li-ji_ch-21_p-73","order":4,"canonicalText":"剡上，左右各寸半，玉也。","chunks":[["剡上，左右各寸半，玉也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-73_s-5","passageId":"li-ji_ch-21_p-73","order":5,"canonicalText":"藻三采六等。","chunks":[["藻三采六等。","zh-Hant"]]},{"id":"li-ji_ch-21_p-74_s-1","passageId":"li-ji_ch-21_p-74","order":1,"canonicalText":"哀公問子羔曰：「子之食奚當？","chunks":[["哀公問子羔曰：「子之食奚當？","zh-Hant"]]},{"id":"li-ji_ch-21_p-74_s-2","passageId":"li-ji_ch-21_p-74","order":2,"canonicalText":"」對曰：「文公之下執事也。","chunks":[["」對曰：「文公之下執事也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-74_s-3","passageId":"li-ji_ch-21_p-74","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-1","passageId":"li-ji_ch-21_p-75","order":1,"canonicalText":"成廟則釁之。","chunks":[["成廟則釁之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-2","passageId":"li-ji_ch-21_p-75","order":2,"canonicalText":"其禮：祝、宗人、宰夫、雍人，皆爵弁純衣。","chunks":[["其禮：祝、宗人、宰夫、雍人，皆爵弁純衣。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-3","passageId":"li-ji_ch-21_p-75","order":3,"canonicalText":"雍人拭羊，宗人視之，宰夫北面於碑南，東上。","chunks":[["雍人拭羊，宗人視之，宰夫北面於碑南，東上。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-4","passageId":"li-ji_ch-21_p-75","order":4,"canonicalText":"雍人舉羊，升屋自中，中屋南面，刲羊，血流於前，乃降。","chunks":[["雍人舉羊，升屋自中，中屋南面，刲羊，血流於前，乃降。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-5","passageId":"li-ji_ch-21_p-75","order":5,"canonicalText":"門、夾室皆用雞。","chunks":[["門、夾室皆用雞。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-6","passageId":"li-ji_ch-21_p-75","order":6,"canonicalText":"先門而後夾室。","chunks":[["先門而後夾室。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-7","passageId":"li-ji_ch-21_p-75","order":7,"canonicalText":"其衈皆於屋下。","chunks":[["其衈皆於屋下。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-8","passageId":"li-ji_ch-21_p-75","order":8,"canonicalText":"割雞，門當門，夾室中室。","chunks":[["割雞，門當門，夾室中室。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-9","passageId":"li-ji_ch-21_p-75","order":9,"canonicalText":"有司皆鄉室而立，門則有司當門北面。","chunks":[["有司皆鄉室而立，門則有司當門北面。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-10","passageId":"li-ji_ch-21_p-75","order":10,"canonicalText":"既事，宗人告事畢，乃皆退。","chunks":[["既事，宗人告事畢，乃皆退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-11","passageId":"li-ji_ch-21_p-75","order":11,"canonicalText":"反命於君曰：「釁某廟事畢。","chunks":[["反命於君曰：「釁某廟事畢。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-12","passageId":"li-ji_ch-21_p-75","order":12,"canonicalText":"」反命於寢，君南鄉于門內朝服。","chunks":[["」反命於寢，君南鄉于門內朝服。","zh-Hant"]]},{"id":"li-ji_ch-21_p-75_s-13","passageId":"li-ji_ch-21_p-75","order":13,"canonicalText":"既反命，乃退。","chunks":[["既反命，乃退。","zh-Hant"]]},{"id":"li-ji_ch-21_p-76_s-1","passageId":"li-ji_ch-21_p-76","order":1,"canonicalText":"路寢成則考之而不釁。","chunks":[["路寢成則考之而不釁。","zh-Hant"]]},{"id":"li-ji_ch-21_p-76_s-2","passageId":"li-ji_ch-21_p-76","order":2,"canonicalText":"釁屋者，交神明之道也。","chunks":[["釁屋者，交神明之道也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-76_s-3","passageId":"li-ji_ch-21_p-76","order":3,"canonicalText":"凡宗廟之器。","chunks":[["凡宗廟之器。","zh-Hant"]]},{"id":"li-ji_ch-21_p-76_s-4","passageId":"li-ji_ch-21_p-76","order":4,"canonicalText":"其名者成則釁之以豭豚。","chunks":[["其名者成則釁之以豭豚。","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-1","passageId":"li-ji_ch-21_p-77","order":1,"canonicalText":"諸侯出夫人，夫人比至於其國，以夫人之禮行；","chunks":[["諸侯出夫人，夫人比至於其國，以夫人之禮行；","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-2","passageId":"li-ji_ch-21_p-77","order":2,"canonicalText":"至，以夫人入。","chunks":[["至，以夫人入。","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-3","passageId":"li-ji_ch-21_p-77","order":3,"canonicalText":"使者將命曰：「寡君不敏，不能從而事社稷宗廟，使使臣某，敢告於執事。","chunks":[["使者將命曰：「寡君不敏，不能從而事社稷宗廟，使使臣某，敢告於執事。","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-4","passageId":"li-ji_ch-21_p-77","order":4,"canonicalText":"」主人對曰：「寡君固前辭不教矣，寡君敢不敬須以俟命。","chunks":[["」主人對曰：「寡君固前辭不教矣，寡君敢不敬須以俟命。","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-5","passageId":"li-ji_ch-21_p-77","order":5,"canonicalText":"」有司官陳器皿；","chunks":[["」有司官陳器皿；","zh-Hant"]]},{"id":"li-ji_ch-21_p-77_s-6","passageId":"li-ji_ch-21_p-77","order":6,"canonicalText":"主人有司亦官受之。","chunks":[["主人有司亦官受之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-1","passageId":"li-ji_ch-21_p-78","order":1,"canonicalText":"妻出，夫使人致之曰：「某不敏，不能從而共粢盛，使某也敢告於侍者。","chunks":[["妻出，夫使人致之曰：「某不敏，不能從而共粢盛，使某也敢告於侍者。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-2","passageId":"li-ji_ch-21_p-78","order":2,"canonicalText":"」主人對曰：「某之子不肖，不敢辟誅，敢不敬須以俟命。","chunks":[["」主人對曰：「某之子不肖，不敢辟誅，敢不敬須以俟命。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-3","passageId":"li-ji_ch-21_p-78","order":3,"canonicalText":"」使者退，主人拜送之。","chunks":[["」使者退，主人拜送之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-4","passageId":"li-ji_ch-21_p-78","order":4,"canonicalText":"如舅在，則稱舅；","chunks":[["如舅在，則稱舅；","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-5","passageId":"li-ji_ch-21_p-78","order":5,"canonicalText":"舅沒，則稱兄；","chunks":[["舅沒，則稱兄；","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-6","passageId":"li-ji_ch-21_p-78","order":6,"canonicalText":"無兄，則稱夫。","chunks":[["無兄，則稱夫。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-7","passageId":"li-ji_ch-21_p-78","order":7,"canonicalText":"主人之辭曰：「某之子不肖。","chunks":[["主人之辭曰：「某之子不肖。","zh-Hant"]]},{"id":"li-ji_ch-21_p-78_s-8","passageId":"li-ji_ch-21_p-78","order":8,"canonicalText":"」如姑姊妹，亦皆稱之。","chunks":[["」如姑姊妹，亦皆稱之。","zh-Hant"]]},{"id":"li-ji_ch-21_p-79_s-1","passageId":"li-ji_ch-21_p-79","order":1,"canonicalText":"孔子曰：「吾食於少施氏而飽，少施氏食我以禮。","chunks":[["孔子曰：「吾食於少施氏而飽，少施氏食我以禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-79_s-2","passageId":"li-ji_ch-21_p-79","order":2,"canonicalText":"吾祭，作而辭曰：『疏食不足祭也。","chunks":[["吾祭，作而辭曰：『疏食不足祭也。","zh-Hant"]]},{"id":"li-ji_ch-21_p-79_s-3","passageId":"li-ji_ch-21_p-79","order":3,"canonicalText":"』吾飧，作而辭曰：『疏食也，不敢以傷吾子。","chunks":[["』吾飧，作而辭曰：『疏食也，不敢以傷吾子。","zh-Hant"]]},{"id":"li-ji_ch-21_p-79_s-4","passageId":"li-ji_ch-21_p-79","order":4,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"li-ji_ch-21_p-80_s-1","passageId":"li-ji_ch-21_p-80","order":1,"canonicalText":"納幣一束：束五兩，兩五尋。","chunks":[["納幣一束：束五兩，兩五尋。","zh-Hant"]]},{"id":"li-ji_ch-21_p-81_s-1","passageId":"li-ji_ch-21_p-81","order":1,"canonicalText":"婦見舅姑，兄弟、姑姊妹，皆立於堂下，西面北上，是見已。","chunks":[["婦見舅姑，兄弟、姑姊妹，皆立於堂下，西面北上，是見已。","zh-Hant"]]},{"id":"li-ji_ch-21_p-81_s-2","passageId":"li-ji_ch-21_p-81","order":2,"canonicalText":"見諸父，各就其寢。","chunks":[["見諸父，各就其寢。","zh-Hant"]]},{"id":"li-ji_ch-21_p-82_s-1","passageId":"li-ji_ch-21_p-82","order":1,"canonicalText":"女雖未許嫁，年二十而笄，禮之，婦人執其禮。","chunks":[["女雖未許嫁，年二十而笄，禮之，婦人執其禮。","zh-Hant"]]},{"id":"li-ji_ch-21_p-82_s-2","passageId":"li-ji_ch-21_p-82","order":2,"canonicalText":"燕則鬈首。","chunks":[["燕則鬈首。","zh-Hant"]]},{"id":"li-ji_ch-21_p-83_s-1","passageId":"li-ji_ch-21_p-83","order":1,"canonicalText":"韠：長三尺，下廣二尺，上廣一尺。","chunks":[["韠：長三尺，下廣二尺，上廣一尺。","zh-Hant"]]},{"id":"li-ji_ch-21_p-83_s-2","passageId":"li-ji_ch-21_p-83","order":2,"canonicalText":"會去上五寸，紕以爵韋六寸，不至下五寸。","chunks":[["會去上五寸，紕以爵韋六寸，不至下五寸。","zh-Hant"]]},{"id":"li-ji_ch-21_p-83_s-3","passageId":"li-ji_ch-21_p-83","order":3,"canonicalText":"純以素，紃以五采。","chunks":[["純以素，紃以五采。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-1","passageId":"li-ji_ch-22_p-1","order":1,"canonicalText":"疾病，外內皆掃。","chunks":[["疾病，外內皆掃。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-2","passageId":"li-ji_ch-22_p-1","order":2,"canonicalText":"君大夫徹縣，士去琴瑟。","chunks":[["君大夫徹縣，士去琴瑟。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-3","passageId":"li-ji_ch-22_p-1","order":3,"canonicalText":"寢東首於北牖下。","chunks":[["寢東首於北牖下。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-4","passageId":"li-ji_ch-22_p-1","order":4,"canonicalText":"廢床。","chunks":[["廢床。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-5","passageId":"li-ji_ch-22_p-1","order":5,"canonicalText":"徹褻衣，加新衣，體一人。","chunks":[["徹褻衣，加新衣，體一人。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-6","passageId":"li-ji_ch-22_p-1","order":6,"canonicalText":"男女改服。","chunks":[["男女改服。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-7","passageId":"li-ji_ch-22_p-1","order":7,"canonicalText":"屬纊以俟絕氣。","chunks":[["屬纊以俟絕氣。","zh-Hant"]]},{"id":"li-ji_ch-22_p-1_s-8","passageId":"li-ji_ch-22_p-1","order":8,"canonicalText":"男子不死於婦人之手，婦人不死於男子之手。","chunks":[["男子不死於婦人之手，婦人不死於男子之手。","zh-Hant"]]},{"id":"li-ji_ch-22_p-2_s-1","passageId":"li-ji_ch-22_p-2","order":1,"canonicalText":"君夫人卒於路寢，大夫世婦卒於適寢，內子未命，則死於下室。","chunks":[["君夫人卒於路寢，大夫世婦卒於適寢，內子未命，則死於下室。","zh-Hant"]]},{"id":"li-ji_ch-22_p-2_s-2","passageId":"li-ji_ch-22_p-2","order":2,"canonicalText":"遷尸於寢，士士之妻皆死於寢。","chunks":[["遷尸於寢，士士之妻皆死於寢。","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-1","passageId":"li-ji_ch-22_p-3","order":1,"canonicalText":"復，有林麓，則虞人設階；","chunks":[["復，有林麓，則虞人設階；","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-2","passageId":"li-ji_ch-22_p-3","order":2,"canonicalText":"無林麓，則狄人設階。","chunks":[["無林麓，則狄人設階。","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-3","passageId":"li-ji_ch-22_p-3","order":3,"canonicalText":"小臣復，復者朝服。","chunks":[["小臣復，復者朝服。","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-4","passageId":"li-ji_ch-22_p-3","order":4,"canonicalText":"君以卷，夫人以屈狄；","chunks":[["君以卷，夫人以屈狄；","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-5","passageId":"li-ji_ch-22_p-3","order":5,"canonicalText":"大夫以玄赬，世婦以襢衣；","chunks":[["大夫以玄赬，世婦以襢衣；","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-6","passageId":"li-ji_ch-22_p-3","order":6,"canonicalText":"士以爵弁，士妻以稅衣。","chunks":[["士以爵弁，士妻以稅衣。","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-7","passageId":"li-ji_ch-22_p-3","order":7,"canonicalText":"皆升自東榮，中屋履危，北面三號，卷衣投於前，司命受之，降自西北榮。","chunks":[["皆升自東榮，中屋履危，北面三號，卷衣投於前，司命受之，降自西北榮。","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-8","passageId":"li-ji_ch-22_p-3","order":8,"canonicalText":"其為賓，則公館復，私館不復；","chunks":[["其為賓，則公館復，私館不復；","zh-Hant"]]},{"id":"li-ji_ch-22_p-3_s-9","passageId":"li-ji_ch-22_p-3","order":9,"canonicalText":"其在野，則升其乘車之左轂而復。","chunks":[["其在野，則升其乘車之左轂而復。","zh-Hant"]]},{"id":"li-ji_ch-22_p-4_s-1","passageId":"li-ji_ch-22_p-4","order":1,"canonicalText":"復衣不以衣尸，不以斂。","chunks":[["復衣不以衣尸，不以斂。","zh-Hant"]]},{"id":"li-ji_ch-22_p-4_s-2","passageId":"li-ji_ch-22_p-4","order":2,"canonicalText":"婦人復，不以袡。","chunks":[["婦人復，不以袡。","zh-Hant"]]},{"id":"li-ji_ch-22_p-4_s-3","passageId":"li-ji_ch-22_p-4","order":3,"canonicalText":"凡復，男子稱名，婦人稱字。","chunks":[["凡復，男子稱名，婦人稱字。","zh-Hant"]]},{"id":"li-ji_ch-22_p-4_s-4","passageId":"li-ji_ch-22_p-4","order":4,"canonicalText":"唯哭先復，復而後行死事。","chunks":[["唯哭先復，復而後行死事。","zh-Hant"]]},{"id":"li-ji_ch-22_p-5_s-1","passageId":"li-ji_ch-22_p-5","order":1,"canonicalText":"始卒，主人啼，兄弟哭，婦人哭踴。","chunks":[["始卒，主人啼，兄弟哭，婦人哭踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-6_s-1","passageId":"li-ji_ch-22_p-6","order":1,"canonicalText":"既正尸，子坐於東方，卿大夫父兄子姓立於東方，有司庶士哭於堂下北面；","chunks":[["既正尸，子坐於東方，卿大夫父兄子姓立於東方，有司庶士哭於堂下北面；","zh-Hant"]]},{"id":"li-ji_ch-22_p-6_s-2","passageId":"li-ji_ch-22_p-6","order":2,"canonicalText":"夫人坐於西方，內命婦姑姊妹子姓立於西方，外命婦率外宗哭於堂上北面。","chunks":[["夫人坐於西方，內命婦姑姊妹子姓立於西方，外命婦率外宗哭於堂上北面。","zh-Hant"]]},{"id":"li-ji_ch-22_p-7_s-1","passageId":"li-ji_ch-22_p-7","order":1,"canonicalText":"大夫之喪，主人坐於東方，主婦坐於西方，其有命夫命婦則坐，無則皆立。","chunks":[["大夫之喪，主人坐於東方，主婦坐於西方，其有命夫命婦則坐，無則皆立。","zh-Hant"]]},{"id":"li-ji_ch-22_p-7_s-2","passageId":"li-ji_ch-22_p-7","order":2,"canonicalText":"士之喪，主人父兄子姓皆坐於東方，主婦姑姊妹子姓皆坐於西方。","chunks":[["士之喪，主人父兄子姓皆坐於東方，主婦姑姊妹子姓皆坐於西方。","zh-Hant"]]},{"id":"li-ji_ch-22_p-7_s-3","passageId":"li-ji_ch-22_p-7","order":3,"canonicalText":"凡哭尸於室者，主人二手承衾而哭。","chunks":[["凡哭尸於室者，主人二手承衾而哭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-8_s-1","passageId":"li-ji_ch-22_p-8","order":1,"canonicalText":"君之喪，未小斂，為寄公國賓出；","chunks":[["君之喪，未小斂，為寄公國賓出；","zh-Hant"]]},{"id":"li-ji_ch-22_p-8_s-2","passageId":"li-ji_ch-22_p-8","order":2,"canonicalText":"大夫之喪，未小斂，為君命出；","chunks":[["大夫之喪，未小斂，為君命出；","zh-Hant"]]},{"id":"li-ji_ch-22_p-8_s-3","passageId":"li-ji_ch-22_p-8","order":3,"canonicalText":"士之喪，於大夫不當斂而出。","chunks":[["士之喪，於大夫不當斂而出。","zh-Hant"]]},{"id":"li-ji_ch-22_p-9_s-1","passageId":"li-ji_ch-22_p-9","order":1,"canonicalText":"凡主人之出也，徒跣扱衽拊心，降自西階。","chunks":[["凡主人之出也，徒跣扱衽拊心，降自西階。","zh-Hant"]]},{"id":"li-ji_ch-22_p-9_s-2","passageId":"li-ji_ch-22_p-9","order":2,"canonicalText":"君拜寄公國賓于位；","chunks":[["君拜寄公國賓于位；","zh-Hant"]]},{"id":"li-ji_ch-22_p-9_s-3","passageId":"li-ji_ch-22_p-9","order":3,"canonicalText":"大夫於君命，迎於寢門外，使者升堂致命，主人拜于下；","chunks":[["大夫於君命，迎於寢門外，使者升堂致命，主人拜于下；","zh-Hant"]]},{"id":"li-ji_ch-22_p-9_s-4","passageId":"li-ji_ch-22_p-9","order":4,"canonicalText":"士於大夫親吊則與之哭；","chunks":[["士於大夫親吊則與之哭；","zh-Hant"]]},{"id":"li-ji_ch-22_p-9_s-5","passageId":"li-ji_ch-22_p-9","order":5,"canonicalText":"不逆於門外。","chunks":[["不逆於門外。","zh-Hant"]]},{"id":"li-ji_ch-22_p-10_s-1","passageId":"li-ji_ch-22_p-10","order":1,"canonicalText":"夫人為寄公夫人出，命婦為夫人之命出，士妻不當斂，則為命婦出。","chunks":[["夫人為寄公夫人出，命婦為夫人之命出，士妻不當斂，則為命婦出。","zh-Hant"]]},{"id":"li-ji_ch-22_p-11_s-1","passageId":"li-ji_ch-22_p-11","order":1,"canonicalText":"小斂，主人即位於戶內，主婦東面，乃斂。","chunks":[["小斂，主人即位於戶內，主婦東面，乃斂。","zh-Hant"]]},{"id":"li-ji_ch-22_p-11_s-2","passageId":"li-ji_ch-22_p-11","order":2,"canonicalText":"卒斂，主人馮之踴，主婦亦如之。","chunks":[["卒斂，主人馮之踴，主婦亦如之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-11_s-3","passageId":"li-ji_ch-22_p-11","order":3,"canonicalText":"主人袒說髦，括髮以麻，婦人髽，帶麻於房中。","chunks":[["主人袒說髦，括髮以麻，婦人髽，帶麻於房中。","zh-Hant"]]},{"id":"li-ji_ch-22_p-12_s-1","passageId":"li-ji_ch-22_p-12","order":1,"canonicalText":"徹帷，男女奉尸夷於堂，降拜。","chunks":[["徹帷，男女奉尸夷於堂，降拜。","zh-Hant"]]},{"id":"li-ji_ch-22_p-13_s-1","passageId":"li-ji_ch-22_p-13","order":1,"canonicalText":"君拜寄公國賓，大夫士拜卿大夫於位，於士旁三拜；","chunks":[["君拜寄公國賓，大夫士拜卿大夫於位，於士旁三拜；","zh-Hant"]]},{"id":"li-ji_ch-22_p-13_s-2","passageId":"li-ji_ch-22_p-13","order":2,"canonicalText":"夫人亦拜寄公夫人於堂上，大夫內子士妻特拜，命婦泛拜眾賓於堂上。","chunks":[["夫人亦拜寄公夫人於堂上，大夫內子士妻特拜，命婦泛拜眾賓於堂上。","zh-Hant"]]},{"id":"li-ji_ch-22_p-14_s-1","passageId":"li-ji_ch-22_p-14","order":1,"canonicalText":"主人即位，襲帶絰踴。","chunks":[["主人即位，襲帶絰踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-14_s-2","passageId":"li-ji_ch-22_p-14","order":2,"canonicalText":"母之喪，即位而免，乃奠。","chunks":[["母之喪，即位而免，乃奠。","zh-Hant"]]},{"id":"li-ji_ch-22_p-14_s-3","passageId":"li-ji_ch-22_p-14","order":3,"canonicalText":"吊者襲裘，加武帶絰，與主人拾踴。","chunks":[["吊者襲裘，加武帶絰，與主人拾踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-15_s-1","passageId":"li-ji_ch-22_p-15","order":1,"canonicalText":"君喪，虞人出木角，狄人出壺，雍人出鼎，司馬縣之，乃官代哭，大夫官代哭不縣壺，士代哭不以官。","chunks":[["君喪，虞人出木角，狄人出壺，雍人出鼎，司馬縣之，乃官代哭，大夫官代哭不縣壺，士代哭不以官。","zh-Hant"]]},{"id":"li-ji_ch-22_p-15_s-2","passageId":"li-ji_ch-22_p-15","order":2,"canonicalText":"君堂上二燭、下二燭，大夫堂上一燭、下二燭，士堂上一燭、下一燭。","chunks":[["君堂上二燭、下二燭，大夫堂上一燭、下二燭，士堂上一燭、下一燭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-16_s-1","passageId":"li-ji_ch-22_p-16","order":1,"canonicalText":"賓出徹帷。","chunks":[["賓出徹帷。","zh-Hant"]]},{"id":"li-ji_ch-22_p-17_s-1","passageId":"li-ji_ch-22_p-17","order":1,"canonicalText":"哭尸於堂上，主人在東方，由外來者在西方，諸婦南鄉。","chunks":[["哭尸於堂上，主人在東方，由外來者在西方，諸婦南鄉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-1","passageId":"li-ji_ch-22_p-18","order":1,"canonicalText":"婦人迎客送客不下堂，下堂不哭；","chunks":[["婦人迎客送客不下堂，下堂不哭；","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-2","passageId":"li-ji_ch-22_p-18","order":2,"canonicalText":"男子出寢門見人不哭。","chunks":[["男子出寢門見人不哭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-3","passageId":"li-ji_ch-22_p-18","order":3,"canonicalText":"其無女主，則男主拜女賓於寢門內；","chunks":[["其無女主，則男主拜女賓於寢門內；","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-4","passageId":"li-ji_ch-22_p-18","order":4,"canonicalText":"其無男主，則女主拜男賓於阼階下。","chunks":[["其無男主，則女主拜男賓於阼階下。","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-5","passageId":"li-ji_ch-22_p-18","order":5,"canonicalText":"子幼，則以衰抱之，人為之拜；","chunks":[["子幼，則以衰抱之，人為之拜；","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-6","passageId":"li-ji_ch-22_p-18","order":6,"canonicalText":"為後者不在，則有爵者辭，無爵者人為之拜。","chunks":[["為後者不在，則有爵者辭，無爵者人為之拜。","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-7","passageId":"li-ji_ch-22_p-18","order":7,"canonicalText":"在竟內則俟之，在竟外則殯葬可也。","chunks":[["在竟內則俟之，在竟外則殯葬可也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-18_s-8","passageId":"li-ji_ch-22_p-18","order":8,"canonicalText":"喪有無後，無無主。","chunks":[["喪有無後，無無主。","zh-Hant"]]},{"id":"li-ji_ch-22_p-19_s-1","passageId":"li-ji_ch-22_p-19","order":1,"canonicalText":"君之喪：三日，子、夫人杖，五日既殯，授大夫世婦杖。","chunks":[["君之喪：三日，子、夫人杖，五日既殯，授大夫世婦杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-19_s-2","passageId":"li-ji_ch-22_p-19","order":2,"canonicalText":"子、大夫寢門之外杖，寢門之內輯之；","chunks":[["子、大夫寢門之外杖，寢門之內輯之；","zh-Hant"]]},{"id":"li-ji_ch-22_p-19_s-3","passageId":"li-ji_ch-22_p-19","order":3,"canonicalText":"夫人世婦在其次則杖，即位則使人執之。","chunks":[["夫人世婦在其次則杖，即位則使人執之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-19_s-4","passageId":"li-ji_ch-22_p-19","order":4,"canonicalText":"子有王命則去杖，國君之命則輯杖，聽卜有事於尸則去杖。","chunks":[["子有王命則去杖，國君之命則輯杖，聽卜有事於尸則去杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-19_s-5","passageId":"li-ji_ch-22_p-19","order":5,"canonicalText":"大夫於君所則輯杖，於大夫所則杖。","chunks":[["大夫於君所則輯杖，於大夫所則杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-20_s-1","passageId":"li-ji_ch-22_p-20","order":1,"canonicalText":"大夫之喪：三日之朝既殯，主人主婦室老皆杖。","chunks":[["大夫之喪：三日之朝既殯，主人主婦室老皆杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-20_s-2","passageId":"li-ji_ch-22_p-20","order":2,"canonicalText":"大夫有君命則去杖，大夫之命則輯杖；","chunks":[["大夫有君命則去杖，大夫之命則輯杖；","zh-Hant"]]},{"id":"li-ji_ch-22_p-20_s-3","passageId":"li-ji_ch-22_p-20","order":3,"canonicalText":"內子為夫人之命去杖，為世婦之命授人杖。","chunks":[["內子為夫人之命去杖，為世婦之命授人杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-21_s-1","passageId":"li-ji_ch-22_p-21","order":1,"canonicalText":"士之喪：二日而殯，三日而朝，主人杖，婦人皆杖。","chunks":[["士之喪：二日而殯，三日而朝，主人杖，婦人皆杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-21_s-2","passageId":"li-ji_ch-22_p-21","order":2,"canonicalText":"於君命夫人之命如大夫，於大夫世婦之命如大夫。","chunks":[["於君命夫人之命如大夫，於大夫世婦之命如大夫。","zh-Hant"]]},{"id":"li-ji_ch-22_p-22_s-1","passageId":"li-ji_ch-22_p-22","order":1,"canonicalText":"子皆杖，不以即位。","chunks":[["子皆杖，不以即位。","zh-Hant"]]},{"id":"li-ji_ch-22_p-22_s-2","passageId":"li-ji_ch-22_p-22","order":2,"canonicalText":"大夫士哭殯則杖，哭柩則輯杖。","chunks":[["大夫士哭殯則杖，哭柩則輯杖。","zh-Hant"]]},{"id":"li-ji_ch-22_p-22_s-3","passageId":"li-ji_ch-22_p-22","order":3,"canonicalText":"棄杖者，斷而棄之於隱者。","chunks":[["棄杖者，斷而棄之於隱者。","zh-Hant"]]},{"id":"li-ji_ch-22_p-23_s-1","passageId":"li-ji_ch-22_p-23","order":1,"canonicalText":"始死，遷尸於床，幠用斂衾，去死衣，小臣楔齒用角柶，綴足用燕几，君大夫士一也。","chunks":[["始死，遷尸於床，幠用斂衾，去死衣，小臣楔齒用角柶，綴足用燕几，君大夫士一也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-24_s-1","passageId":"li-ji_ch-22_p-24","order":1,"canonicalText":"管人汲，不說繘、屈之，盡階不升堂，授御者；","chunks":[["管人汲，不說繘、屈之，盡階不升堂，授御者；","zh-Hant"]]},{"id":"li-ji_ch-22_p-24_s-2","passageId":"li-ji_ch-22_p-24","order":2,"canonicalText":"御者入浴：小臣四人抗衾，御者二人浴，浴水用盆，沃水用枓，浴用絺巾，挋用浴衣，如它日；","chunks":[["御者入浴：小臣四人抗衾，御者二人浴，浴水用盆，沃水用枓，浴用絺巾，挋用浴衣，如它日；","zh-Hant"]]},{"id":"li-ji_ch-22_p-24_s-3","passageId":"li-ji_ch-22_p-24","order":3,"canonicalText":"小臣爪足，浴餘水棄于坎。","chunks":[["小臣爪足，浴餘水棄于坎。","zh-Hant"]]},{"id":"li-ji_ch-22_p-24_s-4","passageId":"li-ji_ch-22_p-24","order":4,"canonicalText":"其母之喪，則內御者抗衾而浴。","chunks":[["其母之喪，則內御者抗衾而浴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-25_s-1","passageId":"li-ji_ch-22_p-25","order":1,"canonicalText":"管人汲，授御者，御者差沐於堂上－─君沐粱，大夫沐稷，士沐粱。","chunks":[["管人汲，授御者，御者差沐於堂上－─君沐粱，大夫沐稷，士沐粱。","zh-Hant"]]},{"id":"li-ji_ch-22_p-25_s-2","passageId":"li-ji_ch-22_p-25","order":2,"canonicalText":"甸人為垼於西墻下，陶人出重鬲，管人受沐，乃煮之，甸人取所徹廟之西北厞薪，用爨之。","chunks":[["甸人為垼於西墻下，陶人出重鬲，管人受沐，乃煮之，甸人取所徹廟之西北厞薪，用爨之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-25_s-3","passageId":"li-ji_ch-22_p-25","order":3,"canonicalText":"管人授御者沐，乃沐；","chunks":[["管人授御者沐，乃沐；","zh-Hant"]]},{"id":"li-ji_ch-22_p-25_s-4","passageId":"li-ji_ch-22_p-25","order":4,"canonicalText":"沐用瓦盤，挋用巾，如它日，小臣爪手翦須，濡濯棄於坎。","chunks":[["沐用瓦盤，挋用巾，如它日，小臣爪手翦須，濡濯棄於坎。","zh-Hant"]]},{"id":"li-ji_ch-22_p-26_s-1","passageId":"li-ji_ch-22_p-26","order":1,"canonicalText":"君設大盤造冰焉，大夫設夷盤造冰焉，士并瓦盤無冰，設床襢笫，有枕。","chunks":[["君設大盤造冰焉，大夫設夷盤造冰焉，士并瓦盤無冰，設床襢笫，有枕。","zh-Hant"]]},{"id":"li-ji_ch-22_p-26_s-2","passageId":"li-ji_ch-22_p-26","order":2,"canonicalText":"含一床，襲一床遷尸於堂又一床，皆有枕席－─君大夫士一也。","chunks":[["含一床，襲一床遷尸於堂又一床，皆有枕席－─君大夫士一也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-27_s-1","passageId":"li-ji_ch-22_p-27","order":1,"canonicalText":"君之喪，子、大夫、公子、眾士皆三日不食。","chunks":[["君之喪，子、大夫、公子、眾士皆三日不食。","zh-Hant"]]},{"id":"li-ji_ch-22_p-27_s-2","passageId":"li-ji_ch-22_p-27","order":2,"canonicalText":"子、大夫、公子食粥，納財，朝一溢米，莫一溢米，食之無算；","chunks":[["子、大夫、公子食粥，納財，朝一溢米，莫一溢米，食之無算；","zh-Hant"]]},{"id":"li-ji_ch-22_p-27_s-3","passageId":"li-ji_ch-22_p-27","order":3,"canonicalText":"士疏食水飲，食之無算；","chunks":[["士疏食水飲，食之無算；","zh-Hant"]]},{"id":"li-ji_ch-22_p-27_s-4","passageId":"li-ji_ch-22_p-27","order":4,"canonicalText":"夫人世婦諸妻皆疏食水飲，食之無算。","chunks":[["夫人世婦諸妻皆疏食水飲，食之無算。","zh-Hant"]]},{"id":"li-ji_ch-22_p-28_s-1","passageId":"li-ji_ch-22_p-28","order":1,"canonicalText":"大夫之喪，主人室老子姓皆食粥；","chunks":[["大夫之喪，主人室老子姓皆食粥；","zh-Hant"]]},{"id":"li-ji_ch-22_p-28_s-2","passageId":"li-ji_ch-22_p-28","order":2,"canonicalText":"眾士疏食水飲；","chunks":[["眾士疏食水飲；","zh-Hant"]]},{"id":"li-ji_ch-22_p-28_s-3","passageId":"li-ji_ch-22_p-28","order":3,"canonicalText":"妻妾疏食水飲。","chunks":[["妻妾疏食水飲。","zh-Hant"]]},{"id":"li-ji_ch-22_p-28_s-4","passageId":"li-ji_ch-22_p-28","order":4,"canonicalText":"士亦如之。","chunks":[["士亦如之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-1","passageId":"li-ji_ch-22_p-29","order":1,"canonicalText":"既葬，主人疏食水飲，不食菜果；","chunks":[["既葬，主人疏食水飲，不食菜果；","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-2","passageId":"li-ji_ch-22_p-29","order":2,"canonicalText":"婦人亦如之。","chunks":[["婦人亦如之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-3","passageId":"li-ji_ch-22_p-29","order":3,"canonicalText":"君大夫士一也。","chunks":[["君大夫士一也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-4","passageId":"li-ji_ch-22_p-29","order":4,"canonicalText":"練而食菜果，祥而食肉。","chunks":[["練而食菜果，祥而食肉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-5","passageId":"li-ji_ch-22_p-29","order":5,"canonicalText":"食粥於盛不盥，食於篹者盥。","chunks":[["食粥於盛不盥，食於篹者盥。","zh-Hant"]]},{"id":"li-ji_ch-22_p-29_s-6","passageId":"li-ji_ch-22_p-29","order":6,"canonicalText":"食菜以醯醬，始食肉者先食乾肉，始飲酒者先飲醴酒。","chunks":[["食菜以醯醬，始食肉者先食乾肉，始飲酒者先飲醴酒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-30_s-1","passageId":"li-ji_ch-22_p-30","order":1,"canonicalText":"期之喪，三不食；","chunks":[["期之喪，三不食；","zh-Hant"]]},{"id":"li-ji_ch-22_p-30_s-2","passageId":"li-ji_ch-22_p-30","order":2,"canonicalText":"食：疏食水飲，不食菜果，三月既葬，食肉飲酒。","chunks":[["食：疏食水飲，不食菜果，三月既葬，食肉飲酒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-30_s-3","passageId":"li-ji_ch-22_p-30","order":3,"canonicalText":"期終喪，不食肉，不飲酒，父在為母，為妻。","chunks":[["期終喪，不食肉，不飲酒，父在為母，為妻。","zh-Hant"]]},{"id":"li-ji_ch-22_p-30_s-4","passageId":"li-ji_ch-22_p-30","order":4,"canonicalText":"九月之喪，食飲猶期之喪也，食肉飲酒，不與人樂之。","chunks":[["九月之喪，食飲猶期之喪也，食肉飲酒，不與人樂之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-1","passageId":"li-ji_ch-22_p-31","order":1,"canonicalText":"五月三月之喪，壹不食再不食可也。","chunks":[["五月三月之喪，壹不食再不食可也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-2","passageId":"li-ji_ch-22_p-31","order":2,"canonicalText":"比葬，食肉飲酒，不與人樂之。","chunks":[["比葬，食肉飲酒，不與人樂之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-3","passageId":"li-ji_ch-22_p-31","order":3,"canonicalText":"叔母、世母、故主、宗子食肉飲酒。","chunks":[["叔母、世母、故主、宗子食肉飲酒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-4","passageId":"li-ji_ch-22_p-31","order":4,"canonicalText":"不能食粥，羹之以菜可也；","chunks":[["不能食粥，羹之以菜可也；","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-5","passageId":"li-ji_ch-22_p-31","order":5,"canonicalText":"有疾，食肉飲酒可也。","chunks":[["有疾，食肉飲酒可也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-31_s-6","passageId":"li-ji_ch-22_p-31","order":6,"canonicalText":"五十不成喪，七十唯衰麻在身。","chunks":[["五十不成喪，七十唯衰麻在身。","zh-Hant"]]},{"id":"li-ji_ch-22_p-32_s-1","passageId":"li-ji_ch-22_p-32","order":1,"canonicalText":"既葬，若君食之則食之；","chunks":[["既葬，若君食之則食之；","zh-Hant"]]},{"id":"li-ji_ch-22_p-32_s-2","passageId":"li-ji_ch-22_p-32","order":2,"canonicalText":"大夫父之友食之則食之矣。","chunks":[["大夫父之友食之則食之矣。","zh-Hant"]]},{"id":"li-ji_ch-22_p-32_s-3","passageId":"li-ji_ch-22_p-32","order":3,"canonicalText":"不辟粱肉，若有酒醴則辭。","chunks":[["不辟粱肉，若有酒醴則辭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-1","passageId":"li-ji_ch-22_p-33","order":1,"canonicalText":"小斂於戶內，大斂於阼。","chunks":[["小斂於戶內，大斂於阼。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-2","passageId":"li-ji_ch-22_p-33","order":2,"canonicalText":"君以簟席，大夫以蒲席，士以葦席。","chunks":[["君以簟席，大夫以蒲席，士以葦席。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-3","passageId":"li-ji_ch-22_p-33","order":3,"canonicalText":"小斂：布絞，縮者一，橫者三。","chunks":[["小斂：布絞，縮者一，橫者三。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-4","passageId":"li-ji_ch-22_p-33","order":4,"canonicalText":"君錦衾，大夫縞衾，士緇衾，皆一。","chunks":[["君錦衾，大夫縞衾，士緇衾，皆一。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-5","passageId":"li-ji_ch-22_p-33","order":5,"canonicalText":"衣十有九稱，君陳衣于序東；","chunks":[["衣十有九稱，君陳衣于序東；","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-6","passageId":"li-ji_ch-22_p-33","order":6,"canonicalText":"大夫士陳衣于房中；","chunks":[["大夫士陳衣于房中；","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-7","passageId":"li-ji_ch-22_p-33","order":7,"canonicalText":"皆西領北上。","chunks":[["皆西領北上。","zh-Hant"]]},{"id":"li-ji_ch-22_p-33_s-8","passageId":"li-ji_ch-22_p-33","order":8,"canonicalText":"絞紟不在列。","chunks":[["絞紟不在列。","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-1","passageId":"li-ji_ch-22_p-34","order":1,"canonicalText":"大斂：布絞，縮者三，橫者五，布紟二衾。","chunks":[["大斂：布絞，縮者三，橫者五，布紟二衾。","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-2","passageId":"li-ji_ch-22_p-34","order":2,"canonicalText":"君大夫士一也。","chunks":[["君大夫士一也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-3","passageId":"li-ji_ch-22_p-34","order":3,"canonicalText":"君陳衣于庭，百稱，北領西上；","chunks":[["君陳衣于庭，百稱，北領西上；","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-4","passageId":"li-ji_ch-22_p-34","order":4,"canonicalText":"大夫陳衣于序東，五十稱，西領南上；","chunks":[["大夫陳衣于序東，五十稱，西領南上；","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-5","passageId":"li-ji_ch-22_p-34","order":5,"canonicalText":"士陳衣于序東，三十稱，西領南上。","chunks":[["士陳衣于序東，三十稱，西領南上。","zh-Hant"]]},{"id":"li-ji_ch-22_p-34_s-6","passageId":"li-ji_ch-22_p-34","order":6,"canonicalText":"絞紟如朝服，絞一幅為三、不辟，紟五幅、無紞。","chunks":[["絞紟如朝服，絞一幅為三、不辟，紟五幅、無紞。","zh-Hant"]]},{"id":"li-ji_ch-22_p-35_s-1","passageId":"li-ji_ch-22_p-35","order":1,"canonicalText":"小斂之衣，祭服不倒。","chunks":[["小斂之衣，祭服不倒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-35_s-2","passageId":"li-ji_ch-22_p-35","order":2,"canonicalText":"君無襚，大夫士畢主人之祭服；","chunks":[["君無襚，大夫士畢主人之祭服；","zh-Hant"]]},{"id":"li-ji_ch-22_p-35_s-3","passageId":"li-ji_ch-22_p-35","order":3,"canonicalText":"親戚之衣，受之不以即陳。","chunks":[["親戚之衣，受之不以即陳。","zh-Hant"]]},{"id":"li-ji_ch-22_p-35_s-4","passageId":"li-ji_ch-22_p-35","order":4,"canonicalText":"小斂，君大夫士皆用復衣復衾；","chunks":[["小斂，君大夫士皆用復衣復衾；","zh-Hant"]]},{"id":"li-ji_ch-22_p-35_s-5","passageId":"li-ji_ch-22_p-35","order":5,"canonicalText":"大斂，君大夫士祭服無算，君褶衣褶衾，大夫士猶小斂也。","chunks":[["大斂，君大夫士祭服無算，君褶衣褶衾，大夫士猶小斂也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-36_s-1","passageId":"li-ji_ch-22_p-36","order":1,"canonicalText":"袍必有表，不禪，衣必有裳，謂之一稱。","chunks":[["袍必有表，不禪，衣必有裳，謂之一稱。","zh-Hant"]]},{"id":"li-ji_ch-22_p-37_s-1","passageId":"li-ji_ch-22_p-37","order":1,"canonicalText":"凡陳衣者實之篋，取衣者亦以篋升，降者自西階。","chunks":[["凡陳衣者實之篋，取衣者亦以篋升，降者自西階。","zh-Hant"]]},{"id":"li-ji_ch-22_p-37_s-2","passageId":"li-ji_ch-22_p-37","order":2,"canonicalText":"凡陳衣、不詘，非列采不入，絺綌紵不入。","chunks":[["凡陳衣、不詘，非列采不入，絺綌紵不入。","zh-Hant"]]},{"id":"li-ji_ch-22_p-38_s-1","passageId":"li-ji_ch-22_p-38","order":1,"canonicalText":"凡斂者袒，遷尸者襲。","chunks":[["凡斂者袒，遷尸者襲。","zh-Hant"]]},{"id":"li-ji_ch-22_p-38_s-2","passageId":"li-ji_ch-22_p-38","order":2,"canonicalText":"君之喪，大胥是斂，眾胥佐之；","chunks":[["君之喪，大胥是斂，眾胥佐之；","zh-Hant"]]},{"id":"li-ji_ch-22_p-38_s-3","passageId":"li-ji_ch-22_p-38","order":3,"canonicalText":"大夫之喪，大胥侍之，眾胥是斂；","chunks":[["大夫之喪，大胥侍之，眾胥是斂；","zh-Hant"]]},{"id":"li-ji_ch-22_p-38_s-4","passageId":"li-ji_ch-22_p-38","order":4,"canonicalText":"士之喪，胥為侍，士是斂。","chunks":[["士之喪，胥為侍，士是斂。","zh-Hant"]]},{"id":"li-ji_ch-22_p-39_s-1","passageId":"li-ji_ch-22_p-39","order":1,"canonicalText":"小斂大斂，祭服不倒，皆左衽結絞不紐。","chunks":[["小斂大斂，祭服不倒，皆左衽結絞不紐。","zh-Hant"]]},{"id":"li-ji_ch-22_p-40_s-1","passageId":"li-ji_ch-22_p-40","order":1,"canonicalText":"斂者既斂必哭。","chunks":[["斂者既斂必哭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-40_s-2","passageId":"li-ji_ch-22_p-40","order":2,"canonicalText":"士與其執事則斂，斂焉則為之壹不食。","chunks":[["士與其執事則斂，斂焉則為之壹不食。","zh-Hant"]]},{"id":"li-ji_ch-22_p-40_s-3","passageId":"li-ji_ch-22_p-40","order":3,"canonicalText":"凡斂者六人。","chunks":[["凡斂者六人。","zh-Hant"]]},{"id":"li-ji_ch-22_p-41_s-1","passageId":"li-ji_ch-22_p-41","order":1,"canonicalText":"君錦冒黼殺，綴旁七；","chunks":[["君錦冒黼殺，綴旁七；","zh-Hant"]]},{"id":"li-ji_ch-22_p-41_s-2","passageId":"li-ji_ch-22_p-41","order":2,"canonicalText":"大夫玄冒黼殺，綴旁五；","chunks":[["大夫玄冒黼殺，綴旁五；","zh-Hant"]]},{"id":"li-ji_ch-22_p-41_s-3","passageId":"li-ji_ch-22_p-41","order":3,"canonicalText":"士緇冒赬殺，綴旁三。","chunks":[["士緇冒赬殺，綴旁三。","zh-Hant"]]},{"id":"li-ji_ch-22_p-41_s-4","passageId":"li-ji_ch-22_p-41","order":4,"canonicalText":"凡冒質長與手齊，殺三尺，自小斂以往用夷衾，夷衾質殺之，裁猶冒也。","chunks":[["凡冒質長與手齊，殺三尺，自小斂以往用夷衾，夷衾質殺之，裁猶冒也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-42_s-1","passageId":"li-ji_ch-22_p-42","order":1,"canonicalText":"君將大斂，子弁絰，即位于序端，卿大夫即位于堂廉楹西，北面東上，父兄堂下北面，夫人命婦尸西東面，外宗房中南面。","chunks":[["君將大斂，子弁絰，即位于序端，卿大夫即位于堂廉楹西，北面東上，父兄堂下北面，夫人命婦尸西東面，外宗房中南面。","zh-Hant"]]},{"id":"li-ji_ch-22_p-42_s-2","passageId":"li-ji_ch-22_p-42","order":2,"canonicalText":"小臣鋪席，商祝鋪絞紟衾衣，士盥于盤，上士舉遷尸于斂上。","chunks":[["小臣鋪席，商祝鋪絞紟衾衣，士盥于盤，上士舉遷尸于斂上。","zh-Hant"]]},{"id":"li-ji_ch-22_p-42_s-3","passageId":"li-ji_ch-22_p-42","order":3,"canonicalText":"卒斂，宰告，子馮之踴，夫人東面亦如之。","chunks":[["卒斂，宰告，子馮之踴，夫人東面亦如之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-43_s-1","passageId":"li-ji_ch-22_p-43","order":1,"canonicalText":"大夫之喪，將大斂，既鋪絞紟衾衣。","chunks":[["大夫之喪，將大斂，既鋪絞紟衾衣。","zh-Hant"]]},{"id":"li-ji_ch-22_p-43_s-2","passageId":"li-ji_ch-22_p-43","order":2,"canonicalText":"君至，主人迎，先入門右，巫止於門外，君釋菜，祝先入升堂，君即位于序端，卿大夫即位于堂廉楹西，北面東上；","chunks":[["君至，主人迎，先入門右，巫止於門外，君釋菜，祝先入升堂，君即位于序端，卿大夫即位于堂廉楹西，北面東上；","zh-Hant"]]},{"id":"li-ji_ch-22_p-43_s-3","passageId":"li-ji_ch-22_p-43","order":3,"canonicalText":"主人房外南面，主婦尸西，東面。","chunks":[["主人房外南面，主婦尸西，東面。","zh-Hant"]]},{"id":"li-ji_ch-22_p-43_s-4","passageId":"li-ji_ch-22_p-43","order":4,"canonicalText":"遷尸，卒斂，宰告，主人降，北面于堂下，君撫之，主人拜稽顙，君降、升主人馮之，命主婦馮之。","chunks":[["遷尸，卒斂，宰告，主人降，北面于堂下，君撫之，主人拜稽顙，君降、升主人馮之，命主婦馮之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-44_s-1","passageId":"li-ji_ch-22_p-44","order":1,"canonicalText":"士之喪，將大斂，君不在，其餘禮猶大夫也。","chunks":[["士之喪，將大斂，君不在，其餘禮猶大夫也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-1","passageId":"li-ji_ch-22_p-45","order":1,"canonicalText":"鋪絞紟，踴；","chunks":[["鋪絞紟，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-2","passageId":"li-ji_ch-22_p-45","order":2,"canonicalText":"鋪衾，踴；","chunks":[["鋪衾，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-3","passageId":"li-ji_ch-22_p-45","order":3,"canonicalText":"鋪衣，踴；","chunks":[["鋪衣，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-4","passageId":"li-ji_ch-22_p-45","order":4,"canonicalText":"遷尸，踴；","chunks":[["遷尸，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-5","passageId":"li-ji_ch-22_p-45","order":5,"canonicalText":"斂衣，踴；","chunks":[["斂衣，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-6","passageId":"li-ji_ch-22_p-45","order":6,"canonicalText":"斂衾，踴；","chunks":[["斂衾，踴；","zh-Hant"]]},{"id":"li-ji_ch-22_p-45_s-7","passageId":"li-ji_ch-22_p-45","order":7,"canonicalText":"斂絞紟，踴。","chunks":[["斂絞紟，踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-1","passageId":"li-ji_ch-22_p-46","order":1,"canonicalText":"君撫大夫，撫內命婦；","chunks":[["君撫大夫，撫內命婦；","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-2","passageId":"li-ji_ch-22_p-46","order":2,"canonicalText":"大夫撫室老，撫侄娣。","chunks":[["大夫撫室老，撫侄娣。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-3","passageId":"li-ji_ch-22_p-46","order":3,"canonicalText":"君大夫馮父母、妻、長子，不馮庶子；","chunks":[["君大夫馮父母、妻、長子，不馮庶子；","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-4","passageId":"li-ji_ch-22_p-46","order":4,"canonicalText":"士馮父母、妻、長子、庶子，庶子有子，則父母不馮其尸。","chunks":[["士馮父母、妻、長子、庶子，庶子有子，則父母不馮其尸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-5","passageId":"li-ji_ch-22_p-46","order":5,"canonicalText":"凡馮尸者，父母先，妻子後。","chunks":[["凡馮尸者，父母先，妻子後。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-6","passageId":"li-ji_ch-22_p-46","order":6,"canonicalText":"君於臣撫之，父母於子執之，子於父母馮之，婦於舅姑奉之，舅姑於婦撫之，妻於夫拘之，夫於妻於昆弟執之。","chunks":[["君於臣撫之，父母於子執之，子於父母馮之，婦於舅姑奉之，舅姑於婦撫之，妻於夫拘之，夫於妻於昆弟執之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-7","passageId":"li-ji_ch-22_p-46","order":7,"canonicalText":"馮尸不當君所。","chunks":[["馮尸不當君所。","zh-Hant"]]},{"id":"li-ji_ch-22_p-46_s-8","passageId":"li-ji_ch-22_p-46","order":8,"canonicalText":"凡馮尸，興必踴。","chunks":[["凡馮尸，興必踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-47_s-1","passageId":"li-ji_ch-22_p-47","order":1,"canonicalText":"父母之喪，居倚廬、不涂，寢苫枕塊，非喪事不言。","chunks":[["父母之喪，居倚廬、不涂，寢苫枕塊，非喪事不言。","zh-Hant"]]},{"id":"li-ji_ch-22_p-47_s-2","passageId":"li-ji_ch-22_p-47","order":2,"canonicalText":"君為廬宮之，大夫士襢之。","chunks":[["君為廬宮之，大夫士襢之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-47_s-3","passageId":"li-ji_ch-22_p-47","order":3,"canonicalText":"既葬柱楣，涂廬不於顯者。","chunks":[["既葬柱楣，涂廬不於顯者。","zh-Hant"]]},{"id":"li-ji_ch-22_p-47_s-4","passageId":"li-ji_ch-22_p-47","order":4,"canonicalText":"君、大夫、士皆宮之。","chunks":[["君、大夫、士皆宮之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-47_s-5","passageId":"li-ji_ch-22_p-47","order":5,"canonicalText":"凡非適子者，自未葬以於隱者為廬。","chunks":[["凡非適子者，自未葬以於隱者為廬。","zh-Hant"]]},{"id":"li-ji_ch-22_p-48_s-1","passageId":"li-ji_ch-22_p-48","order":1,"canonicalText":"既葬，與人立：君言王事，不言國事；","chunks":[["既葬，與人立：君言王事，不言國事；","zh-Hant"]]},{"id":"li-ji_ch-22_p-48_s-2","passageId":"li-ji_ch-22_p-48","order":2,"canonicalText":"大夫士言公事，不言家事。","chunks":[["大夫士言公事，不言家事。","zh-Hant"]]},{"id":"li-ji_ch-22_p-49_s-1","passageId":"li-ji_ch-22_p-49","order":1,"canonicalText":"君既葬，王政入於國，既卒哭而服王事；","chunks":[["君既葬，王政入於國，既卒哭而服王事；","zh-Hant"]]},{"id":"li-ji_ch-22_p-49_s-2","passageId":"li-ji_ch-22_p-49","order":2,"canonicalText":"大夫、士既葬，公政入於家，既卒哭、弁絰帶，金革之事無辟也。","chunks":[["大夫、士既葬，公政入於家，既卒哭、弁絰帶，金革之事無辟也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-1","passageId":"li-ji_ch-22_p-50","order":1,"canonicalText":"既練，居堊室，不與人居。","chunks":[["既練，居堊室，不與人居。","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-2","passageId":"li-ji_ch-22_p-50","order":2,"canonicalText":"君謀國政，大夫、士謀家事。","chunks":[["君謀國政，大夫、士謀家事。","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-3","passageId":"li-ji_ch-22_p-50","order":3,"canonicalText":"既祥，黝堊。","chunks":[["既祥，黝堊。","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-4","passageId":"li-ji_ch-22_p-50","order":4,"canonicalText":"祥而外無哭者；","chunks":[["祥而外無哭者；","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-5","passageId":"li-ji_ch-22_p-50","order":5,"canonicalText":"禫而內無哭者，樂作矣故也。","chunks":[["禫而內無哭者，樂作矣故也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-50_s-6","passageId":"li-ji_ch-22_p-50","order":6,"canonicalText":"禫而從御，吉祭而復寢。","chunks":[["禫而從御，吉祭而復寢。","zh-Hant"]]},{"id":"li-ji_ch-22_p-51_s-1","passageId":"li-ji_ch-22_p-51","order":1,"canonicalText":"期居廬，終喪不御於內者，父在為母為妻；","chunks":[["期居廬，終喪不御於內者，父在為母為妻；","zh-Hant"]]},{"id":"li-ji_ch-22_p-51_s-2","passageId":"li-ji_ch-22_p-51","order":2,"canonicalText":"齊衰期者，大功布衰九月者，皆三月不御於內。","chunks":[["齊衰期者，大功布衰九月者，皆三月不御於內。","zh-Hant"]]},{"id":"li-ji_ch-22_p-51_s-3","passageId":"li-ji_ch-22_p-51","order":3,"canonicalText":"婦人不居廬，不寢苫。","chunks":[["婦人不居廬，不寢苫。","zh-Hant"]]},{"id":"li-ji_ch-22_p-51_s-4","passageId":"li-ji_ch-22_p-51","order":4,"canonicalText":"喪父母，既練而歸；","chunks":[["喪父母，既練而歸；","zh-Hant"]]},{"id":"li-ji_ch-22_p-51_s-5","passageId":"li-ji_ch-22_p-51","order":5,"canonicalText":"期九月者，既葬而歸。","chunks":[["期九月者，既葬而歸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-52_s-1","passageId":"li-ji_ch-22_p-52","order":1,"canonicalText":"公之喪，大夫俟練，士卒哭而歸。","chunks":[["公之喪，大夫俟練，士卒哭而歸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-53_s-1","passageId":"li-ji_ch-22_p-53","order":1,"canonicalText":"大夫、士父母之葬，既練而歸。","chunks":[["大夫、士父母之葬，既練而歸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-53_s-2","passageId":"li-ji_ch-22_p-53","order":2,"canonicalText":"朔月忌日，則歸哭于宗室。","chunks":[["朔月忌日，則歸哭于宗室。","zh-Hant"]]},{"id":"li-ji_ch-22_p-53_s-3","passageId":"li-ji_ch-22_p-53","order":3,"canonicalText":"諸父兄弟之喪，既卒哭而歸。","chunks":[["諸父兄弟之喪，既卒哭而歸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-54_s-1","passageId":"li-ji_ch-22_p-54","order":1,"canonicalText":"父不次於子，兄不次於弟。","chunks":[["父不次於子，兄不次於弟。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-1","passageId":"li-ji_ch-22_p-55","order":1,"canonicalText":"君於大夫、世婦大斂焉；","chunks":[["君於大夫、世婦大斂焉；","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-2","passageId":"li-ji_ch-22_p-55","order":2,"canonicalText":"為之賜則小斂焉。","chunks":[["為之賜則小斂焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-3","passageId":"li-ji_ch-22_p-55","order":3,"canonicalText":"於外命婦，既加蓋而君至。","chunks":[["於外命婦，既加蓋而君至。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-4","passageId":"li-ji_ch-22_p-55","order":4,"canonicalText":"於士，既殯而往；","chunks":[["於士，既殯而往；","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-5","passageId":"li-ji_ch-22_p-55","order":5,"canonicalText":"為之賜，大斂焉。","chunks":[["為之賜，大斂焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-6","passageId":"li-ji_ch-22_p-55","order":6,"canonicalText":"夫人於世婦，大斂焉；","chunks":[["夫人於世婦，大斂焉；","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-7","passageId":"li-ji_ch-22_p-55","order":7,"canonicalText":"為之賜，小斂焉。","chunks":[["為之賜，小斂焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-8","passageId":"li-ji_ch-22_p-55","order":8,"canonicalText":"於諸妻，為之賜，大斂焉。","chunks":[["於諸妻，為之賜，大斂焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-55_s-9","passageId":"li-ji_ch-22_p-55","order":9,"canonicalText":"於大夫外命婦，既殯而往。","chunks":[["於大夫外命婦，既殯而往。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-1","passageId":"li-ji_ch-22_p-56","order":1,"canonicalText":"大夫、士既殯而君往焉，使人戒之，主人具殷奠之禮，俟于門外。","chunks":[["大夫、士既殯而君往焉，使人戒之，主人具殷奠之禮，俟于門外。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-2","passageId":"li-ji_ch-22_p-56","order":2,"canonicalText":"見馬首，先入門右，巫止于門外，祝代之先，君釋菜于門內。","chunks":[["見馬首，先入門右，巫止于門外，祝代之先，君釋菜于門內。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-3","passageId":"li-ji_ch-22_p-56","order":3,"canonicalText":"祝先升自阼階，負墉南面。","chunks":[["祝先升自阼階，負墉南面。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-4","passageId":"li-ji_ch-22_p-56","order":4,"canonicalText":"君即位于阼。","chunks":[["君即位于阼。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-5","passageId":"li-ji_ch-22_p-56","order":5,"canonicalText":"小臣二人執戈立于前，二人立于後。","chunks":[["小臣二人執戈立于前，二人立于後。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-6","passageId":"li-ji_ch-22_p-56","order":6,"canonicalText":"擯者進，主人拜稽顙。","chunks":[["擯者進，主人拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-22_p-56_s-7","passageId":"li-ji_ch-22_p-56","order":7,"canonicalText":"君稱言，視祝而踴，主人踴。","chunks":[["君稱言，視祝而踴，主人踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-57_s-1","passageId":"li-ji_ch-22_p-57","order":1,"canonicalText":"大夫則奠可也。","chunks":[["大夫則奠可也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-57_s-2","passageId":"li-ji_ch-22_p-57","order":2,"canonicalText":"士則出俟于門外，命之反奠，乃反奠。","chunks":[["士則出俟于門外，命之反奠，乃反奠。","zh-Hant"]]},{"id":"li-ji_ch-22_p-57_s-3","passageId":"li-ji_ch-22_p-57","order":3,"canonicalText":"卒奠，主人先俟於門外，君退，主人送于門外，拜稽顙。","chunks":[["卒奠，主人先俟於門外，君退，主人送于門外，拜稽顙。","zh-Hant"]]},{"id":"li-ji_ch-22_p-58_s-1","passageId":"li-ji_ch-22_p-58","order":1,"canonicalText":"君於大夫疾，三問之，在殯，三往焉；","chunks":[["君於大夫疾，三問之，在殯，三往焉；","zh-Hant"]]},{"id":"li-ji_ch-22_p-58_s-2","passageId":"li-ji_ch-22_p-58","order":2,"canonicalText":"士疾，壹問之，在殯，壹往焉。","chunks":[["士疾，壹問之，在殯，壹往焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-58_s-3","passageId":"li-ji_ch-22_p-58","order":3,"canonicalText":"君吊則復殯服。","chunks":[["君吊則復殯服。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-1","passageId":"li-ji_ch-22_p-59","order":1,"canonicalText":"夫人吊於大夫、士，主人出迎于門外，見馬首，先入門右。","chunks":[["夫人吊於大夫、士，主人出迎于門外，見馬首，先入門右。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-2","passageId":"li-ji_ch-22_p-59","order":2,"canonicalText":"夫人入，升堂即位。","chunks":[["夫人入，升堂即位。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-3","passageId":"li-ji_ch-22_p-59","order":3,"canonicalText":"主婦降自西階，拜稽顙于下。","chunks":[["主婦降自西階，拜稽顙于下。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-4","passageId":"li-ji_ch-22_p-59","order":4,"canonicalText":"夫人視世子而踴。","chunks":[["夫人視世子而踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-5","passageId":"li-ji_ch-22_p-59","order":5,"canonicalText":"奠如君至之禮。","chunks":[["奠如君至之禮。","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-6","passageId":"li-ji_ch-22_p-59","order":6,"canonicalText":"夫人退，主婦送于門內，拜稽顙；","chunks":[["夫人退，主婦送于門內，拜稽顙；","zh-Hant"]]},{"id":"li-ji_ch-22_p-59_s-7","passageId":"li-ji_ch-22_p-59","order":7,"canonicalText":"主人送于大門之外不拜。","chunks":[["主人送于大門之外不拜。","zh-Hant"]]},{"id":"li-ji_ch-22_p-60_s-1","passageId":"li-ji_ch-22_p-60","order":1,"canonicalText":"大夫君不迎于門外。","chunks":[["大夫君不迎于門外。","zh-Hant"]]},{"id":"li-ji_ch-22_p-60_s-2","passageId":"li-ji_ch-22_p-60","order":2,"canonicalText":"入即位于堂下。","chunks":[["入即位于堂下。","zh-Hant"]]},{"id":"li-ji_ch-22_p-60_s-3","passageId":"li-ji_ch-22_p-60","order":3,"canonicalText":"主人北面，眾主人南面；","chunks":[["主人北面，眾主人南面；","zh-Hant"]]},{"id":"li-ji_ch-22_p-60_s-4","passageId":"li-ji_ch-22_p-60","order":4,"canonicalText":"婦人即位于房中。","chunks":[["婦人即位于房中。","zh-Hant"]]},{"id":"li-ji_ch-22_p-60_s-5","passageId":"li-ji_ch-22_p-60","order":5,"canonicalText":"若有君命，命夫命婦之命，四鄰賓客，其君後主人而拜。","chunks":[["若有君命，命夫命婦之命，四鄰賓客，其君後主人而拜。","zh-Hant"]]},{"id":"li-ji_ch-22_p-61_s-1","passageId":"li-ji_ch-22_p-61","order":1,"canonicalText":"君吊，見尸柩而後踴。","chunks":[["君吊，見尸柩而後踴。","zh-Hant"]]},{"id":"li-ji_ch-22_p-61_s-2","passageId":"li-ji_ch-22_p-61","order":2,"canonicalText":"大夫、士若君不戒而往，不具殷奠；","chunks":[["大夫、士若君不戒而往，不具殷奠；","zh-Hant"]]},{"id":"li-ji_ch-22_p-61_s-3","passageId":"li-ji_ch-22_p-61","order":3,"canonicalText":"君退必奠。","chunks":[["君退必奠。","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-1","passageId":"li-ji_ch-22_p-62","order":1,"canonicalText":"君大棺八寸，屬六寸，椑四寸；","chunks":[["君大棺八寸，屬六寸，椑四寸；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-2","passageId":"li-ji_ch-22_p-62","order":2,"canonicalText":"上大夫大棺八寸，屬六寸；","chunks":[["上大夫大棺八寸，屬六寸；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-3","passageId":"li-ji_ch-22_p-62","order":3,"canonicalText":"下大夫大棺六寸，屬四寸，士棺六寸。","chunks":[["下大夫大棺六寸，屬四寸，士棺六寸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-4","passageId":"li-ji_ch-22_p-62","order":4,"canonicalText":"君里棺用朱綠，用雜金鐕；","chunks":[["君里棺用朱綠，用雜金鐕；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-5","passageId":"li-ji_ch-22_p-62","order":5,"canonicalText":"大夫里棺用玄綠，用牛骨鐕；","chunks":[["大夫里棺用玄綠，用牛骨鐕；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-6","passageId":"li-ji_ch-22_p-62","order":6,"canonicalText":"士不綠。","chunks":[["士不綠。","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-7","passageId":"li-ji_ch-22_p-62","order":7,"canonicalText":"君蓋用漆，三衽三束；","chunks":[["君蓋用漆，三衽三束；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-8","passageId":"li-ji_ch-22_p-62","order":8,"canonicalText":"大夫蓋用漆，二衽二束；","chunks":[["大夫蓋用漆，二衽二束；","zh-Hant"]]},{"id":"li-ji_ch-22_p-62_s-9","passageId":"li-ji_ch-22_p-62","order":9,"canonicalText":"士蓋不用漆，二衽二束。","chunks":[["士蓋不用漆，二衽二束。","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-1","passageId":"li-ji_ch-22_p-63","order":1,"canonicalText":"君、大夫鬊爪；","chunks":[["君、大夫鬊爪；","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-2","passageId":"li-ji_ch-22_p-63","order":2,"canonicalText":"實于綠中；","chunks":[["實于綠中；","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-3","passageId":"li-ji_ch-22_p-63","order":3,"canonicalText":"士埋之。","chunks":[["士埋之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-4","passageId":"li-ji_ch-22_p-63","order":4,"canonicalText":"君殯用輴，欑至于上，畢涂屋；","chunks":[["君殯用輴，欑至于上，畢涂屋；","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-5","passageId":"li-ji_ch-22_p-63","order":5,"canonicalText":"大夫殯以幬，欑置于西序，涂不暨于棺；","chunks":[["大夫殯以幬，欑置于西序，涂不暨于棺；","zh-Hant"]]},{"id":"li-ji_ch-22_p-63_s-6","passageId":"li-ji_ch-22_p-63","order":6,"canonicalText":"士殯見衽，涂上帷之。","chunks":[["士殯見衽，涂上帷之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-64_s-1","passageId":"li-ji_ch-22_p-64","order":1,"canonicalText":"熬，君四種八筐，大夫三種六筐，士二種四筐，加魚臘焉。","chunks":[["熬，君四種八筐，大夫三種六筐，士二種四筐，加魚臘焉。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-1","passageId":"li-ji_ch-22_p-65","order":1,"canonicalText":"飾棺，君龍帷三池，振容。","chunks":[["飾棺，君龍帷三池，振容。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-2","passageId":"li-ji_ch-22_p-65","order":2,"canonicalText":"黼荒，火三列，黼三列。","chunks":[["黼荒，火三列，黼三列。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-3","passageId":"li-ji_ch-22_p-65","order":3,"canonicalText":"素錦褚，加偽荒。","chunks":[["素錦褚，加偽荒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-4","passageId":"li-ji_ch-22_p-65","order":4,"canonicalText":"纁紐六。","chunks":[["纁紐六。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-5","passageId":"li-ji_ch-22_p-65","order":5,"canonicalText":"齊，五采五貝。","chunks":[["齊，五采五貝。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-6","passageId":"li-ji_ch-22_p-65","order":6,"canonicalText":"黼翣二，黻翣二，畫翣二，皆戴圭。","chunks":[["黼翣二，黻翣二，畫翣二，皆戴圭。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-7","passageId":"li-ji_ch-22_p-65","order":7,"canonicalText":"魚躍拂池。","chunks":[["魚躍拂池。","zh-Hant"]]},{"id":"li-ji_ch-22_p-65_s-8","passageId":"li-ji_ch-22_p-65","order":8,"canonicalText":"君纁戴六，纁披六。","chunks":[["君纁戴六，纁披六。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-1","passageId":"li-ji_ch-22_p-66","order":1,"canonicalText":"大夫畫帷二池，不振容。","chunks":[["大夫畫帷二池，不振容。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-2","passageId":"li-ji_ch-22_p-66","order":2,"canonicalText":"畫荒，火三列，黻三列。","chunks":[["畫荒，火三列，黻三列。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-3","passageId":"li-ji_ch-22_p-66","order":3,"canonicalText":"素錦褚。","chunks":[["素錦褚。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-4","passageId":"li-ji_ch-22_p-66","order":4,"canonicalText":"纁紐二，玄紐二。","chunks":[["纁紐二，玄紐二。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-5","passageId":"li-ji_ch-22_p-66","order":5,"canonicalText":"齊，三采三貝。","chunks":[["齊，三采三貝。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-6","passageId":"li-ji_ch-22_p-66","order":6,"canonicalText":"黻翣二，畫翣二，皆戴綏。","chunks":[["黻翣二，畫翣二，皆戴綏。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-7","passageId":"li-ji_ch-22_p-66","order":7,"canonicalText":"魚躍拂池。","chunks":[["魚躍拂池。","zh-Hant"]]},{"id":"li-ji_ch-22_p-66_s-8","passageId":"li-ji_ch-22_p-66","order":8,"canonicalText":"大夫戴前纁後玄，披亦如之。","chunks":[["大夫戴前纁後玄，披亦如之。","zh-Hant"]]},{"id":"li-ji_ch-22_p-67_s-1","passageId":"li-ji_ch-22_p-67","order":1,"canonicalText":"士布帷布荒，一池，揄絞。","chunks":[["士布帷布荒，一池，揄絞。","zh-Hant"]]},{"id":"li-ji_ch-22_p-67_s-2","passageId":"li-ji_ch-22_p-67","order":2,"canonicalText":"纁紐二，緇紐二。","chunks":[["纁紐二，緇紐二。","zh-Hant"]]},{"id":"li-ji_ch-22_p-67_s-3","passageId":"li-ji_ch-22_p-67","order":3,"canonicalText":"齊，三采一貝。","chunks":[["齊，三采一貝。","zh-Hant"]]},{"id":"li-ji_ch-22_p-67_s-4","passageId":"li-ji_ch-22_p-67","order":4,"canonicalText":"畫翣二，皆戴綏。","chunks":[["畫翣二，皆戴綏。","zh-Hant"]]},{"id":"li-ji_ch-22_p-67_s-5","passageId":"li-ji_ch-22_p-67","order":5,"canonicalText":"士戴前纁後緇，二披用纁。","chunks":[["士戴前纁後緇，二披用纁。","zh-Hant"]]},{"id":"li-ji_ch-22_p-68_s-1","passageId":"li-ji_ch-22_p-68","order":1,"canonicalText":"君葬用輇，四綍二碑，御棺用羽葆。","chunks":[["君葬用輇，四綍二碑，御棺用羽葆。","zh-Hant"]]},{"id":"li-ji_ch-22_p-68_s-2","passageId":"li-ji_ch-22_p-68","order":2,"canonicalText":"大夫葬用輇，二綍二碑，御棺用茅。","chunks":[["大夫葬用輇，二綍二碑，御棺用茅。","zh-Hant"]]},{"id":"li-ji_ch-22_p-68_s-3","passageId":"li-ji_ch-22_p-68","order":3,"canonicalText":"士葬用國車。","chunks":[["士葬用國車。","zh-Hant"]]},{"id":"li-ji_ch-22_p-68_s-4","passageId":"li-ji_ch-22_p-68","order":4,"canonicalText":"二綍無碑，比出宮，御棺用功布。","chunks":[["二綍無碑，比出宮，御棺用功布。","zh-Hant"]]},{"id":"li-ji_ch-22_p-69_s-1","passageId":"li-ji_ch-22_p-69","order":1,"canonicalText":"凡封，用綍去碑負引，君封以衡，大夫士以咸。","chunks":[["凡封，用綍去碑負引，君封以衡，大夫士以咸。","zh-Hant"]]},{"id":"li-ji_ch-22_p-69_s-2","passageId":"li-ji_ch-22_p-69","order":2,"canonicalText":"君命毋嘩，以鼓封；","chunks":[["君命毋嘩，以鼓封；","zh-Hant"]]},{"id":"li-ji_ch-22_p-69_s-3","passageId":"li-ji_ch-22_p-69","order":3,"canonicalText":"大夫命毋哭；","chunks":[["大夫命毋哭；","zh-Hant"]]},{"id":"li-ji_ch-22_p-69_s-4","passageId":"li-ji_ch-22_p-69","order":4,"canonicalText":"士哭者相止也。","chunks":[["士哭者相止也。","zh-Hant"]]},{"id":"li-ji_ch-22_p-70_s-1","passageId":"li-ji_ch-22_p-70","order":1,"canonicalText":"君松槨，大夫柏槨，士雜木槨。","chunks":[["君松槨，大夫柏槨，士雜木槨。","zh-Hant"]]},{"id":"li-ji_ch-22_p-70_s-2","passageId":"li-ji_ch-22_p-70","order":2,"canonicalText":"棺槨之間，君容柷，大夫容壺，士容甒。","chunks":[["棺槨之間，君容柷，大夫容壺，士容甒。","zh-Hant"]]},{"id":"li-ji_ch-22_p-70_s-3","passageId":"li-ji_ch-22_p-70","order":3,"canonicalText":"君里槨虞筐，大夫不里槨，士不虞筐。","chunks":[["君里槨虞筐，大夫不里槨，士不虞筐。","zh-Hant"]]},{"id":"li-ji_ch-23_p-1_s-1","passageId":"li-ji_ch-23_p-1","order":1,"canonicalText":"祭法：有虞氏禘黃帝而郊嚳，祖顓頊而宗堯。","chunks":[["祭法：有虞氏禘黃帝而郊嚳，祖顓頊而宗堯。","zh-Hant"]]},{"id":"li-ji_ch-23_p-1_s-2","passageId":"li-ji_ch-23_p-1","order":2,"canonicalText":"夏后氏亦禘黃帝而郊鯀，祖顓頊而宗禹。","chunks":[["夏后氏亦禘黃帝而郊鯀，祖顓頊而宗禹。","zh-Hant"]]},{"id":"li-ji_ch-23_p-1_s-3","passageId":"li-ji_ch-23_p-1","order":3,"canonicalText":"殷人禘嚳而郊冥，祖契而宗湯。","chunks":[["殷人禘嚳而郊冥，祖契而宗湯。","zh-Hant"]]},{"id":"li-ji_ch-23_p-1_s-4","passageId":"li-ji_ch-23_p-1","order":4,"canonicalText":"周人禘嚳而郊稷，祖文王而宗武王。","chunks":[["周人禘嚳而郊稷，祖文王而宗武王。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-1","passageId":"li-ji_ch-23_p-2","order":1,"canonicalText":"燔柴於泰壇，祭天也；","chunks":[["燔柴於泰壇，祭天也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-2","passageId":"li-ji_ch-23_p-2","order":2,"canonicalText":"瘞埋於泰折，祭地也；","chunks":[["瘞埋於泰折，祭地也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-3","passageId":"li-ji_ch-23_p-2","order":3,"canonicalText":"用騂犢。","chunks":[["用騂犢。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-4","passageId":"li-ji_ch-23_p-2","order":4,"canonicalText":"埋少牢於泰昭，祭時也；","chunks":[["埋少牢於泰昭，祭時也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-5","passageId":"li-ji_ch-23_p-2","order":5,"canonicalText":"相近於坎壇，祭寒暑也。","chunks":[["相近於坎壇，祭寒暑也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-6","passageId":"li-ji_ch-23_p-2","order":6,"canonicalText":"王宮，祭日也；","chunks":[["王宮，祭日也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-7","passageId":"li-ji_ch-23_p-2","order":7,"canonicalText":"夜明，祭月也；","chunks":[["夜明，祭月也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-8","passageId":"li-ji_ch-23_p-2","order":8,"canonicalText":"幽宗，祭星也；","chunks":[["幽宗，祭星也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-9","passageId":"li-ji_ch-23_p-2","order":9,"canonicalText":"雩宗，祭水旱也；","chunks":[["雩宗，祭水旱也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-10","passageId":"li-ji_ch-23_p-2","order":10,"canonicalText":"四坎壇，祭四時也。","chunks":[["四坎壇，祭四時也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-11","passageId":"li-ji_ch-23_p-2","order":11,"canonicalText":"山林、川谷、丘陵，能出云為風雨，見怪物，皆曰神。","chunks":[["山林、川谷、丘陵，能出云為風雨，見怪物，皆曰神。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-12","passageId":"li-ji_ch-23_p-2","order":12,"canonicalText":"有天下者，祭百神。","chunks":[["有天下者，祭百神。","zh-Hant"]]},{"id":"li-ji_ch-23_p-2_s-13","passageId":"li-ji_ch-23_p-2","order":13,"canonicalText":"諸侯在其地則祭之，亡其地則不祭。","chunks":[["諸侯在其地則祭之，亡其地則不祭。","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-1","passageId":"li-ji_ch-23_p-3","order":1,"canonicalText":"大凡生於天地之間者，皆曰命。","chunks":[["大凡生於天地之間者，皆曰命。","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-2","passageId":"li-ji_ch-23_p-3","order":2,"canonicalText":"其萬物死，皆曰折；","chunks":[["其萬物死，皆曰折；","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-3","passageId":"li-ji_ch-23_p-3","order":3,"canonicalText":"人死，曰鬼；","chunks":[["人死，曰鬼；","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-4","passageId":"li-ji_ch-23_p-3","order":4,"canonicalText":"此五代之所不變也。","chunks":[["此五代之所不變也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-5","passageId":"li-ji_ch-23_p-3","order":5,"canonicalText":"七代之所以更立者：禘、郊、宗、祖；","chunks":[["七代之所以更立者：禘、郊、宗、祖；","zh-Hant"]]},{"id":"li-ji_ch-23_p-3_s-6","passageId":"li-ji_ch-23_p-3","order":6,"canonicalText":"其餘不變也。","chunks":[["其餘不變也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-4_s-1","passageId":"li-ji_ch-23_p-4","order":1,"canonicalText":"天下有王，分地建國，置都立邑，設廟祧壇墠而祭之，乃為親疏多少之數。","chunks":[["天下有王，分地建國，置都立邑，設廟祧壇墠而祭之，乃為親疏多少之數。","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-1","passageId":"li-ji_ch-23_p-5","order":1,"canonicalText":"是故：王立七廟，一壇一墠，曰考廟，曰王考廟，曰皇考廟，曰顯考廟，曰祖考廟；","chunks":[["是故：王立七廟，一壇一墠，曰考廟，曰王考廟，曰皇考廟，曰顯考廟，曰祖考廟；","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-2","passageId":"li-ji_ch-23_p-5","order":2,"canonicalText":"皆月祭之。","chunks":[["皆月祭之。","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-3","passageId":"li-ji_ch-23_p-5","order":3,"canonicalText":"遠廟為祧，有二祧，享嘗乃止。","chunks":[["遠廟為祧，有二祧，享嘗乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-4","passageId":"li-ji_ch-23_p-5","order":4,"canonicalText":"去祧為壇，去壇為墠。","chunks":[["去祧為壇，去壇為墠。","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-5","passageId":"li-ji_ch-23_p-5","order":5,"canonicalText":"壇墠，有禱焉祭之，無禱乃止。","chunks":[["壇墠，有禱焉祭之，無禱乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-5_s-6","passageId":"li-ji_ch-23_p-5","order":6,"canonicalText":"去墠曰鬼。","chunks":[["去墠曰鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-1","passageId":"li-ji_ch-23_p-6","order":1,"canonicalText":"諸侯立五廟，一壇一墠。","chunks":[["諸侯立五廟，一壇一墠。","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-2","passageId":"li-ji_ch-23_p-6","order":2,"canonicalText":"曰考廟，曰王考廟，曰皇考廟，皆月祭之；","chunks":[["曰考廟，曰王考廟，曰皇考廟，皆月祭之；","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-3","passageId":"li-ji_ch-23_p-6","order":3,"canonicalText":"顯考廟，祖考廟，享嘗乃止。","chunks":[["顯考廟，祖考廟，享嘗乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-4","passageId":"li-ji_ch-23_p-6","order":4,"canonicalText":"去祖為壇，去壇為墠。","chunks":[["去祖為壇，去壇為墠。","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-5","passageId":"li-ji_ch-23_p-6","order":5,"canonicalText":"壇墠，有禱焉祭之，無禱乃止。","chunks":[["壇墠，有禱焉祭之，無禱乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-6_s-6","passageId":"li-ji_ch-23_p-6","order":6,"canonicalText":"去墠為鬼。","chunks":[["去墠為鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-7_s-1","passageId":"li-ji_ch-23_p-7","order":1,"canonicalText":"大夫立三廟二壇，曰考廟，曰王考廟，曰皇考廟，享嘗乃止。","chunks":[["大夫立三廟二壇，曰考廟，曰王考廟，曰皇考廟，享嘗乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-7_s-2","passageId":"li-ji_ch-23_p-7","order":2,"canonicalText":"顯考祖考無廟，有禱焉，為壇祭之。","chunks":[["顯考祖考無廟，有禱焉，為壇祭之。","zh-Hant"]]},{"id":"li-ji_ch-23_p-7_s-3","passageId":"li-ji_ch-23_p-7","order":3,"canonicalText":"去壇為鬼。","chunks":[["去壇為鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-8_s-1","passageId":"li-ji_ch-23_p-8","order":1,"canonicalText":"適士二廟一壇，曰考廟，曰王考廟，享嘗乃止。","chunks":[["適士二廟一壇，曰考廟，曰王考廟，享嘗乃止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-8_s-2","passageId":"li-ji_ch-23_p-8","order":2,"canonicalText":"皇考無廟，有禱焉，為壇祭之。","chunks":[["皇考無廟，有禱焉，為壇祭之。","zh-Hant"]]},{"id":"li-ji_ch-23_p-8_s-3","passageId":"li-ji_ch-23_p-8","order":3,"canonicalText":"去壇為鬼。","chunks":[["去壇為鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-9_s-1","passageId":"li-ji_ch-23_p-9","order":1,"canonicalText":"官師一廟，曰考廟。","chunks":[["官師一廟，曰考廟。","zh-Hant"]]},{"id":"li-ji_ch-23_p-9_s-2","passageId":"li-ji_ch-23_p-9","order":2,"canonicalText":"王考無廟而祭之，去王考曰鬼。","chunks":[["王考無廟而祭之，去王考曰鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-10_s-1","passageId":"li-ji_ch-23_p-10","order":1,"canonicalText":"庶士庶人無廟，死曰鬼。","chunks":[["庶士庶人無廟，死曰鬼。","zh-Hant"]]},{"id":"li-ji_ch-23_p-11_s-1","passageId":"li-ji_ch-23_p-11","order":1,"canonicalText":"王為群姓立社，曰大社。","chunks":[["王為群姓立社，曰大社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-11_s-2","passageId":"li-ji_ch-23_p-11","order":2,"canonicalText":"王自為立社，曰王社。","chunks":[["王自為立社，曰王社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-11_s-3","passageId":"li-ji_ch-23_p-11","order":3,"canonicalText":"諸侯為百姓立社，曰國社。","chunks":[["諸侯為百姓立社，曰國社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-11_s-4","passageId":"li-ji_ch-23_p-11","order":4,"canonicalText":"諸侯自立社，曰侯社。","chunks":[["諸侯自立社，曰侯社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-11_s-5","passageId":"li-ji_ch-23_p-11","order":5,"canonicalText":"大夫以下，成群立社曰置社。","chunks":[["大夫以下，成群立社曰置社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-12_s-1","passageId":"li-ji_ch-23_p-12","order":1,"canonicalText":"王為群姓立七祀：曰司命，曰中溜，曰國門，曰國行，曰泰厲，曰戶，曰灶。","chunks":[["王為群姓立七祀：曰司命，曰中溜，曰國門，曰國行，曰泰厲，曰戶，曰灶。","zh-Hant"]]},{"id":"li-ji_ch-23_p-12_s-2","passageId":"li-ji_ch-23_p-12","order":2,"canonicalText":"王自為立七祀。","chunks":[["王自為立七祀。","zh-Hant"]]},{"id":"li-ji_ch-23_p-13_s-1","passageId":"li-ji_ch-23_p-13","order":1,"canonicalText":"諸侯為國立五祀，曰司命，曰中溜，曰國門，曰國行，曰公厲。","chunks":[["諸侯為國立五祀，曰司命，曰中溜，曰國門，曰國行，曰公厲。","zh-Hant"]]},{"id":"li-ji_ch-23_p-13_s-2","passageId":"li-ji_ch-23_p-13","order":2,"canonicalText":"諸侯自為立五祀。","chunks":[["諸侯自為立五祀。","zh-Hant"]]},{"id":"li-ji_ch-23_p-14_s-1","passageId":"li-ji_ch-23_p-14","order":1,"canonicalText":"大夫立三祀：曰族厲，曰門，曰行。","chunks":[["大夫立三祀：曰族厲，曰門，曰行。","zh-Hant"]]},{"id":"li-ji_ch-23_p-15_s-1","passageId":"li-ji_ch-23_p-15","order":1,"canonicalText":"適士立二祀：曰門，曰行。","chunks":[["適士立二祀：曰門，曰行。","zh-Hant"]]},{"id":"li-ji_ch-23_p-16_s-1","passageId":"li-ji_ch-23_p-16","order":1,"canonicalText":"庶士、庶人立一祀，或立戶，或立灶。","chunks":[["庶士、庶人立一祀，或立戶，或立灶。","zh-Hant"]]},{"id":"li-ji_ch-23_p-17_s-1","passageId":"li-ji_ch-23_p-17","order":1,"canonicalText":"王下祭殤五：適子、適孫、適曾孫、適玄孫、適來孫。","chunks":[["王下祭殤五：適子、適孫、適曾孫、適玄孫、適來孫。","zh-Hant"]]},{"id":"li-ji_ch-23_p-18_s-1","passageId":"li-ji_ch-23_p-18","order":1,"canonicalText":"諸侯下祭三，大夫下祭二，適士及庶人，祭子而止。","chunks":[["諸侯下祭三，大夫下祭二，適士及庶人，祭子而止。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-1","passageId":"li-ji_ch-23_p-19","order":1,"canonicalText":"夫聖王之制祭祀也：法施於民則祀之，以死勤事則祀之，以勞定國則祀之，能御大菑則祀之，能捍大患則祀之。","chunks":[["夫聖王之制祭祀也：法施於民則祀之，以死勤事則祀之，以勞定國則祀之，能御大菑則祀之，能捍大患則祀之。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-2","passageId":"li-ji_ch-23_p-19","order":2,"canonicalText":"是故厲山氏之有天下也，其子曰農，能殖百穀；","chunks":[["是故厲山氏之有天下也，其子曰農，能殖百穀；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-3","passageId":"li-ji_ch-23_p-19","order":3,"canonicalText":"夏之衰也，周棄繼之，故祀以為稷。","chunks":[["夏之衰也，周棄繼之，故祀以為稷。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-4","passageId":"li-ji_ch-23_p-19","order":4,"canonicalText":"共工氏之霸九州也，其子曰後土，能平九州，故祀以為社。","chunks":[["共工氏之霸九州也，其子曰後土，能平九州，故祀以為社。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-5","passageId":"li-ji_ch-23_p-19","order":5,"canonicalText":"帝嚳能序星辰以著眾；","chunks":[["帝嚳能序星辰以著眾；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-6","passageId":"li-ji_ch-23_p-19","order":6,"canonicalText":"堯能賞均刑法以義終；","chunks":[["堯能賞均刑法以義終；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-7","passageId":"li-ji_ch-23_p-19","order":7,"canonicalText":"舜勤眾事而野死。","chunks":[["舜勤眾事而野死。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-8","passageId":"li-ji_ch-23_p-19","order":8,"canonicalText":"鯀鄣洪水而殛死，禹能修鯀之功。","chunks":[["鯀鄣洪水而殛死，禹能修鯀之功。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-9","passageId":"li-ji_ch-23_p-19","order":9,"canonicalText":"黃帝正名百物以明民共財，顓頊能修之。","chunks":[["黃帝正名百物以明民共財，顓頊能修之。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-10","passageId":"li-ji_ch-23_p-19","order":10,"canonicalText":"契為司徒而民成；","chunks":[["契為司徒而民成；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-11","passageId":"li-ji_ch-23_p-19","order":11,"canonicalText":"冥勤其官而水死。","chunks":[["冥勤其官而水死。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-12","passageId":"li-ji_ch-23_p-19","order":12,"canonicalText":"湯以寬治民而除其虐；","chunks":[["湯以寬治民而除其虐；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-13","passageId":"li-ji_ch-23_p-19","order":13,"canonicalText":"文王以文治，武王以武功，去民之菑。","chunks":[["文王以文治，武王以武功，去民之菑。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-14","passageId":"li-ji_ch-23_p-19","order":14,"canonicalText":"此皆有功烈於民者也。","chunks":[["此皆有功烈於民者也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-15","passageId":"li-ji_ch-23_p-19","order":15,"canonicalText":"及夫日月星辰，民所瞻仰也；","chunks":[["及夫日月星辰，民所瞻仰也；","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-16","passageId":"li-ji_ch-23_p-19","order":16,"canonicalText":"山林川谷丘陵，民所取材用也。","chunks":[["山林川谷丘陵，民所取材用也。","zh-Hant"]]},{"id":"li-ji_ch-23_p-19_s-17","passageId":"li-ji_ch-23_p-19","order":17,"canonicalText":"非此族也，不在祀典。","chunks":[["非此族也，不在祀典。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-1","passageId":"li-ji_ch-24_p-1","order":1,"canonicalText":"祭不欲數，數則煩，煩則不敬。","chunks":[["祭不欲數，數則煩，煩則不敬。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-2","passageId":"li-ji_ch-24_p-1","order":2,"canonicalText":"祭不欲疏，疏則怠，怠則忘。","chunks":[["祭不欲疏，疏則怠，怠則忘。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-3","passageId":"li-ji_ch-24_p-1","order":3,"canonicalText":"是故君子合諸天道：春禘秋嘗。","chunks":[["是故君子合諸天道：春禘秋嘗。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-4","passageId":"li-ji_ch-24_p-1","order":4,"canonicalText":"霜露既降，君子履之，必有凄愴之心，非其寒之謂也。","chunks":[["霜露既降，君子履之，必有凄愴之心，非其寒之謂也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-5","passageId":"li-ji_ch-24_p-1","order":5,"canonicalText":"春，雨露既濡，君子履之，必有怵惕之心，如將見之。","chunks":[["春，雨露既濡，君子履之，必有怵惕之心，如將見之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-1_s-6","passageId":"li-ji_ch-24_p-1","order":6,"canonicalText":"樂以迎來，哀以送往，故禘有樂而嘗無樂。","chunks":[["樂以迎來，哀以送往，故禘有樂而嘗無樂。","zh-Hant"]]},{"id":"li-ji_ch-24_p-2_s-1","passageId":"li-ji_ch-24_p-2","order":1,"canonicalText":"致齊於內，散齊於外。","chunks":[["致齊於內，散齊於外。","zh-Hant"]]},{"id":"li-ji_ch-24_p-2_s-2","passageId":"li-ji_ch-24_p-2","order":2,"canonicalText":"齊之日：思其居處，思其笑語，思其志意，思其所樂，思其所嗜。","chunks":[["齊之日：思其居處，思其笑語，思其志意，思其所樂，思其所嗜。","zh-Hant"]]},{"id":"li-ji_ch-24_p-2_s-3","passageId":"li-ji_ch-24_p-2","order":3,"canonicalText":"齊三日，乃見其所為齊者。","chunks":[["齊三日，乃見其所為齊者。","zh-Hant"]]},{"id":"li-ji_ch-24_p-3_s-1","passageId":"li-ji_ch-24_p-3","order":1,"canonicalText":"祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞乎其容聲，出戶而聽，愾然必有聞乎其嘆息之聲。","chunks":[["祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞乎其容聲，出戶而聽，愾然必有聞乎其嘆息之聲。","zh-Hant"]]},{"id":"li-ji_ch-24_p-4_s-1","passageId":"li-ji_ch-24_p-4","order":1,"canonicalText":"是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜欲不忘乎心。","chunks":[["是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜欲不忘乎心。","zh-Hant"]]},{"id":"li-ji_ch-24_p-4_s-2","passageId":"li-ji_ch-24_p-4","order":2,"canonicalText":"致愛則存，致愨則著。","chunks":[["致愛則存，致愨則著。","zh-Hant"]]},{"id":"li-ji_ch-24_p-4_s-3","passageId":"li-ji_ch-24_p-4","order":3,"canonicalText":"著存不忘乎心，夫安得不敬乎？","chunks":[["著存不忘乎心，夫安得不敬乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-5_s-1","passageId":"li-ji_ch-24_p-5","order":1,"canonicalText":"君子生則敬養，死則敬享，思終身弗辱也。","chunks":[["君子生則敬養，死則敬享，思終身弗辱也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-5_s-2","passageId":"li-ji_ch-24_p-5","order":2,"canonicalText":"君子有終身之喪，忌日之謂也。","chunks":[["君子有終身之喪，忌日之謂也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-5_s-3","passageId":"li-ji_ch-24_p-5","order":3,"canonicalText":"忌日不用，非不祥也。","chunks":[["忌日不用，非不祥也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-5_s-4","passageId":"li-ji_ch-24_p-5","order":4,"canonicalText":"言夫日，志有所至，而不敢盡其私也。","chunks":[["言夫日，志有所至，而不敢盡其私也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-1","passageId":"li-ji_ch-24_p-6","order":1,"canonicalText":"唯聖人為能饗帝，孝子為能饗親。","chunks":[["唯聖人為能饗帝，孝子為能饗親。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-2","passageId":"li-ji_ch-24_p-6","order":2,"canonicalText":"饗者，鄉也。","chunks":[["饗者，鄉也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-3","passageId":"li-ji_ch-24_p-6","order":3,"canonicalText":"鄉之，然後能饗焉。","chunks":[["鄉之，然後能饗焉。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-4","passageId":"li-ji_ch-24_p-6","order":4,"canonicalText":"是故孝子臨尸而不怍。","chunks":[["是故孝子臨尸而不怍。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-5","passageId":"li-ji_ch-24_p-6","order":5,"canonicalText":"君牽牲，夫人奠盎。","chunks":[["君牽牲，夫人奠盎。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-6","passageId":"li-ji_ch-24_p-6","order":6,"canonicalText":"君獻尸，夫人薦豆。","chunks":[["君獻尸，夫人薦豆。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-7","passageId":"li-ji_ch-24_p-6","order":7,"canonicalText":"卿大夫相君，命婦相夫人。","chunks":[["卿大夫相君，命婦相夫人。","zh-Hant"]]},{"id":"li-ji_ch-24_p-6_s-8","passageId":"li-ji_ch-24_p-6","order":8,"canonicalText":"齊齊乎其敬也，愉愉乎其忠也，勿勿諸其欲其饗之也。","chunks":[["齊齊乎其敬也，愉愉乎其忠也，勿勿諸其欲其饗之也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-1","passageId":"li-ji_ch-24_p-7","order":1,"canonicalText":"文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，稱諱如見親。","chunks":[["文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，稱諱如見親。","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-2","passageId":"li-ji_ch-24_p-7","order":2,"canonicalText":"祀之忠也，如見親之所愛，如欲色然；","chunks":[["祀之忠也，如見親之所愛，如欲色然；","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-3","passageId":"li-ji_ch-24_p-7","order":3,"canonicalText":"其文王與？","chunks":[["其文王與？","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-4","passageId":"li-ji_ch-24_p-7","order":4,"canonicalText":"《詩》云：「明發不寐，有懷二人。","chunks":[["《詩》云：「明發不寐，有懷二人。","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-5","passageId":"li-ji_ch-24_p-7","order":5,"canonicalText":"」文王之詩也。","chunks":[["」文王之詩也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-6","passageId":"li-ji_ch-24_p-7","order":6,"canonicalText":"祭之明日，明發不寐，饗而致之，又從而思之。","chunks":[["祭之明日，明發不寐，饗而致之，又從而思之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-7","passageId":"li-ji_ch-24_p-7","order":7,"canonicalText":"祭之日，樂與哀半；","chunks":[["祭之日，樂與哀半；","zh-Hant"]]},{"id":"li-ji_ch-24_p-7_s-8","passageId":"li-ji_ch-24_p-7","order":8,"canonicalText":"饗之必樂，已至必哀。","chunks":[["饗之必樂，已至必哀。","zh-Hant"]]},{"id":"li-ji_ch-24_p-8_s-1","passageId":"li-ji_ch-24_p-8","order":1,"canonicalText":"仲尼嘗，奉薦而進其親也愨，其行趨趨以數。","chunks":[["仲尼嘗，奉薦而進其親也愨，其行趨趨以數。","zh-Hant"]]},{"id":"li-ji_ch-24_p-8_s-2","passageId":"li-ji_ch-24_p-8","order":2,"canonicalText":"已祭，子贛問曰：「子之言祭，濟濟漆漆然；","chunks":[["已祭，子贛問曰：「子之言祭，濟濟漆漆然；","zh-Hant"]]},{"id":"li-ji_ch-24_p-8_s-3","passageId":"li-ji_ch-24_p-8","order":3,"canonicalText":"今子之祭，無濟濟漆漆，何也？","chunks":[["今子之祭，無濟濟漆漆，何也？","zh-Hant"]]},{"id":"li-ji_ch-24_p-8_s-4","passageId":"li-ji_ch-24_p-8","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-1","passageId":"li-ji_ch-24_p-9","order":1,"canonicalText":"子曰：「濟濟者，容也遠也；","chunks":[["子曰：「濟濟者，容也遠也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-2","passageId":"li-ji_ch-24_p-9","order":2,"canonicalText":"漆漆者，容也自反也。","chunks":[["漆漆者，容也自反也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-3","passageId":"li-ji_ch-24_p-9","order":3,"canonicalText":"容以遠，若容以自反也，夫何神明之及交，夫何濟濟漆漆之有乎？","chunks":[["容以遠，若容以自反也，夫何神明之及交，夫何濟濟漆漆之有乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-4","passageId":"li-ji_ch-24_p-9","order":4,"canonicalText":"反饋，樂成，薦其薦俎，序其禮樂，備其百官。","chunks":[["反饋，樂成，薦其薦俎，序其禮樂，備其百官。","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-5","passageId":"li-ji_ch-24_p-9","order":5,"canonicalText":"君子致其濟濟漆漆，夫何慌惚之有乎？","chunks":[["君子致其濟濟漆漆，夫何慌惚之有乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-6","passageId":"li-ji_ch-24_p-9","order":6,"canonicalText":"夫言，豈一端而已？","chunks":[["夫言，豈一端而已？","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-7","passageId":"li-ji_ch-24_p-9","order":7,"canonicalText":"夫各有所當也。","chunks":[["夫各有所當也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-9_s-8","passageId":"li-ji_ch-24_p-9","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-1","passageId":"li-ji_ch-24_p-10","order":1,"canonicalText":"孝子將祭，慮事不可以不豫；","chunks":[["孝子將祭，慮事不可以不豫；","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-2","passageId":"li-ji_ch-24_p-10","order":2,"canonicalText":"比時具物，不可以不備；","chunks":[["比時具物，不可以不備；","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-3","passageId":"li-ji_ch-24_p-10","order":3,"canonicalText":"虛中以治之。","chunks":[["虛中以治之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-4","passageId":"li-ji_ch-24_p-10","order":4,"canonicalText":"宮室既修，墻屋既設，百物既備，夫婦齊戒沐浴，盛服奉承而進之，洞洞乎，屬屬乎，如弗勝，如將失之，其孝敬之心至也與！","chunks":[["宮室既修，墻屋既設，百物既備，夫婦齊戒沐浴，盛服奉承而進之，洞洞乎，屬屬乎，如弗勝，如將失之，其孝敬之心至也與！","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-5","passageId":"li-ji_ch-24_p-10","order":5,"canonicalText":"薦其薦俎，序其禮樂，備其百官，奉承而進之。","chunks":[["薦其薦俎，序其禮樂，備其百官，奉承而進之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-6","passageId":"li-ji_ch-24_p-10","order":6,"canonicalText":"於是諭其志意，以其恍惚以與神明交，庶或饗之。","chunks":[["於是諭其志意，以其恍惚以與神明交，庶或饗之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-10_s-7","passageId":"li-ji_ch-24_p-10","order":7,"canonicalText":"「庶或饗之」，孝子之志也。","chunks":[["「庶或饗之」，孝子之志也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-11_s-1","passageId":"li-ji_ch-24_p-11","order":1,"canonicalText":"孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉，盡其禮而不過失焉。","chunks":[["孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉，盡其禮而不過失焉。","zh-Hant"]]},{"id":"li-ji_ch-24_p-11_s-2","passageId":"li-ji_ch-24_p-11","order":2,"canonicalText":"進退必敬，如親聽命，則或使之也。","chunks":[["進退必敬，如親聽命，則或使之也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-1","passageId":"li-ji_ch-24_p-12","order":1,"canonicalText":"孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其薦之也敬以欲；","chunks":[["孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其薦之也敬以欲；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-2","passageId":"li-ji_ch-24_p-12","order":2,"canonicalText":"退而立，如將受命；","chunks":[["退而立，如將受命；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-3","passageId":"li-ji_ch-24_p-12","order":3,"canonicalText":"已徹而退，敬齊之色不絕於面。","chunks":[["已徹而退，敬齊之色不絕於面。","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-4","passageId":"li-ji_ch-24_p-12","order":4,"canonicalText":"孝子之祭也，立而不詘，固也；","chunks":[["孝子之祭也，立而不詘，固也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-5","passageId":"li-ji_ch-24_p-12","order":5,"canonicalText":"進而不愉，疏也；","chunks":[["進而不愉，疏也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-6","passageId":"li-ji_ch-24_p-12","order":6,"canonicalText":"薦而不欲，不愛也；","chunks":[["薦而不欲，不愛也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-7","passageId":"li-ji_ch-24_p-12","order":7,"canonicalText":"退立而不如受命，敖也；","chunks":[["退立而不如受命，敖也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-8","passageId":"li-ji_ch-24_p-12","order":8,"canonicalText":"已徹而退，無敬齊之色，而忘本也。","chunks":[["已徹而退，無敬齊之色，而忘本也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-12_s-9","passageId":"li-ji_ch-24_p-12","order":9,"canonicalText":"如是而祭，失之矣。","chunks":[["如是而祭，失之矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-13_s-1","passageId":"li-ji_ch-24_p-13","order":1,"canonicalText":"孝子之有深愛者，必有和氣；","chunks":[["孝子之有深愛者，必有和氣；","zh-Hant"]]},{"id":"li-ji_ch-24_p-13_s-2","passageId":"li-ji_ch-24_p-13","order":2,"canonicalText":"有和氣者，必有愉色；","chunks":[["有和氣者，必有愉色；","zh-Hant"]]},{"id":"li-ji_ch-24_p-13_s-3","passageId":"li-ji_ch-24_p-13","order":3,"canonicalText":"有愉色者，必有婉容。","chunks":[["有愉色者，必有婉容。","zh-Hant"]]},{"id":"li-ji_ch-24_p-13_s-4","passageId":"li-ji_ch-24_p-13","order":4,"canonicalText":"孝子如執玉，如奉盈，洞洞屬屬然，如弗勝，如將失之。","chunks":[["孝子如執玉，如奉盈，洞洞屬屬然，如弗勝，如將失之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-13_s-5","passageId":"li-ji_ch-24_p-13","order":5,"canonicalText":"嚴威儼恪，非所以事親也，成人之道也。","chunks":[["嚴威儼恪，非所以事親也，成人之道也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-1","passageId":"li-ji_ch-24_p-14","order":1,"canonicalText":"先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼。","chunks":[["先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-2","passageId":"li-ji_ch-24_p-14","order":2,"canonicalText":"此五者，先王之所以定天下也。","chunks":[["此五者，先王之所以定天下也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-3","passageId":"li-ji_ch-24_p-14","order":3,"canonicalText":"貴有德，何為也？","chunks":[["貴有德，何為也？","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-4","passageId":"li-ji_ch-24_p-14","order":4,"canonicalText":"為其近於道也。","chunks":[["為其近於道也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-5","passageId":"li-ji_ch-24_p-14","order":5,"canonicalText":"貴貴，為其近於君也。","chunks":[["貴貴，為其近於君也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-6","passageId":"li-ji_ch-24_p-14","order":6,"canonicalText":"貴老，為其近於親也。","chunks":[["貴老，為其近於親也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-7","passageId":"li-ji_ch-24_p-14","order":7,"canonicalText":"敬長，為其近於兄也。","chunks":[["敬長，為其近於兄也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-14_s-8","passageId":"li-ji_ch-24_p-14","order":8,"canonicalText":"慈幼，為其近於子也。","chunks":[["慈幼，為其近於子也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-15_s-1","passageId":"li-ji_ch-24_p-15","order":1,"canonicalText":"是故至孝近乎王，至弟近乎霸。","chunks":[["是故至孝近乎王，至弟近乎霸。","zh-Hant"]]},{"id":"li-ji_ch-24_p-15_s-2","passageId":"li-ji_ch-24_p-15","order":2,"canonicalText":"至孝近乎王，雖天子，必有父；","chunks":[["至孝近乎王，雖天子，必有父；","zh-Hant"]]},{"id":"li-ji_ch-24_p-15_s-3","passageId":"li-ji_ch-24_p-15","order":3,"canonicalText":"至弟近乎霸，雖諸侯，必有兄。","chunks":[["至弟近乎霸，雖諸侯，必有兄。","zh-Hant"]]},{"id":"li-ji_ch-24_p-15_s-4","passageId":"li-ji_ch-24_p-15","order":4,"canonicalText":"先王之教，因而弗改，所以領天下國家也。","chunks":[["先王之教，因而弗改，所以領天下國家也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-1","passageId":"li-ji_ch-24_p-16","order":1,"canonicalText":"子曰：「立愛自親始，教民睦也。","chunks":[["子曰：「立愛自親始，教民睦也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-2","passageId":"li-ji_ch-24_p-16","order":2,"canonicalText":"立教自長始，教民順也。","chunks":[["立教自長始，教民順也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-3","passageId":"li-ji_ch-24_p-16","order":3,"canonicalText":"教以慈睦，而民貴有親；","chunks":[["教以慈睦，而民貴有親；","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-4","passageId":"li-ji_ch-24_p-16","order":4,"canonicalText":"教以敬長，而民貴用命。","chunks":[["教以敬長，而民貴用命。","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-5","passageId":"li-ji_ch-24_p-16","order":5,"canonicalText":"孝以事親，順以聽命，錯諸天下，無所不行。","chunks":[["孝以事親，順以聽命，錯諸天下，無所不行。","zh-Hant"]]},{"id":"li-ji_ch-24_p-16_s-6","passageId":"li-ji_ch-24_p-16","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-17_s-1","passageId":"li-ji_ch-24_p-17","order":1,"canonicalText":"郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也。","chunks":[["郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-18_s-1","passageId":"li-ji_ch-24_p-18","order":1,"canonicalText":"祭之日，君牽牲，穆答君，卿大夫序從。","chunks":[["祭之日，君牽牲，穆答君，卿大夫序從。","zh-Hant"]]},{"id":"li-ji_ch-24_p-18_s-2","passageId":"li-ji_ch-24_p-18","order":2,"canonicalText":"既入廟門，麗于碑，卿大夫袒，而毛牛尚耳，鸞刀以刲，取膟菺，乃退。","chunks":[["既入廟門，麗于碑，卿大夫袒，而毛牛尚耳，鸞刀以刲，取膟菺，乃退。","zh-Hant"]]},{"id":"li-ji_ch-24_p-18_s-3","passageId":"li-ji_ch-24_p-18","order":3,"canonicalText":"爓祭，祭腥而退，敬之至也。","chunks":[["爓祭，祭腥而退，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-1","passageId":"li-ji_ch-24_p-19","order":1,"canonicalText":"郊之祭，大報天而主日，配以月。","chunks":[["郊之祭，大報天而主日，配以月。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-2","passageId":"li-ji_ch-24_p-19","order":2,"canonicalText":"夏后氏祭其闇，殷人祭其陽，周人祭日，以朝及闇。","chunks":[["夏后氏祭其闇，殷人祭其陽，周人祭日，以朝及闇。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-3","passageId":"li-ji_ch-24_p-19","order":3,"canonicalText":"祭日於壇，祭月於坎，以別幽明，以制上下。","chunks":[["祭日於壇，祭月於坎，以別幽明，以制上下。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-4","passageId":"li-ji_ch-24_p-19","order":4,"canonicalText":"祭日於東，祭月於西，以別外內，以端其位。","chunks":[["祭日於東，祭月於西，以別外內，以端其位。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-5","passageId":"li-ji_ch-24_p-19","order":5,"canonicalText":"日出於東，月生於西。","chunks":[["日出於東，月生於西。","zh-Hant"]]},{"id":"li-ji_ch-24_p-19_s-6","passageId":"li-ji_ch-24_p-19","order":6,"canonicalText":"陰陽長短，終始相巡，以致天下之和。","chunks":[["陰陽長短，終始相巡，以致天下之和。","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-1","passageId":"li-ji_ch-24_p-20","order":1,"canonicalText":"天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓也。","chunks":[["天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-2","passageId":"li-ji_ch-24_p-20","order":2,"canonicalText":"致反始，以厚其本也；","chunks":[["致反始，以厚其本也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-3","passageId":"li-ji_ch-24_p-20","order":3,"canonicalText":"致鬼神，以尊上也；","chunks":[["致鬼神，以尊上也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-4","passageId":"li-ji_ch-24_p-20","order":4,"canonicalText":"致物用，以立民紀也。","chunks":[["致物用，以立民紀也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-5","passageId":"li-ji_ch-24_p-20","order":5,"canonicalText":"致義，則上下不悖逆矣。","chunks":[["致義，則上下不悖逆矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-6","passageId":"li-ji_ch-24_p-20","order":6,"canonicalText":"致讓，以去爭也。","chunks":[["致讓，以去爭也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-20_s-7","passageId":"li-ji_ch-24_p-20","order":7,"canonicalText":"合此五者，以治天下之禮也，雖有奇邪，而不治者則微矣。","chunks":[["合此五者，以治天下之禮也，雖有奇邪，而不治者則微矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-1","passageId":"li-ji_ch-24_p-21","order":1,"canonicalText":"宰我曰：「吾聞鬼神之名，而不知其所謂。","chunks":[["宰我曰：「吾聞鬼神之名，而不知其所謂。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-2","passageId":"li-ji_ch-24_p-21","order":2,"canonicalText":"」子曰：「氣也者，神之盛也；","chunks":[["」子曰：「氣也者，神之盛也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-3","passageId":"li-ji_ch-24_p-21","order":3,"canonicalText":"魄也者，鬼之盛也；","chunks":[["魄也者，鬼之盛也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-4","passageId":"li-ji_ch-24_p-21","order":4,"canonicalText":"合鬼與神，教之至也。","chunks":[["合鬼與神，教之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-5","passageId":"li-ji_ch-24_p-21","order":5,"canonicalText":"眾生必死，死必歸土：此之謂鬼。","chunks":[["眾生必死，死必歸土：此之謂鬼。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-6","passageId":"li-ji_ch-24_p-21","order":6,"canonicalText":"骨肉斃於下，陰為野土；","chunks":[["骨肉斃於下，陰為野土；","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-7","passageId":"li-ji_ch-24_p-21","order":7,"canonicalText":"其氣發揚于上，為昭明，焄蒿，凄愴，此百物之精也，神之著也。","chunks":[["其氣發揚于上，為昭明，焄蒿，凄愴，此百物之精也，神之著也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-8","passageId":"li-ji_ch-24_p-21","order":8,"canonicalText":"因物之精，制為之極，明命鬼神，以為黔首則。","chunks":[["因物之精，制為之極，明命鬼神，以為黔首則。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-9","passageId":"li-ji_ch-24_p-21","order":9,"canonicalText":"百眾以畏，萬民以服。","chunks":[["百眾以畏，萬民以服。","zh-Hant"]]},{"id":"li-ji_ch-24_p-21_s-10","passageId":"li-ji_ch-24_p-21","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-1","passageId":"li-ji_ch-24_p-22","order":1,"canonicalText":"聖人以是為未足也，筑為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘其所由生也。","chunks":[["聖人以是為未足也，筑為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘其所由生也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-2","passageId":"li-ji_ch-24_p-22","order":2,"canonicalText":"眾之服自此，故聽且速也。","chunks":[["眾之服自此，故聽且速也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-3","passageId":"li-ji_ch-24_p-22","order":3,"canonicalText":"二端既立，報以二禮。","chunks":[["二端既立，報以二禮。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-4","passageId":"li-ji_ch-24_p-22","order":4,"canonicalText":"建設朝事，燔燎膻薌，見以蕭光，以報氣也。","chunks":[["建設朝事，燔燎膻薌，見以蕭光，以報氣也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-5","passageId":"li-ji_ch-24_p-22","order":5,"canonicalText":"此教眾反始也。","chunks":[["此教眾反始也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-6","passageId":"li-ji_ch-24_p-22","order":6,"canonicalText":"薦黍稷，羞肝肺首心，見間以俠甒，加以郁鬯，以報魄也。","chunks":[["薦黍稷，羞肝肺首心，見間以俠甒，加以郁鬯，以報魄也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-22_s-7","passageId":"li-ji_ch-24_p-22","order":7,"canonicalText":"教民相愛，上下用情，禮之至也。","chunks":[["教民相愛，上下用情，禮之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-23_s-1","passageId":"li-ji_ch-24_p-23","order":1,"canonicalText":"君子反古復始，不忘其所由生也，是以致其敬，發其情，竭力從事，以報其親，不敢弗盡也。","chunks":[["君子反古復始，不忘其所由生也，是以致其敬，發其情，竭力從事，以報其親，不敢弗盡也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-23_s-2","passageId":"li-ji_ch-24_p-23","order":2,"canonicalText":"是故昔者天子為藉千畝，冕而朱紘，躬秉耒。","chunks":[["是故昔者天子為藉千畝，冕而朱紘，躬秉耒。","zh-Hant"]]},{"id":"li-ji_ch-24_p-23_s-3","passageId":"li-ji_ch-24_p-23","order":3,"canonicalText":"諸侯為藉百畝，冕而青紘，躬秉耒，以事天地、山川、社稷、先古，以為醴酪齊盛，於是乎取之，敬之至也。","chunks":[["諸侯為藉百畝，冕而青紘，躬秉耒，以事天地、山川、社稷、先古，以為醴酪齊盛，於是乎取之，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-24_s-1","passageId":"li-ji_ch-24_p-24","order":1,"canonicalText":"古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之。","chunks":[["古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-24_s-2","passageId":"li-ji_ch-24_p-24","order":2,"canonicalText":"犧牷祭牲，必於是取之，敬之至也。","chunks":[["犧牷祭牲，必於是取之，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-24_s-3","passageId":"li-ji_ch-24_p-24","order":3,"canonicalText":"君召牛，納而視之，擇其毛而卜之，吉，然後養之。","chunks":[["君召牛，納而視之，擇其毛而卜之，吉，然後養之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-24_s-4","passageId":"li-ji_ch-24_p-24","order":4,"canonicalText":"君皮弁素積，朔月，月半，君巡牲，所以致力，孝之至也。","chunks":[["君皮弁素積，朔月，月半，君巡牲，所以致力，孝之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-1","passageId":"li-ji_ch-24_p-25","order":1,"canonicalText":"古者天子、諸侯必有公桑、蠶室，近川而為之。","chunks":[["古者天子、諸侯必有公桑、蠶室，近川而為之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-2","passageId":"li-ji_ch-24_p-25","order":2,"canonicalText":"筑宮仞有三尺，棘墻而外閉之。","chunks":[["筑宮仞有三尺，棘墻而外閉之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-3","passageId":"li-ji_ch-24_p-25","order":3,"canonicalText":"及大昕之朝，君皮弁素積，卜三宮之夫人世婦之吉者，使入蠶于蠶室，奉種浴于川；","chunks":[["及大昕之朝，君皮弁素積，卜三宮之夫人世婦之吉者，使入蠶于蠶室，奉種浴于川；","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-4","passageId":"li-ji_ch-24_p-25","order":4,"canonicalText":"桑於公桑，風戾以食之。","chunks":[["桑於公桑，風戾以食之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-5","passageId":"li-ji_ch-24_p-25","order":5,"canonicalText":"歲既殫矣，世婦卒蠶，奉繭以示于君，遂獻繭于夫人。","chunks":[["歲既殫矣，世婦卒蠶，奉繭以示于君，遂獻繭于夫人。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-6","passageId":"li-ji_ch-24_p-25","order":6,"canonicalText":"夫人曰：「此所以為君服與？","chunks":[["夫人曰：「此所以為君服與？","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-7","passageId":"li-ji_ch-24_p-25","order":7,"canonicalText":"」遂副褘而受之，因少牢以禮之。","chunks":[["」遂副褘而受之，因少牢以禮之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-8","passageId":"li-ji_ch-24_p-25","order":8,"canonicalText":"古之獻繭者，其率用此與！","chunks":[["古之獻繭者，其率用此與！","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-9","passageId":"li-ji_ch-24_p-25","order":9,"canonicalText":"及良日，夫人繅，三盆手，遂布于三宮夫人世婦之吉者使繅；","chunks":[["及良日，夫人繅，三盆手，遂布于三宮夫人世婦之吉者使繅；","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-10","passageId":"li-ji_ch-24_p-25","order":10,"canonicalText":"遂朱綠之，玄黃之，以為黼黻文章。","chunks":[["遂朱綠之，玄黃之，以為黼黻文章。","zh-Hant"]]},{"id":"li-ji_ch-24_p-25_s-11","passageId":"li-ji_ch-24_p-25","order":11,"canonicalText":"服既成，君服以祀先王先公，敬之至也。","chunks":[["服既成，君服以祀先王先公，敬之至也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-1","passageId":"li-ji_ch-24_p-26","order":1,"canonicalText":"君子曰：禮樂不可斯須去身。","chunks":[["君子曰：禮樂不可斯須去身。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-2","passageId":"li-ji_ch-24_p-26","order":2,"canonicalText":"致樂以治心，則易直子諒之心，油然生矣。","chunks":[["致樂以治心，則易直子諒之心，油然生矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-3","passageId":"li-ji_ch-24_p-26","order":3,"canonicalText":"易直子諒之心生則樂，樂則安，安則久，久則天，天則神。","chunks":[["易直子諒之心生則樂，樂則安，安則久，久則天，天則神。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-4","passageId":"li-ji_ch-24_p-26","order":4,"canonicalText":"天則不言而信，神則不怒而威。","chunks":[["天則不言而信，神則不怒而威。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-5","passageId":"li-ji_ch-24_p-26","order":5,"canonicalText":"致樂以治心者也。","chunks":[["致樂以治心者也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-6","passageId":"li-ji_ch-24_p-26","order":6,"canonicalText":"致禮以治躬則莊敬，莊敬則嚴威。","chunks":[["致禮以治躬則莊敬，莊敬則嚴威。","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-7","passageId":"li-ji_ch-24_p-26","order":7,"canonicalText":"心中斯須不和不樂，而鄙詐之心入之矣；","chunks":[["心中斯須不和不樂，而鄙詐之心入之矣；","zh-Hant"]]},{"id":"li-ji_ch-24_p-26_s-8","passageId":"li-ji_ch-24_p-26","order":8,"canonicalText":"外貌斯須不莊不敬，而慢易之心入之矣。","chunks":[["外貌斯須不莊不敬，而慢易之心入之矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-1","passageId":"li-ji_ch-24_p-27","order":1,"canonicalText":"故樂也者，動於內者也，禮也者，動於外者也。","chunks":[["故樂也者，動於內者也，禮也者，動於外者也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-2","passageId":"li-ji_ch-24_p-27","order":2,"canonicalText":"樂極和，禮極順。","chunks":[["樂極和，禮極順。","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-3","passageId":"li-ji_ch-24_p-27","order":3,"canonicalText":"內和而外順，則民瞻其顏色而不與爭也；","chunks":[["內和而外順，則民瞻其顏色而不與爭也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-4","passageId":"li-ji_ch-24_p-27","order":4,"canonicalText":"望其容貌，而眾不生慢易焉。","chunks":[["望其容貌，而眾不生慢易焉。","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-5","passageId":"li-ji_ch-24_p-27","order":5,"canonicalText":"故德輝動乎內，而民莫不承聽；","chunks":[["故德輝動乎內，而民莫不承聽；","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-6","passageId":"li-ji_ch-24_p-27","order":6,"canonicalText":"理發乎外，而眾莫不承順。","chunks":[["理發乎外，而眾莫不承順。","zh-Hant"]]},{"id":"li-ji_ch-24_p-27_s-7","passageId":"li-ji_ch-24_p-27","order":7,"canonicalText":"故曰：致禮樂之道，而天下塞焉，舉而措之無難矣。","chunks":[["故曰：致禮樂之道，而天下塞焉，舉而措之無難矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-1","passageId":"li-ji_ch-24_p-28","order":1,"canonicalText":"樂也者，動於內者也；","chunks":[["樂也者，動於內者也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-2","passageId":"li-ji_ch-24_p-28","order":2,"canonicalText":"禮也者，動於外者也。","chunks":[["禮也者，動於外者也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-3","passageId":"li-ji_ch-24_p-28","order":3,"canonicalText":"故禮主其減，樂主其盈。","chunks":[["故禮主其減，樂主其盈。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-4","passageId":"li-ji_ch-24_p-28","order":4,"canonicalText":"禮減而進，以進為文；","chunks":[["禮減而進，以進為文；","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-5","passageId":"li-ji_ch-24_p-28","order":5,"canonicalText":"樂盈而反，以反為文。","chunks":[["樂盈而反，以反為文。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-6","passageId":"li-ji_ch-24_p-28","order":6,"canonicalText":"禮減而不進則銷，樂盈而不反則放。","chunks":[["禮減而不進則銷，樂盈而不反則放。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-7","passageId":"li-ji_ch-24_p-28","order":7,"canonicalText":"故禮有報而樂有反。","chunks":[["故禮有報而樂有反。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-8","passageId":"li-ji_ch-24_p-28","order":8,"canonicalText":"禮得其報則樂，樂得其反則安。","chunks":[["禮得其報則樂，樂得其反則安。","zh-Hant"]]},{"id":"li-ji_ch-24_p-28_s-9","passageId":"li-ji_ch-24_p-28","order":9,"canonicalText":"禮之報，樂之反，其義一也。","chunks":[["禮之報，樂之反，其義一也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-1","passageId":"li-ji_ch-24_p-29","order":1,"canonicalText":"曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養。","chunks":[["曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養。","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-2","passageId":"li-ji_ch-24_p-29","order":2,"canonicalText":"」公明儀問於曾子曰：「夫子可以為孝乎？","chunks":[["」公明儀問於曾子曰：「夫子可以為孝乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-3","passageId":"li-ji_ch-24_p-29","order":3,"canonicalText":"」曾子曰：「是何言與！","chunks":[["」曾子曰：「是何言與！","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-4","passageId":"li-ji_ch-24_p-29","order":4,"canonicalText":"是何言與！","chunks":[["是何言與！","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-5","passageId":"li-ji_ch-24_p-29","order":5,"canonicalText":"君子之所為孝者：先意承志，諭父母於道。","chunks":[["君子之所為孝者：先意承志，諭父母於道。","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-6","passageId":"li-ji_ch-24_p-29","order":6,"canonicalText":"參，直養者也，安能為孝乎？","chunks":[["參，直養者也，安能為孝乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-29_s-7","passageId":"li-ji_ch-24_p-29","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-1","passageId":"li-ji_ch-24_p-30","order":1,"canonicalText":"曾子曰：「身也者，父母之遺體也。","chunks":[["曾子曰：「身也者，父母之遺體也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-2","passageId":"li-ji_ch-24_p-30","order":2,"canonicalText":"行父母之遺體，敢不敬乎？","chunks":[["行父母之遺體，敢不敬乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-3","passageId":"li-ji_ch-24_p-30","order":3,"canonicalText":"居處不莊，非孝也；","chunks":[["居處不莊，非孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-4","passageId":"li-ji_ch-24_p-30","order":4,"canonicalText":"事君不忠，非孝也；","chunks":[["事君不忠，非孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-5","passageId":"li-ji_ch-24_p-30","order":5,"canonicalText":"蒞官不敬，非孝也；","chunks":[["蒞官不敬，非孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-6","passageId":"li-ji_ch-24_p-30","order":6,"canonicalText":"朋友不信，非孝也；","chunks":[["朋友不信，非孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-7","passageId":"li-ji_ch-24_p-30","order":7,"canonicalText":"戰陳無勇，非孝也；","chunks":[["戰陳無勇，非孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-30_s-8","passageId":"li-ji_ch-24_p-30","order":8,"canonicalText":"五者不遂，災及於親，敢不敬乎？","chunks":[["五者不遂，災及於親，敢不敬乎？","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-1","passageId":"li-ji_ch-24_p-31","order":1,"canonicalText":"亨孰膻薌，嘗而薦之，非孝也，養也。","chunks":[["亨孰膻薌，嘗而薦之，非孝也，養也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-2","passageId":"li-ji_ch-24_p-31","order":2,"canonicalText":"君子之所謂孝也者，國人稱愿然曰：『幸哉有子！","chunks":[["君子之所謂孝也者，國人稱愿然曰：『幸哉有子！","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-3","passageId":"li-ji_ch-24_p-31","order":3,"canonicalText":"』如此，所謂孝也已。","chunks":[["』如此，所謂孝也已。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-4","passageId":"li-ji_ch-24_p-31","order":4,"canonicalText":"眾之本教曰孝，其行曰養。","chunks":[["眾之本教曰孝，其行曰養。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-5","passageId":"li-ji_ch-24_p-31","order":5,"canonicalText":"養，可能也，敬為難；","chunks":[["養，可能也，敬為難；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-6","passageId":"li-ji_ch-24_p-31","order":6,"canonicalText":"敬，可能也，安為難；","chunks":[["敬，可能也，安為難；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-7","passageId":"li-ji_ch-24_p-31","order":7,"canonicalText":"安，可能也，卒為難。","chunks":[["安，可能也，卒為難。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-8","passageId":"li-ji_ch-24_p-31","order":8,"canonicalText":"父母既沒，慎行其身，不遺父母惡名，可謂能終矣。","chunks":[["父母既沒，慎行其身，不遺父母惡名，可謂能終矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-9","passageId":"li-ji_ch-24_p-31","order":9,"canonicalText":"仁者，仁此者也；","chunks":[["仁者，仁此者也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-10","passageId":"li-ji_ch-24_p-31","order":10,"canonicalText":"禮者，履此者也；","chunks":[["禮者，履此者也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-11","passageId":"li-ji_ch-24_p-31","order":11,"canonicalText":"義者，宜此者也；","chunks":[["義者，宜此者也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-12","passageId":"li-ji_ch-24_p-31","order":12,"canonicalText":"信者，信此者也；","chunks":[["信者，信此者也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-13","passageId":"li-ji_ch-24_p-31","order":13,"canonicalText":"強者，強此者也。","chunks":[["強者，強此者也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-14","passageId":"li-ji_ch-24_p-31","order":14,"canonicalText":"樂自順此生，刑自反此作。","chunks":[["樂自順此生，刑自反此作。","zh-Hant"]]},{"id":"li-ji_ch-24_p-31_s-15","passageId":"li-ji_ch-24_p-31","order":15,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-32_s-1","passageId":"li-ji_ch-24_p-32","order":1,"canonicalText":"曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸後世而無朝夕，推而放諸東海而準，推而放諸西海而準，推而放諸南海而準，推而放諸北海而準。","chunks":[["曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸後世而無朝夕，推而放諸東海而準，推而放諸西海而準，推而放諸南海而準，推而放諸北海而準。","zh-Hant"]]},{"id":"li-ji_ch-24_p-32_s-2","passageId":"li-ji_ch-24_p-32","order":2,"canonicalText":"《詩》云：『自西自東，自南自北，無思不服。","chunks":[["《詩》云：『自西自東，自南自北，無思不服。","zh-Hant"]]},{"id":"li-ji_ch-24_p-32_s-3","passageId":"li-ji_ch-24_p-32","order":3,"canonicalText":"』此之謂也。","chunks":[["』此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-32_s-4","passageId":"li-ji_ch-24_p-32","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-1","passageId":"li-ji_ch-24_p-33","order":1,"canonicalText":"曾子曰：「樹木以時伐焉，禽獸以時殺焉。","chunks":[["曾子曰：「樹木以時伐焉，禽獸以時殺焉。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-2","passageId":"li-ji_ch-24_p-33","order":2,"canonicalText":"夫子曰：『斷一樹，殺一獸，不以其時，非孝也。","chunks":[["夫子曰：『斷一樹，殺一獸，不以其時，非孝也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-3","passageId":"li-ji_ch-24_p-33","order":3,"canonicalText":"』孝有三：小孝用力，中孝用勞，大孝不匱。","chunks":[["』孝有三：小孝用力，中孝用勞，大孝不匱。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-4","passageId":"li-ji_ch-24_p-33","order":4,"canonicalText":"思慈愛忘勞，可謂用力矣。","chunks":[["思慈愛忘勞，可謂用力矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-5","passageId":"li-ji_ch-24_p-33","order":5,"canonicalText":"尊仁安義，可謂用勞矣。","chunks":[["尊仁安義，可謂用勞矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-6","passageId":"li-ji_ch-24_p-33","order":6,"canonicalText":"博施備物，可謂不匱矣。","chunks":[["博施備物，可謂不匱矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-7","passageId":"li-ji_ch-24_p-33","order":7,"canonicalText":"父母愛之，嘉而弗忘；","chunks":[["父母愛之，嘉而弗忘；","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-8","passageId":"li-ji_ch-24_p-33","order":8,"canonicalText":"父母惡之，懼而無怨；","chunks":[["父母惡之，懼而無怨；","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-9","passageId":"li-ji_ch-24_p-33","order":9,"canonicalText":"父母有過，諫而不逆；","chunks":[["父母有過，諫而不逆；","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-10","passageId":"li-ji_ch-24_p-33","order":10,"canonicalText":"父母既沒，必求仁者之粟以祀之。","chunks":[["父母既沒，必求仁者之粟以祀之。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-11","passageId":"li-ji_ch-24_p-33","order":11,"canonicalText":"此之謂禮終。","chunks":[["此之謂禮終。","zh-Hant"]]},{"id":"li-ji_ch-24_p-33_s-12","passageId":"li-ji_ch-24_p-33","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-1","passageId":"li-ji_ch-24_p-34","order":1,"canonicalText":"樂正子春下堂而傷其足，數月不出，猶有憂色。","chunks":[["樂正子春下堂而傷其足，數月不出，猶有憂色。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-2","passageId":"li-ji_ch-24_p-34","order":2,"canonicalText":"門弟子曰：「夫子之足瘳矣，數月不出，猶有憂色，何也？","chunks":[["門弟子曰：「夫子之足瘳矣，數月不出，猶有憂色，何也？","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-3","passageId":"li-ji_ch-24_p-34","order":3,"canonicalText":"」樂正子春曰：「善如爾之問也！","chunks":[["」樂正子春曰：「善如爾之問也！","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-4","passageId":"li-ji_ch-24_p-34","order":4,"canonicalText":"善如爾之問也！","chunks":[["善如爾之問也！","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-5","passageId":"li-ji_ch-24_p-34","order":5,"canonicalText":"吾聞諸曾子，曾子聞諸夫子曰：『天之所生，地之所養，無人為大。","chunks":[["吾聞諸曾子，曾子聞諸夫子曰：『天之所生，地之所養，無人為大。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-6","passageId":"li-ji_ch-24_p-34","order":6,"canonicalText":"』父母全而生之，子全而歸之，可謂孝矣。","chunks":[["』父母全而生之，子全而歸之，可謂孝矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-7","passageId":"li-ji_ch-24_p-34","order":7,"canonicalText":"不虧其體，不辱其身，可謂全矣。","chunks":[["不虧其體，不辱其身，可謂全矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-8","passageId":"li-ji_ch-24_p-34","order":8,"canonicalText":"故君子頃步而弗敢忘孝也。","chunks":[["故君子頃步而弗敢忘孝也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-9","passageId":"li-ji_ch-24_p-34","order":9,"canonicalText":"今予忘孝之道，予是以有憂色也。","chunks":[["今予忘孝之道，予是以有憂色也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-10","passageId":"li-ji_ch-24_p-34","order":10,"canonicalText":"壹舉足而不敢忘父母，壹出言而不敢忘父母。","chunks":[["壹舉足而不敢忘父母，壹出言而不敢忘父母。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-11","passageId":"li-ji_ch-24_p-34","order":11,"canonicalText":"壹舉足而不敢忘父母，是故道而不徑，舟而不游，不敢以先父母之遺體行殆。","chunks":[["壹舉足而不敢忘父母，是故道而不徑，舟而不游，不敢以先父母之遺體行殆。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-12","passageId":"li-ji_ch-24_p-34","order":12,"canonicalText":"壹出言而不敢忘父母，是故惡言不出於口，忿言不反於身。","chunks":[["壹出言而不敢忘父母，是故惡言不出於口，忿言不反於身。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-13","passageId":"li-ji_ch-24_p-34","order":13,"canonicalText":"不辱其身，不羞其親，可謂孝矣。","chunks":[["不辱其身，不羞其親，可謂孝矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-34_s-14","passageId":"li-ji_ch-24_p-34","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-24_p-35_s-1","passageId":"li-ji_ch-24_p-35","order":1,"canonicalText":"昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而尚齒，周人貴親而尚齒。","chunks":[["昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而尚齒，周人貴親而尚齒。","zh-Hant"]]},{"id":"li-ji_ch-24_p-35_s-2","passageId":"li-ji_ch-24_p-35","order":2,"canonicalText":"虞夏殷周，天下之盛王也，未有遺年者。","chunks":[["虞夏殷周，天下之盛王也，未有遺年者。","zh-Hant"]]},{"id":"li-ji_ch-24_p-35_s-3","passageId":"li-ji_ch-24_p-35","order":3,"canonicalText":"年之貴乎天下，久矣；","chunks":[["年之貴乎天下，久矣；","zh-Hant"]]},{"id":"li-ji_ch-24_p-35_s-4","passageId":"li-ji_ch-24_p-35","order":4,"canonicalText":"次乎事親也。","chunks":[["次乎事親也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-36_s-1","passageId":"li-ji_ch-24_p-36","order":1,"canonicalText":"是故朝廷同爵則尚齒。","chunks":[["是故朝廷同爵則尚齒。","zh-Hant"]]},{"id":"li-ji_ch-24_p-36_s-2","passageId":"li-ji_ch-24_p-36","order":2,"canonicalText":"七十杖於朝，君問則席。","chunks":[["七十杖於朝，君問則席。","zh-Hant"]]},{"id":"li-ji_ch-24_p-36_s-3","passageId":"li-ji_ch-24_p-36","order":3,"canonicalText":"八十不俟朝，君問則就之，而弟達乎朝廷矣。","chunks":[["八十不俟朝，君問則就之，而弟達乎朝廷矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-37_s-1","passageId":"li-ji_ch-24_p-37","order":1,"canonicalText":"行，肩而不并，不錯則隨。","chunks":[["行，肩而不并，不錯則隨。","zh-Hant"]]},{"id":"li-ji_ch-24_p-37_s-2","passageId":"li-ji_ch-24_p-37","order":2,"canonicalText":"見老者，則車徒辟；","chunks":[["見老者，則車徒辟；","zh-Hant"]]},{"id":"li-ji_ch-24_p-37_s-3","passageId":"li-ji_ch-24_p-37","order":3,"canonicalText":"斑白者不以其任行乎道路，而弟達乎道路矣。","chunks":[["斑白者不以其任行乎道路，而弟達乎道路矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-37_s-4","passageId":"li-ji_ch-24_p-37","order":4,"canonicalText":"居鄉以齒，而老窮不遺，強不犯弱，眾不暴寡，而弟達乎州巷矣。","chunks":[["居鄉以齒，而老窮不遺，強不犯弱，眾不暴寡，而弟達乎州巷矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-38_s-1","passageId":"li-ji_ch-24_p-38","order":1,"canonicalText":"古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣。","chunks":[["古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-38_s-2","passageId":"li-ji_ch-24_p-38","order":2,"canonicalText":"軍旅什伍，同爵則尚齒，而弟達乎軍旅矣。","chunks":[["軍旅什伍，同爵則尚齒，而弟達乎軍旅矣。","zh-Hant"]]},{"id":"li-ji_ch-24_p-39_s-1","passageId":"li-ji_ch-24_p-39","order":1,"canonicalText":"孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以義死之，而弗敢犯也。","chunks":[["孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以義死之，而弗敢犯也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-1","passageId":"li-ji_ch-24_p-40","order":1,"canonicalText":"祀乎明堂，所以教諸侯之孝也；","chunks":[["祀乎明堂，所以教諸侯之孝也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-2","passageId":"li-ji_ch-24_p-40","order":2,"canonicalText":"食三老五更於大學，所以教諸侯之弟也。","chunks":[["食三老五更於大學，所以教諸侯之弟也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-3","passageId":"li-ji_ch-24_p-40","order":3,"canonicalText":"祀先賢於西學，所以教諸侯之德也；","chunks":[["祀先賢於西學，所以教諸侯之德也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-4","passageId":"li-ji_ch-24_p-40","order":4,"canonicalText":"耕藉，所以教諸侯之養也；","chunks":[["耕藉，所以教諸侯之養也；","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-5","passageId":"li-ji_ch-24_p-40","order":5,"canonicalText":"朝覲，所以教諸侯之臣也。","chunks":[["朝覲，所以教諸侯之臣也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-40_s-6","passageId":"li-ji_ch-24_p-40","order":6,"canonicalText":"五者，天下之大教也。","chunks":[["五者，天下之大教也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-41_s-1","passageId":"li-ji_ch-24_p-41","order":1,"canonicalText":"食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總干，所以教諸侯之弟也。","chunks":[["食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總干，所以教諸侯之弟也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-41_s-2","passageId":"li-ji_ch-24_p-41","order":2,"canonicalText":"是故，鄉里有齒，而老窮不遺，強不犯弱，眾不暴寡，此由大學來者也。","chunks":[["是故，鄉里有齒，而老窮不遺，強不犯弱，眾不暴寡，此由大學來者也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-41_s-3","passageId":"li-ji_ch-24_p-41","order":3,"canonicalText":"天子設四學，當入學，而大子齒。","chunks":[["天子設四學，當入學，而大子齒。","zh-Hant"]]},{"id":"li-ji_ch-24_p-42_s-1","passageId":"li-ji_ch-24_p-42","order":1,"canonicalText":"天子巡守，諸侯待于竟。","chunks":[["天子巡守，諸侯待于竟。","zh-Hant"]]},{"id":"li-ji_ch-24_p-42_s-2","passageId":"li-ji_ch-24_p-42","order":2,"canonicalText":"天子先見百年者。","chunks":[["天子先見百年者。","zh-Hant"]]},{"id":"li-ji_ch-24_p-42_s-3","passageId":"li-ji_ch-24_p-42","order":3,"canonicalText":"八、十九十者東行，西行者弗敢過；","chunks":[["八、十九十者東行，西行者弗敢過；","zh-Hant"]]},{"id":"li-ji_ch-24_p-42_s-4","passageId":"li-ji_ch-24_p-42","order":4,"canonicalText":"西行，東行者弗敢過。","chunks":[["西行，東行者弗敢過。","zh-Hant"]]},{"id":"li-ji_ch-24_p-42_s-5","passageId":"li-ji_ch-24_p-42","order":5,"canonicalText":"欲言政者，君就之可也。","chunks":[["欲言政者，君就之可也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-43_s-1","passageId":"li-ji_ch-24_p-43","order":1,"canonicalText":"壹命齒于鄉里，再命齒于族，三命不齒；","chunks":[["壹命齒于鄉里，再命齒于族，三命不齒；","zh-Hant"]]},{"id":"li-ji_ch-24_p-43_s-2","passageId":"li-ji_ch-24_p-43","order":2,"canonicalText":"族有七十者，弗敢先。","chunks":[["族有七十者，弗敢先。","zh-Hant"]]},{"id":"li-ji_ch-24_p-43_s-3","passageId":"li-ji_ch-24_p-43","order":3,"canonicalText":"七十者，不有大故不入朝；","chunks":[["七十者，不有大故不入朝；","zh-Hant"]]},{"id":"li-ji_ch-24_p-43_s-4","passageId":"li-ji_ch-24_p-43","order":4,"canonicalText":"若有大故而入，君必與之揖讓，而後及爵者。","chunks":[["若有大故而入，君必與之揖讓，而後及爵者。","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-1","passageId":"li-ji_ch-24_p-44","order":1,"canonicalText":"天子有善，讓德於天；","chunks":[["天子有善，讓德於天；","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-2","passageId":"li-ji_ch-24_p-44","order":2,"canonicalText":"諸侯有善，歸諸天子；","chunks":[["諸侯有善，歸諸天子；","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-3","passageId":"li-ji_ch-24_p-44","order":3,"canonicalText":"卿大夫有善，薦於諸侯；","chunks":[["卿大夫有善，薦於諸侯；","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-4","passageId":"li-ji_ch-24_p-44","order":4,"canonicalText":"士、庶人有善，本諸父母，存諸長老；","chunks":[["士、庶人有善，本諸父母，存諸長老；","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-5","passageId":"li-ji_ch-24_p-44","order":5,"canonicalText":"祿爵慶賞，成諸宗廟；","chunks":[["祿爵慶賞，成諸宗廟；","zh-Hant"]]},{"id":"li-ji_ch-24_p-44_s-6","passageId":"li-ji_ch-24_p-44","order":6,"canonicalText":"所以示順也。","chunks":[["所以示順也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-45_s-1","passageId":"li-ji_ch-24_p-45","order":1,"canonicalText":"昔者，聖人建陰陽天地之情，立以為《易》。","chunks":[["昔者，聖人建陰陽天地之情，立以為《易》。","zh-Hant"]]},{"id":"li-ji_ch-24_p-45_s-2","passageId":"li-ji_ch-24_p-45","order":2,"canonicalText":"易抱龜南面，天子卷冕北面，雖有明知之心，必進斷其志焉。","chunks":[["易抱龜南面，天子卷冕北面，雖有明知之心，必進斷其志焉。","zh-Hant"]]},{"id":"li-ji_ch-24_p-45_s-3","passageId":"li-ji_ch-24_p-45","order":3,"canonicalText":"示不敢專，以尊天也。","chunks":[["示不敢專，以尊天也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-45_s-4","passageId":"li-ji_ch-24_p-45","order":4,"canonicalText":"善則稱人，過則稱己。","chunks":[["善則稱人，過則稱己。","zh-Hant"]]},{"id":"li-ji_ch-24_p-45_s-5","passageId":"li-ji_ch-24_p-45","order":5,"canonicalText":"教不伐以尊賢也。","chunks":[["教不伐以尊賢也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-1","passageId":"li-ji_ch-24_p-46","order":1,"canonicalText":"孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，以治百事。","chunks":[["孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，以治百事。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-2","passageId":"li-ji_ch-24_p-46","order":2,"canonicalText":"及祭之日，顏色必溫，行必恐，如懼不及愛然。","chunks":[["及祭之日，顏色必溫，行必恐，如懼不及愛然。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-3","passageId":"li-ji_ch-24_p-46","order":3,"canonicalText":"其奠之也，容貌必溫，身必詘，如語焉而未之然。","chunks":[["其奠之也，容貌必溫，身必詘，如語焉而未之然。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-4","passageId":"li-ji_ch-24_p-46","order":4,"canonicalText":"宿者皆出，其立卑靜以正，如將弗見然。","chunks":[["宿者皆出，其立卑靜以正，如將弗見然。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-5","passageId":"li-ji_ch-24_p-46","order":5,"canonicalText":"及祭之後，陶陶遂遂，如將復入然。","chunks":[["及祭之後，陶陶遂遂，如將復入然。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-6","passageId":"li-ji_ch-24_p-46","order":6,"canonicalText":"是故，愨善不違身，耳目不違心，思慮不違親。","chunks":[["是故，愨善不違身，耳目不違心，思慮不違親。","zh-Hant"]]},{"id":"li-ji_ch-24_p-46_s-7","passageId":"li-ji_ch-24_p-46","order":7,"canonicalText":"結諸心，形諸色，而術省之，孝子之志也。","chunks":[["結諸心，形諸色，而術省之，孝子之志也。","zh-Hant"]]},{"id":"li-ji_ch-24_p-47_s-1","passageId":"li-ji_ch-24_p-47","order":1,"canonicalText":"建國之神位：右社稷，而左宗廟。","chunks":[["建國之神位：右社稷，而左宗廟。","zh-Hant"]]},{"id":"li-ji_ch-25_p-1_s-1","passageId":"li-ji_ch-25_p-1","order":1,"canonicalText":"凡治人之道，莫急於禮。","chunks":[["凡治人之道，莫急於禮。","zh-Hant"]]},{"id":"li-ji_ch-25_p-1_s-2","passageId":"li-ji_ch-25_p-1","order":2,"canonicalText":"禮有五經，莫重於祭。","chunks":[["禮有五經，莫重於祭。","zh-Hant"]]},{"id":"li-ji_ch-25_p-1_s-3","passageId":"li-ji_ch-25_p-1","order":3,"canonicalText":"夫祭者，非物自外至者也，自中出生於心也；","chunks":[["夫祭者，非物自外至者也，自中出生於心也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-1_s-4","passageId":"li-ji_ch-25_p-1","order":4,"canonicalText":"心怵而奉之以禮。","chunks":[["心怵而奉之以禮。","zh-Hant"]]},{"id":"li-ji_ch-25_p-1_s-5","passageId":"li-ji_ch-25_p-1","order":5,"canonicalText":"是故，唯賢者能盡祭之義。","chunks":[["是故，唯賢者能盡祭之義。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-1","passageId":"li-ji_ch-25_p-2","order":1,"canonicalText":"賢者之祭也，必受其福。","chunks":[["賢者之祭也，必受其福。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-2","passageId":"li-ji_ch-25_p-2","order":2,"canonicalText":"非世所謂福也。","chunks":[["非世所謂福也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-3","passageId":"li-ji_ch-25_p-2","order":3,"canonicalText":"福者，備也；","chunks":[["福者，備也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-4","passageId":"li-ji_ch-25_p-2","order":4,"canonicalText":"備者，百順之名也。","chunks":[["備者，百順之名也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-5","passageId":"li-ji_ch-25_p-2","order":5,"canonicalText":"無所不順者，謂之備。","chunks":[["無所不順者，謂之備。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-6","passageId":"li-ji_ch-25_p-2","order":6,"canonicalText":"言：內盡於己，而外順於道也。","chunks":[["言：內盡於己，而外順於道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-7","passageId":"li-ji_ch-25_p-2","order":7,"canonicalText":"忠臣以事其君，孝子以事其親，其本一也。","chunks":[["忠臣以事其君，孝子以事其親，其本一也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-8","passageId":"li-ji_ch-25_p-2","order":8,"canonicalText":"上則順於鬼神，外則順於君長，內則以孝於親。","chunks":[["上則順於鬼神，外則順於君長，內則以孝於親。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-9","passageId":"li-ji_ch-25_p-2","order":9,"canonicalText":"如此之謂備。","chunks":[["如此之謂備。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-10","passageId":"li-ji_ch-25_p-2","order":10,"canonicalText":"唯賢者能備，能備然後能祭。","chunks":[["唯賢者能備，能備然後能祭。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-11","passageId":"li-ji_ch-25_p-2","order":11,"canonicalText":"是故，賢者之祭也：致其誠信與其忠敬，奉之以物，道之以禮，安之以樂，參之以時。","chunks":[["是故，賢者之祭也：致其誠信與其忠敬，奉之以物，道之以禮，安之以樂，參之以時。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-12","passageId":"li-ji_ch-25_p-2","order":12,"canonicalText":"明薦之而已矣。","chunks":[["明薦之而已矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-13","passageId":"li-ji_ch-25_p-2","order":13,"canonicalText":"不求其為。","chunks":[["不求其為。","zh-Hant"]]},{"id":"li-ji_ch-25_p-2_s-14","passageId":"li-ji_ch-25_p-2","order":14,"canonicalText":"此孝子之心也。","chunks":[["此孝子之心也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-1","passageId":"li-ji_ch-25_p-3","order":1,"canonicalText":"祭者，所以追養繼孝也。","chunks":[["祭者，所以追養繼孝也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-2","passageId":"li-ji_ch-25_p-3","order":2,"canonicalText":"孝者畜也。","chunks":[["孝者畜也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-3","passageId":"li-ji_ch-25_p-3","order":3,"canonicalText":"順於道不逆於倫，是之謂畜。","chunks":[["順於道不逆於倫，是之謂畜。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-4","passageId":"li-ji_ch-25_p-3","order":4,"canonicalText":"是故，孝子之事親也，有三道焉：生則養，沒則喪，喪畢則祭。","chunks":[["是故，孝子之事親也，有三道焉：生則養，沒則喪，喪畢則祭。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-5","passageId":"li-ji_ch-25_p-3","order":5,"canonicalText":"養則觀其順也，喪則觀其哀也，祭則觀其敬而時也。","chunks":[["養則觀其順也，喪則觀其哀也，祭則觀其敬而時也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-3_s-6","passageId":"li-ji_ch-25_p-3","order":6,"canonicalText":"盡此三道者，孝子之行也。","chunks":[["盡此三道者，孝子之行也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-1","passageId":"li-ji_ch-25_p-4","order":1,"canonicalText":"既內自盡，又外求助，昏禮是也。","chunks":[["既內自盡，又外求助，昏禮是也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-2","passageId":"li-ji_ch-25_p-4","order":2,"canonicalText":"故國君取夫人之辭曰：「請君之玉女與寡人共有敝邑，事宗廟社稷。","chunks":[["故國君取夫人之辭曰：「請君之玉女與寡人共有敝邑，事宗廟社稷。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-3","passageId":"li-ji_ch-25_p-4","order":3,"canonicalText":"」此求助之本也。","chunks":[["」此求助之本也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-4","passageId":"li-ji_ch-25_p-4","order":4,"canonicalText":"夫祭也者，必夫婦親之，所以備外內之官也；","chunks":[["夫祭也者，必夫婦親之，所以備外內之官也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-5","passageId":"li-ji_ch-25_p-4","order":5,"canonicalText":"官備則具備。","chunks":[["官備則具備。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-6","passageId":"li-ji_ch-25_p-4","order":6,"canonicalText":"水草之菹，陸產之醢，小物備矣；","chunks":[["水草之菹，陸產之醢，小物備矣；","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-7","passageId":"li-ji_ch-25_p-4","order":7,"canonicalText":"三牲之俎，八簋之實，美物備矣；","chunks":[["三牲之俎，八簋之實，美物備矣；","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-8","passageId":"li-ji_ch-25_p-4","order":8,"canonicalText":"昆蟲之異，草木之實，陰陽之物備矣。","chunks":[["昆蟲之異，草木之實，陰陽之物備矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-9","passageId":"li-ji_ch-25_p-4","order":9,"canonicalText":"凡天之所生，地之所長，茍可薦者，莫不咸在，示盡物也。","chunks":[["凡天之所生，地之所長，茍可薦者，莫不咸在，示盡物也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-4_s-10","passageId":"li-ji_ch-25_p-4","order":10,"canonicalText":"外則盡物，內則盡志，此祭之心也。","chunks":[["外則盡物，內則盡志，此祭之心也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-5_s-1","passageId":"li-ji_ch-25_p-5","order":1,"canonicalText":"是故，天子親耕於南郊，以共齊盛；","chunks":[["是故，天子親耕於南郊，以共齊盛；","zh-Hant"]]},{"id":"li-ji_ch-25_p-5_s-2","passageId":"li-ji_ch-25_p-5","order":2,"canonicalText":"王后蠶於北郊，以共純服。","chunks":[["王后蠶於北郊，以共純服。","zh-Hant"]]},{"id":"li-ji_ch-25_p-5_s-3","passageId":"li-ji_ch-25_p-5","order":3,"canonicalText":"諸侯耕於東郊，亦以共齊盛；","chunks":[["諸侯耕於東郊，亦以共齊盛；","zh-Hant"]]},{"id":"li-ji_ch-25_p-5_s-4","passageId":"li-ji_ch-25_p-5","order":4,"canonicalText":"夫人蠶於北郊，以共冕服。","chunks":[["夫人蠶於北郊，以共冕服。","zh-Hant"]]},{"id":"li-ji_ch-25_p-5_s-5","passageId":"li-ji_ch-25_p-5","order":5,"canonicalText":"天子諸侯非莫耕也，王后夫人非莫蠶也，身致其誠信，誠信之謂盡，盡之謂敬，敬盡然後可以事神明，此祭之道也。","chunks":[["天子諸侯非莫耕也，王后夫人非莫蠶也，身致其誠信，誠信之謂盡，盡之謂敬，敬盡然後可以事神明，此祭之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-1","passageId":"li-ji_ch-25_p-6","order":1,"canonicalText":"及時將祭，君子乃齊。","chunks":[["及時將祭，君子乃齊。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-2","passageId":"li-ji_ch-25_p-6","order":2,"canonicalText":"齊之為言齊也。","chunks":[["齊之為言齊也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-3","passageId":"li-ji_ch-25_p-6","order":3,"canonicalText":"齊不齊以致齊者也。","chunks":[["齊不齊以致齊者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-4","passageId":"li-ji_ch-25_p-6","order":4,"canonicalText":"是以君子非有大事也，非有恭敬也，則不齊。","chunks":[["是以君子非有大事也，非有恭敬也，則不齊。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-5","passageId":"li-ji_ch-25_p-6","order":5,"canonicalText":"不齊則於物無防也，嗜欲無止也。","chunks":[["不齊則於物無防也，嗜欲無止也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-6","passageId":"li-ji_ch-25_p-6","order":6,"canonicalText":"及其將齊也，防其邪物，訖其嗜欲，耳不聽樂。","chunks":[["及其將齊也，防其邪物，訖其嗜欲，耳不聽樂。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-7","passageId":"li-ji_ch-25_p-6","order":7,"canonicalText":"故記曰：「齊者不樂」，言不敢散其志也。","chunks":[["故記曰：「齊者不樂」，言不敢散其志也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-8","passageId":"li-ji_ch-25_p-6","order":8,"canonicalText":"心不茍慮，必依於道；","chunks":[["心不茍慮，必依於道；","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-9","passageId":"li-ji_ch-25_p-6","order":9,"canonicalText":"手足不茍動，必依於禮。","chunks":[["手足不茍動，必依於禮。","zh-Hant"]]},{"id":"li-ji_ch-25_p-6_s-10","passageId":"li-ji_ch-25_p-6","order":10,"canonicalText":"是故君子之齊也，專致其精明之德也。","chunks":[["是故君子之齊也，專致其精明之德也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-7_s-1","passageId":"li-ji_ch-25_p-7","order":1,"canonicalText":"故散齊七日以定之，致齊三日以齊之。","chunks":[["故散齊七日以定之，致齊三日以齊之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-7_s-2","passageId":"li-ji_ch-25_p-7","order":2,"canonicalText":"定之之謂齊。","chunks":[["定之之謂齊。","zh-Hant"]]},{"id":"li-ji_ch-25_p-7_s-3","passageId":"li-ji_ch-25_p-7","order":3,"canonicalText":"齊者精明之至也，然後可以交於神明也。","chunks":[["齊者精明之至也，然後可以交於神明也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-7_s-4","passageId":"li-ji_ch-25_p-7","order":4,"canonicalText":"是故，先期旬有一日，宮宰宿夫人，夫人亦散齊七日，致齊三日。","chunks":[["是故，先期旬有一日，宮宰宿夫人，夫人亦散齊七日，致齊三日。","zh-Hant"]]},{"id":"li-ji_ch-25_p-7_s-5","passageId":"li-ji_ch-25_p-7","order":5,"canonicalText":"君致齊於外，夫人致齊於內，然後會於大廟。","chunks":[["君致齊於外，夫人致齊於內，然後會於大廟。","zh-Hant"]]},{"id":"li-ji_ch-25_p-8_s-1","passageId":"li-ji_ch-25_p-8","order":1,"canonicalText":"君純冕立於阼，夫人副褘立於東房。","chunks":[["君純冕立於阼，夫人副褘立於東房。","zh-Hant"]]},{"id":"li-ji_ch-25_p-8_s-2","passageId":"li-ji_ch-25_p-8","order":2,"canonicalText":"君執圭瓚裸尸，大宗執璋瓚亞裸。","chunks":[["君執圭瓚裸尸，大宗執璋瓚亞裸。","zh-Hant"]]},{"id":"li-ji_ch-25_p-8_s-3","passageId":"li-ji_ch-25_p-8","order":3,"canonicalText":"及迎牲，君執紖，卿大夫從士執芻。","chunks":[["及迎牲，君執紖，卿大夫從士執芻。","zh-Hant"]]},{"id":"li-ji_ch-25_p-8_s-4","passageId":"li-ji_ch-25_p-8","order":4,"canonicalText":"宗婦執盎從夫人薦涗水。","chunks":[["宗婦執盎從夫人薦涗水。","zh-Hant"]]},{"id":"li-ji_ch-25_p-8_s-5","passageId":"li-ji_ch-25_p-8","order":5,"canonicalText":"君執鸞刀羞嚌，夫人薦豆，此之謂夫婦親之。","chunks":[["君執鸞刀羞嚌，夫人薦豆，此之謂夫婦親之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-9_s-1","passageId":"li-ji_ch-25_p-9","order":1,"canonicalText":"及入舞，君執干戚就舞位，君為東上，冕而揔干，率其群臣，以樂皇尸。","chunks":[["及入舞，君執干戚就舞位，君為東上，冕而揔干，率其群臣，以樂皇尸。","zh-Hant"]]},{"id":"li-ji_ch-25_p-9_s-2","passageId":"li-ji_ch-25_p-9","order":2,"canonicalText":"是故天子之祭也，與天下樂之；","chunks":[["是故天子之祭也，與天下樂之；","zh-Hant"]]},{"id":"li-ji_ch-25_p-9_s-3","passageId":"li-ji_ch-25_p-9","order":3,"canonicalText":"諸侯之祭也，與竟內樂之。","chunks":[["諸侯之祭也，與竟內樂之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-9_s-4","passageId":"li-ji_ch-25_p-9","order":4,"canonicalText":"冕而揔干，率其群臣，以樂皇尸，此與竟內樂之之義也。","chunks":[["冕而揔干，率其群臣，以樂皇尸，此與竟內樂之之義也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-1","passageId":"li-ji_ch-25_p-10","order":1,"canonicalText":"夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道也。","chunks":[["夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-2","passageId":"li-ji_ch-25_p-10","order":2,"canonicalText":"凡三道者，所以假於外而以增君子之志也，故與志進退；","chunks":[["凡三道者，所以假於外而以增君子之志也，故與志進退；","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-3","passageId":"li-ji_ch-25_p-10","order":3,"canonicalText":"志輕則亦輕，志重則亦重。","chunks":[["志輕則亦輕，志重則亦重。","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-4","passageId":"li-ji_ch-25_p-10","order":4,"canonicalText":"輕其志而求外之重也，雖聖人弗能得也。","chunks":[["輕其志而求外之重也，雖聖人弗能得也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-5","passageId":"li-ji_ch-25_p-10","order":5,"canonicalText":"是故君子之祭也，必身自盡也，所以明重也。","chunks":[["是故君子之祭也，必身自盡也，所以明重也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-10_s-6","passageId":"li-ji_ch-25_p-10","order":6,"canonicalText":"道之以禮，以奉三重，而薦諸皇尸，此聖人之道也。","chunks":[["道之以禮，以奉三重，而薦諸皇尸，此聖人之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-1","passageId":"li-ji_ch-25_p-11","order":1,"canonicalText":"夫祭有餕；","chunks":[["夫祭有餕；","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-2","passageId":"li-ji_ch-25_p-11","order":2,"canonicalText":"餕者祭之末也，不可不知也。","chunks":[["餕者祭之末也，不可不知也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-3","passageId":"li-ji_ch-25_p-11","order":3,"canonicalText":"是故古之人有言曰：「善終者如始。","chunks":[["是故古之人有言曰：「善終者如始。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-4","passageId":"li-ji_ch-25_p-11","order":4,"canonicalText":"」餕其是已。","chunks":[["」餕其是已。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-5","passageId":"li-ji_ch-25_p-11","order":5,"canonicalText":"是故古之君子曰：「尸亦餕鬼神之餘也，惠術也，可以觀政矣。","chunks":[["是故古之君子曰：「尸亦餕鬼神之餘也，惠術也，可以觀政矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-6","passageId":"li-ji_ch-25_p-11","order":6,"canonicalText":"」是故尸謖，君與卿四人餕。","chunks":[["」是故尸謖，君與卿四人餕。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-7","passageId":"li-ji_ch-25_p-11","order":7,"canonicalText":"君起，大夫六人餕；","chunks":[["君起，大夫六人餕；","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-8","passageId":"li-ji_ch-25_p-11","order":8,"canonicalText":"臣餕君之餘也。","chunks":[["臣餕君之餘也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-9","passageId":"li-ji_ch-25_p-11","order":9,"canonicalText":"大夫起，士八人餕；","chunks":[["大夫起，士八人餕；","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-10","passageId":"li-ji_ch-25_p-11","order":10,"canonicalText":"賤餕貴之餘也。","chunks":[["賤餕貴之餘也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-11_s-11","passageId":"li-ji_ch-25_p-11","order":11,"canonicalText":"士起，各執其具以出，陳于堂下，百官進，徹之，下餕上之餘也。","chunks":[["士起，各執其具以出，陳于堂下，百官進，徹之，下餕上之餘也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-1","passageId":"li-ji_ch-25_p-12","order":1,"canonicalText":"凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也。","chunks":[["凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-2","passageId":"li-ji_ch-25_p-12","order":2,"canonicalText":"是故以四簋黍見其修於廟中也。","chunks":[["是故以四簋黍見其修於廟中也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-3","passageId":"li-ji_ch-25_p-12","order":3,"canonicalText":"廟中者竟內之象也。","chunks":[["廟中者竟內之象也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-4","passageId":"li-ji_ch-25_p-12","order":4,"canonicalText":"祭者澤之大者也。","chunks":[["祭者澤之大者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-5","passageId":"li-ji_ch-25_p-12","order":5,"canonicalText":"是故上有大澤則惠必及下，顧上先下後耳。","chunks":[["是故上有大澤則惠必及下，顧上先下後耳。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-6","passageId":"li-ji_ch-25_p-12","order":6,"canonicalText":"非上積重而下有凍餒之民也。","chunks":[["非上積重而下有凍餒之民也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-7","passageId":"li-ji_ch-25_p-12","order":7,"canonicalText":"是故上有大澤，則民夫人待于下流，知惠之必將至也，由餕見之矣。","chunks":[["是故上有大澤，則民夫人待于下流，知惠之必將至也，由餕見之矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-8","passageId":"li-ji_ch-25_p-12","order":8,"canonicalText":"故曰：「可以觀政矣。","chunks":[["故曰：「可以觀政矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-12_s-9","passageId":"li-ji_ch-25_p-12","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-1","passageId":"li-ji_ch-25_p-13","order":1,"canonicalText":"夫祭之為物大矣，其興物備矣。","chunks":[["夫祭之為物大矣，其興物備矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-2","passageId":"li-ji_ch-25_p-13","order":2,"canonicalText":"順以備者也，其教之本與？","chunks":[["順以備者也，其教之本與？","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-3","passageId":"li-ji_ch-25_p-13","order":3,"canonicalText":"是故，君子之教也，外則教之以尊其君長，內則教之以孝於其親。","chunks":[["是故，君子之教也，外則教之以尊其君長，內則教之以孝於其親。","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-4","passageId":"li-ji_ch-25_p-13","order":4,"canonicalText":"是故，明君在上，則諸臣服從；","chunks":[["是故，明君在上，則諸臣服從；","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-5","passageId":"li-ji_ch-25_p-13","order":5,"canonicalText":"崇事宗廟社稷，則子孫順孝。","chunks":[["崇事宗廟社稷，則子孫順孝。","zh-Hant"]]},{"id":"li-ji_ch-25_p-13_s-6","passageId":"li-ji_ch-25_p-13","order":6,"canonicalText":"盡其道，端其義，而教生焉。","chunks":[["盡其道，端其義，而教生焉。","zh-Hant"]]},{"id":"li-ji_ch-25_p-14_s-1","passageId":"li-ji_ch-25_p-14","order":1,"canonicalText":"是故君子之事君也，必身行之，所不安於上，則不以使下；","chunks":[["是故君子之事君也，必身行之，所不安於上，則不以使下；","zh-Hant"]]},{"id":"li-ji_ch-25_p-14_s-2","passageId":"li-ji_ch-25_p-14","order":2,"canonicalText":"所惡於下，則不以事上；","chunks":[["所惡於下，則不以事上；","zh-Hant"]]},{"id":"li-ji_ch-25_p-14_s-3","passageId":"li-ji_ch-25_p-14","order":3,"canonicalText":"非諸人，行諸己，非教之道也。","chunks":[["非諸人，行諸己，非教之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-14_s-4","passageId":"li-ji_ch-25_p-14","order":4,"canonicalText":"是故君子之教也，必由其本，順之至也，祭其是與？","chunks":[["是故君子之教也，必由其本，順之至也，祭其是與？","zh-Hant"]]},{"id":"li-ji_ch-25_p-14_s-5","passageId":"li-ji_ch-25_p-14","order":5,"canonicalText":"故曰：祭者，教之本也已。","chunks":[["故曰：祭者，教之本也已。","zh-Hant"]]},{"id":"li-ji_ch-25_p-15_s-1","passageId":"li-ji_ch-25_p-15","order":1,"canonicalText":"夫祭有十倫焉；","chunks":[["夫祭有十倫焉；","zh-Hant"]]},{"id":"li-ji_ch-25_p-15_s-2","passageId":"li-ji_ch-25_p-15","order":2,"canonicalText":"見事鬼神之道焉，見君臣之義焉，見父子之倫焉，見貴賤之等焉，見親疏之殺焉，見爵賞之施焉，見夫婦之別焉，見政事之均焉，見長幼之序焉，見上下之際焉。","chunks":[["見事鬼神之道焉，見君臣之義焉，見父子之倫焉，見貴賤之等焉，見親疏之殺焉，見爵賞之施焉，見夫婦之別焉，見政事之均焉，見長幼之序焉，見上下之際焉。","zh-Hant"]]},{"id":"li-ji_ch-25_p-15_s-3","passageId":"li-ji_ch-25_p-15","order":3,"canonicalText":"此之謂十倫。","chunks":[["此之謂十倫。","zh-Hant"]]},{"id":"li-ji_ch-25_p-16_s-1","passageId":"li-ji_ch-25_p-16","order":1,"canonicalText":"鋪筵設同几，為依神也；","chunks":[["鋪筵設同几，為依神也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-16_s-2","passageId":"li-ji_ch-25_p-16","order":2,"canonicalText":"詔祝於室，而出于祊，此交神明之道也。","chunks":[["詔祝於室，而出于祊，此交神明之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-17_s-1","passageId":"li-ji_ch-25_p-17","order":1,"canonicalText":"君迎牲而不迎尸，別嫌也。","chunks":[["君迎牲而不迎尸，別嫌也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-17_s-2","passageId":"li-ji_ch-25_p-17","order":2,"canonicalText":"尸在廟門外，則疑於臣，在廟中則全於君；","chunks":[["尸在廟門外，則疑於臣，在廟中則全於君；","zh-Hant"]]},{"id":"li-ji_ch-25_p-17_s-3","passageId":"li-ji_ch-25_p-17","order":3,"canonicalText":"君在廟門外則疑於君，入廟門則全於臣、全於子。","chunks":[["君在廟門外則疑於君，入廟門則全於臣、全於子。","zh-Hant"]]},{"id":"li-ji_ch-25_p-17_s-4","passageId":"li-ji_ch-25_p-17","order":4,"canonicalText":"是故，不出者，明君臣之義也。","chunks":[["是故，不出者，明君臣之義也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-18_s-1","passageId":"li-ji_ch-25_p-18","order":1,"canonicalText":"夫祭之道，孫為王父尸。","chunks":[["夫祭之道，孫為王父尸。","zh-Hant"]]},{"id":"li-ji_ch-25_p-18_s-2","passageId":"li-ji_ch-25_p-18","order":2,"canonicalText":"所使為尸者，於祭者子行也；","chunks":[["所使為尸者，於祭者子行也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-18_s-3","passageId":"li-ji_ch-25_p-18","order":3,"canonicalText":"父北面而事之，所以明子事父之道也。","chunks":[["父北面而事之，所以明子事父之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-18_s-4","passageId":"li-ji_ch-25_p-18","order":4,"canonicalText":"此父子之倫也。","chunks":[["此父子之倫也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-19_s-1","passageId":"li-ji_ch-25_p-19","order":1,"canonicalText":"尸飲五，君洗玉爵獻卿；","chunks":[["尸飲五，君洗玉爵獻卿；","zh-Hant"]]},{"id":"li-ji_ch-25_p-19_s-2","passageId":"li-ji_ch-25_p-19","order":2,"canonicalText":"尸飲七，以瑤爵獻大夫；","chunks":[["尸飲七，以瑤爵獻大夫；","zh-Hant"]]},{"id":"li-ji_ch-25_p-19_s-3","passageId":"li-ji_ch-25_p-19","order":3,"canonicalText":"尸飲九，以散爵獻士及群有司，皆以齒。","chunks":[["尸飲九，以散爵獻士及群有司，皆以齒。","zh-Hant"]]},{"id":"li-ji_ch-25_p-19_s-4","passageId":"li-ji_ch-25_p-19","order":4,"canonicalText":"明尊卑之等也。","chunks":[["明尊卑之等也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-20_s-1","passageId":"li-ji_ch-25_p-20","order":1,"canonicalText":"夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序而無亂也。","chunks":[["夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序而無亂也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-20_s-2","passageId":"li-ji_ch-25_p-20","order":2,"canonicalText":"是故，有事於大廟，則群昭群穆咸在而不失其倫。","chunks":[["是故，有事於大廟，則群昭群穆咸在而不失其倫。","zh-Hant"]]},{"id":"li-ji_ch-25_p-20_s-3","passageId":"li-ji_ch-25_p-20","order":3,"canonicalText":"此之謂親疏之殺也。","chunks":[["此之謂親疏之殺也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-1","passageId":"li-ji_ch-25_p-21","order":1,"canonicalText":"古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也。","chunks":[["古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-2","passageId":"li-ji_ch-25_p-21","order":2,"canonicalText":"故祭之日，一獻，君降立于阼階之南，南鄉。","chunks":[["故祭之日，一獻，君降立于阼階之南，南鄉。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-3","passageId":"li-ji_ch-25_p-21","order":3,"canonicalText":"所命北面，史由君右執策命之。","chunks":[["所命北面，史由君右執策命之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-4","passageId":"li-ji_ch-25_p-21","order":4,"canonicalText":"再拜稽首。","chunks":[["再拜稽首。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-5","passageId":"li-ji_ch-25_p-21","order":5,"canonicalText":"受書以歸，而舍奠于其廟。","chunks":[["受書以歸，而舍奠于其廟。","zh-Hant"]]},{"id":"li-ji_ch-25_p-21_s-6","passageId":"li-ji_ch-25_p-21","order":6,"canonicalText":"此爵賞之施也。","chunks":[["此爵賞之施也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-22_s-1","passageId":"li-ji_ch-25_p-22","order":1,"canonicalText":"君卷冕立于阼，夫人副褘立于東房。","chunks":[["君卷冕立于阼，夫人副褘立于東房。","zh-Hant"]]},{"id":"li-ji_ch-25_p-22_s-2","passageId":"li-ji_ch-25_p-22","order":2,"canonicalText":"夫人薦豆執校，執醴授之執鐙。","chunks":[["夫人薦豆執校，執醴授之執鐙。","zh-Hant"]]},{"id":"li-ji_ch-25_p-22_s-3","passageId":"li-ji_ch-25_p-22","order":3,"canonicalText":"尸酢夫人執柄，夫人受尸執足。","chunks":[["尸酢夫人執柄，夫人受尸執足。","zh-Hant"]]},{"id":"li-ji_ch-25_p-22_s-4","passageId":"li-ji_ch-25_p-22","order":4,"canonicalText":"夫婦相授受，不相襲處，酢必易爵。","chunks":[["夫婦相授受，不相襲處，酢必易爵。","zh-Hant"]]},{"id":"li-ji_ch-25_p-22_s-5","passageId":"li-ji_ch-25_p-22","order":5,"canonicalText":"明夫婦之別也。","chunks":[["明夫婦之別也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-1","passageId":"li-ji_ch-25_p-23","order":1,"canonicalText":"凡為俎者，以骨為主。","chunks":[["凡為俎者，以骨為主。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-2","passageId":"li-ji_ch-25_p-23","order":2,"canonicalText":"骨有貴賤；","chunks":[["骨有貴賤；","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-3","passageId":"li-ji_ch-25_p-23","order":3,"canonicalText":"殷人貴髀，周人貴肩，凡前貴於後。","chunks":[["殷人貴髀，周人貴肩，凡前貴於後。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-4","passageId":"li-ji_ch-25_p-23","order":4,"canonicalText":"俎者，所以明祭之必有惠也。","chunks":[["俎者，所以明祭之必有惠也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-5","passageId":"li-ji_ch-25_p-23","order":5,"canonicalText":"是故，貴者取貴骨，賤者取賤骨。","chunks":[["是故，貴者取貴骨，賤者取賤骨。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-6","passageId":"li-ji_ch-25_p-23","order":6,"canonicalText":"貴者不重，賤者不虛，示均也。","chunks":[["貴者不重，賤者不虛，示均也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-7","passageId":"li-ji_ch-25_p-23","order":7,"canonicalText":"惠均則政行，政行則事成，事成則功立。","chunks":[["惠均則政行，政行則事成，事成則功立。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-8","passageId":"li-ji_ch-25_p-23","order":8,"canonicalText":"功之所以立者，不可不知也。","chunks":[["功之所以立者，不可不知也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-9","passageId":"li-ji_ch-25_p-23","order":9,"canonicalText":"俎者，所以明惠之必均也。","chunks":[["俎者，所以明惠之必均也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-23_s-10","passageId":"li-ji_ch-25_p-23","order":10,"canonicalText":"善為政者如此，故曰：見政事之均焉。","chunks":[["善為政者如此，故曰：見政事之均焉。","zh-Hant"]]},{"id":"li-ji_ch-25_p-24_s-1","passageId":"li-ji_ch-25_p-24","order":1,"canonicalText":"凡賜爵，昭為一，穆為一。","chunks":[["凡賜爵，昭為一，穆為一。","zh-Hant"]]},{"id":"li-ji_ch-25_p-24_s-2","passageId":"li-ji_ch-25_p-24","order":2,"canonicalText":"昭與昭齒，穆與穆齒，凡群有司皆以齒，此之謂長幼有序。","chunks":[["昭與昭齒，穆與穆齒，凡群有司皆以齒，此之謂長幼有序。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-1","passageId":"li-ji_ch-25_p-25","order":1,"canonicalText":"夫祭有畀輝胞翟閽者，惠下之道也。","chunks":[["夫祭有畀輝胞翟閽者，惠下之道也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-2","passageId":"li-ji_ch-25_p-25","order":2,"canonicalText":"唯有德之君為能行此，明足以見之，仁足以與之。","chunks":[["唯有德之君為能行此，明足以見之，仁足以與之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-3","passageId":"li-ji_ch-25_p-25","order":3,"canonicalText":"畀之為言與也，能以其餘畀其下者也。","chunks":[["畀之為言與也，能以其餘畀其下者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-4","passageId":"li-ji_ch-25_p-25","order":4,"canonicalText":"輝者，甲吏之賤者也；","chunks":[["輝者，甲吏之賤者也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-5","passageId":"li-ji_ch-25_p-25","order":5,"canonicalText":"胞者，肉吏之賤者也；","chunks":[["胞者，肉吏之賤者也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-6","passageId":"li-ji_ch-25_p-25","order":6,"canonicalText":"翟者，樂吏之賤者也；","chunks":[["翟者，樂吏之賤者也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-7","passageId":"li-ji_ch-25_p-25","order":7,"canonicalText":"閽者，守門之賤者也。","chunks":[["閽者，守門之賤者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-8","passageId":"li-ji_ch-25_p-25","order":8,"canonicalText":"古者不使刑人守門，此四守者，吏之至賤者也。","chunks":[["古者不使刑人守門，此四守者，吏之至賤者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-9","passageId":"li-ji_ch-25_p-25","order":9,"canonicalText":"尸又至尊；","chunks":[["尸又至尊；","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-10","passageId":"li-ji_ch-25_p-25","order":10,"canonicalText":"以至尊既祭之末，而不忘至賤，而以其餘畀之。","chunks":[["以至尊既祭之末，而不忘至賤，而以其餘畀之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-25_s-11","passageId":"li-ji_ch-25_p-25","order":11,"canonicalText":"是故明君在上，則竟內之民無凍餒者矣，此之謂上下之際。","chunks":[["是故明君在上，則竟內之民無凍餒者矣，此之謂上下之際。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-1","passageId":"li-ji_ch-25_p-26","order":1,"canonicalText":"凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝。","chunks":[["凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-2","passageId":"li-ji_ch-25_p-26","order":2,"canonicalText":"礿、禘，陽義也；","chunks":[["礿、禘，陽義也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-3","passageId":"li-ji_ch-25_p-26","order":3,"canonicalText":"嘗、烝，陰義也。","chunks":[["嘗、烝，陰義也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-4","passageId":"li-ji_ch-25_p-26","order":4,"canonicalText":"禘者陽之盛也，嘗者陰之盛也。","chunks":[["禘者陽之盛也，嘗者陰之盛也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-5","passageId":"li-ji_ch-25_p-26","order":5,"canonicalText":"故曰：莫重於禘、嘗。","chunks":[["故曰：莫重於禘、嘗。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-6","passageId":"li-ji_ch-25_p-26","order":6,"canonicalText":"古者於禘也，發爵賜服，順陽義也；","chunks":[["古者於禘也，發爵賜服，順陽義也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-7","passageId":"li-ji_ch-25_p-26","order":7,"canonicalText":"於嘗也，出田邑，發秋政，順陰義也。","chunks":[["於嘗也，出田邑，發秋政，順陰義也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-8","passageId":"li-ji_ch-25_p-26","order":8,"canonicalText":"故記曰：「嘗之日，發公室，示賞也；","chunks":[["故記曰：「嘗之日，發公室，示賞也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-9","passageId":"li-ji_ch-25_p-26","order":9,"canonicalText":"草艾則墨；","chunks":[["草艾則墨；","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-10","passageId":"li-ji_ch-25_p-26","order":10,"canonicalText":"未發秋政，則民弗敢草也。","chunks":[["未發秋政，則民弗敢草也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-11","passageId":"li-ji_ch-25_p-26","order":11,"canonicalText":"」故曰：禘、嘗之義大矣。","chunks":[["」故曰：禘、嘗之義大矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-12","passageId":"li-ji_ch-25_p-26","order":12,"canonicalText":"治國之本也，不可不知也。","chunks":[["治國之本也，不可不知也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-13","passageId":"li-ji_ch-25_p-26","order":13,"canonicalText":"明其義者君也，能其事者臣也。","chunks":[["明其義者君也，能其事者臣也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-14","passageId":"li-ji_ch-25_p-26","order":14,"canonicalText":"不明其義，君人不全；","chunks":[["不明其義，君人不全；","zh-Hant"]]},{"id":"li-ji_ch-25_p-26_s-15","passageId":"li-ji_ch-25_p-26","order":15,"canonicalText":"不能其事，為臣不全。","chunks":[["不能其事，為臣不全。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-1","passageId":"li-ji_ch-25_p-27","order":1,"canonicalText":"夫義者，所以濟志也，諸德之發也。","chunks":[["夫義者，所以濟志也，諸德之發也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-2","passageId":"li-ji_ch-25_p-27","order":2,"canonicalText":"是故其德盛者，其志厚；","chunks":[["是故其德盛者，其志厚；","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-3","passageId":"li-ji_ch-25_p-27","order":3,"canonicalText":"其志厚者，其義章。","chunks":[["其志厚者，其義章。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-4","passageId":"li-ji_ch-25_p-27","order":4,"canonicalText":"其義章者，其祭也敬。","chunks":[["其義章者，其祭也敬。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-5","passageId":"li-ji_ch-25_p-27","order":5,"canonicalText":"祭敬則竟內之子孫莫敢不敬矣。","chunks":[["祭敬則竟內之子孫莫敢不敬矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-6","passageId":"li-ji_ch-25_p-27","order":6,"canonicalText":"是故君子之祭也，必身親蒞之；","chunks":[["是故君子之祭也，必身親蒞之；","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-7","passageId":"li-ji_ch-25_p-27","order":7,"canonicalText":"有故，則使人可也。","chunks":[["有故，則使人可也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-8","passageId":"li-ji_ch-25_p-27","order":8,"canonicalText":"雖使人也，君不失其義者，君明其義故也。","chunks":[["雖使人也，君不失其義者，君明其義故也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-9","passageId":"li-ji_ch-25_p-27","order":9,"canonicalText":"其德薄者，其志輕，疑於其義，而求祭；","chunks":[["其德薄者，其志輕，疑於其義，而求祭；","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-10","passageId":"li-ji_ch-25_p-27","order":10,"canonicalText":"使之必敬也，弗可得已。","chunks":[["使之必敬也，弗可得已。","zh-Hant"]]},{"id":"li-ji_ch-25_p-27_s-11","passageId":"li-ji_ch-25_p-27","order":11,"canonicalText":"祭而不敬，何以為民父母矣？","chunks":[["祭而不敬，何以為民父母矣？","zh-Hant"]]},{"id":"li-ji_ch-25_p-28_s-1","passageId":"li-ji_ch-25_p-28","order":1,"canonicalText":"夫鼎有銘，銘者，自名也。","chunks":[["夫鼎有銘，銘者，自名也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-28_s-2","passageId":"li-ji_ch-25_p-28","order":2,"canonicalText":"自名以稱揚其先祖之美，而明著之後世者也。","chunks":[["自名以稱揚其先祖之美，而明著之後世者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-28_s-3","passageId":"li-ji_ch-25_p-28","order":3,"canonicalText":"為先祖者，莫不有美焉，莫不有惡焉，銘之義，稱美而不稱惡，此孝子孝孫之心也。","chunks":[["為先祖者，莫不有美焉，莫不有惡焉，銘之義，稱美而不稱惡，此孝子孝孫之心也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-28_s-4","passageId":"li-ji_ch-25_p-28","order":4,"canonicalText":"唯賢者能之。","chunks":[["唯賢者能之。","zh-Hant"]]},{"id":"li-ji_ch-25_p-29_s-1","passageId":"li-ji_ch-25_p-29","order":1,"canonicalText":"銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，而酌之祭器；","chunks":[["銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，而酌之祭器；","zh-Hant"]]},{"id":"li-ji_ch-25_p-29_s-2","passageId":"li-ji_ch-25_p-29","order":2,"canonicalText":"自成其名焉，以祀其先祖者也。","chunks":[["自成其名焉，以祀其先祖者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-29_s-3","passageId":"li-ji_ch-25_p-29","order":3,"canonicalText":"顯揚先祖，所以崇孝也。","chunks":[["顯揚先祖，所以崇孝也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-29_s-4","passageId":"li-ji_ch-25_p-29","order":4,"canonicalText":"身比焉，順也。","chunks":[["身比焉，順也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-29_s-5","passageId":"li-ji_ch-25_p-29","order":5,"canonicalText":"明示後世，教也。","chunks":[["明示後世，教也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-30_s-1","passageId":"li-ji_ch-25_p-30","order":1,"canonicalText":"夫銘者，壹稱而上下皆得焉耳矣。","chunks":[["夫銘者，壹稱而上下皆得焉耳矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-30_s-2","passageId":"li-ji_ch-25_p-30","order":2,"canonicalText":"是故君子之觀於銘也，既美其所稱，又美其所為。","chunks":[["是故君子之觀於銘也，既美其所稱，又美其所為。","zh-Hant"]]},{"id":"li-ji_ch-25_p-30_s-3","passageId":"li-ji_ch-25_p-30","order":3,"canonicalText":"為之者，明足以見之，仁足以與之，知足以利之，可謂賢矣。","chunks":[["為之者，明足以見之，仁足以與之，知足以利之，可謂賢矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-30_s-4","passageId":"li-ji_ch-25_p-30","order":4,"canonicalText":"賢而勿伐，可謂恭矣。","chunks":[["賢而勿伐，可謂恭矣。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-1","passageId":"li-ji_ch-25_p-31","order":1,"canonicalText":"故衛孔悝之鼎銘曰：六月丁亥，公假于大廟。","chunks":[["故衛孔悝之鼎銘曰：六月丁亥，公假于大廟。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-2","passageId":"li-ji_ch-25_p-31","order":2,"canonicalText":"公曰：「叔舅！","chunks":[["公曰：「叔舅！","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-3","passageId":"li-ji_ch-25_p-31","order":3,"canonicalText":"乃祖莊叔，左右成公。","chunks":[["乃祖莊叔，左右成公。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-4","passageId":"li-ji_ch-25_p-31","order":4,"canonicalText":"成公乃命莊叔隨難于漢陽，即宮于宗周，奔走無射。","chunks":[["成公乃命莊叔隨難于漢陽，即宮于宗周，奔走無射。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-5","passageId":"li-ji_ch-25_p-31","order":5,"canonicalText":"啟右獻公。","chunks":[["啟右獻公。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-6","passageId":"li-ji_ch-25_p-31","order":6,"canonicalText":"獻公乃命成叔，纂乃祖服。","chunks":[["獻公乃命成叔，纂乃祖服。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-7","passageId":"li-ji_ch-25_p-31","order":7,"canonicalText":"乃考文叔，興舊耆欲，作率慶士，躬恤衛國，其勤公家，夙夜不解，民咸曰：『休哉！","chunks":[["乃考文叔，興舊耆欲，作率慶士，躬恤衛國，其勤公家，夙夜不解，民咸曰：『休哉！","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-8","passageId":"li-ji_ch-25_p-31","order":8,"canonicalText":"』」公曰：「叔舅！","chunks":[["』」公曰：「叔舅！","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-9","passageId":"li-ji_ch-25_p-31","order":9,"canonicalText":"予女銘：若纂乃考服。","chunks":[["予女銘：若纂乃考服。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-10","passageId":"li-ji_ch-25_p-31","order":10,"canonicalText":"」悝拜稽首曰：「對揚以辟之，勤大命施于烝彝鼎。","chunks":[["」悝拜稽首曰：「對揚以辟之，勤大命施于烝彝鼎。","zh-Hant"]]},{"id":"li-ji_ch-25_p-31_s-11","passageId":"li-ji_ch-25_p-31","order":11,"canonicalText":"」此衛孔悝之鼎銘也。","chunks":[["」此衛孔悝之鼎銘也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-1","passageId":"li-ji_ch-25_p-32","order":1,"canonicalText":"古之君子論譔其先祖之美，而明著之後世者也。","chunks":[["古之君子論譔其先祖之美，而明著之後世者也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-2","passageId":"li-ji_ch-25_p-32","order":2,"canonicalText":"以比其身，以重其國家如此。","chunks":[["以比其身，以重其國家如此。","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-3","passageId":"li-ji_ch-25_p-32","order":3,"canonicalText":"子孫之守宗廟社稷者，其先祖無美而稱之，是誣也；","chunks":[["子孫之守宗廟社稷者，其先祖無美而稱之，是誣也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-4","passageId":"li-ji_ch-25_p-32","order":4,"canonicalText":"有善而弗知，不明也；","chunks":[["有善而弗知，不明也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-5","passageId":"li-ji_ch-25_p-32","order":5,"canonicalText":"知而弗傳，不仁也。","chunks":[["知而弗傳，不仁也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-32_s-6","passageId":"li-ji_ch-25_p-32","order":6,"canonicalText":"此三者，君子之所恥也。","chunks":[["此三者，君子之所恥也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-1","passageId":"li-ji_ch-25_p-33","order":1,"canonicalText":"昔者，周公旦有勛勞於天下。","chunks":[["昔者，周公旦有勛勞於天下。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-2","passageId":"li-ji_ch-25_p-33","order":2,"canonicalText":"周公既沒，成王、康王追念周公之所以勛勞者，而欲尊魯；","chunks":[["周公既沒，成王、康王追念周公之所以勛勞者，而欲尊魯；","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-3","passageId":"li-ji_ch-25_p-33","order":3,"canonicalText":"故賜之以重祭。","chunks":[["故賜之以重祭。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-4","passageId":"li-ji_ch-25_p-33","order":4,"canonicalText":"外祭，則郊社是也；","chunks":[["外祭，則郊社是也；","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-5","passageId":"li-ji_ch-25_p-33","order":5,"canonicalText":"內祭，則大嘗禘是也。","chunks":[["內祭，則大嘗禘是也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-6","passageId":"li-ji_ch-25_p-33","order":6,"canonicalText":"夫大嘗禘，升歌《清廟》，下而管《象》；","chunks":[["夫大嘗禘，升歌《清廟》，下而管《象》；","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-7","passageId":"li-ji_ch-25_p-33","order":7,"canonicalText":"朱干玉戚，以舞《大武》；","chunks":[["朱干玉戚，以舞《大武》；","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-8","passageId":"li-ji_ch-25_p-33","order":8,"canonicalText":"八佾，以舞《大夏》；","chunks":[["八佾，以舞《大夏》；","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-9","passageId":"li-ji_ch-25_p-33","order":9,"canonicalText":"此天子之樂也。","chunks":[["此天子之樂也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-10","passageId":"li-ji_ch-25_p-33","order":10,"canonicalText":"康周公，故以賜魯也。","chunks":[["康周公，故以賜魯也。","zh-Hant"]]},{"id":"li-ji_ch-25_p-33_s-11","passageId":"li-ji_ch-25_p-33","order":11,"canonicalText":"子孫纂之，至于今不廢，所以明周公之德而又以重其國也。","chunks":[["子孫纂之，至于今不廢，所以明周公之德而又以重其國也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-1","passageId":"li-ji_ch-26_p-1","order":1,"canonicalText":"孔子曰：「入其國，其教可知也。","chunks":[["孔子曰：「入其國，其教可知也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-2","passageId":"li-ji_ch-26_p-1","order":2,"canonicalText":"其為人也：溫柔敦厚，《詩》教也；","chunks":[["其為人也：溫柔敦厚，《詩》教也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-3","passageId":"li-ji_ch-26_p-1","order":3,"canonicalText":"疏通知遠，《書》教也；","chunks":[["疏通知遠，《書》教也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-4","passageId":"li-ji_ch-26_p-1","order":4,"canonicalText":"廣博易良，《樂》教也；","chunks":[["廣博易良，《樂》教也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-5","passageId":"li-ji_ch-26_p-1","order":5,"canonicalText":"潔靜精微，《易》教也；","chunks":[["潔靜精微，《易》教也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-6","passageId":"li-ji_ch-26_p-1","order":6,"canonicalText":"恭儉莊敬，《禮》教也；","chunks":[["恭儉莊敬，《禮》教也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-7","passageId":"li-ji_ch-26_p-1","order":7,"canonicalText":"屬辭比事，《春秋》教也。","chunks":[["屬辭比事，《春秋》教也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-8","passageId":"li-ji_ch-26_p-1","order":8,"canonicalText":"故《詩》之失，愚；","chunks":[["故《詩》之失，愚；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-9","passageId":"li-ji_ch-26_p-1","order":9,"canonicalText":"《書》之失，誣；","chunks":[["《書》之失，誣；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-10","passageId":"li-ji_ch-26_p-1","order":10,"canonicalText":"《樂》之失，奢；","chunks":[["《樂》之失，奢；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-11","passageId":"li-ji_ch-26_p-1","order":11,"canonicalText":"《易》之失，賊；","chunks":[["《易》之失，賊；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-12","passageId":"li-ji_ch-26_p-1","order":12,"canonicalText":"《禮》之失，煩；","chunks":[["《禮》之失，煩；","zh-Hant"]]},{"id":"li-ji_ch-26_p-1_s-13","passageId":"li-ji_ch-26_p-1","order":13,"canonicalText":"《春秋》之失，亂。","chunks":[["《春秋》之失，亂。","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-1","passageId":"li-ji_ch-26_p-2","order":1,"canonicalText":"其為人也：溫柔敦厚而不愚，則深於《詩》者也；","chunks":[["其為人也：溫柔敦厚而不愚，則深於《詩》者也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-2","passageId":"li-ji_ch-26_p-2","order":2,"canonicalText":"疏通知遠而不誣，則深於《書》者也；","chunks":[["疏通知遠而不誣，則深於《書》者也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-3","passageId":"li-ji_ch-26_p-2","order":3,"canonicalText":"廣博易良而不奢，則深於《樂》者也；","chunks":[["廣博易良而不奢，則深於《樂》者也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-4","passageId":"li-ji_ch-26_p-2","order":4,"canonicalText":"潔靜精微而不賊，則深於《易》者也；","chunks":[["潔靜精微而不賊，則深於《易》者也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-5","passageId":"li-ji_ch-26_p-2","order":5,"canonicalText":"恭儉莊敬而不煩，則深於《禮》者也；","chunks":[["恭儉莊敬而不煩，則深於《禮》者也；","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-6","passageId":"li-ji_ch-26_p-2","order":6,"canonicalText":"屬辭比事而不亂，則深於《春秋》者也。","chunks":[["屬辭比事而不亂，則深於《春秋》者也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-2_s-7","passageId":"li-ji_ch-26_p-2","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-1","passageId":"li-ji_ch-26_p-3","order":1,"canonicalText":"天子者，與天地參。","chunks":[["天子者，與天地參。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-2","passageId":"li-ji_ch-26_p-3","order":2,"canonicalText":"故德配天地，兼利萬物，與日月并明，明照四海而不遺微小。","chunks":[["故德配天地，兼利萬物，與日月并明，明照四海而不遺微小。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-3","passageId":"li-ji_ch-26_p-3","order":3,"canonicalText":"其在朝廷，則道仁聖禮義之序；","chunks":[["其在朝廷，則道仁聖禮義之序；","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-4","passageId":"li-ji_ch-26_p-3","order":4,"canonicalText":"燕處，則聽雅、頌之音；","chunks":[["燕處，則聽雅、頌之音；","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-5","passageId":"li-ji_ch-26_p-3","order":5,"canonicalText":"行步，則有環佩之聲；","chunks":[["行步，則有環佩之聲；","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-6","passageId":"li-ji_ch-26_p-3","order":6,"canonicalText":"升車，則有鸞和之音。","chunks":[["升車，則有鸞和之音。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-7","passageId":"li-ji_ch-26_p-3","order":7,"canonicalText":"居處有禮，進退有度，百官得其宜，萬事得其序。","chunks":[["居處有禮，進退有度，百官得其宜，萬事得其序。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-8","passageId":"li-ji_ch-26_p-3","order":8,"canonicalText":"《詩》云：「淑人君子，其儀不忒。","chunks":[["《詩》云：「淑人君子，其儀不忒。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-9","passageId":"li-ji_ch-26_p-3","order":9,"canonicalText":"其儀不忒，正是四國。","chunks":[["其儀不忒，正是四國。","zh-Hant"]]},{"id":"li-ji_ch-26_p-3_s-10","passageId":"li-ji_ch-26_p-3","order":10,"canonicalText":"」此之謂也。","chunks":[["」此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-1","passageId":"li-ji_ch-26_p-4","order":1,"canonicalText":"發號出令而民說，謂之和；","chunks":[["發號出令而民說，謂之和；","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-2","passageId":"li-ji_ch-26_p-4","order":2,"canonicalText":"上下相親，謂之仁；","chunks":[["上下相親，謂之仁；","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-3","passageId":"li-ji_ch-26_p-4","order":3,"canonicalText":"民不求其所欲而得之，謂之信；","chunks":[["民不求其所欲而得之，謂之信；","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-4","passageId":"li-ji_ch-26_p-4","order":4,"canonicalText":"除去天地之害，謂之義。","chunks":[["除去天地之害，謂之義。","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-5","passageId":"li-ji_ch-26_p-4","order":5,"canonicalText":"義與信，和與仁，霸王之器也。","chunks":[["義與信，和與仁，霸王之器也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-4_s-6","passageId":"li-ji_ch-26_p-4","order":6,"canonicalText":"有治民之意而無其器，則不成。","chunks":[["有治民之意而無其器，則不成。","zh-Hant"]]},{"id":"li-ji_ch-26_p-5_s-1","passageId":"li-ji_ch-26_p-5","order":1,"canonicalText":"禮之於正國也：猶衡之於輕重也，繩墨之於曲直也，規矩之於方圜也。","chunks":[["禮之於正國也：猶衡之於輕重也，繩墨之於曲直也，規矩之於方圜也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-5_s-2","passageId":"li-ji_ch-26_p-5","order":2,"canonicalText":"故衡誠縣，不可欺以輕重；","chunks":[["故衡誠縣，不可欺以輕重；","zh-Hant"]]},{"id":"li-ji_ch-26_p-5_s-3","passageId":"li-ji_ch-26_p-5","order":3,"canonicalText":"繩墨誠陳，不可欺以曲直；","chunks":[["繩墨誠陳，不可欺以曲直；","zh-Hant"]]},{"id":"li-ji_ch-26_p-5_s-4","passageId":"li-ji_ch-26_p-5","order":4,"canonicalText":"規矩誠設，不可欺以方圓；","chunks":[["規矩誠設，不可欺以方圓；","zh-Hant"]]},{"id":"li-ji_ch-26_p-5_s-5","passageId":"li-ji_ch-26_p-5","order":5,"canonicalText":"君子審禮，不可誣以奸詐。","chunks":[["君子審禮，不可誣以奸詐。","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-1","passageId":"li-ji_ch-26_p-6","order":1,"canonicalText":"是故，隆禮由禮，謂之有方之士；","chunks":[["是故，隆禮由禮，謂之有方之士；","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-2","passageId":"li-ji_ch-26_p-6","order":2,"canonicalText":"不隆禮、不由禮，謂之無方之民。","chunks":[["不隆禮、不由禮，謂之無方之民。","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-3","passageId":"li-ji_ch-26_p-6","order":3,"canonicalText":"敬讓之道也。","chunks":[["敬讓之道也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-4","passageId":"li-ji_ch-26_p-6","order":4,"canonicalText":"故以奉宗廟則敬，以入朝廷則貴賤有位，以處室家則父子親、兄弟和，以處鄉里則長幼有序。","chunks":[["故以奉宗廟則敬，以入朝廷則貴賤有位，以處室家則父子親、兄弟和，以處鄉里則長幼有序。","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-5","passageId":"li-ji_ch-26_p-6","order":5,"canonicalText":"孔子曰：「安上治民，莫善於禮。","chunks":[["孔子曰：「安上治民，莫善於禮。","zh-Hant"]]},{"id":"li-ji_ch-26_p-6_s-6","passageId":"li-ji_ch-26_p-6","order":6,"canonicalText":"」此之謂也。","chunks":[["」此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-1","passageId":"li-ji_ch-26_p-7","order":1,"canonicalText":"故朝覲之禮，所以明君臣之義也。","chunks":[["故朝覲之禮，所以明君臣之義也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-2","passageId":"li-ji_ch-26_p-7","order":2,"canonicalText":"聘問之禮，所以使諸侯相尊敬也。","chunks":[["聘問之禮，所以使諸侯相尊敬也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-3","passageId":"li-ji_ch-26_p-7","order":3,"canonicalText":"喪祭之禮，所以明臣子之恩也。","chunks":[["喪祭之禮，所以明臣子之恩也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-4","passageId":"li-ji_ch-26_p-7","order":4,"canonicalText":"鄉飲酒之禮，所以明長幼之序也。","chunks":[["鄉飲酒之禮，所以明長幼之序也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-5","passageId":"li-ji_ch-26_p-7","order":5,"canonicalText":"昏姻之禮，所以明男女之別也。","chunks":[["昏姻之禮，所以明男女之別也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-6","passageId":"li-ji_ch-26_p-7","order":6,"canonicalText":"夫禮，禁亂之所由生，猶坊止水之所自來也。","chunks":[["夫禮，禁亂之所由生，猶坊止水之所自來也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-7","passageId":"li-ji_ch-26_p-7","order":7,"canonicalText":"故以舊坊為無所用而壞之者，必有水敗；","chunks":[["故以舊坊為無所用而壞之者，必有水敗；","zh-Hant"]]},{"id":"li-ji_ch-26_p-7_s-8","passageId":"li-ji_ch-26_p-7","order":8,"canonicalText":"以舊禮為無所用而去之者，必有亂患。","chunks":[["以舊禮為無所用而去之者，必有亂患。","zh-Hant"]]},{"id":"li-ji_ch-26_p-8_s-1","passageId":"li-ji_ch-26_p-8","order":1,"canonicalText":"故昏姻之禮廢，則夫婦之道苦，而淫辟之罪多矣。","chunks":[["故昏姻之禮廢，則夫婦之道苦，而淫辟之罪多矣。","zh-Hant"]]},{"id":"li-ji_ch-26_p-8_s-2","passageId":"li-ji_ch-26_p-8","order":2,"canonicalText":"鄉飲酒之禮廢，則長幼之序失，而爭鬥之獄繁矣。","chunks":[["鄉飲酒之禮廢，則長幼之序失，而爭鬥之獄繁矣。","zh-Hant"]]},{"id":"li-ji_ch-26_p-8_s-3","passageId":"li-ji_ch-26_p-8","order":3,"canonicalText":"喪祭之禮廢，則臣子之恩薄，而倍死忘生者眾矣。","chunks":[["喪祭之禮廢，則臣子之恩薄，而倍死忘生者眾矣。","zh-Hant"]]},{"id":"li-ji_ch-26_p-8_s-4","passageId":"li-ji_ch-26_p-8","order":4,"canonicalText":"聘覲之禮廢，則君臣之位失，諸侯之行惡，而倍畔侵陵之敗起矣。","chunks":[["聘覲之禮廢，則君臣之位失，諸侯之行惡，而倍畔侵陵之敗起矣。","zh-Hant"]]},{"id":"li-ji_ch-26_p-9_s-1","passageId":"li-ji_ch-26_p-9","order":1,"canonicalText":"故禮之教化也微，其止邪也於未形，使人日徙善遠罪而不自知也。","chunks":[["故禮之教化也微，其止邪也於未形，使人日徙善遠罪而不自知也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-9_s-2","passageId":"li-ji_ch-26_p-9","order":2,"canonicalText":"是以先王隆之也。","chunks":[["是以先王隆之也。","zh-Hant"]]},{"id":"li-ji_ch-26_p-9_s-3","passageId":"li-ji_ch-26_p-9","order":3,"canonicalText":"《易》曰：「君子慎始，差若毫厘，繆以千里。","chunks":[["《易》曰：「君子慎始，差若毫厘，繆以千里。","zh-Hant"]]},{"id":"li-ji_ch-26_p-9_s-4","passageId":"li-ji_ch-26_p-9","order":4,"canonicalText":"」此之謂也。","chunks":[["」此之謂也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-1","passageId":"li-ji_ch-27_p-1","order":1,"canonicalText":"哀公問於孔子曰：「大禮何如？","chunks":[["哀公問於孔子曰：「大禮何如？","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-2","passageId":"li-ji_ch-27_p-1","order":2,"canonicalText":"君子之言禮，何其尊也？","chunks":[["君子之言禮，何其尊也？","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-3","passageId":"li-ji_ch-27_p-1","order":3,"canonicalText":"」孔子曰：「丘也小人，不足以知禮。","chunks":[["」孔子曰：「丘也小人，不足以知禮。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-4","passageId":"li-ji_ch-27_p-1","order":4,"canonicalText":"」君曰：「否！","chunks":[["」君曰：「否！","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-5","passageId":"li-ji_ch-27_p-1","order":5,"canonicalText":"吾子言之也。","chunks":[["吾子言之也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-6","passageId":"li-ji_ch-27_p-1","order":6,"canonicalText":"」孔子曰：「丘聞之：民之所由生，禮為大。","chunks":[["」孔子曰：「丘聞之：民之所由生，禮為大。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-7","passageId":"li-ji_ch-27_p-1","order":7,"canonicalText":"非禮無以節事天地之神也，非禮無以辨君臣上下長幼之位也，非禮無以別男女父子兄弟之親、昏姻疏數之交也；","chunks":[["非禮無以節事天地之神也，非禮無以辨君臣上下長幼之位也，非禮無以別男女父子兄弟之親、昏姻疏數之交也；","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-8","passageId":"li-ji_ch-27_p-1","order":8,"canonicalText":"君子以此之為尊敬然。","chunks":[["君子以此之為尊敬然。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-9","passageId":"li-ji_ch-27_p-1","order":9,"canonicalText":"然後以其所能教百姓，不廢其會節。","chunks":[["然後以其所能教百姓，不廢其會節。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-10","passageId":"li-ji_ch-27_p-1","order":10,"canonicalText":"有成事，然後治其雕鏤文章黼黻以嗣。","chunks":[["有成事，然後治其雕鏤文章黼黻以嗣。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-11","passageId":"li-ji_ch-27_p-1","order":11,"canonicalText":"其順之，然後言其喪算，備其鼎俎，設其豕臘，修其宗廟，歲時以敬祭祀，以序宗族。","chunks":[["其順之，然後言其喪算，備其鼎俎，設其豕臘，修其宗廟，歲時以敬祭祀，以序宗族。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-12","passageId":"li-ji_ch-27_p-1","order":12,"canonicalText":"即安其居，節醜其衣服，卑其宮室，車不雕几，器不刻鏤，食不貳味，以與民同利。","chunks":[["即安其居，節醜其衣服，卑其宮室，車不雕几，器不刻鏤，食不貳味，以與民同利。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-13","passageId":"li-ji_ch-27_p-1","order":13,"canonicalText":"昔之君子之行禮者如此。","chunks":[["昔之君子之行禮者如此。","zh-Hant"]]},{"id":"li-ji_ch-27_p-1_s-14","passageId":"li-ji_ch-27_p-1","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-1","passageId":"li-ji_ch-27_p-2","order":1,"canonicalText":"公曰：「今之君子胡莫行之也？","chunks":[["公曰：「今之君子胡莫行之也？","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-2","passageId":"li-ji_ch-27_p-2","order":2,"canonicalText":"」孔子曰：「今之君子，好實無厭，淫德不倦，荒怠傲慢，固民是盡，午其眾以伐有道；","chunks":[["」孔子曰：「今之君子，好實無厭，淫德不倦，荒怠傲慢，固民是盡，午其眾以伐有道；","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-3","passageId":"li-ji_ch-27_p-2","order":3,"canonicalText":"求得當欲，不以其所。","chunks":[["求得當欲，不以其所。","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-4","passageId":"li-ji_ch-27_p-2","order":4,"canonicalText":"昔之用民者由前，今之用民者由後。","chunks":[["昔之用民者由前，今之用民者由後。","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-5","passageId":"li-ji_ch-27_p-2","order":5,"canonicalText":"今之君子莫為禮也。","chunks":[["今之君子莫為禮也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-2_s-6","passageId":"li-ji_ch-27_p-2","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-3_s-1","passageId":"li-ji_ch-27_p-3","order":1,"canonicalText":"孔子侍坐於哀公，哀公曰：「敢問人道誰為大？","chunks":[["孔子侍坐於哀公，哀公曰：「敢問人道誰為大？","zh-Hant"]]},{"id":"li-ji_ch-27_p-3_s-2","passageId":"li-ji_ch-27_p-3","order":2,"canonicalText":"」孔子愀然作色而對曰：「君之及此言也，百姓之德也！","chunks":[["」孔子愀然作色而對曰：「君之及此言也，百姓之德也！","zh-Hant"]]},{"id":"li-ji_ch-27_p-3_s-3","passageId":"li-ji_ch-27_p-3","order":3,"canonicalText":"碧臣敢無辭而對？","chunks":[["碧臣敢無辭而對？","zh-Hant"]]},{"id":"li-ji_ch-27_p-3_s-4","passageId":"li-ji_ch-27_p-3","order":4,"canonicalText":"人道，政為大。","chunks":[["人道，政為大。","zh-Hant"]]},{"id":"li-ji_ch-27_p-3_s-5","passageId":"li-ji_ch-27_p-3","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-1","passageId":"li-ji_ch-27_p-4","order":1,"canonicalText":"公曰：「敢問何謂為政？","chunks":[["公曰：「敢問何謂為政？","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-2","passageId":"li-ji_ch-27_p-4","order":2,"canonicalText":"」孔子對曰：「政者正也。","chunks":[["」孔子對曰：「政者正也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-3","passageId":"li-ji_ch-27_p-4","order":3,"canonicalText":"君為正，則百姓從政矣。","chunks":[["君為正，則百姓從政矣。","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-4","passageId":"li-ji_ch-27_p-4","order":4,"canonicalText":"君之所為，百姓之所從也。","chunks":[["君之所為，百姓之所從也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-5","passageId":"li-ji_ch-27_p-4","order":5,"canonicalText":"君所不為，百姓何從？","chunks":[["君所不為，百姓何從？","zh-Hant"]]},{"id":"li-ji_ch-27_p-4_s-6","passageId":"li-ji_ch-27_p-4","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-5_s-1","passageId":"li-ji_ch-27_p-5","order":1,"canonicalText":"公曰：「敢問為政如之何？","chunks":[["公曰：「敢問為政如之何？","zh-Hant"]]},{"id":"li-ji_ch-27_p-5_s-2","passageId":"li-ji_ch-27_p-5","order":2,"canonicalText":"」孔子對曰：「夫婦別，父子親，君臣嚴。","chunks":[["」孔子對曰：「夫婦別，父子親，君臣嚴。","zh-Hant"]]},{"id":"li-ji_ch-27_p-5_s-3","passageId":"li-ji_ch-27_p-5","order":3,"canonicalText":"三者正，則庶物從之矣。","chunks":[["三者正，則庶物從之矣。","zh-Hant"]]},{"id":"li-ji_ch-27_p-5_s-4","passageId":"li-ji_ch-27_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-1","passageId":"li-ji_ch-27_p-6","order":1,"canonicalText":"公曰：「寡人雖無似也，愿聞所以行三言之道，可得聞乎？","chunks":[["公曰：「寡人雖無似也，愿聞所以行三言之道，可得聞乎？","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-2","passageId":"li-ji_ch-27_p-6","order":2,"canonicalText":"」孔子對曰：「古之為政，愛人為大；","chunks":[["」孔子對曰：「古之為政，愛人為大；","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-3","passageId":"li-ji_ch-27_p-6","order":3,"canonicalText":"所以治愛人，禮為大；","chunks":[["所以治愛人，禮為大；","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-4","passageId":"li-ji_ch-27_p-6","order":4,"canonicalText":"所以治禮，敬為大；","chunks":[["所以治禮，敬為大；","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-5","passageId":"li-ji_ch-27_p-6","order":5,"canonicalText":"敬之至矣，大昏為大。","chunks":[["敬之至矣，大昏為大。","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-6","passageId":"li-ji_ch-27_p-6","order":6,"canonicalText":"大昏至矣！","chunks":[["大昏至矣！","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-7","passageId":"li-ji_ch-27_p-6","order":7,"canonicalText":"大昏既至，冕而親迎，親之也。","chunks":[["大昏既至，冕而親迎，親之也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-8","passageId":"li-ji_ch-27_p-6","order":8,"canonicalText":"親之也者，親之也。","chunks":[["親之也者，親之也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-9","passageId":"li-ji_ch-27_p-6","order":9,"canonicalText":"是故，君子興敬為親；","chunks":[["是故，君子興敬為親；","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-10","passageId":"li-ji_ch-27_p-6","order":10,"canonicalText":"舍敬，是遺親也。","chunks":[["舍敬，是遺親也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-11","passageId":"li-ji_ch-27_p-6","order":11,"canonicalText":"弗愛不親；","chunks":[["弗愛不親；","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-12","passageId":"li-ji_ch-27_p-6","order":12,"canonicalText":"弗敬不正。","chunks":[["弗敬不正。","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-13","passageId":"li-ji_ch-27_p-6","order":13,"canonicalText":"愛與敬，其政之本與！","chunks":[["愛與敬，其政之本與！","zh-Hant"]]},{"id":"li-ji_ch-27_p-6_s-14","passageId":"li-ji_ch-27_p-6","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-7_s-1","passageId":"li-ji_ch-27_p-7","order":1,"canonicalText":"公曰：「寡人愿有言。","chunks":[["公曰：「寡人愿有言。","zh-Hant"]]},{"id":"li-ji_ch-27_p-7_s-2","passageId":"li-ji_ch-27_p-7","order":2,"canonicalText":"然冕而親迎，不已重乎？","chunks":[["然冕而親迎，不已重乎？","zh-Hant"]]},{"id":"li-ji_ch-27_p-7_s-3","passageId":"li-ji_ch-27_p-7","order":3,"canonicalText":"」孔子愀然作色而對曰：「合二姓之好，以繼先聖之後，以為天地宗廟社稷之主，君何謂已重乎？","chunks":[["」孔子愀然作色而對曰：「合二姓之好，以繼先聖之後，以為天地宗廟社稷之主，君何謂已重乎？","zh-Hant"]]},{"id":"li-ji_ch-27_p-7_s-4","passageId":"li-ji_ch-27_p-7","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-1","passageId":"li-ji_ch-27_p-8","order":1,"canonicalText":"公曰：「寡人固！","chunks":[["公曰：「寡人固！","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-2","passageId":"li-ji_ch-27_p-8","order":2,"canonicalText":"不固，焉得聞此言也。","chunks":[["不固，焉得聞此言也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-3","passageId":"li-ji_ch-27_p-8","order":3,"canonicalText":"寡人欲問，不得其辭，請少進！","chunks":[["寡人欲問，不得其辭，請少進！","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-4","passageId":"li-ji_ch-27_p-8","order":4,"canonicalText":"」孔子曰：「天地不合，萬物不生。","chunks":[["」孔子曰：「天地不合，萬物不生。","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-5","passageId":"li-ji_ch-27_p-8","order":5,"canonicalText":"大昏，萬世之嗣也，君何謂已重焉！","chunks":[["大昏，萬世之嗣也，君何謂已重焉！","zh-Hant"]]},{"id":"li-ji_ch-27_p-8_s-6","passageId":"li-ji_ch-27_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-1","passageId":"li-ji_ch-27_p-9","order":1,"canonicalText":"孔子遂言曰：「內以治宗廟之禮，足以配天地之神明；","chunks":[["孔子遂言曰：「內以治宗廟之禮，足以配天地之神明；","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-2","passageId":"li-ji_ch-27_p-9","order":2,"canonicalText":"出以治直言之禮，足以立上下之敬。","chunks":[["出以治直言之禮，足以立上下之敬。","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-3","passageId":"li-ji_ch-27_p-9","order":3,"canonicalText":"物恥足以振之，國恥足以興之。","chunks":[["物恥足以振之，國恥足以興之。","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-4","passageId":"li-ji_ch-27_p-9","order":4,"canonicalText":"為政先禮。","chunks":[["為政先禮。","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-5","passageId":"li-ji_ch-27_p-9","order":5,"canonicalText":"禮，其政之本與！","chunks":[["禮，其政之本與！","zh-Hant"]]},{"id":"li-ji_ch-27_p-9_s-6","passageId":"li-ji_ch-27_p-9","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-1","passageId":"li-ji_ch-27_p-10","order":1,"canonicalText":"孔子遂言曰：「昔三代明王之政，必敬其妻子也，有道。","chunks":[["孔子遂言曰：「昔三代明王之政，必敬其妻子也，有道。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-2","passageId":"li-ji_ch-27_p-10","order":2,"canonicalText":"妻也者，親之主也，敢不敬與？","chunks":[["妻也者，親之主也，敢不敬與？","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-3","passageId":"li-ji_ch-27_p-10","order":3,"canonicalText":"子也者，親之後也，敢不敬與？","chunks":[["子也者，親之後也，敢不敬與？","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-4","passageId":"li-ji_ch-27_p-10","order":4,"canonicalText":"君子無不敬也，敬身為大。","chunks":[["君子無不敬也，敬身為大。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-5","passageId":"li-ji_ch-27_p-10","order":5,"canonicalText":"身也者，親之枝也，敢不敬與？","chunks":[["身也者，親之枝也，敢不敬與？","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-6","passageId":"li-ji_ch-27_p-10","order":6,"canonicalText":"不能敬其身，是傷其親；","chunks":[["不能敬其身，是傷其親；","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-7","passageId":"li-ji_ch-27_p-10","order":7,"canonicalText":"傷其親，是傷其本；","chunks":[["傷其親，是傷其本；","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-8","passageId":"li-ji_ch-27_p-10","order":8,"canonicalText":"傷其本，枝從而亡。","chunks":[["傷其本，枝從而亡。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-9","passageId":"li-ji_ch-27_p-10","order":9,"canonicalText":"三者，百姓之象也。","chunks":[["三者，百姓之象也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-10","passageId":"li-ji_ch-27_p-10","order":10,"canonicalText":"身以及身，子以及子，妃以及妃，君行此三者，則愾乎天下矣，大王之道也。","chunks":[["身以及身，子以及子，妃以及妃，君行此三者，則愾乎天下矣，大王之道也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-11","passageId":"li-ji_ch-27_p-10","order":11,"canonicalText":"如此，國家順矣。","chunks":[["如此，國家順矣。","zh-Hant"]]},{"id":"li-ji_ch-27_p-10_s-12","passageId":"li-ji_ch-27_p-10","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-1","passageId":"li-ji_ch-27_p-11","order":1,"canonicalText":"公曰：「敢問何謂敬身？","chunks":[["公曰：「敢問何謂敬身？","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-2","passageId":"li-ji_ch-27_p-11","order":2,"canonicalText":"」孔子對曰：「君子過言，則民作辭；","chunks":[["」孔子對曰：「君子過言，則民作辭；","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-3","passageId":"li-ji_ch-27_p-11","order":3,"canonicalText":"過動，則民作則。","chunks":[["過動，則民作則。","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-4","passageId":"li-ji_ch-27_p-11","order":4,"canonicalText":"君子言不過辭，動不過則，百姓不命而敬恭，如是，則能敬其身；","chunks":[["君子言不過辭，動不過則，百姓不命而敬恭，如是，則能敬其身；","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-5","passageId":"li-ji_ch-27_p-11","order":5,"canonicalText":"能敬其身，則能成其親矣。","chunks":[["能敬其身，則能成其親矣。","zh-Hant"]]},{"id":"li-ji_ch-27_p-11_s-6","passageId":"li-ji_ch-27_p-11","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-12_s-1","passageId":"li-ji_ch-27_p-12","order":1,"canonicalText":"公曰：「敢問何謂成親？","chunks":[["公曰：「敢問何謂成親？","zh-Hant"]]},{"id":"li-ji_ch-27_p-12_s-2","passageId":"li-ji_ch-27_p-12","order":2,"canonicalText":"」孔子對曰：「君子也者，人之成名也。","chunks":[["」孔子對曰：「君子也者，人之成名也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-12_s-3","passageId":"li-ji_ch-27_p-12","order":3,"canonicalText":"百姓歸之名，謂之君子之子。","chunks":[["百姓歸之名，謂之君子之子。","zh-Hant"]]},{"id":"li-ji_ch-27_p-12_s-4","passageId":"li-ji_ch-27_p-12","order":4,"canonicalText":"是使其親為君子也，是為成其親之名也已！","chunks":[["是使其親為君子也，是為成其親之名也已！","zh-Hant"]]},{"id":"li-ji_ch-27_p-12_s-5","passageId":"li-ji_ch-27_p-12","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-1","passageId":"li-ji_ch-27_p-13","order":1,"canonicalText":"孔子遂言曰：「古之為政，愛人為大。","chunks":[["孔子遂言曰：「古之為政，愛人為大。","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-2","passageId":"li-ji_ch-27_p-13","order":2,"canonicalText":"不能愛人，不能有其身；","chunks":[["不能愛人，不能有其身；","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-3","passageId":"li-ji_ch-27_p-13","order":3,"canonicalText":"不能有其身，不能安土；","chunks":[["不能有其身，不能安土；","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-4","passageId":"li-ji_ch-27_p-13","order":4,"canonicalText":"不能安土，不能樂天；","chunks":[["不能安土，不能樂天；","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-5","passageId":"li-ji_ch-27_p-13","order":5,"canonicalText":"不能樂天，不能成其身。","chunks":[["不能樂天，不能成其身。","zh-Hant"]]},{"id":"li-ji_ch-27_p-13_s-6","passageId":"li-ji_ch-27_p-13","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-14_s-1","passageId":"li-ji_ch-27_p-14","order":1,"canonicalText":"公曰：「敢問何謂成身？","chunks":[["公曰：「敢問何謂成身？","zh-Hant"]]},{"id":"li-ji_ch-27_p-14_s-2","passageId":"li-ji_ch-27_p-14","order":2,"canonicalText":"」孔子對曰：「不過乎物。","chunks":[["」孔子對曰：「不過乎物。","zh-Hant"]]},{"id":"li-ji_ch-27_p-14_s-3","passageId":"li-ji_ch-27_p-14","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-1","passageId":"li-ji_ch-27_p-15","order":1,"canonicalText":"公曰：「敢問君子何貴乎天道也？","chunks":[["公曰：「敢問君子何貴乎天道也？","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-2","passageId":"li-ji_ch-27_p-15","order":2,"canonicalText":"」孔子對曰：「貴其『不已』。","chunks":[["」孔子對曰：「貴其『不已』。","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-3","passageId":"li-ji_ch-27_p-15","order":3,"canonicalText":"如日月東西相從而不已也，是天道也；","chunks":[["如日月東西相從而不已也，是天道也；","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-4","passageId":"li-ji_ch-27_p-15","order":4,"canonicalText":"不閉其久，是天道也；","chunks":[["不閉其久，是天道也；","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-5","passageId":"li-ji_ch-27_p-15","order":5,"canonicalText":"無為而物成，是天道也；","chunks":[["無為而物成，是天道也；","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-6","passageId":"li-ji_ch-27_p-15","order":6,"canonicalText":"已成而明，是天道也。","chunks":[["已成而明，是天道也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-15_s-7","passageId":"li-ji_ch-27_p-15","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-16_s-1","passageId":"li-ji_ch-27_p-16","order":1,"canonicalText":"公曰：「寡人蠢愚，冥煩子志之心也。","chunks":[["公曰：「寡人蠢愚，冥煩子志之心也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-16_s-2","passageId":"li-ji_ch-27_p-16","order":2,"canonicalText":"」孔子蹴然辟席而對曰：「仁人不過乎物，孝子不過乎物。","chunks":[["」孔子蹴然辟席而對曰：「仁人不過乎物，孝子不過乎物。","zh-Hant"]]},{"id":"li-ji_ch-27_p-16_s-3","passageId":"li-ji_ch-27_p-16","order":3,"canonicalText":"是故，仁人之事親也如事天，事天如事親，是故孝子成身。","chunks":[["是故，仁人之事親也如事天，事天如事親，是故孝子成身。","zh-Hant"]]},{"id":"li-ji_ch-27_p-16_s-4","passageId":"li-ji_ch-27_p-16","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-27_p-17_s-1","passageId":"li-ji_ch-27_p-17","order":1,"canonicalText":"公曰：「寡人既聞此言也，無如後罪何？","chunks":[["公曰：「寡人既聞此言也，無如後罪何？","zh-Hant"]]},{"id":"li-ji_ch-27_p-17_s-2","passageId":"li-ji_ch-27_p-17","order":2,"canonicalText":"」孔子對曰：「君之及此言也，是臣之福也。","chunks":[["」孔子對曰：「君之及此言也，是臣之福也。","zh-Hant"]]},{"id":"li-ji_ch-27_p-17_s-3","passageId":"li-ji_ch-27_p-17","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-1","passageId":"li-ji_ch-28_p-1","order":1,"canonicalText":"仲尼燕居，子張、子貢、言游侍，縱言至於禮。","chunks":[["仲尼燕居，子張、子貢、言游侍，縱言至於禮。","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-2","passageId":"li-ji_ch-28_p-1","order":2,"canonicalText":"子曰：「居！","chunks":[["子曰：「居！","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-3","passageId":"li-ji_ch-28_p-1","order":3,"canonicalText":"女三人者，吾語女禮，使女以禮周流無不遍也。","chunks":[["女三人者，吾語女禮，使女以禮周流無不遍也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-4","passageId":"li-ji_ch-28_p-1","order":4,"canonicalText":"」子貢越席而對曰：「敢問何如？","chunks":[["」子貢越席而對曰：「敢問何如？","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-5","passageId":"li-ji_ch-28_p-1","order":5,"canonicalText":"」子曰：「敬而不中禮，謂之野；","chunks":[["」子曰：「敬而不中禮，謂之野；","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-6","passageId":"li-ji_ch-28_p-1","order":6,"canonicalText":"恭而不中禮，謂之給；","chunks":[["恭而不中禮，謂之給；","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-7","passageId":"li-ji_ch-28_p-1","order":7,"canonicalText":"勇而不中禮，謂之逆。","chunks":[["勇而不中禮，謂之逆。","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-8","passageId":"li-ji_ch-28_p-1","order":8,"canonicalText":"」子曰：「給奪慈仁。","chunks":[["」子曰：「給奪慈仁。","zh-Hant"]]},{"id":"li-ji_ch-28_p-1_s-9","passageId":"li-ji_ch-28_p-1","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-1","passageId":"li-ji_ch-28_p-2","order":1,"canonicalText":"子曰：「師，爾過；","chunks":[["子曰：「師，爾過；","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-2","passageId":"li-ji_ch-28_p-2","order":2,"canonicalText":"而商也不及。","chunks":[["而商也不及。","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-3","passageId":"li-ji_ch-28_p-2","order":3,"canonicalText":"子產猶眾人之母也，能食之不能教也。","chunks":[["子產猶眾人之母也，能食之不能教也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-4","passageId":"li-ji_ch-28_p-2","order":4,"canonicalText":"」子貢越席而對曰：「敢問將何以為此中者也？","chunks":[["」子貢越席而對曰：「敢問將何以為此中者也？","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-5","passageId":"li-ji_ch-28_p-2","order":5,"canonicalText":"」子曰：「禮乎禮！","chunks":[["」子曰：「禮乎禮！","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-6","passageId":"li-ji_ch-28_p-2","order":6,"canonicalText":"夫禮所以制中也。","chunks":[["夫禮所以制中也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-2_s-7","passageId":"li-ji_ch-28_p-2","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-1","passageId":"li-ji_ch-28_p-3","order":1,"canonicalText":"子貢退，言游進曰：「敢問禮也者，領惡而全好者與？","chunks":[["子貢退，言游進曰：「敢問禮也者，領惡而全好者與？","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-2","passageId":"li-ji_ch-28_p-3","order":2,"canonicalText":"」子曰：「然。","chunks":[["」子曰：「然。","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-3","passageId":"li-ji_ch-28_p-3","order":3,"canonicalText":"」「然則何如？","chunks":[["」「然則何如？","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-4","passageId":"li-ji_ch-28_p-3","order":4,"canonicalText":"」子曰：「郊社之義，所以仁鬼神也；","chunks":[["」子曰：「郊社之義，所以仁鬼神也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-5","passageId":"li-ji_ch-28_p-3","order":5,"canonicalText":"嘗禘之禮，所以仁昭穆也；","chunks":[["嘗禘之禮，所以仁昭穆也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-6","passageId":"li-ji_ch-28_p-3","order":6,"canonicalText":"饋奠之禮，所以仁死喪也；","chunks":[["饋奠之禮，所以仁死喪也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-7","passageId":"li-ji_ch-28_p-3","order":7,"canonicalText":"射鄉之禮，所以仁鄉黨也；","chunks":[["射鄉之禮，所以仁鄉黨也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-8","passageId":"li-ji_ch-28_p-3","order":8,"canonicalText":"食饗之禮，所以仁賓客也。","chunks":[["食饗之禮，所以仁賓客也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-3_s-9","passageId":"li-ji_ch-28_p-3","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-1","passageId":"li-ji_ch-28_p-4","order":1,"canonicalText":"子曰：「明乎郊社之義、嘗禘之禮，治國其如指諸掌而已乎！","chunks":[["子曰：「明乎郊社之義、嘗禘之禮，治國其如指諸掌而已乎！","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-2","passageId":"li-ji_ch-28_p-4","order":2,"canonicalText":"是故，以之居處有禮，故長幼辨也。","chunks":[["是故，以之居處有禮，故長幼辨也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-3","passageId":"li-ji_ch-28_p-4","order":3,"canonicalText":"以之閨門之內有禮，故三族和也。","chunks":[["以之閨門之內有禮，故三族和也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-4","passageId":"li-ji_ch-28_p-4","order":4,"canonicalText":"以之朝廷有禮，故官爵序也。","chunks":[["以之朝廷有禮，故官爵序也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-5","passageId":"li-ji_ch-28_p-4","order":5,"canonicalText":"以之田獵有禮，故戎事閑也。","chunks":[["以之田獵有禮，故戎事閑也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-6","passageId":"li-ji_ch-28_p-4","order":6,"canonicalText":"以之軍旅有禮，故武功成也。","chunks":[["以之軍旅有禮，故武功成也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-7","passageId":"li-ji_ch-28_p-4","order":7,"canonicalText":"是故，宮室得其度，量鼎得其象，味得其時，樂得其節，車得其式，鬼神得其饗，喪紀得其哀，辨說得其黨，官得其體，政事得其施；","chunks":[["是故，宮室得其度，量鼎得其象，味得其時，樂得其節，車得其式，鬼神得其饗，喪紀得其哀，辨說得其黨，官得其體，政事得其施；","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-8","passageId":"li-ji_ch-28_p-4","order":8,"canonicalText":"加於身而錯於前，凡眾之動得其宜。","chunks":[["加於身而錯於前，凡眾之動得其宜。","zh-Hant"]]},{"id":"li-ji_ch-28_p-4_s-9","passageId":"li-ji_ch-28_p-4","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-1","passageId":"li-ji_ch-28_p-5","order":1,"canonicalText":"子曰：「禮者何也？","chunks":[["子曰：「禮者何也？","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-2","passageId":"li-ji_ch-28_p-5","order":2,"canonicalText":"即事之治也。","chunks":[["即事之治也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-3","passageId":"li-ji_ch-28_p-5","order":3,"canonicalText":"君子有其事，必有其治。","chunks":[["君子有其事，必有其治。","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-4","passageId":"li-ji_ch-28_p-5","order":4,"canonicalText":"治國而無禮，譬猶瞽之無相與？","chunks":[["治國而無禮，譬猶瞽之無相與？","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-5","passageId":"li-ji_ch-28_p-5","order":5,"canonicalText":"倀倀其何之？","chunks":[["倀倀其何之？","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-6","passageId":"li-ji_ch-28_p-5","order":6,"canonicalText":"譬如終夜有求於幽室之中，非燭何見？","chunks":[["譬如終夜有求於幽室之中，非燭何見？","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-7","passageId":"li-ji_ch-28_p-5","order":7,"canonicalText":"若無禮則手足無所錯，耳目無所加，進退揖讓無所制。","chunks":[["若無禮則手足無所錯，耳目無所加，進退揖讓無所制。","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-8","passageId":"li-ji_ch-28_p-5","order":8,"canonicalText":"是故，以之居處，長幼失其別；","chunks":[["是故，以之居處，長幼失其別；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-9","passageId":"li-ji_ch-28_p-5","order":9,"canonicalText":"閨門，三族失其和；","chunks":[["閨門，三族失其和；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-10","passageId":"li-ji_ch-28_p-5","order":10,"canonicalText":"朝廷，官爵失其序；","chunks":[["朝廷，官爵失其序；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-11","passageId":"li-ji_ch-28_p-5","order":11,"canonicalText":"田獵，戎事失其策；","chunks":[["田獵，戎事失其策；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-12","passageId":"li-ji_ch-28_p-5","order":12,"canonicalText":"軍旅，武功失其制；","chunks":[["軍旅，武功失其制；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-13","passageId":"li-ji_ch-28_p-5","order":13,"canonicalText":"宮室，失其度；","chunks":[["宮室，失其度；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-14","passageId":"li-ji_ch-28_p-5","order":14,"canonicalText":"量鼎，失其象；","chunks":[["量鼎，失其象；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-15","passageId":"li-ji_ch-28_p-5","order":15,"canonicalText":"味，失其時；","chunks":[["味，失其時；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-16","passageId":"li-ji_ch-28_p-5","order":16,"canonicalText":"樂，失其節；","chunks":[["樂，失其節；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-17","passageId":"li-ji_ch-28_p-5","order":17,"canonicalText":"車，失其式；","chunks":[["車，失其式；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-18","passageId":"li-ji_ch-28_p-5","order":18,"canonicalText":"鬼神，失其饗；","chunks":[["鬼神，失其饗；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-19","passageId":"li-ji_ch-28_p-5","order":19,"canonicalText":"喪紀，失其哀；","chunks":[["喪紀，失其哀；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-20","passageId":"li-ji_ch-28_p-5","order":20,"canonicalText":"辯說，失其黨；","chunks":[["辯說，失其黨；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-21","passageId":"li-ji_ch-28_p-5","order":21,"canonicalText":"官，失其體；","chunks":[["官，失其體；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-22","passageId":"li-ji_ch-28_p-5","order":22,"canonicalText":"政事，失其施；","chunks":[["政事，失其施；","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-23","passageId":"li-ji_ch-28_p-5","order":23,"canonicalText":"加於身而錯於前，凡眾之動，失其宜。","chunks":[["加於身而錯於前，凡眾之動，失其宜。","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-24","passageId":"li-ji_ch-28_p-5","order":24,"canonicalText":"如此，則無以祖洽於眾也。","chunks":[["如此，則無以祖洽於眾也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-5_s-25","passageId":"li-ji_ch-28_p-5","order":25,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-1","passageId":"li-ji_ch-28_p-6","order":1,"canonicalText":"子曰：「慎聽之！","chunks":[["子曰：「慎聽之！","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-2","passageId":"li-ji_ch-28_p-6","order":2,"canonicalText":"女三人者，吾語女：禮猶有九焉，大饗有四焉。","chunks":[["女三人者，吾語女：禮猶有九焉，大饗有四焉。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-3","passageId":"li-ji_ch-28_p-6","order":3,"canonicalText":"茍知此矣，雖在畎畝之中事之，聖人已。","chunks":[["茍知此矣，雖在畎畝之中事之，聖人已。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-4","passageId":"li-ji_ch-28_p-6","order":4,"canonicalText":"兩君相見，揖讓而入門，入門而縣興；","chunks":[["兩君相見，揖讓而入門，入門而縣興；","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-5","passageId":"li-ji_ch-28_p-6","order":5,"canonicalText":"揖讓而升堂，升堂而樂闋。","chunks":[["揖讓而升堂，升堂而樂闋。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-6","passageId":"li-ji_ch-28_p-6","order":6,"canonicalText":"下管《象》、《武》，《夏》、《龠》序興。","chunks":[["下管《象》、《武》，《夏》、《龠》序興。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-7","passageId":"li-ji_ch-28_p-6","order":7,"canonicalText":"陳其薦俎，序其禮樂，備其百官。","chunks":[["陳其薦俎，序其禮樂，備其百官。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-8","passageId":"li-ji_ch-28_p-6","order":8,"canonicalText":"如此，而後君子知仁焉。","chunks":[["如此，而後君子知仁焉。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-9","passageId":"li-ji_ch-28_p-6","order":9,"canonicalText":"行中規，還中矩，和鸞中采齊，客出以雍，徹以振羽。","chunks":[["行中規，還中矩，和鸞中采齊，客出以雍，徹以振羽。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-10","passageId":"li-ji_ch-28_p-6","order":10,"canonicalText":"是故，君子無物而不在禮矣。","chunks":[["是故，君子無物而不在禮矣。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-11","passageId":"li-ji_ch-28_p-6","order":11,"canonicalText":"入門而金作，示情也。","chunks":[["入門而金作，示情也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-12","passageId":"li-ji_ch-28_p-6","order":12,"canonicalText":"升歌《清廟》，示德也。","chunks":[["升歌《清廟》，示德也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-13","passageId":"li-ji_ch-28_p-6","order":13,"canonicalText":"下而管《象》，示事也。","chunks":[["下而管《象》，示事也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-14","passageId":"li-ji_ch-28_p-6","order":14,"canonicalText":"是故古之君子，不必親相與言也，以禮樂相示而已。","chunks":[["是故古之君子，不必親相與言也，以禮樂相示而已。","zh-Hant"]]},{"id":"li-ji_ch-28_p-6_s-15","passageId":"li-ji_ch-28_p-6","order":15,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-1","passageId":"li-ji_ch-28_p-7","order":1,"canonicalText":"子曰：「禮也者，理也；","chunks":[["子曰：「禮也者，理也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-2","passageId":"li-ji_ch-28_p-7","order":2,"canonicalText":"樂也者，節也。","chunks":[["樂也者，節也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-3","passageId":"li-ji_ch-28_p-7","order":3,"canonicalText":"君子無理不動，無節不作。","chunks":[["君子無理不動，無節不作。","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-4","passageId":"li-ji_ch-28_p-7","order":4,"canonicalText":"不能《詩》，於禮繆；","chunks":[["不能《詩》，於禮繆；","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-5","passageId":"li-ji_ch-28_p-7","order":5,"canonicalText":"不能樂，於禮素；","chunks":[["不能樂，於禮素；","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-6","passageId":"li-ji_ch-28_p-7","order":6,"canonicalText":"薄於德，於禮虛。","chunks":[["薄於德，於禮虛。","zh-Hant"]]},{"id":"li-ji_ch-28_p-7_s-7","passageId":"li-ji_ch-28_p-7","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-8_s-1","passageId":"li-ji_ch-28_p-8","order":1,"canonicalText":"子曰：「制度在禮，文為在禮，行之，其在人乎！","chunks":[["子曰：「制度在禮，文為在禮，行之，其在人乎！","zh-Hant"]]},{"id":"li-ji_ch-28_p-8_s-2","passageId":"li-ji_ch-28_p-8","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-1","passageId":"li-ji_ch-28_p-9","order":1,"canonicalText":"子貢越席而對曰：「敢問：夔其窮與？","chunks":[["子貢越席而對曰：「敢問：夔其窮與？","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-2","passageId":"li-ji_ch-28_p-9","order":2,"canonicalText":"」子曰：「古之人與？","chunks":[["」子曰：「古之人與？","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-3","passageId":"li-ji_ch-28_p-9","order":3,"canonicalText":"古之人也。","chunks":[["古之人也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-4","passageId":"li-ji_ch-28_p-9","order":4,"canonicalText":"達於禮而不達於樂，謂之素；","chunks":[["達於禮而不達於樂，謂之素；","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-5","passageId":"li-ji_ch-28_p-9","order":5,"canonicalText":"達於樂而不達於禮，謂之偏。","chunks":[["達於樂而不達於禮，謂之偏。","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-6","passageId":"li-ji_ch-28_p-9","order":6,"canonicalText":"夫夔，達於樂而不達於禮，是以傳此名也，古之人也。","chunks":[["夫夔，達於樂而不達於禮，是以傳此名也，古之人也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-9_s-7","passageId":"li-ji_ch-28_p-9","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-1","passageId":"li-ji_ch-28_p-10","order":1,"canonicalText":"子張問政，子曰：「師乎！","chunks":[["子張問政，子曰：「師乎！","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-2","passageId":"li-ji_ch-28_p-10","order":2,"canonicalText":"前，吾語女乎？","chunks":[["前，吾語女乎？","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-3","passageId":"li-ji_ch-28_p-10","order":3,"canonicalText":"君子明於禮樂，舉而錯之而已。","chunks":[["君子明於禮樂，舉而錯之而已。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-4","passageId":"li-ji_ch-28_p-10","order":4,"canonicalText":"」子張復問。","chunks":[["」子張復問。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-5","passageId":"li-ji_ch-28_p-10","order":5,"canonicalText":"子曰：「師，爾以為必鋪几筵，升降酌獻酬酢，然後謂之禮乎？","chunks":[["子曰：「師，爾以為必鋪几筵，升降酌獻酬酢，然後謂之禮乎？","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-6","passageId":"li-ji_ch-28_p-10","order":6,"canonicalText":"爾以為必行綴兆。","chunks":[["爾以為必行綴兆。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-7","passageId":"li-ji_ch-28_p-10","order":7,"canonicalText":"興羽龠，作鐘鼓，然後謂之樂乎？","chunks":[["興羽龠，作鐘鼓，然後謂之樂乎？","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-8","passageId":"li-ji_ch-28_p-10","order":8,"canonicalText":"言而履之，禮也。","chunks":[["言而履之，禮也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-9","passageId":"li-ji_ch-28_p-10","order":9,"canonicalText":"行而樂之，樂也。","chunks":[["行而樂之，樂也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-10","passageId":"li-ji_ch-28_p-10","order":10,"canonicalText":"君子力此二者以南面而立，夫是以天下太平也。","chunks":[["君子力此二者以南面而立，夫是以天下太平也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-11","passageId":"li-ji_ch-28_p-10","order":11,"canonicalText":"諸侯朝，萬物服體，而百官莫敢不承事矣。","chunks":[["諸侯朝，萬物服體，而百官莫敢不承事矣。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-12","passageId":"li-ji_ch-28_p-10","order":12,"canonicalText":"禮之所興，眾之所治也；","chunks":[["禮之所興，眾之所治也；","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-13","passageId":"li-ji_ch-28_p-10","order":13,"canonicalText":"禮之所廢，眾之所亂也。","chunks":[["禮之所廢，眾之所亂也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-14","passageId":"li-ji_ch-28_p-10","order":14,"canonicalText":"目巧之室，則有奧阼，席則有上下，車則有左右，行則有隨，立則有序，古之義也。","chunks":[["目巧之室，則有奧阼，席則有上下，車則有左右，行則有隨，立則有序，古之義也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-15","passageId":"li-ji_ch-28_p-10","order":15,"canonicalText":"室而無奧阼，則亂於堂室也。","chunks":[["室而無奧阼，則亂於堂室也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-16","passageId":"li-ji_ch-28_p-10","order":16,"canonicalText":"席而無上下，則亂於席上也。","chunks":[["席而無上下，則亂於席上也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-17","passageId":"li-ji_ch-28_p-10","order":17,"canonicalText":"車而無左右，則亂於車也。","chunks":[["車而無左右，則亂於車也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-18","passageId":"li-ji_ch-28_p-10","order":18,"canonicalText":"行而無隨，則亂於涂也。","chunks":[["行而無隨，則亂於涂也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-19","passageId":"li-ji_ch-28_p-10","order":19,"canonicalText":"立而無序，則亂於位也。","chunks":[["立而無序，則亂於位也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-20","passageId":"li-ji_ch-28_p-10","order":20,"canonicalText":"昔聖帝明王諸侯，辨貴賤、長幼、遠近、男女、外內，莫敢相逾越，皆由此涂出也。","chunks":[["昔聖帝明王諸侯，辨貴賤、長幼、遠近、男女、外內，莫敢相逾越，皆由此涂出也。","zh-Hant"]]},{"id":"li-ji_ch-28_p-10_s-21","passageId":"li-ji_ch-28_p-10","order":21,"canonicalText":"」三子者，既得聞此言也於夫子，昭然若發矇矣。","chunks":[["」三子者，既得聞此言也於夫子，昭然若發矇矣。","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-1","passageId":"li-ji_ch-29_p-1","order":1,"canonicalText":"孔子閒居，子夏侍。","chunks":[["孔子閒居，子夏侍。","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-2","passageId":"li-ji_ch-29_p-1","order":2,"canonicalText":"子夏曰：「敢問《詩》云：『凱弟君子，民之父母』，何如斯可謂民之父母矣？","chunks":[["子夏曰：「敢問《詩》云：『凱弟君子，民之父母』，何如斯可謂民之父母矣？","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-3","passageId":"li-ji_ch-29_p-1","order":3,"canonicalText":"」孔子曰：「夫民之父母乎，必達於禮樂之原，以致五至，而行三無，以橫於天下。","chunks":[["」孔子曰：「夫民之父母乎，必達於禮樂之原，以致五至，而行三無，以橫於天下。","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-4","passageId":"li-ji_ch-29_p-1","order":4,"canonicalText":"四方有敗，必先知之。","chunks":[["四方有敗，必先知之。","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-5","passageId":"li-ji_ch-29_p-1","order":5,"canonicalText":"此之謂民之父母矣。","chunks":[["此之謂民之父母矣。","zh-Hant"]]},{"id":"li-ji_ch-29_p-1_s-6","passageId":"li-ji_ch-29_p-1","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-1","passageId":"li-ji_ch-29_p-2","order":1,"canonicalText":"子夏曰：「民之父母，既得而聞之矣；","chunks":[["子夏曰：「民之父母，既得而聞之矣；","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-2","passageId":"li-ji_ch-29_p-2","order":2,"canonicalText":"敢問何謂『五至』？","chunks":[["敢問何謂『五至』？","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-3","passageId":"li-ji_ch-29_p-2","order":3,"canonicalText":"」孔子曰：「志之所至，詩亦至焉。","chunks":[["」孔子曰：「志之所至，詩亦至焉。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-4","passageId":"li-ji_ch-29_p-2","order":4,"canonicalText":"詩之所至，禮亦至焉。","chunks":[["詩之所至，禮亦至焉。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-5","passageId":"li-ji_ch-29_p-2","order":5,"canonicalText":"禮之所至，樂亦至焉。","chunks":[["禮之所至，樂亦至焉。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-6","passageId":"li-ji_ch-29_p-2","order":6,"canonicalText":"樂之所至，哀亦至焉。","chunks":[["樂之所至，哀亦至焉。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-7","passageId":"li-ji_ch-29_p-2","order":7,"canonicalText":"哀樂相生。","chunks":[["哀樂相生。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-8","passageId":"li-ji_ch-29_p-2","order":8,"canonicalText":"是故，正明目而視之，不可得而見也；","chunks":[["是故，正明目而視之，不可得而見也；","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-9","passageId":"li-ji_ch-29_p-2","order":9,"canonicalText":"傾耳而聽之，不可得而聞也；","chunks":[["傾耳而聽之，不可得而聞也；","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-10","passageId":"li-ji_ch-29_p-2","order":10,"canonicalText":"志氣塞乎天地，此之謂五至。","chunks":[["志氣塞乎天地，此之謂五至。","zh-Hant"]]},{"id":"li-ji_ch-29_p-2_s-11","passageId":"li-ji_ch-29_p-2","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-1","passageId":"li-ji_ch-29_p-3","order":1,"canonicalText":"子夏曰：「五至既得而聞之矣，敢問何謂三無？","chunks":[["子夏曰：「五至既得而聞之矣，敢問何謂三無？","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-2","passageId":"li-ji_ch-29_p-3","order":2,"canonicalText":"」孔子曰：「無聲之樂，無體之禮，無服之喪，此之謂三無。","chunks":[["」孔子曰：「無聲之樂，無體之禮，無服之喪，此之謂三無。","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-3","passageId":"li-ji_ch-29_p-3","order":3,"canonicalText":"」子夏曰：「三無既得略而聞之矣，敢問何詩近之？","chunks":[["」子夏曰：「三無既得略而聞之矣，敢問何詩近之？","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-4","passageId":"li-ji_ch-29_p-3","order":4,"canonicalText":"」孔子曰：「『夙夜其命宥密』，無聲之樂也。","chunks":[["」孔子曰：「『夙夜其命宥密』，無聲之樂也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-5","passageId":"li-ji_ch-29_p-3","order":5,"canonicalText":"『威儀逮逮，不可選也』，無體之禮也。","chunks":[["『威儀逮逮，不可選也』，無體之禮也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-6","passageId":"li-ji_ch-29_p-3","order":6,"canonicalText":"『凡民有喪，匍匐救之』，無服之喪也。","chunks":[["『凡民有喪，匍匐救之』，無服之喪也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-3_s-7","passageId":"li-ji_ch-29_p-3","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-1","passageId":"li-ji_ch-29_p-4","order":1,"canonicalText":"子夏曰：「言則大矣！","chunks":[["子夏曰：「言則大矣！","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-2","passageId":"li-ji_ch-29_p-4","order":2,"canonicalText":"美矣！","chunks":[["美矣！","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-3","passageId":"li-ji_ch-29_p-4","order":3,"canonicalText":"盛矣！","chunks":[["盛矣！","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-4","passageId":"li-ji_ch-29_p-4","order":4,"canonicalText":"言盡於此而已乎？","chunks":[["言盡於此而已乎？","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-5","passageId":"li-ji_ch-29_p-4","order":5,"canonicalText":"」孔子曰：「何為其然也！","chunks":[["」孔子曰：「何為其然也！","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-6","passageId":"li-ji_ch-29_p-4","order":6,"canonicalText":"君子之服之也，猶有五起焉。","chunks":[["君子之服之也，猶有五起焉。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-7","passageId":"li-ji_ch-29_p-4","order":7,"canonicalText":"」子夏曰：「何如？","chunks":[["」子夏曰：「何如？","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-8","passageId":"li-ji_ch-29_p-4","order":8,"canonicalText":"」子曰：「無聲之樂，氣志不違；","chunks":[["」子曰：「無聲之樂，氣志不違；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-9","passageId":"li-ji_ch-29_p-4","order":9,"canonicalText":"無體之禮，威儀遲遲；","chunks":[["無體之禮，威儀遲遲；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-10","passageId":"li-ji_ch-29_p-4","order":10,"canonicalText":"無服之喪，內恕孔悲。","chunks":[["無服之喪，內恕孔悲。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-11","passageId":"li-ji_ch-29_p-4","order":11,"canonicalText":"無聲之樂，氣志既得；","chunks":[["無聲之樂，氣志既得；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-12","passageId":"li-ji_ch-29_p-4","order":12,"canonicalText":"無體之禮，威儀翼翼；","chunks":[["無體之禮，威儀翼翼；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-13","passageId":"li-ji_ch-29_p-4","order":13,"canonicalText":"無服之喪，施及四國。","chunks":[["無服之喪，施及四國。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-14","passageId":"li-ji_ch-29_p-4","order":14,"canonicalText":"無聲之樂，氣志既從；","chunks":[["無聲之樂，氣志既從；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-15","passageId":"li-ji_ch-29_p-4","order":15,"canonicalText":"無體之禮，上下和同；","chunks":[["無體之禮，上下和同；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-16","passageId":"li-ji_ch-29_p-4","order":16,"canonicalText":"無服之喪，以畜萬邦。","chunks":[["無服之喪，以畜萬邦。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-17","passageId":"li-ji_ch-29_p-4","order":17,"canonicalText":"無聲之樂，日聞四方；","chunks":[["無聲之樂，日聞四方；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-18","passageId":"li-ji_ch-29_p-4","order":18,"canonicalText":"無體之禮，日就月將；","chunks":[["無體之禮，日就月將；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-19","passageId":"li-ji_ch-29_p-4","order":19,"canonicalText":"無服之喪，純德孔明。","chunks":[["無服之喪，純德孔明。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-20","passageId":"li-ji_ch-29_p-4","order":20,"canonicalText":"無聲之樂，氣志既起；","chunks":[["無聲之樂，氣志既起；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-21","passageId":"li-ji_ch-29_p-4","order":21,"canonicalText":"無體之禮，施及四海；","chunks":[["無體之禮，施及四海；","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-22","passageId":"li-ji_ch-29_p-4","order":22,"canonicalText":"無服之喪，施于孫子。","chunks":[["無服之喪，施于孫子。","zh-Hant"]]},{"id":"li-ji_ch-29_p-4_s-23","passageId":"li-ji_ch-29_p-4","order":23,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-29_p-5_s-1","passageId":"li-ji_ch-29_p-5","order":1,"canonicalText":"子夏曰：「三王之德，參於天地，敢問：何如斯可謂參於天地矣？","chunks":[["子夏曰：「三王之德，參於天地，敢問：何如斯可謂參於天地矣？","zh-Hant"]]},{"id":"li-ji_ch-29_p-5_s-2","passageId":"li-ji_ch-29_p-5","order":2,"canonicalText":"」孔子曰：「奉三無私以勞天下。","chunks":[["」孔子曰：「奉三無私以勞天下。","zh-Hant"]]},{"id":"li-ji_ch-29_p-5_s-3","passageId":"li-ji_ch-29_p-5","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-1","passageId":"li-ji_ch-29_p-6","order":1,"canonicalText":"子夏曰：「敢問何謂三無私？","chunks":[["子夏曰：「敢問何謂三無私？","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-2","passageId":"li-ji_ch-29_p-6","order":2,"canonicalText":"」孔子曰：「天無私覆，地無私載，日月無私照。","chunks":[["」孔子曰：「天無私覆，地無私載，日月無私照。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-3","passageId":"li-ji_ch-29_p-6","order":3,"canonicalText":"奉斯三者以勞天下，此之謂三無私。","chunks":[["奉斯三者以勞天下，此之謂三無私。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-4","passageId":"li-ji_ch-29_p-6","order":4,"canonicalText":"其在《詩》曰：『帝命不違，至於湯齊。","chunks":[["其在《詩》曰：『帝命不違，至於湯齊。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-5","passageId":"li-ji_ch-29_p-6","order":5,"canonicalText":"湯降不遲，聖敬日齊。","chunks":[["湯降不遲，聖敬日齊。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-6","passageId":"li-ji_ch-29_p-6","order":6,"canonicalText":"昭假遲遲，上帝是祗。","chunks":[["昭假遲遲，上帝是祗。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-7","passageId":"li-ji_ch-29_p-6","order":7,"canonicalText":"帝命式於九圍。","chunks":[["帝命式於九圍。","zh-Hant"]]},{"id":"li-ji_ch-29_p-6_s-8","passageId":"li-ji_ch-29_p-6","order":8,"canonicalText":"』是湯之德也。","chunks":[["』是湯之德也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-1","passageId":"li-ji_ch-29_p-7","order":1,"canonicalText":"「天有四時，春秋冬夏，風雨霜露，無非教也。","chunks":[["「天有四時，春秋冬夏，風雨霜露，無非教也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-2","passageId":"li-ji_ch-29_p-7","order":2,"canonicalText":"地載神氣，神氣風霆，風霆流形，庶物露生，無非教也。","chunks":[["地載神氣，神氣風霆，風霆流形，庶物露生，無非教也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-3","passageId":"li-ji_ch-29_p-7","order":3,"canonicalText":"清明在躬，氣志如神，嗜欲將至，有開必先。","chunks":[["清明在躬，氣志如神，嗜欲將至，有開必先。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-4","passageId":"li-ji_ch-29_p-7","order":4,"canonicalText":"天降時雨，山川出云。","chunks":[["天降時雨，山川出云。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-5","passageId":"li-ji_ch-29_p-7","order":5,"canonicalText":"其在《詩》曰：『嵩高惟岳，峻極于天。","chunks":[["其在《詩》曰：『嵩高惟岳，峻極于天。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-6","passageId":"li-ji_ch-29_p-7","order":6,"canonicalText":"惟岳降神，生甫及申。","chunks":[["惟岳降神，生甫及申。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-7","passageId":"li-ji_ch-29_p-7","order":7,"canonicalText":"惟申及甫，惟周之翰。","chunks":[["惟申及甫，惟周之翰。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-8","passageId":"li-ji_ch-29_p-7","order":8,"canonicalText":"四國于蕃，四方于宣。","chunks":[["四國于蕃，四方于宣。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-9","passageId":"li-ji_ch-29_p-7","order":9,"canonicalText":"』此文武之德也。","chunks":[["』此文武之德也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-10","passageId":"li-ji_ch-29_p-7","order":10,"canonicalText":"三代之王也，必先令聞，《詩》云：『明明天子，令聞不已。","chunks":[["三代之王也，必先令聞，《詩》云：『明明天子，令聞不已。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-11","passageId":"li-ji_ch-29_p-7","order":11,"canonicalText":"』三代之德也。","chunks":[["』三代之德也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-12","passageId":"li-ji_ch-29_p-7","order":12,"canonicalText":"『弛其文德，協此四國。","chunks":[["『弛其文德，協此四國。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-13","passageId":"li-ji_ch-29_p-7","order":13,"canonicalText":"』大王之德也。","chunks":[["』大王之德也。","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-14","passageId":"li-ji_ch-29_p-7","order":14,"canonicalText":"」子夏蹶然而起，負墻而立曰：「弟子敢不承乎！","chunks":[["」子夏蹶然而起，負墻而立曰：「弟子敢不承乎！","zh-Hant"]]},{"id":"li-ji_ch-29_p-7_s-15","passageId":"li-ji_ch-29_p-7","order":15,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-1_s-1","passageId":"li-ji_ch-30_p-1","order":1,"canonicalText":"子言之：「君子之道，辟則坊與，坊民之所不足者也。","chunks":[["子言之：「君子之道，辟則坊與，坊民之所不足者也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-1_s-2","passageId":"li-ji_ch-30_p-1","order":2,"canonicalText":"」大為之坊，民猶逾之。","chunks":[["」大為之坊，民猶逾之。","zh-Hant"]]},{"id":"li-ji_ch-30_p-1_s-3","passageId":"li-ji_ch-30_p-1","order":3,"canonicalText":"故君子禮以坊德，刑以坊淫，命以坊欲。","chunks":[["故君子禮以坊德，刑以坊淫，命以坊欲。","zh-Hant"]]},{"id":"li-ji_ch-30_p-2_s-1","passageId":"li-ji_ch-30_p-2","order":1,"canonicalText":"子云：「小人貧斯約，富斯驕；","chunks":[["子云：「小人貧斯約，富斯驕；","zh-Hant"]]},{"id":"li-ji_ch-30_p-2_s-2","passageId":"li-ji_ch-30_p-2","order":2,"canonicalText":"約斯盜，驕斯亂。","chunks":[["約斯盜，驕斯亂。","zh-Hant"]]},{"id":"li-ji_ch-30_p-2_s-3","passageId":"li-ji_ch-30_p-2","order":3,"canonicalText":"」禮者，因人之情而為之節文，以為民坊者也。","chunks":[["」禮者，因人之情而為之節文，以為民坊者也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-2_s-4","passageId":"li-ji_ch-30_p-2","order":4,"canonicalText":"故聖人之制富貴也使民富不足以驕，貧不至於約，貴不慊於上，故亂益亡。","chunks":[["故聖人之制富貴也使民富不足以驕，貧不至於約，貴不慊於上，故亂益亡。","zh-Hant"]]},{"id":"li-ji_ch-30_p-3_s-1","passageId":"li-ji_ch-30_p-3","order":1,"canonicalText":"子云：「貧而好樂，富而好禮，眾而以寧者，天下其幾矣。","chunks":[["子云：「貧而好樂，富而好禮，眾而以寧者，天下其幾矣。","zh-Hant"]]},{"id":"li-ji_ch-30_p-3_s-2","passageId":"li-ji_ch-30_p-3","order":2,"canonicalText":"《詩》云：『民之貪亂，寧為荼毒。","chunks":[["《詩》云：『民之貪亂，寧為荼毒。","zh-Hant"]]},{"id":"li-ji_ch-30_p-3_s-3","passageId":"li-ji_ch-30_p-3","order":3,"canonicalText":"』」故制：國不過千乘，都城不過百雉，家富不過百乘。","chunks":[["』」故制：國不過千乘，都城不過百雉，家富不過百乘。","zh-Hant"]]},{"id":"li-ji_ch-30_p-3_s-4","passageId":"li-ji_ch-30_p-3","order":4,"canonicalText":"以此坊民，諸侯猶有畔者。","chunks":[["以此坊民，諸侯猶有畔者。","zh-Hant"]]},{"id":"li-ji_ch-30_p-4_s-1","passageId":"li-ji_ch-30_p-4","order":1,"canonicalText":"子云：「夫禮者，所以章疑別微，以為民坊者也。","chunks":[["子云：「夫禮者，所以章疑別微，以為民坊者也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-4_s-2","passageId":"li-ji_ch-30_p-4","order":2,"canonicalText":"」故貴賤有等，衣服有別，朝廷有位，則民有所讓。","chunks":[["」故貴賤有等，衣服有別，朝廷有位，則民有所讓。","zh-Hant"]]},{"id":"li-ji_ch-30_p-5_s-1","passageId":"li-ji_ch-30_p-5","order":1,"canonicalText":"子云：「天無二日，土無二王，家無二主，尊無二上，示民有君臣之別也。","chunks":[["子云：「天無二日，土無二王，家無二主，尊無二上，示民有君臣之別也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-5_s-2","passageId":"li-ji_ch-30_p-5","order":2,"canonicalText":"」《春秋》不稱楚越之王喪，禮君不稱天，大夫不稱君，恐民之惑也。","chunks":[["」《春秋》不稱楚越之王喪，禮君不稱天，大夫不稱君，恐民之惑也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-5_s-3","passageId":"li-ji_ch-30_p-5","order":3,"canonicalText":"《詩》云：「相彼盍旦，尚猶患之。","chunks":[["《詩》云：「相彼盍旦，尚猶患之。","zh-Hant"]]},{"id":"li-ji_ch-30_p-5_s-4","passageId":"li-ji_ch-30_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-6_s-1","passageId":"li-ji_ch-30_p-6","order":1,"canonicalText":"子云：「君不與同姓同車，與異姓同車不同服，示民不嫌也。","chunks":[["子云：「君不與同姓同車，與異姓同車不同服，示民不嫌也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-6_s-2","passageId":"li-ji_ch-30_p-6","order":2,"canonicalText":"」以此坊民，民猶得同姓以弒其君。","chunks":[["」以此坊民，民猶得同姓以弒其君。","zh-Hant"]]},{"id":"li-ji_ch-30_p-7_s-1","passageId":"li-ji_ch-30_p-7","order":1,"canonicalText":"子云：「君子辭貴不辭賤，辭富不辭貧，則亂益亡。","chunks":[["子云：「君子辭貴不辭賤，辭富不辭貧，則亂益亡。","zh-Hant"]]},{"id":"li-ji_ch-30_p-7_s-2","passageId":"li-ji_ch-30_p-7","order":2,"canonicalText":"」故君子與其使食浮於人也，寧使人浮於食。","chunks":[["」故君子與其使食浮於人也，寧使人浮於食。","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-1","passageId":"li-ji_ch-30_p-8","order":1,"canonicalText":"子云：「觴酒豆肉讓而受惡，民猶犯齒；","chunks":[["子云：「觴酒豆肉讓而受惡，民猶犯齒；","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-2","passageId":"li-ji_ch-30_p-8","order":2,"canonicalText":"衽席之上讓而坐下，民猶犯貴；","chunks":[["衽席之上讓而坐下，民猶犯貴；","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-3","passageId":"li-ji_ch-30_p-8","order":3,"canonicalText":"朝廷之位讓而就賤，民猶犯君。","chunks":[["朝廷之位讓而就賤，民猶犯君。","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-4","passageId":"li-ji_ch-30_p-8","order":4,"canonicalText":"」《詩》云：「民之無良，相怨一方；","chunks":[["」《詩》云：「民之無良，相怨一方；","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-5","passageId":"li-ji_ch-30_p-8","order":5,"canonicalText":"受爵不讓，至于已斯亡。","chunks":[["受爵不讓，至于已斯亡。","zh-Hant"]]},{"id":"li-ji_ch-30_p-8_s-6","passageId":"li-ji_ch-30_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-9_s-1","passageId":"li-ji_ch-30_p-9","order":1,"canonicalText":"子云：「君子貴人而賤己，先人而後己，則民作讓。","chunks":[["子云：「君子貴人而賤己，先人而後己，則民作讓。","zh-Hant"]]},{"id":"li-ji_ch-30_p-9_s-2","passageId":"li-ji_ch-30_p-9","order":2,"canonicalText":"」故稱人之君曰君，自稱其君曰寡君。","chunks":[["」故稱人之君曰君，自稱其君曰寡君。","zh-Hant"]]},{"id":"li-ji_ch-30_p-10_s-1","passageId":"li-ji_ch-30_p-10","order":1,"canonicalText":"子云：「利祿，先死者而後生者，則民不偝；","chunks":[["子云：「利祿，先死者而後生者，則民不偝；","zh-Hant"]]},{"id":"li-ji_ch-30_p-10_s-2","passageId":"li-ji_ch-30_p-10","order":2,"canonicalText":"先亡者而後存者，則民可以托。","chunks":[["先亡者而後存者，則民可以托。","zh-Hant"]]},{"id":"li-ji_ch-30_p-10_s-3","passageId":"li-ji_ch-30_p-10","order":3,"canonicalText":"」《詩》云：「先君之思，以畜寡人。","chunks":[["」《詩》云：「先君之思，以畜寡人。","zh-Hant"]]},{"id":"li-ji_ch-30_p-10_s-4","passageId":"li-ji_ch-30_p-10","order":4,"canonicalText":"」以此坊民，民猶偝死而號無告。","chunks":[["」以此坊民，民猶偝死而號無告。","zh-Hant"]]},{"id":"li-ji_ch-30_p-11_s-1","passageId":"li-ji_ch-30_p-11","order":1,"canonicalText":"子云：「有國家者，貴人而賤祿，則民興讓；","chunks":[["子云：「有國家者，貴人而賤祿，則民興讓；","zh-Hant"]]},{"id":"li-ji_ch-30_p-11_s-2","passageId":"li-ji_ch-30_p-11","order":2,"canonicalText":"尚技而賤車，則民興藝。","chunks":[["尚技而賤車，則民興藝。","zh-Hant"]]},{"id":"li-ji_ch-30_p-11_s-3","passageId":"li-ji_ch-30_p-11","order":3,"canonicalText":"」故君子約言，小人先言。","chunks":[["」故君子約言，小人先言。","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-1","passageId":"li-ji_ch-30_p-12","order":1,"canonicalText":"子云：「上酌民言，則下天上施；","chunks":[["子云：「上酌民言，則下天上施；","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-2","passageId":"li-ji_ch-30_p-12","order":2,"canonicalText":"上不酌民言，則犯也；","chunks":[["上不酌民言，則犯也；","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-3","passageId":"li-ji_ch-30_p-12","order":3,"canonicalText":"下不天上施，則亂也。","chunks":[["下不天上施，則亂也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-4","passageId":"li-ji_ch-30_p-12","order":4,"canonicalText":"」故君子信讓以蒞百姓，則民之報禮重。","chunks":[["」故君子信讓以蒞百姓，則民之報禮重。","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-5","passageId":"li-ji_ch-30_p-12","order":5,"canonicalText":"《詩》云：「先民有言，詢于芻蕘。","chunks":[["《詩》云：「先民有言，詢于芻蕘。","zh-Hant"]]},{"id":"li-ji_ch-30_p-12_s-6","passageId":"li-ji_ch-30_p-12","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-13_s-1","passageId":"li-ji_ch-30_p-13","order":1,"canonicalText":"子云：「善則稱人，過則稱己，則民不爭；","chunks":[["子云：「善則稱人，過則稱己，則民不爭；","zh-Hant"]]},{"id":"li-ji_ch-30_p-13_s-2","passageId":"li-ji_ch-30_p-13","order":2,"canonicalText":"善則稱人，過則稱己，則怨益亡。","chunks":[["善則稱人，過則稱己，則怨益亡。","zh-Hant"]]},{"id":"li-ji_ch-30_p-13_s-3","passageId":"li-ji_ch-30_p-13","order":3,"canonicalText":"」《詩》云：「爾卜爾筮，履無咎言。","chunks":[["」《詩》云：「爾卜爾筮，履無咎言。","zh-Hant"]]},{"id":"li-ji_ch-30_p-13_s-4","passageId":"li-ji_ch-30_p-13","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-14_s-1","passageId":"li-ji_ch-30_p-14","order":1,"canonicalText":"子云：「善則稱人，過則稱己，則民讓善。","chunks":[["子云：「善則稱人，過則稱己，則民讓善。","zh-Hant"]]},{"id":"li-ji_ch-30_p-14_s-2","passageId":"li-ji_ch-30_p-14","order":2,"canonicalText":"」《詩》云：「考卜惟王，度是鎬京；","chunks":[["」《詩》云：「考卜惟王，度是鎬京；","zh-Hant"]]},{"id":"li-ji_ch-30_p-14_s-3","passageId":"li-ji_ch-30_p-14","order":3,"canonicalText":"惟龜正之，武王成之。","chunks":[["惟龜正之，武王成之。","zh-Hant"]]},{"id":"li-ji_ch-30_p-14_s-4","passageId":"li-ji_ch-30_p-14","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-15_s-1","passageId":"li-ji_ch-30_p-15","order":1,"canonicalText":"子云：「善則稱君，過則稱己，則民作忠。","chunks":[["子云：「善則稱君，過則稱己，則民作忠。","zh-Hant"]]},{"id":"li-ji_ch-30_p-15_s-2","passageId":"li-ji_ch-30_p-15","order":2,"canonicalText":"」《君陳》曰：「爾有嘉謀嘉猷，入告爾君于內，女乃順之于外，曰：此謀此猷，惟我君之德。","chunks":[["」《君陳》曰：「爾有嘉謀嘉猷，入告爾君于內，女乃順之于外，曰：此謀此猷，惟我君之德。","zh-Hant"]]},{"id":"li-ji_ch-30_p-15_s-3","passageId":"li-ji_ch-30_p-15","order":3,"canonicalText":"於乎！","chunks":[["於乎！","zh-Hant"]]},{"id":"li-ji_ch-30_p-15_s-4","passageId":"li-ji_ch-30_p-15","order":4,"canonicalText":"是惟良顯哉。","chunks":[["是惟良顯哉。","zh-Hant"]]},{"id":"li-ji_ch-30_p-15_s-5","passageId":"li-ji_ch-30_p-15","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-16_s-1","passageId":"li-ji_ch-30_p-16","order":1,"canonicalText":"子云：「善則稱親，過則稱己，則民作孝。","chunks":[["子云：「善則稱親，過則稱己，則民作孝。","zh-Hant"]]},{"id":"li-ji_ch-30_p-16_s-2","passageId":"li-ji_ch-30_p-16","order":2,"canonicalText":"」《大誓》曰：「予克紂，非予武，惟朕文考無罪；","chunks":[["」《大誓》曰：「予克紂，非予武，惟朕文考無罪；","zh-Hant"]]},{"id":"li-ji_ch-30_p-16_s-3","passageId":"li-ji_ch-30_p-16","order":3,"canonicalText":"紂克予，非朕文考有罪，惟予小子無良。","chunks":[["紂克予，非朕文考有罪，惟予小子無良。","zh-Hant"]]},{"id":"li-ji_ch-30_p-16_s-4","passageId":"li-ji_ch-30_p-16","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-17_s-1","passageId":"li-ji_ch-30_p-17","order":1,"canonicalText":"子云：「君子弛其親之過，而敬其美。","chunks":[["子云：「君子弛其親之過，而敬其美。","zh-Hant"]]},{"id":"li-ji_ch-30_p-17_s-2","passageId":"li-ji_ch-30_p-17","order":2,"canonicalText":"」《論語》曰：「三年無改於父之道，可謂孝矣。","chunks":[["」《論語》曰：「三年無改於父之道，可謂孝矣。","zh-Hant"]]},{"id":"li-ji_ch-30_p-17_s-3","passageId":"li-ji_ch-30_p-17","order":3,"canonicalText":"」《高宗》云：「三年其惟不言，言乃讙。","chunks":[["」《高宗》云：「三年其惟不言，言乃讙。","zh-Hant"]]},{"id":"li-ji_ch-30_p-17_s-4","passageId":"li-ji_ch-30_p-17","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-18_s-1","passageId":"li-ji_ch-30_p-18","order":1,"canonicalText":"子云：「從命不忿，微諫不倦，勞而不怨，可謂孝矣。","chunks":[["子云：「從命不忿，微諫不倦，勞而不怨，可謂孝矣。","zh-Hant"]]},{"id":"li-ji_ch-30_p-18_s-2","passageId":"li-ji_ch-30_p-18","order":2,"canonicalText":"」《詩》云：「孝子不匱。","chunks":[["」《詩》云：「孝子不匱。","zh-Hant"]]},{"id":"li-ji_ch-30_p-18_s-3","passageId":"li-ji_ch-30_p-18","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-19_s-1","passageId":"li-ji_ch-30_p-19","order":1,"canonicalText":"子云：「睦於父母之黨，可謂孝矣。","chunks":[["子云：「睦於父母之黨，可謂孝矣。","zh-Hant"]]},{"id":"li-ji_ch-30_p-19_s-2","passageId":"li-ji_ch-30_p-19","order":2,"canonicalText":"故君子因睦以合族。","chunks":[["故君子因睦以合族。","zh-Hant"]]},{"id":"li-ji_ch-30_p-19_s-3","passageId":"li-ji_ch-30_p-19","order":3,"canonicalText":"」《詩》云：「此令兄弟，綽綽有裕；","chunks":[["」《詩》云：「此令兄弟，綽綽有裕；","zh-Hant"]]},{"id":"li-ji_ch-30_p-19_s-4","passageId":"li-ji_ch-30_p-19","order":4,"canonicalText":"不令兄弟，交相為愈。","chunks":[["不令兄弟，交相為愈。","zh-Hant"]]},{"id":"li-ji_ch-30_p-19_s-5","passageId":"li-ji_ch-30_p-19","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-20_s-1","passageId":"li-ji_ch-30_p-20","order":1,"canonicalText":"子云：「於父之執，可以乘其車，不可以衣其衣。","chunks":[["子云：「於父之執，可以乘其車，不可以衣其衣。","zh-Hant"]]},{"id":"li-ji_ch-30_p-20_s-2","passageId":"li-ji_ch-30_p-20","order":2,"canonicalText":"君子以廣孝也。","chunks":[["君子以廣孝也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-20_s-3","passageId":"li-ji_ch-30_p-20","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-21_s-1","passageId":"li-ji_ch-30_p-21","order":1,"canonicalText":"子云：「小人皆能養其親，君子不敬，何以辨？","chunks":[["子云：「小人皆能養其親，君子不敬，何以辨？","zh-Hant"]]},{"id":"li-ji_ch-30_p-21_s-2","passageId":"li-ji_ch-30_p-21","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-22_s-1","passageId":"li-ji_ch-30_p-22","order":1,"canonicalText":"子云：「父子不同位，以厚敬也。","chunks":[["子云：「父子不同位，以厚敬也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-22_s-2","passageId":"li-ji_ch-30_p-22","order":2,"canonicalText":"」《書》云：「厥辟不辟，忝厥祖。","chunks":[["」《書》云：「厥辟不辟，忝厥祖。","zh-Hant"]]},{"id":"li-ji_ch-30_p-22_s-3","passageId":"li-ji_ch-30_p-22","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-23_s-1","passageId":"li-ji_ch-30_p-23","order":1,"canonicalText":"子云：「父母在，不稱老，言孝不言慈；","chunks":[["子云：「父母在，不稱老，言孝不言慈；","zh-Hant"]]},{"id":"li-ji_ch-30_p-23_s-2","passageId":"li-ji_ch-30_p-23","order":2,"canonicalText":"閨門之內，戲而不嘆。","chunks":[["閨門之內，戲而不嘆。","zh-Hant"]]},{"id":"li-ji_ch-30_p-23_s-3","passageId":"li-ji_ch-30_p-23","order":3,"canonicalText":"」君子以此坊民，民猶薄於孝而厚於慈。","chunks":[["」君子以此坊民，民猶薄於孝而厚於慈。","zh-Hant"]]},{"id":"li-ji_ch-30_p-24_s-1","passageId":"li-ji_ch-30_p-24","order":1,"canonicalText":"子云：「長民者，朝廷敬老，則民作孝。","chunks":[["子云：「長民者，朝廷敬老，則民作孝。","zh-Hant"]]},{"id":"li-ji_ch-30_p-24_s-2","passageId":"li-ji_ch-30_p-24","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-25_s-1","passageId":"li-ji_ch-30_p-25","order":1,"canonicalText":"子云：「祭祀之有尸也，宗廟之主也，示民有事也。","chunks":[["子云：「祭祀之有尸也，宗廟之主也，示民有事也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-25_s-2","passageId":"li-ji_ch-30_p-25","order":2,"canonicalText":"修宗廟，敬祀事，教民追孝也。","chunks":[["修宗廟，敬祀事，教民追孝也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-25_s-3","passageId":"li-ji_ch-30_p-25","order":3,"canonicalText":"」以此坊民，民猶忘其親。","chunks":[["」以此坊民，民猶忘其親。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-1","passageId":"li-ji_ch-30_p-26","order":1,"canonicalText":"子云：「敬則用祭器。","chunks":[["子云：「敬則用祭器。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-2","passageId":"li-ji_ch-30_p-26","order":2,"canonicalText":"故君子不以菲廢禮，不以美沒禮。","chunks":[["故君子不以菲廢禮，不以美沒禮。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-3","passageId":"li-ji_ch-30_p-26","order":3,"canonicalText":"」故食禮：主人親饋，則客祭；","chunks":[["」故食禮：主人親饋，則客祭；","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-4","passageId":"li-ji_ch-30_p-26","order":4,"canonicalText":"主人不親饋，則客不祭。","chunks":[["主人不親饋，則客不祭。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-5","passageId":"li-ji_ch-30_p-26","order":5,"canonicalText":"故君子茍無禮，雖美不食焉。","chunks":[["故君子茍無禮，雖美不食焉。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-6","passageId":"li-ji_ch-30_p-26","order":6,"canonicalText":"《易》曰：「東鄰殺牛，不如西鄰之禴祭，實受其福。","chunks":[["《易》曰：「東鄰殺牛，不如西鄰之禴祭，實受其福。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-7","passageId":"li-ji_ch-30_p-26","order":7,"canonicalText":"」《詩》云：「既醉以酒，既飽以德。","chunks":[["」《詩》云：「既醉以酒，既飽以德。","zh-Hant"]]},{"id":"li-ji_ch-30_p-26_s-8","passageId":"li-ji_ch-30_p-26","order":8,"canonicalText":"」以此示民，民猶爭利而忘義。","chunks":[["」以此示民，民猶爭利而忘義。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-1","passageId":"li-ji_ch-30_p-27","order":1,"canonicalText":"子云：「七日戒，三日齊，承一人焉以為尸，過之者趨走，以教敬也。","chunks":[["子云：「七日戒，三日齊，承一人焉以為尸，過之者趨走，以教敬也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-2","passageId":"li-ji_ch-30_p-27","order":2,"canonicalText":"」醴酒在室，醍酒在堂，澄酒在下，示民不淫也。","chunks":[["」醴酒在室，醍酒在堂，澄酒在下，示民不淫也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-3","passageId":"li-ji_ch-30_p-27","order":3,"canonicalText":"尸飲三，眾賓飲一，示民有上下也。","chunks":[["尸飲三，眾賓飲一，示民有上下也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-4","passageId":"li-ji_ch-30_p-27","order":4,"canonicalText":"因其酒肉，聚其宗族，以教民睦也。","chunks":[["因其酒肉，聚其宗族，以教民睦也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-5","passageId":"li-ji_ch-30_p-27","order":5,"canonicalText":"故堂上觀乎室，堂下觀乎上。","chunks":[["故堂上觀乎室，堂下觀乎上。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-6","passageId":"li-ji_ch-30_p-27","order":6,"canonicalText":"《詩》云：「禮儀卒度，笑語卒獲。","chunks":[["《詩》云：「禮儀卒度，笑語卒獲。","zh-Hant"]]},{"id":"li-ji_ch-30_p-27_s-7","passageId":"li-ji_ch-30_p-27","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-28_s-1","passageId":"li-ji_ch-30_p-28","order":1,"canonicalText":"子云：「賓禮每進以讓，喪禮每加以遠。","chunks":[["子云：「賓禮每進以讓，喪禮每加以遠。","zh-Hant"]]},{"id":"li-ji_ch-30_p-28_s-2","passageId":"li-ji_ch-30_p-28","order":2,"canonicalText":"」浴於中溜，飯於牖下，小斂於戶內，大斂於阼，殯於客位，祖於庭，葬於墓，所以示遠也。","chunks":[["」浴於中溜，飯於牖下，小斂於戶內，大斂於阼，殯於客位，祖於庭，葬於墓，所以示遠也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-28_s-3","passageId":"li-ji_ch-30_p-28","order":3,"canonicalText":"殷人吊於壙，周人吊於家，示民不偝也。","chunks":[["殷人吊於壙，周人吊於家，示民不偝也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-29_s-1","passageId":"li-ji_ch-30_p-29","order":1,"canonicalText":"子云：「死，民之卒事也，吾從周。","chunks":[["子云：「死，民之卒事也，吾從周。","zh-Hant"]]},{"id":"li-ji_ch-30_p-29_s-2","passageId":"li-ji_ch-30_p-29","order":2,"canonicalText":"」以此坊民，諸侯猶有薨而不葬者。","chunks":[["」以此坊民，諸侯猶有薨而不葬者。","zh-Hant"]]},{"id":"li-ji_ch-30_p-30_s-1","passageId":"li-ji_ch-30_p-30","order":1,"canonicalText":"子云：「升自客階，受吊於賓位，教民追孝也。","chunks":[["子云：「升自客階，受吊於賓位，教民追孝也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-30_s-2","passageId":"li-ji_ch-30_p-30","order":2,"canonicalText":"」未沒喪不稱君，示民不爭也。","chunks":[["」未沒喪不稱君，示民不爭也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-30_s-3","passageId":"li-ji_ch-30_p-30","order":3,"canonicalText":"故魯《春秋》記晉喪曰：「殺其君之子奚齊及其君卓。","chunks":[["故魯《春秋》記晉喪曰：「殺其君之子奚齊及其君卓。","zh-Hant"]]},{"id":"li-ji_ch-30_p-30_s-4","passageId":"li-ji_ch-30_p-30","order":4,"canonicalText":"」以此坊民，子猶有弒其父者。","chunks":[["」以此坊民，子猶有弒其父者。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-1","passageId":"li-ji_ch-30_p-31","order":1,"canonicalText":"子云：「孝以事君，弟以事長」，示民不貳也，故君子有君不謀仕，唯卜之日稱二君。","chunks":[["子云：「孝以事君，弟以事長」，示民不貳也，故君子有君不謀仕，唯卜之日稱二君。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-2","passageId":"li-ji_ch-30_p-31","order":2,"canonicalText":"喪父三年，喪君三年，示民不疑也。","chunks":[["喪父三年，喪君三年，示民不疑也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-3","passageId":"li-ji_ch-30_p-31","order":3,"canonicalText":"父母在，不敢有其身，不敢私其財，示民有上下也。","chunks":[["父母在，不敢有其身，不敢私其財，示民有上下也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-4","passageId":"li-ji_ch-30_p-31","order":4,"canonicalText":"故天子四海之內無客禮，莫敢為主焉。","chunks":[["故天子四海之內無客禮，莫敢為主焉。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-5","passageId":"li-ji_ch-30_p-31","order":5,"canonicalText":"故君適其臣，升自阼階，即位於堂，示民不敢有其室也。","chunks":[["故君適其臣，升自阼階，即位於堂，示民不敢有其室也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-6","passageId":"li-ji_ch-30_p-31","order":6,"canonicalText":"父母在，饋獻不及車馬，示民不敢專也。","chunks":[["父母在，饋獻不及車馬，示民不敢專也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-31_s-7","passageId":"li-ji_ch-30_p-31","order":7,"canonicalText":"以此坊民，民猶忘其親而貳其君。","chunks":[["以此坊民，民猶忘其親而貳其君。","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-1","passageId":"li-ji_ch-30_p-32","order":1,"canonicalText":"子云：「禮之先幣帛也，欲民之先事而後祿也。","chunks":[["子云：「禮之先幣帛也，欲民之先事而後祿也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-2","passageId":"li-ji_ch-30_p-32","order":2,"canonicalText":"」先財而後禮，則民利；","chunks":[["」先財而後禮，則民利；","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-3","passageId":"li-ji_ch-30_p-32","order":3,"canonicalText":"無辭而行情，則民爭。","chunks":[["無辭而行情，則民爭。","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-4","passageId":"li-ji_ch-30_p-32","order":4,"canonicalText":"故君子於有饋者，弗能見則不視其饋。","chunks":[["故君子於有饋者，弗能見則不視其饋。","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-5","passageId":"li-ji_ch-30_p-32","order":5,"canonicalText":"《易》曰：「不耕獲，不菑畬，凶。","chunks":[["《易》曰：「不耕獲，不菑畬，凶。","zh-Hant"]]},{"id":"li-ji_ch-30_p-32_s-6","passageId":"li-ji_ch-30_p-32","order":6,"canonicalText":"」以此坊民，民猶貴祿而賤行。","chunks":[["」以此坊民，民猶貴祿而賤行。","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-1","passageId":"li-ji_ch-30_p-33","order":1,"canonicalText":"子云：「君子不盡利以遺民。","chunks":[["子云：「君子不盡利以遺民。","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-2","passageId":"li-ji_ch-30_p-33","order":2,"canonicalText":"」《詩》云：「彼有遺秉，此有不斂穧，伊寡婦之利。","chunks":[["」《詩》云：「彼有遺秉，此有不斂穧，伊寡婦之利。","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-3","passageId":"li-ji_ch-30_p-33","order":3,"canonicalText":"」故君子仕則不稼，田則不漁；","chunks":[["」故君子仕則不稼，田則不漁；","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-4","passageId":"li-ji_ch-30_p-33","order":4,"canonicalText":"食時不力珍，大夫不坐羊，士不坐犬。","chunks":[["食時不力珍，大夫不坐羊，士不坐犬。","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-5","passageId":"li-ji_ch-30_p-33","order":5,"canonicalText":"《詩》云：「采葑采菲，無以下體，德音莫違，及爾同死。","chunks":[["《詩》云：「采葑采菲，無以下體，德音莫違，及爾同死。","zh-Hant"]]},{"id":"li-ji_ch-30_p-33_s-6","passageId":"li-ji_ch-30_p-33","order":6,"canonicalText":"」以此坊民，民猶忘義而爭利，以亡其身。","chunks":[["」以此坊民，民猶忘義而爭利，以亡其身。","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-1","passageId":"li-ji_ch-30_p-34","order":1,"canonicalText":"子云：「夫禮，坊民所淫，章民之別，使民無嫌，以為民紀者也。","chunks":[["子云：「夫禮，坊民所淫，章民之別，使民無嫌，以為民紀者也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-2","passageId":"li-ji_ch-30_p-34","order":2,"canonicalText":"」故男女無媒不交，無幣不相見，恐男女之無別也。","chunks":[["」故男女無媒不交，無幣不相見，恐男女之無別也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-3","passageId":"li-ji_ch-30_p-34","order":3,"canonicalText":"以此坊民，民猶有自獻其身。","chunks":[["以此坊民，民猶有自獻其身。","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-4","passageId":"li-ji_ch-30_p-34","order":4,"canonicalText":"《詩》云：「伐柯如之何？","chunks":[["《詩》云：「伐柯如之何？","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-5","passageId":"li-ji_ch-30_p-34","order":5,"canonicalText":"匪斧不克；","chunks":[["匪斧不克；","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-6","passageId":"li-ji_ch-30_p-34","order":6,"canonicalText":"取妻如之何？","chunks":[["取妻如之何？","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-7","passageId":"li-ji_ch-30_p-34","order":7,"canonicalText":"匪媒不得；","chunks":[["匪媒不得；","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-8","passageId":"li-ji_ch-30_p-34","order":8,"canonicalText":"蓺麻如之何？","chunks":[["蓺麻如之何？","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-9","passageId":"li-ji_ch-30_p-34","order":9,"canonicalText":"橫從其畝；","chunks":[["橫從其畝；","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-10","passageId":"li-ji_ch-30_p-34","order":10,"canonicalText":"取妻如之何？","chunks":[["取妻如之何？","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-11","passageId":"li-ji_ch-30_p-34","order":11,"canonicalText":"必告父母。","chunks":[["必告父母。","zh-Hant"]]},{"id":"li-ji_ch-30_p-34_s-12","passageId":"li-ji_ch-30_p-34","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-30_p-35_s-1","passageId":"li-ji_ch-30_p-35","order":1,"canonicalText":"子云：「取妻不取同姓，以厚別也。","chunks":[["子云：「取妻不取同姓，以厚別也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-35_s-2","passageId":"li-ji_ch-30_p-35","order":2,"canonicalText":"」故買妾不知其姓，則卜之。","chunks":[["」故買妾不知其姓，則卜之。","zh-Hant"]]},{"id":"li-ji_ch-30_p-35_s-3","passageId":"li-ji_ch-30_p-35","order":3,"canonicalText":"以此坊民，魯《春秋》猶去夫人之姓曰吳，其死曰孟子卒。","chunks":[["以此坊民，魯《春秋》猶去夫人之姓曰吳，其死曰孟子卒。","zh-Hant"]]},{"id":"li-ji_ch-30_p-36_s-1","passageId":"li-ji_ch-30_p-36","order":1,"canonicalText":"子云：「禮，非祭，男女不交爵。","chunks":[["子云：「禮，非祭，男女不交爵。","zh-Hant"]]},{"id":"li-ji_ch-30_p-36_s-2","passageId":"li-ji_ch-30_p-36","order":2,"canonicalText":"」以此坊民，陽侯猶殺繆侯而竊其夫人。","chunks":[["」以此坊民，陽侯猶殺繆侯而竊其夫人。","zh-Hant"]]},{"id":"li-ji_ch-30_p-36_s-3","passageId":"li-ji_ch-30_p-36","order":3,"canonicalText":"故大饗廢夫人之禮。","chunks":[["故大饗廢夫人之禮。","zh-Hant"]]},{"id":"li-ji_ch-30_p-37_s-1","passageId":"li-ji_ch-30_p-37","order":1,"canonicalText":"子云：「寡婦之子，不有見焉，則弗友也，君子以辟遠也。","chunks":[["子云：「寡婦之子，不有見焉，則弗友也，君子以辟遠也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-37_s-2","passageId":"li-ji_ch-30_p-37","order":2,"canonicalText":"」故朋友之交，主人不在，不有大故，則不入其門。","chunks":[["」故朋友之交，主人不在，不有大故，則不入其門。","zh-Hant"]]},{"id":"li-ji_ch-30_p-37_s-3","passageId":"li-ji_ch-30_p-37","order":3,"canonicalText":"以此坊民，民猶以色厚於德。","chunks":[["以此坊民，民猶以色厚於德。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-1","passageId":"li-ji_ch-30_p-38","order":1,"canonicalText":"子云：「好德如好色。","chunks":[["子云：「好德如好色。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-2","passageId":"li-ji_ch-30_p-38","order":2,"canonicalText":"」諸侯不下漁色。","chunks":[["」諸侯不下漁色。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-3","passageId":"li-ji_ch-30_p-38","order":3,"canonicalText":"故君子遠色以為民紀。","chunks":[["故君子遠色以為民紀。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-4","passageId":"li-ji_ch-30_p-38","order":4,"canonicalText":"故男女授受不親。","chunks":[["故男女授受不親。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-5","passageId":"li-ji_ch-30_p-38","order":5,"canonicalText":"御婦人則進左手。","chunks":[["御婦人則進左手。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-6","passageId":"li-ji_ch-30_p-38","order":6,"canonicalText":"姑姊妹女子子已嫁而反，男子不與同席而坐。","chunks":[["姑姊妹女子子已嫁而反，男子不與同席而坐。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-7","passageId":"li-ji_ch-30_p-38","order":7,"canonicalText":"寡婦不夜哭。","chunks":[["寡婦不夜哭。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-8","passageId":"li-ji_ch-30_p-38","order":8,"canonicalText":"婦人疾，問之不問其疾。","chunks":[["婦人疾，問之不問其疾。","zh-Hant"]]},{"id":"li-ji_ch-30_p-38_s-9","passageId":"li-ji_ch-30_p-38","order":9,"canonicalText":"以此坊民，民猶淫泆而亂於族。","chunks":[["以此坊民，民猶淫泆而亂於族。","zh-Hant"]]},{"id":"li-ji_ch-30_p-39_s-1","passageId":"li-ji_ch-30_p-39","order":1,"canonicalText":"子云：「婚禮，婿親迎，見於舅姑，舅姑承子以授婿，恐事之違也。","chunks":[["子云：「婚禮，婿親迎，見於舅姑，舅姑承子以授婿，恐事之違也。","zh-Hant"]]},{"id":"li-ji_ch-30_p-39_s-2","passageId":"li-ji_ch-30_p-39","order":2,"canonicalText":"」以此坊民，婦猶有不至者。","chunks":[["」以此坊民，婦猶有不至者。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-1","passageId":"li-ji_ch-31_p-1","order":1,"canonicalText":"天命之謂性，率性之謂道，修道之謂教。","chunks":[["天命之謂性，率性之謂道，修道之謂教。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-2","passageId":"li-ji_ch-31_p-1","order":2,"canonicalText":"道也者，不可須臾離也，可離非道也。","chunks":[["道也者，不可須臾離也，可離非道也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-3","passageId":"li-ji_ch-31_p-1","order":3,"canonicalText":"是故君子戒慎乎其所不睹，恐懼乎其所不聞。","chunks":[["是故君子戒慎乎其所不睹，恐懼乎其所不聞。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-4","passageId":"li-ji_ch-31_p-1","order":4,"canonicalText":"莫見乎隱，莫顯乎微。","chunks":[["莫見乎隱，莫顯乎微。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-5","passageId":"li-ji_ch-31_p-1","order":5,"canonicalText":"故君子慎其獨也。","chunks":[["故君子慎其獨也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-6","passageId":"li-ji_ch-31_p-1","order":6,"canonicalText":"喜怒哀樂之未發，謂之中；","chunks":[["喜怒哀樂之未發，謂之中；","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-7","passageId":"li-ji_ch-31_p-1","order":7,"canonicalText":"發而皆中節，謂之和；","chunks":[["發而皆中節，謂之和；","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-8","passageId":"li-ji_ch-31_p-1","order":8,"canonicalText":"中也者，天下之大本也；","chunks":[["中也者，天下之大本也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-9","passageId":"li-ji_ch-31_p-1","order":9,"canonicalText":"和也者，天下之達道也。","chunks":[["和也者，天下之達道也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-1_s-10","passageId":"li-ji_ch-31_p-1","order":10,"canonicalText":"致中和，天地位焉，萬物育焉。","chunks":[["致中和，天地位焉，萬物育焉。","zh-Hant"]]},{"id":"li-ji_ch-31_p-2_s-1","passageId":"li-ji_ch-31_p-2","order":1,"canonicalText":"仲尼曰：「君子中庸，小人反中庸。","chunks":[["仲尼曰：「君子中庸，小人反中庸。","zh-Hant"]]},{"id":"li-ji_ch-31_p-2_s-2","passageId":"li-ji_ch-31_p-2","order":2,"canonicalText":"君子之中庸也，君子而時中；","chunks":[["君子之中庸也，君子而時中；","zh-Hant"]]},{"id":"li-ji_ch-31_p-2_s-3","passageId":"li-ji_ch-31_p-2","order":3,"canonicalText":"小人之中庸也，小人而無忌憚也。","chunks":[["小人之中庸也，小人而無忌憚也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-2_s-4","passageId":"li-ji_ch-31_p-2","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-3_s-1","passageId":"li-ji_ch-31_p-3","order":1,"canonicalText":"子曰：「中庸其至矣乎！","chunks":[["子曰：「中庸其至矣乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-3_s-2","passageId":"li-ji_ch-31_p-3","order":2,"canonicalText":"民鮮能久矣！","chunks":[["民鮮能久矣！","zh-Hant"]]},{"id":"li-ji_ch-31_p-3_s-3","passageId":"li-ji_ch-31_p-3","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-4_s-1","passageId":"li-ji_ch-31_p-4","order":1,"canonicalText":"子曰：「道之不行也，我知之矣：知者過之，愚者不及也。","chunks":[["子曰：「道之不行也，我知之矣：知者過之，愚者不及也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-4_s-2","passageId":"li-ji_ch-31_p-4","order":2,"canonicalText":"道之不明也，我知之矣：賢者過之，不肖者不及也。","chunks":[["道之不明也，我知之矣：賢者過之，不肖者不及也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-4_s-3","passageId":"li-ji_ch-31_p-4","order":3,"canonicalText":"人莫不飲食也，鮮能知味也。","chunks":[["人莫不飲食也，鮮能知味也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-4_s-4","passageId":"li-ji_ch-31_p-4","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-5_s-1","passageId":"li-ji_ch-31_p-5","order":1,"canonicalText":"子曰：「道其不行矣夫。","chunks":[["子曰：「道其不行矣夫。","zh-Hant"]]},{"id":"li-ji_ch-31_p-5_s-2","passageId":"li-ji_ch-31_p-5","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-6_s-1","passageId":"li-ji_ch-31_p-6","order":1,"canonicalText":"子曰：「舜其大知也與！","chunks":[["子曰：「舜其大知也與！","zh-Hant"]]},{"id":"li-ji_ch-31_p-6_s-2","passageId":"li-ji_ch-31_p-6","order":2,"canonicalText":"舜好問而好察邇言，隱惡而揚善，執其兩端，用其中於民，其斯以為舜乎！","chunks":[["舜好問而好察邇言，隱惡而揚善，執其兩端，用其中於民，其斯以為舜乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-6_s-3","passageId":"li-ji_ch-31_p-6","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-7_s-1","passageId":"li-ji_ch-31_p-7","order":1,"canonicalText":"子曰：「人皆曰『予知』，驅而納諸罟擭陷阱之中，而莫之知辟也。","chunks":[["子曰：「人皆曰『予知』，驅而納諸罟擭陷阱之中，而莫之知辟也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-7_s-2","passageId":"li-ji_ch-31_p-7","order":2,"canonicalText":"人皆曰『予知』，擇乎中庸，而不能期月守也。","chunks":[["人皆曰『予知』，擇乎中庸，而不能期月守也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-7_s-3","passageId":"li-ji_ch-31_p-7","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-8_s-1","passageId":"li-ji_ch-31_p-8","order":1,"canonicalText":"子曰：「回之為人也，擇乎中庸，得一善，則拳拳服膺而弗失之矣。","chunks":[["子曰：「回之為人也，擇乎中庸，得一善，則拳拳服膺而弗失之矣。","zh-Hant"]]},{"id":"li-ji_ch-31_p-8_s-2","passageId":"li-ji_ch-31_p-8","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-9_s-1","passageId":"li-ji_ch-31_p-9","order":1,"canonicalText":"子曰：「天下國家可均也，爵祿可辭也，白刃可蹈也，中庸不可能也。","chunks":[["子曰：「天下國家可均也，爵祿可辭也，白刃可蹈也，中庸不可能也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-9_s-2","passageId":"li-ji_ch-31_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-1","passageId":"li-ji_ch-31_p-10","order":1,"canonicalText":"子路問強。","chunks":[["子路問強。","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-2","passageId":"li-ji_ch-31_p-10","order":2,"canonicalText":"子曰：「南方之強與？","chunks":[["子曰：「南方之強與？","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-3","passageId":"li-ji_ch-31_p-10","order":3,"canonicalText":"北方之強與？","chunks":[["北方之強與？","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-4","passageId":"li-ji_ch-31_p-10","order":4,"canonicalText":"抑而強與？","chunks":[["抑而強與？","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-5","passageId":"li-ji_ch-31_p-10","order":5,"canonicalText":"寬柔以教，不報無道，南方之強也，君子居之。","chunks":[["寬柔以教，不報無道，南方之強也，君子居之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-6","passageId":"li-ji_ch-31_p-10","order":6,"canonicalText":"衽金革，死而不厭，北方之強也，而強者居之。","chunks":[["衽金革，死而不厭，北方之強也，而強者居之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-7","passageId":"li-ji_ch-31_p-10","order":7,"canonicalText":"故君子和而不流，強哉矯！","chunks":[["故君子和而不流，強哉矯！","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-8","passageId":"li-ji_ch-31_p-10","order":8,"canonicalText":"中立而不倚，強哉矯！","chunks":[["中立而不倚，強哉矯！","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-9","passageId":"li-ji_ch-31_p-10","order":9,"canonicalText":"國有道，不變塞焉，強哉矯！","chunks":[["國有道，不變塞焉，強哉矯！","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-10","passageId":"li-ji_ch-31_p-10","order":10,"canonicalText":"國無道，至死不變，強哉矯！","chunks":[["國無道，至死不變，強哉矯！","zh-Hant"]]},{"id":"li-ji_ch-31_p-10_s-11","passageId":"li-ji_ch-31_p-10","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-11_s-1","passageId":"li-ji_ch-31_p-11","order":1,"canonicalText":"子曰：「素隱行怪，後世有述焉，吾弗為之矣。","chunks":[["子曰：「素隱行怪，後世有述焉，吾弗為之矣。","zh-Hant"]]},{"id":"li-ji_ch-31_p-11_s-2","passageId":"li-ji_ch-31_p-11","order":2,"canonicalText":"君子遵道而行，半涂而廢，吾弗能已矣。","chunks":[["君子遵道而行，半涂而廢，吾弗能已矣。","zh-Hant"]]},{"id":"li-ji_ch-31_p-11_s-3","passageId":"li-ji_ch-31_p-11","order":3,"canonicalText":"君子依乎中庸，遁世不見知而不悔，唯聖者能之。","chunks":[["君子依乎中庸，遁世不見知而不悔，唯聖者能之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-1","passageId":"li-ji_ch-31_p-12","order":1,"canonicalText":"君子之道費而隱。","chunks":[["君子之道費而隱。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-2","passageId":"li-ji_ch-31_p-12","order":2,"canonicalText":"夫婦之愚，可以與知焉，及其至也，雖聖人亦有所不知焉；","chunks":[["夫婦之愚，可以與知焉，及其至也，雖聖人亦有所不知焉；","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-3","passageId":"li-ji_ch-31_p-12","order":3,"canonicalText":"夫婦之不肖，可以能行焉，及其至也，雖聖人亦有所不能焉。","chunks":[["夫婦之不肖，可以能行焉，及其至也，雖聖人亦有所不能焉。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-4","passageId":"li-ji_ch-31_p-12","order":4,"canonicalText":"天地之大也，人猶有所憾，故君子語大，天下莫能載焉；","chunks":[["天地之大也，人猶有所憾，故君子語大，天下莫能載焉；","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-5","passageId":"li-ji_ch-31_p-12","order":5,"canonicalText":"語小，天下莫能破焉。","chunks":[["語小，天下莫能破焉。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-6","passageId":"li-ji_ch-31_p-12","order":6,"canonicalText":"《詩》云：『鳶飛戾天，魚躍于淵。","chunks":[["《詩》云：『鳶飛戾天，魚躍于淵。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-7","passageId":"li-ji_ch-31_p-12","order":7,"canonicalText":"』言其上下察也。","chunks":[["』言其上下察也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-8","passageId":"li-ji_ch-31_p-12","order":8,"canonicalText":"君子之道，造端乎夫婦，及其至也，察乎天地。","chunks":[["君子之道，造端乎夫婦，及其至也，察乎天地。","zh-Hant"]]},{"id":"li-ji_ch-31_p-12_s-9","passageId":"li-ji_ch-31_p-12","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-1","passageId":"li-ji_ch-31_p-13","order":1,"canonicalText":"子曰：「道不遠人。","chunks":[["子曰：「道不遠人。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-2","passageId":"li-ji_ch-31_p-13","order":2,"canonicalText":"人之為道而遠人，不可以為道。","chunks":[["人之為道而遠人，不可以為道。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-3","passageId":"li-ji_ch-31_p-13","order":3,"canonicalText":"《詩》云：『伐柯伐柯，其則不遠。","chunks":[["《詩》云：『伐柯伐柯，其則不遠。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-4","passageId":"li-ji_ch-31_p-13","order":4,"canonicalText":"』執柯以伐柯，睨而視之，猶以為遠。","chunks":[["』執柯以伐柯，睨而視之，猶以為遠。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-5","passageId":"li-ji_ch-31_p-13","order":5,"canonicalText":"故君子以人治人，改而止。","chunks":[["故君子以人治人，改而止。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-6","passageId":"li-ji_ch-31_p-13","order":6,"canonicalText":"忠恕違道不遠，施諸己而不愿，亦勿施於人。","chunks":[["忠恕違道不遠，施諸己而不愿，亦勿施於人。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-7","passageId":"li-ji_ch-31_p-13","order":7,"canonicalText":"君子之道四，丘未能一焉：所求乎子以事父，未能也；","chunks":[["君子之道四，丘未能一焉：所求乎子以事父，未能也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-8","passageId":"li-ji_ch-31_p-13","order":8,"canonicalText":"所求乎臣以事君，未能也；","chunks":[["所求乎臣以事君，未能也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-9","passageId":"li-ji_ch-31_p-13","order":9,"canonicalText":"所求乎弟以事兄，未能也；","chunks":[["所求乎弟以事兄，未能也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-10","passageId":"li-ji_ch-31_p-13","order":10,"canonicalText":"所求乎朋友先施之，未能也。","chunks":[["所求乎朋友先施之，未能也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-11","passageId":"li-ji_ch-31_p-13","order":11,"canonicalText":"庸德之行，庸言之謹，有所不足，不敢不勉，有餘不敢盡；","chunks":[["庸德之行，庸言之謹，有所不足，不敢不勉，有餘不敢盡；","zh-Hant"]]},{"id":"li-ji_ch-31_p-13_s-12","passageId":"li-ji_ch-31_p-13","order":12,"canonicalText":"言顧行，行顧言，君子胡不慥慥爾！","chunks":[["言顧行，行顧言，君子胡不慥慥爾！","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-1","passageId":"li-ji_ch-31_p-14","order":1,"canonicalText":"君子素其位而行，不愿乎其外。","chunks":[["君子素其位而行，不愿乎其外。","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-2","passageId":"li-ji_ch-31_p-14","order":2,"canonicalText":"素富貴，行乎富貴；","chunks":[["素富貴，行乎富貴；","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-3","passageId":"li-ji_ch-31_p-14","order":3,"canonicalText":"素貧賤，行乎貧賤；","chunks":[["素貧賤，行乎貧賤；","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-4","passageId":"li-ji_ch-31_p-14","order":4,"canonicalText":"素夷狄，行乎夷狄；","chunks":[["素夷狄，行乎夷狄；","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-5","passageId":"li-ji_ch-31_p-14","order":5,"canonicalText":"素患難，行乎患難：君子無入而不自得焉。","chunks":[["素患難，行乎患難：君子無入而不自得焉。","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-6","passageId":"li-ji_ch-31_p-14","order":6,"canonicalText":"在上位不陵下，在下位不援上，正己而不求於人，則無怨。","chunks":[["在上位不陵下，在下位不援上，正己而不求於人，則無怨。","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-7","passageId":"li-ji_ch-31_p-14","order":7,"canonicalText":"上不怨天，下不尤人。","chunks":[["上不怨天，下不尤人。","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-8","passageId":"li-ji_ch-31_p-14","order":8,"canonicalText":"故君子居易以俟命，小人行險以徼幸。","chunks":[["故君子居易以俟命，小人行險以徼幸。","zh-Hant"]]},{"id":"li-ji_ch-31_p-14_s-9","passageId":"li-ji_ch-31_p-14","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-1","passageId":"li-ji_ch-31_p-15","order":1,"canonicalText":"子曰：「射有似乎君子，失諸正鵠，反求諸其身。","chunks":[["子曰：「射有似乎君子，失諸正鵠，反求諸其身。","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-2","passageId":"li-ji_ch-31_p-15","order":2,"canonicalText":"君子之道，辟如行遠必自邇，辟如登高必自卑。","chunks":[["君子之道，辟如行遠必自邇，辟如登高必自卑。","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-3","passageId":"li-ji_ch-31_p-15","order":3,"canonicalText":"《詩》曰：『妻子好合，如鼓瑟琴；","chunks":[["《詩》曰：『妻子好合，如鼓瑟琴；","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-4","passageId":"li-ji_ch-31_p-15","order":4,"canonicalText":"兄弟既翕，和樂且耽。","chunks":[["兄弟既翕，和樂且耽。","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-5","passageId":"li-ji_ch-31_p-15","order":5,"canonicalText":"宜爾室家，樂爾妻帑。","chunks":[["宜爾室家，樂爾妻帑。","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-6","passageId":"li-ji_ch-31_p-15","order":6,"canonicalText":"』」子曰：「父母其順矣乎！","chunks":[["』」子曰：「父母其順矣乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-15_s-7","passageId":"li-ji_ch-31_p-15","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-1","passageId":"li-ji_ch-31_p-16","order":1,"canonicalText":"子曰：「鬼神之為德，其盛矣乎！","chunks":[["子曰：「鬼神之為德，其盛矣乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-2","passageId":"li-ji_ch-31_p-16","order":2,"canonicalText":"視之而弗見，聽之而弗聞，體物而不可遺。","chunks":[["視之而弗見，聽之而弗聞，體物而不可遺。","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-3","passageId":"li-ji_ch-31_p-16","order":3,"canonicalText":"使天下之人齊明盛服，以承祭祀，洋洋乎如在其上，如在其左右。","chunks":[["使天下之人齊明盛服，以承祭祀，洋洋乎如在其上，如在其左右。","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-4","passageId":"li-ji_ch-31_p-16","order":4,"canonicalText":"《詩》曰：『神之格思，不可度思！","chunks":[["《詩》曰：『神之格思，不可度思！","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-5","passageId":"li-ji_ch-31_p-16","order":5,"canonicalText":"矧可射思！","chunks":[["矧可射思！","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-6","passageId":"li-ji_ch-31_p-16","order":6,"canonicalText":"』夫微之顯，誠之不可掩如此夫。","chunks":[["』夫微之顯，誠之不可掩如此夫。","zh-Hant"]]},{"id":"li-ji_ch-31_p-16_s-7","passageId":"li-ji_ch-31_p-16","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-1","passageId":"li-ji_ch-31_p-17","order":1,"canonicalText":"子曰：「舜其大孝也與！","chunks":[["子曰：「舜其大孝也與！","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-2","passageId":"li-ji_ch-31_p-17","order":2,"canonicalText":"德為聖人，尊為天子，富有四海之內。","chunks":[["德為聖人，尊為天子，富有四海之內。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-3","passageId":"li-ji_ch-31_p-17","order":3,"canonicalText":"宗廟饗之，子孫保之。","chunks":[["宗廟饗之，子孫保之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-4","passageId":"li-ji_ch-31_p-17","order":4,"canonicalText":"故大德必得其位，必得其祿，必得其名，必得其壽。","chunks":[["故大德必得其位，必得其祿，必得其名，必得其壽。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-5","passageId":"li-ji_ch-31_p-17","order":5,"canonicalText":"故天之生物，必因其材而篤焉。","chunks":[["故天之生物，必因其材而篤焉。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-6","passageId":"li-ji_ch-31_p-17","order":6,"canonicalText":"故栽者培之，傾者覆之。","chunks":[["故栽者培之，傾者覆之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-7","passageId":"li-ji_ch-31_p-17","order":7,"canonicalText":"《詩》曰：『嘉樂君子，憲憲令德！","chunks":[["《詩》曰：『嘉樂君子，憲憲令德！","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-8","passageId":"li-ji_ch-31_p-17","order":8,"canonicalText":"宜民宜人，受祿于天。","chunks":[["宜民宜人，受祿于天。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-9","passageId":"li-ji_ch-31_p-17","order":9,"canonicalText":"保佑命之，自天申之！","chunks":[["保佑命之，自天申之！","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-10","passageId":"li-ji_ch-31_p-17","order":10,"canonicalText":"』故大德者必受命。","chunks":[["』故大德者必受命。","zh-Hant"]]},{"id":"li-ji_ch-31_p-17_s-11","passageId":"li-ji_ch-31_p-17","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-1","passageId":"li-ji_ch-31_p-18","order":1,"canonicalText":"子曰：「無憂者其惟文王乎！","chunks":[["子曰：「無憂者其惟文王乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-2","passageId":"li-ji_ch-31_p-18","order":2,"canonicalText":"以王季為父，以武王為子，父作之，子述之。","chunks":[["以王季為父，以武王為子，父作之，子述之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-3","passageId":"li-ji_ch-31_p-18","order":3,"canonicalText":"武王纘大王、王季、文王之緒，壹戎衣而有天下，身不失天下之顯名；","chunks":[["武王纘大王、王季、文王之緒，壹戎衣而有天下，身不失天下之顯名；","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-4","passageId":"li-ji_ch-31_p-18","order":4,"canonicalText":"尊為天子，富有四海之內。","chunks":[["尊為天子，富有四海之內。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-5","passageId":"li-ji_ch-31_p-18","order":5,"canonicalText":"宗廟饗之，子孫保之。","chunks":[["宗廟饗之，子孫保之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-6","passageId":"li-ji_ch-31_p-18","order":6,"canonicalText":"武王末受命，周公成文、武之德，追王大王、王季，上祀先公以天子之禮。","chunks":[["武王末受命，周公成文、武之德，追王大王、王季，上祀先公以天子之禮。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-7","passageId":"li-ji_ch-31_p-18","order":7,"canonicalText":"斯禮也，達乎諸侯、大夫及士、庶人。","chunks":[["斯禮也，達乎諸侯、大夫及士、庶人。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-8","passageId":"li-ji_ch-31_p-18","order":8,"canonicalText":"父為大夫，子為士，葬以大夫，祭以士。","chunks":[["父為大夫，子為士，葬以大夫，祭以士。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-9","passageId":"li-ji_ch-31_p-18","order":9,"canonicalText":"父為士，子為大夫，葬以士，祭以大夫。","chunks":[["父為士，子為大夫，葬以士，祭以大夫。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-10","passageId":"li-ji_ch-31_p-18","order":10,"canonicalText":"期之喪，達乎大夫；","chunks":[["期之喪，達乎大夫；","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-11","passageId":"li-ji_ch-31_p-18","order":11,"canonicalText":"三年之喪，達乎天子；","chunks":[["三年之喪，達乎天子；","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-12","passageId":"li-ji_ch-31_p-18","order":12,"canonicalText":"父母之喪，無貴賤，一也。","chunks":[["父母之喪，無貴賤，一也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-18_s-13","passageId":"li-ji_ch-31_p-18","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-1","passageId":"li-ji_ch-31_p-19","order":1,"canonicalText":"子曰：「武王、周公，其達孝矣乎！","chunks":[["子曰：「武王、周公，其達孝矣乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-2","passageId":"li-ji_ch-31_p-19","order":2,"canonicalText":"夫孝者：善繼人之志，善述人之事者也。","chunks":[["夫孝者：善繼人之志，善述人之事者也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-3","passageId":"li-ji_ch-31_p-19","order":3,"canonicalText":"春、秋修其祖廟，陳其宗器，設其裳衣，薦其時食。","chunks":[["春、秋修其祖廟，陳其宗器，設其裳衣，薦其時食。","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-4","passageId":"li-ji_ch-31_p-19","order":4,"canonicalText":"宗廟之禮，所以序昭穆也；","chunks":[["宗廟之禮，所以序昭穆也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-5","passageId":"li-ji_ch-31_p-19","order":5,"canonicalText":"序爵，所以辨貴賤也；","chunks":[["序爵，所以辨貴賤也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-6","passageId":"li-ji_ch-31_p-19","order":6,"canonicalText":"序事，所以辨賢也；","chunks":[["序事，所以辨賢也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-7","passageId":"li-ji_ch-31_p-19","order":7,"canonicalText":"旅酬下為上，所以逮賤也；","chunks":[["旅酬下為上，所以逮賤也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-8","passageId":"li-ji_ch-31_p-19","order":8,"canonicalText":"燕毛，所以序齒也。","chunks":[["燕毛，所以序齒也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-9","passageId":"li-ji_ch-31_p-19","order":9,"canonicalText":"踐其位，行其禮，奏其樂，敬其所尊，愛其所親，事死如事生，事亡如事存，孝之至也。","chunks":[["踐其位，行其禮，奏其樂，敬其所尊，愛其所親，事死如事生，事亡如事存，孝之至也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-10","passageId":"li-ji_ch-31_p-19","order":10,"canonicalText":"郊社之禮，所以事上帝也；","chunks":[["郊社之禮，所以事上帝也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-11","passageId":"li-ji_ch-31_p-19","order":11,"canonicalText":"宗廟之禮，所以祀乎其先也。","chunks":[["宗廟之禮，所以祀乎其先也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-12","passageId":"li-ji_ch-31_p-19","order":12,"canonicalText":"明乎郊社之禮、禘嘗之義，治國其如示諸掌乎！","chunks":[["明乎郊社之禮、禘嘗之義，治國其如示諸掌乎！","zh-Hant"]]},{"id":"li-ji_ch-31_p-19_s-13","passageId":"li-ji_ch-31_p-19","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-1","passageId":"li-ji_ch-31_p-20","order":1,"canonicalText":"哀公問政。","chunks":[["哀公問政。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-2","passageId":"li-ji_ch-31_p-20","order":2,"canonicalText":"子曰：「文、武之政，布在方策，其人存，則其政舉；","chunks":[["子曰：「文、武之政，布在方策，其人存，則其政舉；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-3","passageId":"li-ji_ch-31_p-20","order":3,"canonicalText":"其人亡，則其政息。","chunks":[["其人亡，則其政息。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-4","passageId":"li-ji_ch-31_p-20","order":4,"canonicalText":"人道敏政，地道敏樹。","chunks":[["人道敏政，地道敏樹。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-5","passageId":"li-ji_ch-31_p-20","order":5,"canonicalText":"夫政也者，蒲盧也。","chunks":[["夫政也者，蒲盧也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-6","passageId":"li-ji_ch-31_p-20","order":6,"canonicalText":"故為政在人，取人以身，修身以道，修道以仁。","chunks":[["故為政在人，取人以身，修身以道，修道以仁。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-7","passageId":"li-ji_ch-31_p-20","order":7,"canonicalText":"仁者人也，親親為大；","chunks":[["仁者人也，親親為大；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-8","passageId":"li-ji_ch-31_p-20","order":8,"canonicalText":"義者宜也，尊賢為大。","chunks":[["義者宜也，尊賢為大。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-9","passageId":"li-ji_ch-31_p-20","order":9,"canonicalText":"親親之殺，尊賢之等，禮所生也。","chunks":[["親親之殺，尊賢之等，禮所生也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-10","passageId":"li-ji_ch-31_p-20","order":10,"canonicalText":"在下位不獲乎上，民不可得而治矣！","chunks":[["在下位不獲乎上，民不可得而治矣！","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-11","passageId":"li-ji_ch-31_p-20","order":11,"canonicalText":"故君子不可以不修身；","chunks":[["故君子不可以不修身；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-12","passageId":"li-ji_ch-31_p-20","order":12,"canonicalText":"思修身，不可以不事親；","chunks":[["思修身，不可以不事親；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-13","passageId":"li-ji_ch-31_p-20","order":13,"canonicalText":"思事親，不可以不知人；","chunks":[["思事親，不可以不知人；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-14","passageId":"li-ji_ch-31_p-20","order":14,"canonicalText":"思知人，不可以不知天。","chunks":[["思知人，不可以不知天。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-15","passageId":"li-ji_ch-31_p-20","order":15,"canonicalText":"天下之達道五，所以行之者三，曰：君臣也，父子也，夫婦也，昆弟也，朋友之交也，五者天下之達道也。","chunks":[["天下之達道五，所以行之者三，曰：君臣也，父子也，夫婦也，昆弟也，朋友之交也，五者天下之達道也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-16","passageId":"li-ji_ch-31_p-20","order":16,"canonicalText":"知仁勇三者，天下之達德也，所以行之者一也。","chunks":[["知仁勇三者，天下之達德也，所以行之者一也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-17","passageId":"li-ji_ch-31_p-20","order":17,"canonicalText":"或生而知之，或學而知之，或困而知之，及其知之，一也；","chunks":[["或生而知之，或學而知之，或困而知之，及其知之，一也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-18","passageId":"li-ji_ch-31_p-20","order":18,"canonicalText":"或安而行之，或利而行之，或勉強而行之，及其成功，一也。","chunks":[["或安而行之，或利而行之，或勉強而行之，及其成功，一也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-20_s-19","passageId":"li-ji_ch-31_p-20","order":19,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-1","passageId":"li-ji_ch-31_p-21","order":1,"canonicalText":"子曰：「好學近乎知，力行近乎仁，知恥近乎勇。","chunks":[["子曰：「好學近乎知，力行近乎仁，知恥近乎勇。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-2","passageId":"li-ji_ch-31_p-21","order":2,"canonicalText":"知斯三者，則知所以修身；","chunks":[["知斯三者，則知所以修身；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-3","passageId":"li-ji_ch-31_p-21","order":3,"canonicalText":"知所以修身，則知所以治人；","chunks":[["知所以修身，則知所以治人；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-4","passageId":"li-ji_ch-31_p-21","order":4,"canonicalText":"知所以治人，則知所以治天下國家矣。","chunks":[["知所以治人，則知所以治天下國家矣。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-5","passageId":"li-ji_ch-31_p-21","order":5,"canonicalText":"凡為天下國家有九經，曰：修身也，尊賢也，親親也，敬大臣也，體群臣也，子庶民也，來百工也，柔遠人也，懷諸侯也。","chunks":[["凡為天下國家有九經，曰：修身也，尊賢也，親親也，敬大臣也，體群臣也，子庶民也，來百工也，柔遠人也，懷諸侯也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-6","passageId":"li-ji_ch-31_p-21","order":6,"canonicalText":"修身則道立，尊賢則不惑，親親則諸父昆弟不怨，敬大臣則不眩，體群臣則士之報禮重，子庶民則百姓勸，來百工則財用足，柔遠人則四方歸之，懷諸侯則天下畏之。","chunks":[["修身則道立，尊賢則不惑，親親則諸父昆弟不怨，敬大臣則不眩，體群臣則士之報禮重，子庶民則百姓勸，來百工則財用足，柔遠人則四方歸之，懷諸侯則天下畏之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-7","passageId":"li-ji_ch-31_p-21","order":7,"canonicalText":"齊明盛服，非禮不動，所以修身也；","chunks":[["齊明盛服，非禮不動，所以修身也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-8","passageId":"li-ji_ch-31_p-21","order":8,"canonicalText":"去讒遠色，賤貨而貴德，所以勸賢也；","chunks":[["去讒遠色，賤貨而貴德，所以勸賢也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-9","passageId":"li-ji_ch-31_p-21","order":9,"canonicalText":"尊其位，重其祿，同其好惡，所以勸親親也；","chunks":[["尊其位，重其祿，同其好惡，所以勸親親也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-10","passageId":"li-ji_ch-31_p-21","order":10,"canonicalText":"官盛任使，所以勸大臣也；","chunks":[["官盛任使，所以勸大臣也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-11","passageId":"li-ji_ch-31_p-21","order":11,"canonicalText":"忠信重祿，所以勸士也；","chunks":[["忠信重祿，所以勸士也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-12","passageId":"li-ji_ch-31_p-21","order":12,"canonicalText":"時使薄斂，所以勸百姓也；","chunks":[["時使薄斂，所以勸百姓也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-13","passageId":"li-ji_ch-31_p-21","order":13,"canonicalText":"日省月試，既廩稱事，所以勸百工也；","chunks":[["日省月試，既廩稱事，所以勸百工也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-14","passageId":"li-ji_ch-31_p-21","order":14,"canonicalText":"送往迎來，嘉善而矜不能，所以柔遠人也；","chunks":[["送往迎來，嘉善而矜不能，所以柔遠人也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-15","passageId":"li-ji_ch-31_p-21","order":15,"canonicalText":"繼絕世，舉廢國，治亂持危，朝聘以時，厚往而薄來，所以懷諸侯也。","chunks":[["繼絕世，舉廢國，治亂持危，朝聘以時，厚往而薄來，所以懷諸侯也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-16","passageId":"li-ji_ch-31_p-21","order":16,"canonicalText":"凡為天下國家有九經，所以行之者一也。","chunks":[["凡為天下國家有九經，所以行之者一也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-21_s-17","passageId":"li-ji_ch-31_p-21","order":17,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-1","passageId":"li-ji_ch-31_p-22","order":1,"canonicalText":"「凡事豫則立，不豫則廢。","chunks":[["「凡事豫則立，不豫則廢。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-2","passageId":"li-ji_ch-31_p-22","order":2,"canonicalText":"言前定則不跲，事前定則不困，行前定則不疚，道前定則不窮。","chunks":[["言前定則不跲，事前定則不困，行前定則不疚，道前定則不窮。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-3","passageId":"li-ji_ch-31_p-22","order":3,"canonicalText":"在下位不獲乎上，民不可得而治矣；","chunks":[["在下位不獲乎上，民不可得而治矣；","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-4","passageId":"li-ji_ch-31_p-22","order":4,"canonicalText":"獲乎上有道：不信乎朋友，不獲乎上矣；","chunks":[["獲乎上有道：不信乎朋友，不獲乎上矣；","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-5","passageId":"li-ji_ch-31_p-22","order":5,"canonicalText":"信乎朋友有道：不順乎親，不信乎朋友矣；","chunks":[["信乎朋友有道：不順乎親，不信乎朋友矣；","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-6","passageId":"li-ji_ch-31_p-22","order":6,"canonicalText":"順乎親有道：反諸身不誠，不順乎親矣；","chunks":[["順乎親有道：反諸身不誠，不順乎親矣；","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-7","passageId":"li-ji_ch-31_p-22","order":7,"canonicalText":"誠身有道：不明乎善，不誠乎身矣。","chunks":[["誠身有道：不明乎善，不誠乎身矣。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-8","passageId":"li-ji_ch-31_p-22","order":8,"canonicalText":"誠者，天之道也；","chunks":[["誠者，天之道也；","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-9","passageId":"li-ji_ch-31_p-22","order":9,"canonicalText":"誠之者，人之道也。","chunks":[["誠之者，人之道也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-10","passageId":"li-ji_ch-31_p-22","order":10,"canonicalText":"誠者不勉而中，不思而得，從容中道，聖人也。","chunks":[["誠者不勉而中，不思而得，從容中道，聖人也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-11","passageId":"li-ji_ch-31_p-22","order":11,"canonicalText":"誠之者，擇善而固執之者也。","chunks":[["誠之者，擇善而固執之者也。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-12","passageId":"li-ji_ch-31_p-22","order":12,"canonicalText":"博學之，審問之，慎思之，明辨之，篤行之。","chunks":[["博學之，審問之，慎思之，明辨之，篤行之。","zh-Hant"]]},{"id":"li-ji_ch-31_p-22_s-13","passageId":"li-ji_ch-31_p-22","order":13,"canonicalText":"有弗學，學之弗能，弗措也；","chunks":[["有弗學，學之弗能，弗措也；","zh-Hant"]]}]') as Sentence[];
